import React, { useEffect, useMemo, useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faArrowRightFromBracket, faCreditCard, faPenToSquare, faUser, faUsers } from '@fortawesome/free-solid-svg-icons';
import { format, subDays } from 'date-fns';
import { useMasterData } from '../../contexts/MasterDataContext';
import { manpowerService, Worker } from '../../services/manpowerService';
import { cardService } from '../../services/cardService';
import { teamService, Team } from '../../services/teamService';
import { Card, CardAssigneeType } from '../../types/card';
import { toast, showConfirmAlert } from '../../utils/swal';

type AssigneeMode = CardAssigneeType;

interface CardAssignmentManagerProps {
    cards: Card[];
    loading: boolean;
    initialCardId?: string | null;
    selectableTeams?: Team[]; // Optional: if provided, use this list instead of filtering from context
    onRefresh: () => void;
    onEditCard: (card: Card) => void;
}

const toDateInputValue = (d: Date): string => {
    return format(d, 'yyyy-MM-dd');
};

const buildEndDateAsDayBefore = (startDate: string): string => {
    const d = new Date(startDate);
    if (Number.isNaN(d.getTime())) return toDateInputValue(new Date());
    return toDateInputValue(subDays(d, 1));
};

export const CardAssignmentManager: React.FC<CardAssignmentManagerProps> = ({
    cards,
    loading,
    initialCardId,
    selectableTeams,
    onRefresh,
    onEditCard
}) => {
    const { teams: allTeams } = useMasterData();

    // Strict Filter or Use Prop
    const teams = useMemo(() => {
        if (selectableTeams) return selectableTeams;

        // Fallback (e.g. if not passed, use Cheongyeon logic if possible, or old logic)
        // Since the parent is updated to pass the correct list, we can keep the old one as fallback
        // or just return allTeams if no filter needed.
        // For safety, let's just return allTeams or strict filter if prop missing.
        const targetTeamTypes = new Set(['시공팀', '시공사팀', '건설사', '시공사']);
        return allTeams.filter(t => {
            const rawType = String(t.type ?? '').trim();
            return targetTeamTypes.has(rawType);
        });
    }, [allTeams, selectableTeams]);

    const today = useMemo(() => toDateInputValue(new Date()), []);

    const [mode, setMode] = useState<AssigneeMode>('TEAM');
    const [workers, setWorkers] = useState<Worker[]>([]);

    const [selectedTeamId, setSelectedTeamId] = useState<string>('');
    const [selectedWorkerId, setSelectedWorkerId] = useState<string>('');
    const [selectedCardId, setSelectedCardId] = useState<string>('');
    const [startDate, setStartDate] = useState<string>(today);
    const [autoUnassignExisting, setAutoUnassignExisting] = useState<boolean>(true);

    const [saving, setSaving] = useState<boolean>(false);

    useEffect(() => {
        const loadWorkers = async () => {
            try {
                const list = await manpowerService.getWorkers();
                setWorkers(list);
            } catch (e) {
                console.error(e);
                toast.error('작업자 목록을 불러오지 못했습니다.');
            }
        };
        loadWorkers();
    }, []);

    useEffect(() => {
        if (selectedTeamId) return;
        const first = teams.find((t) => Boolean(t.id));
        setSelectedTeamId(first?.id ?? '');
    }, [teams, selectedTeamId]);

    const filteredWorkers = useMemo(() => {
        if (!selectedTeamId) return workers;
        return workers.filter((w) => w.teamId === selectedTeamId);
    }, [workers, selectedTeamId]);

    useEffect(() => {
        if (!initialCardId) return;
        setSelectedCardId(String(initialCardId));
    }, [initialCardId]);

    useEffect(() => {
        if (mode !== 'WORKER') return;
        if (selectedWorkerId && filteredWorkers.some((w) => w.id === selectedWorkerId)) return;
        const first = filteredWorkers.find((w) => Boolean(w.id));
        setSelectedWorkerId(first?.id ?? '');
    }, [mode, selectedWorkerId, filteredWorkers]);

    const cardsById = useMemo(() => {
        const map = new Map<string, Card>();
        cards.forEach((c) => map.set(String(c.id), c));
        return map;
    }, [cards]);

    const availableCards = useMemo(() => {
        return cards.filter((c) => (c.status ?? 'AVAILABLE') === 'AVAILABLE');
    }, [cards]);

    const assignedCards = useMemo(() => {
        return cards.filter((c) => (c.status ?? 'AVAILABLE') === 'ASSIGNED');
    }, [cards]);

    const selectedCard = useMemo(() => {
        if (!selectedCardId) return null;
        return cardsById.get(String(selectedCardId)) ?? null;
    }, [cardsById, selectedCardId]);

    const selectedTeam = useMemo(() => {
        return teams.find((t) => t.id === selectedTeamId) ?? null;
    }, [teams, selectedTeamId]);

    const selectedWorker = useMemo(() => {
        if (!selectedWorkerId) return null;
        return filteredWorkers.find((w) => w.id === selectedWorkerId) ?? null;
    }, [filteredWorkers, selectedWorkerId]);

    const getStatusBadge = (status: Card['status']) => {
        if (status === 'ASSIGNED') {
            return <span className="px-2.5 py-1 rounded-lg text-xs font-bold bg-emerald-50 text-emerald-700 border border-emerald-100">사용중</span>;
        }
        if (status === 'AVAILABLE') {
            return <span className="px-2.5 py-1 rounded-lg text-xs font-bold bg-slate-100 text-slate-500 border border-slate-200">대기</span>;
        }
        if (status === 'SUSPENDED') {
            return <span className="px-2.5 py-1 rounded-lg text-xs font-bold bg-orange-50 text-orange-700 border border-orange-100">정지</span>;
        }
        return <span className="px-2.5 py-1 rounded-lg text-xs font-bold bg-slate-900 text-white border border-slate-800">해지</span>;
    };

    const handleAssign = async () => {
        if (!selectedCard || !selectedCard.id) {
            toast.error('카드를 선택해주세요.');
            return;
        }

        if (!startDate) {
            toast.error('배정 시작일을 입력해주세요.');
            return;
        }

        const isAssigned = (selectedCard.status ?? 'AVAILABLE') === 'ASSIGNED';
        if (isAssigned && !autoUnassignExisting) {
            toast.error('이미 배정된 카드입니다. 먼저 해제해주세요.');
            return;
        }

        const assigneeId = mode === 'TEAM' ? selectedTeam?.id : selectedWorker?.id;
        const assigneeName = mode === 'TEAM' ? selectedTeam?.name : selectedWorker?.name;

        if (!assigneeId || !assigneeName) {
            toast.error(mode === 'TEAM' ? '팀을 선택해주세요.' : '작업자를 선택해주세요.');
            return;
        }

        const confirmMessage = `${selectedCard.name} 카드를 ${assigneeName}${mode === 'TEAM' ? '(팀)' : '(개인)'}에 배정할까요?`;
        const result = await showConfirmAlert('카드 배정', confirmMessage);
        if (!result.isConfirmed) return;

        setSaving(true);
        try {
            if (isAssigned) {
                const endDate = buildEndDateAsDayBefore(startDate);
                await cardService.unassignCard(selectedCard.id, endDate);
            }

            await cardService.assignCard(selectedCard.id, assigneeId, mode, assigneeName, startDate);
            toast.success('카드 배정이 완료되었습니다.');
            onRefresh();
        } catch (e: unknown) {
            console.error(e);
            const message = e instanceof Error ? e.message : '카드 배정에 실패했습니다.';
            toast.error(message);
        } finally {
            setSaving(false);
        }
    };

    const handleUnassign = async (card: Card) => {
        const result = await showConfirmAlert('카드 배정 해제', `${card.name} 카드 배정을 해제할까요?`);
        if (!result.isConfirmed) return;

        setSaving(true);
        try {
            const endDate = toDateInputValue(new Date());
            await cardService.unassignCard(card.id, endDate);
            toast.success('배정 해제되었습니다.');
            onRefresh();
        } catch (e: unknown) {
            console.error(e);
            const message = e instanceof Error ? e.message : '배정 해제에 실패했습니다.';
            toast.error(message);
        } finally {
            setSaving(false);
        }
    };

    const handleQuickPick = (card: Card) => {
        setSelectedCardId(card.id);
        if (card.currentAssigneeType === 'TEAM') {
            setMode('TEAM');
            if (card.currentAssigneeId) setSelectedTeamId(card.currentAssigneeId);
        }
        if (card.currentAssigneeType === 'WORKER') {
            setMode('WORKER');
        }
    };

    if (loading) {
        return (
            <div className="h-64 flex items-center justify-center text-slate-400">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-4">
                    <div>
                        <h2 className="text-xl font-extrabold text-slate-900 tracking-tight flex items-center gap-3">
                            <span className="bg-indigo-600 text-white w-9 h-9 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-200">
                                <FontAwesomeIcon icon={faUsers} className="text-sm" />
                            </span>
                            카드 배정
                        </h2>
                        <p className="text-slate-500 mt-2 font-medium ml-12 text-sm">팀/개인 단위로 카드를 배정하거나, 배정을 해제할 수 있습니다.</p>
                    </div>
                    <div className="flex items-center gap-2">
                        <button
                            onClick={handleAssign}
                            disabled={saving}
                            className={`px-5 py-2.5 rounded-xl font-bold text-sm text-white shadow-lg shadow-indigo-200 transition-all active:scale-95 flex items-center gap-2 ${saving ? 'bg-indigo-400 cursor-wait' : 'bg-indigo-600 hover:bg-indigo-700 hover:-translate-y-0.5'
                                }`}
                        >
                            <FontAwesomeIcon icon={faCreditCard} />
                            {saving ? '처리 중...' : '배정 실행'}
                        </button>
                    </div>
                </div>

                <div className="mt-6 grid grid-cols-1 xl:grid-cols-12 gap-4">
                    <div className="xl:col-span-4 space-y-3">
                        <div className="flex bg-slate-100 p-1 rounded-xl">
                            <button
                                onClick={() => setMode('TEAM')}
                                className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${mode === 'TEAM' ? 'bg-white shadow text-indigo-700' : 'text-slate-500 hover:text-slate-700'
                                    }`}
                            >
                                <FontAwesomeIcon icon={faUsers} className="mr-2" /> 팀
                            </button>
                            <button
                                onClick={() => setMode('WORKER')}
                                className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${mode === 'WORKER' ? 'bg-white shadow text-indigo-700' : 'text-slate-500 hover:text-slate-700'
                                    }`}
                            >
                                <FontAwesomeIcon icon={faUser} className="mr-2" /> 개인
                            </button>
                        </div>

                        <div className="bg-slate-50 p-4 rounded-2xl border border-slate-200 space-y-3">
                            <div>
                                <label className="block text-xs font-bold text-slate-600 mb-1">카드 선택</label>
                                <select
                                    className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm font-bold text-slate-700"
                                    value={selectedCardId}
                                    onChange={(e) => setSelectedCardId(e.target.value)}
                                >
                                    <option value="">카드를 선택하세요</option>
                                    {cards
                                        .slice()
                                        .sort((a, b) => String(a.name).localeCompare(String(b.name), 'ko-KR'))
                                        .map((c) => (
                                            <option key={c.id} value={c.id}>
                                                {c.name} ({c.last4})
                                            </option>
                                        ))}
                                </select>
                            </div>

                            {mode === 'TEAM' && (
                                <div>
                                    <label className="block text-xs font-bold text-slate-600 mb-1">팀 선택</label>
                                    <select
                                        className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm font-bold text-slate-700"
                                        value={selectedTeamId}
                                        onChange={(e) => setSelectedTeamId(e.target.value)}
                                    >
                                        {teams
                                            .slice()
                                            .sort((a, b) => String(a.name).localeCompare(String(b.name), 'ko-KR'))
                                            .map((t) => (
                                                <option key={t.id} value={t.id}>
                                                    {t.name}
                                                </option>
                                            ))}
                                    </select>
                                </div>
                            )}

                            {mode === 'WORKER' && (
                                <div>
                                    <label className="block text-xs font-bold text-slate-600 mb-1">작업자 선택</label>
                                    <select
                                        className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm font-bold text-slate-700"
                                        value={selectedWorkerId}
                                        onChange={(e) => setSelectedWorkerId(e.target.value)}
                                    >
                                        {filteredWorkers
                                            .slice()
                                            .sort((a, b) => String(a.name).localeCompare(String(b.name), 'ko-KR'))
                                            .map((w) => (
                                                <option key={w.id} value={w.id}>
                                                    {w.name}
                                                </option>
                                            ))}
                                    </select>
                                </div>
                            )}

                            <div className="grid grid-cols-2 gap-3">
                                <div>
                                    <label className="block text-xs font-bold text-slate-600 mb-1">배정 시작일</label>
                                    <input
                                        type="date"
                                        className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm font-bold text-slate-700"
                                        value={startDate}
                                        onChange={(e) => setStartDate(e.target.value)}
                                    />
                                </div>
                                <div className="flex items-end">
                                    <label className="flex items-center gap-2 text-sm font-bold text-slate-700">
                                        <input
                                            type="checkbox"
                                            checked={autoUnassignExisting}
                                            onChange={(e) => setAutoUnassignExisting(e.target.checked)}
                                        />
                                        기존 배정 자동 해제
                                    </label>
                                </div>
                            </div>
                        </div>

                        {selectedCard && (
                            <div className="bg-white p-4 rounded-2xl border border-slate-200">
                                <div className="flex items-center justify-between">
                                    <div>
                                        <div className="text-xs text-slate-500 font-bold">선택 카드</div>
                                        <div className="text-lg font-extrabold text-slate-900">{selectedCard.name} ({selectedCard.last4})</div>
                                        <div className="text-sm text-slate-500 font-medium mt-1">{selectedCard.issuer} · {selectedCard.maskedNumber}</div>
                                    </div>
                                    <button
                                        onClick={() => onEditCard(selectedCard)}
                                        className="px-3 py-2 rounded-xl text-xs font-bold bg-slate-100 text-slate-700 hover:bg-slate-200 flex items-center gap-2"
                                    >
                                        <FontAwesomeIcon icon={faPenToSquare} />
                                        수정
                                    </button>
                                </div>
                            </div>
                        )}
                    </div>

                    <div className="xl:col-span-8 grid grid-cols-1 lg:grid-cols-2 gap-4">
                        <div className="bg-white p-4 rounded-2xl border border-slate-200">
                            <h3 className="font-extrabold text-slate-800 mb-3">대기 카드</h3>
                            <div className="space-y-2 max-h-[360px] overflow-y-auto">
                                {availableCards.length === 0 ? (
                                    <div className="text-sm text-slate-400">대기 카드가 없습니다.</div>
                                ) : (
                                    availableCards.map((c) => (
                                        <button
                                            key={c.id}
                                            onClick={() => handleQuickPick(c)}
                                            className="w-full text-left p-3 rounded-xl border border-slate-100 hover:border-indigo-200 hover:bg-indigo-50/40 transition"
                                        >
                                            <div className="flex items-center justify-between">
                                                <div className="font-extrabold text-slate-800">{c.name} ({c.last4})</div>
                                                {getStatusBadge(c.status)}
                                            </div>
                                            <div className="text-xs text-slate-500 mt-1 font-mono">{c.maskedNumber}</div>
                                        </button>
                                    ))
                                )}
                            </div>
                        </div>

                        <div className="bg-white p-4 rounded-2xl border border-slate-200">
                            <h3 className="font-extrabold text-slate-800 mb-3">사용중 카드</h3>
                            <div className="space-y-2 max-h-[360px] overflow-y-auto">
                                {assignedCards.length === 0 ? (
                                    <div className="text-sm text-slate-400">사용중 카드가 없습니다.</div>
                                ) : (
                                    assignedCards.map((c) => (
                                        <div
                                            key={c.id}
                                            className="w-full text-left p-3 rounded-xl border border-slate-100 hover:border-indigo-200 hover:bg-indigo-50/40 transition"
                                        >
                                            <div className="flex items-center justify-between">
                                                <button onClick={() => handleQuickPick(c)} className="text-left">
                                                    <div className="font-extrabold text-slate-800">{c.name} ({c.last4})</div>
                                                    <div className="text-xs text-slate-500 mt-1">{c.currentAssigneeName || '-'}</div>
                                                </button>
                                                <div className="flex items-center gap-2">
                                                    {getStatusBadge(c.status)}
                                                    <button
                                                        onClick={() => handleUnassign(c)}
                                                        disabled={saving}
                                                        className="px-3 py-2 rounded-xl text-xs font-bold bg-rose-50 text-rose-700 hover:bg-rose-100 inline-flex items-center gap-2"
                                                    >
                                                        <FontAwesomeIcon icon={faArrowRightFromBracket} />
                                                        해제
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useEffect, useMemo, useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faCalculator,
    faCheckDouble,
    faFloppyDisk,
    faMagnifyingGlass,
    faSearch,
    faTrash,
    faUpload
} from '@fortawesome/free-solid-svg-icons';
import { format, subMonths } from 'date-fns';
import { getDownloadURL, ref as storageRef, uploadBytes } from 'firebase/storage';
import { httpsCallable } from 'firebase/functions';
import { functions as firebaseFunctions, storage } from '../../config/firebase';
import { Card } from '../../types/card';
import { CardBillingCostItem, CardBillingDocument } from '../../types/cardBilling';
import { cardBillingService } from '../../services/cardBillingService';
import { aiSettingsService } from '../../services/aiSettingsService';
import { toast, showConfirmAlert } from '../../utils/swal';
import { Timestamp } from '../../types/timestamp';

interface CardBillingManagerProps {
    cards: Card[];
    loadingCards: boolean;
    onRefreshCards: () => void;
}

export const CardBillingManager: React.FC<CardBillingManagerProps> = ({ cards, loadingCards, onRefreshCards }) => {
    const [yearMonth, setYearMonth] = useState(format(subMonths(new Date(), 1), 'yyyy-MM'));

    const [documents, setDocuments] = useState<CardBillingDocument[]>([]);
    const [selectedDocumentId, setSelectedDocumentId] = useState<string>('');
    const [loading, setLoading] = useState(false);
    const [processing, setProcessing] = useState(false);
    const [saving, setSaving] = useState(false);

    const [uploadingAttachment, setUploadingAttachment] = useState(false);
    const [analyzingAttachment, setAnalyzingAttachment] = useState(false);
    const [selectedAttachmentPath, setSelectedAttachmentPath] = useState<string>('');
    const [isAiEnabledOnPage, setIsAiEnabledOnPage] = useState(true);

    useEffect(() => {
        if (typeof window === 'undefined') return;
        setIsAiEnabledOnPage(aiSettingsService.isPathEnabled(window.location.pathname));
    }, []);

    useEffect(() => {
        loadBillings();
    }, [yearMonth]);

    const loadBillings = async () => {
        setLoading(true);
        try {
            const data = await cardBillingService.getBillingsByMonth(yearMonth);
            const sorted = data
                .slice()
                .sort((a, b) => {
                    const cardCmp = String(a.cardLabel ?? '').localeCompare(String(b.cardLabel ?? ''), 'ko-KR');
                    if (cardCmp !== 0) return cardCmp;
                    const teamCmp = String(a.teamName ?? a.assignedTeamName ?? '').localeCompare(String(b.teamName ?? b.assignedTeamName ?? ''), 'ko-KR');
                    if (teamCmp !== 0) return teamCmp;
                    return String(a.issuedToWorkerName ?? '').localeCompare(String(b.issuedToWorkerName ?? ''), 'ko-KR');
                });

            setDocuments(sorted);
            setSelectedDocumentId((prev) => {
                if (prev && sorted.some((d) => d.id === prev)) return prev;
                return sorted[0]?.id ?? '';
            });
        } catch (e) {
            console.error(e);
            toast.error('청구 문서를 불러오지 못했습니다.');
            setDocuments([]);
        } finally {
            setLoading(false);
        }
    };

    const selectedDocument = useMemo(() => {
        if (!selectedDocumentId) return null;
        return documents.find((d) => d.id === selectedDocumentId) ?? null;
    }, [documents, selectedDocumentId]);

    useEffect(() => {
        const paths = selectedDocument?.statementAttachmentPaths ?? [];
        setSelectedAttachmentPath((prev) => {
            if (prev && paths.includes(prev)) return prev;
            return paths[paths.length - 1] ?? '';
        });
    }, [selectedDocument]);

    const sanitizeFileName = (name: string): string => {
        const v = String(name || '').trim();
        if (!v) return 'statement';
        return v.replace(/[\\/\n\r\t]/g, '_');
    };

    const parseAmount = (value: unknown): number | null => {
        if (typeof value === 'number' && Number.isFinite(value)) return value;
        if (typeof value === 'string') {
            const trimmed = value.trim();
            if (!trimmed) return null;
            const normalized = trimmed.replace(/,/g, '');
            const num = Number(normalized);
            return Number.isFinite(num) ? num : null;
        }
        return null;
    };

    const isRecord = (value: unknown): value is Record<string, unknown> => {
        return typeof value === 'object' && value !== null;
    };

    type AnalyzeCardBillingStatementRequest = {
        statementPath: string;
        billingId?: string;
        yearMonth?: string;
        cardLabel?: string;
    };

    type AnalyzeCardBillingStatementResponse = {
        ok: boolean;
        analysis?: {
            status?: string;
            message?: string;
            gemini?: {
                rawText?: string;
                parsed?: unknown;
            } | null;
        };
    };

    const updateSelectedDocument = (updater: (doc: CardBillingDocument) => CardBillingDocument) => {
        setDocuments((prev) => prev.map((d) => (d.id === selectedDocumentId ? updater(d) : d)));
    };

    const handleUploadAttachment = async (file: File) => {
        if (!selectedDocument) {
            toast.error('문서를 먼저 선택해주세요.');
            return;
        }

        if (!file) return;

        setUploadingAttachment(true);
        try {
            const safeName = sanitizeFileName(file.name);
            const base = `card-billing-statements/${selectedDocument.yearMonth}/${selectedDocument.id}`;
            const objectPath = `${base}/${Date.now()}_${safeName}`;

            const r = storageRef(storage, objectPath);
            await uploadBytes(r, file, file.type ? { contentType: file.type } : undefined);

            updateSelectedDocument((doc) => {
                const nextPaths = [...(doc.statementAttachmentPaths ?? []), objectPath];
                return {
                    ...doc,
                    statementAttachmentPaths: nextPaths,
                    updatedAt: Timestamp.now()
                };
            });

            setSelectedAttachmentPath(objectPath);
            toast.success('첨부 업로드가 완료되었습니다. 저장 버튼을 눌러 반영해주세요.');
        } catch (e: unknown) {
            console.error(e);
            const msg = e instanceof Error ? e.message : '첨부 업로드에 실패했습니다.';
            toast.error(msg);
        } finally {
            setUploadingAttachment(false);
        }
    };

    const handleOpenAttachment = async (path: string) => {
        if (!path) return;
        try {
            const url = await getDownloadURL(storageRef(storage, path));
            window.open(url, '_blank', 'noopener,noreferrer');
        } catch (e) {
            console.error(e);
            toast.error('첨부 파일을 열 수 없습니다.');
        }
    };

    const handleAnalyzeAttachment = async () => {
        try {
            aiSettingsService.assertCurrentPageEnabled('Gemini 청구서 분석');
        } catch (e: unknown) {
            toast.error(e instanceof Error ? e.message : '이 페이지의 AI 분석이 비활성화되어 있습니다.');
            return;
        }

        if (!selectedDocument) {
            toast.error('문서를 먼저 선택해주세요.');
            return;
        }

        const path = selectedAttachmentPath || (selectedDocument.statementAttachmentPaths ?? [])[0] || '';
        if (!path) {
            toast.error('분석할 첨부 파일이 없습니다.');
            return;
        }

        const confirm = await showConfirmAlert('Gemini 분석', 'Gemini 분석 결과로 라인 아이템을 덮어쓸까요?', '분석');
        if (!confirm.isConfirmed) return;

        setAnalyzingAttachment(true);
        try {
            const callable = httpsCallable<AnalyzeCardBillingStatementRequest, AnalyzeCardBillingStatementResponse>(
                firebaseFunctions,
                'analyzeCardBillingStatement'
            );

            const res = await callable({
                statementPath: path,
                billingId: selectedDocument.id,
                yearMonth: selectedDocument.yearMonth,
                cardLabel: selectedDocument.cardLabel
            });

            const data = res.data;
            const parsed = data?.analysis?.gemini?.parsed;
            if (!parsed) {
                toast.error(data?.analysis?.message ?? 'Gemini 분석 결과가 없습니다.');
                return;
            }

            if (!isRecord(parsed)) {
                toast.error('Gemini 분석 결과 형식이 올바르지 않습니다.');
                return;
            }

            const totalAmount = parseAmount(parsed.totalAmount);
            const itemsRaw = parsed.items;
            const nextItems: CardBillingCostItem[] = [];

            if (Array.isArray(itemsRaw)) {
                itemsRaw.forEach((it, idx) => {
                    if (!isRecord(it)) return;
                    const label = typeof it.label === 'string' ? it.label.trim() : '';
                    const amount = parseAmount(it.amount);
                    if (!label || amount == null) return;
                    const category = typeof it.category === 'string' ? it.category.trim() : '';
                    nextItems.push({
                        id: `ai_${Date.now()}_${idx}`,
                        label,
                        amount,
                        type: 'VARIABLE',
                        category: category || undefined
                    });
                });
            }

            if (nextItems.length === 0 && totalAmount != null) {
                nextItems.push({
                    id: `ai_total_${Date.now()}`,
                    label: '청구서 총액',
                    amount: totalAmount,
                    type: 'VARIABLE',
                    category: 'STATEMENT'
                });
            }

            const computedTotal = nextItems.reduce((acc, it) => acc + (Number.isFinite(it.amount) ? it.amount : 0), 0);
            updateSelectedDocument((doc) => ({
                ...doc,
                lineItems: nextItems,
                variableCost: computedTotal,
                totalAmount: computedTotal,
                updatedAt: Timestamp.now()
            }));

            toast.success('Gemini 분석 결과가 적용되었습니다. 저장 버튼을 눌러 반영해주세요.');
        } catch (e: unknown) {
            console.error(e);
            const msg = e instanceof Error ? e.message : 'Gemini 분석에 실패했습니다.';
            toast.error(msg);
        } finally {
            setAnalyzingAttachment(false);
        }
    };

    const handleGenerateDrafts = async () => {
        const result = await showConfirmAlert('청구 문서 생성', `${yearMonth} 기준으로 청구 초안을 생성할까요?`);
        if (!result.isConfirmed) return;

        setProcessing(true);
        try {
            const targets = cards.filter((c) => c.status === 'ASSIGNED');
            if (targets.length === 0) {
                toast.info('배정된 카드가 없어 생성할 문서가 없습니다.');
                return;
            }

            const docs = await Promise.all(targets.map((c) => cardBillingService.generateBilling(c, yearMonth)));
            for (const doc of docs) {
                await cardBillingService.saveBilling(doc);
            }

            toast.success('청구 초안 생성이 완료되었습니다.');
            await loadBillings();
        } catch (e: unknown) {
            console.error(e);
            const msg = e instanceof Error ? e.message : '청구 문서 생성에 실패했습니다.';
            toast.error(msg);
        } finally {
            setProcessing(false);
            onRefreshCards();
        }
    };

    const handleSaveSelected = async () => {
        if (!selectedDocument) return;

        setSaving(true);
        try {
            await cardBillingService.saveBilling({
                ...selectedDocument,
                updatedAt: Timestamp.now()
            });
            toast.success('저장되었습니다.');
            await loadBillings();
        } catch (e: unknown) {
            console.error(e);
            const msg = e instanceof Error ? e.message : '저장에 실패했습니다.';
            toast.error(msg);
        } finally {
            setSaving(false);
        }
    };

    const handleConfirmSelected = async () => {
        if (!selectedDocument) return;

        const result = await showConfirmAlert('청구 확정', '선택한 청구 문서를 확정할까요?', '확정');
        if (!result.isConfirmed) return;

        setSaving(true);
        try {
            await cardBillingService.saveBilling({
                ...selectedDocument,
                status: 'CONFIRMED',
                confirmedAt: Timestamp.now(),
                updatedAt: Timestamp.now()
            });
            toast.success('확정되었습니다.');
            await loadBillings();
        } catch (e: unknown) {
            console.error(e);
            const msg = e instanceof Error ? e.message : '확정에 실패했습니다.';
            toast.error(msg);
        } finally {
            setSaving(false);
        }
    };

    const handleDeleteSelected = async () => {
        if (!selectedDocument) return;

        const result = await showConfirmAlert('청구 문서 삭제', '선택한 청구 문서를 삭제할까요?', '삭제');
        if (!result.isConfirmed) return;

        setSaving(true);
        try {
            await cardBillingService.deleteBilling(selectedDocument.id);
            toast.success('삭제되었습니다.');
            await loadBillings();
        } catch (e: unknown) {
            console.error(e);
            const msg = e instanceof Error ? e.message : '삭제에 실패했습니다.';
            toast.error(msg);
        } finally {
            setSaving(false);
        }
    };

    return (
        <div className="space-y-5">
            <div className="flex flex-col xl:flex-row xl:items-end justify-between gap-4">
                <div>
                    <h2 className="text-xl font-extrabold text-slate-900">카드 청구관리</h2>
                    <p className="text-slate-500 font-medium mt-1 text-sm">배정된 카드의 월별 사용내역을 기반으로 청구 문서를 생성/확정합니다.</p>
                </div>

                <div className="flex flex-wrap items-center gap-2">
                    <input
                        className="border border-slate-200 rounded-xl px-3 py-2.5 font-mono font-bold text-slate-700"
                        value={yearMonth}
                        onChange={(e) => setYearMonth(e.target.value)}
                        placeholder="YYYY-MM"
                    />
                    <button
                        onClick={loadBillings}
                        disabled={loading || loadingCards}
                        className="px-4 py-2.5 rounded-xl font-bold text-sm bg-slate-100 text-slate-700 hover:bg-slate-200 flex items-center gap-2"
                    >
                        <FontAwesomeIcon icon={faSearch} />
                        조회
                    </button>
                    <button
                        onClick={handleGenerateDrafts}
                        disabled={processing || loadingCards}
                        className={`px-4 py-2.5 rounded-xl font-bold text-sm text-white flex items-center gap-2 ${
                            processing ? 'bg-indigo-400 cursor-wait' : 'bg-indigo-600 hover:bg-indigo-700'
                        }`}
                    >
                        <FontAwesomeIcon icon={faCalculator} />
                        {processing ? '생성 중...' : '초안 생성'}
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 xl:grid-cols-12 gap-4">
                <div className="xl:col-span-4 bg-white border border-slate-200 rounded-2xl overflow-hidden">
                    <div className="p-4 border-b border-slate-100">
                        <div className="text-sm font-extrabold text-slate-900">문서 목록</div>
                        <div className="text-xs text-slate-500 font-medium mt-1">{documents.length}건</div>
                    </div>
                    <div className="max-h-[520px] overflow-y-auto">
                        {(loading || loadingCards) ? (
                            <div className="p-6 text-slate-400">불러오는 중...</div>
                        ) : documents.length === 0 ? (
                            <div className="p-6 text-slate-400">문서가 없습니다.</div>
                        ) : (
                            documents.map((d) => (
                                <button
                                    key={d.id}
                                    onClick={() => setSelectedDocumentId(d.id)}
                                    className={`w-full text-left p-4 border-b border-slate-50 hover:bg-indigo-50/30 transition ${
                                        selectedDocumentId === d.id ? 'bg-indigo-50/60' : ''
                                    }`}
                                >
                                    <div className="flex items-center justify-between">
                                        <div className="font-extrabold text-slate-800">{d.cardLabel}</div>
                                        <div className="text-xs font-bold text-slate-500">{d.status}</div>
                                    </div>
                                    <div className="text-xs text-slate-500 mt-1">
                                        {d.teamName ?? d.assignedTeamName ?? '-'} / {d.issuedToWorkerName ?? '-'}
                                    </div>
                                    <div className="text-sm font-extrabold text-indigo-700 font-mono mt-2">
                                        {Number(d.totalAmount ?? 0).toLocaleString()}원
                                    </div>
                                </button>
                            ))
                        )}
                    </div>
                </div>

                <div className="xl:col-span-8 bg-white border border-slate-200 rounded-2xl p-5">
                    {!selectedDocument ? (
                        <div className="text-slate-400">문서를 선택해주세요.</div>
                    ) : (
                        <div className="space-y-4">
                            <div className="flex flex-col md:flex-row md:items-center justify-between gap-3">
                                <div>
                                    <div className="text-xs font-bold text-slate-500">선택 문서</div>
                                    <div className="text-2xl font-extrabold text-slate-900">{selectedDocument.cardLabel}</div>
                                    <div className="text-sm text-slate-500 font-medium mt-1">
                                        {selectedDocument.teamName ?? selectedDocument.assignedTeamName ?? '-'} / {selectedDocument.issuedToWorkerName ?? '-'}
                                    </div>
                                </div>

                                <div className="flex flex-wrap items-center gap-2">
                                    <button
                                        onClick={handleSaveSelected}
                                        disabled={saving}
                                        className={`px-4 py-2.5 rounded-xl font-bold text-sm bg-indigo-50 text-indigo-700 hover:bg-indigo-100 flex items-center gap-2 ${
                                            saving ? 'opacity-60 cursor-wait' : ''
                                        }`}
                                    >
                                        <FontAwesomeIcon icon={faFloppyDisk} />
                                        저장
                                    </button>
                                    <button
                                        onClick={handleConfirmSelected}
                                        disabled={saving}
                                        className={`px-4 py-2.5 rounded-xl font-bold text-sm bg-emerald-50 text-emerald-700 hover:bg-emerald-100 flex items-center gap-2 ${
                                            saving ? 'opacity-60 cursor-wait' : ''
                                        }`}
                                    >
                                        <FontAwesomeIcon icon={faCheckDouble} />
                                        확정
                                    </button>
                                    <button
                                        onClick={handleDeleteSelected}
                                        disabled={saving}
                                        className={`px-4 py-2.5 rounded-xl font-bold text-sm bg-rose-50 text-rose-700 hover:bg-rose-100 flex items-center gap-2 ${
                                            saving ? 'opacity-60 cursor-wait' : ''
                                        }`}
                                    >
                                        <FontAwesomeIcon icon={faTrash} />
                                        삭제
                                    </button>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                                <div className="bg-slate-50 rounded-2xl p-4 border border-slate-100">
                                    <div className="text-xs font-bold text-slate-500">변동비</div>
                                    <div className="text-2xl font-extrabold text-slate-800 font-mono mt-1">
                                        {Number(selectedDocument.variableCost ?? 0).toLocaleString()}
                                    </div>
                                </div>
                                <div className="bg-slate-50 rounded-2xl p-4 border border-slate-100">
                                    <div className="text-xs font-bold text-slate-500">총액</div>
                                    <div className="text-2xl font-extrabold text-indigo-700 font-mono mt-1">
                                        {Number(selectedDocument.totalAmount ?? 0).toLocaleString()}
                                    </div>
                                </div>
                                <div className="bg-slate-50 rounded-2xl p-4 border border-slate-100">
                                    <div className="text-xs font-bold text-slate-500">상태</div>
                                    <div className="text-2xl font-extrabold text-slate-800 font-mono mt-1">{selectedDocument.status}</div>
                                </div>
                            </div>

                            <div className="bg-slate-50 rounded-2xl p-4 border border-slate-100 space-y-3">
                                <div className="flex flex-col md:flex-row md:items-center justify-between gap-3">
                                    <div>
                                        <div className="text-sm font-extrabold text-slate-900">청구서 첨부</div>
                                        <div className="text-xs text-slate-500 font-medium mt-1">PDF/이미지를 업로드하고 Gemini로 총액/항목을 추출할 수 있습니다.</div>
                                    </div>
                                    <div className="flex flex-wrap items-center gap-2">
                                        <label
                                            className={`px-4 py-2.5 rounded-xl font-bold text-sm text-white flex items-center gap-2 cursor-pointer ${
                                                uploadingAttachment ? 'bg-indigo-400 cursor-wait' : 'bg-indigo-600 hover:bg-indigo-700'
                                            }`}
                                        >
                                            <FontAwesomeIcon icon={faUpload} />
                                            {uploadingAttachment ? '업로드 중...' : '첨부 업로드'}
                                            <input
                                                type="file"
                                                className="hidden"
                                                accept="application/pdf,image/*"
                                                disabled={uploadingAttachment}
                                                onChange={(e) => {
                                                    const f = e.target.files?.[0] ?? null;
                                                    e.target.value = '';
                                                    if (f) void handleUploadAttachment(f);
                                                }}
                                            />
                                        </label>
                                        <button
                                            onClick={handleAnalyzeAttachment}
                                            disabled={analyzingAttachment || uploadingAttachment || !isAiEnabledOnPage}
                                            className={`px-4 py-2.5 rounded-xl font-bold text-sm bg-slate-900 text-white hover:bg-slate-800 flex items-center gap-2 ${
                                                analyzingAttachment ? 'opacity-60 cursor-wait' : ''
                                            }`}
                                        >
                                            <FontAwesomeIcon icon={faMagnifyingGlass} />
                                            {analyzingAttachment ? '분석 중...' : (isAiEnabledOnPage ? 'Gemini 분석' : 'AI 비활성')}
                                        </button>
                                    </div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
                                    <div className="md:col-span-2">
                                        <div className="text-xs font-bold text-slate-600 mb-1">첨부 파일</div>
                                        <select
                                            className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm font-bold text-slate-700"
                                            value={selectedAttachmentPath}
                                            onChange={(e) => setSelectedAttachmentPath(e.target.value)}
                                        >
                                            <option value="">선택하세요</option>
                                            {(selectedDocument.statementAttachmentPaths ?? []).map((p) => (
                                                <option key={p} value={p}>
                                                    {p}
                                                </option>
                                            ))}
                                        </select>
                                    </div>
                                    <div>
                                        <div className="text-xs font-bold text-slate-600 mb-1">열기</div>
                                        <button
                                            onClick={() => void handleOpenAttachment(selectedAttachmentPath)}
                                            disabled={!selectedAttachmentPath}
                                            className={`w-full px-4 py-2.5 rounded-xl font-bold text-sm bg-white border border-slate-200 text-slate-700 hover:bg-slate-50 ${
                                                !selectedAttachmentPath ? 'opacity-60 cursor-not-allowed' : ''
                                            }`}
                                        >
                                            첨부 열기
                                        </button>
                                    </div>
                                </div>
                            </div>

                            <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden">
                                <div className="px-4 py-3 bg-slate-900 text-white font-extrabold text-sm">라인 아이템</div>
                                <div className="overflow-x-auto">
                                    <table className="w-full text-sm min-w-[720px]">
                                        <thead className="bg-slate-100 text-slate-600 text-xs font-bold">
                                            <tr>
                                                <th className="px-4 py-3 text-left">항목</th>
                                                <th className="px-4 py-3 text-left">카테고리</th>
                                                <th className="px-4 py-3 text-right">금액</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-slate-100">
                                            {(selectedDocument.lineItems ?? []).length === 0 ? (
                                                <tr>
                                                    <td colSpan={3} className="px-4 py-6 text-slate-400 text-center">라인 아이템이 없습니다.</td>
                                                </tr>
                                            ) : (
                                                (selectedDocument.lineItems ?? []).map((li) => (
                                                    <tr key={li.id} className="hover:bg-indigo-50/20">
                                                        <td className="px-4 py-3 font-bold text-slate-800">{li.label}</td>
                                                        <td className="px-4 py-3 text-slate-600">{li.category ?? '-'}</td>
                                                        <td className="px-4 py-3 text-right font-mono font-extrabold text-slate-800">{Number(li.amount ?? 0).toLocaleString()}</td>
                                                    </tr>
                                                ))
                                            )}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useMemo, useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faBan, faChartPie, faCheckCircle, faClock, faCreditCard, faLock,
    faUser, faUsers, faList, faTh, faPlus, faFileInvoiceDollar
} from '@fortawesome/free-solid-svg-icons';
import { Worker, manpowerService } from '../../services/manpowerService';

import { Card } from '../../types/card';
import { Team } from '../../services/teamService';
import { iconMap } from '../../constants/iconMap';

interface TeamInfo {
    color: string;
    icon?: string;
}

interface CardStatusBoardProps {
    cards: Card[];
    teams?: Team[];
    loading: boolean;
    onEdit: (card: Card) => void;
    onAssign: (card: Card) => void;
    onOpenBilling: (card: Card) => void;
}

const getTeamFaIcon = (iconName?: string) => {
    if (!iconName) return faUsers;
    return iconMap[iconName] || faUsers;
};

const hexToRgba = (hex: string, alpha: number) => {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return `rgba(${r},${g},${b},${alpha})`;
};

export const CardStatusBoard: React.FC<CardStatusBoardProps> = ({ cards, teams = [], loading, onEdit, onAssign, onOpenBilling }) => {
    const [viewMode, setViewMode] = useState<'list' | 'card'>('list');
    const [workers, setWorkers] = useState<Worker[]>([]);

    // Worker 데이터 로드 (개인 배정 시 팀 색상 확인용)
    React.useEffect(() => {
        const loadWorkers = async () => {
            try {
                const data = await manpowerService.getWorkers();
                setWorkers(data);
            } catch (e) {
                console.error('Failed to load workers:', e);
            }
        };
        loadWorkers();
    }, []);

    // Build team info map: teamName -> {color, icon}
    const teamInfoMap = useMemo(() => {
        const map = new Map<string, TeamInfo>();
        teams.forEach(t => {
            if (t.color && t.name) map.set(t.name, { color: t.color, icon: t.icon || t.iconKey });
        });
        return map;
    }, [teams]);

    // Worker -> Team 정보 매핑
    const workerTeamMap = useMemo(() => {
        const map = new Map<string, TeamInfo>();
        workers.forEach(w => {
            if (w.name && w.teamName) {
                const tInfo = teamInfoMap.get(w.teamName);
                if (tInfo) map.set(w.name, tInfo);
            }
        });
        return map;
    }, [workers, teamInfoMap]);

    const stats = useMemo(() => {
        // ... (existing stats logic)
        const total = cards.length;
        const assigned = cards.filter((c) => c.status === 'ASSIGNED').length;
        const available = cards.filter((c) => c.status === 'AVAILABLE').length;
        const suspended = cards.filter((c) => c.status === 'SUSPENDED').length;
        const closed = cards.filter((c) => c.status === 'CLOSED').length;
        return { total, assigned, available, suspended, closed };
    }, [cards]);

    const getStatusBadge = (status: string) => {
        switch (status) {
            case 'ASSIGNED':
                return <span className="px-2 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-700">배정됨</span>;
            case 'AVAILABLE':
                return <span className="px-2 py-0.5 rounded-full text-xs font-medium bg-emerald-100 text-emerald-700">보관중</span>;
            case 'SUSPENDED':
                return <span className="px-2 py-0.5 rounded-full text-xs font-medium bg-amber-100 text-amber-700">분실/정지</span>;
            case 'CLOSED':
                return <span className="px-2 py-0.5 rounded-full text-xs font-medium bg-slate-100 text-slate-500">해지됨</span>;
            default:
                return <span className="px-2 py-0.5 rounded-full text-xs font-medium bg-slate-100 text-slate-500">-</span>;
        }
    };



    const getCardTypeLabel = (type: string) => {
        if (type === 'CREDIT') return <span className="text-purple-600 font-bold text-xs">신용</span>;
        if (type === 'CHECK') return <span className="text-indigo-600 font-bold text-xs">체크</span>;
        return <span className="text-slate-500 text-xs">-</span>;
    };

    const getBillingTargetTypeLabel = (card: Card) => {
        if (!card.currentAssigneeName) return null;
        return card.currentAssigneeType === 'TEAM' ? '팀' : '개인';
    };

    // ... (existing loading and empty state checks)

    return (
        <div className="space-y-8 animate-fade-in-up">
            {/* ... (existing Stats Cards and View Mode Toggle) */}

            {/* ── 목록형 (Table) ── */}
            {viewMode === 'list' ? (
                <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm">
                            {/* ... (thead) */}
                            <thead className="bg-slate-50 border-b border-slate-200">
                                <tr>
                                    <th className="text-left px-4 py-3 font-bold text-slate-500 text-xs uppercase tracking-wider w-8">#</th>
                                    <th className="text-left px-4 py-3 font-bold text-slate-500 text-xs uppercase tracking-wider">카드명</th>
                                    <th className="text-left px-4 py-3 font-bold text-slate-500 text-xs uppercase tracking-wider">발급사</th>
                                    <th className="text-center px-4 py-3 font-bold text-slate-500 text-xs uppercase tracking-wider">유형</th>
                                    <th className="text-center px-4 py-3 font-bold text-slate-500 text-xs uppercase tracking-wider">카드번호</th>
                                    <th className="text-center px-4 py-3 font-bold text-slate-500 text-xs uppercase tracking-wider">유효기간</th>
                                    <th className="text-center px-4 py-3 font-bold text-slate-500 text-xs uppercase tracking-wider">상태</th>
                                    <th className="text-left px-4 py-3 font-bold text-slate-500 text-xs uppercase tracking-wider">배정</th>
                                    <th className="text-left px-4 py-3 font-bold text-slate-500 text-xs uppercase tracking-wider">청구대상</th>
                                    <th className="text-left px-4 py-3 font-bold text-slate-500 text-xs uppercase tracking-wider">메모</th>
                                    <th className="text-center px-4 py-3 font-bold text-slate-500 text-xs uppercase tracking-wider w-16"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {cards.map((card, rowIdx) => {
                                    // 팀 배정 or 개인 배정(workerTeamMap) 확인
                                    const teamInfo = card.currentAssigneeType === 'TEAM' && card.currentAssigneeName
                                        ? teamInfoMap.get(card.currentAssigneeName)
                                        : (card.currentAssigneeType !== 'TEAM' && card.currentAssigneeName
                                            ? workerTeamMap.get(card.currentAssigneeName)
                                            : undefined);

                                    const tc = teamInfo?.color;
                                    const billingTargetTypeLabel = getBillingTargetTypeLabel(card);

                                    return (
                                        <tr
                                            key={card.id}
                                            onClick={() => onEdit(card)}
                                            className="hover:bg-indigo-50/40 cursor-pointer transition-colors group"
                                            style={tc ? { borderLeft: `3px solid ${tc}` } : undefined}
                                        >
                                            {/* ... (existing td cells except Assignee) */}
                                            <td className="px-4 py-3 text-xs text-slate-400 font-mono">{rowIdx + 1}</td>
                                            <td className="px-4 py-3">
                                                <span className="font-bold text-slate-800 group-hover:text-indigo-600 transition-colors">
                                                    {card.name}
                                                </span>
                                            </td>
                                            <td className="px-4 py-3 text-xs text-slate-500 font-medium">
                                                {card.issuer}
                                            </td>
                                            <td className="px-4 py-3 text-center">
                                                <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold ${card.cardType === 'CREDIT'
                                                    ? 'bg-violet-50 text-violet-600 border border-violet-100'
                                                    : 'bg-sky-50 text-sky-600 border border-sky-100'
                                                    }`}>
                                                    {getCardTypeLabel(card.cardType)}
                                                </span>
                                            </td>
                                            <td className="px-4 py-3 text-center">
                                                <span className="font-mono text-xs text-slate-600">{card.maskedNumber || '-'}</span>
                                            </td>
                                            <td className="px-4 py-3 text-center text-xs text-slate-500">
                                                {card.expiry || '-'}
                                            </td>
                                            <td className="px-4 py-3 text-center">
                                                {getStatusBadge(card.status)}
                                            </td>

                                            <td className="px-4 py-3">
                                                {card.currentAssigneeName ? (
                                                    <span
                                                        className="inline-flex items-center gap-1.5 px-2 py-1 rounded-md text-xs font-bold"
                                                        style={tc ? {
                                                            backgroundColor: hexToRgba(tc, 0.1),
