import React, { useEffect, useState } from 'react';
import { componentService, ComponentConfig } from '../../services/componentService';

interface ComponentGuardProps {
    id: string; // Component ID registered in Service
    children: React.ReactNode;
    fallback?: React.ReactNode;
}

const ComponentGuard: React.FC<ComponentGuardProps> = ({ id, children, fallback = null }) => {
    const [config, setConfig] = useState<ComponentConfig | undefined>(componentService.getConfig(id));
    const [isVisible, setIsVisible] = useState(true);

    useEffect(() => {
        // Initial Check
        updateVisibility();

        const unsubscribe = componentService.subscribe(() => {
            setConfig(componentService.getConfig(id));
            updateVisibility();
        });

        return () => unsubscribe();
    }, [id]);

    const updateVisibility = () => {
        // If config requires roles, check them (TODO: Import user role)
        // For now, simple Enabled toggle
        const isEnabled = componentService.isEnabled(id);
        setIsVisible(isEnabled);
    };

    if (!isVisible) return <>{fallback}</>;

    return <>{children}</>;
};

export default ComponentGuard;

import React, { useEffect, useState, ChangeEvent } from 'react';

interface CurrencyInputProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'onChange' | 'value'> {
    value: number;
    onChange: (value: number) => void;
}

export const CurrencyInput: React.FC<CurrencyInputProps> = ({
    value,
    onChange,
    className,
    ...props
}) => {
    const [displayValue, setDisplayValue] = useState('');

    // 부모로부터 value가 변경되면 displayValue 업데이트 (포맷팅 적용)
    useEffect(() => {
        // value가 유효한 숫자이면 포맷팅, 아니면 빈 문자열(또는 0 처리가 필요할 수 있음)
        // 여기서는 0도 "0"으로 표시.
        if (typeof value === 'number' && !Number.isNaN(value)) {
            setDisplayValue(new Intl.NumberFormat('ko-KR').format(value));
        } else {
            setDisplayValue('');
        }
    }, [value]);

    const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
        const rawValue = e.target.value.replace(/,/g, '');

        // 빈 값 처리 (0으로 간주하거나, 필요시 커스텀 가능)
        if (rawValue === '' || rawValue === '-') {
            setDisplayValue(e.target.value);
            onChange(0);
            return;
        }

        // 숫자(정수)만 허용 (마이너스 포함)
        if (!/^[-]?\d*$/.test(rawValue)) {
            return;
        }

        const numValue = Number(rawValue);
        if (!Number.isNaN(numValue)) {
            // 입력 중에는 콤마를 제거한 상태로 부모에게 전달 -> 부모가 state 업데이트 -> useEffect가 다시 포맷팅
            // 단, useEffect 의존성에 의해 커서 점프 문제가 발생할 수 있음.
            // 간단한 해결책: 입력 시점에는 로컬 state(displayValue)를 사용자가 입력한 값(콤마 포함 로직 적용 전)으로 유지하고,
            // 부모의 값이 들어올 때 포맷팅하는 방식은 타이핑 중 콤마 자동 삽입이 안 될 수 있음.
            // 여기서는 "입력 즉시 포맷팅"을 위해 Intl.NumberFormat 사용.

            const formatted = new Intl.NumberFormat('ko-KR').format(numValue);
            // 만약 입력한 값이 이미 포맷팅된 것과 같다면 그대로 둠 (커서 문제 완화)

            onChange(numValue);
        }
    };

    return (
        <input
            type="text"
            className={className} // Tailwind 클래스 등 전달
            value={displayValue}
            onChange={handleChange}
            {...props}
        />
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCheck, faPen, faTimes } from '@fortawesome/free-solid-svg-icons';

interface InputPopoverProps {
    value: string | number;
    onChange: (value: string | number) => void;
    type?: 'text' | 'number' | 'tel';
    placeholder?: string;
    minimal?: boolean;
    disabled?: boolean;
    formatDisplay?: (value: string | number) => React.ReactNode;
    suffix?: string;
    isCard?: boolean;
}

const InputPopover: React.FC<InputPopoverProps> = ({
    value,
    onChange,
    type = 'text',
    placeholder = '입력하세요',
    minimal = false,
    disabled = false,
    formatDisplay,
    suffix,
    isCard = false
}) => {
    const [isOpen, setIsOpen] = useState(false);
    const [inputValue, setInputValue] = useState<string | number>('');
    const wrapperRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, [wrapperRef]);

    useEffect(() => {
        if (isOpen) {
            setInputValue(value || '');
            // Focus input after open
            setTimeout(() => {
                inputRef.current?.focus();
                inputRef.current?.select();
            }, 50);
        }
    }, [isOpen, value]);

    const handleSubmit = (e?: React.FormEvent) => {
        e?.preventDefault();
        onChange(type === 'number' ? Number(inputValue) : inputValue);
        setIsOpen(false);
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter') {
            handleSubmit();
        } else if (e.key === 'Escape') {
            setIsOpen(false);
        }
    };

    if (disabled) {
        return (
            <div className={`py-1 px-2 ${minimal ? '' : 'bg-slate-50 border border-slate-200 rounded text-slate-500'}`}>
                {formatDisplay ? formatDisplay(value) : value}{suffix}
            </div>
        );
    }

    return (
        <div className="relative inline-block w-full" ref={wrapperRef}>
            <div
                className={`w-full py-1.5 px-3 rounded leading-tight cursor-pointer flex justify-between items-center transition-colors
                    ${minimal
                        ? 'bg-transparent border border-transparent hover:bg-slate-100'
                        : 'bg-white border border-slate-300 focus:outline-none focus:bg-white focus:border-indigo-500'}`}
                onClick={() => !disabled && setIsOpen(!isOpen)}
            >
                <div className="truncate text-sm flex items-center gap-2 flex-1 justify-end">
                    <span className={`${!value ? 'text-slate-400' : 'text-slate-800'}`}>
                        {formatDisplay ? formatDisplay(value) : (value || placeholder)}
                        {value && suffix && <span className="text-slate-500 ml-0.5">{suffix}</span>}
                    </span>
                    {!minimal && !value && <FontAwesomeIcon icon={faPen} className="text-xs text-slate-300" />}
                </div>
            </div>

            {isOpen && (
                <div className="absolute z-50 mt-1 right-0 min-w-[200px] bg-white border border-slate-200 rounded-lg shadow-xl animate-in fade-in zoom-in duration-200 p-3">
                    <form onSubmit={handleSubmit} className="flex flex-col gap-2">
                        <div className="relative">
                            <input
                                ref={inputRef}
                                type={type}
                                value={inputValue}
                                onChange={(e) => setInputValue(e.target.value)}
                                onKeyDown={handleKeyDown}
                                className="w-full px-3 py-2 text-sm border border-slate-200 rounded focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 bg-white"
                                placeholder={placeholder}
                            />
                            {suffix && <span className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs">{suffix}</span>}
                        </div>
                        <div className="flex justify-end gap-2">
                            <button
                                type="button"
                                onClick={() => setIsOpen(false)}
                                className="px-2 py-1 text-xs text-slate-500 hover:bg-slate-100 rounded"
                            >
                                취소
                            </button>
                            <button
                                type="submit"
                                className="px-3 py-1 text-xs bg-indigo-600 text-white rounded hover:bg-indigo-700 font-medium"
                            >
                                확인
                            </button>
                        </div>
                    </form>
                </div>
            )}
        </div>
    );
};

export default InputPopover;

import React, { useState, useEffect } from 'react';
import { companyService, Company } from '../../services/companyService';
import CompanyForm from './CompanyForm';
import CompanyTable from './CompanyTable';
import CompanyModal from './CompanyModal';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faSearch, faPlus } from '@fortawesome/free-solid-svg-icons';

const CompanyManagement: React.FC = () => {
    const [companies, setCompanies] = useState<Company[]>([]);
    const [filteredCompanies, setFilteredCompanies] = useState<Company[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isRegistrationOpen, setIsRegistrationOpen] = useState(false);
    const [currentCompany, setCurrentCompany] = useState<Company | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        fetchData();
    }, []);

    useEffect(() => {
        const filtered = companies.filter(c =>
            c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            (c.code ?? '').toLowerCase().includes(searchQuery.toLowerCase()) ||
            (c.ceoName ?? '').toLowerCase().includes(searchQuery.toLowerCase())
        );
        setFilteredCompanies(filtered);
    }, [companies, searchQuery]);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const data = await companyService.getCompanies();
            setCompanies(data);
        } catch (error) {
            console.error("Failed to fetch companies", error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleSaveCompany = async (companyData: Omit<Company, 'id'> | Partial<Company>) => {
        try {
            if (currentCompany && currentCompany.id) {
                await companyService.updateCompany(currentCompany.id, companyData);
            } else {
                await companyService.addCompany(companyData as Omit<Company, 'id'>);
            }
            fetchData();
            setIsModalOpen(false);
            setIsRegistrationOpen(false);
        } catch (error) {
            console.error("Failed to save company", error);
            alert("저장에 실패했습니다.");
        }
    };

    const handleDeleteClick = async (e: React.MouseEvent, company: Company) => {
        e.stopPropagation();
        if (!company.id) return;
        if (window.confirm(`[${company.name}] 회사를 정말 삭제하시겠습니까?`)) {
            try {
                await companyService.deleteCompany(company.id);
                await fetchData();
                alert("삭제되었습니다.");
            } catch (error) {
                console.error("Failed to delete company", error);
                alert("삭제에 실패했습니다.");
            }
        }
    };

    const handleEditCompany = (company: Company) => {
        setCurrentCompany(company);
        setIsModalOpen(true);
    };

    const handleNewCompany = () => {
        setCurrentCompany(null);
        setIsRegistrationOpen(!isRegistrationOpen);
    };

    return (
        <div className="h-full flex flex-col gap-4 p-4 max-w-full mx-auto w-full">
            {/* Toolbar */}
            <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div className="flex items-center gap-3 w-full sm:w-auto">
                    <div className="relative flex-1 sm:flex-none sm:w-64">
                        <FontAwesomeIcon icon={faSearch} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                        <input
                            type="text"
                            placeholder="회사명, 코드, 대표자명 검색..."
                            className="w-full pl-10 pr-4 py-2 bg-slate-50 border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                    </div>
                </div>

                <div className="flex items-center gap-2 w-full sm:w-auto">
                    <button
                        onClick={handleNewCompany}
                        title="회사 등록"
                        className="flex items-center gap-2 px-3 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors shadow-sm shadow-indigo-200 whitespace-nowrap"
                    >
                        <FontAwesomeIcon icon={faPlus} />
                        <span>회사 등록</span>
                    </button>
                </div>
            </div>

            {/* Registration Accordion */}
            <div className={`transition-all duration-300 ease-in-out overflow-hidden ${isRegistrationOpen ? 'max-h-[800px] opacity-100 mb-4' : 'max-h-0 opacity-0'}`}>
                <CompanyForm
                    onCancel={() => setIsRegistrationOpen(false)}
                    onSave={handleSaveCompany}
                />
            </div>

            {/* Table Container */}
            <CompanyTable
                companies={filteredCompanies}
                handleEditCompany={handleEditCompany}
                handleDeleteClick={handleDeleteClick}
            />

            {/* Modal */}
            {isModalOpen && (
                <CompanyModal
                    isOpen={isModalOpen}
                    onClose={() => setIsModalOpen(false)}
                    onSave={handleSaveCompany}
                    initialData={currentCompany || undefined}
                />
            )}
        </div>
    );
};

export default CompanyManagement;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { manpowerService } from '../../services/manpowerService';
import { siteService } from '../../services/siteService';
import { teamService } from '../../services/teamService';
import { dailyReportService } from '../../services/dailyReportService';
import { companyService } from '../../services/companyService';
import { taskService } from '../../services/taskService';
import { Task, STATUS_CONFIG } from '../../types/task';
import WeatherWidget from '../widgets/WeatherWidget';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faUsers, faBuilding, faClipboardList, faHardHat,
    faArrowRight, faChartLine, faCalendarCheck, faFileInvoiceDollar,
    faDatabase, faCog, faSpinner, faHandHoldingDollar, faRightLeft,
    faSignature, faFileSignature, faMoneyBillTrendUp,
    faPaperPlane, faListCheck, faFileExcel
} from '@fortawesome/free-solid-svg-icons';

export const DashboardExecutiveView: React.FC = () => {
    const { currentUser } = useAuth();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(true);
    const [stats, setStats] = useState({
        workers: { total: 0, active: 0 },
        sites: { total: 0, active: 0 },
        teams: { total: 0 },
        reports: { today: 0, thisMonth: 0, todayManDay: 0, thisMonthManDay: 0 },
        support: { inbound: 0, outbound: 0, total: 0 },
        recentReports: [] as any[],
        recentTasks: [] as Task[]
    });

    useEffect(() => {
        let isMounted = true;

        const initDashboard = async () => {
            if (!currentUser?.uid) {
                if (isMounted) setLoading(false);
                return;
            }

            try {
                // Fetch Stats Data
                const [workersData, sitesData, teamsData, reportsData, companiesData] = await Promise.all([
                    manpowerService.getWorkersPaginated(1000),
                    siteService.getSites(),
                    teamService.getTeams(),
                    dailyReportService.getAllReports(),
                    companyService.getCompanies()
                ]);

                if (!isMounted) return;

                const now = new Date();
                const todayStr = now.toISOString().split('T')[0];
                const thisMonthStr = todayStr.substring(0, 7);

                // Identify My Company (Default to '청연' or first one)
                const myCompany = companiesData.find(c => c.name.includes('청연')) || companiesData[0];
                const myCompanyId = myCompany?.id;

                // Calculate Support Man-days for This Month
                let inboundManDay = 0;
                let outboundManDay = 0;

                if (myCompanyId) {
                    const thisMonthReports = reportsData.filter(r => r.date.startsWith(thisMonthStr));
                    const siteMap = new Map(sitesData.map(s => [s.id, s]));
                    const teamMap = new Map(teamsData.map(t => [t.id, t]));

                    thisMonthReports.forEach(report => {
                        const site = siteMap.get(report.siteId);
                        const team = teamMap.get(report.teamId);

                        if (site && team) {
                            const manDay = Number(report.totalManDay) || 0;

                            // Inbound: My Site, Other Team (Received Support)
                            if (site.companyId === myCompanyId && team.companyId !== myCompanyId) {
                                inboundManDay += manDay;
                            }
                            // Outbound: Other Site, My Team (Sent Support)
                            if (site.companyId !== myCompanyId && team.companyId === myCompanyId) {
                                outboundManDay += manDay;
                            }
                        }
                    });
                }

                setStats(prev => ({
                    ...prev,
                    workers: {
                        total: workersData.workers.length,
                        active: workersData.workers.filter(w => w.status === '재직').length
                    },
                    sites: {
                        total: sitesData.length,
                        active: sitesData.filter(s => s.status === 'active').length
                    },
                    teams: {
                        total: teamsData.length
                    },
                    reports: {
                        today: reportsData.filter(r => r.date === todayStr).length,
                        thisMonth: reportsData.filter(r => r.date.startsWith(thisMonthStr)).length,
                        todayManDay: reportsData.filter(r => r.date === todayStr).reduce((sum, r) => sum + (Number(r.totalManDay) || 0), 0),
                        thisMonthManDay: reportsData.filter(r => r.date.startsWith(thisMonthStr)).reduce((sum, r) => sum + (Number(r.totalManDay) || 0), 0)
                    },
                    support: {
                        inbound: inboundManDay,
                        outbound: outboundManDay,
                        total: inboundManDay + outboundManDay
                    },
                    recentReports: reportsData
                        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
                        .slice(0, 5)
                }));

            } catch (error) {
                console.error("Dashboard data load failed", error);
            } finally {
                if (isMounted) setLoading(false);
            }
        };

        initDashboard();

        // Subscribe to Tasks (Real-time)
        const unsubscribeTasks = taskService.subscribe((tasksData) => {
            if (!isMounted) return;
            setStats(prev => ({
                ...prev,
                recentTasks: tasksData
                    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
                    .slice(0, 5)
            }));
        });

        return () => {
            isMounted = false;
            unsubscribeTasks();
        };
    }, [currentUser]);

    if (loading) {
        return (
            <div className="flex items-center justify-center p-12">
                <div className="text-center">
                    <FontAwesomeIcon icon={faSpinner} spin className="text-4xl text-brand-600 mb-4" />
                    <p className="text-slate-500 font-medium">시스템 데이터를 불러오는 중입니다...</p>
                </div>
            </div>
        );
    }

    return (
        <DashboardExecutiveViewContent stats={stats} />
    );
};

