import { useState, useCallback, useRef } from 'react';
import { produce } from 'immer';
import { BuilderElement } from './types';

interface UseBuilderReturn {
    elements: BuilderElement[];
    selection: string[];
    addElement: (type: 'text' | 'table', initialProps?: Partial<BuilderElement>) => void;
    updateElement: (id: string, updates: Partial<BuilderElement>) => void;
    updateSelection: (id: string | null, multi?: boolean) => void;
    deleteSelection: () => void;
    undo: () => void;
    redo: () => void;
    canUndo: boolean;
    canRedo: boolean;
    setElements: (elements: BuilderElement[]) => void;
    moveSelection: (dx: number, dy: number) => void;
}

const MAX_HISTORY = 50;

export const useBuilder = (initialElements: BuilderElement[] = []): UseBuilderReturn => {
    const [elements, _setElements] = useState<BuilderElement[]>(initialElements);
    const [selection, setSelection] = useState<string[]>([]);

    // History
    const historyRef = useRef<{ past: BuilderElement[][]; future: BuilderElement[][] }>({
        past: [],
        future: []
    });

    // Helper to push state to history
    const pushHistory = (newElements: BuilderElement[]) => {
        const { past } = historyRef.current;
        const newPast = [...past, elements];
        if (newPast.length > MAX_HISTORY) newPast.shift();

        historyRef.current = {
            past: newPast,
            future: []
        };
        _setElements(newElements);
    };

    const addElement = useCallback((type: 'text' | 'table', initialProps: Partial<BuilderElement> = {}) => {
        const newElement: BuilderElement = {
            id: `${type}-${Date.now()}`,
            type,
            x: 10,
            y: 10,
            width: type === 'table' ? 180 : 60,
            height: type === 'table' ? 50 : 10,
            isSelected: false,
            style: {
                fontSize: 10,
                fontWeight: 'normal',
                textAlign: 'left',
                color: '#000000',
                ...initialProps.style
            },
            content: {
                text: type === 'text' ? '텍스트를 입력하세요' : '',
                ...initialProps.content
            },
            ...initialProps
        };

        pushHistory([...elements, newElement]);
        setSelection([newElement.id]);
    }, [elements]);

    const updateElement = useCallback((id: string, updates: Partial<BuilderElement>) => {
        const nextElements = produce(elements, draft => {
            const index = draft.findIndex(el => el.id === id);
            if (index !== -1) {
                // Merge top-level properties
                Object.assign(draft[index], updates);
                // Merge nested style if provided
                if (updates.style) {
                    draft[index].style = { ...draft[index].style, ...updates.style };
                }
                // Merge nested content if provided
                if (updates.content) {
                    draft[index].content = { ...draft[index].content, ...updates.content };
                }
            }
        });

        // Optimize history: Don't push if nothing changed (deep check is expensive, assume 'updates' intends change)
        // For dragging, we might want to debounce history pushing, but for now strict strict simple.
        // Actually for high-freq updates like drag, this might be too heavy. 
        // usually drag -> temp state -> dragEnd -> history push.
        // We will assume 'updateElement' is called on dragEnd.

        pushHistory(nextElements);
    }, [elements]);

    const updateSelection = useCallback((id: string | null, multi: boolean = false) => {
        if (id === null) {
            setSelection([]);
            return;
        }
        if (multi) {
            setSelection(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
        } else {
            setSelection([id]);
        }
    }, []);

    const deleteSelection = useCallback(() => {
        if (selection.length === 0) return;

        const nextElements = elements.filter(el => !selection.includes(el.id));
        pushHistory(nextElements);
        setSelection([]);
    }, [elements, selection]);

    const undo = useCallback(() => {
        const { past, future } = historyRef.current;
        if (past.length === 0) return;

        const previous = past[past.length - 1];
        const newPast = past.slice(0, past.length - 1);

        historyRef.current = {
            past: newPast,
            future: [elements, ...future]
        };
        _setElements(previous);
    }, [elements]);

    const moveSelection = useCallback((dx: number, dy: number) => {
        if (selection.length === 0) return;

        const nextElements = produce(elements, draft => {
            draft.forEach(el => {
                if (selection.includes(el.id)) {
                    el.x += dx;
                    el.y += dy;
                }
            });
        });

        // Update state directly without history for every pixel move if it's continuous? 
        // For Nudge (keyboard), we usually want history.
        // Let's push to history for now, or maybe debounce it?
        // For keyboard nudge, individual key presses are distinct actions, so history is fine.
        pushHistory(nextElements);
    }, [elements, selection]);

    const redo = useCallback(() => {
        const { past, future } = historyRef.current;
        if (future.length === 0) return;

        const next = future[0];
        const newFuture = future.slice(1);

        historyRef.current = {
            past: [...past, elements],
            future: newFuture
        };
        _setElements(next);
    }, [elements]);

    return {
        elements,
        selection,
        addElement,
        updateElement,
        updateSelection,
        deleteSelection,
        undo,
        redo,
        canUndo: historyRef.current.past.length > 0,
        canRedo: historyRef.current.future.length > 0,
        setElements: (els) => {
            pushHistory(els);
            setSelection([]);
        },
        moveSelection
    };
};

import React, { useState, useCallback, useRef } from 'react';
import * as XLSX from 'xlsx';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faCloudUploadAlt, faCheckCircle, faSpinner, faExclamationTriangle,
    faFileExcel, faArrowRight, faDatabase, faTimes, faDownload, faCog
} from '@fortawesome/free-solid-svg-icons';
import Swal from 'sweetalert2';

// --- Types ---
export interface FieldDef {
    key: string;            // Internal key (e.g., 'name')
    label: string;          // Display label (e.g., '이름')
    required?: boolean;     // Is mandatory?
    aliases?: string[];     // Auto-match headers (e.g., ['성명', '작업자명'])
    example?: string;       // Example value for guide
}

export interface ValidationResult {
    isValid: boolean;
    errors: string[];
    warnings: string[];
    status?: 'NEW' | 'UPDATE' | 'IDENTICAL';
    changes?: { field: string; oldValue: any; newValue: any }[];
}

export interface SampleDataRow {
    [key: string]: string | number;
}

export interface ExcelWizardProps<T> {
    title: string;
    description?: string;
    fields: FieldDef[];
    onValidate: (row: any) => Promise<ValidationResult> | ValidationResult; // Row-level validation
    onSaveBatch: (rows: T[], options?: { overwrite: boolean }) => Promise<{ success: number; failed: number; skipped?: number }>;
    sampleFileName?: string; // 샘플 파일명 (확장자 제외)
    sampleData?: SampleDataRow[]; // 샘플 데이터 (2-3개 예시 행)
    defaultBatchSize?: number; // 배치 크기 (기본 50)
}

// 에러 로그 타입
interface ErrorLogEntry {
    rowIndex: number;
    rowData: Record<string, any>;
    errors: string[];
    warnings: string[];
    status: 'NEW' | 'UPDATE' | 'IDENTICAL' | 'ERROR';
    timestamp: string;
}

// --- Steps ---
type Step = 'UPLOAD' | 'MAPPING' | 'PREVIEW' | 'SAVING' | 'COMPLETE';

const ExcelUploadWizard = <T extends Record<string, any>>({
    title,
    description,
    fields,
    onValidate,
    onSaveBatch,
    sampleFileName,
    sampleData,
    defaultBatchSize = 50
}: ExcelWizardProps<T>) => {

    // State
    const [step, setStep] = useState<Step>('UPLOAD');
    const [rawFile, setRawFile] = useState<File | null>(null);
    const [excelHeaders, setExcelHeaders] = useState<string[]>([]);
    const [rawRows, setRawRows] = useState<any[]>([]); // Raw Excel JSON
    const [fieldMapping, setFieldMapping] = useState<Record<string, string>>({}); // fieldKey -> excelHeader
    const [previewData, setPreviewData] = useState<(T & { _validation?: ValidationResult; _rowIndex?: number })[]>([]);

    // Progress State
    const [progress, setProgress] = useState(0);
    const [log, setLog] = useState<string[]>([]);
    const [resultSummary, setResultSummary] = useState({ success: 0, failed: 0, skipped: 0, total: 0 });

    // Error Log State (상세 에러 로그)
    const [errorLogs, setErrorLogs] = useState<ErrorLogEntry[]>([]);

    // Settings State
    const [batchSize, setBatchSize] = useState(defaultBatchSize);
    const [showSettings, setShowSettings] = useState(false);

    const downloadSampleExcel = () => {
        const headers = fields.map(f => f.label);
        let dataRows: any[];

        if (sampleData && sampleData.length > 0) {
            dataRows = sampleData.map(row => {
                const converted: Record<string, any> = {};
                fields.forEach(f => {
                    converted[f.label] = row[f.key] ?? '';
                });
                return converted;
            });
        } else {
            // Default sample generation using example values
            const row1: Record<string, any> = {};
            const row2: Record<string, any> = {};
            fields.forEach(f => {
                row1[f.label] = f.example || `예시_${f.label}`;
                row2[f.label] = f.example ? `${f.example}_2` : `예시_${f.label}_2`;
            });
            dataRows = [row1, row2];
        }

        const ws = XLSX.utils.json_to_sheet(dataRows, { header: headers });
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, '데이터');
        const fileName = sampleFileName || 'sample_upload_template';
        XLSX.writeFile(wb, `${fileName}_${new Date().toISOString().slice(0, 10)}.xlsx`);
    };

    // --- 1. File Upload Logic ---
    const handleFileDrop = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        const file = e.dataTransfer.files[0];
        if (file) processFile(file);
    }, []);

    const processFile = (file: File) => {
        const reader = new FileReader();
        reader.onload = (evt) => {
            const bstr = evt.target?.result;
            const wb = XLSX.read(bstr, { type: 'binary' });
            const wsName = wb.SheetNames[0];
            const ws = wb.Sheets[wsName];

            // Read Headers
            const headers = XLSX.utils.sheet_to_json(ws, { header: 1 })[0] as string[];
            // Read Data
            const data = XLSX.utils.sheet_to_json(ws);

            setRawFile(file);
            setExcelHeaders(headers);
            setRawRows(data);

            // Auto mapping
            const initialMapping: Record<string, string> = {};
            fields.forEach(field => {
                const matched = headers.find(h =>
                    h === field.label ||
                    field.aliases?.includes(h) ||
                    h.includes(field.label) // Fuzzy
                );
                if (matched) initialMapping[field.key] = matched;
            });
            setFieldMapping(initialMapping);

            setStep('MAPPING');
        };
        reader.readAsBinaryString(file);
    };

    // --- 2. Mapping Logic ---
    const handleMappingChange = (fieldKey: string, header: string) => {
        setFieldMapping(prev => ({ ...prev, [fieldKey]: header }));
    };

    const proceedToPreview = async () => {
        // validate mapping
        const missingRequired = fields.filter(f => f.required && !fieldMapping[f.key]);
        if (missingRequired.length > 0) {
            Swal.fire('Error', `필수 항목이 연결되지 않았습니다: ${missingRequired.map(f => f.label).join(', ')}`, 'error');
            return;
        }

        // Transform Data
        const mapped = await Promise.all(rawRows.map(async (row, index) => {
            const newRow: any = {};
            fields.forEach(f => {
                const header = fieldMapping[f.key];
                if (header) {
                    newRow[f.key] = row[header];
                }
            });

            // Run Validation
            const validation = await onValidate(newRow);
            return { ...newRow, _validation: validation, _rowIndex: index + 2 }; // +2 for Excel row (1-indexed + header)
        }));

        // 에러 로그 초기화 및 유효하지 않은 행 기록
        const initialErrors: ErrorLogEntry[] = mapped
            .filter(row => !row._validation?.isValid || row._validation?.warnings?.length > 0)
            .map(row => ({
                rowIndex: row._rowIndex,
                rowData: Object.fromEntries(fields.map(f => [f.label, row[f.key]])),
                errors: row._validation?.errors || [],
                warnings: row._validation?.warnings || [],
                status: row._validation?.isValid
                    ? (row._validation?.status || 'NEW')
                    : 'ERROR',
                timestamp: new Date().toISOString()
            }));
        setErrorLogs(initialErrors);

        setPreviewData(mapped);
        setStep('PREVIEW');
    };

    // State for Overwrite
    const [overwrite, setOverwrite] = useState(false);

    // --- 3. Batch Save Logic ---
    const handleUpload = async () => {
        setStep('SAVING');
        setLog([]);
        setProgress(0);

        // Filter out IDENTICAL rows automatically, maybe?
        // Or leave it to `onSaveBatch` to handle provided the flag?
        // Let's pass all valid rows but the handler decides.
        // Actually, if IDENTICAL, we shouldn't even send it usually, but let's send it as skipped.

        const validRows = previewData.filter(d => d._validation?.isValid).map(({ _validation, _rowIndex, ...rest }) => rest as T);
        const total = validRows.length;
        let processed = 0;
        let successTotal = 0;
        let failTotal = 0;
        let skippedTotal = 0;
        const batchErrors: ErrorLogEntry[] = [];

        for (let i = 0; i < total; i += batchSize) {
            const batch = validRows.slice(i, i + batchSize);
            const batchNumber = Math.floor(i / batchSize) + 1;
            try {
                const { success, failed, skipped = 0 } = await onSaveBatch(batch, { overwrite });
                successTotal += success;
                failTotal += failed;
                skippedTotal += skipped;
                setLog(prev => [`[Batch ${batchNumber}] 성공: ${success}, 건너뜀: ${skipped}, 실패: ${failed}`, ...prev.slice(0, 9)]);

                // 실패 건수가 있으면 에러 로그에 추가
                if (failed > 0) {
                    batchErrors.push({
                        rowIndex: i + 1,
                        rowData: { batch: batchNumber, count: batch.length },
                        errors: [`배치 ${batchNumber}에서 ${failed}건 저장 실패`],
                        warnings: [],
                        status: 'ERROR',
                        timestamp: new Date().toISOString()
                    });
                }
            } catch (err: any) {
                console.error(err);
                const errorMsg = err?.message || '알 수 없는 오류';
                setLog(prev => [`[Error] 배치 ${batchNumber} 처리 중 오류: ${errorMsg}`, ...prev]);
                failTotal += batch.length;

                batchErrors.push({
                    rowIndex: i + 1,
                    rowData: { batch: batchNumber, count: batch.length },
                    errors: [`배치 처리 오류: ${errorMsg}`],
                    warnings: [],
                    status: 'ERROR',
                    timestamp: new Date().toISOString()
                });
            }

            processed += batch.length;
            setProgress(Math.round((processed / total) * 100));
            // Slight delay for UI
            await new Promise(r => setTimeout(r, 50));
        }

        // 에러 로그 업데이트 (기존 + 배치 에러)
        setErrorLogs(prev => [...prev, ...batchErrors]);

        setResultSummary({ success: successTotal, failed: failTotal, skipped: skippedTotal, total });
        setStep('COMPLETE');
    };

    // --- 에러 로그 다운로드 함수 ---
    const downloadErrorLog = () => {
        if (errorLogs.length === 0) {
            Swal.fire('알림', '다운로드할 에러 로그가 없습니다.', 'info');
            return;
        }

        // CSV 형식으로 변환
        const headers = ['행번호', '상태', '에러', '경고', '데이터', '시간'];
        const csvRows = [headers.join(',')];

        errorLogs.forEach(entry => {
            const row = [
                entry.rowIndex,
                entry.status,
                `"${entry.errors.join('; ').replace(/"/g, '""')}"`,
                `"${entry.warnings.join('; ').replace(/"/g, '""')}"`,
                `"${JSON.stringify(entry.rowData).replace(/"/g, '""')}"`,
                entry.timestamp
            ];
            csvRows.push(row.join(','));
        });

        const csvContent = '\uFEFF' + csvRows.join('\n'); // BOM for Korean
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `upload_error_log_${new Date().toISOString().slice(0, 10)}.csv`;
        link.click();
        URL.revokeObjectURL(url);
    };

    // --- 엑셀 형식 에러 로그 다운로드 ---
    const downloadErrorLogAsExcel = () => {
        if (errorLogs.length === 0) {
            Swal.fire('알림', '다운로드할 에러 로그가 없습니다.', 'info');
            return;
        }

        const data = errorLogs.map(entry => ({
            '행번호': entry.rowIndex,
            '상태': entry.status,
            '에러': entry.errors.join('; '),
            '경고': entry.warnings.join('; '),
            '데이터': JSON.stringify(entry.rowData),
            '시간': entry.timestamp
        }));

        const ws = XLSX.utils.json_to_sheet(data);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, '에러로그');
        XLSX.writeFile(wb, `upload_error_log_${new Date().toISOString().slice(0, 10)}.xlsx`);
    };


    // --- Renderers ---


    if (step === 'UPLOAD') {
        return (
            <div className="p-10 border-2 border-dashed border-slate-300 rounded-xl bg-slate-50 text-center hover:bg-slate-100 transition-colors"
                onDragOver={handleFileDrop} onDrop={handleFileDrop}
            >
                <div className="mb-4 text-brand-500 text-5xl">
                    <FontAwesomeIcon icon={faCloudUploadAlt} />
                </div>
                <h3 className="text-xl font-bold text-slate-800 mb-2">{title} 마법사</h3>
                <p className="text-slate-500 mb-6">{description || '엑셀 파일을 이곳으로 드래그하거나 클릭하여 업로드하세요.'}</p>
                <div className="flex justify-center gap-3">
                    <label className="bg-brand-600 hover:bg-brand-700 text-white px-6 py-3 rounded-lg font-bold cursor-pointer transition-all">
                        <FontAwesomeIcon icon={faCloudUploadAlt} /> 파일 선택 (.xlsx)
                        <input type="file" className="hidden" accept=".xlsx, .xls" onChange={e => e.target.files?.[0] && processFile(e.target.files[0])} />
                    </label>
                    {sampleData && (
                        <button
                            type="button"
                            onClick={downloadSampleExcel}
                            className="bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-lg font-bold cursor-pointer transition-all flex items-center gap-2"
                        >
                            <FontAwesomeIcon icon={faDownload} /> 샘플 양식 다운로드
                        </button>
                    )}
                </div>

                {/* Guide for Fields */}
                <div className="mt-8 text-left max-w-2xl mx-auto bg-white p-4 rounded-lg shadow-sm border border-slate-200">
                    <h4 className="font-bold text-sm text-slate-700 mb-2">💡 엑셀 파일 권장 헤더</h4>
                    <p className="text-xs text-slate-500 mb-3">
                        아래 필드를 포함하는 엑셀 파일을 업로드해주세요. <span className="text-red-500 font-bold">빨간색*</span>은 필수 항목입니다.
                    </p>
                    <div className="flex flex-wrap gap-2">
                        {fields.map(f => (
                            <div key={f.key} className="group relative">
                                <span className={`text-xs px-2 py-1 rounded border ${f.required ? 'bg-red-50 border-red-200 text-red-700 font-semibold' : 'bg-slate-50 border-slate-200 text-slate-600'}`}>
                                    {f.label}{f.required && '*'}
                                </span>
                                <div className="absolute bottom-full mb-2 w-48 bg-slate-800 text-white text-xs rounded p-2 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-10">
                                    <div className="font-bold">{f.label}</div>
                                    {f.aliases && f.aliases.length > 0 && <div className="text-slate-300">별칭: {f.aliases.join(', ')}</div>}
                                    {f.example && <div>예시: {f.example}</div>}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    if (step === 'MAPPING') {
        // ... (Keep existing MAPPING render logic)
        return (
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
                    <span className="w-8 h-8 rounded-full bg-brand-100 text-brand-600 flex items-center justify-center text-sm">2</span>
                    데이터 연결 (컬럼 매핑)
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {fields.map(field => (
                        <div key={field.key} className="p-3 bg-slate-50 rounded-lg border border-slate-200">
                            <label className="block text-xs font-bold text-slate-700 mb-1">
                                {field.label} {field.required && <span className="text-red-500">*</span>}
                            </label>
                            <select
                                className={`w-full text-sm rounded border-slate-300 ${!fieldMapping[field.key] && field.required ? 'border-red-300 ring-2 ring-red-100' : ''}`}
                                value={fieldMapping[field.key] || ''}
                                onChange={(e) => handleMappingChange(field.key, e.target.value)}
                            >
                                <option value="">(선택 안함)</option>
                                {excelHeaders.map(h => (
                                    <option key={h} value={h}>{h}</option>
                                ))}
                            </select>
                            {fieldMapping[field.key] && (
                                <p className="text-[10px] text-brand-600 mt-1 truncate">
                                    <FontAwesomeIcon icon={faArrowRight} className="mr-1" />
                                    {rawRows[0]?.[fieldMapping[field.key]] || '(예시 없음)'}
                                </p>
                            )}
                        </div>
                    ))}
                </div>
                <div className="mt-6 flex justify-end gap-2">
                    <button onClick={() => setStep('UPLOAD')} className="px-4 py-2 text-slate-500 hover:bg-slate-100 rounded-lg">이전</button>
                    <button onClick={proceedToPreview} className="px-6 py-2 bg-brand-600 text-white rounded-lg font-bold hover:bg-brand-700">다음: 데이터 확인</button>
                </div>
            </div>
        );
    }

    if (step === 'PREVIEW') {
        const validCount = previewData.filter(d => d._validation?.isValid).length;
        const invalidCount = previewData.length - validCount;
        const updateCount = previewData.filter(d => d._validation?.status === 'UPDATE').length;
        const newCount = previewData.filter(d => d._validation?.status === 'NEW').length;
        const warningCount = previewData.filter(d => (d._validation?.warnings?.length ?? 0) > 0).length;

        return (
            <div className="flex flex-col h-[600px] bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                    <div>
                        <h3 className="font-bold text-slate-800">데이터 확인</h3>
                        <p className="text-xs text-slate-500">
                            신규 <span className="text-green-600 font-bold">{newCount}</span>,
                            변경 <span className="text-blue-600 font-bold">{updateCount}</span>,
                            경고 <span className="text-orange-500 font-bold">{warningCount}</span>,
                            오류 <span className="text-red-500 font-bold">{invalidCount}</span>
                        </p>
                    </div>
                    <div className="flex items-center gap-4">
                        {/* 설정 토글 버튼 */}
                        <button
                            onClick={() => setShowSettings(!showSettings)}
                            className={`px-3 py-1.5 text-sm rounded border transition-colors ${showSettings ? 'bg-slate-200 border-slate-400' : 'bg-white border-slate-300 hover:bg-slate-50'}`}
                            title="업로드 설정"
                        >
                            <FontAwesomeIcon icon={faCog} className="mr-1" />
                            설정
                        </button>

                        {updateCount > 0 && (
                            <label className="flex items-center gap-2 text-sm font-bold text-slate-700 cursor-pointer bg-blue-50 px-3 py-1.5 rounded border border-blue-100 hover:bg-blue-100 transition-colors">
                                <input
                                    type="checkbox"
                                    checked={overwrite}
                                    onChange={e => setOverwrite(e.target.checked)}
                                    className="rounded border-slate-300 text-brand-600 focus:ring-brand-500"
                                />
                                중복 데이터 덮어쓰기
                            </label>
                        )}

                        {/* 에러/경고 로그 다운로드 버튼 */}
                        {errorLogs.length > 0 && (
                            <button
                                onClick={downloadErrorLogAsExcel}
                                className="px-3 py-1.5 text-sm text-orange-600 border border-orange-300 rounded bg-orange-50 hover:bg-orange-100 transition-colors"
                                title="에러/경고 로그 다운로드"
                            >
                                <FontAwesomeIcon icon={faDownload} className="mr-1" />
                                로그 ({errorLogs.length})
                            </button>
                        )}

                        <div className="flex gap-2">
                            <button onClick={() => setStep('MAPPING')} className="px-3 py-1.5 text-sm text-slate-600 border border-slate-300 rounded bg-white">설정 변경</button>
                            <button onClick={handleUpload} className="px-4 py-1.5 text-sm bg-brand-600 text-white rounded font-bold shadow-sm hover:bg-brand-700 disabled:opacity-50" disabled={validCount === 0}>
                                {validCount}건 업로드 시작
                            </button>
                        </div>
                    </div>
                </div>

                {/* 설정 패널 */}
                {showSettings && (
                    <div className="p-4 border-b border-slate-200 bg-slate-100">
                        <div className="flex items-center gap-6">
                            <div className="flex items-center gap-2">
                                <label className="text-sm font-medium text-slate-700">배치 크기:</label>
                                <select
                                    value={batchSize}
                                    onChange={(e) => setBatchSize(Number(e.target.value))}
                                    className="text-sm border-slate-300 rounded"
                                >
                                    <option value={10}>10건</option>
                                    <option value={25}>25건</option>
                                    <option value={50}>50건</option>
                                    <option value={100}>100건</option>
                                    <option value={200}>200건</option>
                                </select>
                                <span className="text-xs text-slate-500">(대용량 처리 시 작은 값 권장)</span>
                            </div>
                        </div>
                    </div>
                )}
                <div className="flex-1 overflow-auto">
                    <table className="w-full text-xs text-left border-collapse">
                        <thead className="bg-slate-100 sticky top-0 z-10 font-bold text-slate-700">
                            <tr>
                                <th className="p-2 border-b w-24 text-center">상태</th>
                                {fields.map(f => (
                                    <th key={f.key} className="p-2 border-b">{f.label}</th>
                                ))}
                                <th className="p-2 border-b">메세지</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {previewData.slice(0, 100).map((row, idx) => {
                                const status = row._validation?.status;
                                let rowClass = 'hover:bg-slate-50';
                                if (!row._validation?.isValid) rowClass = 'bg-red-50 hover:bg-red-100';
                                else if (status === 'UPDATE') rowClass = 'bg-blue-50/30 hover:bg-blue-50';
                                else if (status === 'IDENTICAL') rowClass = 'bg-slate-50 opacity-60';

                                return (
                                    <tr key={idx} className={rowClass}>
                                        <td className="p-2 text-center">
                                            {status === 'NEW' && <span className="bg-green-100 text-green-700 px-2 py-0.5 rounded text-[10px] font-bold">신규</span>}
                                            {status === 'UPDATE' && <span className="bg-blue-100 text-blue-700 px-2 py-0.5 rounded text-[10px] font-bold">변경</span>}
                                            {status === 'IDENTICAL' && <span className="bg-slate-100 text-slate-500 px-2 py-0.5 rounded text-[10px] font-bold">동일</span>}
                                            {!status && !row._validation?.isValid && <span className="bg-red-100 text-red-700 px-2 py-0.5 rounded text-[10px] font-bold">오류</span>}
                                        </td>
                                        {fields.map(f => {
                                            const change = row._validation?.changes?.find(c => c.field === f.key);
                                            return (
                                                <td key={f.key} className="p-2 truncate max-w-[150px]" title={String(row[f.key] || '')}>
                                                    <div>{String(row[f.key] || '')}</div>
                                                    {change && (
                                                        <div className="text-[10px] text-red-500 line-through opacity-70">
                                                            {String(change.oldValue || '(공란)')}
                                                        </div>
                                                    )}
                                                </td>
                                            );
                                        })}
                                        <td className="p-2 text-slate-500">
                                            {row._validation?.errors.length ? (
                                                <span className="text-red-600 font-bold">{row._validation.errors.join(', ')}</span>
                                            ) : (
                                                row._validation?.warnings.length ? (
                                                    <span className="text-orange-500">{row._validation.warnings.join(', ')}</span>
                                                ) : <span className="text-green-400">OK</span>
                                            )}
                                        </td>
                                    </tr>
                                )
                            })}
                        </tbody>
                    </table>
                    {previewData.length > 100 && (
                        <div className="p-4 text-center text-slate-400 text-sm">
                            ...외 {previewData.length - 100}건 (성능을 위해 100건만 표시됩니다)
                        </div>
                    )}
                </div>
            </div>
        );
    }

    if (step === 'SAVING') {
        return (
            <div className="flex flex-col items-center justify-center p-20 bg-white rounded-xl shadow-sm border border-slate-200">
                <div className="w-20 h-20 border-4 border-slate-100 border-t-brand-500 rounded-full animate-spin mb-6"></div>
                <h3 className="text-2xl font-bold text-slate-800 mb-2">데이터 저장 중...</h3>
                <p className="text-slate-500 mb-8">{progress}% 완료</p>

                <div className="w-full max-w-md bg-slate-100 rounded-full h-3 mb-6 overflow-hidden">
                    <div className="bg-brand-500 h-full transition-all duration-300" style={{ width: `${progress}%` }}></div>
                </div>

                <div className="w-full max-w-md bg-slate-900 rounded-lg p-4 font-mono text-xs text-green-400 h-32 overflow-y-auto">
                    {log.map((line, i) => (
                        <div key={i}>{line}</div>
                    ))}
                </div>
            </div>
        );
    }

    if (step === 'COMPLETE') {
        const hasErrors = errorLogs.some(e => e.status === 'ERROR') || resultSummary.failed > 0;

        return (
            <div className="text-center p-12 bg-white rounded-xl shadow-sm border border-slate-200">
                <div className={`w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6 text-4xl ${hasErrors ? 'bg-orange-100 text-orange-500' : 'bg-green-100 text-green-500'}`}>
                    <FontAwesomeIcon icon={hasErrors ? faExclamationTriangle : faCheckCircle} />
                </div>
                <h3 className="text-2xl font-bold text-slate-800 mb-2">
                    {hasErrors ? '업로드 완료 (일부 오류)' : '업로드 완료!'}
                </h3>
                <div className="flex justify-center gap-8 my-6">
                    <div className="text-center">
                        <p className="text-3xl font-bold text-green-600">{resultSummary.success}</p>
                        <p className="text-sm text-slate-500">성공</p>
                    </div>
                    <div className="text-center">
                        <p className="text-3xl font-bold text-red-500">{resultSummary.failed}</p>
                        <p className="text-sm text-slate-500">실패</p>
                    </div>
                    <div className="text-center">
                        <p className="text-3xl font-bold text-orange-500">{resultSummary.skipped}</p>
                        <p className="text-sm text-slate-500">중복 (건너뜀)</p>
                    </div>
                    <div className="text-center">
                        <p className="text-3xl font-bold text-slate-700">{resultSummary.total}</p>
                        <p className="text-sm text-slate-500">총 요청</p>
                    </div>
                </div>

                {/* 에러 로그 다운로드 버튼 */}
                {errorLogs.length > 0 && (
                    <div className="mb-6 p-4 bg-orange-50 border border-orange-200 rounded-lg inline-block">
                        <p className="text-sm text-orange-800 mb-3">
                            총 <strong>{errorLogs.length}</strong>건의 에러/경고 로그가 있습니다.
                        </p>
                        <div className="flex justify-center gap-2">
                            <button
                                onClick={downloadErrorLogAsExcel}
                                className="px-4 py-2 text-sm bg-orange-500 text-white rounded font-bold hover:bg-orange-600 transition-colors"
                            >
                                <FontAwesomeIcon icon={faDownload} className="mr-2" />
                                엑셀로 다운로드
                            </button>
                            <button
                                onClick={downloadErrorLog}
                                className="px-4 py-2 text-sm border border-orange-400 text-orange-600 rounded hover:bg-orange-100 transition-colors"
                            >
                                <FontAwesomeIcon icon={faDownload} className="mr-2" />
                                CSV 다운로드
                            </button>
                        </div>
                    </div>
                )}

                <div className="flex justify-center gap-3">
                    <button
                        onClick={() => {
                            setStep('UPLOAD');
                            setRawFile(null);
                            setPreviewData([]);
                            setErrorLogs([]);
                            setLog([]);
                        }}
                        className="px-6 py-3 bg-brand-600 text-white rounded-lg font-bold hover:bg-brand-700"
                    >
                        다른 파일 업로드하기
                    </button>
                </div>
            </div>
        );
    }

    return null;
};

export default ExcelUploadWizard;

import React, { useState, useEffect, useRef, useCallback, useLayoutEffect } from 'react';
import { getColumnLabel, parseTSV, generateTSV } from '../../utils/excelUtils';

interface CellData {
    value: string | number;
    formula?: string;
    style?: React.CSSProperties;
}

interface ExcelGridProps {
    initialData?: CellData[][];
    rowCount?: number;
    colCount?: number;
    onDataChange?: (data: CellData[][]) => void;
    columnHeaders?: string[];
}

const ExcelGrid: React.FC<ExcelGridProps> = ({
    initialData,
    rowCount = 50,
    colCount = 26,
    onDataChange,
    columnHeaders
}) => {
    // State
    const [data, setData] = useState<CellData[][]>(() => {
        if (initialData) return initialData;
        return Array(rowCount).fill(null).map(() => Array(colCount).fill({ value: '' }));
    });

    const [selection, setSelection] = useState<{ start: { r: number, c: number }, end: { r: number, c: number } }>({ start: { r: 0, c: 0 }, end: { r: 0, c: 0 } });
    const [isEditing, setIsEditing] = useState(false);
    const [editValue, setEditValue] = useState('');
    const [inputStyle, setInputStyle] = useState<React.CSSProperties>({ display: 'none' });

    const gridRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);
    const isCommitting = useRef(false);

    // Sync data with initialData
    useEffect(() => {
        if (initialData) {
            setData(initialData);
        }
    }, [initialData]);

    // Position the Input over the selected cell
    useLayoutEffect(() => {
        if (!gridRef.current || !selection) return;

        const { start } = selection;
        const cell = gridRef.current.querySelector(`td[data-r="${start.r}"][data-c="${start.c}"]`) as HTMLElement;

        if (cell) {
            const { offsetLeft, offsetTop, offsetWidth, offsetHeight } = cell;
            setInputStyle({
                display: 'block',
                left: offsetLeft,
                top: offsetTop,
                width: offsetWidth,
                height: offsetHeight,
                opacity: isEditing ? 1 : 0,
                zIndex: isEditing ? 30 : 10, // Above cell content
            });

            // Ensure input is focused
            if (inputRef.current) {
                inputRef.current.focus();
            }
        }
    }, [selection, isEditing]);

    // Update input value when selection changes (if not editing)
    useEffect(() => {
        if (!isEditing && selection) {
            const cell = data[selection.start.r][selection.start.c];
            setEditValue(String(cell.value));
        }
    }, [selection, isEditing, data]);

    // Commit Logic
    const commitEdit = useCallback(() => {
        if (isCommitting.current) return;
        isCommitting.current = true;

        const { start } = selection;
        const newData = [...data];
        newData[start.r] = [...newData[start.r]];

        let val: string | number = editValue;
        if (!isNaN(Number(val)) && val !== '') {
            val = Number(val);
        }

        newData[start.r][start.c] = {
            ...newData[start.r][start.c],
            value: val
        };

        setData(newData);
        if (onDataChange) onDataChange(newData);
        setIsEditing(false);

        setTimeout(() => {
            isCommitting.current = false;
        }, 0);
    }, [data, editValue, selection, onDataChange]);

    // Input Key Handler (The Core Logic)
    const handleInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        // 1. Navigation (only if NOT editing, or special keys)
        const { key, shiftKey, ctrlKey, metaKey } = e;
        const isCmd = ctrlKey || metaKey;

        if (!isEditing) {
            // Navigation Keys
            if (key === 'ArrowUp' || key === 'ArrowDown' || key === 'ArrowLeft' || key === 'ArrowRight' || key === 'Tab' || key === 'Enter') {
                e.preventDefault();
                handleNavigation(key, shiftKey, isCmd);
                return;
            }

            // Delete
            if (key === 'Delete' || key === 'Backspace') {
                e.preventDefault();
                deleteSelection();
                return;
            }

            // F2 -> Start Editing (Append)
            if (key === 'F2') {
                e.preventDefault();
                setIsEditing(true);
                return;
            }

            // Copy/Paste handled by native events or window listeners

            // Typing (Any other key)
            // We DO NOT preventDefault. We let the input capture the key.
            // We DO NOT set isEditing(true) here. We let onChange handle it.
            // This ensures the first character (especially IME) is captured correctly.
        } else {
            // Editing Mode
            if (key === 'Enter') {
                e.preventDefault();
                commitEdit();
                handleNavigation('Enter', shiftKey, false);
            } else if (key === 'Tab') {
                e.preventDefault();
                commitEdit();
                handleNavigation('Tab', shiftKey, false);
            } else if (key === 'Escape') {
                e.preventDefault();
                setIsEditing(false);
                // Revert value logic
                const cell = data[selection.start.r][selection.start.c];
                setEditValue(''); // Clear for nav mode
            } else if (key === 'ArrowUp' || key === 'ArrowDown') {
                e.preventDefault();
                commitEdit();
                handleNavigation(key, false, false);
            }
        }
    };

    // Refined: When selection changes, clear input if not editing
    useEffect(() => {
        if (!isEditing) {
            setEditValue('');
        }
    }, [selection, isEditing]);

    // Special Case: F2 needs to populate value
    const handleKeyDownCapture = (e: React.KeyboardEvent) => {
        if (e.key === 'F2' && !isEditing) {
            const cell = data[selection.start.r][selection.start.c];
            setEditValue(String(cell.value));
        }
    };

    const handleNavigation = (key: string, shift: boolean, cmd: boolean) => {
        const { start } = selection;
        let dr = 0;
        let dc = 0;

        if (key === 'ArrowUp') dr = -1;
        if (key === 'ArrowDown') dr = 1;
        if (key === 'ArrowLeft') dc = -1;
        if (key === 'ArrowRight') dc = 1;
        if (key === 'Enter') dr = shift ? -1 : 1;
        if (key === 'Tab') dc = shift ? -1 : 1;

        if (cmd) {
            if (dr !== 0) dr *= rowCount;
            if (dc !== 0) dc *= colCount;
        }

        const newR = Math.max(0, Math.min(rowCount - 1, start.r + dr));
        const newC = Math.max(0, Math.min(colCount - 1, start.c + dc));

        setSelection({ start: { r: newR, c: newC }, end: { r: newR, c: newC } });
    };

    const deleteSelection = () => {
        const { start, end } = selection;
        const minR = Math.min(start.r, end.r);
        const maxR = Math.max(start.r, end.r);
        const minC = Math.min(start.c, end.c);
        const maxC = Math.max(start.c, end.c);

        const newData = [...data];
        for (let r = minR; r <= maxR; r++) {
            newData[r] = [...newData[r]];
            for (let c = minC; c <= maxC; c++) {
                newData[r][c] = { ...newData[r][c], value: '' };
            }
        }
        setData(newData);
        if (onDataChange) onDataChange(newData);
    };

    // Mouse Handling (Selection)
    const handleMouseDown = (r: number, c: number, e: React.MouseEvent) => {
        if (e.button !== 0) return;
        if (isEditing) {
            commitEdit();
        }
        setSelection({ start: { r, c }, end: { r, c } });
    };

    const handleMouseEnter = (r: number, c: number, e: React.MouseEvent) => {
        if (e.buttons === 1) { // Dragging
            setSelection(prev => ({ ...prev, end: { r, c } }));
        }
    };

    const handleDoubleClick = () => {
        const cell = data[selection.start.r][selection.start.c];
        setEditValue(String(cell.value));
        setIsEditing(true);
    };

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setEditValue(e.target.value);
        if (!isEditing) {
            setIsEditing(true);
        }
    };

    return (
        <div className="w-full h-full overflow-auto select-none bg-white border border-slate-300 relative" ref={gridRef}>
            {/* The Persistent Input */}
            <input
                ref={inputRef}
                type="text"
                className="absolute outline-none px-2 py-1 text-sm font-normal border-2 border-blue-500 bg-white"
                style={{
                    ...inputStyle,
                    color: isEditing ? 'inherit' : 'transparent',
                    caretColor: isEditing ? 'auto' : 'transparent',
                    borderColor: isEditing ? '#3b82f6' : 'transparent',
                    backgroundColor: isEditing ? 'white' : 'transparent',
                }}
                value={editValue}
                onChange={handleInputChange}
                onKeyDown={handleInputKeyDown}
                onKeyDownCapture={handleKeyDownCapture}
            />

            <table className="border-collapse w-full table-fixed">
                <thead>
                    <tr>
                        <th className="w-10 bg-slate-100 border border-slate-300 sticky top-0 left-0 z-20"></th>
                        {Array(colCount).fill(0).map((_, i) => (
                            <th key={i} className="bg-slate-100 border border-slate-300 px-2 py-1 text-xs font-semibold text-slate-600 min-w-[80px] sticky top-0 z-10">
                                {columnHeaders ? (columnHeaders[i] || getColumnLabel(i)) : getColumnLabel(i)}
                            </th>
                        ))}
                    </tr>
                </thead>
                <tbody>
                    {data.map((row, r) => (
                        <tr key={r}>
                            <td className="bg-slate-50 border border-slate-300 text-center text-xs text-slate-500 font-medium sticky left-0 z-10">
                                {r + 1}
                            </td>
                            {row.map((cell, c) => {
                                const isSelected = r >= Math.min(selection.start.r, selection.end.r) &&
                                    r <= Math.max(selection.start.r, selection.end.r) &&
                                    c >= Math.min(selection.start.c, selection.end.c) &&
                                    c <= Math.max(selection.start.c, selection.end.c);
                                const isFocused = selection.start.r === r && selection.start.c === c;

                                return (
                                    <td
                                        key={c}
                                        data-r={r}
                                        data-c={c}
                                        className={`
                                            border border-slate-200 px-2 py-1 text-sm relative cursor-cell
                                            ${isSelected ? 'bg-blue-50' : ''}
                                            ${isFocused ? 'ring-2 ring-blue-500 z-0' : ''} 
                                        `}
                                        onMouseDown={(e) => handleMouseDown(r, c, e)}
                                        onMouseEnter={(e) => handleMouseEnter(r, c, e)}
                                        onDoubleClick={handleDoubleClick}
                                    >
                                        <div className="truncate min-h-[20px]">
                                            {cell.value}
                                        </div>
                                    </td>
                                );
                            })}
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
};

export default ExcelGrid;

import React, { useEffect, useState, useMemo } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faSearch, faCheck, faUser, faBuilding, faSpinner, faWarning } from '@fortawesome/free-solid-svg-icons';
import { manpowerService, Worker } from '../../services/manpowerService';
import { companyService, Company } from '../../services/companyService';

export interface Recipient {
    id: string;
    name: string;
    phone: string;
    type: 'WORKER' | 'COMPANY';
    subType: string; // 'worker', '건설사', '협력사', etc.
    originalData?: any;
}

interface UniversalRecipientSelectorProps {
    onSelectionChange: (selectedRecipients: Recipient[]) => void;
    initialSelectedIds?: Set<string>;
}

type TabType = 'WORKER' | 'CONSTRUCTION' | 'PARTNER';

export const UniversalRecipientSelector: React.FC<UniversalRecipientSelectorProps> = ({
    onSelectionChange,
    initialSelectedIds = new Set(),
}) => {
    const [activeTab, setActiveTab] = useState<TabType>('WORKER');
    const [searchTerm, setSearchTerm] = useState('');
    const [loading, setLoading] = useState(true);

    const [workers, setWorkers] = useState<Recipient[]>([]);
    const [companies, setCompanies] = useState<Recipient[]>([]);

    // Manage selection internally, but sync with parent
    const [selectedIds, setSelectedIds] = useState<Set<string>>(initialSelectedIds);
    const [selectedRecipients, setSelectedRecipients] = useState<Map<string, Recipient>>(new Map());

    useEffect(() => {
        const fetchData = async () => {
            setLoading(true);
            try {
                const [workerData, companyData] = await Promise.all([
                    manpowerService.getWorkers(),
                    companyService.getCompanies(),
                ]);

                const parsedWorkers: Recipient[] = workerData
                    .filter(w => w.contact && w.id)
                    .map(w => ({
                        id: w.id!,
                        name: w.name,
                        phone: w.contact!,
                        type: 'WORKER',
                        subType: 'worker',
                        originalData: w,
                    }));

                const parsedCompanies: Recipient[] = companyData
                    .filter(c => c.phone && c.id) // Only companies with phone (CEO or Office)
                    .map(c => ({
                        id: c.id!,
                        name: c.name,
                        phone: c.phone || '', // Fallback though filter handles it
                        type: 'COMPANY',
                        subType: c.type || '기타',
                        originalData: c,
                    }));

                setWorkers(parsedWorkers);
                setCompanies(parsedCompanies);

            } catch (error) {
                console.error("Failed to fetch recipients", error);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, []);

    // Notify parent on change
    useEffect(() => {
        onSelectionChange(Array.from(selectedRecipients.values()));
    }, [selectedRecipients, onSelectionChange]);


    const filteredList = useMemo(() => {
        let source: Recipient[] = [];
        if (activeTab === 'WORKER') {
            source = workers;
        } else if (activeTab === 'CONSTRUCTION') {
            source = companies.filter(c => c.subType === '건설사' || c.subType === '시공사');
        } else if (activeTab === 'PARTNER') {
            source = companies.filter(c => c.subType === '협력사');
        }

        if (!searchTerm) return source;
        const lowerTerm = searchTerm.toLowerCase();
        return source.filter(r =>
            r.name.toLowerCase().includes(lowerTerm) ||
            r.phone.replace(/-/g, '').includes(lowerTerm)
        );
    }, [activeTab, workers, companies, searchTerm]);

    const handleToggle = (recipient: Recipient) => {
        const newSet = new Set(selectedIds);
        const newMap = new Map(selectedRecipients);

        if (newSet.has(recipient.id)) {
            newSet.delete(recipient.id);
            newMap.delete(recipient.id);
        } else {
            newSet.add(recipient.id);
            newMap.set(recipient.id, recipient);
        }

        setSelectedIds(newSet);
        setSelectedRecipients(newMap);
    };

    const handleSelectAll = () => {
        const newSet = new Set(selectedIds);
        const newMap = new Map(selectedRecipients);

        const isAllSelected = filteredList.length > 0 && filteredList.every(r => newSet.has(r.id));

        if (isAllSelected) {
            filteredList.forEach(r => {
                newSet.delete(r.id);
                newMap.delete(r.id);
            });
        } else {
            filteredList.forEach(r => {
                newSet.add(r.id);
                newMap.set(r.id, r);
            });
        }

        setSelectedIds(newSet);
        setSelectedRecipients(newMap);
    };

    const getCount = (tab: TabType) => {
        if (tab === 'WORKER') return workers.length;
        if (tab === 'CONSTRUCTION') return companies.filter(c => c.subType === '건설사' || c.subType === '시공사').length;
        if (tab === 'PARTNER') return companies.filter(c => c.subType === '협력사').length;
        return 0;
    };

    return (
        <div className="flex flex-col h-full bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            {/* Header / Tabs */}
            <div className="flex border-b bg-gray-50">
                <button
                    onClick={() => setActiveTab('WORKER')}
                    className={`flex-1 py-3 text-sm font-semibold flex items-center justify-center gap-2 transition-colors ${activeTab === 'WORKER'
                            ? 'bg-white text-blue-600 border-b-2 border-blue-600'
                            : 'text-gray-500 hover:text-gray-700'
                        }`}
                >
                    <FontAwesomeIcon icon={faUser} />
                    작업자 ({getCount('WORKER')})
                </button>
                <button
                    onClick={() => setActiveTab('CONSTRUCTION')}
                    className={`flex-1 py-3 text-sm font-semibold flex items-center justify-center gap-2 transition-colors ${activeTab === 'CONSTRUCTION'
