                accountNumber: z.string().optional(),
                accountHolder: z.string().optional(),
                role: z.string().trim().min(1, '직책을 입력해주세요.')
            })
            .superRefine((value, ctx) => {
                if (value.teamType === '시공팀' && value.companyId.trim().length === 0) {
