                        : null;

                const resolvedSupportTeam = teams.find(t => t.id === validated.supportTeamId) ?? null;

                const resolvedPartnerCompany =
                    validated.teamType === '지원팀'
                        ? companies.find(c => c.id === validated.companyId) ?? null
                        : null;

