                        siteIds: [],
                        siteNames: [],
                        totalManDay: 0,
                        isMyCompany: false,
                        assignedClientCompanyIds: []
                    },
                    ...prev
                ]);

                return {
                    companyId,
                    companyName: validated.name,
                    companyCode: resolvedCode,
                    ceoName: validated.ceoName
                };
            };

            if (selectedSection === 'partnerCompany') {
                const trimmedTeamName = partnerCompanyTeamForm.teamName.trim();
                if (trimmedTeamName.length === 0) {
                    toast.error('팀명을 입력해주세요.');
                    return;
                }

                const createdCompany = await registerCompany('협력사', partnerCompanyForm);

                const teamId = await teamService.addTeam({
                    name: trimmedTeamName,
                    type: '지원팀',
                    leaderId: '',
                    leaderName: createdCompany.ceoName,
                    companyId: createdCompany.companyId,
                    companyName: createdCompany.companyName,
                    parentTeamId: '',
                    parentTeamName: '',
                    memberCount: 0,
                    memberIds: [],
                    memberNames: [],
                    siteIds: [],
                    siteNames: [],
                    totalManDay: 0,
                    status: 'active',
                    supportRate: 0,
                    supportModel: 'man_day',
                    supportDescription: '',
                    serviceRate: 0,
                    serviceModel: 'man_day',
                    serviceDescription: '',
                    defaultSalaryModel: '지원팀',
                    color: '',
                    iconKey: '',
                    role: ''
                });

                // 대표자를 팀장으로 등록
                if (registerCeoAsLeader && createdCompany.ceoName.trim().length > 0) {
                    const workerId = await manpowerService.addWorker({
                        name: createdCompany.ceoName,
                        idNumber: '',
                        contact: partnerCompanyForm.phone,
                        address: '',
                        companyId: createdCompany.companyId,
                        companyName: createdCompany.companyName,
                        teamId: teamId,
                        teamName: trimmedTeamName,
                        teamType: '지원팀',
                        unitPrice: 0,
                        salaryModel: '지원팀',
                        bankName: partnerCompanyForm.bankName,
                        accountNumber: partnerCompanyForm.accountNumber,
                        accountHolder: partnerCompanyForm.accountHolder || createdCompany.ceoName,
                        role: '팀장',
                        status: 'active'
                    });

                    // 팀장 정보 업데이트 (undefined 필드 제외)
                    const updateData: any = {
                        leaderId: workerId,
                        leaderName: createdCompany.ceoName,
                        memberIds: [workerId],
                        memberNames: [createdCompany.ceoName],
                        memberCount: 1
                    };

                    // undefined 필드 제거
                    Object.keys(updateData).forEach(key => {
                        if (updateData[key] === undefined) {
                            delete updateData[key];
                        }
                    });

                    await teamService.updateTeam(teamId, updateData);

                    toast.success(`${createdCompany.companyName}, ${trimmedTeamName}, ${createdCompany.ceoName}(팀장)을 등록했습니다.`);
                } else {
                    toast.success(`${createdCompany.companyName}과 ${trimmedTeamName}을 등록했습니다.`);
                }

                setTeams(prev => [
                    {
                        id: teamId,
                        name: trimmedTeamName,
                        type: '지원팀',
                        leaderId: '',
                        leaderName: createdCompany.ceoName,
                        companyId: createdCompany.companyId,
                        companyName: createdCompany.companyName,
                        status: 'active',
                        defaultSalaryModel: '지원팀',
                        siteIds: [],
                        siteNames: [],
                        totalManDay: 0,
                        memberCount: registerCeoAsLeader ? 1 : 0,
                        memberIds: [],
                        memberNames: []
                    },
                    ...prev
                ]);

                setPartnerCompanyForm({
                    name: '',
                    businessNumber: '',
                    ceoName: '',
                    phone: '',
                    bankName: '',
                    accountNumber: '',
                    accountHolder: ''
                });

                setPartnerCompanyTeamForm({ teamName: '' });
                setIsPartnerCompanyTeamNameTouched(false);
                setRegisterCeoAsLeader(true); // 기본값으로 초기화

                emitMasterDataChanged({ companies: true, teams: true });
                return;
            }

            if (selectedSection === 'constructionCompany') {
                const createdCompany = await registerCompany('건설사', constructionCompanyForm);

                // "발주사" 팀 찾기 또는 생성
                let clientTeamId = '';
                let clientTeamName = '발주사';

                const existingClientTeam = teams.find(
                    t => t.name === '발주사' && t.companyId === createdCompany.companyId
                );

                if (existingClientTeam && existingClientTeam.id) {
                    clientTeamId = existingClientTeam.id;
                } else {
                    // "발주사" 팀 생성
                    clientTeamId = await teamService.addTeam({
                        name: clientTeamName,
                        type: '시공팀',
                        leaderId: '',
                        leaderName: '',
                        companyId: createdCompany.companyId,
                        companyName: createdCompany.companyName,
                        parentTeamId: '',
                        parentTeamName: '',
                        memberCount: 0,
                        memberIds: [],
                        memberNames: [],
                        siteIds: [],
                        siteNames: [],
                        totalManDay: 0,
                        status: 'active',
                        supportRate: 0,
                        supportModel: 'man_day',
                        supportDescription: '',
                        serviceRate: 0,
                        serviceModel: 'man_day',
                        serviceDescription: '',
                        defaultSalaryModel: '월급제',
                        color: '',
                        iconKey: '',
                        role: ''
                    });
                }

                // 대표자를 작업자로 등록
                if (registerCeoAsRepresentative && createdCompany.ceoName.trim().length > 0) {
                    const workerId = await manpowerService.addWorker({
                        name: createdCompany.ceoName,
                        idNumber: '',
                        contact: constructionCompanyForm.phone,
                        address: '',
                        companyId: createdCompany.companyId,
                        companyName: createdCompany.companyName,
                        teamId: clientTeamId,
                        teamName: clientTeamName,
                        teamType: '시공팀',
                        unitPrice: 0,
                        salaryModel: '월급제',
                        bankName: constructionCompanyForm.bankName,
                        accountNumber: constructionCompanyForm.accountNumber,
                        accountHolder: constructionCompanyForm.accountHolder || createdCompany.ceoName,
                        role: '대표',
                        status: 'active'
                    });

                    // 팀에 대표 설정
                    await teamService.updateTeam(clientTeamId, {
                        leaderId: workerId,
                        leaderName: createdCompany.ceoName,
                        memberIds: [workerId],
                        memberNames: [createdCompany.ceoName],
                        memberCount: 1
                    });

                    toast.success(`${createdCompany.companyName}, 발주사팀, ${createdCompany.ceoName}(대표)을 등록했습니다.`);
                } else {
                    toast.success(`${createdCompany.companyName}을 등록했습니다.`);
                }

                setConstructionCompanyForm({
                    name: '',
                    businessNumber: '',
                    ceoName: '',
                    phone: '',
                    bankName: '',
                    accountNumber: '',
                    accountHolder: ''
                });
                setRegisterCeoAsRepresentative(true); // 기본값으로 초기화

                emitMasterDataChanged({ companies: true, teams: true });
            }
        } catch (error) {
            if (error instanceof z.ZodError) {
                toast.error(error.issues[0]?.message ?? '입력값을 확인해주세요.');
                return;
            }

            if (error instanceof Error) {
                toast.error(error.message);
                return;
            }

            toast.error('등록 중 오류가 발생했습니다.');
        } finally {
            setIsSaving(false);
        }
    };

    const SectionHeader = ({
        section,
        title
    }: {
        section: QuickRegisterSection;
        title: string;
    }) => {
        const isOpenSection = selectedSection === section;
        const isSelected = selectedSection === section;
        return (
            <button
                type="button"
                onClick={() => toggleAccordion(section)}
                className="w-full text-left px-3 py-2 rounded-md"
                style={{
                    background: isSelected ? 'rgba(59,130,246,0.28)' : isOpenSection ? 'rgba(255,255,255,0.10)' : 'rgba(255,255,255,0.06)',
                    border: '1px solid rgba(255,255,255,0.10)',
                    color: '#fff'
                }}
            >
                <div className="flex items-center justify-between">
                    <span className="font-bold text-sm">{title}</span>
                    <span className="text-xs" style={{ opacity: 0.75 }}>
                        {isOpenSection ? '열림' : '닫힘'}
                    </span>
                </div>
            </button>
        );
    };

    const selectedTitle = useMemo(() => {
        switch (selectedSection) {
            case 'worker':
                return '작업자 등록';
            case 'team':
                return '팀 등록';
            case 'site':
                return '현장 등록';
            case 'partnerCompany':
                return '협력사 등록';
            case 'constructionCompany':
                return '건설사 등록';
            default:
                return '등록';
        }
    }, [selectedSection]);

    return (
        <aside id="bottom-panel" className={`panel ${isOpen ? 'open' : ''}`}>
            <div className="flex flex-col border-b border-white/10">
                {/* Top Row: Title & Actions */}
                <div className="flex justify-between items-center px-4 py-3">
                    {/* Title */}
                    <div className="flex items-center gap-2">
                        <FontAwesomeIcon icon={faUserGear} className="text-blue-400" />
                        <span className="font-bold text-lg tracking-tight">빠른 실행</span>
                    </div>

                    {/* Actions (Close/Save) */}
                    <div className="flex items-center gap-2">
                        {activeTab === 'register' && (
                            <button
                                type="button"
                                onClick={registerActiveSection}
                                disabled={isSaving}
                                className="px-3 py-1.5 rounded-md text-sm font-bold flex items-center gap-2 transition-all hover:brightness-110 active:scale-95"
                                style={{
                                    background: isSaving ? 'rgba(148,163,184,0.35)' : 'rgba(59,130,246,0.95)',
                                    border: '1px solid rgba(255,255,255,0.12)',
                                    color: '#fff'
                                }}
                            >
                                <FontAwesomeIcon icon={faFloppyDisk} />
                                <span className="hidden sm:inline">등록</span>
                            </button>
                        )}
                        <button
                            type="button"
                            onClick={() => togglePanel('bottom')}
                            className="w-8 h-8 rounded-md flex items-center justify-center transition-all hover:bg-white/10 active:scale-95"
                            style={{
                                border: '1px solid rgba(255,255,255,0.12)',
                                color: '#fff'
                            }}
                        >
                            <FontAwesomeIcon icon={faXmark} />
                        </button>
                    </div>
                </div>

                {/* Bottom Row: Tabs */}
                <div className="px-4 pb-3">
                    <div className="flex bg-black/30 rounded-lg p-1 gap-1 w-full sm:w-auto">
                        <button
                            onClick={() => setActiveTab('register')}
                            className={`flex-1 sm:flex-none justify-center items-center gap-2 px-3 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'register'
                                ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30'
                                : 'text-gray-400 hover:text-white hover:bg-white/10'
                                }`}
                        >
                            <FontAwesomeIcon icon={faDatabase} />
                            DB 등록
                        </button>
                        <button
                            onClick={() => setActiveTab('memo')}
                            className={`flex-1 sm:flex-none justify-center items-center gap-2 px-3 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'memo'
                                ? 'bg-yellow-500 text-black shadow-lg shadow-yellow-500/30'
                                : 'text-gray-400 hover:text-white hover:bg-white/10'
                                }`}
                        >
                            <FontAwesomeIcon icon={faNoteSticky} />
                            메모장
                        </button>
                        <button
                            onClick={() => setActiveTab('calculator')}
                            className={`flex-1 sm:flex-none justify-center items-center gap-2 px-3 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'calculator'
                                ? 'bg-green-600 text-white shadow-lg shadow-green-500/30'
                                : 'text-gray-400 hover:text-white hover:bg-white/10'
                                }`}
                        >
                            <FontAwesomeIcon icon={faCalculator} />
                            계산기
                        </button>
                    </div>
                </div>
            </div>
            <div className="panel-content p-4 overflow-y-auto custom-scrollbar bg-[#1e1e1e]">
                {activeTab === 'register' && (
                    <div className="flex flex-col gap-3">
                        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-2">
                            <TopRowButton section="worker" label="작업자" isSelected={selectedSection === 'worker'} onSelect={selectSection} />
                            <TopRowButton section="team" label="팀" isSelected={selectedSection === 'team'} onSelect={selectSection} />
                            <TopRowButton section="site" label="현장" isSelected={selectedSection === 'site'} onSelect={selectSection} />
                            <TopRowButton section="partnerCompany" label="협력사" isSelected={selectedSection === 'partnerCompany'} onSelect={selectSection} />
                            <TopRowButton section="constructionCompany" label="건설사" isSelected={selectedSection === 'constructionCompany'} onSelect={selectSection} />
                        </div>

                        <div
                            className="px-3 py-2 rounded-md"
                            style={{
                                background: 'rgba(255,255,255,0.06)',
                                border: '1px solid rgba(255,255,255,0.10)',
                                color: 'rgba(255,255,255,0.90)'
                            }}
                        >
                            <div className="flex items-center justify-between">
                                <span className="text-sm font-bold">{selectedTitle}</span>
                                <span className="text-xs" style={{ opacity: 0.7 }}>필수 항목만</span>
                            </div>
                        </div>

                        {selectedSection === 'worker' && (
                            <div
                                className="rounded-md p-3 flex flex-col gap-3"
                                style={{ background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.10)' }}
                            >
                                <Input
                                    label="이름"
                                    value={workerForm.name}
                                    onChange={(v) => setWorkerForm(prev => ({ ...prev, name: v }))}
                                    placeholder="예: 홍길동"
                                />
                                <Input
                                    label="식별번호(주민/생년)"
                                    value={workerForm.idNumber}
                                    onChange={(v) => setWorkerForm(prev => ({ ...prev, idNumber: v }))}
                                    placeholder="예: 900101-1234567"
                                />
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                    <Select
                                        label="팀구분"
                                        value={workerForm.teamType}
                                        onChange={(v) => handleWorkerTeamTypeChange(v as '시공팀' | '지원팀')}
                                        options={[
                                            { value: '시공팀', label: '시공팀' },
                                            { value: '지원팀', label: '지원팀' }
                                        ]}
                                    />
                                    {workerForm.teamType === '시공팀' ? (
                                        <Select
                                            label="시공사 회사"
                                            value={workerForm.companyId}
                                            onChange={(v) =>
                                                setWorkerForm(prev => ({
                                                    ...prev,
                                                    companyId: v,
                                                    supportTeamId: ''
                                                }))
                                            }
                                            options={[
                                                { value: '', label: '시공사 선택...' },
                                                ...constructionCompanyOptions
                                            ]}
                                        />
                                    ) : (
                                        <Select
                                            label="협력사 회사"
                                            value={workerForm.companyId}
                                            onChange={(v) =>
                                                setWorkerForm(prev => ({
                                                    ...prev,
                                                    companyId: v,
                                                    supportTeamId: ''
                                                }))
                                            }
                                            options={[
                                                { value: '', label: '선택' },
                                                ...partnerCompanyOptions
                                            ]}
                                        />
                                    )}
                                </div>

                                {workerForm.teamType === '시공팀' && (
                                    <Select
                                        label="시공사 팀 선택"
                                        value={workerForm.supportTeamId}
                                        onChange={(v) => {
                                            const selectedTeam = teams.find(t => t.id === v);
                                            setWorkerForm(prev => ({
                                                ...prev,
                                                supportTeamId: v,
                                                companyId: selectedTeam?.companyId || prev.companyId // 팀의 소속 회사 자동 설정
                                            }));
                                        }}
                                        disabled={!workerForm.companyId}
                                        options={[
                                            { value: '', label: workerForm.companyId ? '선택 (미지정 가능)' : '시공사 회사 먼저 선택' },
                                            ...constructionTeamOptions
                                        ]}
                                    />
                                )}

                                {workerForm.teamType === '지원팀' && (
                                    <Select
                                        label="협력사 팀"
                                        value={workerForm.supportTeamId}
                                        onChange={(v) => {
                                            const selectedTeam = teams.find(t => t.id === v);
                                            setWorkerForm(prev => ({
                                                ...prev,
                                                supportTeamId: v,
                                                companyId: selectedTeam?.companyId || prev.companyId // 팀의 소속 회사 자동 설정
                                            }));
                                        }}
                                        disabled={!workerForm.companyId}
                                        options={[
                                            { value: '', label: workerForm.companyId ? '선택' : '협력사 회사 먼저 선택' },
                                            ...supportTeamOptionsByCompany
                                        ]}
                                    />
                                )}
                                <Select
                                    label="급여방식"
                                    value={workerForm.salaryModel}
                                    onChange={(v) => setWorkerForm(prev => ({ ...prev, salaryModel: v as WorkerSalaryModel }))}
                                    disabled={workerForm.teamType === '지원팀'}
                                    options={[
                                        ...(workerForm.teamType === '지원팀'
                                            ? [{ value: '지원팀', label: '지원팀' }]
                                            : [
                                                { value: '일급제', label: '일급제' },
                                                { value: '월급제', label: '월급제' }
                                            ])
                                    ]}
                                />
                                <Input
                                    label="단가"
                                    type="number"
                                    value={workerForm.unitPrice}
                                    onChange={(val) => setWorkerForm(prev => ({ ...prev, unitPrice: val }))}
                                    placeholder="0"
                                />
                                <Select
                                    label="직책"
                                    value={workerForm.role}
                                    onChange={(val) => setWorkerForm(prev => ({ ...prev, role: val }))}
                                    options={[
                                        { value: '신규', label: '신규' },
                                        { value: '일반', label: '일반' },
                                        { value: '팀장', label: '팀장' }
                                    ]}
                                />
                                <div className="grid grid-cols-3 gap-2">
                                    <Input
                                        label="은행명"
                                        value={workerForm.bankName}
                                        onChange={(val) => setWorkerForm(prev => ({ ...prev, bankName: val }))}
                                        placeholder="은행 입력"
                                    />
                                    <Input
                                        label="계좌번호"
                                        value={workerForm.accountNumber}
                                        onChange={(val) => setWorkerForm(prev => ({ ...prev, accountNumber: val }))}
                                        placeholder="계좌번호 입력"
                                    />
                                    <Input
                                        label="예금주"
                                        value={workerForm.accountHolder}
                                        onChange={(val) => setWorkerForm(prev => ({ ...prev, accountHolder: val }))}
                                        placeholder="예금주 입력"
                                    />
                                </div>
                            </div>
                        )}

                        {selectedSection === 'team' && (
                            <div
                                className="rounded-md p-3 flex flex-col gap-3"
                                style={{ background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.10)' }}
                            >
                                <Input
                                    label="팀명"
                                    value={teamForm.name}
                                    onChange={(v) => {
                                        setIsTeamNameTouched(true);
                                        setTeamForm(prev => ({ ...prev, name: v }));
                                    }}
                                    placeholder="예: 1팀"
                                />
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                    <Select
                                        label="팀구분"
                                        value={teamForm.type}
                                        onChange={(v) => handleTeamTypeChange(v as QuickTeamRegisterType)}
                                        options={[
                                            { value: '시공팀', label: '시공팀' },
                                            { value: '지원팀', label: '지원팀' }
                                        ]}
                                    />
                                    {teamForm.type === '시공팀' ? (
                                        <Select
                                            label="시공사 회사"
                                            value={teamForm.companyId}
                                            onChange={(v) => {
                                                // 선택된 회사 정보 찾기
                                                const selectedCompany = companies.find(c => c.id === v);
                                                setIsTeamNameTouched(false);
                                                setTeamForm(prev => ({
                                                    ...prev,
                                                    companyId: v,
                                                    name: selectedCompany ? `${selectedCompany.name}팀` : '' // 회사명+팀
                                                }));
                                            }}
                                            options={[
                                                { value: '', label: '시공사 선택...' },
                                                ...constructionCompanyOptions
                                            ]}
                                        />
                                    ) : (
                                        <Select
                                            label="협력사 회사"
                                            value={teamForm.companyId}
                                            onChange={(v) => {
                                                // 선택된 회사 정보 찾기
                                                const selectedCompany = companies.find(c => c.id === v);
                                                setIsTeamNameTouched(false);
                                                setTeamForm(prev => ({
                                                    ...prev,
                                                    companyId: v,
                                                    selectedWorkerIds: [],
                                                    leaderWorkerId: '',
                                                    name: selectedCompany ? `${selectedCompany.name}팀` : '' // 회사명+팀
                                                }));
                                            }}
                                            options={[
                                                { value: '', label: '선택' },
                                                ...partnerCompanyOptions
                                            ]}
                                        />
                                    )}
                                </div>
                                <Select
                                    label="팀장(선택)"
                                    value={teamForm.leaderWorkerId}
                                    onChange={(v) => {
                                        const nextLeaderId = v;
                                        const nextLeaderName =
                                            nextLeaderId.trim().length > 0
                                                ? (workers.find(w => (w.id ? w.id === nextLeaderId : false))?.name ?? '')
                                                : '';

                                        setTeamForm(prev => {
                                            const prevLeaderName =
                                                prev.leaderWorkerId.trim().length > 0
                                                    ? (workers.find(w => (w.id ? w.id === prev.leaderWorkerId : false))?.name ?? '')
                                                    : '';

                                            const prevAutoName = prevLeaderName.trim().length > 0 ? `${prevLeaderName}팀` : '';
                                            const shouldAutoUpdateName =
                                                !isTeamNameTouched || prev.name.trim().length === 0 || (prevAutoName.length > 0 && prev.name === prevAutoName);

                                            if (nextLeaderId.trim().length === 0) {
                                                return {
                                                    ...prev,
                                                    leaderWorkerId: '',
                                                    selectedWorkerIds: [],
                                                    name: shouldAutoUpdateName ? '' : prev.name
                                                };
                                            }

                                            const nextAutoName = nextLeaderName.trim().length > 0 ? `${nextLeaderName}팀` : '';
                                            return {
                                                ...prev,
                                                leaderWorkerId: nextLeaderId,
                                                selectedWorkerIds: [nextLeaderId],
                                                name: shouldAutoUpdateName ? nextAutoName : prev.name
                                            };
                                        });
                                    }}
                                    disabled={isWorkersLoading || teamForm.companyId.trim().length === 0}
                                    options={[
                                        { value: '', label: '선택 안함' },
                                        ...teamWorkersForCompany.map(w => ({ value: w.id, label: w.label }))
                                    ]}
                                />
                            </div>
                        )}

                        {selectedSection === 'site' && (
                            <div
                                className="rounded-md p-3 flex flex-col gap-3"
                                style={{ background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.10)' }}
                            >
                                <Input
                                    label="현장명"
                                    value={siteForm.name}
                                    onChange={(v) => setSiteForm(prev => ({ ...prev, name: v }))}
                                    placeholder="예: ○○현장"
                                />

                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                    <Select
                                        label="담당팀(선택)"
                                        value={siteForm.responsibleTeamId}
                                        onChange={(v) =>
                                            setSiteForm(prev => {
                                                if (v.trim().length === 0) {
                                                    return { ...prev, responsibleTeamId: '', companyId: '' };
                                                }

                                                const team = teams.find(t => t.id === v) ?? null;
                                                const nextCompanyId = team?.companyId && team.companyId.trim().length > 0 ? team.companyId : '';

                                                return {
                                                    ...prev,
                                                    responsibleTeamId: v,
                                                    companyId: nextCompanyId
                                                };
                                            })
                                        }
                                        options={[
                                            { value: '', label: '선택안함' },
                                            ...siteTeamOptions
                                        ]}
                                    />
                                    <Select
                                        label="회사(자동)"
                                        value={siteForm.companyId}
                                        onChange={() => undefined}
                                        disabled
                                        options={[
                                            { value: '', label: '선택안함' },
                                            ...siteCompanyOptions
                                        ]}
                                    />
                                </div>
                            </div>
                        )}

                        {selectedSection === 'partnerCompany' && (
