                                        setPartnerCompanyForm(prev => {
                                            const baseName = extractPartnerCompanyBaseName(prev.name, prev.ceoName);
                                            return {
                                                ...prev,
                                                ceoName: nextCeoName,
                                                name:
                                                    trimmedNext.length === 0
                                                        ? baseName
                                                        : buildPartnerCompanyDisplayName(baseName, nextCeoName)
                                            };
                                        });

                                        if (!isPartnerCompanyTeamNameTouched) {
                                            setPartnerCompanyTeamForm({
                                                teamName: trimmedNext.length === 0 ? '' : `${trimmedNext}팀`
                                            });
                                        }
                                    }}
                                    placeholder="예: 홍대표"
                                />
                                <Input
                                    label="회사명"
                                    value={partnerCompanyForm.name}
                                    onChange={(v) => setPartnerCompanyForm(prev => ({ ...prev, name: v }))}
                                    onBlur={() =>
                                        setPartnerCompanyForm(prev => ({
                                            ...prev,
                                            name: buildPartnerCompanyDisplayName(
                                                extractPartnerCompanyBaseName(prev.name, prev.ceoName),
                                                prev.ceoName
                                            )
                                        }))
                                    }
                                    placeholder="예: ○○협력사"
                                />
                                <Input
                                    label="팀명"
                                    value={partnerCompanyTeamForm.teamName}
                                    onChange={(v) => {
                                        setIsPartnerCompanyTeamNameTouched(true);
                                        setPartnerCompanyTeamForm(prev => ({ ...prev, teamName: v }));
                                    }}
                                    placeholder="예: 홍대표팀"
                                />
                                <Input
                                    label="사업자번호"
                                    value={partnerCompanyForm.businessNumber}
                                    onChange={(v) => setPartnerCompanyForm(prev => ({ ...prev, businessNumber: v }))}
                                    placeholder="예: 123-45-67890"
                                />
                                <Input
                                    label="전화번호"
                                    value={partnerCompanyForm.phone}
                                    onChange={(v) => setPartnerCompanyForm(prev => ({ ...prev, phone: v }))}
                                    placeholder="예: 010-0000-0000"
                                />
                                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                                    <Input
                                        label="은행명"
                                        value={partnerCompanyForm.bankName}
                                        onChange={(v) => setPartnerCompanyForm(prev => ({ ...prev, bankName: v }))}
                                        placeholder="예: 국민은행"
                                    />
                                    <Input
                                        label="계좌번호"
                                        value={partnerCompanyForm.accountNumber}
                                        onChange={(v) => setPartnerCompanyForm(prev => ({ ...prev, accountNumber: v }))}
                                        placeholder="예: 123456-78-901234"
                                    />
                                    <Input
                                        label="예금주"
                                        value={partnerCompanyForm.accountHolder}
                                        onChange={(v) => setPartnerCompanyForm(prev => ({ ...prev, accountHolder: v }))}
                                        placeholder="예: 홍길동"
                                    />
                                </div>
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input
                                        type="checkbox"
                                        checked={registerCeoAsLeader}
                                        onChange={(e) => setRegisterCeoAsLeader(e.target.checked)}
                                        className="w-4 h-4 text-brand-600 bg-slate-700 border-slate-600 rounded focus:ring-brand-500 focus:ring-2"
                                    />
                                    <span className="text-sm text-slate-300">대표자를 팀장으로 등록</span>
                                </label>
                            </div>
                        )}

                        {selectedSection === 'constructionCompany' && (
                            <div
                                className="rounded-md p-3 flex flex-col gap-3"
                                style={{ background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.10)' }}
                            >
                                <Input
                                    label="회사명"
                                    value={constructionCompanyForm.name}
                                    onChange={(v) => setConstructionCompanyForm(prev => ({ ...prev, name: v }))}
                                    placeholder="예: ○○건설"
                                />
                                <Input
                                    label="사업자번호"
                                    value={constructionCompanyForm.businessNumber}
                                    onChange={(v) => setConstructionCompanyForm(prev => ({ ...prev, businessNumber: v }))}
                                    placeholder="예: 123-45-67890"
                                />
                                <Input
                                    label="대표자명"
                                    value={constructionCompanyForm.ceoName}
                                    onChange={(v) => setConstructionCompanyForm(prev => ({ ...prev, ceoName: v }))}
                                    placeholder="예: 홍대표"
                                />
                                <Input
                                    label="전화번호"
                                    value={constructionCompanyForm.phone}
                                    onChange={(v) => setConstructionCompanyForm(prev => ({ ...prev, phone: v }))}
                                    placeholder="예: 010-0000-0000"
                                />
                                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                                    <Input
                                        label="은행명"
                                        value={constructionCompanyForm.bankName}
                                        onChange={(v) => setConstructionCompanyForm(prev => ({ ...prev, bankName: v }))}
                                        placeholder="예: 국민은행"
                                    />
                                    <Input
                                        label="계좌번호"
                                        value={constructionCompanyForm.accountNumber}
                                        onChange={(v) => setConstructionCompanyForm(prev => ({ ...prev, accountNumber: v }))}
                                        placeholder="예: 123456-78-901234"
                                    />
                                    <Input
                                        label="예금주"
                                        value={constructionCompanyForm.accountHolder}
                                        onChange={(v) => setConstructionCompanyForm(prev => ({ ...prev, accountHolder: v }))}
                                        placeholder="예: 홍길동"
                                    />
                                </div>
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input
                                        type="checkbox"
                                        checked={registerCeoAsRepresentative}
                                        onChange={(e) => setRegisterCeoAsRepresentative(e.target.checked)}
                                        className="w-4 h-4 text-brand-600 bg-slate-700 border-slate-600 rounded focus:ring-brand-500 focus:ring-2"
                                    />
                                    <span className="text-sm text-slate-300">대표자를 작업자로 등록 (직책: 대표)</span>
                                </label>
                            </div>
                        )}
                    </div>
                )}

                {activeTab === 'memo' && (
                    <div className="h-full w-full overflow-hidden rounded-lg shadow-xl" style={{ minHeight: '400px' }}>
                        <QuickMemoEditor />
                    </div>
                )}

                {activeTab === 'calculator' && (
                    <div className="h-full w-full">
                        <Calculator />
                    </div>
                )}
            </div>
        </aside>
    );
};

export default BottomPanel;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate, useLocation, type NavigateOptions } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { MessageManager } from '../../constants/messages';
// ROLE_SITE_MAP removed - now fully dynamic
import './DashboardLayout.css';

import Header from './Header';
import Sidebar from './Sidebar';
// import RightPanel from './RightPanel';

import BottomPanel from './LayoutBottomPanel';
import AdminPanel from './AdminPanel';

// 타입 인터페이스 정의
import SidebarSkeleton from './SidebarSkeleton';
import { menuServiceV11 } from '../../services/menuServiceV11';
import { SiteData, SiteDataType, MenuItem } from '../../types/menu';
import { MENU_PATHS } from '../../constants/menuPaths';
import { ErrorBoundary } from 'react-error-boundary';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faTriangleExclamation, faRotateRight } from '@fortawesome/free-solid-svg-icons';
import { SiteModeProvider } from '../../contexts/SiteModeContext';

// Removed hardcoded siteData in favor of dynamic loading

interface DashboardLayoutProps {
    children: React.ReactNode;
}

// Error Fallback Component for UI Stability
const ErrorFallback = ({ error, resetErrorBoundary }: { error: Error; resetErrorBoundary: () => void }) => {
    return (
        <div className="flex flex-col items-center justify-center h-full p-6 text-center bg-slate-50 rounded-lg border border-slate-200 m-4">
            <FontAwesomeIcon icon={faTriangleExclamation} className="text-amber-500 text-3xl mb-3" />
            <h3 className="text-lg font-bold text-slate-700 mb-1">일시적인 오류 발생</h3>
            <p className="text-slate-500 text-sm mb-4">화면을 불러오는 중 문제가 발생했습니다.</p>
            <pre className="text-xs text-red-400 bg-red-50 p-2 rounded mb-4 max-w-xs overflow-auto">
                {error.message}
            </pre>
            <button
                onClick={resetErrorBoundary}
                className="px-4 py-2 bg-white border border-slate-300 rounded-lg hover:bg-slate-50 text-slate-700 text-sm font-medium transition-colors flex items-center gap-2"
            >
                <FontAwesomeIcon icon={faRotateRight} />
                다시 시도
            </button>
        </div>
    );
};

const DashboardLayout: React.FC<DashboardLayoutProps> = ({ children }) => {
    const [isMobile, setIsMobile] = useState(false);
    const [isMobileOpen, setIsMobileOpen] = useState(false);
    const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
    const [isBottomPanelOpen, setIsBottomPanelOpen] = useState(false);
    const [isPositionPanelOpen, setIsPositionPanelOpen] = useState(false);
    // 사이트 모드를 localStorage에서 복원하여 수동 변경 시 유지되도록 함
    const [currentSite, setCurrentSite] = useState(() => {
        const saved = localStorage.getItem('cy_current_site');
        return saved || 'admin';
    });
    const [currentPosition, setCurrentPosition] = useState('full');
    const [userManuallyChangedSite, setUserManuallyChangedSite] = useState(() => {
        return localStorage.getItem('cy_site_manual') === 'true';
    });
    const [activeMenuItems, setActiveMenuItems] = useState<{ [key: string]: boolean }>({});
    const [activeNestedMenuItems, setActiveNestedMenuItems] = useState<{ [key: string]: boolean }>({});
    const [isAdmin, setIsAdmin] = useState(false);
    const [isAdminPanelOpen, setIsAdminPanelOpen] = useState(false);
    const [isDarkMode, setIsDarkMode] = useState<boolean>(() => {
        return localStorage.getItem('cy-cheongyeon-theme') !== 'light';
    });

    // Dynamic Menu State
    const [siteData, setSiteData] = useState<SiteDataType | null>(null);

    const didRunMenuMigrationsRef = useRef(false);

    const { currentUser } = useAuth();
    const navigate = useNavigate();
    const location = useLocation();
    const siteModeDashboards: Record<string, string> = {
        test: '/dashboard2',
        nation: '/dashboard3',
    };
    const siteModeDashboardPath = siteModeDashboards[currentSite];
    const isSiteLayerMode = Boolean(siteModeDashboardPath);
    const usesSiteBranding = currentSite === 'test' || currentSite === 'nation';
    const navigateSync = useCallback((to: string, options?: NavigateOptions) => {
        navigate(to, {
            ...options,
            flushSync: true,
        });
    }, [navigate]);

    // Fetch Menu Config
    useEffect(() => {
        // Initial fetch logic omitted as subscribe handles init
        // Subscribe to real-time updates from menuServiceV11
        const unsubscribe = menuServiceV11.subscribe((newConfig) => {
            console.log('[DashboardLayout] Received new menu config update.', { siteKeys: Object.keys(newConfig) });
            setSiteData(newConfig);
        });

        return () => {
            unsubscribe();
        };
    }, []);

    // Update MessageManager context on route change or user change
    useEffect(() => {
        MessageManager.setContext({
            uid: currentUser?.uid,
            page: location.pathname
        });
    }, [currentUser, location]);

    useEffect(() => {
        const handleResize = () => {
            setIsMobile(window.innerWidth <= 768);
        };

        handleResize();
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                closeAll();
            }
        };

        document.addEventListener('keydown', handleKeyDown);
        return () => document.removeEventListener('keydown', handleKeyDown);
    }, []);

    // 청연사이트 모드일 때 /dashboard 접근 시 /dashboard2로 리다이렉트
    useEffect(() => {
        if (siteModeDashboardPath && location.pathname === '/dashboard') {
            navigateSync(siteModeDashboardPath, { replace: true });
        }
    }, [siteModeDashboardPath, location.pathname, navigateSync]);

    useEffect(() => {
        const setupAdminListener = async () => {
            if (currentUser && siteData) { // Wait for siteData to be loaded
                try {
                    const { userService } = await import('../../services/userService');

                    let cancelled = false;
                    const applyRole = (roleRaw: any) => {
                        const role = roleRaw ? String(roleRaw) : '';
                        const adminRoles = ['admin', '관리자', '사장', '실장'];
                        const isAdminRole = adminRoles.includes(role);
                        setIsAdmin(isAdminRole);

                        if (isAdminRole && !didRunMenuMigrationsRef.current) {
                            didRunMenuMigrationsRef.current = true;
                            menuServiceV11.runOneTimeMigrations().catch((err) => {
                                console.error('[MenuService] One-time migration failed:', err);
                            });
                        }

                        let targetSite = '';
                        if (role === 'admin' || role === '관리자') targetSite = 'admin';

                        if (siteData) {
                            const positions = siteData.admin?.positionConfig || [];
                            const matchedPos = positions.find((p: any) => p.name === role || p.id === role);
                            if (matchedPos) {
                                if (matchedPos.id === 'full') {
                                    targetSite = 'admin';
                                } else {
                                    targetSite = matchedPos.id.startsWith('pos_') ? matchedPos.id : `pos_${matchedPos.id}`;
                                }
                            }
                        }

                        // 사용자가 수동으로 사이트를 변경하지 않은 경우에만 자동 설정
                        // 최초 로그인 시에만 역할 기반 사이트 설정 적용
                        if (targetSite && (siteData as any)?.[targetSite] && !userManuallyChangedSite) {
                            setCurrentSite((prevSite) => (prevSite === targetSite ? prevSite : targetSite));
                        }

                        MessageManager.setContext({ role });
                    };

                    const loadAndApply = async () => {
                        if (!currentUser) return;
                        const u = await userService.getUser(currentUser.uid);
                        if (cancelled) return;
                        applyRole(u?.role);
                    };

                    await loadAndApply();
                    const timer = setInterval(loadAndApply, 600000); // 10분 폴링 (비용 최적화)

                    return () => {
                        cancelled = true;
                        clearInterval(timer);
                    };
                } catch (error) {
                    console.error("Failed to setup admin listener", error);
                }
            } else {
                setIsAdmin(false);
            }
        };

        let cleanup: void | (() => void);
        (async () => {
            cleanup = await setupAdminListener();
        })();

        return () => {
            if (typeof cleanup === 'function') cleanup();
        };
    }, [currentUser, siteData]); // Re-run when siteData is loaded

    // Real-time System Config Listener (ERP/SITE logo & favicon)
    const [systemConfig, setSystemConfig] = useState<{
        logoUrl?: string;
        faviconUrl?: string;
        erpLogoUrl?: string;
        siteLogoUrl?: string;
        erpFaviconUrl?: string;
        siteFaviconUrl?: string;
        nationLogoUrl?: string;
        nationFaviconUrl?: string;
    }>({});

    useEffect(() => {
        const setupConfigListener = async () => {
            const { db } = await import('../../config/firebase');
            const { doc, onSnapshot } = await import('firebase/firestore');

            const unsubscribe = onSnapshot(doc(db, 'settings', 'system_config'), (docSnap) => {
                if (docSnap.exists()) {
                    const data = docSnap.data();
                    setSystemConfig({
                        logoUrl: data.logoUrl,
                        faviconUrl: data.faviconUrl,
                        erpLogoUrl: data.erpLogoUrl,
                        siteLogoUrl: data.siteLogoUrl,
                        erpFaviconUrl: data.erpFaviconUrl,
                        siteFaviconUrl: data.siteFaviconUrl,
                        nationLogoUrl: data.nationLogoUrl,
                        nationFaviconUrl: data.nationFaviconUrl,
                    });
                }
            });

            return unsubscribe;
        };

        let unsubscribe: (() => void) | undefined;
        setupConfigListener().then(unsub => {
            unsubscribe = unsub;
        });

        return () => {
            if (unsubscribe) unsubscribe();
        };
    }, []);

    // 전국시스템인력(nation)만 별도 로고/파비콘 우선 적용
    const activeLogoUrl = currentSite === 'nation'
        ? (systemConfig.nationLogoUrl || systemConfig.siteLogoUrl || systemConfig.logoUrl)
        : usesSiteBranding
            ? (systemConfig.siteLogoUrl || systemConfig.logoUrl)
            : (systemConfig.erpLogoUrl || systemConfig.logoUrl);

    useEffect(() => {
        let faviconUrl: string = '';
        if (currentSite === 'nation') {
            faviconUrl = systemConfig.nationFaviconUrl ?? systemConfig.siteFaviconUrl ?? systemConfig.faviconUrl ?? '';
        } else if (usesSiteBranding) {
            faviconUrl = systemConfig.siteFaviconUrl ?? systemConfig.faviconUrl ?? '';
        } else {
            faviconUrl = systemConfig.erpFaviconUrl ?? systemConfig.faviconUrl ?? '';
        }

        if (!faviconUrl) return;

        const link = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
        if (link) {
            link.href = faviconUrl;
        } else {
            const newLink = document.createElement('link');
            newLink.rel = 'icon';
            newLink.href = faviconUrl;
            document.head.appendChild(newLink);
        }
    }, [currentSite, usesSiteBranding, systemConfig.nationFaviconUrl, systemConfig.siteFaviconUrl, systemConfig.erpFaviconUrl, systemConfig.faviconUrl]);

    const toggleSidebar = () => {
        closePanels();
        if (isMobile) {
            setIsMobileOpen(!isMobileOpen);
        } else {
            setIsSidebarCollapsed(!isSidebarCollapsed);
        }
    };

    const togglePanel = (type: 'bottom' | 'admin' | 'position') => {
        if (type === 'bottom') {
            setIsBottomPanelOpen(!isBottomPanelOpen);
            setIsAdminPanelOpen(false);
            setIsPositionPanelOpen(false);
        } else if (type === 'admin') {
            setIsAdminPanelOpen(!isAdminPanelOpen);
            setIsBottomPanelOpen(false);
            setIsPositionPanelOpen(false);
        } else if (type === 'position') {
            setIsPositionPanelOpen(!isPositionPanelOpen);
            setIsBottomPanelOpen(false);
            setIsAdminPanelOpen(false);
        }
    };

    const toggleSubmenu = (itemId: string) => {
        setActiveMenuItems(prev => {
            const newState = { ...prev };
            Object.keys(newState).forEach(key => {
                if (key !== itemId) newState[key] = false;
            });
            newState[itemId] = !newState[itemId];
            return newState;
        });
    };

    const toggleNestedSubmenu = (nestedItemId: string) => {
        setActiveNestedMenuItems(prev => {
            const newState = { ...prev };
            Object.keys(newState).forEach(key => {
                if (key !== nestedItemId) newState[key] = false;
            });
            newState[nestedItemId] = !newState[nestedItemId];
            return newState;
        });
    };

    const handleLogoClick = () => {
        setActiveMenuItems({});
        // 청연사이트 모드이면 /dashboard2로, 아니면 /dashboard로 이동
        navigateSync(siteModeDashboardPath || '/dashboard');
    };

    // Position to Site mapping - 직책별로 전용 메뉴 사용
    // 'full' = 현재 사이트(보통 admin) 전체 메뉴 표시
    // Dynamic Position Config extraction
    const positions = (siteData?.['admin']?.positionConfig || []).sort((a, b) => (a.order || 0) - (b.order || 0));

    // Fallback if no config (shouldn't happen due to auto-migration, but safe fallback)
    // We don't need a hardcoded fallback here if we trust the service migration.

    // Position to Site mapping - 직책별로 전용 메뉴 사용
    // 'full' = 현재 사이트(보통 admin) 전체 메뉴 표시
    const getPositionSiteMap = () => {
        const map: { [key: string]: string } = { 'full': '' };
        if (positions.length > 0) {
            positions.forEach(pos => {
                if (pos.id !== 'full') {
                    // Convention: pos_ + id if id doesn't already start with pos_
                    // Actually, the keys in siteData are 'pos_ceo', 'pos_manager1' etc.
                    // The position IDs in config are 'ceo', 'manager1'.
                    // So we map id -> 'pos_' + id.
                    // But if the ID itself is 'pos_ceo', we handle that.
                    const siteKey = pos.id.startsWith('pos_') ? pos.id : `pos_${pos.id}`;
                    map[pos.id] = siteKey;
                }
            });
        }
        return map;
    };

    const POSITION_SITE_MAP = getPositionSiteMap();

    // Use position-based site for left menu
    // 'full' position uses currentSite (full admin menu)
    const positionSite = POSITION_SITE_MAP[currentPosition];
    const effectiveSite = (currentPosition === 'full' || !positionSite)
        ? currentSite
        : (siteData?.[positionSite] ? positionSite : currentSite);
    const currentSiteData = siteData ? siteData[effectiveSite] : null;

    const handleMenuItemClick = (item: MenuItem, position?: number) => {
        if (!currentSiteData) return;

        // 1. Direct Path (Priority)
        if (item.path) {
            navigateSync(item.path);
            if (isMobile) {
                closeAll();
                setActiveMenuItems({});
            } else {
                // 상위 메뉴(Top Level) 클릭 시에만 다른 메뉴 닫기 (= Accordion 효과)
                // 하위 메뉴(Level 2 등) 클릭 시에는 현재 펼쳐진 상태 유지
                const isTopLevel = currentSiteData.menu.some(topItem => topItem.text === item.text);
                if (isTopLevel) {
                    setActiveMenuItems({});
                }
            }
            return;
        }

        // 2. Folder / Group (has children)
        if (item.sub && item.sub.length > 0) {
            const itemId = `menu-${currentSiteData.menu.findIndex((i: MenuItem) => i.text === item.text)}`;
            toggleSubmenu(itemId);
            return;
        }

        // 3. Empty folder or unlinked item (no path, no children) -> do nothing
        // NOTE: We intentionally do NOT fallback to MENU_PATHS[item.text] here.
        // Path resolution must be done in menuServiceV11 normalization.
        setActiveMenuItems({});
        return;
    };

    const closePanels = () => {
        setIsBottomPanelOpen(false);
        setIsAdminPanelOpen(false);
        setIsPositionPanelOpen(false);
    };

    const closeAll = () => {
        setIsMobileOpen(false);
        closePanels();
        // if (!isMobile) {
        //     setIsSidebarCollapsed(true); // Auto-collapse sidebar on PC - REMOVED to prevent layout thrashing
        // }
    };

    const changeSite = (siteKey: string) => {
        setCurrentSite(siteKey);
        setActiveMenuItems({});
        // 사용자가 수동으로 사이트를 변경했음을 기록
        setUserManuallyChangedSite(true);
        localStorage.setItem('cy_current_site', siteKey);
        localStorage.setItem('cy_site_manual', 'true');

        // 청연사이트(test)로 전환 시 /dashboard2로 이동
        const nextDashboardPath = siteModeDashboards[siteKey];
        if (nextDashboardPath) {
            navigateSync(nextDashboardPath);
        } else if (location.pathname === '/dashboard2' || location.pathname === '/dashboard3') {
            // 다른 사이트로 전환 시 /dashboard2에 있으면 /dashboard로 이동
            navigateSync('/dashboard');
        }
    };

    const changePosition = (positionId: string) => {
        setCurrentPosition(positionId);
        setActiveMenuItems({});
        // TODO: Load position-specific menu when implemented
        console.log('Position changed to:', positionId);
    };

    const menuPaths = MENU_PATHS;

    const toggleDarkMode = () => {
        setIsDarkMode(prev => {
            const next = !prev;
            localStorage.setItem('cy-cheongyeon-theme', next ? 'dark' : 'light');
            return next;
        });
    };

    const shouldOpenInNewTab = (path: string | undefined): boolean => {
        if (!path) return false;
        const [, search] = path.split('?');
        if (!search) return false;
        const params = new URLSearchParams(search);
        return params.get('newTab') === '1' || params.get('newTab') === 'true';
    };

    const handleSubMenuClick = (subItem: string) => {
        const path = menuPaths[subItem];
        if (path) {
            if (shouldOpenInNewTab(path)) {
                window.open(path, '_blank', 'noopener,noreferrer');
                if (isMobile) closeAll();
                return;
            }
            navigateSync(path);
            if (isMobile) closeAll();
        }
    };

    const siteModeValue = {
        siteData,
        currentSite,
        effectiveSite,
        currentSiteData: (currentSiteData as SiteData | null),
        changeSite,
        isDarkMode,
        toggleDarkMode
    };

    if (!siteData) {
        return (
            <SiteModeProvider {...siteModeValue}>
                <div className="app">
                    <SidebarSkeleton />
                    <main id="main-content" style={{ marginLeft: '250px' }}>
                        {children}
                    </main>
                </div>
            </SiteModeProvider>
        );
    }

    // Layout Variant for Cheongyeon SITE (test) - Same structure as Admin ERP with video background
    if (isSiteLayerMode && currentSiteData) {
        const isNation = currentSite === 'nation';
        return (
            <SiteModeProvider {...siteModeValue}>
                <div className={`app cheongyeon-mode ${isNation ? 'nation-mode' : ''} ${isDarkMode ? '' : 'cy-light'} ${isSidebarCollapsed ? 'sidebar-collapsed' : ''} ${isMobileOpen ? 'mobile-open' : ''}`}>
                    <div className="backdrop" id="backdrop" onClick={closeAll}></div>

                    {/* Same Header as Admin ERP */}
                    <Header
                        toggleSidebar={toggleSidebar}
                        togglePanel={togglePanel}
                        currentSiteData={currentSiteData}
                        isAdmin={isAdmin}
                        isPositionPanelOpen={isPositionPanelOpen}
                        currentPosition={currentPosition}
                        changePosition={changePosition}
                        positions={positions}
                        siteData={siteData}
                        currentSite={currentSite}
                        changeSite={changeSite}
                        menuPaths={menuPaths}
                        logoUrl={activeLogoUrl}
                        isDarkMode={isDarkMode}
                        toggleDarkMode={toggleDarkMode}
                    />

                    {/* Same Sidebar as Admin ERP (Left Side) */}
                    <ErrorBoundary FallbackComponent={ErrorFallback} onReset={() => window.location.reload()}>
                        <Sidebar
                            currentSite={effectiveSite}
                            currentSiteData={currentSiteData}
                            closeAll={closeAll}
                            activeMenuItems={activeMenuItems}
                            activeNestedMenuItems={activeNestedMenuItems}
                            toggleSubmenu={toggleSubmenu}
                            toggleNestedSubmenu={toggleNestedSubmenu}
                            handleMenuItemClick={handleMenuItemClick}
                            handleSubMenuClick={handleSubMenuClick}
                            handleLogoClick={handleLogoClick}
                            menuPaths={menuPaths}
                            isSidebarCollapsed={isSidebarCollapsed}
                            isMobile={isMobile}
                            openMobileSidebar={() => setIsMobileOpen(true)}
                            toggleSidebar={toggleSidebar}
                            logoUrl={activeLogoUrl}
                        />
                    </ErrorBoundary>


                    {/* Bottom Panel */}
                    <BottomPanel
                        isOpen={isBottomPanelOpen}
                        togglePanel={togglePanel}
                        currentSite={currentSite}
                        changeSite={changeSite}
                    />

                    {/* Admin Panel */}
                    <AdminPanel
                        isOpen={isAdminPanelOpen}
                        togglePanel={togglePanel}
                        siteData={siteData}
                        menuPaths={menuPaths}
                    />



                    {/* Main Content with Video Background for Dashboard2 */}
                    <main id="main-content" className={location.pathname === siteModeDashboardPath ? 'cheongyeon-main' : ''} onClick={() => {
                        if (isBottomPanelOpen || isAdminPanelOpen || isPositionPanelOpen || isMobileOpen || !isSidebarCollapsed) {
                            closeAll();
                        }
                    }}>
                        <ErrorBoundary
                            FallbackComponent={ErrorFallback}
                            onReset={() => window.location.reload()}
                            resetKeys={[location.pathname, location.search]}
                        >
                            {children}
                        </ErrorBoundary>
                    </main>
                </div>
            </SiteModeProvider>
        );
    }

    return (
        <SiteModeProvider {...siteModeValue}>
            <div className={`app ${isSidebarCollapsed ? 'sidebar-collapsed' : ''} ${isMobileOpen ? 'mobile-open' : ''}`}>
                <div className="backdrop" id="backdrop" onClick={closeAll}></div>

                <Header
                    toggleSidebar={toggleSidebar}
                    togglePanel={togglePanel}
                    currentSiteData={currentSiteData}
                    isAdmin={isAdmin}
                    isPositionPanelOpen={isPositionPanelOpen}
                    currentPosition={currentPosition}
                    changePosition={changePosition}
                    positions={positions}
                    siteData={siteData}
                    currentSite={currentSite}
                    changeSite={changeSite}
                    menuPaths={menuPaths}
                    logoUrl={activeLogoUrl}
                />

                <ErrorBoundary FallbackComponent={ErrorFallback} onReset={() => window.location.reload()}>
                    <Sidebar
                        currentSite={effectiveSite}
                        currentSiteData={currentSiteData}
                        closeAll={closeAll}
                        activeMenuItems={activeMenuItems}
                        activeNestedMenuItems={activeNestedMenuItems}
                        toggleSubmenu={toggleSubmenu}
                        toggleNestedSubmenu={toggleNestedSubmenu}
                        handleMenuItemClick={handleMenuItemClick}
                        handleSubMenuClick={handleSubMenuClick}
                        handleLogoClick={handleLogoClick}
                        menuPaths={menuPaths}
                        isSidebarCollapsed={isSidebarCollapsed}
                        isMobile={isMobile}
                        openMobileSidebar={() => setIsMobileOpen(true)}
                        toggleSidebar={toggleSidebar}
                        logoUrl={activeLogoUrl}
                    />
                </ErrorBoundary>


                <BottomPanel
                    isOpen={isBottomPanelOpen}
                    togglePanel={togglePanel}
                    currentSite={currentSite}
                    changeSite={changeSite}
                />

                <AdminPanel
                    isOpen={isAdminPanelOpen}
                    togglePanel={togglePanel}
                    siteData={siteData}
                    menuPaths={menuPaths}
                />



                <main id="main-content" onClick={() => {
                    if (isBottomPanelOpen || isAdminPanelOpen || isPositionPanelOpen || isMobileOpen || !isSidebarCollapsed) {
                        closeAll();
                    }
                }}>
                    <ErrorBoundary
                        FallbackComponent={ErrorFallback}
                        onReset={() => window.location.reload()}
                        resetKeys={[location.pathname, location.search]}
                    >
                        {children}
                    </ErrorBoundary>
                </main>
            </div>
        </SiteModeProvider>
    );
};

export default DashboardLayout;

import React, { useRef, useState, useEffect } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faBars,
    faUserGear,
    faGear,
    faUserShield,
    faUser,
    faRightFromBracket,
    faShieldHalved,
    faIdBadge,
    faSun,
    faMoon
} from '@fortawesome/free-solid-svg-icons';
import { useAuth } from '../../contexts/AuthContext';
import { useLocation, useNavigate } from 'react-router-dom';
import { resolveIcon } from '../../constants/iconMap';
import { userService } from '../../services/userService';
import PositionPanel from './PositionPanel';
import { PositionItem, SiteDataType, MenuItem } from '../../types/menu';

interface CheongyeonNavChild {
    label: string;
    path: string;
    sourceGroup?: string;
}

interface CheongyeonNavSection {
    key: string;
    label: string;
    path: string;
    children: CheongyeonNavChild[];
}

interface HeaderProps {
    toggleSidebar: () => void;
    togglePanel: (type: 'bottom' | 'admin' | 'position') => void;
    currentSiteData: any;
    isAdmin: boolean;
    isPositionPanelOpen: boolean;
    currentPosition: string;
    changePosition: (positionId: string) => void;
    positions: PositionItem[];
    siteData: SiteDataType | null;
    currentSite: string;
    changeSite: (siteKey: string) => void;
    menuPaths: { [key: string]: string };
    logoUrl?: string;
    isDarkMode?: boolean;
    toggleDarkMode?: () => void;
}

const Header: React.FC<HeaderProps> = ({
    toggleSidebar,
    togglePanel,
    currentSiteData,
    isAdmin,
    isPositionPanelOpen,
    currentPosition,
    changePosition,
    positions,
    siteData,
    currentSite,
    changeSite,
    menuPaths,
    logoUrl,
    isDarkMode = true,
    toggleDarkMode
}) => {
    const { currentUser, logout } = useAuth();
    const navigate = useNavigate();
    const location = useLocation();
    const [isProfileOpen, setIsProfileOpen] = useState(false);
    const [activeTopNavKey, setActiveTopNavKey] = useState<string | null>(null);
    const topNavCloseTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const profileRef = useRef<HTMLDivElement>(null);
    const positionPanelRef = useRef<HTMLDivElement>(null);

    const clearTopNavCloseTimer = () => {
        if (topNavCloseTimerRef.current) {
            clearTimeout(topNavCloseTimerRef.current);
            topNavCloseTimerRef.current = null;
        }
    };

    const scheduleTopNavClose = () => {
        clearTopNavCloseTimer();
        topNavCloseTimerRef.current = setTimeout(() => {
            setActiveTopNavKey(null);
        }, 280);
    };

    const handleTopNavMouseLeave = (event: React.MouseEvent<HTMLElement>) => {
        const nextTarget = event.relatedTarget;
        if (nextTarget instanceof Element) {
            if (
                nextTarget.closest('.cheongyeon-top-nav') ||
                nextTarget.closest('.cheongyeon-top-nav-dropdown')
            ) {
                clearTopNavCloseTimer();
                return;
            }
        }
        scheduleTopNavClose();
    };

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
                setIsProfileOpen(false);
            }
            // Close position panel if click is outside
            if (positionPanelRef.current && !positionPanelRef.current.contains(event.target as Node)) {
                if (isPositionPanelOpen) {
                    togglePanel('position');
                }
            }

            const navContainer = document.querySelector('.cheongyeon-top-nav');
            if (navContainer && !navContainer.contains(event.target as Node)) {
                setActiveTopNavKey(null);
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
            clearTopNavCloseTimer();
        };
    }, [isPositionPanelOpen, togglePanel]);

    const handleLogout = async () => {
        try {
            await logout();
            navigate('/login');
        } catch (error) {
            console.error("Failed to log out", error);
        }
    };

    const handleAdminToggle = async () => {
        if (!currentUser) return;
        try {
            await userService.updateUserRole(currentUser.uid, isAdmin ? 'user' : 'admin');
            alert(`관리자 권한이 ${isAdmin ? '해제' : '부여'}되었습니다. 새로고침하세요.`);
            window.location.reload();
        } catch (e: any) {
            console.error(e);
            alert(`변경 실패: ${e?.message || JSON.stringify(e)}`);
        }
    };

    // `test` and `nation` share the SITE-style top navigation shell.
    const isSiteLayerMode = currentSite === 'test' || currentSite === 'nation';
    const siteLandingPath = currentSite === 'nation' ? '/dashboard3' : '/dashboard2';
    const headerStyle = isSiteLayerMode
        ? isDarkMode
            ? { backgroundColor: '#0f172a', color: '#e2e8f0', borderBottom: '1px solid #1e293b' }
            : { backgroundColor: '#ffffff', color: '#1e293b', borderBottom: '1px solid #e2e8f0' }
        : {};

    const shouldOpenInNewTab = (path: string | undefined): boolean => {
        if (!path) return false;
        const [, search] = path.split('?');
        if (!search) return false;
        const params = new URLSearchParams(search);
        return params.get('newTab') === '1' || params.get('newTab') === 'true';
    };

    const resolvePath = (menuItem?: MenuItem | null): string => {
        if (!menuItem) return '';
        return menuItem.path || menuPaths[menuItem.text] || '';
    };

    const collectChildLinks = (children: (string | MenuItem)[] = [], parentText?: string): CheongyeonNavChild[] => {
        const result: CheongyeonNavChild[] = [];

        children.forEach((child) => {
            if (typeof child === 'string') {
                const path = menuPaths[child] || '';
                if (!path) return;
                result.push({ label: child, path, sourceGroup: parentText });
                return;
            }

            const directPath = resolvePath(child);
            if (directPath) {
                result.push({ label: child.text, path: directPath, sourceGroup: parentText });
            }

            if (child.sub && child.sub.length > 0) {
                result.push(...collectChildLinks(child.sub, child.text));
            }
        });

        const dedup = new Map<string, CheongyeonNavChild>();
        result.forEach((item) => {
            const key = `${item.label}|${item.path}`;
            if (!dedup.has(key)) dedup.set(key, item);
        });

        return Array.from(dedup.values());
    };

    const cheongyeonTopNav: CheongyeonNavSection[] = Array.isArray(currentSiteData?.menu)
        ? currentSiteData.menu
            .filter((item: MenuItem) => !item.hide)
            .map((item: MenuItem, index: number) => {
                const children = collectChildLinks(item.sub || [], item.text);
                const path = resolvePath(item) || children[0]?.path || '';
                return {
                    key: `${item.id || item.text || index}`,
                    label: item.text,
                    path,
                    children,
                };
            })
            .filter((item: CheongyeonNavSection) => !!item.path || item.children.length > 0)
        : [];

    const handleTopNavRoute = (path: string) => {
        if (!path) return;
        setActiveTopNavKey(null);
        if (shouldOpenInNewTab(path)) {
            window.open(path, '_blank', 'noopener,noreferrer');
            return;
        }
        navigate(path);
    };

    const isTopNavActive = (section: CheongyeonNavSection) => {
        if (section.path && location.pathname === section.path) return true;
        return section.children.some((child) => location.pathname.startsWith(child.path));
    };

    return (
        <header id="main-header" style={headerStyle} className={isSiteLayerMode ? 'cheongyeon-header' : ''}>
            <div className="header-left-group">
                <button className="header-btn" id="sidebar-toggle" onClick={toggleSidebar} aria-label="메뉴 토글">
                    <FontAwesomeIcon icon={faBars} />
                </button>

                {isSiteLayerMode && (
                    <button
                        type="button"
                        className="cheongyeon-header-logo"
                        onClick={() => navigate(siteLandingPath)}
                        aria-label="청연 메인으로 이동"
                    >
                        {logoUrl ? (
                            <img
                                src={logoUrl}
                                alt="청연 로고"
                                className="cheongyeon-header-logo-image"
                            />
                        ) : (
                            <FontAwesomeIcon
                                icon={resolveIcon(currentSiteData.icon, faShieldHalved)}
                                className="cheongyeon-header-logo-icon"
                            />
                        )}
                    </button>
                )}

                <div className="mobile-logo-area">
                    {logoUrl ? (
                        <img 
                            src={logoUrl} 
                            alt="Logo" 
                            style={{ height: '24px', width: 'auto', marginRight: '8px', objectFit: 'contain' }}
                        />
                    ) : (
                        <FontAwesomeIcon icon={resolveIcon(currentSiteData.icon, faShieldHalved)} style={{ marginRight: '8px', color: '#3498db' }} />
                    )}
                    <span>{currentSiteData.name}</span>
                </div>
            </div>

            {isSiteLayerMode && (
                <nav
                    className="cheongyeon-top-nav"
                    onMouseEnter={clearTopNavCloseTimer}
                    onMouseLeave={handleTopNavMouseLeave}
                >
                    {cheongyeonTopNav.map((section) => (
                        <div
                            key={section.key}
                            className="cheongyeon-top-nav-item"
                            onMouseLeave={handleTopNavMouseLeave}
                            onMouseEnter={() => {
                                clearTopNavCloseTimer();
                                setActiveTopNavKey(section.key);
                            }}
                        >
                            <button
                                type="button"
                                className={`cheongyeon-top-nav-link ${isTopNavActive(section) ? 'active' : ''}`}
                                onClick={() => handleTopNavRoute(section.path)}
                            >
                                {section.label}
                            </button>

                            {activeTopNavKey === section.key && section.children.length > 0 && (
                                <div className="cheongyeon-top-nav-dropdown" onMouseEnter={clearTopNavCloseTimer} onMouseLeave={handleTopNavMouseLeave}>
                                    <div className="cheongyeon-top-nav-dropdown-grid">
                                        {section.children.map((child) => (
                                            <button
                                                key={`${child.label}|${child.path}`}
                                                type="button"
                                                className={`cheongyeon-top-nav-sub-item ${location.pathname.startsWith(child.path) ? 'active' : ''}`}
                                                onClick={() => handleTopNavRoute(child.path)}
                                            >
                                                <span className="cheongyeon-top-nav-sub-title">{child.label}</span>
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    ))}
                </nav>
            )}

            <div className="header-right-group">
                {isSiteLayerMode && toggleDarkMode && (
                    <button
                        className="header-btn cheongyeon-theme-toggle"
                        onClick={toggleDarkMode}
                        title={isDarkMode ? '라이트 모드로 전환' : '다크 모드로 전환'}
                        style={{ color: isDarkMode ? '#fbbf24' : '#64748b' }}
                    >
                        <FontAwesomeIcon icon={isDarkMode ? faSun : faMoon} />
                    </button>
                )}
                <button className="header-btn" onClick={() => togglePanel('bottom')} title="빠른 실행">
                    <FontAwesomeIcon icon={faUserGear} />
                </button>

                {isAdmin && (
                    <div className="relative" ref={positionPanelRef}>
                        <button className="header-btn text-indigo-400 hover:bg-white/10" onClick={() => togglePanel('position')} title="모드 선택">
                            <FontAwesomeIcon icon={faIdBadge} />
                        </button>
                        {isPositionPanelOpen && (
                            <PositionPanel
                                isOpen={isPositionPanelOpen}
                                togglePanel={togglePanel}
                                currentPosition={currentPosition}
                                changePosition={changePosition}
                                positions={positions}
                                siteData={siteData}
                                currentSite={currentSite}
                                changeSite={changeSite}
                            />
                        )}
                    </div>
                )}

                {isAdmin && (
                    <button className="header-btn text-red-400 hover:bg-white/10" onClick={() => togglePanel('admin')} title="관리자 메뉴">
                        <FontAwesomeIcon icon={faUserShield} />
                    </button>
                )}

                <div className="profile-menu-container" ref={profileRef}>
                    <button
                        className="header-btn profile-btn"
                        onClick={() => setIsProfileOpen(!isProfileOpen)}
                        title="프로필"
                    >
                        {currentUser?.photoURL ? (
                            <img
                                src={currentUser.photoURL}
                                alt="Profile"
                                className="header-profile-img"
                                onError={(e) => {
                                    const target = e.target as HTMLImageElement;
                                    target.style.display = 'none';
                                    const icon = target.parentElement?.querySelector('.fallback-icon') as HTMLElement;
                                    if (icon) icon.style.display = 'block';
                                }}
                            />
                        ) : (
                            <FontAwesomeIcon icon={faUser} />
                        )}
                        {currentUser?.photoURL && (
                            <FontAwesomeIcon icon={faUser} className="fallback-icon" style={{ display: 'none' }} />
                        )}
                    </button>

                    {isProfileOpen && (
                        <div className="profile-dropdown">
                            <div className="profile-info">
                                <div className="profile-name">{currentUser?.displayName || '사용자'}</div>
                                <div className="profile-email">{currentUser?.email}</div>
                            </div>
                            <button className="dropdown-item logout-btn" onClick={() => {
                                setIsProfileOpen(false);
                                navigate('/profile');
                            }}>
                                <FontAwesomeIcon icon={faUserGear} />
                                <span>프로필 설정</span>
                            </button>
                            <button className="dropdown-item logout-btn" onClick={handleLogout}>
                                <FontAwesomeIcon icon={faRightFromBracket} />
                                <span>로그아웃</span>
                            </button>
                            <button className="dropdown-item logout-btn" onClick={handleAdminToggle} style={{ marginTop: '10px', color: '#3b82f6', borderTop: '1px solid #eee' }}>
                                <FontAwesomeIcon icon={faUserShield} />
                                <span>{isAdmin ? '관리자 해제' : '관리자 권한 부여 (임시)'}</span>
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </header>
    );
};

export default Header;

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faXmark, faShieldHalved, faBuilding, faPhotoFilm, faCartShopping, faPenNib, faFlask, faChartPie, faSitemap, faFileImport } from '@fortawesome/free-solid-svg-icons';
import { resolveIcon } from '../../constants/iconMap';

interface RightPanelProps {
    isOpen: boolean;
    togglePanel: (type: 'right') => void;
    siteData: any;
    currentSite: string;
    changeSite: (siteKey: string) => void;
    menuPaths: { [key: string]: string };
}

const RightPanel: React.FC<RightPanelProps> = ({ isOpen, togglePanel, siteData, currentSite, changeSite, menuPaths }) => {
    const navigate = useNavigate();

    const handleNavigation = (path: string) => {
        navigate(path);
        togglePanel('right');
    };

    // Get System Structure Diagram items from learning menu
    const structureItems = siteData.learning?.menu?.find((m: any) => m.text === "시스템 구조도")?.sub || [];



    return (
        <aside id="right-panel" className={`panel ${isOpen ? 'open' : ''}`}>
            <div className="panel-header">
                <span>사이트 모드</span>
                <button onClick={() => togglePanel('right')} style={{ color: 'white' }}>
                    <FontAwesomeIcon icon={faXmark} />
                </button>
            </div>
            <div className="panel-content">
                <div className="site-switch-grid" id="site-switcher" style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '10px', padding: '10px' }}>
                    {Object.keys(siteData)
                        .filter((key: string) => !key.startsWith('pos_')) // Filter out internal position sites
                        .sort((a, b) => (siteData[a].order || 999) - (siteData[b].order || 999))
                        .map((key: string) => (
                            <button
                                key={key}
                                className={`${currentSite === key ? 'active' : ''}`}
                                onClick={() => changeSite(key)}
                                style={{
                                    display: 'flex',
                                    flexDirection: 'column',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    padding: '15px 5px',
                                    background: currentSite === key ? 'white' : 'rgba(255, 255, 255, 0.15)',
                                    borderRadius: '8px',
                                    color: currentSite === key ? '#3498db' : 'white',
                                    border: 'none',
                                    cursor: 'pointer',
                                    transition: '0.2s',
                                    width: '100%',
                                    height: '80px', // Fixed height for uniformity
                                    boxShadow: currentSite === key ? '0 4px 6px rgba(0,0,0,0.1)' : 'none'
                                }}
                            >
                                <FontAwesomeIcon
                                    // @ts-ignore
                                    icon={resolveIcon(siteData[key].icon, faBuilding)}
                                    style={{ fontSize: '20px', marginBottom: '8px' }}
                                />
                                <span style={{ fontSize: '12px', textAlign: 'center', fontWeight: currentSite === key ? 'bold' : 'normal' }}>{siteData[key].name}</span>
                            </button>
                        ))}
                </div>


            </div>
        </aside>
    );
};

export default RightPanel;

import React, { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faXmark,
    faShieldHalved,
    faChartPie,
    faClipboardList,
    faFileInvoiceDollar,
    faDatabase,
    faBuilding,
    faPhotoFilm,
    faCartShopping,
    faPenNib,
    faFlask,
    faChevronRight,
    faChevronLeft,
    faUserGear,
    faHardDrive,
    faUserTie,
    faUsers,
    faUserTag,
    faWrench,
    faPersonDigging,
    faUserPlus,
    faListCheck,
    faFileImport,
    faUserGroup,
    faHandHoldingDollar,
    faTruckFront,
    faHelmetSafety,
    faSitemap,
    faBookOpen,
    faList,
    faClockRotateLeft,
    faMoneyBillWave,
    faChartSimple,
    faBook,
    faUpRightFromSquare
} from '@fortawesome/free-solid-svg-icons';
import { doc, onSnapshot } from 'firebase/firestore';
import { db } from '../../config/firebase';
import { useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { userService } from '../../services/userService';
import { rolePermissionService } from '../../services/rolePermissionService';
import { UserRole } from '../../types/roles';
import { SiteDataType, MenuItem } from '../../types/menu';

import * as AllIcons from '@fortawesome/free-solid-svg-icons';
import { iconMap, resolveIcon } from '../../constants/iconMap';

interface SidebarProps {
    currentSite: string;
    currentSiteData: any;
    closeAll: () => void;
    activeMenuItems: { [key: string]: boolean };
    activeNestedMenuItems: { [key: string]: boolean };
    toggleSubmenu: (itemId: string) => void;
    toggleNestedSubmenu: (nestedItemId: string) => void;
    handleMenuItemClick: (item: MenuItem, position?: number) => void;
    handleSubMenuClick: (subItem: string) => void;
    handleLogoClick: () => void;
    menuPaths: { [key: string]: string };
    isSidebarCollapsed: boolean;
    isMobile: boolean;
    openMobileSidebar: () => void;
    toggleSidebar?: () => void;
    logoUrl?: string;
}

// Map menu text/path to permission IDs
const MENU_PERMISSION_MAP: { [key: string]: string } = {
    '통합 대시보드': 'dashboard',
    '통합 현황판 (전국)': 'status-board',
    '근로자 등록/수정': 'manpower-input',
    '팀 배정 관리': 'assignment',
    '일보 작성 (Input)': 'daily-report-input',
    '일보 목록/승인': 'daily-report-list',
    '급여 지급 관리': 'payroll-payment',
    '명세서 조회': 'payroll-payslip',
    '시스템 설정': 'system-config',
    '스마트 메모': 'smart-memo',
    'Smart Memo': 'smart-memo',
    // Add mappings for parent menus if needed, or handle logic to show parent if any child is visible
};

const Sidebar: React.FC<SidebarProps> = ({
    currentSite,
    currentSiteData,
    closeAll,
    activeMenuItems,
    activeNestedMenuItems,
    toggleSubmenu,
    toggleNestedSubmenu,
    handleMenuItemClick,
    handleSubMenuClick,
    handleLogoClick,
    menuPaths,
    isSidebarCollapsed,
    isMobile,
    openMobileSidebar,
    toggleSidebar,
    logoUrl
}) => {
    const location = useLocation();
    const navigate = useNavigate();
    const { currentUser } = useAuth();
    const [userRole, setUserRole] = useState<string>('user');
    const [permissions, setPermissions] = useState<any>(null);

    useEffect(() => {
        let userUnsubscribe: () => void;

        if (currentUser) {
            // Listen to user role changes in real-time
            userUnsubscribe = onSnapshot(doc(db, 'users', currentUser.uid), (docSnap: any) => {
                if (docSnap.exists()) {
                    const data = docSnap.data();
                    if (data?.role) {
                        setUserRole(data.role);
                        console.log("Sidebar: User role updated to", data.role);
                    }
                }
            });
        }

        const unsubscribe = rolePermissionService.subscribe((perms) => {
            setPermissions(perms);
        });

        // Initial fetch
        rolePermissionService.getPermissions().then(setPermissions);

        return () => {
            unsubscribe();
            if (userUnsubscribe) userUnsubscribe();
        };
    }, [currentUser]);

    const hasPermission = (itemText: string, itemRoles?: string[]): boolean => {
        // 1. Dynamic Check (Priority 1)
        if (itemRoles && itemRoles.length > 0) {
            // Admin bypass (optional)
            if (userRole === 'admin') return true;
            return itemRoles.includes(userRole);
        }

        // 2. Legacy Check (Priority 2)
        const permissionId = MENU_PERMISSION_MAP[itemText];
        if (!permissionId) return true;

        return rolePermissionService.hasAccess(userRole, permissionId);
    };

    const isActiveCheck = (path: string | undefined) => {
        if (!path) return false;

        const [targetPathname, targetSearch] = path.split('?');

        const currentPathname = location.pathname.endsWith('/') && location.pathname.length > 1
            ? location.pathname.slice(0, -1)
            : location.pathname;
        const normalizedTargetPathname = targetPathname.endsWith('/') && targetPathname.length > 1
            ? targetPathname.slice(0, -1)
            : targetPathname;

        if (currentPathname !== normalizedTargetPathname) return false;

        if (!targetSearch) return true;

        const currentParams = new URLSearchParams(location.search);
        const targetParams = new URLSearchParams(targetSearch);

        let isMatch = true;
        targetParams.forEach((value, key) => {
            if (currentParams.get(key) !== value) isMatch = false;
        });
        if (!isMatch) return false;

        return true;
    };

    const shouldOpenInNewTab = (path: string | undefined): boolean => {
        if (!path) return false;
        const [, search] = path.split('?');
        if (!search) return false;
        const params = new URLSearchParams(search);
        return params.get('newTab') === '1' || params.get('newTab') === 'true';
    };

    const openMenuPath = (path: string) => {
        if (shouldOpenInNewTab(path)) {
            window.open(path, '_blank', 'noopener,noreferrer');
            if (isMobile) closeAll();
            return;
        }
        navigate(path);
        if (isMobile) closeAll();
    };

    const isParentActive = (item: MenuItem): boolean => {
        if (!item.sub) return false;
        return item.sub.some(subItem => {
            if (typeof subItem === 'string') {
                return isActiveCheck(menuPaths[subItem]);
            } else {
                return subItem.sub?.some(nestedItem =>
                    typeof nestedItem === 'string' && isActiveCheck(menuPaths[nestedItem])
                );
            }
        });
    };

    // Filter menu items based on permissions
    const filteredMenu = currentSiteData.menu.map((item: MenuItem) => {
        // Check if parent has sub-items
        if (item.sub) {
            // Filter sub-items
            const filteredSub = item.sub.filter((subItem: string | MenuItem) => {
                if (typeof subItem === 'string') {
                    return hasPermission(subItem);
                } else {
                    // Object Item
                    const menuItem = subItem as MenuItem;

                    // If it has children, treat as Nested Group
                    if (menuItem.sub && menuItem.sub.length > 0) {
                        const filteredNested = menuItem.sub.filter((nested: string | MenuItem) => {
                            if (typeof nested === 'string') {
                                return hasPermission(nested);
                            } else {
                                // Nested Object Item
                                return hasPermission(nested.text, nested.roles);
                            }
                        });
                        // If children exist, check if any remain
                        return filteredNested.length > 0;
                    }

                    // If no children (or empty array), treat as Leaf Link (Object format)
                    return hasPermission(menuItem.text, menuItem.roles);
                }
            });

            return { ...item, sub: filteredSub };
        }

        // Single item
        return hasPermission(item.text, item.roles) ? item : null;
    }).filter(Boolean);

    const finalMenu = [...filteredMenu];

    // State for hover menu in collapsed mode
    const [hoveredMenuItem, setHoveredMenuItem] = useState<MenuItem | null>(null);
    const [hoveredItemTop, setHoveredItemTop] = useState<number>(0);
    const [isPanelHovered, setIsPanelHovered] = useState(false);
    const timeoutRef = React.useRef<NodeJS.Timeout | null>(null);

    const handleItemMouseEnter = (item: MenuItem, e: React.MouseEvent<HTMLLIElement>) => {
        if (timeoutRef.current) {
            clearTimeout(timeoutRef.current);
            timeoutRef.current = null;
        }
        if (isSidebarCollapsed && item.sub) {
            const rect = e.currentTarget.getBoundingClientRect();
            setHoveredMenuItem(item);
            setHoveredItemTop(rect.top);
        }
    };

    const handleMouseLeaveNav = () => {
        timeoutRef.current = setTimeout(() => {
            setHoveredMenuItem(null);
        }, 100); // 100ms grace period
    };

    const handlePanelMouseEnter = () => {
        if (timeoutRef.current) {
            clearTimeout(timeoutRef.current);
            timeoutRef.current = null;
        }
        setIsPanelHovered(true);
    };

    const handlePanelMouseLeave = () => {
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
        timeoutRef.current = setTimeout(() => {
            setHoveredMenuItem(null);
            setIsPanelHovered(false);
        }, 300); // Increased delay
    };

    // Cheongyeon Style Check
    const isCheongyeon = currentSite === 'test';
    const sidebarStyle = isCheongyeon ? { backgroundColor: '#0f172a', color: '#e2e8f0' } : {};
    const logoStyle = isCheongyeon ? { color: '#ffffff' } : {};

    const [logoType, setLogoType] = useState<'image' | 'video'>('image');

    useEffect(() => {
        if (logoUrl) {
            const isVideo = logoUrl.toLowerCase().includes('.mp4') || 
                          logoUrl.toLowerCase().includes('.webm') ||
                          logoUrl.toLowerCase().includes('video');
            setLogoType(isVideo ? 'video' : 'image');
        }
    }, [logoUrl]);

    return (
        <>
            <nav id="sidebar" onMouseLeave={handleMouseLeaveNav} style={sidebarStyle} className={isCheongyeon ? 'cheongyeon-sidebar' : ''}>
                <div className="sidebar-header">
                    <div className="logo-group" onClick={(!isMobile && isSidebarCollapsed && toggleSidebar) ? toggleSidebar : handleLogoClick} title={(!isMobile && isSidebarCollapsed) ? '메뉴 펼치기' : undefined} style={{ cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: isSidebarCollapsed ? 'center' : 'flex-start', flex: isSidebarCollapsed ? '0 0 100%' : '1 1 auto', minWidth: 0, overflow: 'hidden' }}>
                        {logoUrl ? (
                            logoType === 'video' ? (
                                <video 
                                    src={logoUrl} 
                                    autoPlay 
                                    loop 
                                    muted 
                                    playsInline
                                    style={{ height: '32px', width: 'auto', marginRight: isSidebarCollapsed ? '0' : '10px', borderRadius: '4px' }}
                                />
                            ) : (
                                <img 
                                    src={logoUrl} 
                                    alt="Logo" 
                                    style={{ height: '32px', width: 'auto', marginRight: isSidebarCollapsed ? '0' : '10px', objectFit: 'contain' }}
                                />
                            )
                        ) : (
                            <FontAwesomeIcon
                                icon={resolveIcon(currentSiteData.icon, faShieldHalved)}
                                id="sidebar-logo-icon"
                                style={{ color: '#1abc9c', fontSize: '24px', marginRight: isSidebarCollapsed ? '0' : '10px' }}
                            />
                        )}
                        <span id="sidebar-logo-text" className="logo-text" style={{ ...logoStyle, whiteSpace: 'nowrap', textOverflow: 'ellipsis', overflow: 'hidden' }}>
                            {currentSiteData.name}
                        </span>
                    </div>
                    {/* PC 전용: 접기 버튼 (펼쳐진 상태일 때만 표시) */}
                    {!isMobile && !isSidebarCollapsed && toggleSidebar && (
                        <button
                            className="sidebar-pc-toggle-btn"
                            onClick={toggleSidebar}
                            title="메뉴 접기"
                        >
                            <FontAwesomeIcon icon={faChevronLeft} />
                        </button>
                    )}
                    <button id="mobile-close-btn" onClick={closeAll} style={isCheongyeon ? { color: 'white' } : {}}>
                        <FontAwesomeIcon icon={faXmark} />
                    </button>
                </div>
                <div className="menu-list-wrapper">
                    <ul className="menu-list" style={{ paddingBottom: '20px' }}>
                        {finalMenu.map((item: MenuItem, index: number) => {
                            const hasSub = item.sub && item.sub.length > 0;
                            const uniqueKey = item.id || `menu-${index}`;
                            const itemId = uniqueKey;
                            const isExpanded = activeMenuItems[itemId];
                            const isChildActive = isParentActive(item);

                            // Determine Active Color (Default: #1abc9c)
                            const activeColor = item.activeColor || '#1abc9c';
                            // Determine Icon Color (Default: inherit or specific logic)
                            // If active/expanded, we might want to force activeColor or keep iconColor?
                            // Usually active state overrides icon color to activeColor.
                            // Let's use iconColor if set, UNLESS active/expanded where we might want high contrast or activeColor.
                            // Current design: Active item text/icon becomes activeColor (green #1abc9c).

                            const isItemActive = isExpanded || isChildActive;
                            const effectiveIconColor = isItemActive ? activeColor : (item.iconColor || undefined);
                            const effectiveTextStyle = isItemActive ? { color: activeColor, fontWeight: 'bold' } : {};

                            return (
                                <li
                                    key={uniqueKey}
                                    className={`menu-item ${isExpanded ? 'active' : ''}`}
                                    onMouseEnter={(e) => handleItemMouseEnter(item, e)}
                                >
                                    {hasSub ? (
                                        <button
                                            className="menu-btn"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                if (isMobile) {
                                                    openMobileSidebar();
                                                    toggleSubmenu(itemId);
                                                } else if (isSidebarCollapsed) {
                                                    e.preventDefault();
                                                } else {
                                                    toggleSubmenu(itemId);
                                                }
                                            }}
                                            data-tooltip={item.text}
                                            style={effectiveTextStyle}
                                        >
                                            <FontAwesomeIcon
                                                icon={resolveIcon(item.icon)}
                                                className="menu-icon"
                                                style={{ color: effectiveIconColor }}
                                            />
                                            <span className="menu-text">{item.text}</span>
                                            <FontAwesomeIcon
                                                icon={faChevronRight}
                                                className={`arrow-icon ${isExpanded ? 'rotated' : ''}`}
                                            />
                                        </button>
                                    ) : (
                                        <a
                                            href="#"
                                            className="menu-link"
                                            onClick={(e) => {
                                                e.preventDefault();
                                                const directPath = item.path || menuPaths[item.text] || '';
                                                if (directPath && shouldOpenInNewTab(directPath)) {
                                                    openMenuPath(directPath);
                                                    return;
                                                }
                                                handleMenuItemClick(item);
                                            }}
                                            onMouseEnter={() => isSidebarCollapsed && setHoveredMenuItem(null)}
                                            data-tooltip={item.text}
                                            style={isActiveCheck(item.path || menuPaths[item.text]) ? { color: activeColor, fontWeight: 'bold' } : {}}
                                        >
                                            <FontAwesomeIcon
                                                icon={resolveIcon(item.icon)}
                                                className="menu-icon"
                                                style={{
                                                    color: isActiveCheck(item.path || menuPaths[item.text]) ? activeColor : (item.iconColor || undefined)
                                                }}
                                            />
                                            <span className="menu-text">{item.text}</span>
                                            {!isSidebarCollapsed && (
                                                <button
                                                    className="menu-open-new-btn"
                                                    onClick={(e) => {
                                                        e.preventDefault();
                                                        e.stopPropagation();
                                                        const path = item.path || menuPaths[item.text] || '';
                                                        if (path) window.open(path, '_blank');
                                                    }}
                                                    title="새 창에서 열기"
                                                >
                                                    <FontAwesomeIcon icon={faUpRightFromSquare} size="xs" />
                                                </button>
                                            )}
                                        </a>
                                    )}
                                    {hasSub && (
                                        <ul className="submenu-list">
                                            {item.sub?.map((subItem: string | MenuItem, subIndex: number) => {
                                                let isLeaf = false;
                                                let linkText = '';
                                                let linkPath = '';
                                                let subUniqueKey = `sub-${uniqueKey}-${subIndex}`;
                                                let subItemIconColor = undefined;
                                                let subItemActiveColor = '#1abc9c';

                                                if (typeof subItem === 'string') {
                                                    isLeaf = true;
                                                    linkText = subItem;
                                                    linkPath = menuPaths[subItem] || '';
                                                    subUniqueKey = `sub-${linkText}`;
                                                } else {
                                                    const menuItem = subItem as MenuItem;
                                                    subUniqueKey = menuItem.id || `sub-${uniqueKey}-${subIndex}`;
                                                    subItemIconColor = menuItem.iconColor;
                                                    subItemActiveColor = menuItem.activeColor || '#1abc9c';

                                                    if (!menuItem.sub || menuItem.sub.length === 0) {
                                                        isLeaf = true;
                                                        linkText = menuItem.text;
                                                        linkPath = menuItem.path || menuPaths[menuItem.text] || '';
                                                    }
                                                }

                                                if (isLeaf) {
                                                    const isSubActive = isActiveCheck(linkPath);
                                                    return (
                                                        <li key={subUniqueKey} className="submenu-leaf-item">
                                                            <a
                                                                href="#"
                                                                onClick={(e) => {
                                                                    e.preventDefault();
                                                                    if (linkPath) {
                                                                        if (shouldOpenInNewTab(linkPath)) {
                                                                            openMenuPath(linkPath);
                                                                            return;
                                                                        }
                                                                        if (typeof subItem !== 'string' && (subItem as MenuItem).path) {
                                                                            handleMenuItemClick(subItem as MenuItem);
                                                                            return;
                                                                        }
                                                                        handleSubMenuClick(linkText);
                                                                    }
                                                                }}
                                                                className={isSubActive ? 'active' : ''}
                                                                style={{
                                                                    color: isSubActive ? subItemActiveColor : undefined,
                                                                    fontWeight: isSubActive ? 'bold' : 'normal'
                                                                }}
                                                            >
                                                                <span>{linkText}</span>
                                                                {!isSidebarCollapsed && (
                                                                    <button
                                                                        className="submenu-open-new-btn"
                                                                        onClick={(e) => {
                                                                            e.preventDefault();
                                                                            e.stopPropagation();
                                                                            if (linkPath) window.open(linkPath, '_blank');
                                                                        }}
                                                                        title="새 창에서 열기"
                                                                    >
                                                                        <FontAwesomeIcon icon={faUpRightFromSquare} size="xs" />
                                                                    </button>
                                                                )}
                                                            </a>
                                                        </li>
                                                    );
                                                } else {
                                                    const menuItem = subItem as MenuItem;
                                                    const nestedItemId = menuItem.id || `nested-${index}-${subIndex}`;
                                                    const isNestedActive = activeNestedMenuItems[nestedItemId];
                                                    const nestedActiveColor = menuItem.activeColor || '#1abc9c';
                                                    const nestedIconColor = menuItem.iconColor;

                                                    return (
                                                        <li key={subUniqueKey} className="nested-submenu">
                                                            <button
                                                                className="submenu-header-btn"
                                                                onClick={(e) => {
                                                                    toggleNestedSubmenu(nestedItemId);
                                                                }}
                                                            >
                                                                <div style={{ display: 'flex', alignItems: 'center' }}>
                                                                    <FontAwesomeIcon
                                                                        icon={resolveIcon(menuItem.icon, faChartPie)}
                                                                        style={{
                                                                            marginRight: '8px',
                                                                            fontSize: '12px',
                                                                            color: isNestedActive ? nestedActiveColor : (nestedIconColor || 'inherit')
                                                                        }}
                                                                    />
                                                                    <span style={isNestedActive ? { color: nestedActiveColor } : {}}>
                                                                        {menuItem.text}
                                                                    </span>
                                                                </div>
                                                                <FontAwesomeIcon
                                                                    icon={faChevronRight}
                                                                    className={`arrow-icon ${isNestedActive ? 'rotated' : ''}`}
                                                                    style={{ fontSize: '10px', transition: 'transform 0.3s' }}
                                                                />
                                                            </button>
                                                            {isNestedActive && (
                                                                <ul className="nested-submenu-list" style={{ paddingLeft: '15px' }}>
                                                                    {menuItem.sub?.map((nestedItem: string | MenuItem, nestedIndex: number) => {
                                                                        let nestedUniqueKey = `nested-${subUniqueKey}-${nestedIndex}`;
                                                                        let nestedDeepActiveColor = '#1abc9c';

                                                                        if (typeof nestedItem === 'string') {
                                                                            nestedUniqueKey = `nested-leaf-${nestedItem}`;
                                                                            const path = menuPaths[nestedItem];
                                                                            const isSubActive = isActiveCheck(path);
                                                                            if (!hasPermission(nestedItem)) return null;

                                                                            return (
                                                                                <li key={nestedUniqueKey}>
                                                                                        <a
                                                                                            href="#"
                                                                                            onClick={(e) => {
                                                                                                e.preventDefault();
                                                                                                if (path) {
                                                                                                    openMenuPath(path);
                                                                                                    return;
                                                                                                }
                                                                                                handleSubMenuClick(nestedItem as string);
                                                                                            }}
                                                                                            className={isSubActive ? 'active' : ''}
                                                                                            style={isSubActive ? { color: nestedDeepActiveColor, fontWeight: 'bold' } : {}}
                                                                                        >
                                                                                            <span>{nestedItem}</span>
                                                                                            {!isSidebarCollapsed && (
                                                                                                <button
                                                                                                    className="submenu-open-new-btn"
                                                                                                    onClick={(e) => {
                                                                                                        e.preventDefault();
                                                                                                        e.stopPropagation();
                                                                                                        if (path) window.open(path, '_blank');
                                                                                                    }}
                                                                                                    title="새 창에서 열기"
                                                                                                >
                                                                                                    <FontAwesomeIcon icon={faUpRightFromSquare} size="xs" />
                                                                                                </button>
                                                                                            )}
                                                                                        </a>
                                                                                </li>
                                                                            );
                                                                        } else {
                                                                            const nestedObj = nestedItem as MenuItem;
                                                                            nestedUniqueKey = nestedObj.id || nestedUniqueKey;
                                                                            nestedDeepActiveColor = nestedObj.activeColor || '#1abc9c';

                                                                            if (!nestedObj.sub || nestedObj.sub.length === 0) {
                                                                                const linkPath = nestedObj.path || menuPaths[nestedObj.text];
                                                                                const isSubActive = isActiveCheck(linkPath);
                                                                                if (!hasPermission(nestedObj.text)) return null;
                                                                                return (
                                                                                    <li key={nestedUniqueKey}>
                                                                                        <a
                                                                                            href="#"
                                                                                            onClick={(e) => {
                                                                                                e.preventDefault();
                                                                                                const directPath = nestedObj.path || linkPath;
                                                                                                if (directPath && shouldOpenInNewTab(directPath)) {
                                                                                                    openMenuPath(directPath);
                                                                                                    return;
                                                                                                }
                                                                                                if (nestedObj.path) handleMenuItemClick(nestedObj);
                                                                                                else handleSubMenuClick(nestedObj.text);
                                                                                            }}
                                                                                            className={isSubActive ? 'active' : ''}
                                                                                            style={isSubActive ? { color: nestedDeepActiveColor, fontWeight: 'bold' } : {}}
                                                                                        >
                                                                                            <span>{nestedObj.text}</span>
                                                                                            {!isSidebarCollapsed && (
                                                                                                <button
                                                                                                    className="submenu-open-new-btn"
                                                                                                    onClick={(e) => {
                                                                                                        e.preventDefault();
                                                                                                        e.stopPropagation();
                                                                                                        const path = nestedObj.path || linkPath || '';
                                                                                                        if (path) window.open(path, '_blank');
                                                                                                    }}
                                                                                                    title="새 창에서 열기"
                                                                                                >
                                                                                                    <FontAwesomeIcon icon={faUpRightFromSquare} size="xs" />
                                                                                                </button>
                                                                                            )}
                                                                                        </a>
                                                                                    </li>
                                                                                )
                                                                            }
                                                                        }
                                                                        return null;
                                                                    })}
                                                                </ul>
                                                            )}
                                                        </li>
                                                    );
                                                }
                                            })}
                                        </ul>
                                    )}
                                </li>
                            );
                        })}
                    </ul>
                </div>
            </nav>

            {/* Hover Submenu Panel for Collapsed Mode (Portal to body) */}
            {isSidebarCollapsed && hoveredMenuItem && createPortal(
                <div
                    className={`submenu-panel ${hoveredMenuItem ? 'open' : ''}`}
                    onMouseEnter={handlePanelMouseEnter}
                    onMouseLeave={handlePanelMouseLeave}
                    style={{
                        position: 'fixed',
                        zIndex: 9999,
                        top: Math.min(hoveredItemTop, window.innerHeight - 300) + 'px',
                        left: '60px',
                        transformOrigin: 'left top',
                        borderColor: hoveredMenuItem.activeColor // Optional border color?
                    }}
                >
                    <div className="submenu-panel-header" style={hoveredMenuItem.activeColor ? { borderBottomColor: hoveredMenuItem.activeColor } : {}}>
                        <span className="submenu-title" style={{ display: 'flex', alignItems: 'center', gap: '8px', color: hoveredMenuItem.activeColor || '#1abc9c' }}>
                            <FontAwesomeIcon
                                icon={resolveIcon(hoveredMenuItem.icon, faChartPie)}
                                style={{ color: hoveredMenuItem.activeColor || hoveredMenuItem.iconColor || '#1abc9c' }}
                            />
                            {hoveredMenuItem.text}
                        </span>
                        <button className="submenu-close-btn" onClick={() => setHoveredMenuItem(null)}>
                            <FontAwesomeIcon icon={faXmark} />
                        </button>
                    </div>
                    <div className="submenu-panel-content">
                        {hoveredMenuItem.sub?.map((subItem: string | MenuItem, idx: number) => {
                            let isLeaf = false;
                            let itemText = '';
                            let itemPath = '';
                            let itemIcon = '';
                            let itemActiveColor = '#1abc9c';
                            let itemIconColor = undefined;

                            if (typeof subItem === 'string') {
                                isLeaf = true;
                                itemText = subItem;
                                itemPath = menuPaths[subItem];
                            } else {
                                const mi = subItem as MenuItem;
                                itemActiveColor = mi.activeColor || '#1abc9c';
                                itemIconColor = mi.iconColor;
                                if (!mi.sub || mi.sub.length === 0) {
                                    isLeaf = true;
                                    itemText = mi.text;
                                    itemPath = mi.path || menuPaths[mi.text];
                                    itemIcon = mi.icon || '';
                                } else {
                                    isLeaf = false;
                                    itemText = mi.text;
                                    itemIcon = mi.icon || '';
                                }
                            }

                            if (isLeaf) {
                                const isSubActive = isActiveCheck(itemPath);
                                return (
                                    <button
                                        key={idx}
                                        className={`submenu-item ${isSubActive ? 'active' : ''}`}
                                        style={{
                                            cursor: 'pointer', userSelect: 'none', textAlign: 'left', width: '100%',
                                            color: isSubActive ? itemActiveColor : undefined,
                                            fontWeight: isSubActive ? 'bold' : 'normal'
                                        }}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            if (itemPath) {
                                                openMenuPath(itemPath);
                                            } else {
                                                alert(`경로를 찾을 수 없습니다: ${itemText}`);
                                            }
                                            setHoveredMenuItem(null);
                                        }}
                                    >
                                        {itemIcon && (
                                            <FontAwesomeIcon
                                                icon={resolveIcon(itemIcon, faChartPie)}
                                                style={{ marginRight: '8px', fontSize: '10px', width: '12px', color: itemIconColor }}
                                            />
                                        )}
                                        <span>{itemText}</span>
                                    </button>
                                );
                            } else {
                                const menuItem = subItem as MenuItem;
                                return (
                                    <div key={idx}>
                                        <div className="submenu-item nested-header" style={{ userSelect: 'none' }}>
                                            <span style={{ color: itemActiveColor }}>
                                                <FontAwesomeIcon
                                                    icon={resolveIcon(menuItem.icon || 'faCircle', faChartPie)}
                                                    style={{ marginRight: '8px', fontSize: '10px', color: itemIconColor }}
                                                />
                                                {menuItem.text}
                                            </span>
                                        </div>
                                        {menuItem.sub?.map((nested: string | MenuItem, nIdx: number) => {
                                            let deepText = '';
                                            let deepPath = '';
                                            let deepPermission = '';
                                            let deepActiveColor = '#1abc9c';

                                            if (typeof nested === 'string') {
                                                deepText = nested;
                                                deepPath = menuPaths[nested];
                                                deepPermission = nested;
                                            } else {
                                                deepText = nested.text;
                                                deepPath = nested.path || menuPaths[nested.text];
                                                deepPermission = nested.text;
                                                deepActiveColor = nested.activeColor || '#1abc9c';
                                            }

                                            if (!hasPermission(deepPermission)) return null;

                                            const isNestedActive = isActiveCheck(deepPath);

                                            return (
                                                <button
                                                    key={`${idx}-${nIdx}`}
                                                    className={`submenu-item nested-item ${isNestedActive ? 'active' : ''}`}
                                                    style={{
                                                        cursor: 'pointer', userSelect: 'none', textAlign: 'left', width: '100%',
                                                        color: isNestedActive ? deepActiveColor : undefined,
                                                        fontWeight: isNestedActive ? 'bold' : 'normal'
                                                    }}
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        if (deepPath) {
                                                            openMenuPath(deepPath);
                                                        } else {
                                                            console.warn("No deepPath found, falling back to handleSubMenuClick");
                                                            alert(`이 메뉴에는 연결된 경로가 없습니다: ${deepText}\n메뉴 관리에서 경로를 설정해주세요.`);
                                                            handleSubMenuClick(deepText);
                                                        }
                                                        setHoveredMenuItem(null);
                                                    }}
                                                >
                                                    <span>{deepText}</span>
                                                </button>
                                            );
                                        })}
                                    </div>
                                );
                            }
                        })}
                    </div>
                </div>,
                document.body
            )}
        </>
    );
};

export default Sidebar;

import React, { useRef, useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faXmark, faChevronRight, faChartPie, faCircle, faUpRightFromSquare } from '@fortawesome/free-solid-svg-icons';
import { MenuItem } from '../../types/menu';
import { resolveIcon } from '../../constants/iconMap';

interface SidebarSubmenuProps {
    item: MenuItem;
    top: number;
    menuPaths: { [key: string]: string };
    onClose: () => void;
    onMouseEnter: () => void;
    onMouseLeave: () => void;
    onItemClick: (path: string) => void;
    onOpenInNewWindow: (path: string) => void;
    isActiveCheck: (path: string | undefined) => boolean;
}

export const SidebarSubmenu: React.FC<SidebarSubmenuProps> = ({
    item,
    top,
    menuPaths,
    onClose,
    onMouseEnter,
    onMouseLeave,
    onItemClick,
    onOpenInNewWindow,
    isActiveCheck
}) => {
    const menuRef = useRef<HTMLDivElement>(null);
    const [adjustedTop, setAdjustedTop] = useState(top);

    useEffect(() => {
        if (menuRef.current) {
            const height = menuRef.current.offsetHeight;
            const windowHeight = window.innerHeight;
            // Ensure at least 20px padding from bottom
            const maxTop = windowHeight - height - 20;
            // Ensure not negative
            const newTop = Math.max(10, Math.min(top, maxTop));
            setAdjustedTop(newTop);
        }
    }, [top, item.sub]); // Re-calculate when item changes

    const headerColor = item.activeColor || '#1abc9c';

    return createPortal(
        <div
            ref={menuRef}
            className="fixed z-[250] w-64 bg-slate-800/95 backdrop-blur-sm rounded-xl shadow-2xl border border-slate-700/50 overflow-hidden transition-all duration-200"
            style={{
                top: `${adjustedTop}px`,
                left: '70px', // slightly offset from collapsed sidebar
                animation: 'submenu-slide-in 0.2s cubic-bezier(0.16, 1, 0.3, 1)'
            }}
            onMouseEnter={onMouseEnter}
            onMouseLeave={onMouseLeave}
        >
            {/* Header */}
            <div className="flex items-center justify-between px-4 py-3 bg-slate-900/80 border-b border-slate-700/50">
                <div className="flex items-center gap-2 font-bold text-sm text-white">
                    <FontAwesomeIcon
                        icon={resolveIcon(item.icon)}
                        style={{ color: headerColor }}
                        className="w-4 h-4 opacity-100" // Ensure visible
                    />
                    <span>{item.text}</span>
                </div>
                {/* Close button mostly for mobile or explicit intent, though hover usually handles it */}
                <button
                    onClick={(e) => {
                        e.stopPropagation();
                        onClose();
                    }}
                    className="text-slate-400 hover:text-white transition-colors p-1 rounded-md hover:bg-slate-700"
                >
                    <FontAwesomeIcon icon={faXmark} />
                </button>
            </div>

            {/* Content List */}
            <div className="py-2 max-h-[70vh] overflow-y-auto custom-scrollbar flex flex-col">
                {item.sub?.map((subItem: string | MenuItem, idx: number) => {
                    // Normalize Sub Item
                    let isLeaf = false;
                    let text = '';
                    let path = '';
                    let iconFn = undefined;
                    let activeColor = '#f59e0b';
                    let iconColor = undefined;
                    let subChildren: (string | MenuItem)[] = [];

                    if (typeof subItem === 'string') {
                        isLeaf = true;
                        text = subItem;
                        path = menuPaths[subItem] || '';
                        iconFn = faCircle; // Default fallback for string items
                    } else {
                        const mi = subItem as MenuItem;
                        text = mi.text;
                        iconFn = mi.icon ? resolveIcon(mi.icon) : faCircle; // Default fallback if no icon
                        activeColor = mi.activeColor || '#f59e0b';
                        iconColor = mi.iconColor;

                        if (!mi.sub || mi.sub.length === 0) {
                            isLeaf = true;
                            path = mi.path || menuPaths[text] || '';
                        } else {
                            isLeaf = false;
                            subChildren = mi.sub;
                        }
                    }

                    if (isLeaf) {
                        const active = isActiveCheck(path);
                        const canOpenInNewWindow = Boolean(path);
                        return (
                            <div key={`sub-${idx}`} className="relative group">
                                <button
                                    onClick={() => path && onItemClick(path)}
                                    className={`w-full text-left px-4 py-2.5 text-sm transition-all flex items-center gap-3
                                    ${canOpenInNewWindow ? 'pr-10' : ''}
                                    ${active
                                        ? 'bg-slate-700/50 text-white font-semibold border-l-2'
                                        : 'text-slate-400 hover:bg-slate-700/30 hover:text-slate-200 border-l-2 border-transparent hover:pl-5'
                                    }`}
                                    style={{ borderColor: active ? activeColor : 'transparent' }}
                                >
                                    <FontAwesomeIcon
                                        icon={iconFn}
                                        style={{ color: active ? activeColor : iconColor }}
                                        className={iconFn === faCircle ? "w-1.5 h-1.5 opacity-50" : "w-3 h-3"}
                                    />
                                    <span className={active ? '' : ''}>{text}</span>
                                </button>

                                {canOpenInNewWindow && (
                                    <button
                                        type="button"
                                        className="absolute right-2 top-1/2 -translate-y-1/2 w-6 h-6 rounded text-slate-400 hover:text-white hover:bg-slate-700/60 transition-colors"
                                        title={`${text} 새창 열기`}
                                        aria-label={`${text} 새창 열기`}
                                        onClick={(e) => {
                                            e.preventDefault();
                                            e.stopPropagation();
                                            onOpenInNewWindow(path);
                                        }}
                                    >
                                        <FontAwesomeIcon icon={faUpRightFromSquare} className="w-3 h-3" />
                                    </button>
                                )}
                            </div>
                        );
                    } else {
                        // Render Group (Nested)
                        return (
                            <div key={`group-${idx}`} className="mt-2 mb-1">
                                <div className="px-4 py-1.5 text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
                                    <FontAwesomeIcon
                                        icon={iconFn || faCircle}
                                        className={(iconFn === faCircle || !iconFn) ? "w-1.5 h-1.5 opacity-50" : "w-3 h-3 opacity-70"}
                                    />
                                    {text}
                                </div>
                                <div className="flex flex-col ml-2 border-l border-slate-700/50 space-y-0.5">
                                    {subChildren.map((child: string | MenuItem, cIdx) => {
                                        let cText = '';
                                        let cPath = '';

                                        if (typeof child === 'string') {
                                            cText = child;
                                            cPath = menuPaths[child] || '';
                                        } else {
                                            cText = child.text;
                                            cPath = child.path || menuPaths[cText] || '';
                                        }

                                        const cActive = isActiveCheck(cPath);
                                        const canOpenInNewWindow = Boolean(cPath);
                                        return (
                                            <div key={`child-${cIdx}`} className="relative group">
                                                <button
                                                    onClick={() => cPath && onItemClick(cPath)}
                                                    className={`w-full text-left pl-4 py-2 text-sm transition-all flex items-center
                                                    ${canOpenInNewWindow ? 'pr-10' : 'pr-3'}
                                                    ${cActive
                                                        ? 'text-white font-medium'
                                                        : 'text-slate-400 hover:text-slate-200'
                                                    }`}
                                                >
                                                    <span className={`w-1.5 h-1.5 rounded-full mr-2 transition-colors ${cActive ? 'bg-indigo-500' : 'bg-slate-600 group-hover:bg-slate-500'}`}></span>
                                                    {cText}
                                                </button>

                                                {canOpenInNewWindow && (
                                                    <button
                                                        type="button"
                                                        className="absolute right-2 top-1/2 -translate-y-1/2 w-6 h-6 rounded text-slate-400 hover:text-white hover:bg-slate-700/60 transition-colors"
                                                        title={`${cText} 새창 열기`}
                                                        aria-label={`${cText} 새창 열기`}
                                                        onClick={(e) => {
                                                            e.preventDefault();
                                                            e.stopPropagation();
                                                            onOpenInNewWindow(cPath);
                                                        }}
                                                    >
                                                        <FontAwesomeIcon icon={faUpRightFromSquare} className="w-3 h-3" />
                                                    </button>
                                                )}
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        );
                    }
                })}
            </div>

            <style>{`
                @keyframes submenu-slide-in {
                    from { opacity: 0; transform: translateX(-8px) scale(0.98); }
                    to { opacity: 1; transform: translateX(0) scale(1); }
                }
            `}</style>
        </div>,
        document.body
    );
};

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faBars, faXmark, faChevronDown } from '@fortawesome/free-solid-svg-icons';
import { MenuItem } from '../../types/menu';
import { iconMap } from '../../utils/iconMapper';

interface WebsiteHeaderProps {
    currentSiteData: any;
    menuPaths: { [key: string]: string };
    toggleSidebar: () => void;
}

const WebsiteHeader: React.FC<WebsiteHeaderProps> = ({ currentSiteData, menuPaths, toggleSidebar }) => {
    const navigate = useNavigate();
    const [hoveredMenu, setHoveredMenu] = useState<string | null>(null);
    const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
    const [isLayerMenuOpen, setIsLayerMenuOpen] = useState(false);

    const handleMenuClick = (item: MenuItem) => {
        if (item.path) {
            navigate(item.path);
        } else if (item.text === "메인페이지") {
            navigate('/dashboard');
        }
    };

    const handleSubMenuClick = (subItem: string | MenuItem) => {
        // Logic similar to Sidebar
        if (typeof subItem === 'string') {
            const path = menuPaths[subItem];
            if (path) navigate(path);
        } else {
            if (subItem.path) navigate(subItem.path);
        }
        setHoveredMenu(null);
    };

    return (
        <header className="fixed top-0 left-0 right-0 h-[80px] bg-white/90 backdrop-blur-md border-b border-slate-200 z-[1000] transition-all duration-300">
            <div className="max-w-[1600px] mx-auto h-full px-6 flex items-center justify-between">
                {/* Logo */}
                <div
                    className="flex items-center gap-3 cursor-pointer"
                    onClick={() => navigate('/dashboard')}
                >
                    <div className="w-10 h-10 bg-indigo-600 rounded-lg flex items-center justify-center text-white">
                        <FontAwesomeIcon icon={iconMap[currentSiteData.icon] || iconMap['fa-building']} />
                    </div>
                    <span className="text-xl font-bold text-slate-800 tracking-tight font-display">
                        {currentSiteData.name}
                    </span>
                </div>

                {/* Right Side Tools */}
                <div className="flex items-center gap-6">
                    {/* Desktop Menu (Horizontal) */}
                    <nav className="hidden lg:flex items-center gap-8 h-full">
                        {currentSiteData.menu.map((item: MenuItem, index: number) => (
                            <div
                                key={index}
                                className="relative h-full flex items-center"
                                onMouseEnter={() => setHoveredMenu(item.text)}
                                onMouseLeave={() => setHoveredMenu(null)}
                            >
                                <button
                                    className={`text-base font-bold transition-colors flex items-center gap-2 px-2 py-2
                                        ${hoveredMenu === item.text ? 'text-indigo-600' : 'text-slate-700 hover:text-indigo-600'}
                                    `}
                                    onClick={() => handleMenuClick(item)}
                                >
                                    {item.text}
                                    {item.sub && item.sub.length > 0 && (
                                        <FontAwesomeIcon icon={faChevronDown} className="text-xs opacity-50" />
                                    )}
                                </button>

                                {/* Dropdown Menu */}
                                {item.sub && item.sub.length > 0 && hoveredMenu === item.text && (
                                    <div className="absolute top-[80px] left-1/2 -translate-x-1/2 min-w-[200px] bg-white rounded-b-xl shadow-xl border-t border-indigo-500 py-3 animate-slideDown origin-top z-50">
                                        {item.sub.map((sub: string | MenuItem, idx: number) => {
                                            const text = typeof sub === 'string' ? sub : sub.text;
                                            return (
                                                <button
                                                    key={idx}
                                                    className="w-full text-left px-6 py-2.5 text-sm text-slate-600 hover:bg-slate-50 hover:text-indigo-600 font-medium transition-colors"
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        handleSubMenuClick(sub);
                                                    }}
                                                >
                                                    {text}
                                                </button>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>
                        ))}
                    </nav>

                    {/* All Menu Button (Sidebar Trigger) */}
                    <button
                        className="w-10 h-10 rounded-full bg-slate-100 hover:bg-slate-200 text-slate-700 flex items-center justify-center transition-colors"
                        onClick={toggleSidebar}
                        title="전체메뉴"
                    >
                        <FontAwesomeIcon icon={faBars} className="text-lg" />
                    </button>
                </div>
            </div>

        </header>
    );
};

export default WebsiteHeader;

import React, { useState, useRef } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCloudUploadAlt, faSpinner, faCheck, faTimes, faMoneyCheck, faSearch, faExclamationTriangle } from '@fortawesome/free-solid-svg-icons';
import { geminiService, AnalyzedBankBook } from '../../services/geminiService';
import { Worker } from '../../services/manpowerService';

interface BankBookAnalysisModalProps {
    isOpen: boolean;
    onClose: () => void;
    workers: Worker[]; // Filtered workers from parent
    onUpdateWorkers: (updates: { workerId: string, bankName: string, accountNumber: string, accountHolder: string }[]) => Promise<void>;
}

interface AnalysisResult {
    file: File;
    status: 'idle' | 'analyzing' | 'success' | 'error';
    data?: AnalyzedBankBook;
    matchedWorkerId?: string;
    error?: string;
}

const BankBookAnalysisModal: React.FC<BankBookAnalysisModalProps> = ({ isOpen, onClose, workers, onUpdateWorkers }) => {
    const [results, setResults] = useState<AnalysisResult[]>([]);
    const [isAnalyzing, setIsAnalyzing] = useState(false);
    const [isDragging, setIsDragging] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    if (!isOpen) return null;

    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files) {
            const fileList = Array.from(e.target.files);
            const newFiles = fileList.map(file => ({
                file,
                status: 'idle' as const
            }));
            setResults(prev => [...prev, ...newFiles]);
        }
    };

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);

        if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
            const fileList = Array.from(e.dataTransfer.files);
            const newFiles = fileList.map(file => ({
                file,
                status: 'idle' as const
            }));
            setResults(prev => [...prev, ...newFiles]);
        }
    };

    const runAnalysis = async () => {
        setIsAnalyzing(true);
        const newResults = [...results];

        // Process sequentially to avoid rate limits or overwhelming UI
        for (let i = 0; i < newResults.length; i++) {
            if (newResults[i].status === 'success') continue;

            newResults[i].status = 'analyzing';
            setResults([...newResults]);

            try {
                // 1. AI Analysis
                const data = await geminiService.analyzeBankBook(newResults[i].file);
                newResults[i].data = data;
                newResults[i].status = 'success';

                // 2. Auto-match Worker by Filename
                // Remove extension and trim
                const fileNameNoExt = newResults[i].file.name.replace(/\.[^/.]+$/, "").trim();

                // Find exact match first
                const exactMatch = workers.find(w => w.name === fileNameNoExt);
                if (exactMatch) {
                    newResults[i].matchedWorkerId = exactMatch.id;
                } else {
                    // Try to match by "Account Holder" name from AI if available
                    if (data.accountHolder) {
                        const holderMatch = workers.find(w => w.name === data.accountHolder);
                        if (holderMatch) {
                            newResults[i].matchedWorkerId = holderMatch.id;
                        }
                    }
                }

                // Add delay to prevent rate limiting
                await new Promise(resolve => setTimeout(resolve, 1000));

            } catch (error: any) {
                newResults[i].status = 'error';
                newResults[i].error = error.message || '인식 실패';
            }
            setResults([...newResults]);
        }
        setIsAnalyzing(false);
    };

    const handleWorkerSelect = (index: number, workerId: string) => {
        const newResults = [...results];
        newResults[index].matchedWorkerId = workerId;
        setResults(newResults);
    };

    const handleSave = async () => {
        const validUpdates = results
            .filter(r => r.status === 'success' && r.matchedWorkerId && r.data)
            .map(r => ({
                workerId: r.matchedWorkerId!,
                bankName: r.data!.bankName || '',
                accountNumber: r.data!.accountNumber || '',
                accountHolder: r.data!.accountHolder || ''
            }));

        if (validUpdates.length === 0) {
            alert('저장할 데이터가 없습니다. 매칭된 항목이 있는지 확인해주세요.');
            return;
        }

        if (window.confirm(`${validUpdates.length}명의 계좌정보를 업데이트하시겠습니까?`)) {
            await onUpdateWorkers(validUpdates);
            onClose();
        }
    };

    const handleRemoveResult = (index: number) => {
        setResults(prev => prev.filter((_, i) => i !== index));
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col">
                {/* Header */}
                <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between">
                    <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                        <FontAwesomeIcon icon={faMoneyCheck} className="text-orange-500" />
                        AI 통장사본 자동 인식
                    </h2>
                    <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
                        <FontAwesomeIcon icon={faTimes} size="lg" />
                    </button>
                </div>

                {/* Body */}
                <div className="flex-1 overflow-y-auto p-6 bg-slate-50">
                    <input
                        type="file"
                        ref={fileInputRef}
                        className="hidden"
                        multiple
                        accept="image/*"
                        onChange={handleFileSelect}
                    />
                    {/* Drag & Drop Zone - 파일이 없을 때 표시 */}
                    {results.length === 0 && (
                        <div
                            onClick={() => fileInputRef.current?.click()}
                            onDragOver={handleDragOver}
                            onDragLeave={handleDragLeave}
                            onDrop={handleDrop}
                            className={`border-2 border-dashed rounded-xl p-12 text-center cursor-pointer transition-all
                                ${isDragging
                                    ? 'border-orange-400 bg-orange-50'
                                    : 'border-slate-300 hover:border-orange-300 hover:bg-slate-100'
                                }`}
                        >
                            <FontAwesomeIcon icon={faCloudUploadAlt} className="text-5xl text-slate-400 mb-4" />
                            <p className="text-lg font-medium text-slate-600 mb-2">
                                통장사본 이미지를 드래그하거나 클릭하여 업로드
                            </p>
                            <p className="text-sm text-slate-400">
                                여러 장의 이미지를 한 번에 업로드할 수 있습니다
                            </p>
                        </div>
                    )}

                    {/* Results List */}
                    {results.length > 0 && (
                        <div className="space-y-4">
                            <div className="flex justify-between items-center mb-2">
                                <div className="text-sm text-slate-500">
                                    총 {results.length}장 / 인식 성공 {results.filter(r => r.status === 'success').length}건
                                </div>
                                <div className="flex gap-2">
                                    <button
                                        onClick={() => fileInputRef.current?.click()}
                                        className="px-3 py-1.5 text-sm bg-white border border-slate-200 text-slate-600 rounded-lg hover:bg-slate-50"
                                    >
                                        + 파일 추가
                                    </button>
                                    <button
                                        onClick={runAnalysis}
                                        disabled={isAnalyzing}
                                        className={`px-4 py-1.5 text-sm font-bold text-white rounded-lg flex items-center gap-2 ${isAnalyzing ? 'bg-slate-400 cursor-not-allowed' : 'bg-orange-500 hover:bg-orange-600'
                                            }`}
                                    >
                                        {isAnalyzing ? <><FontAwesomeIcon icon={faSpinner} spin /> 분석 중...</> : 'AI 분석 시작'}
                                    </button>
                                </div>
                            </div>

                            {results.map((result, idx) => (
                                <div key={idx} className="bg-white rounded-lg border border-slate-200 p-4 shadow-sm flex flex-col md:flex-row gap-4 items-start md:items-center">
                                    {/* Image Preview */}
                                    <div className="w-16 h-16 rounded overflow-hidden bg-slate-100 flex-shrink-0 relative group">
                                        <img src={URL.createObjectURL(result.file)} alt="preview" className="w-full h-full object-cover" />
                                        <div className="absolute inset-0 bg-black/40 hidden group-hover:flex items-center justify-center cursor-pointer text-white text-xs" onClick={() => window.open(URL.createObjectURL(result.file), '_blank')}>확대</div>
                                    </div>

                                    {/* Status & File Info */}
                                    <div className="w-40 flex-shrink-0">
                                        <div className="text-xs text-slate-400 mb-1 truncate" title={result.file.name}>{result.file.name}</div>
                                        {result.status === 'idle' && <span className="text-xs text-slate-500 bg-slate-100 px-2 py-1 rounded">대기 중</span>}
                                        {result.status === 'analyzing' && <span className="text-xs text-blue-500 flex items-center gap-1"><FontAwesomeIcon icon={faSpinner} spin /> 분석 중</span>}
                                        {result.status === 'error' && <span className="text-xs text-red-500 flex items-center gap-1"><FontAwesomeIcon icon={faExclamationTriangle} /> {result.error}</span>}
                                        {result.status === 'success' && <span className="text-xs text-green-600 flex items-center gap-1"><FontAwesomeIcon icon={faCheck} /> 인식 완료</span>}
                                    </div>

                                    {/* Recognized Data */}
                                    <div className="flex-1 grid grid-cols-2 lg:grid-cols-3 gap-2">
                                        <div className="flex flex-col">
                                            <span className="text-[10px] text-slate-400">은행명</span>
                                            <input
                                                type="text"
                                                className="border rounded px-2 py-1 text-sm bg-slate-50"
                                                value={result.data?.bankName || ''}
                                                readOnly
                                                placeholder="-"
                                            />
                                        </div>
                                        <div className="flex flex-col">
                                            <span className="text-[10px] text-slate-400">계좌번호</span>
                                            <input
                                                type="text"
                                                className="border rounded px-2 py-1 text-sm bg-slate-50"
                                                value={result.data?.accountNumber || ''}
                                                readOnly
                                                placeholder="-"
                                            />
                                        </div>
                                        <div className="flex flex-col">
                                            <span className="text-[10px] text-slate-400">예금주</span>
                                            <input
                                                type="text"
                                                className="border rounded px-2 py-1 text-sm bg-slate-50"
                                                value={result.data?.accountHolder || ''}
                                                readOnly
                                                placeholder="-"
                                            />
                                        </div>
                                    </div>

                                    {/* Worker Matching */}
                                    <div className="w-full md:w-48 flex-shrink-0">
                                        <span className="text-[10px] text-slate-400 block mb-1">매칭 대상 (목록 내 검색)</span>
                                        <select
                                            className={`w-full border rounded px-2 py-1.5 text-sm ${result.matchedWorkerId ? 'border-green-300 bg-green-50 text-green-800 font-bold' : 'border-red-300 bg-red-50 text-red-800'}`}
                                            value={result.matchedWorkerId || ''}
                                            onChange={(e) => handleWorkerSelect(idx, e.target.value)}
                                        >
                                            <option value="">대상 선택 필요</option>
                                            {workers.map(w => (
                                                <option key={w.id} value={w.id!}>{w.name} ({w.teamName || '미배정'})</option>
                                            ))}
                                        </select>
                                    </div>

                                    <button onClick={() => handleRemoveResult(idx)} className="text-slate-300 hover:text-red-500">
                                        <FontAwesomeIcon icon={faTimes} />
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="px-6 py-4 border-t border-slate-100 flex justify-end gap-3 bg-white">
                    <button onClick={onClose} className="px-4 py-2 text-slate-500 hover:bg-slate-100 rounded-lg transition-colors">
                        취소
                    </button>
                    <button
                        onClick={handleSave}
                        className="px-6 py-2 bg-orange-600 text-white font-bold rounded-lg hover:bg-orange-700 transition-colors shadow-lg shadow-orange-200"
                    >
                        적용하기
                    </button>
                </div>
            </div>
        </div >
    );
};

export default BankBookAnalysisModal;

import React, { useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faTimes, faSave, faCheck } from '@fortawesome/free-solid-svg-icons';
import { confirm } from '../../utils/swal';
import { Team } from '../../services/teamService';
import { Worker } from '../../services/manpowerService';
import { Site } from '../../services/siteService';
import { Company } from '../../services/companyService';
import { Position } from '../../services/positionService';

interface BulkEditWorkerModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSave: (updates: Partial<Worker>) => Promise<void>;
    selectedCount: number;
    teams: Team[];
    sites: Site[];
    companies: Company[];
    positions: Position[]; // 직책 데이터 추가
}

const BulkEditWorkerModal: React.FC<BulkEditWorkerModalProps> = ({ isOpen, onClose, onSave, selectedCount, teams, sites, companies, positions }) => {
    const [updates, setUpdates] = useState<Partial<Worker>>({});
    const [selectedFields, setSelectedFields] = useState<string[]>([]);
    const [loading, setLoading] = useState(false);

    if (!isOpen) return null;

    const handleFieldToggle = (field: string) => {
        if (selectedFields.includes(field)) {
            setSelectedFields(selectedFields.filter(f => f !== field));
            const newUpdates = { ...updates };
            delete newUpdates[field as keyof Worker];
            if (field === 'teamId') delete newUpdates.teamName;
            if (field === 'siteId') delete newUpdates.siteName;
            if (field === 'companyId') delete newUpdates.companyName;
            setUpdates(newUpdates);
        } else {
            setSelectedFields([...selectedFields, field]);

            // Set default value immediately when checked to prevent undefined error
            let defaultValue: any = '';
            switch (field) {
                case 'status': defaultValue = 'active'; break;
                case 'role': defaultValue = '일반'; break;
                case 'payType': defaultValue = '일급제'; break;
                case 'unitPrice': defaultValue = 0; break;
                case 'teamId':
                case 'siteId':
                case 'companyId': defaultValue = ''; break;
                default: defaultValue = '';
            }

            // Preserve existing value if for some reason it exists (though usually deleted on toggle off)
            setUpdates(prev => ({
                ...prev,
                [field]: (prev as any)[field] !== undefined ? (prev as any)[field] : defaultValue
            }));
        }
    };

    const handleChange = (field: keyof Worker, value: any) => {
        setUpdates(prev => ({ ...prev, [field]: value }));
    };

    const handleSave = async () => {
        if (selectedFields.length === 0) {
            alert('수정할 항목을 하나 이상 선택해주세요.');
            return;
        }

        const result = await confirm.batch('작업자', selectedCount);
        if (!result.isConfirmed) return;

        setLoading(true);
        try {
            // Only send updates for selected fields
            const finalUpdates: Partial<Worker> = {};
            selectedFields.forEach(field => {
                (finalUpdates as any)[field] = (updates as any)[field];
            });

            // If team is selected, also update teamName
            if (selectedFields.includes('teamId') && updates.teamId) {
                const team = teams.find(t => t.id === updates.teamId);
                if (team) {
                    finalUpdates.teamName = team.name;
                }
            }

            // If site is selected, also update siteName
            if (selectedFields.includes('siteId') && updates.siteId) {
                const site = sites.find(s => s.id === updates.siteId);
                if (site) {
                    finalUpdates.siteName = site.name;
                }
            }

            // If company is selected, also update companyName
            if (selectedFields.includes('companyId') && updates.companyId) {
                const company = companies.find(c => c.id === updates.companyId);
                if (company) {
                    finalUpdates.companyName = company.name;
                }
            }

            await onSave(finalUpdates);
            onClose();
        } catch (error) {
            console.error("Bulk update failed:", error);
            alert("일괄 수정 중 오류가 발생했습니다.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white rounded-lg shadow-xl w-full max-w-md mx-4 max-h-[90vh] overflow-y-auto">
                <div className="flex justify-between items-center p-4 border-b border-gray-200 sticky top-0 bg-white z-10">
                    <h3 className="text-lg font-bold text-gray-800">
                        작업자 일괄 수정 ({selectedCount}명)
                    </h3>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
                        <FontAwesomeIcon icon={faTimes} />
                    </button>
                </div>

                <div className="p-6 space-y-4">
                    <p className="text-sm text-gray-500 mb-4">
                        수정할 항목을 체크하고 새로운 값을 입력하세요.
                    </p>

                    {/* Team */}
                    <div className="flex items-center gap-3">
                        <input
                            type="checkbox"
                            id="chk-team"
                            checked={selectedFields.includes('teamId')}
                            onChange={() => handleFieldToggle('teamId')}
                            className="w-4 h-4 text-blue-600 rounded border-gray-300"
                        />
                        <label htmlFor="chk-team" className="w-20 text-sm font-medium text-gray-700">소속 팀</label>
                        <select
                            className="flex-1 border border-gray-300 rounded px-3 py-2 text-sm disabled:bg-gray-100 disabled:text-gray-400"
                            disabled={!selectedFields.includes('teamId')}
                            value={updates.teamId || ''}
                            onChange={(e) => handleChange('teamId', e.target.value)}
                        >
                            <option value="">팀 선택</option>
                            {teams.map(team => (
                                <option key={team.id} value={team.id}>{team.name}</option>
                            ))}
                        </select>
                    </div>

                    {/* Site */}
                    <div className="flex items-center gap-3">
                        <input
                            type="checkbox"
                            id="chk-site"
                            checked={selectedFields.includes('siteId')}
                            onChange={() => handleFieldToggle('siteId')}
                            className="w-4 h-4 text-blue-600 rounded border-gray-300"
                        />
                        <label htmlFor="chk-site" className="w-20 text-sm font-medium text-gray-700">현장</label>
                        <select
                            className="flex-1 border border-gray-300 rounded px-3 py-2 text-sm disabled:bg-gray-100 disabled:text-gray-400"
                            disabled={!selectedFields.includes('siteId')}
                            value={updates.siteId || ''}
                            onChange={(e) => handleChange('siteId', e.target.value)}
                        >
                            <option value="">현장 선택</option>
                            {sites.map(site => (
                                <option key={site.id} value={site.id}>{site.name}</option>
                            ))}
                        </select>
                    </div>

                    {/* Company */}
                    <div className="flex items-center gap-3">
                        <input
                            type="checkbox"
                            id="chk-company"
                            checked={selectedFields.includes('companyId')}
                            onChange={() => handleFieldToggle('companyId')}
                            className="w-4 h-4 text-blue-600 rounded border-gray-300"
                        />
                        <label htmlFor="chk-company" className="w-20 text-sm font-medium text-gray-700">소속 회사</label>
                        <select
                            className="flex-1 border border-gray-300 rounded px-3 py-2 text-sm disabled:bg-gray-100 disabled:text-gray-400"
                            disabled={!selectedFields.includes('companyId')}
                            value={updates.companyId || ''}
                            onChange={(e) => handleChange('companyId', e.target.value)}
                        >
                            <option value="">회사 선택</option>
                            {companies.map(company => (
                                <option key={company.id} value={company.id}>{company.name}</option>
                            ))}
                        </select>
                    </div>

                    {/* Role */}
                    <div className="flex items-center gap-3">
                        <input
                            type="checkbox"
                            id="chk-role"
                            checked={selectedFields.includes('role')}
                            onChange={() => handleFieldToggle('role')}
                            className="w-4 h-4 text-blue-600 rounded border-gray-300"
                        />
                        <label htmlFor="chk-role" className="w-20 text-sm font-medium text-gray-700">직책</label>
                        <select
                            className="flex-1 border border-gray-300 rounded px-3 py-2 text-sm disabled:bg-gray-100 disabled:text-gray-400"
                            disabled={!selectedFields.includes('role')}
                            value={updates.role || '일반'}
                            onChange={(e) => handleChange('role', e.target.value)}
                        >
                            {positions.length > 0 ? (
                                positions.map(pos => (
                                    <option key={pos.id} value={pos.name}>{pos.name}</option>
                                ))
                            ) : (
                                <>
                                    <option value="작업자">작업자</option>
                                    <option value="팀장">팀장</option>
                                    <option value="관리자">관리자</option>
                                </>
                            )}
                        </select>
                    </div>

                    {/* PayType */}
                    <div className="flex items-center gap-3">
                        <input
                            type="checkbox"
                            id="chk-payType"
                            checked={selectedFields.includes('payType')}
                            onChange={() => handleFieldToggle('payType')}
                            className="w-4 h-4 text-blue-600 rounded border-gray-300"
                        />
                        <label htmlFor="chk-payType" className="w-20 text-sm font-medium text-gray-700">급여방식</label>
                        <select
                            className="flex-1 border border-gray-300 rounded px-3 py-2 text-sm disabled:bg-gray-100 disabled:text-gray-400"
                            disabled={!selectedFields.includes('payType')}
                            value={updates.payType || '일급제'}
                            onChange={(e) => handleChange('payType', e.target.value)}
                        >
                            <option value="일급제">일급제</option>
                            <option value="주급제">주급제</option>
                            <option value="월급제">월급제</option>
                            <option value="지원팀">지원팀</option>
                            <option value="용역팀">용역팀</option>
                            <option value="가지급">가지급</option>
                        </select>
                    </div>

                    {/* Status */}
                    <div className="flex items-center gap-3">
                        <input
                            type="checkbox"
                            id="chk-status"
                            checked={selectedFields.includes('status')}
                            onChange={() => handleFieldToggle('status')}
                            className="w-4 h-4 text-blue-600 rounded border-gray-300"
                        />
                        <label htmlFor="chk-status" className="w-20 text-sm font-medium text-gray-700">상태</label>
                        <select
                            className="flex-1 border border-gray-300 rounded px-3 py-2 text-sm disabled:bg-gray-100 disabled:text-gray-400"
                            disabled={!selectedFields.includes('status')}
                            value={updates.status || 'active'}
                            onChange={(e) => handleChange('status', e.target.value)}
                        >
                            <option value="active">재직 (Active)</option>
                            <option value="inactive">퇴사 (Inactive)</option>
                            <option value="temporary">일용직</option>
                        </select>
                    </div>

                    {/* Unit Price */}
                    <div className="flex items-center gap-3">
                        <input
                            type="checkbox"
                            id="chk-unitPrice"
                            checked={selectedFields.includes('unitPrice')}
                            onChange={() => handleFieldToggle('unitPrice')}
                            className="w-4 h-4 text-blue-600 rounded border-gray-300"
                        />
                        <label htmlFor="chk-unitPrice" className="w-20 text-sm font-medium text-gray-700">단가</label>
                        <input
                            type="number"
                            className="flex-1 border border-gray-300 rounded px-3 py-2 text-sm disabled:bg-gray-100 disabled:text-gray-400"
                            disabled={!selectedFields.includes('unitPrice')}
                            value={updates.unitPrice || 0}
                            onChange={(e) => handleChange('unitPrice', parseInt(e.target.value))}
                        />
                    </div>
                </div>

                <div className="p-4 border-t border-gray-200 flex justify-end gap-2 sticky bottom-0 bg-white">
                    <button
                        onClick={onClose}
                        className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg text-sm font-medium"
                    >
                        취소
                    </button>
                    <button
                        onClick={handleSave}
                        disabled={loading || selectedFields.length === 0}
                        className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm font-medium flex items-center gap-2 disabled:opacity-50"
                    >
                        {loading ? '저장 중...' : (
                            <>
                                <FontAwesomeIcon icon={faCheck} />
                                일괄 적용
                            </>
                        )}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default BulkEditWorkerModal;

import React, { useState, useRef } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faCloudUploadAlt, faSpinner, faCheck, faTimes, faIdCard,
    faExclamationTriangle, faPlus, faSync, faUserPlus, faEdit
} from '@fortawesome/free-solid-svg-icons';
import { geminiService, AnalyzedIdCard } from '../../services/geminiService';
import { Worker } from '../../services/manpowerService';

interface IdCardAnalysisModalProps {
    isOpen: boolean;
    onClose: () => void;
    existingWorkers: Worker[];
    onAddWorkers: (newWorkers: {
        name: string,
        idNumber: string,
        address: string,
        file: File,
        matchType: 'new' | 'update' | 'duplicate',
        matchedWorkerId?: string
    }[]) => Promise<void>;
}

// 주민번호 정규화 함수
const normalizeIdNumber = (id: string): string => {
    if (!id) return '';
    return id.replace(/[-\s]/g, '').trim();
};

// 주민번호 비교 함수
const isSameIdNumber = (a: string, b: string): boolean => {
    const normA = normalizeIdNumber(a);
    const normB = normalizeIdNumber(b);
    if (!normA || !normB || normA.length < 6 || normB.length < 6) return false;
    return normA === normB;
};

interface AnalysisResult {
    file: File;
    status: 'idle' | 'analyzing' | 'success' | 'error';
    data?: AnalyzedIdCard;
    error?: string;
    // 개선된 매칭 정보
    matchType: 'new' | 'update' | 'duplicate' | 'pending';
    matchedWorker?: Worker;
    changes?: {
        name: boolean;
        idNumber: boolean;
        address: boolean;
        photo: boolean;
    };
}

const IdCardAnalysisModal: React.FC<IdCardAnalysisModalProps> = ({ isOpen, onClose, existingWorkers, onAddWorkers }) => {
    const [results, setResults] = useState<AnalysisResult[]>([]);
    const [isAnalyzing, setIsAnalyzing] = useState(false);
    const [isDragging, setIsDragging] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    if (!isOpen) return null;

    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files) {
            const newFiles = Array.from(e.target.files).map(file => ({
                file,
                status: 'idle' as const,
                matchType: 'pending' as const
            }));
            setResults(prev => [...prev, ...newFiles]);
        }
    };

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);

        if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
            const newFiles = Array.from(e.dataTransfer.files).map(file => ({
                file,
                status: 'idle' as const,
                matchType: 'pending' as const
            }));
            setResults(prev => [...prev, ...newFiles]);
        }
    };

    // 기존 작업자와 매칭 로직
    const matchWithExistingWorkers = (data: AnalyzedIdCard): {
        matchType: 'new' | 'update' | 'duplicate';
        matchedWorker?: Worker;
        changes?: { name: boolean; idNumber: boolean; address: boolean; photo: boolean };
    } => {
        if (!data.idNumber && !data.name) {
            return { matchType: 'new' };
        }

        // 1. 주민번호로 정확 매칭 시도
        const idMatch = existingWorkers.find(w => isSameIdNumber(w.idNumber || '', data.idNumber || ''));

        if (idMatch) {
            // 기존 작업자 발견 - 채울 필드 확인
            const changes = {
                name: !idMatch.name && !!data.name,
                idNumber: !idMatch.idNumber && !!data.idNumber,
                address: !idMatch.address && !!data.address,
                photo: !idMatch.fileNameSaved // 사진 없으면 업데이트
            };

            const hasChanges = changes.name || changes.address || changes.photo;

            if (hasChanges) {
                return { matchType: 'update', matchedWorker: idMatch, changes };
            } else {
                return { matchType: 'duplicate', matchedWorker: idMatch, changes };
            }
        }

        // 2. 이름으로만 매칭 시도 (경고용)
        const nameMatch = existingWorkers.find(w =>
            w.name && data.name && w.name.trim() === data.name.trim()
        );

        if (nameMatch) {
            // 이름만 같음 - 주민번호가 다르면 다른 사람일 수 있음
            // 일단 신규로 처리하되 경고 표시
            return { matchType: 'new', matchedWorker: nameMatch };
        }

        // 3. 매칭 없음 - 신규 작업자
        return { matchType: 'new' };
    };

    // AI 분석 + 재시도 로직
    const analyzeWithRetry = async (file: File, retries = 2): Promise<AnalyzedIdCard> => {
        for (let i = 0; i <= retries; i++) {
            try {
                return await geminiService.analyzeImage(file);
            } catch (e: any) {
                if (i === retries || !e.message?.includes('429')) throw e;
                await new Promise(r => setTimeout(r, 3000 * (i + 1)));
            }
        }
        throw new Error('분석 실패');
    };

    const runAnalysis = async () => {
        const apiKey = geminiService.getKey();
        if (!apiKey) {
            alert('API 키가 설정되지 않았습니다. /settings/ai 에서 Gemini API 키를 등록해주세요.');
            return;
        }

        setIsAnalyzing(true);
        const newResults = [...results];

        for (let i = 0; i < newResults.length; i++) {
            if (newResults[i].status === 'success') continue;

            newResults[i].status = 'analyzing';
            setResults([...newResults]);

            try {
                // AI 분석 (재시도 포함)
                const data = await analyzeWithRetry(newResults[i].file);

                newResults[i].data = {
                    name: data.name || '',
                    idNumber: data.idNumber || '',
                    address: data.address || ''
                };
                newResults[i].status = 'success';

                // 기존 작업자 매칭
                const matchResult = matchWithExistingWorkers(newResults[i].data!);
                newResults[i].matchType = matchResult.matchType;
                newResults[i].matchedWorker = matchResult.matchedWorker;
                newResults[i].changes = matchResult.changes;

                // Rate limit 방지 지연
                await new Promise(resolve => setTimeout(resolve, 2000));

            } catch (error: any) {
                newResults[i].status = 'error';
                const message = error?.message || '인식 실패';
                if (/API Key Missing|API key not valid|403|PERMISSION_DENIED|referer|blocked/i.test(message)) {
                    newResults[i].error = `${message} (/settings/ai 확인)`;
                } else {
                    newResults[i].error = message;
                }
                newResults[i].matchType = 'pending';
            }
            setResults([...newResults]);
        }
        setIsAnalyzing(false);
    };

    const handleDataChange = (index: number, field: keyof AnalyzedIdCard, value: string) => {
        const newResults = [...results];
        if (newResults[index].data) {
            newResults[index].data![field] = value;

            // 데이터 변경 시 매칭 재계산
            const matchResult = matchWithExistingWorkers(newResults[index].data!);
            newResults[index].matchType = matchResult.matchType;
            newResults[index].matchedWorker = matchResult.matchedWorker;
            newResults[index].changes = matchResult.changes;
        }
        setResults(newResults);
    };

    const handleSave = async () => {
        const validItems = results
            .filter(r => r.status === 'success' && r.data && r.matchType !== 'pending')
            .map(r => ({
                name: r.data!.name || '',
                idNumber: r.data!.idNumber || '',
                address: r.data!.address || '',
                file: r.file,
                matchType: r.matchType as 'new' | 'update' | 'duplicate',
                matchedWorkerId: r.matchedWorker?.id
            }));

        if (validItems.length === 0) {
            alert('저장할 데이터가 없습니다.');
            return;
        }

        const newCount = validItems.filter(i => i.matchType === 'new').length;
        const updateCount = validItems.filter(i => i.matchType === 'update').length;
        const dupCount = validItems.filter(i => i.matchType === 'duplicate').length;

        const message = [
            newCount > 0 ? `신규 ${newCount}명` : '',
            updateCount > 0 ? `업데이트 ${updateCount}명` : '',
            dupCount > 0 ? `중복(사진만) ${dupCount}명` : ''
        ].filter(Boolean).join(', ');

        if (!window.confirm(`${message}을 처리하시겠습니까?`)) {
            return;
        }

        await onAddWorkers(validItems);
        onClose();
    };

    const handleRemoveResult = (index: number) => {
        setResults(prev => prev.filter((_, i) => i !== index));
    };

    // 매칭 타입별 UI 정보
    const getMatchTypeInfo = (matchType: string, matchedWorker?: Worker) => {
        switch (matchType) {
            case 'new':
                return {
                    icon: faUserPlus,
                    label: '신규 등록',
                    color: 'text-green-600',
                    bgColor: 'bg-green-50',
                    borderColor: 'border-green-200'
                };
            case 'update':
                return {
                    icon: faEdit,
                    label: `업데이트: ${matchedWorker?.name || ''}`,
                    color: 'text-blue-600',
                    bgColor: 'bg-blue-50',
                    borderColor: 'border-blue-200'
                };
            case 'duplicate':
                return {
                    icon: faSync,
                    label: `사진만 업데이트: ${matchedWorker?.name || ''}`,
                    color: 'text-amber-600',
                    bgColor: 'bg-amber-50',
                    borderColor: 'border-amber-200'
                };
            default:
                return {
                    icon: faExclamationTriangle,
                    label: '대기 중',
                    color: 'text-slate-500',
                    bgColor: 'bg-slate-50',
                    borderColor: 'border-slate-200'
                };
        }
    };

    // 통계
    const stats = {
        total: results.length,
        success: results.filter(r => r.status === 'success').length,
        new: results.filter(r => r.matchType === 'new' && r.status === 'success').length,
        update: results.filter(r => r.matchType === 'update').length,
        duplicate: results.filter(r => r.matchType === 'duplicate').length,
        error: results.filter(r => r.status === 'error').length
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col">
                {/* Header */}
                <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between">
                    <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                        <FontAwesomeIcon icon={faIdCard} className="text-indigo-600" />
                        AI 신분증 자동 인식 (미리보기)
                    </h2>
                    <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
                        <FontAwesomeIcon icon={faTimes} size="lg" />
                    </button>
                </div>

                {/* Body */}
                <div className="flex-1 overflow-y-auto p-6 bg-slate-50">

                    {/* Upload Section */}
                    {results.length === 0 && (
                        <div
                            onClick={() => fileInputRef.current?.click()}
                            onDragOver={handleDragOver}
                            onDragLeave={handleDragLeave}
                            onDrop={handleDrop}
                            className={`border-2 border-dashed rounded-xl p-12 text-center transition-all cursor-pointer group ${isDragging
                                ? 'border-indigo-500 bg-indigo-50 ring-4 ring-indigo-100'
                                : 'border-slate-300 hover:border-indigo-400 hover:bg-indigo-50'
                                }`}
                        >
                            <div className="w-16 h-16 bg-indigo-100 text-indigo-500 rounded-full flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                                <FontAwesomeIcon icon={faCloudUploadAlt} size="2x" />
                            </div>
                            <h3 className="text-lg font-bold text-slate-700 mb-2">
                                {isDragging ? '파일을 여기에 놓으세요' : '신분증 이미지를 업로드하세요'}
                            </h3>
                            <p className="text-slate-500 text-sm">클릭하거나 파일을 드래그하여 업로드 (여러 장 가능)</p>
                            <p className="text-slate-400 text-xs mt-2">* 이름, 주민번호, 주소가 자동으로 인식됩니다.</p>
                            <p className="text-indigo-500 text-xs mt-1">* 기존 작업자는 자동 매칭되어 정보가 업데이트됩니다.</p>
                        </div>
                    )}

                    <input
                        type="file"
                        ref={fileInputRef}
                        className="hidden"
                        multiple
                        accept="image/*"
                        onChange={handleFileSelect}
                    />

                    {/* Results List */}
                    {results.length > 0 && (
                        <div className="space-y-4">
                            {/* 통계 및 버튼 */}
                            <div className="flex justify-between items-center mb-2 flex-wrap gap-2">
                                <div className="flex gap-3 text-sm">
                                    <span className="text-slate-500">총 {stats.total}장</span>
                                    {stats.success > 0 && (
                                        <>
                                            <span className="text-green-600">🆕 신규 {stats.new}</span>
                                            <span className="text-blue-600">🔄 업데이트 {stats.update}</span>
                                            <span className="text-amber-600">⚠️ 중복 {stats.duplicate}</span>
                                        </>
                                    )}
                                    {stats.error > 0 && <span className="text-red-600">❌ 실패 {stats.error}</span>}
                                </div>
                                <div className="flex gap-2">
                                    <button
                                        onClick={() => fileInputRef.current?.click()}
                                        className="px-3 py-1.5 text-sm bg-white border border-slate-200 text-slate-600 rounded-lg hover:bg-slate-50"
                                    >
                                        + 파일 추가
                                    </button>
                                    <button
                                        onClick={runAnalysis}
                                        disabled={isAnalyzing}
                                        className={`px-4 py-1.5 text-sm font-bold text-white rounded-lg flex items-center gap-2 ${isAnalyzing ? 'bg-slate-400 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700'
                                            }`}
                                    >
                                        {isAnalyzing ? <><FontAwesomeIcon icon={faSpinner} spin /> 분석 중...</> : 'AI 분석 시작'}
                                    </button>
                                </div>
                            </div>

                            {results.map((result, idx) => {
                                const matchInfo = getMatchTypeInfo(result.matchType, result.matchedWorker);

                                return (
                                    <div key={idx} className={`bg-white rounded-lg border p-4 shadow-sm flex flex-col md:flex-row gap-4 items-start md:items-center ${matchInfo.borderColor}`}>
                                        {/* Image Preview */}
                                        <div className="w-20 h-20 rounded overflow-hidden bg-slate-100 flex-shrink-0 relative group">
                                            <img src={URL.createObjectURL(result.file)} alt="preview" className="w-full h-full object-cover" />
                                            <div className="absolute inset-0 bg-black/40 hidden group-hover:flex items-center justify-center cursor-pointer text-white text-xs" onClick={() => window.open(URL.createObjectURL(result.file), '_blank')}>확대</div>
                                        </div>

                                        {/* Status & Match Type */}
                                        <div className="w-36 flex-shrink-0">
                                            <div className="text-xs text-slate-400 mb-1 truncate" title={result.file.name}>{result.file.name}</div>
                                            {result.status === 'idle' && <span className="text-xs text-slate-500 bg-slate-100 px-2 py-1 rounded">대기 중</span>}
                                            {result.status === 'analyzing' && <span className="text-xs text-blue-500 flex items-center gap-1"><FontAwesomeIcon icon={faSpinner} spin /> 분석 중</span>}
                                            {result.status === 'error' && <span className="text-xs text-red-500 flex items-center gap-1"><FontAwesomeIcon icon={faExclamationTriangle} /> {result.error}</span>}
                                            {result.status === 'success' && (
                                                <span className={`text-xs ${matchInfo.color} flex items-center gap-1 font-medium`}>
                                                    <FontAwesomeIcon icon={matchInfo.icon} />
                                                    {result.matchType === 'new' ? '신규 등록' :
                                                        result.matchType === 'update' ? '정보 업데이트' :
                                                            result.matchType === 'duplicate' ? '사진만 업데이트' : '대기'}
                                                </span>
                                            )}
                                            {result.matchedWorker && result.matchType !== 'new' && (
                                                <div className="text-[10px] text-slate-400 mt-0.5">
                                                    → {result.matchedWorker.name}
                                                </div>
                                            )}
                                        </div>

                                        {/* Recognized Data */}
                                        <div className="flex-1 grid grid-cols-1 md:grid-cols-3 gap-2 w-full">
                                            <div>
                                                <label className="block text-[10px] text-slate-400 mb-0.5">
                                                    이름 {result.changes?.name && <span className="text-blue-500">(채움)</span>}
                                                </label>
                                                <input
                                                    type="text"
                                                    className="w-full border rounded px-2 py-1.5 text-sm focus:ring-indigo-500 focus:border-indigo-500"
                                                    value={result.data?.name || ''}
                                                    onChange={(e) => handleDataChange(idx, 'name', e.target.value)}
                                                    placeholder="이름"
                                                />
                                            </div>
                                            <div>
                                                <label className="block text-[10px] text-slate-400 mb-0.5">
                                                    주민번호 {result.changes?.idNumber && <span className="text-blue-500">(채움)</span>}
                                                </label>
                                                <input
                                                    type="text"
                                                    className="w-full border rounded px-2 py-1.5 text-sm focus:ring-indigo-500 focus:border-indigo-500"
                                                    value={result.data?.idNumber || ''}
                                                    onChange={(e) => handleDataChange(idx, 'idNumber', e.target.value)}
                                                    placeholder="000000-0000000"
                                                />
                                            </div>
                                            <div>
                                                <label className="block text-[10px] text-slate-400 mb-0.5">
                                                    주소 {result.changes?.address && <span className="text-blue-500">(채움)</span>}
                                                </label>
                                                <input
                                                    type="text"
                                                    className="w-full border rounded px-2 py-1.5 text-sm focus:ring-indigo-500 focus:border-indigo-500"
                                                    value={result.data?.address || ''}
                                                    onChange={(e) => handleDataChange(idx, 'address', e.target.value)}
                                                    placeholder="주소"
                                                />
                                            </div>
                                        </div>

                                        <button onClick={() => handleRemoveResult(idx)} className="text-slate-300 hover:text-red-500 p-2">
                                            <FontAwesomeIcon icon={faTimes} />
                                        </button>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="px-6 py-4 border-t border-slate-100 flex justify-between items-center bg-white">
                    <div className="text-xs text-slate-400">
                        🆕 신규: 새 작업자 생성 | 🔄 업데이트: 기존 작업자 정보 보충 | ⚠️ 중복: 사진만 업데이트
                    </div>
                    <div className="flex gap-3">
                        <button onClick={onClose} className="px-4 py-2 text-slate-500 hover:bg-slate-100 rounded-lg transition-colors">
                            취소
                        </button>
                        <button
                            onClick={handleSave}
                            disabled={stats.success === 0}
                            className={`px-6 py-2 font-bold rounded-lg transition-colors shadow-lg flex items-center gap-2 ${stats.success === 0
                                    ? 'bg-slate-300 text-slate-500 cursor-not-allowed'
                                    : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-200'
                                }`}
                        >
                            <FontAwesomeIcon icon={faPlus} />
                            일괄 처리하기 ({stats.success}건)
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default IdCardAnalysisModal;

import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { 
    faHardHat, faChevronDown, faChevronRight, faSearch, 
    faCheck, faExclamationTriangle, faProjectDiagram, faBuilding, faUser 
} from '@fortawesome/free-solid-svg-icons';
import { siteService, Site } from '../../services/siteService';
import { manpowerService } from '../../services/manpowerService';
import { Team } from '../../services/teamService';
import { Company, companyService } from '../../services/companyService';

interface SiteFormProps {
    initialData?: Partial<Site>;
    teams: Team[];
    companies: Company[];
    onSave: () => void;
    onCancel: () => void;
}

const SiteForm: React.FC<SiteFormProps> = ({ initialData, teams, companies, onSave, onCancel }) => {
    const [currentSite, setCurrentSite] = useState<Partial<Site>>(initialData || { status: 'active' });
    const [companyOptions, setCompanyOptions] = useState<Company[]>(companies);

    const [isCompanyTouched, setIsCompanyTouched] = useState(false);
    const [isPartnerTouched, setIsPartnerTouched] = useState(false);
    const [, setIsClientTouched] = useState(false);

    const [isClientCompanyTouched, setIsClientCompanyTouched] = useState(false);
    const [showInlinePartnerForm, setShowInlinePartnerForm] = useState(false);
    const [isPartnerSaving, setIsPartnerSaving] = useState(false);
    const [partnerDraft, setPartnerDraft] = useState({
        name: '',
        code: '',
        ceoName: '',
        phone: '',
        address: ''
    });

    const CREATE_PARTNER_VALUE = '__CREATE_PARTNER__';

    useEffect(() => {
        setCompanyOptions(companies);
    }, [companies]);

    const companyUuidByAnyId = useMemo(() => {
        const map = new Map<string, string>();
        companyOptions.forEach(c => {
            if (c.id) map.set(String(c.id), String(c.id));
            if (c.legacyId) map.set(String(c.legacyId), String(c.id));
        });
        return map;
    }, [companyOptions]);

    const filteredTeams = useMemo(() => {
        const rawPartnerId = currentSite.partnerId ? String(currentSite.partnerId).trim() : '';
        const rawCompanyId = currentSite.companyId ? String(currentSite.companyId).trim() : '';

        const targetCompanyIdRaw = rawPartnerId || rawCompanyId;
        const targetCompanyId = targetCompanyIdRaw ? (companyUuidByAnyId.get(targetCompanyIdRaw) ?? targetCompanyIdRaw) : '';
        if (!targetCompanyId) return teams;

        return teams.filter(t => {
            const teamCompanyIdRaw = t.companyId ? String(t.companyId).trim() : '';
            if (!teamCompanyIdRaw) return false;
            const teamCompanyId = companyUuidByAnyId.get(teamCompanyIdRaw) ?? teamCompanyIdRaw;
            return teamCompanyId === targetCompanyId;
        });
    }, [teams, currentSite.partnerId, currentSite.companyId, companyUuidByAnyId]);

    useEffect(() => {
        const teamId = currentSite.responsibleTeamId ? String(currentSite.responsibleTeamId).trim() : '';
        if (!teamId) return;

        const rawPartnerId = currentSite.partnerId ? String(currentSite.partnerId).trim() : '';
        const rawCompanyId = currentSite.companyId ? String(currentSite.companyId).trim() : '';
        const hasCompanyConstraint = rawPartnerId.length > 0 || rawCompanyId.length > 0;
        if (!hasCompanyConstraint) return;

        const isValid = filteredTeams.some(t => t.id === teamId);
        if (isValid) return;

        setCurrentSite(prev => ({
            ...prev,
            responsibleTeamId: ''
        }));
    }, [currentSite.responsibleTeamId, currentSite.partnerId, currentSite.companyId, filteredTeams]);

    useEffect(() => {
        if (!companyOptions || companyOptions.length === 0) return;

        const normalizeCompanyId = (raw: unknown): string | undefined => {
            if (raw === undefined) return undefined;
            if (raw === null) return '';
            const v = String(raw);
            if (!v) return '';
            const found = companyOptions.find(c => c.id === v || c.legacyId === v);
            if (found?.id && found.id !== v) return found.id;
            return v;
        };

        setCurrentSite(prev => {
            const nextCompanyId = normalizeCompanyId(prev.companyId);
            const nextPartnerId = normalizeCompanyId((prev as any).partnerId);
            const nextClientCompanyId = normalizeCompanyId((prev as any).clientCompanyId);

            if (
                nextCompanyId === prev.companyId &&
                nextPartnerId === (prev as any).partnerId &&
                nextClientCompanyId === (prev as any).clientCompanyId
            ) {
                return prev;
            }

            return {
                ...prev,
                companyId: nextCompanyId as any,
                partnerId: nextPartnerId as any,
                clientCompanyId: nextClientCompanyId as any
            };
        });
    }, [companyOptions]);

    // Auto-select company based on team selection
    useEffect(() => {
        if (!currentSite.responsibleTeamId) return;

        const team = teams.find(t => t.id === currentSite.responsibleTeamId);
        if (!team || !team.companyId) return;

        const teamCompany = companyOptions.find(c => c.id === team.companyId || c.legacyId === team.companyId);
        const resolvedTeamCompanyId = teamCompany?.id || team.companyId;

        const normalizedTeamType = String(team?.type ?? '').trim();
        const normalizedCompanyType = String((teamCompany as any)?.type ?? '').trim();
        const isPartnerTeam = normalizedCompanyType === '협력사' || normalizedTeamType.includes('지원') || normalizedTeamType.includes('협력');

        if (isPartnerTeam) {
            setCurrentSite(prev => {
                const next: any = { ...prev };

                if (!isPartnerTouched && (!prev.partnerId || String(prev.partnerId).trim().length === 0)) {
                    next.partnerId = resolvedTeamCompanyId;
                }

                if (!isCompanyTouched && (prev.companyId === undefined || prev.companyId === null || String(prev.companyId).trim().length === 0)) {
                    const constructorCompanies = companyOptions.filter(c => String((c as any)?.type ?? '').trim() === '시공사');
                    if (constructorCompanies.length === 1) {
                        next.companyId = constructorCompanies[0].id;
                    }
                }

                return next;
            });
            return;
        }

        setCurrentSite(prev => {
            const next: any = { ...prev };

            if (!isCompanyTouched && (!prev.companyId || String(prev.companyId).trim().length === 0)) {
                next.companyId = resolvedTeamCompanyId;
            }

            if (!isPartnerTouched && (prev.partnerId === undefined || prev.partnerId === null || String(prev.partnerId).trim().length === 0)) {
                next.partnerId = '';
            }

            return next;
        });
    }, [currentSite.responsibleTeamId, teams, companyOptions, isCompanyTouched, isPartnerTouched]);

    // Auto-select Client (발주사/건설사) based on selected Constructor (시공사)
    useEffect(() => {
        const rawConstructorId = currentSite.companyId ? String(currentSite.companyId).trim() : '';
        if (!rawConstructorId) return;
        if (isClientCompanyTouched) return;

        const currentClientId = (currentSite as any).clientCompanyId ? String((currentSite as any).clientCompanyId).trim() : '';
        if (currentClientId.length > 0) return;

        const constructorCompany = companyOptions.find(c => c.id === rawConstructorId || c.legacyId === rawConstructorId);
        const constructorCompanyType = String((constructorCompany as any)?.type ?? '').trim();

        if (constructorCompany && constructorCompanyType === '미지정') {
            setCurrentSite(prev => ({
                ...prev,
                clientCompanyId: constructorCompany.id as any
            }));
            return;
        }

        const assigned = (constructorCompany as any)?.assignedClientCompanyIds as unknown;
        const assignedIds = Array.isArray(assigned)
            ? assigned.map(v => String(v)).filter(Boolean)
            : [];

        const resolvedClientIds = assignedIds
            .map(id => companyOptions.find(c => c.id === id || c.legacyId === id)?.id)
            .filter((id): id is string => typeof id === 'string' && id.length > 0);

        // If there is exactly one candidate, auto-fill it
        if (resolvedClientIds.length === 1) {
            setCurrentSite(prev => ({
                ...prev,
                clientCompanyId: resolvedClientIds[0] as any
            }));
        }
    }, [currentSite.companyId, companyOptions, isClientCompanyTouched]);

    const handleInlinePartnerSave = async () => {
        const trimmedName = partnerDraft.name.trim();
        if (!trimmedName) {
            alert('협력사명을 입력해주세요.');
            return;
        }

        const duplicate = companyOptions.find(
            (c) => c.name.trim().toLowerCase() === trimmedName.toLowerCase()
        );
        if (duplicate?.id) {
            alert('이미 등록된 협력사입니다. 기존 협력사를 선택합니다.');
            setCurrentSite((prev) => ({ ...prev, partnerId: duplicate.id, partnerName: duplicate.name }));
            setShowInlinePartnerForm(false);
            return;
        }

        setIsPartnerSaving(true);
        try {
            const payload = {
                name: trimmedName,
                code: partnerDraft.code.trim(),
                businessNumber: '',
                ceoName: partnerDraft.ceoName.trim(),
                address: partnerDraft.address.trim(),
                phone: partnerDraft.phone.trim(),
                email: '',
                type: '협력사' as const,
                bankName: '',
                accountNumber: '',
                accountHolder: '',
                ceoResidentNumber: '',
                color: '#16a34a'
            };

            const newId = await companyService.addCompany(payload);
            const created: Company = {
                ...payload,
                id: newId,
                status: 'active'
            };

            setCompanyOptions((prev) => [...prev, created].sort((a, b) => a.name.localeCompare(b.name, 'ko')));
            setCurrentSite((prev) => ({
                ...prev,
                partnerId: created.id,
                partnerName: created.name
            }));
            setShowInlinePartnerForm(false);
            setIsPartnerTouched(true);
            setPartnerDraft({ name: '', code: '', ceoName: '', phone: '', address: '' });
            alert(`협력사 [${created.name}] 등록 후 자동 선택되었습니다.`);
        } catch (error) {
            console.error('Failed to create partner company:', error);
            alert('협력사 등록에 실패했습니다.');
        } finally {
            setIsPartnerSaving(false);
        }
    };

    // ... (rest of code) ...

    // Client (발주사)

    const getErrorMessage = (error: unknown): string => {
        if (error instanceof Error) return error.message;
        if (typeof error === 'string') return error;
        if (typeof error === 'object' && error !== null && 'message' in error) {
            const msg = (error as { message: unknown }).message;
            if (typeof msg === 'string') return msg;
        }
        return 'Unknown error';
    };

    const [teamSearch, setTeamSearch] = useState('');
    const [clientSearch, setClientSearch] = useState('');
    const [isTeamMenuOpen, setIsTeamMenuOpen] = useState(false);
    const [isClientMenuOpen, setIsClientMenuOpen] = useState(false);

    // Filtered lists for search UI
    const searchedTeams = useMemo(() => {
        if (!teamSearch.trim()) return filteredTeams;
        const lower = teamSearch.toLowerCase();
        return filteredTeams.filter(t => t.name.toLowerCase().includes(lower));
    }, [filteredTeams, teamSearch]);

    const searchedClients = useMemo(() => {
        const base = companyOptions.filter(c => {
            const t = String((c as any)?.type ?? '').trim();
            const selectedId = currentSite.clientCompanyId ? String(currentSite.clientCompanyId) : '';
            if (selectedId && c.id === selectedId) return true;
            return t === '건설사' || t === '발주사' || t === '발주처' || t === '미지정';
        });
        if (!clientSearch.trim()) return base;
        const lower = clientSearch.toLowerCase();
        return base.filter(c => c.name.toLowerCase().includes(lower));
    }, [companyOptions, clientSearch, currentSite.clientCompanyId]);

    const handleSave = async () => {
        try {
            if (!currentSite.name) {
                alert("현장명은 필수입니다.");
                return;
            }

            const partnerId = currentSite.partnerId ? String(currentSite.partnerId).trim() : '';
            if (partnerId && !currentSite.responsibleTeamId) {
                alert('협력사 현장 등록 시 협력사 담당팀을 선택해주세요.');
                return;
            }

            // Find team name
            const team = teams.find(t => t.id === currentSite.responsibleTeamId);

            const normalizedCompanyId = currentSite.companyId ? String(currentSite.companyId) : null;
            const normalizedClientCompanyId = (currentSite as any).clientCompanyId ? String((currentSite as any).clientCompanyId) : null;
            const normalizedPartnerId = (currentSite as any).partnerId ? String((currentSite as any).partnerId) : null;

            // Find company names
            const constructor = normalizedCompanyId ? companyOptions.find(c => c.id === normalizedCompanyId) : undefined; // companyId is Constructor
            const client = normalizedClientCompanyId ? companyOptions.find(c => c.id === normalizedClientCompanyId) : undefined; // clientCompanyId is Client
            const partner = normalizedPartnerId ? companyOptions.find(c => c.id === normalizedPartnerId) : undefined;

            const siteData: any = {
                ...currentSite,
                companyId: normalizedCompanyId as any,
                clientCompanyId: normalizedClientCompanyId as any,
                partnerId: normalizedPartnerId as any,
                code: currentSite.code || '',
                address: currentSite.address || '',
                responsibleTeamName: team ? team.name : null,
                companyName: constructor ? constructor.name : null, // 시공사 (Constructor)
                clientCompanyName: client ? client.name : null, // 발주사 (Client)
                partnerName: partner ? partner.name : null, // 협력사 (Partner)
            };

            if (currentSite.id) {
                await siteService.updateSite(currentSite.id, siteData);
                // Sync Name Change
                if (initialData?.name && currentSite.name && initialData.name !== currentSite.name) {
                    await manpowerService.updateWorkersSiteName(currentSite.id, currentSite.name);
                }
            } else {
                await siteService.addSite(siteData as Site);
            }
            onSave();
        } catch (error) {
            console.error("Failed to save site", error);
            alert(`저장에 실패했습니다.\n${getErrorMessage(error)}`);
        }
    };

    return (
        <div className="bg-white border border-slate-200 rounded-xl shadow-xl overflow-hidden max-w-3xl mx-auto">
            {/* Header */}
            <div className="bg-slate-50 px-6 py-4 border-b border-slate-200 flex justify-between items-center">
                <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                    <span className="w-8 h-8 rounded-full bg-brand-100 flex items-center justify-center text-brand-600">
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
                        </svg>
                    </span>
                    {currentSite.id ? '현장 정보 수정' : '새 현장 등록'}
                </h2>
                <div className="flex gap-2 text-sm">
                    <span className={`px-2 py-1 rounded-full font-medium ${currentSite.status === 'active' ? 'bg-green-100 text-green-700' :
                        currentSite.status === 'completed' ? 'bg-slate-100 text-slate-600' : 'bg-yellow-100 text-yellow-700'
                        }`}>
                        {currentSite.status === 'active' ? '진행중' : currentSite.status === 'completed' ? '완료' : '예정'}
                    </span>
                </div>
            </div>

            <div className={`p-6 space-y-6 max-h-[75vh] overflow-y-auto custom-scrollbar transition-all duration-500 ${isClientMenuOpen ? 'pb-80' : isTeamMenuOpen ? 'pb-40' : 'pb-6'}`}>
                {/* 1. Basic Information Table */}
                <section className="border border-slate-300 rounded-lg overflow-visible shadow-sm relative z-0">
                    <div className="bg-slate-800 px-4 py-2.5 flex items-center justify-between">
                        <h3 className="text-sm font-bold text-white flex items-center gap-2">
                            <span className="w-2 h-2 rounded-full bg-brand-400"></span>
                            기본 정보 (Basic Info)
                        </h3>
                    </div>

                    <div className="grid grid-cols-12 text-sm divide-y divide-slate-200">
                        {/* Row 1: Site Name */}
                        <div className="col-span-12 grid grid-cols-12">
                            <div className="col-span-3 md:col-span-2 bg-slate-50 flex items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200">
                                현장명 <span className="text-red-500 ml-1">*</span>
                            </div>
                            <div className="col-span-9 md:col-span-10 p-2">
                                <input
                                    type="text"
                                    value={currentSite.name || ''}
                                    onChange={(e) => setCurrentSite({ ...currentSite, name: e.target.value })}
                                    className="w-full border-slate-200 bg-white rounded focus:ring-1 focus:ring-brand-500 focus:border-brand-500 text-sm py-1.5 px-3 shadow-sm placeholder:text-slate-300"
                                    placeholder="예: 대전 데이터센터 신축공사"
                                />
                            </div>
                        </div>

                        {/* Row 2: Status & Address */}
                        <div className="col-span-12 grid grid-cols-12">
                            {/* Status Label */}
                            <div className="col-span-3 md:col-span-2 bg-slate-50 flex items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200">
                                진행 상태
                            </div>
                            {/* Status Input */}
                            <div className="col-span-9 md:col-span-4 p-2 border-r border-slate-200">
                                <select
                                    value={currentSite.status || 'active'}
                                    onChange={(e) => setCurrentSite({ ...currentSite, status: e.target.value as any })}
                                    className={`w-full border-slate-200 rounded text-sm py-1.5 px-3 font-medium cursor-pointer focus:ring-1 focus:ring-brand-500 focus:border-brand-500
                                        ${currentSite.status === 'active' ? 'text-green-600 bg-green-50/50' :
                                            currentSite.status === 'planned' ? 'text-amber-600 bg-amber-50/50' : 'text-slate-600 bg-slate-50'}`}
                                >
                                    <option value="active">🟢 진행중 (Active)</option>
                                    <option value="planned">🟡 예정 (Planned)</option>
                                    <option value="completed">⚫ 완료 (Completed)</option>
                                </select>
                            </div>

                            {/* Address Label */}
                            <div className="hidden md:flex col-span-3 md:col-span-2 bg-slate-50 items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200 border-t md:border-t-0">
                                주소
                            </div>
                            {/* Address Input */}
                            <div className="col-span-12 md:col-span-4 p-2 border-t md:border-t-0">
                                <input
                                    type="text"
                                    value={currentSite.address || ''}
                                    onChange={(e) => setCurrentSite({ ...currentSite, address: e.target.value })}
                                    className="w-full border-slate-200 bg-white rounded focus:ring-1 focus:ring-brand-500 focus:border-brand-500 text-sm py-1.5 px-3 shadow-sm placeholder:text-slate-300"
                                    placeholder="현장 주소 입력"
                                />
                            </div>
                        </div>

                        {/* Row 3: Site Type & Payment Method */}
                        <div className="col-span-12 grid grid-cols-12 border-t border-slate-200">
                            {/* Site Type Label */}
                            <div className="col-span-3 md:col-span-2 bg-slate-50 flex items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200">
                                현장 구분
                            </div>
                            {/* Site Type Input */}
                            <div className="col-span-9 md:col-span-4 p-2 border-r border-slate-200">
                                <select
                                    value={currentSite.siteType || ''}
                                    onChange={(e) => setCurrentSite({ ...currentSite, siteType: e.target.value as any })}
                                    className="w-full border-slate-200 rounded text-sm py-1.5 px-3 font-medium cursor-pointer focus:ring-1 focus:ring-brand-500 focus:border-brand-500 bg-white"
                                >
                                    <option value="">(선택)</option>
                                    <option value="도급">도급</option>
                                    <option value="직영">직영</option>
                                    <option value="지원">지원</option>
                                </select>
                            </div>

                            {/* Payment Method Label */}
                            <div className="hidden md:flex col-span-3 md:col-span-2 bg-slate-50 items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200 border-t md:border-t-0">
                                결제 구분
                            </div>
                            {/* Payment Method Input */}
                            <div className="col-span-12 md:col-span-4 p-2 border-t md:border-t-0 flex items-center">
                                <div className="flex gap-4 items-center px-2">
                                    <label className="flex items-center gap-2 cursor-pointer hover:text-brand-600 transition-colors">
                                        <input
                                            type="radio"
                                            name="paymentMethod"
                                            value="계산서"
                                            checked={currentSite.paymentMethod === '계산서'}
                                            onChange={(e) => setCurrentSite({ ...currentSite, paymentMethod: e.target.value as any })}
                                            className="w-4 h-4 text-brand-600 focus:ring-brand-500 border-slate-300"
                                        />
                                        <span className="text-sm font-medium">계산서</span>
                                    </label>
                                    <label className="flex items-center gap-2 cursor-pointer hover:text-brand-600 transition-colors">
                                        <input
                                            type="radio"
                                            name="paymentMethod"
                                            value="노무"
                                            checked={currentSite.paymentMethod === '노무'}
                                            onChange={(e) => setCurrentSite({ ...currentSite, paymentMethod: e.target.value as any })}
                                            className="w-4 h-4 text-brand-600 focus:ring-brand-500 border-slate-300"
                                        />
                                        <span className="text-sm font-medium">노무</span>
                                    </label>
                                </div>
                            </div>
                        </div>
                    </div>
                </section>

                <div className="w-full border-t border-slate-100 my-2"></div>

                {/* 2. Contract & Responsibility */}
                {/* 2. Contract & Responsibility Table */}
                <section className="border border-slate-300 rounded-lg overflow-hidden shadow-sm">
                    <div className="bg-slate-800 px-4 py-2.5 flex items-center justify-between">
                        <h3 className="text-sm font-bold text-white flex items-center gap-2">
                            <span className="w-2 h-2 rounded-full bg-indigo-400"></span>
                            계약 및 담당 관리 (Contract & Responsibility)
                        </h3>
                    </div>

                    <div className="grid grid-cols-12 text-sm divide-y divide-slate-200 border-t border-slate-200">

                        {/* Row 1: Responsible Team (Searchable) */}
                        <div className="col-span-12 grid grid-cols-12 relative">
                            <div className="col-span-3 md:col-span-2 bg-slate-50 flex flex-col justify-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200">
                                <span>담당 팀</span>
                                <span className="text-[10px] text-slate-400 font-normal mt-0.5 tracking-tighter text-indigo-500 font-black">SEARCHABLE</span>
                            </div>
                            <div className="col-span-9 md:col-span-10 p-2 relative">
                                <div className="relative group">
                                    <div 
                                        className={`flex items-center justify-between w-full border-2 rounded-xl px-4 py-2.5 cursor-pointer transition-all ${isTeamMenuOpen ? 'border-indigo-500 ring-4 ring-indigo-50 bg-white' : 'border-slate-100 bg-slate-50/50 hover:border-indigo-300'}`}
                                        onClick={() => setIsTeamMenuOpen(!isTeamMenuOpen)}
                                    >
                                        <div className="flex items-center gap-2 overflow-hidden">
                                            <FontAwesomeIcon icon={faHardHat} className={currentSite.responsibleTeamId ? 'text-indigo-500' : 'text-slate-300'} />
                                            <span className={`font-bold truncate ${currentSite.responsibleTeamId ? 'text-slate-800' : 'text-slate-400'}`}>
                                                {teams.find(t => t.id === currentSite.responsibleTeamId)?.name || '팀 이름을 입력하거나 선택하세요...'}
                                            </span>
                                        </div>
                                        <FontAwesomeIcon icon={isTeamMenuOpen ? faChevronDown : faChevronRight} className={`text-xs transition-transform duration-300 ${isTeamMenuOpen ? 'rotate-180 text-indigo-500' : 'text-slate-300'}`} />
                                    </div>

                                    <AnimatePresence>
                                        {isTeamMenuOpen && (
                                            <motion.div 
                                                initial={{ opacity: 0, y: 10, scale: 0.95 }}
                                                animate={{ opacity: 1, y: 0, scale: 1 }}
                                                exit={{ opacity: 0, y: 10, scale: 0.95 }}
                                                className="absolute left-0 right-0 top-full mt-2 bg-white border border-slate-200 shadow-2xl rounded-2xl z-50 overflow-hidden"
                                            >
                                                <div className="p-3 border-b border-slate-100 bg-slate-50/50">
                                                    <div className="relative">
                                                        <FontAwesomeIcon icon={faSearch} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs" />
                                                        <input 
                                                            autoFocus
                                                            type="text"
                                                            value={teamSearch}
                                                            onChange={(e) => setTeamSearch(e.target.value)}
                                                            onKeyDown={(e) => {
                                                                if (e.key === 'Enter' && searchedTeams.length > 0) {
                                                                    const t = searchedTeams[0];
                                                                    setCurrentSite({...currentSite, responsibleTeamId: t.id});
                                                                    setIsTeamMenuOpen(false);
                                                                    setTeamSearch('');
                                                                }
                                                            }}
                                                            placeholder="단어 하나만 쳐보세요 (예: 인사, 1팀...)"
                                                            className="w-full pl-9 pr-4 py-2 text-sm border-2 border-slate-100 rounded-lg focus:border-indigo-400 focus:ring-0 font-bold"
                                                        />
                                                    </div>
                                                </div>
                                                <div className="max-h-60 overflow-y-auto custom-scrollbar p-1">
                                                    {searchedTeams.length > 0 ? searchedTeams.map(t => (
                                                        <div 
                                                            key={t.id}
                                                            onClick={() => {
                                                                setCurrentSite({...currentSite, responsibleTeamId: t.id});
                                                                setIsTeamMenuOpen(false);
                                                                setTeamSearch('');
                                                            }}
                                                            className="flex items-center justify-between px-4 py-2.5 hover:bg-indigo-50 rounded-xl cursor-pointer transition-colors group"
                                                        >
                                                            <div className="flex items-center gap-3">
                                                                <div className="w-8 h-8 rounded-lg bg-slate-100 group-hover:bg-white flex items-center justify-center text-xs text-slate-400 group-hover:text-indigo-600 transition-all">
                                                                    <FontAwesomeIcon icon={faHardHat} />
                                                                </div>
                                                                <span className="font-bold text-slate-700 group-hover:text-indigo-700">{t.name}</span>
                                                            </div>
                                                            {currentSite.responsibleTeamId === t.id && <FontAwesomeIcon icon={faCheck} className="text-indigo-500 text-xs" />}
                                                        </div>
                                                    )) : (
                                                        <div className="py-10 text-center text-slate-400 text-xs font-bold italic">
                                                            검색 결과가 없습니다.
                                                        </div>
                                                    )}
                                                </div>
                                            </motion.div>
                                        )}
                                    </AnimatePresence>
                                </div>

                                {/* Current Context Helpers */}
                                {currentSite.responsibleTeamId && (() => {
                                    const team = teams.find(t => t.id === currentSite.responsibleTeamId);
                                    const company = team?.companyId ? companyOptions.find(c => c.id === team.companyId) : null;
                                    if (company) {
                                        return (
                                            <div className="mt-2 flex items-center gap-2 text-[11px] text-indigo-700 bg-indigo-50/50 px-3 py-1.5 rounded-lg border border-indigo-100 animate-in fade-in slide-in-from-top-1">
                                                <span className="font-black tracking-widest uppercase text-[9px] bg-indigo-600 text-white px-1.5 py-0.5 rounded">Auto-Context</span>
                                                <span className="font-bold">'{team?.name}'</span>은 <span className="font-black underline">{company.name}</span> 소속입니다.
                                            </div>
                                        );
                                    }
                                    return null;
                                })()}
                            </div>
                        </div>

                        {/* Row 2: Constructor & Partner */}
                        <div className="col-span-12 grid grid-cols-12">
                            {/* Constructor Label */}
                            <div className="col-span-3 md:col-span-2 bg-slate-50 flex items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200">
                                시공사
                            </div>
                            {/* Constructor Input */}
                            <div className="col-span-9 md:col-span-4 p-2 border-r border-slate-200">
                                <div className={`relative w-full rounded-xl border ${currentSite.companyId ? 'border-slate-300 bg-slate-100' : 'border-slate-200 bg-slate-50/50'}`}>
                                    <select
                                        value={currentSite.companyId || ''}
                                        onChange={(e) => {
                                            setIsCompanyTouched(true);
                                            setCurrentSite({ ...currentSite, companyId: e.target.value });
                                        }}
                                        className="w-full bg-transparent border-none rounded-xl text-slate-600 text-sm py-2 px-3 appearance-none font-bold focus:ring-0"
                                    >
                                        <option value="">(자동 선택)</option>
                                        {companyOptions
                                            .filter(c => {
                                                const t = String((c as any)?.type ?? '').trim();
                                                const selectedId = currentSite.companyId ? String(currentSite.companyId) : '';
                                                if (selectedId && c.id === selectedId) return true;
                                                return t === '시공사' || t === '미지정';
                                            })
                                            .map(c => (
                                                <option key={c.id} value={c.id}>{c.name}</option>
                                            ))
                                        }
                                    </select>
                                </div>
                            </div>

                            {/* Partner Label */}
                            <div className="hidden md:flex col-span-3 md:col-span-2 bg-slate-50 items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200 border-t md:border-t-0">
                                협력사
                            </div>
                            {/* Partner Input */}
                            <div className="col-span-12 md:col-span-4 p-2 border-t md:border-t-0">
                                <div className={`relative w-full rounded-xl border ${currentSite.partnerId ? 'border-slate-300 bg-slate-100' : 'border-slate-200 bg-slate-50/50'}`}>
                                    <select
                                        value={currentSite.partnerId || ''}
                                        onChange={(e) => {
                                            const next = e.target.value;
                                            if (next === CREATE_PARTNER_VALUE) {
                                                setShowInlinePartnerForm(true);
                                                return;
                                            }
                                            setIsPartnerTouched(true);
                                            setShowInlinePartnerForm(false);
                                            setCurrentSite({ ...currentSite, partnerId: next });
                                        }}
                                        className="w-full bg-transparent border-none rounded-xl text-slate-600 text-sm py-2 px-3 appearance-none font-bold focus:ring-0"
                                    >
                                        <option value="">(자동 선택)</option>
                                        {companyOptions
                                            .filter(c => {
                                                const t = String((c as any)?.type ?? '').trim();
                                                const selectedId = currentSite.partnerId ? String(currentSite.partnerId) : '';
                                                if (selectedId && c.id === selectedId) return true;
                                                return t === '협력사';
                                            })
                                            .map(c => (
                                                <option key={c.id} value={c.id}>{c.name}</option>
                                            ))
                                        }
                                        <option value={CREATE_PARTNER_VALUE}>+ 신규 협력사 등록</option>
                                    </select>
                                </div>
                                {!showInlinePartnerForm && (
                                    <button
                                        type="button"
                                        onClick={() => setShowInlinePartnerForm(true)}
                                        className="mt-2 inline-flex items-center gap-1 rounded-lg border border-emerald-200 bg-emerald-50 px-2.5 py-1.5 text-[10px] font-black text-emerald-700 hover:bg-emerald-100 uppercase tracking-tighter"
                                    >
                                        + Quick Register Partner
                                    </button>
                                )}
                                {showInlinePartnerForm && (
                                    <div className="mt-3 rounded-2xl border border-emerald-200 bg-emerald-50/40 p-4 shadow-sm">
                                        <div className="mb-3 text-[11px] font-black text-emerald-800 uppercase tracking-widest flex items-center gap-2">
                                            <div className="w-1 h-3 bg-emerald-500 rounded-full" />
                                            협력사 즉시 등록
                                        </div>
                                        <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
                                            <input type="text" value={partnerDraft.name} onChange={(e) => setPartnerDraft((prev) => ({ ...prev, name: e.target.value }))} placeholder="협력사명 *" className="w-full border-2 border-emerald-100 bg-white rounded-xl px-3 py-2 text-sm font-bold focus:border-emerald-400 focus:ring-0" />
                                            <input type="text" value={partnerDraft.code} onChange={(e) => setPartnerDraft((prev) => ({ ...prev, code: e.target.value }))} placeholder="회사코드" className="w-full border-2 border-emerald-100 bg-white rounded-xl px-3 py-2 text-sm font-bold focus:border-emerald-400 focus:ring-0" />
                                            <input type="text" value={partnerDraft.ceoName} onChange={(e) => setPartnerDraft((prev) => ({ ...prev, ceoName: e.target.value }))} placeholder="대표자" className="w-full border-2 border-emerald-100 bg-white rounded-xl px-3 py-2 text-sm font-bold focus:border-emerald-400 focus:ring-0" />
                                            <input type="text" value={partnerDraft.phone} onChange={(e) => setPartnerDraft((prev) => ({ ...prev, phone: e.target.value }))} placeholder="연락처" className="w-full border-2 border-emerald-100 bg-white rounded-xl px-3 py-2 text-sm font-bold focus:border-emerald-400 focus:ring-0" />
                                        </div>
                                        <div className="mt-4 flex items-center gap-2">
                                            <button type="button" onClick={handleInlinePartnerSave} disabled={isPartnerSaving} className="flex-1 rounded-xl bg-emerald-600 px-4 py-2 text-xs font-black text-white hover:bg-emerald-700 disabled:opacity-50 shadow-lg shadow-emerald-200">
                                                {isPartnerSaving ? '처리 중...' : '등록 및 선택'}
                                            </button>
                                            <button type="button" onClick={() => setShowInlinePartnerForm(false)} className="rounded-xl border border-slate-200 bg-white px-4 py-2 text-xs font-bold text-slate-500 hover:bg-slate-50">닫기</button>
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Row 3: Client (Searchable) */}
                        <div className="col-span-12 grid grid-cols-12 relative">
                            <div className="col-span-3 md:col-span-2 bg-slate-50 flex items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200">
                                발주사 (Client)
                            </div>
                            <div className="col-span-9 md:col-span-10 p-2">
                                <div className="relative group">
                                    <div 
                                        className={`flex items-center justify-between w-full border-2 rounded-xl px-4 py-2.5 cursor-pointer transition-all ${isClientMenuOpen ? 'border-brand-500 ring-4 ring-brand-50 bg-white' : 'border-slate-100 bg-slate-50/50 hover:border-brand-300'}`}
                                        onClick={() => setIsClientMenuOpen(!isClientMenuOpen)}
                                    >
                                        <div className="flex items-center gap-2 overflow-hidden">
                                            <FontAwesomeIcon icon={faBuilding} className={currentSite.clientCompanyId ? 'text-brand-500' : 'text-slate-300'} />
                                            <span className={`font-bold truncate ${currentSite.clientCompanyId ? 'text-slate-800' : 'text-slate-400'}`}>
                                                {companyOptions.find(c => c.id === currentSite.clientCompanyId)?.name || '발주사명을 입력하거나 선택하세요...'}
                                            </span>
                                        </div>
                                        <FontAwesomeIcon icon={isClientMenuOpen ? faChevronDown : faChevronRight} className={`text-xs transition-transform duration-300 ${isClientMenuOpen ? 'rotate-180 text-brand-500' : 'text-slate-300'}`} />
                                    </div>

                                    <AnimatePresence>
                                        {isClientMenuOpen && (
                                            <motion.div 
                                                initial={{ opacity: 0, y: 10, scale: 0.95 }}
                                                animate={{ opacity: 1, y: 0, scale: 1 }}
                                                exit={{ opacity: 0, y: 10, scale: 0.95 }}
                                                className="absolute left-0 right-0 top-full mt-2 bg-white border border-slate-200 shadow-2xl rounded-2xl z-50 overflow-hidden"
                                            >
                                                <div className="p-3 border-b border-slate-100 bg-slate-50/50">
                                                    <div className="relative">
                                                        <FontAwesomeIcon icon={faSearch} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs" />
                                                        <input 
                                                            autoFocus
                                                            type="text"
                                                            value={clientSearch}
                                                            onChange={(e) => setClientSearch(e.target.value)}
                                                            onKeyDown={(e) => {
                                                                if (e.key === 'Enter' && searchedClients.length > 0) {
                                                                    const c = searchedClients[0];
                                                                    setCurrentSite({...currentSite, clientCompanyId: c.id});
                                                                    setIsClientMenuOpen(false);
                                                                    setClientSearch('');
                                                                }
                                                            }}
                                                            placeholder="발주사명 검색 (예: 현대, 삼성...)"
                                                            className="w-full pl-9 pr-4 py-2 text-sm border-2 border-slate-100 rounded-lg focus:border-brand-400 focus:ring-0 font-bold"
                                                        />
                                                    </div>
                                                </div>
                                                <div className="max-h-60 overflow-y-auto custom-scrollbar p-1">
                                                    <div 
                                                        onClick={() => {
                                                            setCurrentSite({...currentSite, clientCompanyId: ''});
                                                            setIsClientMenuOpen(false);
                                                            setClientSearch('');
                                                        }}
                                                        className="px-4 py-2.5 hover:bg-slate-50 rounded-xl cursor-pointer text-xs font-bold text-slate-400 italic"
                                                    >
                                                        선택 안함 (초기화)
                                                    </div>
                                                    {searchedClients.length > 0 ? searchedClients.map(c => (
                                                        <div 
                                                            key={c.id}
                                                            onClick={() => {
                                                                setCurrentSite({...currentSite, clientCompanyId: c.id});
                                                                setIsClientMenuOpen(false);
                                                                setClientSearch('');
                                                            }}
                                                            className="flex items-center justify-between px-4 py-2.5 hover:bg-brand-50 rounded-xl cursor-pointer transition-colors group"
                                                        >
                                                            <div className="flex items-center gap-3">
                                                                <div className="w-8 h-8 rounded-lg bg-slate-100 group-hover:bg-white flex items-center justify-center text-xs text-slate-400 group-hover:text-brand-600 transition-all">
                                                                    🏗️
                                                                </div>
                                                                <span className="font-bold text-slate-700 group-hover:text-brand-700">{c.name}</span>
                                                            </div>
                                                            {currentSite.clientCompanyId === c.id && <FontAwesomeIcon icon={faCheck} className="text-brand-500 text-xs" />}
                                                        </div>
                                                    )) : (
                                                        <div className="py-10 text-center text-slate-400 text-xs font-bold italic">
                                                            검색 결과가 없습니다.
                                                        </div>
                                                    )}
                                                </div>
                                            </motion.div>
                                        )}
                                    </AnimatePresence>
                                </div>
                            </div>
                        </div>

                    </div>
                </section>
            </div>

            {/* Footer */}
            <div className="bg-slate-50 px-6 py-4 border-t border-slate-200 flex justify-end gap-3">
                <button
                    onClick={onCancel}
                    className="px-5 py-2.5 rounded-lg text-sm font-medium text-slate-600 hover:bg-white hover:border-slate-300 border border-transparent transition-all"
                >
                    취소
                </button>
                <button
                    onClick={handleSave}
                    className="px-8 py-2.5 rounded-lg text-sm font-bold text-white bg-brand-600 hover:bg-brand-700 shadow-lg hover:shadow-brand-500/30 transition-all transform hover:-translate-y-0.5"
                >
                    {currentSite.id ? '변경사항 저장' : '현장 등록 완료'}
                </button>
            </div>
        </div >
    );
};

export default SiteForm;

import React, { useState, useEffect } from 'react';
import { siteService, Site } from '../../services/siteService';
import { teamService, Team } from '../../services/teamService';
import { companyService, Company } from '../../services/companyService';
import { toast } from '../../utils/swal';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faPlus, faPenToSquare, faTrash, faBuilding, faFileExcel, faFileImport, faFileExport } from '@fortawesome/free-solid-svg-icons';
import * as XLSX from 'xlsx';
import SiteForm from './SiteForm';


const SiteManagement: React.FC = () => {
    const [sites, setSites] = useState<Site[]>([]);
    const [teams, setTeams] = useState<Team[]>([]);
    const [companies, setCompanies] = useState<Company[]>([]);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [currentSite, setCurrentSite] = useState<Partial<Site>>({});
    const [isLoading, setIsLoading] = useState(true);
    const [lastDoc, setLastDoc] = useState<any>(null);
    const [hasMore, setHasMore] = useState(true);
    const [isLoadingMore, setIsLoadingMore] = useState(false);
    const LIMIT = 100;

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const [sitesData, teamsData, companiesData] = await Promise.all([
                siteService.getSitesPaginated(LIMIT),
                teamService.getTeams(),
                companyService.getCompanies()
            ]);
            setSites(sitesData.sites);
            setLastDoc(sitesData.lastDoc);
            setHasMore(sitesData.sites.length === LIMIT);
            setTeams(teamsData);
            setCompanies(companiesData);
        } catch (error) {
            console.error("Failed to fetch data", error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleLoadMore = async () => {
        if (!lastDoc || isLoadingMore) return;
        setIsLoadingMore(true);
        try {
            const result = await siteService.getSitesPaginated(LIMIT, lastDoc);
            setSites(prev => [...prev, ...result.sites]);
            setLastDoc(result.lastDoc);
            setHasMore(result.sites.length === LIMIT);
        } catch (error) {
            console.error("Failed to load more sites", error);
        } finally {
            setIsLoadingMore(false);
        }
    };



    const handleDelete = async (id: string) => {
        if (window.confirm('정말 삭제하시겠습니까?')) {
            try {
                await siteService.deleteSite(id);
                fetchData();
            } catch (error) {
                console.error("Failed to delete site", error);
                alert("삭제에 실패했습니다.");
            }
        }
    };

    const openModal = (site?: Site) => {
        setCurrentSite(site || { status: 'active' });
        setIsModalOpen(true);
    };



    // ... existing useEffect ...

    const handleExcelDownload = () => {
        const data = sites.map(site => ({
            '현장명': site.name,
            '담당팀': site.responsibleTeamName || '',
            '현장코드': site.code || '',
            '주소': site.address || '',
            '상태': site.status === 'active' ? '진행중' : site.status === 'completed' ? '완료' : '예정'
        }));

        if (data.length === 0) {
            data.push({
                '현장명': '예시현장',
                '담당팀': '예시팀',
                '현장코드': 'SITE-001',
                '주소': '서울시 강남구',
                '상태': '진행중'
            });
        }

        const ws = XLSX.utils.json_to_sheet(data);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "현장목록");
        XLSX.writeFile(wb, `현장목록_${new Date().toISOString().slice(0, 10)}.xlsx`);
    };

    const handleExcelUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = async (evt) => {
            try {
                const bstr = evt.target?.result;
                const wb = XLSX.read(bstr, { type: 'binary' });
                const wsname = wb.SheetNames[0];
                const ws = wb.Sheets[wsname];
                const data = XLSX.utils.sheet_to_json(ws) as any[];

                if (data.length === 0) {
                    alert('엑셀 파일에 데이터가 없습니다.');
                    return;
                }

                setIsLoading(true);
                let successCount = 0;

                for (const row of data) {
                    const teamName = row['담당팀'];
                    let teamId = '';
                    let responsibleTeamName = '';

                    if (teamName) {
                        const team = teams.find(t => t.name === teamName);
                        if (team) {
                            teamId = team.id!;
                            responsibleTeamName = team.name;
                        }
                    }

                    const statusMap: { [key: string]: 'active' | 'planned' | 'completed' } = {
                        '진행중': 'active',
                        '예정': 'planned',
                        '완료': 'completed'
                    };

                    const newSite: Site = {
                        name: row['현장명'],
                        responsibleTeamId: teamId,
                        responsibleTeamName: responsibleTeamName,
                        code: row['현장코드'],
                        address: row['주소'],
                        status: statusMap[row['상태']] || 'active'
                    };

                    if (newSite.name) {
                        await siteService.addSite(newSite);
                        successCount++;
                    }
                }

                alert(`${successCount}건의 현장이 등록되었습니다.`);
                fetchData();

            } catch (error) {
                console.error("Excel upload failed", error);
                alert("엑셀 업로드 중 오류가 발생했습니다.");
            } finally {
                setIsLoading(false);
                e.target.value = '';
            }
        };
        reader.readAsBinaryString(file);
    };

    // ... existing functions ...

    const handleUpdateSite = async (siteId: string, field: 'clientCompanyId' | 'companyId' | 'partnerId', value: string) => {
        const company = companies.find(c => c.id === value);
        let updates: Partial<Site> = { [field]: value };

        if (field === 'clientCompanyId') updates.clientCompanyName = company?.name || '';
        if (field === 'companyId') updates.companyName = company?.name || '';
        if (field === 'partnerId') updates.partnerName = company?.name || '';

        try {
            await siteService.updateSite(siteId, updates);
            setSites(prev => prev.map(s => s.id === siteId ? { ...s, ...updates } : s));
        } catch (error) {
            console.error("Failed to update site", error);
            alert("수정 실패");
        }
    };

    const refreshSites = async () => {
        try {
            const fetchedSites = await siteService.getSites();
            setSites(fetchedSites);
        } catch (error) {
            console.error("Failed to refresh sites", error);
        }
    };

    const handleTeamChange = async (siteId: string, teamId: string) => {
        // 1. Fetch Fresh Team Data from DB
        let freshTeam: Team | null = null;
        try {
            freshTeam = await teamService.getTeam(teamId);
        } catch (e) {
            console.error("Failed to fetch fresh team", e);
            freshTeam = teams.find(t => t.id === teamId) || null;
        }

        const team = freshTeam || teams.find(t => t.id === teamId);
        if (!team) return;

        // 2. Resolve Company (Smart Match Logic - Self Healing)
        let targetCompany: Company | undefined = undefined;
        let matchMethod = 'id';

        const normalize = (s: string) => s ? s.replace(/\s+/g, '').trim() : '';
        const teamCompName = normalize(team.companyName || '');

        // A. Try ID Match
        if (team.companyId) {
            targetCompany = companies.find(c => c.id === team.companyId);
        }

        // B. Check for Data Drift & Fuzzy Search
        // If ID Match failed OR Name Mismatch (Drift)
        let isDrift = false;
        if (targetCompany && teamCompName && normalize(targetCompany.name) !== teamCompName) {
            isDrift = true;
            console.warn(`[SmartMatch] Name Mismatch! Team says '${team.companyName}', ID points to '${targetCompany.name}'`);
        }

        if (!targetCompany || isDrift) {
            // Priority 1: Exact Name Match
            let candidate = companies.find(c => c.name === team.companyName);

            // Priority 2: Normalized Name Match
            if (!candidate && teamCompName) {
                candidate = companies.find(c => normalize(c.name) === teamCompName);
            }

            // Priority 3: Partial Match (Team name inside Company name or vice versa)
            // Only if string is long enough to avoid false positives
            if (!candidate && teamCompName.length > 2) {
                candidate = companies.find(c => {
                    const cName = normalize(c.name);
                    return cName.includes(teamCompName) || teamCompName.includes(cName);
                });
            }

            if (candidate) {
                targetCompany = candidate;
                matchMethod = 'fuzzy_fix';
                console.log(`[SmartMatch] Found Company by Name/Fuzzy: ${candidate.name}`);

                // *** SELF HEALING ***
                // Update the Team's broken link so it works next time
                try {
                    await teamService.updateTeam(team.id!, {
                        companyId: candidate.id,
                        companyName: candidate.name
                    });
                    console.log("[SmartMatch] Auto-Repaired Team Data.");
                } catch (err) {
                    console.error("Failed to auto-repair team", err);
                }
            }
        }

        let updates: Partial<Site> = {
            responsibleTeamId: teamId,
            responsibleTeamName: team.name || ''
        };

        let typeLabel = '';
        if (targetCompany) {
            const companyType = targetCompany.type?.trim();
            if (companyType === '협력사') {
                updates.partnerId = targetCompany.id;
                updates.partnerName = targetCompany.name;
                updates.companyId = '';
                updates.companyName = '';
                updates.clientCompanyId = '';
                updates.clientCompanyName = '';
                typeLabel = '협력사';
            } else {
                updates.companyId = targetCompany.id;
                updates.companyName = targetCompany.name;
                updates.partnerId = '';
                updates.partnerName = '';
                typeLabel = companyType || '시공사(기본)';
            }
        } else if (teamId) {
            updates.companyId = '';
            updates.companyName = '';
            updates.partnerId = '';
            updates.partnerName = '';
        }

        try {
            await siteService.updateSite(siteId, updates);
            setSites(prev => prev.map(s => s.id === siteId ? { ...s, ...updates } : s));
            await refreshSites();

            if (targetCompany) {
                let msg = `[${team.name}] → ${targetCompany.name} (${typeLabel}) 적용 완료`;
                if (matchMethod === 'fuzzy_fix') msg += ' (자동 보정됨)';
                if (isDrift) msg += ' (데이터 오류 수정됨)';
                toast.success(msg);
            } else if (teamId) {
                // Diagnose WHY it failed
                const reason = team.companyName
                    ? `회사명 '${team.companyName}'을(를) DB에서 찾을 수 없습니다.`
                    : '팀에 연결된 회사가 없습니다.';
                toast.error(`[${team.name}] 회사 연동 실패: ${reason}`);
            }
        } catch (error) {
            console.error("Failed to update site team", error);
            alert("팀 수정 실패");
        }
    };

    // ... existing useEffect ...



    return (
        <div className="flex flex-col h-full">
            {/* Toolbar */}
            <div className="bg-white border-b border-slate-200 p-4 flex items-center justify-between flex-shrink-0">
                <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                    <FontAwesomeIcon icon={faBuilding} className="text-brand-600" /> 현장 목록
                </h2>
                <div className="flex gap-2">
                    <button
                        onClick={handleExcelDownload}
                        className="bg-green-600 text-white px-3 py-2 rounded-lg hover:bg-green-700 transition font-bold shadow-sm text-sm flex items-center"
                        title="엑셀 다운로드"
                    >
                        <FontAwesomeIcon icon={faFileExport} className="mr-2" /> 엑셀
                    </button>
                    <label className="bg-blue-500 text-white px-3 py-2 rounded-lg hover:bg-blue-600 transition font-bold shadow-sm text-sm flex items-center cursor-pointer" title="엑셀 업로드">
                        <input
                            type="file"
                            accept=".xlsx, .xls"
                            className="hidden"
                            onChange={handleExcelUpload}
                            disabled={isLoading}
                        />
                        <FontAwesomeIcon icon={faFileImport} className="mr-2" /> 업로드
                    </label>

                    <button onClick={() => openModal()} className="bg-brand-600 text-white px-4 py-2 rounded-lg hover:bg-brand-700 transition font-bold shadow-sm text-sm">
                        <FontAwesomeIcon icon={faPlus} className="mr-2" /> 현장 등록
                    </button>
                </div>
            </div>



            {/* Content Area: Table or Form */}
            <div className="flex-1 overflow-auto p-4">
                {isModalOpen ? (
                    <SiteForm
                        initialData={currentSite}
                        teams={teams}
                        companies={companies}
                        onSave={() => {
                            fetchData();
                            setIsModalOpen(false);
                        }}
                        onCancel={() => setIsModalOpen(false)}
                    />
                ) : (
                    <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
                        <table className="w-full text-left border-collapse">
                            <thead className="bg-slate-50 text-xs font-bold text-slate-500 uppercase tracking-wider">
                                <tr>
                                    <th className="px-6 py-3 border-b border-slate-200">현장명</th>
                                    <th className="px-6 py-3 border-b border-slate-200">담당팀</th>
                                    <th className="px-4 py-3 border-b border-slate-200">발주사</th>
                                    <th className="px-4 py-3 border-b border-slate-200">시공사</th>
                                    <th className="px-4 py-3 border-b border-slate-200">협력사</th>
                                    <th className="px-6 py-3 border-b border-slate-200">현장코드</th>
                                    <th className="px-6 py-3 border-b border-slate-200">주소</th>


                                    <th className="px-6 py-3 border-b border-slate-200">상태</th>
                                    <th className="px-6 py-3 border-b border-slate-200 text-right">관리</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 text-sm">
                                {isLoading ? (
                                    <tr><td colSpan={10} className="text-center py-10">로딩중...</td></tr>
                                ) : sites.length === 0 ? (
                                    <tr><td colSpan={10} className="text-center py-10 text-slate-400">등록된 현장이 없습니다.</td></tr>
                                ) : (
                                    sites.map((site) => {
                                        const company = companies.find(c => c.id === site.companyId);
                                        const siteColor = company?.color || '#e5e7eb';
                                        return (
                                            <tr key={site.id} className="hover:bg-slate-50 transition-colors">
                                                <td className="px-6 py-4 font-bold text-slate-800">
                                                    <div className="flex items-center gap-2">
                                                        <span
                                                            className="inline-block w-1.5 h-6 rounded-full border border-slate-200"
                                                            style={{ backgroundColor: siteColor }}
                                                        />
                                                        <span>{site.name}</span>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-4 text-slate-600">
                                                    <select
                                                        value={site.responsibleTeamId || ''}
                                                        onChange={(e) => handleTeamChange(site.id!, e.target.value)}
                                                        className="text-xs border border-slate-200 rounded px-2 py-1 w-full cursor-pointer hover:border-brand-500 transition-colors bg-indigo-50 text-indigo-700 font-bold"
                                                        style={{ minWidth: '100px' }}
                                                    >
                                                        <option value="">-</option>
                                                        {teams.map(t => (
                                                            <option key={t.id} value={t.id}>{t.name}</option>
                                                        ))}
                                                    </select>
                                                </td>

                                                {/* Client (발주사) Editable */}
                                                <td className="px-4 py-4">
                                                    <select
                                                        value={site.clientCompanyId || ''}
                                                        onChange={(e) => handleUpdateSite(site.id!, 'clientCompanyId', e.target.value)}
                                                        className={`text-xs border rounded px-2 py-1 w-32 cursor-pointer hover:border-brand-500 transition-colors ${site.clientCompanyId && companies.find(c => c.id === site.clientCompanyId)?.type !== '건설사'
                                                            ? 'border-red-500 text-red-600 bg-red-50 font-bold'
                                                            : 'border-slate-200'
                                                            }`}
                                                    >
                                                        <option value="">-</option>
                                                        {companies.map(c => (
                                                            <option key={c.id} value={c.id}>
                                                                {c.type !== '건설사' ? '⚠️ ' : ''}{c.name}
                                                            </option>
                                                        ))}
                                                    </select>
                                                </td>

                                                {/* Constructor (시공사) Editable */}
                                                <td className="px-4 py-4">
                                                    <select
                                                        value={site.companyId || ''}
                                                        onChange={(e) => handleUpdateSite(site.id!, 'companyId', e.target.value)}
                                                        className={`text-xs border rounded px-2 py-1 w-32 cursor-pointer hover:border-brand-500 transition-colors ${site.companyId && !['시공사', '건설사', '미지정'].includes(companies.find(c => c.id === site.companyId)?.type || '')
                                                            ? 'border-red-500 text-red-600 bg-red-50 font-bold'
                                                            : 'border-slate-200'
                                                            }`}
                                                    >
                                                        <option value="">-</option>
                                                        {companies.map(c => (
                                                            <option key={c.id} value={c.id}>
                                                                {c.type === '협력사' ? '⚠️ ' : ''}{c.name}
                                                            </option>
                                                        ))}
                                                    </select>
                                                </td>

                                                {/* Partner (협력사) Editable */}
                                                <td className="px-4 py-4">
                                                    <select
                                                        value={site.partnerId || ''}
                                                        onChange={(e) => handleUpdateSite(site.id!, 'partnerId', e.target.value)}
                                                        className={`text-xs border rounded px-2 py-1 w-32 cursor-pointer hover:border-brand-500 transition-colors ${site.partnerId && companies.find(c => c.id === site.partnerId)?.type !== '협력사'
                                                            ? 'border-red-500 text-red-600 bg-red-50 font-bold'
                                                            : 'border-slate-200'
                                                            }`}
                                                    >
                                                        <option value="">-</option>
                                                        {companies.map(c => (
                                                            <option key={c.id} value={c.id}>
                                                                {c.type !== '협력사' ? '⚠️ ' : ''}{c.name}
                                                            </option>
                                                        ))}
                                                    </select>
                                                </td>

                                                <td className="px-6 py-4 text-slate-600 font-mono">{site.code}</td>
                                                <td className="px-6 py-4 text-slate-600">{site.address}</td>


                                                <td className="px-6 py-4">
                                                    <span className={`px-2 py-1 rounded-full text-xs font-bold ${site.status === 'active' ? 'bg-emerald-100 text-emerald-700' :
                                                        site.status === 'completed' ? 'bg-slate-100 text-slate-500' :
                                                            'bg-orange-100 text-orange-700'
                                                        }`}>
                                                        {site.status === 'active' ? '진행중' :
                                                            site.status === 'completed' ? '완료' : '예정'}
                                                    </span>
                                                </td>
                                                <td className="px-6 py-4 text-right">
                                                    <button onClick={() => openModal(site)} className="text-slate-400 hover:text-brand-600 mr-2 transition"><FontAwesomeIcon icon={faPenToSquare} /></button>
                                                    <button onClick={() => handleDelete(site.id!)} className="text-slate-400 hover:text-red-600 transition"><FontAwesomeIcon icon={faTrash} /></button>
                                                </td>
                                            </tr>
                                        );
                                    })
                                )}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div >
    );
};


export default SiteManagement;

import React, { useMemo, useState, useEffect } from 'react';
import { Team, teamService } from '../../services/teamService';
import { Worker, manpowerService } from '../../services/manpowerService';
import { Company, companyService } from '../../services/companyService';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faUsers, faCheck, faTimes, faPlus } from '@fortawesome/free-solid-svg-icons';

interface TeamFormProps {
    initialData?: Partial<Team>;
    teams: Team[];
    workers: Worker[];
    companies: Company[];
    onSave: () => void;
    onCancel: () => void;
}

const TeamForm: React.FC<TeamFormProps> = ({ initialData, teams, workers, companies, onSave, onCancel }) => {
    const [currentTeam, setCurrentTeam] = useState<Partial<Team>>(initialData || {
        type: '시공팀',
        bankName: '',
        accountNumber: '',
        accountHolder: ''
    });
    const [isSaving, setIsSaving] = useState(false);
    const [companyOptions, setCompanyOptions] = useState<Company[]>(companies);
    const [showInlinePartnerForm, setShowInlinePartnerForm] = useState(false);
    const [isPartnerSaving, setIsPartnerSaving] = useState(false);
    const [partnerDraft, setPartnerDraft] = useState({
        name: '',
        code: '',
        ceoName: '',
        phone: '',
        address: ''
    });

    const salaryModelOptions = ['일급제', '주급제', '월급제', '지원팀', '용역팀', '가지급'];
    const CREATE_PARTNER_VALUE = '__CREATE_PARTNER__';

    useEffect(() => {
        setCompanyOptions(companies);
    }, [companies]);

    const teamType = String(currentTeam.type ?? '시공팀');
    const isConstructorTeam = teamType === '시공팀';
    const isSupportTeam = teamType === '지원팀';
    const canCreatePartnerInline = isSupportTeam || teamType === '용역팀';

    const constructorCompanyOptions = useMemo(() => {
        const constructorCompanies = companyOptions.filter((c) => c.type === '시공사');
        const cheongyeonCompanies = constructorCompanies.filter((c) => String(c.name ?? '').includes('청연'));
        return cheongyeonCompanies.length > 0 ? cheongyeonCompanies : constructorCompanies;
    }, [companyOptions]);

    const partnerCompanies = useMemo(
        () => companyOptions.filter((c) => c.type === '협력사'),
        [companyOptions]
    );

    const selectableCompanies = useMemo(() => {
        if (isConstructorTeam) return constructorCompanyOptions;
        if (isSupportTeam) return partnerCompanies;
        return companyOptions;
    }, [companyOptions, constructorCompanyOptions, isConstructorTeam, isSupportTeam, partnerCompanies]);

    useEffect(() => {
        setCurrentTeam((prev) => {
            const currentCompanyId = String(prev.companyId ?? '').trim();
            const isValid = selectableCompanies.some((c) => String(c.id ?? '') === currentCompanyId);
            if (isValid) return prev;

            const nextCompanyId = String(selectableCompanies[0]?.id ?? '').trim();
            if (currentCompanyId === nextCompanyId) return prev;
            return { ...prev, companyId: nextCompanyId };
        });

        if (!canCreatePartnerInline && showInlinePartnerForm) {
            setShowInlinePartnerForm(false);
        }
    }, [canCreatePartnerInline, selectableCompanies, showInlinePartnerForm]);

    const handleInlinePartnerSave = async () => {
        const trimmedName = partnerDraft.name.trim();
        if (!trimmedName) {
            alert('협력사명을 입력해주세요.');
            return;
        }

        const duplicate = companyOptions.find(
            (c) => c.name.trim().toLowerCase() === trimmedName.toLowerCase()
        );
        if (duplicate?.id) {
            alert('이미 등록된 협력사입니다. 기존 협력사를 선택합니다.');
            setCurrentTeam((prev) => ({ ...prev, companyId: duplicate.id, companyName: duplicate.name }));
            setShowInlinePartnerForm(false);
            return;
        }

        setIsPartnerSaving(true);
        try {
            const payload = {
                name: trimmedName,
                code: partnerDraft.code.trim(),
                businessNumber: '',
                ceoName: partnerDraft.ceoName.trim(),
                address: partnerDraft.address.trim(),
                phone: partnerDraft.phone.trim(),
                email: '',
                type: '협력사' as const,
                bankName: '',
                accountNumber: '',
                accountHolder: '',
                ceoResidentNumber: '',
                color: '#16a34a'
            };

            const newId = await companyService.addCompany(payload);
            const created: Company = {
                ...payload,
                id: newId,
                status: 'active'
            };

            setCompanyOptions((prev) => [...prev, created].sort((a, b) => a.name.localeCompare(b.name, 'ko')));
            setCurrentTeam((prev) => ({ ...prev, companyId: newId, companyName: created.name }));
            setShowInlinePartnerForm(false);
            setPartnerDraft({ name: '', code: '', ceoName: '', phone: '', address: '' });
            alert(`협력사 [${created.name}] 등록 후 자동 선택되었습니다.`);
        } catch (error) {
            console.error('Failed to create partner company:', error);
            alert('협력사 등록에 실패했습니다.');
        } finally {
            setIsPartnerSaving(false);
        }
    };

    const handleSave = async () => {
        if (isSaving) return;
        try {
            const trimmedName = String(currentTeam.name ?? '').trim();
            if (!trimmedName) {
                alert('팀명을 입력해주세요.');
                return;
            }

            const selectedCompanyId = String(currentTeam.companyId ?? '').trim();
            const selectedCompany = companyOptions.find((c) => String(c.id ?? '') === selectedCompanyId);

            if (isConstructorTeam) {
                const isAllowedConstructor = constructorCompanyOptions.some((c) => String(c.id ?? '') === selectedCompanyId);
                if (!selectedCompany || !isAllowedConstructor) {
                    alert('시공팀은 청연 소속 시공사만 소속 회사로 선택할 수 있습니다.');
                    return;
                }
            }

            if (isSupportTeam) {
                const isAllowedPartner = partnerCompanies.some((c) => String(c.id ?? '') === selectedCompanyId);
                if (!selectedCompany || !isAllowedPartner) {
                    alert('지원팀은 협력사를 소속 회사로 선택해주세요.');
                    return;
                }
            }

            setIsSaving(true);

            // Find leader name
            const leader = workers.find(w => w.id === currentTeam.leaderId);
            // Find company name
            const company = companyOptions.find(c => c.id === currentTeam.companyId);


            const teamData = {
                ...currentTeam,
                name: trimmedName,
                leaderName: leader ? leader.name : '',
                companyName: company ? company.name : ''
            };

            if (currentTeam.id) {
                await teamService.updateTeam(currentTeam.id, teamData);

                // Sync Name Change if needed
                if (initialData?.name && currentTeam.name && initialData.name !== currentTeam.name) {
                    await manpowerService.updateWorkersTeamName(currentTeam.id, currentTeam.name);
                }

                const prevDefaultSalaryModel = initialData?.defaultSalaryModel ?? '';
                const nextDefaultSalaryModel = currentTeam.defaultSalaryModel ?? '';
                if (prevDefaultSalaryModel !== nextDefaultSalaryModel && nextDefaultSalaryModel) {
                    const ok = window.confirm('팀 기본 지급구분이 변경되었습니다. 이 팀의 모든 작업자 지급구분도 일괄 변경할까요?');
                    if (ok) {
                        await manpowerService.updateWorkersSalaryModelByTeam(currentTeam.id, nextDefaultSalaryModel);
                    }
                }
            } else {
                await teamService.addTeam(teamData as Team);
            }
            onSave();
        } catch (error) {
            console.error("Failed to save team", error);
            const message = error instanceof Error ? error.message : String(error);
            alert(`저장에 실패했습니다: ${message}`);
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="bg-white border border-slate-200 rounded-xl shadow-xl overflow-hidden max-w-3xl mx-auto">
            {/* Header */}
            <div className="bg-slate-50 px-6 py-4 border-b border-slate-200 flex justify-between items-center">
                <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                    <span className="w-8 h-8 rounded-full bg-brand-100 flex items-center justify-center text-brand-600">
                        <FontAwesomeIcon icon={faUsers} className="text-sm" />
                    </span>
                    <span>{currentTeam.id ? '팀 정보 수정' : '새 팀 등록'}</span>
                </h3>
            </div>

            <div className="p-6 space-y-6 max-h-[75vh] overflow-y-auto custom-scrollbar">
                {/* 1. Basic Information */}
                <section className="border border-slate-300 rounded-lg overflow-hidden shadow-sm">
                    <div className="bg-slate-800 px-4 py-2.5 flex items-center justify-between">
                        <h3 className="text-sm font-bold text-white flex items-center gap-2">
                            <span className="w-2 h-2 rounded-full bg-brand-400"></span>
                            기본 정보 (Basic Information)
                        </h3>
                    </div>

                    <div className="grid grid-cols-12 text-sm divide-y divide-slate-200">
                        {/* Row 1: Team Name */}
                        <div className="col-span-12 grid grid-cols-12">
                            <div className="col-span-3 md:col-span-2 bg-slate-50 flex items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200">
                                팀명 <span className="text-red-500 ml-1">*</span>
                            </div>
                            <div className="col-span-9 md:col-span-10 p-2">
                                <input
                                    type="text"
                                    value={currentTeam.name || ''}
                                    onChange={(e) => setCurrentTeam({ ...currentTeam, name: e.target.value })}
                                    className="w-full border-slate-200 bg-white rounded focus:ring-1 focus:ring-brand-500 focus:border-brand-500 text-sm py-1.5 px-3 shadow-sm placeholder:text-slate-300"
                                    placeholder="팀명을 입력하세요"
                                />
                            </div>
                        </div>

                        {/* Row 2: Type & Company */}
                        <div className="col-span-12 grid grid-cols-12">
                            <div className="col-span-3 md:col-span-2 bg-slate-50 flex items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200">
                                팀 유형
                            </div>
                            <div className="col-span-9 md:col-span-4 p-2 border-r border-slate-200">
                                <select
                                    value={currentTeam.type || '시공팀'}
                                    onChange={(e) => {
                                        const nextType = e.target.value;
                                        setCurrentTeam(prev => {
                                            const next: Partial<Team> = { ...prev, type: nextType };
                                            if (!prev.defaultSalaryModel) {
                                                if (nextType === '지원팀') next.defaultSalaryModel = '지원팀';
                                                if (nextType === '용역팀') next.defaultSalaryModel = '용역팀';
                                            }
                                            return next;
                                        });
                                    }}
                                    className="w-full border-slate-200 rounded text-sm py-1.5 px-3 font-medium cursor-pointer focus:ring-1 focus:ring-brand-500 focus:border-brand-500 bg-white"
                                >
                                    <option value="시공팀">시공팀</option>
                                    <option value="지원팀">지원팀</option>
                                    <option value="용역팀">용역팀</option>
                                </select>
                            </div>
                            <div className="hidden md:flex col-span-3 md:col-span-2 bg-slate-50 items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200 border-t md:border-t-0">
                                소속 회사
                            </div>
                            <div className="col-span-12 md:col-span-4 p-2 border-t md:border-t-0">
                                <select
                                    value={currentTeam.companyId || ''}
                                    onChange={(e) => {
                                        const next = e.target.value;
                                        if (next === CREATE_PARTNER_VALUE && canCreatePartnerInline) {
                                            setShowInlinePartnerForm(true);
                                            return;
                                        }
                                        setShowInlinePartnerForm(false);
                                        setCurrentTeam({ ...currentTeam, companyId: next });
                                    }}
                                    className="w-full border-slate-200 rounded text-sm py-1.5 px-3 font-medium cursor-pointer focus:ring-1 focus:ring-brand-500 focus:border-brand-500 bg-white"
                                >
                                    <option value="">
                                        {isConstructorTeam
                                            ? '청연 소속 시공사 선택'
                                            : isSupportTeam
                                                ? '협력사 선택'
                                                : '소속 회사 선택'}
                                    </option>
                                    {selectableCompanies.map(c => (
                                        <option key={c.id} value={c.id}>{c.name}</option>
                                    ))}
                                    {canCreatePartnerInline && <option value={CREATE_PARTNER_VALUE}>+ 신규 협력사 등록</option>}
                                </select>
                                <div className="mt-2 space-y-2">
                                    {isConstructorTeam && (
                                        <div className="text-[12px] text-slate-500">
                                            시공팀은 청연 소속 시공사만 선택됩니다.
                                        </div>
                                    )}
                                    {isSupportTeam && (
                                        <div className="text-[12px] text-slate-500">
                                            지원팀은 협력사만 선택됩니다. 신규 협력사는 아래에서 바로 등록할 수 있습니다.
                                        </div>
                                    )}
                                    {isSupportTeam && partnerCompanies.length === 0 && !showInlinePartnerForm && (
                                        <div className="rounded border border-amber-200 bg-amber-50 px-2.5 py-2 text-[12px] text-amber-700">
                                            등록된 협력사가 없습니다. `신규 협력사 등록`을 눌러 먼저 등록해주세요.
                                        </div>
                                    )}
                                    {canCreatePartnerInline && !showInlinePartnerForm && (
                                        <button
                                            type="button"
                                            onClick={() => setShowInlinePartnerForm(true)}
                                            className="inline-flex items-center gap-1 rounded border border-emerald-200 bg-emerald-50 px-2.5 py-1.5 text-xs font-bold text-emerald-700 hover:bg-emerald-100"
                                        >
                                            <FontAwesomeIcon icon={faPlus} />
                                            신규 협력사 등록
                                        </button>
                                    )}
                                </div>
                                {canCreatePartnerInline && showInlinePartnerForm && (
                                    <div className="mt-3 rounded-lg border border-emerald-200 bg-emerald-50/60 p-3">
                                        <div className="mb-2 text-xs font-bold text-emerald-800">협력사 먼저 등록</div>
                                        <div className="grid grid-cols-1 gap-2 md:grid-cols-2">
                                            <input
                                                type="text"
                                                value={partnerDraft.name}
                                                onChange={(e) => setPartnerDraft((prev) => ({ ...prev, name: e.target.value }))}
                                                placeholder="협력사명 *"
                                                className="w-full border border-emerald-200 bg-white rounded px-2.5 py-1.5 text-sm"
                                            />
                                            <input
                                                type="text"
                                                value={partnerDraft.code}
                                                onChange={(e) => setPartnerDraft((prev) => ({ ...prev, code: e.target.value }))}
                                                placeholder="회사코드(선택)"
                                                className="w-full border border-emerald-200 bg-white rounded px-2.5 py-1.5 text-sm"
                                            />
                                            <input
                                                type="text"
                                                value={partnerDraft.ceoName}
                                                onChange={(e) => setPartnerDraft((prev) => ({ ...prev, ceoName: e.target.value }))}
                                                placeholder="대표자명(선택)"
                                                className="w-full border border-emerald-200 bg-white rounded px-2.5 py-1.5 text-sm"
                                            />
                                            <input
                                                type="text"
                                                value={partnerDraft.phone}
                                                onChange={(e) => setPartnerDraft((prev) => ({ ...prev, phone: e.target.value }))}
                                                placeholder="연락처(선택)"
                                                className="w-full border border-emerald-200 bg-white rounded px-2.5 py-1.5 text-sm"
                                            />
                                            <input
                                                type="text"
                                                value={partnerDraft.address}
                                                onChange={(e) => setPartnerDraft((prev) => ({ ...prev, address: e.target.value }))}
                                                placeholder="주소(선택)"
                                                className="w-full border border-emerald-200 bg-white rounded px-2.5 py-1.5 text-sm md:col-span-2"
                                            />
                                        </div>
                                        <div className="mt-3 flex items-center gap-2">
                                            <button
                                                type="button"
                                                onClick={handleInlinePartnerSave}
                                                disabled={isPartnerSaving}
                                                className="rounded bg-emerald-600 px-3 py-1.5 text-xs font-bold text-white hover:bg-emerald-700 disabled:opacity-50"
                                            >
                                                {isPartnerSaving ? '등록 중...' : '협력사 등록 후 선택'}
                                            </button>
                                            <button
                                                type="button"
                                                onClick={() => setShowInlinePartnerForm(false)}
                                                className="rounded border border-slate-200 bg-white px-3 py-1.5 text-xs font-medium text-slate-600 hover:bg-slate-50"
                                            >
                                                닫기
                                            </button>
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Row 3: Leader */}
                        <div className="col-span-12 grid grid-cols-12">
                            <div className="col-span-3 md:col-span-2 bg-slate-50 flex items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200">
                                팀장
                            </div>
                            <div className="col-span-9 md:col-span-10 p-2">
                                <select
                                    value={currentTeam.leaderId || ''}
                                    onChange={(e) => setCurrentTeam({ ...currentTeam, leaderId: e.target.value })}
                                    className="w-full border-slate-200 rounded text-sm py-1.5 px-3 font-medium cursor-pointer focus:ring-1 focus:ring-brand-500 focus:border-brand-500 bg-white"
                                >
                                    <option value="">선택안함</option>
                                    {workers.map(w => (
                                        <option key={w.id} value={w.id}>
                                            {w.name} ({w.teamType}/{w.role || '작업자'})
                                        </option>
                                    ))}
                                </select>
                            </div>
                        </div>

                        {/* Row 4: Bank Account */}
                        <div className="col-span-12 grid grid-cols-12">
                            <div className="col-span-3 md:col-span-2 bg-slate-50 flex items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200">
                                계좌정보
                            </div>
                            <div className="col-span-9 md:col-span-10 p-2">
                                <div className="grid grid-cols-1 gap-2 md:grid-cols-3">
                                    <input
                                        type="text"
                                        value={currentTeam.bankName || ''}
                                        onChange={(e) => setCurrentTeam({ ...currentTeam, bankName: e.target.value })}
                                        placeholder="은행명"
                                        className="w-full border-slate-200 rounded focus:ring-1 focus:ring-brand-500 focus:border-brand-500 text-sm py-1.5 px-3 shadow-sm"
                                    />
                                    <input
                                        type="text"
                                        value={currentTeam.accountNumber || ''}
                                        onChange={(e) => setCurrentTeam({ ...currentTeam, accountNumber: e.target.value })}
                                        placeholder="계좌번호"
                                        className="w-full border-slate-200 rounded focus:ring-1 focus:ring-brand-500 focus:border-brand-500 text-sm py-1.5 px-3 shadow-sm"
                                    />
                                    <input
                                        type="text"
                                        value={currentTeam.accountHolder || ''}
                                        onChange={(e) => setCurrentTeam({ ...currentTeam, accountHolder: e.target.value })}
                                        placeholder="예금주"
                                        className="w-full border-slate-200 rounded focus:ring-1 focus:ring-brand-500 focus:border-brand-500 text-sm py-1.5 px-3 shadow-sm"
                                    />
                                </div>
                            </div>
                        </div>
                    </div>
                </section>

                {/* 2. Management Setting */}
                <section className="border border-slate-300 rounded-lg overflow-hidden shadow-sm">
                    <div className="bg-slate-800 px-4 py-2.5 flex items-center justify-between">
                        <h3 className="text-sm font-bold text-white flex items-center gap-2">
                            <span className="w-2 h-2 rounded-full bg-indigo-400"></span>
                            관리 설정 (Management Setting)
                        </h3>
                    </div>

                    <div className="grid grid-cols-12 text-sm divide-y divide-slate-200 border-t border-slate-200">
                        {/* Row 1: Default Salary Model */}
                        <div className="col-span-12 grid grid-cols-12">
                            <div className="col-span-3 md:col-span-2 bg-slate-50 flex items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200">
                                기본 지급구분
                            </div>
                            <div className="col-span-9 md:col-span-10 p-2">
                                <select
                                    value={currentTeam.defaultSalaryModel || ''}
                                    onChange={(e) => setCurrentTeam({ ...currentTeam, defaultSalaryModel: e.target.value })}
                                    className="w-full border-slate-200 rounded text-sm py-1.5 px-3 font-medium cursor-pointer focus:ring-1 focus:ring-brand-500 focus:border-brand-500 bg-white"
                                >
                                    <option value="">선택안함 (개별 설정 따름)</option>
                                    {salaryModelOptions.map(v => (
                                        <option key={v} value={v}>{v}</option>
                                    ))}
                                </select>
                            </div>
                        </div>

                        {/* Row 2: Team Color */}
                        <div className="col-span-12 grid grid-cols-12">
                            <div className="col-span-3 md:col-span-2 bg-slate-50 flex items-center px-4 py-3 font-semibold text-slate-700 border-r border-slate-200">
                                팀 색상
                            </div>
                            <div className="col-span-9 md:col-span-10 p-2">
                                <div className="flex items-center gap-3">
                                    <input
                                        type="color"
                                        value={currentTeam.color || '#2563eb'}
                                        onChange={(e) => setCurrentTeam({ ...currentTeam, color: e.target.value })}
                                        className="h-8 w-8 rounded border border-slate-200 cursor-pointer p-0 shadow-sm"
                                    />
                                    <input
                                        type="text"
                                        value={currentTeam.color || ''}
                                        onChange={(e) => setCurrentTeam({ ...currentTeam, color: e.target.value })}
                                        placeholder="#2563eb"
                                        className="w-32 border-slate-200 rounded focus:ring-1 focus:ring-brand-500 focus:border-brand-500 text-sm py-1.5 px-3 font-mono shadow-sm"
                                    />
                                </div>
                            </div>
                        </div>
                    </div>
                </section>
            </div>

            {/* Footer */}
            <div className="bg-slate-50 px-6 py-4 border-t border-slate-200 flex justify-end gap-3">
                <button
                    onClick={onCancel}
                    className="px-5 py-2.5 rounded-lg text-sm font-medium text-slate-600 hover:bg-white hover:border-slate-300 border border-transparent transition-all"
                >
                    취소
                </button>
                <button
                    onClick={handleSave}
                    disabled={isSaving}
                    className="px-8 py-2.5 rounded-lg text-sm font-bold text-white bg-brand-600 hover:bg-brand-700 shadow-lg hover:shadow-brand-500/30 transition-all transform hover:-translate-y-0.5 flex items-center gap-2 disabled:opacity-60 disabled:cursor-not-allowed"
                >
                    <FontAwesomeIcon icon={faCheck} />
                    <span>{currentTeam.id ? '변경사항 저장' : '팀 등록 완료'}</span>
                </button>
            </div>
        </div>
    );
};

export default TeamForm;

import React, { useState, useEffect } from 'react';
import { teamService, Team } from '../../services/teamService';
import { manpowerService, Worker } from '../../services/manpowerService';
import { siteService, Site } from '../../services/siteService';
import { companyService, Company } from '../../services/companyService';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faPlus, faPenToSquare, faTrash, faUsers, faChevronDown, faChevronRight, faBuilding, faFileExcel, faFileImport, faFileExport } from '@fortawesome/free-solid-svg-icons';
import * as XLSX from 'xlsx';
import TeamForm from './TeamForm';

interface TeamManagementProps {
    onDataChange?: () => void;
}

const TeamManagement: React.FC<TeamManagementProps> = ({ onDataChange }) => {
    const [teams, setTeams] = useState<Team[]>([]);
    const [workers, setWorkers] = useState<Worker[]>([]);
    const [sites, setSites] = useState<Site[]>([]);
    const [companies, setCompanies] = useState<Company[]>([]);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [currentTeam, setCurrentTeam] = useState<Partial<Team>>({});
    const [isLoading, setIsLoading] = useState(true);
    const [lastDoc, setLastDoc] = useState<any>(null);
    const [hasMore, setHasMore] = useState(true);
    const [isLoadingMore, setIsLoadingMore] = useState(false);
    const LIMIT = 100;

    const [expandedTeamId, setExpandedTeamId] = useState<string | null>(null);

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const [teamsData, workersData, sitesData, companiesData] = await Promise.all([
                teamService.getTeamsPaginated(LIMIT),
                manpowerService.getWorkers(),
                siteService.getSites(),
                companyService.getCompanies()
            ]);
            setTeams(teamsData.teams);
            setLastDoc(teamsData.lastDoc);
            setHasMore(teamsData.teams.length === LIMIT);
            setWorkers(workersData);
            setSites(sitesData);
            setCompanies(companiesData);
        } catch (error) {
            console.error("Failed to fetch data", error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleLoadMore = async () => {
        if (!lastDoc || isLoadingMore) return;
        setIsLoadingMore(true);
        try {
            const result = await teamService.getTeamsPaginated(LIMIT, lastDoc);
            setTeams(prev => [...prev, ...result.teams]);
            setLastDoc(result.lastDoc);
            setHasMore(result.teams.length === LIMIT);
        } catch (error) {
            console.error("Failed to load more teams", error);
        } finally {
            setIsLoadingMore(false);
        }
    };

    const handleUpdateLeader = async (teamId: string, leaderId: string) => {
        try {
            const leader = workers.find(w => w.id === leaderId);
            const leaderName = leader ? leader.name : '';

            await teamService.updateTeam(teamId, { leaderId, leaderName });

            // Local update for immediate feedback
            setTeams(prev => prev.map(t =>
                t.id === teamId
                    ? { ...t, leaderId, leaderName }
                    : t
            ));
        } catch (error) {
            console.error("Failed to update team leader", error);
            alert("팀장 수정에 실패했습니다.");
        }
    };

    const handleDelete = async (id: string) => {
        if (window.confirm('정말 삭제하시겠습니까?')) {
            try {
                await teamService.deleteTeam(id);
                fetchData();
                if (onDataChange) onDataChange();
            } catch (error) {
                console.error("Failed to delete team", error);
                alert("삭제에 실패했습니다.");
            }
        }
    };

    const openModal = (team?: Team) => {
        setCurrentTeam(team || { type: '본팀' });
        setIsModalOpen(true);
    };

    const toggleExpand = (teamId: string) => {

        if (expandedTeamId === teamId) {
            setExpandedTeamId(null);
        } else {
            setExpandedTeamId(teamId);
        }
    };

    // Helper to count members
    const getMemberCount = (teamId?: string) => {
        if (!teamId) return 0;
        return workers.filter(w => (w as any).teamId === teamId).length;
    };

    // Helper to count sites
    const getSiteCount = (teamId?: string) => {
        if (!teamId) return 0;
        return sites.filter(s => s.responsibleTeamId === teamId).length;
    };

    const handleExcelDownload = () => {
        const data = teams.map(team => ({
            '팀명': team.name,
            '회사명': team.companyName || '',
            '팀유형': team.type,
            '팀장명': team.leaderName || ''
        }));

        if (data.length === 0) {
            data.push({
                '팀명': '예시팀',
                '회사명': '예시건설',
                '팀유형': '관리팀',
                '팀장명': '홍길동'
            });
        }

        const ws = XLSX.utils.json_to_sheet(data);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "팀목록");
        XLSX.writeFile(wb, `팀목록_${new Date().toISOString().slice(0, 10)}.xlsx`);
    };

    const handleExcelUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = async (evt) => {
            try {
                const bstr = evt.target?.result;
                const wb = XLSX.read(bstr, { type: 'binary' });
                const wsname = wb.SheetNames[0];
                const ws = wb.Sheets[wsname];
                const data = XLSX.utils.sheet_to_json(ws) as any[];

                if (data.length === 0) {
                    alert('엑셀 파일에 데이터가 없습니다.');
                    return;
                }

                setIsLoading(true);
                let successCount = 0;

                for (const row of data) {
                    const leaderName = row['팀장명'];
                    let leaderId = '';

                    if (leaderName) {
                        const leader = workers.find(w => w.name === leaderName);
                        if (leader) {
                            leaderId = leader.id!;
                        }
                    }

                    const newTeam: Team = {
                        name: row['팀명'],
                        companyName: row['회사명'],
                        type: row['팀유형'] || '관리팀',
                        leaderId: leaderId,
                        leaderName: leaderName
                    };

                    if (newTeam.name) {
                        await teamService.addTeam(newTeam);
                        successCount++;
                    }
                }

                alert(`${successCount}건의 팀이 등록되었습니다.`);
                fetchData();

            } catch (error) {
                console.error("Excel upload failed", error);
                alert("엑셀 업로드 중 오류가 발생했습니다.");
            } finally {
                setIsLoading(false);
                e.target.value = '';
            }
        };
        reader.readAsBinaryString(file);
    };

    return (
        <div className="flex flex-col h-full">
            {/* Toolbar */}
            <div className="bg-white border-b border-slate-200 p-4 flex items-center justify-between flex-shrink-0">
                <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                    <FontAwesomeIcon icon={faUsers} className="text-brand-600" /> 팀 목록
                </h2>
                <div className="flex gap-2">
                    <button
                        onClick={handleExcelDownload}
                        className="bg-green-600 text-white px-3 py-2 rounded-lg hover:bg-green-700 transition font-bold shadow-sm text-sm flex items-center"
                        title="엑셀 다운로드"
                    >
                        <FontAwesomeIcon icon={faFileExport} className="mr-2" /> 엑셀
                    </button>
                    <label className="bg-blue-500 text-white px-3 py-2 rounded-lg hover:bg-blue-600 transition font-bold shadow-sm text-sm flex items-center cursor-pointer" title="엑셀 업로드">
                        <input
                            type="file"
                            accept=".xlsx, .xls"
                            className="hidden"
                            onChange={handleExcelUpload}
                            disabled={isLoading}
                        />
                        <FontAwesomeIcon icon={faFileImport} className="mr-2" /> 업로드
                    </label>
                    <button onClick={() => openModal()} className="bg-brand-600 text-white px-4 py-2 rounded-lg hover:bg-brand-700 transition font-bold shadow-sm text-sm">
                        <FontAwesomeIcon icon={faPlus} className="mr-2" /> 팀 등록
                    </button>
                </div>
            </div>

            {/* Content Area: Table or Form */}
            <div className="flex-1 overflow-auto p-4">
                {isModalOpen ? (
                    <TeamForm
                        initialData={currentTeam}
                        teams={teams}
                        workers={workers}
                        companies={companies}
                        onSave={() => {
                            fetchData();
                            if (onDataChange) onDataChange();
                            setIsModalOpen(false);
                        }}
                        onCancel={() => setIsModalOpen(false)}
                    />
                ) : (
                    <>
                        <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
                            <table className="w-full text-left border-collapse">
                                <thead className="bg-slate-50 text-xs font-bold text-slate-500 uppercase tracking-wider">
                                    <tr>
                                        <th className="px-6 py-3 border-b border-slate-200 w-10"></th>
                                        <th className="px-6 py-3 border-b border-slate-200">팀명</th>
                                        <th className="px-6 py-3 border-b border-slate-200">회사명</th>
                                        <th className="px-6 py-3 border-b border-slate-200">팀유형</th>
                                        <th className="px-6 py-3 border-b border-slate-200">팀장</th>
                                        <th className="px-6 py-3 border-b border-slate-200">팀원 수</th>
                                        <th className="px-6 py-3 border-b border-slate-200">담당 현장</th>

                                        <th className="px-6 py-3 border-b border-slate-200 text-right">관리</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100 text-sm">
                                    {isLoading ? (
                                        <tr><td colSpan={8} className="text-center py-10">로딩중...</td></tr>
                                    ) : teams.length === 0 ? (
                                        <tr><td colSpan={8} className="text-center py-10 text-slate-400">등록된 팀이 없습니다.</td></tr>
                                    ) : (
                                        teams.map((team) => {
                                            const isExpanded = expandedTeamId === team.id;
                                            const teamSites = sites.filter(s => s.responsibleTeamId === team.id);
                                            const teamWorkers = workers.filter(w => (w as any).teamId === team.id);

                                            return (
                                                <React.Fragment key={team.id}>
                                                    <tr
                                                        className={`hover:bg-slate-50 transition-colors cursor-pointer ${isExpanded ? 'bg-slate-50' : ''}`}
                                                        onClick={() => toggleExpand(team.id!)}
                                                    >
                                                        <td className="px-6 py-4 text-slate-400">
                                                            <FontAwesomeIcon icon={isExpanded ? faChevronDown : faChevronRight} />
                                                        </td>
                                                        <td className="px-6 py-4 font-bold text-slate-800">
                                                            <div className="flex items-center gap-2">
                                                                <span
                                                                    className="inline-block w-1.5 h-6 rounded-full border border-slate-200"
                                                                    style={{ backgroundColor: team.color || '#e5e7eb' }}
                                                                />
                                                                <span>
                                                                    {team.name}
                                                                    {team.parentTeamName && (
                                                                        <span className="ml-2 text-xs text-slate-400 font-normal">
                                                                            (상위: {team.parentTeamName})
                                                                        </span>
                                                                    )}
                                                                </span>
                                                            </div>
                                                        </td>
                                                        <td className="px-6 py-4 text-slate-600">{team.companyName || '-'}</td>
                                                        <td className="px-6 py-4 text-slate-600">
                                                            <span className="bg-slate-100 px-2 py-1 rounded text-xs font-bold text-slate-600">{team.type}</span>
                                                        </td>
                                                        <td className="px-6 py-4 text-slate-600" onClick={(e) => e.stopPropagation()}>
                                                            <select
                                                                value={team.leaderId || ''}
                                                                onChange={(e) => handleUpdateLeader(team.id!, e.target.value)}
                                                                className="w-full max-w-[150px] bg-white border border-slate-300 rounded px-2 py-1 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500 transition-colors cursor-pointer"
                                                            >
                                                                <option value="">(미지정)</option>
                                                                {workers
                                                                    .sort((a, b) => a.name.localeCompare(b.name))
                                                                    .map(worker => (
                                                                        <option key={worker.id} value={worker.id!}>
                                                                            {worker.name} {worker.role && `(${worker.role})`}
                                                                        </option>
                                                                    ))}
                                                            </select>
                                                        </td>
                                                        <td className="px-6 py-4 text-slate-600">
                                                            {teamWorkers.length}명
                                                        </td>
                                                        <td className="px-6 py-4 text-slate-600">
                                                            {teamSites.length}개
                                                        </td>

                                                        <td className="px-6 py-4 text-right" onClick={(e) => e.stopPropagation()}>
                                                            <button onClick={() => openModal(team)} className="text-slate-400 hover:text-brand-600 mr-2 transition"><FontAwesomeIcon icon={faPenToSquare} /></button>
                                                            <button onClick={() => handleDelete(team.id!)} className="text-slate-400 hover:text-red-600 transition"><FontAwesomeIcon icon={faTrash} /></button>
                                                        </td>
                                                    </tr>
                                                    {isExpanded && (
                                                        <tr className="bg-slate-50">
                                                            <td colSpan={8} className="p-4 border-b border-slate-200">
                                                                <div className="flex gap-6">
                                                                    {/* Assigned Sites */}
                                                                    <div className="flex-1 bg-white rounded-lg border border-slate-200 p-4">
                                                                        <h3 className="font-bold text-slate-700 mb-3 flex items-center gap-2">
                                                                            <FontAwesomeIcon icon={faBuilding} className="text-slate-400" />
                                                                            담당 현장 ({teamSites.length})
                                                                        </h3>
                                                                        {teamSites.length === 0 ? (
                                                                            <div className="text-slate-400 text-sm text-center py-4">담당하는 현장이 없습니다.</div>
                                                                        ) : (
                                                                            <ul className="space-y-2">
                                                                                {teamSites.map(site => (
                                                                                    <li key={site.id} className="flex justify-between items-center text-sm p-2 hover:bg-slate-50 rounded border border-transparent hover:border-slate-100">
                                                                                        <span className="font-medium text-slate-700">{site.name}</span>
                                                                                        <span className={`px-2 py-0.5 rounded text-xs ${site.status === 'active' ? 'bg-emerald-100 text-emerald-700' :
                                                                                            site.status === 'completed' ? 'bg-slate-100 text-slate-500' : 'bg-orange-100 text-orange-700'
                                                                                            }`}>
                                                                                            {site.status === 'active' ? '진행중' : site.status === 'completed' ? '완료' : '예정'}
                                                                                        </span>
                                                                                    </li>
                                                                                ))}
                                                                            </ul>
                                                                        )}
                                                                    </div>

                                                                    {/* Team Members */}
                                                                    <div className="flex-1 bg-white rounded-lg border border-slate-200 p-4">
                                                                        <h3 className="font-bold text-slate-700 mb-3 flex items-center gap-2">
                                                                            <FontAwesomeIcon icon={faUsers} className="text-slate-400" />
                                                                            소속 팀원 ({teamWorkers.length})
                                                                        </h3>
                                                                        {teamWorkers.length === 0 ? (
                                                                            <div className="text-slate-400 text-sm text-center py-4">소속된 팀원이 없습니다.</div>
                                                                        ) : (
                                                                            <ul className="space-y-2 max-h-60 overflow-y-auto pr-2">
                                                                                {teamWorkers.map(worker => (
                                                                                    <li key={worker.id} className="flex justify-between items-center text-sm p-2 hover:bg-slate-50 rounded border border-transparent hover:border-slate-100">
                                                                                        <div className="flex items-center gap-2">
                                                                                            <span className="w-6 h-6 bg-slate-100 text-slate-500 rounded-full flex items-center justify-center text-xs font-bold">
                                                                                                {worker.name[0]}
                                                                                            </span>
                                                                                            <span className="font-medium text-slate-700">{worker.name}</span>
                                                                                        </div>
                                                                                        <span className="text-slate-500 text-xs">{worker.role || '작업자'}</span>
                                                                                    </li>
                                                                                ))}
                                                                            </ul>
                                                                        )}
                                                                    </div>
                                                                </div>
                                                            </td>
                                                        </tr>
                                                    )}
                                                </React.Fragment>
                                            );
                                        })
                                    )}
                                </tbody>
                            </table>
                        </div>
                        {/* Load More Button */}
                        {hasMore && (
                            <div className="flex justify-center py-4">
                                <button
                                    onClick={handleLoadMore}
                                    disabled={isLoadingMore}
                                    className="px-6 py-2 bg-white border border-slate-200 rounded-full text-slate-600 font-bold hover:bg-slate-50 transition shadow-sm disabled:opacity-50"
                                >
                                    {isLoadingMore ? '로딩 중...' : '더보기 (100개)'}
                                </button>
                            </div>
                        )}
                    </>
                )}
            </div>
        </div >
    );
};

export default TeamManagement;

import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faUsers, faUser, faPlus, faSearch, faEdit, faTrash, faPenToSquare,
    faImages, faLink, faDownload, faCheckSquare, faSquare, faTable, faMoneyCheck, faBuilding,
    faGripVertical, faIdCard, faChevronUp, faChevronDown, IconDefinition
} from '@fortawesome/free-solid-svg-icons';

import { manpowerService, Worker } from '../../services/manpowerService';
import { teamService, Team } from '../../services/teamService';
import { siteService, Site } from '../../services/siteService';
import { companyService, Company } from '../../services/companyService';
import { positionService, Position } from '../../services/positionService';
import { storage } from '../../config/firebase';
import { ref, uploadBytes, getDownloadURL, getBlob, updateMetadata } from 'firebase/storage';
import JSZip from 'jszip';
import { saveAs } from 'file-saver';
import AccountLinkingModal from './AccountLinkingModal';
import BulkProgressModal from './BulkProgressModal';
import BulkEditWorkerModal from './BulkEditWorkerModal';
import BankBookAnalysisModal from './BankBookAnalysisModal';
import IdCardAnalysisModal from './IdCardAnalysisModal';
import WorkerModal from '../../pages/manpower/WorkerModal';
import { useColumnSettings } from '../../hooks/useColumnSettings';

import { resolveIcon } from '../../constants/iconMap';

// 아이콘 맵핑 (문자열 → 실제 아이콘) -> Removed in favor of resolveIcon


const WORKER_COLUMNS = [
    { key: 'name', label: '이름' },
    { key: 'idNumber', label: '주민번호' },
    { key: 'contact', label: '연락처' },
    { key: 'address', label: '주소' },
    { key: 'role', label: '직책' },
    { key: 'payType', label: '구분' },
    { key: 'teamName', label: '팀명' },
    { key: 'companyName', label: '회사' },
    { key: 'status', label: '상태' },
    { key: 'unitPrice', label: '단가' },
    { key: 'bankName', label: '은행' },
    { key: 'accountNumber', label: '계좌번호' },
    { key: 'accountHolder', label: '예금주' },
];

const QUICK_VIEW_PERSONAL_COLUMNS = ['name', 'idNumber', 'contact', 'address', 'unitPrice', 'bankName', 'accountNumber', 'accountHolder'];
const QUICK_VIEW_WORK_COLUMNS = ['name', 'role', 'payType', 'teamName', 'companyName', 'status'];

// 드래그 가능한 열 아이템 컴포넌트


const WorkerManagement: React.FC = () => {
    const [workers, setWorkers] = useState<Worker[]>([]);
    const [teams, setTeams] = useState<Team[]>([]);
    const [sites, setSites] = useState<Site[]>([]);
    const [companies, setCompanies] = useState<Company[]>([]);
    const [positions, setPositions] = useState<Position[]>([]); // 직책 데이터
    const [searchTerm, setSearchTerm] = useState('');
    const [loading, setLoading] = useState(false);
    const { currentUser } = useAuth();
    const hideHeader = false;
    const highlightedId: string | null = null;

    const {
        visibleColumns,
        toggleColumn,
        showColumnSettings,
        setShowColumnSettings,
        moveColumn,
        getOrderedColumns,
        columnOrder
    } = useColumnSettings('worker_registration_visible_columns', WORKER_COLUMNS);

    const [quickColumnView, setQuickColumnView] = useState<'personal' | 'work' | ''>('');

    const orderedColumns = getOrderedColumns();
    const effectiveOrderedColumns = quickColumnView === 'personal'
        ? columnOrder.filter((key) => QUICK_VIEW_PERSONAL_COLUMNS.includes(key))
        : (quickColumnView === 'work'
            ? columnOrder.filter((key) => QUICK_VIEW_WORK_COLUMNS.includes(key))
            : orderedColumns);
    const tableColSpan = effectiveOrderedColumns.length + 2;

    const applyQuickView = (next: 'personal' | 'work') => {
        setShowColumnSettings(false);
        setQuickColumnView((prev) => (prev === next ? '' : next));
    };

    // Bulk Actions State
    const [selectedWorkerIds, setSelectedWorkerIds] = useState<string[]>([]);
    const [showLinkingModal, setShowLinkingModal] = useState(false);
    const [isBulkProgressOpen, setIsBulkProgressOpen] = useState(false);
    const [isBulkEditOpen, setIsBulkEditOpen] = useState(false);
    const [bulkProgress, setBulkProgress] = useState({ current: 0, total: 0, success: 0, fail: 0 });
    const [bulkLogs, setBulkLogs] = useState<string[]>([]);
    const [isBankBookModalOpen, setIsBankBookModalOpen] = useState(false);
    const [isIdCardAnalysisModalOpen, setIsIdCardAnalysisModalOpen] = useState(false);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [currentWorker, setCurrentWorker] = useState<Worker | null>(null);
    const [isEditMode, setIsEditMode] = useState(false);
    const [showInactive, setShowInactive] = useState(false); // Default: Hide inactive workers

    // Highlight scroll control (for Data Integrity "관리" navigation)
    const highlightScrolledRef = useRef(false);
    const lastHighlightIdRef = useRef<string | null>(null);

    // Handlers for Inline Editing
    const handleWorkerChange = (id: string, field: keyof Worker, value: any) => {
        setWorkers(prev => prev.map(w => w.id === id ? { ...w, [field]: value } : w));
    };

    const handleWorkerBlur = async (id: string, field: keyof Worker, value: any) => {
        try {
            await manpowerService.updateWorker(id, { [field]: value });
        } catch (error) {
            console.error("Update failed", error);
            fetchWorkers(); // Revert on error
        }
    };

    // 상태 값을 화면/기존 데이터 형식에 맞게 정규화
    const getCanonicalStatus = (status?: string): string => {
        if (!status) return '미배정';
        if (status === 'active') return '재직';
        if (status === 'inactive') return '퇴사';
        return status;
    };

    // 목록에서 바로 상태 변경 (토글/셀렉트 공통 사용)
    const handleStatusChange = async (workerId: string, newStatus: string) => {
        if (!workerId) return;

        // Optimistic UI 업데이트
        setWorkers(prev => prev.map(w => w.id === workerId ? { ...w, status: newStatus } : w));

        try {
            await manpowerService.updateWorker(workerId, { status: newStatus });
        } catch (error) {
            console.error('Failed to update worker status', error);
            alert('상태 변경에 실패했습니다. 다시 시도해 주세요.');
            // 실패 시 최신 데이터로 롤백
            fetchWorkers();
        }
    };

    const handleWorkerTeamSelect = async (workerId: string, teamId: string) => {
        if (!teamId) {
            // Unassign
            setWorkers(prev => prev.map(w => w.id === workerId ? { ...w, teamId: '', teamName: '', teamType: '미배정' } : w));
            await manpowerService.updateWorker(workerId, { teamId: '', teamName: '', teamType: '미배정' });
            return;
        }

        const team = teams.find(t => t.id === teamId);
        if (team) {
            // 팀의 회사 정보도 함께 설정
            const teamCompany = team.companyId ? companies.find(c => c.id === team.companyId) : null;

            // 회사 유형에 따라 급여방식 결정 (협력사면 지원팀, 아니면 팀의 defaultSalaryModel 우선 적용)
            const worker = workers.find(w => w.id === workerId);
            const isPartnerCompany = teamCompany?.type === '협력사';
            const newSalaryModel = isPartnerCompany ? '지원팀' : (worker?.payType || team.defaultSalaryModel || '일급제');

            const updates = {
                teamId: team.id,
                teamName: team.name,
                teamType: team.type,
                companyId: team.companyId || '',
                companyName: team.companyName || '',
                salaryModel: newSalaryModel,
                payType: newSalaryModel
            };

            setWorkers(prev => prev.map(w => w.id === workerId ? { ...w, ...updates } : w));
            try {
                await manpowerService.updateWorker(workerId, updates);
            } catch (e) {
                console.error(e);
                fetchWorkers();
            }
        }
    };

    const handleWorkerSiteSelect = async (workerId: string, siteId: string) => {
        if (!siteId) {
            setWorkers(prev => prev.map(w => w.id === workerId ? { ...w, siteId: '', siteName: '' } : w));
            await manpowerService.updateWorker(workerId, { siteId: '', siteName: '' });
            return;
        }
        const site = sites.find(s => s.id === siteId);
        if (site) {
            setWorkers(prev => prev.map(w => w.id === workerId ? { ...w, siteId: site.id, siteName: site.name } : w));
            await manpowerService.updateWorker(workerId, { siteId: site.id, siteName: site.name });
        }
    }

    const handleWorkerCompanySelect = async (workerId: string, companyId: string) => {
        if (!companyId) {
            setWorkers(prev => prev.map(w => w.id === workerId ? { ...w, companyId: '', companyName: '' } : w));
            await manpowerService.updateWorker(workerId, { companyId: '', companyName: '' });
            return;
        }
        const company = companies.find(c => c.id === companyId);
        if (company) {
            setWorkers(prev => prev.map(w => w.id === workerId ? { ...w, companyId: company.id, companyName: company.name } : w));
            await manpowerService.updateWorker(workerId, { companyId: company.id, companyName: company.name });
        }
    }

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setLoading(true);
        try {
            const [workersData, teamsData, sitesData, companiesData, positionsData] = await Promise.all([
                manpowerService.getWorkers(),
                teamService.getTeams(),
                siteService.getSites(),
                companyService.getCompanies(),
                positionService.getPositions()
            ]);

            setWorkers(workersData);
            setTeams(teamsData);
            setSites(sitesData);
            setCompanies(companiesData);
            setPositions(positionsData);
        } catch (error) {
            console.error("Failed to fetch data:", error);
        } finally {
            setLoading(false);
        }
    };

    const fetchWorkers = async () => {
        try {
            const workersData = await manpowerService.getWorkers();
            setWorkers(workersData);
        } catch (error) {
            console.error("Failed to fetch workers:", error);
        }
    };

    // 작업자 삭제
    const handleDelete = async (workerId: string, workerName: string) => {
        if (window.confirm(`[${workerName}] 작업자를 퇴사 처리하시겠습니까? (일보 이력은 유지됩니다)`)) {
            try {
                await manpowerService.retireWorker(workerId);
                alert('작업자가 퇴사 처리되었습니다.');
                await fetchWorkers();
            } catch (error) {
                console.error("삭제 실패:", error);
                alert("작업자 퇴사 처리에 실패했습니다.");
            }
        }
    };

    // 필터링된 작업자 목록 (Memoized)
    const filteredWorkers = React.useMemo(() => {
        return workers.filter(worker => {
            const lowerSearch = searchTerm.toLowerCase();

            // Status filter: If showInactive is false, only show 'active'/'재직' or 'unassigned'/'미배정'.
            const isActive = worker.status === '재직' || worker.status === 'active' || worker.status === '미배정' || !worker.status;
            if (!showInactive && !isActive) return false;

            return (
                worker.name.toLowerCase().includes(lowerSearch) ||
                (worker.idNumber ?? '').includes(lowerSearch) ||
                (worker.contact && worker.contact.includes(lowerSearch))
            );
        });
    }, [workers, searchTerm, showInactive]);

    // 선택 기능
    const toggleSelectAll = () => {
        if (selectedWorkerIds.length === filteredWorkers.length && filteredWorkers.length > 0) {
            setSelectedWorkerIds([]);
        } else {
            setSelectedWorkerIds(filteredWorkers.map(w => w.id!).filter(Boolean));
        }
    };

    const toggleSelectWorker = (id: string) => {
        if (selectedWorkerIds.includes(id)) {
            setSelectedWorkerIds(selectedWorkerIds.filter(wid => wid !== id));
        } else {
            setSelectedWorkerIds([...selectedWorkerIds, id]);
        }
    };

    // 일괄 삭제
    const handleBulkDelete = async () => {
        if (selectedWorkerIds.length === 0) return;

        if (window.confirm(`선택한 ${selectedWorkerIds.length}명의 작업자를 정말 퇴사 처리하시겠습니까? (일보 이력은 유지됩니다)`)) {
            try {
                await manpowerService.retireWorkers(selectedWorkerIds);
                setSelectedWorkerIds([]);
                await fetchWorkers();
                alert("일괄 퇴사 처리되었습니다.");
            } catch (error) {
                console.error("Failed to delete workers", error);
                alert("일괄 퇴사 처리에 실패했습니다.");
            }
        }
    };



    // 선택 항목 다운로드 (신분증)
    const handleBulkDownload = async () => {
        if (selectedWorkerIds.length === 0) return;

        const workersToDownload = workers.filter(w => selectedWorkerIds.includes(w.id!) && w.fileNameSaved);
        if (workersToDownload.length === 0) {
            alert("선택한 작업자 중 다운로드할 신분증 이미지가 없습니다.");
            return;
        }

        setIsBulkProgressOpen(true);
        setBulkProgress({ current: 0, total: workersToDownload.length, success: 0, fail: 0 });
        setBulkLogs([]);

        const zip = new JSZip();
        let successCount = 0;
        let failCount = 0;

        for (let i = 0; i < workersToDownload.length; i++) {
            const worker = workersToDownload[i];
            setBulkProgress(prev => ({ ...prev, current: i + 1 }));

            try {
                // Use getBlob directly from SDK
                const blob = await getBlob(ref(storage, worker.fileNameSaved!));

                const ext = worker.fileNameSaved!.split('.').pop() || 'jpg';
                const cleanName = (worker.name || '').replace(/[0-9]/g, '');
                const filename = `${cleanName}_${worker.idNumber}.${ext}`;

                zip.file(filename, blob);

                successCount++;
                setBulkLogs(prev => [`[성공] ${worker.name} 이미지 다운로드 완료`, ...prev]);
            } catch (error: any) {
                console.error(error);
                failCount++;
                // Try to provide a helpful error message
                let msg = error.code === 'storage/unauthorized' ? '권한 없음' :
                    error.code === 'storage/object-not-found' ? '파일 없음' :
                        error.message;
                setBulkLogs(prev => [`[실패] ${worker.name}: ${msg}`, ...prev]);
            }
            setBulkProgress(prev => ({ ...prev, success: successCount, fail: failCount }));
        }

        if (successCount > 0) {
            setBulkLogs(prev => [`[압축] 파일 압축 중...`, ...prev]);
            try {
                const content = await zip.generateAsync({ type: "blob" });
                saveAs(content, `신분증_모음_${new Date().toISOString().slice(0, 10)}.zip`);
                setBulkLogs(prev => [`[완료] 다운로드 시작`, ...prev]);
            } catch (zipError) {
                console.error("Zip generation failed:", zipError);
                setBulkLogs(prev => [`[오류] 압축 파일 생성 실패`, ...prev]);
            }
        } else {
            setBulkLogs(prev => [`[알림] 다운로드 가능한 파일이 없습니다.`, ...prev]);
        }
    };



    // 개별 신분증 다운로드 (Blob 방식 - CORS 해결)
    const handleDownloadIdCard = async (worker: Worker) => {
        if (!worker.fileNameSaved) {
            alert("등록된 신분증 이미지가 없습니다.");
            return;
        }

        try {
            const fileRef = ref(storage, worker.fileNameSaved);
            const url = await getDownloadURL(fileRef);

            const ext = worker.fileNameSaved.split('.').pop() || 'jpg';
            const safeIdNumber = worker.idNumber || '미등록';
            const cleanName = (worker.name || '').replace(/[0-9]/g, '');
            const filename = `${cleanName}_${safeIdNumber}.${ext}`;

            const downloadUrl = new URL(url);
            downloadUrl.searchParams.set(
                'response-content-disposition',
                `attachment; filename*=UTF-8''${encodeURIComponent(filename)}`
            );

            const link = document.createElement('a');
            link.href = downloadUrl.toString();
            link.rel = 'noopener noreferrer';
            link.style.display = 'none';
            document.body.appendChild(link);
            link.click();
            link.remove();

        } catch (error: unknown) {
            console.error("Download failed:", error);
            alert("다운로드에 실패했습니다. (파일을 찾을 수 없거나 권한 부족)");
        }
    };

    const handleSaveWorker = async (workerData: Omit<Worker, 'id'> | Partial<Worker>) => {
        try {
            if (currentWorker && currentWorker.id) {
                await manpowerService.updateWorker(currentWorker.id, workerData);
            } else {
                await manpowerService.addWorker(workerData as Omit<Worker, 'id'>);
            }
            fetchWorkers();
            setIsModalOpen(false);
        } catch (error) {
            console.error("Failed to save worker", error);
            alert("저장에 실패했습니다.");
        }
    };

    const handleBankBookUpdate = async (updates: { workerId: string, bankName: string, accountNumber: string, accountHolder: string }[]) => {
        setLoading(true);
        try {
            await Promise.all(updates.map(update =>
                manpowerService.updateWorker(update.workerId, {
                    bankName: update.bankName,
                    accountNumber: update.accountNumber,
                    accountHolder: update.accountHolder
                })
            ));
            alert(`${updates.length}명의 계좌정보가 업데이트되었습니다.`);
            await fetchData(); // 데이터 새로고침
        } catch (error) {
            console.error("Batch update failed", error);
            alert("일부 업데이트에 실패했습니다.");
        } finally {
            setLoading(false);
        }
    };

    const handleIdCardRegister = async (newWorkers: {
        name: string,
        idNumber: string,
        address: string,
        file: File,
        matchType: 'new' | 'update' | 'duplicate',
        matchedWorkerId?: string
    }[]) => {
        setLoading(true);
        setIsBulkProgressOpen(true);
        setBulkProgress({ current: 0, total: newWorkers.length, success: 0, fail: 0 });
        setBulkLogs([]);

        let successCount = 0;
        let failCount = 0;

        for (let i = 0; i < newWorkers.length; i++) {
            const worker = newWorkers[i];
            setBulkProgress(prev => ({ ...prev, current: i + 1 }));

            try {
                // 1. Upload image to Firebase Storage
                const storagePath = `id_cards/${Date.now()}_${worker.file.name}`;
                const storageRef = ref(storage, storagePath);
                await uploadBytes(storageRef, worker.file);

                // 2. 분기 처리: 신규 / 업데이트 / 중복
                let processed = false;

                if (worker.matchType === 'new') {
                    // 신규 작업자 생성
                    await manpowerService.addWorker({
                        name: worker.name,
                        idNumber: worker.idNumber,
                        address: worker.address,
                        role: '작업자',
                        teamType: '미배정',
                        status: '미배정',
                        unitPrice: 0,
                        fileNameSaved: storagePath
                    });
                    setBulkLogs(prev => [`[신규] ${worker.name} 등록 완료`, ...prev]);
                    processed = true;
                } else if (worker.matchType === 'update' && worker.matchedWorkerId) {
                    // 기존 작업자 업데이트 (누락 필드만)
                    const updates: Partial<Worker> = { fileNameSaved: storagePath };
                    if (worker.name) updates.name = worker.name;
                    if (worker.idNumber) updates.idNumber = worker.idNumber;
                    if (worker.address) updates.address = worker.address;

                    await manpowerService.updateWorker(worker.matchedWorkerId, updates);
                    setBulkLogs(prev => [`[업데이트] ${worker.name} 정보 보충 완료`, ...prev]);
                    processed = true;
                } else if (worker.matchType === 'duplicate' && worker.matchedWorkerId) {
                    // 중복 - 사진만 업데이트
                    await manpowerService.updateWorker(worker.matchedWorkerId, {
                        fileNameSaved: storagePath
                    });
                    setBulkLogs(prev => [`[사진] ${worker.name} 신분증 사진 업데이트`, ...prev]);
                    processed = true;
                }

                if (processed) {
                    successCount++;
                } else {
                    failCount++;
                    const reason = !worker.matchedWorkerId ? '매칭된 작업자 ID 없음' : '알 수 없는 유형';
                    setBulkLogs(prev => [`[실패] ${worker.name}: 처리되지 않음 (${worker.matchType}, ${reason})`, ...prev]);
                }
            } catch (error: any) {
                console.error(error);
                failCount++;
                setBulkLogs(prev => [`[실패] ${worker.name}: ${error.message}`, ...prev]);
            }
            setBulkProgress(prev => ({ ...prev, success: successCount, fail: failCount }));
        }

        setLoading(false);
        fetchWorkers();
        // Keep progress modal open to show results
    };

    return (
        <div className="flex flex-col h-full bg-slate-50">
            {/* Header & Toolbar - Single Row */}
            <div className="bg-white border-b border-slate-200 p-4 flex flex-col xl:flex-row items-start xl:items-center justify-between gap-4 flex-shrink-0">
                <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2 whitespace-nowrap">
                    <FontAwesomeIcon icon={faUsers} className="text-blue-600" />
                    작업자 등록 관리
                </h2>

                <div className="flex flex-wrap items-center gap-2 w-full xl:w-auto xl:ml-auto justify-end">
                    {/* 열 설정 */}
                    {/* 열 설정 */}
                    <div className="relative inline-block">
                        <button
                            onClick={() => setShowColumnSettings(!showColumnSettings)}
                            className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 text-slate-600 rounded-lg hover:bg-slate-50 transition-colors shadow-sm whitespace-nowrap"
                        >
                            <FontAwesomeIcon icon={faTable} />
                            <span className="hidden sm:inline">열 설정</span>
                        </button>

                        {showColumnSettings && (
                            <div className="absolute top-full right-0 mt-2 w-64 bg-white rounded-lg shadow-xl border border-slate-200 z-50 p-2 text-left">
                                <div className="text-xs font-bold text-slate-500 mb-2 px-2">열 설정 (순서 변경 가능)</div>
                                <div className="space-y-1 max-h-80 overflow-y-auto">
                                    {columnOrder.map((key, index) => {
                                        const col = WORKER_COLUMNS.find(c => c.key === key);
                                        if (!col) return null;
                                        const isFirst = index === 0;
                                        const isLast = index === columnOrder.length - 1;

                                        return (
                                            <div key={key} className="flex items-center gap-2 px-2 py-1.5 hover:bg-slate-50 rounded group">
                                                <label className="flex items-center gap-2 flex-1 cursor-pointer">
                                                    <input
                                                        type="checkbox"
                                                        checked={visibleColumns.includes(key)}
                                                        onChange={() => toggleColumn(key)}
                                                        className="rounded text-indigo-600 focus:ring-indigo-500"
                                                    />
                                                    <span className="text-sm text-slate-700">{col.label}</span>
                                                </label>
                                                <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button
                                                        onClick={(e) => {
                                                            e.stopPropagation();
                                                            if (!isFirst) moveColumn(index, index - 1);
                                                        }}
                                                        disabled={isFirst}
                                                        className={`p-1 rounded hover:bg-slate-200 ${isFirst ? 'text-slate-300' : 'text-slate-500'}`}
                                                    >
                                                        <FontAwesomeIcon icon={faChevronUp} size="xs" />
                                                    </button>
                                                    <button
                                                        onClick={(e) => {
                                                            e.stopPropagation();
                                                            if (!isLast) moveColumn(index, index + 1);
                                                        }}
                                                        disabled={isLast}
                                                        className={`p-1 rounded hover:bg-slate-200 ${isLast ? 'text-slate-300' : 'text-slate-500'}`}
                                                    >
                                                        <FontAwesomeIcon icon={faChevronDown} size="xs" />
                                                    </button>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                                <div className="fixed inset-0 -z-10" onClick={() => setShowColumnSettings(false)}></div>
                            </div>
                        )}
                    </div>

                    <button
                        onClick={() => applyQuickView('personal')}
                        className={`flex items-center gap-2 px-3 py-2 rounded-lg transition-all shadow-sm whitespace-nowrap ${quickColumnView === 'personal'
                            ? 'bg-blue-100 text-blue-700 border border-blue-200'
                            : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'
                            }`}
                    >
                        <FontAwesomeIcon icon={faMoneyCheck} />
                        <span className="hidden sm:inline">개인/급여</span>
                    </button>

                    <button
                        onClick={() => applyQuickView('work')}
                        className={`flex items-center gap-2 px-3 py-2 rounded-lg transition-all shadow-sm whitespace-nowrap ${quickColumnView === 'work'
                            ? 'bg-emerald-100 text-emerald-700 border border-emerald-200'
                            : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'
                            }`}
                    >
                        <FontAwesomeIcon icon={faUsers} />
                        <span className="hidden sm:inline">소속/상태</span>
                    </button>

                    {/* 계정 연결 */}
                    <button
                        onClick={() => setShowLinkingModal(true)}
                        title="계정 연동"
                        className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 text-slate-600 rounded-lg hover:bg-slate-50 transition-colors shadow-sm whitespace-nowrap"
                    >
                        <FontAwesomeIcon icon={faLink} className="text-slate-500" />
                        <span className="hidden sm:inline">계정 연결</span>
                    </button>

                    {/* 신분증 등록 */}
                    <button
                        onClick={() => setIsIdCardAnalysisModalOpen(true)}
                        title="신분증 대량 등록 (AI)"
                        className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 text-slate-600 rounded-lg hover:bg-slate-50 transition-colors shadow-sm whitespace-nowrap"
                    >
                        <FontAwesomeIcon icon={faImages} className="text-brand-600" />
                        <span className="hidden sm:inline">신분증 등록</span>
                    </button>

                    {/* 수정모드 */}
                    <button
                        onClick={() => setIsEditMode(!isEditMode)}
                        className={`flex items-center gap-2 px-3 py-2 rounded-lg transition-all shadow-sm whitespace-nowrap ${isEditMode
                            ? 'bg-indigo-100 text-indigo-700 border border-indigo-200'
                            : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'
                            }`}
                    >
                        <FontAwesomeIcon icon={faPenToSquare} />
                        <span className="hidden sm:inline">{isEditMode ? '수정 종료' : '수정모드'}</span>
                    </button>

                    {/* 선택 다운로드 */}
                    <button
                        onClick={handleBulkDownload}
                        disabled={selectedWorkerIds.length === 0}
                        title="선택 항목 다운로드"
                        className={`flex items-center gap-2 px-3 py-2 rounded-lg transition-all shadow-sm whitespace-nowrap ${selectedWorkerIds.length > 0
                            ? 'bg-blue-100 text-blue-600 hover:bg-blue-200 border border-blue-200'
                            : 'bg-slate-100 text-slate-400 cursor-not-allowed'
                            }`}
                    >
                        <FontAwesomeIcon icon={faDownload} />
                        <span className="hidden sm:inline">선택 다운로드</span>
                    </button>

                    {/* 일괄 수정 */}
                    <button
                        onClick={() => setIsBulkEditOpen(true)}
                        disabled={selectedWorkerIds.length === 0}
                        title="일괄 수정"
                        className={`flex items-center gap-2 px-3 py-2 rounded-lg transition-all shadow-sm whitespace-nowrap ${selectedWorkerIds.length > 0
                            ? 'bg-indigo-100 text-indigo-600 hover:bg-indigo-200 border border-indigo-200'
                            : 'bg-slate-100 text-slate-400 cursor-not-allowed'
                            }`}
                    >
                        <FontAwesomeIcon icon={faEdit} />
                        <span className="hidden sm:inline">일괄 수정</span>
                    </button>

                    {/* 일괄 삭제 */}
                    <button
                        onClick={handleBulkDelete}
                        disabled={selectedWorkerIds.length === 0}
                        title="일괄 삭제"
                        className={`flex items-center gap-2 px-3 py-2 rounded-lg transition-all shadow-sm whitespace-nowrap ${selectedWorkerIds.length > 0
                            ? 'bg-red-100 text-red-600 hover:bg-red-200 border border-red-200'
                            : 'bg-slate-100 text-slate-400 cursor-not-allowed'
                            }`}
                    >
                        <FontAwesomeIcon icon={faTrash} />
                        <span className="hidden sm:inline">일괄 삭제</span>
                    </button>

                    {/* 근로자 등록 */}
                    <button
                        onClick={() => {
                            setCurrentWorker(null);
                            setIsModalOpen(true);
                        }}
                        title="근로자 등록"
                        className="flex items-center gap-2 px-3 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors shadow-sm shadow-indigo-200 whitespace-nowrap ml-auto xl:ml-0"
                    >
                        <FontAwesomeIcon icon={faPlus} />
                        근로자 등록
                    </button>
                </div>
            </div>

            {/* 검색 및 목록 - Content Area */}
            <div className="flex-1 overflow-auto p-4 md:p-6">
                <div className="bg-white border border-gray-200 rounded-lg shadow-sm">
                    <div className="p-4 border-b border-gray-200 flex items-center justify-between">
                        <h3 className="text-md font-semibold text-gray-800 flex items-center gap-2">
                            <FontAwesomeIcon icon={faUsers} className="text-blue-600" />
                            등록된 작업자 ({filteredWorkers.length}명)
                        </h3>
                        <div className="flex items-center gap-4">
                            <label className="flex items-center gap-2 text-sm text-gray-600 cursor-pointer">
                                <input
                                    type="checkbox"
                                    checked={showInactive}
                                    onChange={(e) => setShowInactive(e.target.checked)}
                                    className="rounded text-indigo-600 focus:ring-indigo-500"
                                />
                                퇴사자 포함
                            </label>
                            <div className="flex items-center gap-2">
                                <FontAwesomeIcon icon={faSearch} className="text-gray-400" />
                                <input
                                    type="text"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    placeholder="이름, 주민번호, 연락처 검색"
                                    className="px-3 py-1 border border-gray-300 rounded text-sm focus:ring-1 focus:ring-blue-500 focus:border-blue-500 w-64"
                                />
                            </div>
                        </div>
                    </div>

                    <div className="overflow-auto max-h-[calc(100vh-250px)]">
                        <table className="w-full text-sm">
                            <thead className="bg-gray-50 border-b border-gray-200 sticky top-0 z-10">
                                <tr>
                                    <th className="px-4 py-3 text-center w-12 bg-gray-50">
                                        <button onClick={toggleSelectAll} className="text-gray-500 hover:text-gray-700">
                                            <FontAwesomeIcon icon={selectedWorkerIds.length === filteredWorkers.length && filteredWorkers.length > 0 ? faCheckSquare : faSquare} />
                                        </button>
                                    </th>
                                    {effectiveOrderedColumns.map(key => {
                                        const col = WORKER_COLUMNS.find(c => c.key === key);
                                        if (!col) return null;
                                        return (
                                            <th key={col.key} className={`px-4 py-3 text-${col.key === 'unitPrice' ? 'right' : 'left'} font-medium text-gray-700 bg-gray-50`}>
                                                {col.label}
                                            </th>
                                        );
                                    })}
                                    <th className="px-4 py-3 text-center font-medium text-gray-700 bg-gray-50">관리</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {loading ? (
                                    <tr>
                                        <td colSpan={tableColSpan} className="px-4 py-8 text-center text-gray-500">
                                            데이터를 불러오는 중입니다...
                                        </td>
                                    </tr>
                                ) : filteredWorkers.length === 0 ? (
                                    <tr>
                                        <td colSpan={tableColSpan} className="px-4 py-8 text-center text-gray-500">
                                            등록된 작업자가 없습니다.
                                        </td>
                                    </tr>
                                ) : (
                                    filteredWorkers.map((worker) => {
                                        const isInactive = worker.status === '퇴사' || worker.status === 'inactive' || worker.status === '출입금지';
                                        const workerTeam = worker.teamId ? teams.find(t => t.id === worker.teamId) : undefined;
                                        const workerCompany = worker.companyId ? companies.find(c => c.id === worker.companyId) : undefined;
                                        const iconColor = workerTeam?.color || worker.color || '#e5e7eb';

                                        return (
                                            <tr
                                                key={worker.id}
                                                className={`border-b transition-colors 
                                                    ${selectedWorkerIds.includes(worker.id!) ? 'bg-indigo-50' : 'hover:bg-gray-50'} 
                                                    ${isInactive ? 'bg-slate-50 text-slate-400' : ''}
                                                `}
                                            >
                                                <td className="px-4 py-3 text-center">
                                                    <button onClick={() => toggleSelectWorker(worker.id!)} className={`${selectedWorkerIds.includes(worker.id!) ? 'text-indigo-600' : 'text-gray-400'} hover:text-indigo-600`}>
                                                        <FontAwesomeIcon icon={selectedWorkerIds.includes(worker.id!) ? faCheckSquare : faSquare} />
                                                    </button>
                                                </td>
                                                {effectiveOrderedColumns.map(key => {
                                                    const col = WORKER_COLUMNS.find(c => c.key === key);
                                                    if (!col) return null;

                                                    return (
                                                        <td key={key} className={`px-4 py-3 ${key === 'unitPrice' ? 'text-right' : 'text-left'} ${key === 'name' ? 'font-medium text-gray-900' : 'text-gray-600'}`}>
                                                            {(() => {
                                                                switch (key) {
                                                                    case 'name': return isEditMode ? (
                                                                        <div className="flex items-center gap-2">
                                                                            <input
                                                                                type="color"
                                                                                value={worker.color || '#0f766e'}
                                                                                onChange={(e) => handleWorkerChange(worker.id!, 'color', e.target.value)}
                                                                                onBlur={(e) => handleWorkerBlur(worker.id!, 'color', e.target.value)}
                                                                                className="h-8 w-8 rounded border border-slate-300 cursor-pointer"
                                                                            />
                                                                            <input
                                                                                type="text"
                                                                                value={worker.name || ''}
                                                                                onChange={(e) => handleWorkerChange(worker.id!, 'name', e.target.value)}
                                                                                onBlur={(e) => handleWorkerBlur(worker.id!, 'name', e.target.value)}
                                                                                className="w-full border rounded px-2 py-1 text-sm"
                                                                            />
                                                                        </div>
                                                                    ) : (
                                                                        <div className="flex items-center gap-2">
                                                                            <span
                                                                                className="inline-flex items-center justify-center w-7 h-7 rounded-full border border-slate-200 flex-shrink-0"
                                                                                style={{ backgroundColor: iconColor }}
                                                                            >
                                                                                <FontAwesomeIcon icon={faUser} className="text-white text-xs" />
                                                                            </span>
                                                                            <span className="truncate">{worker.name}</span>
                                                                            {worker.fileNameSaved && (
                                                                                <button
                                                                                    onClick={(e) => {
                                                                                        e.stopPropagation();
                                                                                        handleDownloadIdCard(worker);
                                                                                    }}
                                                                                    className="text-slate-400 hover:text-indigo-600 transition-colors ml-1"
                                                                                    title="신분증 다운로드"
                                                                                >
                                                                                    <FontAwesomeIcon icon={faIdCard} size="sm" />
                                                                                </button>
                                                                            )}
                                                                            {isInactive && <span className="px-1.5 py-0.5 rounded text-[10px] bg-gray-200 text-gray-500">퇴사</span>}
                                                                        </div>
                                                                    );
                                                                    case 'idNumber': return isEditMode ? (
                                                                        <input
                                                                            type="text"
                                                                            value={worker.idNumber || ''}
                                                                            onChange={(e) => handleWorkerChange(worker.id!, 'idNumber', e.target.value)}
                                                                            onBlur={(e) => handleWorkerBlur(worker.id!, 'idNumber', e.target.value)}
                                                                            className="w-full border rounded px-2 py-1 text-sm"
                                                                        />
                                                                    ) : worker.idNumber;
                                                                    case 'contact': return isEditMode ? (
                                                                        <input
                                                                            type="text"
                                                                            value={worker.contact || ''}
                                                                            onChange={(e) => handleWorkerChange(worker.id!, 'contact', e.target.value)}
                                                                            onBlur={(e) => handleWorkerBlur(worker.id!, 'contact', e.target.value)}
                                                                            className="w-full border rounded px-2 py-1 text-sm"
                                                                        />
                                                                    ) : (worker.contact || '-');
                                                                    case 'address': return isEditMode ? (
                                                                        <input
                                                                            type="text"
                                                                            value={worker.address || ''}
                                                                            onChange={(e) => handleWorkerChange(worker.id!, 'address', e.target.value)}
                                                                            onBlur={(e) => handleWorkerBlur(worker.id!, 'address', e.target.value)}
                                                                            className="w-full border rounded px-2 py-1 text-sm"
                                                                        />
                                                                    ) : (worker.address || '-');
                                                                    case 'role': {
                                                                        const workerPosition = positions.find(p => p.name === worker.role);
                                                                        const posIcon = resolveIcon(workerPosition?.icon, faUser);
                                                                        const posColor = workerPosition?.color || 'gray';
                                                                        const colorClass = {
                                                                            red: 'bg-red-500', orange: 'bg-orange-500', yellow: 'bg-yellow-500',
                                                                            green: 'bg-emerald-500', blue: 'bg-blue-500', indigo: 'bg-indigo-500',
                                                                            purple: 'bg-purple-500', pink: 'bg-pink-500', gray: 'bg-slate-500',
                                                                            slate: 'bg-slate-500', black: 'bg-slate-900',
                                                                        }[posColor] || 'bg-slate-500';

                                                                        return isEditMode ? (
                                                                            <select
                                                                                value={worker.role || '일반'}
                                                                                onChange={(e) => {
                                                                                    handleWorkerChange(worker.id!, 'role', e.target.value);
                                                                                    handleWorkerBlur(worker.id!, 'role', e.target.value);
                                                                                }}
                                                                                className="w-full border rounded px-2 py-1 text-sm"
                                                                            >
                                                                                {positions.map(pos => (
                                                                                    <option key={pos.id} value={pos.name}>{pos.name}</option>
                                                                                ))}
                                                                            </select>
                                                                        ) : (
                                                                            <div className="flex items-center gap-2">
                                                                                <span className={`inline-flex items-center justify-center w-6 h-6 rounded-md ${colorClass}`}>
                                                                                    <FontAwesomeIcon icon={posIcon} className="text-white text-xs" />
                                                                                </span>
                                                                                <span>{worker.role || '일반'}</span>
                                                                            </div>
                                                                        );
                                                                    }
                                                                    case 'payType': {
                                                                        const companyType = workerCompany?.type;
                                                                        const isPartner = companyType === '협력사';
                                                                        const currentValue = isPartner ? '지원팀' : (worker.payType || '일급제');
                                                                        return isEditMode ? (
                                                                            <select
                                                                                value={currentValue}
                                                                                onChange={(e) => {
                                                                                    handleWorkerChange(worker.id!, 'payType', e.target.value);
                                                                                    handleWorkerBlur(worker.id!, 'payType', e.target.value);
                                                                                }}
                                                                                disabled={isPartner}
                                                                                className={`w-full border rounded px-2 py-1 text-sm ${isPartner ? 'bg-gray-100 text-gray-500' : ''}`}
                                                                            >
                                                                                {isPartner ? <option value="지원팀">지원팀</option> :
                                                                                    <>
                                                                                        <option value="일급제">일급제</option>
                                                                                        <option value="주급제">주급제</option>
                                                                                        <option value="월급제">월급제</option>
                                                                                        <option value="지원팀">지원팀</option>
                                                                                        <option value="용역팀">용역팀</option>
                                                                                        <option value="가지급">가지급</option>
                                                                                    </>
                                                                                }
                                                                            </select>
                                                                        ) : (
                                                                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${currentValue === '일급제' ? 'bg-yellow-100 text-yellow-700' :
                                                                                currentValue === '월급제' ? 'bg-green-100 text-green-700' :
                                                                                    currentValue === '지원팀' ? 'bg-orange-100 text-orange-700' :
                                                                                        'bg-gray-100 text-gray-600'}`}>
                                                                                {currentValue}
                                                                            </span>
                                                                        );
                                                                    }
                                                                    case 'teamName': {
                                                                        const teamIcon = resolveIcon(workerTeam?.icon, faUsers);
                                                                        const teamColor = workerTeam?.color || '#94a3b8';
                                                                        return isEditMode ? (
                                                                            <div className="flex items-center gap-2">
                                                                                <span className="inline-flex items-center justify-center w-6 h-6 rounded-md flex-shrink-0" style={{ backgroundColor: teamColor }}>
                                                                                    <FontAwesomeIcon icon={teamIcon} className="text-white text-xs" />
                                                                                </span>
                                                                                <select
                                                                                    value={worker.teamId || ''}
                                                                                    onChange={(e) => handleWorkerTeamSelect(worker.id!, e.target.value)}
                                                                                    className="w-full border rounded px-2 py-1 text-sm"
                                                                                >
                                                                                    <option value="">미배정</option>
                                                                                    {teams.map(t => (<option key={t.id} value={t.id}>{t.name}</option>))}
                                                                                </select>
                                                                            </div>
                                                                        ) : (
                                                                            <div className="flex items-center gap-2">
                                                                                <span className="inline-flex items-center justify-center w-6 h-6 rounded-md flex-shrink-0" style={{ backgroundColor: teamColor }}>
                                                                                    <FontAwesomeIcon icon={teamIcon || faUsers} className="text-white text-xs" />
                                                                                </span>
                                                                                <span className={workerTeam ? 'text-gray-900' : 'text-gray-400'}>{workerTeam?.name || worker.teamName || '-'}</span>
                                                                            </div>
                                                                        );
                                                                    }
                                                                    case 'companyName': {
                                                                        return isEditMode ? (
                                                                            <div className="flex items-center gap-2">
                                                                                <span className="inline-flex items-center justify-center w-7 h-7 rounded-full border border-slate-200 flex-shrink-0" style={{ backgroundColor: workerCompany?.color || '#e5e7eb' }}>
                                                                                    <FontAwesomeIcon icon={faBuilding} className="text-white text-xs" />
                                                                                </span>
                                                                                <select
                                                                                    value={worker.companyId || ''}
                                                                                    onChange={(e) => handleWorkerCompanySelect(worker.id!, e.target.value)}
                                                                                    className="w-full border rounded px-2 py-1 text-sm"
                                                                                >
                                                                                    <option value="">미소속</option>
                                                                                    {companies.map(c => (<option key={c.id} value={c.id}>{c.name}</option>))}
                                                                                </select>
                                                                            </div>
                                                                        ) : (
                                                                            <div className="flex items-center gap-2">
                                                                                <span className="inline-flex items-center justify-center w-7 h-7 rounded-full border border-slate-200 flex-shrink-0" style={{ backgroundColor: workerCompany?.color || '#e5e7eb' }}>
                                                                                    <FontAwesomeIcon icon={faBuilding} className="text-white text-xs" />
                                                                                </span>
                                                                                <span>{workerCompany?.name || worker.companyName || '-'}</span>
                                                                            </div>
                                                                        );
                                                                    }
                                                                    case 'status': {
                                                                        const canonicalStatus = getCanonicalStatus(worker.status);
                                                                        const isWorkerActive = canonicalStatus === '재직';
                                                                        return isEditMode ? (
                                                                            <select
                                                                                value={isWorkerActive ? '재직' : '퇴사'}
                                                                                onChange={(e) => handleStatusChange(worker.id!, e.target.value)}
                                                                                className="w-full border rounded px-2 py-1 text-sm"
                                                                            >
                                                                                <option value="재직">재직</option>
                                                                                <option value="퇴사">퇴사</option>
                                                                            </select>
                                                                        ) : (
                                                                            <div className="flex items-center gap-2">
                                                                                <button
                                                                                    onClick={() => handleStatusChange(worker.id!, isWorkerActive ? '퇴사' : '재직')}
                                                                                    className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 ${isWorkerActive ? 'bg-green-500' : 'bg-slate-300'}`}
                                                                                >
                                                                                    <span className="sr-only">상태 변경</span>
                                                                                    <span className={`${isWorkerActive ? 'translate-x-5' : 'translate-x-1'} inline-block h-3 w-3 transform rounded-full bg-white transition duration-200 ease-in-out`} />
                                                                                </button>
                                                                                <span className="text-xs text-slate-500">{canonicalStatus}</span>
                                                                            </div>
                                                                        );
                                                                    }
                                                                    case 'unitPrice': return isEditMode ? (
                                                                        <input
                                                                            type="number"
                                                                            value={worker.unitPrice || 0}
                                                                            onChange={(e) => handleWorkerChange(worker.id!, 'unitPrice', Number(e.target.value))}
                                                                            onBlur={(e) => handleWorkerBlur(worker.id!, 'unitPrice', Number(e.target.value))}
                                                                            className="w-full border rounded px-2 py-1 text-sm text-right"
                                                                        />
                                                                    ) : (worker.unitPrice ? worker.unitPrice.toLocaleString() : '0');
                                                                    case 'bankName': return isEditMode ? (
                                                                        <input
                                                                            type="text"
                                                                            value={worker.bankName || ''}
                                                                            onChange={(e) => handleWorkerChange(worker.id!, 'bankName', e.target.value)}
                                                                            onBlur={(e) => handleWorkerBlur(worker.id!, 'bankName', e.target.value)}
                                                                            className="w-full border rounded px-2 py-1 text-sm"
                                                                        />
                                                                    ) : (worker.bankName || '-');
                                                                    case 'accountNumber': return isEditMode ? (
                                                                        <input
                                                                            type="text"
                                                                            value={worker.accountNumber || ''}
                                                                            onChange={(e) => handleWorkerChange(worker.id!, 'accountNumber', e.target.value)}
                                                                            onBlur={(e) => handleWorkerBlur(worker.id!, 'accountNumber', e.target.value)}
                                                                            className="w-full border rounded px-2 py-1 text-sm"
                                                                        />
                                                                    ) : (worker.accountNumber || '-');
                                                                    case 'accountHolder': return isEditMode ? (
                                                                        <input
                                                                            type="text"
                                                                            value={worker.accountHolder || ''}
                                                                            onChange={(e) => handleWorkerChange(worker.id!, 'accountHolder', e.target.value)}
                                                                            onBlur={(e) => handleWorkerBlur(worker.id!, 'accountHolder', e.target.value)}
                                                                            className="w-full border rounded px-2 py-1 text-sm"
                                                                        />
                                                                    ) : (worker.accountHolder || '-');
                                                                    default: return null;
                                                                }
                                                            })()}
                                                        </td>
                                                    );
                                                })
                                                }

                                                <td className="px-4 py-3 text-center">
                                                    <div className="flex items-center justify-center gap-2">
                                                        {worker.fileNameSaved ? (
                                                            <button
                                                                onClick={() => handleDownloadIdCard(worker)}
                                                                className="p-1.5 text-xs font-medium bg-green-100 text-green-700 rounded hover:bg-green-200 transition-colors flex items-center gap-1"
                                                                title="신분증 다운로드"
                                                            >
                                                                <FontAwesomeIcon icon={faCheckSquare} />
                                                                <span>신분증</span>
                                                            </button>
                                                        ) : (
                                                            <span className="text-xs text-gray-400 p-1.5">미등록</span>
                                                        )}
                                                        <button
                                                            onClick={() => {
                                                                setCurrentWorker(worker);
                                                                setIsModalOpen(true);
                                                            }}
                                                            className="p-1 text-blue-600 hover:bg-blue-100 rounded transition-colors"
                                                            title="수정"
                                                        >
                                                            <FontAwesomeIcon icon={faEdit} />
                                                        </button>
                                                        <button
                                                            onClick={() => handleDelete(worker.id!, worker.name)}
                                                            className="p-1 text-red-600 hover:bg-red-100 rounded transition-colors"
                                                            title="삭제"
                                                        >
                                                            <FontAwesomeIcon icon={faTrash} />
                                                        </button>
                                                    </div>
                                                </td>
                                            </tr>
                                        );
                                    })
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div >

            {/* Modals */}
            {
                isModalOpen && (
                    <WorkerModal
                        isOpen={isModalOpen}
                        onClose={() => setIsModalOpen(false)}
                        onSave={handleSaveWorker}
                        initialData={currentWorker || { status: '재직' }}
                        teams={teams}
                        companies={companies}
                        positions={positions}
                    />
                )
            }

            <IdCardAnalysisModal
                isOpen={isIdCardAnalysisModalOpen}
                onClose={() => setIsIdCardAnalysisModalOpen(false)}
                onAddWorkers={handleIdCardRegister}
                existingWorkers={workers}
            />

            {
                isBankBookModalOpen && (
                    <BankBookAnalysisModal
                        isOpen={isBankBookModalOpen}
                        onClose={() => setIsBankBookModalOpen(false)}
                        workers={filteredWorkers}
                        onUpdateWorkers={handleBankBookUpdate}
                    />
                )
            }

            {
                showLinkingModal && (
                    <AccountLinkingModal
                        onClose={() => setShowLinkingModal(false)}
                    />
                )
            }

            <BulkProgressModal
                isOpen={isBulkProgressOpen}
                onClose={() => setIsBulkProgressOpen(false)}
                progress={bulkProgress}
                logs={bulkLogs}
            />

            <BulkEditWorkerModal
                isOpen={isBulkEditOpen}
                onClose={() => setIsBulkEditOpen(false)}
                onSave={async (updates) => {
                    await manpowerService.updateWorkersBatch(selectedWorkerIds, updates);
                    await fetchWorkers();
                    setSelectedWorkerIds([]);
                    alert('일괄 수정이 완료되었습니다.');
                }}
                selectedCount={selectedWorkerIds.length}
                teams={teams}
                sites={sites}
                companies={companies}
                positions={positions}
            />
        </div >
    );
};

export default WorkerManagement;

import React from 'react';
import { Worker } from '../../services/manpowerService';
import { Team } from '../../services/teamService';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faPenToSquare, faTrash, faImages, faUsers, faUser, faDownload } from '@fortawesome/free-solid-svg-icons';
import { storage } from '../../config/firebase';
import { ref, getDownloadURL } from 'firebase/storage';

interface Column {
    id: string;
    label: string;
    fixed?: boolean;
}

interface WorkerTableProps {
    workers: Worker[];
    columns: Column[];
    visibleColumns: string[];
    selectedWorkerIds: string[];
    toggleSelectAll: () => void;
    toggleSelectWorker: (id: string) => void;
    handleEditWorker: (worker: Worker) => void;
    handleDeleteClick: (e: React.MouseEvent, worker: Worker) => void;
    teams: Team[];
    stats: {
        total: number;
        active: number;
        unassigned: number;
    };
    onStatusToggle: (id: string, currentStatus: string) => void;
}

const WorkerTable: React.FC<WorkerTableProps> = ({
    workers,
    columns,
    visibleColumns,
    selectedWorkerIds,
    toggleSelectAll,
    toggleSelectWorker,
    handleEditWorker,
    handleDeleteClick,
    teams,
    stats,
    onStatusToggle
}) => {
    const triggerDownloadFromUrl = (url: string, filename: string) => {
        const downloadUrl = new URL(url);
        const encodedFilename = encodeURIComponent(filename);
        downloadUrl.searchParams.set(
            'response-content-disposition',
            `attachment; filename*=UTF-8''${encodedFilename}`
        );

        const anchor = document.createElement('a');
        anchor.href = downloadUrl.toString();
        anchor.rel = 'noopener noreferrer';
        anchor.style.display = 'none';
        document.body.appendChild(anchor);
        anchor.click();
        anchor.remove();
    };

    const getStorageErrorMessage = (error: unknown): string => {
        if (!error || typeof error !== 'object') return '알 수 없는 오류';

        const maybe = error as { code?: unknown; message?: unknown };
        const code = typeof maybe.code === 'string' ? maybe.code : undefined;
        const message = typeof maybe.message === 'string' ? maybe.message : undefined;

        if (code === 'storage/unauthorized') return '권한이 없습니다.';
        if (code === 'storage/object-not-found') return '파일이 존재하지 않습니다.';
        return message ?? '다운로드에 실패했습니다.';
    };

    const handleDownloadIdCard = async (worker: Worker) => {
        const path = worker.fileNameSaved;
        if (!path) {
            alert('등록된 신분증 이미지가 없습니다.');
            return;
        }

        try {
            const url = await getDownloadURL(ref(storage, path));
            const ext = path.split('.').pop() || 'jpg';
            const safeIdNumber = worker.idNumber || '미등록';
            const filename = `${worker.name}_${safeIdNumber}.${ext}`;
            triggerDownloadFromUrl(url, filename);
        } catch (error) {
            console.error('Download failed', error);
            alert(getStorageErrorMessage(error));
        }
    };

    return (
        <div className="bg-white border border-slate-200 rounded-xl shadow-sm flex-1 overflow-hidden flex flex-col">
            <div className="overflow-auto flex-1">
                <table className="w-full text-sm text-left">
                    <thead className="text-xs text-slate-500 uppercase bg-slate-50 sticky top-0 z-10">
                        <tr>
                            <th className="p-4 w-4">
                                <div className="flex items-center">
                                    <input
                                        type="checkbox"
                                        className="w-4 h-4 text-brand-600 bg-gray-100 border-gray-300 rounded focus:ring-brand-500"
                                        checked={selectedWorkerIds.length === workers.length && workers.length > 0}
                                        onChange={toggleSelectAll}
                                    />
                                </div>
                            </th>
                            {columns.filter(col => visibleColumns.includes(col.id) || col.fixed).map(col => (
                                <th key={col.id} className="px-4 py-3 font-bold text-slate-600 whitespace-nowrap">
                                    {col.label}
                                </th>
                            ))}
                            <th className="px-4 py-3 text-right">관리</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-200">
                        {workers.map((worker) => {
                            const team = worker.teamId ? teams.find(t => t.id === worker.teamId) : undefined;
                            const iconColor = team?.color || worker.color || '#e5e7eb';

                            return (
                                <tr key={worker.id} className={`hover:bg-slate-50 transition-colors ${selectedWorkerIds.includes(worker.id!) ? 'bg-indigo-50/50' : ''}`}>
                                    <td className="p-4 w-4">
                                        <div className="flex items-center">
                                            <input
                                                type="checkbox"
                                                className="w-4 h-4 text-brand-600 bg-gray-100 border-gray-300 rounded focus:ring-brand-500"
                                                checked={selectedWorkerIds.includes(worker.id!)}
                                                onChange={() => toggleSelectWorker(worker.id!)}
                                            />
                                        </div>
                                    </td>

                                    {columns.filter(col => visibleColumns.includes(col.id) || col.fixed).map(col => {
                                        if (col.id === 'name') return (
                                            <td key={col.id} className="px-4 py-3 font-medium text-slate-900 whitespace-nowrap">
                                                <div className="flex items-center gap-2">
                                                    <span
                                                        className="inline-flex items-center justify-center w-7 h-7 rounded-full border border-slate-200 flex-shrink-0"
                                                        style={{ backgroundColor: iconColor }}
                                                    >
                                                        <FontAwesomeIcon icon={faUser} className="text-white text-xs" />
                                                    </span>
                                                    <span>{worker.name}</span>
                                                </div>
                                            </td>
                                        );
                                        if (col.id === 'idNumber') return (
                                            <td key={col.id} className="px-4 py-3 text-slate-600 whitespace-nowrap">
                                                {worker.idNumber}
                                            </td>
                                        );
                                        if (col.id === 'teamName') return (
                                            <td key={col.id} className="px-4 py-3 whitespace-nowrap">
                                                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-100 text-slate-800">
                                                    {worker.teamName || '-'}
                                                </span>
                                            </td>
                                        );
                                        if (col.id === 'teamType') return (
                                            <td key={col.id} className="px-4 py-3 whitespace-nowrap">
                                                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-100 text-slate-800">
                                                    {worker.teamType || '미배정'}
                                                </span>
                                            </td>
                                        );
                                        if (col.id === 'siteName') return (
                                            <td key={col.id} className="px-4 py-3 whitespace-nowrap">
                                                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-100 text-slate-800">
                                                    {worker.siteName || '-'}
                                                </span>
                                            </td>
                                        );
                                        if (col.id === 'companyName') return (
                                            <td key={col.id} className="px-4 py-3 whitespace-nowrap">
                                                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-100 text-slate-800">
                                                    {worker.companyName || '-'}
                                                </span>
                                            </td>
                                        );
                                        if (col.id === 'salaryModel') return (
                                            <td key={col.id} className="px-4 py-3 whitespace-nowrap">
                                                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-100 text-slate-800">
                                                    {worker.salaryModel || '일급제'}
                                                </span>
                                            </td>
                                        );
                                        if (col.id === 'role') return (
                                            <td key={col.id} className="px-4 py-3 text-slate-600 whitespace-nowrap">
                                                {worker.role || '작업자'}
                                            </td>
                                        );
                                        if (col.id === 'status') return (
                                            <td key={col.id} className="px-4 py-3 whitespace-nowrap">
                                                <button
                                                    onClick={() => onStatusToggle(worker.id!, worker.status || '')}
                                                    className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 ${worker.status === '재직' ? 'bg-green-500' : 'bg-slate-300'
                                                        }`}
                                                >
                                                    <span className="sr-only">상태 변경</span>
                                                    <span
                                                        className={`${worker.status === '재직' ? 'translate-x-5' : 'translate-x-1'
                                                            } inline-block h-3 w-3 transform rounded-full bg-white transition duration-200 ease-in-out`}
                                                    />
                                                </button>
                                                <span className="ml-2 text-xs text-slate-500">{worker.status}</span>
                                            </td>
                                        );
                                        if (col.id === 'contact') return (
                                            <td key={col.id} className="px-4 py-3 text-slate-600 whitespace-nowrap">
                                                {worker.contact}
                                            </td>
                                        );
                                        if (col.id === 'email') return (
                                            <td key={col.id} className="px-4 py-3 text-slate-600 whitespace-nowrap">
                                                {worker.email}
                                            </td>
                                        );
                                        if (col.id === 'address') return (
                                            <td key={col.id} className="px-4 py-3 text-slate-600 whitespace-nowrap max-w-[200px] truncate" title={worker.address}>
                                                {worker.address}
                                            </td>
                                        );
                                        if (col.id === 'unitPrice') return (
                                            <td key={col.id} className="px-4 py-3 text-slate-600 whitespace-nowrap">
                                                {worker.unitPrice?.toLocaleString()}원
                                            </td>
                                        );
                                        if (col.id === 'bankInfo') return (
                                            <td key={col.id} className="px-4 py-3 text-slate-600 whitespace-nowrap">
                                                {worker.bankName} {worker.accountNumber}
                                                {worker.accountHolder && <span className="text-xs text-slate-400 ml-1">({worker.accountHolder})</span>}
                                            </td>
                                        );
                                        if (col.id === 'accountStatus') return (
                                            <td key={col.id} className="px-4 py-3 whitespace-nowrap">
                                                <span className="text-slate-400 text-xs">미연동</span>
                                            </td>
                                        );
                                        if (col.id === 'fileNameSaved') return (
                                            <td key={col.id} className="px-4 py-3 text-slate-600 whitespace-nowrap">
                                                {worker.fileNameSaved ? (
                                                    <button
                                                        onClick={() => handleDownloadIdCard(worker)}
                                                        className="text-blue-600 hover:text-blue-800 text-xs flex items-center gap-1 bg-blue-50 px-2 py-1 rounded-md transition-colors"
                                                    >
                                                        <FontAwesomeIcon icon={faDownload} /> 다운로드
                                                    </button>
                                                ) : '-'}
                                            </td>
                                        );
                                        return null;
                                    })}

                                    <td className="px-4 py-3 text-right">
                                        <div className="flex items-center justify-end gap-2">
                                            <button
                                                onClick={() => handleEditWorker(worker)}
                                                className="text-slate-400 hover:text-brand-600 transition"
                                            >
                                                <FontAwesomeIcon icon={faPenToSquare} />
                                            </button>
                                            <button
                                                onClick={(e) => handleDeleteClick(e, worker)}
                                                className="text-slate-400 hover:text-red-600 transition"
                                            >
                                                <FontAwesomeIcon icon={faTrash} />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            );
                        })}
                        {workers.length === 0 && (
                            <tr>
                                <td colSpan={100} className="px-6 py-12 text-center text-slate-500">
                                    <div className="flex flex-col items-center justify-center">
                                        <FontAwesomeIcon icon={faUsers} className="text-4xl text-slate-300 mb-4" />
                                        <p>등록된 근로자가 없습니다.</p>
                                    </div>
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            <div className="bg-slate-50 border-t border-slate-200 p-3 text-xs text-slate-500 flex justify-between items-center">
                <span>총 {stats.total}명 (재직: {stats.active}명, 미배정: {stats.unassigned}명)</span>
            </div>
        </div >
    );
