                                <div className="font-medium" style={{ color: COLORS.textPrimary }}>
                                    {team?.leaderName || '-'}
                                </div>
                            </div>
                            <div className="p-3 rounded-lg" style={{ background: COLORS.glass }}>
                                <div className="text-xs" style={{ color: COLORS.textMuted }}>인원</div>
                                <div className="font-medium" style={{ color: COLORS.textPrimary }}>
                                    {teamWorkers.length}명
