                            <div className="flex items-center gap-2 p-3 rounded-lg" style={{ background: COLORS.glass }}>
                                <FontAwesomeIcon icon={faPhone} style={{ color: COLORS.textMuted }} />
                                <span style={{ color: COLORS.textPrimary }}>{worker.contact}</span>
                            </div>
                        )}
