		if (memoId) {
			saveContent.cancel();
			await performSave(memoId, contentRef.current, nextColor);
		}
	};

	const handleDeleteMemo = useCallback(async (targetMemoId: string) => {
		if (!window.confirm(TXT.deleteConfirm)) return;

		saveContent.cancel();
		setStatus('saving');
		try {
			await deleteMemo(targetMemoId);
			hasPendingChangesRef.current = false;

			if (memoId === targetMemoId) {
				const remaining = quickMemos.filter((memo) => memo.id !== targetMemoId);
				if (remaining.length > 0) {
					setMemoId(remaining[0].id);
					setContent(remaining[0].content);
					setColor(remaining[0].color);
					contentRef.current = remaining[0].content;
					colorRef.current = remaining[0].color;
				} else {
					setMemoId(null);
					setContent('');
					setColor('yellow');
					contentRef.current = '';
					colorRef.current = 'yellow';
				}
			}

			setStatus('ready');
		} catch (e) {
			setStatus('error');
		}
	}, [deleteMemo, memoId, quickMemos, saveContent]);

	const handleSelectMemo = async (selected: Memo) => {
		await flushCurrentMemoSave();
		setMemoId(selected.id);
		setContent(selected.content);
		setColor(selected.color);
		hasPendingChangesRef.current = false;
		setStatus('ready');
	};

	if ((status === 'loading' || !memoId) && quickMemos.length === 0) {
		return (
			<div className="flex h-full items-center justify-center p-8">
				<Loader2 className="h-6 w-6 animate-spin text-gray-400" />
			</div>
		);
	}

	return (
		<div className={cn(
			'flex flex-col h-full rounded-lg shadow-inner overflow-hidden transition-colors duration-300',
			color === 'white' ? 'bg-white' :
				color === 'red' ? 'bg-[#ffebec]' :
					color === 'orange' ? 'bg-[#fff0e0]' :
						color === 'yellow' ? 'bg-[#fffbe0]' :
							color === 'green' ? 'bg-[#e6fdec]' :
								color === 'blue' ? 'bg-[#e3f2fd]' :
									color === 'purple' ? 'bg-[#f3e5f5]' :
										'bg-[#f5f5f5]'
		)}>
			<div className="flex items-center justify-between px-3 py-2 border-b border-black/5 bg-black/5">
				<div className="flex gap-1.5 items-center">
					{COLORS.map((c) => (
						<button
							key={c}
							type="button"
							onMouseDown={(e) => e.preventDefault()}
							onClick={() => {
								void handleColorChange(c);
							}}
							className={cn(
								'w-4 h-4 rounded-full border border-black/10 transition-transform hover:scale-110',
								color === c && 'ring-1 ring-offset-1 ring-slate-400 scale-110',
								c === 'white' && 'bg-white',
								c === 'red' && 'bg-[#ffebec]',
								c === 'orange' && 'bg-[#fff0e0]',
								c === 'yellow' && 'bg-[#fffbe0]',
								c === 'green' && 'bg-[#e6fdec]',
								c === 'blue' && 'bg-[#e3f2fd]',
								c === 'purple' && 'bg-[#f3e5f5]',
								c === 'gray' && 'bg-[#f5f5f5]'
							)}
						/>
					))}
					<div className="w-px h-3 bg-slate-300 mx-1.5" />
					<button
						type="button"
						onMouseDown={(e) => e.preventDefault()}
						onClick={async () => {
							await flushCurrentMemoSave();
							void createNewMemo();
						}}
						className="p-1 hover:bg-slate-200 rounded-full text-slate-500 hover:text-slate-700 transition-colors"
						title={TXT.newMemo}
					>
						<FilePlus className="w-4 h-4" />
					</button>
					<button
						type="button"
						onMouseDown={(e) => e.preventDefault()}
						onClick={() => {
							if (memoId) {
								void handleDeleteMemo(memoId);
							}
						}}
						className="p-1 hover:bg-rose-100 rounded-full text-rose-500 hover:text-rose-700 transition-colors"
						title={TXT.deleteMemo}
						disabled={!memoId}
					>
						<Trash2 className="w-4 h-4" />
					</button>
				</div>
				<div className="text-xs text-slate-400 flex items-center gap-1">
					{status === 'saving' ? (
						<>
							<Loader2 className="w-3 h-3 animate-spin" />
							<span>{TXT.saving}</span>
						</>
					) : status === 'ready' ? (
						<>
							<Save className="w-3 h-3" />
							<span>{TXT.saved}</span>
						</>
					) : status === 'error' ? (
						<span className="text-rose-500">{TXT.failedSave}</span>
					) : null}
				</div>
			</div>

			<div className="border-b border-black/5 bg-black/5">
				<div className="flex items-center justify-between px-3 py-1.5">
					<span className="text-[11px] font-semibold text-slate-500">
						{TXT.memoList} ({quickMemos.length})
					</span>
					<button
						type="button"
						className="text-[11px] font-medium text-slate-500 hover:text-slate-700"
						onClick={() => setIsCompactList((prev) => !prev)}
					>
						{isCompactList ? TXT.compactOff : TXT.compactOn}
					</button>
				</div>
				<div className={cn('overflow-y-auto px-2 pb-2 space-y-1', isCompactList ? 'max-h-24' : 'max-h-40')}>
					{quickMemos.length === 0 && (
						<div className="text-[11px] text-slate-400 px-1 py-1.5">{TXT.emptyList}</div>
					)}
					{quickMemos.map((memo) => {
						const active = memo.id === memoId;
						return (
							<div
								key={memo.id}
								className={cn(
									'w-full rounded-md border transition-colors',
									active
										? 'border-sky-300 bg-sky-50/80'
										: 'border-black/10 bg-white/70 hover:bg-white',
									isCompactList ? 'px-2 py-1' : 'px-2.5 py-1.5'
								)}
							>
								<div className="flex items-start gap-2">
									<button
										type="button"
										onClick={() => void handleSelectMemo(memo)}
										className="flex-1 text-left min-w-0"
									>
										<div className={cn('truncate text-slate-700', isCompactList ? 'text-[11px] font-medium' : 'text-xs font-semibold')}>
											{getContentPreview(memo.content)}
										</div>
										<div className={cn('text-slate-400', isCompactList ? 'text-[10px]' : 'text-[11px]')}>
											{formatUpdatedAt(memo)}
										</div>
									</button>
									<button
										type="button"
										onClick={() => {
											void handleDeleteMemo(memo.id);
										}}
										className="mt-0.5 p-1 rounded text-slate-400 hover:text-rose-600 hover:bg-rose-50"
										title={TXT.deleteMemo}
									>
										<Trash2 className="w-3.5 h-3.5" />
									</button>
								</div>
							</div>
						);
					})}
				</div>
			</div>

			<textarea
				className={cn(
					'flex-1 w-full resize-none bg-transparent text-slate-800 placeholder:text-slate-400 outline-none leading-relaxed',
					isCompactList ? 'p-3 text-sm' : 'p-4 text-base'
				)}
				placeholder={TXT.placeholder}
				value={content}
				onChange={handleContentChange}
				onBlur={() => {
					void flushCurrentMemoSave();
				}}
			/>
		</div>
	);
};

export default QuickMemoEditor;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useMemoStore } from '../../features/smart-memo/store/useMemoStore';
import { debounce } from 'lodash';
import { Loader2, Save, FilePlus } from 'lucide-react';
import { MemoColor } from '../../features/smart-memo/types/memo';
import { cn } from '../../features/smart-memo/lib/utils'; // Assuming this utility exists

const COLORS: MemoColor[] = ['white', 'red', 'orange', 'yellow', 'green', 'blue', 'purple', 'gray'];

export const QuickMemoEditor: React.FC = () => {
    const { currentUser } = useAuth();
    const { memos, addMemo, updateMemo, subscribeMemos } = useMemoStore();

    const [status, setStatus] = useState<'loading' | 'ready' | 'saving' | 'error'>('loading');
    const [memoId, setMemoId] = useState<string | null>(null);
    const [content, setContent] = useState('');
    const [color, setColor] = useState<MemoColor>('yellow'); // Default to yellow for "Post-it" feel

    // Ensure we are subscribed to memos when this component is active
    useEffect(() => {
        if (!currentUser) return;
        const unsubscribe = subscribeMemos(currentUser.uid);
        return () => {
            unsubscribe();
        };
    }, [currentUser, subscribeMemos]);

    // Find or Create "Quick Note"
    useEffect(() => {
        if (!currentUser) return;
        if (memos.length === 0) return; // Wait for memos to load

        // Try to find existing Quick Note (Pick the latest one)
        const quickMemos = memos.filter(m => m.title === 'Quick Note' && !m.isPinned);
        // Sort by updatedAt desc (assuming timestamp objects or numbers)
        quickMemos.sort((a, b) => {
            const timeA = a.updatedAt?.seconds ? a.updatedAt.seconds : (a.updatedAt || 0);
            const timeB = b.updatedAt?.seconds ? b.updatedAt.seconds : (b.updatedAt || 0);
            return timeB - timeA;
        });

        const quickMemo = quickMemos[0];

        if (quickMemo) {
            setMemoId(quickMemo.id);
            setContent(quickMemo.content);
            setColor(quickMemo.color);
            setStatus('ready');
        } else {
            // Create new one
            const createInit = async () => {
                try {
                    const newId = await addMemo({
                        title: 'Quick Note',
                        content: '',
                        color: 'yellow',
                        type: 'text',
                        isPinned: false,
                        scope: 'private',
                        order: 0,
                        x: 0,
                        y: 0,
                        w: 4,
                        h: 4,
                        checklistItems: [],
                        tags: [],
                        categoryId: null,
                        isCollapsed: false,
                    }, currentUser.uid);
                    setMemoId(newId);
                    setStatus('ready');
                } catch (e) {
                    console.error("Failed to create quick memo", e);
                    setStatus('error');
                }
            };
            // Prevent multiple creations if re-renders happen fast
            // Check if we already have a pending creation? 
            // Simplified: just strictly check again inside
            createInit();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [currentUser, memos.length === 0]); // Run once when memos load

    // Debounced Save
    const saveContent = useMemo(
        () => debounce(async (id: string, newContent: string, newColor: MemoColor) => {
            setStatus('saving');
            try {
                await updateMemo(id, { content: newContent, color: newColor });
                setStatus('ready');
            } catch (e) {
                setStatus('error');
            }
        }, 1000),
        [updateMemo]
    );

    const handleContentChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        const val = e.target.value;
        setContent(val);
        if (memoId) {
            saveContent(memoId, val, color);
        }
    };

    const handleColorChange = (c: MemoColor) => {
        setColor(c);
        if (memoId) {
            saveContent(memoId, content, c);
        }
    };

    // If still initial loading
    if ((status === 'loading' || !memoId) && memos.length === 0) {
        return (
            <div className="flex h-full items-center justify-center p-8">
                <Loader2 className="h-6 w-6 animate-spin text-gray-400" />
            </div>
        );
    }

    return (
        <div className={cn(
            "flex flex-col h-full rounded-lg shadow-inner overflow-hidden transition-colors duration-300",
            color === 'white' ? "bg-white" :
                color === 'red' ? "bg-[#ffebec]" :
                    color === 'orange' ? "bg-[#fff0e0]" :
                        color === 'yellow' ? "bg-[#fffbe0]" :
                            color === 'green' ? "bg-[#e6fdec]" :
                                color === 'blue' ? "bg-[#e3f2fd]" :
                                    color === 'purple' ? "bg-[#f3e5f5]" :
                                        "bg-[#f5f5f5]"
        )}>
            {/* Toolbar */}
            <div className="flex items-center justify-between px-3 py-2 border-b border-black/5 bg-black/5">
                <div className="flex gap-1.5 items-center">
                    {COLORS.map((c) => (
                        <button
                            key={c}
                            onClick={() => handleColorChange(c)}
                            className={cn(
                                "w-4 h-4 rounded-full border border-black/10 transition-transform hover:scale-110",
                                color === c && "ring-1 ring-offset-1 ring-slate-400 scale-110",
                                c === 'white' && "bg-white",
                                c === 'red' && "bg-[#ffebec]",
                                c === 'orange' && "bg-[#fff0e0]",
                                c === 'yellow' && "bg-[#fffbe0]",
                                c === 'green' && "bg-[#e6fdec]",
                                c === 'blue' && "bg-[#e3f2fd]",
                                c === 'purple' && "bg-[#f3e5f5]",
                                c === 'gray' && "bg-[#f5f5f5]"
                            )}
                        />
                    ))}
                    <div className="w-px h-3 bg-slate-300 mx-1.5" />
                    <button
                        onClick={async () => {
                            if (!currentUser) return;
                            setStatus('saving');
                            try {
                                const newId = await addMemo({
                                    title: 'Quick Note',
                                    content: '',
                                    color: 'yellow',
                                    type: 'text',
                                    isPinned: false,
                                    scope: 'private',
                                    order: 0,
                                    x: 0,
                                    y: 0,
                                    w: 4,
                                    h: 4,
                                    checklistItems: [],
                                    tags: [],
                                    categoryId: null,
                                    isCollapsed: false,
                                }, currentUser.uid);
                                setMemoId(newId);
                                setContent('');
                                setColor('yellow');
                                setStatus('ready');
                            } catch (e) {
                                console.error("Failed to create new quick memo", e);
                                setStatus('error');
                            }
                        }}
                        className="p-1 hover:bg-slate-200 rounded-full text-slate-500 hover:text-slate-700 transition-colors"
                        title="새 메모 작성"
                    >
                        <FilePlus className="w-4 h-4" />
                    </button>
                </div>
                <div className="text-xs text-slate-400 flex items-center gap-1">
                    {status === 'saving' ? (
                        <>
                            <Loader2 className="w-3 h-3 animate-spin" />
                            <span>저장 중...</span>
                        </>
                    ) : status === 'ready' ? (
                        <>
                            <Save className="w-3 h-3" />
                            <span>저장됨</span>
                        </>
                    ) : null}
                </div>
            </div>

            {/* Editor */}
            <textarea
                className="flex-1 w-full resize-none bg-transparent p-4 text-slate-800 placeholder:text-slate-400 outline-none leading-relaxed"
                placeholder="간단한 메모를 입력하세요 (자동 저장됨)"
                value={content}
                onChange={handleContentChange}
            />
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import {
    Vehicle, VehicleAssigneeType, VehicleAssignmentRecord
} from '../../types/vehicle';
import { vehicleService } from '../../services/vehicleService';
import { useMasterData } from '../../contexts/MasterDataContext';
import { manpowerService, Worker } from '../../services/manpowerService';
import { toast, showConfirmAlert } from '../../utils/swal';
import { format } from 'date-fns';

import { teamService, Team } from '../../services/teamService';

interface VehicleAssignmentProps {
    vehicle: Vehicle;
    selectableTeams?: Team[];
    onClose: () => void;
    onUpdate: () => void; // Trigger parent refresh
}

export const VehicleAssignment: React.FC<VehicleAssignmentProps> = ({
    vehicle, selectableTeams, onClose, onUpdate
}) => {
    const { teams: allTeams } = useMasterData();

    // Strict Filter or Use Prop
    const teams = React.useMemo(() => {
        if (selectableTeams) return selectableTeams;

        const targetTeamTypes = new Set(['시공팀', '시공사팀', '건설사', '시공사']);
        return allTeams.filter(t => {
            const rawType = String(t.type ?? '').trim();
            return targetTeamTypes.has(rawType);
        });
    }, [allTeams, selectableTeams]);

    const [history, setHistory] = useState<VehicleAssignmentRecord[]>([]);
    const [workers, setWorkers] = useState<Worker[]>([]);
    const [loading, setLoading] = useState(false);

    // Form State
    const [assigneeType, setAssigneeType] = useState<VehicleAssigneeType>('TEAM');
    const [selectedAssigneeId, setSelectedAssigneeId] = useState('');
    const [startDate, setStartDate] = useState(format(new Date(), 'yyyy-MM-dd'));
    const [saving, setSaving] = useState(false);

    // Initial Load
    useEffect(() => {
        loadHistory();
        loadWorkers();
    }, [vehicle.id]);

    const loadHistory = async () => {
        try {
            const data = await vehicleService.getAssignmentHistory(vehicle.id);
            setHistory(data);
        } catch (error) {
            console.error("Failed to load history", error);
        }
    };

    const loadWorkers = async () => {
        // Optimize: Only load if type is WORKER? Or pre-load for better UX
        // For MVP, loading all. If too slow, optimize.
        try {
            const data = await manpowerService.getWorkers();
            setWorkers(data);
        } catch (error) {
            console.error("Failed to load workers", error);
        }
    };

    const handleAssign = async () => {
        if (!selectedAssigneeId) {
            toast.error("배정 대상을 선택해주세요.");
            return;
        }

        const result = await showConfirmAlert(
            '차량 배정',
            `${getAssigneeName(selectedAssigneeId)}에게 배정하시겠습니까?`
        );

        if (!result.isConfirmed) return;

        setSaving(true);
        try {
            const assigneeName = getAssigneeName(selectedAssigneeId);
            await vehicleService.assignVehicle(
                vehicle.id,
                selectedAssigneeId,
                assigneeType,
                assigneeName,
                startDate
            );
            toast.success("차량이 성공적으로 배정되었습니다.");
            onUpdate(); // Refresh parent
            onClose();
        } catch (error: any) {
            toast.error(error.message || "배정에 실패했습니다.");
        } finally {
            setSaving(false);
        }
    };

    const handleUnassign = async () => {
        const result = await showConfirmAlert(
            '배정 해제',
            '현재 차량의 배정을 해제하시겠습니까?'
        );

        if (!result.isConfirmed) return;

        setSaving(true);
        try {
            const endDate = format(new Date(), 'yyyy-MM-dd');
            await vehicleService.unassignVehicle(vehicle.id, endDate);
            toast.success("차량 배정이 해제되었습니다.");
            onUpdate(); // Refresh parent
            onClose();
        } catch (error: any) {
            toast.error(error.message || "배정 해제에 실패했습니다.");
        } finally {
            setSaving(false);
        }
    };

    const getAssigneeName = (id: string) => {
        if (assigneeType === 'TEAM') {
            return teams.find(t => t.id === id)?.name || '알 수 없는 팀';
        } else {
            return workers.find(w => w.id === id)?.name || '알 수 없는 작업자';
        }
    };

    // Filtered options based on type
    const getOptions = () => {
        if (assigneeType === 'TEAM') {
            return teams.map(t => (
                <option key={t.id} value={t.id}>{t.name}</option>
            ));
        } else {
            return workers.map(w => (
                <option key={w.id} value={w.id}>{w.name} ({w.teamName || '팀 없음'})</option>
            ));
        }
    };

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-2xl max-h-[90vh] flex flex-col">
                <div className="p-6 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
                    <h2 className="text-xl font-bold text-gray-800">
                        차량 배정: {vehicle.licensePlate}
                    </h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
                        <i className="fas fa-times text-xl"></i>
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-6 space-y-6">
                    {/* Current Status Block */}
                    <div className="bg-blue-50 p-4 rounded-lg border border-blue-100">
                        <div className="flex justify-between items-center">
                            <div>
                                <p className="text-xs font-bold text-blue-600 uppercase tracking-wide">현재 상태</p>
                                <div className="mt-1 flex items-center gap-2">
                                    <span className={`px-2 py-1 rounded text-xs font-bold ${vehicle.status === 'AVAILABLE' ? 'bg-green-100 text-green-700' :
                                        vehicle.status === 'ASSIGNED' ? 'bg-blue-100 text-blue-700' :
                                            'bg-gray-100 text-gray-700'
                                        }`}>
                                        {vehicle.status === 'AVAILABLE' ? '대기중' : vehicle.status === 'ASSIGNED' ? '운행중' : vehicle.status}
                                    </span>
                                    {vehicle.status === 'ASSIGNED' && (
                                        <span className="font-medium text-gray-900">
                                            {vehicle.currentAssigneeName} ({vehicle.currentAssigneeType === 'TEAM' ? '팀' : '작업자'})
                                        </span>
                                    )}
                                </div>
                            </div>
                            {vehicle.status === 'ASSIGNED' && (
                                <button
                                    onClick={handleUnassign}
                                    disabled={saving}
                                    className="px-3 py-1.5 bg-red-100 text-red-600 hover:bg-red-200 rounded-md text-sm font-medium transition-colors"
                                >
                                    {saving ? '처리중...' : '배정 해제'}
                                </button>
                            )}
                        </div>
                    </div>

                    {/* New Assignment Form (Only if Available) */}
                    {vehicle.status === 'AVAILABLE' && (
                        <div className="border rounded-lg p-5">
                            <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2">
                                <i className="fas fa-key text-yellow-500"></i> 새 배정
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="space-y-1">
                                    <label className="text-sm font-medium text-gray-600">배정 구분</label>
                                    <div className="flex bg-gray-100 p-1 rounded-md">
                                        <button
                                            className={`flex-1 py-1.5 text-sm rounded transition-all ${assigneeType === 'TEAM' ? 'bg-white shadow text-blue-600 font-bold' : 'text-gray-500 hover:text-gray-700'}`}
                                            onClick={() => setAssigneeType('TEAM')}
                                        >
                                            팀
                                        </button>
                                        <button
                                            className={`flex-1 py-1.5 text-sm rounded transition-all ${assigneeType === 'WORKER' ? 'bg-white shadow text-blue-600 font-bold' : 'text-gray-500 hover:text-gray-700'}`}
                                            onClick={() => setAssigneeType('WORKER')}
                                        >
                                            작업자
                                        </button>
                                    </div>
                                </div>

                                <div className="space-y-1">
                                    <label className="text-sm font-medium text-gray-600">배정 시작일</label>
                                    <input
                                        type="date"
                                        value={startDate}
                                        onChange={(e) => setStartDate(e.target.value)}
                                        className="w-full px-3 py-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none"
                                    />
                                </div>

                                <div className="col-span-1 md:col-span-2 space-y-1">
                                    <label className="text-sm font-medium text-gray-600">{assigneeType === 'TEAM' ? '팀' : '작업자'} 선택</label>
                                    <select
                                        value={selectedAssigneeId}
                                        onChange={(e) => setSelectedAssigneeId(e.target.value)}
                                        className="w-full px-3 py-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none"
                                    >
                                        <option value="">선택하세요...</option>
                                        {getOptions()}
                                    </select>
                                </div>
                            </div>
                            <div className="mt-4 flex justify-end">
                                <button
                                    onClick={handleAssign}
                                    disabled={saving}
                                    className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-md font-medium shadow-sm transition-colors"
                                >
                                    {saving ? '저장중...' : '배정 확정'}
                                </button>
                            </div>
                        </div>
                    )}

                    {/* History Table */}
                    <div>
                        <h3 className="font-bold text-gray-800 mb-3 flex items-center gap-2">
                            <i className="fas fa-history text-gray-400"></i> 배정 이력
                        </h3>
                        <div className="overflow-x-auto rounded-lg border">
                            <table className="min-w-full divide-y divide-gray-200">
                                <thead className="bg-gray-50">
                                    <tr>
                                        <th className="px-4 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">배정 대상</th>
                                        <th className="px-4 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">시작일</th>
                                        <th className="px-4 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">반납일</th>
                                        <th className="px-4 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">기간</th>
                                    </tr>
                                </thead>
                                <tbody className="bg-white divide-y divide-gray-200">
                                    {history.length === 0 ? (
                                        <tr>
                                            <td colSpan={4} className="px-4 py-8 text-center text-gray-500 text-sm">
                                                배정 이력이 없습니다.
                                            </td>
                                        </tr>
                                    ) : (
                                        history.map((record) => (
                                            <tr key={record.id} className="hover:bg-gray-50">
                                                <td className="px-4 py-3 whitespace-nowrap">
                                                    <div className="text-sm font-medium text-gray-900">{record.assigneeName}</div>
                                                    <div className="text-xs text-gray-500">{record.assigneeType === 'TEAM' ? '팀' : '작업자'}</div>
                                                </td>
                                                <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-500">
                                                    {record.startDate}
                                                </td>
                                                <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-500">
                                                    {record.endDate || <span className="text-green-600 font-bold text-xs uppercase bg-green-50 px-2 py-0.5 rounded">운행 중</span>}
                                                </td>
                                                <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-500">
                                                    -
                                                </td>
                                            </tr>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useEffect, useMemo, useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCalculator, faCheckDouble, faFileInvoiceDollar, faFloppyDisk, faPlus, faSearch, faTrash, faUser, faUsers } from '@fortawesome/free-solid-svg-icons';
import { teamService, Team } from '../../services/teamService';
import { manpowerService, Worker } from '../../services/manpowerService';
import { vehicleBillingService } from '../../services/vehicleBillingService';
import { vehicleService } from '../../services/vehicleService';
import { VehicleBillingDocument, VehicleBillingIssuedToType } from '../../types/vehicleBilling';
import { toast, showConfirmAlert } from '../../utils/swal';
import { format, subMonths } from 'date-fns';
import { Vehicle } from '../../types/vehicle';
import { Timestamp } from '../../types/timestamp';

type DraftStatus = 'DRAFT' | 'CONFIRMED' | 'PAID' | 'OVERDUE';

const createEmptyLineItem = () => {
    return {
        id: uuidv4(),
        label: '',
        amount: 0,
        type: 'VARIABLE' as const,
        category: 'OTHER'
    };
};

const computeTotals = (draft: VehicleBillingDocument) => {
    const fixedCost = (draft.lineItems ?? []).filter((li) => li.type === 'FIXED').reduce((sum, li) => sum + (li.amount || 0), 0);
    const variableCost = (draft.lineItems ?? []).filter((li) => li.type === 'VARIABLE').reduce((sum, li) => sum + (li.amount || 0), 0);
    const totalAmount = fixedCost + variableCost;
    return { fixedCost, variableCost, totalAmount };
};

export const VehicleBillingManager: React.FC = () => {
    const [yearMonth, setYearMonth] = useState(format(subMonths(new Date(), 1), 'yyyy-MM'));
    const [vehicles, setVehicles] = useState<Vehicle[]>([]);
    const [teams, setTeams] = useState<Team[]>([]);
    const [workers, setWorkers] = useState<Worker[]>([]);

    const [selectedTeamId, setSelectedTeamId] = useState<string>('');
    const [issuedToType, setIssuedToType] = useState<VehicleBillingIssuedToType>('team');
    const [issuedToWorkerId, setIssuedToWorkerId] = useState<string>('');

    const [documents, setDocuments] = useState<VehicleBillingDocument[]>([]);
    const [selectedDocumentId, setSelectedDocumentId] = useState<string>('');
    const [draft, setDraft] = useState<VehicleBillingDocument | null>(null);

    const [newLineItemType, setNewLineItemType] = useState<'FIXED' | 'VARIABLE'>('VARIABLE');
    const [newLineItemLabel, setNewLineItemLabel] = useState<string>('');
    const [newLineItemAmount, setNewLineItemAmount] = useState<number>(0);

    const [createVehicleId, setCreateVehicleId] = useState<string>('');
    const [search, setSearch] = useState<string>('');

    const [loading, setLoading] = useState(false);
    const [processing, setProcessing] = useState(false);
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        const loadMaster = async () => {
            try {
                const [vehicleList, teamList, workerList] = await Promise.all([
                    vehicleService.getVehicles(),
                    teamService.getTeams(),
                    manpowerService.getWorkers()
                ]);

                setVehicles(vehicleList);
                setCreateVehicleId((prev) => prev || (vehicleList[0]?.id ?? ''));

                const sortedTeams = [...teamList].sort((a, b) => (a.name || '').localeCompare(b.name || '', 'ko-KR'));
                setTeams(sortedTeams);
                setWorkers(workerList);
                setSelectedTeamId((prev) => prev || (sortedTeams[0]?.id ?? ''));
            } catch (e) {
                console.error(e);
                setVehicles([]);
                setTeams([]);
                setWorkers([]);
            }
        };

        loadMaster();
    }, []);

    const selectedTeam = useMemo(() => {
        return teams.find((t) => t.id === selectedTeamId);
    }, [teams, selectedTeamId]);

    const resolveTeamSelectionId = (rawId: string) => {
        const raw = rawId ? String(rawId) : '';
        if (!raw) return '';
        const hit = teams.find((t) => String(t.id) === raw || String(t.legacyId ?? '') === raw);
        return hit?.id ?? raw;
    };

    useEffect(() => {
        if (!selectedTeamId) return;
        if (selectedTeam) return;
        const normalized = resolveTeamSelectionId(selectedTeamId);
        if (normalized && normalized !== selectedTeamId) {
            setSelectedTeamId(normalized);
        }
    }, [teams, selectedTeamId, selectedTeam]);

    const teamWorkers = useMemo(() => {
        if (!selectedTeamId) return [];

        const team = teams.find((t) => String(t.id) === String(selectedTeamId) || String(t.legacyId ?? '') === String(selectedTeamId));
        const teamIdCandidates = new Set<string>();
        if (team?.id) teamIdCandidates.add(String(team.id));
        if (team?.legacyId) teamIdCandidates.add(String(team.legacyId));
        teamIdCandidates.add(String(selectedTeamId));

        return workers.filter((w) => Boolean(w.id) && w.teamId && teamIdCandidates.has(String(w.teamId)));
    }, [workers, selectedTeamId, teams]);

    const teamLeader = useMemo(() => {
        if (!selectedTeam?.leaderId) return null;
        const leader = teamWorkers.find((w) => w.id === selectedTeam.leaderId);
        if (!leader?.id) return null;
        return { id: leader.id, name: leader.name };
    }, [selectedTeam?.leaderId, teamWorkers]);

    useEffect(() => {
        loadBillings();
    }, [yearMonth]);

    const loadBillings = async () => {
        setLoading(true);
        try {
            const data = await vehicleBillingService.getBillingsByMonth(yearMonth);
            const sorted = data
                .slice()
                .sort((a, b) => {
                    const plateCmp = String(a.vehiclePlate ?? '').localeCompare(String(b.vehiclePlate ?? ''), 'ko-KR');
                    if (plateCmp !== 0) return plateCmp;
                    const teamCmp = String(a.teamName ?? a.assignedTeamName ?? '').localeCompare(String(b.teamName ?? b.assignedTeamName ?? ''), 'ko-KR');
                    if (teamCmp !== 0) return teamCmp;
                    return String(a.issuedToWorkerName ?? '').localeCompare(String(b.issuedToWorkerName ?? ''), 'ko-KR');
                });
            setDocuments(sorted);

            setSelectedDocumentId((prev) => {
                if (prev && sorted.some((d) => d.id === prev)) return prev;
                return sorted[0]?.id ?? '';
            });
        } catch (error) {
            console.error(error);
            toast.error("청구서 목록을 불러오는데 실패했습니다.");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (!selectedDocumentId) {
            setDraft(null);
            return;
        }
        const found = documents.find((d) => d.id === selectedDocumentId) ?? null;
        setDraft(found);

        if (found) {
            const nextTeamId = found.teamId ?? found.assignedTeamId ?? '';
            setSelectedTeamId(resolveTeamSelectionId(nextTeamId));
            const normalizedIssuedToType = (found.issuedToType === 'team_leader' ? 'team' : (found.issuedToType ?? 'team')) as VehicleBillingIssuedToType;
            setIssuedToType(normalizedIssuedToType);
            setIssuedToWorkerId(normalizedIssuedToType === 'worker' ? (found.issuedToWorkerId ?? '') : '');
        }
    }, [documents, selectedDocumentId]);

    useEffect(() => {
        setNewLineItemType('VARIABLE');
        setNewLineItemLabel('');
        setNewLineItemAmount(0);
    }, [draft?.id]);

    useEffect(() => {
        const normalizedIssuedToType = issuedToType === 'team_leader' ? 'team' : issuedToType;
        if (normalizedIssuedToType === 'team') {
            if (issuedToWorkerId) setIssuedToWorkerId('');
            return;
        }

        if (!teamWorkers.some((w) => w.id === issuedToWorkerId)) {
            const first = teamWorkers.find((w) => Boolean(w.id));
            setIssuedToWorkerId(first?.id ?? '');
        }
    }, [issuedToType, teamWorkers, issuedToWorkerId]);

    useEffect(() => {
        if (!draft) return;

        const normalizedIssuedToType = issuedToType === 'team_leader' ? 'team' : issuedToType;

        const resolvedIssuedToWorkerName =
            normalizedIssuedToType === 'team'
                ? (selectedTeam?.name ?? draft.teamName ?? draft.assignedTeamName ?? '')
                : (teamWorkers.find((w) => w.id === issuedToWorkerId)?.name ?? draft.issuedToWorkerName);

        setDraft((prev) => {
            if (!prev) return prev;

            const nextTeamId = selectedTeamId || prev.teamId;
            const nextTeamName = selectedTeam?.name ?? prev.teamName;
            const nextWorkerId = normalizedIssuedToType === 'team' ? '' : (issuedToWorkerId || prev.issuedToWorkerId);

            const shouldUpdate =
                String(prev.teamId ?? '') !== String(nextTeamId ?? '') ||
                String(prev.teamName ?? '') !== String(nextTeamName ?? '') ||
                String(prev.issuedToType ?? '') !== String(issuedToType ?? '') ||
                String(prev.issuedToWorkerId ?? '') !== String(nextWorkerId ?? '') ||
                String(prev.issuedToWorkerName ?? '') !== String(resolvedIssuedToWorkerName ?? '');

            if (!shouldUpdate) return prev;

            return {
                ...prev,
                teamId: nextTeamId,
                teamName: nextTeamName,
                issuedToType: normalizedIssuedToType,
                issuedToWorkerId: normalizedIssuedToType === 'worker' ? nextWorkerId : undefined,
                issuedToWorkerName: resolvedIssuedToWorkerName
            };
        });
    }, [draft?.id, issuedToType, issuedToWorkerId, selectedTeamId, selectedTeam?.name, teamWorkers]);

    const handleCalculate = async () => {
        const result = await showConfirmAlert(
            "청구서 계산",
            `${yearMonth}월 DRAFT 청구서를 재계산하시겠습니까? (확정된 문서는 변경되지 않습니다.)`
        );
        if (!result.isConfirmed) return;

        setProcessing(true);
        try {
            const targets = documents.filter((d) => d.status !== 'CONFIRMED');
            if (targets.length === 0) {
                toast.info('재계산할 DRAFT 문서가 없습니다.');
                return;
            }

            let skipped = 0;
            await Promise.all(
                targets.map(async (doc) => {
                    const vehicle = vehicles.find((v) => String(v.id) === String(doc.vehicleId)) ?? null;
                    if (!vehicle) {
                        skipped += 1;
                        return;
                    }

                    const regenerated = await vehicleBillingService.generateBilling(vehicle, yearMonth);
                    const next: VehicleBillingDocument = {
                        ...doc,
                        vehiclePlate: vehicle.licensePlate,
                        fixedCost: regenerated.fixedCost,
                        variableCost: regenerated.variableCost,
                        totalAmount: regenerated.totalAmount,
                        lineItems: regenerated.lineItems
                    };
                    await vehicleBillingService.saveBilling(next);
                })
            );

            const msg = skipped > 0
                ? `재계산 완료 (대상 ${targets.length}건 중 ${skipped}건은 차량 매칭 실패로 스킵)`
                : `재계산 완료 (${targets.length}건)`;

            toast.success(msg);
            await loadBillings();
        } catch (error) {
            console.error(error);
            toast.error("계산에 실패했습니다.");
        } finally {
            setProcessing(false);
        }
    };

    const selectedVehicle = useMemo(() => {
        if (!draft?.vehicleId) return null;
        return vehicles.find((v) => String(v.id) === String(draft.vehicleId)) ?? null;
    }, [vehicles, draft?.vehicleId]);

    const draftTotals = useMemo(() => {
        if (!draft) return { fixedCost: 0, variableCost: 0, totalAmount: 0 };
        return computeTotals(draft);
    }, [draft]);

    const canEdit = draft?.status !== 'CONFIRMED';

    const totals = useMemo(() => {
        return documents.reduce(
            (acc, d) => {
                acc.fixed += d.fixedCost || 0;
                acc.variable += d.variableCost || 0;
                acc.total += d.totalAmount || 0;
                return acc;
            },
            { fixed: 0, variable: 0, total: 0 }
        );
    }, [documents]);

    const visibleDocuments = useMemo(() => {
        const q = search.trim();
        if (!q) return documents;
        return documents.filter((d) => {
            const plate = String(d.vehiclePlate ?? '');
            const team = String(d.teamName ?? d.assignedTeamName ?? '');
            const issuedTo = String(d.issuedToWorkerName ?? '');
            return plate.includes(q) || team.includes(q) || issuedTo.includes(q);
        });
    }, [documents, search]);

    const handleCreateNew = async () => {
        const vehicle = vehicles.find((v) => String(v.id) === String(createVehicleId)) ?? null;
        if (!vehicle) {
            toast.error('차량을 선택해주세요.');
            return;
        }

        if (!selectedTeam || !selectedTeam.id) {
            toast.error('발행 팀을 선택해주세요.');
            return;
        }

        const normalizedIssuedToType = issuedToType === 'team_leader' ? 'team' : issuedToType;
        const target = normalizedIssuedToType === 'worker'
            ? (() => {
                const w = teamWorkers.find((x) => x.id === issuedToWorkerId);
                return w?.id ? { id: w.id, name: w.name } : null;
            })()
            : null;

        if (normalizedIssuedToType === 'worker' && !target) {
            toast.error('발행 대상을 선택해주세요.');
            return;
        }

        setProcessing(true);
        try {
            const next = await vehicleBillingService.generateBilling(vehicle, yearMonth);

            const resolvedId = vehicleBillingService.buildBillingDocumentId({
                vehicleId: vehicle.id,
                teamId: selectedTeam.id,
                issuedToType: normalizedIssuedToType as any,
                workerId: normalizedIssuedToType === 'worker' ? target?.id : undefined,
                yearMonth
            });

            const withIssue: VehicleBillingDocument = {
                ...next,
                id: resolvedId,
                teamId: selectedTeam.id,
                teamName: selectedTeam.name,
                issuedToType: normalizedIssuedToType,
                issuedToWorkerId: normalizedIssuedToType === 'worker' ? target?.id : undefined,
                issuedToWorkerName: normalizedIssuedToType === 'team' ? selectedTeam.name : (target?.name ?? '')
            };

            const exists = documents.some((d) => d.id === resolvedId);

            if (exists) {
                const ok = await showConfirmAlert('청구서 생성', '이미 해당 차량의 청구서가 존재합니다. 재계산하여 덮어쓸까요?');
                if (!ok.isConfirmed) return;
            }

            await vehicleBillingService.saveBilling(withIssue);
            await loadBillings();
            setSelectedDocumentId(resolvedId);
            toast.success('청구서가 생성되었습니다.');
        } catch (e) {
            console.error(e);
            toast.error('청구서 생성에 실패했습니다.');
        } finally {
            setProcessing(false);
        }
    };

    const handleDraftChange = (patch: Partial<VehicleBillingDocument>) => {
        if (!draft) return;
        setDraft({ ...draft, ...patch });
    };

    const handleLineItemChange = (id: string, patch: Partial<VehicleBillingDocument['lineItems'][number]>) => {
        if (!draft) return;
        const items = (draft.lineItems ?? []).map((li) => (li.id === id ? { ...li, ...patch } : li));
        setDraft({ ...draft, lineItems: items });
    };

    const handleAddLineItemFromForm = () => {
        if (!draft) return;
        if (!canEdit) return;

        const label = newLineItemLabel.trim();
        if (!label) {
            toast.error('항목명을 입력해주세요.');
            return;
        }

        const amount = Number(newLineItemAmount || 0);
        const nextItem = {
            ...createEmptyLineItem(),
            type: newLineItemType,
            label,
            amount,
            category: 'OTHER'
        };

        const items = [...(draft.lineItems ?? []), nextItem];
        setDraft({ ...draft, lineItems: items });
        setNewLineItemType('VARIABLE');
        setNewLineItemLabel('');
        setNewLineItemAmount(0);
    };

    const handleRemoveLineItem = (id: string) => {
        if (!draft) return;
        const items = (draft.lineItems ?? []).filter((li) => li.id !== id);
        setDraft({ ...draft, lineItems: items });
    };

    const handleSave = async () => {
        if (!draft) return;

        if (!selectedTeamId) {
            toast.error('발행 팀을 선택해주세요.');
            return;
        }

        const normalizedIssuedToType = issuedToType === 'team_leader' ? 'team' : issuedToType;
        if (normalizedIssuedToType === 'worker' && !issuedToWorkerId) {
            toast.error('발행 대상을 선택해주세요.');
            return;
        }

        setSaving(true);
        try {
            const computed = computeTotals(draft);

            const resolvedIssuedToWorkerName =
                normalizedIssuedToType === 'team'
                    ? (selectedTeam?.name ?? draft.teamName ?? draft.assignedTeamName ?? '')
                    : (teamWorkers.find((w) => w.id === issuedToWorkerId)?.name ?? draft.issuedToWorkerName);

            const resolvedId = vehicleBillingService.buildBillingDocumentId({
                vehicleId: draft.vehicleId,
                teamId: selectedTeamId,
                issuedToType: normalizedIssuedToType as any,
                workerId: normalizedIssuedToType === 'worker' ? issuedToWorkerId : undefined,
                yearMonth: draft.yearMonth
            });

            const next: VehicleBillingDocument = {
                ...draft,
                id: resolvedId,
                fixedCost: computed.fixedCost,
                variableCost: computed.variableCost,
                totalAmount: computed.totalAmount,
                teamId: selectedTeamId,
                teamName: selectedTeam?.name ?? draft.teamName,
                issuedToType: normalizedIssuedToType,
                issuedToWorkerId: normalizedIssuedToType === 'worker' ? issuedToWorkerId : undefined,
                issuedToWorkerName: resolvedIssuedToWorkerName,
                status: (draft.status || 'DRAFT') as DraftStatus
            };
            await vehicleBillingService.saveBilling(next);
            toast.success('저장되었습니다.');
            await loadBillings();
            setSelectedDocumentId(resolvedId);
        } catch (e) {
            console.error(e);
            toast.error('저장에 실패했습니다.');
        } finally {
            setSaving(false);
        }
    };

    const handleConfirm = async () => {
        if (!draft) return;

        if (!selectedTeamId) {
            toast.error('발행 팀을 선택해주세요.');
            return;
        }

        const normalizedIssuedToType = issuedToType === 'team_leader' ? 'team' : issuedToType;
        if (normalizedIssuedToType === 'worker' && !issuedToWorkerId) {
            toast.error('발행 대상을 선택해주세요.');
            return;
        }

        const result = await showConfirmAlert('확정 처리', '해당 청구서를 확정할까요? (확정 후 편집이 제한됩니다)');
        if (!result.isConfirmed) return;

        setSaving(true);
        try {
            const computed = computeTotals(draft);

            const resolvedIssuedToWorkerName =
                normalizedIssuedToType === 'team'
                    ? (selectedTeam?.name ?? draft.teamName ?? draft.assignedTeamName ?? '')
                    : (teamWorkers.find((w) => w.id === issuedToWorkerId)?.name ?? draft.issuedToWorkerName);

            const resolvedId = vehicleBillingService.buildBillingDocumentId({
                vehicleId: draft.vehicleId,
                teamId: selectedTeamId,
                issuedToType: normalizedIssuedToType as any,
                workerId: normalizedIssuedToType === 'worker' ? issuedToWorkerId : undefined,
                yearMonth: draft.yearMonth
            });

            const next: VehicleBillingDocument = {
                ...draft,
                id: resolvedId,
                fixedCost: computed.fixedCost,
                variableCost: computed.variableCost,
                totalAmount: computed.totalAmount,
                teamId: selectedTeamId,
                teamName: selectedTeam?.name ?? draft.teamName,
                issuedToType: normalizedIssuedToType,
                issuedToWorkerId: normalizedIssuedToType === 'worker' ? issuedToWorkerId : undefined,
                issuedToWorkerName: resolvedIssuedToWorkerName,
                status: 'CONFIRMED',
                confirmedAt: Timestamp.now() as any
            };
            await vehicleBillingService.saveBilling(next);
            toast.success('확정되었습니다.');
            await loadBillings();
            setSelectedDocumentId(resolvedId);
        } catch (e) {
            console.error(e);
            toast.error('확정에 실패했습니다.');
        } finally {
            setSaving(false);
        }
    };

    return (
        <div className="space-y-6">
            <div className="bg-white p-5 rounded-2xl border border-indigo-100 shadow-sm">
                <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-4">
                    <div className="flex items-center gap-3">
                        <h2 className="text-xl font-extrabold text-slate-900 tracking-tight flex items-center gap-2">
                            <FontAwesomeIcon icon={faFileInvoiceDollar} className="text-indigo-600" />
                            차량 청구관리
                        </h2>
                        <div className="flex items-center gap-3 ml-2">
                            <span className="text-sm font-bold text-slate-600">청구 월</span>
                            <input
                                type="month"
                                value={yearMonth}
                                onChange={(e) => setYearMonth(e.target.value)}
                                className="px-3 py-2 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-200"
                            />
                        </div>
                    </div>

                    <div className="flex flex-col md:flex-row md:items-center gap-3">
                        <div className="flex flex-col md:flex-row md:items-end gap-2">
                            <div>
                                <div className="text-xs font-bold text-slate-500 mb-1">발행 팀</div>
                                <select
                                    value={selectedTeamId}
                                    onChange={(e) => setSelectedTeamId(e.target.value)}
                                    className="px-3 py-2 border border-slate-200 rounded-xl bg-white text-sm min-w-[220px]"
                                >
                                    {teams
                                        .filter((t) => Boolean(t.id))
                                        .map((t) => (
                                            <option key={t.id} value={t.id}>
                                                {t.name}
                                            </option>
                                        ))}
                                </select>
                            </div>

                            <div>
                                <div className="text-xs font-bold text-slate-500 mb-1">발행 대상</div>
                                <div className="flex items-center gap-2">
                                    <div className="flex bg-slate-100 p-1 rounded-xl">
                                        <button
                                            onClick={() => setIssuedToType('team')}
                                            className={`px-3 py-2 text-xs font-bold rounded-lg transition flex items-center gap-1 ${issuedToType === 'team' ? 'bg-white shadow-sm text-indigo-700' : 'text-slate-500 hover:text-slate-700'
                                                }`}
                                            type="button"
                                        >
                                            <FontAwesomeIcon icon={faUsers} />
                                            팀
                                        </button>
                                        <button
                                            onClick={() => setIssuedToType('worker')}
                                            className={`px-3 py-2 text-xs font-bold rounded-lg transition flex items-center gap-1 ${issuedToType === 'worker' ? 'bg-white shadow-sm text-indigo-700' : 'text-slate-500 hover:text-slate-700'
                                                }`}
                                            type="button"
                                        >
                                            <FontAwesomeIcon icon={faUser} />
                                            개인
                                        </button>
                                    </div>

                                    {issuedToType === 'team' ? (
                                        <input
                                            value={selectedTeam?.name ?? ''}
                                            disabled
                                            placeholder="팀 선택"
                                            className="px-3 py-2 border border-slate-200 rounded-xl bg-slate-50 text-sm w-[160px]"
                                        />
                                    ) : (
                                        <select
                                            value={issuedToWorkerId}
                                            onChange={(e) => setIssuedToWorkerId(e.target.value)}
                                            className="px-3 py-2 border border-slate-200 rounded-xl bg-white text-sm w-[160px]"
                                        >
                                            <option value="">작업자 선택</option>
                                            {teamWorkers.map((w) => (
                                                <option key={w.id} value={w.id}>
                                                    {w.name}
                                                </option>
                                            ))}
                                        </select>
                                    )}
                                </div>
                            </div>
                        </div>

                        <div className="flex items-center gap-2">
                            <select
                                value={createVehicleId}
                                onChange={(e) => setCreateVehicleId(e.target.value)}
                                className="px-3 py-2 border border-slate-200 rounded-xl bg-white text-sm min-w-[240px]"
                            >
                                {vehicles
                                    .slice()
                                    .sort((a, b) => String(a.licensePlate).localeCompare(String(b.licensePlate), 'ko-KR'))
                                    .map((v) => (
                                        <option key={v.id} value={v.id}>
                                            {v.licensePlate} ({v.model})
                                        </option>
                                    ))}
                            </select>
                            <button
                                onClick={handleCreateNew}
                                disabled={processing}
                                className={`px-4 py-2.5 rounded-xl font-bold text-sm text-white shadow-lg shadow-indigo-200 transition-all active:scale-95 flex items-center gap-2 ${processing ? 'bg-indigo-400 cursor-wait' : 'bg-indigo-600 hover:bg-indigo-700 hover:-translate-y-0.5'
                                    }`}
                            >
                                <FontAwesomeIcon icon={faPlus} />
                                차량 청구서 생성
                            </button>
                        </div>

                        <button
                            onClick={handleCalculate}
                            disabled={processing}
                            className={`px-4 py-2.5 rounded-xl font-bold text-sm text-white shadow-lg shadow-indigo-200 transition-all active:scale-95 flex items-center gap-2 ${processing ? 'bg-slate-400 cursor-wait' : 'bg-slate-800 hover:bg-slate-900 hover:-translate-y-0.5'
                                }`}
                        >
                            <FontAwesomeIcon icon={faCalculator} />
                            DRAFT 재계산
                        </button>
                    </div>
                </div>

                <div className="mt-5 flex justify-end gap-6 text-right">
                    <div>
                        <p className="text-xs text-slate-500 uppercase font-bold">고정비</p>
                        <p className="font-extrabold text-slate-700 font-mono">{totals.fixed.toLocaleString()}</p>
                    </div>
                    <div>
                        <p className="text-xs text-slate-500 uppercase font-bold">변동비</p>
                        <p className="font-extrabold text-slate-700 font-mono">{totals.variable.toLocaleString()}</p>
                    </div>
                    <div>
                        <p className="text-xs text-slate-500 uppercase font-bold">합계</p>
                        <p className="font-extrabold text-indigo-700 text-xl font-mono">{totals.total.toLocaleString()}</p>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 xl:grid-cols-12 gap-6">
                <div className="xl:col-span-4">
                    <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                        <div className="p-4 border-b border-slate-200 bg-slate-50">
                            <div className="flex items-center gap-2">
                                <div className="relative flex-1">
                                    <FontAwesomeIcon icon={faSearch} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm" />
                                    <input
                                        value={search}
                                        onChange={(e) => setSearch(e.target.value)}
                                        placeholder="차량번호/팀/대상 검색"
                                        className="w-full pl-9 pr-3 py-2 border border-slate-200 rounded-xl text-sm"
                                    />
                                </div>
                            </div>
                            <div className="mt-3 text-xs text-slate-500 font-medium">
                                문서 {visibleDocuments.length}건
                            </div>
                        </div>

                        <div className="max-h-[720px] overflow-y-auto">
                            {loading ? (
                                <div className="p-10 text-center text-slate-400">불러오는 중...</div>
                            ) : visibleDocuments.length === 0 ? (
                                <div className="p-10 text-center text-slate-400">해당 월 청구서가 없습니다.</div>
                            ) : (
                                <div className="divide-y divide-slate-100">
                                    {visibleDocuments.map((doc) => {
                                        const isSelected = doc.id === selectedDocumentId;
                                        return (
                                            <button
                                                key={doc.id}
                                                onClick={() => setSelectedDocumentId(doc.id)}
                                                className={`w-full text-left p-4 hover:bg-indigo-50/40 transition ${isSelected ? 'bg-indigo-50 ring-1 ring-indigo-100' : ''
                                                    }`}
                                            >
                                                <div className="flex items-start justify-between gap-3">
                                                    <div>
                                                        <div className="text-sm font-extrabold text-slate-800">
                                                            {doc.vehiclePlate || '-'}
                                                        </div>
                                                        <div className="text-xs text-slate-500 mt-1">
                                                            {doc.teamName || doc.assignedTeamName ? `팀: ${doc.teamName ?? doc.assignedTeamName}` : '팀: -'}
                                                        </div>
                                                        <div className="text-xs text-slate-500 mt-0.5">
                                                            {doc.issuedToWorkerName ? `대상: ${doc.issuedToWorkerName}` : '대상: -'}
                                                        </div>
                                                    </div>
                                                    <div className="text-right">
                                                        <div className="text-sm font-extrabold text-slate-800 font-mono">
                                                            {(doc.totalAmount || 0).toLocaleString()}
                                                        </div>
                                                        <div>
                                                            <span
                                                                className={`inline-flex px-2 py-0.5 rounded-lg text-[11px] font-bold border ${doc.status === 'CONFIRMED'
                                                                    ? 'bg-emerald-50 text-emerald-700 border-emerald-100'
                                                                    : 'bg-amber-50 text-amber-700 border-amber-100'
                                                                    }`}
                                                            >
                                                                {doc.status === 'CONFIRMED' ? '확정' : '작성중'}
                                                            </span>
                                                        </div>
                                                    </div>
                                                </div>
                                            </button>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                <div className="xl:col-span-8">
                    <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6 min-h-[720px]">
                        {!draft ? (
                            <div className="h-full flex flex-col items-center justify-center text-slate-400">
                                선택된 청구서가 없습니다.
                            </div>
                        ) : (
                            <div className="space-y-6">
                                <div className="flex flex-col md:flex-row md:items-start justify-between gap-4">
                                    <div>
                                        <div className="text-2xl font-extrabold text-slate-900 tracking-tight">
                                            {draft.vehiclePlate || '-'}
                                        </div>
                                        <div className="text-sm text-slate-500 font-medium mt-1">
                                            {selectedVehicle ? `${selectedVehicle.model} / ${selectedVehicle.type}` : ''}
                                        </div>
                                        <div className="text-sm text-slate-600 font-bold mt-3">
                                            발행 팀: {draft.teamName ?? draft.assignedTeamName ?? '-'}
                                        </div>
                                        <div className="text-sm text-slate-600 font-bold mt-1">
                                            발행 대상: {draft.issuedToWorkerName ?? '-'}
                                        </div>
                                    </div>

                                    <div className="flex items-center gap-2">
                                        <button
                                            onClick={handleSave}
                                            disabled={!canEdit || saving}
                                            className={`px-4 py-2.5 rounded-xl font-bold text-sm text-white shadow-lg shadow-indigo-200 transition-all active:scale-95 flex items-center gap-2 ${!canEdit || saving
                                                ? 'bg-indigo-300 cursor-not-allowed'
                                                : 'bg-indigo-600 hover:bg-indigo-700 hover:-translate-y-0.5'
                                                }`}
                                        >
                                            <FontAwesomeIcon icon={faFloppyDisk} />
                                            저장
                                        </button>
                                        <button
                                            onClick={handleConfirm}
                                            disabled={!canEdit || saving}
                                            className={`px-4 py-2.5 rounded-xl font-bold text-sm text-white shadow-lg shadow-emerald-200 transition-all active:scale-95 flex items-center gap-2 ${!canEdit || saving
                                                ? 'bg-emerald-300 cursor-not-allowed'
                                                : 'bg-emerald-600 hover:bg-emerald-700 hover:-translate-y-0.5'
                                                }`}
                                        >
                                            <FontAwesomeIcon icon={faCheckDouble} />
                                            확정
                                        </button>
                                    </div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                    <div className="bg-slate-50 rounded-2xl border border-slate-200 p-4">
                                        <div className="text-xs text-slate-500 font-bold uppercase">고정비</div>
                                        <div className="text-xl font-extrabold text-slate-800 font-mono mt-1">{draftTotals.fixedCost.toLocaleString()}</div>
                                    </div>
                                    <div className="bg-slate-50 rounded-2xl border border-slate-200 p-4">
                                        <div className="text-xs text-slate-500 font-bold uppercase">변동비</div>
                                        <div className="text-xl font-extrabold text-slate-800 font-mono mt-1">{draftTotals.variableCost.toLocaleString()}</div>
                                    </div>
                                    <div className="bg-indigo-50 rounded-2xl border border-indigo-100 p-4">
                                        <div className="text-xs text-indigo-600 font-bold uppercase">합계</div>
                                        <div className="text-xl font-extrabold text-indigo-700 font-mono mt-1">{draftTotals.totalAmount.toLocaleString()}</div>
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <div className="text-sm font-extrabold text-slate-800">메모</div>
                                    <textarea
                                        value={draft.memo ?? ''}
                                        disabled={!canEdit}
                                        onChange={(e) => handleDraftChange({ memo: e.target.value })}
                                        className={`w-full min-h-[90px] p-3 border rounded-2xl text-sm ${canEdit ? 'border-slate-200 focus:ring-2 focus:ring-indigo-100' : 'border-slate-100 bg-slate-50'
                                            }`}
                                    />
                                </div>

                                <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden">
                                    <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
                                        <div className="text-sm font-extrabold text-slate-800">라인 아이템</div>
                                        <div className="flex flex-wrap items-end gap-2">
                                            <div>
                                                <div className="text-[11px] font-bold text-slate-500 mb-1">구분</div>
                                                <select
                                                    value={newLineItemType}
                                                    disabled={!canEdit}
                                                    onChange={(e) => setNewLineItemType(e.target.value as 'FIXED' | 'VARIABLE')}
                                                    className={`px-3 py-2 border rounded-xl bg-white text-xs font-bold ${canEdit ? 'border-slate-200' : 'border-slate-100 bg-slate-100 text-slate-400'
                                                        }`}
                                                >
                                                    <option value="FIXED">고정</option>
                                                    <option value="VARIABLE">변동</option>
                                                </select>
                                            </div>

                                            <div className="min-w-[220px]">
                                                <div className="text-[11px] font-bold text-slate-500 mb-1">항목</div>
                                                <input
                                                    value={newLineItemLabel}
                                                    disabled={!canEdit}
                                                    onChange={(e) => setNewLineItemLabel(e.target.value)}
                                                    className={`w-full px-3 py-2 border rounded-xl text-sm ${canEdit ? 'border-slate-200' : 'border-slate-100 bg-slate-100 text-slate-400'
                                                        }`}
                                                    placeholder="예: 주유비, 렌트료"
                                                />
                                            </div>

                                            <div className="min-w-[160px]">
                                                <div className="text-[11px] font-bold text-slate-500 mb-1">금액</div>
                                                <input
                                                    type="number"
                                                    value={Number(newLineItemAmount || 0)}
                                                    disabled={!canEdit}
                                                    onChange={(e) => setNewLineItemAmount(Number(e.target.value || 0))}
                                                    className={`w-full px-3 py-2 border rounded-xl text-right font-mono ${canEdit ? 'border-slate-200' : 'border-slate-100 bg-slate-100 text-slate-400'
                                                        }`}
                                                />
                                            </div>

                                            <button
                                                onClick={handleAddLineItemFromForm}
                                                disabled={!canEdit}
                                                className={`px-3 py-2 rounded-xl text-xs font-bold inline-flex items-center gap-2 ${canEdit ? 'bg-indigo-50 text-indigo-700 hover:bg-indigo-100' : 'bg-slate-100 text-slate-400 cursor-not-allowed'
                                                    }`}
                                                type="button"
                                            >
                                                <FontAwesomeIcon icon={faPlus} />
                                                추가
                                            </button>
                                        </div>
                                    </div>

                                    <div className="overflow-x-auto">
                                        <table className="w-full text-sm min-w-[820px]">
                                            <thead className="text-xs text-slate-500 uppercase bg-white border-b border-slate-100">
                                                <tr>
                                                    <th className="px-4 py-3 text-left w-[120px]">구분</th>
                                                    <th className="px-4 py-3 text-left">항목</th>
                                                    <th className="px-4 py-3 text-right w-[180px]">금액</th>
                                                    <th className="px-4 py-3 text-right w-[90px]"></th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-slate-100">
                                                {(draft.lineItems ?? []).length === 0 ? (
                                                    <tr>
                                                        <td colSpan={4} className="px-4 py-10 text-center text-slate-400">
                                                            항목이 없습니다.
                                                        </td>
                                                    </tr>
                                                ) : (
                                                    (draft.lineItems ?? []).map((li) => (
                                                        <tr key={li.id} className="hover:bg-indigo-50/30">
                                                            <td className="px-4 py-3">
                                                                <select
                                                                    value={li.type}
                                                                    disabled={!canEdit}
                                                                    onChange={(e) => handleLineItemChange(li.id, { type: e.target.value as 'FIXED' | 'VARIABLE' })}
                                                                    className="px-3 py-2 border border-slate-200 rounded-xl bg-white text-xs font-bold"
                                                                >
                                                                    <option value="FIXED">고정</option>
                                                                    <option value="VARIABLE">변동</option>
                                                                </select>
                                                            </td>
                                                            <td className="px-4 py-3">
                                                                <input
                                                                    value={li.label}
                                                                    disabled={!canEdit}
                                                                    onChange={(e) => handleLineItemChange(li.id, { label: e.target.value })}
                                                                    className={`w-full px-3 py-2 border rounded-xl text-sm ${canEdit ? 'border-slate-200' : 'border-slate-100 bg-slate-50'
                                                                        }`}
                                                                    placeholder="예: 주유비, 렌트료"
                                                                />
                                                            </td>
                                                            <td className="px-4 py-3 text-right">
                                                                <input
                                                                    type="number"
                                                                    value={Number(li.amount || 0)}
                                                                    disabled={!canEdit}
                                                                    onChange={(e) => handleLineItemChange(li.id, { amount: Number(e.target.value || 0) })}
                                                                    className={`w-full px-3 py-2 border rounded-xl text-right font-mono ${canEdit ? 'border-slate-200' : 'border-slate-100 bg-slate-50'
                                                                        }`}
                                                                />
                                                            </td>
                                                            <td className="px-4 py-3 text-right">
                                                                <button
                                                                    onClick={() => handleRemoveLineItem(li.id)}
                                                                    disabled={!canEdit}
                                                                    className={`w-9 h-9 rounded-xl inline-flex items-center justify-center ${canEdit ? 'bg-red-50 text-red-600 hover:bg-red-100' : 'bg-slate-100 text-slate-300 cursor-not-allowed'
                                                                        }`}
                                                                >
                                                                    <FontAwesomeIcon icon={faTrash} className="text-xs" />
                                                                </button>
                                                            </td>
                                                        </tr>
                                                    ))
                                                )}
                                            </tbody>
                                        </table>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import { Vehicle, VehicleExpenseRecord, VehicleExpenseType, VehicleExpensePayer } from '../../types/vehicle';
import { vehicleService } from '../../services/vehicleService';
import { toast, showConfirmAlert } from '../../utils/swal';
import { format } from 'date-fns';

interface VehicleExpenseLogProps {
    vehicle: Vehicle;
    onClose: () => void;
}

const EXPENSE_TYPES: VehicleExpenseType[] = ['FUEL', 'REPAIR', 'TOLL', 'FINE', 'OTHER'];
const PAYERS: VehicleExpensePayer[] = ['COMPANY', 'DRIVER'];

export const VehicleExpenseLog: React.FC<VehicleExpenseLogProps> = ({ vehicle, onClose }) => {
    const [currentMonth, setCurrentMonth] = useState(format(new Date(), 'yyyy-MM'));
    const [expenses, setExpenses] = useState<VehicleExpenseRecord[]>([]);
    const [loading, setLoading] = useState(false);

    // Form State
    const [date, setDate] = useState(format(new Date(), 'yyyy-MM-dd'));
    const [type, setType] = useState<VehicleExpenseType>('FUEL');
    const [amount, setAmount] = useState<number | ''>('');
    const [payer, setPayer] = useState<VehicleExpensePayer>('COMPANY');
    const [note, setNote] = useState('');
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        loadExpenses();
    }, [vehicle.id, currentMonth]);

    const getExpenseTypeLabel = (type: VehicleExpenseType) => {
        switch (type) {
            case 'FUEL': return '주유비';
            case 'REPAIR': return '정비비';
            case 'TOLL': return '통행료';
            case 'FINE': return '과태료';
            case 'OTHER': return '기타';
            default: return type;
        }
    };

    const getPayerLabel = (payer: VehicleExpensePayer) => {
        switch (payer) {
            case 'COMPANY': return '법인카드';
            case 'DRIVER': return '개인(청구)';
            default: return payer;
        }
    };

    const loadExpenses = async () => {
        setLoading(true);
        try {
            const data = await vehicleService.getExpensesByVehicle(vehicle.id, currentMonth);
            setExpenses(data);
        } catch (error) {
            console.error(error);
            toast.error("지출 내역을 불러오지 못했습니다.");
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        if (!amount || Number(amount) <= 0) {
            toast.error("유효한 금액을 입력해주세요.");
            return;
        }

        setSaving(true);
        try {
            await vehicleService.addExpense({
                vehicleId: vehicle.id,
                vehiclePlate: vehicle.licensePlate,
                date,
                type,
                amount: Number(amount),
                payer,
                note
            });
            toast.success("지출 내역이 추가되었습니다.");

            // Reset Form
            setAmount('');
            setNote('');
            loadExpenses(); // Reload
        } catch (error) {
            console.error(error);
            toast.error("저장에 실패했습니다.");
        } finally {
            setSaving(false);
        }
    };

    const handleDelete = async (id: string) => {
        const result = await showConfirmAlert("지출 내역 삭제", "정말 삭제하시겠습니까?");
        if (!result.isConfirmed) return;

        try {
            await vehicleService.deleteExpense(id);
            toast.success("삭제되었습니다.");
            loadExpenses();
        } catch (error) {
            toast.error("삭제에 실패했습니다.");
        }
    };

    const totalAmount = expenses.reduce((sum, item) => sum + item.amount, 0);

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-4xl max-h-[90vh] flex flex-col">
                <div className="p-6 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
                    <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                        <i className="fas fa-gas-pump text-orange-500"></i>
                        차량 지출 내역: {vehicle.licensePlate}
                    </h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
                        <i className="fas fa-times text-xl"></i>
                    </button>
                </div>

                <div className="flex-1 overflow-hidden flex flex-col md:flex-row">
                    {/* Left: Input Form */}
                    <div className="w-full md:w-1/3 p-6 border-r bg-gray-50/50 overflow-y-auto">
                        <h3 className="font-bold text-gray-700 mb-4">새 지출 추가</h3>
                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-600 mb-1">날짜</label>
                                <input
                                    type="date"
                                    value={date}
                                    onChange={e => setDate(e.target.value)}
                                    className="w-full px-3 py-2 border rounded-md focus:ring-2 focus:ring-orange-500 outline-none"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-600 mb-1">구분</label>
                                <div className="grid grid-cols-2 gap-2">
                                    {EXPENSE_TYPES.map(t => (
                                        <button
                                            key={t}
                                            onClick={() => setType(t)}
                                            className={`px-2 py-1.5 text-xs font-bold rounded border ${type === t ? 'bg-orange-100 text-orange-700 border-orange-300' : 'bg-white text-gray-600 hover:bg-gray-50'}`}
                                        >
                                            {getExpenseTypeLabel(t)}
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-600 mb-1">금액 (원)</label>
                                <input
                                    type="number"
                                    value={amount}
                                    onChange={e => setAmount(Number(e.target.value))}
                                    placeholder="0"
                                    className="w-full px-3 py-2 border rounded-md focus:ring-2 focus:ring-orange-500 outline-none text-right font-mono"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-600 mb-1">결제자</label>
                                <div className="flex bg-gray-200 p-1 rounded">
                                    {PAYERS.map(p => (
                                        <button
                                            key={p}
                                            onClick={() => setPayer(p)}
                                            className={`flex-1 py-1 text-xs font-bold rounded ${payer === p ? 'bg-white shadow text-gray-800' : 'text-gray-500'}`}
                                        >
                                            {getPayerLabel(p)}
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-600 mb-1">메모</label>
                                <input
                                    type="text"
                                    value={note}
                                    onChange={e => setNote(e.target.value)}
                                    className="w-full px-3 py-2 border rounded-md focus:ring-2 focus:ring-orange-500 outline-none"
                                    placeholder="메모 입력 (선택)"
                                />
                            </div>

                            <button
                                onClick={handleSave}
                                disabled={saving}
                                className="w-full py-2 bg-orange-600 hover:bg-orange-700 text-white rounded-md font-bold shadow transition-colors"
                            >
                                {saving ? '저장중...' : '추가하기'}
                            </button>
                        </div>
                    </div>

                    {/* Right: List */}
                    <div className="w-full md:w-2/3 flex flex-col h-full">
                        <div className="p-4 border-b flex justify-between items-center bg-white">
                            <div className="flex items-center gap-3">
                                <label className="text-sm font-bold text-gray-600">조회 월:</label>
                                <input
                                    type="month"
                                    value={currentMonth}
                                    onChange={e => setCurrentMonth(e.target.value)}
                                    className="px-2 py-1 border rounded text-sm"
                                />
                            </div>
                            <div className="text-right">
                                <p className="text-xs text-gray-500 uppercase">총 지출액</p>
                                <p className="text-lg font-bold text-gray-800">{totalAmount.toLocaleString()} 원</p>
                            </div>
                        </div>

                        <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
                            {loading ? (
                                <div className="text-center py-10 text-gray-400">불러오는 중...</div>
                            ) : expenses.length === 0 ? (
                                <div className="text-center py-10 text-gray-400">
                                    이번 달 지출 내역이 없습니다.
                                </div>
                            ) : (
                                <div className="space-y-2">
                                    {expenses.map(item => (
                                        <div key={item.id} className="bg-white p-3 rounded border hover:shadow-sm flex justify-between items-center group">
                                            <div className="flex items-start gap-3">
                                                <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white font-bold text-xs
                                                    ${item.type === 'FUEL' ? 'bg-green-500' :
                                                        item.type === 'REPAIR' ? 'bg-red-500' :
                                                            item.type === 'TOLL' ? 'bg-blue-500' : 'bg-gray-500'}`
                                                }>
                                                    {getExpenseTypeLabel(item.type)[0]}
                                                </div>
                                                <div>
                                                    <p className="text-sm font-bold text-gray-800">{item.amount.toLocaleString()} 원</p>
                                                    <p className="text-xs text-gray-500">{item.date} | {getPayerLabel(item.payer)} | {getExpenseTypeLabel(item.type)}</p>
                                                    {item.note && <p className="text-xs text-gray-400 mt-0.5 max-w-[200px] truncate">{item.note}</p>}
                                                </div>
                                            </div>
                                            <button
                                                onClick={() => handleDelete(item.id)}
                                                className="text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                                            >
                                                <i className="fas fa-trash"></i>
                                            </button>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useMemo } from 'react';
import { Vehicle } from '../../types/vehicle';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faCar, faGasPump, faEdit, faUser, faUsers, faWonSign, faCalendarAlt
} from '@fortawesome/free-solid-svg-icons';

interface VehicleListProps {
    vehicles?: Vehicle[]; // Optional to support direct usage or prop usage
    onEdit: (vehicle: Vehicle) => void;
    onManageExpenses: (vehicle: Vehicle) => void;
    onAssign: (vehicle: Vehicle) => void;
}

// Internal default props if needed, but mainly we expect data passed from parent
export const VehicleList: React.FC<VehicleListProps> = ({
    vehicles = [],
    onEdit,
    onManageExpenses,
    onAssign
}) => {

    // Calculate Total Monthly Cost
    const totalMonthlyCost = useMemo(() => {
        return vehicles.reduce((sum, v) => sum + (v.contract?.monthlyFee || 0), 0);
    }, [vehicles]);

    const getStatusBadge = (status: string) => {
        switch (status) {
            case 'ASSIGNED': return <span className="px-2 py-0.5 rounded text-xs font-bold bg-emerald-100 text-emerald-700">운행중</span>;
            case 'AVAILABLE': return <span className="px-2 py-0.5 rounded text-xs font-bold bg-slate-100 text-slate-500">대기중</span>;
            case 'MAINTENANCE': return <span className="px-2 py-0.5 rounded text-xs font-bold bg-orange-100 text-orange-700">정비중</span>;
            default: return <span className="px-2 py-0.5 rounded text-xs font-bold bg-gray-100 text-gray-500">{status}</span>;
        }
    };

    if (!vehicles || vehicles.length === 0) {
        return (
            <div className="p-20 text-center text-slate-400 bg-slate-50 rounded-2xl border border-dashed border-slate-200">
                <div className="flex flex-col items-center gap-3">
                    <FontAwesomeIcon icon={faCar} className="text-4xl text-slate-300" />
                    <p>등록된 차량이 없습니다.</p>
                </div>
            </div>
        );
    }

    return (
        <div className="flex flex-col h-full">
            <div className="bg-white border border-indigo-100 shadow-xl shadow-indigo-50/50 rounded-2xl overflow-hidden flex-1 flex flex-col max-h-[700px]">
                <div className="overflow-x-auto custom-scrollbar flex-1 relative">
                    <table className="w-full text-sm min-w-[1000px]">
                        <thead className="bg-indigo-600 text-white font-bold text-xs uppercase sticky top-0 z-20 shadow-md">
                            <tr>
                                <th className="px-4 py-4 text-left w-20 tracking-wider bg-indigo-700 border-r border-indigo-500">No.</th>
                                <th className="px-4 py-4 text-left w-36 border-r border-indigo-500">차량번호</th>
                                <th className="px-4 py-4 text-left w-32 border-r border-indigo-500">차종/모델</th>
                                <th className="px-4 py-4 text-center w-24 border-r border-indigo-500">상태</th>
                                <th className="px-4 py-4 text-left w-40 border-r border-indigo-500">운행자(팀)</th>
                                <th className="px-4 py-4 text-center w-48 border-r border-indigo-500">계약 기간</th>
                                <th className="px-4 py-4 text-right w-36 border-r border-indigo-500 bg-indigo-500">월 렌트료</th>
                                <th className="px-4 py-4 text-center w-32">관리</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-indigo-50">
                            {vehicles.map((vehicle, idx) => (
                                <tr key={vehicle.id} className="group hover:bg-blue-50/40 transition-colors">
                                    <td className="px-4 py-3 border-r border-indigo-50 text-slate-400 font-mono text-center">
                                        {idx + 1}
                                    </td>
                                    <td className="px-4 py-3 border-r border-indigo-50 font-bold text-slate-700 group-hover:text-indigo-700">
                                        {vehicle.licensePlate}
                                        <div className="text-[10px] text-slate-400 font-normal mt-0.5">{vehicle.type}</div>
                                    </td>
                                    <td className="px-4 py-3 border-r border-indigo-50 text-slate-600">
                                        {vehicle.model}
                                    </td>
                                    <td className="px-4 py-3 border-r border-indigo-50 text-center">
                                        {getStatusBadge(vehicle.status || 'AVAILABLE')}
                                    </td>
                                    <td className="px-4 py-3 border-r border-indigo-50">
                                        {vehicle.currentAssigneeName ? (
                                            <div className="flex items-center gap-2 text-slate-700 font-medium">
                                                <FontAwesomeIcon icon={vehicle.currentAssigneeType === 'TEAM' ? faUsers : faUser} className="text-slate-400 text-xs" />
                                                {vehicle.currentAssigneeName}
                                            </div>
                                        ) : (
                                            <span className="text-slate-300">-</span>
                                        )}
                                    </td>
                                    <td className="px-4 py-3 border-r border-indigo-50 text-center text-xs">
                                        {vehicle.contract?.endDate ? (
                                            <div className="flex flex-col items-center gap-0.5 text-slate-600">
                                                <span>{vehicle.contract.startDate} ~</span>
                                                <span className="font-bold text-slate-700">{vehicle.contract.endDate}</span>
                                            </div>
                                        ) : (
                                            <span className="text-slate-300">-</span>
                                        )}
                                    </td>
                                    <td className="px-4 py-3 border-r border-indigo-50 text-right font-bold text-slate-700 bg-indigo-50/10">
                                        {vehicle.contract?.monthlyFee ? vehicle.contract.monthlyFee.toLocaleString() : 0}
                                    </td>
                                    <td className="px-4 py-3 text-center">
                                        <div className="flex items-center justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button
                                                onClick={() => onManageExpenses(vehicle)}
                                                className="w-7 h-7 rounded bg-indigo-50 text-indigo-600 hover:bg-indigo-100 flex items-center justify-center"
                                                title="비용 관리"
                                            >
                                                <FontAwesomeIcon icon={faGasPump} className="text-xs" />
                                            </button>
                                            <button
                                                onClick={() => onAssign(vehicle)}
                                                className="w-7 h-7 rounded bg-emerald-50 text-emerald-600 hover:bg-emerald-100 flex items-center justify-center"
                                                title="배정"
                                            >
                                                <FontAwesomeIcon icon={faUser} className="text-xs" />
                                            </button>
                                            <button
                                                onClick={() => onEdit(vehicle)}
                                                className="w-7 h-7 rounded bg-slate-100 text-slate-600 hover:bg-slate-200 flex items-center justify-center"
                                                title="수정"
                                            >
                                                <FontAwesomeIcon icon={faEdit} className="text-xs" />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                        <tfoot className="bg-slate-800 text-white font-bold text-sm tracking-wide sticky bottom-0 z-20 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)]">
                            <tr>
                                <td colSpan={6} className="p-4 border-r border-slate-600 text-center">합계 (Total)</td>
                                <td className="p-4 border-r border-slate-600 text-right font-mono text-amber-300 text-lg">
                                    {totalMonthlyCost.toLocaleString()}
                                </td>
                                <td className="bg-slate-900 border-l border-slate-700"></td>
                            </tr>
                        </tfoot>
                    </table>
                </div>
            </div>

            <div className="mt-4 flex items-start gap-3 p-4 bg-slate-50 rounded-xl border border-slate-200 text-xs text-slate-500">
                <FontAwesomeIcon icon={faWonSign} className="text-slate-400 mt-0.5" />
                <p>
                    * <strong>월 렌트료</strong>는 차량 계약 정보에 등록된 고정 비용의 합계입니다.<br />
                    * 주유비, 하이패스 등 변동 비용은 <strong>[월별 비용 정산]</strong> 탭에서 확인하실 수 있습니다.
                </p>
            </div>
        </div>
    );
};

import React, { useMemo, useState } from 'react';
import { Vehicle } from '../../types/vehicle';
import { Team } from '../../services/teamService';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faCar, faGasPump, faWrench, faCheckCircle, faClock,
    faWonSign, faExclamationTriangle, faCalendarAlt, faUser, faUsers,
    faList, faTh, faTrash, faPlus, faFileInvoiceDollar
} from '@fortawesome/free-solid-svg-icons';
import { iconMap } from '../../constants/iconMap';

interface TeamInfo {
    color: string;
    icon?: string;
}

interface VehicleStatusBoardProps {
    vehicles: Vehicle[];
    teams?: Team[];
    loading: boolean;
    onEdit: (vehicle: Vehicle) => void;
    onManageExpenses: (vehicle: Vehicle) => void;
    onAssign: (vehicle: Vehicle) => void;
    onOpenBilling: (vehicle: Vehicle) => void;
}

const getTeamFaIcon = (iconName?: string) => {
    if (!iconName) return faUsers;
    return iconMap[iconName] || faUsers;
};

/** HEX → rgba 변환 유틸 */
const hexToRgba = (hex: string, alpha: number) => {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return `rgba(${r},${g},${b},${alpha})`;
};

export const VehicleStatusBoard: React.FC<VehicleStatusBoardProps> = ({
    vehicles,
    teams = [],
    loading,
    onEdit,
    onManageExpenses,
    onAssign,
    onOpenBilling
}) => {
    const [viewMode, setViewMode] = useState<'list' | 'card'>('list');

    // Build team info map: assigneeName -> {color, icon}
    const teamInfoMap = useMemo(() => {
        const map = new Map<string, TeamInfo>();
        teams.forEach(t => {
            if (t.color && t.name) map.set(t.name, { color: t.color, icon: t.icon || t.iconKey });
        });
        return map;
    }, [teams]);

    // 1. Statistics Calculation
    const stats = useMemo(() => {
        const total = vehicles.length;
        const operating = vehicles.filter(v => v.status === 'ASSIGNED').length;
        const available = vehicles.filter(v => v.status === 'AVAILABLE').length;
        const maintenance = vehicles.filter(v => v.status === 'MAINTENANCE').length;

        const totalMonthlyCost = vehicles.reduce((sum, v) => sum + (v.contract?.monthlyFee || 0), 0);

        return { total, operating, available, maintenance, totalMonthlyCost };
    }, [vehicles]);

    // 2. Alert Logic (Contracts expiring soon, etc.)
    const expiringVehicles = useMemo(() => {
        const today = new Date();
        return vehicles.filter(v => {
            if (!v.contract?.endDate) return false;
            const endDate = new Date(v.contract.endDate);
            const diffTime = endDate.getTime() - today.getTime();
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
            return diffDays >= 0 && diffDays <= 30; // Expiring in 30 days
        });
    }, [vehicles]);

    // 3. Sorting Logic: Rent > Lease > Others
    const sortedVehicles = useMemo(() => {
        return [...vehicles].sort((a, b) => {
            const getPriority = (type: string) => {
                if (type === 'RENT') return 0;
                if (type === 'LEASE') return 1;
                return 2;
            };
            const pA = getPriority(a.type || '');
            const pB = getPriority(b.type || '');
            if (pA !== pB) return pA - pB;
            return (a.licensePlate || '').localeCompare(b.licensePlate || '');
        });
    }, [vehicles]);

    const getStatusBadge = (status: string) => {
        switch (status) {
            case 'ASSIGNED':
                return (
                    <span className="px-2.5 py-1 rounded-lg text-xs font-bold bg-emerald-50 text-emerald-600 border border-emerald-100 flex items-center gap-1.5">
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
                        운행중
                    </span>
                );
            case 'AVAILABLE':
                return (
                    <span className="px-2.5 py-1 rounded-lg text-xs font-bold bg-slate-100 text-slate-500 border border-slate-200 flex items-center gap-1.5">
                        <div className="w-1.5 h-1.5 rounded-full bg-slate-400"></div>
                        대기중
                    </span>
                );
            case 'MAINTENANCE':
                return (
                    <span className="px-2.5 py-1 rounded-lg text-xs font-bold bg-orange-50 text-orange-600 border border-orange-100 flex items-center gap-1.5">
                        <div className="w-1.5 h-1.5 rounded-full bg-orange-500 animate-pulse"></div>
                        정비중
                    </span>
                );
            default:
                return null;
        }
    };

    /** 테이블용 상태 배지 (inline) */
    const getStatusBadgeInline = (status: string) => {
        switch (status) {
            case 'ASSIGNED':
                return (
                    <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-xs font-bold bg-emerald-50 text-emerald-600 border border-emerald-100">
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
                        운행중
                    </span>
                );
            case 'AVAILABLE':
                return (
                    <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-xs font-bold bg-slate-100 text-slate-500 border border-slate-200">
                        <div className="w-1.5 h-1.5 rounded-full bg-slate-400"></div>
                        대기중
                    </span>
                );
            case 'MAINTENANCE':
                return (
                    <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-xs font-bold bg-orange-50 text-orange-600 border border-orange-100">
                        <div className="w-1.5 h-1.5 rounded-full bg-orange-500 animate-pulse"></div>
                        정비중
                    </span>
                );
            default:
                return <span className="text-xs text-slate-300">-</span>;
        }
    };

    /** 차량 타입 라벨 */
    const getTypeLabel = (type: string) => {
        switch (type) {
            case 'RENT': return '렌트';
            case 'LEASE': return '리스';
            case 'OWNED': return '자가';
            default: return type;
        }
    };

    const getBillingTargetTypeLabel = (vehicle: Vehicle) => {
        if (!vehicle.currentAssigneeName) return null;
        return vehicle.currentAssigneeType === 'TEAM' ? '팀' : '개인';
    };

    if (loading) {
        return (
            <div className="h-64 flex items-center justify-center text-slate-400">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
            </div>
        );
    }

    if (vehicles.length === 0) {
        return (
            <div className="bg-white rounded-3xl border border-dashed border-slate-300 p-20 text-center">
                <div className="bg-slate-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6 text-slate-300">
                    <FontAwesomeIcon icon={faCar} className="text-4xl" />
                </div>
                <h3 className="text-xl font-bold text-slate-700 mb-2">등록된 법인차량이 없습니다</h3>
                <p className="text-slate-400 mb-6">새로운 차량을 등록하여 관리를 시작해보세요.</p>
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-fade-in-up">
            {/* Alerts Section */}
            {expiringVehicles.length > 0 && (
                <div className="bg-amber-50 border border-amber-200 rounded-2xl p-4 flex items-start gap-4 shadow-sm">
                    <div className="bg-amber-100 p-2 rounded-full text-amber-600">
                        <FontAwesomeIcon icon={faExclamationTriangle} className="animate-swing" />
                    </div>
                    <div className="flex-1">
                        <h3 className="font-bold text-amber-800 text-sm mb-1">계약 만료 예정 차량이 {expiringVehicles.length}대 있습니다</h3>
                        <div className="flex flex-wrap gap-2">
                            {expiringVehicles.map(v => (
                                <span key={v.id} className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-white border border-amber-200 text-xs font-bold text-amber-700 shadow-sm">
                                    <FontAwesomeIcon icon={faCar} className="text-amber-400" />
                                    {v.licensePlate} ({v.contract?.endDate})
                                </span>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-5">
                {/* Total Stats */}
                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-[0_4px_20px_-4px_rgba(0,0,0,0.05)] hover:shadow-lg transition-shadow relative overflow-hidden group">
                    <div className="absolute right-0 top-0 w-32 h-32 bg-slate-50 rounded-full -mr-10 -mt-10 group-hover:scale-110 transition-transform"></div>
                    <div className="relative z-10">
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">총 보유 차량</p>
                        <div className="flex items-baseline gap-2">
                            <h3 className="text-3xl font-extrabold text-slate-800">{stats.total}</h3>
                            <span className="text-sm font-bold text-slate-400">대</span>
                        </div>
                        <div className="mt-4 flex items-center gap-2 text-xs font-medium text-slate-500 bg-slate-100 w-fit px-2 py-1 rounded-lg">
                            <FontAwesomeIcon icon={faCar} className="text-slate-400" /> 전체 법인차량
                        </div>
                    </div>
                </div>

                {/* Operating Stats */}
                <div className="bg-white p-6 rounded-2xl border border-emerald-100 shadow-[0_4px_20px_-4px_rgba(16,185,129,0.1)] hover:shadow-lg transition-shadow relative overflow-hidden group">
