import React, { useRef, useEffect, useState, useCallback } from 'react';
import { Memo, ChecklistItem } from '../types/memo';
import { useMemoStore } from '../store/useMemoStore';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCheck, faPlus, faComment, faTrash } from '@fortawesome/free-solid-svg-icons';

import { AnimatePresence, motion } from 'framer-motion';

interface MemoChecklistProps {
    memo: Memo;
}

export const MemoChecklist: React.FC<MemoChecklistProps> = ({ memo }) => {
    const { addChecklistItem, updateChecklistItem, deleteChecklistItem, toggleChecklistItem, addChecklistComment, deleteChecklistComment } = useMemoStore();
    const [focusedId, setFocusedId] = useState<string | null>(null);
    const [expandedComments, setExpandedComments] = useState<Record<string, boolean>>({});
    const textareaRefs = useRef<Record<string, HTMLTextAreaElement | null>>({});

    const toggleComments = (itemId: string) => {
        setExpandedComments(prev => ({ ...prev, [itemId]: !prev[itemId] }));
    };

    const handleAddComment = (itemId: string, text: string) => {
        if (!text.trim()) return;
        addChecklistComment(memo.id, itemId, text);
    };

    const items = memo.checklistItems || [];

    const adjustHeight = useCallback((id: string) => {
        const el = textareaRefs.current[id];
        if (el) {
            el.style.height = 'auto';
            el.style.height = el.scrollHeight + 'px';
        }
    }, []);

    // Focus management
    useEffect(() => {
        if (focusedId && textareaRefs.current[focusedId]) {
            textareaRefs.current[focusedId]?.focus();
            adjustHeight(focusedId);
        }
    }, [focusedId, items, adjustHeight]);

    // Auto-resize trigger
    useEffect(() => {
        items.forEach(item => adjustHeight(item.id));
    }, [items, adjustHeight]);

    const handleKeyDown = (e: React.KeyboardEvent, index: number, item: ChecklistItem) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            const nextIndex = index + 1;
            addChecklistItem(memo.id, '', nextIndex);
        } else if (e.key === 'Backspace' && item.text === '') {
            e.preventDefault();
            if (items.length > 1) {
                const prevIndex = index - 1;
                deleteChecklistItem(memo.id, item.id);
                if (prevIndex >= 0) {
                    setFocusedId(items[prevIndex].id);
                }
            }
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            const prevIndex = index - 1;
            if (prevIndex >= 0) {
                setFocusedId(items[prevIndex].id);
            }
        } else if (e.key === 'ArrowDown') {
            e.preventDefault();
            const nextIndex = index + 1;
            if (nextIndex < items.length) {
                setFocusedId(items[nextIndex].id);
            }
        }
    };

    const handleChange = (id: string, text: string) => {
        updateChecklistItem(memo.id, id, text);
        adjustHeight(id);
    };

    return (
        <div className="flex flex-col gap-0.5">
            {items.map((item, index) => (
                <React.Fragment key={item.id}>
                    <div className="group flex items-start gap-2 py-1">
                        {/* Checkbox */}
                        <button
                            onClick={() => toggleChecklistItem(memo.id, item.id)}
                            className={`
                                flex-shrink-0 w-4 h-4 rounded mt-1 ml-[-2px] border transition-colors duration-200 flex items-center justify-center
                                ${item.isChecked
                                    ? 'bg-slate-500 border-slate-500 text-white'
                                    : 'bg-white border-slate-300 hover:border-slate-400 shadow-sm'}
                            `}
                        >
                            {item.isChecked && <FontAwesomeIcon icon={faCheck} className="text-[10px]" />}
                        </button>

                        {/* Textarea */}
                        <textarea
                            ref={el => { textareaRefs.current[item.id] = el; }}
                            value={item.text}
                            onChange={(e) => handleChange(item.id, e.target.value)}
                            onKeyDown={(e) => handleKeyDown(e, index, item)}
                            onFocus={() => setFocusedId(item.id)}
                            rows={1}
                            placeholder={items.length === 1 ? "리스트 아이템 입력..." : ""}
                            className={`
                                flex-1 bg-transparent outline-none text-slate-700 text-sm placeholder:text-slate-300 resize-none overflow-hidden min-h-[24px] leading-relaxed
                                ${item.isChecked ? 'line-through text-slate-400' : ''}
                            `}
                        />

                        {/* Comment Button */}
                        <button
                            onClick={() => toggleComments(item.id)}
                            className={`opacity-0 group-hover:opacity-100 transition-opacity p-1 mt-0.5 hover:text-slate-500 ${(item.comments?.length || 0) > 0 ? 'opacity-100 text-slate-400' : 'text-slate-300'
                                }`}
                            tabIndex={-1}
                            title="댓글"
                        >
                            <div className="relative">
                                <FontAwesomeIcon icon={faComment} className="text-xs" />
                                {(item.comments?.length || 0) > 0 && (
                                    <span className="absolute -top-1.5 -right-1.5 bg-slate-500 text-white text-[8px] px-1 rounded-full min-w-[12px] h-[12px] flex items-center justify-center">
                                        {item.comments?.length}
                                    </span>
                                )}
                            </div>
                        </button>

                        {/* Delete Button */}
                        <button
                            onClick={() => deleteChecklistItem(memo.id, item.id)}
                            className="opacity-0 group-hover:opacity-100 transition-opacity p-1 mt-0.5 text-slate-300 hover:text-slate-500"
                            tabIndex={-1}
                        >
                            &times;
                        </button>
                    </div>

                    {/* Comments Section */}
                    <AnimatePresence>
                        {expandedComments[item.id] && (
                            <motion.div
                                initial={{ height: 0, opacity: 0 }}
                                animate={{ height: 'auto', opacity: 1 }}
                                exit={{ height: 0, opacity: 0 }}
                                className="overflow-hidden ml-8 mr-2 mb-2"
                            >
                                <div className="bg-slate-50 rounded pl-2 pr-1 py-1 flex flex-col gap-1 border border-slate-100">
                                    {item.comments?.map(comment => (
                                        <div key={comment.id} className="flex items-start gap-2 group/comment text-xs text-slate-600 mb-1">
                                            <div className="flex-1 whitespace-pre-wrap break-words">{comment.text}</div>
                                            <button
                                                onClick={() => deleteChecklistComment(memo.id, item.id, comment.id)}
                                                className="opacity-0 group-hover/comment:opacity-100 text-slate-300 hover:text-red-400 px-1"
                                            >
                                                <FontAwesomeIcon icon={faTrash} size="xs" />
                                            </button>
                                        </div>
                                    ))}
                                    <input
                                        type="text"
                                        placeholder="댓글 입력..."
                                        className="w-full text-xs bg-transparent outline-none placeholder:text-slate-300 mt-1"
                                        onKeyDown={(e) => {
                                            if (e.key === 'Enter') {
                                                handleAddComment(item.id, e.currentTarget.value);
                                                e.currentTarget.value = '';
                                            }
                                        }}
                                    />
                                </div>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </React.Fragment>
            ))}

            {/* Add Item Button */}
            <div
                className="flex items-center gap-2 py-1 opacity-50 hover:opacity-100 cursor-text transition-opacity"
                onClick={() => addChecklistItem(memo.id, '')}
            >
                <div className="w-4 h-4 ml-[-2px] flex items-center justify-center">
                    <FontAwesomeIcon icon={faPlus} className="text-xs text-slate-400" />
                </div>
                <span className="text-sm text-slate-400">항목 추가</span>
            </div>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';
import { useMemoStore } from '../store/useMemoStore';
import { useMemo$ } from '../hooks/useMemoSelector';
import { cn } from '../lib/utils';
import { X, Trash2, Globe, Pin, List, FileText } from 'lucide-react';
import debounce from 'lodash.debounce';

const COLOR_MAP: Record<string, string> = {
    white: 'bg-white',
    red: 'bg-rose-100',
    orange: 'bg-orange-100',
    yellow: 'bg-amber-100',
    green: 'bg-emerald-100',
    blue: 'bg-sky-100',
    purple: 'bg-violet-100',
    gray: 'bg-slate-100',
};

export const MemoDetailModal: React.FC = () => {
    const expandedMemoId = useMemoStore(state => state.selectedMemoId); // Mapped to selectedMemoId now
    const setExpandedMemoId = useMemoStore(state => state.setSelectedMemoId);
    const updateMemo = useMemoStore(state => state.updateMemo);
    const deleteMemo = useMemoStore(state => state.deleteMemo);
    const convertToChecklist = useMemoStore(state => state.convertToChecklist);
    const convertToText = useMemoStore(state => state.convertToText);

    const memo = useMemo$(expandedMemoId);

    const [title, setTitle] = useState('');
    const [content, setContent] = useState('');
    const titleRef = useRef<HTMLInputElement>(null);
    const contentRef = useRef<HTMLTextAreaElement>(null);

    // Sync local state with memo
    useEffect(() => {
        if (memo) {
            setTitle(memo.title || '');
            setContent(memo.content || '');
        }
    }, [memo?.id]); // Only on memo change

    // Debounced save
    const debouncedSave = useRef(
        debounce((id: string, updates: Record<string, any>) => {
            void updateMemo(id, updates).catch(() => { });
        }, 600)
    ).current;

    useEffect(() => {
        return () => {
            debouncedSave.flush();
            debouncedSave.cancel();
        };
    }, [debouncedSave]);

    const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setTitle(e.target.value);
        if (memo) debouncedSave(memo.id, { title: e.target.value });
    };

    const handleContentChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        setContent(e.target.value);
        if (memo) debouncedSave(memo.id, { content: e.target.value });
    };

    const handleClose = () => {
        debouncedSave.flush(); // Ensure pending save is committed
        setExpandedMemoId(null);
    };

    const handleDelete = async () => {
        if (memo) {
            await deleteMemo(memo.id);
            setExpandedMemoId(null);
        }
    };

    const handleTogglePin = () => {
        if (memo) updateMemo(memo.id, { isPinned: !memo.isPinned });
    };

    const handleToggleType = () => {
        if (memo) {
            if (memo.type === 'checklist') {
                convertToText(memo.id);
            } else {
                convertToChecklist(memo.id);
            }
        }
    };

    if (!memo) return null;

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm"
            onClick={handleClose}
        >
            <motion.div
                layoutId={`memo-card-${memo.id}`}
                className={cn(
                    "relative w-full max-w-2xl max-h-[80vh] m-4 rounded-2xl shadow-2xl overflow-hidden flex flex-col",
                    COLOR_MAP[memo.color] || COLOR_MAP.white
                )}
                onClick={(e) => e.stopPropagation()}
            >
                {/* Header */}
                <div className="flex items-center justify-between px-6 py-4 border-b border-black/5">
                    <div className="flex items-center gap-3 flex-1">
                        {memo.scope === 'public' && (
                            <div className="flex items-center gap-1 px-2 py-1 rounded-full bg-blue-100 text-blue-600">
                                <Globe size={12} />
                                <span className="text-[10px] font-bold">Public</span>
                            </div>
                        )}
                        <input
                            ref={titleRef}
                            type="text"
                            value={title}
                            onChange={handleTitleChange}
                            placeholder="제목 없음"
                            className="flex-1 bg-transparent text-xl font-bold text-slate-800 placeholder:text-slate-400 outline-none"
                        />
                    </div>
                    <div className="flex items-center gap-2">
                        <button
                            onClick={handleTogglePin}
                            className={cn(
                                "p-2 rounded-lg transition-colors",
                                memo.isPinned
                                    ? "bg-amber-100 text-amber-600"
                                    : "text-slate-400 hover:bg-slate-100"
                            )}
                            title={memo.isPinned ? "고정 해제" : "고정"}
                        >
                            <Pin size={18} />
                        </button>
                        <button
                            onClick={handleToggleType}
                            className="p-2 rounded-lg text-slate-400 hover:bg-slate-100 transition-colors"
                            title={memo.type === 'checklist' ? "텍스트로 변환" : "체크리스트로 변환"}
                        >
                            {memo.type === 'checklist' ? <FileText size={18} /> : <List size={18} />}
                        </button>
                        <button
                            onClick={handleDelete}
                            className="p-2 rounded-lg text-red-400 hover:bg-red-100 hover:text-red-600 transition-colors"
                            title="삭제"
                        >
                            <Trash2 size={18} />
                        </button>
                        <button
                            onClick={handleClose}
                            className="p-2 rounded-lg text-slate-400 hover:bg-slate-100 transition-colors"
                            title="닫기"
                        >
                            <X size={18} />
                        </button>
                    </div>
                </div>

                {/* Body */}
                <div className="flex-1 p-6 overflow-y-auto">
                    {memo.type === 'checklist' ? (
                        <div className="space-y-2">
                            {(memo.checklistItems || []).map(item => (
                                <div key={item.id} className="flex items-start gap-3">
                                    <input
                                        type="checkbox"
                                        checked={item.isChecked}
                                        onChange={() => useMemoStore.getState().toggleChecklistItem(memo.id, item.id)}
                                        className="mt-1 w-4 h-4 accent-slate-600"
                                    />
                                    <span className={cn(
                                        "flex-1 text-slate-700",
                                        item.isChecked && "line-through text-slate-400"
                                    )}>
                                        {item.text || <span className="text-slate-300 italic">빈 항목</span>}
                                    </span>
                                </div>
                            ))}
                            {(!memo.checklistItems || memo.checklistItems.length === 0) && (
                                <p className="text-slate-400 italic">체크리스트 항목이 없습니다.</p>
                            )}
                        </div>
                    ) : (
                        <textarea
                            ref={contentRef}
                            value={content}
                            onChange={handleContentChange}
                            placeholder="내용을 입력하세요..."
                            className="w-full h-full min-h-[200px] bg-transparent text-slate-700 placeholder:text-slate-400 outline-none resize-none"
                        />
                    )}
                </div>

                {/* Footer */}
                <div className="px-6 py-3 border-t border-black/5 text-xs text-slate-400">
                    마지막 수정: {memo.updatedAt?.toDate?.()?.toLocaleString?.() || '방금 전'}
                </div>
            </motion.div>
        </motion.div>
    );
};

import React, { useEffect, useState, useMemo, useCallback, useRef } from 'react';
import { useResizeDetector } from 'react-resize-detector';
import { ResponsiveGridLayout } from 'react-grid-layout';
import 'react-grid-layout/css/styles.css';
import 'react-resizable/css/styles.css';

import { useMemoStore } from '../store/useMemoStore';
import { MemoCard } from '../components/MemoCard';
import { useAuth } from '../../../contexts/AuthContext';
import { Button } from '../components/ui/Button';
import {
    LayoutDashboard,
    Plus,
    Search,
    Settings,
    ArrowDownWideNarrow,
    Palette,
    GripHorizontal,
    MoreHorizontal,
    Globe,
    Inbox,
    ChevronsDown,
    ChevronsUp
} from 'lucide-react';
import { cn } from '../lib/utils';
import { CategoryManagerDialog } from '../components/CategoryManagerDialog';

const DEFAULT_W = 4;
const DEFAULT_H = 4;
const GRID_ROW_HEIGHT = 50; // Adjusted for better density
const BREAKPOINTS = { lg: 1200, md: 996, sm: 768, xs: 480, xxs: 0 };
const COLS = { lg: 12, md: 10, sm: 6, xs: 4, xxs: 2 };
const MARGIN_X = 20;
const MARGIN_Y = 20;

const isFiniteNumber = (val: unknown): val is number => typeof val === 'number' && Number.isFinite(val);

export const MemoPage = () => {
    const { width, ref } = useResizeDetector();
    const { currentUser } = useAuth();

    const memos = useMemoStore(state => state.memos);
    const subscribeMemos = useMemoStore(state => state.subscribeMemos);
    const addMemo = useMemoStore(state => state.addMemo);
    const deleteMemo = useMemoStore(state => state.deleteMemo);
    const updateMemo = useMemoStore(state => state.updateMemo);
    const updateMemoLayouts = useMemoStore(state => state.updateMemoLayouts);
    const repackMemos = useMemoStore(state => state.repackMemos);
    const setMemosCollapsed = useMemoStore(state => state.setMemosCollapsed);
    const loadingState = useMemoStore(state => state.isLoading);
    const errorState = useMemoStore(state => state.error);
    const addCategory = useMemoStore(state => state.addCategory);
    const categories = useMemoStore(state => state.categories);

    const [selectedCategoryId, setSelectedCategoryId] = useState<string>('all');
    const [isLocalLoading, setIsLocalLoading] = useState(true);
    const [currentCols, setCurrentCols] = useState<number>(COLS.lg);
    const [currentBreakpoint, setCurrentBreakpoint] = useState<string>('lg');
    const [isCategoryManagerOpen, setIsCategoryManagerOpen] = useState(false);

    const [dismissedError, setDismissedError] = useState<string | null>(null);

    useEffect(() => {
        setDismissedError(null);
    }, [errorState]);

    const errorMessage = useMemo(() => {
        if (!errorState) return null;
        if (errorState.includes('smartMemoCategories')) {
            return '카테고리 로드에 실패했어요. 메모는 계속 사용할 수 있어요.';
        }
        return errorState;
    }, [errorState]);

    // 1. Stable Subscription
    useEffect(() => {
        if (!currentUser?.uid) {
            setIsLocalLoading(false);
            return;
        }

        setIsLocalLoading(true);
        const unsubscribe = subscribeMemos({
            uid: currentUser.uid,
            email: currentUser.email
        });

        // Safety timeout
        const timer = setTimeout(() => setIsLocalLoading(false), 2000);

        return () => {
            clearTimeout(timer);
            unsubscribe();
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [currentUser?.uid]);

    // 2. Sync Global Loading
    useEffect(() => {
        if (!loadingState) setIsLocalLoading(false);
    }, [loadingState]);

    const handleCreate = async () => {
        if (!currentUser?.uid) return;
        try {
            await addMemo({
                title: 'New Memo',
                content: '',
                categoryId: selectedCategoryId === 'all' ? null : selectedCategoryId,
                w: DEFAULT_W,
                h: DEFAULT_H,
                x: 0,
                y: 0,
                color: 'white',
                isCollapsed: false,
                isPinned: false,
                type: 'text',
                order: 0
            }, currentUser.uid);
        } catch (error) {
            console.error("Failed to create memo:", error);
        }
    };

    // 3. Stable Persistence
    const handleLayoutSave = useCallback((layout: any) => {
        if (!Array.isArray(layout)) return;

        const updates = layout.map((l) => ({
            i: l.i,
            x: l.x,
            y: l.y,
            w: l.w,
            h: l.h
        }));

        void updateMemoLayouts(updates).catch(() => { });
    }, [updateMemoLayouts]);

    const [isSortOpen, setIsSortOpen] = useState(false);

    const layoutVersion = useMemoStore(state => state.layoutVersion);
    const searchQuery = useMemoStore(state => state.searchQuery);
    const setSearchQuery = useMemoStore(state => state.setSearchQuery);

    const categoryScopedMemos = useMemo(() => {
        return memos.filter(memo => {
            if (selectedCategoryId === 'all') return true;
            if (selectedCategoryId === 'uncategorized') return !memo.categoryId;
            return memo.categoryId === selectedCategoryId;
        });
    }, [memos, selectedCategoryId]);

    const sortScopeIds = useMemo(() => categoryScopedMemos.map(m => m.id), [categoryScopedMemos]);

    const filteredMemos = useMemo(() => {
        return categoryScopedMemos.filter(memo => {
            if (!searchQuery) return true;
            return (
                memo.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
                memo.content?.toLowerCase().includes(searchQuery.toLowerCase()) ||
                memo.checklistItems?.some(item => item.text.toLowerCase().includes(searchQuery.toLowerCase()))
            );
        });
    }, [categoryScopedMemos, searchQuery]);

    const visibleMemoIds = useMemo(() => filteredMemos.map(m => m.id), [filteredMemos]);
    const isAllCollapsed = useMemo(() => filteredMemos.length > 0 && filteredMemos.every(m => m.isCollapsed), [filteredMemos]);

    // 4. Robust Layout Generation
    const [isDragging, setIsDragging] = useState(false);
    const lastLayoutsRef = useRef<any>({});

    const handleMemoSizeChange = useCallback((id: string, size: { height: number }) => {
        // Prevent updates during drag to avoid fighting
        if (isDragging) return;

        const memo = useMemoStore.getState().memos.find(m => m.id === id);
        if (!memo || memo.isCollapsed) return;

        const neededH = Math.ceil((size.height + MARGIN_Y) / (GRID_ROW_HEIGHT + MARGIN_Y));
        const finalH = Math.max(2, neededH); // Min 2 rows

        if (finalH !== memo.h) {
            void updateMemo(id, { h: finalH }).catch(() => { });
        }
    }, [memos, updateMemo, isDragging]);

    const handleSetAllCollapsed = useCallback((collapsed: boolean) => {
        if (visibleMemoIds.length === 0) return;
        void setMemosCollapsed(visibleMemoIds, collapsed, { gridCols: currentCols }).catch(() => { });
    }, [visibleMemoIds, setMemosCollapsed, currentCols]);

    const layouts = useMemo(() => {
        // Stability: Return stale layout during dragging
        if (isDragging && Object.keys(lastLayoutsRef.current).length > 0) {
            return lastLayoutsRef.current;
        }

        const breakpoints = Object.keys(COLS) as Array<keyof typeof COLS>;
        const result = breakpoints.reduce<Record<string, Array<{ i: string; x: number; y: number; w: number; h: number }>>>((acc, bp) => {
            const cols = COLS[bp];
            acc[bp] = filteredMemos.map(m => {
                const rawW = m.w ?? DEFAULT_W;
                const w = Math.min(Math.max(1, rawW), cols);
                const rawX = m.x ?? 0;
                // Clamp X to fit in columns
                const x = Math.max(0, Math.min(rawX, Math.max(0, cols - w)));

                return {
                    i: m.id,
                    x,
                    y: isFiniteNumber(m.y) ? m.y : 0, // Trust store, default to 0
                    w,
                    h: m.isCollapsed ? 1 : (m.h ?? DEFAULT_H)
                };
            });
            return acc;
        }, {});

        lastLayoutsRef.current = result;
        return result;
    }, [filteredMemos, isDragging]);

    // Close sort menu on click outside
    useEffect(() => {
        const closeSort = () => setIsSortOpen(false);
