                let updateCount = 0;
                layouts.forEach((layout: any) => {
                    const original = previousMemos.find(m => m.id === layout.i);
                    if (
                        original &&
                        (original.x !== layout.x || original.y !== layout.y || original.w !== layout.w || original.h !== layout.h)
                    ) {
