                            x: layout.x,
                            y: layout.y,
                            w: layout.w,
                            h: layout.h,
                            updatedAt: serverTimestamp()
                        });
                        updateCount++;
                    }
                });
                if (updateCount > 0) {
                    await batch.commit();
                }
                return;
            }

            const uuidById = await listSmartMemoUuidMap();
            const updates: Promise<any>[] = [];

            layouts.forEach((layout: any) => {
                const original = previousMemos.find(m => m.id === layout.i);
