    toggleMemoCollapse: async (id, updates) => {
        const state = get();
        const memo = state.memos.find(m => m.id === id);

        if (!memo) return;
        if (memo.isCollapsed === updates.isCollapsed) return;

        // 1. Calculate new dimensions
        // Collapsed size: W=2, H=1 (Title only view)
        const COLLAPSED_W = 2;
        const COLLAPSED_H = 1;

        const newW = updates.isCollapsed ? COLLAPSED_W : (memo.prevW || memo.w || 4);
        const newH = updates.isCollapsed ? COLLAPSED_H : (memo.prevH || memo.h || 4);

        // 2. Optimistic State Preparation
        // Deep copy needed for mutation during collision resolution
        let newMemos = state.memos.map(m => m.id === id
            ? { ...m, isCollapsed: updates.isCollapsed, w: newW, h: newH }
            : { ...m }
        );

        // 3. PUSH LOGIC (Only when Expanding)
        // If expanding, we shove other memos down to make space.
        if (!updates.isCollapsed) {
            const collides = (r1: any, r2: any) => {
                return (r1.x < r2.x + r2.w && r1.x + r1.w > r2.x && r1.y < r2.y + r2.h && r1.y + r1.h > r2.y);
            };

            const resolveCollisions = () => {
                let changed = false;
                // Sort by Y (top to bottom) to resolve cascading pushes
                newMemos.sort((a, b) => a.y - b.y || a.x - b.x);

                for (let i = 0; i < newMemos.length; i++) {
                    const m1 = newMemos[i];
                    for (let j = 0; j < newMemos.length; j++) {
                        const m2 = newMemos[j];
                        if (m1.id === m2.id) continue;

                        if (collides(m1, m2)) {
                            // Collision detected. 
                            // Rule: The one that is "below" or isn't the active one moves.
                            let mover, anchor;

                            if (m1.id === id) { mover = m2; anchor = m1; }
                            else if (m2.id === id) { mover = m1; anchor = m2; }
                            else {
                                // If neither is the expander, move the one visibly lower
                                if (m1.y < m2.y) { mover = m2; anchor = m1; }
                                else { mover = m1; anchor = m2; }
                            }

                            // Move mover below anchor
                            const requiredY = anchor.y + anchor.h;
                            if (mover.y < requiredY) {
                                mover.y = requiredY;
                                changed = true;
                            }
                        }
                    }
                }
                return changed;
            };

            // Run resolution until stable (max 10 passes to prevent infinite loops)
            let passes = 0;
            while (resolveCollisions() && passes < 10) {
                passes++;
            }
        }

        // 4. Update Store
        set((s) => ({ memos: newMemos, layoutVersion: s.layoutVersion + 1 }));

        // 5. Update Firestore
        try {
            if (activeMemoBackend === 'firestore') {
                const batch = writeBatch(db);
                const targetData: any = {
                    isCollapsed: updates.isCollapsed,
                    w: newW,
                    h: newH,
                    updatedAt: serverTimestamp()
                };

                if (updates.isCollapsed) {
                    targetData.prevW = memo.w;
                    targetData.prevH = memo.h;
                } else {
                    targetData.prevW = deleteField();
                    targetData.prevH = deleteField();
                }

                batch.update(doc(db, MEMO_COLLECTION, id), targetData);

                newMemos.forEach((m) => {
                    if (m.id === id) return;
                    const original = state.memos.find(om => om.id === m.id);
                    if (original && (original.x !== m.x || original.y !== m.y)) {
                        batch.update(doc(db, MEMO_COLLECTION, m.id), {
                            x: m.x,
                            y: m.y,
                            updatedAt: serverTimestamp()
                        });
                    }
                });

                await batch.commit();
                return;
            }

            const uuidById = await listSmartMemoUuidMap();
            const targetUuid = uuidById.get(id);

            if (targetUuid) {
                const targetData: any = {
                    id: targetUuid,
                    isCollapsed: updates.isCollapsed,
                    w: newW,
                    h: newH
                };

                if (updates.isCollapsed) {
                    targetData.prevW = memo.w;
                    targetData.prevH = memo.h;
                } else {
                    targetData.prevW = null;
                    targetData.prevH = null;
                }

                await updateSmartMemo(targetData);
            }

            await Promise.all(
                newMemos.map(async (m) => {
                    if (m.id === id) return;
                    const original = state.memos.find(om => om.id === m.id);
                    if (original && (original.x !== m.x || original.y !== m.y)) {
                        const uuid = uuidById.get(m.id);
                        if (!uuid) return;
                        await updateSmartMemo({ id: uuid, x: m.x, y: m.y } as any);
                    }
                })
            );
        } catch (error: any) {
            console.error("Failed to toggle collapse:", error);
            // Rollback on error
            set({ memos: state.memos, error: error.message });
        }
    },

    repackMemos: async (strategy: 'date-desc' | 'date-asc' | 'title' = 'date-desc', options) => {
        const previousMemos = get().memos;

        const gridCols = Math.max(1, Math.floor(options?.gridCols ?? 12));
        const scopeSet = options?.scopeIds ? new Set(options.scopeIds) : null;
        const scopeMemos = scopeSet ? previousMemos.filter(m => scopeSet.has(m.id)) : previousMemos;

        const sortedMemos = [...scopeMemos];

        const getUpdatedMillis = (memo: Memo) => {
            const val = memo.updatedAt;
            // Handle Firestore Timestamp
            if (val && typeof val.toMillis === 'function') {
                return val.toMillis();
            }
            // Handle Optimistic ServerTimestamp (FieldValue or similar object)
            // If it exists but no toMillis, assume it's "now" (pending write)
            if (val && typeof val === 'object') {
                return Date.now();
            }
            // Fallback for missing date
            return 0;
        };

        sortedMemos.sort((a, b) => {
            const pinnedA = a.isPinned ? 1 : 0;
            const pinnedB = b.isPinned ? 1 : 0;
            if (pinnedA !== pinnedB) return pinnedB - pinnedA;

            if (strategy === 'date-desc') {
                return getUpdatedMillis(b) - getUpdatedMillis(a);
            }
            if (strategy === 'date-asc') {
                return getUpdatedMillis(a) - getUpdatedMillis(b);
            }
            return a.title.localeCompare(b.title);
        });

        const colHeights = new Array(gridCols).fill(0);

        const isFiniteNumber = (value: unknown): value is number => typeof value === 'number' && Number.isFinite(value);
        const getSafeNumber = (value: unknown, fallback: number) => (isFiniteNumber(value) ? value : fallback);

        const layouts = sortedMemos.map(memo => {
            const rawW = getSafeNumber(memo.w, 4);
            const rawH = memo.isCollapsed ? 1 : getSafeNumber(memo.h, 4);

            const w = Math.min(Math.max(1, Math.floor(rawW)), gridCols);
            const h = Math.max(1, Math.floor(rawH));

            let bestX = 0;
            let bestY = Infinity;

            // Find the absolute lowest position that fits the width
            for (let x = 0; x <= gridCols - w; x++) {
                let maxYInSpan = 0;
                for (let k = x; k < x + w; k++) {
                    maxYInSpan = Math.max(maxYInSpan, colHeights[k]);
                }

                if (maxYInSpan < bestY) {
                    bestY = maxYInSpan;
                    bestX = x;
                }
            }

            // Update column heights
            for (let k = bestX; k < bestX + w; k++) {
                colHeights[k] = bestY + h;
            }

            return {
                i: memo.id,
                x: bestX,
                y: bestY,
                w,
                h
            };
        });

        const newVersion = get().layoutVersion + 1;
        set({ layoutVersion: newVersion });
        await get().updateMemoLayouts(layouts);
    },

    setCommentDraft: (memoId: string, itemId: string, text: string) => {
        const key = `${memoId}:${itemId}`;
        set((state) => ({
            commentDrafts: { ...state.commentDrafts, [key]: text }
        }));
    }
}));

import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../contexts/AuthContext';

export interface ColumnDefinition {
    key: string;
    label: string;
}

export const useColumnSettings = (
    storageKeyId: string,
    allColumns: ColumnDefinition[]
) => {
    const { currentUser } = useAuth();
    const [visibleColumns, setVisibleColumns] = useState<string[]>(allColumns.map(c => c.key));
    const [columnOrder, setColumnOrder] = useState<string[]>(allColumns.map(c => c.key));
    const [showColumnSettings, setShowColumnSettings] = useState(false);

    // Load settings on mount or user change
    useEffect(() => {
        if (currentUser) {
            const visibleKey = `column_settings_${storageKeyId}_${currentUser.uid}`;
            const orderKey = `column_order_${storageKeyId}_${currentUser.uid}`;

            const savedVisible = localStorage.getItem(visibleKey);
            const savedOrder = localStorage.getItem(orderKey);
            const allKeys = allColumns.map(c => c.key);

            let previousOrderKeys: string[] | null = null;
            if (savedOrder) {
                try {
                    const order = JSON.parse(savedOrder);
                    previousOrderKeys = [...new Set(order as string[])].filter((k) => allKeys.includes(k));
                } catch (e) {
                    console.error("Failed to parse column order", e);
                    previousOrderKeys = null;
                }
            }

            if (savedVisible) {
                try {
                    const visible = JSON.parse(savedVisible);
                    const validVisible = [...new Set(visible as string[])].filter((k) => allKeys.includes(k));

                    if (previousOrderKeys) {
                        const newKeys = allKeys.filter((k) => !previousOrderKeys!.includes(k));
                        newKeys.forEach((k) => {
                            if (!validVisible.includes(k)) validVisible.push(k);
                        });
                    }

                    setVisibleColumns(validVisible);
                } catch (e) {
                    console.error("Failed to parse column settings", e);
                    setVisibleColumns(allColumns.map(c => c.key));
                }
            } else {
                setVisibleColumns(allColumns.map(c => c.key));
            }

            if (savedOrder) {
                try {
                    const order = JSON.parse(savedOrder);

                    // Deduplicate and filter valid keys only
                    const validOrder = [...new Set(order as string[])].filter((k) => allKeys.includes(k));

                    // Append missing keys
                    allKeys.forEach(k => {
                        if (!validOrder.includes(k)) validOrder.push(k as string);
                    });

                    setColumnOrder(validOrder as string[]);
                } catch (e) {
                    console.error("Failed to parse column order", e);
                    setColumnOrder(allColumns.map(c => c.key));
                }
            } else {
                setColumnOrder(allColumns.map(c => c.key));
            }
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [currentUser?.uid, storageKeyId]);

    // Save visible columns on change
    useEffect(() => {
        if (currentUser) {
            const key = `column_settings_${storageKeyId}_${currentUser.uid}`;
            localStorage.setItem(key, JSON.stringify(visibleColumns));
        }
    }, [visibleColumns, currentUser?.uid, storageKeyId]);

    // Save column order on change
    useEffect(() => {
        if (currentUser) {
            const key = `column_order_${storageKeyId}_${currentUser.uid}`;
            localStorage.setItem(key, JSON.stringify(columnOrder));
        }
    }, [columnOrder, currentUser?.uid, storageKeyId]);

    const toggleColumn = (key: string) => {
        setVisibleColumns(prev =>
            prev.includes(key)
                ? prev.filter(k => k !== key)
                : [...prev, key]
        );
    };

    // 열 순서 변경 (from -> to 인덱스)
    const moveColumn = useCallback((fromIndex: number, toIndex: number) => {
        setColumnOrder(prev => {
            const newOrder = [...prev];
            const [removed] = newOrder.splice(fromIndex, 1);
            newOrder.splice(toIndex, 0, removed);
            return newOrder;
        });
    }, []);

    // 전체 순서 재설정
    const reorderColumns = useCallback((newOrder: string[]) => {
        setColumnOrder(newOrder);
    }, []);

    const resetColumns = () => {
        setVisibleColumns(allColumns.map(c => c.key));
        setColumnOrder(allColumns.map(c => c.key));
    };

    // 순서대로 정렬된 열 반환 (표시될 열만)
    const getOrderedColumns = useCallback(() => {
        return columnOrder.filter(key => visibleColumns.includes(key));
    }, [columnOrder, visibleColumns]);

    return {
        visibleColumns,
        setVisibleColumns,
        columnOrder,
        setColumnOrder,
        toggleColumn,
        moveColumn,
        reorderColumns,
        getOrderedColumns,
        showColumnSettings,
        setShowColumnSettings,
        resetColumns
    };
};

import { useState, useEffect } from 'react';

/**
 * Animates a number from 0 to the target value over a specified duration.
 * @param target The target number to animate to.
 * @param duration The duration of the animation in milliseconds. Default: 1000ms.
 */
export const useCountAnimation = (target: number, duration: number = 1000) => {
    const [count, setCount] = useState(0);

    useEffect(() => {
        let startTimestamp: number | null = null;
        let animationFrameId: number;

        const startValue = count; // Start from current count to handle changes smoothly
        const diff = target - startValue;

        if (diff === 0) return;

        const step = (timestamp: number) => {
            if (!startTimestamp) startTimestamp = timestamp;
            const progress = Math.min((timestamp - startTimestamp) / duration, 1);

            // Ease-out expo function for smoother landing
            // 1 - Math.pow(2, -10 * progress)

            const easedProgress = progress === 1 ? 1 : 1 - Math.pow(2, -10 * progress);

            setCount(startValue + (diff * easedProgress));

            if (progress < 1) {
                animationFrameId = window.requestAnimationFrame(step);
            }
        };

        animationFrameId = window.requestAnimationFrame(step);

        return () => window.cancelAnimationFrame(animationFrameId);
    }, [target, duration]);

    // Return integer for display
    return Math.round(count);
};

import { useState, useCallback } from 'react';

export interface MenuItem {
    text: string;
    icon?: string;
    sub?: (string | MenuItem)[];
}

export interface MenuState {
    isSidebarCollapsed: boolean;
    isMobileOpen: boolean;
    activeMenuItems: { [key: string]: boolean };
    submenuData: { title: string; items: (string | MenuItem)[] } | null;
    isRightPanelOpen: boolean;
    isBottomPanelOpen: boolean;
    isAdminPanelOpen: boolean;
}

export interface MenuActions {
    toggleSidebar: () => void;
    togglePanel: (type: 'right' | 'bottom' | 'admin') => void;
    toggleSubmenu: (itemId: string) => void;
    handleMenuItemClick: (item: MenuItem, isMobile: boolean) => void;
    handleSubMenuClick: (subItem: string, menuPaths: { [key: string]: string }, navigate: (path: string) => void) => void;
    closeAll: () => void;
    closePanels: () => void;
    closeSubmenuPanel: () => void;
    handleLogoClick: (navigate: (path: string) => void) => void;
}

export const useMenu = (initialState: Partial<MenuState> = {}): [MenuState, MenuActions] => {
    const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(initialState.isSidebarCollapsed ?? false);
    const [isMobileOpen, setIsMobileOpen] = useState(initialState.isMobileOpen ?? false);
    const [activeMenuItems, setActiveMenuItems] = useState<{ [key: string]: boolean }>(initialState.activeMenuItems ?? {});
    const [submenuData, setSubmenuData] = useState<{ title: string; items: (string | MenuItem)[] } | null>(initialState.submenuData ?? null);
    const [isRightPanelOpen, setIsRightPanelOpen] = useState(initialState.isRightPanelOpen ?? false);
    const [isBottomPanelOpen, setIsBottomPanelOpen] = useState(initialState.isBottomPanelOpen ?? false);
    const [isAdminPanelOpen, setIsAdminPanelOpen] = useState(initialState.isAdminPanelOpen ?? false);

    const toggleSidebar = useCallback(() => {
        closePanels();
        closeSubmenuPanel();
        setIsMobileOpen(prev => !prev);
        setIsSidebarCollapsed(prev => !prev);
    }, []);

    const togglePanel = useCallback((type: 'right' | 'bottom' | 'admin') => {
        if (type === 'right') {
            setIsRightPanelOpen(prev => !prev);
            setIsBottomPanelOpen(false);
            setIsAdminPanelOpen(false);
        } else if (type === 'bottom') {
            setIsBottomPanelOpen(prev => !prev);
            setIsRightPanelOpen(false);
            setIsAdminPanelOpen(false);
        } else if (type === 'admin') {
            setIsAdminPanelOpen(prev => !prev);
            setIsRightPanelOpen(false);
            setIsBottomPanelOpen(false);
        }
    }, []);

    const toggleSubmenu = useCallback((itemId: string) => {
        setActiveMenuItems(prev => {
            const newState = { ...prev };
            Object.keys(newState).forEach(key => {
                if (key !== itemId) newState[key] = false;
            });
            newState[itemId] = !newState[itemId];
            return newState;
        });
    }, []);

    const handleMenuItemClick = useCallback((item: MenuItem, isMobile: boolean) => {
        if (isSidebarCollapsed && !isMobile) {
            if (item.sub && item.sub.length > 0) {
                setSubmenuData({
                    title: item.text,
                    items: item.sub
                });
                closePanels();
            } else {
                setSubmenuData(null);
                closePanels();
            }
        } else {
            if (item.sub && item.sub.length > 0) {
                // This would need the menu data - we'll handle this differently
                const itemId = `menu-${item.text}`;
                toggleSubmenu(itemId);
            } else {
                setActiveMenuItems({});
            }
        }
    }, [isSidebarCollapsed, toggleSubmenu]);

    const handleSubMenuClick = useCallback((subItem: string, menuPaths: { [key: string]: string }, navigate: (path: string) => void) => {
        const path = menuPaths[subItem];
        if (path) {
            navigate(path);
            if (isMobileOpen) {
                closeAll();
            }
        }
    }, [isMobileOpen]);

    const closeSubmenuPanel = useCallback(() => {
        setSubmenuData(null);
        if (isMobileOpen) {
            setIsMobileOpen(false);
        }
    }, [isMobileOpen]);

    const closePanels = useCallback(() => {
        setIsRightPanelOpen(false);
        setIsBottomPanelOpen(false);
        setIsAdminPanelOpen(false);
    }, []);

    const closeAll = useCallback(() => {
        setIsMobileOpen(false);
        closePanels();
        closeSubmenuPanel();
        if (!isMobileOpen) {
            setIsSidebarCollapsed(true);
        }
    }, [isMobileOpen, closePanels, closeSubmenuPanel]);

    const handleLogoClick = useCallback((navigate: (path: string) => void) => {
        setActiveMenuItems({});
        navigate('/dashboard');
    }, []);

    const state: MenuState = {
        isSidebarCollapsed,
        isMobileOpen,
        activeMenuItems,
        submenuData,
        isRightPanelOpen,
        isBottomPanelOpen,
        isAdminPanelOpen,
    };

    const actions: MenuActions = {
        toggleSidebar,
        togglePanel,
        toggleSubmenu,
        handleMenuItemClick,
        handleSubMenuClick,
        closeAll,
        closePanels,
        closeSubmenuPanel,
        handleLogoClick,
    };

    return [state, actions];
};

