            </div>

            {/* === Position Tab === */}
            {activeTab === 'position' && (
                <div className="flex-1 grid grid-cols-12 gap-6 min-h-0">
                    <div className="col-span-3 bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden flex flex-col">
