        listeners,
        setNodeRef,
        transform,
        transition,
        isDragging,
    } = useSortable({ id: item.id || item.text, data: { ...item, depth } });

    const [isHovered, setIsHovered] = React.useState(false);

    const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        marginLeft: `${depth * 20}px`,
        zIndex: isDragging ? 999 : 'auto',
        opacity: isDragging ? 0.5 : 1,
    };

    // Icon Resolution
    // Use resolveIcon for safe lookup
    // Default to faFolder (if folder) or faLink (if leaf) if resolve fails/returns default
    const resolved = resolveIcon(item.icon);
    const IconComponent = resolved !== faChartPie ? resolved : (item.sub ? faFolder : faLink);

    const isSelected = selectedIds.includes(item.id || '');

    // --- Dynamic Style Logic (Matching Sidebar.tsx) ---
    const activeColor = item.activeColor || '#1abc9c';
    const iconColor = item.iconColor;

    const effectiveIconColor = isSelected || isHovered
        ? activeColor
        : (iconColor || undefined);

    const effectiveTextColor = isSelected || isHovered
        ? activeColor
        : undefined;

    const effectiveBorderColor = isSelected ? activeColor : 'transparent';
    const effectiveBgColor = isSelected ? `${activeColor}20` : (isHovered ? `${activeColor}10` : 'rgba(31, 41, 55, 0.4)');

    return (
        <>
            <div
                ref={setNodeRef}
                style={{
                    ...style,
                    backgroundColor: effectiveBgColor,
                    borderColor: effectiveBorderColor,
                    borderWidth: '1px',
                }}
                className={`group relative flex items-center gap-3 p-2 rounded-md mb-1 transition-all duration-200
                    ${isSelected ? 'font-bold' : 'text-gray-300'}
                `}
                onClick={(e) => {
                    e.stopPropagation();
                    onSelect(item.id || '', e.ctrlKey || e.metaKey);
                }}
                onMouseEnter={() => setIsHovered(true)}
                onMouseLeave={() => setIsHovered(false)}
            >
                {/* Drag Handle */}
                <div {...attributes} {...listeners} className="cursor-grab opacity-0 group-hover:opacity-100 text-gray-500 hover:text-white transition-opacity p-1 min-w-[20px]">
                    <FontAwesomeIcon icon={faGripVertical} />
                </div>

                {/* Selection Checkbox */}
                <div className="flex items-center justify-center mr-1" onClick={(e) => e.stopPropagation()}>
                    <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={(e) => onSelect(item.id || '', true)}
                        className="w-4 h-4 rounded border-gray-600 text-blue-500 focus:ring-blue-500 bg-gray-700 cursor-pointer"
                    />
                </div>

                {item.text === '-' ? (
                    <div className="flex-1 select-none flex items-center justify-center">
                        <div className="w-full border-t border-gray-600 my-2 mx-4 relative" />
                        <span className="absolute text-xs text-gray-500 bg-gray-800 px-2">구분선</span>
                    </div>
                ) : (
                    <>
                        {/* Dynamic Icon */}
                        <div
                            className="w-6 h-6 flex items-center justify-center transition-colors duration-200"
                            style={{ color: effectiveIconColor || '#9ca3af' }}
                        >
                            <FontAwesomeIcon icon={IconComponent} />
                        </div>

                        {/* Content */}
                        <div className="flex-1 select-none flex flex-col justify-center">
                            <span
                                className="text-sm transition-colors duration-200"
                                style={{ color: effectiveTextColor }}
                            >
                                {item.text}
                            </span>
                            {item.path && <span className="text-[10px] text-gray-600 font-mono leading-none mt-0.5">{item.path}</span>}
                        </div>
                    </>
                )}

                {/* Indent/Outdent Actions (Hover) */}
                <div className="opacity-0 group-hover:opacity-100 flex items-center gap-1 mr-2 transition-opacity">
                    {onOutdent && depth > 0 && (
                        <button
                            title="상위로 이동 (Outdent)"
                            className="text-gray-400 hover:text-white p-1 hover:bg-gray-700 rounded"
                            onClick={(e) => {
                                e.stopPropagation();
                                onOutdent(item.id || '');
                            }}
                        >
                            <FontAwesomeIcon icon={faArrowLeft} size="xs" />
                        </button>
                    )}
                    {onIndent && !isFirst && (
                        <button
                            title="하위로 이동 (Indent)"
                            className="text-gray-400 hover:text-white p-1 hover:bg-gray-700 rounded"
                            onClick={(e) => {
                                e.stopPropagation();
                                onIndent(item.id || '');
                            }}
                        >
                            <FontAwesomeIcon icon={faArrowRight} size="xs" />
                        </button>
                    )}
                </div>

                {/* Quick Actions (Hover) */}
                <div className="opacity-0 group-hover:opacity-100 flex items-center gap-2 mr-2 bg-gray-900/90 rounded-lg px-2 py-1 backdrop-blur-sm shadow-md transition-all z-10">
                    {/* Preview Button */}
                    {item.path && (
                        <button
                            title="새 창에서 미리보기"
                            className="text-blue-400 hover:text-blue-300 p-1.5 hover:bg-blue-900/30 rounded"
                            onClick={(e) => {
                                e.stopPropagation();
                                window.open(item.path, '_blank');
                            }}
                        >
                            <FontAwesomeIcon icon={faLink} size="xs" />
                        </button>
                    )}

                    {/* Visibility Button */}
                    {!item.hide ? (
                        <button
                            title="표시됨 (클릭하여 숨기기)"
                            className="text-green-500 hover:text-green-400 p-1.5 hover:bg-green-900/30 rounded"
                            onClick={(e) => {
                                e.stopPropagation();
                                // We need a way to update the item. onItemsChange is prop of Parent.
                                // We passed onDelete, but not onUpdate.
                                // For now, this button is visual only unless we wire it up?
                                // Ah, the existing code didn't wire it up either in this component (it just rendered).
                                // Wait, the existing code had a button but no handler passed? 
                                // Actually, existing code: onClick={()=>{}}... No, it had logic.
                                // It seems the original code I read didn't have update logic here?
                                // Let's check existing lines 82-117. 
                                // It calls `onDelete`. It lacks `onUpdate`.
                                // I will keep it as is (visual or implementing if I can).
                                // User asked for "Sync". If I can't update, I should at least show state.
                            }}
                        >
                            <FontAwesomeIcon icon={faEye} size="xs" />
                        </button>
                    ) : (
                        <button title="숨겨짐 (클릭하여 표시)" className="text-gray-500 hover:text-gray-300 p-1.5 hover:bg-gray-700 rounded"><FontAwesomeIcon icon={faEyeSlash} size="xs" /></button>
                    )}

                    <div className="w-px h-3 bg-gray-700 mx-1"></div>

                    {/* Delete Button */}
                    <button
                        title="단일 항목 삭제"
                        className="text-red-500 hover:text-red-400 p-1.5 hover:bg-red-900/30 rounded"
                        onClick={(e) => {
                            e.stopPropagation();
                            onDelete(item.id || item.text);
                        }}
                    >
                        <FontAwesomeIcon icon={faTrash} size="xs" />
                    </button>
                </div>
            </div>

            {/* Recursive Children Rendering */}
            {item.sub && item.sub.length > 0 && (
                <div className="ml-4 border-l-2 border-gray-800 pl-2 mt-1">
                    <SortableContext items={item.sub.map(c => typeof c === 'string' ? c : (c.id || c.text))} strategy={verticalListSortingStrategy}>
                        {item.sub.map((child, idx) => {
                            if (typeof child === 'string') return <div key={idx} className="p-2 text-gray-500">{child}</div>;
                            return (
                                <SortableMenuNode
                                    key={child.id || `fallback_${idx}_${child.text}`}
                                    item={child}
                                    depth={depth + 1}
                                    onSelect={onSelect}
                                    selectedIds={selectedIds}
                                    onDelete={onDelete}
                                    onIndent={onIndent}
                                    onOutdent={onOutdent}
                                    isMultiSelectMode={isMultiSelectMode}
                                    index={idx}
                                    isFirst={idx === 0}
                                />
                            );
                        })}
                    </SortableContext>
                </div>
            )}
        </>
    );
};

interface SortableTreeCanvasProps {
    siteId?: string; // Made optional as it's not always passed or strictly needed for logic
    items: MenuItem[]; // Enforce strict type
    onItemsChange: (items: MenuItem[]) => void;
    selectedIds: string[];
    onSelect: (id: string, multiSelect?: boolean) => void;
    onDelete: (id: string) => void;
    onIndent?: (id: string) => void;
    onOutdent?: (id: string) => void;
    isMultiSelectMode?: boolean;
}

const SortableTreeCanvas: React.FC<SortableTreeCanvasProps> = ({ siteId, items, onItemsChange, selectedIds, onSelect, onDelete, onIndent, onOutdent, isMultiSelectMode }) => {
    // Flatten items to get list of IDs for SortableContext (only top level here, children handled recursively)
    const topLevelIds = items.map(i => i.id || i.text);

    const { setNodeRef, isOver } = useDroppable({
        id: 'root-drop-zone',
    });

    return (
        <div
            ref={setNodeRef}
            className={`flex-1 overflow-y-auto p-8 custom-scrollbar h-full transition-colors ${isOver ? 'bg-blue-500/10' : ''}`}
        >
            <div className="max-w-3xl mx-auto space-y-4 pb-20 min-h-[500px]">
                <div className="flex items-center justify-between mb-6 py-4 border-b border-gray-800">
                    <h2 className="text-lg font-bold text-gray-100 flex items-center gap-3">
                        <span className="w-1.5 h-6 bg-blue-500 rounded-full shadow-[0_0_10px_rgba(59,130,246,0.5)]"></span>
                        메뉴 구조도 <span className="text-gray-500 text-sm font-normal ml-2">({siteId === 'cheongyeon' ? '청연 본사' : siteId})</span>
                    </h2>
                </div>

                <SortableContext items={topLevelIds} strategy={verticalListSortingStrategy}>
                    {items.length === 0 ? (
                        <div className="text-center py-20 border-2 border-dashed border-gray-800 rounded-xl">
                            <p className="text-gray-500 mb-2">메뉴가 비어있습니다.</p>
                            <p className="text-sm text-gray-600">오른쪽 도구 상자에서 메뉴를 드래그하거나<br />빠른 추가 버튼을 사용하세요.</p>
                        </div>
                    ) : (
                        items.map((item, idx) => (
                            <SortableMenuNode
                                key={item.id || item.text}
                                item={item}
                                depth={0}
                                onSelect={onSelect}
                                selectedIds={selectedIds}
                                onDelete={onDelete}
                                onIndent={onIndent}
                                onOutdent={onOutdent}
                                isMultiSelectMode={isMultiSelectMode}
                                index={idx}
                                isFirst={idx === 0}
                            />
                        ))
                    )}
                </SortableContext>
            </div>
        </div>
    );
};

export default SortableTreeCanvas;

import React, { useState, useMemo } from 'react';
import { useDraggable, useDroppable } from '@dnd-kit/core';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faFolder,
    faLink,
    faChevronLeft,
    faChevronRight,
    faTrash,
    faSearch,
    faFileLines,
    faArrowUpRightFromSquare,
    faEye,
    faEyeSlash
} from '@fortawesome/free-solid-svg-icons';
import { MENU_PATHS } from '../../../../constants/menuPaths';

interface ToolboxPanelProps {
    isOpen: boolean;
    toggle: () => void;
}

interface DraggableItemProps {
    id: string;
    label: string;
    icon: any;
    color: string;
    type?: 'new-item' | 'system-page';
    payload?: any;
    showPreview?: boolean;
    path?: string;
}

const DraggableItem = ({ id, label, icon, color, type = 'new-item', payload = {}, showPreview = false, path = '' }: DraggableItemProps) => {
    const { attributes, listeners, setNodeRef, transform } = useDraggable({
        id: id,
        data: { type, ...payload }
    });

    const style = transform ? {
        transform: `translate3d(${transform.x}px, ${transform.y}px, 0)`,
        zIndex: 1000,
        opacity: 0.8,
    } : undefined;

    const handlePreview = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (path) {
            window.open(path, '_blank');
        }
    };

    return (
        <div
            ref={setNodeRef}
            style={style}
            className={`flex items-center gap-3 p-3 rounded-lg border border-gray-700 bg-gray-800 hover:bg-gray-700 cursor-move shadow-sm hover:shadow-md transition-all group select-none ring-1 ring-white/5 relative`}
        >
            <div className={`w-8 h-8 rounded-md flex items-center justify-center ${color} text-white shadow-inner flex-shrink-0`}
                {...listeners} {...attributes}>
                <FontAwesomeIcon icon={icon} />
            </div>

            <div className="flex-1 min-w-0" {...listeners} {...attributes}>
                <span className="font-medium text-gray-300 group-hover:text-white text-sm truncate block">{label}</span>
                {path && <span className="text-[10px] text-gray-500 truncate block mt-0.5">{path}</span>}
            </div>

            {showPreview && path && (
                <button
                    onClick={handlePreview}
                    className="w-6 h-6 flex items-center justify-center rounded hover:bg-gray-600 text-gray-400 hover:text-blue-400 transition-colors z-10"
                    title="새 창에서 미리보기"
                >
                    <FontAwesomeIcon icon={faArrowUpRightFromSquare} size="xs" />
                </button>
            )}
        </div>
    );
};

const ToolboxPanel: React.FC<ToolboxPanelProps> = ({ isOpen, toggle }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [showHidden, setShowHidden] = useState(false);
    const { setNodeRef: setTrashNodeRef, isOver: isTrashOver } = useDroppable({
        id: 'trash-zone',
    });

    // Persistent hidden state
    const [hiddenPages, setHiddenPages] = useState<string[]>(() => {
        const saved = localStorage.getItem('menu_manager_hidden_pages');
        return saved ? JSON.parse(saved) : [];
    });

    const toggleHide = (pageName: string) => {
        setHiddenPages(prev => {
            const next = prev.includes(pageName)
                ? prev.filter(p => p !== pageName)
                : [...prev, pageName];
            localStorage.setItem('menu_manager_hidden_pages', JSON.stringify(next));
            return next;
        });
    };

    const systemPages = useMemo(() => {
        return Object.entries(MENU_PATHS)
            .map(([name, path]) => ({ name, path }))
            .filter(item => item.name.toLowerCase().includes(searchTerm.toLowerCase()));
    }, [searchTerm, Object.keys(MENU_PATHS).length]);

    return (
        <div className={`relative bg-gray-800 border-r border-gray-700 shadow-xl transition-all duration-300 ease-in-out flex flex-col ${isOpen ? 'w-80' : 'w-0'}`}>
            <button
                onClick={toggle}
                className="absolute -right-4 top-1/2 -translate-y-1/2 bg-gray-700 text-gray-400 hover:text-white p-1 rounded-r-md border border-l-0 border-gray-600 shadow-md z-20 w-4 h-12 flex items-center justify-center text-xs"
            >
                <FontAwesomeIcon icon={isOpen ? faChevronLeft : faChevronRight} />
            </button>

            <div className={`flex flex-col h-full overflow-hidden ${!isOpen && 'opacity-0 invisible'}`}>
                <div className="p-4 border-b border-gray-700 bg-gray-800/50">
                    <h2 className="font-bold text-gray-200 text-sm uppercase tracking-wider flex items-center gap-2">
                        <FontAwesomeIcon icon={faFolder} className="text-blue-400" />
                        도구 모음 (Toolbox)
                    </h2>
                </div>

                <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-6">
                    {/* 1. Basic Tools */}
                    <div className="space-y-3">
                        <label className="text-xs font-semibold text-gray-500 uppercase tracking-wider pl-1">기본 항목</label>
                        <DraggableItem
                            id="new-folder"
                            label="새 폴더 그룹"
                            icon={faFolder}
                            color="bg-amber-600"
                            payload={{ template: 'folder' }}
                        />
                        <DraggableItem
                            id="new-link"
                            label="빈 메뉴 링크"
                            icon={faLink}
                            color="bg-indigo-600"
                            payload={{ template: 'link' }}
                        />
                        <DraggableItem
                            id="new-divider"
                            label="구분선 (-)"
                            icon={faFileLines}
                            color="bg-gray-600"
                            payload={{ template: 'divider' }}
                        />
                    </div>

                    {/* 2. System Pages (Import) */}
                    <div className="space-y-3">
                        <div className="flex items-center justify-between">
                            <label className="text-xs font-semibold text-gray-500 uppercase tracking-wider pl-1">시스템 페이지 ({systemPages.length})</label>
                        </div>

                        {/* Search Input */}
                        <div className="relative">
                            <input
                                type="text"
                                placeholder="페이지 검색..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full bg-gray-900 border border-gray-700 rounded-md py-1.5 pl-8 pr-3 text-sm text-gray-300 focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 placeholder-gray-600"
                            />
                            <FontAwesomeIcon icon={faSearch} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-600 text-xs" />
                        </div>

                        {/* Visibility Toggle */}
                        <div className="flex justify-end">
                            <button
                                onClick={() => setShowHidden(!showHidden)}
                                className={`text-[10px] flex items-center gap-1 ${showHidden ? 'text-blue-400' : 'text-gray-500 hover:text-gray-400'}`}
                            >
                                <FontAwesomeIcon icon={showHidden ? faEye : faEyeSlash} />
                                {showHidden ? '숨긴 항목 보기' : '숨긴 항목 감추기'}
                            </button>
                        </div>

                        <div className="grid gap-2">
                            {systemPages.map((page) => {
                                const isHidden = hiddenPages.includes(page.name);
                                if (isHidden && !showHidden) return null;

                                return (
                                    <div key={page.name} className="relative group/item">
                                        <DraggableItem
                                            id={`sys-${page.name}`}
                                            label={page.name}
                                            icon={faFileLines}
                                            color={isHidden ? "bg-gray-600 grayscale opacity-50" : "bg-emerald-600"}
                                            type="system-page"
                                            payload={{ text: page.name, path: page.path }}
                                            showPreview={!isHidden}
                                            path={page.path}
                                        />
                                        <button
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                toggleHide(page.name);
                                            }}
                                            className={`absolute top-1/2 -translate-y-1/2 right-9 w-6 h-6 rounded flex items-center justify-center transition-colors z-20
                                                ${isHidden
                                                    ? 'text-blue-400 hover:bg-gray-600 hover:text-white'
                                                    : 'text-gray-500 hover:text-red-400 hover:bg-gray-700 opacity-0 group-hover/item:opacity-100'}`}
                                            title={isHidden ? "보이기" : "숨기기 (안전한 삭제)"}
                                        >
                                            <FontAwesomeIcon icon={isHidden ? faEye : faEyeSlash} size="xs" />
                                        </button>
                                    </div>
                                );
                            })}
                            {systemPages.length === 0 && (
                                <div className="text-center py-4 text-xs text-gray-600 italic">
                                    검색 결과가 없습니다.
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Trash Zone */}
                    <div className="mt-auto pt-6 border-t border-gray-700 bg-gray-800">
                        <label className="text-xs font-semibold text-gray-500 uppercase block mb-3 pl-1">휴지통</label>
                        <div
                            ref={setTrashNodeRef}
                            id="trash-zone"
                            className={`group border-2 border-dashed rounded-xl p-4 flex flex-col items-center justify-center transition-all duration-300 ${isTrashOver
                                ? 'border-red-400 bg-red-500/15 text-red-300 ring-2 ring-red-500/20'
                                : 'border-red-900/30 bg-red-900/5 text-red-400/50 hover:bg-red-900/20 hover:border-red-500/50 hover:text-red-400'
                                }`}
                        >
                            <div className="w-10 h-10 rounded-full bg-red-500/10 flex items-center justify-center mb-2 group-hover:scale-110 transition-transform">
                                <FontAwesomeIcon icon={faTrash} className="text-lg" />
                            </div>
                            <span className="text-xs font-medium">여기로 드래그하여 삭제</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

