        borderColor = 'border-purple-200';
        textColor = 'text-purple-700';
        salaryBadge = '월';
        salaryBadgeColor = 'bg-purple-500 text-white';
    } else if (salaryModel === '지원팀') {
        bgColor = 'bg-green-50';
        borderColor = 'border-green-200';
        textColor = 'text-green-700';
        salaryBadge = '지';
        salaryBadgeColor = 'bg-green-500 text-white';
    } else if (salaryModel === '용역팀') {
        bgColor = 'bg-orange-50';
        borderColor = 'border-orange-200';
        textColor = 'text-orange-700';
        salaryBadge = '용';
        salaryBadgeColor = 'bg-orange-500 text-white';
    } else { // 일급제 (default)
        bgColor = 'bg-blue-50';
        borderColor = 'border-blue-200';
        textColor = 'text-blue-700';
        salaryBadge = '일';
        salaryBadgeColor = 'bg-blue-500 text-white';
    }

    return (
        <div
            className={`px-2 py-1 rounded shadow-sm border ${bgColor} ${borderColor} ${textColor} text-xs font-bold flex items-center gap-2 cursor-grab hover:shadow-md transition-all select-none whitespace-nowrap`}
            title={`이름: ${worker.name}\n구분: ${salaryModel}`}
        >
            <span className={`w-4 h-4 rounded-full flex items-center justify-center text-[10px] font-bold ${salaryBadgeColor}`}>
                {salaryBadge}
            </span>
            <span className="flex items-center gap-1">
                {worker.name}
            </span>
            {onDelete && (
                <button onClick={(e) => { e.stopPropagation(); onDelete(); }} className="text-slate-400 hover:text-red-500 ml-1">
                    <FontAwesomeIcon icon={faTimes} />
                </button>
            )}
        </div>
    );
};

// 2. Sortable Item Wrapper
const SortableItem = ({ id, data, type, origin, siteId, onDelete }: DraggableItemData & { onDelete?: () => void }) => {
    const {
        attributes,
        listeners,
        setNodeRef,
        transform,
        transition,
        isDragging,
    } = useSortable({
        id: id,
        data: { type, data, origin, siteId }
    });

    const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: isDragging ? 0.3 : 1,
    };

    return (
        <div ref={setNodeRef} style={style} {...attributes} {...listeners} className="inline-block mr-1 mb-1">
            {type === 'worker' ? (
                <WorkerChip worker={data} onDelete={onDelete} />
            ) : (
                <div className="px-2 py-1 bg-slate-100 rounded border border-slate-300 text-xs font-bold flex items-center gap-1 cursor-grab">
                    <FontAwesomeIcon icon={faTruck} className="text-slate-500" />
                    {data.licensePlate}
                </div>
            )}
        </div>
    );
};

// 3. Site Row (List View Item)
const SiteRow = ({ site, workers, vehicles, onRemoveWorker }: { site: Site, workers: Worker[], vehicles: Vehicle[], onRemoveWorker: (workerId: string) => void }) => {
    const { setNodeRef } = useDroppable({
        id: site.id!,
        data: { type: 'site', site }
    });

    // Find Team Leader
    const teamLeader = workers.find(w => w.role === '팀장');

    return (
        <tr className="border-b border-slate-200 hover:bg-slate-50 transition-colors">
            {/* Site Info */}
            <td className="p-3 align-top w-64">
                <div className="font-bold text-slate-800">{site.name}</div>
                <div className="text-xs text-slate-500 mt-1">{site.address || '-'}</div>
            </td>

            {/* Team Leader */}
            <td className="p-3 align-top w-32">
                {teamLeader ? (
                    <div className="text-sm font-bold text-slate-700 flex items-center gap-2">
                        <span className="w-6 h-6 rounded-full bg-red-100 text-red-600 flex items-center justify-center text-xs">
                            팀
                        </span>
                        {teamLeader.name}
                    </div>
                ) : (
                    <span className="text-xs text-slate-400">-</span>
                )}
            </td>

            {/* Assigned Workers (Droppable Area) */}
            <td ref={setNodeRef} className="p-3 align-top">
                <div className="min-h-[40px] p-2 rounded bg-slate-100/50 border border-slate-200 border-dashed flex flex-wrap gap-1">
                    <SortableContext items={[...workers.map(w => w.id!), ...vehicles.map(v => v.id)]} strategy={horizontalListSortingStrategy}>
                        {workers.map(w => (
                            <SortableItem
                                key={w.id!}
                                id={w.id!}
                                type="worker"
                                data={w}
                                origin="site"
                                siteId={site.id}
                                onDelete={() => onRemoveWorker(w.id!)}
                            />
                        ))}
                        {vehicles.map(v => (
                            <SortableItem
                                key={v.id!}
                                id={v.id!}
                                type="vehicle"
                                data={v}
                                origin="site"
                                siteId={site.id}
                                onDelete={() => onRemoveWorker(v.id!)} // Reuse remove handler for now or add specific one
                            />
                        ))}
                    </SortableContext>
                    {workers.length === 0 && vehicles.length === 0 && (
                        <span className="text-xs text-slate-400 italic self-center ml-2">인원/차량 배정 (드래그)</span>
                    )}
                </div>
            </td>

            {/* Count */}
            <td className="p-3 align-top w-20 text-center font-bold text-slate-600">
                {workers.length}명 / {vehicles.length}대
            </td>
        </tr>
    );
};

// --- Main Page ---
const DailyDispatchPage: React.FC = () => {
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [sites, setSites] = useState<Site[]>([]);
    const [allWorkers, setAllWorkers] = useState<Worker[]>([]);
    const [assignments, setAssignments] = useState<Record<string, { workers: Worker[], vehicles: Vehicle[] }>>({});
    const [unassignedWorkers, setUnassignedWorkers] = useState<Worker[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [activeId, setActiveId] = useState<string | null>(null);
    const [activeItem, setActiveItem] = useState<any>(null);

    // Vehicle Support
    const [activeTab, setActiveTab] = useState<'worker' | 'vehicle'>('worker');
    const [vehicles, setVehicles] = useState<Vehicle[]>([]);
    const [unassignedVehicles, setUnassignedVehicles] = useState<Vehicle[]>([]);

    const sensors = useSensors(
        useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
        useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
    );

    useEffect(() => {
        loadData();
    }, [date]);

    const loadData = async () => {
        try {
            const [sitesData, workersData, vehiclesData] = await Promise.all([
                siteService.getSites(),
                manpowerService.getWorkers(),
                vehicleService.getVehicles() // Static import call
            ]);
            setSites(sitesData);
            setAllWorkers(workersData);
            setVehicles(vehiclesData);

            const dispatchData = await dispatchService.getDispatchByDate(date);

            const newAssignments: Record<string, { workers: Worker[], vehicles: Vehicle[] }> = {};
            const assignedWorkerIds = new Set<string>();
            const assignedVehicleIds = new Set<string>();

            if (dispatchData) {
                dispatchData.assignments.forEach(a => {
                    const siteWorkers = workersData.filter(w => a.workerIds.includes(w.id!));
                    const siteVehicles = vehiclesData.filter((v: Vehicle) => a.vehicleIds?.includes(v.id));

                    siteWorkers.forEach(w => assignedWorkerIds.add(w.id!));
                    siteVehicles.forEach((v: Vehicle) => assignedVehicleIds.add(v.id));

                    newAssignments[a.siteId] = {
                        workers: siteWorkers,
                        vehicles: siteVehicles
                    };
                });
            }

            sitesData.forEach(site => {
                if (!newAssignments[site.id!]) {
                    newAssignments[site.id!] = { workers: [], vehicles: [] };
                }
            });

            setAssignments(newAssignments);
            setUnassignedWorkers(workersData.filter(w => !assignedWorkerIds.has(w.id!)));
            setUnassignedVehicles(vehiclesData.filter((v: Vehicle) => !assignedVehicleIds.has(v.id)));
        } catch (e) {
            console.error('Failed to load dispatch data', e);
        }
    };

    const handleSave = async () => {
        const dispatchAssignments: DispatchAssignment[] = Object.entries(assignments).map(([siteId, data]) => ({
            siteId,
            siteName: sites.find(s => s.id === siteId)?.name || '',
            workerIds: data.workers.map(w => w.id!),
            vehicleIds: data.vehicles.map(v => v.id)
        })).filter(a => a.workerIds.length > 0 || a.vehicleIds.length > 0);

        await dispatchService.saveDispatch(date, dispatchAssignments);
        alert('저장되었습니다.');
    };

    const handleCopyPreviousDay = async () => {
        if (!window.confirm('전일(어제) 배정 내역을 불러오시겠습니까? 현재 작성 중인 내용은 덮어씌워집니다.')) return;

        const yesterday = new Date(date);
        yesterday.setDate(yesterday.getDate() - 1);
        const yesterdayStr = yesterday.toISOString().split('T')[0];

        const prevData = await dispatchService.getDispatchByDate(yesterdayStr);
        if (!prevData) {
            alert('전일 배정 내역이 없습니다.');
            return;
        }

        // Apply previous data
        const newAssignments: Record<string, { workers: Worker[], vehicles: Vehicle[] }> = {};
        const assignedWorkerIds = new Set<string>();
        const assignedVehicleIds = new Set<string>();

        prevData.assignments.forEach(a => {
            const siteWorkers = allWorkers.filter(w => a.workerIds.includes(w.id!));
            const siteVehicles = vehicles.filter((v) => a.vehicleIds?.includes(v.id));

            siteWorkers.forEach(w => assignedWorkerIds.add(w.id!));
            siteVehicles.forEach(v => assignedVehicleIds.add(v.id));

            newAssignments[a.siteId] = {
                workers: siteWorkers,
                vehicles: siteVehicles
            };
        });

        // Fill remaining sites
        sites.forEach(site => {
            if (!newAssignments[site.id!]) {
                newAssignments[site.id!] = { workers: [], vehicles: [] };
            }
        });

        setAssignments(newAssignments);
        setUnassignedWorkers(allWorkers.filter(w => !assignedWorkerIds.has(w.id!)));
        setUnassignedVehicles(vehicles.filter(v => !assignedVehicleIds.has(v.id)));
    };

    // --- Drag Handlers ---
    const handleDragStart = (event: DragStartEvent) => {
        const { active } = event;
        setActiveId(active.id as string);
        setActiveItem(active.data.current?.data);
    };

    const handleDragEnd = (event: DragEndEvent) => {
        const { active, over } = event;
        setActiveId(null);
        setActiveItem(null);

        if (!over) return;

        const activeData = active.data.current as DraggableItemData;
        const overId = over.id as string;

        let targetContainerId = overId;
        if (over.data.current?.type === 'site') {
            targetContainerId = overId;
        } else if (over.data.current?.siteId) {
            targetContainerId = over.data.current.siteId;
        } else if (overId === 'sidebar-droppable' || over.data.current?.origin === 'sidebar') {
            targetContainerId = 'sidebar';
        }

        const sourceContainerId = activeData.origin === 'sidebar' ? 'sidebar' : activeData.siteId!;

        if (sourceContainerId === targetContainerId) return;

        if (activeData.type === 'worker') {
            const worker = activeData.data as Worker;

            // Remove from Source
            if (sourceContainerId === 'sidebar') {
                setUnassignedWorkers(prev => prev.filter(w => w.id !== worker.id));
            } else {
                setAssignments(prev => ({
                    ...prev,
                    [sourceContainerId]: {
                        ...prev[sourceContainerId],
                        workers: prev[sourceContainerId].workers.filter(w => w.id !== worker.id)
                    }
                }));
            }

            // Add to Target
            if (targetContainerId === 'sidebar') {
                setUnassignedWorkers(prev => [worker, ...prev]);
            } else {
                setAssignments(prev => ({
                    ...prev,
                    [targetContainerId]: {
                        ...prev[targetContainerId],
                        workers: [...prev[targetContainerId].workers, worker]
                    }
                }));
            }
        } else if (activeData.type === 'vehicle') {
            const vehicle = activeData.data;

            // Remove from Source
            if (sourceContainerId === 'sidebar') {
                setUnassignedVehicles(prev => prev.filter(v => v.id !== vehicle.id));
            } else {
                setAssignments(prev => ({
                    ...prev,
                    [sourceContainerId]: {
                        ...prev[sourceContainerId],
                        vehicles: prev[sourceContainerId].vehicles.filter(v => v.id !== vehicle.id)
                    }
                }));
            }

            // Add to Target
            if (targetContainerId === 'sidebar') {
                setUnassignedVehicles(prev => [vehicle, ...prev]);
            } else {
                setAssignments(prev => ({
                    ...prev,
                    [targetContainerId]: {
                        ...prev[targetContainerId],
                        vehicles: [...prev[targetContainerId].vehicles, vehicle]
                    }
                }));
            }
        }
    };

    const handleRemoveWorker = (siteId: string, itemId: string) => {
        // Try to find in workers first
        const worker = allWorkers.find(w => w.id === itemId);
        if (worker) {
            setAssignments(prev => ({
                ...prev,
                [siteId]: {
                    ...prev[siteId],
                    workers: prev[siteId].workers.filter(w => w.id !== itemId)
                }
            }));
            setUnassignedWorkers(prev => [worker, ...prev]);
            return;
        }

        // Try vehicles
        const vehicle = vehicles.find(v => v.id === itemId);
        if (vehicle) {
            setAssignments(prev => ({
                ...prev,
                [siteId]: {
                    ...prev[siteId],
                    vehicles: prev[siteId].vehicles.filter(v => v.id !== itemId)
                }
            }));
            setUnassignedVehicles(prev => [vehicle, ...prev]);
        }
    };

    const filteredUnassigned = unassignedWorkers.filter(w =>
        w.name.includes(searchTerm) || w.teamName?.includes(searchTerm)
    );
    const filteredVehicles = unassignedVehicles.filter(v => v.licensePlate.includes(searchTerm));

    return (
        <div className="flex h-full max-w-[1920px] mx-auto overflow-hidden bg-white">
            <DndContext
                sensors={sensors}
                collisionDetection={closestCorners}
                onDragStart={handleDragStart}
                onDragEnd={handleDragEnd}
            >
                {/* Left Sidebar: Resources */}
                <div className="w-72 border-r border-slate-200 flex flex-col h-full shrink-0 z-10 bg-slate-50">
                    <div className="p-4 border-b border-slate-200 bg-white">
                        {/* Tab Switcher */}
                        <div className="flex bg-slate-100 p-1 rounded-lg mb-4">
                            <button
                                onClick={() => setActiveTab('worker')}
                                className={`flex-1 py-1.5 text-sm font-bold rounded-md transition-all flex items-center justify-center gap-2 ${activeTab === 'worker'
                                    ? 'bg-white text-blue-600 shadow-sm'
                                    : 'text-slate-500 hover:text-slate-700'
                                    }`}
                            >
                                <FontAwesomeIcon icon={faUser} />
                                인원
                            </button>
                            <button
                                onClick={() => setActiveTab('vehicle')}
                                className={`flex-1 py-1.5 text-sm font-bold rounded-md transition-all flex items-center justify-center gap-2 ${activeTab === 'vehicle'
                                    ? 'bg-white text-blue-600 shadow-sm'
                                    : 'text-slate-500 hover:text-slate-700'
                                    }`}
                            >
                                <FontAwesomeIcon icon={faTruck} />
                                차량
                            </button>
                        </div>

                        {/* Status Header */}
                        <div className="mb-4">
                            <h2 className="font-bold text-lg text-slate-800">
                                {activeTab === 'worker' ? `대기 인원 (${filteredUnassigned.length})` : `대기 차량 (${filteredVehicles.length})`}
                            </h2>
                        </div>

                        <div className="flex items-center gap-2 bg-slate-100 p-2 rounded border border-slate-200 mb-3">
                            <FontAwesomeIcon icon={faCalendarAlt} className="text-slate-400" />
                            <input
                                type="date"
                                value={date}
                                onChange={(e) => setDate(e.target.value)}
                                className="w-full text-sm font-bold text-slate-700 bg-transparent focus:outline-none"
                            />
                        </div>

                        <div className="relative">
                            <FontAwesomeIcon icon={faSearch} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                            <input
                                type="text"
                                placeholder="검색..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none"
                            />
                        </div>
                    </div>

                    <div className="flex-1 overflow-y-auto p-3">
                        <SortableContext items={activeTab === 'worker' ? filteredUnassigned.map(w => w.id!) : filteredVehicles.map(v => v.id!)} strategy={verticalListSortingStrategy}>
                            <div id="sidebar-droppable" className="min-h-[200px] flex flex-col gap-1">
                                {activeTab === 'worker' ? (
                                    filteredUnassigned.map(worker => (
                                        <div key={worker.id} className="w-full">
                                            <SortableItem
                                                id={worker.id!}
                                                type="worker"
                                                data={worker}
                                                origin="sidebar"
                                            />
                                        </div>
                                    ))
                                ) : (
                                    filteredVehicles.map(vehicle => (
                                        <div key={vehicle.id} className="w-full">
                                            <SortableItem
                                                id={vehicle.id!}
                                                type="vehicle"
                                                data={vehicle}
                                                origin="sidebar"
                                            />
                                        </div>
                                    ))
                                )}
                            </div>
                        </SortableContext>
                    </div>

                    <div className="p-4 border-t border-slate-200 bg-white space-y-2">
                        <button
                            onClick={handleCopyPreviousDay}
                            className="w-full py-2 bg-slate-100 text-slate-600 rounded-lg font-bold hover:bg-slate-200 transition flex items-center justify-center gap-2 text-sm"
                        >
                            <FontAwesomeIcon icon={faCopy} />
                            전일 복사
                        </button>
                        <button
                            onClick={handleSave}
                            className="w-full py-3 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 transition shadow-md flex items-center justify-center gap-2"
                        >
                            <FontAwesomeIcon icon={faSave} />
                            저장하기
                        </button>
                    </div>
                </div>

                {/* Main Content: List View */}
                <div className="flex-1 overflow-y-auto bg-white">
                    <div className="p-6">
                        <h1 className="text-2xl font-bold text-slate-800 mb-6 flex items-center gap-2">
                            <FontAwesomeIcon icon={faList} className="text-slate-600" />
                            일일 배차 현황 (목록형)
                        </h1>

                        <div className="border border-slate-200 rounded-lg overflow-hidden shadow-sm">
                            <table className="w-full text-left border-collapse">
                                <thead className="bg-slate-50 border-b border-slate-200">
                                    <tr>
                                        <th className="p-3 font-bold text-slate-600 text-sm w-64">현장 정보</th>
                                        <th className="p-3 font-bold text-slate-600 text-sm w-32">책임자</th>
                                        <th className="p-3 font-bold text-slate-600 text-sm">배정 인원 / 차량</th>
                                        <th className="p-3 font-bold text-slate-600 text-sm w-20 text-center">합계</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {sites.map(site => (
                                        <SiteRow
                                            key={site.id}
                                            site={site}
                                            workers={assignments[site.id!]?.workers || []}
                                            vehicles={assignments[site.id!]?.vehicles || []}
                                            onRemoveWorker={(itemId) => handleRemoveWorker(site.id!, itemId)}
                                        />
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>

                {/* Drag Overlay */}
                <DragOverlay>
                    {activeId && activeItem ? (
                        <div className="opacity-90 rotate-3 scale-105">
                            {activeItem.licensePlate ? (
                                <div className="px-2 py-1 bg-slate-100 rounded border border-slate-300 text-xs font-bold flex items-center gap-1">
                                    <FontAwesomeIcon icon={faTruck} className="text-slate-500" />
                                    {activeItem.licensePlate}
                                </div>
                            ) : (
                                <WorkerChip worker={activeItem} isOverlay />
                            )}
                        </div>
                    ) : null}
                </DragOverlay>
            </DndContext>
        </div>
    );
};

export default DailyDispatchPage;

import React, { useState, useEffect } from 'react';
import {
    DndContext,
    closestCenter,
    KeyboardSensor,
    PointerSensor,
    useSensor,
    useSensors,
    DragOverlay,
    defaultDropAnimationSideEffects,
    DragStartEvent,
    DragOverEvent,
    DragEndEvent,
} from '@dnd-kit/core';
import {
    arrayMove,
    SortableContext,
    sortableKeyboardCoordinates,
    verticalListSortingStrategy,
    useSortable,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faBuilding, faCalendarAlt, faMapMarkerAlt, faArrowLeft } from '@fortawesome/free-solid-svg-icons';
import { siteService, Site } from '../../services/siteService';

// --- Types ---
type SiteStatus = 'planned' | 'active' | 'completed';

interface ColumnData {
    id: SiteStatus;
    title: string;
    items: Site[];
}

// --- Sortable Item Component ---
interface SortableItemProps {
    site: Site;
}

const SortableItem: React.FC<SortableItemProps> = ({ site }) => {
    const {
        attributes,
        listeners,
        setNodeRef,
        transform,
        transition,
        isDragging,
    } = useSortable({ id: site.id! });

    const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: isDragging ? 0.5 : 1,
    };

    return (
        <div
            ref={setNodeRef}
            style={style}
            {...attributes}
            {...listeners}
            className="bg-white p-4 rounded-lg shadow-sm border border-slate-200 mb-3 cursor-grab hover:shadow-md transition-shadow"
        >
            <div className="font-bold text-slate-800 mb-1">{site.name}</div>
            <div className="text-xs text-slate-500 flex items-center gap-1 mb-1">
                <FontAwesomeIcon icon={faMapMarkerAlt} />
                {site.address}
            </div>

            {site.responsibleTeamName && (
                <div className="mt-2 text-xs font-medium text-blue-600 bg-blue-50 px-2 py-1 rounded inline-block">
                    담당: {site.responsibleTeamName}
                </div>
            )}
        </div>
    );
};

// --- Column Component ---
interface ColumnProps {
    column: ColumnData;
}

const Column: React.FC<ColumnProps> = ({ column }) => {
    const { setNodeRef } = useSortable({
        id: column.id,
        data: {
            type: 'Column',
            column,
        },
    });

    return (
        <div className="flex flex-col h-full bg-slate-100 rounded-xl p-4 min-w-[300px]">
            <h3 className={`font-bold text-lg mb-4 flex items-center justify-between ${column.id === 'planned' ? 'text-slate-600' :
                column.id === 'active' ? 'text-blue-600' : 'text-green-600'
                }`}>
                {column.title}
                <span className="bg-white px-2 py-0.5 rounded-full text-sm shadow-sm border border-slate-200">
                    {column.items.length}
                </span>
            </h3>
            <div ref={setNodeRef} className="flex-1 overflow-y-auto min-h-[100px]">
                <SortableContext items={column.items.map(i => i.id!)} strategy={verticalListSortingStrategy}>
                    {column.items.map((site) => (
                        <SortableItem key={site.id} site={site} />
                    ))}
                </SortableContext>
            </div>
        </div>
    );
};

// --- Main Page Component ---
const SiteAssignmentPage: React.FC = () => {
    const [columns, setColumns] = useState<Record<SiteStatus, ColumnData>>({
        planned: { id: 'planned', title: '예정된 현장', items: [] },
        active: { id: 'active', title: '진행중인 현장', items: [] },
        completed: { id: 'completed', title: '마감된 현장', items: [] },
    });
    const [activeId, setActiveId] = useState<string | null>(null);

    const sensors = useSensors(
        useSensor(PointerSensor, {
            activationConstraint: {
                distance: 5,
            },
        }),
        useSensor(KeyboardSensor, {
            coordinateGetter: sortableKeyboardCoordinates,
        })
    );

    useEffect(() => {
        fetchSites();
    }, []);

    const fetchSites = async () => {
        try {
            const sites = await siteService.getSites();
            const newColumns: Record<SiteStatus, ColumnData> = {
                planned: { id: 'planned', title: '예정된 현장', items: [] },
                active: { id: 'active', title: '진행중인 현장', items: [] },
                completed: { id: 'completed', title: '마감된 현장', items: [] },
            };

            sites.forEach(site => {
                const status = site.status || 'planned';
                if (newColumns[status]) {
                    newColumns[status].items.push(site);
                } else {
                    // Fallback for unknown status
                    newColumns['planned'].items.push(site);
                }
            });

            setColumns(newColumns);
        } catch (error) {
            console.error("Failed to fetch sites", error);
        }
    };

    const findContainer = (id: string): SiteStatus | undefined => {
        if (id in columns) return id as SiteStatus;
        return (Object.keys(columns) as SiteStatus[]).find(key =>
            columns[key].items.find(item => item.id === id)
        );
    };

    const handleDragStart = (event: DragStartEvent) => {
        setActiveId(event.active.id as string);
    };

    const handleDragOver = (event: DragOverEvent) => {
        const { active, over } = event;
        const overId = over?.id;

        if (!overId || active.id === overId) return;

        const activeContainer = findContainer(active.id as string);
        const overContainer = findContainer(overId as string);

        if (!activeContainer || !overContainer || activeContainer === overContainer) {
            return;
        }

        setColumns((prev) => {
            const activeItems = prev[activeContainer].items;
            const overItems = prev[overContainer].items;
            const activeIndex = activeItems.findIndex((item) => item.id === active.id);
            const overIndex = overItems.findIndex((item) => item.id === overId);

            let newIndex;
            if (overId in prev) {
                newIndex = overItems.length + 1;
            } else {
                const isBelowOverItem =
                    over &&
                    active.rect.current.translated &&
                    active.rect.current.translated.top > over.rect.top + over.rect.height;

                const modifier = isBelowOverItem ? 1 : 0;
                newIndex = overIndex >= 0 ? overIndex + modifier : overItems.length + 1;
            }

            return {
                ...prev,
                [activeContainer]: {
                    ...prev[activeContainer],
                    items: [
                        ...prev[activeContainer].items.filter((item) => item.id !== active.id),
                    ],
                },
                [overContainer]: {
                    ...prev[overContainer],
                    items: [
                        ...prev[overContainer].items.slice(0, newIndex),
                        activeItems[activeIndex],
                        ...prev[overContainer].items.slice(newIndex, prev[overContainer].items.length),
                    ],
                },
            };
        });
    };

    const handleDragEnd = async (event: DragEndEvent) => {
        const { active, over } = event;
        const activeContainer = findContainer(active.id as string);
        const overContainer = findContainer(over?.id as string);

        if (
            !activeContainer ||
            !overContainer ||
            (activeContainer === overContainer && active.id === over?.id)
        ) {
            setActiveId(null);
            return;
        }

        // Update local state for reordering within same column
        if (activeContainer === overContainer) {
            const activeIndex = columns[activeContainer].items.findIndex(i => i.id === active.id);
            const overIndex = columns[overContainer].items.findIndex(i => i.id === over?.id);

            if (activeIndex !== overIndex) {
                setColumns((prev) => ({
                    ...prev,
                    [activeContainer]: {
                        ...prev[activeContainer],
                        items: arrayMove(prev[activeContainer].items, activeIndex, overIndex),
                    },
                }));
            }
        } else {
            // Moved to different column -> Update Status in Firestore
            // Note: handleDragOver already updated the UI optimistically.
            // We just need to persist the change.
            const item = columns[overContainer].items.find(i => i.id === active.id);

            // If item is not found in overContainer, it might be because handleDragOver didn't fire correctly or state wasn't updated yet.
            // However, with dnd-kit, handleDragOver handles the visual move.
            // Let's ensure we find the item even if it's still conceptually in the old container for the logic, 
            // but visually it should be in the new one.

            // Actually, in dnd-kit with sortable, handleDragOver moves the item in the state.
            // So at DragEnd, the item IS in the overContainer in our state.

            if (item) {
                try {
                    await siteService.updateSite(item.id!, { status: overContainer });
                    console.log(`Updated site ${item.name} status to ${overContainer}`);
                } catch (error) {
                    console.error("Failed to update site status", error);
                    alert("상태 업데이트에 실패했습니다.");
                    fetchSites(); // Revert on failure
                }
            } else {
                // Fallback: If for some reason the item isn't in the new container yet (rare race condition or logic error),
                // we try to find it in the old container and move it manually.
                const oldItem = columns[activeContainer].items.find(i => i.id === active.id);
                if (oldItem) {
                    try {
                        await siteService.updateSite(oldItem.id!, { status: overContainer });
                        // Manually update state to reflect the move if handleDragOver didn't
                        setColumns(prev => ({
                            ...prev,
                            [activeContainer]: {
                                ...prev[activeContainer],
                                items: prev[activeContainer].items.filter(i => i.id !== active.id)
                            },
                            [overContainer]: {
                                ...prev[overContainer],
                                items: [...prev[overContainer].items, oldItem]
                            }
                        }));
                    } catch (error) {
                        console.error("Failed to update site status (fallback)", error);
                    }
                }
            }
        }

        setActiveId(null);
    };

    const dropAnimation = {
        sideEffects: defaultDropAnimationSideEffects({
            styles: {
                active: {
                    opacity: '0.5',
                },
            },
        }),
    };

    return (
        <div className="p-6 h-full flex flex-col max-w-[1600px] mx-auto">
            <div className="mb-6">
                <button
                    onClick={() => window.history.back()}
                    className="mb-4 px-4 py-2 bg-slate-600 text-white rounded-md hover:bg-slate-700 transition-colors flex items-center gap-2"
                >
                    <FontAwesomeIcon icon={faArrowLeft} />
                    뒤로 가기
                </button>
                <h1 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                    <FontAwesomeIcon icon={faBuilding} className="text-blue-600" />
                    현장 배정 관리 (Kanban)
                </h1>
                <p className="text-slate-600 mt-2">
                    현장 상태를 드래그 앤 드롭으로 관리하세요.
                </p>
            </div>

            <DndContext
                sensors={sensors}
                collisionDetection={closestCenter}
                onDragStart={handleDragStart}
                onDragOver={handleDragOver}
                onDragEnd={handleDragEnd}
            >
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-1 min-h-0">
                    <Column column={columns.planned} />
                    <Column column={columns.active} />
                    <Column column={columns.completed} />
                </div>

                <DragOverlay dropAnimation={dropAnimation}>
                    {activeId ? (
                        <div className="bg-white p-4 rounded-lg shadow-lg border border-blue-200 opacity-90 rotate-3 cursor-grabbing">
                            {/* Find the item to render overlay */}
                            {(() => {
                                const container = findContainer(activeId);
                                const item = container ? columns[container].items.find(i => i.id === activeId) : null;
                                return item ? (
                                    <>
                                        <div className="font-bold text-slate-800 mb-1">{item.name}</div>
                                        <div className="text-xs text-slate-500 flex items-center gap-1 mb-1">
                                            <FontAwesomeIcon icon={faMapMarkerAlt} />
                                            {item.address}
                                        </div>
                                    </>
                                ) : null;
                            })()}
                        </div>
                    ) : null}
                </DragOverlay>
            </DndContext>
        </div>
    );
};

export default SiteAssignmentPage;

import React, { useState, useEffect } from 'react';
import {
    DndContext,
    DragOverlay,
    useDraggable,
    useDroppable,
    DragStartEvent,
    DragEndEvent,
    useSensor,
    useSensors,
    PointerSensor,
    closestCenter
} from '@dnd-kit/core';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faUsers, faArrowRight, faExchangeAlt, faCalendarAlt, faSearch } from '@fortawesome/free-solid-svg-icons';
import { teamService, Team } from '../../services/teamService';
import { dailyReportService, DailyReport } from '../../services/dailyReportService';
import { manpowerService, Worker } from '../../services/manpowerService';

// --- Types ---
interface SupportWorker {
    reportId: string;
    workerId: string;
    workerName: string;
    manDay: number;
    originalTeamId: string;
    originalTeamName: string;
    currentTeamId: string; // The team they are currently assigned to in the report
    currentTeamName: string;
    isSupport: boolean;
}

interface TeamColumn {
    teamId: string;
    teamName: string;
    workers: SupportWorker[];
    totalManDay: number;
}

// --- Draggable Worker Card ---
const WorkerCard: React.FC<{ worker: SupportWorker; isOverlay?: boolean }> = ({ worker, isOverlay }) => {
    const uniqueId = `${worker.reportId}_${worker.workerId}`;
    const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
        id: uniqueId,
        data: { worker }
    });

    return (
        <div
            ref={setNodeRef}
            {...listeners}
            {...attributes}
            className={`
                p-3 rounded-lg border shadow-sm mb-2 cursor-grab flex justify-between items-center
                ${isOverlay ? 'bg-blue-50 border-blue-500 shadow-xl scale-105 z-50' : 'bg-white border-slate-200 hover:border-blue-300'}
                ${isDragging ? 'opacity-50' : 'opacity-100'}
            `}
        >
            <div>
                <div className="font-bold text-slate-700">{worker.workerName}</div>
                <div className="text-xs text-slate-500">
                    {worker.isSupport ? (
                        <span className="text-orange-600 font-medium">지원중 ({worker.currentTeamName})</span>
                    ) : (
                        <span>{worker.originalTeamName}</span>
                    )}
                </div>
            </div>
            <div className="bg-slate-100 px-2 py-1 rounded text-sm font-bold text-slate-600">
                {worker.manDay}공수
            </div>
        </div>
    );
};

// --- Droppable Column ---
const TeamColumn: React.FC<{ column: TeamColumn; isSource?: boolean }> = ({ column, isSource }) => {
    const { setNodeRef, isOver } = useDroppable({
        id: column.teamId,
        data: { teamId: column.teamId, isSource }
    });

    return (
        <div
            ref={setNodeRef}
            className={`
                flex-1 min-w-[300px] bg-slate-50 rounded-xl border-2 p-4 flex flex-col
                ${isOver ? 'border-blue-400 bg-blue-50' : 'border-slate-200'}
                transition-colors
            `}
        >
            <div className="flex justify-between items-center mb-4 pb-2 border-b border-slate-200">
                <div>
                    <h3 className={`font-bold text-lg ${isSource ? 'text-slate-800' : 'text-blue-700'}`}>
                        {column.teamName}
                    </h3>
                    <p className="text-xs text-slate-500">{isSource ? '내 팀 (출력)' : '지원 받을 팀'}</p>
                </div>
                <div className="text-right">
                    <div className="text-2xl font-bold text-slate-800">{column.totalManDay.toFixed(1)}</div>
                    <div className="text-xs text-slate-500">총 공수</div>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto min-h-[200px]">
                {column.workers.length === 0 ? (
                    <div className="h-full flex items-center justify-center text-slate-400 text-sm">
                        데이터 없음
                    </div>
                ) : (
                    column.workers.map(w => (
                        <WorkerCard key={`${w.reportId}_${w.workerId}`} worker={w} />
                    ))
                )}
            </div>
        </div>
    );
};

// --- Main Page ---
const SupportAssignmentPage: React.FC = () => {
    const [date, setDate] = useState(new Date().toISOString().slice(0, 10));
    const [myTeamId, setMyTeamId] = useState<string>('');
    const [teams, setTeams] = useState<Team[]>([]);
    const [reports, setReports] = useState<DailyReport[]>([]);
    const [workers, setWorkers] = useState<Worker[]>([]);
    const [activeId, setActiveId] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);

    // Derived State
    const [sourceColumn, setSourceColumn] = useState<TeamColumn | null>(null);
    const [targetColumns, setTargetColumns] = useState<TeamColumn[]>([]);

    const sensors = useSensors(
        useSensor(PointerSensor, { activationConstraint: { distance: 5 } })
    );

    useEffect(() => {
        fetchInitialData();
    }, []);

    useEffect(() => {
        if (myTeamId && date) {
            fetchDailyData();
        }
    }, [myTeamId, date]);

    const fetchInitialData = async () => {
        try {
            const [teamsData, workersData] = await Promise.all([
                teamService.getTeams(),
                manpowerService.getWorkers()
            ]);
            setTeams(teamsData);
            setWorkers(workersData);
            if (teamsData.length > 0) {
                setMyTeamId(teamsData[0].id!); // Default to first team
            }
        } catch (error) {
            console.error("Failed to fetch initial data", error);
        }
    };

    const fetchDailyData = async () => {
        setLoading(true);
        try {
            // Fetch reports for the date
            // Note: In a real app, we should query by date. 
            // For now, fetching all and filtering (optimization needed for production)
            const allReports = await dailyReportService.getAllReports();
            const dailyReports = allReports.filter(r => r.date === date);
            setReports(dailyReports);

            processColumns(dailyReports, myTeamId);
        } catch (error) {
            console.error("Failed to fetch daily data", error);
        } finally {
            setLoading(false);
        }
    };

    const processColumns = (currentReports: DailyReport[], currentMyTeamId: string) => {
        const newTargetColumns: TeamColumn[] = [];
        let newSourceColumn: TeamColumn | null = null;

        // Group workers by team (report)
        const teamWorkersMap = new Map<string, SupportWorker[]>();
        const teamManDayMap = new Map<string, number>();

        // Initialize maps for all teams
        teams.forEach(team => {
            teamWorkersMap.set(team.id!, []);
            teamManDayMap.set(team.id!, 0);
        });

        currentReports.forEach(report => {
            const teamId = report.teamId;
            if (!teamWorkersMap.has(teamId)) {
                teamWorkersMap.set(teamId, []);
                teamManDayMap.set(teamId, 0);
            }

            report.workers.forEach(worker => {
                const originalWorker = workers.find(w => w.id === worker.workerId);
                const originalTeamId = originalWorker?.teamId || 'unknown';
                const originalTeam = teams.find(t => t.id === originalTeamId);
                const originalTeamName = originalTeam?.name || '미배정';

                const supportWorker: SupportWorker = {
                    reportId: report.id!,
                    workerId: worker.workerId,
                    workerName: worker.name,
                    manDay: worker.manDay,
                    originalTeamId: originalTeamId,
                    originalTeamName: originalTeamName,
                    currentTeamId: teamId,
                    currentTeamName: report.teamName || '',
                    isSupport: originalTeamId !== teamId
                };

                teamWorkersMap.get(teamId)?.push(supportWorker);
                teamManDayMap.set(teamId, (teamManDayMap.get(teamId) || 0) + worker.manDay);
            });
        });

        // Build columns
        teams.forEach(team => {
            const column: TeamColumn = {
                teamId: team.id!,
                teamName: team.name,
                workers: teamWorkersMap.get(team.id!) || [],
                totalManDay: teamManDayMap.get(team.id!) || 0
            };

            if (team.id === currentMyTeamId) {
                newSourceColumn = column;
            } else {
                newTargetColumns.push(column);
            }
        });

        setSourceColumn(newSourceColumn);
        setTargetColumns(newTargetColumns);
    };

    const handleDragStart = (event: DragStartEvent) => {
        setActiveId(event.active.id as string);
    };

    const handleDragEnd = async (event: DragEndEvent) => {
        const { active, over } = event;
        if (!over) return;

        const worker = active.data.current?.worker as SupportWorker;
        const targetTeamId = over.id as string;

        if (worker.currentTeamId === targetTeamId) return;

        const sourceReport = reports.find(r => r.id === worker.reportId);
        const targetReport = reports.find(r => r.teamId === targetTeamId && r.date === date);

        if (!sourceReport) return;

        if (!targetReport) {
            alert("해당 팀의 금일 일보가 존재하지 않아 이동할 수 없습니다. 먼저 일보를 생성해주세요.");
            return;
        }

        if (window.confirm(`${worker.workerName} 님을 ${worker.currentTeamName}에서 ${targetReport.teamName}(으)로 이동하시겠습니까?`)) {
            try {
                // 1. Remove from source report
                await dailyReportService.removeWorkerFromReport(sourceReport.id!, worker.workerId);

                // 2. Add to target report
                const workerDetails = sourceReport.workers.find(w => w.workerId === worker.workerId);
                if (workerDetails) {
                    await dailyReportService.addWorkerToReport(
                        targetReport.date,
                        targetReport.teamId,
                        targetReport.teamName || '',
                        targetReport.siteId,
                        targetReport.siteName || '',
                        workerDetails
                    );
                }

                fetchDailyData();

            } catch (error) {
                console.error("Failed to move worker", error);
                alert("이동 중 오류가 발생했습니다.");
            }
        }
    };

    const activeWorker = activeId
        ? (sourceColumn?.workers.find(w => w.reportId === activeId) || targetColumns.flatMap(c => c.workers).find(w => w.reportId === activeId))
        : null;

    return (
        <div className="p-6 h-full flex flex-col max-w-[1800px] mx-auto">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                        <FontAwesomeIcon icon={faExchangeAlt} className="text-blue-600" />
                        지원 공수 관리
                    </h1>
                    <p className="text-slate-600 mt-1">
                        내 팀의 공수를 다른 팀으로 지원 보낼 수 있습니다.
                    </p>
                </div>
                <div className="flex gap-4">
                    <div className="flex items-center gap-2 bg-white px-3 py-2 rounded-lg border border-slate-200">
                        <FontAwesomeIcon icon={faCalendarAlt} className="text-slate-400" />
                        <input
                            type="date"
                            value={date}
                            onChange={(e) => setDate(e.target.value)}
                            className="border-none focus:ring-0 text-sm text-slate-700"
                        />
                    </div>
                    <div className="flex items-center gap-2 bg-white px-3 py-2 rounded-lg border border-slate-200">
                        <FontAwesomeIcon icon={faUsers} className="text-slate-400" />
                        <select
                            value={myTeamId}
                            onChange={(e) => setMyTeamId(e.target.value)}
                            className="border-none focus:ring-0 text-sm text-slate-700 min-w-[150px]"
                        >
                            {teams.map(t => (
                                <option key={t.id} value={t.id}>{t.name}</option>
                            ))}
                        </select>
                    </div>
                </div>
            </div>

            <DndContext
                sensors={sensors}
                collisionDetection={closestCenter}
                onDragStart={handleDragStart}
                onDragEnd={handleDragEnd}
            >
                <div className="flex gap-8 flex-1 min-h-0 overflow-x-auto pb-4">
                    {/* Source Column (My Team) */}
                    {sourceColumn && (
                        <div className="flex-shrink-0 w-80">
                            <TeamColumn column={sourceColumn} isSource />
                        </div>
                    )}

                    {/* Arrow Divider */}
                    <div className="flex flex-col justify-center items-center text-slate-300">
                        <FontAwesomeIcon icon={faArrowRight} className="text-4xl" />
                        <span className="text-sm font-bold mt-2">지원 이동</span>
                    </div>

                    {/* Target Columns (Other Teams) */}
                    <div className="flex gap-4 flex-1 overflow-x-auto">
                        {targetColumns.map(col => (
                            <div key={col.teamId} className="flex-shrink-0 w-80">
                                <TeamColumn column={col} />
                            </div>
                        ))}
                    </div>
                </div>

                <DragOverlay>
                    {activeWorker ? <WorkerCard worker={activeWorker} isOverlay /> : null}
                </DragOverlay>
            </DndContext>
        </div>
    );
};

export default SupportAssignmentPage;

import React, { useState, useEffect } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faUsers, faUserGroup, faBuilding, faSave, faPlus, faSearch, faGripVertical } from '@fortawesome/free-solid-svg-icons';
import { teamService, Team } from '../../services/teamService';
import { manpowerService, Worker } from '../../services/manpowerService';
import { companyService, Company } from '../../services/companyService';
import TeamForm from '../../components/manpower/TeamForm';
import {
    DndContext,
    DragOverlay,
    useDraggable,
    useDroppable,
    DragStartEvent,
    DragEndEvent,
    useSensor,
    useSensors,
    PointerSensor,
    TouchSensor,
    closestCenter
} from '@dnd-kit/core';

interface TeamAssignmentData {
    teamId: string;
    teamName: string;
    assignedWorkers: string[];
}

// --- Draggable Worker Component ---
interface DraggableWorkerProps {
    worker: Worker;
    isOverlay?: boolean;
}

const DraggableWorker: React.FC<DraggableWorkerProps> = ({ worker, isOverlay }) => {
    const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
        id: worker.id || '',
        data: { worker }
    });

    const style = {
        opacity: isDragging ? 0.5 : 1,
        cursor: 'grab',
    };

    return (
        <div
            ref={setNodeRef}
            style={style}
            {...listeners}
            {...attributes}
            className={`
                flex items-center justify-between p-3 bg-white rounded-lg border shadow-sm 
                ${isOverlay ? 'border-blue-500 shadow-lg scale-105 z-50' : 'border-gray-200 hover:border-blue-300'}
                transition-all duration-200
            `}
        >
            <div className="flex items-center gap-3">
                <div className="text-gray-400 cursor-grab active:cursor-grabbing">
                    <FontAwesomeIcon icon={faGripVertical} />
                </div>
                <div>
                    <div className="font-medium text-gray-800">{worker.name}</div>
                    <div className="text-xs text-gray-500">{worker.role}</div>
                </div>
            </div>
            <div className={`text-xs px-2 py-1 rounded-full ${worker.status === '재직' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'
                }`}>
                {worker.status}
            </div>
        </div>
    );
};

// --- Droppable Container Component (Team Card) ---
interface DroppableTeamProps {
    team: Team;
    assignedWorkers: Worker[];
    onRemoveWorker: (workerId: string) => void;
}

const DroppableTeam: React.FC<DroppableTeamProps> = ({ team, assignedWorkers, onRemoveWorker }) => {
    const { setNodeRef, isOver } = useDroppable({
        id: `team-${team.id}`,
        data: { type: 'team', teamId: team.id }
    });

    return (
        <div
            ref={setNodeRef}
            className={`
                bg-white rounded-xl border-2 transition-colors duration-200 flex flex-col h-full
                ${isOver ? 'border-blue-500 bg-blue-50' : 'border-gray-200'}
            `}
        >
            {/* Header */}
            <div className="p-4 border-b border-gray-100 bg-gray-50 rounded-t-xl flex justify-between items-center">
