                        source?.data?.leaderName ??
                        (source ? '현장 리더 확인 필요' : '배치 예정'),
                    leaderImageUrl:
                        getWorkerProfileImageUrl(preferredLeader) ||
                        getWorkerProfileImageUrl(leader) ||
                        resolveLeaderImageFromWorker(
                            preferredLeaderName ?? leader?.name ?? source?.data?.leaderName ?? ''
                        ) ||
                        '',
