                                    </div>
                                    <div className="h-10 flex items-center justify-center bg-slate-50 group-hover:bg-teal-100 transition-colors">
                                        <span className={`text-lg font-bold ${manDay > 0 ? 'text-teal-600' : 'text-slate-300'}`}>
                                            {manDay.toFixed(1)}
                                        </span>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
};

