            const orderCompare = (a.sortOrder ?? 0) - (b.sortOrder ?? 0);
            if (orderCompare !== 0) return orderCompare;
            return normalizeText(a.name).localeCompare(normalizeText(b.name), 'ko');
        });
    }, []);

