                                                        </button>
                                                        <button
                                                            onClick={() => handleDeleteCompany(company)}
                                                            className="p-1 text-red-600 hover:text-red-800 transition-colors"
                                                            title="삭제"
                                                        >
                                                            <FontAwesomeIcon icon={faTrash} />
                                                        </button>
                                                    </div>
                                                </td>
                                            </tr>


                                        </React.Fragment>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                )
                }
            </div >
            {/* End of Card Grid */}
        </div >
    );
};

