    companyId: '소속 회사 ID',
    companyName: '소속 회사명',
    salaryModel: '급여 형태',
    unitPrice: '단가',
    bankName: '은행명',
    accountNumber: '계좌번호',
    accountHolder: '예금주',
    idNumber: '주민등록번호',
    contact: '연락처',
    email: '이메일',
    totalManDay: '누적 공수',
    fileNameSaved: '저장된 파일명',

    // Team
    leaderId: '팀장 ID',
    leaderName: '팀장명',
    memberCount: '팀원 수',
    parentTeamId: '상위 팀 ID',
    parentTeamName: '상위 팀명',

    // Site
    startDate: '시작일',
    endDate: '종료일',
    responsibleTeamId: '담당 팀 ID',

    // Company
    code: '회사 코드',
    businessNumber: '사업자번호',
    ceoName: '대표자명',

    // Daily Report
    date: '날짜',
    siteId: '현장 ID',
    siteName: '현장명',
    writerId: '작성자 ID',
    workers: '작업자 목록',
    manDay: '공수',
    workContent: '작업 내용',
    weather: '날씨',

    // User
    username: '사용자명',
    department: '부서',
    position: '직위',
    photoURL: '프로필 사진 URL',
    phoneNumber: '전화번호',

    // Audit Log
    action: '활동 유형',
    actorId: '수행자 ID',
    actorEmail: '수행자 이메일',
    targetId: '대상 ID',
    details: '상세 내용',
    timestamp: '발생 일시'
};

const FirestoreStructureViewer: React.FC = () => {
    const [schemas, setSchemas] = useState<{ [key: string]: CollectionSchema }>({});
    const [loading, setLoading] = useState<{ [key: string]: boolean }>({});
    const [showHelp, setShowHelp] = useState(true);
    const [copySuccess, setCopySuccess] = useState(false);
    const [copiedActionId, setCopiedActionId] = useState<string | null>(null);
    const [isPasteModalOpen, setIsPasteModalOpen] = useState(false);
    const [pasteText, setPasteText] = useState('');
    const [pasteError, setPasteError] = useState<string | null>(null);
    const [pastedItems, setPastedItems] = useState<ClipboardCollectionSchemaPayloadV1[]>([]);

    useEffect(() => {
        COLLECTIONS.forEach(col => {
            setLoading(prev => ({ ...prev, [col.id]: true }));
            const inferredFields = inferSchema({}, col.id);
            setSchemas(prev => ({
                ...prev,
                [col.id]: {
                    name: col.name,
                    docCount: 0,
                    fields: inferredFields,
                    lastUpdated: new Date()
                }
            }));
            setLoading(prev => ({ ...prev, [col.id]: false }));
        });
    }, []);

    const inferSchema = (data: any, collectionId?: string): SchemaField[] => {
        const fields: SchemaField[] = [];
        const existingKeys = new Set(Object.keys(data));

        // 1. Process existing data fields
        Object.keys(data).sort().forEach(key => {
            const value = data[key];
            let type: string = typeof value;
            let example = String(value);
            let children: SchemaField[] | undefined = undefined;

            if (value === null) {
                type = 'null';
                example = 'null';
            } else if (Array.isArray(value)) {
                type = 'array';
                example = `Array(${value.length})`;
                if (value.length > 0) {
                    const firstItem = value[0];
                    if (typeof firstItem === 'object' && firstItem !== null) {
                        children = inferSchema(firstItem);
                    }
                }
            } else if (value instanceof Date) {
                type = 'timestamp';
                example = value.toISOString();
            } else if (typeof value === 'object') {
                if (value.seconds !== undefined && value.nanoseconds !== undefined) {
                    type = 'timestamp';
                    example = new Date(value.seconds * 1000).toLocaleString();
                } else {
                    type = 'map';
                    example = '{...}';
                    children = inferSchema(value);
                }
            } else if (type === 'string') {
                if (value.length > 30) example = value.substring(0, 30) + '...';
            }

            const isRequired = collectionId ? REQUIRED_FIELDS[collectionId]?.includes(key) : false;
            const relatedCollection = collectionId ? RELATIONSHIPS[`${collectionId}.${key}`] : undefined;

            fields.push({
                name: key,
                type,
                example,
                description: FIELD_DESCRIPTIONS[key],
                isSystem: SYSTEM_FIELDS.includes(key),
                isRequired,
                relatedCollection,
                isMissing: false,
                hasChildren: !!children,
                children
            });
        });

        // 2. Add missing known fields
        if (collectionId && KNOWN_FIELDS[collectionId]) {
            KNOWN_FIELDS[collectionId].forEach(key => {
                if (!existingKeys.has(key)) {
                    const isRequired = REQUIRED_FIELDS[collectionId]?.includes(key) || false;
                    const relatedCollection = RELATIONSHIPS[`${collectionId}.${key}`];

                    fields.push({
                        name: key,
                        type: 'unknown',
                        example: 'No Data',
                        description: FIELD_DESCRIPTIONS[key],
                        isSystem: SYSTEM_FIELDS.includes(key),
                        isRequired,
                        relatedCollection,
                        isMissing: true,
                        hasChildren: false
                    });
                }
            });
        }

        return fields;
    };

    const getTypeColor = (type: string, isMissing?: boolean) => {
        if (isMissing) return 'text-slate-400 bg-slate-50 border-slate-100';

        switch (type) {
            case 'string': return 'text-green-600 bg-green-50 border-green-100';
            case 'number': return 'text-blue-600 bg-blue-50 border-blue-100';
            case 'boolean': return 'text-purple-600 bg-purple-50 border-purple-100';
            case 'timestamp': return 'text-orange-600 bg-orange-50 border-orange-100';
            case 'array': return 'text-pink-600 bg-pink-50 border-pink-100';
            case 'map': return 'text-indigo-600 bg-indigo-50 border-indigo-100';
            default: return 'text-slate-600 bg-slate-50 border-slate-100';
        }
    };

    const generateAIContext = () => {
        let markdown = `# Project Database Schema (Firestore)\n\n`;
        markdown += `Generated at: ${new Date().toLocaleString()}\n\n`;

        // 1. Collections & Fields
        Object.entries(schemas).forEach(([colId, schema]) => {
            markdown += `## Collection: ${schema.name} (ID: ${colId})\n`;
            schema.fields.forEach(field => {
                const flags = [];
                if (field.isRequired) flags.push('Required');
                if (field.isSystem) flags.push('System/Auto');
                if (field.relatedCollection) flags.push(`Link -> ${field.relatedCollection}`);
                if (field.isMissing) flags.push('Optional/Empty');

                const flagStr = flags.length > 0 ? ` [${flags.join(', ')}]` : '';
                const desc = field.description ? ` - ${field.description}` : '';

                markdown += `- \`${field.name}\` (${field.type}): ${field.example}${flagStr}${desc}\n`;
            });
            markdown += `\n`;
        });

        // 2. Relationships
        markdown += `## Relationships (Foreign Keys)\n`;
        Object.entries(RELATIONSHIPS).forEach(([key, target]) => {
            markdown += `- \`${key}\` references \`${target}\` collection\n`;
        });
        markdown += `\n`;

        // 3. Enums
        markdown += `## Enums (Allowed Values)\n`;
        Object.entries(ENUMS).forEach(([key, values]) => {
            markdown += `- \`${key}\`: ${values.join(', ')}\n`;
        });

        return markdown;
    };

    const handleCopyAIContext = async () => {
        const context = generateAIContext();
        const ok = await copyTextToClipboard(context);
        if (!ok) {
            alert('복사하기 실패');
            return;
        }

        setCopySuccess(true);
        setTimeout(() => setCopySuccess(false), 2000);
    };

     const markCopied = (id: string) => {
         setCopiedActionId(id);
         window.setTimeout(() => setCopiedActionId(null), 1500);
     };

     const handleCopyCollectionItem = async (collectionId: string, collectionName: string) => {
         const schema = schemas[collectionId];
         if (!schema) {
             alert('아직 스키마를 불러오지 못했습니다. 잠시 후 다시 시도해주세요.');
             return;
         }

         const payload: ClipboardCollectionSchemaPayloadV1 = {
             __type: 'firestore_schema_collection',
             version: 1,
             collectionId,
             collectionName,
             schema,
             copiedAt: new Date().toISOString()
         };

         const ok = await copyTextToClipboard(JSON.stringify(payload, null, 2));
         if (!ok) {
             alert('복사 실패');
             return;
         }

         markCopied(`collection-item:${collectionId}`);
     };

     const handleCopyFieldLocation = async (
         collectionId: string,
         collectionName: string,
         field: SchemaField
     ) => {
         const context =
             `[Context: Field '${collectionId}.${field.name}']\n` +
             `Collection: ${collectionName} (ID: ${collectionId})\n` +
             `Field: ${field.name}\n` +
             `Type: ${field.type}\n` +
             `Example: ${field.example}\n` +
             `Description: ${field.description ?? ''}\n` +
             `Required: ${field.isRequired ? 'true' : 'false'}\n` +
             `System: ${field.isSystem ? 'true' : 'false'}\n` +
             `RelatedCollection: ${field.relatedCollection ?? ''}`;

         const ok = await copyTextToClipboard(context);
         if (!ok) {
             alert('복사 실패');
             return;
         }

         markCopied(`field-location:${collectionId}:${field.name}`);
     };

     const tryParseJson = (text: string): unknown | null => {
         try {
             return JSON.parse(text);
         } catch {
             return null;
         }
     };

     const handlePasteConfirm = () => {
         const trimmed = pasteText.trim();
         if (trimmed.length === 0) {
             setPasteError('붙여넣을 내용이 비어있습니다.');
             return;
         }

         const parsed = tryParseJson(trimmed);
         if (!isClipboardCollectionSchemaPayloadV1(parsed)) {
             setPasteError('붙여넣기 형식이 올바르지 않습니다. (항목 복사로 생성된 JSON만 지원)');
             return;
         }

         setPastedItems(prev => {
             const existsIndex = prev.findIndex(p => p.collectionId === parsed.collectionId);
             if (existsIndex === -1) return [parsed, ...prev];

             const next = prev.slice();
             next[existsIndex] = parsed;
             return next;
         });

         setPasteError(null);
         setPasteText('');
         setIsPasteModalOpen(false);
     };

    const renderFields = (
        fields: SchemaField[],
        meta: { collectionId: string; collectionName: string },
        level = 0
    ) => {
        return (
            <div className={`space-y-1 ${level > 0 ? 'ml-4 border-l-2 border-slate-100 pl-2 mt-1' : ''}`}>
                {fields.map((field) => (
                    <div
                        key={field.name}
                        className={`text-sm group hover:bg-slate-50 p-1 rounded transition-colors ${field.isMissing ? 'opacity-60' : ''}`}
                    >
                        <div className="flex items-center gap-2 flex-wrap">
                            <span className={`font-semibold min-w-[100px] flex items-center gap-1 ${field.isMissing ? 'text-slate-400 italic' : 'text-slate-700'}`}>
                                {field.name}
                                {field.isRequired && (
                                    <span title="필수 입력 항목" className="text-red-500 text-[10px]">
                                        <FontAwesomeIcon icon={faAsterisk} />
                                    </span>
                                )}
                                {field.isSystem && (
                                    <span title="시스템 자동 생성 데이터" className="text-[10px] bg-slate-200 text-slate-600 px-1 rounded flex items-center gap-1">
                                        <FontAwesomeIcon icon={faRobot} className="text-[8px]" />
                                        Auto
                                    </span>
                                )}
                                {field.relatedCollection && (
                                    <span title={`연결된 컬렉션: ${field.relatedCollection}`} className="text-[10px] bg-indigo-100 text-indigo-700 px-1 rounded flex items-center gap-1 cursor-help">
                                        <FontAwesomeIcon icon={faLink} className="text-[8px]" />
                                        {field.relatedCollection}
                                    </span>
                                )}
                                {field.isMissing && (
                                    <span title="데이터 없음 (Optional)" className="text-[10px] bg-slate-100 text-slate-400 px-1 rounded flex items-center gap-1">
                                        <FontAwesomeIcon icon={faGhost} className="text-[8px]" />
                                        Empty
                                    </span>
                                )}
                            </span>

                            <span className={`text-[10px] px-1.5 py-0.5 rounded font-mono border ${getTypeColor(field.type, field.isMissing)}`}>
                                {field.type}
                            </span>

                            {field.description && (
                                <span className="text-xs text-slate-500 bg-slate-100 px-1.5 py-0.5 rounded">
                                    {field.description}
                                </span>
                            )}

                            <span className="text-slate-400 text-xs truncate max-w-[200px] font-mono">
                                {field.example}
                            </span>

                             <button
                                 type="button"
                                 onClick={() => void handleCopyFieldLocation(meta.collectionId, meta.collectionName, field)}
                                 className="ml-auto text-xs bg-white border border-slate-200 text-slate-500 hover:text-indigo-700 hover:border-indigo-200 px-2 py-1 rounded transition-colors opacity-0 group-hover:opacity-100"
                                 title="필드 위치/정보 복사"
                             >
                                 <FontAwesomeIcon icon={copiedActionId === `field-location:${meta.collectionId}:${field.name}` ? faCheck : faCopy} />
                                 <span className="ml-1">복사</span>
                             </button>
                        </div>
                        {field.children && renderFields(field.children, meta, level + 1)}
                    </div>
                ))}
            </div>
        );
    };

    return (
        <div className="p-6 max-w-[1800px] mx-auto">
            <div className="mb-6 flex justify-between items-start">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800 flex items-center gap-3">
                        <FontAwesomeIcon icon={faLayerGroup} className="text-brand-600" />
                        실시간 DB 구조도
                    </h1>
                    <p className="text-slate-500 mt-2 flex items-center gap-2 text-sm">
                        <FontAwesomeIcon icon={faInfoCircle} />
                        실제 데이터베이스에 저장된 최신 데이터를 기반으로 구조를 시각화합니다.
                    </p>
                </div>
                <div className="flex gap-2">
                    <button
                        onClick={handleCopyAIContext}
                        className={`transition flex items-center gap-2 text-sm font-medium border px-3 py-2 rounded-lg shadow-sm ${copySuccess
                            ? 'bg-green-50 border-green-200 text-green-700'
                            : 'bg-indigo-50 border-indigo-200 text-indigo-700 hover:bg-indigo-100'
                            }`}
                    >
                        <FontAwesomeIcon icon={copySuccess ? faCheck : faCopy} />
                        {copySuccess ? '복사 완료!' : 'AI 프롬프트 복사'}
                    </button>
                    <button
                        onClick={() => {
                            setPasteError(null);
                            setIsPasteModalOpen(true);
                        }}
                        className="transition flex items-center gap-2 text-sm font-medium bg-white border border-slate-200 text-slate-600 hover:bg-slate-50 px-3 py-2 rounded-lg shadow-sm"
                        title="항목 복사로 생성된 JSON을 붙여넣습니다"
                    >
                        <FontAwesomeIcon icon={faCopy} />
                        항목 붙여넣기
                    </button>
                    <button
                        onClick={() => setShowHelp(!showHelp)}
                        className="text-slate-500 hover:text-brand-600 transition flex items-center gap-2 text-sm font-medium bg-white border border-slate-200 px-3 py-2 rounded-lg shadow-sm"
                    >
                        <FontAwesomeIcon icon={faQuestionCircle} />
                        {showHelp ? '도움말 숨기기' : '도움말 보기'}
                    </button>
                </div>
            </div>

            {pastedItems.length > 0 && (
                <div className="mb-6 bg-white rounded-xl border border-slate-200 p-4 shadow-sm">
                    <div className="flex items-center justify-between gap-3">
                        <div className="font-bold text-slate-800">붙여넣은 항목</div>
                        <button
                            type="button"
                            onClick={() => setPastedItems([])}
                            className="text-xs font-bold text-slate-600 hover:text-slate-900"
                        >
                            전체 비우기
                        </button>
                    </div>
                    <div className="mt-3 grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3">
                        {pastedItems.map((item) => (
                            <div key={item.collectionId} className="border border-slate-200 rounded-lg p-3 bg-slate-50">
                                <div className="flex items-center justify-between gap-2">
                                    <div className="font-bold text-slate-800 truncate">{item.collectionName}</div>
                                    <button
                                        type="button"
                                        onClick={() => {
                                            setPastedItems(prev => prev.filter(p => p.collectionId !== item.collectionId));
                                        }}
                                        className="text-xs font-bold text-rose-600 hover:text-rose-700"
                                    >
                                        삭제
                                    </button>
                                </div>
                                <div className="mt-1 text-xs text-slate-500 font-mono">Collection ID: {item.collectionId}</div>
                                <div className="mt-1 text-xs text-slate-500">Fields: {item.schema.fields.length}</div>
                                <div className="mt-3 flex justify-end">
                                    <button
                                        type="button"
                                        onClick={() => {
                                            void copyTextToClipboard(JSON.stringify(item, null, 2)).then(ok => {
                                                if (!ok) {
                                                    alert('복사 실패');
                                                    return;
                                                }
                                                markCopied(`pasted-item:${item.collectionId}`);
                                            });
                                        }}
                                        className="text-xs bg-white border border-slate-200 text-slate-600 hover:text-indigo-700 hover:border-indigo-200 px-2 py-1 rounded transition-colors"
                                    >
                                        <FontAwesomeIcon icon={copiedActionId === `pasted-item:${item.collectionId}` ? faCheck : faCopy} />
                                        <span className="ml-1">다시 복사</span>
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {showHelp && (
                <div className="mb-8 bg-white rounded-xl border border-slate-200 p-5 shadow-sm animate-fade-in">
                    <h3 className="font-bold text-slate-800 mb-3 flex items-center gap-2">
                        <FontAwesomeIcon icon={faCode} className="text-slate-400" />
                        데이터 타입 범례
                    </h3>
                    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3 mb-4">
                        <div className="flex items-center gap-2 p-2 rounded bg-green-50 border border-green-100">
                            <span className="w-2 h-2 rounded-full bg-green-500"></span>
                            <span className="text-xs font-medium text-green-700">String (문자열)</span>
                        </div>
                        <div className="flex items-center gap-2 p-2 rounded bg-blue-50 border border-blue-100">
                            <span className="w-2 h-2 rounded-full bg-blue-500"></span>
                            <span className="text-xs font-medium text-blue-700">Number (숫자)</span>
                        </div>
                        <div className="flex items-center gap-2 p-2 rounded bg-orange-50 border border-orange-100">
                            <span className="w-2 h-2 rounded-full bg-orange-500"></span>
                            <span className="text-xs font-medium text-orange-700">Timestamp (날짜)</span>
                        </div>
                        <div className="flex items-center gap-2 p-2 rounded bg-purple-50 border border-purple-100">
                            <span className="w-2 h-2 rounded-full bg-purple-500"></span>
                            <span className="text-xs font-medium text-purple-700">Boolean (참/거짓)</span>
                        </div>
                        <div className="flex items-center gap-2 p-2 rounded bg-pink-50 border border-pink-100">
                            <span className="w-2 h-2 rounded-full bg-pink-500"></span>
                            <span className="text-xs font-medium text-pink-700">Array (배열/목록)</span>
                        </div>
                        <div className="flex items-center gap-2 p-2 rounded bg-indigo-50 border border-indigo-100">
                            <span className="w-2 h-2 rounded-full bg-indigo-500"></span>
                            <span className="text-xs font-medium text-indigo-700">Map (객체)</span>
                        </div>
                    </div>

                    <div className="flex flex-wrap gap-4 mb-4">
                        <div className="flex items-center gap-2 p-2 rounded bg-slate-100 border border-slate-200">
                            <span className="text-[10px] bg-slate-200 text-slate-600 px-1 rounded flex items-center gap-1">
                                <FontAwesomeIcon icon={faRobot} className="text-[8px]" />
                                Auto
                            </span>
                            <span className="text-xs text-slate-600">: 시스템 자동 생성 데이터</span>
                        </div>
                        <div className="flex items-center gap-2 p-2 rounded bg-red-50 border border-red-100">
                            <span className="text-red-500 text-[10px]">
                                <FontAwesomeIcon icon={faAsterisk} />
                            </span>
                            <span className="text-xs text-red-600">: 필수 입력 항목</span>
                        </div>
                        <div className="flex items-center gap-2 p-2 rounded bg-indigo-50 border border-indigo-100">
                            <span className="text-[10px] bg-indigo-100 text-indigo-700 px-1 rounded flex items-center gap-1">
                                <FontAwesomeIcon icon={faLink} className="text-[8px]" />
                                teams
                            </span>
                            <span className="text-xs text-indigo-700">: 다른 컬렉션과 연결됨 (관계)</span>
                        </div>
                        <div className="flex items-center gap-2 p-2 rounded bg-slate-50 border border-slate-200 opacity-60">
                            <span className="text-[10px] bg-slate-100 text-slate-400 px-1 rounded flex items-center gap-1">
                                <FontAwesomeIcon icon={faGhost} className="text-[8px]" />
                                Empty
                            </span>
                            <span className="text-xs text-slate-400">: 데이터 없음 (선택 항목)</span>
                        </div>
                    </div>

                    <div className="mt-4 text-xs text-slate-500 bg-slate-50 p-3 rounded border border-slate-100">
                        <p className="mb-1">💡 <strong>참고사항:</strong></p>
                        <ul className="list-disc list-inside space-y-1">
                            <li>이 화면은 Firestore 데이터베이스의 실제 구조를 보여줍니다.</li>
                            <li><strong>흐리게 표시된 항목</strong>은 현재 데이터가 없지만, 입력 가능한 필드입니다.</li>
                            <li>'설명' 태그는 개발 편의를 위해 추가된 것으로, 실제 DB에는 저장되지 않습니다.</li>
                            <li><strong>AI 프롬프트 복사</strong> 버튼을 누르면 현재 DB 구조를 AI가 이해하기 쉬운 텍스트로 복사합니다.</li>
                        </ul>
                    </div>
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {COLLECTIONS.map(col => (
                    <div key={col.id} className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col h-full hover:shadow-md transition-shadow">
                        <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                            <h3 className="font-bold text-slate-800 flex items-center gap-2">
                                <FontAwesomeIcon icon={faDatabase} className="text-slate-400" />
                                {col.name}
                            </h3>
                            <div className="flex items-center gap-2">
                                {loading[col.id] && <span className="text-xs text-slate-400 animate-pulse">분석 중...</span>}
                                <button
                                    onClick={() => {
                                        const schema = schemas[col.id];
                                        if (!schema) return;

                                        const fieldNames = schema.fields.map(f => f.name).join(', ');
                                        const context = `[Context: Collection '${col.id}']\nName: ${col.name}\nFields: ${fieldNames}\nDescription: ${col.name} 컬렉션입니다.`;

                                        navigator.clipboard.writeText(context).then(() => {
                                            alert(`'${col.name}' 위치 정보가 복사되었습니다.\nAI에게 붙여넣어주세요.`);
                                        }).catch(err => {
                                            console.error('Copy failed', err);
                                            alert('복사 실패');
                                        });
                                    }}
                                    className="text-xs bg-white border border-slate-200 text-slate-500 hover:text-blue-600 hover:border-blue-200 px-2 py-1 rounded transition-colors"
                                    title="AI에게 알려줄 위치 정보 복사"
                                >
                                    <FontAwesomeIcon icon={faCopy} /> AI 위치 복사
                                </button>
                                <button
                                    type="button"
                                    onClick={() => void handleCopyCollectionItem(col.id, col.name)}
                                    className="text-xs bg-white border border-slate-200 text-slate-500 hover:text-indigo-700 hover:border-indigo-200 px-2 py-1 rounded transition-colors"
                                    title="컬렉션 항목(JSON) 복사"
                                >
                                    <FontAwesomeIcon icon={copiedActionId === `collection-item:${col.id}` ? faCheck : faCopy} />
                                    <span className="ml-1">항목 복사</span>
                                </button>
                            </div>
                        </div>
                        <div className="p-4 overflow-auto flex-1 max-h-[600px] min-h-[200px]">
                            {schemas[col.id]?.fields.length > 0 ? (
                                renderFields(schemas[col.id].fields, { collectionId: col.id, collectionName: col.name })
                            ) : (
                                <div className="flex flex-col items-center justify-center h-full text-slate-400 text-sm py-10">
                                    <FontAwesomeIcon icon={faTable} className="text-3xl mb-2 opacity-20" />
                                    <p>데이터가 없습니다</p>
                                </div>
                            )}
                        </div>
                        <div className="p-2 border-t border-slate-100 bg-slate-50 text-[10px] text-right text-slate-400 font-mono">
                            Collection ID: {col.id}
                        </div>
                    </div>
                ))}
            </div>

            {isPasteModalOpen && (
                <div className="fixed inset-0 bg-black/40 flex items-center justify-center p-4 z-50">
                    <div className="w-full max-w-2xl bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
                        <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
                            <div className="font-bold text-slate-800">항목 붙여넣기</div>
                            <button
                                type="button"
                                onClick={() => {
                                    setIsPasteModalOpen(false);
                                    setPasteError(null);
                                }}
                                className="text-xs font-bold text-slate-600 hover:text-slate-900"
                            >
                                닫기
                            </button>
                        </div>

                        <div className="p-4">
                            <div className="text-sm text-slate-600">
                                컬렉션 카드의 <span className="font-bold">항목 복사</span>로 생성된 JSON을 아래에 붙여넣고 저장하세요.
                            </div>
                            <textarea
                                value={pasteText}
                                onChange={(e) => setPasteText(e.target.value)}
                                className="mt-3 w-full h-56 border border-slate-200 rounded-lg p-3 font-mono text-xs focus:outline-none focus:ring-2 focus:ring-indigo-500"
                                placeholder="여기에 CTRL+V로 붙여넣기..."
                            />
                            {pasteError && (
                                <div className="mt-2 text-sm text-rose-600 font-bold">{pasteError}</div>
                            )}
                        </div>

                        <div className="p-4 border-t border-slate-100 bg-slate-50 flex justify-end gap-2">
                            <button
                                type="button"
                                onClick={() => {
                                    setIsPasteModalOpen(false);
                                    setPasteError(null);
                                    setPasteText('');
                                }}
                                className="px-4 py-2 rounded-lg font-bold border border-slate-200 bg-white text-slate-700 hover:bg-slate-100"
                            >
                                취소
                            </button>
                            <button
                                type="button"
                                onClick={handlePasteConfirm}
                                className="px-4 py-2 rounded-lg font-bold border border-indigo-600 bg-indigo-600 text-white hover:bg-indigo-700"
                            >
                                저장
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default FirestoreStructureViewer;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { manpowerService, Worker } from '../../services/manpowerService';
import { teamService, Team } from '../../services/teamService';
import { siteService, Site } from '../../services/siteService';
import { companyService, Company } from '../../services/companyService';
import { dailyReportService, DailyReport } from '../../services/dailyReportService';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faDatabase, faUsers, faBuilding, faHardHat, faCalendar, faChartBar,
    faExclamationTriangle, faUserSlash, faIdBadge, faCreditCard, faChevronDown, faChevronUp, faLink, faUserClock,
    faUserXmark, faStoreSlash
} from '@fortawesome/free-solid-svg-icons';

// Sub-components
import WorkerDatabase from './WorkerDatabase';
import TeamDatabase from './TeamDatabase';
import SiteDatabase from './SiteDatabase';
import CompanyDatabase from './CompanyDatabase';
import AccountManagementPage from './AccountManagementPage';

interface DatabaseStats {
    workers: {
        total: number;
        active: number;
        inactive: number;
        unassigned: number;
    };
    teams: {
        total: number;
        active: number;
        inactive: number;
    };
    sites: {
        total: number;
        active: number;
        completed: number;
    };
    companies: {
        total: number;
        contractor: number; // 시공팀
        partner: number;
        builder: number; // 건설사
    };
    accounts: {
        workerMissing: number;
        teamMissing: number;
        companyMissing: number;
    };
    reports: {
        total: number;
        thisMonth: number;
        today: number;
    };
}

interface IssueStats {
    unassignedWorkers: Worker[];
    noIdCardWorkers: Worker[];
    noAccountWorkers: Worker[];
    unassignedSites: Site[];
    unassignedBuilders: Company[];
    unassignedTeamLeaders: Worker[];
    isolatedWorkers: Worker[];
    duplicateWorkers: { list: Worker[], label: string }[]; // Groups of duplicates
    ghostWorkers: Worker[]; // Active but no work in 30 days
    retiredWorkers: Worker[];
    closedTeams: Team[];
}

function IntegratedDatabase() {
    const [loading, setLoading] = useState(false);
    const [activeTab, setActiveTab] = useState<'overview' | 'workers' | 'teams' | 'sites' | 'companies' | 'accounts' | 'reports'>('overview');

    // Stats State
    const [stats, setStats] = useState<DatabaseStats>({
        workers: { total: 0, active: 0, inactive: 0, unassigned: 0 },
        teams: { total: 0, active: 0, inactive: 0 },
        sites: { total: 0, active: 0, completed: 0 },
        companies: { total: 0, contractor: 0, partner: 0, builder: 0 },
        accounts: { workerMissing: 0, teamMissing: 0, companyMissing: 0 },
        reports: { total: 0, thisMonth: 0, today: 0 }
    });

    // Issue State
    const [issues, setIssues] = useState<IssueStats>({
        unassignedWorkers: [],
        noIdCardWorkers: [],
        noAccountWorkers: [],
        unassignedSites: [],
        unassignedBuilders: [],
        unassignedTeamLeaders: [],
        isolatedWorkers: [],
        duplicateWorkers: [],
        ghostWorkers: [],
        retiredWorkers: [],
        closedTeams: []
    });

    const [expandedIssue, setExpandedIssue] = useState<keyof IssueStats | null>(null);
    const [highlightedId, setHighlightedId] = useState<string | null>(null);

    const loadStats = async () => {
        setLoading(true);
        try {
            // Calculate date range for Ghost Worker check (last 30 days)
            const endDate = new Date();
            const startDate = new Date();
            startDate.setDate(startDate.getDate() - 30);

            const startDateStr = startDate.toISOString().split('T')[0];
            const endDateStr = endDate.toISOString().split('T')[0];

            // Parallel Fetch: Replaced getAllReports with getDBStats
            const [workersData, teamsData, sitesData, companiesData, reportStats, recentReports] = await Promise.all([
                manpowerService.getWorkers(),
                teamService.getTeams(),
                siteService.getSites(),
                companyService.getCompanies(),
                dailyReportService.getDBStats(), // Optimized: Count only
                dailyReportService.getReports({ startDate: startDateStr, endDate: endDateStr })
            ]);

            calculateStats(workersData, teamsData, sitesData, companiesData, reportStats);
            calculateIssues(workersData, teamsData, sitesData, companiesData, recentReports);
        } catch (error) {
            console.error('Failed to load stats:', error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        loadStats();
    }, []);


    const calculateStats = (
        workers: Worker[],
        teams: Team[],
        sites: Site[],
        companies: Company[],
        reportStats: { total: number; thisMonth: number; today: number }
    ) => {
        setStats({
            workers: {
                total: workers.length,
                active: workers.filter(w => w.status === '재직').length,
                inactive: workers.filter(w => w.status === '퇴사' || w.status === '휴직').length,
                unassigned: workers.filter(w => !w.teamId).length
            },
            teams: {
                total: teams.length,
                active: teams.filter(t => t.status === 'active' || !t.status).length,
                inactive: teams.filter(t => t.status === 'waiting' || t.status === 'closed').length
            },
            sites: {
                total: sites.length,
                active: sites.filter(s => s.status === 'active').length,
                completed: sites.filter(s => s.status === 'completed').length
            },
            companies: {
                total: companies.length,
                contractor: companies.filter(c => c.type === '시공사').length,
                partner: companies.filter(c => c.type === '협력사').length,
                builder: companies.filter(c => c.type === '건설사').length
            },
            accounts: {
                workerMissing: workers.filter(w => !w.accountNumber).length,
                teamMissing: teams.filter(t => !t.accountNumber).length,
                companyMissing: companies.filter(c => !c.accountNumber).length,
            },
            reports: reportStats // Use pre-calculated stats directly
        });
    };

    const calculateIssues = (workers: Worker[], teams: Team[], sites: Site[], companies: Company[], recentReports: DailyReport[]) => {
        const newIssues: IssueStats = {
            unassignedWorkers: [],
            noIdCardWorkers: [],
            noAccountWorkers: [],
            unassignedSites: [],
            unassignedBuilders: [],
            unassignedTeamLeaders: [],
            isolatedWorkers: [],
            duplicateWorkers: [],
            ghostWorkers: [],
            retiredWorkers: workers.filter(w => w.status === '퇴사'),
            closedTeams: teams.filter(t => t.status === 'closed' || t.status === 'waiting')
        };

        // Helper sets
        const activeTeamLeaderIds = new Set(teams.map(t => t.leaderId).filter(Boolean));
        const recentWorkerIds = new Set<string>();
        recentReports.forEach(r => {
            r.workers.forEach(w => {
                if (w.manDay > 0) recentWorkerIds.add(w.workerId);
            });
        });

        // Worker Checks
        workers.forEach(w => {
            // Unassigned (No Team)
            if (!w.teamId) newIssues.unassignedWorkers.push(w);

            // Missing Info
            if (!w.fileNameSaved) newIssues.noIdCardWorkers.push(w);
            if (!w.accountNumber) newIssues.noAccountWorkers.push(w);

            // Unassigned Team Leader
            if (w.role === '팀장' && !activeTeamLeaderIds.has(w.id || '')) {
                newIssues.unassignedTeamLeaders.push(w);
            }

            // Isolated
            if (!w.teamId && !w.siteId && !w.companyId) {
                newIssues.isolatedWorkers.push(w);
            }

            // Ghost Worker (Active but no work in 30 days)
            if (w.status === '재직' && !recentWorkerIds.has(w.id || '')) {
                newIssues.ghostWorkers.push(w);
            }
        });

        // Sites Checks
        newIssues.unassignedSites = sites.filter(s => !s.responsibleTeamId);

        // Company Checks (Builders without any assigned sites via Site.companyId)
        newIssues.unassignedBuilders = companies.filter(c => {
            if (c.type !== '건설사') return false;
            const hasSite = sites.some(s => s.companyId === c.id);
            return !hasSite;
        });

        // Duplicate Functionality
        const idMap = new Map<string, Worker[]>();
        const phoneMap = new Map<string, Worker[]>();

        workers.forEach(w => {
            if (w.idNumber) {
                const list = idMap.get(w.idNumber) || [];
                list.push(w);
                idMap.set(w.idNumber, list);
            }
            if (w.contact) {
                const list = phoneMap.get(w.contact) || [];
                list.push(w);
                phoneMap.set(w.contact, list);
            }
        });

        idMap.forEach((list, key) => {
            if (list.length > 1) newIssues.duplicateWorkers.push({ list, label: `주민번호 중복: ${key}` });
        });
        phoneMap.forEach((list, key) => {
            // Only add if not already added by ID number to avoid noise
            const isAlreadyAdded = newIssues.duplicateWorkers.some(d => d.label.includes(key));
            if (!isAlreadyAdded && list.length > 1) newIssues.duplicateWorkers.push({ list, label: `연락처 중복: ${key}` });
        });

        setIssues(newIssues);
    };

    const toggleIssue = (issueKey: keyof IssueStats) => {
        if (expandedIssue === issueKey) {
            setExpandedIssue(null);
        } else {
            setExpandedIssue(issueKey);
        }
    };

    const renderIssueCard = (
        key: keyof IssueStats,
        title: string,
        count: number,
        icon: any,
        colorClass: string,
        unit: string = '명'
    ) => {


        const isSelected = expandedIssue === key;

        return (
            <div
                onClick={() => toggleIssue(key)}
                className={`p-4 rounded-xl border cursor-pointer transition-all duration-200 relative overflow-hidden group
                    ${isSelected
                        ? 'bg-white border-slate-400 ring-2 ring-slate-200 shadow-md transform -translate-y-1'
                        : 'bg-white border-slate-200 hover:border-slate-300 hover:shadow-sm'
                    }
                `}
            >
                <div className={`absolute top-0 right-0 p-3 opacity-10 group-hover:opacity-20 transition-opacity ${colorClass}`}>
                    <FontAwesomeIcon icon={icon} className="text-4xl" />
                </div>

                <div className="flex items-center gap-2 mb-2">
                    <div className={`p-1.5 rounded-lg text-xs ${colorClass.replace('text-', 'bg-').replace('600', '50').replace('500', '50')} ${colorClass}`}>
                        <FontAwesomeIcon icon={icon} />
                    </div>
                    <span className="text-slate-600 font-bold text-sm">{title}</span>
                </div>

                <div className="flex items-end gap-1 relative z-10">
                    <span className={`text-2xl font-bold ${colorClass}`}>{count}</span>
                    <span className="text-xs text-slate-400 mb-1">{unit}</span>
                </div>

                <div className="mt-2 flex justify-between items-center text-xs text-slate-400">
                    <span>상세보기</span>
                    <FontAwesomeIcon icon={isSelected ? faChevronUp : faChevronDown} />
                </div>
            </div>
        );
    };

    return (
        <div className="bg-slate-50 min-h-screen pb-20">
            <div className="bg-white border-b border-slate-200">
                <div className="p-6">
                    <div className="flex justify-between items-center mb-6">
                        <div className="flex items-center gap-3">
                            <div className="bg-indigo-600 p-2 rounded-lg">
                                <FontAwesomeIcon icon={faDatabase} className="text-white text-xl" />
                            </div>
                            <h1 className="text-2xl font-bold text-slate-800">통합 데이터베이스</h1>
                        </div>
                    </div>

                    {/* Main Stats Cards */}
                    <div className="flex flex-wrap gap-4 mb-4">
                        <div className="flex-1 min-w-[200px] bg-white p-4 rounded-xl border border-slate-200 shadow-sm cursor-pointer hover:border-indigo-300 transition-colors" onClick={() => setActiveTab('workers')}>
                            <div className="flex items-center justify-between mb-2">
                                <span className="text-slate-500 font-medium text-sm">총 작업자</span>
                                <div className="p-1.5 bg-blue-50 text-blue-600 rounded-lg text-xs">
                                    <FontAwesomeIcon icon={faHardHat} />
                                </div>
                            </div>
                            <div className="flex items-end gap-2">
                                <h3 className="text-2xl font-bold text-slate-800">{stats.workers.total}</h3>
                                <span className="text-xs text-slate-500 mb-1">명</span>
                            </div>
                            <div className="mt-2 text-xs text-slate-400 flex justify-between">
                                <span>재직 {stats.workers.active}</span>
                                <span>미배정 {stats.workers.unassigned}</span>
                            </div>
                        </div>

                        <div className="flex-1 min-w-[200px] bg-white p-4 rounded-xl border border-slate-200 shadow-sm cursor-pointer hover:border-indigo-300 transition-colors" onClick={() => setActiveTab('teams')}>
                            <div className="flex items-center justify-between mb-2">
                                <span className="text-slate-500 font-medium text-sm">등록 팀</span>
                                <div className="p-1.5 bg-purple-50 text-purple-600 rounded-lg text-xs">
                                    <FontAwesomeIcon icon={faUsers} />
                                </div>
                            </div>
                            <div className="flex items-end gap-2">
                                <h3 className="text-2xl font-bold text-slate-800">{stats.teams.total}</h3>
                                <span className="text-xs text-slate-500 mb-1">팀</span>
                            </div>
                            <div className="mt-2 text-xs text-slate-400">
                                <span>협업 {stats.teams.active} · 대기/폐업 {stats.teams.inactive}</span>
                            </div>
                        </div>

                        <div className="flex-1 min-w-[200px] bg-white p-4 rounded-xl border border-slate-200 shadow-sm cursor-pointer hover:border-indigo-300 transition-colors" onClick={() => setActiveTab('sites')}>
                            <div className="flex items-center justify-between mb-2">
                                <span className="text-slate-500 font-medium text-sm">현장 현황</span>
                                <div className="p-1.5 bg-emerald-50 text-emerald-600 rounded-lg text-xs">
                                    <FontAwesomeIcon icon={faBuilding} />
                                </div>
                            </div>
                            <div className="flex items-end gap-2">
                                <h3 className="text-2xl font-bold text-slate-800">{stats.sites.total}</h3>
                                <span className="text-xs text-slate-500 mb-1">곳</span>
                            </div>
                            <div className="mt-2 text-xs text-slate-400">
                                <span>진행중 {stats.sites.active} · 종료 {stats.sites.completed}</span>
                            </div>
                        </div>

                        <div className="flex-1 min-w-[200px] bg-white p-4 rounded-xl border border-slate-200 shadow-sm cursor-pointer hover:border-indigo-300 transition-colors" onClick={() => setActiveTab('companies')}>
                            <div className="flex items-center justify-between mb-2">
                                <span className="text-slate-500 font-medium text-sm">거래처</span>
                                <div className="p-1.5 bg-orange-50 text-orange-600 rounded-lg text-xs">
                                    <FontAwesomeIcon icon={faBuilding} />
                                </div>
                            </div>
                            <div className="flex items-end gap-2">
                                <h3 className="text-2xl font-bold text-slate-800">{stats.companies.total}</h3>
                                <span className="text-xs text-slate-500 mb-1">개사</span>
                            </div>
                            <div className="mt-2 text-xs text-slate-400">
                                <span>시공사 {stats.companies.contractor} · 협력사 {stats.companies.partner} · 건설사 {stats.companies.builder}</span>
                            </div>
                        </div>

                        <div className="flex-1 min-w-[200px] bg-white p-4 rounded-xl border border-slate-200 shadow-sm cursor-pointer hover:border-indigo-300 transition-colors" onClick={() => setActiveTab('accounts')}>
                            <div className="flex items-center justify-between mb-2">
                                <span className="text-slate-500 font-medium text-sm">계좌 관리</span>
                                <div className="p-1.5 bg-rose-50 text-rose-600 rounded-lg text-xs">
                                    <FontAwesomeIcon icon={faCreditCard} />
                                </div>
                            </div>
                            <div className="flex items-end gap-2">
                                <h3 className="text-2xl font-bold text-slate-800">{stats.accounts.workerMissing + stats.accounts.teamMissing + stats.accounts.companyMissing}</h3>
                                <span className="text-xs text-slate-500 mb-1">건 누락</span>
                            </div>
                            <div className="mt-2 text-xs text-slate-400">
                                <span>작업자 {stats.accounts.workerMissing} · 팀 {stats.accounts.teamMissing} · 회사 {stats.accounts.companyMissing}</span>
                            </div>
                        </div>

                        <div className="flex-1 min-w-[200px] bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                            <div className="flex items-center justify-between mb-2">
                                <span className="text-slate-500 font-medium text-sm">일일 보고서</span>
                                <div className="p-1.5 bg-indigo-50 text-indigo-600 rounded-lg text-xs">
                                    <FontAwesomeIcon icon={faCalendar} />
                                </div>
                            </div>
                            <div className="flex items-end gap-2">
                                <h3 className="text-2xl font-bold text-slate-800">{stats.reports.total}</h3>
                                <span className="text-xs text-slate-500 mb-1">건</span>
                            </div>
                            <div className="mt-2 text-xs text-slate-400">
                                <span>금일 {stats.reports.today} · 이번달 {stats.reports.thisMonth}</span>
                            </div>
                        </div>
                    </div>

                    {/* Tabs */}
                    <div className="flex border-b border-slate-200 mt-8 overflow-x-auto">
                        <button
                            onClick={() => setActiveTab('overview')}
                            className={`px-6 py-4 text-sm font-medium whitespace-nowrap transition-colors ${activeTab === 'overview' ? 'text-indigo-600 border-b-2 border-indigo-600 bg-indigo-50/50' : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
                        >
                            데이터베이스 현황
                        </button>
                        <button
                            onClick={() => setActiveTab('workers')}
                            className={`px-6 py-4 text-sm font-medium whitespace-nowrap transition-colors ${activeTab === 'workers' ? 'text-indigo-600 border-b-2 border-indigo-600 bg-indigo-50/50' : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
                        >
                            작업자 목록
                        </button>
                        <button
                            onClick={() => setActiveTab('teams')}
                            className={`px-6 py-4 text-sm font-medium whitespace-nowrap transition-colors ${activeTab === 'teams' ? 'text-indigo-600 border-b-2 border-indigo-600 bg-indigo-50/50' : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
                        >
                            팀 목록
                        </button>
                        <button
                            onClick={() => setActiveTab('sites')}
                            className={`px-6 py-4 text-sm font-medium whitespace-nowrap transition-colors ${activeTab === 'sites' ? 'text-indigo-600 border-b-2 border-indigo-600 bg-indigo-50/50' : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
                        >
                            현장 목록
                        </button>
                        <button
                            onClick={() => setActiveTab('companies')}
                            className={`px-6 py-4 text-sm font-medium whitespace-nowrap transition-colors ${activeTab === 'companies' ? 'text-indigo-600 border-b-2 border-indigo-600 bg-indigo-50/50' : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
                        >
                            회사 목록
                        </button>
                        <button
                            onClick={() => setActiveTab('accounts')}
                            className={`px-6 py-4 text-sm font-medium whitespace-nowrap transition-colors ${activeTab === 'accounts' ? 'text-indigo-600 border-b-2 border-indigo-600 bg-indigo-50/50' : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
                        >
                            계좌 관리
                        </button>
                    </div>
                </div>

                <div className="p-6">
                    {activeTab === 'overview' && (
                        <div className="space-y-6">
                            {/* Data Integrity Board */}
                            <div className="bg-slate-50 rounded-2xl p-6 border border-slate-200">
                                <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
                                    <FontAwesomeIcon icon={faExclamationTriangle} className="text-amber-500" />
                                    데이터 무결성 현황 (Data Integrity)
                                </h3>
                                <div className="grid grid-cols-2 md:grid-cols-4 xl:grid-cols-8 gap-3">
                                    {renderIssueCard('unassignedWorkers', '미배정 작업자', issues.unassignedWorkers.length, faUserSlash, 'text-rose-500')}
                                    {renderIssueCard('noIdCardWorkers', '신분증 미등록', issues.noIdCardWorkers.length, faIdBadge, 'text-orange-500')}
                                    {renderIssueCard('noAccountWorkers', '계좌 미등록', issues.noAccountWorkers.length, faCreditCard, 'text-amber-600')}
                                    {renderIssueCard('unassignedSites', '미배정 현장', issues.unassignedSites.length, faBuilding, 'text-rose-500', '곳')}
                                    {renderIssueCard('unassignedBuilders', '미배정 건설사', issues.unassignedBuilders.length, faBuilding, 'text-orange-500', '개')}
                                    {renderIssueCard('unassignedTeamLeaders', '미배정 팀장', issues.unassignedTeamLeaders.length, faUserSlash, 'text-rose-600')}
                                    {renderIssueCard('isolatedWorkers', '고립된 작업자', issues.isolatedWorkers.length, faLink, 'text-slate-600')}
                                    {renderIssueCard('duplicateWorkers', '중복 데이터', issues.duplicateWorkers.length, faUsers, 'text-purple-600', '건')}
                                    {renderIssueCard('ghostWorkers', '유령 작업자', issues.ghostWorkers.length, faUserClock, 'text-slate-500')}
                                    {renderIssueCard('retiredWorkers', '퇴사자', issues.retiredWorkers.length, faUserXmark, 'text-slate-500')}
                                    {renderIssueCard('closedTeams', '폐업/대기 팀', issues.closedTeams.length, faStoreSlash, 'text-slate-500', '팀')}
                                </div>

                                {/* Accordion Detail View */}
                                {expandedIssue && (
                                    <div className="mt-4 bg-white rounded-xl border border-slate-200 shadow-sm animate-fade-in-down">
                                        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
                                            <h4 className="font-bold text-slate-700">
                                                {expandedIssue === 'unassignedWorkers' && '미배정 작업자 목록 (팀 정보 없음)'}
                                                {expandedIssue === 'noIdCardWorkers' && '신분증 미등록 작업자 목록'}
                                                {expandedIssue === 'noAccountWorkers' && '계좌번호 누락 작업자 목록'}
                                                {expandedIssue === 'unassignedSites' && '담당 팀이 없는 현장 목록'}
                                                {expandedIssue === 'unassignedBuilders' && '담당 현장이 없는 건설사 목록'}
                                                {expandedIssue === 'unassignedTeamLeaders' && '직책이 팀장이지만 팀을 맡고 있지 않은 인원'}
                                                {expandedIssue === 'isolatedWorkers' && '팀, 현장, 회사 어디에도 소속되지 않은 작업자'}
                                                {expandedIssue === 'duplicateWorkers' && '중복 의심 데이터 (주민번호/연락처)'}
                                                {expandedIssue === 'ghostWorkers' && '최근 30일간 작업 기록이 없는 재직자 (유령 작업자)'}
                                                {expandedIssue === 'retiredWorkers' && '퇴사자 목록 (히스토리)'}
                                                {expandedIssue === 'closedTeams' && '폐업 또는 대기 상태인 팀 목록'}
                                            </h4>
                                            <button onClick={() => setExpandedIssue(null)} className="text-slate-400 hover:text-slate-600">
                                                닫기
                                            </button>
                                        </div>
                                        <div className="p-4 max-h-96 overflow-y-auto">
                                            {/* Worker Lists */}
                                            {['unassignedWorkers', 'noIdCardWorkers', 'noAccountWorkers', 'unassignedTeamLeaders', 'isolatedWorkers', 'ghostWorkers', 'retiredWorkers'].includes(expandedIssue) && (
                                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2">
                                                    {(issues[expandedIssue as keyof IssueStats] as Worker[])?.map((worker) => (
                                                        <div key={worker.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-lg border border-slate-100">
                                                            <div>
                                                                <div className="font-bold text-slate-800">{worker.name}</div>
                                                                <div className="text-xs text-slate-500">{worker.idNumber} / {worker.role}</div>
                                                            </div>
                                                            <button
                                                                onClick={() => {
                                                                    setActiveTab('workers');
                                                                    setHighlightedId(worker.id || null);
                                                                }}
                                                                className="text-xs text-indigo-600 hover:underline"
                                                            >
                                                                관리
                                                            </button>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}

                                            {/* Site List */}
                                            {expandedIssue === 'unassignedSites' && (
                                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2">
                                                    {(issues.unassignedSites).map((site) => (
                                                        <div key={site.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-lg border border-slate-100">
                                                            <div>
                                                                <div className="font-bold text-slate-800">{site.name}</div>
                                                                <div className="text-xs text-slate-500">{site.code}</div>
                                                            </div>
                                                            <button onClick={() => { setActiveTab('sites'); setHighlightedId(site.id || null); }} className="text-xs text-indigo-600 hover:underline">관리</button>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}

                                            {/* Company List */}
                                            {expandedIssue === 'unassignedBuilders' && (
                                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2">
                                                    {(issues.unassignedBuilders).map((comp) => (
                                                        <div key={comp.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-lg border border-slate-100">
                                                            <div>
                                                                <div className="font-bold text-slate-800">{comp.name}</div>
                                                                <div className="text-xs text-slate-500">{comp.ceoName}</div>
                                                            </div>
                                                            <button onClick={() => { setActiveTab('companies'); setHighlightedId(comp.id || null); }} className="text-xs text-indigo-600 hover:underline">관리</button>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}

                                            {/* Closed Teams List */}
                                            {expandedIssue === 'closedTeams' && (
                                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2">
                                                    {(issues.closedTeams).map((team) => (
                                                        <div key={team.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-lg border border-slate-100">
                                                            <div>
                                                                <div className="font-bold text-slate-800">{team.name}</div>
                                                                <div className="text-xs text-slate-500">{team.leaderName} / {team.status === 'closed' ? '폐업' : '대기'}</div>
                                                            </div>
                                                            <button onClick={() => { setActiveTab('teams'); setHighlightedId(team.id || null); }} className="text-xs text-indigo-600 hover:underline">관리</button>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}

                                            {/* Duplicate List */}
                                            {expandedIssue === 'duplicateWorkers' && (
                                                <div className="space-y-3">
                                                    {issues.duplicateWorkers.map((group, idx) => (
                                                        <div key={idx} className="bg-slate-50 p-3 rounded-lg border border-slate-200">
                                                            <div className="text-sm font-bold text-rose-600 mb-2">{group.label} ({group.list.length}명)</div>
                                                            <div className="flex flex-wrap gap-2">
                                                                {group.list.map(w => (
                                                                    <div key={w.id} className="bg-white px-3 py-1.5 rounded border border-slate-300 text-sm">
                                                                        {w.name} <span className="text-slate-400 text-xs">({w.status})</span>
                                                                    </div>
                                                                ))}
                                                            </div>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>
                    )}

                    {activeTab === 'workers' && (
                        <WorkerDatabase hideHeader={true} highlightedId={highlightedId} />
                    )}
                    {activeTab === 'teams' && (
                        <TeamDatabase hideHeader={false} highlightedId={highlightedId} />
                    )}
                    {activeTab === 'sites' && (
                        <SiteDatabase hideHeader={true} highlightedId={highlightedId} />
                    )}
                    {activeTab === 'companies' && (
                        <CompanyDatabase
                            hideHeader={false}
                            highlightedId={highlightedId}
                            entityLabel="회사"
                            defaultType="미지정"
                        />
                    )}
                    {activeTab === 'accounts' && (
                        <AccountManagementPage embedded={true} />
                    )}
                </div>
            </div>
        </div>
    );
}

export default IntegratedDatabase;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faSearch, faFilter, faDownload, faPenToSquare, faPlus, faTable, faTrash,
    faChevronDown, faChevronRight, faBuilding, faMapMarkerAlt, faTimes, faUsers, faHardHat,
    faBriefcase, faHandshake, faFileInvoiceDollar, faUserTie, faShieldHalved, faExclamationTriangle
} from '@fortawesome/free-solid-svg-icons';
import { siteService, Site } from '../../services/siteService';
import { Team } from '../../services/teamService';
import { Company } from '../../services/companyService';
import { manpowerService } from '../../services/manpowerService';
import { dailyReportService } from '../../services/dailyReportService';
import { statisticsService } from '../../services/statisticsService';
import SiteForm from '../../components/manpower/SiteForm';
import { Timestamp } from '../../types/timestamp';
import { useColumnSettings } from '../../hooks/useColumnSettings';
import { useMasterData } from '../../contexts/MasterDataContext';
import SingleSelectPopover, { InputPopover } from '../../components/common/SingleSelectPopover';
import { useAuth } from '../../contexts/AuthContext';
import { userService } from '../../services/userService';
import { useNavigate } from 'react-router-dom';

const SITE_COLUMNS = [
    { key: 'name', label: '현장명' },
    { key: 'address', label: '주소' },
    { key: 'responsibleTeamName', label: '담당팀' },
    { key: 'clientCompanyName', label: '발주사' },
    { key: 'companyName', label: '시공사' },
    { key: 'partnerName', label: '협력사' },
    { key: 'siteType', label: '현장구분' },
    { key: 'paymentMethod', label: '결제구분' },
    { key: 'status', label: '상태' }
];

interface SiteDatabaseProps {
    hideHeader?: boolean;
    highlightedId?: string | null;
}

interface SiteHistoryData {
    teams: { id: string; name: string; lastDate: string; totalManDay: number }[];
    workers: { id: string; name: string; role: string; lastDate: string; totalManDay: number }[];
}

const SiteDatabase: React.FC<SiteDatabaseProps> = ({ hideHeader = false, highlightedId }) => {
    // Context & Auth
    const { companies, teams, sites, refreshSites } = useMasterData();
    const { currentUser } = useAuth();
    const navigate = useNavigate();

    // Permission State
    const [isRestricted, setIsRestricted] = useState<boolean | null>(null);
    const [userData, setUserData] = useState<any>(null);

    const companyUuidByAnyId = useMemo(() => {
        const map = new Map<string, string>();
        companies.forEach(c => {
            if (c.id) map.set(String(c.id), String(c.id));
            if (c.legacyId) map.set(String(c.legacyId), String(c.id));
        });
        return map;
    }, [companies]);

    const getFilteredTeamsForSite = (site: Site): Team[] => {
        const rawCompanyId = site.companyId ? String(site.companyId).trim() : '';
        const targetCompanyId = rawCompanyId ? (companyUuidByAnyId.get(rawCompanyId) ?? rawCompanyId) : '';

        const constructorCompanyIds = new Set(
            companies
                .filter((company) => {
                    const type = String(company.type ?? '').trim();
                    return type === '시공사' || type === '미지정';
                })
                .map((company) => String(company.id ?? '').trim())
                .filter(Boolean)
        );

        const constructorTeams = teams.filter((team) => {
            const teamCompanyIdRaw = team.companyId ? String(team.companyId).trim() : '';
            if (!teamCompanyIdRaw) return false;
            const teamCompanyId = companyUuidByAnyId.get(teamCompanyIdRaw) ?? teamCompanyIdRaw;
            return constructorCompanyIds.has(teamCompanyId);
        });

        if (!targetCompanyId) return constructorTeams;

        return constructorTeams.filter((team) => {
            const teamCompanyIdRaw = team.companyId ? String(team.companyId).trim() : '';
            if (!teamCompanyIdRaw) return false;
            const teamCompanyId = companyUuidByAnyId.get(teamCompanyIdRaw) ?? teamCompanyIdRaw;
            return teamCompanyId === targetCompanyId;
        });
    };

    const [siteStats, setSiteStats] = useState<{ [id: string]: number }>({});
    const [loading, setLoading] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [showInactive, setShowInactive] = useState(false);
    const [isStickyHeader, setIsStickyHeader] = useState(false);

    // Selection & Edit State
    const [selectedSiteIds, setSelectedSiteIds] = useState<string[]>([]);
    const [isEditMode, setIsEditMode] = useState(false);
    const [showSiteModal, setShowSiteModal] = useState(false);
    const [editingSite, setEditingSite] = useState<Site | null>(null);

    // Accordion State
    const [expandedSiteId, setExpandedSiteId] = useState<string | null>(null);
    const [historyLoading, setHistoryLoading] = useState(false);
    const [siteHistory, setSiteHistory] = useState<SiteHistoryData | null>(null);

    // Highlight scroll control
    const highlightScrolledRef = useRef(false);
    const lastHighlightIdRef = useRef<string | null>(null);

    // Column Settings Hook
    const {
        visibleColumns,
        toggleColumn,
        showColumnSettings,
        setShowColumnSettings
    } = useColumnSettings('site_db_v5', SITE_COLUMNS);

    useEffect(() => {
        const checkPermission = async () => {
            if (!currentUser) return;
            try {
                const user = await userService.getUser(currentUser.uid);
                setUserData(user);
                
                // 청연 소속이며 admin/사장이 아닌 경우 제한
                const isCheongyeon = user?.department?.includes('청연');
                const isAdmin = user?.role === 'admin' || user?.role === '사장';
                
                if (isCheongyeon && !isAdmin) {
                    setIsRestricted(true);
                } else {
                    setIsRestricted(false);
                }
            } catch (error) {
                console.error("Error checking permission:", error);
                setIsRestricted(false);
            }
        };
        checkPermission();
    }, [currentUser]);

    const loadStats = async () => {
        setLoading(true);
        try {
            const statsData = await statisticsService.getCumulativeManpower();
            setSiteStats(statsData.siteStats);
        } catch (error) {
            console.error("Failed to load stats:", error);
        } finally {
            setLoading(false);
        }
    };

    // 통계 데이터 로드
    useEffect(() => {
        loadStats();
    }, []);

    if (isRestricted === true) {
        return (
            <div style={{ 
                height: '80vh', 
                display: 'flex', 
                flexDirection: 'column', 
                alignItems: 'center', 
                justifyContent: 'center',
                gap: '20px',
                color: '#64748b'
            }}>
                <div style={{ display: 'flex', position: 'relative' }}>
                    <FontAwesomeIcon icon={faShieldHalved} size="4x" style={{ color: '#cbd5e1' }} />
                    <FontAwesomeIcon icon={faExclamationTriangle} size="2x" style={{ 
                        color: '#ef4444', 
                        position: 'absolute',
                        bottom: '-5px',
                        right: '-5px'
                    }} />
                </div>
                <h2 style={{ color: '#1e293b' }}>접근 권한이 없습니다</h2>
                <p>현장 데이터베이스 관리 권한이 없습니다. 관리자에게 문의하세요.</p>
                <button 
                    onClick={() => navigate('/site/management')}
                    style={{
                        padding: '10px 20px',
                        backgroundColor: '#3b82f6',
                        color: 'white',
                        border: 'none',
                        borderRadius: '6px',
                        cursor: 'pointer',
                        fontWeight: 'bold'
                    }}
                >
                    현장 관리 페이지로 이동
                </button>
            </div>
        );
    }

    if (isRestricted === null) {
        return <div style={{ padding: '20px', textAlign: 'center' }}>권한 확인 중...</div>;
    }




    const renderCellValue = (site: Site, column: any) => {
        const value = site[column.key as keyof Site];

        if (column.key === 'totalGongsu') {
            // Try matching by ID first, then Name
            const gongsu = siteStats[site.id!] || siteStats[site.name] || 0;
            return (
                <span className="font-bold text-blue-600">
                    {gongsu.toFixed(1)}공수
                </span>
            );
        }

        if (column.key === 'status') {
            return (
                <span className={`px-2 py-0.5 rounded text-xs font-bold ${site.status === 'completed' ? 'bg-slate-100 text-slate-500' : 'bg-green-100 text-green-600'}`}>
                    {site.status === 'completed' ? '종료' : '진행중'}
                </span>
            );
        }

        if (value === undefined || value === null) return '';
        if (typeof value === 'object' && 'toDate' in value) {
            return (value as any).toDate().toLocaleDateString();
        }
        if (typeof value === 'object') return JSON.stringify(value);
        return String(value);
    };

    const toggleSelectAll = () => {
        if (selectedSiteIds.length === sites.length) setSelectedSiteIds([]);
        else setSelectedSiteIds(sites.map(s => s.id!).filter(Boolean));
    };

    const toggleSelect = (id: string) => {
        setSelectedSiteIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
    };

    const handleBulkDelete = async () => {
        if (selectedSiteIds.length === 0) return;
        if (!window.confirm(`${selectedSiteIds.length}개의 현장을 삭제 하시겠습니까?`)) return;

        try {
            setLoading(true);
            await Promise.all(selectedSiteIds.map(id => siteService.deleteSite(id)));
            await refreshSites(); // Context 새로고침
            setSelectedSiteIds([]);
            alert('삭제되었습니다.');
        } catch (error) {
            console.error("Bulk delete failed:", error);
            alert('삭제 중 오류가 발생했습니다.');
        } finally {
            setLoading(false);
        }
    };

    const handleSiteChange = async (id: string, field: keyof Site, value: any) => {
        // Context 데이터는 불변이므로 직접 수정하지 않고 DB만 업데이트
        try {
            await siteService.updateSite(id, { [field]: value });
        } catch (error) {
            console.error("Failed to update site", error);
        }
    };

    const handleSiteBlur = async (id: string, field: keyof Site, value: any) => {
        try {
            await siteService.updateSite(id, { [field]: value });
            if (field === 'name') {
                await manpowerService.updateWorkersSiteName(id, value);
            }
            await refreshSites(); // Context 새로고침
        } catch (error) {
            console.error("Failed to update site", error);
            await refreshSites();
        }
    };

    const handleSiteSelectChange = async (id: string, updates: Partial<Site>) => {
        try {
            await siteService.updateSite(id, updates);
            await refreshSites(); // Context 새로고침
        } catch (error) {
            console.error("Failed to update site select", error);
            await refreshSites();
        }
    };

    const handleSiteSave = async () => {
        await refreshSites(); // Context 새로고침
        setShowSiteModal(false);
        setEditingSite(null);
        alert('현장 정보가 저장되었습니다.');
    };



    const toggleExpand = async (siteId: string) => {
        if (expandedSiteId === siteId) {
            setExpandedSiteId(null);
            setSiteHistory(null);
            return;
        }

        setExpandedSiteId(siteId);
        setHistoryLoading(true);
        setSiteHistory(null);

        try {
            const reports = await dailyReportService.getReportsBySite(siteId);

            // Aggregate Data
            const teamMap = new Map<string, { name: string; lastDate: string; totalManDay: number }>();
            const workerMap = new Map<string, { name: string; role: string; lastDate: string; totalManDay: number }>();

            reports.forEach(report => {
                // Team Aggregation
                if (report.teamId) {
                    const existing = teamMap.get(report.teamId);
                    const currentTotal = existing ? existing.totalManDay : 0;
                    const newTotal = currentTotal + (report.totalManDay || 0);

                    if (!existing) {
                        teamMap.set(report.teamId, {
                            name: report.teamName || '',
                            lastDate: report.date,
                            totalManDay: newTotal
                        });
                    } else {
                        teamMap.set(report.teamId, {
                            ...existing,
                            totalManDay: newTotal
                        });
                    }
                }

                // Worker Aggregation
                report.workers.forEach(worker => {
                    const existing = workerMap.get(worker.workerId);
                    const currentTotal = existing ? existing.totalManDay : 0;
                    const newTotal = currentTotal + (worker.manDay || 0);

                    if (!existing) {
                        workerMap.set(worker.workerId, {
                            name: worker.name,
                            role: worker.role || '작업자',
                            lastDate: report.date,
                            totalManDay: newTotal
                        });
                    } else {
                        workerMap.set(worker.workerId, {
                            ...existing,
                            totalManDay: newTotal
                        });
                    }
                });
            });

            const teamsArr = Array.from(teamMap.entries())
                .map(([id, data]) => ({ id, ...data }))
                .filter(t => t.totalManDay > 0);

            const workersArr = Array.from(workerMap.entries())
                .map(([id, data]) => ({ id, ...data }))
                .filter(w => w.totalManDay > 0);

            setSiteHistory({
                teams: teamsArr,
                workers: workersArr
            });

        } catch (error) {
            console.error("Failed to fetch site history:", error);
            alert("히스토리 불러오기 실패");
        } finally {
            setHistoryLoading(false);
        }
    };

    // Filter Logic
    const filteredSites = sites.filter(site => {
        // Status Filter
        if (!showInactive && site.status === 'completed') return false;

        // Search Filter
        if (searchTerm) {
            const searchLower = searchTerm.toLowerCase();
            return (
                site.name.toLowerCase().includes(searchLower) ||
                site.address?.toLowerCase().includes(searchLower) ||
                site.companyName?.toLowerCase().includes(searchLower)
            );
        }
        return true;
    });

    return (
        <div className="flex flex-col h-full bg-slate-50">
            {/* Header & Toolbar */}
            <div className={`bg-white border-b border-slate-200 p-4 flex flex-col xl:flex-row items-start xl:items-center justify-between gap-4 flex-shrink-0 ${!hideHeader ? 'border-t-0' : ''}`}>
                {!hideHeader && (
                    <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2 whitespace-nowrap">
                        <FontAwesomeIcon icon={faMapMarkerAlt} className="text-emerald-600" />
                        <span>현장 등록 관리</span>
                    </h2>
                )}

                <div className="flex flex-wrap items-center gap-2 w-full xl:w-auto xl:ml-auto justify-end">
                    <button
                        onClick={handleBulkDelete}
                        disabled={selectedSiteIds.length === 0}
                        className={`px-3 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 whitespace-nowrap ${selectedSiteIds.length > 0 ? 'bg-red-50 text-red-600 hover:bg-red-100' : 'bg-slate-100 text-slate-400 cursor-not-allowed'}`}
                    >
                        <FontAwesomeIcon icon={faTrash} /> <span className="hidden sm:inline">삭제</span>
                    </button>

                    <button onClick={() => setIsEditMode(!isEditMode)} className={`px-3 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 whitespace-nowrap ${isEditMode ? 'bg-indigo-50 text-indigo-600' : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
                        <FontAwesomeIcon icon={faPenToSquare} /> <span className="hidden sm:inline">{isEditMode ? '수정 종료' : '수정모드'}</span>
                    </button>

                    <div className="relative">
                        <button
                            onClick={() => setShowColumnSettings(!showColumnSettings)}
                            className="px-3 py-2 bg-white border border-slate-200 text-slate-600 rounded-lg hover:bg-slate-50 transition-colors flex items-center gap-2 text-sm font-medium whitespace-nowrap"
                        >
                            <FontAwesomeIcon icon={faTable} /> <span className="hidden sm:inline">열 설정</span>
                        </button>
                        {showColumnSettings && (
                            <div className="absolute top-full right-0 mt-2 w-48 bg-white rounded-lg shadow-xl border border-slate-200 z-50 p-2 text-left">
                                <div className="text-xs font-bold text-slate-500 mb-2 px-2">표시할 열 선택</div>
                                <div className="space-y-1">
                                    {SITE_COLUMNS.map(col => (
                                        <label key={col.key} className="flex items-center gap-2 px-2 py-1.5 hover:bg-slate-50 rounded cursor-pointer">
                                            <input
                                                type="checkbox"
                                                checked={visibleColumns.includes(col.key)}
                                                onChange={() => toggleColumn(col.key)}
                                                className="rounded text-indigo-600 focus:ring-indigo-500"
                                            />
                                            <span className="text-sm text-slate-700">{col.label}</span>
                                        </label>
                                    ))}
                                </div>
                                <div className="fixed inset-0 -z-10" onClick={() => setShowColumnSettings(false)}></div>
                            </div>
                        )}
                    </div>

                    <button onClick={() => setShowSiteModal(true)} className="px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm font-medium hover:bg-indigo-700 transition-colors flex items-center gap-2 shadow-sm whitespace-nowrap">
                        <FontAwesomeIcon icon={faPlus} /> <span className="hidden sm:inline">현장 등록</span>
                    </button>
                </div>
            </div>

            {/* Table */}
            <div className={`flex-1 overflow-auto ${!hideHeader ? 'p-6 pb-[400px]' : 'pb-[400px]'}`}>
                <div className="bg-white rounded-lg border border-slate-200 overflow-hidden shadow-sm">
                    <div className="p-4 border-b border-gray-200 flex items-center justify-between">
                        <h3 className="text-md font-semibold text-gray-800 flex items-center gap-2">
                            <FontAwesomeIcon icon={faMapMarkerAlt} className="text-emerald-600" />
                            등록된 현장 ({filteredSites.length}개)
                        </h3>
                        <div className="flex items-center gap-4">
                            <label className="flex items-center gap-2 text-sm text-gray-600 cursor-pointer">
                                <input
                                    type="checkbox"
                                    checked={showInactive}
                                    onChange={(e) => setShowInactive(e.target.checked)}
                                    className="rounded text-indigo-600 focus:ring-indigo-500"
                                />
                                마감현장 포함
                            </label>
                            <label className="flex items-center gap-2 text-sm text-gray-600 cursor-pointer">
                                <input
                                    type="checkbox"
                                    checked={isStickyHeader}
                                    onChange={(e) => setIsStickyHeader(e.target.checked)}
                                    className="rounded text-indigo-600 focus:ring-indigo-500"
                                />
                                목록 고정
                            </label>
                            <div className="flex items-center gap-2">
                                <FontAwesomeIcon icon={faSearch} className="text-gray-400" />
                                <input
                                    type="text"
                                    placeholder="현장명, 주소, 회사 검색"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="border-none focus:ring-0 text-sm text-gray-600 w-48 placeholder-gray-400"
                                />
                            </div>
                        </div>
                    </div>

                    <div className={`${isStickyHeader ? 'overflow-auto h-[calc(100vh-300px)]' : 'overflow-x-auto'}`}>
                        <table className="min-w-full divide-y divide-slate-200 text-sm">
                            <thead className={`bg-slate-900 text-white ${isStickyHeader ? 'sticky top-0 z-10' : ''}`}>
                                <tr>
                                    <th className="px-6 py-3 w-10 border border-slate-700">
                                        <input
                                            type="checkbox"
                                            checked={filteredSites.length > 0 && selectedSiteIds.length === filteredSites.length}
                                            onChange={toggleSelectAll}
                                            className="rounded text-indigo-600 focus:ring-indigo-500"
                                        />
                                    </th>
                                    <th className="px-2 py-3 w-8 border border-slate-700"></th>
                                    {SITE_COLUMNS.filter(col => visibleColumns.includes(col.key)).map(col => (
                                        <th key={col.key} className="px-6 py-3 font-semibold text-left text-white whitespace-nowrap border border-slate-700">
                                            {col.label}
                                        </th>
                                    ))}
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 bg-white">
                                {filteredSites.length > 0 ? (
                                    filteredSites.map((site) => {
                                        const isHighlighted = site.id === highlightedId;

                                        const responsibleTeam = site.responsibleTeamId
                                            ? teams.find(t => t.id === site.responsibleTeamId)
                                            : undefined;
                                        const responsibleTeamColor = responsibleTeam?.color || '#6366f1';

                                        const siteCompany = site.companyId
                                            ? companies.find(c => c.id === site.companyId)
                                            : undefined;
                                        const siteCompanyColor = siteCompany?.color || '#e5e7eb';

                                        return (
                                            <React.Fragment key={site.id || site.name}>
                                                <tr
                                                    className={`transition-colors border-b ${isHighlighted
                                                        ? 'bg-red-50 border border-red-300 ring-1 ring-red-300 z-10 relative'
                                                        : expandedSiteId === site.id
                                                            ? 'bg-slate-50'
                                                            : 'bg-white hover:bg-slate-50'
                                                        }`}
                                                >
                                                    <td className="px-6 py-4 align-top border border-slate-200">
                                                        <input
                                                            type="checkbox"
                                                            checked={!!site.id && selectedSiteIds.includes(site.id)}
                                                            onChange={() => site.id && toggleSelect(site.id)}
                                                            className="rounded text-indigo-600 focus:ring-indigo-500"
                                                        />
                                                    </td>
                                                    <td
                                                        className="px-2 py-4 text-center align-top cursor-pointer"
                                                        onClick={() => site.id && toggleExpand(site.id)}
                                                    >
                                                        {site.id && (
                                                            <FontAwesomeIcon
                                                                icon={expandedSiteId === site.id ? faChevronDown : faChevronRight}
                                                                className="text-slate-400 hover:text-indigo-600 transition-colors"
                                                            />
                                                        )}
                                                    </td>
                                                    {SITE_COLUMNS.filter(col => visibleColumns.includes(col.key)).map(col => (
                                                        <td key={`${site.id || site.name}-${col.key}`} className="px-6 py-4 align-top border border-slate-200">
                                                            {isEditMode && site.id ? (
                                                                col.key === 'status' ? (
                                                                    <select
                                                                        value={site.status}
                                                                        onChange={(e) => handleSiteSelectChange(site.id!, { status: e.target.value as Site['status'] })}
                                                                        className="border rounded px-2 py-1 w-full text-sm"
                                                                    >
                                                                        <option value="planned">예정</option>
                                                                        <option value="active">진행중</option>
                                                                        <option value="completed">종료</option>
                                                                    </select>
                                                                ) : col.key === 'responsibleTeamName' ? (
                                                                    <SingleSelectPopover
                                                                        options={getFilteredTeamsForSite(site).map(t => ({
                                                                            id: t.id || '',
                                                                            name: t.name,
                                                                            icon: (
                                                                                <span
                                                                                    className="inline-flex items-center justify-center w-4 h-4 rounded-full border border-slate-200 flex-shrink-0"
                                                                                    style={{ backgroundColor: t.color || '#6366f1' }}
                                                                                >
                                                                                    <FontAwesomeIcon icon={faUsers} className="text-white text-[8px]" />
                                                                                </span>
                                                                            )
                                                                        }))}
                                                                        selectedId={site.responsibleTeamId || null}
                                                                        onSelect={(id) => {
                                                                            const team = teams.find(t => t.id === id);
                                                                            handleSiteSelectChange(site.id!, {
                                                                                responsibleTeamId: id,
                                                                                responsibleTeamName: team?.name || ''
                                                                            });
                                                                        }}
                                                                        placeholder="담당팀 선택"
                                                                    />
                                                                ) : col.key === 'clientCompanyName' ? (
                                                                    <select
                                                                        value={site.clientCompanyId || ''}
                                                                        onChange={(e) => {
                                                                            const companyId = e.target.value;
                                                                            const company = companies.find(c => c.id === companyId);
                                                                            handleSiteSelectChange(site.id!, {
                                                                                clientCompanyId: companyId || '',
                                                                                clientCompanyName: company?.name || ''
                                                                            });
                                                                        }}
                                                                        className="border rounded px-2 py-1 w-full text-sm"
                                                                    >
                                                                        <option value="">발주사 선택</option>
                                                                        {companies
                                                                            .filter(c => {
                                                                                const type = String(c.type ?? '').trim();
                                                                                const selectedId = String(site.clientCompanyId ?? '').trim();
                                                                                if (selectedId && String(c.id ?? '').trim() === selectedId) return true;
                                                                                return type === '건설사' || type === '미지정';
                                                                            })
                                                                            .map(company => (
                                                                                <option key={company.id} value={company.id}>{company.name}</option>
                                                                            ))}
                                                                    </select>
                                                                ) : col.key === 'companyName' ? (
                                                                    <select
                                                                        value={site.companyId || ''}
                                                                        onChange={(e) => {
                                                                            const companyId = e.target.value;
                                                                            const company = companies.find(c => c.id === companyId);
                                                                            const companyType = String(company?.type ?? '').trim();
                                                                            handleSiteSelectChange(site.id!, {
                                                                                companyId: companyId || '',
                                                                                companyName: company?.name || '',
                                                                                ...(companyType === '미지정'
                                                                                    ? {
                                                                                        clientCompanyId: companyId || '',
                                                                                        clientCompanyName: company?.name || ''
                                                                                    }
                                                                                    : {})
                                                                            });
                                                                        }}
                                                                        className="border rounded px-2 py-1 w-full text-sm"
                                                                    >
                                                                        <option value="">시공사 선택</option>
                                                                        {companies
                                                                            .filter(c => {
                                                                                const type = String(c.type ?? '').trim();
                                                                                return type === '시공사' || type === '미지정';
                                                                            })
                                                                            .map(company => (
                                                                                <option key={company.id} value={company.id}>{company.name}</option>
                                                                            ))}
                                                                    </select>
                                                                ) : col.key === 'partnerName' ? (
                                                                    <select
                                                                        value={site.partnerId || ''}
                                                                        onChange={(e) => {
                                                                            const companyId = e.target.value;
                                                                            const company = companies.find(c => c.id === companyId);
                                                                            handleSiteSelectChange(site.id!, {
                                                                                partnerId: companyId || '',
                                                                                partnerName: company?.name || ''
                                                                            });
                                                                        }}
                                                                        className="border rounded px-2 py-1 w-full text-sm"
                                                                    >
                                                                        <option value="">협력사 선택</option>
                                                                        {companies
                                                                            .filter(c => c.type === '협력사')
                                                                            .map(company => (
                                                                                <option key={company.id} value={company.id}>{company.name}</option>
                                                                            ))}
                                                                    </select>
                                                                ) : col.key === 'name' ? (
                                                                    <div className="flex items-center gap-2">
                                                                        <input
                                                                            type="color"
                                                                            value={site.color || '#6366f1'}
                                                                            onChange={(e) => handleSiteSelectChange(site.id!, { color: e.target.value })}
                                                                            className="h-8 w-8 rounded border border-slate-300 cursor-pointer p-0"
                                                                        />
                                                                        <input
                                                                            type="text"
                                                                            value={site.name}
                                                                            onChange={(e) => handleSiteChange(site.id!, 'name', e.target.value)}
                                                                            onBlur={(e) => handleSiteBlur(site.id!, 'name', e.target.value)}
                                                                            className="border rounded px-2 py-1 w-full text-sm font-medium"
                                                                        />
                                                                    </div>
                                                                ) : col.key === 'totalGongsu' ? (
                                                                    <span className="font-bold text-blue-600">
                                                                        {(siteStats[site.id!] || siteStats[site.name] || 0).toFixed(1)}공수
                                                                    </span>
                                                                ) : (
                                                                    <input
                                                                        type="text"
                                                                        value={String(site[col.key as keyof Site] || '')}
                                                                        onChange={(e) => handleSiteChange(site.id!, col.key as keyof Site, e.target.value)}
                                                                        onBlur={(e) => handleSiteBlur(site.id!, col.key as keyof Site, e.target.value)}
                                                                        className="border rounded px-2 py-1 w-full text-sm"
                                                                    />
                                                                )
                                                            ) : (
                                                                col.key === 'status' ? (
                                                                    <div className="flex items-center gap-2">
                                                                        <button
                                                                            onClick={() => handleSiteSelectChange(site.id!, { status: site.status === 'active' ? 'completed' : 'active' })}
                                                                            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none ${site.status === 'active' ? 'bg-green-500' : 'bg-slate-300'
                                                                                }`}
                                                                        >
                                                                            <span
                                                                                className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${site.status === 'active' ? 'translate-x-6' : 'translate-x-1'
                                                                                    }`}
                                                                            />
                                                                        </button>
                                                                        <span className={`text-xs font-bold ${site.status === 'active' ? 'text-green-600' : 'text-slate-500'}`}>
                                                                            {site.status === 'active' ? '진행중' : '종료'}
                                                                        </span>
                                                                    </div>
                                                                ) : col.key === 'name' ? (
                                                                    <div className="flex items-center gap-2">
                                                                        <span
                                                                            className="inline-flex items-center justify-center w-8 h-8 rounded-full border border-slate-200 flex-shrink-0"
                                                                            style={{ backgroundColor: site.color || siteCompanyColor || '#F3F4F6' }}
                                                                        >
                                                                            <FontAwesomeIcon icon={faHardHat} className={`text-xs ${site.color || siteCompanyColor ? 'text-white' : 'text-slate-400'}`} />
                                                                        </span>
                                                                        <span className="font-bold text-slate-800">{site.name}</span>
                                                                    </div>
                                                                ) : col.key === 'responsibleTeamName' ? (
                                                                    <SingleSelectPopover
                                                                        options={getFilteredTeamsForSite(site).map(t => ({
                                                                            id: t.id || '',
                                                                            name: t.name,
                                                                            icon: (
                                                                                <span
                                                                                    className="inline-flex items-center justify-center w-4 h-4 rounded-full border border-slate-200 flex-shrink-0"
                                                                                    style={{ backgroundColor: t.color || '#6366f1' }}
                                                                                >
                                                                                    <FontAwesomeIcon icon={faUsers} className="text-white text-[8px]" />
                                                                                </span>
                                                                            )
                                                                        }))}
                                                                        selectedId={site.responsibleTeamId || null}
                                                                        onSelect={(id) => {
                                                                            const team = teams.find(t => t.id === id);
                                                                            handleSiteSelectChange(site.id!, {
                                                                                responsibleTeamId: id,
                                                                                responsibleTeamName: team?.name || ''
                                                                            });
                                                                        }}
                                                                        placeholder="-"
                                                                        minimal={true}
                                                                        renderSelected={(opt) => {
                                                                            const team = teams.find(t => t.id === opt.id);
                                                                            const color = team?.color || '#6366f1';
                                                                            return (
                                                                                <div className="flex items-center gap-2">
                                                                                    <span
                                                                                        className="inline-flex items-center justify-center w-7 h-7 rounded-full border border-slate-200 flex-shrink-0"
                                                                                        style={{ backgroundColor: color }}
                                                                                    >
                                                                                        <FontAwesomeIcon icon={faUsers} className="text-white text-xs" />
                                                                                    </span>
                                                                                    <span className="font-semibold text-slate-800">
                                                                                        {opt.name}
                                                                                    </span>
                                                                                </div>
                                                                            );
                                                                        }}
                                                                    />
                                                                ) : col.key === 'clientCompanyName' ? (
                                                                    <SingleSelectPopover
                                                                        options={companies
                                                                            .filter((company) => {
                                                                                const type = String(company.type ?? '').trim();
                                                                                const selectedId = String(site.clientCompanyId ?? '').trim();
                                                                                if (selectedId && String(company.id ?? '').trim() === selectedId) return true;
                                                                                return type === '건설사' || type === '미지정';
                                                                            })
                                                                            .map((company) => ({
                                                                                id: String(company.id ?? ''),
                                                                                name: company.name,
                                                                                icon: <FontAwesomeIcon icon={faBuilding} className="text-slate-400" />
                                                                            }))}
                                                                        selectedId={site.clientCompanyId || null}
                                                                        onSelect={(id) => {
                                                                            const company = companies.find((c) => c.id === id);
                                                                            handleSiteSelectChange(site.id!, {
                                                                                clientCompanyId: id,
                                                                                clientCompanyName: company?.name || ''
                                                                            });
                                                                        }}
                                                                        placeholder="-"
                                                                        minimal={true}
                                                                    />
                                                                ) : col.key === 'companyName' ? (
                                                                    <SingleSelectPopover
                                                                        options={companies
                                                                            .filter((company) => {
                                                                                const type = String(company.type ?? '').trim();
                                                                                const selectedId = String(site.companyId ?? '').trim();
                                                                                if (selectedId && String(company.id ?? '').trim() === selectedId) return true;
                                                                                return type === '시공사' || type === '미지정';
                                                                            })
                                                                            .map((company) => ({
                                                                                id: String(company.id ?? ''),
                                                                                name: company.name,
                                                                                icon: <FontAwesomeIcon icon={faBuilding} className="text-slate-400" />
                                                                            }))}
                                                                        selectedId={site.companyId || null}
                                                                        onSelect={(id) => {
                                                                            const company = companies.find((c) => c.id === id);
                                                                            const companyType = String(company?.type ?? '').trim();
                                                                            handleSiteSelectChange(site.id!, {
                                                                                companyId: id,
                                                                                companyName: company?.name || '',
                                                                                ...(companyType === '미지정'
                                                                                    ? {
                                                                                        clientCompanyId: id,
                                                                                        clientCompanyName: company?.name || ''
                                                                                    }
                                                                                    : {})
                                                                            });
                                                                        }}
                                                                        placeholder="-"
                                                                        minimal={true}
                                                                    />
                                                                ) : col.key === 'partnerName' ? (
                                                                    <SingleSelectPopover
                                                                        options={companies
                                                                            .filter((company) => {
                                                                                const type = String(company.type ?? '').trim();
                                                                                const selectedId = String(site.partnerId ?? '').trim();
                                                                                if (selectedId && String(company.id ?? '').trim() === selectedId) return true;
                                                                                return type === '협력사';
                                                                            })
                                                                            .map((company) => ({
                                                                                id: String(company.id ?? ''),
                                                                                name: company.name,
                                                                                icon: <FontAwesomeIcon icon={faHandshake} className="text-slate-400" />
                                                                            }))}
                                                                        selectedId={site.partnerId || null}
                                                                        onSelect={(id) => {
                                                                            const company = companies.find((c) => c.id === id);
                                                                            handleSiteSelectChange(site.id!, {
                                                                                partnerId: id,
                                                                                partnerName: company?.name || ''
                                                                            });
                                                                        }}
                                                                        placeholder="-"
                                                                        minimal={true}
                                                                    />
                                                                ) : col.key === 'siteType' ? (
                                                                    <SingleSelectPopover
                                                                        options={[
                                                                            { id: '도급', name: '도급', icon: <FontAwesomeIcon icon={faBriefcase} className="text-slate-400" /> },
                                                                            { id: '직영', name: '직영', icon: <FontAwesomeIcon icon={faBuilding} className="text-slate-400" /> },
                                                                            { id: '지원', name: '지원', icon: <FontAwesomeIcon icon={faHandshake} className="text-slate-400" /> }
                                                                        ]}
                                                                        selectedId={site.siteType || null}
                                                                        onSelect={(id) => handleSiteSelectChange(site.id!, { siteType: id as any })}
                                                                        placeholder="-"
                                                                        minimal={true}
                                                                    />
                                                                ) : col.key === 'paymentMethod' ? (
                                                                    <SingleSelectPopover
                                                                        options={[
                                                                            { id: '계산서', name: '계산서', icon: <FontAwesomeIcon icon={faFileInvoiceDollar} className="text-slate-400" /> },
                                                                            { id: '노무', name: '노무', icon: <FontAwesomeIcon icon={faUserTie} className="text-slate-400" /> }
                                                                        ]}
                                                                        selectedId={site.paymentMethod || null}
                                                                        onSelect={(id) => handleSiteSelectChange(site.id!, { paymentMethod: id as any })}
                                                                        placeholder="-"
                                                                        minimal={true}
                                                                    />
                                                                ) : col.key === 'address' ? (
                                                                    <InputPopover
                                                                        value={site.address || ''}
                                                                        onChange={(val) => handleSiteBlur(site.id!, 'address', val)}
                                                                        placeholder="주소 입력"
                                                                        minimal={true}
                                                                    />
                                                                ) : (
                                                                    renderCellValue(site, col)
                                                                )
                                                            )}
                                                        </td>
                                                    ))}
                                                </tr>
                                                {/* Accordion Row */}
                                                {expandedSiteId === site.id && (
                                                    <tr className="bg-slate-50 border-b border-slate-200">
                                                        <td colSpan={visibleColumns.length + 2} className="p-4 px-8">
                                                            {historyLoading ? (
                                                                <div className="text-center py-4 text-slate-500">
                                                                    <div className="animate-spin inline-block w-6 h-6 border-[3px] border-current border-t-transparent text-indigo-600 rounded-full" role="status" aria-label="loading"></div>
                                                                    <span className="ml-2">데이터 불러오는 중...</span>
                                                                </div>
                                                            ) : siteHistory ? (
                                                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                                                    {/* Entered Teams */}
                                                                    <div className="bg-white rounded-lg border border-slate-200 p-4">
                                                                        <h4 className="text-sm font-bold text-slate-700 mb-3 flex items-center gap-2">
                                                                            <FontAwesomeIcon icon={faUsers} className="text-indigo-500" />
                                                                            <span>들어왔던 팀목록 ({siteHistory.teams.length})</span>
                                                                        </h4>
                                                                        <div className="overflow-x-auto max-h-60 overflow-y-auto">
                                                                            <table className="w-full text-xs text-left">
                                                                                <thead className="bg-slate-100 text-slate-600 sticky top-0">
                                                                                    <tr>
                                                                                        <th className="px-3 py-2 rounded-tl-md">팀명</th>
                                                                                        <th className="px-3 py-2">최근 진입</th>
                                                                                        <th className="px-3 py-2 rounded-tr-md text-right">총 공수</th>
                                                                                    </tr>
                                                                                </thead>
                                                                                <tbody className="divide-y divide-slate-100">
                                                                                    {siteHistory.teams.length > 0 ? (
                                                                                        siteHistory.teams.map(team => (
                                                                                            <tr key={team.id} className="hover:bg-slate-50">
                                                                                                <td className="px-3 py-2 font-medium text-slate-800">{team.name}</td>
                                                                                                <td className="px-3 py-2 text-slate-500">{team.lastDate}</td>
                                                                                                <td className="px-3 py-2 text-right font-medium text-indigo-600">{team.totalManDay.toFixed(1)}</td>
                                                                                            </tr>
                                                                                        ))
                                                                                    ) : (
                                                                                        <tr><td colSpan={3} className="px-3 py-4 text-center text-slate-400">데이터 없음</td></tr>
                                                                                    )}
                                                                                </tbody>
                                                                            </table>
                                                                        </div>
                                                                    </div>

                                                                    {/* Entered Workers */}
                                                                    <div className="bg-white rounded-lg border border-slate-200 p-4">
                                                                        <h4 className="text-sm font-bold text-slate-700 mb-3 flex items-center gap-2">
                                                                            <FontAwesomeIcon icon={faUsers} className="text-emerald-500" />
                                                                            <span>들어왔던 인원들 ({siteHistory.workers.length})</span>
                                                                        </h4>
                                                                        <div className="overflow-x-auto max-h-60 overflow-y-auto">
                                                                            <table className="w-full text-xs text-left">
                                                                                <thead className="bg-slate-100 text-slate-600 sticky top-0">
                                                                                    <tr>
                                                                                        <th className="px-3 py-2 rounded-tl-md">이름</th>
                                                                                        <th className="px-3 py-2">직종</th>
                                                                                        <th className="px-3 py-2">최근 진입</th>
                                                                                        <th className="px-3 py-2 rounded-tr-md text-right">총 공수</th>
                                                                                    </tr>
                                                                                </thead>
                                                                                <tbody className="divide-y divide-slate-100">
                                                                                    {siteHistory.workers.length > 0 ? (
                                                                                        siteHistory.workers.map(worker => (
                                                                                            <tr key={worker.id} className="hover:bg-slate-50">
                                                                                                <td className="px-3 py-2 font-medium text-slate-800">{worker.name}</td>
                                                                                                <td className="px-3 py-2 text-slate-500">{worker.role}</td>
                                                                                                <td className="px-3 py-2 text-slate-500">{worker.lastDate}</td>
                                                                                                <td className="px-3 py-2 text-right font-medium text-emerald-600">{worker.totalManDay.toFixed(1)}</td>
                                                                                            </tr>
                                                                                        ))
                                                                                    ) : (
                                                                                        <tr><td colSpan={4} className="px-3 py-4 text-center text-slate-400">데이터 없음</td></tr>
                                                                                    )}
                                                                                </tbody>
                                                                            </table>
                                                                        </div>
                                                                    </div>
                                                                </div>
                                                            ) : (
                                                                <div className="text-center text-slate-400 py-4">데이터를 불러올 수 없습니다.</div>
                                                            )}
                                                        </td>
                                                    </tr>
                                                )}
                                            </React.Fragment>
                                        );
                                    })
                                ) : (
                                    <tr>
                                        <td colSpan={visibleColumns.length + 2} className="px-6 py-12 text-center text-slate-500">
                                            <div className="flex flex-col items-center gap-2">
                                                <FontAwesomeIcon icon={faBuilding} className="text-4xl text-slate-300 mb-2" />
                                                <p>{searchTerm ? '검색 결과가 없습니다.' : '등록된 현장이 없습니다.'}</p>
                                            </div>
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            {/* Modals */}
            {showSiteModal && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 backdrop-blur-sm">
                    <div className="bg-white p-6 rounded-xl w-full max-w-2xl max-h-[90vh] overflow-y-auto shadow-2xl">
                        <div className="flex justify-between items-center mb-6">
                            <h2 className="text-xl font-bold text-slate-800">현장 등록</h2>
                            <button onClick={() => setShowSiteModal(false)} className="text-slate-400 hover:text-slate-600 transition-colors">
                                <FontAwesomeIcon icon={faTimes} className="text-lg" />
                            </button>
                        </div>
                        <SiteForm
                            initialData={editingSite || undefined}
                            teams={teams}
                            companies={companies}
                            onSave={handleSiteSave}
                            onCancel={() => setShowSiteModal(false)}
                        />
                    </div>
                </div>
            )}
        </div>
    );
};

export default SiteDatabase;

import React, { useState, useEffect, useRef } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faSearch, faPenToSquare, faPlus, faTable, faTrash, faPalette,
    faChevronDown, faChevronRight, faHardHat, faBuilding, faUsers, faTimes,
    faUserGear, faUserShield, faUser
} from '@fortawesome/free-solid-svg-icons';
import { teamService, Team } from '../../services/teamService';
import { manpowerService, Worker } from '../../services/manpowerService';
import { siteService, Site } from '../../services/siteService';
import { companyService, Company } from '../../services/companyService';
import { statisticsService } from '../../services/statisticsService';
import TeamForm from '../../components/manpower/TeamForm';
import { Timestamp } from '../../types/timestamp';
import MultiSelectPopover from '../../components/common/MultiSelectPopover';
import SingleSelectPopover, { InputPopover } from '../../components/common/SingleSelectPopover';
import { useColumnSettings } from '../../hooks/useColumnSettings';
import { positionService, Position } from '../../services/positionService';
import { getIcon } from '../../utils/iconMapper';

// 직책별 아이콘 매핑 (positions DB 기반)
const getPositionIcon = (role: string | undefined, positions: Position[]) => {
    if (!role) return faUser;
    const pos = positions.find(p => p.name === role);
    if (pos?.iconKey) {
        return getIcon(pos.iconKey);
    }
    // 폴백: 기본 매핑
    if (role.includes('사장') || role.includes('대표')) return faUserShield;
    if (role.includes('팀장') || role.includes('반장')) return faUserGear;
    return faUser;
};

const TEAM_TYPE_OPTIONS = ['시공팀', '지원팀', '용역팀'] as const;

const getTeamTypeBadgeClass = (type?: string) => {
    switch (type) {
        case '시공팀':
            return 'bg-blue-100 text-blue-800 border border-blue-200';
        case '지원팀':
            return 'bg-amber-100 text-amber-800 border border-amber-200';
        case '용역팀':
            return 'bg-emerald-100 text-emerald-800 border border-emerald-200';
        default:
            return 'bg-slate-100 text-slate-700 border border-slate-200';
    }
};

const TEAM_COLUMNS = [
    { key: 'name', label: '팀명' },
    { key: 'type', label: '구분' },
    { key: 'status', label: '상태' },
    { key: 'leaderName', label: '팀장' },
    { key: 'companyName', label: '소속사' },
    { key: 'bankName', label: '은행' },
    { key: 'accountNumber', label: '계좌번호' },
    { key: 'accountHolder', label: '예금주' },
    { key: 'siteCount', label: '배정 현장' },
    { key: 'memberCount', label: '팀원' },
    { key: 'totalManDay', label: '누적공수' }
];

interface TeamDatabaseProps {
    hideHeader?: boolean;
    highlightedId?: string | null;
}

const TeamDatabase: React.FC<TeamDatabaseProps> = ({ hideHeader = false, highlightedId }) => {
    const [teams, setTeams] = useState<Team[]>([]);
    const [workers, setWorkers] = useState<Worker[]>([]);
    const [sites, setSites] = useState<Site[]>([]);
    const [companies, setCompanies] = useState<Company[]>([]);
    const [positions, setPositions] = useState<Position[]>([]);
    const [teamStats, setTeamStats] = useState<{ [id: string]: number }>({});
    const [loading, setLoading] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [showInactive, setShowInactive] = useState(false);
    const [isStickyHeader, setIsStickyHeader] = useState(false); // Sticky header toggle

    // Highlight scroll control
    const highlightScrolledRef = useRef(false);
    const lastHighlightIdRef = useRef<string | null>(null);
    const partnerColorInputRef = useRef<HTMLInputElement>(null);
    const debounceTimerRef = useRef<NodeJS.Timeout | null>(null);

    // Selection & Edit State
    const [selectedTeamIds, setSelectedTeamIds] = useState<string[]>([]);
    const [expandedTeamIds, setExpandedTeamIds] = useState<string[]>([]);
    const [isEditMode, setIsEditMode] = useState(false);
    const [showTeamModal, setShowTeamModal] = useState(false);
    const [editingTeam, setEditingTeam] = useState<Team | null>(null);

    // Column Settings Hook
    const {
        visibleColumns,
        toggleColumn,
        showColumnSettings,
        setShowColumnSettings
    } = useColumnSettings('team_db', TEAM_COLUMNS);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        setLoading(true);
        try {
            const [teamsData, workersData, sitesData, companiesData, statsData, positionsData] = await Promise.all([
                teamService.getTeams(),
                manpowerService.getWorkers(),
                siteService.getSites(),
                companyService.getCompanies(),
                statisticsService.getCumulativeManpower(),
                positionService.getPositions()
            ]);
            setTeams(teamsData);
            setWorkers(workersData);
            setSites(sitesData);
            setCompanies(companiesData);
            setTeamStats(statsData.teamStats);
            setPositions(positionsData);
        } catch (error) {
            console.error("Failed to load team data:", error);
        } finally {
            setLoading(false);
        }
    };

    const renderCellValue = (team: Team, column: any) => {
        if (column.key === 'totalManDay') {
            const gongsu = teamStats[team.id!] || 0;
            return (
                <span className="font-bold text-blue-600">
                    {gongsu.toFixed(1)}공수
                </span>
            );
        }
        if (column.key === 'type') {
            return (
                <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-xs font-semibold ${getTeamTypeBadgeClass(team.type)}`}>
                    {team.type || '미지정'}
                </span>
            );
        }
        if (column.key === 'bankName' || column.key === 'accountNumber' || column.key === 'accountHolder') {
            const value = team[column.key as keyof Team];
            return value ? String(value) : '-';
        }

        const value = team[column.key as keyof Team];
        if (value === undefined || value === null) return '';
        if (typeof value === 'object' && 'toDate' in value) {
            return (value as any).toDate().toLocaleDateString();
        }
        if (typeof value === 'object') return JSON.stringify(value);
        return String(value);
    };

    const toggleSelectAll = () => {
        if (selectedTeamIds.length === teams.length) setSelectedTeamIds([]);
        else setSelectedTeamIds(teams.map(t => t.id!).filter(Boolean));
    };

    const toggleSelect = (id: string) => {
        setSelectedTeamIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
    };

    const toggleTeamExpand = (id: string) => {
        setExpandedTeamIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
    };

    const handleBulkDelete = async () => {
        if (selectedTeamIds.length === 0) return;
        if (!window.confirm(`${selectedTeamIds.length}개의 팀을 삭제 하시겠습니까?`)) return;

        try {
            setLoading(true);
            await Promise.all(selectedTeamIds.map(id => teamService.deleteTeam(id)));
            await loadData();
            setSelectedTeamIds([]);
            alert('삭제되었습니다.');
        } catch (error) {
            console.error("Bulk delete failed:", error);
            alert('삭제 중 오류가 발생했습니다.');
        } finally {
            setLoading(false);
        }
    };

    const handleTeamChange = (id: string, field: keyof Team, value: any) => {
        setTeams(prev => prev.map(t => t.id === id ? { ...t, [field]: value } : t));
    };

    const handleTeamBlur = async (id: string, field: keyof Team, value: any) => {
        try {
            await teamService.updateTeam(id, { [field]: value });
            if (field === 'name') {
                await manpowerService.updateWorkersTeamName(id, value);
            }
        } catch (error) {
            console.error("Failed to update team", error);
            loadData();
        }
    };

    const handleTeamSelectChange = async (id: string, updates: Partial<Team>) => {
        setTeams(prev => prev.map(t => t.id === id ? { ...t, ...updates } : t));
        try {
            await teamService.updateTeam(id, updates);
        } catch (error) {
            console.error("Failed to update team select", error);
            loadData();
        }
    };

    const handleTeamSiteSelect = async (id: string, selectedIds: string[]) => {
        const targetTeam = teams.find(t => t.id === id);
        if (!targetTeam) return;

        const currentAssignedSites = sites.filter(s => s.responsibleTeamId === id);
        const currentSiteIds = currentAssignedSites.map(s => s.id!);
        const addedIds = selectedIds.filter(sid => !currentSiteIds.includes(sid));
        const removedIds = currentSiteIds.filter(cid => !selectedIds.includes(cid));
        const selectedNames = sites.filter(s => selectedIds.includes(s.id!)).map(s => s.name);

        setSites(prev => prev.map(s => {
            if (addedIds.includes(s.id!)) return { ...s, responsibleTeamId: id, responsibleTeamName: targetTeam.name };
            if (removedIds.includes(s.id!)) return { ...s, responsibleTeamId: undefined, responsibleTeamName: undefined };
            return s;
        }));

        setTeams(prev => prev.map(t => t.id === id ? { ...t, siteIds: selectedIds, siteNames: selectedNames, assignedSiteId: selectedIds[0] || '' } : t));

        try {
            if (addedIds.length > 0) {
                await siteService.updateSitesBatch(addedIds, { responsibleTeamId: id, responsibleTeamName: targetTeam.name });
            }
            if (removedIds.length > 0) {
                await siteService.updateSitesBatch(removedIds, { responsibleTeamId: null as any, responsibleTeamName: null as any });
            }
            await teamService.updateTeam(id, {
                siteIds: selectedIds,
                siteNames: selectedNames,
                assignedSiteId: selectedIds.length > 0 ? selectedIds[0] : '',
                assignedSiteName: selectedNames.length > 0 ? selectedNames[0] + (selectedNames.length > 1 ? ` 외 ${selectedNames.length - 1}곳` : '') : ''
            });
        } catch (error) {
            console.error("Failed to update team sites", error);
            loadData();
        }
    };

    const handleTeamMemberSelect = async (id: string, selectedIds: string[]) => {
        const targetTeam = teams.find(t => t.id === id);
        if (!targetTeam) return;

        const currentMembers = workers.filter(w => w.teamId === id);
        const currentMemberIds = currentMembers.map(w => w.id!);
        const addedIds = selectedIds.filter(sid => !currentMemberIds.includes(sid));
        const removedIds = currentMemberIds.filter(cid => !selectedIds.includes(cid));
        const selectedNames = workers.filter(w => selectedIds.includes(w.id!)).map(w => w.name);

        setWorkers(prev => prev.map(w => {
            if (addedIds.includes(w.id!)) return { ...w, teamId: id, teamName: targetTeam.name };
            if (removedIds.includes(w.id!)) return { ...w, teamId: undefined, teamName: undefined };
            return w;
        }));

        setTeams(prev => prev.map(t => t.id === id ? { ...t, memberIds: selectedIds, memberNames: selectedNames, memberCount: selectedIds.length } : t));

        try {
            if (addedIds.length > 0) {
                await manpowerService.updateWorkersBatch(addedIds, { teamId: id, teamName: targetTeam.name });
            }
            if (removedIds.length > 0) {
                await manpowerService.updateWorkersBatch(removedIds, { teamId: null as any, teamName: null as any });
            }
            await teamService.updateTeam(id, {
                memberIds: selectedIds,
                memberNames: selectedNames,
                memberCount: selectedIds.length,
                assignedWorkers: selectedIds
            });
        } catch (error) {
            console.error("Failed to update team members", error);
            loadData();
        }
    };

    const handleTeamSave = async () => {
        await loadData();
        setShowTeamModal(false);
        setEditingTeam(null);
        alert('팀 정보가 저장되었습니다.');
    };

    const handleLeaderUpdate = async (teamId: string, leaderId: string) => {
        try {
            const currentTeam = teams.find(t => t.id === teamId);
            const oldLeaderId = currentTeam?.leaderId;
            const selectedWorker = workers.find(w => w.id === leaderId);
            const leaderName = selectedWorker ? selectedWorker.name : '';

            setTeams(prev => prev.map(t =>
                t.id === teamId ? { ...t, leaderId, leaderName } : t
            ));

            // 1. Team Update
            await teamService.updateTeam(teamId, { leaderId, leaderName });

            // 2. Worker Role Update
            // New Leader -> 팀장
            if (leaderId) {
                await manpowerService.updateWorker(leaderId, { role: '팀장' });
            }
            // Old Leader -> 팀원 (if exists and different from new leader)
            if (oldLeaderId && oldLeaderId !== leaderId) {
                await manpowerService.updateWorker(oldLeaderId, { role: '팀원' });
            }

            // 3. Update local workers state to reflect role changes immediately
            setWorkers(prev => prev.map(w => {
                if (w.id === leaderId) return { ...w, role: '팀장' };
                if (w.id === oldLeaderId && oldLeaderId !== leaderId) return { ...w, role: '팀원' };
                return w;
            }));

        } catch (error) {
            console.error("Failed to update leader", error);
            loadData();
        }
    };

    const filteredTeams = teams.filter(team => {
        if (!showInactive && (team.status === 'waiting' || team.status === 'closed')) return false;
        if (searchTerm) {
            const searchLower = searchTerm.toLowerCase();
            return (
                team.name.toLowerCase().includes(searchLower) ||
                team.leaderName?.toLowerCase().includes(searchLower) ||
                team.companyName?.toLowerCase().includes(searchLower) ||
                team.type?.toLowerCase().includes(searchLower)
            );
        }
        return true;
    });

    const companyOptions = companies.filter((company) => {
        const type = String(company.type ?? '').trim();
        return type === '시공사' || type === '미지정' || type === '협력사';
    });

    return (
        <div className="flex flex-col h-full bg-slate-50">
            {!hideHeader && (
                <>
                    <div className="flex justify-between items-center p-6 border-b border-slate-200 bg-white">
                        <h1 className="text-2xl font-bold text-slate-800">팀 관리</h1>
                        <div className="flex gap-2">
                            <button onClick={() => setShowColumnSettings(true)} className="p-2 text-slate-500 hover:text-slate-700 bg-white border border-slate-200 rounded">
                                <FontAwesomeIcon icon={faTable} />
                            </button>
                            <button onClick={() => { setEditingTeam(null); setShowTeamModal(true); }} className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded flex items-center gap-2">
                                <FontAwesomeIcon icon={faPlus} />
                                <span>팀 등록</span>
                            </button>
                        </div>
                    </div>
                    <div className="p-6 bg-white border-b border-slate-200 flex flex-wrap gap-4 items-center">
                        <div className="relative">
                            <FontAwesomeIcon icon={faSearch} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                            <input
                                type="text"
                                placeholder="팀명, 팀장, 소속사 검색"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="pl-10 pr-4 py-2 border border-slate-200 rounded w-64 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                            />
                        </div>
                        <div className="flex items-center gap-2">
                            <label className="flex items-center gap-2 cursor-pointer">
                                <input
                                    type="checkbox"
                                    checked={showInactive}
                                    onChange={(e) => setShowInactive(e.target.checked)}
                                    className="rounded text-indigo-600 focus:ring-indigo-500"
                                />
                                <span className="text-sm text-slate-600">폐업/대기 포함</span>
                            </label>
                            <label className="flex items-center gap-2 cursor-pointer bg-white px-2 py-1 rounded border border-gray-200 hover:bg-gray-50">
                                <input
                                    type="checkbox"
                                    checked={isStickyHeader}
                                    onChange={(e) => setIsStickyHeader(e.target.checked)}
                                    className="rounded text-indigo-600 focus:ring-indigo-500"
                                />
                                <span className="text-sm text-slate-600">목록 고정</span>
                            </label>
                        </div>
                        <div className="flex-1" />
                        <div className="flex gap-2">
                            {selectedTeamIds.length > 0 && (
                                <button onClick={handleBulkDelete} className="px-3 py-1.5 rounded text-sm font-medium bg-red-50 text-red-600 hover:bg-red-100 border border-red-200">
                                    <FontAwesomeIcon icon={faTrash} className="mr-1" /> 삭제 ({selectedTeamIds.length})
                                </button>
                            )}
                            <button onClick={() => setIsEditMode(!isEditMode)} className={`px-3 py-1.5 rounded text-sm font-medium border ${isEditMode ? 'bg-indigo-50 border-indigo-200 text-indigo-700' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
                                {isEditMode ? '편집 종료' : '편집 모드'}
                            </button>
                        </div>
                    </div>
                </>
            )}

            <div className={`flex-1 ${!hideHeader ? 'p-6' : ''} ${isStickyHeader ? 'overflow-hidden' : 'overflow-auto pb-[400px]'}`}>
                <div className={`${isStickyHeader ? 'overflow-auto h-full max-h-[calc(100vh-250px)]' : 'overflow-x-auto'}`}>
                    <table className="w-full text-sm text-left text-slate-500">
                        <thead className={`text-xs text-white uppercase bg-slate-900 ${isStickyHeader ? 'sticky top-0 z-10' : ''}`}>
                            <tr>
                                <th className="px-6 py-3 w-4 border border-slate-700">
                                    <input
                                        type="checkbox"
                                        checked={teams.length > 0 && selectedTeamIds.length === teams.length}
                                        onChange={toggleSelectAll}
                                        className="rounded text-indigo-600 focus:ring-indigo-500 w-4 h-4 cursor-pointer"
                                    />
                                </th>
                                <th className="px-2 py-3 w-8 border border-slate-700"></th>
                                {TEAM_COLUMNS.filter(col => visibleColumns.includes(col.key)).map(col => (
                                    <th key={col.key} className="px-6 py-3 font-semibold border border-slate-700">{col.label}</th>
                                ))}
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {filteredTeams.length > 0 ? (
                                filteredTeams.map((team) => {
                                    const isHighlighted = team.id === highlightedId;
                                    const teamCompany = team.companyId ? companies.find(c => c.id === team.companyId) : undefined;
                                    const assignedSites = sites.filter(s => s.responsibleTeamId === team.id);
                                    const assignedWorkers = workers.filter(w => w.teamId === team.id);
                                    const assignedWorkerIds = assignedWorkers.map(w => w.id!).filter(Boolean);

                                    return (
                                        <React.Fragment key={team.id}>
                                            <tr
                                                onClick={() => toggleSelect(team.id!)}
                                                className={`transition-colors border-b cursor-pointer
                                                    ${isHighlighted ? 'bg-red-50 border border-red-300 ring-1 ring-red-300 z-10 relative' :
                                                        expandedTeamIds.includes(team.id!) ? 'bg-slate-50' :
                                                            selectedTeamIds.includes(team.id!) ? 'bg-indigo-50/50' :
                                                                'bg-white hover:bg-slate-50'} 
                                                    ${!isHighlighted && (team.status === 'waiting' || team.status === 'closed') ? 'opacity-75 bg-slate-50' : ''}
                                                `}
                                                ref={isHighlighted
                                                    ? (el) => {
                                                        if (!el) return;
                                                        const currentId = highlightedId || null;
                                                        if (lastHighlightIdRef.current !== currentId) {
                                                            lastHighlightIdRef.current = currentId;
                                                            highlightScrolledRef.current = false;
                                                        }
                                                        if (!highlightScrolledRef.current) {
                                                            el.scrollIntoView({ behavior: 'smooth', block: 'center' });
                                                            highlightScrolledRef.current = true;
                                                        }
                                                    }
                                                    : null}
                                            >
                                                <td className="px-6 py-4 border border-slate-200" onClick={(e) => e.stopPropagation()}>
                                                    <input
                                                        type="checkbox"
                                                        checked={selectedTeamIds.includes(team.id!)}
                                                        onChange={() => toggleSelect(team.id!)}
                                                        className="rounded text-indigo-600 focus:ring-indigo-500"
                                                    />
                                                </td>
                                                <td className="px-2 py-4 text-center cursor-pointer border border-slate-200" onClick={() => toggleTeamExpand(team.id!)}>
                                                    <FontAwesomeIcon
                                                        icon={expandedTeamIds.includes(team.id!) ? faChevronDown : faChevronRight}
                                                        className="text-slate-400 hover:text-indigo-600 transition-colors"
                                                    />
                                                </td>
                                                {TEAM_COLUMNS.filter(col => visibleColumns.includes(col.key)).map(col => (
                                                    <td key={`${team.id}-${col.key}`} className="px-6 py-4 border border-slate-200">
                                                        {isEditMode && team.id ? (
                                                            col.key === 'totalManDay' ? (
                                                                <span className="font-bold text-blue-600">
                                                                    {(teamStats[team.id!] || 0).toFixed(1)}공수
                                                                </span>
                                                            ) : col.key === 'type' ? (
                                                                <select
                                                                    value={team.type || TEAM_TYPE_OPTIONS[0]}
                                                                    onChange={(e) => team.id && handleTeamChange(team.id, 'type', e.target.value)}
                                                                    onBlur={(e) => team.id && handleTeamBlur(team.id, 'type', e.target.value)}
                                                                    className="border rounded px-2 py-1 w-full text-sm"
                                                                >
                                                                    {[...new Set([
                                                                        ...TEAM_TYPE_OPTIONS,
                                                                        ...teams.map((item) => String(item.type || '').trim()).filter(Boolean)
                                                                    ])].map((type) => (
                                                                        <option key={type} value={type}>
                                                                            {type}
                                                                        </option>
                                                                    ))}
                                                                </select>
                                                            ) : col.key === 'status' ? (
                                                                <select
                                                                    value={team.status || 'active'}
                                                                    onChange={(e) => team.id && handleTeamChange(team.id, 'status', e.target.value)}
                                                                    onBlur={(e) => team.id && handleTeamBlur(team.id, 'status', e.target.value)}
                                                                    className="border rounded px-2 py-1 w-full text-sm"
                                                                >
                                                                    <option value="active">협업중</option>
                                                                    <option value="waiting">대기</option>
                                                                    <option value="closed">폐업</option>
                                                                </select>
                                                            ) : col.key === 'leaderName' ? (
                                                                <SingleSelectPopover
                                                                    options={workers.sort((a, b) => a.name.localeCompare(b.name)).map(w => ({
                                                                        id: w.id!,
                                                                        name: w.name,
                                                                        icon: <div className="w-5 h-5 rounded-full bg-slate-200 flex items-center justify-center text-[10px] font-bold text-slate-500">{w.name[0]}</div>
                                                                    }))}
                                                                    selectedId={team.leaderId || null}
                                                                    onSelect={(id: string) => handleLeaderUpdate(team.id!, id)}
                                                                    placeholder="팀장 선택"
                                                                    renderSelected={(opt: any) => {
                                                                        const leaderWorker = workers.find(w => w.id === team.leaderId);
                                                                        const leaderPosition = positions.find(p => p.name === leaderWorker?.role);
                                                                        const posColor = leaderPosition?.color || 'blue';
                                                                        const colorClass = {
                                                                            red: 'bg-red-500', orange: 'bg-orange-500', yellow: 'bg-yellow-500',
                                                                            green: 'bg-emerald-500', blue: 'bg-blue-500', indigo: 'bg-indigo-500',
                                                                            purple: 'bg-purple-500', pink: 'bg-pink-500', gray: 'bg-slate-500',
                                                                            slate: 'bg-slate-500', black: 'bg-slate-900',
                                                                        }[posColor] || 'bg-blue-500';
                                                                        return (
                                                                            <div className="flex items-center gap-2">
                                                                                <span className={`inline-flex items-center justify-center w-6 h-6 rounded-md ${colorClass}`}>
                                                                                    <FontAwesomeIcon icon={getPositionIcon(leaderWorker?.role, positions)} className="text-white text-xs" />
                                                                                </span>
                                                                                <span className="font-medium text-slate-700">{opt.name}</span>
                                                                            </div>
                                                                        );
                                                                    }}
                                                                />
                                                            ) : col.key === 'companyName' ? (
                                                                <select
                                                                    value={team.companyId || ''}
                                                                    onChange={(e) => {
                                                                        const selectedCompany = companies.find(c => c.id === e.target.value);
                                                                        if (team.id) {
                                                                            handleTeamSelectChange(team.id, {
                                                                                companyId: e.target.value,
                                                                                companyName: selectedCompany ? selectedCompany.name : ''
                                                                            });
                                                                        }
                                                                    }}
                                                                    className="border rounded px-2 py-1 w-full text-sm"
                                                                >
                                                                    <option value="">미소속</option>
                                                                    {companyOptions.map(company => (
                                                                        <option key={company.id} value={company.id}>{company.name}</option>
                                                                    ))}
                                                                </select>
                                                            ) : col.key === 'siteCount' ? (
                                                                <MultiSelectPopover
                                                                    options={sites.map(s => ({ ...s, id: s.id || '' }))}
                                                                    selectedIds={assignedSites.map(s => s.id!)}
                                                                    placeholder={`${assignedSites.length}개 담당`}
                                                                    onSelect={(id) => {
                                                                        const currentIds = assignedSites.map(s => s.id!);
                                                                        const newIds = currentIds.includes(id)
                                                                            ? currentIds.filter(x => x !== id)
                                                                            : [...currentIds, id];
                                                                        if (team.id) handleTeamSiteSelect(team.id, newIds);
                                                                    }}
                                                                    onSelectAll={() => {
                                                                        const currentLen = assignedSites.length;
                                                                        const totalLen = sites.length;
                                                                        if (currentLen === totalLen) {
                                                                            if (team.id) handleTeamSiteSelect(team.id, []);
                                                                        } else {
                                                                            const allIds = sites.map(s => s.id || '').filter(Boolean);
                                                                            if (team.id) handleTeamSiteSelect(team.id, allIds);
                                                                        }
                                                                    }}
                                                                />
                                                            ) : col.key === 'memberCount' ? (
                                                                <MultiSelectPopover
                                                                    options={workers.map(w => ({ ...w, id: w.id || '' }))}
                                                                    selectedIds={assignedWorkerIds}
                                                                    placeholder={`${assignedWorkerIds.length}명`}
                                                                    onSelect={(id) => {
                                                                        const current = assignedWorkerIds;
                                                                        const newIds = current.includes(id) ? current.filter(x => x !== id) : [...current, id];
                                                                        if (team.id) handleTeamMemberSelect(team.id, newIds);
                                                                    }}
                                                                    onSelectAll={() => {
                                                                        const currentLen = assignedWorkerIds.length;
                                                                        const totalLen = workers.length;
                                                                        if (!team.id) return;
                                                                        if (currentLen === totalLen) {
                                                                            handleTeamMemberSelect(team.id, []);
                                                                        } else {
                                                                            const allIds = workers.map(w => w.id || '').filter(Boolean);
                                                                            handleTeamMemberSelect(team.id, allIds);
                                                                        }
                                                                    }}
                                                                />
                                                            ) : col.key === 'name' ? (
                                                                <div className="flex items-center gap-2">
                                                                    <input
                                                                        type="color"
                                                                        value={team.color || '#2563eb'}
                                                                        onChange={(e) => team.id && handleTeamChange(team.id, 'color', e.target.value)}
                                                                        onBlur={(e) => team.id && handleTeamBlur(team.id, 'color', e.target.value)}
                                                                        className="h-8 w-8 rounded border border-slate-300 cursor-pointer"
                                                                    />
                                                                    <input
                                                                        type="text"
                                                                        value={team.name || ''}
                                                                        onChange={(e) => team.id && handleTeamChange(team.id, 'name', e.target.value)}
                                                                        onBlur={(e) => team.id && handleTeamBlur(team.id, 'name', e.target.value)}
                                                                        className="flex-1 border rounded px-2 py-1 w-full text-sm"
                                                                    />
                                                                </div>
                                                            ) : (
                                                                <input
                                                                    type="text"
                                                                    value={String(team[col.key as keyof Team] || '')}
                                                                    onChange={(e) => team.id && handleTeamChange(team.id, col.key as keyof Team, e.target.value)}
                                                                    onBlur={(e) => team.id && handleTeamBlur(team.id, col.key as keyof Team, e.target.value)}
                                                                    className="border rounded px-2 py-1 w-full text-sm"
                                                                />
                                                            )
                                                        ) : (
                                                            col.key === 'name' ? (
                                                                <div className="flex items-center gap-2">
                                                                    <span
                                                                        className="inline-flex items-center justify-center w-7 h-7 rounded-full border border-slate-200 flex-shrink-0"
                                                                        style={{ backgroundColor: team.color || '#e5e7eb' }}
                                                                    >
                                                                        <FontAwesomeIcon icon={faUsers} className="text-white text-xs" />
                                                                    </span>
                                                                    <span>{team.name}</span>
                                                                </div>
                                                            ) : col.key === 'totalManDay' ? (
                                                                <span className="font-bold text-blue-600">
                                                                    {(teamStats[team.id!] || 0).toFixed(1)}공수
                                                                </span>
                                                            ) : col.key === 'type' ? (
                                                                <SingleSelectPopover
                                                                    options={[...new Set([
                                                                        ...TEAM_TYPE_OPTIONS,
                                                                        ...teams.map((item) => String(item.type || '').trim()).filter(Boolean)
                                                                    ])].map((type) => ({
                                                                        id: type,
                                                                        name: type,
                                                                    }))}
                                                                    selectedId={team.type || TEAM_TYPE_OPTIONS[0]}
                                                                    onSelect={(id: string) => {
                                                                        if (!team.id) return;
                                                                        handleTeamSelectChange(team.id, { type: id });
                                                                    }}
                                                                    placeholder="구분 선택"
                                                                    minimal={true}
                                                                />
                                                            ) : col.key === 'status' ? (
                                                                <SingleSelectPopover
                                                                    options={[
                                                                        { id: 'active', name: '협업중' },
                                                                        { id: 'waiting', name: '대기' },
                                                                        { id: 'closed', name: '폐업' }
                                                                    ]}
                                                                    selectedId={team.status || 'active'}
                                                                    onSelect={(id: string) => {
                                                                        if (!team.id) return;
                                                                        handleTeamSelectChange(team.id, { status: id as Team['status'] });
                                                                    }}
                                                                    placeholder="상태 선택"
                                                                    minimal={true}
                                                                />
                                                            ) : col.key === 'leaderName' ? (
                                                                <SingleSelectPopover
                                                                    options={workers.sort((a, b) => a.name.localeCompare(b.name)).map(w => ({
                                                                        id: w.id!,
                                                                        name: w.name,
                                                                        icon: <div className="w-5 h-5 rounded-full bg-slate-200 flex items-center justify-center text-[10px] font-bold text-slate-500">{w.name[0]}</div>
                                                                    }))}
                                                                    selectedId={team.leaderId || null}
                                                                    onSelect={(id: string) => handleLeaderUpdate(team.id!, id)}
                                                                    placeholder="미지정"
                                                                    minimal={true}
                                                                    renderSelected={(opt: any) => {
                                                                        const leaderWorker = workers.find(w => w.id === team.leaderId);
                                                                        const leaderPosition = positions.find(p => p.name === leaderWorker?.role);
                                                                        const posColor = leaderPosition?.color || 'blue';
                                                                        const colorClass = {
                                                                            red: 'bg-red-500', orange: 'bg-orange-500', yellow: 'bg-yellow-500',
                                                                            green: 'bg-emerald-500', blue: 'bg-blue-500', indigo: 'bg-indigo-500',
                                                                            purple: 'bg-purple-500', pink: 'bg-pink-500', gray: 'bg-slate-500',
                                                                            slate: 'bg-slate-500', black: 'bg-slate-900',
                                                                        }[posColor] || 'bg-blue-500';
                                                                        return (
                                                                            <div className="flex items-center gap-2">
                                                                                <span className={`inline-flex items-center justify-center w-6 h-6 rounded-md ${colorClass}`}>
                                                                                    <FontAwesomeIcon icon={getPositionIcon(leaderWorker?.role, positions)} className="text-white text-xs" />
                                                                                </span>
                                                                                <span className="font-medium text-slate-700">{opt.name}</span>
                                                                            </div>
                                                                        );
                                                                    }}
                                                                />
                                                            ) : col.key === 'companyName' ? (
                                                                <SingleSelectPopover
                                                                    options={companyOptions.map(company => ({
                                                                        id: company.id || '',
                                                                        name: company.name,
                                                                        icon: <FontAwesomeIcon icon={faBuilding} className="text-slate-400" />
                                                                    }))}
                                                                    selectedId={team.companyId || null}
                                                                    onSelect={(id: string) => {
                                                                        if (!team.id) return;
                                                                        const selectedCompany = companies.find(c => c.id === id);
                                                                        handleTeamSelectChange(team.id, {
                                                                            companyId: id,
                                                                            companyName: selectedCompany ? selectedCompany.name : ''
                                                                        });
                                                                    }}
                                                                    placeholder="미소속"
                                                                    minimal={true}
                                                                />
                                                            ) : col.key === 'bankName' ? (
                                                                <InputPopover
                                                                    value={team.bankName || ''}
                                                                    onChange={(value) => {
                                                                        if (!team.id) return;
                                                                        handleTeamSelectChange(team.id, { bankName: String(value || '') });
                                                                    }}
                                                                    placeholder="은행명"
                                                                    minimal={true}
                                                                />
                                                            ) : col.key === 'accountNumber' ? (
                                                                <InputPopover
                                                                    value={team.accountNumber || ''}
                                                                    onChange={(value) => {
                                                                        if (!team.id) return;
                                                                        handleTeamSelectChange(team.id, { accountNumber: String(value || '') });
                                                                    }}
                                                                    placeholder="계좌번호"
                                                                    minimal={true}
                                                                />
                                                            ) : col.key === 'accountHolder' ? (
                                                                <InputPopover
                                                                    value={team.accountHolder || ''}
                                                                    onChange={(value) => {
                                                                        if (!team.id) return;
                                                                        handleTeamSelectChange(team.id, { accountHolder: String(value || '') });
                                                                    }}
                                                                    placeholder="예금주"
                                                                    minimal={true}
                                                                />
                                                            ) : col.key === 'siteCount' ? (
                                                                <MultiSelectPopover
                                                                    options={sites.map(s => ({ ...s, id: s.id || '' }))}
                                                                    selectedIds={assignedSites.map(s => s.id!)}
                                                                    placeholder={`${assignedSites.length}개 담당`}
                                                                    minimal={true}
                                                                    onSelect={(id: string) => {
                                                                        const currentIds = assignedSites.map(s => s.id!);
                                                                        const newIds = currentIds.includes(id)
                                                                            ? currentIds.filter(x => x !== id)
                                                                            : [...currentIds, id];
                                                                        if (team.id) handleTeamSiteSelect(team.id, newIds);
                                                                    }}
                                                                    onSelectAll={() => {
                                                                        const currentLen = assignedSites.length;
                                                                        const totalLen = sites.length;
                                                                        if (currentLen === totalLen) {
                                                                            if (team.id) handleTeamSiteSelect(team.id, []);
                                                                        } else {
                                                                            const allIds = sites.map(s => s.id || '').filter(Boolean);
                                                                            if (team.id) handleTeamSiteSelect(team.id, allIds);
                                                                        }
                                                                    }}
                                                                />
                                                            ) : col.key === 'memberCount' ? (
                                                                <MultiSelectPopover
                                                                    options={workers.map(w => ({ ...w, id: w.id || '' }))}
                                                                    selectedIds={assignedWorkerIds}
                                                                    placeholder={`${assignedWorkerIds.length}명`}
                                                                    minimal={true}
                                                                    onSelect={(id: string) => {
                                                                        const currentIds = assignedWorkerIds;
                                                                        const newIds = currentIds.includes(id)
                                                                            ? currentIds.filter(x => x !== id)
                                                                            : [...currentIds, id];
                                                                        if (team.id) handleTeamMemberSelect(team.id, newIds);
                                                                    }}
                                                                    onSelectAll={() => {
                                                                        const currentLen = assignedWorkerIds.length;
                                                                        const totalLen = workers.length;
                                                                        if (currentLen === totalLen) {
                                                                            if (team.id) handleTeamMemberSelect(team.id, []);
                                                                        } else {
                                                                            const allIds = workers.map(w => w.id || '').filter(Boolean);
                                                                            if (team.id) handleTeamMemberSelect(team.id, allIds);
                                                                        }
                                                                    }}
                                                                />
                                                            ) : col.key === 'name' ? (
                                                                <div className="flex items-center gap-2">
                                                                    <span
                                                                        className="inline-block w-1.5 h-6 rounded-full border border-slate-200"
                                                                        style={{ backgroundColor: team.color || '#e5e7eb' }}
                                                                    />
                                                                    <span className="font-semibold text-slate-800">{team.name}</span>
                                                                </div>
                                                            ) : (
                                                                renderCellValue(team, col)
                                                            )
                                                        )}
                                                    </td>
                                                ))}
                                            </tr>
                                            {
                                                expandedTeamIds.includes(team.id!) && (
                                                    <tr className="bg-slate-50/50">
                                                        <td colSpan={visibleColumns.length + 2} className="px-6 py-4">
                                                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                                                                {/* Assigned Sites (via Site.responsibleTeamId) */}
                                                                {assignedSites.map(site => (
                                                                    <div key={site.id} className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm flex items-center gap-3">
                                                                        <div className="p-2 bg-emerald-50 text-emerald-600 rounded-lg">
                                                                            <FontAwesomeIcon icon={faBuilding} />
                                                                        </div>
                                                                        <div>
                                                                            <div className="text-sm font-semibold text-slate-800">{site.name}</div>
                                                                            <div className="text-xs text-slate-500">{site.address}</div>
                                                                        </div>
                                                                    </div>
                                                                ))}
                                                                {/* Assigned Workers */}
                                                                {assignedWorkers.map(worker => (
                                                                    <div key={worker.id} className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm flex items-center gap-3">
                                                                        <div className="w-8 h-8 bg-slate-100 rounded-full flex items-center justify-center text-slate-500 text-xs">
                                                                            <FontAwesomeIcon icon={faHardHat} />
                                                                        </div>
                                                                        <div className="min-w-0">
                                                                            <div className="text-sm font-semibold text-slate-800 truncate">{worker.name}</div>
                                                                            <div className="text-xs text-slate-500 truncate">{worker.role || '팀원'}</div>
                                                                        </div>
                                                                    </div>
                                                                ))}
                                                                {(!team.siteIds?.length && !workers.some(w => w.teamId === team.id)) && (
                                                                    <div className="col-span-full py-8 text-center text-slate-400 text-sm bg-white rounded-lg border border-dashed border-slate-300">
                                                                        배정된 현장이나 작업자가 없습니다.
                                                                    </div>
                                                                )}
                                                            </div>
                                                        </td>
                                                    </tr>
                                                )
                                            }
                                        </React.Fragment>
                                    );
                                })
                            ) : (
                                <tr>
                                    <td colSpan={visibleColumns.length + 2} className="px-6 py-12 text-center text-slate-500">
                                        <div className="flex flex-col items-center gap-2">
                                            <FontAwesomeIcon icon={faUsers} className="text-4xl text-slate-300 mb-2" />
                                            <p>{searchTerm ? '검색 결과가 없습니다.' : '등록된 팀이 없습니다.'}</p>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Modals */}
            {
                showTeamModal && (
                    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 backdrop-blur-sm">
                        <div className="bg-white p-6 rounded-xl w-full max-w-2xl max-h-[90vh] overflow-y-auto shadow-2xl">
                            <div className="flex justify-between items-center mb-6">
                                <h2 className="text-xl font-bold text-slate-800">팀 등록</h2>
                                <button onClick={() => setShowTeamModal(false)} className="text-slate-400 hover:text-slate-600 transition-colors">
                                    <FontAwesomeIcon icon={faTimes} className="text-lg" />
                                </button>
                            </div>
                            <TeamForm
                                initialData={editingTeam || undefined}
                                teams={teams}
                                workers={workers}
                                companies={companyOptions}
                                onSave={handleTeamSave}
                                onCancel={() => setShowTeamModal(false)}
                            />
                        </div>
                    </div>
                )
            }
        </div >
    );
};

export default TeamDatabase;

import React, { useState, useEffect, useRef } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { resolveIcon } from '../../constants/iconMap';
import {
    faUsers, faUser, faPlus, faSearch, faEdit, faTrash,
    faCheckSquare, faSquare, faTable, faBuilding,
    faIdCard, faArrowUp, faArrowDown,
    faEye, faEyeSlash, faLink, faImages, faPenToSquare, faDownload, faMoneyCheck,
    IconDefinition
} from '@fortawesome/free-solid-svg-icons';
import { manpowerService, Worker } from '../../services/manpowerService';
import { teamService, Team } from '../../services/teamService';
import { siteService, Site } from '../../services/siteService';
import { companyService, Company } from '../../services/companyService';
import { positionService, Position } from '../../services/positionService';
import { dailyReportService } from '../../services/dailyReportService';
import { geminiService } from '../../services/geminiService';
import { storage } from '../../config/firebase';
import { ref, uploadBytes, getDownloadURL, getBlob } from 'firebase/storage';
import JSZip from 'jszip';
import { saveAs } from 'file-saver';
import AccountLinkingModal from '../../components/manpower/AccountLinkingModal';
import BulkProgressModal from '../../components/manpower/BulkProgressModal';
import BulkEditWorkerModal from '../../components/manpower/BulkEditWorkerModal';
import BankBookAnalysisModal from '../../components/manpower/BankBookAnalysisModal';
import IdCardAnalysisModal from '../../components/manpower/IdCardAnalysisModal';
import WorkerModal from '../manpower/WorkerModal';
import SignatureGeneratorModal from '../../components/signatures/SignatureGeneratorModal';
import { useColumnSettings } from '../../hooks/useColumnSettings';
import SingleSelectPopover, { InputPopover } from '../../components/common/SingleSelectPopover';

const WORKER_COLUMNS = [
    { key: 'name', label: '이름' },
    { key: 'idNumber', label: '주민번호' },
    { key: 'contact', label: '연락처' },
    { key: 'address', label: '주소' },
    { key: 'role', label: '직책' },
    { key: 'salaryModel', label: '구분' },
    { key: 'teamName', label: '소속팀' },
    { key: 'companyName', label: '소속회사' },
    { key: 'status', label: '상태' },
    { key: 'unitPrice', label: '단가' },
    { key: 'bankName', label: '은행' },
    { key: 'accountNumber', label: '계좌번호' },
    { key: 'accountHolder', label: '예금주' },
    { key: 'signature', label: '서명' },
    { key: 'bloodType', label: '혈액형' },
];

const QUICK_VIEW_PERSONAL_COLUMNS = ['name', 'idNumber', 'contact', 'address', 'unitPrice', 'bankName', 'accountNumber', 'accountHolder'];
const QUICK_VIEW_WORK_COLUMNS = ['name', 'role', 'salaryModel', 'teamName', 'companyName', 'status'];
const UNASSIGNED_TEAM_FILTER_ID = '__unassigned_team__';

interface WorkerDatabaseProps {
    hideHeader?: boolean;
    highlightedId?: string | null;
}

const WorkerDatabase: React.FC<WorkerDatabaseProps> = ({ hideHeader = false, highlightedId }) => {
    const [workers, setWorkers] = useState<Worker[]>([]);
    const [teams, setTeams] = useState<Team[]>([]);
    const [sites, setSites] = useState<Site[]>([]);
    const [companies, setCompanies] = useState<Company[]>([]);
    const [positions, setPositions] = useState<Position[]>([]); // 직책 데이터
    const [manpowerStats, setManpowerStats] = useState<{ [id: string]: number }>({}); // Added state
    const [searchTerm, setSearchTerm] = useState('');
    const [loading, setLoading] = useState(false);

    // Column Settings Hook
    const {
        visibleColumns,
        columnOrder,
        setColumnOrder,
        toggleColumn,
        showColumnSettings,
        setShowColumnSettings,
        resetColumns
    } = useColumnSettings('worker_registration_visible_columns', [
        { key: 'name', label: '이름' },
        { key: 'idNumber', label: '주민번호' },
        { key: 'contact', label: '연락처' },
        { key: 'address', label: '주소' },
        { key: 'role', label: '직책' },
        { key: 'salaryModel', label: '구분' },
        { key: 'teamName', label: '팀명' },
        { key: 'companyName', label: '회사' },
        { key: 'status', label: '상태' },
        { key: 'unitPrice', label: '단가' },
        { key: 'bankName', label: '은행' },
        { key: 'accountNumber', label: '계좌번호' },
        { key: 'accountHolder', label: '예금주' },
        { key: 'signature', label: '서명' },
        { key: 'bloodType', label: '혈액형' },
    ]);

    const [quickColumnView, setQuickColumnView] = useState<'personal' | 'work' | ''>('');

    const orderedVisibleColumnKeys = columnOrder.filter((key) => visibleColumns.includes(key));
    const effectiveVisibleColumnKeys = quickColumnView === 'personal'
        ? columnOrder.filter((key) => QUICK_VIEW_PERSONAL_COLUMNS.includes(key))
        : (quickColumnView === 'work'
            ? columnOrder.filter((key) => QUICK_VIEW_WORK_COLUMNS.includes(key))
            : orderedVisibleColumnKeys);
    const tableColSpan = effectiveVisibleColumnKeys.length + 2;

    const applyQuickView = (next: 'personal' | 'work') => {
        setShowColumnSettings(false);
        setQuickColumnView((prev) => (prev === next ? '' : next));
    };

    // Bulk Actions State
    const [selectedWorkerIds, setSelectedWorkerIds] = useState<string[]>([]);
    const [showLinkingModal, setShowLinkingModal] = useState(false);
    const [isBulkProgressOpen, setIsBulkProgressOpen] = useState(false);
    const [isBulkEditOpen, setIsBulkEditOpen] = useState(false);
    const [bulkProgress, setBulkProgress] = useState({ current: 0, total: 0, success: 0, fail: 0 });
    const [bulkLogs, setBulkLogs] = useState<string[]>([]);
    const [isBankBookModalOpen, setIsBankBookModalOpen] = useState(false);
    const [isIdCardAnalysisModalOpen, setIsIdCardAnalysisModalOpen] = useState(false);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [currentWorker, setCurrentWorker] = useState<Worker | null>(null);
    const [isEditMode, setIsEditMode] = useState(false);
    const [showInactive, setShowInactive] = useState(false); // Default: Hide inactive workers
    const [isStickyHeader, setIsStickyHeader] = useState(false); // Sticky header toggle
    const [selectedTeamId, setSelectedTeamId] = useState('');

    // Highlight scroll control (for Data Integrity "관리" navigation)
    const highlightScrolledRef = useRef(false);
    const lastHighlightIdRef = useRef<string | null>(null);

    // Signature Modal State
    const [isSignatureModalOpen, setIsSignatureModalOpen] = useState(false);
    const [signatureTargetWorker, setSignatureTargetWorker] = useState<{ id: string, name: string } | null>(null);

    const openSignatureModal = (worker: Worker) => {
        const id = String((worker.id || worker.legacyId || '') as any).trim();
        setSignatureTargetWorker({ id, name: worker.name });
        setIsSignatureModalOpen(true);
    };

    const handleSignatureSaveComplete = async (newUrl: string) => {
        if (signatureTargetWorker) {
            // Optimistic update
            setWorkers(prev =>
                prev.map(w =>
                    String(w.id ?? '').trim() === String(signatureTargetWorker.id).trim() || String(w.legacyId ?? '').trim() === String(signatureTargetWorker.id).trim()
                        ? { ...w, signatureUrl: newUrl }
                        : w
                )
            );
            // Real fetch to ensure consistency
            await fetchWorkers();
        }
    };

    // Handlers for Inline Editing
    const handleWorkerChange = (id: string, field: keyof Worker, value: any) => {
        setWorkers(prev => prev.map(w => w.id === id ? { ...w, [field]: value } : w));
    };

    const handleWorkerBlur = async (id: string, field: keyof Worker, value: any) => {
        try {
            await manpowerService.updateWorker(id, { [field]: value });
        } catch (error) {
            console.error("Update failed", error);
            fetchWorkers(); // Revert on error
        }
    };

    // 상태 값을 화면/기존 데이터 형식에 맞게 정규화
    const getCanonicalStatus = (status?: string): string => {
        if (!status) return '미배정';
        if (status === 'active') return '재직';
        if (status === 'inactive') return '퇴사';
        return status;
    };

    // 목록에서 바로 상태 변경 (토글/셀렉트 공통 사용)
    const handleStatusChange = async (workerId: string, newStatus: string) => {
        if (!workerId) return;

        // Optimistic UI 업데이트
        setWorkers(prev => prev.map(w => w.id === workerId ? { ...w, status: newStatus } : w));

        try {
            await manpowerService.updateWorker(workerId, { status: newStatus });
        } catch (error) {
            console.error('Failed to update worker status', error);
            alert('상태 변경에 실패했습니다. 다시 시도해 주세요.');
            // 실패 시 최신 데이터로 롤백
            fetchWorkers();
        }
    };

    const handleWorkerTeamSelect = async (workerId: string, teamId: string) => {
        if (!teamId) {
            // Unassign
            setWorkers(prev => prev.map(w => w.id === workerId ? { ...w, teamId: '', teamName: '', teamType: '미배정' } : w));
            await manpowerService.updateWorker(workerId, { teamId: '', teamName: '', teamType: '미배정' });
            return;
        }

        const team = teams.find(t => t.id === teamId);
        if (team) {
            // 팀의 회사 정보도 함께 설정
            const teamCompany = team.companyId ? companies.find(c => c.id === team.companyId) : null;

            // 회사 유형에 따라 급여방식 결정 (협력사면 지원팀, 아니면 팀의 defaultSalaryModel 우선 적용)
            const worker = workers.find(w => w.id === workerId);
            const isPartnerCompany = teamCompany?.type === '협력사';
            const newSalaryModel = isPartnerCompany ? '지원팀' : (worker?.salaryModel || team.defaultSalaryModel || '일급제');

            const updates = {
                teamId: team.id,
                teamName: team.name,
                teamType: team.type,
                companyId: team.companyId || '',
                companyName: team.companyName || '',
                salaryModel: newSalaryModel,
                payType: newSalaryModel
            };

            setWorkers(prev => prev.map(w => w.id === workerId ? { ...w, ...updates } : w));
            try {
                await manpowerService.updateWorker(workerId, updates);
            } catch (e) {
                console.error(e);
                fetchWorkers();
            }
        }
    };

    const handleWorkerSiteSelect = async (workerId: string, siteId: string) => {
        if (!siteId) {
            setWorkers(prev => prev.map(w => w.id === workerId ? { ...w, siteId: '', siteName: '' } : w));
            await manpowerService.updateWorker(workerId, { siteId: '', siteName: '' });
            return;
        }
        const site = sites.find(s => s.id === siteId);
        if (site) {
            setWorkers(prev => prev.map(w => w.id === workerId ? { ...w, siteId: site.id, siteName: site.name } : w));
            await manpowerService.updateWorker(workerId, { siteId: site.id, siteName: site.name });
        }
    }

    const handleWorkerCompanySelect = async (workerId: string, companyId: string) => {
        if (!companyId) {
            setWorkers(prev => prev.map(w => w.id === workerId ? { ...w, companyId: '', companyName: '' } : w));
            await manpowerService.updateWorker(workerId, { companyId: '', companyName: '' });
            return;
        }
        const company = companies.find(c => c.id === companyId);
        if (company) {
            setWorkers(prev => prev.map(w => w.id === workerId ? { ...w, companyId: company.id, companyName: company.name } : w));
            await manpowerService.updateWorker(workerId, { companyId: company.id, companyName: company.name });
        }
    }

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setLoading(true);
        try {
            const [workersData, teamsData, sitesData, companiesData, positionsData] = await Promise.all([
                manpowerService.getWorkers(),
                teamService.getTeams(),
                siteService.getSites(),
                companyService.getCompanies(),
                positionService.getPositions()
            ]);

            setWorkers(workersData);
            setTeams(teamsData);
            setSites(sitesData);
            setCompanies(companiesData);
            setPositions(positionsData);
        } catch (error) {
            console.error("Failed to fetch data:", error);
        } finally {
            setLoading(false);
        }
    };

    const fetchWorkers = async () => {
        try {
            const workersData = await manpowerService.getWorkers();
            setWorkers(workersData);
        } catch (error) {
            console.error("Failed to fetch workers:", error);
        }
    };

    // 작업자 삭제
    const handleDelete = async (workerId: string, workerName: string) => {
        if (window.confirm(`[${workerName}] 작업자를 영구 삭제하시겠습니까?\n이 작업은 되돌릴 수 없습니다.`)) {
            try {
                await manpowerService.deleteWorker(workerId);
                alert('작업자가 삭제되었습니다.');
                await fetchWorkers();
            } catch (error) {
                console.error("삭제 실패:", error);
                alert('삭제 중 오류가 발생했습니다.');
            }
        }
    };


    // 필터링된 작업자 목록
    const filteredWorkers = workers.filter(worker => {
        const lowerSearch = searchTerm.trim().toLowerCase();
        const selectedTeamNameForFilter = teams.find((team) => team.id === selectedTeamId)?.name?.trim() ?? '';
        const workerTeamId = String(worker.teamId ?? '').trim();
        const workerTeamName = String(worker.teamName ?? '').trim();
        const matchesTeam = !selectedTeamId
            ? true
            : selectedTeamId === UNASSIGNED_TEAM_FILTER_ID
                ? !workerTeamId && !workerTeamName
                : workerTeamId === selectedTeamId || (!workerTeamId && selectedTeamNameForFilter.length > 0 && workerTeamName === selectedTeamNameForFilter);

        // Status filter: If showInactive is false, only show 'active'/'재직' or 'unassigned'/'미배정'.
        const isActive = worker.status === '재직' || worker.status === 'active' || worker.status === '미배정' || !worker.status;
        if (!showInactive && !isActive) return false;
        if (!matchesTeam) return false;

        if (!lowerSearch) return true;

        return (
            worker.name.toLowerCase().includes(lowerSearch) ||
            String(worker.idNumber ?? '').toLowerCase().includes(lowerSearch) ||
            String(worker.contact ?? '').toLowerCase().includes(lowerSearch) ||
            String(worker.teamName ?? '').toLowerCase().includes(lowerSearch)
        );
    });

    // 선택 기능
    const selectedTeamName = React.useMemo(
        () => teams.find((team) => team.id === selectedTeamId)?.name?.trim() ?? '',
        [teams, selectedTeamId]
    );

    const teamFilterOptions = React.useMemo(() => {
        const teamNameToId = new Map<string, string>();
        const teamCounts = new Map<string, number>();
        let unassignedCount = 0;

        teams.forEach((team) => {
            const normalizedName = String(team.name ?? '').trim().toLowerCase();
            if (team.id && normalizedName) {
                teamNameToId.set(normalizedName, team.id);
            }
        });

        workers.forEach((worker) => {
            const rawTeamId = String(worker.teamId ?? '').trim();
            if (rawTeamId) {
                teamCounts.set(rawTeamId, (teamCounts.get(rawTeamId) ?? 0) + 1);
                return;
            }

            const normalizedTeamName = String(worker.teamName ?? '').trim().toLowerCase();
            const mappedTeamId = normalizedTeamName ? teamNameToId.get(normalizedTeamName) : undefined;
            if (mappedTeamId) {
                teamCounts.set(mappedTeamId, (teamCounts.get(mappedTeamId) ?? 0) + 1);
                return;
            }

            unassignedCount += 1;
        });

        const options = [...teams]
            .filter((team) => Boolean(team.id))
            .sort((a, b) => a.name.localeCompare(b.name, 'ko'))
            .map((team) => ({
                id: team.id!,
                name: `${team.name} (${teamCounts.get(team.id!) ?? 0}명)`
            }));

        if (unassignedCount > 0) {
            options.unshift({
                id: UNASSIGNED_TEAM_FILTER_ID,
                name: `미배정 (${unassignedCount}명)`
            });
        }

        return options;
    }, [teams, workers]);

    const toggleSelectAll = () => {
        if (selectedWorkerIds.length === filteredWorkers.length && filteredWorkers.length > 0) {
            setSelectedWorkerIds([]);
        } else {
            setSelectedWorkerIds(filteredWorkers.map(w => w.id!).filter(Boolean));
        }
    };

    const toggleSelectWorker = (id: string) => {
        if (selectedWorkerIds.includes(id)) {
            setSelectedWorkerIds(selectedWorkerIds.filter(wid => wid !== id));
        } else {
            setSelectedWorkerIds([...selectedWorkerIds, id]);
        }
    };

    // 일괄 삭제
    const handleBulkDelete = async () => {
        if (selectedWorkerIds.length === 0) return;

        if (window.confirm(`선택한 ${selectedWorkerIds.length}명의 작업자를 정말 퇴사 처리하시겠습니까? (일보 이력은 유지됩니다)`)) {
            try {
                await manpowerService.retireWorkers(selectedWorkerIds);
                setSelectedWorkerIds([]);
                await fetchWorkers();
                alert("일괄 퇴사 처리되었습니다.");
            } catch (error) {
                console.error("Failed to delete workers", error);
                alert("일괄 퇴사 처리에 실패했습니다.");
            }
        }
    };



    // 선택 항목 다운로드 (신분증)
    const handleBulkDownload = async () => {
        if (selectedWorkerIds.length === 0) return;

        const workersToDownload = workers.filter(w => selectedWorkerIds.includes(w.id!) && w.fileNameSaved);
        if (workersToDownload.length === 0) {
            alert("선택한 작업자 중 다운로드할 신분증 이미지가 없습니다.");
            return;
        }

        setIsBulkProgressOpen(true);
        setBulkProgress({ current: 0, total: workersToDownload.length, success: 0, fail: 0 });
        setBulkLogs([]);

        const zip = new JSZip();
        let successCount = 0;
        let failCount = 0;

        for (let i = 0; i < workersToDownload.length; i++) {
            const worker = workersToDownload[i];
            setBulkProgress(prev => ({ ...prev, current: i + 1 }));

            try {
                // Use getBlob directly from SDK
                const blob = await getBlob(ref(storage, worker.fileNameSaved!));

                const ext = worker.fileNameSaved!.split('.').pop() || 'jpg';
                const cleanName = (worker.name || '').replace(/[0-9]/g, '');
                const filename = `${cleanName}_${worker.idNumber}.${ext}`;

                zip.file(filename, blob);

                successCount++;
                setBulkLogs(prev => [`[성공] ${worker.name} 이미지 다운로드 완료`, ...prev]);
            } catch (error: any) {
                console.error(error);
                failCount++;
                // Try to provide a helpful error message
                let msg = error.code === 'storage/unauthorized' ? '권한 없음' :
                    error.code === 'storage/object-not-found' ? '파일 없음' :
                        error.message;
                setBulkLogs(prev => [`[실패] ${worker.name}: ${msg}`, ...prev]);
            }
            setBulkProgress(prev => ({ ...prev, success: successCount, fail: failCount }));
        }

        if (successCount > 0) {
            setBulkLogs(prev => [`[압축] 파일 압축 중...`, ...prev]);
            try {
                const content = await zip.generateAsync({ type: "blob" });
                saveAs(content, `신분증_모음_${new Date().toISOString().slice(0, 10)}.zip`);
                setBulkLogs(prev => [`[완료] 다운로드 시작`, ...prev]);
            } catch (zipError) {
                console.error("Zip generation failed:", zipError);
                setBulkLogs(prev => [`[오류] 압축 파일 생성 실패`, ...prev]);
            }
        } else {
            setBulkLogs(prev => [`[알림] 다운로드 가능한 파일이 없습니다.`, ...prev]);
        }
    };



    // 개별 신분증 다운로드
    const handleDownloadIdCard = async (worker: Worker) => {
        if (!worker.fileNameSaved) {
            alert("등록된 신분증 이미지가 없습니다.");
            return;
        }

        try {
            const url = await getDownloadURL(ref(storage, worker.fileNameSaved));

            const ext = worker.fileNameSaved.split('.').pop() || 'jpg';
            const safeIdNumber = worker.idNumber || '미등록';
            const cleanName = (worker.name || '').replace(/[0-9]/g, '');
            const filename = `${cleanName}_${safeIdNumber}.${ext}`;

            const downloadUrl = new URL(url);
            downloadUrl.searchParams.set(
                'response-content-disposition',
                `attachment; filename*=UTF-8''${encodeURIComponent(filename)}`
            );

            const anchor = document.createElement('a');
            anchor.href = downloadUrl.toString();
            anchor.rel = 'noopener noreferrer';
            anchor.style.display = 'none';
            document.body.appendChild(anchor);
            anchor.click();
            anchor.remove();
        } catch (error: unknown) {
            console.error("Download failed:", error);
            alert("파일을 찾을 수 없거나 접근 권한이 없습니다.");
        }
    };

    const handleSaveWorker = async (workerData: Omit<Worker, 'id'> | Partial<Worker>) => {
        try {
            if (currentWorker && currentWorker.id) {
                await manpowerService.updateWorker(currentWorker.id, workerData);
            } else {
                // 신규 등록 시 중복 체크
                const name = (workerData as any).name;
                const existingWorker = workers.find(w => w.name === name);

                if (existingWorker) {
                    if (window.confirm(`'${name}' 작업자가 이미 존재합니다.\n기존 정보를 업데이트하시겠습니까?`)) {
                        await manpowerService.updateWorker(existingWorker.id!, workerData);
                    } else {
                        return; // 취소 시 중단
                    }
                } else {
                    await manpowerService.addWorker(workerData as Omit<Worker, 'id'>);
                }
            }
            fetchWorkers();
            setIsModalOpen(false);
        } catch (error) {
            console.error("Failed to save worker", error);
            const message = error instanceof Error ? error.message : (typeof error === 'string' ? error : '저장에 실패했습니다.');
            alert(message);
        }
    };

    const handleBankBookUpdate = async (updates: { workerId: string, bankName: string, accountNumber: string, accountHolder: string }[]) => {
        setLoading(true);
        try {
            await Promise.all(updates.map(update =>
                manpowerService.updateWorker(update.workerId, {
                    bankName: update.bankName,
                    accountNumber: update.accountNumber,
                    accountHolder: update.accountHolder
                })
            ));
            alert(`${updates.length}명의 계좌정보가 업데이트되었습니다.`);
            await fetchData(); // 데이터 새로고침
        } catch (error) {
            console.error("Batch update failed", error);
            alert("일부 업데이트에 실패했습니다.");
        } finally {
            setLoading(false);
        }
    };

    const handleIdCardRegister = async (newWorkers: {
        name: string,
        idNumber: string,
        address: string,
        file: File,
        matchType: 'new' | 'update' | 'duplicate',
        matchedWorkerId?: string
    }[]) => {
        setLoading(true);
        setIsBulkProgressOpen(true);
        setBulkProgress({ current: 0, total: newWorkers.length, success: 0, fail: 0 });
        setBulkLogs([]);

        let successCount = 0;
        let failCount = 0;

        for (let i = 0; i < newWorkers.length; i++) {
            const worker = newWorkers[i];
            setBulkProgress(prev => ({ ...prev, current: i + 1 }));

            try {
                // 1. Upload image to Firebase Storage
                const storagePath = `id_cards/${Date.now()}_${worker.file.name}`;
                const storageRef = ref(storage, storagePath);
                await uploadBytes(storageRef, worker.file);

                // 2. 분기 처리: 신규 / 업데이트 / 중복
                let processed = false;

                if (worker.matchType === 'new') {
                    // 신규 작업자 생성
                    await manpowerService.addWorker({
                        name: worker.name,
                        idNumber: worker.idNumber,
                        address: worker.address,
                        role: '작업자',
                        teamType: '미배정',
                        status: '미배정',
                        unitPrice: 0,
                        fileNameSaved: storagePath
                    });
                    setBulkLogs(prev => [`[신규] ${worker.name} 등록 완료`, ...prev]);
                    processed = true;
                } else if (worker.matchType === 'update' && worker.matchedWorkerId) {
                    // 기존 작업자 업데이트 (누락 필드만)
                    const updates: Partial<Worker> = { fileNameSaved: storagePath };
                    if (worker.name) updates.name = worker.name;
                    if (worker.idNumber) updates.idNumber = worker.idNumber;
                    if (worker.address) updates.address = worker.address;

                    await manpowerService.updateWorker(worker.matchedWorkerId, updates);
                    setBulkLogs(prev => [`[업데이트] ${worker.name} 정보 보충 완료`, ...prev]);
                    processed = true;
                } else if (worker.matchType === 'duplicate' && worker.matchedWorkerId) {
                    // 중복 - 사진만 업데이트
                    await manpowerService.updateWorker(worker.matchedWorkerId, {
                        fileNameSaved: storagePath
                    });
                    setBulkLogs(prev => [`[사진] ${worker.name} 신분증 사진 업데이트`, ...prev]);
                    processed = true;
                }

                if (processed) {
                    successCount++;
                } else {
                    failCount++;
                    const reason = !worker.matchedWorkerId ? '매칭된 작업자 ID 없음' : '알 수 없는 유형';
                    setBulkLogs(prev => [`[실패] ${worker.name}: 처리되지 않음 (${worker.matchType}, ${reason})`, ...prev]);
                }
            } catch (error: any) {
                console.error(error);
                failCount++;
                // Try to provide a helpful error message
                let msg = error.code === 'storage/unauthorized' ? '권한 없음' :
                    error.code === 'storage/object-not-found' ? '파일 없음' :
                        error.message;
                setBulkLogs(prev => [`[실패] ${worker.name}: ${msg}`, ...prev]);
            }
            setBulkProgress(prev => ({ ...prev, success: successCount, fail: failCount }));
        }

        setLoading(false);
        fetchWorkers();
        // Keep progress modal open to show results
    };

    return (
        <div className="flex flex-col h-full bg-slate-50">
            {/* Header & Toolbar - Single Row */}
            <div className={`bg-white border-b border-slate-200 p-4 flex flex-col xl:flex-row items-start xl:items-center justify-between gap-4 flex-shrink-0 ${!hideHeader ? 'border-t-0' : ''}`}>
                {!hideHeader && (
                    <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2 whitespace-nowrap">
                        <FontAwesomeIcon icon={faUsers} className="text-blue-600" />
                        작업자 등록 관리
                    </h2>
                )}

                <div className="flex flex-wrap items-center gap-2 w-full xl:w-auto xl:ml-auto justify-end">
                    {/* 열 설정 */}
                    <button
                        onClick={() => setShowColumnSettings(!showColumnSettings)}
                        className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 text-slate-600 rounded-lg hover:bg-slate-50 transition-colors shadow-sm whitespace-nowrap relative"
                    >
                        <FontAwesomeIcon icon={faTable} />
                        <span className="hidden sm:inline">열 설정</span>
                        {showColumnSettings && (
                            <div className="absolute top-full right-0 mt-2 w-72 bg-white rounded-lg shadow-xl border border-slate-200 z-50 p-3 text-left" onClick={e => e.stopPropagation()}>
                                <div className="text-xs font-bold text-slate-700 mb-3 px-1 flex items-center justify-between">
                                    <span>열 표시 및 순서 설정</span>
                                    <button
                                        onClick={() => {
                                            resetColumns();
                                        }}
                                        className="text-xs text-blue-600 hover:text-blue-700 font-normal"
                                    >
                                        초기화
                                    </button>
                                </div>
                                <div className="space-y-1 max-h-96 overflow-y-auto">
                                    {columnOrder.map((key) => {
                                        const col = WORKER_COLUMNS.find(c => c.key === key);
                                        if (!col) return null;

                                        const isVisible = visibleColumns.includes(col.key);
                                        const currentIndex = columnOrder.indexOf(col.key);

                                        return (
                                            <div
                                                key={col.key}
                                                className={`flex items-center gap-2 px-2 py-2 rounded hover:bg-slate-50 ${!isVisible ? 'opacity-50' : ''}`}
                                            >
                                                <button
                                                    onClick={() => toggleColumn(col.key)}
                                                    className={`flex-shrink-0 w-6 h-6 rounded flex items-center justify-center transition-colors ${isVisible ? 'bg-blue-500 text-white' : 'bg-slate-200 text-slate-400'}`}
                                                    title={isVisible ? '숨기기' : '표시'}
                                                >
                                                    <FontAwesomeIcon icon={isVisible ? faEye : faEyeSlash} className="text-xs" />
                                                </button>
                                                <span className="flex-1 text-sm text-slate-700">{col.label}</span>
                                                <div className="flex gap-1">
                                                    <button
                                                        onClick={() => {
                                                            if (currentIndex > 0) {
                                                                const nextOrder = [...columnOrder];
                                                                const temp = nextOrder[currentIndex - 1];
                                                                nextOrder[currentIndex - 1] = nextOrder[currentIndex];
                                                                nextOrder[currentIndex] = temp;
                                                                setColumnOrder(nextOrder);
                                                            }
                                                        }}
                                                        disabled={currentIndex === 0}
                                                        className={`w-6 h-6 rounded flex items-center justify-center transition-colors ${currentIndex === 0 ? 'bg-slate-100 text-slate-300 cursor-not-allowed' : 'bg-slate-200 text-slate-600 hover:bg-slate-300'}`}
                                                        title="위로"
                                                    >
                                                        <FontAwesomeIcon icon={faArrowUp} className="text-xs" />
                                                    </button>
                                                    <button
                                                        onClick={() => {
                                                            if (currentIndex < columnOrder.length - 1) {
                                                                const nextOrder = [...columnOrder];
                                                                const temp = nextOrder[currentIndex + 1];
                                                                nextOrder[currentIndex + 1] = nextOrder[currentIndex];
                                                                nextOrder[currentIndex] = temp;
                                                                setColumnOrder(nextOrder);
                                                            }
                                                        }}
                                                        disabled={currentIndex === columnOrder.length - 1}
                                                        className={`w-6 h-6 rounded flex items-center justify-center transition-colors ${currentIndex === columnOrder.length - 1 ? 'bg-slate-100 text-slate-300 cursor-not-allowed' : 'bg-slate-200 text-slate-600 hover:bg-slate-300'}`}
                                                        title="아래로"
                                                    >
                                                        <FontAwesomeIcon icon={faArrowDown} className="text-xs" />
                                                    </button>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                                <div className="fixed inset-0 -z-10" onClick={() => setShowColumnSettings(false)}></div>
                            </div>
                        )}
                    </button>

                    <button
                        onClick={() => applyQuickView('personal')}
                        className={`flex items-center gap-2 px-3 py-2 rounded-lg transition-all shadow-sm whitespace-nowrap ${quickColumnView === 'personal'
                            ? 'bg-blue-100 text-blue-700 border border-blue-200'
                            : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'
                            }`}
                    >
                        <FontAwesomeIcon icon={faMoneyCheck} />
                        <span className="hidden sm:inline">개인/급여</span>
                    </button>

                    <button
                        onClick={() => applyQuickView('work')}
                        className={`flex items-center gap-2 px-3 py-2 rounded-lg transition-all shadow-sm whitespace-nowrap ${quickColumnView === 'work'
                            ? 'bg-emerald-100 text-emerald-700 border border-emerald-200'
                            : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'
                            }`}
                    >
                        <FontAwesomeIcon icon={faUsers} />
                        <span className="hidden sm:inline">소속/상태</span>
                    </button>

                    {/* 계정 연결 */}
                    <button
                        onClick={() => setShowLinkingModal(true)}
                        title="계정 연동"
                        className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 text-slate-600 rounded-lg hover:bg-slate-50 transition-colors shadow-sm whitespace-nowrap"
                    >
                        <FontAwesomeIcon icon={faLink} className="text-slate-500" />
                        <span className="hidden sm:inline">계정 연결</span>
                    </button>

                    {/* 신분증 등록 */}
                    {/* 신분증 등록 - Modal Trigger */}
                    <button
                        onClick={() => setIsIdCardAnalysisModalOpen(true)}
                        title="신분증 대량 등록 (AI)"
                        className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 text-slate-600 rounded-lg hover:bg-slate-50 transition-colors shadow-sm whitespace-nowrap"
                    >
                        <FontAwesomeIcon icon={faImages} className="text-brand-600" />
                        <span className="hidden sm:inline">신분증 등록</span>
                    </button>

                    {/* 수정모드 */}
                    <button
                        onClick={() => setIsEditMode(!isEditMode)}
                        className={`flex items-center gap-2 px-3 py-2 rounded-lg transition-all shadow-sm whitespace-nowrap ${isEditMode
                            ? 'bg-indigo-100 text-indigo-700 border border-indigo-200'
                            : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'
                            }`}
                    >
                        <FontAwesomeIcon icon={faPenToSquare} />
                        <span className="hidden sm:inline">{isEditMode ? '수정 종료' : '수정모드'}</span>
                    </button>

                    {/* 선택 다운로드 */}
                    <button
                        onClick={handleBulkDownload}
                        disabled={selectedWorkerIds.length === 0}
                        title="선택 항목 다운로드"
                        className={`flex items-center gap-2 px-3 py-2 rounded-lg transition-all shadow-sm whitespace-nowrap ${selectedWorkerIds.length > 0
                            ? 'bg-blue-100 text-blue-600 hover:bg-blue-200 border border-blue-200'
                            : 'bg-slate-100 text-slate-400 cursor-not-allowed'
                            }`}
                    >
                        <FontAwesomeIcon icon={faDownload} />
                        <span className="hidden sm:inline">선택 다운로드</span>
                    </button>

                    {/* 일괄 수정 */}
                    <button
                        onClick={() => setIsBulkEditOpen(true)}
                        disabled={selectedWorkerIds.length === 0}
                        title="일괄 수정"
                        className={`flex items-center gap-2 px-3 py-2 rounded-lg transition-all shadow-sm whitespace-nowrap ${selectedWorkerIds.length > 0
                            ? 'bg-indigo-100 text-indigo-600 hover:bg-indigo-200 border border-indigo-200'
                            : 'bg-slate-100 text-slate-400 cursor-not-allowed'
                            }`}
                    >
                        <FontAwesomeIcon icon={faEdit} />
                        <span className="hidden sm:inline">일괄 수정</span>
                    </button>

                    {/* 일괄 삭제 */}
                    <button
                        onClick={handleBulkDelete}
                        disabled={selectedWorkerIds.length === 0}
                        title="일괄 삭제"
                        className={`flex items-center gap-2 px-3 py-2 rounded-lg transition-all shadow-sm whitespace-nowrap ${selectedWorkerIds.length > 0
                            ? 'bg-red-100 text-red-600 hover:bg-red-200 border border-red-200'
                            : 'bg-slate-100 text-slate-400 cursor-not-allowed'
                            }`}
                    >
                        <FontAwesomeIcon icon={faTrash} />
                        <span className="hidden sm:inline">일괄 삭제</span>
                    </button>

                    {/* 근로자 등록 */}
                    <button
                        onClick={() => {
                            setCurrentWorker(null);
                            setIsModalOpen(true);
                        }}
                        title="근로자 등록"
                        className="flex items-center gap-2 px-3 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors shadow-sm shadow-indigo-200 whitespace-nowrap ml-auto xl:ml-0"
                    >
                        <FontAwesomeIcon icon={faPlus} />
                        근로자 등록
                    </button>
                </div>
            </div>

            {/* 검색 및 목록 - Content Area */}
            <div className={`flex-1 overflow-auto ${!hideHeader ? 'p-6 pb-80' : 'pb-80'}`}>
                <div className="bg-white border border-gray-200 rounded-lg shadow-sm">
                    <div className="p-4 border-b border-gray-200 flex items-center justify-between">
                        <h3 className="text-md font-semibold text-gray-800 flex items-center gap-2">
                            <FontAwesomeIcon icon={faUsers} className="text-blue-600" />
                            등록된 작업자 ({filteredWorkers.length}명)
                        </h3>
                        <div className="flex items-center gap-4">
                            <label className="flex items-center gap-2 text-sm text-gray-600 cursor-pointer">
                                <input
                                    type="checkbox"
                                    checked={showInactive}
                                    onChange={(e) => setShowInactive(e.target.checked)}
                                    className="rounded text-indigo-600 focus:ring-indigo-500"
                                />
                                퇴사자 포함
                            </label>
                            <label className="flex items-center gap-2 text-sm text-gray-600 cursor-pointer bg-white px-2 py-1 rounded border border-gray-200 hover:bg-gray-50">
                                <input
                                    type="checkbox"
                                    checked={isStickyHeader}
                                    onChange={(e) => setIsStickyHeader(e.target.checked)}
                                    className="rounded text-indigo-600 focus:ring-indigo-500"
                                />
                                목록 고정
                            </label>
                            <div className="flex items-center gap-2">
                                <FontAwesomeIcon icon={faSearch} className="text-gray-400" />
                                <input
                                    type="text"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    placeholder="이름, 주민번호, 연락처 검색"
                                    className="px-3 py-1 border border-gray-300 rounded text-sm focus:ring-1 focus:ring-blue-500 focus:border-blue-500 w-64"
                                />
                            </div>
                            <div className="flex items-center gap-2">
                                <span className="text-sm text-gray-600 whitespace-nowrap">팀</span>
                                <div className="w-56 min-w-[14rem]">
                                    <SingleSelectPopover
                                        options={teamFilterOptions}
                                        selectedId={selectedTeamId}
                                        onSelect={(id) => setSelectedTeamId(id)}
                                        placeholder="전체 팀"
                                    />
                                </div>
                            </div>
                            {selectedTeamId && (
                                <div className="text-xs text-slate-500 whitespace-nowrap">
                                    조회 팀: {teamFilterOptions.find((option) => option.id === selectedTeamId)?.name ?? selectedTeamName}
                                </div>
                            )}
                        </div>
                    </div>

                    <div className={`overflow-auto ${isStickyHeader ? 'h-[calc(100vh-250px)] border-b border-gray-200' : 'pb-80'}`}>
                        <table className="w-full text-sm">
                            <thead className={`bg-slate-900 text-white ${isStickyHeader ? 'sticky top-0 z-10' : ''}`}>
                                <tr>
                                    <th className="px-4 py-3 text-center w-12 border border-slate-700">
                                        <button onClick={toggleSelectAll} className="text-gray-500 hover:text-gray-700">
                                            <FontAwesomeIcon icon={selectedWorkerIds.length === filteredWorkers.length && filteredWorkers.length > 0 ? faCheckSquare : faSquare} />
                                        </button>
                                    </th>
                                    {effectiveVisibleColumnKeys.map((key) => {
                                        const col = WORKER_COLUMNS.find(c => c.key === key);
                                        if (!col) return null;
                                        const alignClass = col.key === 'unitPrice'
                                            ? 'text-right'
                                            : col.key === 'signature'
                                                ? 'text-center'
                                                : 'text-left';
                                        return (
                                            <th key={col.key} className={`px-4 py-3 ${alignClass} font-medium text-white border border-slate-700`}>
                                                {col.label}
                                            </th>
                                        );
                                    })}
                                    <th className="px-4 py-3 text-center font-medium text-white border border-slate-700">관리</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {loading ? (
                                    <tr>
                                        <td colSpan={tableColSpan} className="px-4 py-8 text-center text-gray-500">
                                            데이터를 불러오는 중입니다...
                                        </td>
                                    </tr>
                                ) : filteredWorkers.length === 0 ? (
                                    <tr>
                                        <td colSpan={tableColSpan} className="px-4 py-8 text-center text-gray-500">
                                            등록된 작업자가 없습니다.
                                        </td>
                                    </tr>
                                ) : (
                                    filteredWorkers.map((worker) => {
                                        const isInactive = worker.status === '퇴사' || worker.status === 'inactive' || worker.status === '출입금지';
                                        const workerTeam = worker.teamId ? teams.find(t => t.id === worker.teamId) : undefined;
                                        const workerCompany = worker.companyId ? companies.find(c => c.id === worker.companyId) : undefined;
                                        const iconColor = workerTeam?.color || worker.color || '#e5e7eb';
                                        const isHighlighted = worker.id === highlightedId;

                                        return (
                                            <tr
                                                key={worker.id}
                                                className={`border-b transition-colors 
                                                    ${isHighlighted ? 'bg-red-50 border border-red-300 ring-1 ring-red-300 z-10 relative' :
                                                        selectedWorkerIds.includes(worker.id!) ? 'bg-indigo-50' :
                                                            'hover:bg-gray-50'} 
                                                    ${isInactive && !isHighlighted ? 'bg-slate-50 text-slate-400' : ''}
                                                `}
                                                ref={isHighlighted
                                                    ? (el) => {
                                                        if (!el) return;
                                                        // Reset scroll flag when highlighted target changes
                                                        const currentId = highlightedId || null;
                                                        if (lastHighlightIdRef.current !== currentId) {
                                                            lastHighlightIdRef.current = currentId;
                                                            highlightScrolledRef.current = false;
                                                        }
                                                        // Scroll only once per highlightedId
                                                        if (!highlightScrolledRef.current) {
                                                            el.scrollIntoView({ behavior: 'smooth', block: 'center' });
                                                            highlightScrolledRef.current = true;
                                                        }
                                                    }
                                                    : null}
                                            >
                                                <td className="px-4 py-3 text-center border border-slate-200">
                                                    <button onClick={() => toggleSelectWorker(worker.id!)} className={`${selectedWorkerIds.includes(worker.id!) ? 'text-indigo-600' : 'text-gray-400'} hover:text-indigo-600`}>
                                                        <FontAwesomeIcon icon={selectedWorkerIds.includes(worker.id!) ? faCheckSquare : faSquare} />
                                                    </button>
                                                </td>
                                                {effectiveVisibleColumnKeys.map((key) => {
                                                    switch (key) {
                                                        case 'name':
                                                            return (
                                                                <td key={key} className="px-4 py-3 font-medium text-gray-900 border border-slate-200">
                                                                    {isEditMode ? (
                                                                        <div className="flex items-center gap-2">
                                                                            <input
                                                                                type="color"
                                                                                value={worker.color || '#0f766e'}
                                                                                onChange={(e) => handleWorkerChange(worker.id!, 'color', e.target.value)}
                                                                                onBlur={(e) => handleWorkerBlur(worker.id!, 'color', e.target.value)}
                                                                                className="h-8 w-8 rounded border border-slate-300 cursor-pointer"
                                                                            />
                                                                            <input
                                                                                type="text"
                                                                                value={worker.name}
                                                                                onChange={(e) => handleWorkerChange(worker.id!, 'name', e.target.value)}
                                                                                onBlur={(e) => handleWorkerBlur(worker.id!, 'name', e.target.value)}
                                                                                className="w-full border rounded px-2 py-1 text-sm"
                                                                            />
                                                                        </div>
                                                                    ) : (
                                                                        <div className="flex items-center gap-2">
                                                                            <span
                                                                                className="inline-flex items-center justify-center w-7 h-7 rounded-full border border-slate-200 flex-shrink-0"
                                                                                style={{ backgroundColor: iconColor }}
                                                                            >
                                                                                <FontAwesomeIcon icon={faUser} className="text-white text-xs" />
                                                                            </span>
                                                                            <span className="truncate">{worker.name}</span>
                                                                            {worker.fileNameSaved && (
                                                                                <button
                                                                                    onClick={(e) => {
                                                                                        e.stopPropagation();
                                                                                        handleDownloadIdCard(worker);
                                                                                    }}
                                                                                    className="text-slate-400 hover:text-indigo-600 transition-colors ml-1"
                                                                                    title="신분증 다운로드"
                                                                                >
                                                                                    <FontAwesomeIcon icon={faIdCard} size="sm" />
                                                                                </button>
                                                                            )}
                                                                            {isInactive && <span className="px-1.5 py-0.5 rounded text-[10px] bg-gray-200 text-gray-500">퇴사</span>}
                                                                        </div>
                                                                    )}
                                                                </td>
                                                            );
                                                        case 'idNumber':
                                                            return (
                                                                <td key={key} className="px-4 py-3 text-gray-600 border border-slate-200">
                                                                    {isEditMode ? (
                                                                        <input
                                                                            type="text"
                                                                            value={worker.idNumber}
                                                                            onChange={(e) => handleWorkerChange(worker.id!, 'idNumber', e.target.value)}
                                                                            onBlur={(e) => handleWorkerBlur(worker.id!, 'idNumber', e.target.value)}
                                                                            className="w-full border rounded px-2 py-1 text-sm"
                                                                        />
                                                                    ) : worker.idNumber}
                                                                </td>
                                                            );
                                                        case 'contact':
                                                            return (
                                                                <td key={key} className="px-4 py-3 text-gray-600 border border-slate-200">
                                                                    <InputPopover
                                                                        value={worker.contact || ''}
                                                                        type="tel"
                                                                        placeholder="연락처"
                                                                        onChange={(val) => {
                                                                            handleWorkerChange(worker.id!, 'contact', String(val));
                                                                            handleWorkerBlur(worker.id!, 'contact', String(val));
                                                                        }}
                                                                        minimal={!isEditMode}
                                                                        formatDisplay={(val) => val || '-'}
                                                                    />
                                                                </td>
                                                            );
                                                        case 'address':
                                                            return (
                                                                <td key={key} className="px-4 py-3 text-gray-600 border border-slate-200">
                                                                    <InputPopover
                                                                        value={worker.address || ''}
                                                                        placeholder="주소"
                                                                        onChange={(val) => {
                                                                            handleWorkerChange(worker.id!, 'address', String(val));
                                                                            handleWorkerBlur(worker.id!, 'address', String(val));
                                                                        }}
                                                                        minimal={!isEditMode}
                                                                        formatDisplay={(val) => <span className="truncate max-w-[200px] inline-block" title={String(val)}>{val || '-'}</span>}
                                                                    />
                                                                </td>
                                                            );
                                                        case 'role': {
                                                            const workerPosition = positions.find(p => p.name === worker.role);
                                                            const posColor = workerPosition?.color || 'gray';
                                                            const colorClass = {
                                                                red: 'bg-red-500',
                                                                orange: 'bg-orange-500',
                                                                yellow: 'bg-yellow-500',
                                                                green: 'bg-emerald-500',
                                                                blue: 'bg-blue-500',
                                                                indigo: 'bg-indigo-500',
                                                                purple: 'bg-purple-500',
                                                                pink: 'bg-pink-500',
                                                                gray: 'bg-slate-500',
                                                                slate: 'bg-slate-500',
                                                                black: 'bg-slate-900',
                                                            }[posColor] || 'bg-slate-500';

                                                            return (
                                                                <td key={key} className="px-4 py-3 text-gray-600 border border-slate-200">
                                                                    <div className="w-full">
                                                                        <SingleSelectPopover
                                                                            options={positions.map(p => ({
                                                                                id: p.name,
                                                                                name: p.name,
                                                                                icon: <FontAwesomeIcon icon={resolveIcon(p.icon, faUser)} />
                                                                            }))}
                                                                            selectedId={worker.role || '일반'}
                                                                            onSelect={(val) => {
                                                                                handleWorkerChange(worker.id!, 'role', val);
                                                                                handleWorkerBlur(worker.id!, 'role', val);
                                                                            }}
                                                                            placeholder="직책 선택"
                                                                            minimal={!isEditMode}
                                                                            renderSelected={(opt) => (
                                                                                <div className="flex items-center gap-2">
                                                                                    <span className={`inline-flex items-center justify-center w-6 h-6 rounded-md ${colorClass}`}>
                                                                                        {opt.icon && <span className="text-white text-xs">{opt.icon}</span>}
                                                                                    </span>
                                                                                    <span>{opt.name}</span>
                                                                                </div>
                                                                            )}
                                                                        />
                                                                    </div>
                                                                </td>
                                                            );
                                                        }
                                                        case 'salaryModel': {
                                                            const companyType = workerCompany?.type;
                                                            const isPartner = companyType === '협력사';
                                                            const currentValue = isPartner ? '지원팀' : (worker.salaryModel || '일급제');

                                                            return (
                                                                <td key={key} className="px-4 py-3 border border-slate-200">
                                                                    <SingleSelectPopover
                                                                        options={isPartner
                                                                            ? [{ id: '지원팀', name: '지원팀' }]
                                                                            : [
                                                                                { id: '일급제', name: '일급제' },
                                                                                { id: '주급제', name: '주급제' },
                                                                                { id: '월급제', name: '월급제' },
                                                                                { id: '지원팀', name: '지원팀' },
                                                                                { id: '용역팀', name: '용역팀' },
                                                                                { id: '가지급', name: '가지급' }
                                                                            ]
                                                                        }
                                                                        selectedId={currentValue}
                                                                        onSelect={(val) => {
                                                                            handleWorkerChange(worker.id!, 'salaryModel', val);
                                                                            handleWorkerBlur(worker.id!, 'salaryModel', val);
                                                                        }}
                                                                        disabled={isPartner}
                                                                        minimal={!isEditMode}
                                                                        renderSelected={(opt) => (
                                                                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${opt.id === '일급제' ? 'bg-yellow-100 text-yellow-700' :
                                                                                opt.id === '월급제' ? 'bg-green-100 text-green-700' :
                                                                                    opt.id === '지원팀' ? 'bg-orange-100 text-orange-700' :
                                                                                        opt.id === '용역팀' ? 'bg-gray-100 text-slate-600' :
                                                                                            'bg-gray-100 text-gray-600'
                                                                                }`}>
                                                                                {opt.name}
                                                                            </span>
                                                                        )}
                                                                    />
                                                                </td>
                                                            );
                                                        }
                                                        case 'teamName': {
                                                            return (
                                                                <td key={key} className="px-4 py-3 text-gray-600 border border-slate-200">
                                                                    <SingleSelectPopover
                                                                        options={[
                                                                            { id: '', name: '미배정' },
                                                                            ...teams.map(t => ({
                                                                                id: t.id || '',
                                                                                name: t.name,
                                                                                icon: <FontAwesomeIcon icon={resolveIcon(t.icon, faUsers)} className="text-xs" />,
                                                                                color: t.color
                                                                            }))
                                                                        ]}
                                                                        selectedId={worker.teamId || ''}
                                                                        onSelect={(val) => handleWorkerTeamSelect(worker.id!, val)}
                                                                        placeholder="미배정"
                                                                        minimal={!isEditMode}
                                                                        renderSelected={(opt) => {
                                                                            const tColor = teams.find(t => t.id === opt.id)?.color || '#94a3b8';
                                                                            if (!opt.id) return <span>미배정</span>;
                                                                            return (
                                                                                <div className="flex items-center gap-2">
                                                                                    <span
                                                                                        className="inline-flex items-center justify-center w-6 h-6 rounded-md flex-shrink-0"
                                                                                        style={{ backgroundColor: tColor }}
                                                                                    >
                                                                                        <FontAwesomeIcon icon={faUsers} className="text-white text-xs" />
                                                                                    </span>
                                                                                    <span>{opt.name}</span>
                                                                                </div>
                                                                            );
                                                                        }}
                                                                    />
                                                                </td>
                                                            );
                                                        }
                                                        case 'companyName':
                                                            return (
                                                                <td key={key} className="px-4 py-3 text-gray-600 border border-slate-200">
                                                                    <SingleSelectPopover
                                                                        options={[
                                                                            { id: '', name: '미배정' },
                                                                            ...companies.map(c => ({
                                                                                id: c.id || '',
                                                                                name: c.name,
                                                                                color: c.color
                                                                            }))
                                                                        ]}
                                                                        selectedId={worker.companyId || ''}
                                                                        onSelect={(val) => handleWorkerCompanySelect(worker.id!, val)}
                                                                        placeholder="미배정"
                                                                        minimal={!isEditMode}
                                                                        renderSelected={(opt) => {
                                                                            const cColor = companies.find(c => c.id === opt.id)?.color || '#e5e7eb';
                                                                            if (!opt.id) return <span>미배정</span>;
                                                                            return (
                                                                                <div className="flex items-center gap-2">
                                                                                    <span
                                                                                        className="inline-flex items-center justify-center w-7 h-7 rounded-full border border-slate-200 flex-shrink-0"
                                                                                        style={{ backgroundColor: cColor }}
                                                                                    >
                                                                                        <FontAwesomeIcon icon={faBuilding} className="text-white text-xs" />
                                                                                    </span>
                                                                                    <span>{opt.name}</span>
                                                                                </div>
                                                                            );
                                                                        }}
                                                                    />
                                                                </td>
                                                            );
                                                        case 'status':
                                                            return (
                                                                <td key={key} className="px-4 py-3 border border-slate-200">
                                                                    {isEditMode ? (
                                                                        <select
                                                                            value={getCanonicalStatus(worker.status) === '퇴사' ? '퇴사' : '재직'}
                                                                            onChange={(e) => handleStatusChange(worker.id!, e.target.value)}
                                                                            className="w-full border rounded px-2 py-1 text-sm"
                                                                        >
                                                                            <option value="재직">재직</option>
                                                                            <option value="퇴사">퇴사</option>
                                                                        </select>
                                                                    ) : (
                                                                        (() => {
                                                                            const canonicalStatus = getCanonicalStatus(worker.status);
                                                                            const isWorkerActive = canonicalStatus === '재직';
                                                                            return (
                                                                                <div className="flex items-center gap-2">
                                                                                    <button
                                                                                        onClick={() => handleStatusChange(worker.id!, isWorkerActive ? '퇴사' : '재직')}
                                                                                        className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 ${isWorkerActive ? 'bg-green-500' : 'bg-slate-300'}`}
                                                                                    >
                                                                                        <span className="sr-only">상태 변경</span>
                                                                                        <span
                                                                                            className={`${isWorkerActive ? 'translate-x-5' : 'translate-x-1'} inline-block h-3 w-3 transform rounded-full bg-white transition duration-200 ease-in-out`}
                                                                                        />
                                                                                    </button>
                                                                                    <span className="text-xs text-slate-500">{canonicalStatus}</span>
                                                                                </div>
                                                                            );
                                                                        })()
                                                                    )}
                                                                </td>
                                                            );
                                                        case 'unitPrice':
                                                            return (
                                                                <td key={key} className="px-4 py-3 text-right font-mono text-gray-600 border border-slate-200">
                                                                    <InputPopover
                                                                        value={worker.unitPrice || 0}
                                                                        type="number"
                                                                        placeholder="0"
                                                                        onChange={(val) => {
                                                                            handleWorkerChange(worker.id!, 'unitPrice', Number(val));
                                                                            handleWorkerBlur(worker.id!, 'unitPrice', Number(val));
                                                                        }}
                                                                        formatDisplay={(val) => val ? Number(val).toLocaleString() : '0'}
                                                                        minimal={!isEditMode}
                                                                    />
                                                                </td>
                                                            );
                                                        case 'bankName':
                                                            return (
                                                                <td key={key} className="px-4 py-3 text-gray-600 border border-slate-200">
                                                                    <InputPopover
                                                                        value={worker.bankName || ''}
                                                                        placeholder="은행"
                                                                        onChange={(val) => {
                                                                            handleWorkerChange(worker.id!, 'bankName', String(val));
                                                                            handleWorkerBlur(worker.id!, 'bankName', String(val));
                                                                        }}
                                                                        minimal={!isEditMode}
                                                                        formatDisplay={(val) => (
                                                                            <span className={`text-xs ${isEditMode ? '' : 'font-bold text-slate-700'}`}>{val || '-'}</span>
                                                                        )}
                                                                    />
                                                                </td>
                                                            );
                                                        case 'accountNumber':
                                                            return (
                                                                <td key={key} className="px-4 py-3 text-gray-600 border border-slate-200">
                                                                    <InputPopover
                                                                        value={worker.accountNumber || ''}
                                                                        placeholder="계좌번호"
                                                                        onChange={(val) => {
                                                                            handleWorkerChange(worker.id!, 'accountNumber', String(val));
                                                                            handleWorkerBlur(worker.id!, 'accountNumber', String(val));
                                                                        }}
                                                                        minimal={!isEditMode}
                                                                        formatDisplay={(val) => <span className="text-xs">{val || '-'}</span>}
                                                                    />
                                                                </td>
                                                            );
                                                        case 'accountHolder':
                                                            return (
                                                                <td key={key} className="px-4 py-3 text-gray-600 border border-slate-200">
                                                                    <InputPopover
                                                                        value={worker.accountHolder || ''}
                                                                        placeholder="예금주"
                                                                        onChange={(val) => {
                                                                            handleWorkerChange(worker.id!, 'accountHolder', String(val));
                                                                            handleWorkerBlur(worker.id!, 'accountHolder', String(val));
                                                                        }}
                                                                        minimal={!isEditMode}
                                                                        formatDisplay={(val) => <span className="text-xs">{val || '-'}</span>}
                                                                    />
                                                                </td>
                                                            );
                                                        case 'signature':
                                                            return (
                                                                <td key={key} className="px-4 py-3 text-center border border-slate-200">
                                                                    {worker.signatureUrl ? (
                                                                        <div className="flex justify-center group relative">
                                                                            <img
                                                                                src={worker.signatureUrl}
                                                                                alt="서명"
                                                                                className="h-8 w-auto object-contain cursor-pointer hover:scale-150 transition-transform bg-white border border-slate-200 rounded"
                                                                                onClick={() => openSignatureModal(worker)}
                                                                            />
                                                                            <button
                                                                                onClick={(e) => {
                                                                                    e.stopPropagation();
                                                                                    openSignatureModal(worker);
                                                                                }}
                                                                                className="absolute -top-1 -right-1 bg-slate-800 text-white text-[10px] w-4 h-4 rounded-full opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center"
                                                                            >
                                                                                <FontAwesomeIcon icon={faPenToSquare} />
                                                                            </button>
                                                                        </div>
                                                                    ) : (
                                                                        <button
                                                                            onClick={() => openSignatureModal(worker)}
                                                                            className="px-2 py-1 text-xs border border-dashed border-slate-300 rounded text-slate-400 hover:text-blue-600 hover:border-blue-400 hover:bg-blue-50 transition-colors"
                                                                        >
                                                                            <FontAwesomeIcon icon={faPenToSquare} className="mr-1" />
                                                                            생성
                                                                        </button>
                                                                    )}
                                                                </td>
                                                            );
                                                        default:
                                                            return null;
                                                    }
                                                })}

                                                <td className="px-4 py-3 text-center border border-slate-200">
                                                    <div className="flex items-center justify-center gap-2">
                                                        {worker.fileNameSaved ? (
                                                            <button
                                                                onClick={() => handleDownloadIdCard(worker)}
                                                                className="p-1.5 text-xs font-medium bg-green-100 text-green-700 rounded hover:bg-green-200 transition-colors flex items-center gap-1"
                                                                title="신분증 다운로드"
                                                            >
                                                                <FontAwesomeIcon icon={faCheckSquare} />
                                                                <span>신분증</span>
                                                            </button>
                                                        ) : (
                                                            <span className="text-xs text-gray-400 p-1.5">미등록</span>
                                                        )}
                                                        <button
                                                            onClick={() => {
                                                                setCurrentWorker(worker);
                                                                setIsModalOpen(true);
                                                            }}
                                                            className="p-1 text-blue-600 hover:bg-blue-100 rounded transition-colors"
                                                            title="수정"
                                                        >
                                                            <FontAwesomeIcon icon={faEdit} />
                                                        </button>
                                                        <button
                                                            onClick={() => handleDelete(worker.id!, worker.name)}
                                                            className="p-1 text-red-600 hover:bg-red-100 rounded transition-colors"
                                                            title="삭제"
                                                        >
                                                            <FontAwesomeIcon icon={faTrash} />
                                                        </button>
                                                    </div>
                                                </td>
                                            </tr>
                                        );
                                    })
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div >

            {/* Modals */}
            {isModalOpen && (
                <WorkerModal
                    isOpen={isModalOpen}
                    onClose={() => setIsModalOpen(false)}
                    onSave={handleSaveWorker}
                    initialData={currentWorker}
                    teams={teams}
                    companies={companies}
                    positions={positions}
                />
            )}

            <IdCardAnalysisModal
                isOpen={isIdCardAnalysisModalOpen}
                onClose={() => setIsIdCardAnalysisModalOpen(false)}
                onAddWorkers={handleIdCardRegister}
                existingWorkers={workers}
            />

            {isBankBookModalOpen && (
                <BankBookAnalysisModal
                    isOpen={isBankBookModalOpen}
                    onClose={() => setIsBankBookModalOpen(false)}
                    workers={filteredWorkers}
                    onUpdateWorkers={handleBankBookUpdate}
                />
            )}

            {showLinkingModal && (
                <AccountLinkingModal
                    onClose={() => setShowLinkingModal(false)}
                />
            )}

            {signatureTargetWorker && (
                <SignatureGeneratorModal
                    isOpen={isSignatureModalOpen}
                    onClose={() => setIsSignatureModalOpen(false)}
                    workerId={signatureTargetWorker.id}
                    workerName={signatureTargetWorker.name}
                    onSaveComplete={handleSignatureSaveComplete}
                />
            )}

            <BulkProgressModal
                isOpen={isBulkProgressOpen}
                onClose={() => setIsBulkProgressOpen(false)}
                progress={bulkProgress}
                logs={bulkLogs}
            />

            <BulkEditWorkerModal
                isOpen={isBulkEditOpen}
                onClose={() => setIsBulkEditOpen(false)}
                onSave={async (updates) => {
                    await manpowerService.updateWorkersBatch(selectedWorkerIds, updates);
                    await fetchWorkers();
                    setSelectedWorkerIds([]);
                    alert('일괄 수정이 완료되었습니다.');
                }}
                selectedCount={selectedWorkerIds.length}
                teams={teams}
                sites={sites}
                companies={companies}
                positions={positions}
            />
        </div>
    );
};

export default WorkerDatabase;

import React, { useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faTable, faPlus, faMinus, faSave, faCopy, faPaste, faUsers, faBuilding, faHardHat, faDatabase } from '@fortawesome/free-solid-svg-icons';
import { manpowerService, Worker } from '../../services/manpowerService';
import { teamService, Team } from '../../services/teamService';
import { siteService, Site } from '../../services/siteService';

interface TableData {
    현장명: string;
    팀명: string;
    이름: string;
    공수: string;
    단가: string;
    담당팀: string;
}

const WorkerDatabaseInput: React.FC = () => {
    const [tableData, setTableData] = useState<TableData[]>([
        { 현장명: '', 팀명: '', 이름: '', 공수: '1.0', 단가: '', 담당팀: '' },
        { 현장명: '', 팀명: '', 이름: '', 공수: '1.0', 단가: '', 담당팀: '' },
        { 현장명: '', 팀명: '', 이름: '', 공수: '1.0', 단가: '', 담당팀: '' },
        { 현장명: '', 팀명: '', 이름: '', 공수: '1.0', 단가: '', 담당팀: '' },
        { 현장명: '', 팀명: '', 이름: '', 공수: '1.0', 단가: '', 담당팀: '' }
    ]);

    const [workers, setWorkers] = useState<Worker[]>([]);
    const [teams, setTeams] = useState<Team[]>([]);
    const [sites, setSites] = useState<Site[]>([]);
    const [loading, setLoading] = useState(false);

    React.useEffect(() => {
        fetchInitialData();
    }, []);

    const fetchInitialData = async () => {
        try {
            const [workersData, teamsData, sitesData] = await Promise.all([
                manpowerService.getWorkers(),
                teamService.getTeams(),
                siteService.getSites()
            ]);
            setWorkers(workersData);
            setTeams(teamsData);
            setSites(sitesData);
        } catch (error) {
            console.error("Failed to fetch initial data", error);
        }
    };

    // 행 추가
    const addRow = () => {
        setTableData([...tableData, { 현장명: '', 팀명: '', 이름: '', 공수: '1.0', 단가: '', 담당팀: '' }]);
    };

    // 행 삭제
    const removeRow = (index: number) => {
        if (tableData.length > 1) {
            setTableData(tableData.filter((_, i) => i !== index));
        }
    };

    // 데이터 변경
    const handleCellChange = (rowIndex: number, field: keyof TableData, value: string) => {
        const newData = [...tableData];
        newData[rowIndex][field] = value;
        setTableData(newData);
    };

    // 테이블 데이터 복사
    const copyTableData = () => {
        const headers = ['현장명', '팀명', '이름', '공수', '단가', '담당팀'];
        const rows = tableData.map(row =>
            [row.현장명, row.팀명, row.이름, row.공수, row.단가, row.담당팀].join('\t')
        );

        const clipboardData = [headers.join('\t'), ...rows].join('\n');

        navigator.clipboard.writeText(clipboardData).then(() => {
            alert('테이블 데이터가 복사되었습니다. 엑셀에 붙여넣으세요.');
        });
    };

    // 테이블 데이터 붙여넣기
    const pasteTableData = async () => {
        try {
            const text = await navigator.clipboard.readText();
            const lines = text.trim().split('\n');

            if (lines.length < 2) {
                alert('붙여넣을 데이터가 없습니다.');
                return;
            }

            const newData: TableData[] = [];

            // 첫 줄은 헤더이므로 건너뛰기
            for (let i = 1; i < lines.length; i++) {
                const columns = lines[i].split('\t');

                if (columns.length >= 6) {
                    newData.push({
                        현장명: columns[0] || '',
                        팀명: columns[1] || '',
                        이름: columns[2] || '',
                        공수: columns[3] || '1.0',
                        단가: columns[4] || '',
                        담당팀: columns[5] || ''
                    });
                }
            }

            if (newData.length > 0) {
                setTableData(newData);
                alert(`${newData.length}개의 행이 붙여넣기 되었습니다.`);
            }
        } catch (error) {
            alert('붙여넣기에 실패했습니다.');
        }
    };

    // 데이터 등록
    const handleRegister = async () => {
        const validData = tableData.filter(row => row.이름.trim() !== '');

        if (validData.length === 0) {
            alert('등록할 데이터가 없습니다.');
            return;
        }

        setLoading(true);
        try {
            // 1. 작업자 등록/업데이트
            for (const row of validData) {
                // 기존 작업자 찾기
                const existingWorker = workers.find(w => w.name === row.이름);

                if (existingWorker) {
                    // 기존 작업자 업데이트
                    await manpowerService.updateWorker(existingWorker.id!, {
                        name: row.이름,
                        role: '작업자',
                        status: 'active',
                        unitPrice: parseInt(row.단가) || 0,
                        teamType: '작업팀'
                    });
                } else {
                    // 새 작업자 등록
                    await manpowerService.addWorker({
                        name: row.이름,
                        idNumber: '', // 필수 필드지만 빈값으로 설정
                        role: '작업자',
                        status: 'active',
                        unitPrice: parseInt(row.단가) || 0,
                        teamType: '작업팀'
                    });
                }
            }

            // 2. 팀 등록/업데이트
            for (const row of validData) {
                if (row.팀명.trim() !== '') {
                    const existingTeam = teams.find(t => t.name === row.팀명);

                    if (!existingTeam) {
                        await teamService.addTeam({
                            name: row.팀명,
                            type: '작업팀',
                            leaderId: '', // 필수 필드지만 빈값으로 설정
                            leaderName: '미지정'
                        });
                    }
                }
            }

            // 3. 현장 등록/업데이트
            for (const row of validData) {
                if (row.현장명.trim() !== '') {
                    const existingSite = sites.find(s => s.name === row.현장명);

                    if (!existingSite) {
                        await siteService.addSite({
                            name: row.현장명,
                            code: 'AUTO', // 필수 필드
                            address: '미등록', // 필수 필드
                            status: 'active'
                        });
                    }
                }
            }

            alert(`${validData.length}건의 데이터가 등록되었습니다.`);

            // 데이터 다시 불러오기
            await fetchInitialData();

            // 테이블 초기화
            setTableData([
                { 현장명: '', 팀명: '', 이름: '', 공수: '1.0', 단가: '', 담당팀: '' },
                { 현장명: '', 팀명: '', 이름: '', 공수: '1.0', 단가: '', 담당팀: '' },
                { 현장명: '', 팀명: '', 이름: '', 공수: '1.0', 단가: '', 담당팀: '' },
                { 현장명: '', 팀명: '', 이름: '', 공수: '1.0', 단가: '', 담당팀: '' },
                { 현장명: '', 팀명: '', 이름: '', 공수: '1.0', 단가: '', 담당팀: '' }
            ]);

