import React, { useState, useMemo } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faTools,
    faSearch,
    faFileCode,
    faCubes,
    faServer,
    faList
} from '@fortawesome/free-solid-svg-icons';
import FileCard from '../../components/developer/FileCard';
import { projectFiles, FileInfo } from '../../data/projectFiles';

type CategoryFilter = 'all' | 'page' | 'component' | 'service' | 'hook' | 'util';

const DeveloperTools: React.FC = () => {
    const [searchQuery, setSearchQuery] = useState('');
    const [categoryFilter, setCategoryFilter] = useState<CategoryFilter>('all');

    // 필터링된 파일 목록
    const filteredFiles = useMemo(() => {
        let files = projectFiles;

        // 카테고리 필터
        if (categoryFilter !== 'all') {
            files = files.filter(file => file.category === categoryFilter);
        }

        // 검색 필터
        if (searchQuery) {
            const query = searchQuery.toLowerCase();
            files = files.filter(file =>
                file.name.toLowerCase().includes(query) ||
                file.description?.toLowerCase().includes(query) ||
                file.tags?.some(tag => tag.toLowerCase().includes(query))
            );
        }

        return files;
    }, [searchQuery, categoryFilter]);

    // 카테고리별 개수
    const categoryCounts = useMemo(() => {
        return {
            all: projectFiles.length,
            page: projectFiles.filter(f => f.category === 'page').length,
            component: projectFiles.filter(f => f.category === 'component').length,
            service: projectFiles.filter(f => f.category === 'service').length,
            hook: projectFiles.filter(f => f.category === 'hook').length,
            util: projectFiles.filter(f => f.category === 'util').length
        };
    }, []);

    return (
        <div className="flex flex-col h-full bg-slate-50">
            {/* 헤더 */}
            <div className="bg-white border-b border-slate-200 p-4 flex-shrink-0">
                <div className="flex items-center justify-between mb-4">
                    <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                        <FontAwesomeIcon icon={faTools} className="text-indigo-600" />
                        <span>개발자 도구</span>
                    </h2>
                    <div className="text-sm text-slate-500">
                        {filteredFiles.length}개 파일
                    </div>
                </div>

                {/* 검색 */}
                <div className="relative">
                    <FontAwesomeIcon
                        icon={faSearch}
                        className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400"
                    />
                    <input
                        type="text"
                        placeholder="파일명, 설명, 태그로 검색..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
                    />
                </div>
            </div>

            {/* 카테고리 필터 탭 */}
            <div className="bg-white border-b border-slate-200 px-4 py-2 flex gap-2 overflow-x-auto flex-shrink-0">
                <button
                    onClick={() => setCategoryFilter('all')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-colors ${categoryFilter === 'all'
                            ? 'bg-indigo-100 text-indigo-700'
                            : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                        }`}
                >
                    <FontAwesomeIcon icon={faList} className="mr-2" />
                    전체 ({categoryCounts.all})
                </button>
                <button
                    onClick={() => setCategoryFilter('page')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-colors ${categoryFilter === 'page'
                            ? 'bg-blue-100 text-blue-700'
                            : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                        }`}
                >
                    <FontAwesomeIcon icon={faFileCode} className="mr-2" />
                    Pages ({categoryCounts.page})
                </button>
                <button
                    onClick={() => setCategoryFilter('component')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-colors ${categoryFilter === 'component'
                            ? 'bg-purple-100 text-purple-700'
                            : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                        }`}
                >
                    <FontAwesomeIcon icon={faCubes} className="mr-2" />
                    Components ({categoryCounts.component})
                </button>
                <button
                    onClick={() => setCategoryFilter('service')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-colors ${categoryFilter === 'service'
                            ? 'bg-green-100 text-green-700'
                            : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                        }`}
                >
                    <FontAwesomeIcon icon={faServer} className="mr-2" />
                    Services ({categoryCounts.service})
                </button>
            </div>

            {/* 파일 목록 */}
            <div className="flex-1 overflow-auto p-6">
                {filteredFiles.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {filteredFiles.map(file => (
                            <FileCard key={file.id} file={file} />
                        ))}
                    </div>
                ) : (
                    <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                        <FontAwesomeIcon icon={faSearch} className="text-6xl mb-4" />
                        <p>검색 결과가 없습니다</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default DeveloperTools;

import React, { useEffect, useState, useRef } from 'react';
import styled from 'styled-components';
import { useForm, Controller } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import Swal from 'sweetalert2';
import withReactContent from 'sweetalert2-react-content';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { 
  faCloudUploadAlt, 
  faPaperPlane, 
  faTimes, 
  faFileAlt, 
  faBuilding, 
  faUser, 
  faPhone, 
  faEnvelope,
  faCircleCheck,
  faSpinner
} from '@fortawesome/free-solid-svg-icons';
import { db, storage } from '../../config/firebase';
import { collection, addDoc, serverTimestamp } from 'firebase/firestore';
import { ref as storageRef, uploadBytes, getDownloadURL } from 'firebase/storage';

const MySwal = withReactContent(Swal);

// Zod 검증 스키마
const estimateSchema = z.object({
  inquiryType: z.enum(['시스템동바리', '시스템비계', '기타'], { required_error: '견적 종류를 선택해주세요.' }),
  companyName: z.string().min(1, '회사명 또는 현장명을 입력해주세요.'),
  requesterName: z.string().min(1, '담당자(신청자) 성함을 입력해주세요.'),
  phone: z.string().min(9, '올바른 연락처를 입력해주세요.'),
  email: z.string().email('유효한 이메일 주소를 입력해주세요.').optional().or(z.literal('')),
  details: z.string().min(5, '요청 상세내용을 최소 5자 이상 입력해주세요.'),
});

type EstimateFormValues = z.infer<typeof estimateSchema>;

const EstimateRequestPage: React.FC = () => {
  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState<boolean>(() => localStorage.getItem('cy-cheongyeon-theme') !== 'light');
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const syncTheme = () => {
      setIsDarkMode(localStorage.getItem('cy-cheongyeon-theme') !== 'light');
    };

    syncTheme();
    window.addEventListener('storage', syncTheme);
    window.addEventListener('focus', syncTheme);
    return () => {
      window.removeEventListener('storage', syncTheme);
      window.removeEventListener('focus', syncTheme);
    };
  }, []);

  const {
    register,
    handleSubmit,
    control,
    reset,
    formState: { errors }
  } = useForm<EstimateFormValues>({
    resolver: zodResolver(estimateSchema),
    defaultValues: {
      inquiryType: '시스템동바리',
      companyName: '',
      requesterName: '',
      phone: '',
      email: '',
      details: '',
    }
  });

  // 다중 파일 선택 처리
  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files);
      setSelectedFiles((prev) => [...prev, ...newFiles]);
    }
    // 동일 파일 재선택 가능하도록 초기화
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  // 선택된 파일 제거
  const handleRemoveFile = (indexToRemove: number) => {
    setSelectedFiles((prev) => prev.filter((_, idx) => idx !== indexToRemove));
  };

  // 파일 업로드 (병렬 처리)
  const uploadFiles = async (files: File[]): Promise<{ name: string; url: string; size: number }[]> => {
    if (files.length === 0) return [];

    const uploadPromises = files.map(async (file) => {
      const timestamp = Date.now();
      const uniqueName = `estimate_files/${timestamp}_${file.name}`;
      const fileRef = storageRef(storage, uniqueName);

      const snapshot = await uploadBytes(fileRef, file);
      const downloadURL = await getDownloadURL(snapshot.ref);

      return {
        name: file.name,
        url: downloadURL,
        size: file.size
      };
    });

    return Promise.all(uploadPromises);
  };

  // 폼 제출 핸들러
  const onSubmit = async (data: EstimateFormValues) => {
    try {
      setIsSubmitting(true);

      // 1. 파일 업로드 실행
      let uploadedFileUrls: { name: string; url: string; size: number }[] = [];
      if (selectedFiles.length > 0) {
        uploadedFileUrls = await uploadFiles(selectedFiles);
      }

      // 2. 파이어스토어 데이터 저장
      const estimateData = {
        ...data,
        attachedFiles: uploadedFileUrls,
        status: '접수대기',
        createdAt: serverTimestamp(),
      };

      await addDoc(collection(db, 'estimate_inquiries'), estimateData);

      // 3. 성공 알림 및 초기화
      await MySwal.fire({
        icon: 'success',
        title: '접수 완료',
        html: `견적 문의가 성공적으로 접수되었습니다.<br/>빠른 시일 내에 연락 드리겠습니다.`,
        background: isDarkMode ? '#111827' : '#ffffff',
        color: isDarkMode ? '#e5e7eb' : '#1e293b',
        confirmButtonColor: '#2563eb'
      });

      reset();
      setSelectedFiles([]);

    } catch (error) {
      console.error('견적 저장 에러:', error);
      MySwal.fire({
        icon: 'error',
        title: '오류 발생',
        text: '접수 중 문제가 발생했습니다. 관리자에게 문의해주세요.',
        background: isDarkMode ? '#111827' : '#ffffff',
        color: isDarkMode ? '#e5e7eb' : '#1e293b',
        confirmButtonColor: '#ef4444'
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Container $isDarkMode={isDarkMode}>
      <PageHeader>
        <HeaderTitle>초간편 견적 상담</HeaderTitle>
        <HeaderSubtitle>시스템동바리 및 시스템비계 시공/임대 단가, 즉시 산출해 드립니다.</HeaderSubtitle>
      </PageHeader>

      <FormCard onSubmit={handleSubmit(onSubmit)}>
        {/* --- 1. 기본 정보 --- */}
        <SectionTitle>
          <FontAwesomeIcon icon={faBuilding} className="mr-2 text-blue-500" />
          기본 정보 입력
        </SectionTitle>

        <GridContainer>
          {/* 견적 유형 */}
          <FormGroup className="col-span-1 md:col-span-2">
            <Label>문의 유형 <Required>*</Required></Label>
            <RadioGroup>
              {['시스템동바리', '시스템비계', '기타'].map((type) => (
                <RadioLabel key={type}>
                  <input
                    type="radio"
                    value={type}
                    {...register('inquiryType')}
                    disabled={isSubmitting}
                  />
                  <span className="radio-text">{type}</span>
                </RadioLabel>
              ))}
            </RadioGroup>
            {errors.inquiryType && <ErrorText>{errors.inquiryType.message}</ErrorText>}
          </FormGroup>

          {/* 회사명/현장명 */}
          <FormGroup className="col-span-1 md:col-span-2">
            <Label>회사명 / 현장명 <Required>*</Required></Label>
            <InputWrapper>
              <InputIcon>
                <FontAwesomeIcon icon={faBuilding} />
              </InputIcon>
              <Input
                type="text"
                placeholder="(주)청연건설 / 송도 랜드마크 현장"
                {...register('companyName')}
                disabled={isSubmitting}
                $hasError={!!errors.companyName}
              />
            </InputWrapper>
            {errors.companyName && <ErrorText>{errors.companyName.message}</ErrorText>}
          </FormGroup>

          {/* 담당자명 */}
          <FormGroup>
            <Label>담당자 성함 <Required>*</Required></Label>
            <InputWrapper>
              <InputIcon>
                <FontAwesomeIcon icon={faUser} />
              </InputIcon>
              <Input
                type="text"
                placeholder="홍길동 과장"
                {...register('requesterName')}
                disabled={isSubmitting}
                $hasError={!!errors.requesterName}
              />
            </InputWrapper>
            {errors.requesterName && <ErrorText>{errors.requesterName.message}</ErrorText>}
          </FormGroup>

          {/* 연락처 */}
          <FormGroup>
            <Label>연락처 <Required>*</Required></Label>
            <InputWrapper>
              <InputIcon>
                <FontAwesomeIcon icon={faPhone} />
              </InputIcon>
              <Input
                type="text"
                placeholder="010-0000-0000"
                {...register('phone')}
                disabled={isSubmitting}
                $hasError={!!errors.phone}
              />
            </InputWrapper>
            {errors.phone && <ErrorText>{errors.phone.message}</ErrorText>}
          </FormGroup>

          {/* 이메일 */}
          <FormGroup className="col-span-1 md:col-span-2">
            <Label>이메일 (선택)</Label>
            <InputWrapper>
              <InputIcon>
                <FontAwesomeIcon icon={faEnvelope} />
              </InputIcon>
              <Input
                type="email"
                placeholder="example@cy-enc.com (견적서를 이메일로 받아보실 수 있습니다)"
                {...register('email')}
                disabled={isSubmitting}
                $hasError={!!errors.email}
              />
            </InputWrapper>
            {errors.email && <ErrorText>{errors.email.message}</ErrorText>}
          </FormGroup>
        </GridContainer>

        <Divider />

        {/* --- 2. 상세 요청 및 도면 첨부 --- */}
        <SectionTitle>
          <FontAwesomeIcon icon={faFileAlt} className="mr-2 text-indigo-500" />
          상세 요청 & 도면 첨부
        </SectionTitle>

        <FormGroup>
          <Label>현장 상황 및 상세 요청 <Required>*</Required></Label>
          <TextArea
            placeholder="설치 시공 기간, 예상 물량, 현장 특이사항 등을 자세히 적어주시면 더욱 정확한 견적이 가능합니다."
            rows={5}
            {...register('details')}
            disabled={isSubmitting}
            $hasError={!!errors.details}
          />
          {errors.details && <ErrorText>{errors.details.message}</ErrorText>}
        </FormGroup>

        <FormGroup>
          <Label>도면 및 첨부 문서 (선택)</Label>
          <FileUploadZone 
            onClick={() => !isSubmitting && fileInputRef.current?.click()}
            $isSubmitting={isSubmitting}
          >
            <FontAwesomeIcon icon={faCloudUploadAlt} className="upload-icon" />
            <div className="upload-text">
              <span className="upload-highlight">클릭하여 파일 추가</span> 또는 이 영역으로 드래그
            </div>
            <div className="upload-subtext">지원 파일: PDF, CAD(dwg), JPG, PNG, Excel 등 (최대 50MB)</div>
            <input
              type="file"
              multiple
              ref={fileInputRef}
              onChange={handleFileSelect}
              style={{ display: 'none' }}
              disabled={isSubmitting}
            />
          </FileUploadZone>

          {/* 선택된 파일 목록 */}
          {selectedFiles.length > 0 && (
            <FileList>
              {selectedFiles.map((file, idx) => (
                <FileItem key={`${file.name}-${idx}`}>
                  <div className="file-info">
                    <FontAwesomeIcon icon={faFileAlt} className="file-icon" />
                    <span className="file-name">{file.name}</span>
                    <span className="file-size">({(file.size / 1024 / 1024).toFixed(2)} MB)</span>
                  </div>
                  <RemoveButton 
                    type="button" 
                    onClick={() => handleRemoveFile(idx)}
                    disabled={isSubmitting}
                  >
                    <FontAwesomeIcon icon={faTimes} />
                  </RemoveButton>
                </FileItem>
              ))}
            </FileList>
          )}
        </FormGroup>

        <SubmitButton type="submit" disabled={isSubmitting}>
          {isSubmitting ? (
            <>
              <FontAwesomeIcon icon={faSpinner} spin className="mr-2" />
              업로드 및 전송 중...
            </>
          ) : (
            <>
              <FontAwesomeIcon icon={faPaperPlane} className="mr-2" />
              견적 문의 접수하기
            </>
          )}
        </SubmitButton>
      </FormCard>
    </Container>
  );
};

