    { id: 'blue', bg: 'bg-blue-500', text: 'text-blue-700', light: 'bg-blue-50' },
    { id: 'indigo', bg: 'bg-indigo-500', text: 'text-indigo-700', light: 'bg-indigo-50' },
    { id: 'purple', bg: 'bg-purple-500', text: 'text-purple-700', light: 'bg-purple-50' },
