            {/* Kanban Board */}
            <div className="flex-1 overflow-hidden px-8 pb-8">
                <div className="flex h-full gap-6 overflow-x-auto pb-2">
                    {columns.map(col => (
                        <KanbanColumn
                            key={col.id}
                            column={col}
                            onMove={handleMove}
                        />
                    ))}
                </div>
            </div>
        </div>
    );
};

export default StatusManagementPage;

import React, { useState, useEffect } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faFlask,
    faCalendarAlt,
    faListUl,
    faEraser,
    faCheck,
    faBolt,
    faEye,
    faSave,
    faTruckFast,
    faChartSimple
} from '@fortawesome/free-solid-svg-icons';
import { dailyReportService } from '../../services/dailyReportService';
import { siteService, Site } from '../../services/siteService';
import { teamService, Team } from '../../services/teamService';
import { manpowerService, Worker } from '../../services/manpowerService';

interface SimulationResult {
    totalReports: number;
    totalManDays: number;
    totalAmount: number;
    supportCount: number;
    internalSupportCount: number;
    externalSupportCount: number;
    datesProcessed: number;
    reports: any[]; // The actual payload to save
}

const TestDailyReportGeneratorPage: React.FC = () => {
    const [loading, setLoading] = useState(false);
    const [logs, setLogs] = useState<string[]>([]);
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [scenario, setScenario] = useState('standard');

    // Preview Data
    const [simulation, setSimulation] = useState<SimulationResult | null>(null);

    // Data check states
    const [siteCount, setSiteCount] = useState(0);
    const [teamCount, setTeamCount] = useState(0);
    const [workerCount, setWorkerCount] = useState(0);

    useEffect(() => {
        // Set default dates (Current month) based on Local Time
        const today = new Date();
        const year = today.getFullYear();
        const month = String(today.getMonth() + 1).padStart(2, '0');
        const day = String(today.getDate()).padStart(2, '0');

        setEndDate(`${year}-${month}-${day}`);
        setStartDate(`${year}-${month}-01`);

        // Load initial counts
        checkDataCounts();
    }, []);

    const addLog = (message: string) => {
        setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${message}`, ...prev]);
    };

    const checkDataCounts = async () => {
        try {
            const [sites, teams, workers] = await Promise.all([
                siteService.getSites(),
                teamService.getTeams(),
                manpowerService.getWorkers()
            ]);
            setSiteCount(sites.length);
            setTeamCount(teams.length);
            setWorkerCount(workers.length);
        } catch (error) {
            console.error("Failed to check data counts:", error);
        }
    };

    // --- Core Simulation Logic ---
    const runSimulation = async () => {
        if (!startDate || !endDate) {
            alert("시작일과 종료일을 선택해주세요.");
            return;
        }
        if (siteCount === 0 || teamCount === 0 || workerCount === 0) {
            alert("기초 데이터가 부족합니다.");
            return;
        }

        setLoading(true);
        setSimulation(null);
        addLog(`🎲 시뮬레이션 시작 (${scenario})`);

        try {
            const sites = await siteService.getSites();
            const teams = await teamService.getTeams();
            const workers = await manpowerService.getWorkers();

            const generatedReports: any[] = [];
            let totalMD = 0;
            let totalAmt = 0;
            let supportCnt = 0;
            let internalCnt = 0;
            let externalCnt = 0;

            let current = new Date(startDate);
            const end = new Date(endDate);
            let dateCount = 0;

            // Pre-calculate worker schedules (e.g., who works 5 days vs 6 days)
            // Ideally assume random availability per day for simplicity in this version

            while (current <= end) {
                const dateStr = current.toISOString().split('T')[0];
                const dayOfWeek = current.getDay(); // 0: Sun
                dateCount++;

                // Skip Sundays unless 'full' scenario
                if (dayOfWeek === 0 && scenario !== 'full') {
                    current.setDate(current.getDate() + 1);
                    continue;
                }

                // Weather Logic (Random Rain)
                let weather = "맑음";
                if (scenario === 'rain' && Math.random() < 0.4) weather = "비";
                if (weather === "비" && Math.random() < 0.7) {
                    // Rain often cancels work
                    current.setDate(current.getDate() + 1);
                    continue;
                }

                // Iterate per Team
                for (const team of teams) {
                    // Filter members
                    const teamWorkers = workers.filter(w => w.teamId === team.id);
                    if (teamWorkers.length === 0) continue;

                    // 1. Determine if Team Works Today (90% chance usually)
                    if (Math.random() > 0.9) continue;

                    // 2. Identify Main Site (Responsible Site)
                    // If team has no responsible site, they are purely support team?
                    // Let's find sites where this team is responsible
                    const responsibleSites = sites.filter(s => s.responsibleTeamId === team.id);
                    let mainSite = responsibleSites.length > 0 ? responsibleSites[0] : null;

                    // If 'Support Team' (no site), they MUST go somewhere as support
                    // If 'Construction Team' (has site), they work at main site, BUT might send some support elsewhere

                    const availableWorkers = [...teamWorkers];
                    const dailyWorkEvents = [];

                    // --- Support Logic (30% Chance) ---
                    // "Coming and Going": simulate dividing the team or moving entirely
                    // Probability to do support today
                    const doSupport = Math.random() < 0.3 || (!mainSite);

                    if (doSupport) {
                        // Pick random target site NOT equal to mainSite
                        const otherSites = sites.filter(s => s.id !== mainSite?.id);
                        if (otherSites.length > 0) {
                            const targetSite = otherSites[Math.floor(Math.random() * otherSites.length)];

                            // Determine Support Type
                            // Check Company ID match
                            const isSameCompany = targetSite.companyId === team.companyId;
                            const supportType = isSameCompany ? 'internal_support' : 'external_support';

                            // How many go? (Support usually 20-50% of team, or all if support team)
                            const supportSize = !mainSite
                                ? availableWorkers.length // All go
                                : Math.floor(availableWorkers.length * 0.3) + 1; // Partial go

                            // Extract workers
                            const supportGroup = availableWorkers.splice(0, supportSize);

                            if (supportGroup.length > 0) {
                                dailyWorkEvents.push({
                                    site: targetSite,
                                    workers: supportGroup,
                                    type: supportType
                                });
                                supportCnt++;
                                if (supportType === 'internal_support') internalCnt++;
                                else externalCnt++;
                            }
                        }
                    }

                    // --- Main Work Logic ---
                    // Remaining workers work at Main Site
                    if (mainSite && availableWorkers.length > 0) {
                        dailyWorkEvents.push({
                            site: mainSite,
                            workers: availableWorkers,
                            type: 'main'
                        });
                    }

                    // --- Create Payloads ---
                    for (const event of dailyWorkEvents) {
                        // Man-Day Logic (0.5 ~ 1.5)
                        // 80% = 1.0, 10% = 0.5, 10% = 1.5
                        const attendees = event.workers.map(w => {
                            let md = 1.0;
                            const r = Math.random();
                            if (r < 0.1) md = 0.5;
                            else if (r > 0.9) md = 1.5;

                            return {
                                workerId: w.id!,
                                name: w.name,
                                role: w.role,
                                unitPrice: w.unitPrice,
                                manDay: md,
                                status: 'attendance',
                                workContent: event.type === 'main' ? '일반 시공' : (event.type === 'internal_support' ? '내부 지원' : '외부 지원')
                            };
                        });

                        const eventTotalMD = attendees.reduce((sum, w) => sum + w.manDay, 0);
                        const eventTotalAmt = attendees.reduce((sum, w) => sum + (w.unitPrice || 0) * w.manDay, 0);

                        generatedReports.push({
                            date: dateStr,
                            siteId: event.site.id!,
                            siteName: event.site.name,
                            teamId: team.id!,
                            teamName: team.name,
                            responsibleTeamId: event.site.responsibleTeamId,
                            responsibleTeamName: event.site.responsibleTeamName,
                            writerId: 'sys-sim',
                            totalManDay: eventTotalMD,
                            totalAmount: eventTotalAmt,
                            weather,
                            workContent: attendees[0].workContent,
                            workers: attendees
                        });

                        totalMD += eventTotalMD;
                        totalAmt += eventTotalAmt;
                    }
                } // end team loop

                current.setDate(current.getDate() + 1);
            } // end date loop

            setSimulation({
                totalReports: generatedReports.length,
                totalManDays: totalMD,
                totalAmount: totalAmt,
                supportCount: supportCnt,
                internalSupportCount: internalCnt,
                externalSupportCount: externalCnt,
                datesProcessed: dateCount,
                reports: generatedReports
            });

            addLog(`✅ 시뮬레이션 완료! 총 ${generatedReports.length}건 산출`);

        } catch (error) {
            console.error(error);
            addLog(`❌ 오류: ${error}`);
        } finally {
            setLoading(false);
        }
    };

    const saveToDatabase = async () => {
        if (!simulation || simulation.reports.length === 0) return;
        if (!window.confirm(`${simulation.totalReports}건의 일보 데이터를 실제로 저장하시겠습니까?`)) return;

        setLoading(true);
        addLog("💾 데이터베이스 저장 시작...");

        try {
            const batchSize = 50;
            const reports = simulation.reports;

            for (let i = 0; i < reports.length; i += batchSize) {
                const batch = reports.slice(i, i + batchSize);
                await Promise.all(batch.map(r => dailyReportService.addReport(r)));
                addLog(`... ${Math.min(i + batchSize, reports.length)} / ${reports.length} 저장 중`);
            }

            addLog("🎉 모든 데이터가 저장되었습니다!");
            setSimulation(null); // Reset preview
        } catch (error) {
            addLog(`❌ 저장 실패: ${error}`);
        } finally {
            setLoading(false);
        }
    };

    const clearReports = async () => {
        if (!window.confirm("정말로 모든 '일보 데이터'를 삭제하시겠습니까?\n(현장, 팀, 작업자 데이터는 유지됩니다)")) return;

        setLoading(true);
        addLog("🗑️ 일보 데이터 삭제 시작...");
        try {
            const reports = await dailyReportService.getAllReports();
            addLog(`발견된 일보: ${reports.length}개`);

            const ids = reports.map(r => r.id!).filter(Boolean);
            if (ids.length > 0) {
                // Delete in chunks
                for (let i = 0; i < ids.length; i += 100) {
                    await dailyReportService.deleteReports(ids.slice(i, i + 100));
                }
            }

            addLog("✅ 모든 일보 데이터가 삭제되었습니다.");
            setSimulation(null);

        } catch (error) {
            addLog(`❌ 삭제 중 오류: ${error}`);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="p-6 max-w-6xl mx-auto">
            <h1 className="text-2xl font-bold text-slate-800 mb-6 flex items-center gap-2">
                <FontAwesomeIcon icon={faFlask} className="text-purple-600" />
                테스트 데이터 생성기 v2.0 (일보 전용)
            </h1>

            {/* Status Card */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 mb-6">
                <h3 className="font-bold text-slate-700 mb-4 flex items-center gap-2">
                    <FontAwesomeIcon icon={faCheck} className="text-green-500" />
                    기초 데이터 현황
                </h3>
                <div className="grid grid-cols-3 gap-4 text-center">
                    <div className="p-4 bg-slate-50 rounded-lg">
                        <div className="text-3xl font-bold text-blue-600">{siteCount}</div>
                        <div className="text-sm text-slate-500">현장</div>
                    </div>
                    <div className="p-4 bg-slate-50 rounded-lg">
                        <div className="text-3xl font-bold text-indigo-600">{teamCount}</div>
                        <div className="text-sm text-slate-500">팀</div>
                    </div>
                    <div className="p-4 bg-slate-50 rounded-lg">
                        <div className="text-3xl font-bold text-green-600">{workerCount}</div>
                        <div className="text-sm text-slate-500">작업자</div>
                    </div>
                </div>
                {siteCount === 0 && (
                    <div className="mt-4 p-3 bg-yellow-50 text-yellow-800 text-sm rounded-lg">
                        ⚠️ 기초 데이터가 없습니다. 먼저 [데이터 생성] 메뉴에서 1단계~4단계를 진행해주세요.
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
                {/* 1. Settings Panel */}
                <div className="space-y-6">
                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                        <h3 className="font-bold text-slate-700 mb-4 flex items-center gap-2">
                            <FontAwesomeIcon icon={faListUl} />
                            생성 설정
                        </h3>

                        <div className="space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-500 mb-1">
                                    <FontAwesomeIcon icon={faCalendarAlt} className="mr-1" />
                                    기간 설정
                                </label>
                                <div className="flex gap-2">
                                    <input
                                        type="date"
                                        value={startDate}
                                        onChange={e => setStartDate(e.target.value)}
                                        className="flex-1 border-slate-200 rounded-lg text-sm"
                                    />
                                    <span className="self-center">~</span>
                                    <input
                                        type="date"
                                        value={endDate}
                                        onChange={e => setEndDate(e.target.value)}
                                        className="flex-1 border-slate-200 rounded-lg text-sm"
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="block text-xs font-bold text-slate-500 mb-1">
                                    <FontAwesomeIcon icon={faBolt} className="mr-1" />
                                    시나리오 선택 (3종)
                                </label>
                                <select
                                    value={scenario}
                                    onChange={e => setScenario(e.target.value)}
                                    className="w-full border-slate-200 rounded-lg text-sm p-3"
                                >
                                    <option value="standard">📅 [표준] 주 5~6일 근무 + 지원 30%</option>
                                    <option value="full">🔥 [풀가동] 휴일 없음 + 야근(1.5공수) 빈도 증가</option>
                                    <option value="random">🎲 [랜덤] 불규칙적 지원 및 공수 패턴</option>
                                </select>
                                <div className="mt-2 text-xs text-slate-500 bg-slate-50 p-2 rounded">
                                    <p>• <strong>공수</strong>: 0.5 ~ 1.5 랜덤 배정</p>
                                    <p>• <strong>지원</strong>: 30% 확률로 타 현장(내부/외부) 지원 투입</p>
                                    <p>• <strong>작업자</strong>: 소속 팀/회사를 기반으로 논리적 연결</p>
                                </div>
                            </div>

                            <button
                                onClick={runSimulation}
                                disabled={loading || siteCount === 0}
                                className="w-full bg-indigo-600 text-white py-3 rounded-lg hover:bg-indigo-700 font-bold transition-colors disabled:bg-slate-300 flex items-center justify-center gap-2"
                            >
                                <FontAwesomeIcon icon={faEye} />
                                시뮬레이션 미리보기
                            </button>
                        </div>
                    </div>

                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 flex flex-col justify-between">
                        <h3 className="font-bold text-slate-700 mb-4 flex items-center gap-2 text-red-600">
                            <FontAwesomeIcon icon={faEraser} />
                            데이터 초기화
                        </h3>
                        <button
                            onClick={clearReports}
                            disabled={loading}
                            className="w-full bg-slate-100 text-red-600 border border-red-200 py-2.5 rounded-lg hover:bg-red-50 font-bold transition-colors disabled:opacity-50"
                        >
                            🗑️ 일보 데이터만 삭제
                        </button>
                    </div>
                </div>

                {/* 2. Result & Log Panel */}
                <div className="space-y-6">
                    {/* Preview Result */}
                    {simulation && (
                        <div className="bg-gradient-to-br from-indigo-50 to-blue-50 rounded-xl border border-indigo-100 p-6">
                            <h3 className="font-bold text-indigo-800 mb-4 flex items-center gap-2">
                                <FontAwesomeIcon icon={faChartSimple} />
                                시뮬레이션 결과
                            </h3>

                            <div className="grid grid-cols-2 gap-4 mb-4">
                                <div className="bg-white p-3 rounded shadow-sm">
                                    <div className="text-xs text-slate-500">생성될 일보</div>
                                    <div className="text-xl font-bold text-slate-800">{simulation.totalReports.toLocaleString()}건</div>
                                </div>
                                <div className="bg-white p-3 rounded shadow-sm">
                                    <div className="text-xs text-slate-500">총 공수 합계</div>
                                    <div className="text-xl font-bold text-slate-800">{simulation.totalManDays.toLocaleString('ko-KR', { minimumFractionDigits: 1 })}</div>
                                </div>
                                <div className="bg-white p-3 rounded shadow-sm">
                                    <div className="text-xs text-slate-500">지원(Dispatch) 건수</div>
                                    <div className="text-xl font-bold text-orange-600">{simulation.supportCount.toLocaleString()}건</div>
                                </div>
                                <div className="bg-white p-3 rounded shadow-sm">
                                    <div className="text-xs text-slate-500">예상 인건비</div>
                                    <div className="text-xl font-bold text-slate-800">{(simulation.totalAmount / 100000000).toFixed(1)}억원</div>
                                </div>
                            </div>

                            <div className="text-xs text-slate-600 flex gap-4 mb-4 bg-white/50 p-2 rounded">
                                <span>🏢 내부지원: {simulation.internalSupportCount}건</span>
                                <span>🤝 외부지원: {simulation.externalSupportCount}건</span>
                            </div>

                            <button
                                onClick={saveToDatabase}
                                disabled={loading}
                                className="w-full bg-green-600 text-white py-3 rounded-lg hover:bg-green-700 font-bold transition-colors shadow-lg shadow-green-200 flex items-center justify-center gap-2"
                            >
                                <FontAwesomeIcon icon={faSave} />
                                데이터베이스 저장 확정
                            </button>
                        </div>
                    )}

                    {/* Logs */}
                    <div className="bg-slate-900 rounded-xl p-6 text-slate-300 font-mono text-sm h-64 overflow-y-auto shadow-inner">
                        <div className="flex justify-between items-center mb-4 border-b border-slate-700 pb-2">
                            <span className="font-bold text-white">처리 로그</span>
                            <button onClick={() => setLogs([])} className="text-xs hover:text-white">지우기</button>
                        </div>
                        <div className="space-y-1">
                            {logs.length === 0 && <span className="text-slate-600 italic">대기 중...</span>}
                            {logs.map((log, index) => (
                                <div key={index} className="break-all">
                                    <span className="text-green-500 mr-2">➜</span>
                                    {log}
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default TestDailyReportGeneratorPage;

import React, { useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faFlask, faBuilding, faUserGroup, faHelmetSafety, faMapLocationDot, faFileLines, faTrash, faCheck } from '@fortawesome/free-solid-svg-icons';
import { companyService } from '../../services/companyService';
import { teamService } from '../../services/teamService';
import { manpowerService } from '../../services/manpowerService';
import { siteService } from '../../services/siteService';
import { dailyReportService } from '../../services/dailyReportService';

const TestDataGeneratorPage: React.FC = () => {
    const [logs, setLogs] = useState<string[]>([]);
    const [loading, setLoading] = useState(false);

    const addLog = (message: string) => {
        setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${message}`, ...prev]);
    };

    const generateCompanies = async () => {
        setLoading(true);
        addLog("회사 데이터 생성 시작...");
        try {
            const companies = [
                {
                    name: "전국건설",
                    businessNumber: "123-45-67890",
                    ceoName: "김대표",
                    address: "서울시 강남구",
                    code: "C001",
                    phone: "02-111-1111",
                    type: "건설사" as const,
                    siteName: "본사",
                    siteManager: "김관리",
                    status: "active" as const
                },
                {
                    name: "청연ENG",
                    businessNumber: "234-56-78901",
                    ceoName: "이대표",
                    address: "경기도 성남시",
                    code: "C002",
                    phone: "031-222-2222",
                    type: "건설사" as const,
                    siteName: "경기지사",
                    siteManager: "이관리",
                    status: "active" as const
                },
                {
                    name: "미래건설",
                    businessNumber: "345-67-89012",
                    ceoName: "박대표",
                    address: "인천시 송도",
                    code: "C003",
                    phone: "032-333-3333",
                    type: "건설사" as const,
                    siteName: "인천지사",
                    siteManager: "박관리",
                    status: "active" as const
                }
            ];

            for (const company of companies) {
                await companyService.addCompany(company);
                addLog(`회사 생성: ${company.name} (${company.type})`);
            }
            addLog("회사 데이터 생성 완료!");
        } catch (error) {
            addLog(`오류 발생: ${error}`);
        } finally {
            setLoading(false);
        }
    };

    const generateTeams = async () => {
        setLoading(true);
        addLog("팀 데이터 생성 시작...");
        try {
            const companies = await companyService.getCompanies();
            const constructionCompanies = companies.filter(c => c.type === '건설사');

            if (constructionCompanies.length === 0) {
                addLog("오류: '건설사' 타입의 회사가 없습니다.");
                setLoading(false);
                return;
            }

            // 1. 일반 시공팀 생성
            for (let i = 0; i < 6; i++) {
                const company = constructionCompanies[i % constructionCompanies.length];
                const teamName = `[${company.name}] ${i + 1}팀`;
                const leaderName = `[${company.name}] ${i + 1}팀장`;

                await teamService.addTeam({
                    name: teamName,
                    leaderName: leaderName,
                    leaderId: "temp_id",
                    companyId: company.id,
                    companyName: company.name,
                    type: "시공팀",
                    memberCount: 0
                });
                addLog(`시공팀 생성: ${teamName}`);
            }

            // 2. 지원팀 생성 (모든 건설사 대상)
            for (const company of constructionCompanies) {
                // 각 회사별로 1~2개 지원팀 생성
                for (let i = 1; i <= 2; i++) {
                    const teamName = `[${company.name}] 지원${i}팀`;
                    const leaderName = `[${company.name}] 지원${i}팀장`;

                    await teamService.addTeam({
                        name: teamName,
                        leaderName: leaderName,
                        leaderId: "temp_id",
                        companyId: company.id,
                        companyName: company.name,
                        type: "지원팀",
                        memberCount: 0
                    });
                    addLog(`지원팀 생성: ${teamName}`);
                }
            }

            addLog("팀 데이터 생성 완료!");
        } catch (error) {
            addLog(`오류 발생: ${error}`);
        } finally {
            setLoading(false);
        }
    };

    const generateSites = async () => {
        setLoading(true);
        addLog("현장 데이터 생성 시작...");
        try {
            const companies = await companyService.getCompanies();
            if (companies.length === 0) {
                addLog("오류: 회사가 없습니다.");
                setLoading(false);
                return;
            }

            const teams = await teamService.getTeams();
            const siteLocations = [
                { name: "서울 아파트", address: "서울시 강남구", code: "S001" },
                { name: "부산 항만", address: "부산시 해운대구", code: "S002" },
                { name: "인천 공항", address: "인천시 중구", code: "S003" },
                { name: "대구 스타디움", address: "대구시 수성구", code: "S004" },
                { name: "광주 쇼핑몰", address: "광주시 서구", code: "S005" },
                { name: "대전 과학단지", address: "대전시 유성구", code: "S006" }
            ];

            for (let i = 0; i < siteLocations.length; i++) {
                const location = siteLocations[i];
                const company = companies[i % companies.length];
                const siteName = `[${company.name}] ${location.name}`;

                // 책임 팀 배정
                let responsibleTeamId = '';
                let responsibleTeamName = '';
                if (teams.length > 0) {
                    const companyTeams = teams.filter(t => t.companyId === company.id);
                    const targetTeams = companyTeams.length > 0 ? companyTeams : teams;
                    const randomTeam = targetTeams[Math.floor(Math.random() * targetTeams.length)];
                    responsibleTeamId = randomTeam.id || '';
                    responsibleTeamName = randomTeam.name;
                }

                await siteService.addSite({
                    name: siteName,
                    address: location.address,
                    code: location.code,
                    status: "active",
                    companyId: company.id,
                    companyName: company.name,
                    responsibleTeamId: responsibleTeamId,
                    responsibleTeamName: responsibleTeamName
                });
                addLog(`현장 생성: ${siteName}`);
            }
            addLog("현장 데이터 생성 완료!");
        } catch (error) {
            addLog(`오류 발생: ${error}`);
        } finally {
            setLoading(false);
        }
    };

    const generateWorkers = async () => {
        setLoading(true);
        addLog("작업자 데이터 생성 시작...");
        try {
            const teams = await teamService.getTeams();
            if (teams.length === 0) {
                addLog("오류: 팀이 없습니다.");
                setLoading(false);
                return;
            }

            let totalWorkers = 0;
            for (const team of teams) {
                // 팀 타입에 따라 작업자 타입 결정
                const isSupportTeam = team.type === '지원팀';

                // 각 팀당 10명 생성
                for (let i = 1; i <= 10; i++) {
                    const role = i === 1 ? "팀장" : "작업자";
                    const workerName = `${team.name} ${role} ${i === 1 ? '' : i - 1}`.trim();

                    await manpowerService.addWorker({
                        name: workerName,
                        idNumber: `900101-1${String(i).padStart(6, '0')}`,
                        contact: `010-1234-${String(totalWorkers).padStart(4, '0')}`,
                        address: "서울시 어딘가",
                        role: role,
                        teamId: team.id,
                        teamName: team.name,
                        status: "재직",
                        unitPrice: 150000 + (i * 1000),
                        // 팀이 지원팀이면 작업자도 지원팀, 아니면 팀소속
                        teamType: isSupportTeam ? "지원팀" : "팀소속",
                        salaryModel: "일급제"
                    }, false);
                    totalWorkers++;
                }
                addLog(`팀 [${team.name}] 작업자 10명 생성 (${isSupportTeam ? '지원팀' : '일반팀'})`);
            }
            addLog(`총 ${totalWorkers}명 작업자 데이터 생성 완료!`);
        } catch (error) {
            addLog(`오류 발생: ${error}`);
        } finally {
            setLoading(false);
        }
    };

    const generateDailyReports = async (scenario: string) => {
        setLoading(true);
        addLog(`일보 데이터 생성 시작 (시나리오: ${scenario})...`);
        try {
            const sites = await siteService.getSites();
            const teams = await teamService.getTeams();
            const workers = await manpowerService.getWorkers();

            if (sites.length === 0 || teams.length === 0 || workers.length === 0) {
                addLog("오류: 현장, 팀, 또는 작업자 데이터가 없습니다.");
                setLoading(false);
                return;
            }

            const constructionTeams = teams.filter(t => t.type === '시공팀');
            const supportTeams = teams.filter(t => t.type === '지원팀');

            let count = 0;
            const today = new Date();
            const year = today.getFullYear();
            const month = today.getMonth() + 1; // 1월은 0이므로 +1

            // 지난 30일간의 데이터 생성
            for (let d = 30; d >= 0; d--) {
                const date = new Date(year, month - 1, today.getDate() - d);
                const dateStr = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
                const dayOfWeek = date.getDay(); // 0: 일요일, 1: 월요일, ..., 6: 토요일

                let dailyWeather = "맑음";
                if (scenario === 'rain' && Math.random() < 0.4) { // 장마 시나리오에서 40% 확률로 비
                    dailyWeather = "비";
                }

                // 시나리오에 따른 작업 여부 결정
                let shouldWork = true;
                if (scenario === 'standard' && dayOfWeek === 0) { // 기본 시나리오: 일요일 휴무
                    shouldWork = false;
                }
                if (dailyWeather === '비' && Math.random() < 0.7) { // 비 오는 날 70% 확률로 작업 안함
                    shouldWork = false;
                }

                if (!shouldWork) {
                    // addLog(`${dateStr}: 휴무 또는 우천으로 작업 없음.`);
                    continue;
                }

                // 각 현장에 대해 일보 생성
                for (const site of sites) {
                    // 현장 책임 팀 투입
                    const responsibleTeam = teams.find(t => t.id === site.responsibleTeamId);
                    if (responsibleTeam) {
                        const teamWorkers = workers.filter(w => w.teamId === responsibleTeam.id);
                        if (teamWorkers.length > 0) {
                            const numWorkers = Math.floor(Math.random() * (teamWorkers.length / 2)) + Math.ceil(teamWorkers.length / 2); // 절반 이상 투입
                            const selectedWorkers = teamWorkers.slice(0, numWorkers);

                            let manDay = 1; // 기본 1공수
                            if (scenario === 'full' && Math.random() < 0.5) manDay = 1.5; // 풀가동 시 50% 확률로 1.5공수
                            if (scenario === 'rain') manDay = 0.5; // 장마 시 0.5공수

                            const mappedWorkers = selectedWorkers.map(w => ({
                                workerId: w.id,
                                name: w.name,
                                role: w.role,
                                unitPrice: w.unitPrice,
                                manDay: manDay
                            }));

                            await dailyReportService.addReport({
                                date: dateStr,
                                siteId: site.id!,
                                siteName: site.name,
                                teamId: responsibleTeam.id!,
                                teamName: responsibleTeam.name,
                                writerId: 'system',
                                totalManDay: mappedWorkers.reduce((s, w) => s + w.manDay, 0),
                                totalAmount: mappedWorkers.reduce((s, w) => s + (w.unitPrice || 0) * w.manDay, 0),
                                weather: dailyWeather,
                                workContent: `${responsibleTeam.name} 일반 시공`,
                                workers: mappedWorkers as any[]
                            });
                            count++;
                        }
                    }

                    // 시나리오에 따라 지원팀 랜덤 투입
                    if (supportTeams.length > 0 && Math.random() < (scenario === 'finish' ? 0.8 : 0.2)) { // 마감 시나리오에서 80%, 그 외 20% 확률
                        const supportTeam = supportTeams[Math.floor(Math.random() * supportTeams.length)];
                        const supportWorkers = workers.filter(w => w.teamId === supportTeam.id);

                        if (supportWorkers.length > 0) {
                            const numSupportWorkers = Math.floor(Math.random() * (supportWorkers.length / 2)) + 1; // 1명 이상 절반까지
                            const selectedSupportWorkers = supportWorkers.slice(0, numSupportWorkers);

                            let manDay = 1;
                            if (scenario === 'finish' && Math.random() < 0.7) manDay = 1.5; // 마감 시 70% 확률로 1.5공수

                            const mappedSupportWorkers = selectedSupportWorkers.map(w => ({
                                workerId: w.id,
                                name: w.name,
                                role: w.role,
                                unitPrice: w.unitPrice,
                                manDay: manDay
                            }));

                            await dailyReportService.addReport({
                                date: dateStr,
                                siteId: site.id!,
                                siteName: site.name,
                                teamId: supportTeam.id!,
                                teamName: supportTeam.name,
                                writerId: 'system',
                                totalManDay: mappedSupportWorkers.reduce((s, w) => s + w.manDay, 0),
                                totalAmount: mappedSupportWorkers.reduce((s, w) => s + (w.unitPrice || 0) * w.manDay, 0),
                                weather: dailyWeather,
                                workContent: scenario === 'finish' ? '마감 긴급 지원' : '긴급 지원 작업',
                                workers: mappedSupportWorkers as any[]
                            });
                            count++;
                        }
                    }
                }
                if (d % 10 === 0) addLog(`${d}일 전 (시나리오: ${scenario}) 생성 중...`);
            }

            addLog(`총 ${count}개 일보 데이터 생성 완료 (${scenario} 모드)!`);
        } catch (error) {
            addLog(`오류 발생: ${error}`);
        } finally {
            setLoading(false);
        }
    };

    const clearAllData = async () => {
        if (!window.confirm("일보 데이터를 제외한 모든 기본 데이터(회사/팀/현장/작업자)를 삭제하시겠습니까? (이 작업은 되돌릴 수 없습니다.)")) return;

        setLoading(true);
        addLog("데이터 초기화(일보 제외) 시작...");
        try {
            // 1. 일보 삭제 (사용자 요청으로 제외)
            /* 
            const reports = await dailyReportService.getAllReports();
            addLog(`일보 데이터 ${reports.length}개 삭제 중...`);

            const reportIds = reports.map(r => r.id!).filter(id => id);
            if (reportIds.length > 0) {
                await dailyReportService.deleteReports(reportIds);
            }
            addLog(`일보 데이터 ${reports.length}개 삭제 완료`);
            */
            addLog("일보 데이터 삭제 건너뜀 (보존)");

            // 2. 작업자 삭제
            const workers = await manpowerService.getWorkers();
            const workerIds = workers.map(w => w.id!).filter(id => id);
            if (workerIds.length > 0) {
                // 500개씩 끊어서 삭제
                for (let i = 0; i < workerIds.length; i += 500) {
                    const chunk = workerIds.slice(i, i + 500);
                    await manpowerService.deleteWorkers(chunk);
                }
            }
            addLog(`작업자 데이터 ${workers.length}개 삭제 완료`);

            // 3. 현장 삭제
            const sites = await siteService.getSites();
            for (const site of sites) {
                if (site.id) await siteService.deleteSite(site.id);
            }
            addLog(`현장 데이터 ${sites.length}개 삭제 완료`);

            // 4. 팀 삭제
            const teams = await teamService.getTeams();
            for (const team of teams) {
                if (team.id) await teamService.deleteTeam(team.id);
            }
            addLog(`팀 데이터 ${teams.length}개 삭제 완료`);

            // 5. 회사 삭제
            const companies = await companyService.getCompanies();
            for (const company of companies) {
                if (company.id) await companyService.deleteCompany(company.id);
            }
            addLog(`회사 데이터 ${companies.length}개 삭제 완료`);

            addLog("기본 데이터 초기화 완료 (일보 데이터는 보존됨)!");
        } catch (error) {
            addLog(`오류 발생: ${error}`);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="p-6 max-w-7xl mx-auto">
            <div className="mb-8">
                <h1 className="text-2xl font-bold text-slate-800 flex items-center gap-3 mb-2">
                    <FontAwesomeIcon icon={faFlask} className="text-brand-600" />
                    테스트 데이터 생성기 v2.0
                </h1>
                <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 text-sm text-blue-800">
                    <h3 className="font-bold mb-2 flex items-center gap-2">
                        <FontAwesomeIcon icon={faCheck} /> 사용 가이드
                    </h3>
                    <ol className="list-decimal list-inside space-y-1 ml-2">
                        <li><strong>기본 데이터 삭제</strong> 버튼을 눌러 회사/팀/현장/작업자 데이터를 초기화합니다. (일보 데이터는 유지됩니다)</li>
                        <li><strong>1. 회사 생성</strong>부터 <strong>4. 작업자 생성</strong>까지 순서대로 버튼을 클릭합니다.</li>
                        <li>각 단계가 완료될 때까지 기다려주세요. (로그 창 확인)</li>
                        <li>모든 생성이 완료되면 <strong>통합 현황판</strong> 메뉴에서 데이터를 확인하세요.</li>
                    </ol>
                    <p className="mt-2 text-xs text-blue-600">
                        * 지원팀 테스트를 위해 '지원팀' 타입의 팀과 작업자가 자동으로 생성되며,
                        일보 생성 시 랜덤하게 지원팀이 현장에 투입되는 시나리오가 포함되어 있습니다.
                    </p>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
                {/* 1. 회사 생성 */}
                <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow">
                    <div className="flex items-center gap-3 mb-4">
                        <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-600">
                            <FontAwesomeIcon icon={faBuilding} />
                        </div>
                        <div>
                            <h3 className="font-bold text-slate-800">1. 회사 데이터</h3>
                            <p className="text-xs text-slate-500">3개 회사 생성</p>
                        </div>
                    </div>
                    <button
                        onClick={generateCompanies}
                        disabled={loading}
                        className="w-full py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-slate-300 transition-colors"
                    >
                        회사 생성
                    </button>
                </div>

                {/* 2. 팀 생성 */}
                <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow">
                    <div className="flex items-center gap-3 mb-4">
                        <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600">
                            <FontAwesomeIcon icon={faUserGroup} />
                        </div>
                        <div>
                            <h3 className="font-bold text-slate-800">2. 팀 데이터</h3>
                            <p className="text-xs text-slate-500">시공팀 6개 + 지원팀 2개</p>
                        </div>
                    </div>
                    <button
                        onClick={generateTeams}
                        disabled={loading}
                        className="w-full py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:bg-slate-300 transition-colors"
                    >
                        팀 생성
                    </button>
                </div>

                {/* 3. 현장 생성 */}
                <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow">
                    <div className="flex items-center gap-3 mb-4">
                        <div className="w-10 h-10 rounded-full bg-green-100 flex items-center justify-center text-green-600">
                            <FontAwesomeIcon icon={faMapLocationDot} />
                        </div>
                        <div>
                            <h3 className="font-bold text-slate-800">3. 현장 데이터</h3>
                            <p className="text-xs text-slate-500">6개 현장 생성</p>
                        </div>
                    </div>
                    <button
                        onClick={generateSites}
                        disabled={loading}
                        className="w-full py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:bg-slate-300 transition-colors"
                    >
                        현장 생성
                    </button>
                </div>

                {/* 4. 작업자 생성 */}
                <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow">
                    <div className="flex items-center gap-3 mb-4">
                        <div className="w-10 h-10 rounded-full bg-orange-100 flex items-center justify-center text-orange-600">
                            <FontAwesomeIcon icon={faHelmetSafety} />
                        </div>
                        <div>
                            <h3 className="font-bold text-slate-800">4. 작업자 데이터</h3>
                            <p className="text-xs text-slate-500">팀별 10명 (지원팀 포함)</p>
                        </div>
                    </div>
                    <button
                        onClick={generateWorkers}
                        disabled={loading}
                        className="w-full py-2 bg-orange-600 text-white rounded-lg hover:bg-orange-700 disabled:bg-slate-300 transition-colors"
                    >
                        작업자 생성
                    </button>
                </div>

                {/* 5. 일보 생성 */}
                <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow relative">
                    <div className="flex items-center gap-3 mb-4">
                        <div className="w-10 h-10 rounded-full bg-purple-100 flex items-center justify-center text-purple-600">
                            <FontAwesomeIcon icon={faFileLines} />
                        </div>
                        <div>
                            <h3 className="font-bold text-slate-800">5. 일보 데이터</h3>
                            <p className="text-xs text-slate-500">다양한 시나리오 테스트</p>
                        </div>
                    </div>

                    <div className="mb-3">
                        <label className="text-xs font-bold text-slate-500 mb-1 block">테스트 시나리오 선택</label>
                        <select
                            className="w-full text-sm border-slate-200 rounded-lg focus:ring-purple-500 focus:border-purple-500 mb-2"
                            id="scenario-select"
                            defaultValue="standard"
                        >
                            <option value="standard">📅 [기본] 월 25일 가동 (일요일 휴무)</option>
                            <option value="full">🔥 [골조] 풀가동 (휴일 없음/야근)</option>
                            <option value="rain">☔ [장마] 우천 다발 (공수 저조)</option>
                            <option value="finish">✨ [마감] 지원팀 집중 투입</option>
                        </select>
                    </div>

                    <button
                        onClick={async () => {
                            const scenario = (document.getElementById('scenario-select') as HTMLSelectElement).value;
                            await generateDailyReports(scenario);
                        }}
                        disabled={loading}
                        className="w-full py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 disabled:bg-slate-300 transition-colors"
                    >
                        일보 생성
                    </button>
                </div>

                {/* 초기화 */}
                <div className="bg-white p-6 rounded-xl border border-red-200 shadow-sm hover:shadow-md transition-shadow">
                    <div className="flex items-center gap-3 mb-4">
                        <div className="w-10 h-10 rounded-full bg-red-100 flex items-center justify-center text-red-600">
                            <FontAwesomeIcon icon={faTrash} />
                        </div>
                        <div>
                            <h3 className="font-bold text-slate-800">기본 데이터 삭제</h3>
                            <p className="text-xs text-slate-500">회사/팀/현장/작업자 삭제</p>
                        </div>
                    </div>
                    <button
                        onClick={clearAllData}
                        disabled={loading}
                        className="w-full py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 disabled:bg-slate-300 transition-colors"
                    >
                        삭제 (일보 제외)
                    </button>
                </div>
            </div>

            {/* 로그 영역 */}
            <div className="bg-slate-900 rounded-xl p-6 text-slate-300 font-mono text-sm h-96 overflow-y-auto shadow-inner">
                <div className="flex justify-between items-center mb-4 border-b border-slate-700 pb-2">
                    <span className="font-bold text-white">System Logs</span>
                    <button onClick={() => setLogs([])} className="text-xs hover:text-white">Clear Logs</button>
                </div>
                <div className="space-y-1">
                    {logs.length === 0 && <span className="text-slate-600 italic">대기 중...</span>}
                    {logs.map((log, index) => (
                        <div key={index} className="break-all">
                            <span className="text-green-500 mr-2">➜</span>
                            {log}
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default TestDataGeneratorPage;

import React, { useState, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { saveAs } from 'file-saver';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faFileInvoiceDollar, faSpinner, faExclamationTriangle, faCalendarAlt, faSearch
} from '@fortawesome/free-solid-svg-icons';
import { settlementService } from '../../services/settlementService';
import { SettlementEntry } from '../../types/settlement';

const TotalLaborHistoryPage: React.FC = () => {
    const [loading, setLoading] = useState(false);
    const [entries, setEntries] = useState<SettlementEntry[]>([]);
    const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
    const [searchTerm, setSearchTerm] = useState('');

    useEffect(() => {
        loadData();
    }, [selectedMonth]);

    const loadData = async () => {
        setLoading(true);
        try {
            const data = await settlementService.getAllSettlements(selectedMonth);
            setEntries(data);
        } catch (error) {
            console.error(error);
            alert("데이터를 불러오는 중 오류가 발생했습니다.");
        } finally {
            setLoading(false);
        }
    };

    const handleExportExcel = () => {
        if (entries.length === 0) {
            alert("내보낼 데이터가 없습니다.");
            return;
        }

        const excelData = entries.map((entry, index) => ({
            'No': index + 1,
            '이름': entry.workerName,
            '주민번호': entry.workerId ? '******-*******' : '-', // Masked for privacy in demo
            '직책': entry.role,
            '소속팀': entry.teamId, // Should ideally map to team name if available in entry
            '신고 현장': entry.reportedSite,
            '신고 공수': entry.reportedDays,
            '신고 급여': entry.reportedGrossPay,
            '세금(3.3%)': entry.taxAmount,
            '실지급액': entry.netPay,
            '상태': entry.status === 'paid' ? '지급완료' : '대기'
        }));

        const worksheet = XLSX.utils.json_to_sheet(excelData);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, '전체인원내역');
        const excelBuffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
        const data = new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;charset=UTF-8' });
        saveAs(data, `전체인원내역_${selectedMonth}.xlsx`);
    };

    const filteredEntries = entries.filter(entry =>
        entry.workerName.includes(searchTerm) ||
        (entry.reportedSite && entry.reportedSite.includes(searchTerm))
    );

    // Calculate Totals
    const totalReportedDays = filteredEntries.reduce((sum, e) => sum + e.reportedDays, 0);
    const totalReportedGross = filteredEntries.reduce((sum, e) => sum + e.reportedGrossPay, 0);
    const totalTax = filteredEntries.reduce((sum, e) => sum + e.taxAmount, 0);
    const totalNetPay = filteredEntries.reduce((sum, e) => sum + e.netPay, 0);

    return (
        <div className="p-6 max-w-[1800px] mx-auto">
            <div className="mb-6 flex justify-between items-center">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                        <FontAwesomeIcon icon={faFileInvoiceDollar} className="text-indigo-600" />
                        인원 전체 내역 조회 (Total Labor History)
                    </h1>
                    <p className="text-slate-500 text-sm">전체 현장/팀의 노무 신고용 데이터 통합 조회</p>
                </div>
                <button
                    onClick={handleExportExcel}
                    className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 flex items-center gap-2"
                >
                    <FontAwesomeIcon icon={faFileInvoiceDollar} />
                    전체 엑셀 다운로드
                </button>
            </div>

            {/* Controls */}
            <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-wrap items-center gap-4">
                <div className="flex items-center gap-2 bg-slate-50 px-3 py-2 rounded-lg border border-slate-200">
                    <FontAwesomeIcon icon={faCalendarAlt} className="text-slate-400" />
                    <input
                        type="month"
                        value={selectedMonth}
                        onChange={(e) => setSelectedMonth(e.target.value)}
                        className="bg-transparent border-none text-slate-700 font-bold focus:ring-0"
                    />
                </div>

                <div className="flex items-center gap-2 bg-slate-50 px-3 py-2 rounded-lg border border-slate-200 flex-1 max-w-md">
                    <FontAwesomeIcon icon={faSearch} className="text-slate-400" />
                    <input
                        type="text"
                        placeholder="이름 또는 현장 검색..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="bg-transparent border-none text-slate-700 w-full focus:ring-0"
                    />
                </div>
            </div>

            {/* Summary Cards */}
            <div className="grid grid-cols-4 gap-4 mb-6">
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                    <div className="text-slate-500 text-xs mb-1">총 인원</div>
                    <div className="text-2xl font-bold text-slate-800">{filteredEntries.length}명</div>
                </div>
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                    <div className="text-slate-500 text-xs mb-1">총 신고 공수</div>
                    <div className="text-2xl font-bold text-blue-600">{totalReportedDays.toLocaleString()}공수</div>
                </div>
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                    <div className="text-slate-500 text-xs mb-1">총 신고 급여</div>
                    <div className="text-2xl font-bold text-slate-800">{totalReportedGross.toLocaleString()}원</div>
                </div>
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                    <div className="text-slate-500 text-xs mb-1">총 세금 (3.3%)</div>
                    <div className="text-2xl font-bold text-red-600">{totalTax.toLocaleString()}원</div>
                </div>
            </div>

            {/* Main Table */}
            <div className="bg-white rounded-xl shadow-lg border border-slate-300 overflow-hidden overflow-x-auto">
                {loading ? (
                    <div className="p-20 text-center text-slate-500">
                        <FontAwesomeIcon icon={faSpinner} spin className="text-3xl mb-4 text-indigo-500" />
                        <p>전체 데이터를 집계 중입니다...</p>
                    </div>
                ) : filteredEntries.length === 0 ? (
                    <div className="p-20 text-center text-slate-400">
                        <FontAwesomeIcon icon={faExclamationTriangle} className="text-3xl mb-4 opacity-50" />
                        <p>데이터가 없습니다.</p>
                    </div>
                ) : (
                    <table className="w-full text-sm border-collapse min-w-[1000px]">
                        <thead>
                            <tr className="bg-slate-100 text-slate-700 text-xs uppercase font-bold text-center border-b border-slate-300">
                                <th className="p-3 border-r border-slate-300 w-12">No</th>
                                <th className="p-3 border-r border-slate-300 w-24">이름</th>
                                <th className="p-3 border-r border-slate-300 w-24">직책</th>
                                <th className="p-3 border-r border-slate-300 w-40 bg-indigo-50">신고 현장</th>
                                <th className="p-3 border-r border-slate-300 w-24 bg-blue-50">신고 공수</th>
                                <th className="p-3 border-r border-slate-300 w-32">신고 급여 (총액)</th>
                                <th className="p-3 border-r border-slate-300 w-24 text-red-600">세금 (3.3%)</th>
                                <th className="p-3 border-r border-slate-300 w-32 bg-indigo-50 text-indigo-900">실지급액</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-200">
                            {filteredEntries.map((entry, idx) => (
                                <tr key={entry.id} className="hover:bg-slate-50">
                                    <td className="p-3 text-center text-slate-500">{idx + 1}</td>
                                    <td className="p-3 text-center font-bold text-slate-700">{entry.workerName}</td>
                                    <td className="p-3 text-center text-slate-500 text-xs">{entry.role}</td>
                                    <td className="p-3 text-center text-slate-600 font-medium bg-indigo-50/10">
                                        {entry.reportedSite || '-'}
                                    </td>
                                    <td className="p-3 text-center font-bold text-blue-600 bg-blue-50/10">
                                        {entry.reportedDays}
                                    </td>
                                    <td className="p-3 text-right font-bold text-slate-800">
                                        {entry.reportedGrossPay.toLocaleString()}
                                    </td>
                                    <td className="p-3 text-right text-red-600">
                                        {entry.taxAmount.toLocaleString()}
                                    </td>
                                    <td className="p-3 text-right font-bold text-indigo-700 bg-indigo-50/30">
                                        {entry.netPay.toLocaleString()}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                )}
            </div>
        </div>
    );
};

export default TotalLaborHistoryPage;

import React, { useEffect, useMemo, useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faChevronDown, faDownload, faFileInvoiceDollar, faSearch, faSync, faTimes, faUser } from '@fortawesome/free-solid-svg-icons';
import { motion, AnimatePresence } from 'framer-motion';
import * as XLSX from 'xlsx-js-style';
import { dailyReportService, DailyReportWorkerRow } from '../../services/dailyReportService';
import { companyService, Company } from '../../services/companyService';
import { manpowerService, Worker } from '../../services/manpowerService';
import { teamService, Team } from '../../services/teamService';
import { normalizeTypedDateInput, sanitizeTypedDateInput } from '../../utils/typedDateInput';
import { resolveReportPayType, resolveWorkerPayType } from '../../utils/payType';
import OutputManagementTabs from '../../components/common/OutputManagementTabs';

type CompanyTypeFilter = 'construction' | 'partner';
type SalaryModelFilter = '전체' | '일급제' | '월급제' | '지원팀' | '용역팀';

interface PersonnelHistoryRow {
    workerId: string;
    name: string;
    idNumber: string;
    salaryModel: SalaryModelFilter;
    teamId: string;
    teamName: string;
    totalManDay: number;
    laborManDay: number;
    invoiceManDay: number;
    unitPrice: number;
    laborAmount: number;
    invoiceAmount: number;
    totalAmount: number;
}

const resolveWorkerSalaryModel = (worker: Worker): SalaryModelFilter => {
    const payType = resolveWorkerPayType(worker);
    if (payType === '일급제') return '일급제';
    if (payType === '월급제') return '월급제';
    if (payType === '지원팀') return '지원팀';
    if (payType === '용역팀') return '용역팀';
    return '전체';
};

const resolveSnapshotSalaryModel = (params: {
    worker: Worker;
    reportSalaryModel?: string;
    reportPayType?: string;
}): SalaryModelFilter => {
    const payType = resolveReportPayType({
        salaryModel: params.reportSalaryModel,
        payType: params.reportPayType
    }, params.worker);
    if (payType === '일급제') return '일급제';
    if (payType === '월급제') return '월급제';
    if (payType === '지원팀') return '지원팀';
    if (payType === '용역팀') return '용역팀';
    return '전체';
};

const normalizeCategoryKey = (value: unknown): string => {
    return String(value ?? '')
        .replace(/\s+/g, '')
        .trim();
};

const classifyInvoiceBySiteContext = (params: {
    paymentType?: unknown;
    siteType?: unknown;
    salaryModel: SalaryModelFilter;
}): boolean => {
    const paymentKey = normalizeCategoryKey(params.paymentType);
    const siteTypeKey = normalizeCategoryKey(params.siteType);

    if (paymentKey.includes('노무')) return false;
    if (paymentKey.includes('계산서') || paymentKey.includes('계산')) return true;

    if (siteTypeKey.includes('직영')) return false;
    if (siteTypeKey.includes('도급') || siteTypeKey.includes('지원')) return true;

    if (params.salaryModel === '지원팀') return true;
    return false;
};

const formatResidentNumberForDisplay = (rawValue: string): string => {
    const raw = String(rawValue ?? '').trim();
    if (!raw) return '';

    const digits = raw.replace(/[^0-9]/g, '');
    if (digits.length === 13) {
        return `${digits.slice(0, 6)}-${digits.slice(6)}`;
    }
    return raw;
};

const formatManDay = (value: number): string => {
    return Number.isFinite(value) ? value.toFixed(2) : '0.00';
};


const TotalPersonnelHistoryPage: React.FC = () => {
    return (
        <div className="flex flex-col overflow-hidden" style={{ height: 'calc(100vh - var(--header-height))' }}>
            <OutputManagementTabs activeTab="history" title="인원관리" />
            <div className="flex flex-col overflow-hidden flex-1" style={{ minHeight: 0 }}>
                <TotalPersonnelHistoryInner />
            </div>
        </div>
    );
};

const TotalPersonnelHistoryInner: React.FC = () => {
    const today = new Date();
    const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
    const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0);

    const formatDate = (date: Date) => {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    };

    const [startDate, setStartDate] = useState(formatDate(firstDay));
    const [endDate, setEndDate] = useState(formatDate(lastDay));
    const [startDateInput, setStartDateInput] = useState(formatDate(firstDay));
    const [endDateInput, setEndDateInput] = useState(formatDate(lastDay));

    const [companyType, setCompanyType] = useState<CompanyTypeFilter>('construction');
    const [salaryModel, setSalaryModel] = useState<SalaryModelFilter>('전체');

    const [selectedTeamId, setSelectedTeamId] = useState<string>('');
    const [selectedWorkerId, setSelectedWorkerId] = useState<string>('');
    const [workerSearchTerm, setWorkerSearchTerm] = useState<string>('');
    const [isWorkerDropdownOpen, setIsWorkerDropdownOpen] = useState(false);
    const [activeIndex, setActiveIndex] = useState(0);

    const [historyData, setHistoryData] = useState<PersonnelHistoryRow[]>([]);
    const [teamScopeRows, setTeamScopeRows] = useState<DailyReportWorkerRow[]>([]);
    const [companies, setCompanies] = useState<Company[]>([]);
    const [teams, setTeams] = useState<Team[]>([]);
    const [allWorkers, setAllWorkers] = useState<Worker[]>([]);
    const [loading, setLoading] = useState(false);
    const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc');
    const [isFixed, setIsFixed] = useState<boolean>(true);

    // Lock parent scroll for internal scrolling
    useEffect(() => {
        const mainContent = document.getElementById('main-content');
        if (mainContent) {
            const originalOverflow = mainContent.style.overflow;
            mainContent.style.overflow = 'hidden';
            return () => {
                mainContent.style.overflow = originalOverflow;
            };
        }
    }, []);

    const fetchInitialData = async () => {
        try {
            const [fetchedTeams, fetchedCompanies, fetchedWorkers] = await Promise.all([
                teamService.getTeams(),
                companyService.getCompanies(),
                manpowerService.getWorkers()
            ]);
            setTeams(fetchedTeams);
            setCompanies(fetchedCompanies);
            setAllWorkers(fetchedWorkers);
        } catch (error) {
            console.error('Error fetching initial data:', error);
        }
    };

    useEffect(() => {
        void fetchInitialData();
    }, []);

    useEffect(() => {
        setStartDateInput(startDate);
    }, [startDate]);

    useEffect(() => {
        setEndDateInput(endDate);
    }, [endDate]);

    useEffect(() => {
        if (companyType === 'partner') {
            setSalaryModel('지원팀');
        } else {
            if (salaryModel === '지원팀') setSalaryModel('전체');
        }
        setSelectedTeamId('');
        setSelectedWorkerId('');
        setWorkerSearchTerm('');
    }, [companyType]);

    const companyById = useMemo(() => {
        const map = new Map<string, Company>();
        companies.forEach((company) => {
            if (!company.id) return;
            map.set(company.id, company);
        });
        return map;
    }, [companies]);

    const teamById = useMemo(() => {
        const map = new Map<string, Team>();
        teams.forEach((team) => {
            if (team.id) map.set(String(team.id).trim(), team);
            if ((team as any).legacyId) map.set(String((team as any).legacyId).trim(), team);
        });
        return map;
    }, [teams]);

    const teamByName = useMemo(() => {
        const map = new Map<string, Team>();
        teams.forEach((team) => {
            const nameKey = String(team.name ?? '').replace(/\s+/g, '').trim();
            if (nameKey && !map.has(nameKey)) {
                map.set(nameKey, team);
            }
        });
        return map;
    }, [teams]);

    const allowedTeamIds = useMemo(() => {
        const ids = new Set<string>();
        teams.forEach((team) => {
            if (!team.id) return;
            const companyId = String(team.companyId ?? '').trim();
            if (!companyId) return;
            const company = companyById.get(companyId);
            if (!company) return;

            const teamId = String(team.id).trim();
            const teamLegacyId = String((team as any).legacyId ?? '').trim();
            const isAllowed =
                (companyType === 'construction' && company.type === '시공사')
                || (companyType === 'partner' && company.type === '협력사');
            if (!isAllowed) return;

            if (teamId) ids.add(teamId);
            if (teamLegacyId) ids.add(teamLegacyId);
        });
        return ids;
    }, [companyById, companyType, teams]);

    const teamOptions = useMemo(() => {
        const scopedSupportTeamIds =
            companyType === 'partner'
                ? new Set(
                    teamScopeRows
                        .map((row) => {
                            const rawTeamId = String(row.workerTeamId ?? '').trim();
                            if (rawTeamId) {
                                return String(teamById.get(rawTeamId)?.id ?? rawTeamId).trim();
                            }
                            const rawTeamName = String(row.workerTeamName ?? '').replace(/\s+/g, '').trim();
                            return String(teamByName.get(rawTeamName)?.id ?? '').trim();
                        })
                        .filter((id) => Boolean(id) && allowedTeamIds.has(id))
                )
                : null;

        return teams
            .filter((team) => Boolean(team.id) && team.id && allowedTeamIds.has(team.id))
            .filter((team) => {
                if (companyType !== 'partner') return true;
                const canonicalTeamId = String(team.id ?? '').trim();
                return scopedSupportTeamIds ? scopedSupportTeamIds.has(canonicalTeamId) : false;
            })
            .slice()
            .sort((a, b) => String(a.name ?? '').localeCompare(String(b.name ?? ''), 'ko'));
    }, [allowedTeamIds, companyType, teamById, teamByName, teamScopeRows, teams]);

    const workerOptions = useMemo(() => {
        const filtered = allWorkers
            .filter((worker) => Boolean(worker.id))
            .filter((worker) => {
                if (!workerSearchTerm) return true;
                const nameMatch = String(worker.name ?? '').includes(workerSearchTerm);
                const idMatch = String(worker.idNumber ?? '').includes(workerSearchTerm);
                return nameMatch || idMatch;
            })
            .filter((worker) => {
                const teamId = String(worker.teamId ?? '').trim();
                if (!teamId) return false;
                if (!allowedTeamIds.has(teamId)) return false;
                if (selectedTeamId && teamId !== selectedTeamId) return false;

                const model = resolveWorkerSalaryModel(worker);
                if (companyType === 'partner') return model === '지원팀';
                return model === '일급제' || model === '월급제' || model === '용역팀';
            })
            .filter((worker) => {
                const model = resolveWorkerSalaryModel(worker);
                if (companyType === 'partner') return model === '지원팀';
                if (salaryModel === '전체') return model === '일급제' || model === '월급제' || model === '용역팀';
                return model === salaryModel;
            })
            .slice()
            .sort((a, b) => String(a.name ?? '').localeCompare(String(b.name ?? ''), 'ko'));

        return filtered;
    }, [allWorkers, allowedTeamIds, companyType, salaryModel, selectedTeamId, workerSearchTerm]);

    // Reset active index when search term changes or dropdown opens
    useEffect(() => {
        setActiveIndex(0);
    }, [workerSearchTerm, isWorkerDropdownOpen]);

    // Handle Keyboard Navigation
    const handleWorkerKeyDown = (e: React.KeyboardEvent) => {
        if (!isWorkerDropdownOpen) {
            if (e.key === 'ArrowDown' || e.key === 'Enter') {
                setIsWorkerDropdownOpen(true);
            }
            return;
        }

        switch (e.key) {
            case 'ArrowDown':
                e.preventDefault();
                setActiveIndex(prev => (prev < workerOptions.length - 1 ? prev + 1 : prev));
                break;
            case 'ArrowUp':
                e.preventDefault();
                setActiveIndex(prev => (prev > 0 ? prev - 1 : prev));
                break;
            case 'Enter':
                e.preventDefault();
                if (workerOptions.length > 0 && activeIndex >= 0) {
                    const selected = workerOptions[activeIndex];
                    setSelectedWorkerId(selected.id || '');
                    setIsWorkerDropdownOpen(false);
                }
                break;
            case 'Escape':
                setIsWorkerDropdownOpen(false);
                break;
            case 'Tab':
                setIsWorkerDropdownOpen(false);
                break;
        }
    };

    // Text Highlighter Utility
    const HighlightText = ({ text, highlight }: { text: string; highlight: string }) => {
        if (!highlight.trim()) return <span>{text}</span>;
        const parts = text.split(new RegExp(`(${highlight})`, 'gi'));
        return (
            <span>
                {parts.map((part, i) =>
                    part.toLowerCase() === highlight.toLowerCase() ? (
                        <span key={i} className="bg-yellow-200 text-slate-900 rounded-sm px-0.5">{part}</span>
                    ) : (
                        <span key={i}>{part}</span>
                    )
                )}
            </span>
        );
    };

    useEffect(() => {
        const selectableTeamIds = new Set(
            teamOptions
                .map((team) => String(team.id ?? '').trim())
                .filter((id) => Boolean(id))
        );

        if (selectedTeamId && !selectableTeamIds.has(selectedTeamId)) {
            setSelectedTeamId('');
            setSelectedWorkerId('');
            setWorkerSearchTerm('');
            return;
        }
        if (selectedWorkerId && !workerOptions.some((w) => w.id === selectedWorkerId)) {
            setSelectedWorkerId('');
        }
    }, [selectedTeamId, selectedWorkerId, teamOptions, workerOptions]);

    useEffect(() => {
        let cancelled = false;

        const loadTeamScopeRows = async () => {
            if (companyType !== 'partner') {
                setTeamScopeRows([]);
                return;
            }

            try {
                const rows = await dailyReportService.getReportWorkerRowsByRange({
                    startDate,
                    endDate
                });
                if (!cancelled) {
                    setTeamScopeRows(rows);
                }
            } catch (error) {
                console.error('Error fetching support team options:', error);
                if (!cancelled) {
                    setTeamScopeRows([]);
                }
            }
        };

        void loadTeamScopeRows();

        return () => {
            cancelled = true;
        };
    }, [companyType, endDate, startDate]);

    const commitDateDrafts = () => {
        const nextStartDate = normalizeTypedDateInput(startDateInput) ?? startDate;
        const nextEndDate = normalizeTypedDateInput(endDateInput) ?? endDate;

        setStartDateInput(nextStartDate);
        setEndDateInput(nextEndDate);

        if (nextStartDate !== startDate) setStartDate(nextStartDate);
        if (nextEndDate !== endDate) setEndDate(nextEndDate);

        return {
            startDate: nextStartDate,
            endDate: nextEndDate,
        };
    };

    const fetchData = async (dateOverride?: { startDate: string; endDate: string }) => {
        setLoading(true);
        try {
            const effectiveStartDate = dateOverride?.startDate ?? startDate;
            const effectiveEndDate = dateOverride?.endDate ?? endDate;
            const [workers, reportRows] = await Promise.all([
                manpowerService.getWorkers(),
                dailyReportService.getReportWorkerRowsByRange({ startDate: effectiveStartDate, endDate: effectiveEndDate })
            ]);
            setTeamScopeRows(reportRows);
            const workerById = new Map<string, Worker>();
            workers.forEach((w) => {
                const id = String(w.id ?? '').trim();
                const legacyId = String((w as any).legacyId ?? '').trim();
                if (id) workerById.set(id, w);
                if (legacyId) workerById.set(legacyId, w);
            });

            const normalizeTeamId = (value?: string | null): string => {
                const raw = String(value ?? '').trim();
                if (!raw) return '';
                return String(teamById.get(raw)?.id ?? raw).trim();
            };

            const normalizeWorkerId = (value?: string | null): string => {
                const raw = String(value ?? '').trim();
                if (!raw) return '';
                return String(workerById.get(raw)?.id ?? raw).trim();
            };

            const selectedNormalizedTeamId = normalizeTeamId(selectedTeamId);
            const selectedWorkerIds = new Set<string>();
            if (selectedWorkerId) {
                const normalizedSelectedWorkerId = normalizeWorkerId(selectedWorkerId);
                if (normalizedSelectedWorkerId) selectedWorkerIds.add(normalizedSelectedWorkerId);

                const selectedWorker =
                    workerById.get(String(selectedWorkerId).trim())
                    ?? allWorkers.find((worker) => String(worker.id ?? '').trim() === String(selectedWorkerId).trim());
                const selectedLegacyId = String((selectedWorker as any)?.legacyId ?? '').trim();
                const normalizedLegacyId = normalizeWorkerId(selectedLegacyId);
                if (normalizedLegacyId) selectedWorkerIds.add(normalizedLegacyId);
            }

            const search = workerSearchTerm.trim();

            const statsByWorker = new Map<string, {
                workerId: string;
                name: string;
                idNumber: string;
                salaryModel: SalaryModelFilter;
                teamId: string;
                teamName: string;
                laborManDay: number;
                invoiceManDay: number;
                laborAmount: number;
                invoiceAmount: number;
            }>();
            const salaryByWorker = new Map<string, SalaryModelFilter>();
            const siteById = new Map<string, { siteType?: unknown; paymentMethod?: unknown }>();

            reportRows.forEach((row) => {
                const rawWorkerId = String(row.workerId ?? '').trim();
                if (!rawWorkerId) return;

                const normalizedWorkerId = normalizeWorkerId(rawWorkerId);
                if (!normalizedWorkerId) return;
                if (selectedWorkerIds.size > 0 && !selectedWorkerIds.has(normalizedWorkerId)) return;

                const worker = workerById.get(rawWorkerId) ?? workerById.get(normalizedWorkerId);
                const workerName = String(row.workerName ?? worker?.name ?? '').trim();
                const idNumber = String(worker?.idNumber ?? '').trim();
                if (search && selectedWorkerIds.size === 0) {
                    const matchesName = workerName.includes(search);
                    const matchesIdNumber = idNumber.includes(search);
                    if (!matchesName && !matchesIdNumber) return;
                }

                const workerTeamId = normalizeTeamId(String(row.workerTeamId ?? worker?.teamId ?? '').trim());
                if (!workerTeamId) return;
                if (!allowedTeamIds.has(workerTeamId)) return;
                if (selectedNormalizedTeamId && workerTeamId !== selectedNormalizedTeamId) return;

                const workerId = normalizedWorkerId;
                const rw = row;
                const report = row as any;

                const model = resolveSnapshotSalaryModel({
                    worker: worker ?? ({
                        name: row.name ?? '',
                        salaryModel: row.salaryModel ?? '',
                        payType: row.payType ?? '',
                    }),
                    reportSalaryModel: row.salaryModel,
                    reportPayType: row.payType
                });

                    if (companyType === 'partner') {
                        if (model !== '지원팀') return;
                    } else {
                        if (model !== '일급제' && model !== '월급제' && model !== '지원팀' && model !== '용역팀') return;

                        if (salaryModel === '전체') {
                            if (model !== '일급제' && model !== '월급제' && model !== '용역팀') return;
                        } else {
                            if (model !== salaryModel) return;
                        }
                    }

                    const prevModel = salaryByWorker.get(workerId);
                    if (!prevModel) salaryByWorker.set(workerId, model);

                    const manDay = typeof rw.manDay === 'number' ? rw.manDay : 0;
                    const snapshotUnitPrice = typeof rw.unitPrice === 'number' ? rw.unitPrice : null;
                    const fallbackUnitPrice = typeof worker?.unitPrice === 'number' ? worker.unitPrice : 0;
                    const unitPrice = snapshotUnitPrice ?? fallbackUnitPrice;
                    const amount = typeof rw.amount === 'number' ? rw.amount : (manDay * unitPrice);

                    const current = statsByWorker.get(workerId) ?? {
                        workerId,
                        name: workerName,
                        idNumber,
                        salaryModel: model,
                        teamId: workerTeamId,
                        teamName: String(rw.workerTeamName ?? teamById.get(workerTeamId)?.name ?? worker?.teamName ?? '').trim(),
                        laborManDay: 0,
                        invoiceManDay: 0,
                        laborAmount: 0,
                        invoiceAmount: 0
                    };
                    if (!current.name && workerName) current.name = workerName;
                    if (!current.idNumber && idNumber) current.idNumber = idNumber;
                    if (!current.teamId && workerTeamId) current.teamId = workerTeamId;
                    if (!current.teamName) {
                        current.teamName = String(rw.workerTeamName ?? teamById.get(workerTeamId)?.name ?? worker?.teamName ?? '').trim();
                    }
                    // 2024-05-22 Separate Labor/Invoice based on siteType & paymentType
                    const site = siteById.get(String(report.siteId ?? '').trim());
                    const siteType = report.siteType ?? rw.siteType ?? site?.siteType;
                    const paymentType = report.paymentType ?? rw.paymentType ?? site?.paymentMethod;
                    const isInvoice = classifyInvoiceBySiteContext({
                        paymentType,
                        siteType,
                        salaryModel: model
                    });

                    if (isInvoice) {
                        current.invoiceManDay += manDay;
                        current.invoiceAmount += amount;
                    } else {
                        current.laborManDay += manDay;
                        current.laborAmount += amount;
                    }

                    statsByWorker.set(workerId, current);
            });

            const result: PersonnelHistoryRow[] = [];
            statsByWorker.forEach((stats, workerId) => {
                const worker = workerById.get(workerId);
                const teamId = stats.teamId || String(worker?.teamId ?? '').trim();
                const teamName = stats.teamName || teamById.get(teamId)?.name || String(worker?.teamName ?? '');
                const model = salaryByWorker.get(workerId) ?? stats.salaryModel ?? resolveWorkerSalaryModel(worker ?? ({ name: stats.name } as Worker));
                const fallbackUnitPrice = typeof worker?.unitPrice === 'number' ? worker.unitPrice : 0;

                const totalManDay = stats.laborManDay + stats.invoiceManDay;
                const totalAmount = stats.laborAmount + stats.invoiceAmount;
                const computedUnitPrice = totalManDay > 0 ? Math.round(totalAmount / totalManDay) : fallbackUnitPrice;

                result.push({
                    workerId,
                    name: stats.name || String(worker?.name ?? ''),
                    idNumber: stats.idNumber || String(worker?.idNumber ?? ''),
                    salaryModel: model,
                    teamId,
                    teamName,
                    laborManDay: stats.laborManDay,
                    invoiceManDay: stats.invoiceManDay,
                    totalManDay,
                    unitPrice: computedUnitPrice,
                    laborAmount: stats.laborAmount,
                    invoiceAmount: stats.invoiceAmount,
                    totalAmount
                });
            });

            result.sort((a, b) => {
                const cmp = String(a.name ?? '').localeCompare(String(b.name ?? ''), 'ko');
                return sortOrder === 'asc' ? cmp : -cmp;
            });

            setHistoryData(result);
        } catch (error) {
            console.error('Error fetching history data:', error);
            alert('데이터 조회 중 오류가 발생했습니다.');
        } finally {
            setLoading(false);
        }
    };

    const handleDownloadExcel = () => {
        if (historyData.length === 0) {
            alert('다운로드할 데이터가 없습니다. 먼저 조회해주세요.');
            return;
        }

        const headers = ['No', '이름', '주민번호', '본봉'] as const;
        const wsData: Array<Array<string | number>> = [headers.slice() as unknown as Array<string | number>];

        historyData.forEach((row, index) => {
            wsData.push([
                index + 1,
                row.name,
                formatResidentNumberForDisplay(row.idNumber),
                row.invoiceAmount
            ]);
        });

        const ws = XLSX.utils.aoa_to_sheet(wsData);

        // Column widths
        ws['!cols'] = [
            { wch: 6 },
            { wch: 12 },
            { wch: 20 },
            { wch: 16 }
        ];

        // Number formats (xlsx-js-style)
        const setCellNumFmt = (rowIndex: number, colIndex: number, numFmt: string) => {
            const addr = XLSX.utils.encode_cell({ r: rowIndex, c: colIndex });
            const cell = ws[addr] as { t?: string; v?: unknown; s?: Record<string, unknown> } | undefined;
            if (!cell) return;
            cell.s = { ...(cell.s ?? {}), numFmt };
        };

        // Data rows start at r=1 (r=0 is header)
        for (let r = 1; r < wsData.length; r += 1) {
            setCellNumFmt(r, 3, '#,##0');   // 본봉
        }

        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, '인원전체내역');
        XLSX.writeFile(wb, `인원전체내역_${startDate}_${endDate}.xlsx`);
    };

    const handleSyncPartner = async () => {
        if (!window.confirm('협력사 소속 작업자들의 급여방식을 "지원팀"으로 일괄 동기화합니다. 계속하시겠습니까?')) return;
        try {
            const result = await manpowerService.syncPartnerCompanyWorkersTeamType();
            if (result.updated > 0) {
                alert(`${result.updated}명의 작업자가 "지원팀"으로 동기화되었습니다.`);
            } else if (result.errors.length > 0) {
                alert(`동기화 실패: ${result.errors.join(', ')}`);
            } else {
                alert('동기화할 작업자가 없습니다. (이미 모두 동기화됨)');
            }
        } catch (error) {
            alert('동기화 중 오류가 발생했습니다.');
            console.error(error);
        }
    };

    const handleSyncReports = async () => {
        if (!window.confirm('기존 일보의 작업자별 급여방식을 일괄 동기화합니다. 시간이 걸릴 수 있습니다. 계속하시겠습니까?')) return;
        try {
            const result = await dailyReportService.syncReportsSalaryModel();
            if (result.updated > 0) {
                alert(`${result.updated}개의 일보가 동기화되었습니다.`);
            } else if (result.errors.length > 0) {
                alert(`동기화 실패: ${result.errors.join(', ')}`);
            } else {
                alert('동기화할 일보가 없습니다. (이미 모두 동기화됨)');
            }
        } catch (error) {
            alert('동기화 중 오류가 발생했습니다.');
            console.error(error);
        }
    };

    return (
        <div className="flex-1 flex flex-col min-h-0 bg-slate-50 overflow-hidden">
            {/* Header */}
            <div className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between flex-shrink-0">
                <div className="flex flex-col">
                    <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                        <FontAwesomeIcon icon={faFileInvoiceDollar} className="text-blue-600" />
                        인원 전체내역 조회
                    </h1>
                    <p className="text-sm text-slate-500 mt-1">
                        기간별 전체 인원의 공수 및 급여 내역을 조회하고 엑셀로 다운로드합니다.
                    </p>
                </div>
                {/* Header Buttons Row */}
                <div className="flex items-center gap-2">
                    <button
                        onClick={handleDownloadExcel}
                        className="flex items-center gap-2 px-3 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-all shadow-sm font-medium text-sm"
                    >
                        <FontAwesomeIcon icon={faDownload} />
                        세무용 Excel
                    </button>
                    <button
                        onClick={handleSyncReports}
                        className="flex items-center gap-2 px-3 py-2 bg-purple-500 text-white rounded-lg hover:bg-purple-600 transition-all shadow-sm font-medium text-sm"
                    >
                        <FontAwesomeIcon icon={faSync} />
                        일보
                    </button>
                </div>
            </div>

            {/* Main Content */}
            <div className="flex-1 flex flex-col p-4 overflow-hidden gap-3">
                {/* Filter Bar */}
                <div className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm flex flex-col gap-3 flex-shrink-0">
                    <div className="flex flex-wrap items-end gap-3">
                        <div className="flex flex-col gap-1">
                            <div className="flex items-center gap-1">
                                <label className="text-xs font-medium text-slate-500">시작일</label>
                                <button
                                    onClick={() => {
                                        const t = new Date();
                                        const nextStartDate = formatDate(new Date(t.getFullYear(), t.getMonth() - 1, 1));
                                        const nextEndDate = formatDate(new Date(t.getFullYear(), t.getMonth(), 0));
                                        setStartDate(nextStartDate);
                                        setEndDate(nextEndDate);
                                        setStartDateInput(nextStartDate);
                                        setEndDateInput(nextEndDate);
                                    }}
                                    className="px-1.5 py-0.5 text-[10px] bg-slate-100 hover:bg-slate-200 rounded"
                                >
                                    전달
                                </button>
                                <button
                                    onClick={() => {
                                        const t = new Date();
                                        const nextStartDate = formatDate(new Date(t.getFullYear(), t.getMonth(), 1));
                                        const nextEndDate = formatDate(t);
                                        setStartDate(nextStartDate);
                                        setEndDate(nextEndDate);
                                        setStartDateInput(nextStartDate);
                                        setEndDateInput(nextEndDate);
                                    }}
                                    className="px-1.5 py-0.5 text-[10px] bg-slate-100 hover:bg-slate-200 rounded"
                                >
                                    이달
                                </button>
                            </div>
                            <input
                                type="text"
                                inputMode="numeric"
                                value={startDateInput}
                                onChange={(e) => setStartDateInput(sanitizeTypedDateInput(e.target.value))}
                                onBlur={() => {
                                    const nextStartDate = normalizeTypedDateInput(startDateInput) ?? startDate;
                                    setStartDateInput(nextStartDate);
                                    if (nextStartDate !== startDate) {
                                        setStartDate(nextStartDate);
                                    }
                                }}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        e.currentTarget.blur();
                                    }
                                }}
                                placeholder="YYYY-MM-DD"
                                className="px-2 py-1.5 bg-slate-50 border border-slate-200 rounded-lg text-sm w-36"
                            />
                        </div>

                        <div className="flex flex-col gap-1">
                            <label className="text-xs font-medium text-slate-500">종료일</label>
                            <input
                                type="text"
                                inputMode="numeric"
                                value={endDateInput}
                                onChange={(e) => setEndDateInput(sanitizeTypedDateInput(e.target.value))}
                                onBlur={() => {
                                    const nextEndDate = normalizeTypedDateInput(endDateInput) ?? endDate;
                                    setEndDateInput(nextEndDate);
                                    if (nextEndDate !== endDate) {
                                        setEndDate(nextEndDate);
                                    }
                                }}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        e.currentTarget.blur();
                                    }
                                }}
                                placeholder="YYYY-MM-DD"
                                className="px-2 py-1.5 bg-slate-50 border border-slate-200 rounded-lg text-sm w-36"
                            />
                        </div>

                        <div className="flex flex-col gap-1">
                            <label className="text-xs font-medium text-slate-500">구분</label>
                            <select
                                value={companyType}
                                onChange={(e) => setCompanyType(e.target.value as CompanyTypeFilter)}
                                className="px-2 py-1.5 bg-slate-50 border border-slate-200 rounded-lg text-sm min-w-32"
                            >
                                <option value="construction">청연이엔지</option>
                                <option value="partner">지원팀(현재협력사)</option>
                            </select>
                        </div>

                        <div className="flex flex-col gap-1">
                            <label className="text-xs font-medium text-slate-500">급여방식</label>
                            <select
                                value={salaryModel}
                                onChange={(e) => setSalaryModel(e.target.value as SalaryModelFilter)}
                                className="px-2 py-1.5 bg-slate-50 border border-slate-200 rounded-lg text-sm min-w-32"
                                disabled={companyType === 'partner'}
                            >
                                {companyType === 'partner' ? (
                                    <option value="지원팀">지원팀</option>
                                ) : (
                                    <>
                                        <option value="전체">전체</option>
                                        <option value="일급제">일급제</option>
                                        <option value="월급제">월급제</option>
                                        <option value="용역팀">용역팀</option>
                                    </>
                                )}
                            </select>
                        </div>

                        <div className="flex flex-col gap-1">
                            <label className="text-xs font-medium text-slate-500">팀</label>
                            <select
                                value={selectedTeamId}
                                onChange={(e) => setSelectedTeamId(e.target.value)}
                                className="px-2 py-1.5 bg-slate-50 border border-slate-200 rounded-lg text-sm min-w-40"
                            >
                                <option value="">전체 팀</option>
                                {teamOptions.map((team) => (
                                    <option key={team.id} value={team.id}>
                                        {team.name}
                                    </option>
                                ))}
                            </select>
                        </div>

                        <div className="flex flex-col gap-1 relative">
                            <label className="text-xs font-medium text-slate-500">작업자 검색 및 선택</label>
                            <div className="relative">
                                <div
                                    onClick={() => setIsWorkerDropdownOpen(!isWorkerDropdownOpen)}
                                    className={`flex items-center gap-2 px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-lg text-sm w-72 h-[38px] cursor-pointer hover:border-blue-400 transition-all ${isWorkerDropdownOpen ? 'ring-2 ring-blue-500 border-blue-500' : ''}`}
                                >
                                    <FontAwesomeIcon icon={faSearch} className="text-slate-400 text-xs" />
                                    <input
                                        type="text"
                                        value={selectedWorkerId ? (allWorkers.find(w => w.id === selectedWorkerId)?.name || '') : workerSearchTerm}
                                        onChange={(e) => {
                                            if (selectedWorkerId) {
                                                setSelectedWorkerId('');
                                            }
                                            setWorkerSearchTerm(e.target.value);
                                            setIsWorkerDropdownOpen(true);
                                        }}
                                        onKeyDown={handleWorkerKeyDown}
                                        placeholder="이름 또는 주민번호 입력"
                                        className="bg-transparent border-none outline-none text-sm w-full"
                                        onFocus={() => setIsWorkerDropdownOpen(true)}
                                    />
                                    {(selectedWorkerId || workerSearchTerm) && (
                                        <button
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                setSelectedWorkerId('');
                                                setWorkerSearchTerm('');
                                            }}
                                            className="ml-auto text-slate-400 hover:text-slate-600 p-1"
                                        >
                                            <FontAwesomeIcon icon={faTimes} className="text-[10px]" />
                                        </button>
                                    )}
                                    <FontAwesomeIcon icon={faChevronDown} className={`text-slate-300 text-[10px] transition-transform duration-200 ${isWorkerDropdownOpen ? 'rotate-180' : ''}`} />
                                </div>

                                <AnimatePresence>
                                    {isWorkerDropdownOpen && (
                                        <>
                                            <div
                                                className="fixed inset-0 z-40"
                                                onClick={() => setIsWorkerDropdownOpen(false)}
                                            />
                                            <motion.div
                                                initial={{ opacity: 0, y: -10, scale: 0.95 }}
                                                animate={{ opacity: 1, y: 0, scale: 1 }}
                                                exit={{ opacity: 0, y: -10, scale: 0.95 }}
                                                transition={{ duration: 0.15, ease: 'easeOut' }}
                                                className="absolute top-full left-0 right-0 mt-2 bg-white border border-slate-200 rounded-xl shadow-2xl z-50 overflow-hidden min-w-[320px]"
                                            >
                                                <div className="max-h-[300px] overflow-y-auto p-2 space-y-1 custom-scrollbar">
                                                    {workerOptions.length > 0 ? (
                                                        <>
                                                            <div className="px-3 py-2 text-[11px] font-bold text-slate-400 flex items-center justify-between">
                                                                <span>검색 결과: {workerOptions.length}명</span>
                                                                {workerSearchTerm && !selectedWorkerId && (
                                                                    <span className="bg-blue-50 text-blue-600 px-2 py-0.5 rounded-full">검색 모드</span>
                                                                )}
                                                            </div>
                                                            {workerOptions.map((worker, index) => (
                                                                <button
                                                                    key={worker.id}
                                                                    onClick={() => {
                                                                        setSelectedWorkerId(worker.id || '');
                                                                        setIsWorkerDropdownOpen(false);
                                                                    }}
                                                                    onMouseEnter={() => setActiveIndex(index)}
                                                                    className={`w-full flex items-center justify-between px-3 py-2.5 rounded-lg text-sm transition-all group ${selectedWorkerId === worker.id || activeIndex === index
                                                                        ? (selectedWorkerId === worker.id ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-900')
                                                                        : 'hover:bg-slate-50 text-slate-700'
                                                                        }`}
                                                                >
                                                                    <div className="flex items-center gap-3">
                                                                        <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs ${selectedWorkerId === worker.id ? 'bg-blue-500' : activeIndex === index ? 'bg-blue-100 text-blue-600' : 'bg-slate-100 group-hover:bg-blue-50 group-hover:text-blue-600'}`}>
                                                                            <FontAwesomeIcon icon={faUser} />
                                                                        </div>
                                                                        <div className="text-left">
                                                                            <p className="font-bold">
                                                                                <HighlightText text={worker.name} highlight={workerSearchTerm} />
                                                                            </p>
                                                                            <p className={`text-[11px] ${selectedWorkerId === worker.id ? 'text-blue-100' : 'text-slate-400'}`}>
                                                                                {worker.teamName || '팀 미지정'} • <HighlightText text={formatResidentNumberForDisplay(worker.idNumber || '').slice(0, 8)} highlight={workerSearchTerm} />******
                                                                            </p>
                                                                        </div>
                                                                    </div>
                                                                    {selectedWorkerId === worker.id && (
                                                                        <div className="w-2 h-2 rounded-full bg-white shadow-sm" />
                                                                    )}
                                                                </button>
                                                            ))}
                                                        </>
                                                    ) : (
                                                        <div className="py-12 flex flex-col items-center justify-center text-slate-400 gap-3">
                                                            <div className="w-12 h-12 rounded-full bg-slate-50 flex items-center justify-center">
                                                                <FontAwesomeIcon icon={faSearch} className="text-lg opacity-20" />
                                                            </div>
                                                            <p className="text-xs">검색 결과가 없습니다.</p>
                                                        </div>
                                                    )}
                                                </div>
                                            </motion.div>
                                        </>
                                    )}
                                </AnimatePresence>
                            </div>
                        </div>

                        <button
                            type="button"
                            onClick={() => setSortOrder((prev) => (prev === 'asc' ? 'desc' : 'asc'))}
                            className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${sortOrder === 'asc' ? 'bg-indigo-500 text-white' : 'bg-amber-500 text-white'}`}
                        >
                            {sortOrder === 'asc' ? '이름 ㄱ→ㅎ' : '이름 ㅎ→ㄱ'}
                        </button>

                        <button
                            onClick={() => {
                                const nextRange = commitDateDrafts();
                                fetchData(nextRange);
                            }}
                            className="px-4 py-1.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-all shadow-md font-bold flex items-center gap-2 text-sm"
                        >
                            <FontAwesomeIcon icon={faSearch} />
                            조회
                        </button>
                    </div>
                </div>

                {/* Table Area */}
                <div className="flex-1 min-h-0 bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden flex flex-col">
                    <div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white">
                        <h3 className="font-bold text-slate-800 flex items-center gap-2">
                            <span className="w-1.5 h-5 bg-blue-600 rounded-sm"></span>
                            조회 결과
                            <span className="text-slate-400 font-normal text-sm">({historyData.length.toLocaleString()}건)</span>
                        </h3>
                    </div>

                    <div className="flex-1 min-h-0 overflow-auto overscroll-contain">
                        <table className="w-full text-sm text-left border-separate border-spacing-0">
                            <thead className="bg-slate-50 text-slate-500 font-semibold sticky top-0 z-40">
                                <tr className="text-xs uppercase tracking-wider">
                                    <th rowSpan={2} className={`px-4 py-2 text-center w-12 border-b border-r border-slate-200 ${isFixed ? 'sticky left-0 z-50 bg-slate-50 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]' : ''}`}>No</th>
                                    <th rowSpan={2} className={`px-4 py-2 border-b border-r border-slate-200 ${isFixed ? 'sticky left-[48px] z-50 bg-slate-50 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]' : ''}`} style={{ width: isFixed ? '100px' : 'auto', minWidth: isFixed ? '100px' : 'auto' }}>이름</th>
                                    <th rowSpan={2} className={`px-4 py-2 border-b border-r border-slate-200 ${isFixed ? 'sticky left-[148px] z-50 bg-slate-50 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]' : ''}`} style={{ width: isFixed ? '140px' : 'auto', minWidth: isFixed ? '140px' : 'auto' }}>팀명</th>
                                    <th rowSpan={2} className="px-4 py-2 border-b border-r border-slate-200">주민번호</th>
                                    <th rowSpan={2} className="px-4 py-2 border-b border-r border-slate-200">급여방식</th>
                                    <th colSpan={3} className="px-4 py-1 text-center border-b border-r border-slate-200 bg-slate-100/50">공수 (Man-Days)</th>
                                    <th rowSpan={2} className="px-4 py-2 text-right border-b border-r border-slate-200">단가</th>
                                    <th colSpan={3} className="px-4 py-1 text-center border-b border-slate-200 bg-blue-50/50 text-blue-700">본봉 (Total Amount)</th>
                                </tr>
                                <tr>
                                    <th className="px-3 py-1 text-right border-b border-r border-slate-200 text-[10px] bg-slate-50">노무</th>
                                    <th className="px-3 py-1 text-right border-b border-r border-slate-200 text-[10px] bg-slate-50">계산서</th>
                                    <th className="px-3 py-1 text-right border-b border-r border-slate-200 text-[11px] bg-slate-100 font-bold">합계</th>
                                    <th className="px-3 py-1 text-right border-b border-r border-slate-200 text-[10px] bg-blue-50/30">노무</th>
                                    <th className="px-3 py-1 text-right border-b border-r border-slate-200 text-[10px] bg-blue-50/30">계산서</th>
                                    <th className="px-3 py-1 text-right border-b border-slate-200 text-[11px] bg-blue-600 text-white font-bold">합계</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {loading ? (
                                    <tr>
                                        <td colSpan={8} className="px-4 py-12 text-center text-slate-500">
                                            <div className="flex flex-col items-center gap-2">
                                                <div className="w-6 h-6 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                                                <span>데이터 분석 중...</span>
                                            </div>
                                        </td>
                                    </tr>
                                ) : historyData.length === 0 ? (
                                    <tr>
                                        <td colSpan={8} className="px-4 py-12 text-center text-slate-500 bg-slate-50/50">
                                            <FontAwesomeIcon icon={faSearch} className="text-2xl text-slate-300 mb-2" />
                                            <p className="font-medium">조회된 데이터가 없습니다.</p>
                                            <p className="text-xs text-slate-400">검색 조건을 변경하여 다시 조회해보세요.</p>
                                        </td>
                                    </tr>
                                ) : (
                                    historyData.map((item, index) => (
                                        <tr key={item.workerId} className="hover:bg-blue-50/50 transition-colors">
                                            <td className={`px-4 py-3 text-center text-slate-400 text-xs border-b border-slate-100 ${isFixed ? 'sticky left-0 z-10 bg-white shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]' : ''}`}>{index + 1}</td>
                                            <td className={`px-4 py-3 font-bold text-slate-800 border-b border-slate-100 ${isFixed ? 'sticky left-[48px] z-10 bg-white shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]' : ''}`}>{item.name}</td>
                                            <td className={`px-4 py-3 text-slate-600 border-b border-slate-100 ${isFixed ? 'sticky left-[148px] z-10 bg-white shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]' : ''}`}>{item.teamName || '-'}</td>
                                            <td className="px-4 py-3 text-slate-500 font-mono text-xs border-b border-slate-100">{item.idNumber}</td>
                                            <td className="px-4 py-3 border-b border-slate-100">
                                                <span className={`px-2 py-0.5 rounded text-xs font-medium ${item.salaryModel === '일급제' ? 'bg-blue-50 text-blue-600' :
                                                    item.salaryModel === '월급제' ? 'bg-indigo-50 text-indigo-600' :
                                                        item.salaryModel === '지원팀' ? 'bg-green-50 text-green-600' : 'bg-slate-100 text-slate-600'
                                                    }`}>{item.salaryModel}</span>
                                            </td>
                                            <td className="px-3 py-3 text-right font-mono text-slate-500 bg-slate-50/30 border-b border-r border-slate-100">{item.laborManDay > 0 ? formatManDay(item.laborManDay) : '-'}</td>
                                            <td className="px-3 py-3 text-right font-mono text-slate-500 bg-slate-50/30 border-b border-r border-slate-100">{item.invoiceManDay > 0 ? formatManDay(item.invoiceManDay) : '-'}</td>
                                            <td className="px-3 py-3 text-right font-mono text-slate-800 font-bold bg-slate-100/30 border-b border-r border-slate-100 tracking-tighter">{formatManDay(item.totalManDay)}</td>
                                            <td className="px-4 py-3 text-right font-mono text-slate-500 text-xs border-b border-r border-slate-100">{item.unitPrice.toLocaleString()}</td>
                                            <td className="px-3 py-3 text-right font-mono text-slate-600 border-b border-r border-slate-100">{item.laborAmount > 0 ? item.laborAmount.toLocaleString() : '-'}</td>
                                            <td className="px-3 py-3 text-right font-mono text-slate-600 border-b border-r border-slate-100">{item.invoiceAmount > 0 ? item.invoiceAmount.toLocaleString() : '-'}</td>
                                            <td className="px-4 py-3 text-right border-b border-slate-100 bg-blue-50/10">
                                                <span className="font-bold text-blue-700 font-mono tracking-tighter">{item.totalAmount.toLocaleString()}</span>
                                                <span className="text-[10px] text-slate-400 ml-0.5">원</span>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                            {!loading && historyData.length > 0 && (
                                <tfoot className="bg-slate-50 font-bold border-t border-slate-200 sticky bottom-0 z-40">
                                    <tr>
                                        <td colSpan={5} className="px-4 py-3 text-center text-slate-600 border-r border-slate-200">전체 합계</td>
                                        <td className="px-3 py-3 text-right text-slate-500 font-mono text-xs border-r border-slate-200">
                                            {formatManDay(historyData.reduce((sum, item) => sum + item.laborManDay, 0))}
                                        </td>
                                        <td className="px-3 py-3 text-right text-slate-500 font-mono text-xs border-r border-slate-200">
                                            {formatManDay(historyData.reduce((sum, item) => sum + item.invoiceManDay, 0))}
                                        </td>
                                        <td className="px-3 py-3 text-right text-slate-900 font-mono border-r border-slate-200">
                                            {formatManDay(historyData.reduce((sum, item) => sum + item.totalManDay, 0))}
                                        </td>
                                        <td className="px-4 py-3 border-r border-slate-200"></td>
                                        <td className="px-3 py-3 text-right text-slate-600 font-mono text-xs border-r border-slate-200">
                                            {historyData.reduce((sum, item) => sum + item.laborAmount, 0).toLocaleString()}
                                        </td>
                                        <td className="px-3 py-3 text-right text-slate-600 font-mono text-xs border-r border-slate-200">
                                            {historyData.reduce((sum, item) => sum + item.invoiceAmount, 0).toLocaleString()}
                                        </td>
                                        <td className="px-4 py-3 text-right text-blue-800 font-mono font-black text-base">
                                            {historyData.reduce((sum, item) => sum + item.totalAmount, 0).toLocaleString()} <span className="text-[10px] font-normal">원</span>
                                        </td>
                                    </tr>
                                </tfoot>
                            )}
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
};

