                            const isOrangeTheme = item.type === 'team' && isOtherCompany;
                            const volumeRatio = maxItemManDay > 0 ? (item.manDay || 0) / maxItemManDay : 0;

                            const siteCompany = item.type === 'site'
                                ? companies.find(c => c.id === item.companyId)
                                : undefined;

