                                                                // Logic for Level 2 (Team in Site)
                                                                const isResponsibleTeam = item.responsibleTeamId === detail.targetId;
                                                                const isInternalSupport = viewMode === 'site' && detail.companyId === item.companyId && !isResponsibleTeam;
