const SmartWorkerRegistrationPage: React.FC = () => {
    const [registrationMode, setRegistrationMode] = useState<'worker' | 'team'>('worker');
    const [pasteData, setPasteData] = useState('');
    const [parsedData, setParsedData] = useState<any[]>([]);
    const [headers, setHeaders] = useState<string[]>([]);
    const [mappedFields, setMappedFields] = useState<{ [index: number]: string }>({});
    const [loading, setLoading] = useState(false);

    const handlePaste = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        const text = e.target.value;
        setPasteData(text);
        parseData(text);
    };

    const parseData = (text: string) => {
        const lines = text.trim().split('\n');
        if (lines.length === 0) return;

        // Detect delimiter based on the first line
        const firstLine = lines[0];
        let delimiter = '\t';
        if (!firstLine.includes('\t') && firstLine.match(/\s{2,}/)) {
            delimiter = '   '; // Use a regex or special marker for multiple spaces
        }

        const rows = lines.map(row => {
            if (delimiter === '   ') {
                return row.split(/\s{2,}/);
            }
            return row.split(delimiter);
        });
        if (rows.length === 0) return;

        // Assume first row is header
        const headerRow = rows[0];
        setHeaders(headerRow);

        // Auto-map headers
        const newMapping: { [index: number]: string } = {};
        const currentMapping = registrationMode === 'worker' ? FIELD_MAPPING : TEAM_FIELD_MAPPING;

        headerRow.forEach((header, index) => {
            const cleanHeader = header.trim().normalize('NFC').replace(/\s+/g, '');
            let bestMatchField = '';
            let maxMatchLength = 0;
            let exactMatchFound = false;

            for (const [field, synonyms] of Object.entries(currentMapping)) {
                if (exactMatchFound) break;

                for (const synonym of synonyms) {
                    // Exact Match Priority
                    if (cleanHeader === synonym) {
                        bestMatchField = field;
                        exactMatchFound = true;
                        break;
                    }

                    // Longest Partial Match
                    if (cleanHeader.includes(synonym)) {
                        if (synonym.length > maxMatchLength) {
                            maxMatchLength = synonym.length;
                            bestMatchField = field;
                        }
                    }
                }
            }

            if (bestMatchField) {
                newMapping[index] = bestMatchField;
            }
        });
        setMappedFields(newMapping);

        // Parse data rows
        const dataRows = rows.slice(1).map((row, index) => {
            const rowData: any = { _valid: true, _errors: [] };

            // Map values to fields
            Object.entries(newMapping).forEach(([colIndex, field]) => {
                const val = row[parseInt(colIndex)]?.trim() || '';
                rowData[field] = val;
            });

            if (registrationMode === 'worker') {
                // Smart Category Parsing (Handle mixed data)
                if (rowData.category) {
                    const cat = rowData.category.trim();

                    // Check for Salary Model keywords
                    if (['일급', '일급제', '주급', '주급제', '월급', '월급제', '지원', '지원팀', '용역', '용역팀'].some(k => cat.includes(k))) {
                        if (!rowData.salaryModel) {
                            if (cat.includes('일급')) rowData.salaryModel = '일급제';
                            else if (cat.includes('주급')) rowData.salaryModel = '주급제';
                            else if (cat.includes('월급')) rowData.salaryModel = '월급제';
                            else if (cat.includes('지원')) rowData.salaryModel = '지원팀';
                            else if (cat.includes('용역')) rowData.salaryModel = '용역팀';
                        }
                    }

                    // Check for Team Type keywords
                    if (['직영', '직영팀', '시공', '시공팀'].some(k => cat.includes(k))) {
                        if (!rowData.teamType) {
                            if (cat.includes('직영')) rowData.teamType = '직영팀';
                            else if (cat.includes('시공')) rowData.teamType = '시공팀';
                        }
                    }
                }

                // Validation for Worker
                if (!rowData.name) {
                    rowData._valid = false;
                    rowData._errors.push('이름 누락');
                }
                if (!rowData.idNumber) {
                    rowData._valid = false;
                    rowData._errors.push('주민번호 누락');
                }
            } else {
                // Validation for Team
                if (!rowData.name) {
                    rowData._valid = false;
                    rowData._errors.push('팀명 누락');
                }
            }

            return rowData;
        });

        setParsedData(dataRows);
    };

    // Re-parse when mode changes
    React.useEffect(() => {
        if (pasteData) {
            parseData(pasteData);
        }
    }, [registrationMode]);

    const handleSave = async () => {
        const validRows = parsedData.filter(r => r._valid);
        if (validRows.length === 0) {
            Swal.fire('Error', '저장할 유효한 데이터가 없습니다.', 'error');
            return;
        }

        setLoading(true);
        let successCount = 0;
        let failCount = 0;

        try {
            for (const row of validRows) {
                try {
                    if (registrationMode === 'worker') {
                        await manpowerService.addWorker({
                            name: row.name,
                            idNumber: row.idNumber,
                            contact: row.contact || '',
                            address: row.address || '',
                            bankName: row.bankName || '',
                            accountNumber: row.accountNumber || '',
                            accountHolder: row.accountHolder || row.name,
                            role: row.role || '조공',
                            teamName: row.teamName || '',
                            companyName: row.companyName || '',
                            leaderName: row.leaderName || '',
                            teamType: row.teamType || (row.teamName ? '팀소속' : '미배정'),
                            status: '재직',
                            unitPrice: parseInt(row.unitPrice?.replace(/,/g, '')) || 0,
                            salaryModel: row.salaryModel || '일급제'
                        }, false);
                    } else {
                        // Team Registration
                        await teamService.addTeam({
                            name: row.name,
                            leaderName: row.leaderName || '',
                            leaderId: '', // Cannot resolve ID automatically in bulk
                            companyName: row.companyName || '',
                            type: row.type || (row.name.includes('지원') ? '지원팀' : '일반팀'),
                            memberCount: 0,
                            totalManDay: 0
                        });
                    }
                    successCount++;
                } catch (error) {
                    console.error("Failed to add item:", row.name, error);
                    failCount++;
                }
            }

            Swal.fire({
                title: '완료',
                text: `성공: ${successCount}건, 실패: ${failCount}건`,
                icon: failCount > 0 ? 'warning' : 'success'
            });

            if (successCount > 0) {
                setPasteData('');
                setParsedData([]);
                setHeaders([]);
            }

        } catch (error) {
            console.error("Batch save error:", error);
            Swal.fire('Error', '저장 중 오류가 발생했습니다.', 'error');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="flex flex-col h-full bg-slate-50">
            {/* Header - Full Width */}
            {/* Header & Toolbar - Single Row */}
            <div className="bg-white border-b border-slate-200 p-4 flex flex-col xl:flex-row items-start xl:items-center justify-between gap-4 flex-shrink-0">
                <div className="flex items-center gap-4">
                    <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2 whitespace-nowrap">
                        <FontAwesomeIcon icon={faPaste} className="text-blue-600" />
                        {registrationMode === 'worker' ? '작업자 대량 등록' : '팀 대량 등록'} (Smart Excel)
                    </h2>
                    <div className="flex bg-slate-100 p-1 rounded-lg">
                        <button
                            onClick={() => setRegistrationMode('worker')}
                            className={`px-3 py-1.5 text-sm font-bold rounded-md transition-all ${registrationMode === 'worker' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                        >
                            작업자 등록
                        </button>
                        <button
                            onClick={() => setRegistrationMode('team')}
                            className={`px-3 py-1.5 text-sm font-bold rounded-md transition-all ${registrationMode === 'team' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                        >
                            팀 등록
                        </button>
                    </div>
                </div>

                <div className="flex flex-wrap items-center gap-2 w-full xl:w-auto justify-start xl:justify-end">
                    <button
                        onClick={handleSave}
                        disabled={loading || parsedData.length === 0}
                        className={`flex items-center gap-2 px-4 py-2 text-white rounded-lg transition-colors shadow-sm whitespace-nowrap disabled:opacity-50 disabled:cursor-not-allowed ml-auto xl:ml-0 ${registrationMode === 'worker' ? 'bg-blue-600 hover:bg-blue-700 shadow-blue-200' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200'}`}
                    >
                        {loading ? <FontAwesomeIcon icon={faSpinner} spin /> : <FontAwesomeIcon icon={faSave} />}
                        <span className="hidden sm:inline">일괄 등록하기</span>
                    </button>
                </div>
            </div>

            {/* Content Area */}
            <div className="p-6 flex-1 overflow-auto">
                <div className={`mb-6 border rounded-lg p-4 ${registrationMode === 'worker' ? 'bg-blue-50 border-blue-200' : 'bg-indigo-50 border-indigo-200'}`}>
                    <h3 className={`font-bold mb-2 ${registrationMode === 'worker' ? 'text-blue-800' : 'text-indigo-800'}`}>💡 사용 방법 ({registrationMode === 'worker' ? '작업자' : '팀'} 등록)</h3>
                    <ul className={`list-disc list-inside text-sm space-y-1 ${registrationMode === 'worker' ? 'text-blue-700' : 'text-indigo-700'}`}>
                        <li>엑셀에서 <strong>헤더(항목 이름)를 포함하여</strong> 데이터를 복사한 후 아래 입력창에 붙여넣으세요.</li>
                        <li>시스템이 헤더 이름을 분석하여 자동으로 항목을 매핑합니다.</li>
                        {registrationMode === 'worker' ? (
                            <>
                                <li><strong>필수 항목:</strong> 이름, 주민번호</li>
                                <li><strong>지원 항목:</strong> 이름, 주민번호, 연락처, 주소, 은행명, 계좌번호, 예금주, 공종, 팀명, 회사명, 단가, 급여형태, 팀구분</li>
                            </>
                        ) : (
                            <>
                                <li><strong>필수 항목:</strong> 팀명</li>
                                <li><strong>지원 항목:</strong> 팀명, 팀장명(대표), 소속회사, 팀구분(지원팀/일반팀), 연락처</li>
                            </>
                        )}
                        <li><strong>통합 지원:</strong> '구분' 또는 '비고' 열에 "일급제", "지원팀" 등의 내용이 섞여 있어도 자동으로 인식하여 분류합니다.</li>
                    </ul>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[600px]">
                    {/* Input Area */}
                    <div className="lg:col-span-1 flex flex-col gap-2">
                        <label className="font-semibold text-slate-700 flex items-center gap-2">
                            <FontAwesomeIcon icon={faPaste} className={registrationMode === 'worker' ? 'text-blue-500' : 'text-indigo-500'} />
                            데이터 붙여넣기
                        </label>
                        <textarea
                            className={`w-full h-full p-4 border rounded-lg focus:ring-2 resize-none font-mono text-sm ${registrationMode === 'worker' ? 'border-slate-300 focus:ring-blue-500 focus:border-blue-500' : 'border-slate-300 focus:ring-indigo-500 focus:border-indigo-500'}`}
                            placeholder={registrationMode === 'worker'
                                ? `엑셀에서 헤더를 포함하여 복사 후 붙여넣으세요.\n\n[예시]\n이름\t주민번호\t주소\t연락처\n홍길동\t800101-1234567\t서울시 강남구\t010-1234-5678`
                                : `엑셀에서 헤더를 포함하여 복사 후 붙여넣으세요.\n\n[예시]\n팀명\t팀장명\t소속회사\t팀구분\nA팀\t김철수\t현대건설\t시공팀`
                            }
                            value={pasteData}
                            onChange={handlePaste}
                        />
                    </div>

                    {/* Preview Area */}
                    <div className="lg:col-span-2 flex flex-col gap-2 overflow-hidden">
                        <label className="font-semibold text-slate-700 flex items-center gap-2">
                            <FontAwesomeIcon icon={faCheckCircle} className="text-green-500" />
                            미리보기 ({parsedData.length}건)
                        </label>

                        <div className="flex-1 overflow-auto border border-slate-200 rounded-lg bg-slate-50">
                            {parsedData.length > 0 ? (
                                <table className="w-full text-sm text-left">
                                    <thead className="text-xs text-slate-500 uppercase bg-slate-100 sticky top-0">
                                        <tr>
                                            <th className="px-4 py-3 border-b">상태</th>
                                            {headers.map((header, idx) => (
                                                <th key={idx} className="px-4 py-3 border-b">
                                                    <div className="flex flex-col gap-1">
                                                        <span className="font-bold text-slate-700">{header}</span>
                                                        {mappedFields[idx] ? (
                                                            <span className={`text-xs px-1.5 py-0.5 rounded border ${registrationMode === 'worker' ? 'text-blue-600 bg-blue-50 border-blue-100' : 'text-indigo-600 bg-indigo-50 border-indigo-100'}`}>
                                                                → {(registrationMode === 'worker' ? FIELD_LABELS : TEAM_FIELD_LABELS)[mappedFields[idx]]}
                                                            </span>
                                                        ) : (
                                                            <span className="text-slate-400 text-xs">무시됨</span>
                                                        )}
                                                    </div>
                                                </th>
                                            ))}
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-200 bg-white">
                                        {parsedData.map((row, rowIdx) => (
                                            <tr key={rowIdx} className={row._valid ? 'hover:bg-slate-50' : 'bg-red-50 hover:bg-red-100'}>
                                                <td className="px-4 py-2 whitespace-nowrap">
                                                    {row._valid ? (
                                                        <FontAwesomeIcon icon={faCheckCircle} className="text-green-500" />
                                                    ) : (
                                                        <div className="flex items-center gap-1 text-red-500" title={row._errors.join(', ')}>
                                                            <FontAwesomeIcon icon={faExclamationTriangle} />
                                                            <span className="text-xs font-bold">오류</span>
                                                        </div>
                                                    )}
                                                </td>
                                                {headers.map((_, colIdx) => {
                                                    const field = mappedFields[colIdx];
                                                    return (
                                                        <td key={colIdx} className="px-4 py-2 whitespace-nowrap text-slate-700">
                                                            {field ? row[field] : <span className="text-slate-300">-</span>}
                                                        </td>
                                                    );
                                                })}
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            ) : (
                                <div className="h-full flex flex-col items-center justify-center text-slate-400">
                                    <FontAwesomeIcon icon={faArrowRight} className="text-4xl mb-4 opacity-20" />
                                    <p>좌측 입력창에 엑셀 데이터를 붙여넣으세요.</p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default SmartWorkerRegistrationPage;

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { HotTable } from '@handsontable/react';
import { registerAllModules } from 'handsontable/registry';
import 'handsontable/dist/handsontable.full.min.css';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faSave, faPlus, faTrash, faPaste, faKeyboard, faInfoCircle, faCheckCircle, faExclamationTriangle, faSpinner } from '@fortawesome/free-solid-svg-icons';
import Swal from 'sweetalert2';
import { manpowerService } from '../../services/manpowerService';
import { teamService } from '../../services/teamService';
import { companyService } from '../../services/companyService';
import { geminiService } from '../../services/geminiService';

// Register Handsontable modules
registerAllModules();

interface WorkerRow {
    name: string;
    idNumber: string;
    contact: string;
    address: string;
    role: string;
    teamName: string;
    companyName: string;
    unitPrice: number;
    salaryModel: string;
    bankName: string;
    accountNumber: string;
    accountHolder: string;
}

const WorkerBulkRegistrationPage: React.FC = () => {
    const hotRef = useRef<any>(null);
    const [loading, setLoading] = useState(false);
    const [teams, setTeams] = useState<any[]>([]);

    // Initial Empty Data
    const generateEmptyRows = (count: number): WorkerRow[] => {
        return Array(count).fill(null).map(() => ({
            name: '',
            idNumber: '',
            contact: '',
            address: '',
            role: '조공',
            teamName: '',
            companyName: '',
            unitPrice: 0,
            salaryModel: '일급제',
            bankName: '',
            accountNumber: '',
            accountHolder: ''
        }));
    };

    const [data, setData] = useState<WorkerRow[]>(generateEmptyRows(20));

    useEffect(() => {
        loadTeams();

        // Custom Keyboard Shortcuts
        const handleKeyDown = (e: KeyboardEvent) => {
            if ((e.ctrlKey || e.metaKey) && e.key === 's') {
                e.preventDefault();
                handleSave();
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, []);

    const loadTeams = async () => {
        const teamsData = await teamService.getTeams();
        setTeams(teamsData);
    };

    const handleSave = async () => {
        // Filter valid rows (must have Name and ID Number)
        const validRows = data.filter(row => row.name && row.name.trim() !== '' && row.idNumber && row.idNumber.trim() !== '');

        if (validRows.length === 0) {
            Swal.fire('알림', '저장할 데이터가 없습니다. (이름, 주민번호 필수)', 'warning');
            return;
        }

        setLoading(true);
        let successCount = 0;
        let failCount = 0;

        try {
            for (const row of validRows) {
                try {
                    // Determine team type based on input or logic
                    const teamType = row.teamName ? '팀소속' : '미배정';

                    await manpowerService.addWorker({
                        name: row.name,
                        idNumber: row.idNumber,
                        contact: row.contact || '',
                        address: row.address || '',
                        role: row.role || '조공',
                        teamName: row.teamName || '',
                        companyName: row.companyName || '',
                        leaderName: '', // Optional or inferred
                        teamType: teamType,
                        status: '재직',
                        unitPrice: Number(row.unitPrice) || 0,
                        salaryModel: row.salaryModel || '일급제',
                        bankName: row.bankName || '',
                        accountNumber: row.accountNumber || '',
                        accountHolder: row.accountHolder || row.name
                    }, false); // false = batch mode (no individual toast)
                    successCount++;
                } catch (err) {
                    console.error('Row failed', row, err);
                    failCount++;
                }
            }
            Swal.fire({
                title: '저장 완료',
                text: `성공: ${successCount}건, 실패: ${failCount}건`,
                icon: failCount > 0 ? 'warning' : 'success'
            });

            // Clear or Keep? Usually keep for review, but maybe clear succeed ones?
            // For now, reload empty
            if (successCount > 0 && failCount === 0) {
                setData(generateEmptyRows(20));
            }

        } catch (error) {
            console.error(error);
            Swal.fire('오류', '저장 중 문제가 발생했습니다.', 'error');
        } finally {
            setLoading(false);
        }
    };

    // Kakao/Text Parsing Logic
    const handlePasteSpecial = async () => {
        const apiKey = geminiService.getKey();
        const { value: formValues } = await Swal.fire({
            title: '카톡/텍스트 붙여넣기',
            html: `
                <textarea id="swal-input-text" class="swal2-textarea" placeholder="카톡 내용, 엑셀 텍스트, 또는 문장형 데이터를 붙여넣으세요..." style="height: 200px; width: 90%;"></textarea>
                <div style="margin-top: 15px; text-align: left; padding: 0 20px;">
                    <label style="display: flex; align-items: center; gap: 8px; cursor: pointer;">
                        <input type="checkbox" id="swal-input-use-ai" ${apiKey ? 'checked' : ''}>
                        <span style="font-weight: bold; color: #4f46e5;">Google Gemini AI 분석 사용 (추천)</span>
                    </label>
                    <p style="font-size: 0.85em; color: #64748b; margin-top: 4px; margin-left: 24px;">
                        AI를 사용하면 문맥을 파악하여 훨씬 정확하게 데이터를 추출합니다.
                    </p>
                    ${!apiKey ? '<p style="color: red; font-size: 0.8em; margin-top: 5px; margin-left: 24px;">⚠ API Key가 설정되지 않았습니다. /settings/ai 에서 키를 입력해주세요.</p>' : ''}
                </div>
            `,
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: '분석 및 적용',
            cancelButtonText: '취소',
            width: 600,
            preConfirm: () => {
                return {
                    text: (document.getElementById('swal-input-text') as HTMLTextAreaElement).value,
                    useAI: (document.getElementById('swal-input-use-ai') as HTMLInputElement).checked
                }
            }
        });

        if (formValues && formValues.text) {
            if (formValues.useAI) {
                if (!apiKey) {
                    Swal.fire('API Key 없음', 'Gemini API Key가 설정되지 않았습니다. 단순 패턴 분석으로 진행합니다.', 'warning');
                    parseAndPopulateRegex(formValues.text);
                    return;
                }

                setLoading(true);
                try {
                    const parsedData = await geminiService.analyzeWorkerRegistrationText(formValues.text);
                    applyParsedRows(parsedData);
                    Swal.fire({
                        title: 'AI 분석 완료',
                        text: `${parsedData.length}명의 데이터를 성공적으로 추출했습니다.`,
                        icon: 'success',
                        timer: 1500
                    });
                } catch (error) {
                    console.error("AI Analysis Failed", error);
                    let errMsg = '알 수 없는 오류';
                    if (error instanceof Error) errMsg = error.message;

                    Swal.fire({
                        title: 'AI 분석 실패',
                        text: `오류: ${errMsg}\n단순 패턴 분석을 대신 시도합니다.`,
                        icon: 'error'
                    }).then(() => {
                        parseAndPopulateRegex(formValues.text);
                    });
                } finally {
                    setLoading(false);
                }
            } else {
                parseAndPopulateRegex(formValues.text);
            }
        }
    };

    const applyParsedRows = (parsedItems: any[]) => {
        const newRows: WorkerRow[] = [...data];
        let insertIndex = 0;

        // Find first empty row
        while (insertIndex < newRows.length && newRows[insertIndex].name) {
            insertIndex++;
        }

        // If not enough space, expand
        if (insertIndex + parsedItems.length > newRows.length) {
            const needed = (insertIndex + parsedItems.length) - newRows.length;
            newRows.push(...generateEmptyRows(needed + 5));
        }

        parsedItems.forEach(item => {
            newRows[insertIndex] = {
                ...newRows[insertIndex],
                name: item.name || '',
                idNumber: item.idNumber || '',
                contact: item.contact || '',
                address: item.address || '',
                role: item.role || '조공',
                teamName: item.teamName || '',
                companyName: item.companyName || '',
                unitPrice: Number(item.unitPrice) || 0,
                salaryModel: item.salaryModel || '일급제',
                bankName: item.bankName || '',
                accountNumber: item.accountNumber || '',
                accountHolder: item.accountHolder || item.name || ''
            };
            insertIndex++;
        });

        setData(newRows);
    };

    const parseAndPopulateRegex = (text: string) => {
        const lines = text.split('\n').filter(l => l.trim());
        const parsedItems: any[] = [];

        lines.forEach(line => {
            const spaceParts = line.split(/[\s,]+/);

            let name = '';
            let idNum = '';
            let contact = '';
            let role = '';

            spaceParts.forEach(part => {
                if (!name && /^[가-힣]{2,5}$/.test(part)) name = part;
                else if (!idNum && /(\d{6}[-]?\d{7})/.test(part)) idNum = part;
                else if (!contact && /010[-]?\d{3,4}[-]?\d{4}/.test(part)) contact = part;
                else if (!role && ['기공', '조공', '팀장', '준기공'].includes(part)) role = part;
            });

            if (name || idNum) {
                parsedItems.push({ name, idNumber: idNum, contact, role });
            }
        });

        if (parsedItems.length > 0) {
            applyParsedRows(parsedItems);
            Swal.fire('완료', `${parsedItems.length}건을 단순 분석했습니다.`, 'success');
        } else {
            Swal.fire('결과 없음', '인식된 데이터가 없습니다. 형식을 확인해주세요.', 'info');
        }
    };

    const addMoreRows = () => {
        setData(prev => [...prev, ...generateEmptyRows(10)]);
    };

    const clearData = () => {
        Swal.fire({
            title: '초기화 하시겠습니까?',
            text: "입력된 모든 데이터가 삭제됩니다.",
            icon: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#d33',
            confirmButtonText: '예, 초기화합니다'
        }).then((result) => {
            if (result.isConfirmed) {
                setData(generateEmptyRows(20));
            }
        });
    }

    return (
        <div className="flex flex-col h-full bg-slate-50 p-4">
            <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm mb-4 flex flex-wrap items-center justify-between gap-4">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-indigo-50 rounded-lg text-indigo-600">
                        <FontAwesomeIcon icon={faKeyboard} size="lg" />
                    </div>
                    <div>
                        <h1 className="text-xl font-bold text-slate-800">작업자 엑셀/그리드 대량 등록</h1>
                        <p className="text-sm text-slate-500">엑셀처럼 입력하고 단축키(Ctrl+S)로 저장하세요.</p>
                    </div>
                </div>
                <div className="flex items-center gap-2">
                    <button onClick={handlePasteSpecial} className="px-4 py-2 bg-yellow-400 hover:bg-yellow-500 text-slate-900 font-bold rounded-lg transition-colors flex items-center gap-2">
                        <FontAwesomeIcon icon={faPaste} />
                        카톡/텍스트 분석
                    </button>
                    <button onClick={addMoreRows} className="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-lg transition-colors flex items-center gap-2">
                        <FontAwesomeIcon icon={faPlus} />
                        행 추가
                    </button>
                    <button onClick={clearData} className="px-4 py-2 bg-red-50 hover:bg-red-100 text-red-600 font-bold rounded-lg transition-colors flex items-center gap-2">
                        <FontAwesomeIcon icon={faTrash} />
                        초기화
                    </button>
                    <button onClick={handleSave} disabled={loading} className="px-6 py-2 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-lg shadow-md transition-colors flex items-center gap-2">
                        {loading ? <FontAwesomeIcon icon={faSpinner} spin /> : <FontAwesomeIcon icon={faSave} />}
                        일괄 저장
                    </button>
                </div>
            </div>

            <div className="flex-1 overflow-hidden bg-white rounded-xl shadow-sm border border-slate-200 relative">
                <HotTable
                    ref={hotRef}
                    data={data}
                    colHeaders={['이름(필수)', '주민번호(필수)', '연락처', '주소', '공종', '팀명', '소속회사', '단가', '급여형태', '은행명', '계좌번호', '예금주']}
                    columns={[
                        { data: 'name', type: 'text' },
                        { data: 'idNumber', type: 'text' },
                        { data: 'contact', type: 'text' },
                        { data: 'address', type: 'text' },
                        { data: 'role', type: 'dropdown', source: ['기공', '조공', '팀장', '준기공'] },
                        { data: 'teamName', type: 'text' }, // Could be dropdown from teams
                        { data: 'companyName', type: 'text' },
                        { data: 'unitPrice', type: 'numeric', numericFormat: { pattern: '0,0' } },
                        { data: 'salaryModel', type: 'dropdown', source: ['일급제', '주급제', '월급제'] },
                        { data: 'bankName', type: 'text' },
                        { data: 'accountNumber', type: 'text' },
                        { data: 'accountHolder', type: 'text' },
                    ]}
                    rowHeaders={true}
                    width="100%"
                    height="100%"
                    stretchH="all"
                    contextMenu={true}
                    autoWrapRow={true}
                    autoWrapCol={true}
                    licenseKey="non-commercial-and-evaluation"
                    minSpareRows={1}
                />
            </div>

            {/* Keyboard Shortcuts Hint */}
            <div className="mt-2 text-xs text-slate-400 text-right">
                <span className="mr-3">💡 <strong>Ctrl+C / Ctrl+V</strong>: 엑셀 복사/붙여넣기</span>
                <span className="mr-3">💡 <strong>Ctrl+S</strong>: 저장</span>
            </div>
        </div>
    );
};

export default WorkerBulkRegistrationPage;

import React, { useState } from 'react';
import { Worker } from '../../services/manpowerService';
import { Team } from '../../services/teamService';
import { Company } from '../../services/companyService';
import { storage } from '../../config/firebase';
import { ref, uploadBytes } from 'firebase/storage';
import { Position } from '../../services/positionService';
import WorkerForm from '../../components/manpower/WorkerForm';
import { showErrorAlert } from '../../utils/swal';

interface WorkerModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSave: (worker: Omit<Worker, 'id'> | Partial<Worker>) => Promise<void>;
    initialData?: Partial<Worker> | null;
    teams: Team[];
    companies: Company[];
    positions: Position[];
}

const WorkerModal: React.FC<WorkerModalProps> = ({ isOpen, onClose, onSave, initialData, teams, companies, positions }) => {
    if (!isOpen) return null;

    const handleSaveWrapper = async (data: Omit<Worker, 'id'> | Partial<Worker>, file?: File | null) => {
        try {
            let finalData = { ...data };

            // Upload file if selected
            if (file) {
                const storagePath = `id_cards/${Date.now()}_${file.name}`;
                const storageRef = ref(storage, storagePath);
                await uploadBytes(storageRef, file);
                finalData.fileNameSaved = storagePath;
            }

            await onSave(finalData);
            onClose();
        } catch (error: any) {
            console.error("Failed to save worker:", error);
            await showErrorAlert('저장 실패', error.message || "저장 중 오류가 발생했습니다.");
        }
    };

    // initialData가 있으면 해당 id를 가진 Worker 객체로 간주, 없으면 null (New Mode)
    // WorkerForm will handle the defaulting logic if initialData is null.
    // However, initialData from props is Partial<Worker> | null, but WorkerForm expects Worker | null.
    // casting is safe here as WorkerForm handles Partial logic internally anyway or we can adjust type.
    const formInitialData = initialData ? (initialData as Worker) : null;
    const isEditMode = !!(initialData && initialData.id);

    return (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="w-full max-w-5xl max-h-[90vh] overflow-hidden rounded-xl shadow-2xl">
                <WorkerForm
                    initialData={formInitialData}
                    teams={teams}
                    companies={companies}
                    positions={positions}
                    onSave={handleSaveWrapper}
                    onCancel={onClose}
                    isEditMode={isEditMode}
                />
            </div>
        </div>
    );
};

