                                                                : 'border-slate-300'
                                                            }`}
                                                        value={mapping[field.key] || ''}
                                                        onChange={(e) => handleMappingChange(type, field.key, e.target.value)}
                                                    >
                                                        <option value="">(선택 안함)</option>
                                                        {headers.map(h => (
                                                            <option key={h} value={h}>{h}</option>
                                                        ))}
                                                    </select>
