                                                        <p className="text-[10px] text-slate-500 mt-1 truncate">
                                                            예: {sheetData[type][0][mapping[field.key]] ?? '-'}
                                                        </p>
                                                    )}
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>
        );
    }

    // Stage: PREVIEW
    if (stage === 'PREVIEW') {
        return (
            <div className="max-w-7xl mx-auto p-6">
