import materialService from '../../services/materialService';
import { siteService, Site } from '../../services/siteService';
import { Material, InboundTransaction } from '../../types/materials';
import { useAuth } from '../../contexts/AuthContext';

// 임시저장 데이터 타입
type InboundTempData = {
    transactionDate: string;
    siteId: string;
    siteName: string;
    vehicleNumber: string;
    supplier: string;
    quantities: Record<string, number>;
    savedAt: number;
};

const MaterialInboundPage: React.FC = () => {
    const navigate = useNavigate();
    const { currentUser } = useAuth();
    const [loading, setLoading] = useState(false);
    const [transactionDate, setTransactionDate] = useState(new Date().toISOString().slice(0, 10));
    const [siteId, setSiteId] = useState('');
    const [siteName, setSiteName] = useState('');
    const [vehicleNumber, setVehicleNumber] = useState('');
    const [supplier, setSupplier] = useState('');

    const [sites, setSites] = useState<Site[]>([]);
    const [materials, setMaterials] = useState<Material[]>([]);
    const [quantities, setQuantities] = useState<Record<string, number>>({});
    const [hasTempData, setHasTempData] = useState(false);

    // 임시저장 데이터 로드
    const loadTempData = () => {
        try {
            const tempDataStr = localStorage.getItem('inbound_temp');
            if (!tempDataStr) return;

            const tempData: InboundTempData = JSON.parse(tempDataStr);

            // 24시간 이상 된 데이터는 정리
            const now = Date.now();
            if (now - tempData.savedAt > 24 * 60 * 60 * 1000) {
                localStorage.removeItem('inbound_temp');
                return;
            }

            // 데이터 복원
            setTransactionDate(tempData.transactionDate);
            setSiteId(tempData.siteId);
            setSiteName(tempData.siteName);
            setVehicleNumber(tempData.vehicleNumber);
            setSupplier(tempData.supplier);
            setQuantities(tempData.quantities || {});
            setHasTempData(true);

            // Ref도 즉시 동기화 (Strict Mode 대응)
            stateRef.current = {
                transactionDate: tempData.transactionDate,
                siteId: tempData.siteId,
                siteName: tempData.siteName,
                vehicleNumber: tempData.vehicleNumber,
                supplier: tempData.supplier,
                quantities: tempData.quantities || {}
            };

            console.log('[Inbound] 임시저장 데이터를 복원했습니다:', tempData);
        } catch (error) {
            console.error('[Inbound] 임시저장 데이터 로드 실패:', error);
            localStorage.removeItem('inbound_temp');
        }
    };

    // 임시저장 데이터 저장
    const saveTempData = () => {
        try {
            const tempData: InboundTempData = {
                transactionDate,
                siteId,
                siteName,
                vehicleNumber,
                supplier,
                quantities,
                savedAt: Date.now()
            };
            localStorage.setItem('inbound_temp', JSON.stringify(tempData));
            setHasTempData(true);
        } catch (error) {
            console.error('[Inbound] 임시저장 데이터 저장 실패:', error);
        }
    };

    // 임시저장 데이터 삭제
    const clearTempData = () => {
        localStorage.removeItem('inbound_temp');
        setHasTempData(false);
    };

    // 최신 상태를 추적하기 위한 Ref
    const stateRef = React.useRef({
        transactionDate,
        siteId,
        siteName,
        vehicleNumber,
        supplier,
        quantities
    });

    // 렌더링마다 Ref 업데이트
    useEffect(() => {
        stateRef.current = {
            transactionDate,
            siteId,
            siteName,
            vehicleNumber,
            supplier,
            quantities
        };
    }, [transactionDate, siteId, siteName, vehicleNumber, supplier, quantities]);

    // 실제 저장 로직 (Ref 기준)
    const performSave = () => {
        try {
            const current = stateRef.current;
            const tempData: InboundTempData = {
                transactionDate: current.transactionDate,
                siteId: current.siteId,
                siteName: current.siteName,
                vehicleNumber: current.vehicleNumber,
                supplier: current.supplier,
                quantities: current.quantities,
                savedAt: Date.now()
            };
            localStorage.setItem('inbound_temp', JSON.stringify(tempData));
            setHasTempData(true);
            console.log('[Inbound] Auto-saved data:', tempData);
        } catch (error) {
            console.error('[Inbound] Temp save failed:', error);
        }
    };

    useEffect(() => {
        loadData();
        loadTempData();

        // 브라우저 종료/새로고침 시 저장
        const handleBeforeUnload = () => {
            performSave();
        };
        window.addEventListener('beforeunload', handleBeforeUnload);

        return () => {
            window.removeEventListener('beforeunload', handleBeforeUnload);
            // 컴포넌트 언마운트(페이지 이동) 시 저장
            performSave();
        };
    }, []);

    // 자동 저장 (Debounce)
    useEffect(() => {
        const timer = setTimeout(() => {
            performSave();
        }, 1000);

        return () => clearTimeout(timer);
    }, [transactionDate, siteId, siteName, vehicleNumber, supplier, quantities]);

    const loadData = async () => {
        setLoading(true);
        try {
            const [sitesData, materialsData] = await Promise.all([
                siteService.getSites(),
                materialService.getUniqueMaterialsForSelection()
            ]);
            setSites(sitesData.filter((s: any) => s.status === 'active'));
            setMaterials(materialsData);

            setQuantities((prev) => {
                const validIds = new Set(materialsData.map((m) => m.id));
                const nextEntries = Object.entries(prev).filter(([id]) => validIds.has(id));
                return Object.fromEntries(nextEntries);
            });
        } catch (error) {
            console.error('Failed to load data:', error);
            alert('데이터를 불러오지 못했습니다.');
        } finally {
            setLoading(false);
        }
    };

    const handleSiteChange = (selectedSiteId: string) => {
        setSiteId(selectedSiteId);
        const site = sites.find(s => s.id === selectedSiteId);
        setSiteName(site?.name || '');
    };

    const handleQuantityChange = (materialId: string, value: string) => {
        const numValue = parseInt(value) || 0;
        setQuantities(prev => ({
            ...prev,
            [materialId]: numValue
        }));
    };

    const handleSave = async () => {
        if (!siteId) {
            alert('현장을 선택하세요.');
            return;
        }

        const transactions: Array<Omit<InboundTransaction, 'id' | 'createdAt' | 'updatedAt'>> = [];

        const resolvedSiteName = siteName || sites.find(s => s.id === siteId)?.name || '';
        Object.entries(quantities).forEach(([materialId, quantity]) => {
            if (quantity > 0) {
                const material = materials.find(m => m.id === materialId);
                if (material) {
                    transactions.push({
                        transactionDate,
                        siteId,
                        siteName: String(resolvedSiteName || '').trim(),
                        vehicleNumber: vehicleNumber || '',
                        materialId: material.id,
                        category: String(material.category || '').trim(),
                        itemName: String(material.itemName || '').trim(),
                        spec: String(material.spec || '').trim(),
                        quantity,
                        unit: String(material.unit || '').trim(),
                        supplier: supplier || '',
                        notes: '',
                        registeredBy: currentUser?.uid || '',
                        registeredByName: currentUser?.displayName || currentUser?.email || '관리자'
                    });
                }
            }
        });

        if (transactions.length === 0) {
            alert('입고할 자재를 입력하세요.');
            return;
        }

        setLoading(true);
        try {
            await materialService.addInboundTransactionsBatch(transactions);
            alert(`${transactions.length}건의 입고가 등록되었습니다.`);
            // 저장 성공 후 임시저장 데이터 삭제
            clearTempData();
            handleReset();
        } catch (error) {
            console.error('Failed to save inbound transactions:', error);
            alert('입고 등록에 실패했습니다.');
        } finally {
            setLoading(false);
        }
    };

    const handleReset = () => {
        setQuantities({});
        setVehicleNumber('');
        setSupplier('');
        // 리셋 시 임시저장 데이터도 삭제
        clearTempData();
    };



    // --- Data Processing for Layout ---
    // 1. Consolidate into Dongbari vs Scaffolding vs Others
    const dongbariList: Material[] = [];
    const scaffoldingList: Material[] = [];
    const otherList: Material[] = [];

    materials.forEach(m => {
        const cat = (m.category || '').trim();
        // 1. Right Column: Scaffolding (비계)
        if (cat.includes('비계')) {
            scaffoldingList.push(m);
        }
        // 2. Left Column: Dongbari (동바리) OR Support (서포트) OR System (시스템 - excluding Scaffolding)
        else if (cat.includes('동바리') || cat.includes('서포트') || cat.includes('시스템')) {
            dongbariList.push(m);
        }
        // 3. Others
        else {
            otherList.push(m);
        }
    });

    // Helper to render a "Section" (Card)
    const renderSection = (title: string, items: Material[], colorClass = 'blue') => {
        if (items.length === 0) return null;

        // 1. Sort items by Category > Name > Spec (Numeric Aware)
        items.sort((a, b) => {
            // [NEW] Special Sort for System Scaffolding (시스템 비계)
            if (title === '시스템 비계') {
                // 1. Priority: Vertical (수직재) > Horizontal (수평재) > Others
                const getPriority = (name: string) => {
                    if (name.includes('수직재')) return 1;
                    if (name.includes('수평재')) return 2;
                    return 3;
                };

                const priA = getPriority(a.itemName);
                const priB = getPriority(b.itemName);

                if (priA !== priB) return priA - priB;

                // 2. Spec Descending (Numeric Aware)
                // e.g., H18 -> H03, 4018 -> 4006
                // Using localeCompare with numeric: true in reverse order
                return (b.spec || '').localeCompare(a.spec || '', undefined, { numeric: true });
            }

            // [Original] Standard Sort for other sections
            const catCompare = (a.category || '').localeCompare(b.category || '');
            if (catCompare !== 0) return catCompare;

            const nameCompare = a.itemName.localeCompare(b.itemName);
            if (nameCompare !== 0) return nameCompare;

            // Helper to extract numeric value from spec (e.g., "2.5m" -> 2.5)
            const getSpecValue = (spec: string) => {
                const match = spec.match(/([\d.]+)/);
                return match ? parseFloat(match[1]) : 0;
            };

            const valA = getSpecValue(a.spec || '');
            const valB = getSpecValue(b.spec || '');

            // If both extracted values are valid numbers and different, sort by value
            if (valA !== valB && valA > 0 && valB > 0) {
                return valA - valB;
            }

            // Fallback to natural sort
            return (a.spec || '').localeCompare(b.spec || '', undefined, { numeric: true });
        });

        // 2. Chunk into groups of 10 (Requested: 10 items per row)
        const chunks: Material[][] = [];
        for (let i = 0; i < items.length; i += 10) {
            chunks.push(items.slice(i, i + 10));
        }

        return (
            <div className="bg-slate-50 rounded-xl border border-slate-200 overflow-hidden mb-6 h-full">
                <div className={`bg-${colorClass}-50/50 px-4 py-3 border-b border-${colorClass}-100 flex justify-between items-center`}>
                    <h3 className="font-bold text-slate-700 flex items-center gap-2">
                        <span className={`bg-${colorClass}-500 w-2 h-6 rounded-sm`}></span>
                        {title}
                    </h3>
                    <div className={`text-xs text-${colorClass}-600 font-medium bg-white px-2 py-1 rounded border border-${colorClass}-100`}>
                        {items.length} 품목
                    </div>
                </div>

                {/* Responsive Grid for Card Items - Adaptive to column width */}
                <div className="p-4 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-6 gap-4 items-start">
                    {chunks.map((chunk, chunkIndex) => (
                        <div key={chunkIndex} className="bg-white rounded-lg border border-slate-200 overflow-hidden shadow-sm">
                            <table className="w-full text-sm">
                                <thead className="bg-slate-50 border-b border-slate-200">
                                    <tr>
                                        <th className="p-3 text-left text-sm font-bold text-slate-500 uppercase tracking-wider pl-4">품명/규격</th>
                                        <th className="p-3 text-center text-sm font-bold text-slate-500 uppercase tracking-wider w-20">수량</th>
                                        <th className="p-3 text-center text-sm font-bold text-slate-500 uppercase tracking-wider w-16">단위</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {chunk.map(material => {
                                        const qty = quantities[material.id] || 0;
                                        return (
                                            <tr key={material.id} className={`transition-colors ${qty > 0 ? `bg-${colorClass}-50` : 'hover:bg-slate-50'}`}>
                                                <td className="p-3 pl-4">
                                                    <div className="text-sm text-slate-500">{material.itemName}</div>
                                                    <div className="font-bold text-slate-700 text-base mt-0.5">{material.spec}</div>
                                                </td>
                                                <td className="p-2 text-center">
                                                    <input
                                                        type="number"
                                                        value={qty || ''}
                                                        onChange={(e) => handleQuantityChange(material.id, e.target.value)}
                                                        placeholder="0"
                                                        className={`w-full border rounded px-1.5 py-2 text-center font-bold text-lg transition-all outline-none [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none ${qty > 0
                                                            ? `border-${colorClass}-500 text-${colorClass}-700 bg-white`
                                                            : `border-slate-200 bg-slate-50 text-slate-400 focus:bg-white focus:border-${colorClass}-500 focus:text-slate-800`
                                                            }`}
                                                        onFocus={(e) => e.target.select()}
                                                    />
                                                </td>
                                                <td className="p-2 text-center text-xs text-slate-400 font-medium whitespace-nowrap">
                                                    {material.unit}
                                                </td>
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                    ))}
                </div>
            </div>
        );
    };

    if (loading) return <div className="p-8 text-center">데이터 로딩 중...</div>;

    return (
        <div className="max-w-[2100px] mx-auto p-4 space-y-6">
            <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                        <FontAwesomeIcon icon={faArrowDown} className="text-blue-600" />
                        입고 등록 (Inbound)
                    </h1>
                    <p className="text-slate-500 mt-1">시스템 비계(좌) / 시스템 동바리(우) 고정 배치</p>
                </div>
                <div className="flex flex-wrap items-center gap-2">
                    <button
                        onClick={() => navigate('/materials/transactions')}
                        className="px-4 py-2.5 rounded-xl border border-slate-300 text-slate-600 font-bold hover:bg-slate-50 transition flex items-center gap-2"
                    >
                        <FontAwesomeIcon icon={faEdit} />
                        수정
                    </button>
                    <button
                        onClick={handleReset}
                        disabled={loading}
                        className="px-4 py-2.5 rounded-xl bg-slate-200 text-slate-700 font-bold hover:bg-slate-300 transition flex items-center gap-2 disabled:opacity-50"
                    >
                        <FontAwesomeIcon icon={faRotateRight} />
                        초기화
                    </button>
                    <button
                        onClick={handleSave}
                        disabled={loading}
                        className="px-6 py-2.5 rounded-xl bg-blue-600 text-white font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 transition flex items-center gap-2 disabled:opacity-50"
                    >
                        <FontAwesomeIcon icon={faSave} />
                        {loading ? '저장 중...' : '입고 완료'}
                    </button>
                </div>
            </div>

            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
                {/* 1. 기본 정보 입력 (날짜, 현장, 차량번호, 공급업체) */}
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6 mb-8">
                    <div className="space-y-2">
                        <label className="text-sm font-bold text-slate-600">입고 일자</label>
                        <input
                            type="date"
                            value={transactionDate}
                            onChange={(e) => setTransactionDate(e.target.value)}
                            className="w-full border border-slate-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all shadow-sm"
                        />
                    </div>
                    <div className="space-y-2">
                        <label className="text-sm font-bold text-slate-600">현장 선택</label>
                        <select
                            value={siteId}
                            onChange={(e) => handleSiteChange(e.target.value)}
                            className="w-full border border-slate-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all shadow-sm bg-white"
                        >
                            <option value="">현장을 선택하세요</option>
                            {sites.map(site => (
                                <option key={site.id} value={site.id}>{site.name}</option>
                            ))}
                        </select>
                    </div>
                    <div className="space-y-2">
                        <label className="text-sm font-bold text-slate-600">차량번호</label>
                        <input
                            type="text"
                            value={vehicleNumber}
                            onChange={(e) => setVehicleNumber(e.target.value)}
                            placeholder="12가3456"
                            className="w-full border border-slate-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all shadow-sm"
                        />
                    </div>
                    <div className="space-y-2">
                        <label className="block text-sm font-bold text-slate-600">공급업체</label>
                        <input
                            type="text"
                            value={supplier}
                            onChange={(e) => setSupplier(e.target.value)}
                            placeholder="공급업체명"
                            className="w-full border border-slate-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all shadow-sm"
                        />
                    </div>
                </div>


                {/* 2. Side-by-Side Layout: Scaffolding (Left) | Dongbari (Right) */}
                {/* 2. Vertical Layout: Scaffolding (Row 1) -> Dongbari (Row 2) */}
                <div className="flex flex-col gap-6 mb-6">
                    {/* Row 1: System Scaffolding */}
                    <div className="w-full">
                        {renderSection('시스템 비계', scaffoldingList, 'blue')}
                    </div>

                    {/* Row 2: System Dongbari */}
                    <div className="w-full">
                        {renderSection('시스템 동바리', dongbariList, 'blue')}
                    </div>

                    {/* Others */}
                    {otherList.length > 0 && (
                        <div className="w-full">
                            {renderSection('기타 및 소모품', otherList, 'slate')}
                        </div>
                    )}
                </div>

                {/* 임시저장 안내 */}
                {hasTempData && (
                    <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-6">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                <FontAwesomeIcon icon={faFloppyDisk} className="text-blue-600" />
                                <span className="text-blue-800 font-medium">
                                    임시저장된 데이터가 있습니다. 마지막 저장: {new Date(
                                        JSON.parse(localStorage.getItem('inbound_temp') || '{}').savedAt || Date.now()
                                    ).toLocaleString('ko-KR')}
                                </span>
                            </div>
                            <button
                                onClick={() => {
                                    if (window.confirm('임시저장된 데이터를 삭제하시겠습니까?')) {
                                        clearTempData();
                                        handleReset();
                                    }
                                }}
                                className="text-blue-600 hover:text-blue-800 transition-colors"
                            >
                                <FontAwesomeIcon icon={faTrash} />
                            </button>
                        </div>
                    </div>
                )}

                {/* 액션 버튼 */}
                <div className="flex justify-end gap-3 mt-8 pt-6 border-t border-slate-200">
                    <button
                        onClick={() => window.history.back()}
                        className="px-6 py-3 rounded-xl border border-slate-300 text-slate-600 font-bold hover:bg-slate-50 hover:text-slate-800 transition-colors"
                    >
                        취소
                    </button>
                    <button
                        onClick={handleReset}
                        disabled={loading}
                        className="px-6 py-3 rounded-xl bg-slate-200 text-slate-700 font-bold hover:bg-slate-300 transition flex items-center gap-2 disabled:opacity-50"
                    >
                        <FontAwesomeIcon icon={faRotateRight} />
                        초기화
                    </button>
                    <button
                        onClick={handleSave}
                        disabled={loading}
                        className="px-8 py-3 rounded-xl bg-blue-600 text-white font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 hover:shadow-blue-300 transition-all transform hover:-translate-y-0.5 active:translate-y-0"
                    >
                        {loading ? '저장 중...' : '입고 완료'}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default MaterialInboundPage;

import React, { useState, useEffect } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faBoxesStacked, faPlus, faEdit, faTrash, faSave, faTimes } from '@fortawesome/free-solid-svg-icons';
import materialService from '../../services/materialService';
import { siteService } from '../../services/siteService';
import { Material } from '../../types/materials';

const MaterialMasterPage: React.FC = () => {
    const [loading, setLoading] = useState(false);
    const [materials, setMaterials] = useState<Material[]>([]);
    const [filteredMaterials, setFilteredMaterials] = useState<Material[]>([]);
    const [categoryFilter, setCategoryFilter] = useState('');
    const [itemNameFilter, setItemNameFilter] = useState('');
    const [specFilter, setSpecFilter] = useState('');
    const [showForm, setShowForm] = useState(false);
    const [editingItem, setEditingItem] = useState<Material | undefined>(undefined);

    // 폼 상태
    const [formData, setFormData] = useState({
        category: '',
        itemName: '',
        spec: '',
        unit: 'EA',
        safetyStock: 0,
        description: '',
        isActive: true
    });

    useEffect(() => {
        loadData();
    }, []);

    // Lock main content scroll
    useEffect(() => {
        const mainContent = document.getElementById('main-content');
        if (mainContent) {
            const originalOverflow = mainContent.style.overflow;
            mainContent.style.overflow = 'hidden';
            return () => {
                mainContent.style.overflow = originalOverflow;
            };
        }
    }, []);

    useEffect(() => {
        applyFilters();
    }, [materials, categoryFilter, itemNameFilter, specFilter]);

    const loadData = async () => {
        setLoading(true);
        try {
            const data = await materialService.getAllMaterials();
            setMaterials(data);
        } catch (error) {
            console.error('Failed to load materials:', error);
            alert('자재 목록을 불러오지 못했습니다.');
        } finally {
            setLoading(false);
        }
    };

    const applyFilters = () => {
        let result = [...materials];

        if (categoryFilter) {
            result = result.filter(m => m.category.includes(categoryFilter));
        }
        if (itemNameFilter) {
            result = result.filter(m => m.itemName.toLowerCase().includes(itemNameFilter.toLowerCase()));
        }
        if (specFilter) {
            result = result.filter(m => m.spec.toLowerCase().includes(specFilter.toLowerCase()));
        }

        setFilteredMaterials(result);
    };

    const handleAdd = () => {
        setEditingItem(undefined);
        setFormData({
            category: '',
            itemName: '',
            spec: '',
            unit: 'EA',
            safetyStock: 0,
            description: '',
            isActive: true
        });
        setShowForm(true);
    };

    const handleEdit = (material: Material) => {
        setEditingItem(material);
        setFormData({
            category: material.category,
            itemName: material.itemName,
            spec: material.spec,
            unit: material.unit,
            safetyStock: material.safetyStock || 0,
            description: material.description || '',
            isActive: material.isActive
        });
        setShowForm(true);
    };

    const handleSave = async () => {
        if (!formData.category || !formData.itemName || !formData.spec) {
            alert('분류, 품명, 규격은 필수입니다.');
            return;
        }

        // 중복 체크 (신규 등록 시에만)
        if (!editingItem) {
            const isDuplicate = materials.some(
                m => m.itemName.trim() === formData.itemName.trim() && 
                     m.spec.trim() === formData.spec.trim() &&
                     m.isActive !== false
            );
            if (isDuplicate) {
                alert(`이미 등록된 자재입니다: ${formData.itemName} (${formData.spec})`);
                return;
            }
        }

        setLoading(true);
        try {
            if (editingItem) {
                await materialService.updateMaterial(editingItem.id, formData);
                alert('수정되었습니다.');
            } else {
                await materialService.addMaterial(formData);
                alert('등록되었습니다.');
            }
            setShowForm(false);
            loadData();
        } catch (error) {
            console.error('Failed to save material:', error);
            alert('저장에 실패했습니다.');
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id: string, name: string, spec: string) => {
        if (!window.confirm(`${name} (${spec})을 삭제하시겠습니까?`)) return;

        setLoading(true);
        try {
            await materialService.deleteMaterial(id);
            alert('삭제되었습니다.');
            loadData();
        } catch (error) {
            console.error('Failed to delete material:', error);
            alert('삭제에 실패했습니다.');
        } finally {
            setLoading(false);
        }
    };



    return (
        <div className="flex-1 min-h-0 flex flex-col p-6 max-w-[1800px] w-full mx-auto bg-slate-50 overflow-hidden">
            <div className="flex justify-between items-center mb-6 flex-shrink-0">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                        <FontAwesomeIcon icon={faBoxesStacked} className="text-indigo-600" />
                        자재 마스터 관리
                    </h1>
                    <p className="text-slate-500 mt-1">자재 정보를 등록하고 관리합니다</p>
                </div>
                <button
                    onClick={handleAdd}
                    className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition flex items-center gap-2 shadow-sm"
                >
                    <FontAwesomeIcon icon={faPlus} />
                    자재 등록
                </button>
            </div>

            {/* 등록/수정 폼 */}
            {showForm && (
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 mb-6 flex-shrink-0">
                    <h2 className="text-lg font-bold text-slate-800 mb-4">
                        {editingItem ? '자재 수정' : '자재 등록'}
                    </h2>
                    <div className="grid grid-cols-3 gap-4">
                        <div>
                            <label className="block text-sm font-bold text-slate-700 mb-2">분류 *</label>
                            <input
                                type="text"
                                value={formData.category}
                                onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                                placeholder="분류 입력 (예: 시스템 동바리)"
                                className="w-full border border-slate-300 rounded-lg px-3 py-2"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-slate-700 mb-2">품명 *</label>
                            <input
                                type="text"
                                value={formData.itemName}
                                onChange={(e) => setFormData({ ...formData, itemName: e.target.value })}
                                placeholder="수직재, 수평재 등"
                                className="w-full border border-slate-300 rounded-lg px-3 py-2"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-slate-700 mb-2">규격 *</label>
                            <input
                                type="text"
                                value={formData.spec}
                                onChange={(e) => setFormData({ ...formData, spec: e.target.value })}
                                placeholder="P17, H15 등"
                                className="w-full border border-slate-300 rounded-lg px-3 py-2"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-slate-700 mb-2">단위</label>
                            <input
                                type="text"
                                value={formData.unit}
                                onChange={(e) => setFormData({ ...formData, unit: e.target.value })}
                                placeholder="EA, SET 등"
                                className="w-full border border-slate-300 rounded-lg px-3 py-2"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-slate-700 mb-2">안전재고</label>
                            <input
                                type="number"
                                value={formData.safetyStock}
                                onChange={(e) => setFormData({ ...formData, safetyStock: parseInt(e.target.value) || 0 })}
                                placeholder="0"
                                className="w-full border border-slate-300 rounded-lg px-3 py-2"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-slate-700 mb-2">설명</label>
                            <input
                                type="text"
                                value={formData.description}
                                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                placeholder="선택사항"
                                className="w-full border border-slate-300 rounded-lg px-3 py-2"
                            />
                        </div>
                    </div>
                    <div className="flex justify-end gap-2 mt-4">
                        <button
                            onClick={() => setShowForm(false)}
                            className="bg-slate-200 text-slate-700 px-4 py-2 rounded-lg hover:bg-slate-300 transition flex items-center gap-2"
                        >
                            <FontAwesomeIcon icon={faTimes} />
                            취소
                        </button>
                        <button
                            onClick={handleSave}
                            disabled={loading}
                            className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition flex items-center gap-2 disabled:opacity-50"
                        >
                            <FontAwesomeIcon icon={faSave} />
                            저장
                        </button>
                    </div>
                </div>
            )}

            {/* 필터 및 목록 */}
            <div className="flex-1 min-h-0 bg-white rounded-xl shadow-sm border border-slate-200 p-6 flex flex-col overflow-hidden">
                <div className="mb-4 flex gap-4 flex-shrink-0">
                    <input
                        type="text"
                        value={categoryFilter}
                        onChange={(e) => setCategoryFilter(e.target.value)}
                        placeholder="분류 검색..."
                        className="border border-slate-300 rounded-lg px-3 py-2 text-sm"
                    />
                    <input
                        type="text"
                        value={itemNameFilter}
                        onChange={(e) => setItemNameFilter(e.target.value)}
                        placeholder="품명 검색..."
                        className="border border-slate-300 rounded-lg px-3 py-2 text-sm flex-1"
                    />
                    <input
                        type="text"
                        value={specFilter}
                        onChange={(e) => setSpecFilter(e.target.value)}
                        placeholder="규격 검색..."
                        className="border border-slate-300 rounded-lg px-3 py-2 text-sm w-40"
                    />
                </div>

                {loading ? (
                    <div className="text-center py-20 text-slate-400">
                        로딩 중...
                    </div>
                ) : filteredMaterials.length === 0 ? (
                    <div className="text-center py-20 text-slate-400">
                        <FontAwesomeIcon icon={faBoxesStacked} className="text-6xl mb-4 text-slate-200" />
                        <p>등록된 자재가 없습니다.</p>
                        <p className="text-sm mt-2">우측 상단의 '자재 등록' 버튼을 눌러 자재를 추가하세요.</p>
                    </div>
                ) : (
                    <div className="flex-1 overflow-auto">
                        <table className="w-full text-sm">
                            <thead className="bg-slate-100 border-b border-slate-300 sticky top-0 z-10">
                                <tr>
                                    <th className="p-3 text-left font-bold text-slate-700">분류</th>
                                    <th className="p-3 text-left font-bold text-slate-700">품명</th>
                                    <th className="p-3 text-left font-bold text-slate-700">규격</th>
                                    <th className="p-3 text-center font-bold text-slate-700">단위</th>
                                    <th className="p-3 text-right font-bold text-slate-700">안전재고</th>
                                    <th className="p-3 text-left font-bold text-slate-700">설명</th>
                                    <th className="p-3 text-center font-bold text-slate-700">액션</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-200">
                                {filteredMaterials.map(material => (
                                    <tr key={material.id} className="hover:bg-slate-50">
                                        <td className="p-3">{material.category}</td>
                                        <td className="p-3 font-semibold">{material.itemName}</td>
                                        <td className="p-3">{material.spec}</td>
                                        <td className="p-3 text-center">{material.unit}</td>
                                        <td className="p-3 text-right">{material.safetyStock || '-'}</td>
                                        <td className="p-3">{material.description || '-'}</td>
                                        <td className="p-3 text-center">
                                            <button
                                                onClick={() => handleEdit(material)}
                                                className="text-blue-600 hover:text-blue-800 mx-1"
                                            >
                                                <FontAwesomeIcon icon={faEdit} />
                                            </button>
                                            <button
                                                onClick={() => handleDelete(material.id, material.itemName, material.spec)}
                                                className="text-red-600 hover:text-red-800 mx-1"
                                            >
                                                <FontAwesomeIcon icon={faTrash} />
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div>
    );
};

export default MaterialMasterPage;

/* Force Re-build: 2025-12-26 11:45 - Fixed Split Layout */
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faArrowUp, faSave, faRotateRight, faFloppyDisk, faTrash, faEdit } from '@fortawesome/free-solid-svg-icons';
import materialService from '../../services/materialService';
import { siteService, Site } from '../../services/siteService';
import { Material, OutboundTransaction } from '../../types/materials';
import { useAuth } from '../../contexts/AuthContext';

// 임시저장 데이터 타입
type OutboundTempData = {
    transactionDate: string;
    siteId: string;
    siteName: string;
    vehicleNumber: string;
    recipient: string;
    quantities: Record<string, number>;
    savedAt: number;
};

const MaterialOutboundPage: React.FC = () => {
    const navigate = useNavigate();
    const { currentUser } = useAuth();
    const [loading, setLoading] = useState(false);
    const [transactionDate, setTransactionDate] = useState(new Date().toISOString().slice(0, 10));
    const [siteId, setSiteId] = useState('');
    const [siteName, setSiteName] = useState('');
    const [vehicleNumber, setVehicleNumber] = useState('');
    const [recipient, setRecipient] = useState('');

    const [sites, setSites] = useState<Site[]>([]);
    const [materials, setMaterials] = useState<Material[]>([]);
    const [quantities, setQuantities] = useState<Record<string, number>>({});
    const [hasTempData, setHasTempData] = useState(false);

    // 임시저장 데이터 로드
    const loadTempData = () => {
        try {
            const tempDataStr = localStorage.getItem('outbound_temp');
            if (!tempDataStr) return;

            const tempData: OutboundTempData = JSON.parse(tempDataStr);

            // 24시간 이상 된 데이터는 정리
            const now = Date.now();
            if (now - tempData.savedAt > 24 * 60 * 60 * 1000) {
                localStorage.removeItem('outbound_temp');
                return;
            }

            // 데이터 복원
            setTransactionDate(tempData.transactionDate);
            setSiteId(tempData.siteId);
            setSiteName(tempData.siteName);
            setVehicleNumber(tempData.vehicleNumber);
            setRecipient(tempData.recipient);
            setQuantities(tempData.quantities || {});
            setHasTempData(true);

            // Ref도 즉시 동기화 (Strict Mode 대응)
            stateRef.current = {
                transactionDate: tempData.transactionDate,
                siteId: tempData.siteId,
                siteName: tempData.siteName,
                vehicleNumber: tempData.vehicleNumber,
                recipient: tempData.recipient,
                quantities: tempData.quantities || {}
            };

            console.log('[Outbound] 임시저장 데이터를 복원했습니다:', tempData);
        } catch (error) {
            console.error('[Outbound] 임시저장 데이터 로드 실패:', error);
            localStorage.removeItem('outbound_temp');
        }
    };

    // 임시저장 데이터 저장
    const saveTempData = () => {
        try {
            const tempData: OutboundTempData = {
                transactionDate,
                siteId,
                siteName,
                vehicleNumber,
                recipient,
                quantities,
                savedAt: Date.now()
            };
            localStorage.setItem('outbound_temp', JSON.stringify(tempData));
            setHasTempData(true);
        } catch (error) {
            console.error('[Outbound] 임시저장 데이터 저장 실패:', error);
        }
    };

    // 임시저장 데이터 삭제
    const clearTempData = () => {
        localStorage.removeItem('outbound_temp');
        setHasTempData(false);
    };

    // 최신 상태를 추적하기 위한 Ref
    const stateRef = React.useRef({
        transactionDate,
        siteId,
        siteName,
        vehicleNumber,
        recipient,
        quantities
    });

    // 렌더링마다 Ref 업데이트
    useEffect(() => {
        stateRef.current = {
            transactionDate,
            siteId,
            siteName,
            vehicleNumber,
            recipient,
            quantities
        };
    }, [transactionDate, siteId, siteName, vehicleNumber, recipient, quantities]);

    // 실제 저장 로직 (Ref 기준)
    const performSave = () => {
        try {
            const current = stateRef.current;
            const tempData: OutboundTempData = {
                transactionDate: current.transactionDate,
                siteId: current.siteId,
                siteName: current.siteName,
                vehicleNumber: current.vehicleNumber,
                recipient: current.recipient,
                quantities: current.quantities,
                savedAt: Date.now()
            };
            localStorage.setItem('outbound_temp', JSON.stringify(tempData));
            setHasTempData(true);
            console.log('[Outbound] Auto-saved data:', tempData);
        } catch (error) {
            console.error('[Outbound] Temp save failed:', error);
        }
    };

    useEffect(() => {
        loadData();
        loadTempData();

        // 브라우저 종료/새로고침 시 저장
        const handleBeforeUnload = () => {
            performSave();
        };
        window.addEventListener('beforeunload', handleBeforeUnload);

        return () => {
            window.removeEventListener('beforeunload', handleBeforeUnload);
            // 컴포넌트 언마운트(페이지 이동) 시 저장
            performSave();
        };
    }, []);

    const loadData = async () => {
        setLoading(true);
        try {
            const [sitesData, materialsData] = await Promise.all([
                siteService.getSites(),
                materialService.getUniqueMaterialsForSelection()
            ]);
            setSites(sitesData.filter((s: any) => s.status === 'active'));
            setMaterials(materialsData);

            setQuantities((prev) => {
                const validIds = new Set(materialsData.map((m) => m.id));
                const nextEntries = Object.entries(prev).filter(([id]) => validIds.has(id));
                return Object.fromEntries(nextEntries);
            });
        } catch (error) {
            console.error('Failed to load data:', error);
            alert('데이터를 불러오지 못했습니다.');
        } finally {
            setLoading(false);
        }
    };

    const handleSiteChange = (selectedSiteId: string) => {
        setSiteId(selectedSiteId);
        const site = sites.find(s => s.id === selectedSiteId);
        setSiteName(site?.name || '');
    };

    const handleQuantityChange = (materialId: string, value: string) => {
        const numValue = parseInt(value) || 0;
        setQuantities(prev => ({
            ...prev,
            [materialId]: numValue
        }));
    };

    const handleSave = async () => {
        if (!siteId) {
            alert('현장을 선택하세요.');
            return;
        }

        const transactions: Array<Omit<OutboundTransaction, 'id' | 'createdAt' | 'updatedAt'>> = [];
        const resolvedSiteName = siteName || sites.find(s => s.id === siteId)?.name || '';

        Object.entries(quantities).forEach(([materialId, quantity]) => {
            if (quantity > 0) {
                const material = materials.find(m => m.id === materialId);
                if (material) {
                    transactions.push({
                        transactionDate,
                        siteId,
                        siteName: String(resolvedSiteName || '').trim(),
                        vehicleNumber: vehicleNumber || '',
                        materialId: material.id,
                        category: String(material.category || '').trim(),
                        itemName: String(material.itemName || '').trim(),
                        spec: String(material.spec || '').trim(),
                        quantity,
                        unit: String(material.unit || '').trim(),
                        recipient: recipient || '',
                        deliveryStatus: 'pending',
                        notes: '',
                        registeredBy: currentUser?.uid || '',
                        registeredByName: currentUser?.displayName || currentUser?.email || '관리자'
                    });
                }
            }
        });

        if (transactions.length === 0) {
            alert('출고할 자재를 입력하세요.');
            return;
        }

        setLoading(true);
        try {
            await materialService.addOutboundTransactionsBatch(transactions);
            alert(`${transactions.length}건의 출고가 등록되었습니다.`);
            // 저장 성공 후 임시저장 데이터 삭제
            clearTempData();
            handleReset();
        } catch (error) {
            console.error('Failed to save outbound transactions:', error);
            alert('출고 등록에 실패했습니다.');
        } finally {
            setLoading(false);
        }
    };

    const handleReset = () => {
        setQuantities({});
        setVehicleNumber('');
        setRecipient('');
        // 리셋 시 임시저장 데이터도 삭제
        clearTempData();
    };

    // 자동 저장 (Debounce)
    useEffect(() => {
        const timer = setTimeout(() => {
            performSave();
        }, 1000);

        return () => clearTimeout(timer);
    }, [transactionDate, siteId, siteName, vehicleNumber, recipient, quantities]);

    // --- Data Processing for Layout ---
    // 1. Consolidate into Dongbari vs Scaffolding vs Others
    const dongbariList: Material[] = [];
    const scaffoldingList: Material[] = [];
    const otherList: Material[] = [];

    materials.forEach(m => {
        const cat = (m.category || '').trim();
        // 1. Right Column: Scaffolding (비계)
        if (cat.includes('비계')) {
            scaffoldingList.push(m);
        }
        // 2. Left Column: Dongbari (동바리) OR Support (서포트) OR System (시스템 - excluding Scaffolding)
        else if (cat.includes('동바리') || cat.includes('서포트') || cat.includes('시스템')) {
            dongbariList.push(m);
        }
        // 3. Others
        else {
            otherList.push(m);
        }
    });

    // Helper to render a "Section" (Card)
    const renderSection = (title: string, items: Material[], colorClass = 'red') => {
        if (items.length === 0) return null;

        // 1. Sort items by Category > Name > Spec (Numeric Aware)
        items.sort((a, b) => {
            // [NEW] Special Sort for System Scaffolding (시스템 비계)
            if (title === '시스템 비계') {
                // 1. Priority: Vertical (수직재) > Horizontal (수평재) > Others
                const getPriority = (name: string) => {
                    if (name.includes('수직재')) return 1;
                    if (name.includes('수평재')) return 2;
                    return 3;
                };

                const priA = getPriority(a.itemName);
                const priB = getPriority(b.itemName);

                if (priA !== priB) return priA - priB;

                // 2. Spec Descending (Numeric Aware)
                // e.g., H18 -> H03, 4018 -> 4006
                // Using localeCompare with numeric: true in reverse order
                return (b.spec || '').localeCompare(a.spec || '', undefined, { numeric: true });
            }

            // [Original] Standard Sort for other sections
            const catCompare = (a.category || '').localeCompare(b.category || '');
            if (catCompare !== 0) return catCompare;

            const nameCompare = a.itemName.localeCompare(b.itemName);
            if (nameCompare !== 0) return nameCompare;

            // Helper to extract numeric value from spec (e.g., "2.5m" -> 2.5)
            const getSpecValue = (spec: string) => {
                const match = spec.match(/([\d.]+)/);
                return match ? parseFloat(match[1]) : 0;
            };

            const valA = getSpecValue(a.spec || '');
            const valB = getSpecValue(b.spec || '');

            // If both extracted values are valid numbers and different, sort by value
            if (valA !== valB && valA > 0 && valB > 0) {
                return valA - valB;
            }

            // Fallback to natural sort
            return (a.spec || '').localeCompare(b.spec || '', undefined, { numeric: true });
        });

        // 2. Chunk into groups of 10 (Requested: 10 items per row)
        const chunks: Material[][] = [];
        for (let i = 0; i < items.length; i += 10) {
            chunks.push(items.slice(i, i + 10));
        }

        return (
            <div className="bg-slate-50 rounded-xl border border-slate-200 overflow-hidden mb-6">
                <div className={`bg-${colorClass}-50/50 px-4 py-3 border-b border-${colorClass}-100 flex justify-between items-center`}>
                    <h3 className="font-bold text-slate-700 flex items-center gap-2">
                        <span className={`bg-${colorClass}-500 w-2 h-6 rounded-sm`}></span>
                        {title}
                    </h3>
                    <div className={`text-xs text-${colorClass}-600 font-medium bg-white px-2 py-1 rounded border border-${colorClass}-100`}>
                        {items.length} 품목
                    </div>
                </div>

                {/* Responsive Grid for Card Items - Adaptive to column width */}
                <div className="p-4 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-6 gap-4 items-start">
                    {chunks.map((chunk, chunkIndex) => (
                        <div key={chunkIndex} className="bg-white rounded-lg border border-slate-200 overflow-hidden shadow-sm">
                            <table className="w-full text-sm">
                                <thead className="bg-slate-50 border-b border-slate-200">
                                    <tr>
                                        <th className="p-3 text-left text-sm font-bold text-slate-500 uppercase tracking-wider pl-4">품명/규격</th>
                                        <th className="p-3 text-center text-sm font-bold text-slate-500 uppercase tracking-wider w-20">수량</th>
                                        <th className="p-3 text-center text-sm font-bold text-slate-500 uppercase tracking-wider w-16">단위</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {chunk.map(material => {
                                        const qty = quantities[material.id] || 0;
                                        return (
                                            <tr key={material.id} className={`transition-colors ${qty > 0 ? `bg-${colorClass}-50` : 'hover:bg-slate-50'}`}>
                                                <td className="p-3 pl-4">
                                                    <div className="text-sm text-slate-500">{material.itemName}</div>
                                                    <div className="font-bold text-slate-700 text-base mt-0.5">{material.spec}</div>
                                                </td>
                                                <td className="p-2 text-center">
                                                    <input
                                                        type="number"
                                                        value={qty || ''}
                                                        onChange={(e) => handleQuantityChange(material.id, e.target.value)}
                                                        placeholder="0"
                                                        className={`w-full border rounded px-1.5 py-2 text-center font-bold text-lg transition-all outline-none [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none ${qty > 0
                                                            ? `border-${colorClass}-500 text-${colorClass}-700 bg-white`
                                                            : `border-slate-200 bg-slate-50 text-slate-400 focus:bg-white focus:border-${colorClass}-500 focus:text-slate-800`
                                                            }`}
                                                        onFocus={(e) => e.target.select()}
                                                    />
                                                </td>
                                                <td className="p-2 text-center text-xs text-slate-400 font-medium whitespace-nowrap">
                                                    {material.unit}
                                                </td>
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                    ))}
                </div>
            </div>
        );
    };

    return (
        <div className="p-6 max-w-[2100px] mx-auto bg-slate-50 min-h-screen">
            <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4 mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                        <FontAwesomeIcon icon={faArrowUp} className="text-red-600" />
                        출고 등록
                    </h1>
                    <p className="text-slate-500 mt-1">시스템 비계(좌) / 시스템 동바리(우) 고정 배치</p>
                </div>
                <div className="flex flex-wrap items-center gap-2">
                    <button
                        onClick={() => navigate('/materials/transactions')}
                        className="px-4 py-2.5 rounded-xl border border-slate-300 text-slate-600 font-bold hover:bg-slate-50 transition flex items-center gap-2"
                    >
                        <FontAwesomeIcon icon={faEdit} />
                        수정
                    </button>
                    <button
                        onClick={handleReset}
                        disabled={loading}
                        className="px-4 py-2.5 rounded-xl bg-slate-200 text-slate-700 font-bold hover:bg-slate-300 transition flex items-center gap-2 disabled:opacity-50"
                    >
                        <FontAwesomeIcon icon={faRotateRight} />
                        초기화
                    </button>
                    <button
                        onClick={handleSave}
                        disabled={loading}
                        className="px-6 py-2.5 rounded-xl bg-red-600 text-white font-bold hover:bg-red-700 shadow-md transition flex items-center gap-2 disabled:opacity-50"
                    >
                        <FontAwesomeIcon icon={faSave} />
                        {loading ? '저장 중...' : '출고 완료'}
                    </button>
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                {/* 기본 정보 입력 */}
                <div className="grid grid-cols-4 gap-4 mb-6">
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2">출고일자 *</label>
                        <input
                            type="date"
                            value={transactionDate}
                            onChange={(e) => setTransactionDate(e.target.value)}
                            className="w-full border border-slate-300 rounded-lg px-3 py-2"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2">현장명 *</label>
                        <select
                            value={siteId}
                            onChange={(e) => handleSiteChange(e.target.value)}
                            className="w-full border border-slate-300 rounded-lg px-3 py-2"
                        >
                            <option value="">현장 선택</option>
                            {sites.map(site => (
                                <option key={site.id} value={site.id}>{site.name}</option>
                            ))}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2">차량번호</label>
                        <input
                            type="text"
                            value={vehicleNumber}
                            onChange={(e) => setVehicleNumber(e.target.value)}
                            placeholder="12가3456"
                            className="w-full border border-slate-300 rounded-lg px-3 py-2"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2">반출자</label>
                        <input
                            type="text"
                            value={recipient}
                            onChange={(e) => setRecipient(e.target.value)}
                            placeholder="반출자명"
                            className="w-full border border-slate-300 rounded-lg px-3 py-2"
                        />
                    </div>
                </div>

                {/* 2. Side-by-Side Layout: Scaffolding (Left) | Dongbari (Right) */}
                {/* 2. Vertical Layout: Scaffolding (Row 1) -> Dongbari (Row 2) */}
                <div className="flex flex-col gap-6 mb-6">
                    {/* Row 1: System Scaffolding */}
                    <div className="w-full">
                        {renderSection('시스템 비계', scaffoldingList, 'red')}
                    </div>

                    {/* Row 2: System Dongbari */}
                    <div className="w-full">
                        {renderSection('시스템 동바리', dongbariList, 'red')}
                    </div>

                    {/* Others */}
                    {otherList.length > 0 && (
                        <div className="w-full">
                            {renderSection('기타 및 소모품', otherList, 'slate')}
                        </div>
                    )}
                </div>

                {/* 임시저장 안내 */}
                {hasTempData && (
                    <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-6">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                <FontAwesomeIcon icon={faFloppyDisk} className="text-blue-600" />
                                <span className="text-blue-800 font-medium">
                                    임시저장된 데이터가 있습니다. 마지막 저장: {new Date(
                                        JSON.parse(localStorage.getItem('outbound_temp') || '{}').savedAt || Date.now()
                                    ).toLocaleString('ko-KR')}
                                </span>
                            </div>
                            <button
                                onClick={() => {
                                    if (window.confirm('임시저장된 데이터를 삭제하시겠습니까?')) {
                                        clearTempData();
                                        handleReset();
                                    }
                                }}
                                className="text-blue-600 hover:text-blue-800 transition-colors"
                            >
                                <FontAwesomeIcon icon={faTrash} />
                            </button>
                        </div>
                    </div>
                )}

                {/* 액션 버튼 */}
                <div className="flex justify-end gap-2 pt-6 border-t border-slate-200">
                    <button
                        onClick={() => window.history.back()}
                        className="px-6 py-2 rounded-lg border border-slate-300 text-slate-600 font-bold hover:bg-slate-50 hover:text-slate-800 transition-colors"
                    >
                        취소
                    </button>
                    <button
                        onClick={handleReset}
                        disabled={loading}
                        className="bg-slate-200 text-slate-700 px-6 py-2 rounded-lg hover:bg-slate-300 transition flex items-center gap-2 disabled:opacity-50"
                    >
                        <FontAwesomeIcon icon={faRotateRight} />
                        초기화
                    </button>
                    <button
                        onClick={handleSave}
                        disabled={loading}
                        className="bg-red-600 text-white px-6 py-2 rounded-lg hover:bg-red-700 transition flex items-center gap-2 shadow-md disabled:opacity-50"
                    >
                        <FontAwesomeIcon icon={faSave} />
                        {loading ? '저장 중...' : '저장'}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default MaterialOutboundPage;

import React, { useState, useEffect } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faClipboardList,
    faSearch,
    faDownload,
    faTruck,
    faArrowRight,
    faArrowLeft,
    faFilter,
    faEdit,
    faTrash,
    faTimes,
    faSave
} from '@fortawesome/free-solid-svg-icons';
import materialService from '../../services/materialService';
import { siteService, Site } from '../../services/siteService';
import { InboundTransaction, Material, OutboundTransaction } from '../../types/materials';
import * as XLSX from 'xlsx';

type Transaction = (InboundTransaction | OutboundTransaction) & { type: 'inbound' | 'outbound' };

const MaterialTransactionsPage: React.FC = () => {
    const [loading, setLoading] = useState(false);
    const [transactions, setTransactions] = useState<Transaction[]>([]);
    const [sites, setSites] = useState<Site[]>([]);
    const [materials, setMaterials] = useState<Material[]>([]);

    // Filters
    const [startDate, setStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
    const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);
    const [siteId, setSiteId] = useState('');
    const [siteKeyword, setSiteKeyword] = useState('');
    const [transactionType, setTransactionType] = useState<'all' | 'inbound' | 'outbound'>('all');
    const [vehicleNumber, setVehicleNumber] = useState('');
    const [materialName, setMaterialName] = useState('');

    // Edit State
    const [editingTx, setEditingTx] = useState<Transaction | null>(null);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);

    // Edit Form State
    const [editForm, setEditForm] = useState({
        transactionDate: '',
        siteId: '',
        vehicleNumber: '',
        quantity: 0,
        notes: ''
    });

    const normalizeDateInput = (value: string): string => {
        const digits = String(value ?? '').replace(/[^\d]/g, '').slice(0, 8);
        if (digits.length <= 4) return digits;
        if (digits.length <= 6) return `${digits.slice(0, 4)}-${digits.slice(4)}`;
        return `${digits.slice(0, 4)}-${digits.slice(4, 6)}-${digits.slice(6, 8)}`;
    };

    const isValidDateText = (value: string): boolean => {
        return /^\d{4}-\d{2}-\d{2}$/.test(String(value ?? '').trim());
    };

    const trimText = (value: unknown): string => String(value ?? '').trim();
    const normalizeSearchText = (value: unknown): string => trimText(value).replace(/\s+/g, '').toLowerCase();

    useEffect(() => {
        loadMasterData();
        handleSearch();
    }, []);

    // Lock main content scroll
    useEffect(() => {
        const mainContent = document.getElementById('main-content');
        if (mainContent) {
            const originalOverflow = mainContent.style.overflow;
            mainContent.style.overflow = 'hidden';
            return () => {
                mainContent.style.overflow = originalOverflow;
            };
        }
    }, []);

    const loadMasterData = async () => {
        try {
            const [siteRows, materialRows] = await Promise.all([
                siteService.getSites(),
                materialService.getAllMaterials(),
            ]);
            setSites(siteRows.filter((s) => s.status === 'active'));
            setMaterials(materialRows);
        } catch (error) {
            console.error('Failed to load transaction master data:', error);
        }
    };

    const filteredSites = sites.filter((site) => {
        if (!siteKeyword.trim()) return true;
        return normalizeSearchText(site.name).includes(normalizeSearchText(siteKeyword));
    });

    const handleSearch = async () => {
        if (!isValidDateText(startDate) || !isValidDateText(endDate)) {
            alert('날짜는 YYYY-MM-DD 형식으로 입력해 주세요.');
            return;
        }

        setLoading(true);
        try {
            let fetchedInbound: InboundTransaction[] = [];
            let fetchedOutbound: OutboundTransaction[] = [];

            const filters = {
                startDate,
                endDate,
                siteId: siteId || undefined,
                vehicleNumber: vehicleNumber || undefined,
            };

            if (transactionType === 'all' || transactionType === 'inbound') {
                fetchedInbound = await materialService.getInboundTransactions(filters);
            }
            if (transactionType === 'all' || transactionType === 'outbound') {
                fetchedOutbound = await materialService.getOutboundTransactions(filters);
            }

            // Merge and Tag
            const labeledInbound = fetchedInbound.map(t => ({ ...t, type: 'inbound' as const }));
            const labeledOutbound = fetchedOutbound.map(t => ({ ...t, type: 'outbound' as const }));

            let all = [...labeledInbound, ...labeledOutbound];

            // Client-side filtering for Material Name
            if (materialName) {
                all = all.filter(t => t.itemName.includes(materialName) || t.spec?.includes(materialName));
            }

            // Sort by Date DESC
            all.sort((a, b) => new Date(b.transactionDate).getTime() - new Date(a.transactionDate).getTime());

            const materialById = new Map(materials.map((m) => [m.id, m]));
            const normalized = all.map((t) => {
                const master = materialById.get(t.materialId);
                return {
                    ...t,
                    category: trimText(master?.category) || trimText(t.category),
                    itemName: trimText(master?.itemName) || trimText(t.itemName),
                    spec: trimText(master?.spec) || trimText(t.spec),
                    unit: trimText(master?.unit) || trimText(t.unit),
                };
            });

            setTransactions(normalized);
        } catch (error) {
            console.error('Failed to search transactions:', error);
            alert('데이터를 조회하는 중 오류가 발생했습니다.');
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (tx: Transaction) => {
        if (!window.confirm(`${tx.transactionDate} ${tx.itemName} 내역을 삭제하시겠습니까?`)) return;

        try {
            if (tx.type === 'inbound') {
                await materialService.deleteInboundTransaction(tx.id);
            } else {
                await materialService.deleteOutboundTransaction(tx.id);
            }
            alert('삭제되었습니다.');
            handleSearch(); // Refresh list
        } catch (error) {
            console.error('Deletion failed:', error);
            alert('삭제에 실패했습니다.');
        }
    };

    const openEditModal = (tx: Transaction) => {
        setEditingTx(tx);
        setEditForm({
            transactionDate: tx.transactionDate,
            siteId: tx.siteId,
            vehicleNumber: tx.vehicleNumber || '',
            quantity: tx.quantity,
            notes: tx.notes || ''
        });
        setIsEditModalOpen(true);
    };

    const handleUpdate = async () => {
        if (!editingTx) return;
        if (!isValidDateText(editForm.transactionDate)) {
            alert('일자는 YYYY-MM-DD 형식으로 입력해 주세요.');
            return;
        }

        try {
            const updates = {
                transactionDate: editForm.transactionDate,
                siteId: editForm.siteId,
                siteName: sites.find(s => s.id === editForm.siteId)?.name || '',
                vehicleNumber: editForm.vehicleNumber,
                quantity: Number(editForm.quantity),
                notes: editForm.notes
            };

            if (editingTx.type === 'inbound') {
                await materialService.updateInboundTransaction(editingTx.id, updates);
            } else {
                await materialService.updateOutboundTransaction(editingTx.id, updates);
            }

            alert('수정되었습니다.');
            setIsEditModalOpen(false);
            setEditingTx(null);
            handleSearch(); // Refresh list
        } catch (error) {
            console.error('Update failed:', error);
            alert('수정에 실패했습니다.');
        }
    };

    const handleDownloadExcel = () => {
        const data = visibleTransactions.map(t => ({
            '일자': t.transactionDate,
            '구분': t.type === 'inbound' ? '입고' : '출고',
            '현장': t.siteName,
            '품명': t.itemName,
            '규격': t.spec,
            '수량': t.quantity,
            '단위': t.unit,
            '차량번호': t.vehicleNumber || '-',
            '담당자': t.registeredByName,
            '비고': t.notes || ''
        }));

        const ws = XLSX.utils.json_to_sheet(data);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "입출고내역");
        XLSX.writeFile(wb, `자재입출고내역_${new Date().toISOString().slice(0, 10)}.xlsx`);
    };

    const visibleTransactions = transactions.filter((t) => {
        if (!siteKeyword.trim()) return true;
        return normalizeSearchText(t.siteName).includes(normalizeSearchText(siteKeyword));
    });

    return (
        <div className="flex-1 min-h-0 flex flex-col p-6 max-w-[2200px] w-full mx-auto bg-slate-50 overflow-hidden font-sans">
            <div className="flex justify-between items-center mb-6 flex-shrink-0">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                        <FontAwesomeIcon icon={faClipboardList} className="text-indigo-600" />
                        자재 입출고 내역
                    </h1>
                    <p className="text-slate-500 mt-1 text-sm">기간별, 차량별, 현장별 자재 이동 내역을 조회합니다.</p>
                </div>
                <button
                    onClick={handleDownloadExcel}
                    className="bg-emerald-600 text-white px-4 py-2 rounded-lg hover:bg-emerald-700 transition flex items-center gap-2 shadow-sm font-medium"
                >
                    <FontAwesomeIcon icon={faDownload} />
                    Excel 다운로드
                </button>
            </div>

            {/* Filter Section */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 mb-6 flex-shrink-0">
                <div className="grid grid-cols-1 md:grid-cols-7 gap-4 items-end">
                    <div className="md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 mb-1">시작일</label>
                        <input
                            type="text"
                            value={startDate}
                            onChange={(e) => setStartDate(normalizeDateInput(e.target.value))}
                            onBlur={(e) => setStartDate(normalizeDateInput(e.target.value))}
                            placeholder="YYYY-MM-DD"
                            inputMode="numeric"
                            autoComplete="off"
                            className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-100 outline-none"
                        />
                    </div>
                    <div className="md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 mb-1">종료일</label>
                        <input
                            type="text"
                            value={endDate}
                            onChange={(e) => setEndDate(normalizeDateInput(e.target.value))}
                            onBlur={(e) => setEndDate(normalizeDateInput(e.target.value))}
                            placeholder="YYYY-MM-DD"
                            inputMode="numeric"
                            autoComplete="off"
                            className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-100 outline-none"
                        />
                    </div>
                    <div className="md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 mb-1">현장</label>
                        <select
                            value={siteId}
                            onChange={(e) => setSiteId(e.target.value)}
                            className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-100 outline-none"
                        >
                            <option value="">전체 현장</option>
                            {filteredSites.map(site => (
                                <option key={site.id} value={site.id}>{site.name}</option>
                            ))}
                        </select>
                    </div>
                    <div className="md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 mb-1">현장명 검색</label>
                        <input
                            type="text"
                            value={siteKeyword}
                            onChange={(e) => setSiteKeyword(e.target.value)}
                            placeholder="현장명 포함 검색"
                            className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-100 outline-none"
                        />
                    </div>
                    <div className="md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 mb-1">구분</label>
                        <select
                            value={transactionType}
                            onChange={(e) => setTransactionType(e.target.value as any)}
                            className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-100 outline-none"
                        >
                            <option value="all">전체</option>
                            <option value="inbound">입고 (In)</option>
                            <option value="outbound">출고 (Out)</option>
                        </select>
                    </div>
                    <div className="md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 mb-1">차량번호</label>
                        <div className="relative">
                            <input
                                type="text"
                                value={vehicleNumber}
                                onChange={(e) => setVehicleNumber(e.target.value)}
                                placeholder="차량번호 (예: 12가3456)"
                                className="w-full border border-slate-200 rounded-lg pl-9 pr-3 py-2 text-sm focus:ring-2 focus:ring-indigo-100 outline-none"
                            />
                            <FontAwesomeIcon icon={faTruck} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs" />
                        </div>
                    </div>
                    <div className="md:col-span-1 flex gap-2">
                        <button
                            onClick={handleSearch}
                            className="flex-1 bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition flex items-center justify-center gap-2 shadow-sm shadow-indigo-200"
                        >
                            <FontAwesomeIcon icon={faSearch} />
                            조회
                        </button>
                    </div>
                </div>
            </div>

            {/* Data Table */}
            <div className="flex-1 min-h-0 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col overflow-hidden">
                <div className="flex-1 overflow-auto min-h-[780px] max-h-[calc(100vh-220px)]">
                    <table className="w-full min-w-[1680px] text-sm">
                        <thead className="bg-slate-50 border-b border-slate-200 sticky top-0 z-10">
                            <tr>
                                <th className="p-4 text-left font-bold text-slate-600 w-32 sticky left-0 z-20 bg-slate-50">일자</th>
                                <th className="p-4 text-center font-bold text-slate-600 w-24 sticky left-[128px] z-20 bg-slate-50">구분</th>
                                <th className="p-4 text-left font-bold text-slate-600 min-w-[220px] sticky left-[224px] z-20 bg-slate-50">현장</th>
                                <th className="p-4 text-left font-bold text-slate-600 min-w-[220px] sticky left-[444px] z-20 bg-slate-50">품명</th>
                                <th className="p-4 text-left font-bold text-slate-600 min-w-[180px]">규격</th>
                                <th className="p-4 text-right font-bold text-slate-600 w-24">수량</th>
                                <th className="p-4 text-left font-bold text-slate-600 w-20">단위</th>
                                <th className="p-4 text-left font-bold text-slate-600 min-w-[160px]">차량번호</th>
                                <th className="p-4 text-left font-bold text-slate-600 min-w-[120px]">등록자</th>
                                <th className="p-4 text-left font-bold text-slate-600 min-w-[220px]">비고</th>
                                <th className="p-4 text-center font-bold text-slate-600 w-24">관리</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {loading ? (
                                <tr>
                                    <td colSpan={11} className="p-20 text-center text-slate-400">
                                        <div className="animate-spin inline-block w-8 h-8 border-4 border-indigo-200 border-t-indigo-600 rounded-full mb-4"></div>
                                        <p>데이터를 불러오는 중입니다...</p>
                                    </td>
                                </tr>
                            ) : visibleTransactions.length > 0 ? (
                                visibleTransactions.map((t, index) => (
                                    <tr key={`${t.id}-${index}`} className="hover:bg-slate-50 transition-colors">
                                        <td className="p-4 text-slate-600 sticky left-0 z-10 bg-white">{t.transactionDate}</td>
                                        <td className="p-4 text-center sticky left-[128px] z-10 bg-white">
                                            <span className={`px-2.5 py-1 rounded-full text-xs font-bold inline-flex items-center gap-1.5
                                                ${t.type === 'inbound'
                                                    ? 'bg-emerald-50 text-emerald-700 border border-emerald-100'
                                                    : 'bg-orange-50 text-orange-700 border border-orange-100'
                                                }`}
                                            >
                                                <FontAwesomeIcon icon={t.type === 'inbound' ? faArrowRight : faArrowLeft} />
                                                {t.type === 'inbound' ? '입고' : '출고'}
                                            </span>
                                        </td>
                                        <td className="p-4 font-medium text-slate-800 sticky left-[224px] z-10 bg-white">{t.siteName}</td>
                                        <td className="p-4 font-medium text-slate-800 sticky left-[444px] z-10 bg-white">{t.itemName}</td>
                                        <td className="p-4 text-slate-500">{t.spec}</td>
                                        <td className={`p-4 text-right font-bold ${t.type === 'inbound' ? 'text-emerald-600' : 'text-orange-600'}`}>
                                            {t.quantity.toLocaleString()}
                                        </td>
                                        <td className="p-4 text-slate-500">{t.unit}</td>
                                        <td className="p-4 text-slate-600">
                                            {(t.vehicleNumber != null && String(t.vehicleNumber).trim()) ? (
                                                <span className="bg-slate-100 text-slate-600 px-2 py-1 rounded text-xs font-mono">
                                                    {String(t.vehicleNumber).trim()}
                                                </span>
                                            ) : (
                                                <span className="text-slate-300">-</span>
                                            )}
                                        </td>
                                        <td className="p-4 text-slate-500 text-xs">{t.registeredByName}</td>
                                        <td className="p-4 text-slate-500 whitespace-pre-wrap break-words">{t.notes || '-'}</td>
                                        <td className="p-4 text-center">
                                            <div className="flex justify-center gap-2">
                                                <button
                                                    onClick={() => openEditModal(t)}
                                                    className="w-8 h-8 rounded-full bg-indigo-50 text-indigo-600 hover:bg-indigo-100 flex items-center justify-center transition"
                                                    title="수정"
                                                >
                                                    <FontAwesomeIcon icon={faEdit} />
                                                </button>
                                                <button
                                                    onClick={() => handleDelete(t)}
                                                    className="w-8 h-8 rounded-full bg-red-50 text-red-600 hover:bg-red-100 flex items-center justify-center transition"
                                                    title="삭제"
                                                >
                                                    <FontAwesomeIcon icon={faTrash} />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                <tr>
                                    <td colSpan={11} className="p-24 text-center text-slate-400">
                                        <div className="bg-slate-50 rounded-full w-20 h-20 flex items-center justify-center mx-auto mb-4">
                                            <FontAwesomeIcon icon={faFilter} className="text-3xl text-slate-300" />
                                        </div>
                                        <p className="text-lg font-medium text-slate-600 mb-1">조회된 내역이 없습니다</p>
                                        <p className="text-sm">검색 조건을 변경하여 다시 조회해보세요.</p>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
                <div className="bg-slate-50 px-6 py-4 border-t border-slate-200 text-xs text-slate-400 flex justify-end">
                    Total {visibleTransactions.length} records found
                </div>
            </div>

            {/* Edit Modal */}
            {isEditModalOpen && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden animate-fade-in-up">
                        <div className="bg-indigo-600 p-4 flex justify-between items-center text-white">
                            <h3 className="font-bold text-lg flex items-center gap-2">
                                <FontAwesomeIcon icon={faEdit} />
                                {editingTx?.type === 'inbound' ? '입고 내역 수정' : '출고 내역 수정'}
                            </h3>
                            <button
                                onClick={() => setIsEditModalOpen(false)}
                                className="text-white/80 hover:text-white transition"
                            >
                                <FontAwesomeIcon icon={faTimes} />
                            </button>
                        </div>
                        <div className="p-6">
                            <div className="space-y-4">
                                <div className="bg-slate-50 p-3 rounded-lg border border-slate-200 mb-4">
                                    <p className="text-sm text-slate-500 mb-1">수정 대상 자재</p>
                                    <p className="font-bold text-slate-800">{editingTx?.itemName}</p>
                                    <p className="text-xs text-slate-500">{editingTx?.spec} ({editingTx?.unit})</p>
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-bold text-slate-700 mb-1">일자</label>
                                        <input
                                            type="text"
                                            value={editForm.transactionDate}
                                            onChange={(e) => setEditForm(prev => ({ ...prev, transactionDate: normalizeDateInput(e.target.value) }))}
                                            onBlur={(e) => setEditForm(prev => ({ ...prev, transactionDate: normalizeDateInput(e.target.value) }))}
                                            placeholder="YYYY-MM-DD"
                                            inputMode="numeric"
                                            autoComplete="off"
                                            className="w-full border border-slate-300 rounded-lg px-3 py-2"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-bold text-slate-700 mb-1">수량</label>
                                        <input
                                            type="number"
                                            value={editForm.quantity}
                                            onChange={(e) => setEditForm(prev => ({ ...prev, quantity: Number(e.target.value) }))}
                                            className="w-full border border-slate-300 rounded-lg px-3 py-2"
                                        />
                                    </div>
                                </div>

                                <div>
                                    <label className="block text-sm font-bold text-slate-700 mb-1">현장</label>
                                    <select
                                        value={editForm.siteId}
                                        onChange={(e) => setEditForm(prev => ({ ...prev, siteId: e.target.value }))}
                                        className="w-full border border-slate-300 rounded-lg px-3 py-2"
                                    >
                                        {sites.map(site => (
                                            <option key={site.id} value={site.id}>{site.name}</option>
                                        ))}
                                    </select>
                                </div>

                                <div>
                                    <label className="block text-sm font-bold text-slate-700 mb-1">차량번호</label>
                                    <input
                                        type="text"
                                        value={editForm.vehicleNumber}
                                        onChange={(e) => setEditForm(prev => ({ ...prev, vehicleNumber: e.target.value }))}
                                        placeholder="차량번호 입력"
                                        className="w-full border border-slate-300 rounded-lg px-3 py-2"
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-bold text-slate-700 mb-1">비고</label>
                                    <input
                                        type="text"
                                        value={editForm.notes}
                                        onChange={(e) => setEditForm(prev => ({ ...prev, notes: e.target.value }))}
                                        placeholder="비고 입력"
                                        className="w-full border border-slate-300 rounded-lg px-3 py-2"
                                    />
                                </div>
                            </div>
                        </div>
                        <div className="p-4 bg-slate-50 border-t border-slate-200 flex justify-end gap-2">
                            <button
                                onClick={() => setIsEditModalOpen(false)}
                                className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg transition"
                            >
                                취소
                            </button>
                            <button
                                onClick={handleUpdate}
                                className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition flex items-center gap-2"
                            >
                                <FontAwesomeIcon icon={faSave} />
                                저장하기
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default MaterialTransactionsPage;

import React, { useEffect, useMemo, useState } from 'react';
import { AgGridReact } from 'ag-grid-react';
import { ColDef, ValueFormatterParams } from 'ag-grid-community';
import 'ag-grid-community/styles/ag-grid.css';
import 'ag-grid-community/styles/ag-theme-alpine.css';
import {
    Bar,
    BarChart,
    CartesianGrid,
    Cell,
    Legend,
    ResponsiveContainer,
    Tooltip,
    XAxis,
    YAxis,
    PieChart,
    Pie
} from 'recharts';
import Swal from 'sweetalert2';
import { YearMonthPicker } from '../../components/common/YearMonthPicker';
import { officeService, OfficeTransaction, OfficeTransactionCategory } from '../../services/officeService';
import { toast } from '../../utils/swal';
import { format } from 'date-fns';

const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('ko-KR').format(value);
};

const CATEGORY_LABELS: Record<OfficeTransactionCategory, string> = {
    'TEAM_FEE': '팀 관리비',
    'SALES_GOODS': '물품 판매',
    'SITE_PAYBACK': '현장 바이백',
    'OTHER_INCOME': '기타 수입',
    'SALARY_STAFF': '직원 급여',
    'OFFICE_RENT': '사무실 월세',
    'UTILITIES': '공과금',
    'RENTAL_FEE': '렌트비',
    'GENERAL_EXPENSE': '일반 지출'
};

const INCOME_CATEGORIES: OfficeTransactionCategory[] = ['TEAM_FEE', 'SALES_GOODS', 'SITE_PAYBACK', 'OTHER_INCOME'];
const EXPENSE_CATEGORIES: OfficeTransactionCategory[] = ['SALARY_STAFF', 'OFFICE_RENT', 'UTILITIES', 'RENTAL_FEE', 'GENERAL_EXPENSE'];

export const OfficeManagementPage: React.FC = () => {
    const [yearMonth, setYearMonth] = useState(() => format(new Date(), 'yyyy-MM'));
    const [transactions, setTransactions] = useState<OfficeTransaction[]>([]);
    const [annualTransactions, setAnnualTransactions] = useState<OfficeTransaction[]>([]);
    const [loading, setLoading] = useState(false);

    // Load Data
    useEffect(() => {
        fetchData();
        fetchAnnualData();
    }, [yearMonth]);

    const fetchData = async () => {
        setLoading(true);
        try {
            const data = await officeService.getTransactionsByMonth(yearMonth);
            setTransactions(data);
        } catch (error) {
            console.error(error);
            toast.error('데이터 로드 실패');
        } finally {
            setLoading(false);
        }
    };

    const fetchAnnualData = async () => {
        try {
            // Fetch data for the whole year of the selected month
            const year = yearMonth.split('-')[0];
            const start = `${year}-01-01`;
            const end = `${year}-12-31`;
            const data = await officeService.getTransactionsByRange(start, end);
            setAnnualTransactions(data);
        } catch (error) {
            console.error("Failed to fetch annual data", error);
        }
    };

    // Dashboard Metrics (Current Month)
    const metrics = useMemo(() => {
        const income = transactions.filter(t => t.type === 'income').reduce((sum, t) => sum + t.amount, 0);
        const expense = transactions.filter(t => t.type === 'expense').reduce((sum, t) => sum + t.amount, 0);
        const profit = income - expense;
        return { income, expense, profit };
    }, [transactions]);

    // Chart Data (Annual Trend)
    const trendData = useMemo(() => {
        const monthlyData: Record<string, { month: string, income: number, expense: number, profit: number }> = {};

        // Initialize all 12 months
        const year = yearMonth.split('-')[0];
        for (let i = 1; i <= 12; i++) {
            const m = String(i).padStart(2, '0');
            const key = `${year}-${m}`;
            monthlyData[key] = { month: `${m}월`, income: 0, expense: 0, profit: 0 };
        }

        annualTransactions.forEach(t => {
            const monthKey = t.date.slice(0, 7); // YYYY-MM
            if (monthlyData[monthKey]) {
                if (t.type === 'income') monthlyData[monthKey].income += t.amount;
                else monthlyData[monthKey].expense += t.amount;
            }
        });

        // Calculate profit
        Object.keys(monthlyData).forEach(key => {
            monthlyData[key].profit = monthlyData[key].income - monthlyData[key].expense;
        });

        return Object.values(monthlyData);
    }, [annualTransactions, yearMonth]);

    // Pie Chart Data (Expense Breakdown - Current Month)
    const expenseBreakdown = useMemo(() => {
        const breakdown: Record<string, number> = {};
        transactions.filter(t => t.type === 'expense').forEach(t => {
            const cat = CATEGORY_LABELS[t.category] || t.category;
            breakdown[cat] = (breakdown[cat] || 0) + t.amount;
        });
        return Object.keys(breakdown).map(k => ({ name: k, value: breakdown[k] }));
    }, [transactions]);

    // Add Transaction Handler
    const handleAdd = () => {
        Swal.fire({
            title: '거래 내역 추가',
            html: `
        <div class="space-y-3 text-left">
            <div>
                <label class="block text-sm font-medium text-slate-700">날짜</label>
                <input id="swal-date" type="date" class="w-full border rounded px-3 py-2" value="${yearMonth}-01">
            </div>
            <div>
                <label class="block text-sm font-medium text-slate-700">유형</label>
                <select id="swal-type" class="w-full border rounded px-3 py-2" onchange="window.updateCategories(this.value)">
                    <option value="income">수입</option>
                    <option value="expense">지출</option>
                </select>
            </div>
            <div>
                <label class="block text-sm font-medium text-slate-700">카테고리</label>
                <select id="swal-category" class="w-full border rounded px-3 py-2">
                    <!-- Options populated by JS -->
                </select>
            </div>
            <div>
                <label class="block text-sm font-medium text-slate-700">금액</label>
                <input id="swal-amount" type="number" class="w-full border rounded px-3 py-2" placeholder="0">
            </div>
            <div>
                <label class="block text-sm font-medium text-slate-700">내용 (메모)</label>
                <input id="swal-desc" type="text" class="w-full border rounded px-3 py-2" placeholder="내용 입력">
            </div>
        </div>
      `,
            didOpen: () => {
                // Helper to update categories based on type
                const typeSelect = document.getElementById('swal-type') as HTMLSelectElement;
                const catSelect = document.getElementById('swal-category') as HTMLSelectElement;

                (window as any).updateCategories = (type: string) => {
                    const cats = type === 'income' ? INCOME_CATEGORIES : EXPENSE_CATEGORIES;
                    catSelect.innerHTML = cats.map(c => `<option value="${c}">${CATEGORY_LABELS[c]}</option>`).join('');
                };

                // Initialize
                (window as any).updateCategories(typeSelect.value);
            },
            showCancelButton: true,
            confirmButtonText: '저장',
            cancelButtonText: '취소',
            preConfirm: () => {
                const date = (document.getElementById('swal-date') as HTMLInputElement).value;
                const type = (document.getElementById('swal-type') as HTMLSelectElement).value as 'income' | 'expense';
                const category = (document.getElementById('swal-category') as HTMLSelectElement).value as OfficeTransactionCategory;
                const amount = Number((document.getElementById('swal-amount') as HTMLInputElement).value);
                const description = (document.getElementById('swal-desc') as HTMLInputElement).value;

                if (!date || !category || !amount) {
                    Swal.showValidationMessage('필수 항목을 모두 입력해주세요.');
                    return false;
                }
                return { date, type, category, amount, description };
            }
        }).then(async (result) => {
            if (result.isConfirmed && result.value) {
                try {
                    const id = `manual_${Date.now()}`;
                    const newTransaction: OfficeTransaction = {
                        id,
                        createdAt: new Date().toISOString(),
                        updatedAt: new Date().toISOString(),
                        ...result.value
                    };
                    await officeService.setTransaction(newTransaction);
                    toast.success('저장되었습니다.');
                    fetchData();
                    fetchAnnualData(); // Update charts too
                } catch (e) {
                    console.error(e);
                    toast.error('저장 실패');
                }
            }
        });
    };

    // Delete Handler
    const handleDelete = (id: string) => {
        Swal.fire({
            title: '삭제하시겠습니까?',
            text: '삭제된 데이터는 복구할 수 없습니다.',
            icon: 'warning',
            showCancelButton: true,
            confirmButtonText: '삭제',
            confirmButtonColor: '#ef4444'
        }).then(async (res) => {
            if (res.isConfirmed) {
                try {
                    await officeService.deleteTransaction(id);
                    toast.success('삭제 완료');
                    fetchData();
                    fetchAnnualData();
                } catch (e) {
                    console.error(e);
                    toast.error('삭제 실패');
                }
            }
        });
    };

    // AG Grid Column Defs
    const colDefs: ColDef<OfficeTransaction>[] = [
        { field: 'date', headerName: '날짜', width: 120, sortable: true },
        {
            field: 'type',
            headerName: '구분',
            width: 80,
            cellRenderer: (params: any) => {
                const isIncome = params.value === 'income';
                return (
                    <span className={`px-2 py-1 rounded text-xs font-bold ${isIncome ? 'bg-blue-100 text-blue-700' : 'bg-red-100 text-red-700'}`}>
                        {isIncome ? '수입' : '지출'}
                    </span>
                );
            }
        },
        {
            field: 'category',
            headerName: '카테고리',
            width: 150,
            valueFormatter: (params) => CATEGORY_LABELS[params.value as OfficeTransactionCategory] || params.value
        },
        { field: 'description', headerName: '내용', flex: 1 },
        {
            field: 'amount',
            headerName: '금액',
            width: 120,
            type: 'rightAligned',
            valueFormatter: (params: ValueFormatterParams) => formatCurrency(params.value),
            cellStyle: (params) => ({
                color: params.data?.type === 'income' ? '#2563eb' : '#dc2626',
                fontWeight: '600'
            })
        },
        {
            headerName: '관리',
            width: 80,
            cellRenderer: (params: any) => (
                <button
                    onClick={() => handleDelete(params.data.id)}
                    className="text-red-500 hover:text-red-700 text-xs px-2 py-1 border border-red-200 rounded hover:bg-red-50"
                >
                    삭제
                </button>
            )
        }
    ];

    const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8'];

    return (
        <div className="w-full p-6 space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800">사무실 관리</h1>
                    <p className="text-slate-500 text-sm mt-1">사무실 수입/지출 및 자금 흐름을 관리합니다.</p>
                </div>
                <div>
                    <YearMonthPicker value={yearMonth} onChange={setYearMonth} />
                </div>
            </div>

            {/* Metrics Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                    <div className="text-sm text-slate-500 font-medium">총 수입 (Current Month)</div>
                    <div className="text-3xl font-extrabold text-blue-600 mt-2">{formatCurrency(metrics.income)}원</div>
                </div>
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                    <div className="text-sm text-slate-500 font-medium">총 지출 (Current Month)</div>
                    <div className="text-3xl font-extrabold text-red-600 mt-2">{formatCurrency(metrics.expense)}원</div>
                </div>
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                    <div className="text-sm text-slate-500 font-medium">순이익 (Net Profit)</div>
                    <div className={`text-3xl font-extrabold mt-2 ${metrics.profit >= 0 ? 'text-emerald-600' : 'text-amber-600'}`}>
                        {formatCurrency(metrics.profit)}원
                    </div>
                </div>
            </div>

            {/* Charts Section */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                    <h3 className="text-lg font-bold text-slate-800 mb-4">연간 자금 흐름 ({yearMonth.split('-')[0]}년)</h3>
                    <div className="h-64">
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={trendData}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                                <XAxis dataKey="month" tick={{ fontSize: 12 }} />
                                <YAxis tickFormatter={(val) => `${val / 10000}만`} tick={{ fontSize: 12 }} />
                                <Tooltip formatter={(val: any) => formatCurrency(Number(val || 0))} />
                                <Legend />
                                <Bar dataKey="income" name="수입" fill="#3b82f6" radius={[4, 4, 0, 0]} />
                                <Bar dataKey="expense" name="지출" fill="#ef4444" radius={[4, 4, 0, 0]} />
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                    <h3 className="text-lg font-bold text-slate-800 mb-4">지출 내역 ({yearMonth})</h3>
                    <div className="h-64 flex items-center justify-center">
                        {expenseBreakdown.length > 0 ? (
                            <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                    <Pie
                                        data={expenseBreakdown}
                                        cx="50%"
                                        cy="50%"
                                        innerRadius={60}
                                        outerRadius={80}
                                        fill="#8884d8"
                                        paddingAngle={5}
                                        dataKey="value"
                                    >
                                        {expenseBreakdown.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                        ))}
                                    </Pie>
                                    <Tooltip formatter={(val: any) => formatCurrency(Number(val || 0))} />
                                    <Legend layout="horizontal" verticalAlign="bottom" align="center" />
                                </PieChart>
                            </ResponsiveContainer>
                        ) : (
                            <div className="text-slate-400 text-sm">지출 내역이 없습니다.</div>
                        )}
                    </div>
                </div>
            </div>

            {/* Ledger Grid */}
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                <div className="flex items-center justify-between mb-4">
                    <h3 className="text-lg font-bold text-slate-800">거래 명세서 (Transaction Ledger)</h3>
                    <button
                        onClick={handleAdd}
                        className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg text-sm font-semibold transition-colors"
                    >
                        + 거래 내역 추가
                    </button>
                </div>
                <div className="ag-theme-alpine w-full h-[500px]">
                    <AgGridReact
                        rowData={transactions}
                        columnDefs={colDefs}
                        defaultColDef={{ resizable: true }}
                        animateRows={true}
                        rowSelection="multiple"
                    />
                </div>
            </div>
        </div>
    );
};

