const isServiceTeamNode = (team: Team | null): boolean => {
  if (!team) return false;
  const target = normalizeText(`${team.type || ''} ${team.name || ''} ${team.defaultSalaryModel || ''} ${team.companyName || ''}`);
  return (
    target.includes('용역') ||
