            <div className="text-xs font-bold text-[#4A452A]">회사</div>
            <div className="mt-2 text-base font-black text-[#1E1C11]">
              {statementTeamOption?.team?.companyName || filteredEntries.find(e => e.teamKey === statementTeamKey)?.companyName || '-'}
