                    <td className="border border-[#e3dcc4] px-3 py-2">{row.salaryType || '-'}</td>
                    <td className="border border-[#e3dcc4] px-3 py-2">{row.address || '-'}</td>
                    {row.days.map((value, dayIndex) => {
                      // 누적 1~5회차 작업일 파란색 표시
