              {selectedDate}
            </div>
          </div>

          <div className="space-y-3 p-4 text-sm">
            <div className="rounded-md border border-[#d5ccb0] bg-white px-3 py-3">
              <div className="text-xs font-bold text-slate-500">선택일 공수</div>
              <div className="mt-1 text-lg font-black text-[#4A452A]">
                {formatNumber(
                  selectedDateEntries.reduce((sum, entry) => {
                    const draftValue = manDayDrafts[entry.key];
                    const nextManDay = draftValue === undefined ? entry.manDay : toNumber(draftValue);
                    return sum + nextManDay;
                  }, 0)
                )}
              </div>
            </div>
            <div className="rounded-md border border-[#d5ccb0] bg-white px-3 py-3">
              <div className="text-xs font-bold text-slate-500">선택일 실지급금</div>
              <div className="mt-1 text-lg font-black text-[#4A452A]">
                {formatCurrency(
                  selectedDateEntries.reduce(
                    (sum, entry) => {
                      const draftValue = manDayDrafts[entry.key];
                      const nextManDay = draftValue === undefined ? entry.manDay : toNumber(draftValue);
                      return sum + nextManDay * getActualUnitPrice(entry.claimUnitPrice);
                    },
                    0
                  )
                )}
              </div>
            </div>
            <div className="rounded-md border border-[#d5ccb0] bg-white px-3 py-3">
              <div className="text-xs font-bold text-slate-500">선택일 청구금 합계</div>
              <div className="mt-1 text-lg font-black text-[#4A452A]">
                {formatCurrency(
                  selectedDateEntries.reduce((sum, entry) => {
                    const draftValue = manDayDrafts[entry.key];
                    const nextManDay = draftValue === undefined ? entry.manDay : toNumber(draftValue);
                    return sum + nextManDay * entry.reportUnitPrice;
                  }, 0)
                )}
              </div>
            </div>
          </div>
        </div>

        <div className="flex-1">
          <div className="overflow-x-auto">
            <table className="min-w-[1200px] border-collapse text-sm">
              <thead>
                <tr style={{ backgroundColor: COLORS.blackBrown }} className="text-white">
                  {['팀', '이름', '현장', '공수'].map((header) => (
                    <th key={header} className="border border-[#d5ccb0] px-3 py-2 text-center font-bold">{header}</th>
                  ))}
                  <th className="border border-[#d5ccb0] px-3 py-2 text-center font-bold">실지급금</th>
                  <th className="border border-[#d5ccb0] px-3 py-2 text-center font-bold" style={{ backgroundColor: COLORS.aqua, color: COLORS.blackBrown }}>청구금액</th>
                  {['은행명', '예금주명'].map((header) => (
                    <th key={header} className="border border-[#d5ccb0] px-3 py-2 text-center font-bold">{header}</th>
                  ))}
                  <th className="border border-[#d5ccb0] px-3 py-2 text-center font-bold" style={{ backgroundColor: COLORS.red }}>
                    계좌번호
                  </th>
                  <th className="border border-[#d5ccb0] px-3 py-2 text-center font-bold">비고</th>
                </tr>
              </thead>
              <tbody>
                {selectedDateEntries.length === 0 ? (
                  <tr>
                    <td colSpan={10} className="px-4 py-10 text-center text-sm text-slate-500">
                      선택한 일자에 조회 결과가 없습니다.
                    </td>
                  </tr>
                ) : (
                  selectedDateEntries.map((entry) => {
                    const draftValue = manDayDrafts[entry.key];
                    const nextManDay = draftValue === undefined ? entry.manDay : toNumber(draftValue);
                    const actualAmount = nextManDay * getActualUnitPrice(entry.claimUnitPrice);
                    const claimAmount = nextManDay * entry.reportUnitPrice;
                    return (
                      <tr key={entry.key} className="odd:bg-white even:bg-[#faf8ef]">
                        <td className="border border-[#e3dcc4] px-3 py-2">{entry.teamName}</td>
                        <td className="border border-[#e3dcc4] px-3 py-2 font-semibold">{entry.workerName}</td>
                        <td className="border border-[#e3dcc4] px-3 py-2">{entry.siteName || '-'}</td>
                        <td className="border border-[#e3dcc4] px-2 py-1.5 text-center">
                          <input
                            type="number"
                            min="0"
                            step="0.5"
                            value={draftValue ?? String(entry.manDay)}
                            onChange={(event) => handleManDayDraftChange(entry.key, event.target.value)}
                            className="w-20 rounded border border-[#d7cfb5] px-2 py-1 text-right text-xs outline-none focus:border-[#948A54]"
                          />
                        </td>
                        <td className="border border-[#e3dcc4] px-3 py-2 text-right font-black text-[#4A452A]">
                          {formatCurrency(actualAmount)}
                        </td>
                        <td className="border border-[#e3dcc4] px-3 py-2 text-right font-semibold text-sky-700">
                          {formatCurrency(claimAmount)}
                        </td>
                        <td className="border border-[#e3dcc4] px-3 py-2">{entry.bankName || '-'}</td>
                        <td className="border border-[#e3dcc4] px-3 py-2">{entry.accountHolder || '-'}</td>
                        <td className="border border-[#e3dcc4] px-3 py-2 font-medium text-[#7a2c2c]">
                          {entry.accountNumber || '-'}
                        </td>
                        <td className="border border-[#e3dcc4] px-3 py-2">{entry.note || '-'}</td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );

  const renderDailyWageTab = () => (
    <div className="overflow-hidden rounded-xl border border-[#d5ccb0] bg-white shadow-sm">
      <div className="border-b border-[#d5ccb0] bg-[#faf8ef] px-4 py-3">
        <div className="text-sm font-black text-[#4A452A]">일급제 인원 현황</div>
        <div className="text-xs text-slate-500">
          {getMonthTitle(month)} 기준 일급제 인원별 총공수, 실지급금, 청구금 현황
        </div>
      </div>
      <div className="grid gap-px bg-[#d5ccb0] sm:grid-cols-4">
        {[
          ['인원수', `${workerMasterRows.length}명`],
          ['총공수', formatNumber(workerMasterRows.reduce((s, r) => s + r.totalManDay, 0))],
          ['총 실지급금', formatCurrency(workerMasterRows.reduce((s, r) => s + r.actualTotal, 0))],
          ['총 청구금', formatCurrency(workerMasterRows.reduce((s, r) => s + r.claimTotal, 0))],
        ].map(([label, value]) => (
          <div key={label} className="bg-[#faf8ef] px-4 py-3">
            <div className="text-xs font-bold text-slate-500">{label}</div>
            <div className="mt-1 text-lg font-black text-[#4A452A]">{value}</div>
          </div>
        ))}
      </div>
      <div className="overflow-x-auto">
        <table className="min-w-[1100px] border-collapse text-sm">
          <thead>
            <tr style={{ backgroundColor: COLORS.olive }} className="text-white">
              {['번호', '팀', '이름', '총공수', '실지급금', '청구금', '일당', '청구단가', '인력소개비', '상태'].map((header) => (
                <th key={header} className="border border-[#d5ccb0] px-3 py-2 text-center font-bold">
                  {header}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {workerMasterRows.length === 0 ? (
              <tr>
                <td colSpan={10} className="px-4 py-10 text-center text-sm text-slate-500">
                  표시할 일급제 작업자가 없습니다.
                </td>
              </tr>
            ) : (
              workerMasterRows.map((row, index) => (
                <tr key={row.workerId} className="odd:bg-white even:bg-[#faf8ef]">
                  <td className="border border-[#e3dcc4] px-3 py-2 text-center">{index + 1}</td>
                  <td className="border border-[#e3dcc4] px-3 py-2 align-middle">
                    <span>{row.teamName}</span>
                    <span className="ml-2 text-xs text-slate-500 align-middle">[{row.salaryType}]</span>
                  </td>
                  <td className="border border-[#e3dcc4] px-3 py-2 font-semibold">{row.workerName}</td>
                  <td className="border border-[#e3dcc4] px-3 py-2 text-center font-bold">{formatNumber(row.totalManDay)}</td>
                  <td className="border border-[#e3dcc4] px-3 py-2 text-right font-bold text-[#4A452A]">
                    {formatCurrency(row.actualTotal)}
                  </td>
                  <td className="border border-[#e3dcc4] px-3 py-2 text-right font-bold text-sky-700">
                    {formatCurrency(row.claimTotal)}
                  </td>
                  <td className="border border-[#e3dcc4] px-3 py-2 text-right">{formatCurrency(row.actualUnitPrice)}</td>
                  <td className="border border-[#e3dcc4] px-3 py-2 text-right">{formatCurrency(row.claimUnitPrice)}</td>
                  <td className="border border-[#e3dcc4] px-3 py-2 text-right">
                    {row.recruiterFee ? formatCurrency(row.recruiterFee) : '-'}
                  </td>
                  <td className="border border-[#e3dcc4] px-3 py-2 text-center">
                    {row.status === '신규' ? (
                      <span className="rounded bg-rose-100 px-2 py-1 text-xs font-bold text-rose-700">신규</span>
                    ) : (
                      row.status || '-'
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );

  const renderServiceTeamTab = () => {
    const groupedRows = new Map<string, {
      teamKey: string;
      teamName: string;
      workerId: string;
      workerName: string;
      idNumber: string;
      entriesByDay: Record<number, WorkbookEntry>;
      totalManDay: number;
      totalRecruiterFee: number;
    }>();

    filteredEntries.forEach((entry) => {
      const rowKey = `${entry.teamKey}__${entry.workerId || normalizeText(entry.workerName)}`;
      if (!groupedRows.has(rowKey)) {
        groupedRows.set(rowKey, {
          teamKey: entry.teamKey,
          teamName: entry.teamName,
          workerId: entry.workerId,
          workerName: entry.workerName,
          idNumber: entry.idNumber,
          entriesByDay: {},
          totalManDay: 0,
          totalRecruiterFee: 0,
        });
      }

      const workerRow = groupedRows.get(rowKey)!;
      workerRow.entriesByDay[entry.day] = entry;
      workerRow.totalManDay += entry.manDay;
      workerRow.totalRecruiterFee += entry.recruiterFee;
    });

    const serviceRows = Array.from(groupedRows.values()).sort((left, right) => {
      const teamCompare = left.teamName.localeCompare(right.teamName, 'ko');
      if (teamCompare !== 0) return teamCompare;
      return left.workerName.localeCompare(right.workerName, 'ko');
    });

    const serviceStickyHeaderStyle = {
      backgroundColor: COLORS.blue,
      height: '48px',
      minHeight: '48px',
    } as const;

    const serviceStickyCellStyle = {
      height: '48px',
      minHeight: '48px',
    } as const;

    return (
      <div className="overflow-hidden rounded-xl border border-[#d5ccb0] bg-white shadow-sm">
        <div className="border-b border-[#d5ccb0] bg-blue-50 px-4 py-3">
          <div className="text-sm font-black text-blue-900">용역팀 정산 관리 (인력소개비 자동계산)</div>
          <div className="text-xs text-blue-700">
            작업자별 생애 누적 1~5회차 작업일에 일 60,000원의 소개비를 자동 부과하며, 해당 일자는 파란색으로 표시됩니다.
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="min-w-[1800px] border-collapse text-sm">
            <thead>
              <tr style={{ backgroundColor: COLORS.blue }} className="text-white">
                <th
                  className="h-12 w-[120px] min-w-[120px] max-w-[120px] border border-white/20 px-3 py-2 font-bold sticky left-0 z-10 align-middle whitespace-nowrap"
                  style={serviceStickyHeaderStyle}
                >
                  팀명
                </th>
                <th
                  className="h-12 w-[120px] min-w-[120px] max-w-[120px] border border-white/20 px-3 py-2 font-bold sticky left-[120px] z-10 align-middle whitespace-nowrap"
                  style={serviceStickyHeaderStyle}
                >
                  이름
                </th>
                {statementDayNumbers.map((day) => (
                  <th key={day} className="h-12 border border-white/20 px-2 py-2 font-bold align-middle">{day}</th>
                ))}
                <th className="h-12 border border-white/20 px-3 py-2 font-bold text-center align-middle">총공수</th>
                <th className="h-12 border border-white/20 px-3 py-2 font-bold text-center align-middle" style={{ backgroundColor: COLORS.orange }}>인력소개비</th>
                <th className="h-12 border border-white/20 px-3 py-2 font-bold text-center align-middle">비고</th>
              </tr>
            </thead>
            <tbody>
              {serviceRows.length === 0 ? (
                <tr>
                  <td colSpan={statementDayNumbers.length + 5} className="px-4 py-10 text-center text-sm text-slate-500">
                    용역팀 데이터가 없습니다. (팀 유형을 '용역'으로 설정해주세요)
                  </td>
                </tr>
              ) : (
                serviceRows.map((row) => (
                  <tr key={`${row.teamKey}__${row.workerId || normalizeText(row.workerName)}`} className="h-12 hover:bg-blue-50/30">
                    <td
                      className="h-12 w-[120px] min-w-[120px] max-w-[120px] border border-[#e3dcc4] px-3 py-2 font-bold text-[#4A452A] bg-[#faf8ef] sticky left-0 z-10 align-middle whitespace-nowrap"
                      style={serviceStickyCellStyle}
                    >
                      {row.teamName}
                    </td>
                    <td
                      className="h-12 w-[120px] min-w-[120px] max-w-[120px] border border-[#e3dcc4] px-3 py-2 font-semibold bg-white sticky left-[120px] z-10 align-middle whitespace-nowrap"
                      style={serviceStickyCellStyle}
                    >
                      {row.workerName}
                    </td>
                    {statementDayNumbers.map((day) => {
                      const entry = row.entriesByDay[day];
                      const isIntroFeeDay = !!entry && entry.recruiterFee > 0;
                      return (
                        <td
                          key={day}
                          className={`h-12 border border-[#e3dcc4] px-2 py-2 text-center align-middle ${isIntroFeeDay ? 'bg-blue-100 font-bold text-blue-700' : ''}`}
                          title={isIntroFeeDay ? `누적 ${entry?.cumulativeCount}일차` : ''}
                        >
                          {entry ? formatNumber(entry.manDay) : '-'}
                        </td>
                      );
                    })}
                    <td className="h-12 border border-[#e3dcc4] px-3 py-2 text-right font-black align-middle">{formatNumber(row.totalManDay)}</td>
                    <td className="h-12 border border-[#e3dcc4] px-3 py-2 text-right font-black text-orange-600 bg-orange-50 align-middle">
                      {formatCurrency(row.totalRecruiterFee)}
                    </td>
                    <td className="h-12 border border-[#e3dcc4] px-3 py-2 text-xs text-slate-400 italic align-middle">
                      {row.totalRecruiterFee > 0 ? `소개비 ${Math.round(row.totalRecruiterFee / 60000)}일분 포함` : '-'}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  const renderActiveTab = () => {
    switch (activeTab) {
      case 'workers':
        return renderWorkersTab();
      case 'team-summary':
        return renderTeamSummaryTab();
      case 'statement':
        return renderStatementTab();
      case 'day-lookup':
        return renderDayLookupTab();
      case 'daily-wage':
        return renderDailyWageTab();
      case 'service-team':
        return renderServiceTeamTab();
      default:
        return null;
    }
  };

  const summaryPanelClassName = isGoyunjungMode
    ? 'rounded-xl border border-[#d9cfb2] bg-white/82 p-6 shadow-sm backdrop-blur-sm'
    : 'rounded-xl border border-[#d9cfb2] bg-white p-6 shadow-sm';

  const filterPanelClassName = isGoyunjungMode
    ? 'rounded-xl border border-[#d9cfb2] bg-white/82 p-5 shadow-sm backdrop-blur-sm'
    : 'rounded-xl border border-[#d9cfb2] bg-white p-5 shadow-sm';

  const tabPanelClassName = isGoyunjungMode
    ? 'space-y-4 rounded-xl border border-[#d9cfb2] bg-[#fbf8ee]/88 p-5 shadow-sm backdrop-blur-sm'
    : 'space-y-4 rounded-xl border border-[#d9cfb2] bg-[#fbf8ee] p-5 shadow-sm';

  return (
    <div className="relative min-h-screen overflow-hidden">
      <style>
        {`
          @keyframes goyunjungBurstCard {
            0% { opacity: 0; transform: translate(-50%, 28px) scale(0.82); }
            12% { opacity: 1; transform: translate(-50%, 0) scale(1); }
            78% { opacity: 1; transform: translate(-50%, -6px) scale(1.02); }
            100% { opacity: 0; transform: translate(-50%, -34px) scale(0.9); }
          }

          @keyframes goyunjungMessageFloat {
            0% { opacity: 0; transform: translateY(18px) scale(0.92); }
            18% { opacity: 1; transform: translateY(0) scale(1); }
            76% { opacity: 1; transform: translateY(-10px) scale(1.02); }
            100% { opacity: 0; transform: translateY(-26px) scale(0.95); }
          }

          @keyframes goyunjungHeartBurst {
            0% { opacity: 0; transform: translate3d(0, 30px, 0) scale(0.7) rotate(0deg); }
            15% { opacity: 1; }
            100% { opacity: 0; transform: translate3d(var(--heart-drift), -220px, 0) scale(1.3) rotate(22deg); }
          }
        `}
      </style>
      {isGoyunjungMode && goyunjungBackgroundUrl && (
        <>
          <div
            className="pointer-events-none absolute inset-0 bg-cover bg-center bg-fixed opacity-[0.78] saturate-[1.12]"
            style={{ backgroundImage: `url("${goyunjungBackgroundUrl}")` }}
          />
          <div className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_center,_rgba(255,255,255,0.10),_rgba(255,255,255,0.28)_55%,_rgba(255,255,255,0.42))]" />
        </>
      )}

      {isGoyunjungMode && goyunjungBursts.length > 0 && (
        <div className="pointer-events-none absolute inset-0 z-30 overflow-hidden">
          {goyunjungBursts.map((burst) => (
            <div key={burst.id} className="absolute inset-0">
              <div
                className="absolute w-[240px] max-w-[34vw] min-w-[180px] overflow-hidden rounded-[28px] border border-white/70 bg-white/18 shadow-[0_25px_80px_rgba(190,24,93,0.33)] backdrop-blur-md xl:w-[280px]"
                style={{
                  left: burst.position.left,
                  top: burst.position.top,
                  transform:
                    burst.position.align === 'left'
                      ? 'translate(0, 0)'
                      : burst.position.align === 'right'
                        ? 'translate(0, 0)'
                        : 'translate(-50%, 0)',
                  animation: 'goyunjungBurstCard 4.2s ease forwards',
                }}
              >
                <div className="bg-gradient-to-r from-rose-500/80 via-pink-500/75 to-fuchsia-500/80 px-4 py-2 text-center text-sm font-black tracking-[0.18em] text-white">
                  GOYUNJUNG MODE
                </div>
                <div className="bg-white/82 p-3">
                  <img
                    src={burst.imageUrl}
                    alt="고윤정"
                    className="h-[340px] w-full rounded-[20px] object-cover object-center shadow-lg"
                  />
                </div>
              </div>

              <div
                className={`absolute flex flex-col gap-3 px-2 ${
                  burst.position.align === 'left'
                    ? 'items-start'
                    : burst.position.align === 'right'
                      ? 'items-end'
                      : 'items-center'
                }`}
                style={{
                  left:
                    burst.position.align === 'left'
                      ? burst.position.left
                      : burst.position.align === 'right'
                        ? 'auto'
                        : burst.position.left,
                  right: burst.position.align === 'right' ? burst.position.left : 'auto',
                  top: `calc(${burst.position.top} + 360px)`,
                  width: burst.position.align === 'center' ? '70vw' : '260px',
                  maxWidth: '70vw',
                  transform: burst.position.align === 'center' ? 'translateX(-50%)' : 'none',
                }}
              >
                {burst.messages.map((message, index) => (
                  <div
                    key={`${burst.id}-message-${index}`}
                    className="rounded-full border border-white/70 bg-white/80 px-5 py-2 text-center text-sm font-black text-rose-700 shadow-[0_14px_40px_rgba(225,29,72,0.22)] backdrop-blur-md"
                    style={{
                      animation: 'goyunjungMessageFloat 3.2s ease forwards',
                      animationDelay: `${0.18 * index}s`,
                    }}
                  >
                    {message}
                  </div>
                ))}
              </div>

              {burst.hearts.map((heart) => (
                <div
                  key={heart.id}
                  className="absolute top-[56%] text-rose-500 drop-shadow-[0_6px_14px_rgba(244,63,94,0.35)]"
                  style={{
                    left: `${heart.left}%`,
                    fontSize: `${heart.size}px`,
                    animation: `goyunjungHeartBurst ${heart.duration}s ease-out forwards`,
                    animationDelay: `${heart.delay}s`,
                    ['--heart-drift' as string]: `${heart.drift}px`,
                  }}
                >
                  ♥
                </div>
              ))}
            </div>
          ))}
        </div>
      )}

      <div className="relative space-y-6">
        <div className={summaryPanelClassName}>
          <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
            <div>
              <div className="text-2xl font-black text-[#4A452A]">대납출력부</div>
              <div className="mt-2 text-sm leading-6 text-slate-600">
                일급제 인원 기준으로 일자별 출역, 청구, 계좌 정보를 한 화면에서 관리합니다.
              </div>
            </div>

            <div className="mt-3 flex flex-wrap items-center gap-2">
              <span className="rounded-full bg-[#4A452A] px-3 py-1 text-xs font-bold text-white">
                급여구분
              </span>
              <span className="rounded-full bg-sky-100 px-3 py-1 text-xs font-bold text-sky-700">
                일급제
              </span>
              <span className="text-xs font-medium text-slate-500">
                일급제 인원만 지급 대상으로 집계합니다.
              </span>
              <button
                type="button"
                onClick={() => setIsGoyunjungMode((prev) => !prev)}
                className={`inline-flex items-center gap-2 rounded-full border px-3 py-1.5 text-xs font-bold transition ${
                  isGoyunjungMode
                    ? 'border-rose-200 bg-rose-50 text-rose-700'
                    : 'border-[#d7cfb5] bg-white text-[#4A452A] hover:border-[#948A54]'
                }`}
              >
                <span>고윤정모드</span>
                <span
                  className={`h-2.5 w-2.5 rounded-full ${
                    isGoyunjungMode ? 'bg-rose-500' : 'bg-slate-300'
                  }`}
                />
              </button>
              {isGoyunjungMode && (
                <button
                  type="button"
                  onClick={() => void applyRandomGoyunjungBackground()}
                  className="inline-flex items-center rounded-full border border-rose-200 bg-white/85 px-3 py-1.5 text-xs font-bold text-rose-700 transition hover:bg-rose-50"
                >
                  배경 변경
                </button>
              )}
            </div>

            <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
              {[
                {
                  label: '조회월',
                  value: getMonthTitle(month),
                  icon: faCalendarAlt,
                  bg: COLORS.paleBlue,
                },
                {
                  label: '작업자',
                  value: `${workbookStats.workerCount}명`,
                  icon: faUsers,
                  bg: COLORS.paleYellow,
                },
                {
                  label: '팀수',
                  value: `${workbookStats.teamCount}팀`,
                  icon: faBuilding,
                  bg: '#f5ebc8',
                },
                {
                  label: '총공수',
                  value: formatNumber(workbookStats.totalManDay),
                  icon: faTable,
                  bg: '#f4e0c2',
                },
              ].map((card) => (
                <div
                  key={card.label}
                  className="flex min-w-[140px] items-center gap-3 rounded-lg border border-[#d5ccb0] px-4 py-3"
                  style={{ backgroundColor: card.bg }}
                >
                  <div className="flex h-10 w-10 items-center justify-center rounded-full bg-white/70 text-[#4A452A]">
                    <FontAwesomeIcon icon={card.icon} />
                  </div>
                  <div>
                    <div className="text-xs font-bold text-slate-500">{card.label}</div>
                    <div className="text-lg font-black text-[#4A452A]">{card.value}</div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className={filterPanelClassName}>
          <div className="grid gap-4 xl:grid-cols-[180px_180px_220px_220px_1fr_auto]">
            <label className="space-y-2 text-sm">
              <div className="font-bold text-[#4A452A]">조회월</div>
              <input
                type="month"
                value={month}
                onChange={(event) => setMonth(event.target.value)}
                className="w-full rounded-md border border-[#d7cfb5] px-3 py-2 outline-none focus:border-[#948A54]"
              />
            </label>

            <label className="space-y-2 text-sm">
              <div className="font-bold text-[#4A452A]">일자</div>
              <input
                type="date"
                value={selectedDate}
                min={monthToPeriod(month).startDate}
                max={monthToPeriod(month).endDate}
                onChange={(event) => setSelectedDate(event.target.value)}
                className="w-full rounded-md border border-[#d7cfb5] px-3 py-2 outline-none focus:border-[#948A54]"
              />
            </label>

            <label className="space-y-2 text-sm">
              <div className="font-bold text-[#4A452A]">팀 필터</div>
              <select
                value={selectedTeamKey}
                onChange={(event) => setSelectedTeamKey(event.target.value)}
                className="w-full rounded-md border border-[#d7cfb5] px-3 py-2 outline-none focus:border-[#948A54]"
              >
                <option value="ALL">전체 팀</option>
                {teamOptions.map((option) => (
                  <option key={option.key} value={option.key}>
                    {option.name}
                  </option>
                ))}
              </select>
            </label>

            <label className="space-y-2 text-sm">
              <div className="font-bold text-[#4A452A]">청구서 팀</div>
              <select
                value={statementTeamKey}
                onChange={(event) => setStatementTeamKey(event.target.value)}
                className="w-full rounded-md border border-[#d7cfb5] px-3 py-2 outline-none focus:border-[#948A54]"
              >
                {teamOptions.length === 0 ? (
                  <option value="">팀 없음</option>
                ) : (
                  teamOptions.map((option) => (
                    <option key={option.key} value={option.key}>
                      {option.name}
                    </option>
                  ))
                )}
              </select>
            </label>

            <div className="flex items-end">
              <div className="rounded-lg border border-[#d7cfb5] px-4 py-3 text-sm text-slate-600">
                실지급금은 일당 기준, 노무청구금은 일보 작업자금액(작업자 단가) 기준으로 계산합니다.
              </div>
            </div>

            <div className="flex items-end">
              <div className="rounded-lg border border-sky-200 bg-sky-50 px-4 py-3 text-sm text-sky-800">
                <div className="font-bold">급여구분</div>
                <div className="mt-1">일급제만 지급 대상으로 집계합니다.</div>
              </div>
            </div>

            <div className="flex items-end justify-end">
              <button
                type="button"
                onClick={() => void loadData()}
                disabled={loading}
                className="inline-flex items-center gap-2 rounded-md bg-[#4A452A] px-4 py-2 text-sm font-bold text-white transition hover:bg-[#3a361f] disabled:cursor-not-allowed disabled:bg-slate-300"
              >
                <FontAwesomeIcon icon={loading ? faSpinner : faSearch} spin={loading} />
                <span>새로고침</span>
              </button>
            </div>
          </div>
        </div>

        <div className={tabPanelClassName}>
          {renderSheetTabs()}
          {loading ? (
            <div className="flex min-h-[260px] items-center justify-center rounded-xl border border-dashed border-[#d5ccb0] bg-white">
              <div className="flex items-center gap-3 text-sm font-bold text-[#4A452A]">
                <FontAwesomeIcon icon={faSpinner} spin />
                <span>대납출력부 데이터를 불러오는 중입니다.</span>
              </div>
            </div>
          ) : (
            renderActiveTab()
          )}
        </div>
      </div>
    </div>
  );
};

export default DailyAdvanceWorkbookPage;

import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCalendarDay, faExclamationTriangle, faEye, faEyeSlash, faPrint, faSearch, faSpinner, faThumbtack } from '@fortawesome/free-solid-svg-icons';
import { dailyReportService, DailyReport, DailyReportWorker } from '../../services/dailyReportService';
import { companyService } from '../../services/companyService';
import { manpowerService, Worker } from '../../services/manpowerService';
import { teamService, Team } from '../../services/teamService';
import { BANK_CODES } from './team-payment/types';
import { toast } from '../../utils/swal';
import { useNavigate } from 'react-router-dom';

type TeamWithId = Team & { id: string };

type DraftRow = {
    rowKey: string;
    date: string;
    workerId: string;
    workerName: string;
    teamId: string;
    teamName: string;
    manDay: number;
    originalUnitPrice: number;
    actualUnitPrice: number;
    billingUnitPrice: number;
    reportUnitPrice: number;
    bankName: string;
    bankCode: string;
    accountNumber: string;
    accountHolder: string;
    isValid: boolean;
    errors: {
        bankName?: boolean;
        bankCode?: boolean;
        accountNumber?: boolean;
        accountHolder?: boolean;
    };
};

type DraftRowTotals = {
    originalTotal: number;
    actualTotal: number;
    billingTotal: number;
    reportTotal: number;
};

type ViewMode = 'daily' | 'monthly';

type DeductionPreset = {
    actual: number;
    billing: number;
    report: number;
};

type DailyWageDraftPageProps = {
    embedded?: boolean;
    dateOverride?: string;
    monthOverride?: string;
    viewModeOverride?: ViewMode;
    deductionStorageKey?: string;
};

const DEFAULT_DEDUCTION_STORAGE_KEY = 'daily-wage-draft:deductions';

const DailyWageDraftPage: React.FC<DailyWageDraftPageProps> = ({
    embedded = false,
    dateOverride,
    monthOverride,
    viewModeOverride,
    deductionStorageKey,
}) => {
    const navigate = useNavigate();

    const today = new Date().toISOString().split('T')[0];
    const currentMonth = today.slice(0, 7);

    const [selectedDate, setSelectedDate] = useState<string>(dateOverride || today);
    const [selectedMonth, setSelectedMonth] = useState<string>(monthOverride || currentMonth);
    const [viewMode, setViewMode] = useState<ViewMode>(viewModeOverride || 'daily');

    // 팀(현장) 검색어 상태 추가
    const [teamSearch, setTeamSearch] = useState<string>('');
    const [selectedTeamId, setSelectedTeamId] = useState<string>('');

    const [teams, setTeams] = useState<TeamWithId[]>([]);
        // 팀(현장) 검색어로 필터링된 팀 목록
        const filteredTeams = useMemo(() => {
            if (!teamSearch.trim()) return teams;
            const keyword = teamSearch.trim().toLowerCase();
            return teams.filter((t) => (t.name ?? '').toLowerCase().includes(keyword));
        }, [teams, teamSearch]);
    const [allTeams, setAllTeams] = useState<Team[]>([]);
    const [filtersReady, setFiltersReady] = useState<boolean>(false);

    const [rows, setRows] = useState<DraftRow[]>([]);
    const [originalRows, setOriginalRows] = useState<DraftRow[]>([]);
    const [loading, setLoading] = useState<boolean>(false);
    const [errorCount, setErrorCount] = useState<number>(0);

    const [bulkActualDeductionUnitPrice, setBulkActualDeductionUnitPrice] = useState<number>(0);
    const [bulkBillingDeductionUnitPrice, setBulkBillingDeductionUnitPrice] = useState<number>(0);
    const [bulkReportDeductionUnitPrice, setBulkReportDeductionUnitPrice] = useState<number>(0);

    const [showAccountColumns, setShowAccountColumns] = useState<boolean>(false);
    const [isFixed, setIsFixed] = useState<boolean>(true);

    const resolvedDeductionStorageKey = deductionStorageKey || DEFAULT_DEDUCTION_STORAGE_KEY;

    // Lock parent scroll for internal scrolling
    useEffect(() => {
        if (embedded) return;
        const mainContent = document.getElementById('main-content');
        if (mainContent) {
            const originalOverflow = mainContent.style.overflow;
            mainContent.style.overflow = 'hidden';
            return () => {
                mainContent.style.overflow = originalOverflow;
            };
        }
    }, [embedded]);

    const normalizeTeamName = useCallback((value: string): string => {
        return value.replace(/\(.*?\)/g, '').replace(/\s+/g, '').trim();
    }, []);

    const toYyyyMmDd = useCallback((date: Date): string => {
        const yyyy = String(date.getFullYear());
        const mm = String(date.getMonth() + 1).padStart(2, '0');
        const dd = String(date.getDate()).padStart(2, '0');
        return `${yyyy}-${mm}-${dd}`;
    }, []);

    const toYearMonth = useCallback((value: string): string => {
        const s = String(value ?? '').trim();
        const m = s.match(/^(\d{4}-\d{2})/);
        return m ? m[1] : '';
    }, []);

    const getThisYearMonth = useCallback((): string => {
        return new Date().toISOString().slice(0, 7);
    }, []);

    useEffect(() => {
        if (!dateOverride) return;
        setSelectedDate(dateOverride);
        const nextMonth = toYearMonth(dateOverride);
        if (nextMonth) {
            setSelectedMonth(nextMonth);
        }
    }, [dateOverride, toYearMonth]);

    useEffect(() => {
        if (typeof window === 'undefined') return;

        try {
            const raw = window.localStorage.getItem(resolvedDeductionStorageKey);
            if (!raw) return;
            const parsed = JSON.parse(raw) as Partial<DeductionPreset>;
            setBulkActualDeductionUnitPrice(Number(parsed.actual) || 0);
            setBulkBillingDeductionUnitPrice(Number(parsed.billing) || 0);
            setBulkReportDeductionUnitPrice(Number(parsed.report) || 0);
        } catch (error) {
            console.warn('Failed to load deduction preset:', error);
        }
    }, [resolvedDeductionStorageKey]);

    const handleSaveDeductionPreset = useCallback(() => {
        if (typeof window === 'undefined') return;

        const payload: DeductionPreset = {
            actual: Math.max(0, bulkActualDeductionUnitPrice || 0),
            billing: Math.max(0, bulkBillingDeductionUnitPrice || 0),
            report: Math.max(0, bulkReportDeductionUnitPrice || 0),
        };

        window.localStorage.setItem(resolvedDeductionStorageKey, JSON.stringify(payload));
        toast.success('차감 저장값을 저장했습니다.');
    }, [
        bulkActualDeductionUnitPrice,
        bulkBillingDeductionUnitPrice,
        bulkReportDeductionUnitPrice,
        resolvedDeductionStorageKey,
    ]);

    useEffect(() => {
        if (!monthOverride) return;
        setSelectedMonth(monthOverride);
    }, [monthOverride]);

    useEffect(() => {
        if (!viewModeOverride) return;
        setViewMode(viewModeOverride);
    }, [viewModeOverride]);

    const openLaborCostStatement = useCallback(
        (yearMonth: string) => {
            const ym = toYearMonth(yearMonth) || getThisYearMonth();
            const teamId = selectedTeamId ? selectedTeamId : 'ALL';
            navigate(`/payroll/daily-wage-statement?month=${encodeURIComponent(ym)}&teamId=${encodeURIComponent(teamId)}`);
        },
        [getThisYearMonth, navigate, selectedTeamId, toYearMonth]
    );

    const addDays = useCallback(
        (base: string, diffDays: number): string => {
            const [yyyy, mm, dd] = base.split('-').map((v) => Number(v));
            const safeDate = new Date(yyyy, (mm ?? 1) - 1, dd ?? 1);
            safeDate.setDate(safeDate.getDate() + diffDays);
            return toYyyyMmDd(safeDate);
        },
        [toYyyyMmDd]
    );

    const addMonths = useCallback((baseYearMonth: string, diffMonths: number): string => {
        const [yyyy, mm] = baseYearMonth.split('-').map((v) => Number(v));
        const safeDate = new Date(yyyy, (mm ?? 1) - 1, 1);
        safeDate.setMonth(safeDate.getMonth() + diffMonths);
        return safeDate.toISOString().slice(0, 7);
    }, []);

    const getMonthPeriod = useCallback((yearMonth: string): { startDate: string; endDate: string } => {
        const normalizedYearMonth = toYearMonth(yearMonth);
        if (!normalizedYearMonth) {
            return { startDate: '', endDate: '' };
        }

        const [yyyy, mm] = normalizedYearMonth.split('-').map((value) => Number(value));
        if (!yyyy || !mm) {
            return { startDate: '', endDate: '' };
        }

        const endDate = new Date(yyyy, mm, 0);

        return {
            startDate: `${normalizedYearMonth}-01`,
            endDate: toYyyyMmDd(endDate),
        };
    }, [toYearMonth, toYyyyMmDd]);

    useEffect(() => {
        const loadTeams = async () => {
            try {
                const fetchedTeams = await teamService.getTeams();
                setAllTeams(fetchedTeams);

                const normalizeCompanyType = (value: string | undefined): string => {
                    return (value ?? '').replace(/\s+/g, '').trim();
                };

                const companies = await companyService.getCompanies();
                const constructionCompanyIds = new Set<string>();
                const companyIdByNameNormalized = new Map<string, string>();

                companies.forEach((company) => {
                    const companyId = (company.id ?? '').trim();
                    if (!companyId) return;

                    const nameKey = normalizeTeamName(company.name ?? '');
                    if (nameKey && !companyIdByNameNormalized.has(nameKey)) {
                        companyIdByNameNormalized.set(nameKey, companyId);
                    }

                    if (normalizeCompanyType(company.type) === '시공사') {
                        constructionCompanyIds.add(companyId);
                    }
                });

                const filtered: TeamWithId[] = fetchedTeams
                    .filter((t): t is TeamWithId => typeof t.id === 'string' && t.id.trim().length > 0)
                    .filter((team) => {
                        const companyIdRaw = (team.companyId ?? '').trim();
                        const companyNameKey = normalizeTeamName(team.companyName ?? '');
                        const companyId = companyIdRaw || (companyNameKey ? (companyIdByNameNormalized.get(companyNameKey) ?? '') : '');
                        if (!companyId) return false;
                        return constructionCompanyIds.has(companyId);
                    })
                    .sort((a, b) => (a.name ?? '').localeCompare(b.name ?? '', 'ko'));

                setTeams(filtered);
            } catch (error) {
                console.error(error);
                toast.error('팀 목록을 불러오는 중 오류가 발생했습니다.');
            } finally {
                setFiltersReady(true);
            }
        };

        void loadTeams();
    }, []);


    const teamScope = useMemo(() => {
        const allowedTeamIds = new Set<string>();
        const allowedTeamNameNormalized = new Set<string>();

        if (!selectedTeamId) {
            return { allowedTeamIds, allowedTeamNameNormalized };
        }

        allowedTeamIds.add(selectedTeamId);
        const selectedTeamName = allTeams.find((t) => t.id === selectedTeamId)?.name ?? '';
        const selectedTeamNameNormalized = normalizeTeamName(selectedTeamName);
        if (selectedTeamNameNormalized) {
            allowedTeamNameNormalized.add(selectedTeamNameNormalized);
        }

        return { allowedTeamIds, allowedTeamNameNormalized };
    }, [allTeams, normalizeTeamName, selectedTeamId, teams]);

    const scopedRows = useMemo(() => {
        if (teamScope.allowedTeamIds.size === 0 && teamScope.allowedTeamNameNormalized.size === 0) {
            return rows;
        }
        return rows.filter((row) => {
            if (teamScope.allowedTeamIds.has(row.teamId)) return true;
            const normalized = normalizeTeamName(row.teamName);
            return normalized ? teamScope.allowedTeamNameNormalized.has(normalized) : false;
        });
    }, [
        normalizeTeamName,
        rows,
        selectedTeamId,
        teamScope.allowedTeamIds,
        teamScope.allowedTeamNameNormalized,
    ]);

    const filteredRows = scopedRows;

    const getRowTotals = useCallback((row: DraftRow): DraftRowTotals => {
        return {
            originalTotal: row.originalUnitPrice * row.manDay,
            actualTotal: row.actualUnitPrice * row.manDay,
            billingTotal: row.billingUnitPrice * row.manDay,
            reportTotal: row.reportUnitPrice * row.manDay,
        };
    }, []);

    const summary = useMemo(() => {
        return scopedRows.reduce(
            (acc, row) => {
                const totals = getRowTotals(row);
                acc.totalManDay += row.manDay;
                acc.totalOriginal += totals.originalTotal;
                acc.totalActual += totals.actualTotal;
                acc.totalBilling += totals.billingTotal;
                acc.totalReport += totals.reportTotal;
                return acc;
            },
            { totalManDay: 0, totalOriginal: 0, totalActual: 0, totalBilling: 0, totalReport: 0 }
        );
    }, [getRowTotals, scopedRows]);

    const validateRow = useCallback((params: {
        bankName: string;
        bankCode: string;
        accountNumber: string;
        accountHolder: string;
    }): { isValid: boolean; errors: DraftRow['errors'] } => {
        const errors: DraftRow['errors'] = {};
        let isValid = true;

        if (!params.bankName) {
            errors.bankName = true;
            isValid = false;
        }
        if (params.bankName && !params.bankCode) {
            errors.bankCode = true;
            isValid = false;
        }
        if (!params.accountNumber) {
            errors.accountNumber = true;
            isValid = false;
        }
        if (!params.accountHolder) {
            errors.accountHolder = true;
            isValid = false;
        }

        return { isValid, errors };
    }, []);

    const fetchData = useCallback(async (options?: { mode?: ViewMode; date?: string; month?: string }) => {
        const mode = options?.mode ?? viewMode;
        const date = (options?.date ?? selectedDate).trim();
        const month = (options?.month ?? selectedMonth).trim() || toYearMonth(date) || getThisYearMonth();
        const period = mode === 'monthly'
            ? getMonthPeriod(month)
            : { startDate: date, endDate: date };

        if (!period.startDate || !period.endDate) {
            toast.error('조회 날짜를 입력해 주세요.');
            return;
        }

        setLoading(true);
        try {
            const [reports, allWorkers] = await Promise.all([
                dailyReportService.getReports({ startDate: period.startDate, endDate: period.endDate }),
                manpowerService.getWorkers(),
            ]);

            const workerMap = new Map<string, Worker>();
            allWorkers.forEach((worker: Worker) => {
                if (worker.id) workerMap.set(worker.id, worker);
            });

            const teamMap = new Map<string, Team>();
            allTeams.forEach((t) => {
                if (t.id) teamMap.set(t.id, t);
            });

            const nextRows: DraftRow[] = [];
            let nextErrorCount = 0;

            reports.forEach((report: DailyReport) => {
                const resolvedReportTeamIdFromName = (() => {
                    const normalized = normalizeTeamName(report.teamName ?? '');
                    if (!normalized) return '';
                    const matched = allTeams.find((team) => normalizeTeamName(team.name ?? '') === normalized);
                    return matched?.id ?? '';
                })();

                const reportTeamId = (report.teamId ?? '').trim() || resolvedReportTeamIdFromName;
                const reportTeamName = report.teamName || teamMap.get(reportTeamId)?.name || '';

                report.workers.forEach((reportWorker: DailyReportWorker) => {
                    const workerDetails = workerMap.get(reportWorker.workerId);
                    if (!workerDetails) return;

                    const snapshotSalaryModel =
                        (typeof reportWorker.salaryModel === 'string' && reportWorker.salaryModel.trim().length > 0
                            ? reportWorker.salaryModel
                            : typeof reportWorker.payType === 'string' && reportWorker.payType.trim().length > 0
                                ? reportWorker.payType
                                : workerDetails.salaryModel || workerDetails.payType) ?? '';

                    // snapshotSalaryModel 필터 제거 (모든 작업자를 대상으로 함)

                    const originalUnitPrice = reportWorker.unitPrice ?? workerDetails.unitPrice ?? 0;
                    const actualUnitPrice = originalUnitPrice;
                    const billingUnitPrice = originalUnitPrice;
                    const reportUnitPrice = originalUnitPrice;

                    const bankName = workerDetails.bankName || '';
                    const bankCode = BANK_CODES[bankName] || '';
                    const accountNumber = workerDetails.accountNumber || '';
                    const accountHolder = workerDetails.accountHolder || '';

                    const validation = validateRow({ bankName, bankCode, accountNumber, accountHolder });
                    if (!validation.isValid) nextErrorCount += 1;

                    const resolvedTeamId = reportTeamId || reportWorker.teamId || '';
                    const safeTeamKey = resolvedTeamId || (normalizeTeamName(reportTeamName) ? `unresolved:${normalizeTeamName(reportTeamName)}` : 'no-team');
                    const reportKey = report.id ?? `${report.date}__${report.siteId}__${safeTeamKey}`;
                    const rowKey = `${reportKey}__${reportWorker.workerId}`;

                    nextRows.push({
                        rowKey,
                        date: report.date,
                        workerId: reportWorker.workerId,
                        workerName: reportWorker.name,
                        teamId: safeTeamKey,
                        teamName: reportTeamName,
                        manDay: reportWorker.manDay,
                        originalUnitPrice,
                        actualUnitPrice,
                        billingUnitPrice,
                        reportUnitPrice,
                        bankName,
                        bankCode,
                        accountNumber,
                        accountHolder,
                        isValid: validation.isValid,
                        errors: validation.errors,
                    });
                });
            });

            setRows(nextRows);
            setOriginalRows(nextRows.map((row) => ({ ...row })));
            setErrorCount(nextErrorCount);

            if (nextRows.length === 0) {
                toast.info('조회 결과가 없습니다.');
            }
        } catch (error) {
            console.error(error);
            toast.error('데이터를 불러오는 중 오류가 발생했습니다.');
        } finally {
            setLoading(false);
        }
    }, [allTeams, getMonthPeriod, getThisYearMonth, normalizeTeamName, selectedDate, selectedMonth, toYearMonth, validateRow, viewMode]);

    useEffect(() => {
        if (!filtersReady) return;
        void fetchData();
    }, [fetchData, filtersReady]);

    const updateRow = useCallback((rowKey: string, updater: (row: DraftRow) => DraftRow) => {
        setRows((prev) => prev.map((row) => (row.rowKey === rowKey ? updater(row) : row)));
    }, []);

    const applyBulk = useCallback(() => {
        setRows((prev) =>
            prev.map((row) => {
                if (selectedTeamId) {
                    const inScope =
                        teamScope.allowedTeamIds.has(row.teamId) ||
                        teamScope.allowedTeamNameNormalized.has(normalizeTeamName(row.teamName));
                    if (!inScope) return row;
                }

                const next: DraftRow = { ...row };

                next.actualUnitPrice = Math.max(0, row.originalUnitPrice - bulkActualDeductionUnitPrice);
                next.billingUnitPrice = Math.max(0, row.originalUnitPrice - bulkBillingDeductionUnitPrice);
                next.reportUnitPrice = Math.max(0, row.originalUnitPrice - bulkReportDeductionUnitPrice);

                return next;
            })
        );
    }, [
        bulkActualDeductionUnitPrice,
        bulkBillingDeductionUnitPrice,
        bulkReportDeductionUnitPrice,
        normalizeTeamName,
        selectedTeamId,
        teamScope.allowedTeamIds,
        teamScope.allowedTeamNameNormalized,
    ]);

    const resetRows = useCallback(() => {
        if (originalRows.length === 0) {
            void fetchData();
            return;
        }
        setRows(originalRows.map((row) => ({ ...row })));
    }, [fetchData, originalRows]);

    const resetDraftForSelection = useCallback(() => {
        setRows([]);
        setOriginalRows([]);
        setErrorCount(0);
        setBulkActualDeductionUnitPrice(0);
        setBulkBillingDeductionUnitPrice(0);
        setBulkReportDeductionUnitPrice(0);
        void fetchData({ mode: viewMode, date: selectedDate, month: selectedMonth });
    }, [fetchData, selectedDate, selectedMonth, viewMode]);

    const formatNumber = useCallback((value: number) => {
        return new Intl.NumberFormat('ko-KR').format(value);
    }, []);

    const currentYearMonth = useMemo(() => {
        if (viewMode === 'monthly') {
            return selectedMonth || toYearMonth(selectedDate) || getThisYearMonth();
        }
        return toYearMonth(selectedDate) || selectedMonth || getThisYearMonth();
    }, [getThisYearMonth, selectedDate, selectedMonth, toYearMonth, viewMode]);

    const tableColSpan = showAccountColumns ? 11 : 8;

    return (
        <div
            className={`flex-1 min-h-0 flex flex-col overflow-hidden ${
                embedded ? 'w-full max-w-none p-0' : 'max-w-[1600px] w-full mx-auto p-4 md:p-6'
            }`}
        >
            {!embedded && (
            <div className="flex-shrink-0 bg-white border border-slate-200 rounded-2xl shadow-sm px-6 py-4 mb-4">
                <div className="flex items-center gap-3">
                    <div className="bg-blue-100 text-blue-600 p-2 rounded-xl">
                        <FontAwesomeIcon icon={faCalendarDay} className="text-xl" />
                    </div>
                    <div>
                        <h1 className="text-2xl font-bold text-slate-800">일급제</h1>
                        <p className="text-sm text-slate-500 mt-1">일보 기반으로 일급제 지급/청구/신고 단가를 조정합니다.</p>
                    </div>
                </div>
            </div>
            )}

            <div className={`flex-shrink-0 bg-white border shadow-sm p-4 ${embedded ? 'rounded-xl border-[#d5ccb0] mb-4' : 'border-slate-200 rounded-2xl mb-6'}`}>
                <div className="flex flex-wrap gap-3 items-center justify-between">
                    <div className="flex flex-wrap items-end gap-3">
                        <div>
                            <div className="text-xs text-slate-500 mb-1">조회 기준</div>
                            <div className="inline-flex rounded-lg border border-slate-300 bg-slate-50 p-1">
                                <button
                                    type="button"
                                    onClick={() => setViewMode('daily')}
                                    className={`px-3 py-1.5 rounded-md text-sm font-semibold transition ${viewMode === 'daily'
                                        ? 'bg-white text-blue-700 shadow-sm'
                                        : 'text-slate-600 hover:text-slate-800'
                                        }`}
                                >
                                    일별
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setViewMode('monthly')}
                                    className={`px-3 py-1.5 rounded-md text-sm font-semibold transition ${viewMode === 'monthly'
                                        ? 'bg-white text-blue-700 shadow-sm'
                                        : 'text-slate-600 hover:text-slate-800'
                                        }`}
                                >
                                    월별
                                </button>
                            </div>
                        </div>
                        {!embedded && <div className={viewMode === 'monthly' ? 'hidden' : ''}>
                            <div className="text-xs text-slate-500 mb-1">날짜</div>
                            <input
                                type="date"
                                value={selectedDate}
                                onChange={(e) => {
                                    const next = e.target.value;
                                    setSelectedDate(next);
                                    const nextMonth = toYearMonth(next);
                                    if (nextMonth) setSelectedMonth(nextMonth);
                                }}
                                className="h-9 border border-slate-300 rounded-lg px-3 text-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none"
                            />
                        </div>}
                        {!embedded && <div className={`flex gap-2 self-end ${viewMode === 'monthly' ? 'hidden' : ''}`}>
                            <button
                                type="button"
                                onClick={() => {
                                    const base = selectedDate || today;
                                    const next = addDays(base, -1);
                                    setSelectedDate(next);
                                    const nextMonth = toYearMonth(next);
                                    if (nextMonth) setSelectedMonth(nextMonth);
                                }}
                                className="h-9 bg-slate-100 text-slate-700 hover:bg-slate-200 px-3 rounded-lg text-sm font-semibold transition disabled:opacity-50 disabled:cursor-not-allowed"
                                disabled={loading}
                            >
                                어제
                            </button>
                            <button
                                type="button"
                                onClick={() => {
                                    setSelectedDate(today);
                                    setSelectedMonth(currentMonth);
                                }}
                                className="h-9 bg-slate-100 text-slate-700 hover:bg-slate-200 px-3 rounded-lg text-sm font-semibold transition disabled:opacity-50 disabled:cursor-not-allowed"
                                disabled={loading}
                            >
                                오늘
                            </button>
                        </div>}
                        {embedded && (
                            <div className="flex items-end">
                                <div className="rounded-lg border border-[#d5ccb0] bg-[#faf8ef] px-3 py-2 text-xs text-slate-600">
                                    <div className="font-semibold text-[#4A452A]">{'\uC0C1\uB2E8 \uC870\uD68C \uAE30\uC900 \uC5F0\uB3D9'}</div>
                                    <div className="mt-1">{viewMode === 'monthly' ? selectedMonth : selectedDate}</div>
                                </div>
                            </div>
                        )}
                    </div>

                    {!embedded && viewMode === 'monthly' && (
                        <div className="flex items-end gap-2">
                            <div>
                                <div className="text-xs text-slate-500 mb-1">조회 월</div>
                                <input
                                    type="month"
                                    value={selectedMonth}
                                    onChange={(e) => setSelectedMonth(e.target.value)}
                                    className="h-9 border border-slate-300 rounded-lg px-3 text-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none"
                                />
                            </div>
                            <div className="flex gap-2 self-end">
                                <button
                                    type="button"
                                    onClick={() => setSelectedMonth((prev) => addMonths(prev || currentMonth, -1))}
                                    className="h-9 bg-slate-100 text-slate-700 hover:bg-slate-200 px-3 rounded-lg text-sm font-semibold transition disabled:opacity-50 disabled:cursor-not-allowed"
                                    disabled={loading}
                                >
                                    이전 달
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setSelectedMonth(currentMonth)}
                                    className="h-9 bg-slate-100 text-slate-700 hover:bg-slate-200 px-3 rounded-lg text-sm font-semibold transition disabled:opacity-50 disabled:cursor-not-allowed"
                                    disabled={loading}
                                >
                                    이번 달
                                </button>
                            </div>
                        </div>
                    )}

                    {/* 현장명(팀명) 검색 입력창 */}
                    <input
                        type="text"
                        value={teamSearch}
                        onChange={e => setTeamSearch(e.target.value)}
                        className="w-32 border border-slate-300 rounded-lg px-2 py-1 text-xs mr-2"
                        placeholder="현장명 검색 (예: 김포)"
                        style={{ minWidth: 100 }}
                    />
                    <select
                        value={selectedTeamId}
                        onChange={(e) => setSelectedTeamId(e.target.value)}
                        className="border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-brand-500 focus:border-brand-500 outline-none"
                        disabled={!filtersReady}
                    >
                        <option value="">팀전체</option>
                        {filteredTeams.map((team) => (
                            <option key={team.id} value={team.id}>
                                {team.name}
                            </option>
                        ))}
                    </select>

                    <button
                        type="button"
                        onClick={() => setShowAccountColumns((prev) => !prev)}
                        className="px-3 py-2 bg-white border border-slate-300 text-slate-700 hover:bg-slate-50 rounded-lg text-sm font-semibold transition flex items-center gap-2"
                    >
                        <FontAwesomeIcon icon={showAccountColumns ? faEyeSlash : faEye} />
                        {showAccountColumns ? '계좌 숨기기' : '계좌 보기'}
                    </button>

                    <button
                        type="button"
                        onClick={() => setIsFixed((prev) => !prev)}
                        className={`px-3 py-2 border rounded-lg text-sm font-semibold transition flex items-center gap-2 ${isFixed
                            ? 'bg-blue-50 border-blue-200 text-blue-700 hover:bg-blue-100'
                            : 'bg-white border-slate-300 text-slate-700 hover:bg-slate-50'
                            }`}
                    >
                        <FontAwesomeIcon icon={faThumbtack} className={isFixed ? 'rotate-45' : ''} />
                        {isFixed ? '틀고정 해제' : '틀고정'}
                    </button>

                    <div className="flex gap-2">
                        <button
                            type="button"
                            onClick={() => void fetchData({ mode: viewMode, date: selectedDate, month: selectedMonth })}
                            className="bg-slate-100 text-slate-600 hover:bg-slate-200 px-4 py-2 rounded-lg text-sm font-medium transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                            disabled={loading}
                        >
                            <FontAwesomeIcon icon={faSearch} />
                            <span>조회</span>
                        </button>
                        <button
                            type="button"
                            onClick={resetDraftForSelection}
                            className="bg-white text-slate-600 border border-slate-300 hover:bg-slate-50 px-4 py-2 rounded-lg text-sm font-semibold transition disabled:opacity-50 disabled:cursor-not-allowed"
                            disabled={loading}
                        >
                            리셋
                        </button>
                        <button
                            type="button"
                            onClick={() => openLaborCostStatement(currentYearMonth)}
                            className="bg-slate-700 text-white hover:bg-slate-800 px-4 py-2 rounded-lg text-sm font-bold transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                            disabled={loading}
                        >
                            <FontAwesomeIcon icon={faPrint} />
                            명세서 열기
                        </button>
                    </div>
                </div>
            </div>

            <div className="flex-shrink-0">
                {errorCount > 0 && (
                    <div className="mb-4 bg-amber-50 border border-amber-200 text-amber-700 px-4 py-3 rounded-lg flex items-center gap-2 text-sm">
                        <FontAwesomeIcon icon={faExclamationTriangle} className="text-amber-500" />
                        <span>
                            <strong>{errorCount.toLocaleString()}건</strong>의 데이터에 은행 정보가 누락되었습니다. (은행명/코드/계좌/예금주)
                        </span>
                    </div>
                )}

                <div className={`bg-white shadow-sm p-4 mb-4 ${embedded ? 'rounded-xl border border-[#d5ccb0]' : 'rounded-2xl border border-slate-200'}`}>
                    <div className="flex flex-col lg:flex-row gap-3 lg:items-end lg:justify-between">
                        <div className="flex flex-wrap items-end gap-3">
                            <div>
                                <div className="text-[11px] text-slate-500 mb-1">지급차감</div>
                                <input
                                    type="number"
                                    value={bulkActualDeductionUnitPrice}
                                    onChange={(e) => setBulkActualDeductionUnitPrice(Number(e.target.value))}
                                    step={5000}
                                    className="w-20 border border-slate-300 rounded-lg px-2 py-1 text-[11px] text-right"
                                    placeholder="0"
                                />
                            </div>
                            <div>
                                <div className="text-[11px] text-slate-500 mb-1">청구차감</div>
                                <input
                                    type="number"
                                    value={bulkBillingDeductionUnitPrice}
                                    onChange={(e) => setBulkBillingDeductionUnitPrice(Number(e.target.value))}
                                    step={5000}
                                    className="w-20 border border-slate-300 rounded-lg px-2 py-1 text-[11px] text-right"
                                    placeholder="0"
                                />
                            </div>
                            <div>
                                <div className="text-[11px] text-slate-500 mb-1">신고차감</div>
                                <input
                                    type="number"
                                    value={bulkReportDeductionUnitPrice}
                                    onChange={(e) => setBulkReportDeductionUnitPrice(Number(e.target.value))}
                                    step={5000}
                                    className="w-20 border border-slate-300 rounded-lg px-2 py-1 text-[11px] text-right"
                                    placeholder="0"
                                />
                            </div>
                            <div className="flex flex-wrap items-center gap-2">
                                <button
                                    type="button"
                                    onClick={applyBulk}
                                    className="bg-blue-600 text-white px-2.5 py-1 rounded-lg text-[11px] font-bold hover:bg-blue-700"
                                >
                                    일괄 적용
                                </button>
                                <button
                                    type="button"
                                    onClick={handleSaveDeductionPreset}
                                    className="bg-emerald-600 text-white px-2.5 py-1 rounded-lg text-[11px] font-bold hover:bg-emerald-700"
                                >
                                    차감 저장
                                </button>
                                <button
                                    type="button"
                                    onClick={resetRows}
                                    className="bg-slate-500 text-white px-2.5 py-1 rounded-lg text-[11px] font-bold hover:bg-slate-600"
                                >
                                    초기화
                                </button>
                            </div>
                            <div className="text-[11px] text-slate-400">
                                저장한 차감값은 이 화면에서 자동으로 다시 불러옵니다.
                            </div>
                        </div>

                        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-2 text-sm shrink-0">
                            <div className="bg-slate-50 border border-slate-200 rounded-lg p-2">
                                <div className="text-[11px] text-slate-500">총 공수</div>
                                <div className="font-bold text-slate-800 mt-0.5 text-sm">{summary.totalManDay.toFixed(1)}</div>
                            </div>
                            <div className="bg-emerald-50 border border-emerald-200 rounded-lg p-2">
                                <div className="text-[11px] text-emerald-700">지급 합계</div>
                                <div className="font-bold text-emerald-900 mt-0.5 text-sm">{formatNumber(summary.totalActual)}</div>
                            </div>
                            <div className="bg-orange-50 border border-orange-200 rounded-lg p-2">
                                <div className="text-[11px] text-orange-700">청구 합계</div>
                                <div className="font-bold text-orange-900 mt-0.5 text-sm">{formatNumber(summary.totalBilling)}</div>
                            </div>
                            <div className="bg-blue-50 border border-blue-200 rounded-lg p-2">
                                <div className="text-[11px] text-blue-700">신고 합계</div>
                                <div className="font-bold text-blue-900 mt-0.5 text-sm">{formatNumber(summary.totalReport)}</div>
                            </div>
                            <div className="bg-slate-50 border border-slate-200 rounded-lg p-2">
                                <div className="text-[11px] text-slate-500">원 총액</div>
                                <div className="font-bold text-slate-800 mt-0.5 text-sm">{formatNumber(summary.totalOriginal)}</div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className={`flex-1 min-h-0 bg-white shadow-sm border flex flex-col overflow-hidden ${embedded ? 'rounded-xl border-[#d5ccb0]' : 'rounded-2xl border-slate-200'}`}>
                <div className="flex-1 overflow-auto">
                    <table className="w-full text-sm border-separate border-spacing-0">
                        <thead className="bg-slate-50 text-slate-600 sticky top-0 z-40">
                            <tr>
                                <th className={`px-3 py-3 text-left border-b border-slate-200 ${isFixed ? 'sticky left-0 z-50 bg-slate-50 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]' : ''}`} style={{ width: isFixed ? '90px' : 'auto', minWidth: isFixed ? '90px' : 'auto' }}>날짜</th>
                                <th className={`px-3 py-3 text-left border-b border-slate-200 ${isFixed ? 'sticky left-[90px] z-50 bg-slate-50 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]' : ''}`} style={{ width: isFixed ? '100px' : 'auto', minWidth: isFixed ? '100px' : 'auto' }}>이름</th>
                                <th className={`px-3 py-3 text-left border-b border-slate-200 ${isFixed ? 'sticky left-[190px] z-50 bg-slate-50 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]' : ''}`} style={{ width: isFixed ? '140px' : 'auto', minWidth: isFixed ? '140px' : 'auto' }}>팀명</th>
                                <th className="px-3 py-3 text-right border-b border-slate-200">공수</th>
                                <th className="px-3 py-3 text-right border-b border-slate-200">원단가</th>
                                <th className="px-3 py-3 text-right text-emerald-700 border-b border-slate-200">지급단가</th>
                                <th className="px-3 py-3 text-right text-orange-700 border-b border-slate-200">청구단가</th>
                                <th className="px-3 py-3 text-right text-blue-700 border-b border-slate-200">신고단가</th>
                                {showAccountColumns && <th className="px-3 py-3 text-left border-b border-slate-200">은행</th>}
                                {showAccountColumns && <th className="px-3 py-3 text-left border-b border-slate-200">계좌</th>}
                                {showAccountColumns && <th className="px-3 py-3 text-left border-b border-slate-200">예금주</th>}
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {loading && (
                                <tr>
                                    <td colSpan={tableColSpan} className="px-4 py-10 text-center text-slate-500">
                                        <FontAwesomeIcon icon={faSpinner} className="animate-spin mr-2" />
                                        로딩 중...
                                    </td>
                                </tr>
                            )}

                            {!loading && filteredRows.length === 0 && (
                                <tr>
                                    <td colSpan={tableColSpan} className="px-4 py-10 text-center text-slate-400">
                                        조회 결과가 없습니다.
                                    </td>
                                </tr>
                            )}

                            {!loading &&
                                filteredRows.map((row) => {
                                    const invalidClass = row.isValid ? '' : 'bg-amber-50';
                                    const isActualChanged = row.actualUnitPrice !== row.originalUnitPrice;
                                    const isBillingChanged = row.billingUnitPrice !== row.originalUnitPrice;
                                    const isReportChanged = row.reportUnitPrice !== row.originalUnitPrice;

                                    return (
                                        <tr key={row.rowKey} className={`hover:bg-slate-50 ${invalidClass}`}>
                                            <td className={`px-3 py-2 whitespace-nowrap font-mono text-xs text-slate-600 border-b border-slate-100 ${isFixed ? 'sticky left-0 z-10 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]' : ''} ${isFixed ? (row.isValid ? 'bg-white' : 'bg-amber-50') : ''}`}>{row.date}</td>
                                            <td className={`px-3 py-2 whitespace-nowrap font-semibold text-slate-800 border-b border-slate-100 ${isFixed ? 'sticky left-[90px] z-10 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]' : ''} ${isFixed ? (row.isValid ? 'bg-white' : 'bg-amber-50') : ''}`}>{row.workerName}</td>
                                            <td className={`px-3 py-2 whitespace-nowrap text-slate-700 border-b border-slate-100 ${isFixed ? 'sticky left-[190px] z-10 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]' : ''} ${isFixed ? (row.isValid ? 'bg-white' : 'bg-amber-50') : ''}`}>{row.teamName}</td>
                                            <td className="px-3 py-2 text-right font-mono border-b border-slate-100">{row.manDay.toFixed(1)}</td>
                                            <td className="px-3 py-2 text-right font-mono">{formatNumber(row.originalUnitPrice)}</td>
                                            <td className="px-3 py-2 text-right">
                                                <input
                                                    type="number"
                                                    value={row.actualUnitPrice}
                                                    onChange={(e) =>
                                                        updateRow(row.rowKey, (prev) => ({ ...prev, actualUnitPrice: Number(e.target.value) }))
                                                    }
                                                    step={5000}
                                                    className={`w-20 rounded px-2 py-1 text-right font-mono text-xs focus:outline-none focus:ring-2 ${isActualChanged
                                                        ? 'border border-emerald-300 bg-emerald-50 text-emerald-900 focus:ring-emerald-200'
                                                        : 'border border-slate-300 bg-white text-emerald-700 focus:ring-blue-200'
                                                        }`}
                                                />
                                            </td>
                                            <td className="px-3 py-2 text-right">
                                                <input
                                                    type="number"
                                                    value={row.billingUnitPrice}
                                                    onChange={(e) =>
                                                        updateRow(row.rowKey, (prev) => ({ ...prev, billingUnitPrice: Number(e.target.value) }))
                                                    }
                                                    step={5000}
                                                    className={`w-20 rounded px-2 py-1 text-right font-mono text-xs focus:outline-none focus:ring-2 ${isBillingChanged
                                                        ? 'border border-orange-300 bg-orange-50 text-orange-900 focus:ring-orange-200'
                                                        : 'border border-slate-300 bg-white text-orange-700 focus:ring-blue-200'
                                                        }`}
                                                />
                                            </td>
                                            <td className="px-3 py-2 text-right">
                                                <input
                                                    type="number"
                                                    value={row.reportUnitPrice}
                                                    onChange={(e) =>
                                                        updateRow(row.rowKey, (prev) => ({ ...prev, reportUnitPrice: Number(e.target.value) }))
                                                    }
                                                    step={5000}
                                                    className={`w-20 rounded px-2 py-1 text-right font-mono text-xs focus:outline-none focus:ring-2 ${isReportChanged
                                                        ? 'border border-blue-300 bg-blue-50 text-blue-900 focus:ring-blue-200'
                                                        : 'border border-slate-300 bg-white text-blue-700 focus:ring-blue-200'
                                                        }`}
                                                />
                                            </td>
                                            {showAccountColumns && (
                                                <td
                                                    className={`px-3 py-2 whitespace-nowrap ${row.errors.bankName || row.errors.bankCode ? 'text-red-700 font-semibold' : ''
                                                        }`}
                                                >
                                                    {row.bankName || '-'}
                                                </td>
                                            )}
                                            {showAccountColumns && (
                                                <td
                                                    className={`px-3 py-2 whitespace-nowrap font-mono ${row.errors.accountNumber ? 'text-red-700 font-semibold' : ''
                                                        }`}
                                                >
                                                    {row.accountNumber || '-'}
                                                </td>
                                            )}
                                            {showAccountColumns && (
                                                <td
                                                    className={`px-3 py-2 whitespace-nowrap border-b border-slate-100 ${row.errors.accountHolder ? 'text-red-700 font-semibold' : ''
                                                        }`}
                                                >
                                                    {row.accountHolder || '-'}

                                                </td>
                                            )}
                                        </tr>
                                    );
                                })}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default DailyWageDraftPage;

import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { dailyReportService } from '../../services/dailyReportService';
import { manpowerService, Worker } from '../../services/manpowerService';
import { teamService, Team } from '../../services/teamService';
import * as XLSX from 'xlsx';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faFileExcel, faSearch, faSpinner, faExclamationTriangle, faPrint } from '@fortawesome/free-solid-svg-icons';
import { useNavigate } from 'react-router-dom';

interface PaymentData {
    rowKey: string;
    workerId: string;
    workerName: string;
    teamId: string;
    teamName: string;
    date: string;
    manDay: number;
    unitPrice: number;
    totalAmount: number;
    actualPayment: number; // 실지급
    billingAmount: number; // 청구액
    reportAmount: number; // 신고액
    bankName: string;
    bankCode: string;
    accountNumber: string;
    accountHolder: string;
    displayContent: string;
    isValid: boolean;
    errors: {
        bankName?: boolean;
        bankCode?: boolean;
        accountNumber?: boolean;
        accountHolder?: boolean;
    };
}

const BANK_CODES: { [key: string]: string } = {
    'KB국민은행': '004', '국민은행': '004', '국민': '004',
    'SC제일은행': '023', '제일은행': '023', 'SC': '023',
    '경남은행': '039', '경남': '039',
    '광주은행': '034', '광주': '034',
    '기업은행': '003', '기업': '003', 'IBK': '003',
    '농협은행': '011', '농협': '011', 'NH': '011',
    '대구은행': '031', '대구': '031',
    '부산은행': '032', '부산': '032',
    '산업은행': '002', '산업': '002',
    '수협은행': '007', '수협': '007',
    '신한은행': '088', '신한': '088',
    '우리은행': '020', '우리': '020',
    '우체국': '071',
    '전북은행': '037', '전북': '037',
    '제주은행': '035', '제주': '035',
    '카카오뱅크': '090', '카카오': '090',
    '케이뱅크': '089', '케이': '089',
    '토스뱅크': '092', '토스': '092',
    '하나은행': '081', '하나': '081',
    '한국씨티은행': '027', '씨티': '027',
};

interface Props {
    hideHeader?: boolean;
}

const toYearMonth = (value: string): string => {
    const s = String(value ?? '').trim();
    const m = s.match(/^(\d{4}-\d{2})/);
    return m ? m[1] : '';
};

const getThisYearMonth = (): string => {
    return new Date().toISOString().slice(0, 7);
};

const getPrevYearMonth = (yearMonth: string): string => {
    const safe = toYearMonth(yearMonth) || getThisYearMonth();
    const [yStr, mStr] = safe.split('-');
    const y = Number(yStr);
    const m = Number(mStr);
    if (!y || !m) return getThisYearMonth();
    const d = new Date(y, m - 2, 1);
    const yy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    return `${yy}-${mm}`;
};

const DailyWagePaymentPage: React.FC<Props> = ({ hideHeader }) => {
    const navigate = useNavigate();

    const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
    const [paymentData, setPaymentData] = useState<PaymentData[]>([]);
    const [loading, setLoading] = useState<boolean>(false);
    const [totalAmount, setTotalAmount] = useState<number>(0); // 총 청구금액 (공수×단가 합산)
    const [bulkDisplayContent, setBulkDisplayContent] = useState<string>('급여');
    const [errorCount, setErrorCount] = useState<number>(0);
    const [bulkActualPayment, setBulkActualPayment] = useState<number>(150000);
    const [bulkBillingAmount, setBulkBillingAmount] = useState<number>(165000);
    const [bulkReportAmount, setBulkReportAmount] = useState<number>(170000);
    const [bulkTargetReportAmount, setBulkTargetReportAmount] = useState<number>(0); // 청구용 기준 (신고금액)
    const [bulkPaymentTotalAmount, setBulkPaymentTotalAmount] = useState<number>(150000); // 지급용 입금액
    const [bulkUnitPrice, setBulkUnitPrice] = useState<number>(150000); // 지급용 단가
    const [bulkTargetUnitPrice, setBulkTargetUnitPrice] = useState<number>(0); // 조건: 이 단가와 같은 항목만 변경 (0=변경안함)
    const [originalPaymentData, setOriginalPaymentData] = useState<PaymentData[]>([]); // 초기화용 원본 데이터
    const [viewTab, setViewTab] = useState<'payment' | 'billing'>('payment'); // 지급용 vs 청구용
    const [teams, setTeams] = useState<Team[]>([]);
    const [allTeams, setAllTeams] = useState<Team[]>([]);
    const [selectedTeamId, setSelectedTeamId] = useState<string>('');
    const [filtersReady, setFiltersReady] = useState<boolean>(false);

    const openLaborCostStatement = (yearMonth: string) => {
        const ym = toYearMonth(yearMonth) || getThisYearMonth();
        const teamId = selectedTeamId ? selectedTeamId : 'ALL';
        navigate(`/payroll/daily-wage-statement?month=${encodeURIComponent(ym)}&teamId=${encodeURIComponent(teamId)}`);
    };

    const filteredPaymentData = useMemo(() => {
        const normalizeTeamName = (value: string): string => {
            return value
                .replace(/\(.*?\)/g, '')
                .replace(/\s+/g, '')
                .trim();
        };

        if (!selectedTeamId) return paymentData;

        const selectedTeamName = allTeams.find(t => t.id === selectedTeamId)?.name ?? '';
        const selectedTeamNameNormalized = normalizeTeamName(selectedTeamName);

        const allowedTeamIds = new Set<string>();
        allowedTeamIds.add(selectedTeamId);

        allTeams.forEach(team => {
            if (!team.id) return;
            if (team.parentTeamId === selectedTeamId) {
                allowedTeamIds.add(team.id);
                return;
            }
            if (selectedTeamNameNormalized) {
                const parentNameNormalized = normalizeTeamName(team.parentTeamName ?? '');
                if (parentNameNormalized && parentNameNormalized === selectedTeamNameNormalized) {
                    allowedTeamIds.add(team.id);
                }
            }
        });

        const allowedTeamNameNormalized = new Set<string>();
        allTeams.forEach(team => {
            if (!team.id) return;
            if (!allowedTeamIds.has(team.id)) return;
            const normalized = normalizeTeamName(team.name ?? '');
            if (normalized) allowedTeamNameNormalized.add(normalized);
        });

        return paymentData.filter(item => {
            if (allowedTeamIds.has(item.teamId)) return true;
            const normalized = normalizeTeamName(item.teamName);
            return normalized ? allowedTeamNameNormalized.has(normalized) : false;
        });
    }, [paymentData, selectedTeamId, allTeams]);

    useEffect(() => {
        const loadTeams = async () => {
            try {
                const allTeams = await teamService.getTeams();
                setAllTeams(allTeams);
                const filtered = allTeams
                    .filter(t => !!t.id)
                    .sort((a, b) => (a.name ?? '').localeCompare(b.name ?? ''));
                setTeams(filtered);
            } catch (error) {
                console.error('Failed to load teams:', error);
                alert('팀 목록을 불러오는 중 오류가 발생했습니다.');
            } finally {
                setFiltersReady(true);
            }
        };

        void loadTeams();
        setSelectedTeamId('');
    }, []);

    const validateItem = useCallback((item: Partial<PaymentData>): { isValid: boolean, errors: PaymentData['errors'] } => {
        const errors: PaymentData['errors'] = {};
        let isValid = true;

        if (!item.bankName) {
            errors.bankName = true;
            isValid = false;
        }
        if (!item.bankCode && item.bankName) {
            if (!BANK_CODES[item.bankName]) {
                errors.bankCode = true;
                isValid = false;
            }
        }
        if (!item.accountNumber) {
            errors.accountNumber = true;
            isValid = false;
        }
        if (!item.accountHolder) {
            errors.accountHolder = true;
            isValid = false;
        }

        return { isValid, errors };
    }, []);

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const reports = await dailyReportService.getReports(selectedDate);

            const allWorkers = await manpowerService.getWorkers();
            const workerMap = new Map(allWorkers.map(w => [w.id!, w]));

            const teamMap = new Map<string, Team>();
            allTeams.forEach(t => {
                if (t.id) teamMap.set(t.id, t);
            });

            const normalizeTeamName = (value: string): string => {
                return value
                    .replace(/\(.*?\)/g, '')
                    .replace(/\s+/g, '')
                    .trim();
            };

            const processedData: PaymentData[] = [];
            let sumAmount = 0;
            let errCount = 0;

            reports.forEach(report => {
                const resolvedReportTeamIdFromName = (() => {
                    const normalized = normalizeTeamName(report.teamName ?? '');
                    if (!normalized) return '';
                    const matched = allTeams.find(t => normalizeTeamName(t.name ?? '') === normalized);
                    return matched?.id ?? '';
                })();

                const reportTeamId = report.teamId || resolvedReportTeamIdFromName;
                const reportTeamName = report.teamName || teamMap.get(reportTeamId)?.name || '';

                report.workers.forEach(reportWorker => {
                    const workerDetails = workerMap.get(reportWorker.workerId);

                    if (!workerDetails) return;

                    const snapshotSalaryModel =
                        typeof reportWorker.salaryModel === 'string' && reportWorker.salaryModel.trim().length > 0
                            ? reportWorker.salaryModel
                            : typeof reportWorker.payType === 'string' && reportWorker.payType.trim().length > 0
                                ? reportWorker.payType
                                : workerDetails.salaryModel;

                    if (snapshotSalaryModel && snapshotSalaryModel !== '일급제') return;

                    const unitPrice = reportWorker.unitPrice ?? workerDetails.unitPrice ?? 0;
                    const amount = reportWorker.manDay * unitPrice;
                    const bankName = workerDetails.bankName || '';
                    const bankCode = BANK_CODES[bankName] || '';
                    const accountNumber = workerDetails.accountNumber || '';
                    const accountHolder = workerDetails.accountHolder || '';

                    const validation = validateItem({ bankName, bankCode, accountNumber, accountHolder });
                    if (!validation.isValid) errCount++;

                    const resolvedTeamId = reportTeamId || reportWorker.teamId || '';
                    const resolvedTeamName = reportTeamName;
                    const safeTeamKey = resolvedTeamId || (normalizeTeamName(resolvedTeamName) ? `unresolved:${normalizeTeamName(resolvedTeamName)}` : 'no-team');
                    const reportKey = report.id ?? `${report.date}__${report.siteId}__${safeTeamKey}`;
                    const rowKey = `${reportKey}__${reportWorker.workerId}`;

                    processedData.push({
                        rowKey,
                        workerId: reportWorker.workerId,
                        workerName: reportWorker.name,
                        teamId: safeTeamKey,
                        teamName: resolvedTeamName,
                        date: report.date,
                        manDay: reportWorker.manDay,
                        unitPrice: unitPrice,
                        totalAmount: amount,
                        actualPayment: 150000, // 기본 실지급
                        billingAmount: 165000, // 기본 청구액
                        reportAmount: unitPrice, // 신고액 = 단가
                        bankName: bankName,
                        bankCode: bankCode,
                        accountNumber: accountNumber,
                        accountHolder: accountHolder,
                        displayContent: '급여',
                        isValid: validation.isValid,
                        errors: validation.errors
                    });
                    sumAmount += amount;
                });
            });

            setPaymentData(processedData);
            setOriginalPaymentData(processedData.map(item => ({ ...item }))); // 원본 저장
            setTotalAmount(sumAmount);
            setErrorCount(errCount);

        } catch (error) {
            console.error("Error fetching payment data:", error);
            alert("데이터를 불러오는 중 오류가 발생했습니다.");
        } finally {
            setLoading(false);
        }
    }, [allTeams, selectedDate, validateItem]);

    useEffect(() => {
        if (!filtersReady) return;
        void fetchData();
    }, [fetchData, filtersReady]);

    const handleDisplayContentChange = (rowKey: string, value: string) => {
        setPaymentData(prev => prev.map(item => (item.rowKey === rowKey ? { ...item, displayContent: value } : item)));
    };

    const handleBulkDisplayContentApply = () => {
        const visibleKeys = new Set(filteredPaymentData.map(item => item.rowKey));
        setPaymentData(prev => prev.map(item => {
            if (!visibleKeys.has(item.rowKey)) return item;
            return { ...item, displayContent: bulkDisplayContent };
        }));
    };

    const handleBulkAmountApply = () => {
        const visibleKeys = new Set(filteredPaymentData.map(item => item.rowKey));
        setPaymentData(prev => prev.map(item => {
            if (!visibleKeys.has(item.rowKey)) return item;
            return {
                ...item,
                actualPayment: bulkActualPayment,
                billingAmount: bulkBillingAmount,
                reportAmount: bulkReportAmount
            };
        }));
    };

    const handleActualPaymentChange = (rowKey: string, value: number) => {
        setPaymentData(prev => prev.map(item => (item.rowKey === rowKey ? { ...item, actualPayment: value } : item)));
    };

    const handleBillingAmountChange = (rowKey: string, value: number) => {
        setPaymentData(prev => prev.map(item => (item.rowKey === rowKey ? { ...item, billingAmount: value } : item)));
    };

    const handleReportAmountChange = (rowKey: string, value: number) => {
        setPaymentData(prev => prev.map(item => (item.rowKey === rowKey ? { ...item, reportAmount: value } : item)));
    };

    const handleUnitPriceChange = (rowKey: string, value: number) => {
        setPaymentData(prev => prev.map(item => {
            if (item.rowKey !== rowKey) return item;
            return { ...item, unitPrice: value, totalAmount: value * item.manDay };
        }));
    };

    const handleDownloadExcel = () => {
        if (filteredPaymentData.length === 0) {
            alert("출력할 데이터가 없습니다.");
            return;
        }

        const filteredErrorCount = viewTab === 'payment'
            ? filteredPaymentData.filter(item => !item.isValid).length
            : 0;

        if (filteredErrorCount > 0 && viewTab === 'payment') {
            if (!window.confirm(`${filteredErrorCount}건의 데이터에 누락된 정보가 있습니다. 그래도 다운로드하시겠습니까?`)) {
                return;
            }
        }

        let excelData: Record<string, string | number>[];
        let sheetName: string;
        let colWidths: { wch: number }[];

        const exportRows = filteredPaymentData;

        if (viewTab === 'payment') {
            // 지급용 엑셀 데이터
            excelData = exportRows.map((item, idx) => ({
                '순번': idx + 1,
                '이름': item.workerName,
                '팀명': item.teamName,
                '공수': item.manDay,
                '단가': item.unitPrice,
                '입금액': item.totalAmount,
                '은행코드': item.bankCode,
                '은행명': item.bankName,
                '계좌번호': item.accountNumber,
                '예금주': item.accountHolder,
                '표시내용': item.displayContent,
            }));

            // 합계 행 추가
            excelData.push({
                '순번': '',
                '이름': '합계',
                '팀명': '',
                '공수': exportRows.reduce((sum, item) => sum + item.manDay, 0),
                '단가': '',
                '입금액': exportRows.reduce((sum, item) => sum + item.totalAmount, 0),
                '은행코드': '',
                '은행명': '',
                '계좌번호': '',
                '예금주': '',
                '표시내용': '',
            });

            sheetName = "일급제_지급용";
            colWidths = [
                { wch: 5 },   // 순번
                { wch: 10 },  // 이름
                { wch: 12 },  // 팀명
                { wch: 6 },   // 공수
                { wch: 10 },  // 단가
                { wch: 12 },  // 입금액
                { wch: 6 },   // 은행코드
                { wch: 12 },  // 은행명
                { wch: 18 },  // 계좌번호
                { wch: 10 },  // 예금주
                { wch: 10 },  // 표시내용
            ];
        } else {
            // 청구용 엑셀 데이터
            excelData = exportRows.map((item, idx) => ({
                '순번': idx + 1,
                '이름': item.workerName,
                '팀명': item.teamName,
                '공수': item.manDay,
                '실지급': item.actualPayment,
                '청구액': item.billingAmount,
                '신고액': item.reportAmount,
                '실지급합계': item.actualPayment * item.manDay,
                '청구액합계': item.billingAmount * item.manDay,
                '신고액합계': item.reportAmount * item.manDay,
            }));

            // 합계 행 추가
            excelData.push({
                '순번': '',
                '이름': '합계',
                '팀명': '',
                '공수': exportRows.reduce((sum, item) => sum + item.manDay, 0),
                '실지급': '',
                '청구액': '',
                '신고액': '',
                '실지급합계': exportRows.reduce((sum, item) => sum + (item.actualPayment * item.manDay), 0),
                '청구액합계': exportRows.reduce((sum, item) => sum + (item.billingAmount * item.manDay), 0),
                '신고액합계': exportRows.reduce((sum, item) => sum + (item.reportAmount * item.manDay), 0),
            });

            sheetName = "일급제_청구용";
            colWidths = [
                { wch: 5 },   // 순번
                { wch: 10 },  // 이름
                { wch: 12 },  // 팀명
                { wch: 6 },   // 공수
                { wch: 10 },  // 실지급
                { wch: 10 },  // 청구액
                { wch: 10 },  // 신고액
                { wch: 12 },  // 실지급합계
                { wch: 12 },  // 청구액합계
                { wch: 12 },  // 신고액합계
            ];
        }

        const ws = XLSX.utils.json_to_sheet(excelData);
        ws['!cols'] = colWidths;

        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, sheetName);

        const tabSuffix = viewTab === 'payment' ? '지급용' : '청구용';
        const fileName = `일급제_${tabSuffix}_${selectedDate}.xlsx`;
        XLSX.writeFile(wb, fileName);
    };

    return (
        <div className="p-6 max-w-[1600px] w-full mx-auto">
            <div className="flex justify-between items-center mb-4">
                {!hideHeader && <h1 className="text-2xl font-bold text-slate-800">일급제 지급 관리</h1>}
                <div className="flex gap-3">
                    <input
                        type="date"
                        value={selectedDate}
                        onChange={(e) => setSelectedDate(e.target.value)}
                        className="border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-brand-500 focus:border-brand-500 outline-none"
                    />
                    <select
                        value={selectedTeamId}
                        onChange={(e) => setSelectedTeamId(e.target.value)}
                        className="border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-brand-500 focus:border-brand-500 outline-none"
                    >
                        <option value="">모든 팀</option>
                        {teams.filter(t => !!t.id).map(team => (
                            <option key={team.id} value={team.id}>{team.name}</option>
                        ))}
                    </select>
                    <button
                        onClick={fetchData}
                        className="bg-slate-100 text-slate-600 hover:bg-slate-200 px-4 py-2 rounded-lg text-sm font-medium transition flex items-center gap-2"
                    >
                        <FontAwesomeIcon icon={faSearch} />
                        <span>조회</span>
                    </button>
                    <button
                        onClick={handleDownloadExcel}
                        className={`px-4 py-2 rounded-lg text-sm font-bold transition flex items-center gap-2 shadow-sm ${errorCount > 0 ? 'bg-orange-500 hover:bg-orange-600 text-white' : 'bg-green-600 hover:bg-green-700 text-white'}`}
                    >
                        <FontAwesomeIcon icon={faFileExcel} />
                        <span>엑셀 다운로드</span>
                    </button>

                    <button
                        onClick={() => openLaborCostStatement(getPrevYearMonth(toYearMonth(selectedDate) || getThisYearMonth()))}
                        className="bg-slate-700 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-slate-800 transition flex items-center gap-2 shadow-sm"
                        disabled={!filtersReady}
                    >
                        <FontAwesomeIcon icon={faPrint} />
                        <span>전달 명세서</span>
                    </button>

                    <button
                        onClick={() => openLaborCostStatement(getThisYearMonth())}
                        className="bg-slate-700 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-slate-800 transition flex items-center gap-2 shadow-sm"
                        disabled={!filtersReady}
                    >
                        <FontAwesomeIcon icon={faPrint} />
                        <span>이달 명세서</span>
                    </button>
                </div>
            </div>

            {/* Tabs */}
            <div className="flex gap-2 mb-4">
                <button
                    onClick={() => setViewTab('payment')}
                    className={`px-4 py-2 rounded-lg text-sm font-bold transition-colors ${viewTab === 'payment'
                        ? 'bg-blue-600 text-white shadow-sm'
                        : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                        }`}
                >
                    💳 지급용 (계좌정보 포함)
                </button>
                <button
                    onClick={() => setViewTab('billing')}
                    className={`px-4 py-2 rounded-lg text-sm font-bold transition-colors ${viewTab === 'billing'
                        ? 'bg-orange-600 text-white shadow-sm'
                        : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                        }`}
                >
                    📋 청구용 (공수/금액만)
                </button>
            </div>

            {errorCount > 0 && (
                <div className="mb-4 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg flex items-center gap-2 text-sm">
                    <FontAwesomeIcon icon={faExclamationTriangle} className="text-red-500" />
                    <span><strong>{errorCount}건</strong>의 데이터에 은행명, 계좌번호 또는 예금주 정보가 누락되었습니다. 확인 후 작업자 DB를 수정해주세요.</span>
                </div>
            )}

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                {/* 상단 헤더 */}
                <div className="p-4 border-b border-slate-100 bg-slate-50">
                    {/* 1행: 타이틀 + 총 공수 */}
                    <div className="flex items-center justify-between mb-3">
                        <h2 className="font-semibold text-slate-700 text-lg">지급 대상자 목록</h2>
                        <div className="flex items-center gap-2 text-sm">
                            <span className="text-slate-500 font-medium">총 공수:</span>
                            <span className="font-bold text-slate-800 text-lg">
                                {filteredPaymentData.reduce((sum, item) => sum + item.manDay, 0).toFixed(1)}
                            </span>

                            {viewTab === 'payment' && (
                                <>
                                    <span className="w-px h-4 bg-slate-300 mx-3"></span>
                                    <span className="text-brand-600 font-medium">입금액:</span>
                                    <span className="font-bold text-brand-700 text-lg">
