      <div
        id="mainContainer"
        className="w-full labor-statement-print-root"
        style={{ ['--print-scale' as string]: String(printScale) }}
      >
        <div className="mb-6 flex flex-col gap-4 lg:grid lg:grid-cols-[350px_1fr_350px] lg:items-end">
