                          value={r.unitPrice}
                          onChange={(e) => updateRow(r.id, { unitPrice: formatAmountInput(e.target.value) })}
                        />
                      </td>

                      <td
                        rowSpan={2}
                        className={`p-1 bank-cell bank-col ${isDelegate ? 'cell-delegate' : ''}`}
                      >
                        <div className="delegation-ui">
