                            <input
                              type="text"
                              className="bank-name-input text-[10px] w-1/2"
                              placeholder="은행"
                              value={bankName}
                              onChange={(e) => updateRow(r.id, { bankName: e.target.value })}
                            />
                            <input
                              type="text"
                              className="bank-owner-input text-[10px] w-1/2"
                              placeholder="예금주"
                              value={bankOwner}
                              onChange={(e) => updateRow(r.id, { bankOwner: e.target.value })}
                            />
                          </div>
                          <input
                            type="text"
                            className="bank-account-input text-[10px] pt-1"
                            placeholder="계좌번호"
                            value={bankAccount}
                            onChange={(e) => updateRow(r.id, { bankAccount: e.target.value })}
                          />
                        </div>
                      </td>
                    </tr>

                    <tr data-row-id={r.id}>
                      {Array.from({ length: SECONDARY_DAY_COUNT }, (_, i) => (
                        <td key={`d2-${r.id}-${i}`} className="p-0">
                          <input
                            type="text"
                            className={`day-input day-${i + PRIMARY_DAY_COUNT + 1}`}
                            value={r.days[i + PRIMARY_DAY_COUNT]}
                            onChange={(e) => updateRowDay(r.id, i + PRIMARY_DAY_COUNT, e.target.value)}
                          />
                        </td>
                      ))}

                      <td className="p-0">
                        <input
                          type="text"
                          className="total-price-input font-bold text-right pr-2"
                          readOnly
                          value={Number.isFinite(totalAmount) ? totalAmount.toLocaleString() : '0'}
                        />
                      </td>
                    </tr>
                  </React.Fragment>
                );
              })}
            </tbody>

            <tfoot>
              <tr className="total-row">
                <td rowSpan={2} colSpan={3} className="total-label-cell text-left font-bold pl-2">
                  합계
                </td>

                {Array.from({ length: PRIMARY_DAY_COUNT }, (_, i) => (
                  <td key={`sum-d1-${i}`} className="p-0">
                    <input type="text" className="day-input font-bold footer-summary-input" readOnly value={formatDaysTotal(statementSummary.dayTotals[i] ?? 0)} />
                  </td>
                ))}

                <td rowSpan={2} className="p-0">
                  <input type="text" className="days-total font-bold footer-summary-input footer-total-days" readOnly value={formatDaysTotal(statementSummary.totalDays)} />
                </td>

                <td className="p-0">
                  <input type="text" className="unit-price-input text-right pr-2 footer-summary-input" readOnly value="" />
                </td>

                <td rowSpan={2} className="bank-col" />
              </tr>

              <tr className="total-row">
                {Array.from({ length: SECONDARY_DAY_COUNT }, (_, i) => (
                  <td key={`sum-d2-${i}`} className="p-0">
                    <input
                      type="text"
                      className="day-input font-bold footer-summary-input"
                      readOnly
                      value={formatDaysTotal(statementSummary.dayTotals[i + PRIMARY_DAY_COUNT] ?? 0)}
                    />
