                                                                    ? activeTab === 'outgoing'
                                                                        ? 'bg-green-100 text-green-800 font-medium'
                                                                        : 'bg-red-100 text-red-800 font-medium'
                                                                    : 'text-slate-200'
                                                                    }`}
                                                            >
                                                                {manDay ? manDay.toFixed(1) : '0.0'}
                                                            </td>
                                                        );
                                                    })}
                                                    <td className="py-1.5 px-2 text-center font-bold text-slate-700 border-r border-slate-100 bg-green-50">
                                                        {worker.totalManDay.toFixed(1)}
                                                    </td>
                                                    <td className="py-1.5 px-2 text-right text-slate-600 border-r border-slate-100 bg-blue-50">
                                                        {formatCurrency(worker.unitPrice)}
                                                    </td>
                                                    <td className={`py-1.5 px-2 text-right font-bold ${activeTab === 'outgoing' ? 'text-green-700 bg-green-50' : 'text-red-700 bg-red-50'
                                                        }`}>
                                                        {formatCurrency(worker.totalAmount)}
                                                    </td>
                                                </tr>
                                            ))}
                                            {/* Site subtotal */}
                                            <tr className={`font-bold ${activeTab === 'outgoing' ? 'bg-green-100' : 'bg-red-100'}`}>
                                                <td colSpan={2} className="py-2 px-2 text-center sticky left-0 z-10" style={{ backgroundColor: activeTab === 'outgoing' ? '#dcfce7' : '#fee2e2' }}>
                                                    소계
                                                </td>
                                                {dates.map(day => {
                                                    const dayTotal = site.workers.reduce((sum, w) => sum + (w.dailyManDay[day] || 0), 0);
                                                    return (
                                                        <td key={day} className={`py-2 px-1 text-center ${dayTotal > 0 ? 'text-slate-700' : 'text-slate-300'}`}>
                                                            {dayTotal > 0 ? dayTotal.toFixed(1) : '-'}
                                                        </td>
                                                    );
                                                })}
                                                <td className="py-2 px-2 text-center text-slate-800 bg-green-200">
                                                    {site.totalManDay.toFixed(1)}
                                                </td>
                                                <td className="py-2 px-2 text-right text-slate-600 bg-blue-100">-</td>
                                                <td className={`py-2 px-2 text-right ${activeTab === 'outgoing' ? 'text-green-800' : 'text-red-800'}`}>
                                                    {formatCurrency(site.totalAmount)}
                                                </td>
                                            </tr>
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        ))}

                        {/* Grand Total */}
                        <div className={`rounded-xl p-4 ${activeTab === 'outgoing' ? 'bg-green-600' : 'bg-red-600'} text-white`}>
                            <div className="flex items-center justify-between">
                                <div className="font-bold text-lg">
                                    총합계 ({currentSites.length}현장 / {currentTotal.workers}명)
                                </div>
                                <div className="text-right">
                                    <div className="2xl font-bold">
                                        {formatCurrency(currentTotal.amount)}원
                                    </div>
                                    <div className="text-sm opacity-80">
                                        {currentTotal.manDay.toFixed(1)}공
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default LaborExchangePage;

import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
  faTable,
  faRotateRight,
  faSpinner
} from '@fortawesome/free-solid-svg-icons';
import { Square, CheckSquare } from 'lucide-react';

import { dailyReportService, DailyReport, DailyReportWorker } from '../../services/dailyReportService';
import { manpowerService, Worker } from '../../services/manpowerService';
import { teamService, Team } from '../../services/teamService';
import { siteService, Site } from '../../services/siteService';
import { advancePaymentService, AdvancePayment } from '../../services/advancePaymentService';
import { payrollConfigService, PayrollConfig } from '../../services/payrollConfigService';

// --- Types ---
type SalaryMode = 'daily' | 'monthly' | 'all';
type StatsScope = 'team' | 'worker';

type DailyDeductionInputs = {
  actualDeductionUnitPrice: number;
  billingDeductionUnitPrice: number;
  reportDeductionUnitPrice: number;
};

type MonthlyWorkEntry = {
  date: string;
  siteId: string;
  siteName: string;
  clientCompanyId: string;
  isLabor: boolean;
  manDay: number;
  unitPrice: number;
  amount: number;
};

type DeductionLine = { label: string; amount: number };

type MonthlyRow = {
  id: string; // Unique ID
  month: string;
  workerId: string;
  workerName: string;
  teamId: string;
  teamName: string;
  totalManDay: number;
  grossAmount: number;
  deductionLines: DeductionLine[];
  taxLines: DeductionLine[];
  totalDeduction: number;
  totalAmount: number;
  workEntries: MonthlyWorkEntry[];
};

type DailyLine = {
  id: string; // Unique ID
  date: string;
  teamId: string;
  teamName: string;
  workerId: string;
  workerName: string;
  manDay: number;
  originalUnitPrice: number;
  originalAmount: number;
  actualAmount: number;
  billingAmount: number;
  reportAmount: number;
  actualDeductionAmount: number;
  billingDeductionAmount: number;
  reportDeductionAmount: number;
};

// --- Helpers ---
const toNumber = (value: unknown): number => (typeof value === 'number' && Number.isFinite(value) ? value : 0);

const formatWon = (value: number): string => {
  const safe = Number.isFinite(value) ? value : 0;
  return Math.round(safe).toLocaleString('ko-KR');
};

const normalizeKey = (value: string | undefined): string =>
  (value ?? '').replace(/\(.*?\)/g, '').replace(/\s+/g, '').trim();

const compareYearMonth = (a: string, b: string): number => {
  const left = (a ?? '').trim();
  const right = (b ?? '').trim();
  if (left === right) return 0;
  return left < right ? -1 : 1;
};

const yearMonthFromDate = (date: string): string => (date ?? '').slice(0, 7);

const shiftYearMonth = (yearMonth: string, diffMonths: number): string => {
  const [yStr, mStr] = yearMonth.split('-');
  const y = Number(yStr);
  const m = Number(mStr);
  const base = new Date(Number.isFinite(y) ? y : new Date().getFullYear(), (Number.isFinite(m) ? m : 1) - 1, 1);
  base.setMonth(base.getMonth() + diffMonths);
  const yyyy = String(base.getFullYear());
  const mm = String(base.getMonth() + 1).padStart(2, '0');
  return `${yyyy}-${mm}`;
};

const buildMonthRange = (start: string, end: string): string[] => {
  const safeStart = (start ?? '').trim();
  const safeEnd = (end ?? '').trim();
  if (!safeStart || !safeEnd) return [];

  const from = compareYearMonth(safeStart, safeEnd) <= 0 ? safeStart : safeEnd;
  const to = compareYearMonth(safeStart, safeEnd) <= 0 ? safeEnd : safeStart;

  const result: string[] = [];
  let cursor = from;

  for (let i = 0; i < 240; i += 1) {
    result.push(cursor);
    if (cursor === to) break;
    cursor = shiftYearMonth(cursor, 1);
  }

  return result;
};

const resolveSalaryModel = (rw: DailyReportWorker, worker: Worker | undefined): string => {
  const a = typeof rw.salaryModel === 'string' ? rw.salaryModel.trim() : '';
  if (a) return a;
  const b = typeof rw.payType === 'string' ? rw.payType.trim() : '';
  if (b) return b;
  const c = typeof worker?.salaryModel === 'string' ? worker.salaryModel.trim() : '';
  if (c) return c;
  const d = typeof worker?.payType === 'string' ? worker.payType.trim() : '';
  return d;
};

const getAdvanceValue = (record: AdvancePayment, key: string): number => {
  const raw = (record as unknown as Record<string, unknown>)[key];
  if (typeof raw === 'number' && Number.isFinite(raw)) return raw;
  const items = record.items;
  const maybe = items?.[key];
  if (typeof maybe === 'number' && Number.isFinite(maybe)) return maybe;
  return 0;
};

const PayrollStatisticsPage: React.FC = () => {
  const now = new Date();
  const today = now.toISOString().slice(0, 10);
  const defaultStartDate = useMemo(() => {
    const d = new Date(now);
    d.setDate(d.getDate() - 14);
    return d.toISOString().slice(0, 10);
  }, []);

  const currentYearMonth = useMemo(() => {
    const yyyy = String(now.getFullYear());
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    return `${yyyy}-${mm}`;
  }, []);

  // --- State ---
  const [salaryMode, setSalaryMode] = useState<SalaryMode>('daily');

  const [loading, setLoading] = useState(false);
  const [errorText, setErrorText] = useState('');

  const [teams, setTeams] = useState<Team[]>([]);
  const [workers, setWorkers] = useState<Worker[]>([]);
  const [sites, setSites] = useState<Site[]>([]);

  // Filter State
  const [selectedSiteId, setSelectedSiteId] = useState('');
  const [selectedTeamId, setSelectedTeamId] = useState('');
  const [selectedWorkerId, setSelectedWorkerId] = useState('');

  const [dailyStartDate, setDailyStartDate] = useState(defaultStartDate);
  const [dailyEndDate, setDailyEndDate] = useState(today);

  const [monthlyStartMonth, setMonthlyStartMonth] = useState(currentYearMonth);
  const [monthlyEndMonth, setMonthlyEndMonth] = useState(currentYearMonth);

  const [dailyDeductionInputs, setDailyDeductionInputs] = useState<DailyDeductionInputs>({
    actualDeductionUnitPrice: 0,
    billingDeductionUnitPrice: 0,
    reportDeductionUnitPrice: 0
  });

  const [applyInsurance, setApplyInsurance] = useState(true);
  const [applyBusinessIncome, setApplyBusinessIncome] = useState(true);

  const [payrollConfig, setPayrollConfig] = useState<PayrollConfig | null>(null);

  // Data State
  const [dailyLines, setDailyLines] = useState<DailyLine[]>([]);
  const [monthlyRows, setMonthlyRows] = useState<MonthlyRow[]>([]);

  // Selection State (Set of IDs)
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // --- Init Data ---
  useEffect(() => {
    const init = async () => {
      try {
        const [t, w, s] = await Promise.all([teamService.getTeams(), manpowerService.getWorkers(), siteService.getSites()]);
        setTeams(t);
        setWorkers(w);
        setSites(s);
        const config = await payrollConfigService.getConfig();
        setPayrollConfig(config);
      } catch (e) {
        console.error(e);
      }
    };
    init();
  }, []);

  // --- Memos (Maps) ---
  const workerMap = useMemo(() => {
    const map = new Map<string, Worker>();
    workers.forEach((w) => {
      if (w.id) map.set(w.id, w);
    });
    return map;
  }, [workers]);

  const teamMap = useMemo(() => {
    const map = new Map<string, Team>();
    teams.forEach((t) => {
      if (t.id) map.set(t.id, t);
    });
    return map;
  }, [teams]);

  const siteMap = useMemo(() => {
    const map = new Map<string, Site>();
    sites.forEach((s) => {
      if (s.id) map.set(s.id, s);
      if (s.legacyId) map.set(s.legacyId, s);
    });
    return map;
  }, [sites]);

  // --- Selection Logic ---
  const toggleSelectAll = (checked: boolean) => {
    if (checked) {
      const allIds = salaryMode === 'daily'
        ? dailyLines.map(r => r.id)
        : monthlyRows.map(r => r.id);
      setSelectedIds(new Set(allIds));
    } else {
      setSelectedIds(new Set());
    }
  };

  const toggleSelectRow = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const isAllSelected = useMemo(() => {
    const currentList = salaryMode === 'daily' ? dailyLines : monthlyRows;
    if (currentList.length === 0) return false;
    return currentList.every(r => selectedIds.has(r.id));
  }, [salaryMode, dailyLines, monthlyRows, selectedIds]);

  // --- Fetch Logic ---
  const fetchDaily = useCallback(async () => {
    if (!dailyStartDate || !dailyEndDate) return;
    setLoading(true);
    setErrorText('');
    setDailyLines([]);
    setSelectedIds(new Set());

    try {
      const reports = await dailyReportService.getReportsByRange(
        dailyStartDate,
        dailyEndDate,
        selectedTeamId || undefined,
        selectedSiteId || undefined
      );

      const lines: DailyLine[] = [];
      reports.forEach((report) => {
        report.workers.forEach((rw) => {
          if (!rw) return;
          if (selectedWorkerId && rw.workerId !== selectedWorkerId) return;

          const worker = workerMap.get(rw.workerId);
          const model = resolveSalaryModel(rw, worker);
          if (model !== '일급제') return;

          const manDay = toNumber(rw.manDay);
          const originalUnitPrice = toNumber(rw.unitPrice ?? worker?.unitPrice ?? 0);
          const originalAmount = manDay * originalUnitPrice;

          const actualUnitPrice = originalUnitPrice - dailyDeductionInputs.actualDeductionUnitPrice;
          const billingUnitPrice = originalUnitPrice - dailyDeductionInputs.billingDeductionUnitPrice;
          const reportUnitPrice = originalUnitPrice - dailyDeductionInputs.reportDeductionUnitPrice;

          const actualAmount = manDay * actualUnitPrice;
          const billingAmount = manDay * billingUnitPrice;
          const reportAmount = manDay * reportUnitPrice;

          lines.push({
            id: `${report.date}_${rw.workerId}_${report.teamId}_${Math.random()}`,
            date: report.date,
            teamId: report.teamId,
            teamName: report.teamName || '',
            workerId: rw.workerId,
            workerName: rw.name,
            manDay,
            originalUnitPrice,
            originalAmount,
            actualAmount,
            billingAmount,
            reportAmount,
            actualDeductionAmount: originalAmount - actualAmount,
            billingDeductionAmount: originalAmount - billingAmount,
            reportDeductionAmount: originalAmount - reportAmount
          });
        });
      });

      lines.sort((a, b) => b.date.localeCompare(a.date));
      setDailyLines(lines);
    } catch (e) {
      console.error(e);
      setErrorText('일급제 데이터 로드 실패');
    } finally {
      setLoading(false);
    }
  }, [dailyStartDate, dailyEndDate, selectedTeamId, selectedSiteId, selectedWorkerId, workerMap, dailyDeductionInputs]);

  const buildMonthlyTaxLines = useCallback(
    (config: PayrollConfig, entries: MonthlyWorkEntry[]): DeductionLine[] => {
      const safeThreshold = Math.max(0, Math.floor(toNumber(config.insuranceConfig?.thresholdDays)));
      const insuranceConfig = config.insuranceConfig;

      const laborEntries = entries.filter((e) => e.isLabor);

      const perSite = new Map<string, { manDay: number; amount: number; clientCompanyId: string; siteName: string }>();
      laborEntries.forEach((e) => {
        const prev = perSite.get(e.siteId) ?? { manDay: 0, amount: 0, clientCompanyId: e.clientCompanyId, siteName: e.siteName };
        perSite.set(e.siteId, {
          manDay: prev.manDay + toNumber(e.manDay),
          amount: prev.amount + toNumber(e.amount),
          clientCompanyId: (e.clientCompanyId ?? prev.clientCompanyId).trim(),
          siteName: (e.siteName ?? prev.siteName).trim()
        });
      });

      const perClient = new Map<string, { manDay: number; siteIds: Set<string> }>();
      perSite.forEach((v, siteId) => {
        const clientId = (v.clientCompanyId ?? '').trim();
        if (!clientId) return;
        const prev = perClient.get(clientId) ?? { manDay: 0, siteIds: new Set<string>() };
        prev.siteIds.add(siteId);
        perClient.set(clientId, { manDay: prev.manDay + v.manDay, siteIds: prev.siteIds });
      });

      const insuranceSiteIds = new Set<string>();
      if (applyInsurance && safeThreshold > 0) {
        perSite.forEach((v, siteId) => {
          if (v.manDay >= safeThreshold) insuranceSiteIds.add(siteId);
        });

        perClient.forEach((v, clientId) => {
          if (v.manDay < safeThreshold) return;
          v.siteIds.forEach((siteId) => insuranceSiteIds.add(siteId));
          const direct = Array.from(perSite.entries()).filter(([_, s]) => s.clientCompanyId === clientId);
          direct.forEach(([siteId]) => insuranceSiteIds.add(siteId));
        });
      }

      const insuranceBaseAmount = applyInsurance
        ? Array.from(perSite.entries()).reduce((sum, [siteId, v]) => sum + (insuranceSiteIds.has(siteId) ? v.amount : 0), 0)
        : 0;

      const allAmount = entries.reduce((sum, e) => sum + toNumber(e.amount), 0);
      const businessBaseAmount = applyBusinessIncome ? (allAmount - insuranceBaseAmount) : 0;

      const lines: DeductionLine[] = [];

      if (applyInsurance && insuranceBaseAmount > 0) {
        const pension = Math.floor(insuranceBaseAmount * toNumber(insuranceConfig?.pensionRate));
        const health = Math.floor(insuranceBaseAmount * toNumber(insuranceConfig?.healthRate));
        const care = Math.floor(health * toNumber(insuranceConfig?.careRateOfHealth));
        const employment = Math.floor(insuranceBaseAmount * toNumber(insuranceConfig?.employmentRate));

        if (pension > 0) lines.push({ label: '국민연금', amount: pension });
        if (health > 0) lines.push({ label: '건강보험', amount: health });
        if (care > 0) lines.push({ label: '장기요양', amount: care });
        if (employment > 0) lines.push({ label: '고용보험', amount: employment });

        const incomeTax = Math.floor(insuranceBaseAmount * toNumber(config.incomeTaxRate));
        const residentTax = Math.floor(insuranceBaseAmount * toNumber(config.residentTaxRate));
        if (incomeTax > 0) lines.push({ label: '근로소득세', amount: incomeTax });
        if (residentTax > 0) lines.push({ label: '지방소득세', amount: residentTax });
      }

      if (applyBusinessIncome && businessBaseAmount > 0) {
        const income = Math.floor(businessBaseAmount * 0.03);
        const resident = Math.floor(businessBaseAmount * 0.003);
        if (income > 0) lines.push({ label: '사업소득세', amount: income });
        if (resident > 0) lines.push({ label: '사업지방세', amount: resident });
      }

      return lines;
    },
    [applyBusinessIncome, applyInsurance]
  );

  const fetchMonthly = useCallback(async () => {
    if (!monthlyStartMonth || !monthlyEndMonth) return;
    const monthRange = buildMonthRange(monthlyStartMonth, monthlyEndMonth);
    if (monthRange.length === 0) return;

    setLoading(true);
    setErrorText('');
    setMonthlyRows([]);
    setSelectedIds(new Set());

    try {
      const config = payrollConfig ?? (await payrollConfigService.getConfig());
      if (!payrollConfig) setPayrollConfig(config);

      const safeStart = compareYearMonth(monthlyStartMonth, monthlyEndMonth) <= 0 ? monthlyStartMonth : monthlyEndMonth;
      const safeEnd = compareYearMonth(monthlyStartMonth, monthlyEndMonth) <= 0 ? monthlyEndMonth : monthlyStartMonth;
      const [endYearStr, endMonthStr] = safeEnd.split('-');
      const lastDay = new Date(Number(endYearStr), Number(endMonthStr), 0).getDate();
      const startDate = `${safeStart}-01`;
      const endDate = `${safeEnd}-${String(lastDay).padStart(2, '0')}`;

      const reports = await dailyReportService.getReportsByRange(startDate, endDate, selectedTeamId || undefined, selectedSiteId || undefined);

      const advancesByMonth = new Map<string, AdvancePayment[]>();
      await Promise.all(
        monthRange.map(async (month) => {
          const [y, m] = month.split('-').map(Number);
          if (!Number.isFinite(y)) return;
          const rows = await advancePaymentService.getAdvancePaymentsByYearMonth(y, m);
          advancesByMonth.set(month, rows);
        })
      );

      const advanceIndex = new Map<string, AdvancePayment[]>();
      advancesByMonth.forEach((rows) => {
        rows.forEach((row) => {
          const wid = (row.workerId || '').trim();
          const tid = (row.teamId || '').trim();
          if (wid) {
            const key = `${wid}__${tid || '-'}`;
            const prev = advanceIndex.get(key) ?? [];
            prev.push(row);
            advanceIndex.set(key, prev);
          }
        });
      });

      const agg = new Map<string, {
        month: string, workerId: string, teamId: string, teamName: string,
        totalManDay: number, grossAmount: number, workEntries: MonthlyWorkEntry[]
      }>();

      const resolveTeamName = (teamId: string, fallback: string) => {
        return teamMap.get(teamId)?.name || fallback;
      };

      reports.forEach((report) => {
        const month = yearMonthFromDate(report.date);
        if (!monthRange.includes(month)) return;

        report.workers.forEach((rw) => {
          if (!rw) return;
          if (selectedWorkerId && rw.workerId !== selectedWorkerId) return;
          const worker = workerMap.get(rw.workerId);
          if (resolveSalaryModel(rw, worker) !== '월급제') return;

          const teamId = (worker?.teamId || report.teamId || '').trim();
          const teamName = resolveTeamName(teamId, report.teamName || '');
          const manDay = toNumber(rw.manDay);
          const amount = manDay * toNumber(rw.unitPrice ?? worker?.unitPrice ?? 0);

          const key = `${month}__${rw.workerId}__${teamId || '-'}`;
          const prev = agg.get(key) ?? {
            month, workerId: rw.workerId, teamId, teamName,
            totalManDay: 0, grossAmount: 0, workEntries: []
          };

          agg.set(key, {
            ...prev,
            totalManDay: prev.totalManDay + manDay,
            grossAmount: prev.grossAmount + amount,
            workEntries: [...prev.workEntries, {
              date: report.date,
              siteId: report.siteId,
              siteName: report.siteName || '',
              clientCompanyId: (siteMap.get(report.siteId)?.clientCompanyId || '').trim(),
              isLabor: (siteMap.get(report.siteId)?.paymentMethod || '').trim() === '노무',
              manDay,
              unitPrice: toNumber(rw.unitPrice),
              amount
            }]
          });
        });
      });

      const rows: MonthlyRow[] = [];
      agg.forEach((v) => {
        const worker = workerMap.get(v.workerId);
        if (!worker) return;

        const advKey = `${v.workerId}__${v.teamId || '-'}`;
        const records = advanceIndex.get(advKey) ?? advanceIndex.get(`${v.workerId}__-`) ?? [];

        const deductionLines: DeductionLine[] = [];
        (config.deductionItems || []).forEach(item => {
          const sum = records.reduce((acc, r) => acc + getAdvanceValue(r, item.id), 0);
          if (sum > 0) deductionLines.push({ label: item.label, amount: sum });
        });

        const taxLines = buildMonthlyTaxLines(config, v.workEntries);
        const totalDeduction = [...deductionLines, ...taxLines].reduce((acc, l) => acc + l.amount, 0);

        rows.push({
          id: `${v.month}_${v.workerId}`,
          month: v.month,
          workerId: v.workerId,
          workerName: worker.name,
          teamId: v.teamId,
          teamName: v.teamName,
          totalManDay: v.totalManDay,
          grossAmount: v.grossAmount,
          deductionLines,
          taxLines,
          totalDeduction,
          totalAmount: v.grossAmount - totalDeduction,
          workEntries: v.workEntries
        });
      });

      rows.sort((a, b) => b.month.localeCompare(a.month)); // Sort by month desc
      setMonthlyRows(rows);

    } catch (e) {
      console.error(e);
      setErrorText('월급제 데이터 로드 실패');
    } finally {
      setLoading(false);
    }
  }, [monthlyEndMonth, monthlyStartMonth, selectedTeamId, selectedSiteId, selectedWorkerId, payrollConfig, buildMonthlyTaxLines, workerMap, teamMap, siteMap]);

  const handleRefresh = useCallback(() => {
    if (salaryMode === 'daily') void fetchDaily();
    else if (salaryMode === 'monthly') void fetchMonthly();
    else {
      void fetchDaily();
      void fetchMonthly();
    }
  }, [salaryMode, fetchDaily, fetchMonthly]);

  // --- Statistics ---
  const activeDailyData = useMemo(() => {
    if (salaryMode !== 'daily') return [];
    if (selectedIds.size > 0) return dailyLines.filter(r => selectedIds.has(r.id));
    return dailyLines;
  }, [dailyLines, selectedIds, salaryMode]);

  const activeMonthlyData = useMemo(() => {
    if (salaryMode !== 'monthly') return [];
    if (selectedIds.size > 0) return monthlyRows.filter(r => selectedIds.has(r.id));
    return monthlyRows;
  }, [monthlyRows, selectedIds, salaryMode]);

  const stats = useMemo(() => {
    const d = activeDailyData.reduce((acc, c) => ({
      manDay: acc.manDay + c.manDay,
      gross: acc.gross + c.originalAmount,
      deduction: acc.deduction + c.actualDeductionAmount,
      net: acc.net + c.actualAmount
    }), { manDay: 0, gross: 0, deduction: 0, net: 0 });

    const m = activeMonthlyData.reduce((acc, c) => ({
      manDay: acc.manDay + c.totalManDay,
      gross: acc.gross + c.grossAmount,
      deduction: acc.deduction + c.totalDeduction,
      net: acc.net + c.totalAmount
    }), { manDay: 0, gross: 0, deduction: 0, net: 0 });

    if (salaryMode === 'daily') return d;
    if (salaryMode === 'monthly') return m;

    return {
      manDay: d.manDay + m.manDay,
      gross: d.gross + m.gross,
      deduction: d.deduction + m.deduction,
      net: d.net + m.net
    };
  }, [salaryMode, activeDailyData, activeMonthlyData]);

  const selectedCount = selectedIds.size;
  const isSelectionActive = selectedCount > 0;

  return (
    <div className="h-full bg-[#f8fafc] flex flex-col">
      {/* 1. Header & Controls */}
      <div className="bg-white border-b border-slate-200 px-6 py-4 flex-shrink-0">
        <div className="flex items-center justify-between gap-4 mb-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-indigo-50 text-indigo-600 flex items-center justify-center">
              <FontAwesomeIcon icon={faTable} className="text-lg" />
            </div>
            <div>
              <h1 className="text-xl font-extrabold text-slate-800">급여/노임 통계</h1>
              <p className="text-xs text-slate-500 font-bold">
                {salaryMode === 'daily' ? '일급제' : salaryMode === 'monthly' ? '월급제' : '전체내역'} 근로자의 급여 정보를 분석합니다.
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button
                onClick={() => { setSalaryMode('daily'); setSelectedIds(new Set()); }}
                className={`px-3 py-1.5 text-xs font-extrabold rounded-md transition-all ${salaryMode === 'daily' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
              >일급제</button>
              <button
                onClick={() => { setSalaryMode('monthly'); setSelectedIds(new Set()); }}
                className={`px-3 py-1.5 text-xs font-extrabold rounded-md transition-all ${salaryMode === 'monthly' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
              >월급제</button>
              <button
                onClick={() => { setSalaryMode('all'); setSelectedIds(new Set()); }}
                className={`px-3 py-1.5 text-xs font-extrabold rounded-md transition-all ${salaryMode === 'all' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
              >전체내역</button>
            </div>
            <button
              onClick={handleRefresh}
              className="px-3 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-sm font-bold flex items-center gap-2 transition-colors shadow-sm shadow-indigo-200"
            >
              <FontAwesomeIcon icon={loading ? faSpinner : faRotateRight} className={loading ? "animate-spin" : ""} />
              {loading ? '로딩...' : '조회'}
            </button>
          </div>
        </div>

        {/* Filters Grid */}
        <div className="grid grid-cols-1 md:grid-cols-4 lg:grid-cols-6 gap-3">
          <div className="flex flex-col gap-1">
            <label className="text-[10px] font-bold text-slate-500">기간 설정</label>
            {(salaryMode === 'daily' || salaryMode === 'all') ? (
              <div className="flex gap-1 items-center">
                <input type="date" value={dailyStartDate} onChange={e => setDailyStartDate(e.target.value)} className="w-full text-xs font-bold border border-slate-200 rounded p-1.5" />
                <span className="text-slate-400">~</span>
                <input type="date" value={dailyEndDate} onChange={e => setDailyEndDate(e.target.value)} className="w-full text-xs font-bold border border-slate-200 rounded p-1.5" />
              </div>
            ) : (
              <div className="flex gap-1 items-center">
                <input type="month" value={monthlyStartMonth} onChange={e => setMonthlyStartMonth(e.target.value)} className="w-full text-xs font-bold border border-slate-200 rounded p-1.5" />
                <span className="text-slate-400">~</span>
                <input type="month" value={monthlyEndMonth} onChange={e => setMonthlyEndMonth(e.target.value)} className="w-full text-xs font-bold border border-slate-200 rounded p-1.5" />
              </div>
            )}
          </div>

          <div className="flex flex-col gap-1">
            <label className="text-[10px] font-bold text-slate-500">현장</label>
            <select value={selectedSiteId} onChange={e => setSelectedSiteId(e.target.value)} className="text-xs font-bold border border-slate-200 rounded p-1.5 bg-white">
              <option value="">전체 현장</option>
              {sites.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
          </div>

          <div className="flex flex-col gap-1">
            <label className="text-[10px] font-bold text-slate-500">팀</label>
            <select value={selectedTeamId} onChange={e => setSelectedTeamId(e.target.value)} className="text-xs font-bold border border-slate-200 rounded p-1.5 bg-white">
              <option value="">전체 팀</option>
              {teams.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>
          </div>

          <div className="flex flex-col gap-1">
            <label className="text-[10px] font-bold text-slate-500">작업자</label>
            <select value={selectedWorkerId} onChange={e => setSelectedWorkerId(e.target.value)} className="text-xs font-bold border border-slate-200 rounded p-1.5 bg-white">
              <option value="">전체 작업자</option>
              {workers.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
            </select>
          </div>

          {/* Deduction Inputs for Daily / All */}
          {(salaryMode === 'daily' || salaryMode === 'all') && (
            <>
              <div className="flex flex-col gap-1">
                <label className="text-[10px] font-bold text-slate-500">단가 일괄차감 (지급)</label>
                <input type="number" value={dailyDeductionInputs.actualDeductionUnitPrice} onChange={e => setDailyDeductionInputs(p => ({ ...p, actualDeductionUnitPrice: Number(e.target.value) }))} className="text-xs font-bold border border-slate-200 rounded p-1.5" placeholder="0" />
              </div>
            </>
          )}
        </div>
      </div>

      {/* 2. Selection Summary Dashboard (Sticky) */}
      <div className="bg-slate-50 border-b border-indigo-100 px-6 py-4 grid grid-cols-2 md:grid-cols-4 gap-4 flex-shrink-0">
        <div className="bg-white p-3 rounded-xl border border-slate-200 shadow-sm flex flex-col items-center justify-center relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-1 bg-indigo-500"></div>
          <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">
            {isSelectionActive ? `선택된 항목 (${selectedCount})` : '전체 합계'}
          </p>
          <p className="text-lg font-extrabold text-slate-800">
            {currentYearMonth} {salaryMode === 'daily' ? '일급' : salaryMode === 'monthly' ? '월급' : '전체'}
          </p>
        </div>

        <div className="bg-white p-3 rounded-xl border border-slate-200 shadow-sm flex flex-col items-center justify-center relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-1 bg-slate-400"></div>
          <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">총 공수</p>
          <p className="text-xl font-extrabold text-slate-700">{stats.manDay.toFixed(1)} <span className="text-xs font-semibold text-slate-400">공수</span></p>
        </div>

        <div className="bg-white p-3 rounded-xl border border-slate-200 shadow-sm flex flex-col items-center justify-center relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-1 bg-rose-400"></div>
          <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">총 공제액 (지급차감)</p>
          <p className="text-xl font-extrabold text-rose-600">{formatWon(stats.deduction)} <span className="text-xs font-semibold text-rose-300">원</span></p>
        </div>

        <div className="bg-white p-3 rounded-xl border border-slate-200 shadow-sm flex flex-col items-center justify-center relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-1 bg-emerald-500"></div>
          <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">실지급 총액</p>
          <p className="text-2xl font-black text-emerald-600 drop-shadow-sm">{formatWon(stats.net)} <span className="text-xs font-semibold text-emerald-300">원</span></p>
        </div>
      </div>

      {/* 3. Table Area */}
      <div className="flex-1 p-4 w-full h-full min-h-0 overflow-y-auto custom-scrollbar">
        <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 sticky top-0 z-10">
              <tr className="divide-x divide-slate-100 border-b border-slate-200">
                <th className="px-3 py-3 w-12 text-center">
                  <button onClick={() => toggleSelectAll(!isAllSelected)} className="text-slate-400 hover:text-indigo-600">
                    {isAllSelected ? <CheckSquare className="w-5 h-5 text-indigo-600" /> : <Square className="w-5 h-5" />}
                  </button>
                </th>
                {salaryMode === 'daily' ? (
                  <>
                    <th className="px-3 py-3 text-left font-extrabold text-slate-500 text-xs uppercase">날짜</th>
                    <th className="px-3 py-3 text-left font-extrabold text-slate-500 text-xs uppercase">팀</th>
                    <th className="px-3 py-3 text-left font-extrabold text-slate-500 text-xs uppercase">작업자</th>
                    <th className="px-3 py-3 text-right font-extrabold text-slate-500 text-xs uppercase">공수</th>
                    <th className="px-3 py-3 text-right font-extrabold text-slate-500 text-xs uppercase">총액</th>
                    <th className="px-3 py-3 text-right font-extrabold text-slate-500 text-xs uppercase">지급차감</th>
                    <th className="px-3 py-3 text-right font-extrabold text-slate-500 text-xs uppercase">실지급액</th>
                  </>
                ) : salaryMode === 'monthly' ? (
                  <>
                    <th className="px-3 py-3 text-left font-extrabold text-slate-500 text-xs uppercase">월</th>
                    <th className="px-3 py-3 text-left font-extrabold text-slate-500 text-xs uppercase">팀</th>
                    <th className="px-3 py-3 text-left font-extrabold text-slate-500 text-xs uppercase">작업자</th>
                    <th className="px-3 py-3 text-right font-extrabold text-slate-500 text-xs uppercase">총 공수</th>
                    <th className="px-3 py-3 text-right font-extrabold text-slate-500 text-xs uppercase">총액</th>
                    <th className="px-3 py-3 text-right font-extrabold text-slate-500 text-xs uppercase">총 공제</th>
                    <th className="px-3 py-3 text-right font-extrabold text-slate-500 text-xs uppercase">실지급액</th>
                  </>
                ) : (
                  <>
                    <th className="px-3 py-3 text-left font-extrabold text-slate-500 text-xs uppercase">구분</th>
                    <th className="px-3 py-3 text-left font-extrabold text-slate-500 text-xs uppercase">날짜/월</th>
                    <th className="px-3 py-3 text-left font-extrabold text-slate-500 text-xs uppercase">팀</th>
                    <th className="px-3 py-3 text-left font-extrabold text-slate-500 text-xs uppercase">작업자</th>
                    <th className="px-3 py-3 text-right font-extrabold text-slate-500 text-xs uppercase">공수</th>
                    <th className="px-3 py-3 text-right font-extrabold text-slate-500 text-xs uppercase">총액</th>
                    <th className="px-3 py-3 text-right font-extrabold text-slate-500 text-xs uppercase">공제액</th>
                    <th className="px-3 py-3 text-right font-extrabold text-slate-500 text-xs uppercase">실지급액</th>
                  </>
                )}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {loading ? (
                <tr>
                  <td colSpan={8} className="px-4 py-8 text-center text-slate-400 font-bold">
                    로딩 중입니다...
                  </td>
                </tr>
              ) : (
                salaryMode === 'daily' ? (
                  dailyLines.length === 0 ? (
                    <tr><td colSpan={8} className="px-4 py-8 text-center text-slate-400 font-bold">조회된 내역이 없습니다.</td></tr>
                  ) : (
                    dailyLines.map((row) => {
                      const isSelected = selectedIds.has(row.id);
                      return (
                        <tr key={row.id} className={`hover:bg-indigo-50/30 transition-colors cursor-pointer ${isSelected ? 'bg-indigo-50/40' : ''}`} onClick={() => toggleSelectRow(row.id)}>
                          <td className="px-3 py-3 text-center">
                            <button className={`${isSelected ? 'text-indigo-600' : 'text-slate-300'}`}>
                              {isSelected ? <CheckSquare className="w-5 h-5" /> : <Square className="w-5 h-5" />}
                            </button>
                          </td>
                          <td className="px-3 py-3 font-bold text-slate-600">{row.date}</td>
                          <td className="px-3 py-3 font-medium text-slate-500">{row.teamName}</td>
                          <td className="px-3 py-3 font-bold text-slate-700">{row.workerName}</td>
                          <td className="px-3 py-3 text-right font-bold text-slate-600">{row.manDay.toFixed(1)}</td>
                          <td className="px-3 py-3 text-right font-medium text-slate-400">{formatWon(row.originalAmount)}</td>
                          <td className="px-3 py-3 text-right font-medium text-rose-400">{formatWon(row.actualDeductionAmount)}</td>
                          <td className="px-3 py-3 text-right font-extrabold text-emerald-600">{formatWon(row.actualAmount)}</td>
                        </tr>
                      );
                    })
                  )
                ) : salaryMode === 'monthly' ? (
                  monthlyRows.length === 0 ? (
                    <tr><td colSpan={8} className="px-4 py-8 text-center text-slate-400 font-bold">조회된 내역이 없습니다.</td></tr>
                  ) : (
                    monthlyRows.map((row) => {
                      const isSelected = selectedIds.has(row.id);
                      return (
                        <tr key={row.id} className={`hover:bg-indigo-50/30 transition-colors cursor-pointer ${isSelected ? 'bg-indigo-50/40' : ''}`} onClick={() => toggleSelectRow(row.id)}>
                          <td className="px-3 py-3 text-center">
                            <button className={`${isSelected ? 'text-indigo-600' : 'text-slate-300'}`}>
                              {isSelected ? <CheckSquare className="w-5 h-5" /> : <Square className="w-5 h-5" />}
                            </button>
                          </td>
                          <td className="px-3 py-3 font-bold text-slate-600">{row.month}</td>
                          <td className="px-3 py-3 font-medium text-slate-500">{row.teamName}</td>
                          <td className="px-3 py-3 font-bold text-slate-700">{row.workerName}</td>
                          <td className="px-3 py-3 text-right font-bold text-slate-600">{row.totalManDay.toFixed(1)}</td>
                          <td className="px-3 py-3 text-right font-medium text-slate-400">{formatWon(row.grossAmount)}</td>
                          <td className="px-3 py-3 text-right font-medium text-rose-400">{formatWon(row.totalDeduction)}</td>
                          <td className="px-3 py-3 text-right font-extrabold text-emerald-600">{formatWon(row.totalAmount)}</td>
                        </tr>
                      );
                    })
                  )
                ) : (
                  // mode: ALL
                  (() => {
                    const unified = [
                      ...dailyLines.map(d => ({ ...d, type: '일급' as const, time: d.date, manDay: d.manDay, gross: d.originalAmount, deduction: d.actualDeductionAmount, net: d.actualAmount })),
                      ...monthlyRows.map(m => ({ ...m, type: '월급' as const, time: m.month, manDay: m.totalManDay, gross: m.grossAmount, deduction: m.totalDeduction, net: m.totalAmount }))
                    ].sort((a, b) => b.time.localeCompare(a.time));

                    if (unified.length === 0) {
                      return <tr><td colSpan={9} className="px-4 py-8 text-center text-slate-400 font-bold">조회된 내역이 없습니다.</td></tr>;
                    }

                    return unified.map((row) => {
                      const isSelected = selectedIds.has(row.id);
                      return (
                        <tr key={row.id} className={`hover:bg-indigo-50/30 transition-colors cursor-pointer ${isSelected ? 'bg-indigo-50/40' : ''}`} onClick={() => toggleSelectRow(row.id)}>
                          <td className="px-3 py-3 text-center">
                            <button className={`${isSelected ? 'text-indigo-600' : 'text-slate-300'}`}>
                              {isSelected ? <CheckSquare className="w-5 h-5" /> : <Square className="w-5 h-5" />}
                            </button>
                          </td>
                          <td className="px-3 py-3">
                            <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${row.type === '일급' ? 'bg-amber-100 text-amber-700' : 'bg-blue-100 text-blue-700'}`}>
                              {row.type}
                            </span>
                          </td>
                          <td className="px-3 py-3 font-bold text-slate-600">{row.time}</td>
                          <td className="px-3 py-3 font-medium text-slate-500">{row.teamName}</td>
                          <td className="px-3 py-3 font-bold text-slate-700">{row.workerName}</td>
                          <td className="px-3 py-3 text-right font-bold text-slate-600">{row.manDay.toFixed(1)}</td>
                          <td className="px-3 py-3 text-right font-medium text-slate-400">{formatWon(row.gross)}</td>
                          <td className="px-3 py-3 text-right font-medium text-rose-400">{formatWon(row.deduction)}</td>
                          <td className="px-3 py-3 text-right font-extrabold text-emerald-600">{formatWon(row.net)}</td>
                        </tr>
                      );
                    });
                  })()
                )
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default PayrollStatisticsPage;

import React, { useState, useEffect, useRef } from 'react';
import { dailyReportService } from '../../services/dailyReportService';
import { siteService } from '../../services/siteService';
import { manpowerService } from '../../services/manpowerService';
import { payrollService, PayrollData } from '../../services/payrollService';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faFileExcel, faSpinner, faSearch, faPrint, faChevronDown, faCheck } from '@fortawesome/free-solid-svg-icons';
import ExcelJS from 'exceljs';
import { saveAs } from 'file-saver';

interface WorkerData {
    id: string;
    name: string;
    juminId: string;
    address: string;
    category: string;
    bankName: string;
    accountNumber: string;
    phone: string;
}

interface InvoiceItem {
    workerId: string;
    workerName: string;
    juminId: string;
    address: string;
    category: string;
    days: number[]; // 1-31
    totalDays: number;
    unitPrice: number;
    totalAmount: number;
    bankName: string;
    accountNumber: string;
    phone: string;
}

interface Props {
    hideHeader?: boolean;
}

const SiteLaborCostInvoice: React.FC<Props> = ({ hideHeader }) => {
    const [loading, setLoading] = useState(false);
    const [sites, setSites] = useState<{ id: string; name: string }[]>([]);
    const [selectedSiteId, setSelectedSiteId] = useState('');
    const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));

    // Popup states
    const [sitePopupOpen, setSitePopupOpen] = useState(false);
    const [monthPopupOpen, setMonthPopupOpen] = useState(false);
    const sitePopupRef = useRef<HTMLDivElement>(null);
    const monthPopupRef = useRef<HTMLDivElement>(null);

    // Use PayrollData type from service
    const [invoiceData, setInvoiceData] = useState<PayrollData[]>([]);
    const [dailyDetails, setDailyDetails] = useState<{ [key: string]: number[] }>({}); // workerId -> days array
    const [isSearched, setIsSearched] = useState(false);

    // Click outside to close popup
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (sitePopupRef.current && !sitePopupRef.current.contains(e.target as Node)) {
                setSitePopupOpen(false);
            }
            if (monthPopupRef.current && !monthPopupRef.current.contains(e.target as Node)) {
                setMonthPopupOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    useEffect(() => {
        loadSites();
    }, []);

    const loadSites = async () => {
        try {
            const siteList = await siteService.getSites();
            const formattedSites = siteList.map(site => ({
                id: site.id || '',
                name: site.name
            }));
            setSites(formattedSites);
            if (formattedSites.length > 0) setSelectedSiteId(formattedSites[0].id);
        } catch (error) {
            console.error("Error loading sites:", error);
        }
    };

    const fetchData = async () => {
        if (!selectedSiteId || !selectedMonth) {
            alert("현장과 월을 선택해주세요.");
            return null;
        }

        setLoading(true);
        try {
            const [yearStr, monthStr] = selectedMonth.split('-');
            const year = parseInt(yearStr);
            const month = parseInt(monthStr);

            // 1. Fetch Payroll Data (Aggregated)
            const payrollList = await payrollService.getPayrollData(year, month, undefined, selectedSiteId);

            // 2. Fetch Daily Details (for the days grid)
            // We need to fetch reports again to get the specific days, or modify payrollService to return them.
            // For now, let's fetch reports separately to get the days, or we can optimize later.
            // To be consistent with payrollService, we should probably fetch reports here too or ask payrollService to return days.
            // Let's just fetch reports here for the days grid to ensure accuracy.
            const startDate = `${yearStr}-${monthStr}-01`;
            const lastDay = new Date(year, month, 0).getDate();
            const endDate = `${yearStr}-${monthStr}-${lastDay}`;
            const reports = await dailyReportService.getReportsByRange(startDate, endDate, undefined, selectedSiteId);

            const details: { [key: string]: number[] } = {};
            reports.forEach(report => {
                // Parse date safely (YYYY-MM-DD -> integer day)
                const day = parseInt(report.date.split('-')[2], 10);
                report.workers.forEach(w => {
                    const workerId = w.workerId || w.name;
                    if (!details[workerId]) details[workerId] = [];
                    if (!details[workerId].includes(day)) details[workerId].push(day);
                });
            });

            // Override Tax to 0 as requested
            const modifiedPayrollList = payrollList.map(item => ({
                ...item,
                tax: { income: 0, resident: 0 },
                netPay: item.grossPay - (item.deductions.advance + item.deductions.other) // Recalculate Net without tax
            }));

            setDailyDetails(details);
            setInvoiceData(modifiedPayrollList);
            setIsSearched(true);

            if (payrollList.length === 0) {
                alert("해당 기간에 데이터가 없습니다.");
            }

            return payrollList;

        } catch (error) {
            console.error("Error fetching data:", error);
            alert("데이터 조회 중 오류가 발생했습니다.");
            return null;
        } finally {
            setLoading(false);
        }
    };

    const handleSearch = () => {
        fetchData();
    };

    const getDayOfWeek = (month: string, day: number): string => {
        const [y, m] = month.split('-').map(Number);
        if (!y || !m) return '';
        const date = new Date(y, m - 1, day);
        const days = ['일', '월', '화', '수', '목', '금', '토'];
        return days[date.getDay()];
    };

    const handleDownload = async () => {
        if (invoiceData.length === 0) {
            alert("출력할 데이터가 없습니다.");
            return;
        }

        setLoading(true);
        try {
            const siteName = sites.find(s => s.id === selectedSiteId)?.name || '';
            const workbook = new ExcelJS.Workbook();
            const worksheet = workbook.addWorksheet('노무내역서');

            worksheet.columns = [
                { width: 12 }, // A: Name
                { width: 18 }, // B: JuminID/Phone
                { width: 40 }, // C: Address
                ...Array(16).fill({ width: 5.5 }), // D-S: Days (increased for dow)
                { width: 8 },  // T: Total Days
                { width: 12 }, // U: Unit Price
                { width: 15 }, // V: Gross Pay
                { width: 12 }, // W: Deductions
                { width: 15 }, // X: Net Pay
            ];

            // Title
            worksheet.mergeCells('A1:X1');
            const titleCell = worksheet.getCell('A1');
            titleCell.value = '노무내역서';
            titleCell.alignment = { horizontal: 'center', vertical: 'middle' };
            titleCell.font = { size: 22, bold: true, underline: true };
            worksheet.getRow(1).height = 50;

            // Metadata
            const lastDayDate = new Date(new Date(selectedMonth).getFullYear(), new Date(selectedMonth).getMonth() + 1, 0).toISOString().slice(0, 10);
            worksheet.mergeCells('A2:C2');
            worksheet.getCell('A2').value = `기간: ${selectedMonth}-01 ~ ${lastDayDate}`;
            worksheet.getCell('A2').font = { bold: true };
            worksheet.getCell('A2').alignment = { vertical: 'middle' };

            worksheet.mergeCells('D2:X2');
            worksheet.getCell('D2').value = `현장명: ${siteName}`;
            worksheet.getCell('D2').alignment = { horizontal: 'right', vertical: 'middle' };
            worksheet.getCell('D2').font = { bold: true };
            worksheet.getRow(2).height = 25;

            // Header Rows
            const headerRow1 = worksheet.getRow(3);
            const headerRow2 = worksheet.getRow(4);

            // Build Day Headers with DOW
            const dayHeaders1: string[] = [];
            for (let i = 1; i <= 15; i++) {
                const dow = getDayOfWeek(selectedMonth, i);
                dayHeaders1.push(`${String(i).padStart(2, '0')}\n(${dow})`);
            }

            const dayHeaders2: string[] = [];
            const maxDay = new Date(new Date(selectedMonth).getFullYear(), new Date(selectedMonth).getMonth() + 1, 0).getDate();
            for (let i = 16; i <= 31; i++) {
                if (i <= maxDay) {
                    const dow = getDayOfWeek(selectedMonth, i);
                    dayHeaders2.push(`${String(i).padStart(2, '0')}\n(${dow})`);
                } else {
                    dayHeaders2.push('');
                }
            }

            headerRow1.values = ['성명', '주민등록번호', '주소', ...dayHeaders1, '', '출역일수', '단가', '총액', '공제', '실지급액'];
            headerRow2.values = ['', '전화번호', '', ...dayHeaders2, ''];

            // Header Merges
            ['A', 'C', 'T', 'U', 'V', 'W', 'X'].forEach(col => {
                worksheet.mergeCells(`${col}3:${col}4`);
            });

            // Style Headers
            [headerRow1, headerRow2].forEach((row, rowIdx) => {
                row.height = 35; // Increased for two lines
                row.eachCell((cell, colIdx) => {
                    cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFFF2CC' } };
                    cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
                    cell.font = { bold: true, size: 9 };
                    cell.border = { top: { style: 'thin' }, left: { style: 'thin' }, bottom: { style: 'thin' }, right: { style: 'thin' } };

                    // Color Coding Days
                    if (colIdx >= 4 && colIdx <= 19) {
                        const dayNum = rowIdx === 0 ? (colIdx - 3) : (colIdx - 3 + 15);
                        if (dayNum >= 1 && dayNum <= maxDay) {
                            const dow = getDayOfWeek(selectedMonth, dayNum);
                            let bgColor = rowIdx === 0 ? 'FF0070C0' : 'FFC00000'; // Default Blue/Red
                            if (dow === '일') bgColor = 'FFA52A2A'; // Dark Red for Sunday
                            if (dow === '토') bgColor = 'FF000080'; // Navy for Saturday
                            
                            cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: bgColor } };
                            cell.font = { color: { argb: 'FFFFFFFF' }, bold: true, size: 8 };
                        } else if (colIdx === 19 && rowIdx === 0) {
                            // Spacer
                            cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF0070C0' } };
                        }
                    }
                });
            });

            // Data Rows
            let currentRow = 5;
            invoiceData.forEach(item => {
                const row1 = worksheet.getRow(currentRow);
                const row2 = worksheet.getRow(currentRow + 1);
                const days = dailyDetails[item.id] || [];

                // Basic Info
                worksheet.mergeCells(`A${currentRow}:A${currentRow + 1}`);
                worksheet.getCell(`A${currentRow}`).value = item.name;

                row1.getCell(2).value = '******-*******';
                row2.getCell(2).value = ''; // Phone placeholder

                worksheet.mergeCells(`C${currentRow}:C${currentRow + 1}`);
                worksheet.getCell(`C${currentRow}`).value = item.address || '';

                // Days 1-15
                for (let i = 1; i <= 15; i++) {
                    if (days.includes(i)) {
                        const cell = row1.getCell(i + 3);
                        cell.value = 1.0;
                    }
                }
                row1.getCell(19).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF2F2F2' } };

                // Days 16-31
                for (let i = 16; i <= 31; i++) {
                    if (days.includes(i)) {
                        const cell = row2.getCell(i - 16 + 4);
                        cell.value = 1.0;
                    }
                }

                // Financials
                worksheet.mergeCells(`T${currentRow}:T${currentRow + 1}`);
                worksheet.getCell(`T${currentRow}`).value = item.gongsu.total;
                worksheet.mergeCells(`U${currentRow}:U${currentRow + 1}`);
                worksheet.getCell(`U${currentRow}`).value = item.unitPrice;
                worksheet.getCell(`U${currentRow}`).numFmt = '#,##0';
                worksheet.mergeCells(`V${currentRow}:V${currentRow + 1}`);
                worksheet.getCell(`V${currentRow}`).value = item.grossPay;
                worksheet.getCell(`V${currentRow}`).numFmt = '#,##0';
                worksheet.mergeCells(`W${currentRow}:W${currentRow + 1}`);
                worksheet.getCell(`W${currentRow}`).value = item.deductions.advance + item.deductions.other;
                worksheet.getCell(`W${currentRow}`).numFmt = '#,##0';
                worksheet.getCell(`W${currentRow}`).font = { color: { argb: 'FFFF0000' } };
                worksheet.mergeCells(`X${currentRow}:X${currentRow + 1}`);
                worksheet.getCell(`X${currentRow}`).value = item.netPay;
                worksheet.getCell(`X${currentRow}`).numFmt = '#,##0';
                worksheet.getCell(`X${currentRow}`).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE6F0FF' } };
                worksheet.getCell(`X${currentRow}`).font = { color: { argb: 'FF0000FF' }, bold: true };

                [row1, row2].forEach(row => {
                    row.eachCell({ includeEmpty: true }, (cell) => {
                        cell.border = { top: { style: 'thin' }, left: { style: 'thin' }, bottom: { style: 'thin' }, right: { style: 'thin' } };
                        cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
                        cell.font = { size: 9 };
                    });
                });
                currentRow += 2;
            });

            // Footer
            const footerRow = worksheet.getRow(currentRow);
            footerRow.height = 35;
            worksheet.mergeCells(`A${currentRow}:C${currentRow}`);
            worksheet.getCell(`A${currentRow}`).value = '합 계';
            worksheet.mergeCells(`D${currentRow}:S${currentRow}`);
            
            footerRow.getCell(20).value = invoiceData.reduce((sum, item) => sum + item.gongsu.total, 0);
            footerRow.getCell(22).value = invoiceData.reduce((sum, item) => sum + item.grossPay, 0);
            footerRow.getCell(23).value = invoiceData.reduce((sum, item) => sum + (item.deductions.advance + item.deductions.other), 0);
            footerRow.getCell(24).value = invoiceData.reduce((sum, item) => sum + item.netPay, 0);

            footerRow.eachCell({ includeEmpty: true }, (cell, colNumber) => {
                cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF8CBAD' } };
                cell.border = { top: { style: 'thin' }, left: { style: 'thin' }, bottom: { style: 'thin' }, right: { style: 'thin' } };
                cell.font = { bold: true, size: 10 };
                cell.alignment = { horizontal: 'center', vertical: 'middle' };
                if (colNumber >= 22) cell.numFmt = '#,##0';
            });

            // Remove AutoFilter (Ensuring no filter is applied)
            worksheet.autoFilter = undefined;

            const buffer = await workbook.xlsx.writeBuffer();
            const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
            saveAs(blob, `노무내역서_${siteName}_${selectedMonth}.xlsx`);

        } catch (error) {
            console.error("Error generating Excel:", error);
            alert("엑셀 생성 중 오류가 발생했습니다.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="p-4 md:p-8 max-w-[1400px] mx-auto bg-white rounded-xl shadow-lg mt-10 min-h-screen">
            {!hideHeader && <h1 className="text-2xl font-bold text-slate-800 mb-6 border-b pb-4">노무내역서 (현장별)</h1>}

            <div className="space-y-6">
                {/* Control Panel */}
                <div className="flex flex-col md:flex-row gap-4 items-end bg-slate-50 p-4 rounded-lg border border-slate-200">
                    {/* 현장 선택 팝업 */}
                    <div className="relative" ref={sitePopupRef}>
                        <label className="block text-sm font-bold text-slate-600 mb-2">현장 선택</label>
                        <button
                            onClick={() => { setSitePopupOpen(!sitePopupOpen); setMonthPopupOpen(false); }}
                            className="w-full md:w-64 bg-white border border-slate-300 rounded-lg px-4 py-2.5 text-left flex items-center justify-between shadow-sm hover:border-brand-500 transition"
                        >
                            <span className="truncate">{sites.find(s => s.id === selectedSiteId)?.name || '현장을 선택하세요'}</span>
                            <FontAwesomeIcon icon={faChevronDown} className={`ml-2 text-slate-400 transition-transform ${sitePopupOpen ? 'rotate-180' : ''}`} />
                        </button>
                        {sitePopupOpen && (
                            <div className="absolute top-full left-0 mt-1 w-full md:w-72 bg-white border border-slate-200 rounded-lg shadow-xl z-50 max-h-60 overflow-y-auto">
                                {sites.map(site => (
                                    <button
                                        key={site.id}
                                        onClick={() => { setSelectedSiteId(site.id); setSitePopupOpen(false); }}
                                        className={`w-full px-4 py-2.5 text-left hover:bg-brand-50 flex items-center justify-between transition ${selectedSiteId === site.id ? 'bg-brand-50 text-brand-700 font-bold' : 'text-slate-700'}`}
                                    >
                                        <span className="truncate">{site.name}</span>
                                        {selectedSiteId === site.id && <FontAwesomeIcon icon={faCheck} className="text-brand-600" />}
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* 월 선택 팝업 */}
                    <div className="relative" ref={monthPopupRef}>
                        <label className="block text-sm font-bold text-slate-600 mb-2">월 선택</label>
                        <button
                            onClick={() => { setMonthPopupOpen(!monthPopupOpen); setSitePopupOpen(false); }}
                            className="w-full md:w-40 bg-white border border-slate-300 rounded-lg px-4 py-2.5 text-left flex items-center justify-between shadow-sm hover:border-brand-500 transition"
                        >
                            <span>{selectedMonth}</span>
                            <FontAwesomeIcon icon={faChevronDown} className={`ml-2 text-slate-400 transition-transform ${monthPopupOpen ? 'rotate-180' : ''}`} />
                        </button>
                        {monthPopupOpen && (
                            <div className="absolute top-full left-0 mt-1 w-full md:w-48 bg-white border border-slate-200 rounded-lg shadow-xl z-50 p-3">
                                <input
                                    type="month"
                                    value={selectedMonth}
                                    onChange={(e) => { setSelectedMonth(e.target.value); setMonthPopupOpen(false); }}
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:border-brand-500 focus:ring-brand-500"
                                />
                                <div className="mt-2 grid grid-cols-3 gap-1">
                                    {Array.from({ length: 6 }, (_, i) => {
                                        const d = new Date();
                                        d.setMonth(d.getMonth() - i);
                                        const val = d.toISOString().slice(0, 7);
                                        const label = `${d.getMonth() + 1}월`;
                                        return (
                                            <button
                                                key={val}
                                                onClick={() => { setSelectedMonth(val); setMonthPopupOpen(false); }}
                                                className={`px-2 py-1.5 text-xs rounded transition ${selectedMonth === val ? 'bg-brand-600 text-white font-bold' : 'bg-slate-100 hover:bg-slate-200 text-slate-600'}`}
                                            >
                                                {label}
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                        )}
                    </div>
                    <div className="flex gap-2 ml-auto">
                        <button
                            onClick={handleSearch}
                            disabled={loading}
                            className="bg-blue-600 text-white px-6 py-2.5 rounded-lg hover:bg-blue-700 font-bold shadow-sm flex items-center gap-2 transition"
                        >
                            {loading && !isSearched ? <FontAwesomeIcon icon={faSpinner} spin /> : <FontAwesomeIcon icon={faSearch} />}
                            조회
                        </button>
                        <button
                            onClick={handleDownload}
                            disabled={loading}
                            className="bg-green-600 text-white px-6 py-2.5 rounded-lg hover:bg-green-700 font-bold shadow-sm flex items-center gap-2 transition"
                        >
                            {loading && isSearched ? <FontAwesomeIcon icon={faSpinner} spin /> : <FontAwesomeIcon icon={faFileExcel} />}
                            엑셀 다운로드
                        </button>
                    </div>
                </div >

                {/* Web View Table */}
                {
                    isSearched && invoiceData.length > 0 && (
                        <div className="overflow-x-auto border border-slate-300 rounded-lg shadow-inner bg-white p-4">
                            <table className="w-full border-collapse text-xs md:text-sm whitespace-nowrap">
                                <thead>
                                    <tr>
                                        <th colSpan={25} className="border border-slate-400 p-4 text-center text-2xl font-bold bg-white text-slate-900">
                                            노무내역서
                                        </th>
                                    </tr>
                                    <tr className="bg-white">
                                        <td colSpan={3} className="border border-slate-400 p-2 text-left font-bold">
                                            기간: {selectedMonth}-01 ~ {new Date(new Date(selectedMonth).getFullYear(), new Date(selectedMonth).getMonth() + 1, 0).toISOString().slice(0, 10)}
                                        </td>
                                        <td colSpan={22} className="border border-slate-400 p-2 text-right font-bold">
                                            현장명: {sites.find(s => s.id === selectedSiteId)?.name}
                                        </td>
                                    </tr>

                                    <tr className="bg-[#fff2cc] text-slate-800">
                                        <th rowSpan={2} className="border border-slate-400 p-2 text-center w-20">성명</th>
                                        <th className="border border-slate-400 p-2 text-center w-32">주민등록번호</th>
                                        <th rowSpan={2} className="border border-slate-400 p-2 text-center min-w-[240px]">주소</th>

                                        {/* Days 1-15 */}
                                        {Array.from({ length: 15 }, (_, i) => i + 1).map(day => (
                                            <th key={`h1-${day}`} className="border border-slate-400 p-1 text-center w-6 bg-[#0070c0] text-white">
                                                {day}
                                            </th>
                                        ))}
                                        <th className="border border-slate-400 p-1 text-center w-6 bg-[#0070c0] text-white"></th>

                                        <th rowSpan={2} className="border border-slate-400 p-2 text-center w-16">출역일수</th>
                                        <th rowSpan={2} className="border border-slate-400 p-2 text-center w-16">단가</th>
                                        <th rowSpan={2} className="border border-slate-400 p-2 text-center w-20">총액</th>
                                        {/* Tax Header Removed */}
                                        <th rowSpan={2} className="border border-slate-400 p-2 text-center w-16">공제</th>
                                        <th rowSpan={2} className="border border-slate-400 p-2 text-center w-20 bg-yellow-100">실지급액</th>
                                    </tr>
                                    <tr className="bg-[#fff2cc] text-slate-800">
                                        <th className="border border-slate-400 p-2 text-center">전화번호</th>
                                        {/* Days 16-31 */}
                                        {Array.from({ length: 16 }, (_, i) => i + 16).map(day => (
                                            <th key={`h2-${day}`} className="border border-slate-400 p-1 text-center w-6 bg-[#c00000] text-white">
                                                {day <= 31 ? day : ''}
                                            </th>
                                        ))}
                                    </tr>
                                </thead>
                                <tbody>
                                    {invoiceData.map((item, idx) => {
                                        const days = dailyDetails[item.id] || [];
                                        return (
                                            <React.Fragment key={item.id}>
                                                <tr className="hover:bg-slate-50">
                                                    <td rowSpan={2} className="border border-slate-300 p-2 text-center font-bold">{item.name}</td>
                                                    <td className="border border-slate-300 p-2 text-center">******-*******</td>
                                                    <td rowSpan={2} className="border border-slate-300 p-2 text-left font-semibold min-w-[240px] break-words">
                                                        {item.address || '-'}
                                                    </td>

                                                    {Array.from({ length: 15 }, (_, i) => i + 1).map(day => (
                                                        <td key={`d1-${day}`} className="border border-slate-300 p-1 text-center text-[10px]">
                                                            {days.includes(day) ? '1.0' : ''}
                                                        </td>
                                                    ))}
                                                    <td className="border border-slate-300 p-1 text-center bg-slate-100"></td>

                                                    <td rowSpan={2} className="border border-slate-300 p-2 text-center font-bold">{item.gongsu.total.toFixed(1)}</td>
                                                    <td rowSpan={2} className="border border-slate-300 p-2 text-right font-bold">{item.unitPrice.toLocaleString()}</td>
                                                    <td rowSpan={2} className="border border-slate-300 p-2 text-right font-bold">{item.grossPay.toLocaleString()}</td>
                                                    {/* Tax Removed */}
                                                    <td rowSpan={2} className="border border-slate-300 p-2 text-right font-bold text-red-600">{(item.deductions.advance + item.deductions.other).toLocaleString()}</td>
                                                    <td rowSpan={2} className="border border-slate-300 p-2 text-right font-bold text-blue-600 bg-blue-50">{item.netPay.toLocaleString()}</td>
                                                </tr>
                                                <tr className="hover:bg-slate-50">
                                                    <td className="border border-slate-300 p-2 text-center text-xs text-slate-500"></td>
                                                    {Array.from({ length: 16 }, (_, i) => i + 16).map(day => (
                                                        <td key={`d2-${day}`} className="border border-slate-300 p-1 text-center text-[10px]">
                                                            {day <= 31 && days.includes(day) ? '1.0' : ''}
                                                        </td>
                                                    ))}
                                                </tr>
                                            </React.Fragment>
                                        );
                                    })}
                                </tbody>
                                <tfoot className="bg-[#f8cbad] font-bold">
                                    <tr>
                                        <td colSpan={3} className="border border-slate-400 p-3 text-center text-lg">합 계</td>
                                        <td colSpan={16} className="border border-slate-400 p-2"></td>
                                        <td className="border border-slate-400 p-2 text-center">
                                            {invoiceData.reduce((sum, item) => sum + item.gongsu.total, 0).toFixed(1)}
                                        </td>
                                        <td className="border border-slate-400 p-2"></td>
                                        <td className="border border-slate-400 p-2 text-right">
                                            {invoiceData.reduce((sum, item) => sum + item.grossPay, 0).toLocaleString()}
                                        </td>
                                        {/* Tax Removed */}
                                        <td className="border border-slate-400 p-2 text-right">
                                            {invoiceData.reduce((sum, item) => sum + (item.deductions.advance + item.deductions.other), 0).toLocaleString()}
                                        </td>
                                        <td className="border border-slate-400 p-2 text-right text-blue-700">
                                            {invoiceData.reduce((sum, item) => sum + item.netPay, 0).toLocaleString()}
                                        </td>
                                    </tr>
                                </tfoot>
                            </table>
                        </div>
                    )
                }

                {
                    isSearched && invoiceData.length === 0 && (
                        <div className="text-center py-20 text-slate-500 bg-slate-50 rounded-lg border border-dashed border-slate-300">
                            <p className="text-xl mb-2">데이터가 없습니다.</p>
                            <p>선택한 기간에 출역 기록이 없습니다.</p>
                        </div>
                    )
                }

                {
                    !isSearched && (
                        <div className="text-center py-20 text-slate-500 bg-slate-50 rounded-lg border border-dashed border-slate-300">
                            <p className="text-xl mb-2">조회 버튼을 눌러주세요.</p>
                            <p>현장과 월을 선택하고 조회하면 명세서가 표시됩니다.</p>
                        </div>
                    )
                }
            </div >
        </div >
    );
};

export default SiteLaborCostInvoice;

import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faCalendarAlt,
    faCircleExclamation,
    faDownload,
    faExclamationTriangle,
    faFileLines,
    faFilter,
    faSpinner,
    faTable,
    faTriangleExclamation,
    faUserShield
} from '@fortawesome/free-solid-svg-icons';
import ExcelJS from 'exceljs';
import { saveAs } from 'file-saver';
import { supportClaimService, SupportClaimResult, SupportClaimSheet } from '../../services/supportClaimService';
import { companyService, Company } from '../../services/companyService';
import { teamService, Team } from '../../services/teamService';
import { siteService, Site } from '../../services/siteService';

const formatNumber = (value: number) => new Intl.NumberFormat('ko-KR', { maximumFractionDigits: 1 }).format(value);

const SupportClaimPage: React.FC = () => {
    const today = new Date();
    const defaultMonth = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`;

    const [selectedMonth, setSelectedMonth] = useState(defaultMonth);
    const [selectedContractorId, setSelectedContractorId] = useState<string>('');
    const [selectedTeamId, setSelectedTeamId] = useState<string>('');
    const [selectedSiteId, setSelectedSiteId] = useState<string>('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [result, setResult] = useState<SupportClaimResult | null>(null);
    const [companies, setCompanies] = useState<Company[]>([]);
    const [teams, setTeams] = useState<Team[]>([]);
    const [sites, setSites] = useState<Site[]>([]);
    const [pendingSheetId, setPendingSheetId] = useState<string | null>(null);
    const [showSensitiveModal, setShowSensitiveModal] = useState(false);
    const [downloadLoading, setDownloadLoading] = useState(false);

    const fetchMasterData = useCallback(async () => {
        try {
            const [companyList, teamList, siteList] = await Promise.all([
                companyService.getCompanies(),
                teamService.getTeams(),
                siteService.getSites()
            ]);
            setCompanies(companyList);
            setTeams(teamList);
            setSites(siteList);
        } catch (masterError) {
            console.error(masterError);
            setError('기준 데이터를 불러오지 못했습니다. 새로고침 후 다시 시도해주세요.');
        }
    }, []);

    const fetchClaims = useCallback(async () => {
        if (!selectedMonth) return;
        setLoading(true);
        setError(null);
        try {
            const claimResult = await supportClaimService.fetchClaims({
                month: selectedMonth,
                contractorCompanyIds: selectedContractorId ? [selectedContractorId] : undefined,
                teamIds: selectedTeamId ? [selectedTeamId] : undefined,
                siteIds: selectedSiteId ? [selectedSiteId] : undefined
            });
            setResult(claimResult);
        } catch (fetchError) {
            console.error(fetchError);
            setError('지원비 청구 데이터를 조회하는 중 오류가 발생했습니다.');
        } finally {
            setLoading(false);
        }
    }, [selectedContractorId, selectedMonth, selectedSiteId, selectedTeamId]);

    useEffect(() => {
        void fetchMasterData();
    }, [fetchMasterData]);

    useEffect(() => {
        if (companies.length === 0 || teams.length === 0 || sites.length === 0) return;
        void fetchClaims();
    }, [companies.length, fetchClaims, sites.length, teams.length]);

    const contractorOptions = useMemo(
        () => companies.filter((company) => (company.type ?? '').includes('시공사')), [companies]
    );

    const supportTeams = useMemo(
        () => teams.filter((team) => (team.type ?? '').includes('지원')), [teams]
    );

    const claimContractorOptions = useMemo(() => {
        const optionMap = new Map<string, string>();

        result?.sheets.forEach((sheet) => {
            if (!sheet.contractorId) return;
            optionMap.set(sheet.contractorId, sheet.contractorName);
        });

        if (optionMap.size === 0) {
            companies
                .filter((company) => !company.isMyCompany)
                .forEach((company) => {
                    const optionId = company.id || company.name;
                    if (!optionId) return;
                    optionMap.set(optionId, company.name);
                });
        }

        return Array.from(optionMap.entries())
            .map(([id, name]) => ({ id, name }))
            .sort((a, b) => a.name.localeCompare(b.name, 'ko-KR'));
    }, [companies, result?.sheets]);

    const claimTeamOptions = useMemo(() => {
        const optionMap = new Map<string, string>();

        result?.sheets.forEach((sheet) => {
            const optionId = sheet.teamId || sheet.teamName;
            if (!optionId) return;
            optionMap.set(optionId, sheet.teamName);
        });

        if (optionMap.size === 0) {
            teams.forEach((team) => {
                const optionId = team.id || team.name;
                if (!optionId) return;
                optionMap.set(optionId, team.name);
            });
        }

        return Array.from(optionMap.entries())
            .map(([id, name]) => ({ id, name }))
            .sort((a, b) => a.name.localeCompare(b.name, 'ko-KR'));
    }, [result?.sheets, teams]);

    const claimSiteOptions = useMemo(() => {
        const optionMap = new Map<string, string>();

        result?.sheets.forEach((sheet) => {
            const optionId = sheet.siteId || sheet.siteName;
            if (!optionId) return;
            optionMap.set(optionId, sheet.siteName);
        });

        if (optionMap.size === 0) {
            sites.forEach((site) => {
                const optionId = site.id || site.name;
                if (!optionId) return;
                optionMap.set(optionId, site.name);
            });
        }

        return Array.from(optionMap.entries())
            .map(([id, name]) => ({ id, name }))
            .sort((a, b) => a.name.localeCompare(b.name, 'ko-KR'));
    }, [result?.sheets, sites]);

    const claimRules = [
        {
            title: '지원 현장',
            description: '현장구분이 지원이면 출력일보 기준 외부 지원팀/외부 소속 투입을 청구 대상으로 집계합니다.'
        },
        {
            title: '도급 · 직영 현장',
            description: '도급/직영 현장은 청연 내부 소속을 제외하고 다른 소속 팀이 출력한 인원만 청구 대상으로 집계합니다.'
        },
        {
            title: '검증 항목',
            description: '주민등록번호, 주소, 단가, 청구 대상 팀/회사 매핑 누락은 보완 목록으로 바로 표시합니다.'
        }
    ] as const;

    const monthDays = result?.period.daysInMonth ?? 31;
    const dayColumns = useMemo(() => Array.from({ length: monthDays }, (_, index) => index + 1), [monthDays]);

    const hasData = (result?.sheets.length ?? 0) > 0;
    const findSheetById = useCallback(
        (sheetId: string | null) => result?.sheets.find((sheet) => sheet.sheetId === sheetId),
        [result?.sheets]
    );

    useEffect(() => {
        if (selectedContractorId && !claimContractorOptions.some((option) => option.id === selectedContractorId)) {
            setSelectedContractorId('');
        }
    }, [claimContractorOptions, selectedContractorId]);

    useEffect(() => {
        if (selectedTeamId && !claimTeamOptions.some((option) => option.id === selectedTeamId)) {
            setSelectedTeamId('');
        }
    }, [claimTeamOptions, selectedTeamId]);

    useEffect(() => {
        if (selectedSiteId && !claimSiteOptions.some((option) => option.id === selectedSiteId)) {
            setSelectedSiteId('');
        }
    }, [claimSiteOptions, selectedSiteId]);

    const handleRequestDownload = (sheetId: string) => {
        setPendingSheetId(sheetId);
        setShowSensitiveModal(true);
    };

    const handleConfirmDownload = useCallback(async () => {
        if (!pendingSheetId) return;
        const targetSheet = findSheetById(pendingSheetId);
        if (!targetSheet) {
            setShowSensitiveModal(false);
            return;
        }
        setDownloadLoading(true);
        try {
            const daysInMonth = targetSheet.rows[0]?.dailyManDays.length ?? result?.period.daysInMonth ?? 31;
            await exportSupportClaimSheet(targetSheet, daysInMonth);
        } catch (downloadError) {
            console.error(downloadError);
            window.alert('엑셀 파일 생성 중 오류가 발생했습니다. 다시 시도해주세요.');
        } finally {
            setDownloadLoading(false);
            setShowSensitiveModal(false);
            setPendingSheetId(null);
        }
    }, [findSheetById, pendingSheetId, result?.period.daysInMonth]);

    const handleCancelDownload = () => {
        setShowSensitiveModal(false);
        setPendingSheetId(null);
    };

    return (
        <div className="space-y-6 p-6">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-semibold text-gray-900">지원비 청구 명세서</h1>
                    <p className="text-sm text-gray-500">일보 데이터를 기반으로 시공사 제출용 일용노무비 지급명세서를 생성합니다.</p>
                </div>
                <button
                    type="button"
                    className="inline-flex items-center gap-2 rounded-lg border border-gray-200 px-4 py-2 text-sm font-semibold text-gray-700 shadow-sm hover:bg-gray-50"
                    onClick={fetchClaims}
                >
                    <FontAwesomeIcon icon={faFilter} />
                    다시 집계
                </button>
            </div>

            <section className="grid gap-4 md:grid-cols-3">
                {claimRules.map((rule) => (
                    <div key={rule.title} className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
                        <div className="mb-2 inline-flex items-center gap-2 rounded-full bg-amber-50 px-3 py-1 text-xs font-semibold text-amber-700">
                            <FontAwesomeIcon icon={faTriangleExclamation} />
                            {rule.title}
                        </div>
                        <p className="text-sm leading-6 text-slate-600">{rule.description}</p>
                    </div>
                ))}
            </section>

            <section className="rounded-2xl border border-gray-200 bg-white p-4 shadow-sm">
                <div className="grid gap-4 lg:grid-cols-4">
                    <label className="text-sm font-medium text-gray-600">
                        정산 월
                        <div className="mt-1 flex items-center rounded-lg border border-gray-300 px-3">
                            <FontAwesomeIcon icon={faCalendarAlt} className="mr-2 text-gray-400" />
                            <input
                                type="month"
                                value={selectedMonth}
                                onChange={(event) => setSelectedMonth(event.target.value)}
                                className="flex-1 border-none bg-transparent py-2 text-gray-900 focus:outline-none"
                            />
                        </div>
                    </label>
                    <label className="text-sm font-medium text-gray-600">
                        시공사
                        <select
                            value={selectedContractorId}
                            onChange={(event) => setSelectedContractorId(event.target.value)}
                            className="mt-1 w-full rounded-lg border border-gray-300 px-3 py-2 text-gray-900 focus:border-indigo-500 focus:outline-none"
                        >
                            <option value="">전체 시공사</option>
                            {claimContractorOptions.map((company) => (
                                <option key={company.id} value={company.id}>{company.name}</option>
                            ))}
                        </select>
                    </label>
                    <label className="text-sm font-medium text-gray-600">
                        지원팀
                        <select
                            value={selectedTeamId}
                            onChange={(event) => setSelectedTeamId(event.target.value)}
                            className="mt-1 w-full rounded-lg border border-gray-300 px-3 py-2 text-gray-900 focus:border-indigo-500 focus:outline-none"
                        >
                            <option value="">전체 지원팀</option>
                            {claimTeamOptions.map((team) => (
                                <option key={team.id} value={team.id}>{team.name}</option>
                            ))}
                        </select>
                    </label>
                    <label className="text-sm font-medium text-gray-600">
                        현장
                        <select
                            value={selectedSiteId}
                            onChange={(event) => setSelectedSiteId(event.target.value)}
                            className="mt-1 w-full rounded-lg border border-gray-300 px-3 py-2 text-gray-900 focus:border-indigo-500 focus:outline-none"
                        >
                            <option value="">전체 현장</option>
                            {claimSiteOptions.map((site) => (
                                <option key={site.id} value={site.id}>{site.name}</option>
                            ))}
                        </select>
                    </label>
                </div>
                <p className="mt-3 flex items-center text-xs text-amber-600">
                    <FontAwesomeIcon icon={faUserShield} className="mr-2" />
                    주민등록번호 등 민감정보가 표시됩니다. 열람 권한이 있는지 확인 후 사용하세요.
                </p>
            </section>

            <section className="grid gap-4 md:grid-cols-4">
                {[
                    { label: '시트 수', value: formatNumber(result?.stats.totalSheets ?? 0), icon: faTable },
                    { label: '근로자 수', value: formatNumber(result?.stats.totalWorkers ?? 0), icon: faUserShield },
                    { label: '총 공수', value: formatNumber(result?.stats.totalManDay ?? 0), icon: faFileLines },
                    { label: '총 청구액', value: `${formatNumber(result?.stats.totalAmount ?? 0)}원`, icon: faDownload }
                ].map((card) => (
                    <div key={card.label} className="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm">
                        <div className="flex items-center gap-3">
                            <span className="rounded-xl bg-indigo-50 p-3 text-indigo-600">
                                <FontAwesomeIcon icon={card.icon} />
                            </span>
                            <div>
                                <p className="text-sm text-gray-500">{card.label}</p>
                                <p className="text-xl font-semibold text-gray-900">{card.value}</p>
                            </div>
                        </div>
                    </div>
                ))}
            </section>

            {error && (
                <div className="rounded-2xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-700">
                    <FontAwesomeIcon icon={faCircleExclamation} className="mr-2" />
                    {error}
                </div>
            )}

            {result?.issues.length ? (
                <section className="rounded-2xl border border-amber-200 bg-amber-50 p-4">
                    <div className="flex items-center gap-2 text-amber-700">
                        <FontAwesomeIcon icon={faExclamationTriangle} />
                        <p className="font-semibold">필수 정보 누락 {result.issues.length}건</p>
                    </div>
                    <div className="mt-3 max-h-40 overflow-y-auto text-sm text-amber-800">
                        <ul className="list-disc space-y-1 pl-4">
                            {result.issues.map((issue, index) => (
                                <li key={`${issue.type}-${index}`}>
                                    [{issue.contractorName} · {issue.teamName}] {issue.workerName} - {issue.message}
                                </li>
                            ))}
                        </ul>
                    </div>
                </section>
            ) : null}

            <section className="space-y-6">
                {loading && (
                    <div className="flex items-center justify-center rounded-2xl border border-dashed border-gray-200 bg-white py-12 text-gray-500">
                        <FontAwesomeIcon icon={faSpinner} spin className="mr-2 text-indigo-500" />
                        데이터를 불러오는 중입니다...
                    </div>
                )}

                {!loading && !hasData && (
                    <div className="flex flex-col items-center gap-2 rounded-2xl border border-dashed border-gray-200 bg-white py-12 text-sm text-gray-500">
                        <FontAwesomeIcon icon={faExclamationTriangle} className="text-amber-500" />
                        선택한 조건에 해당하는 명세서 데이터가 없습니다.
                    </div>
                )}

                {result?.sheets.map((sheet) => (
                    <div key={sheet.sheetId} className="rounded-2xl border border-gray-200 bg-white shadow-sm">
                        <div className="flex flex-wrap items-center justify-between gap-4 border-b border-gray-100 p-4">
                            <div>
                                <div className="mb-2 flex flex-wrap gap-2">
                                    <span className="rounded-full bg-indigo-50 px-3 py-1 text-xs font-semibold text-indigo-700">
                                        {sheet.claimCategoryLabel}
                                    </span>
                                    <span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-semibold text-slate-600">
                                        현장구분 {sheet.siteType}
                                    </span>
                                </div>
                                <h2 className="text-lg font-semibold text-gray-900">
                                    {sheet.contractorName} · {sheet.siteName} · {sheet.teamName}
