                                    </div>

                                    {/* 4대보험 영역 */}
                                    <div className="text-center py-2 font-bold text-slate-700 border-b border-slate-300 bg-blue-50">4대보험 및 세금</div>
                                    <div className="grid grid-cols-4 text-sm">
