                                        <div className="border-r border-b border-slate-300 p-2 font-medium bg-blue-50">건강보험 ({healthPct}%)</div>
                                        <div className="border-b border-slate-300 p-2 text-right text-red-600">{health > 0 ? health.toLocaleString() : '-'}</div>

