}

type LedgerSide = 'invoice' | 'labor';
type LedgerSideNumberField =
    | 'carry'
    | 'carrySecond'
    | 'currentAdvance'
    | 'currentAdvanceSecond'
    | 'lodging'
    | 'electricity'
    | 'gas'
    | 'water'
    | 'internet'
    | 'management'
    | 'fine'
    | 'other';

interface LedgerSideInput {
