                    invoiceLodging: 0,
                    invoiceElectricity: 0,
                    invoiceGas: 0,
                    invoiceWater: 0,
                    laborInternet: 0,
                    laborManagement: 0,
                    laborFine: 0,
                    laborOther: 0,
                    invoiceDeductionTotal: 0,
