    standardLines: DeductionLine[];
    additionalLines: DeductionLine[];
    pension?: number;
    health?: number;
    longterm?: number;
    employment?: number;
    incomeTax?: number;
    residentTax?: number;
    businessIncomeTax?: number;
    businessResidentTax?: number;
    totalStandard?: number;
    totalAdditional?: number;
    total: number;
    hasData: boolean;
}

export interface WorkerWorkEntry {
