                                                    {row.valid ? <FontAwesomeIcon icon={faCheckCircle} className="text-green-500" /> : <FontAwesomeIcon icon={faExclamationTriangle} className="text-red-500" title="매칭 실패 (현장/팀/이름 확인)" />}
