                                                        </button>
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        )}
                    </SortableContext>
                    {workers.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300 text-xs italic p-4 text-center">
                            {site ? "작업자를 드래그하거나 선택하여 배정하세요" : "모든 인원이 배정되었습니다"}
