                            <div className="flex-1 p-2 overflow-y-auto">
                                {(companies.find(c => c.name === selectedCompany)?.type === '협력사' || inputMode === 'support') ? (
                                    /* External/Support Team Table View */
                                    <SortableContext
                                        items={visibleTeams.map(t => `team-source-${t.id}`)}
