                                                <div className="p-8 text-center text-xs text-slate-400">
                                                    {inputMode === 'support' ? '등록된 협력사가 없습니다.' : '등록된 협력사 팀이 없습니다.'}
                                                </div>
                                            )}
                                        </div>
                                    </SortableContext>
                                ) : (
                                    /* Internal Worker List */
                                    <SiteColumn
                                        site={null} // Represents Unassigned
                                        workers={unassignedWorkers}
                                        selectedWorkerIds={selectedWorkerIds}
                                        onToggleSelect={handleToggleSelect}
                                        onSelectAll={handleSelectAllUnassigned}
                                        isGrid={true} // Use Grid for compact view
                                        onWorkerDoubleClick={handleWorkerDoubleClick}
                                        selectedCompany={selectedCompany}
                                        teams={teams}
                                    />
                                )}
                            </div>
                        </div>
                    </div>

                    {/* RIGHT PANE: TARGET (Sites) */}
                    <div className="flex-1 flex flex-col bg-[#f1f5f9] overflow-hidden relative">
                        {/* Right Pane Header (Stats & Filters) */}
                        <div className="p-3 bg-white border-b border-slate-200 flex items-center justify-between shadow-sm z-10 shrink-0">
                            <div className="flex items-center gap-4">
                                <h2 className="text-sm font-bold text-slate-700 flex items-center gap-2">
                                    <FontAwesomeIcon icon={faBuilding} className="text-blue-500" />
                                    현장 목록 ({rightPaneSites.length}개)
                                </h2>
                                <div className="text-xs text-slate-500 bg-slate-100 px-2 py-1 rounded">
                                    총 배정: <span className="font-bold text-blue-600">{workerItems.filter(w => w.currentSiteId !== null).length}</span>명
                                    <span className="mx-1 text-slate-300">|</span>
                                    총 공수: <span className="font-bold text-blue-600">
                                        {workerItems
                                            .filter(w => w.currentSiteId !== null)
                                            .reduce((sum, w) => sum + (w.manDay || 0), 0)
                                            .toFixed(1)}
                                    </span>
                                </div>
                            </div>
                            <div className="flex items-center gap-2">
                                <button
                                    onClick={handleExpandAll}
                                    className="text-xs px-2 py-1 rounded hover:bg-slate-100 text-slate-600 border border-transparent hover:border-slate-200 transition-colors"
                                >
                                    전체 펼치기
                                </button>
                                <button
                                    onClick={handleCollapseAll}
                                    className="text-xs px-2 py-1 rounded hover:bg-slate-100 text-slate-600 border border-transparent hover:border-slate-200 transition-colors"
                                >
                                    전체 접기
                                </button>
                                <div className="h-3 w-px bg-slate-200 mx-1"></div>
                                <button
                                    onClick={handleResetAssignments}
                                    className="text-xs text-red-500 hover:bg-red-50 px-2 py-1 rounded border border-transparent hover:border-red-100 transition-colors flex items-center gap-1"
                                >
                                    <FontAwesomeIcon icon={faUndo} />
                                    배정 초기화
                                </button>
                            </div>
                        </div>

                        {/* Background Grid Pattern */}
                        <div className="absolute inset-0 z-0 opacity-[0.03]"
                            style={{ backgroundImage: 'radial-gradient(#475569 1px, transparent 1px)', backgroundSize: '20px 20px', pointerEvents: 'none' }}>
                        </div>

                        <div className="flex-1 overflow-y-auto p-4 md:p-6 z-10 custom-scrollbar">
                            {/* 4-Column Flex Layout (Kanban Style) */}
                            <div className="flex gap-4 h-full pb-20 items-start">
                                {['col-1', 'col-2', 'col-3', 'col-4'].map(colId => (
                                    <div key={colId} className="flex-1 flex flex-col gap-4 min-w-[200px]">
                                        <SortableContext
                                            id={colId}
                                            items={siteColumns[colId]}
                                            strategy={verticalListSortingStrategy}
                                        >
                                            {siteColumns[colId].map(siteId => {
                                                const site = rightPaneSites.find(s => s.id === siteId);
                                                // If site is filtered out by search, don't show it (visual filter)
                                                // BUT Keep it in the sortable context to maintain index?
                                                // If we remove from context, drag might break.
                                                // Better to filter visual only, but dnd-kit likes mapping.
                                                // If filtered out, let's just null check.
                                                if (!site) return null;

                                                // Sort siteWorkers by Role Priority
                                                const rolePriority: { [key: string]: number } = {
                                                    '팀장': 5,
                                                    '반장': 4,
                                                    '기공': 3,
                                                    '조공': 2,
                                                    '일반': 1
                                                };

                                                const siteWorkers = workerItems
                                                    .filter(w => w.currentSiteId === site.id)
                                                    .sort((a, b) => {
                                                        const rankA = rolePriority[a.role || '일반'] || 0;
                                                        const rankB = rolePriority[b.role || '일반'] || 0;
                                                        if (rankA !== rankB) return rankB - rankA; // Higher rank first
                                                        return a.name.localeCompare(b.name); // Name fallback
                                                    });

                                                const responsibleTeam = teams.find(t => t.id === site.responsibleTeamId);
                                                const isExpanded = expandedSiteIds.has(site.id || '');

                                                return (
                                                    <SiteColumn
                                                        key={site.id}
                                                        site={site}
                                                        workers={siteWorkers}
                                                        selectedWorkerIds={selectedWorkerIds}
                                                        onToggleSelect={handleToggleSelect}
                                                        isAccordion={true}
                                                        isExpanded={isExpanded}
                                                        onHeaderClick={() => toggleSiteExpansion(site.id || '')}
                                                        isGrid={true}
                                                        selectedCompany={selectedCompany}
                                                        responsibleTeamCompanyName={responsibleTeam?.companyName}
                                                        onWorkerDoubleClick={handleWorkerDoubleClick}
                                                        onSiteSelect={() => setTargetSiteId(site.id || '')}
                                                        isTargetSite={targetSiteId === site.id}
                                                        onChangeManDay={handleManDayChange}
                                                        onChangeWorkContent={handleWorkContentChange}
                                                        siteWorkContent={siteWorkContentMap.get(site.id || '') || ''}
                                                        onSiteWorkContentChange={(val) => {
                                                            setSiteWorkContentMap(prev => new Map(prev).set(site.id || '', val));
                                                        }}
                                                        onChangeWorkerTeam={handleWorkerTeamChange}
                                                        responsibleTeamColor={responsibleTeam?.color}
                                                        siteColor={site.color}
                                                        // Subcontractor Props
                                                        teams={teams}
                                                    />
                                                );
                                            })}
                                        </SortableContext>
                                        {/* Empty Drop Zone for Column */}
                                        {siteColumns[colId].length === 0 && (
                                            <div id={colId} className="h-20 border-2 border-dashed border-slate-200 rounded-xl flex items-center justify-center text-slate-300 text-xs">
                                                빈 열
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </DndContext>

            <DragOverlay>
                {activeDragId ? (
                    <WorkerCard
                        worker={activeWorker!}
                        isOverlay
                        selectionCount={selectedWorkerIds.size > 1 && selectedWorkerIds.has(activeDragId as string) ? selectedWorkerIds.size : 0}
                    />
                ) : null}
            </DragOverlay>
        </div >
    );
};

// Helper Component for External Team Row
interface DraggableTeamRowProps {
    team: Team;
}

const DraggableTeamRow = ({ team }: DraggableTeamRowProps) => {
    const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
        id: `team-source-${team.id}`,
        data: {
            type: 'Team',
            team
        }
    });

    const style = {
        transform: CSS.Translate.toString(transform),
        transition,
        opacity: isDragging ? 0.5 : 1,
    };

    return (
        <div
            ref={setNodeRef}
            style={style}
            {...attributes}
            {...listeners}
            className="flex items-center p-2 border-b border-slate-100 hover:bg-slate-50 cursor-grab active:cursor-grabbing bg-white text-xs"
        >
            <div className="flex-1 font-bold text-slate-700 truncate flex items-center gap-2">
                <FontAwesomeIcon icon={faUsers} className="text-slate-400 text-[10px]" />
                {team.name}
            </div>
            <div className="w-10 flex justify-center">
                <div className="w-3 h-3 rounded-full border border-slate-300" style={{ backgroundColor: team.color }}></div>
            </div>
        </div>
    );
};

export default DailyReportDragDropPage;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { HotTable } from '@handsontable/react';
import { registerAllModules } from 'handsontable/registry';
import 'handsontable/dist/handsontable.full.min.css';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faSave, faRobot, faPaste, faFileExcel, faExclamationTriangle, faSpinner, faCheck, faTrash } from '@fortawesome/free-solid-svg-icons';
import Swal from 'sweetalert2';
import { siteService, Site } from '../../services/siteService';
import { teamService, Team } from '../../services/teamService';
import { manpowerService, Worker } from '../../services/manpowerService';
import { dailyReportService } from '../../services/dailyReportService';
import { geminiService } from '../../services/geminiService';
import { useAuth } from '../../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';

registerAllModules();

interface ReportRow {
    date: string;
    siteName: string;
    teamName: string;
    workerName: string;
    manDay: number;
    unitPrice: number;
    role: string;
    content: string;
    note: string;
    // IDs for validation/saving
    siteId?: string;
    teamId?: string;
    workerId?: string;
}

const DailyReportExcelPage: React.FC = () => {
    const navigate = useNavigate();
    const { currentUser } = useAuth();
    const hotRef = useRef<any>(null);
    const [loading, setLoading] = useState(false);

    // Lookups
    const [sites, setSites] = useState<Site[]>([]);
    const [teams, setTeams] = useState<Team[]>([]);
    const [workers, setWorkers] = useState<Worker[]>([]);

    useEffect(() => {
        Promise.all([
            siteService.getSites(),
            teamService.getTeams(),
            manpowerService.getWorkers()
        ]).then(([s, t, w]) => {
            setSites(s);
            setTeams(t);
            setWorkers(w);
        });
    }, []);

    // Initial Data
    const generateEmptyRows = (count: number): ReportRow[] => {
        return Array(count).fill(null).map(() => ({
            date: new Date().toISOString().slice(0, 10),
            siteName: '',
            teamName: '',
            workerName: '',
            manDay: 1.0,
            unitPrice: 0,
            role: '조공',
            content: '',
            note: ''
        }));
    };

    const [data, setData] = useState<ReportRow[]>(generateEmptyRows(50));

    // Data Processing & Validation
    const validateAndProcessData = (rows: ReportRow[]) => {
        return rows.map(row => {
            // Find IDs based on Names
            const site = sites.find(s => s.name === row.siteName);
            const team = teams.find(t => t.name === row.teamName);
            // Worker search (exact match or remove spaces)
            const cleanName = row.workerName.replace(/\s+/g, '');
            const worker = workers.find(w => w.name.replace(/\s+/g, '') === cleanName);

            return {
                ...row,
                siteId: site?.id,
                teamId: team?.id,
                workerId: worker?.id,
                // Auto-fill logic can go here (e.g. if Worker found but Team empty, fill Team)
                teamName: (!row.teamName && worker && worker.teamName) ? worker.teamName : row.teamName,
                // If Unit Price 0, fill from worker
                unitPrice: (row.unitPrice === 0 && worker) ? (worker.unitPrice ?? row.unitPrice) : row.unitPrice,
                role: (!row.role && worker) ? (worker.role || '조공') : (row.role || '조공')
            };
        });
    };

    // AI Analysis Handler
    const handleAIAnalysis = async () => {
        const apiKey = geminiService.getKey();
        const { value: formValues } = await Swal.fire({
            title: '카톡/일보 텍스트 AI 분석',
            html: `
                <textarea id="ai-input" class="swal2-textarea" placeholder="카톡 내용이나 일보 텍스트를 붙여넣으세요..." style="height: 200px; width: 90%;"></textarea>
                <div style="margin-top: 10px; font-size: 0.9em; color: #666;">
                    ${apiKey ? '✅ Gemini API Key가 감지되었습니다.' : '⚠ API Key가 필요합니다.'}
                </div>
            `,
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: 'AI 분석 실행',
            cancelButtonText: '취소',
            width: 600,
            preConfirm: () => (document.getElementById('ai-input') as HTMLTextAreaElement).value
        });

        if (formValues) {
            if (!apiKey) {
                Swal.fire('Error', 'API Key가 없습니다. /settings/ai 에서 키를 등록해주세요.', 'error');
                return;
            }

            setLoading(true);
            try {
                // Determine if it's multiple reports or single
                // We'll use a generic "analyzeDailyReportText" which might return one object.
                // Or maybe we need a "Bulk" version? 
                // Let's assume the user pastes one or more.
                // Ideally geminiService.analyzeDailyReportText should return an ARRAY of reports if multiple found.
                // Current implementation returns ONE object.
                // I might need to ask Gemini to return Array.
                // But let's try with current service.
                const result = await geminiService.analyzeDailyReportText(formValues);

                // Map result to rows
                // Result structure: { teamName, siteName, date, workers: [...] }
                // We need to fill multiple rows.

                const newRows: ReportRow[] = [];
                const reportDate = result.date || new Date().toISOString().slice(0, 10);

                result.workers.forEach(w => {
                    newRows.push({
                        date: reportDate,
                        siteName: result.siteName || '',
                        teamName: w.teamName || result.teamName || '',
                        workerName: w.name,
                        manDay: w.manDay,
                        unitPrice: 0, // Inferred later
                        role: w.role || '조공', // Inferred later
                        content: w.workContent || '',
                        note: '',
                        siteId: undefined,
                        teamId: undefined,
                        workerId: undefined
                    });
                });

                // Merge into current grid
                const processed = validateAndProcessData(newRows);

                // Find first empty row
                const currentData = [...data];
                let insertIndex = 0;
                while (insertIndex < currentData.length && currentData[insertIndex].siteName) {
                    insertIndex++;
                }

                processed.forEach((item, idx) => {
                    if (insertIndex + idx < currentData.length) {
                        currentData[insertIndex + idx] = item;
                    } else {
                        currentData.push(item);
                    }
                });

                setData(currentData);
                Swal.fire('Success', `${processed.length}명의 데이터가 분석되었습니다.`, 'success');

            } catch (error) {
                console.error(error);
                Swal.fire('Error', 'AI 분석 중 오류가 발생했습니다.', 'error');
            } finally {
                setLoading(false);
            }
        }
    };

    // Save Validation
    const handleSave = async () => {
        // Filter valid rows
        const validRows = data.filter(r => r.workerName && r.workerName.trim() !== '');

        if (validRows.length === 0) {
            Swal.fire('Info', '저장할 데이터가 없습니다.', 'info');
            return;
        }

        // Validate Critical Fields
        const invalidRows = validRows.filter(r => !r.siteName || !r.teamName); // We rely on Names, IDs resolved during save is better
        // Actually Handsontable data might not have IDs if user just typed "Site A".
        // We resolve IDs now.

        const resolvedRows = validateAndProcessData(validRows);
        const badRows = resolvedRows.filter(r => !r.siteId || !r.teamId);

        if (badRows.length > 0) {
            Swal.fire({
                title: '검증 실패',
                text: `${badRows.length}건의 데이터에 현장명 또는 팀명이 유효하지 않습니다. 빨간색 셀을 확인해주세요.`,
                icon: 'warning'
            });
            // Update data to show red cells? 
            // We should update the state with resolved IDs so renderer knows.
            // But we need to keep the user's text too.
            // The renderer relies on mapping names to IDs validation. 
            // We'll update the data state with what we found.
            // Actually, we should update the whole grid with resolved info to give feedback.
            return;
        }

        setLoading(true);
        try {
            // Group by Key (Date + Site + Team)
            const groups: { [key: string]: typeof resolvedRows } = {};

            resolvedRows.forEach(row => {
                const key = `${row.date}_${row.siteId}_${row.teamId}`;
                if (!groups[key]) groups[key] = [];
                groups[key].push(row);
            });

            // Save sequentially or parallel
            let count = 0;
            for (const key in groups) {
                const groupRows = groups[key];
                const first = groupRows[0];

                await dailyReportService.addReport({
                    date: first.date,
                    siteId: first.siteId!,
                    siteName: first.siteName,
                    teamId: first.teamId!,
                    teamName: first.teamName,
                    totalManDay: groupRows.reduce((acc, cur) => acc + cur.manDay, 0),
                    writerId: currentUser?.uid || 'unknown',
                    workers: groupRows.map(r => ({
                        salaryModel: (() => {
                            const matchedWorker = workers.find(w => w.id === r.workerId);
                            if (matchedWorker?.teamType === '지원팀') return '지원팀';
                            if (matchedWorker?.teamType === '용역팀') return '용역팀';
                            return matchedWorker?.salaryModel || '일급제';
                        })(),
                        workerId: r.workerId || 'unknown', // Unknown worker is allowed? Maybe.
                        name: r.workerName,
                        role: r.role || '조공',
                        manDay: r.manDay,
                        unitPrice: r.unitPrice,
                        workContent: r.content,
                        status: 'attendance'
                    }))
                });
                count++;
            }

            Swal.fire('Success', `${count}건의 일보가 저장되었습니다.`, 'success');
            // Clear or Redirect?
            // navigate('/report/list');
            setData(generateEmptyRows(50)); // Reset

        } catch (error) {
            console.error(error);
            Swal.fire('Error', '저장 실패', 'error');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="flex flex-col h-full bg-slate-50 p-4">
            <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm mb-4 flex justify-between items-center">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-green-100 text-green-600 rounded-lg">
                        <FontAwesomeIcon icon={faFileExcel} size="lg" />
                    </div>
                    <div>
                        <h1 className="text-xl font-bold text-slate-800">스마트 일보 입력 (v3)</h1>
                        <p className="text-sm text-slate-500">AI로 분석된 데이터를 그리드에서 수정 후 저장하세요.</p>
                    </div>
                </div>
                <div className="flex gap-2">
                    <button onClick={handleAIAnalysis} className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-lg shadow transition flex items-center gap-2">
                        <FontAwesomeIcon icon={faRobot} /> AI 일보 분석
                    </button>
                    <button onClick={handleSave} className="px-5 py-2 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-lg shadow transition flex items-center gap-2">
                        {loading ? <FontAwesomeIcon icon={faSpinner} spin /> : <FontAwesomeIcon icon={faCheck} />} 저장
                    </button>
                </div>
            </div>

            <div className="flex-1 bg-white rounded-xl shadow border border-slate-200 overflow-hidden relative">
                <HotTable
                    ref={hotRef}
                    data={data}
                    colHeaders={['날짜', '현장명', '팀명', '작업자명', '공수', '단가', '직종', '작업내용', '비고']}
                    columns={[
                        { data: 'date', type: 'date', dateFormat: 'YYYY-MM-DD', correctFormat: true, width: 100 },
                        { data: 'siteName', type: 'dropdown', source: sites.map(s => s.name), width: 120 },
                        { data: 'teamName', type: 'dropdown', source: teams.map(t => t.name), width: 100 },
                        { data: 'workerName', type: 'text', width: 100 },
                        { data: 'manDay', type: 'numeric', numericFormat: { pattern: '0.0' }, width: 60 },
                        { data: 'unitPrice', type: 'numeric', numericFormat: { pattern: '0,0' }, width: 80 },
                        { data: 'role', type: 'dropdown', source: ['기공', '조공', '팀장', '준기공'], width: 70 },
                        { data: 'content', type: 'text', width: 200 },
                        { data: 'note', type: 'text', width: 100 },
                    ]}
                    rowHeaders={true}
                    width="100%"
                    height="100%"
                    stretchH="all"
                    contextMenu={true}
                    autoWrapRow={true}
                    autoWrapCol={true}
                    licenseKey="non-commercial-and-evaluation"
                    minSpareRows={1}
                    // Renderer for validation styling
                    cells={(row, col, prop) => {
                        const cellProps: any = {};
                        if (row < data.length) {
                            const rowData = data[row];
                            // Check valid Site
                            if (prop === 'siteName' && rowData.siteName && !sites.find(s => s.name === rowData.siteName)) {
                                cellProps.className = 'bg-red-100 text-red-600 font-bold';
                            }
                            // Check valid Team
                            if (prop === 'teamName' && rowData.teamName && !teams.find(t => t.name === rowData.teamName)) {
                                cellProps.className = 'bg-red-100 text-red-600 font-bold';
                            }
                            // Check Worker
                            if (prop === 'workerName' && rowData.workerName && !workers.find(w => w.name.replace(/\s/g, '') === rowData.workerName.replace(/\s/g, ''))) {
                                cellProps.className = 'bg-yellow-50 text-orange-600 font-bold'; // Warning only (can save unknown)
                            }
                        }
                        return cellProps;
                    }}
                />
            </div>
        </div>
    );
};

export default DailyReportExcelPage;

import React, { useState, useEffect, useLayoutEffect, useMemo, useCallback, useRef } from 'react';
import { HotTable } from '@handsontable/react';
import { registerAllModules } from 'handsontable/registry';
import 'handsontable/dist/handsontable.full.min.css';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faPlus, faSave, faCalendarAlt, faTimes, faMinus, faComment, faExclamationTriangle, faCheckCircle, faSpinner, faClipboardCheck, faEraser, faFloppyDisk, faClipboardList } from '@fortawesome/free-solid-svg-icons';
import { siteService, Site } from '../../services/siteService';
import SingleSelectPopover from '../../components/common/SingleSelectPopover';
import { teamService, Team } from '../../services/teamService';
import { manpowerService, Worker } from '../../services/manpowerService';
import { dailyReportService, DailyReport } from '../../services/dailyReportService';

import { geminiService } from '../../services/geminiService';
import { useAuth } from '../../contexts/AuthContext';
import Swal from 'sweetalert2';

// Register all Handsontable modules
registerAllModules();

interface GridRow {
    id: string;
    teamId: string;
    teamName: string;
    workerId: string;
    name: string;
    manDay: number;
    unitPrice: number | null;
    payType: string; // 급여구분 (New)
    role: string;
    description: string; // 작업내용
    workerTeamId?: string; // Original Team ID of the worker
    workerTeamName?: string; // Original Team Name of the worker
}

interface Ledger {
    id: string;
    siteId: string;
    rows: GridRow[];
    description: string; // Ledger-level Work Content
}

const normalizeSalaryType = (value?: string | null): string => {
    const normalized = String(value ?? '').trim();
    if (!normalized) return '';
    if (normalized === '일급') return '일급제';
    if (normalized === '월급') return '월급제';
    return normalized;
};

const resolveWorkerSalaryType = (worker?: Partial<Worker> | null): string => {
    if (!worker) return '일급제';

    const teamType = normalizeSalaryType(worker.teamType);
    if (teamType === '지원팀') return '지원팀';
    if (teamType === '용역팀') return '용역팀';

    const salaryModel = normalizeSalaryType(worker.salaryModel);
    if (salaryModel) return salaryModel;

    const payType = normalizeSalaryType(worker.payType);
    if (payType) return payType;

    return '일급제';
};

const resolveReportWorkerSalaryType = (
    reportWorker?: { payType?: string | null; salaryModel?: string | null } | null,
    worker?: Partial<Worker> | null
): string => {
    const payType = normalizeSalaryType(reportWorker?.payType);
    if (payType) return payType;

    const salaryModel = normalizeSalaryType(reportWorker?.salaryModel);
    if (salaryModel) return salaryModel;

    return resolveWorkerSalaryType(worker);
};

// --- Child Component: DailyReportTable ---
const DailyReportTable: React.FC<{
    ledger: Ledger;
    ledgerIndex: number;
    sites: Site[];
    teams: Team[];
    workerMap: Map<string, Worker & { isDuplicateName?: boolean }>;
    globalDuplicateNames: Set<string>;
    onUpdate: (ledgerId: string, updates: Partial<Ledger>) => void;
    onDelete: (ledgerId: string) => void;
    onAddRow: (ledgerId: string) => void; 
}> = ({ ledger, ledgerIndex, sites, teams, workerMap, globalDuplicateNames, onUpdate, onDelete, onAddRow }) => {

    const hotRef = useRef<any>(null);
    const isEditingNameCellRef = useRef(false);
    const duplicateInputNamesRef = useRef<Set<string>>(new Set());

    const buildDuplicateInputNames = useCallback((rows: GridRow[]): Set<string> => {
        const counts = new Map<string, number>();
        rows.forEach((row) => {
            const normalized = String(row.name ?? '').replace(/\s+/g, '').trim();
            if (!normalized) return;
            counts.set(normalized, (counts.get(normalized) ?? 0) + 1);
        });
        const duplicates = new Set<string>();
        counts.forEach((count, name) => {
            if (count > 1) duplicates.add(name);
        });
        return duplicates;
    }, []);

    const buildDuplicateInputNamesFromNames = useCallback((names: unknown[]): Set<string> => {
        const counts = new Map<string, number>();
        names.forEach((name) => {
            const normalized = String(name ?? '').replace(/\s+/g, '').trim();
            if (!normalized) return;
            counts.set(normalized, (counts.get(normalized) ?? 0) + 1);
        });
        const duplicates = new Set<string>();
        counts.forEach((count, name) => {
            if (count > 1) duplicates.add(name);
        });
        return duplicates;
    }, []);

    const syncDuplicateFromHot = useCallback(() => {
        const hot = hotRef.current?.hotInstance;
        if (!hot) return;
        try {
            if (!hot.isDestroyed) {
                const colValues = hot.getDataAtCol(0) as unknown[];
                duplicateInputNamesRef.current = buildDuplicateInputNamesFromNames(colValues);
            }
        } catch {
        }
    }, [buildDuplicateInputNamesFromNames]);

    useEffect(() => {
        duplicateInputNamesRef.current = buildDuplicateInputNames(ledger.rows);
    }, [buildDuplicateInputNames, ledger.rows]);

    useLayoutEffect(() => {
        let cancelled = false;
        let boundHot: any = null;

        const handleAfterBeginEditing = (_row: number, col: number) => {
            isEditingNameCellRef.current = col === 0;
            if (col === 0) {
                syncDuplicateFromHot();
            }
            try {
                if (boundHot && !boundHot.isDestroyed) {
                    boundHot.render();
                }
            } catch {
            }
        };

        const handleAfterEndEditing = () => {
            syncDuplicateFromHot();
            try {
                if (boundHot && !boundHot.isDestroyed) {
                    boundHot.render();
                }
            } catch {
            }

            requestAnimationFrame(() => {
                isEditingNameCellRef.current = false;
                syncDuplicateFromHot();
                try {
                    if (boundHot && !boundHot.isDestroyed) {
                        boundHot.render();
                    }
                } catch {
                }
            });
        };

        const tryBindHooks = () => {
            if (cancelled) return;
            const hot = hotRef.current?.hotInstance;
            if (!hot) {
                requestAnimationFrame(tryBindHooks);
                return;
            }
            boundHot = hot;
            hot.addHook('afterBeginEditing', handleAfterBeginEditing);
            hot.addHook('afterEndEditing', handleAfterEndEditing);
        };

        tryBindHooks();

        return () => {
            cancelled = true;
            if (!boundHot) return;
            try {
                if (!boundHot.isDestroyed) {
                    boundHot.removeHook('afterBeginEditing', handleAfterBeginEditing);
                    boundHot.removeHook('afterEndEditing', handleAfterEndEditing);
                }
            } catch {
            }
        };
    }, []);

    // Convert rows to 2D array for Handsontable
    const tableData = useMemo(() => {
        return ledger.rows.map(row => [row.name, row.manDay, row.teamName, row.unitPrice, row.payType]);
    }, [ledger.rows]);

    const handleAfterChange = useCallback((changes: any, source: string) => {
        if (!changes || source === 'loadData') return;

        const newRows = ledger.rows.map(row => ({ ...row }));
        let didChangeName = false;

        changes.forEach(([row, col, oldValue, newValue]: [number, number, any, any]) => {
            if (row >= newRows.length) return;

            if (col === 0) { // Name column
                didChangeName = true;
                const rawName = newValue?.toString() || '';
                const searchName = rawName.replace(/\s+/g, ''); 
                newRows[row].name = rawName;

                if (searchName) {
                    const matchedWorker = workerMap.get(searchName);
                    if (matchedWorker) {
                        newRows[row].workerId = matchedWorker.id || '';
                        newRows[row].unitPrice = matchedWorker.unitPrice || 0;
                        newRows[row].payType = resolveWorkerSalaryType(matchedWorker);
                        newRows[row].role = matchedWorker.role || '작업자';

                        const team = matchedWorker.teamId ? teams.find(t => t.id === matchedWorker.teamId) : undefined;
                        if (team) {
                            newRows[row].teamName = team.name;
                            newRows[row].teamId = team.id || '';
                            newRows[row].workerTeamName = team.name;
                            newRows[row].workerTeamId = team.id || '';
                        } else {
                            const masterTeamName = matchedWorker.teamName || (matchedWorker as any).workerTeamName || '';
                            const masterTeamId = matchedWorker.teamId || (matchedWorker as any).workerTeamId || '';
                            newRows[row].teamName = masterTeamName;
                            newRows[row].teamId = masterTeamId;
                            newRows[row].workerTeamName = masterTeamName;
                            newRows[row].workerTeamId = masterTeamId;
                        }
                    } else {
                        newRows[row].workerId = '';
                        newRows[row].unitPrice = null;
                        newRows[row].payType = '';
                        newRows[row].role = '작업자';
                    }
                } else {
                    newRows[row].workerId = '';
                    newRows[row].unitPrice = null;
                    newRows[row].payType = '';
                    newRows[row].role = '작업자';
                    newRows[row].teamName = '';
                    newRows[row].teamId = '';
                    newRows[row].description = '';
                }
            } else if (col === 1) { 
                newRows[row].manDay = Number(newValue) || 1;
            } else if (col === 3) { 
                newRows[row].unitPrice = Number(newValue) || 0;
            } else if (col === 4) { 
                newRows[row].payType = newValue?.toString() || '';
            }
        });

        if (didChangeName) {
            syncDuplicateFromHot();
            try {
                const hot = hotRef.current?.hotInstance;
                if (hot && !hot.isDestroyed) {
                    hot.render();
                }
            } catch {
            }
        }

        onUpdate(ledger.id, { rows: newRows });
    }, [syncDuplicateFromHot, ledger.id, ledger.rows, onUpdate, teams, workerMap]);

    const normalizedLedgerSiteId = String(ledger.siteId ?? '').trim();
    const siteOptions = useMemo(
        () =>
            sites
                .map((site) => ({
                    id: String(site.id ?? '').trim(),
                    name: String(site.name ?? '').trim()
                }))
                .filter((site) => Boolean(site.id) && Boolean(site.name)),
        [sites]
    );
    const selectedSite = sites.find((s) => String(s.id ?? '').trim() === normalizedLedgerSiteId);

    const siteTeams = useMemo(() => {
        if (!normalizedLedgerSiteId) return [];
        const site = sites.find((s) => String(s.id ?? '').trim() === normalizedLedgerSiteId);
        if (!site || !site.responsibleTeamId) return [];
        return teams.filter(t => t.id === site.responsibleTeamId);
    }, [normalizedLedgerSiteId, sites, teams]);

    const handleAddTeamMembers = (team: Team) => {
        const teamWorkers = Array.from(workerMap.values()).filter(w => w.teamId === team.id);
        if (teamWorkers.length === 0) {
            Swal.fire('Info', '해당 팀에 등록된 작업자가 없거나 모두 퇴사 상태입니다.', 'info');
            return;
        }
        const newRows = [...ledger.rows];
        let insertIndex = newRows.findIndex(r => !r.name || r.name.trim() === '');
        if (insertIndex === -1) insertIndex = newRows.length;

        let filledCount = 0;
        teamWorkers.forEach(worker => {
            const targetIndex = newRows.findIndex((r, idx) => idx >= insertIndex && (!r.name || r.name.trim() === ''));
            if (targetIndex !== -1) {
                newRows[targetIndex] = {
                    ...newRows[targetIndex],
                    workerId: worker.id || '',
                    name: worker.name,
                    manDay: 1.0,
                    teamId: team.id || '',
                    teamName: team.name,
                    unitPrice: worker.unitPrice || 0,
                    payType: resolveWorkerSalaryType(worker),
                    role: worker.role || '작업자',
                    description: '',
                    workerTeamId: team.id || '',
                    workerTeamName: team.name
                };
                filledCount++;
            }
        });
        if (filledCount < teamWorkers.length) {
            Swal.fire('Warning', `빈 행이 부족하여 ${teamWorkers.length - filledCount}명을 추가하지 못했습니다. 행을 추가해주세요.`, 'warning');
        }
        onUpdate(ledger.id, { rows: newRows });
    };

    const isSiteMissing = !ledger.siteId;
    const unknownWorkersCount = ledger.rows.filter(r => r.name.trim() !== '' && !r.workerId).length;
    const totalManDay = ledger.rows.reduce((sum, r) => {
        if (!r.name || r.name.trim() === '') return sum;
        return sum + (Number(r.manDay) || 0);
    }, 0);

    return (
        <div className={`border rounded-lg overflow-hidden shadow-sm flex flex-col w-[415px] bg-white transition-all ${isSiteMissing ? 'border-red-400 ring-1 ring-red-400' : 'border-slate-300'}`}>
            <div className={`px-2 py-1 flex flex-col shrink-0 ${isSiteMissing ? 'bg-red-500' : 'bg-[#4A192C]'} text-white transition-colors`}>
                <div className="flex justify-between items-center w-full">
                    <div className="flex items-center gap-2 flex-1">
                        <span className="font-bold text-xs whitespace-nowrap">장부{ledgerIndex}</span>
                        <div style={{ minWidth: 180, flex: 1 }}>
                            <SingleSelectPopover
                                options={siteOptions}
                                selectedId={normalizedLedgerSiteId || null}
                                onSelect={(siteId) => onUpdate(ledger.id, { siteId: String(siteId ?? '').trim() })}
                                renderSelected={(selectedOption) => (
                                    <span className="text-slate-800 font-medium">{selectedOption.name}</span>
                                )}
                                placeholder="현장명을 검색/선택하세요"
                            />
                        </div>
                    </div>
                    <div className="flex items-center gap-2">
                        <span className="bg-white/20 text-white text-[10px] px-1.5 py-0.5 rounded font-bold" title="총 공수">
                            {totalManDay.toFixed(1)}공수
                        </span>
                        {unknownWorkersCount > 0 && (
                            <span className="bg-yellow-400 text-slate-900 text-[10px] px-1.5 rounded-full font-bold flex items-center gap-1" title="등록되지 않은 작업자 수">
                                <FontAwesomeIcon icon={faExclamationTriangle} /> {unknownWorkersCount}
                            </span>
                        )}
                        <button onClick={() => onDelete(ledger.id)} className="ml-1 text-white/70 hover:text-white" title="장부 삭제">
                            <FontAwesomeIcon icon={faTimes} />
                        </button>
                    </div>
                </div>

                {selectedSite && (
                    <div className="mt-1 pb-1 flex flex-wrap gap-x-3 gap-y-1 text-[10px] text-white/90 border-t border-white/20 pt-1">
                        {selectedSite.clientCompanyName && selectedSite.clientCompanyName.trim() !== '' && (
                            <div className="flex items-center gap-1" title="발주사">
                                <span>🏢</span>
                                <span className="opacity-70 text-[9px]">발주:</span>
                                <span className="font-medium">{selectedSite.clientCompanyName}</span>
                            </div>
                        )}
                        {selectedSite.companyName && selectedSite.companyName.trim() !== '' && selectedSite.companyName !== selectedSite.partnerName && (
                            <div className="flex items-center gap-1" title="시공사">
                                <span>🏗️</span>
                                <span className="opacity-70 text-[9px]">시공:</span>
                                <span className="font-medium">{selectedSite.companyName}</span>
                            </div>
                        )}
                        {selectedSite.partnerName && selectedSite.partnerName.trim() !== '' && (
                            <div className="flex items-center gap-1" title="협력사">
                                <span>🤝</span>
                                <span className="opacity-70 text-[9px]">협력:</span>
                                <span className="font-medium">{selectedSite.partnerName}</span>
                            </div>
                        )}
                        {selectedSite.responsibleTeamName && (
                            <button
                                onClick={() => {
                                    const team = siteTeams.find(t => t.id === selectedSite.responsibleTeamId);
                                    if (team) handleAddTeamMembers(team);
                                }}
                                disabled={!siteTeams.find(t => t.id === selectedSite.responsibleTeamId)}
                                className="flex items-center gap-1 hover:bg-white/20 px-1 py-0.5 rounded cursor-pointer transition-colors"
                                title="현장담당팀 (클릭하여 팀원 일괄 추가)"
                            >
                                <span>👷</span>
                                <span className="opacity-70 text-[9px]">현장담당팀:</span>
                                <span className="font-medium underline decoration-dotted">{selectedSite.responsibleTeamName}</span>
                            </button>
                        )}
                    </div>
                )}
            </div>

            <div className="handsontable-container relative">
                <HotTable
                    ref={hotRef}
                    data={tableData}
                    colHeaders={['이름', '공수', '소속팀', '단가', '급여']}
                    columns={[
                        { type: 'text', width: 80 }, 
                        { type: 'numeric', width: 50 }, 
                        { type: 'text', width: 80, readOnly: true, className: 'htDimmed' }, 
                        { type: 'numeric', width: 80, numericFormat: { pattern: '0,0' }, readOnly: true, className: 'htDimmed' }, 
                        { type: 'text', width: 60 }, 
                    ]}
                    rowHeaders={false}
                    width="100%"
                    height="auto"
                    stretchH="all"
                    autoWrapRow={true}
                    autoWrapCol={true}
                    licenseKey="non-commercial-and-evaluation"
                    enterBeginsEditing={true}
                    enterMoves={{ row: 1, col: 0 }}
                    tabMoves={{ row: 0, col: 1 }}
                    fillHandle={true}
                    afterChange={handleAfterChange}
                    beforeOnCellMouseDown={(event: MouseEvent, coords: any) => {
                        if (coords.col >= 2 && coords.col <= 3) event.stopImmediatePropagation();
                    }}
                    afterSelection={(r: number, c: number) => {
                        if (c >= 2 && c <= 3) {
                            const hot = hotRef.current?.hotInstance;
                            if (hot) hot.selectCell(r + 1, 0);
                        }
                    }}
                    imeFastEdit={true}
                    cells={(row, col, prop) => {
                        const cellProperties: any = {};
                        if (col === 0) {
                            const hot = hotRef.current?.hotInstance;
                            const rawName = hot ? hot.getDataAtCell(row, 0) : '';
                            const normalized = String(rawName ?? '').replace(/\s+/g, '').trim();
                            if (normalized) {
                                const matchedWorker = workerMap.get(normalized);
                                if (!matchedWorker) {
                                    cellProperties.className = 'unknown-worker-cell';
                                    cellProperties.title = "등록되지 않았거나 퇴사한 작업자입니다. 확인해주세요.";
                                } else if (matchedWorker.isDuplicateName) {
                                    cellProperties.className = 'duplicate-worker-cell';
                                    cellProperties.title = `동명이인이 존재합니다 (${matchedWorker.teamName}). 정확한 인원인지 확인해주세요.`;
                                } else if (globalDuplicateNames.has(normalized)) {
                                    cellProperties.className = 'duplicate-worker-cell';
                                    cellProperties.title = "당일 다른 장부(현장)에 동일 이름이 이미 입력되었습니다.";
                                } else if (isEditingNameCellRef.current) {
                                    if (duplicateInputNamesRef.current.has(normalized)) {
                                        cellProperties.className = 'duplicate-worker-cell';
                                        cellProperties.title = "이 장부 내에 동일 이름이 2회 이상 입력되었습니다.";
                                    }
                                }
                            }
                        }
                        return cellProperties;
                    }}
                />
            </div>

            <div className="px-3 py-2 bg-slate-50 border-t border-slate-200">
                <div className="flex items-center gap-2">
                    <span className="text-xs font-bold text-slate-600 shrink-0">
                        <FontAwesomeIcon icon={faComment} className="mr-1" />
                        작업내용
                    </span>
                    <input
                        type="text"
                        value={ledger.description || ''}
                        onChange={(e) => onUpdate(ledger.id, { description: e.target.value })}
                        placeholder="이 현장의 금일 작업내용을 입력하세요"
                        className="flex-1 text-xs px-2 py-1 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                    />
                    <button
                        onClick={() => onAddRow(ledger.id)}
                        className="px-2 py-1 bg-slate-200 text-slate-700 rounded hover:bg-slate-300 text-xs font-bold transition-colors flex items-center gap-1 shrink-0"
                        title="행 추가"
                    >
                        <FontAwesomeIcon icon={faPlus} />
                        행 추가
                    </button>
                </div>
            </div>
        </div>
    );
};


// --- Main Component ---
const DailyReportGridInput: React.FC = () => {
    const { currentUser } = useAuth();
    const [ledgers, setLedgers] = useState<Ledger[]>([]);
    const [sites, setSites] = useState<Site[]>([]);
    const [teams, setTeams] = useState<Team[]>([]);
    const [workers, setWorkers] = useState<Worker[]>([]);

    useEffect(() => {
        const unsubscribe = manpowerService.subscribeWorkers((newWorkers) => {
            setWorkers(newWorkers);
        });
        return () => unsubscribe();
    }, []);

    const [date, setDate] = useState(new Date().toISOString().slice(0, 10));
    const [weather, setWeather] = useState('맑음');
    const [loading, setLoading] = useState(false);
    const [fetching, setFetching] = useState(true);
    const [isDragging, setIsDragging] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const normalizeSiteId = useCallback((value: unknown): string => String(value ?? '').trim(), []);

    const buildWorkerSearchMap = useCallback((workerList: Worker[]) => {
        const map = new Map<string, Worker & { isDuplicateName?: boolean }>();
        const activeWorkers = workerList.filter(w => w.status !== '퇴사' && w.status !== '퇴사자');
        const nameCounts = new Map<string, number>();
        activeWorkers.forEach(w => {
            const key = w.name.replace(/\s+/g, '');
            nameCounts.set(key, (nameCounts.get(key) || 0) + 1);
        });
        activeWorkers.forEach(w => {
            const key = w.name.replace(/\s+/g, '');
            const isDuplicate = nameCounts.get(key)! > 1;
            map.set(key, { ...w, isDuplicateName: isDuplicate });
        });
        return map;
    }, []);

    const workerMap = useMemo(() => buildWorkerSearchMap(workers), [workers, buildWorkerSearchMap]);

    const globalDuplicateNames = useMemo(() => {
        const counts = new Map<string, number>();
        ledgers.forEach(ledger => {
            ledger.rows.forEach(row => {
                const normalized = String(row.name ?? '').replace(/\s+/g, '').trim();
                if (!normalized) return;
                counts.set(normalized, (counts.get(normalized) ?? 0) + 1);
            });
        });
        const duplicates = new Set<string>();
        counts.forEach((count, name) => {
            if (count > 1) duplicates.add(name);
        });
        return duplicates;
    }, [ledgers]);

    const validationSummary = useMemo(() => {
        let missingSites = 0;
        let unknownWorkers = 0;
        let totalWorkers = 0;
        ledgers.forEach(ledger => {
            if (!ledger.siteId) missingSites++;
            ledger.rows.forEach(r => {
                if (r.name.trim() !== '') {
                    totalWorkers++;
                    if (!r.workerId) unknownWorkers++;
                }
            });
        });
        return { missingSites, unknownWorkers, totalWorkers };
    }, [ledgers]);

    const fetchMasterData = useCallback(
        async (options?: { rematchLedgers?: boolean }) => {
            try {
                setFetching(true);
                const [sitesData, teamsData, workersData] = await Promise.all([
                    siteService.getSites(),
                    teamService.getTeams(),
                    manpowerService.getWorkers(true)
                ]);
                setSites(sitesData);
                setTeams(teamsData);
                setWorkers(workersData);

                if (options?.rematchLedgers) {
                    const workerByName = buildWorkerSearchMap(workersData);
                    const teamById = new Map<string, Team>();
                    teamsData.forEach(t => { if (t.id) teamById.set(t.id, t); });

                    setLedgers(prev =>
                        prev.map(ledger => ({
                            ...ledger,
                            rows: ledger.rows.map(row => {
                                if (row.name.trim().length === 0 || row.workerId.trim().length > 0) return row;
                                const key = row.name.replace(/\s+/g, '');
                                const matchedWorker = workerByName.get(key);
                                if (!matchedWorker) return row;
                                const matchedTeam = matchedWorker.teamId ? teamById.get(matchedWorker.teamId) : undefined;
                                return {
                                    ...row,
                                    workerId: matchedWorker.id ?? '',
                                    unitPrice: matchedWorker.unitPrice ?? 0,
                                    payType: row.payType || resolveWorkerSalaryType(matchedWorker),
                                    role: matchedWorker.role || '작업자',
                                    teamId: matchedTeam?.id ?? matchedWorker.teamId ?? (matchedWorker as any).workerTeamId ?? '',
                                    teamName: matchedTeam?.name ?? matchedWorker.teamName ?? (matchedWorker as any).workerTeamName ?? '',
                                    workerTeamId: matchedTeam?.id ?? matchedWorker.teamId ?? (matchedWorker as any).workerTeamId ?? '',
                                    workerTeamName: matchedTeam?.name ?? matchedWorker.teamName ?? (matchedWorker as any).workerTeamName ?? ''
                                };
                            })
                        }))
                    );
                }
            } catch (error) {
                console.error('Failed to fetch master data', error);
            } finally {
                setFetching(false);
            }
        },
        [buildWorkerSearchMap]
    );

    const stateRef = useRef({ ledgers, date });
    const [hasTempData, setHasTempData] = useState(false);

    useEffect(() => {
        stateRef.current = { ledgers, date };
    }, [ledgers, date]);

    const performSave = useCallback(() => {
        try {
            const current = stateRef.current;
            const isInitialEmpty = current.ledgers.length === 0 || (current.ledgers.length === 1 && !current.ledgers[0].siteId && current.ledgers[0].rows.every(r => !r.name || r.name.trim() === ''));
            if (isInitialEmpty) return;
            const tempData = { ledgers: current.ledgers, date: current.date, savedAt: Date.now() };
            localStorage.setItem('daily_report_temp_data', JSON.stringify(tempData));
            setHasTempData(true);
        } catch (e) {
            console.error("Temp save failed", e);
        }
    }, []);

    const loadTempData = useCallback(async () => {
        try {
            const tempDataStr = localStorage.getItem('daily_report_temp_data');
            if (!tempDataStr) return false;
            const tempData = JSON.parse(tempDataStr);
            if (Date.now() - tempData.savedAt > 24 * 60 * 60 * 1000) {
                localStorage.removeItem('daily_report_temp_data');
                return false;
            }
            setLedgers(tempData.ledgers);
            if (tempData.date) setDate(tempData.date);
            setHasTempData(true);
            return true;
        } catch (e) {
            console.error("Failed to load temp data", e);
            localStorage.removeItem('daily_report_temp_data');
            return false;
        }
    }, []);

    const clearTempData = useCallback(() => {
        localStorage.removeItem('daily_report_temp_data');
        setHasTempData(false);
    }, []);

    useEffect(() => {
        const timer = setTimeout(() => { performSave(); }, 1000);
        return () => clearTimeout(timer);
    }, [ledgers, date, performSave]);

    useEffect(() => {
        const handleBeforeUnload = () => { performSave(); };
        window.addEventListener('beforeunload', handleBeforeUnload);
        return () => {
            window.removeEventListener('beforeunload', handleBeforeUnload);
            performSave();
        };
    }, [performSave]);

    const fetchReportsForDate = useCallback(async (targetDate: string) => {
        try {
            setFetching(true);
            const reports = await dailyReportService.getReports(targetDate);
            if (reports.length === 0) return null;

            const siteGroups = new Map<string, DailyReport[]>();
            reports.forEach(r => {
                const siteIdKey = normalizeSiteId(r.siteId);
                if (!siteIdKey) return;
                const list = siteGroups.get(siteIdKey) || [];
                list.push(r);
                siteGroups.set(siteIdKey, list);
            });

            const newLedgers: Ledger[] = [];
            siteGroups.forEach((siteReports, siteId) => {
                const uniqueContent = Array.from(new Set(siteReports.map(r => r.workContent).filter(Boolean))).join(', ');
                const aggregatedRows: GridRow[] = [];
                siteReports.forEach(report => {
                    const reportTeamId = report.teamId || '';
                    const reportTeamName = report.teamName || (teams.find(t => t.id === reportTeamId)?.name) || '';
                    report.workers.forEach(w => {
                        const wId = w.workerId || '';
                        const wName = w.name || (w as any).workerName || '';
                        const workerBase = workers.find(wk => wk.id === wId) || workers.find(wk => wk.name === wName);
                        const finalWorkerName = wName || workerBase?.name || '';
                        const finalTeamId = w.teamId || (w as any).workerTeamId || workerBase?.teamId || reportTeamId;
                        const finalTeamName = (w as any).teamName || (teams.find(t => t.id === finalTeamId)?.name) || reportTeamName;

                        aggregatedRows.push({
                            id: Math.random().toString(36).substr(2, 9),
                            teamId: finalTeamId,
                            teamName: finalTeamName,
                            workerId: wId,
                            name: finalWorkerName,
                            manDay: (w as any).gongsu || w.manDay || 0,
                            unitPrice: w.unitPrice ?? 0,
                            payType: resolveReportWorkerSalaryType(w as any, workerBase),
                            role: w.role || '작업자',
                            description: w.workContent || (w as any).workDescription || '',
                            workerTeamId: finalTeamId,
                            workerTeamName: finalTeamName
                        });
                    });
                });
                const rows = [...aggregatedRows];
                const needed = 20 - rows.length;
                if (needed > 0) rows.push(...createEmptyRows(needed));
                else rows.push(...createEmptyRows(5));

                newLedgers.push({ id: Date.now().toString() + Math.random(), siteId, rows: rows, description: uniqueContent });
            });
            return newLedgers;
        } catch (error) {
            console.error("Failed to fetch reports for date", error);
            return null;
        } finally {
            setFetching(false);
        }
    }, [normalizeSiteId, sites, teams, workers]);

    useEffect(() => {
        const run = async () => {
            if (sites.length === 0 || teams.length === 0) await fetchMasterData();
            setFetching(true);
            const serverLedgers = await fetchReportsForDate(date);
            if (serverLedgers && serverLedgers.length > 0) {
                setLedgers(serverLedgers);
                setHasTempData(false);
            } else {
                const loaded = await loadTempData();
                if (!loaded) {
                    setLedgers([{ id: Date.now().toString(), siteId: '', rows: createEmptyRows(20), description: '' }]);
                } else {
                    const tempDataStr = localStorage.getItem('daily_report_temp_data');
                    if (tempDataStr) {
                        const parsed = JSON.parse(tempDataStr);
                        if (parsed.date !== date) {
                            setLedgers([{ id: Date.now().toString(), siteId: '', rows: createEmptyRows(20), description: '' }]);
                            setHasTempData(false);
                        }
                    }
                }
            }
            setFetching(false);
        };
        run();
    }, [date, fetchMasterData, fetchReportsForDate]);

    useEffect(() => {
        const onMasterDataChanged = (event: Event) => {
            const customEvent = event as CustomEvent<{ workers?: boolean; teams?: boolean; sites?: boolean; }>;
            if (customEvent.detail?.workers || customEvent.detail?.teams || customEvent.detail?.sites) {
                fetchMasterData({ rematchLedgers: true }).catch(err => console.error(err));
            }
        };
        window.addEventListener('smart-construction:master-data-changed', onMasterDataChanged);
        return () => window.removeEventListener('smart-construction:master-data-changed', onMasterDataChanged);
    }, [fetchMasterData]);

    const createEmptyRows = (count: number): GridRow[] => {
        return Array(count).fill(null).map(() => ({
            id: Math.random().toString(36).substr(2, 9),
            teamId: '', teamName: '', workerId: '', name: '', manDay: 1.0, unitPrice: null, payType: '', role: '작업자', description: '', workerTeamId: '', workerTeamName: ''
        }));
    };

    const addLedger = useCallback(() => {
        setLedgers(prev => [...prev, { id: Date.now().toString(), siteId: '', rows: createEmptyRows(20), description: '' }]);
    }, []);

    const removeLedger = useCallback((id: string) => { setLedgers(prev => prev.filter(l => l.id !== id)); }, []);
    const removeLastLedger = useCallback(() => { setLedgers(prev => prev.length > 0 ? prev.slice(0, -1) : prev); }, []);
    const updateLedger = useCallback((id: string, updates: Partial<Ledger>) => { setLedgers(prev => prev.map(l => l.id === id ? { ...l, ...updates } : l)); }, []);
    const handleReset = useCallback(async () => {
        const result = await Swal.fire({ title: '작성 내용 초기화', text: '현재 입력된 모든 내용을 삭제하고 새로 시작하시겠습니까?', icon: 'warning', showCancelButton: true, confirmButtonText: '초기화', cancelButtonText: '취소', confirmButtonColor: '#d33' });
        if (result.isConfirmed) setLedgers([{ id: Date.now().toString(), siteId: '', rows: createEmptyRows(20), description: '' }]);
    }, []);
    const addRowToLedger = useCallback((id: string) => {
        setLedgers(prev => prev.map(l => l.id !== id ? l : { ...l, rows: [...l.rows, ...createEmptyRows(5)] }));
    }, []);

    const handleSaveAll = async () => {
        if (validationSummary.missingSites > 0) { Swal.fire('Warning', '현장이 선택되지 않은 장부가 있습니다.', 'warning'); return; }
        setLoading(true);
        try {
            const allReports: Omit<DailyReport, 'id'>[] = [];
            const involvedTeamIds = new Set<string>();
            let skippedGroupCount = 0;
            for (const ledger of ledgers) {
                const normalizedLedgerSiteId = normalizeSiteId(ledger.siteId);
                if (!normalizedLedgerSiteId) continue;
                const validRows = ledger.rows.filter(r => r.name.trim() !== '');
                if (validRows.length === 0) continue;
                const groups: { [key: string]: GridRow[] } = {};
                validRows.forEach(row => { const key = normalizeSiteId(row.teamId) || 'no-team'; if (!groups[key]) groups[key] = []; groups[key].push(row); });
                const site = sites.find((s) => normalizeSiteId(s.id) === normalizedLedgerSiteId);
                Object.entries(groups).forEach(([teamKey, rows]) => {
                    const realTeamId = teamKey === 'no-team' ? '' : normalizeSiteId(teamKey);
                    const fallbackTeamId = normalizeSiteId(site?.responsibleTeamId) || normalizeSiteId(rows[0]?.workerTeamId) || normalizeSiteId(rows[0]?.teamId);
                    const resolvedTeamId = realTeamId || fallbackTeamId;
                    const team = teams.find((t) => normalizeSiteId(t.id) === resolvedTeamId);
                    if (!resolvedTeamId) { skippedGroupCount += 1; return; }
                    involvedTeamIds.add(resolvedTeamId);
                    const totalManDay = rows.reduce((sum, r) => sum + r.manDay, 0);
                    const reportWorkers = rows.map(r => {
                        const matchedWorker = workers.find(w => w.id === r.workerId);
                        const resolvedSalaryType = normalizeSalaryType(r.payType) || resolveWorkerSalaryType(matchedWorker);
                        return { salaryModel: resolvedSalaryType, payType: resolvedSalaryType, workerId: r.workerId || 'unknown', name: r.name, role: r.role, status: 'attendance' as const, manDay: r.manDay, workContent: r.description, teamId: normalizeSiteId(r.teamId) || resolvedTeamId, unitPrice: r.unitPrice ?? 0, workerTeamId: normalizeSiteId(r.workerTeamId) || normalizeSiteId(r.teamId) || resolvedTeamId, workerTeamName: r.workerTeamName || r.teamName || team?.name || site?.responsibleTeamName || '' };
                    });
                    allReports.push({ date, teamId: resolvedTeamId, teamName: team?.name || site?.responsibleTeamName || rows[0]?.teamName || '', siteId: normalizedLedgerSiteId, siteName: site?.name || '', writerId: currentUser?.uid || 'unknown', workers: reportWorkers, totalManDay, responsibleTeamId: normalizeSiteId(site?.responsibleTeamId) || resolvedTeamId, responsibleTeamName: site?.responsibleTeamName || team?.name || '', companyId: site?.clientCompanyId || '', companyName: site?.clientCompanyName || '', constructorCompanyId: site?.companyId || '', constructorCompanyName: site?.companyName || '', partnerId: site?.partnerId || '', partnerName: site?.partnerName != null ? String(site.partnerName) : '', workContent: ledger.description || '' });
                });
            }
            if (allReports.length > 0) {
                await dailyReportService.overwriteReports(date, allReports, Array.from(involvedTeamIds));
                clearTempData();
                alert(`${allReports.length}건의 일보가 저장되었습니다.`);
            } else {
                alert('저장할 데이터가 없습니다.');
            }
        } catch (error) { console.error(error); alert('저장 중 오류가 발생했습니다.'); } finally { setLoading(false); }
    };

    const processKakaoImage = async (file: File) => {
        if (!file.type.startsWith('image/')) {
            Swal.fire('Error', '이미지 파일만 가능합니다.', 'error');
            return;
        }
        const apiKey = geminiService.getKey();
        if (!apiKey) {
            Swal.fire('Info', 'API 키 설정이 필요합니다. (/settings/ai)', 'info');
            return;
        }
        setLoading(true);
        try {
            const analyzedReports = await geminiService.analyzeKakaoImage(file);
            const newLedgers: Ledger[] = [];
            let totalUnknowns = 0;
            for (const report of analyzedReports) {
                const site = sites.find(s => s.name === report.siteName) || sites.find(s => s.name.includes(report.siteName || '') || (report.siteName || '').includes(s.name));
                const siteId = site?.id || '';
                const rows = createEmptyRows(20);
                report.workers.forEach((w, idx) => {
                    const worker = workers.find(wk => wk.name === w.name);
                    if (!worker) totalUnknowns++;
                    rows[idx] = {
                        id: Math.random().toString(36).substr(2, 9),
                        name: w.name,
                        manDay: w.manDay || 1,
                        teamId: worker?.teamId || '',
                        teamName: worker?.teamType === '지원팀' ? '지원' : (worker ? (teams.find(t => t.id === worker.teamId)?.name || '') : ''),
                        workerId: worker?.id || '',
                        unitPrice: worker?.unitPrice || 0,
                        payType: resolveWorkerSalaryType(worker),
                        role: w.role || worker?.role || '작업자',
                        description: w.workContent || '',
                        workerTeamId: worker?.teamId || '',
                        workerTeamName: worker?.teamType === '지원팀' ? '지원' : (worker ? (teams.find(t => t.id === worker.teamId)?.name || worker?.teamName || '') : '')
                    };
                });
                const aggregatedContent = Array.from(new Set(report.workers.map(w => w.workContent).filter(Boolean))).join(', ');
                newLedgers.push({ id: Date.now().toString() + Math.random(), siteId, rows: rows, description: aggregatedContent });
            }
            if (newLedgers.length === 0) { Swal.fire('Info', '인식된 데이터가 없습니다.', 'info'); return; }
            setLedgers(prev => {
                if (prev.length === 1 && !prev[0].siteId && prev[0].rows.every(r => !r.name)) return newLedgers;
                return [...prev, ...newLedgers];
            });
            let message = `${newLedgers.length}개의 장부가 생성되었습니다.`;
            if (totalUnknowns > 0) {
                message += `\n⚠️ 식별되지 않은 작업자 ${totalUnknowns}명이 있습니다. 빨간색으로 표시된 항목을 확인해주세요.`;
                Swal.fire({ title: 'AI 분석 완료 (확인 필요)', text: message, icon: 'warning', confirmButtonText: '확인' });
            } else { Swal.fire('Success', message, 'success'); }
        } catch (error) {
            console.error(error);
            const message = error instanceof Error ? error.message : '이미지 분석에 실패했습니다.';
            Swal.fire('Error', `이미지 분석에 실패했습니다.\n${message}`, 'error');
        } finally { setLoading(false); }
    };

    const hasWarnings = validationSummary.unknownWorkers > 0 || validationSummary.missingSites > 0;

    return (
        <div className="flex flex-col h-full bg-slate-50 overflow-hidden relative" onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }} onDragLeave={(e) => { e.preventDefault(); if (!e.currentTarget.contains(e.relatedTarget as Node)) setIsDragging(false); }} onDrop={(e) => { e.preventDefault(); setIsDragging(false); const file = e.dataTransfer.files?.[0]; if (file) processKakaoImage(file); }}>
            {isDragging && (
                <div className="absolute inset-0 bg-yellow-400/80 z-50 flex items-center justify-center backdrop-blur-sm pointer-events-none">
                    <div className="text-center bg-white p-8 rounded-2xl shadow-2xl">
                        <FontAwesomeIcon icon={faComment} className="text-6xl text-yellow-500 mb-4" />
                        <h2 className="text-3xl font-bold text-slate-800">카톡 이미지 떨어뜨리기</h2>
                        <p className="text-xl text-slate-500 mt-2">AI가 자동으로 일보를 작성합니다!</p>
                    </div>
                </div>
            )}

            {hasWarnings && (
                <div className="bg-orange-50 border-b border-orange-200 px-6 py-3 flex items-center justify-between shrink-0 animate-fade-in-down">
                    <div className="flex items-center gap-3 text-orange-800">
                        <div className="w-8 h-8 rounded-full bg-orange-100 flex items-center justify-center text-orange-600"><FontAwesomeIcon icon={faExclamationTriangle} /></div>
                        <div>
                            <p className="font-bold text-sm">확인이 필요한 항목이 있습니다</p>
                            <p className="text-xs text-orange-700">{validationSummary.missingSites > 0 && <span>• 현장 미지정: <b>{validationSummary.missingSites}</b>건 </span>}{validationSummary.unknownWorkers > 0 && <span>• 미등록 작업자: <b>{validationSummary.unknownWorkers}</b>명 </span>}<span>(빨간색 표시를 확인해주세요)</span></p>
                        </div>
                    </div>
                </div>
            )}

            <div className="sticky-toolbar-wrapper">
                <div className="p-4 bg-white border-b border-slate-200 flex justify-between items-center shadow-sm sticky-toolbar z-[20]">
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2 bg-slate-100 border border-slate-300 rounded-lg px-3 py-2">
                            <FontAwesomeIcon icon={faCalendarAlt} className="text-slate-500" />
                            <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="bg-transparent border-none text-sm font-bold text-slate-700 focus:ring-0 p-0 outline-none" />
                        </div>
                        <div className="flex items-center gap-2 bg-slate-100 border border-slate-200 rounded-lg px-3 py-1">
                            <span className="text-[10px] font-bold text-slate-400">날씨</span>
                            <select value={weather} onChange={(e) => setWeather(e.target.value)} className="bg-transparent border-none text-xs font-bold text-slate-700 p-0 focus:ring-0 cursor-pointer">
                                <option value="맑음">맑음 ☀️</option><option value="흐림">흐림 ☁️</option><option value="비">비 ☔</option><option value="눈">눈 ❄️</option>
                            </select>
                        </div>
                        <div className="flex items-center gap-2">
                             {globalDuplicateNames.size > 0 && (
                                <span className="bg-yellow-100 text-yellow-700 text-[10px] px-2 py-1 rounded-full font-bold flex items-center gap-1 animate-pulse">
                                    <FontAwesomeIcon icon={faExclamationTriangle} /> 이름중복 {globalDuplicateNames.size}종
                                </span>
                            )}
                            <span className="bg-slate-100 text-slate-600 text-[10px] px-2 py-1 rounded-full font-bold">총 {validationSummary.totalWorkers}명</span>
                        </div>
                    </div>
                    <div className="flex gap-2">
                        <button onClick={() => fileInputRef.current?.click()} className="px-4 py-2 bg-yellow-400 text-slate-900 rounded-lg hover:bg-yellow-500 flex items-center gap-2 shadow-sm transition-colors font-bold"><FontAwesomeIcon icon={faComment} /> 카톡 분석</button>
                        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => { const file = e.target.files?.[0]; if (file) processKakaoImage(file); e.target.value = ''; }} />
                        <button onClick={addLedger} className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 flex items-center gap-2 shadow-sm transition-colors"><FontAwesomeIcon icon={faPlus} /> 장부 추가</button>
                        <button onClick={removeLastLedger} className="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 flex items-center gap-2 shadow-sm transition-colors"><FontAwesomeIcon icon={faMinus} /> 장부 삭제</button>
                        <button onClick={handleReset} className="px-4 py-2 bg-slate-600 text-white rounded-lg hover:bg-slate-700 flex items-center gap-2 shadow-sm transition-colors" title="초기화"><FontAwesomeIcon icon={faEraser} /> 초기화</button>
                        <button onClick={handleSaveAll} disabled={loading} className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2 shadow-sm transition-colors"><FontAwesomeIcon icon={faSave} className={loading ? "animate-spin" : ""} />{loading ? '저장 중...' : '전체 저장'}</button>
                    </div>
                </div>
            </div>

            {hasTempData && (
                <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 mb-4 mx-6 flex items-center justify-between mt-4">
                    <div className="flex items-center gap-2"><FontAwesomeIcon icon={faFloppyDisk} className="text-blue-600" /><span className="text-blue-800 font-medium text-sm">임시 저장된 데이터를 불러왔습니다.</span></div>
                    <button onClick={() => { clearTempData(); handleReset(); }} className="text-xs text-red-500 hover:text-red-700 underline">임시데이터 삭제</button>
                </div>
            )}

            <div className="flex-1 overflow-y-auto p-6">
                <div className="flex flex-wrap gap-4 items-start content-start">
                    {ledgers.map((ledger, index) => (
                        <DailyReportTable
                            key={ledger.id}
                            ledger={ledger}
                            ledgerIndex={index + 1}
                            sites={sites}
                            teams={teams}
                            workerMap={workerMap}
                            globalDuplicateNames={globalDuplicateNames}
                            onUpdate={updateLedger}
                            onDelete={removeLedger}
                            onAddRow={addRowToLedger}
                        />
                    ))}
                    {ledgers.length === 0 && (
                        <div className="w-full text-center py-20 text-slate-400 border-2 border-dashed border-slate-300 rounded-xl">
                            <p className="text-xl mb-4">작성된 장부가 없습니다.</p>
                            <button onClick={addLedger} className="px-4 py-2 bg-white border border-slate-300 rounded-lg hover:bg-slate-50 text-slate-600">+ 새 장부 추가하기</button>
                        </div>
                    )}
                </div>
            </div>

            <style>{`
                .sticky-toolbar-wrapper { position: sticky; top: 0; z-index: 20; }
                .sticky-toolbar { position: sticky; top: 0; z-index: 20; background: white; }
                .handsontable-container .handsontable { font-size: 12px; }
                .handsontable-container .handsontable th { background-color: #4A192C; color: white !important; font-weight: bold !important; font-size: 11px; position: sticky !important; top: 0; z-index: 2; }
                .handsontable-container .handsontable td:nth-child(1) { background-color: #E0F7FA; }
                .handsontable-container .handsontable td:nth-child(2) { background-color: #FCE4EC; text-align: center; }
                .handsontable-container .handsontable td:nth-child(3) { background-color: #F5F5F5; color: #64748b; font-size: 11px; }
                .handsontable-container .handsontable td.unknown-worker-cell { background-color: #fca5a5 !important; color: #7f1d1d !important; font-weight: bold; border: 1px solid #ef4444 !important; }
                .handsontable-container .handsontable td.duplicate-worker-cell { background-color: #fef08a !important; color: #854d0e !important; font-weight: bold; border: 1px solid #eab308 !important; }
            `}</style>

            {loading && (
                <div className="absolute inset-0 bg-black/20 flex items-center justify-center z-40 backdrop-blur-[1px]">
                    <div className="bg-white p-6 rounded-xl shadow-2xl flex flex-col items-center">
                        <div className="animate-spin text-indigo-600 mb-3"><FontAwesomeIcon icon={faSpinner} className="animate-spin" size="2x" /></div>
                        <span className="font-bold text-slate-700">처리 중입니다...</span>
                    </div>
                </div>
            )}
        </div>
    );
};

export default DailyReportGridInput;

import React, { useState, useEffect, useMemo } from 'react';
import { dailyReportService, DailyReport, DailyReportWorker } from '../../services/dailyReportService';
import { teamService, Team } from '../../services/teamService';
import { siteService, Site } from '../../services/siteService';
import { companyService, Company } from '../../services/companyService';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faSearch, faCalendarAlt, faSortAmountDown, faSortAmountUp
} from '@fortawesome/free-solid-svg-icons';
import DailyReportCard from './components/DailyReportCard';

interface DailyReportListProps {
    initialDate?: string;
}

const DailyReportList: React.FC<DailyReportListProps> = ({ initialDate }) => {
    const [reports, setReports] = useState<DailyReport[]>([]);
    const [teams, setTeams] = useState<Team[]>([]);
    const [sites, setSites] = useState<Site[]>([]);
    const [companies, setCompanies] = useState<Company[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    const today = new Date();
    const formatDate = (d: Date) => {
        const y = d.getFullYear();
        const m = String(d.getMonth() + 1).padStart(2, '0');
        const day = String(d.getDate()).padStart(2, '0');
        return `${y}-${m}-${day}`;
    };

    const todayStr = formatDate(today);
    const [startDate, setStartDate] = useState(initialDate || todayStr);
    const [endDate, setEndDate] = useState(initialDate || todayStr);
    const [selectedTeamId, setSelectedTeamId] = useState('');
    const [selectedSiteId, setSelectedSiteId] = useState('');
    const [workerSearch, setWorkerSearch] = useState('');
    const [dateSortOrder, setDateSortOrder] = useState<'asc' | 'desc'>('desc');
    const [companyTypeFilter, setCompanyTypeFilter] = useState<'all' | 'construction' | 'partner'>('all');

    useEffect(() => { fetchInitialData(); }, []);

    // Auto-fetch ONLY on mount (or if we want to honor initialDate if it changes, but usually just once)
    // Removed auto-fetch on filter changes as per user request
    useEffect(() => { fetchReports(); }, []);

    const fetchInitialData = async () => {
        try {
            const [teamsData, sitesData, companiesData] = await Promise.all([
                teamService.getTeams(), siteService.getSites(), companyService.getCompanies()
            ]);
            setTeams(teamsData);
            setSites(sitesData);
            setCompanies(companiesData);
        } catch (error) { console.error("Failed to fetch initial data", error); }
    };

    const fetchReports = async () => {
        setIsLoading(true);
        try {
            const data = await dailyReportService.getReportsByRange(startDate, endDate, selectedTeamId, selectedSiteId);
            setReports(data);
        } catch (error) { console.error("Failed to fetch reports", error); }
        finally { setIsLoading(false); }
    };

    // --- Actions ---

    const handleUpdateWorker = async (reportId: string, workerId: string, field: keyof DailyReportWorker, value: any) => {
        try {
            await dailyReportService.updateWorkerInReport(reportId, workerId, { [field]: value });
            // Optimistic update or fetch? Small scale, fetch is safer for consistent totals
            fetchReports();
        } catch (error) { throw error; }
    };

    const handleDeleteWorker = async (reportId: string, workerId: string, workerName: string) => {
        if (!window.confirm(`"${workerName}"를 삭제하시겠습니까?`)) return;
        try {
            await dailyReportService.removeWorkerFromReport(reportId, workerId);
            fetchReports();
        } catch (error) { throw error; }
    };

    const handleUpdateReport = async (reportId: string, field: keyof DailyReport, value: any) => {
        try {
            const report = reports.find(r => r.id === reportId);
            if (!report) return;

            // Using updateReport to ensure consistency, even though it's heavy
            await dailyReportService.updateReport(reportId, { ...report, [field]: value, workers: report.workers });
            fetchReports();
        } catch (error) { console.error("Update report failed", error); }
    };


    // --- Filtering & Grouping ---

    const filteredReports = useMemo(() => {
        const nonEmpty = (value?: unknown): string | undefined => {
            if (value == null) return undefined;
            const trimmed = String(value).trim();
            return trimmed ? trimmed : undefined;
        };

        let result = reports.filter(r => Array.isArray(r.workers) && r.workers.length > 0);

        // 1. Worker Search
        if (workerSearch.trim()) {
            const lower = workerSearch.toLowerCase();
            result = result.filter(r =>
                r.workers.some(w => w.name.toLowerCase().includes(lower) || (w.role || '').includes(lower))
            );
        }

        // 2. Company Type Filter
        if (companyTypeFilter !== 'all') {
            result = result.filter(r => {
                const team = teams.find(t => t.id === r.teamId);
                if (!team?.companyId) return true; // Keep if unknown
                const company = companies.find(c => c.id === team.companyId);
                if (!company) return true;
                return company.type === (companyTypeFilter === 'construction' ? '시공사' : '협력사');
            });
        }

        // 3. Inject site metadata for display (발주/시공/협력)
        result = result.map(r => {
            const site = sites.find(s => (s.id && String(s.id) === String(r.siteId)) || (s.legacyId && String(s.legacyId) === String(r.siteId)));
            if (!site) return r;

            const clientName = nonEmpty(r.companyName) ?? nonEmpty(site.clientCompanyName);
            const constructorName = nonEmpty(r.constructorCompanyName) ?? nonEmpty(site.companyName) ?? nonEmpty(site.constructorCompanyName);
            const partnerName = nonEmpty(r.partnerName) ?? nonEmpty(site.partnerName);

            return {
                ...r,
                companyName: clientName,
                constructorCompanyName: constructorName,
                partnerName
            };
        });

        return result;
    }, [reports, workerSearch, companyTypeFilter, teams, companies, sites]);

    // Group by Date
    const groupedReports = useMemo(() => {
        const groups: { [date: string]: DailyReport[] } = {};
        filteredReports.forEach(r => {
            if (!groups[r.date]) groups[r.date] = [];
            groups[r.date].push(r);
        });
        return groups;
    }, [filteredReports]);

    const sortedDates = useMemo(() => {
        const dates = Object.keys(groupedReports);
        return dates.sort((a, b) => dateSortOrder === 'asc' ? a.localeCompare(b) : b.localeCompare(a));
    }, [groupedReports, dateSortOrder]);

    // Calculate Totals
    const totalManDays = useMemo(() => filteredReports.reduce((sum, r) => sum + r.totalManDay, 0), [filteredReports]);

    return (
        <div className="flex flex-col h-full gap-4">
            {/* Filters */}
            <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-wrap gap-3 items-end">
                {/* Date Inputs */}
                <div className="flex items-center gap-2">
                    <div className="relative">
                        <FontAwesomeIcon icon={faCalendarAlt} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                        <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)}
                            className="pl-10 pr-3 py-2 border-slate-300 rounded-lg text-sm" />
                    </div>
                    <span className="text-slate-400">~</span>
                    <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)}
                        className="px-3 py-2 border-slate-300 rounded-lg text-sm" />
                    {/* Quick Date Buttons */}
                    <button onClick={() => {
                        // Update state AND fetch immediately for convenience when clicking "Today/Yesterday"
                        // Or just update state? User asked for manual check.
                        // However, quick buttons usually imply action. 
                        // I'll leave them as state updates only, so user hits "Search" to confirm.
                        setStartDate(todayStr); setEndDate(todayStr);
                    }}
                        className="px-2 py-1.5 text-xs bg-blue-50 text-blue-600 rounded-lg font-medium hover:bg-blue-100 transition-colors">오늘</button>
                    <button onClick={() => {
                        const y = new Date(); y.setDate(y.getDate() - 1);
                        const yStr = formatDate(y);
                        setStartDate(yStr); setEndDate(yStr);
                    }}
                        className="px-2 py-1.5 text-xs bg-slate-50 text-slate-600 rounded-lg font-medium hover:bg-slate-100 transition-colors">어제</button>

                    <button onClick={() => setDateSortOrder(prev => prev === 'desc' ? 'asc' : 'desc')}
                        className={`px-3 py-2 text-sm rounded-lg font-medium flex items-center gap-2 transition-colors ${dateSortOrder === 'desc' ? 'bg-indigo-50 text-indigo-600' : 'bg-amber-50 text-amber-600'}`}>
                        <FontAwesomeIcon icon={dateSortOrder === 'desc' ? faSortAmountDown : faSortAmountUp} />
                    </button>
                </div>

                {/* Site Select */}
                <select value={selectedSiteId} onChange={e => setSelectedSiteId(e.target.value)}
                    className="px-3 py-2 border-slate-300 rounded-lg text-sm min-w-[120px]">
                    <option value="">전체 현장</option>
                    {sites.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>

                {/* Company Type Filter */}
                <div className="flex gap-1 bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setCompanyTypeFilter('all')}
                        className={`px-3 py-1.5 text-xs rounded-md font-bold transition-all ${companyTypeFilter === 'all' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>전체</button>
                    <button onClick={() => setCompanyTypeFilter('construction')}
                        className={`px-3 py-1.5 text-xs rounded-md font-bold transition-all ${companyTypeFilter === 'construction' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-blue-600'}`}>시공팀</button>
                    <button onClick={() => setCompanyTypeFilter('partner')}
                        className={`px-3 py-1.5 text-xs rounded-md font-bold transition-all ${companyTypeFilter === 'partner' ? 'bg-white text-green-600 shadow-sm' : 'text-slate-500 hover:text-green-600'}`}>협력사</button>
                </div>

                {/* Team Select */}
                <select value={selectedTeamId} onChange={e => setSelectedTeamId(e.target.value)}
                    className="px-3 py-2 border-slate-300 rounded-lg text-sm min-w-[120px]">
                    <option value="">전체 팀</option>
                    {teams.filter(t => {
                        if (companyTypeFilter === 'all') return true;
                        const company = companies.find(c => c.id === t.companyId);
                        if (!company) return true;
                        if (companyTypeFilter === 'construction') return company.type === '시공사';
                        if (companyTypeFilter === 'partner') return company.type === '협력사';
                        return true;
                    }).map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                </select>

                {/* Search Button (Manual Trigger) */}
                <button
                    onClick={fetchReports}
                    className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2 rounded-lg text-sm font-bold shadow-sm flex items-center gap-2 transition-transform active:scale-95"
                >
                    <FontAwesomeIcon icon={faSearch} />
                    조회
                </button>

                {/* Worker Search */}
                <div className="relative flex-1 min-w-[150px]">
                    <FontAwesomeIcon icon={faSearch} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input type="text" value={workerSearch} onChange={e => setWorkerSearch(e.target.value)}
                        placeholder="작업자 검색" className="w-full pl-10 pr-4 py-2 border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-brand-500 focus:border-brand-500 outline-none transition-all" />
                </div>

                <div className="bg-slate-800 text-white px-4 py-2 rounded-lg shadow-sm flex items-center gap-2">
                    <span className="text-xs font-light text-slate-300">Total</span>
                    <span className="font-bold text-lg">{totalManDays.toFixed(1)}</span>
                    <span className="text-xs">공수</span>
                </div>
            </div>

            {/* List Content */}
            <div className="flex-1 overflow-y-auto pr-2 pb-10 custom-scrollbar">
                {isLoading ? (
                    <div className="flex flex-col items-center justify-center h-64 opacity-50">
                        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-brand-600 mb-2"></div>
                        <span className="text-sm font-medium text-slate-500">불러오는 중...</span>
                    </div>
                ) : filteredReports.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                        <FontAwesomeIcon icon={faSearch} className="text-4xl mb-3 opacity-20" />
                        <span className="text-sm">조건에 맞는 일보가 없습니다.</span>
                    </div>
                ) : (
                    <div className="flex flex-col gap-8">
                        {sortedDates.map(date => (
                            <div key={date} className="flex flex-col gap-4">
                                {/* Date Divider */}
                                <div className="flex items-center gap-4">
                                    <div className="bg-slate-100 text-slate-600 px-3 py-1 rounded-full text-xs font-bold border border-slate-200 shadow-sm">
                                        {date}
                                        <span className="ml-2 px-1.5 py-0.5 bg-slate-200 rounded-full text-[10px] text-slate-500">
                                            {new Date(date).toLocaleDateString('ko-KR', { weekday: 'long' })}
                                        </span>
                                    </div>
                                    <div className="h-px bg-slate-200 flex-1"></div>
                                </div>

                                {/* Cards Grid */}
                                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 items-start">
                                    {groupedReports[date].map(report => (
                                        <DailyReportCard
                                            key={report.id}
                                            report={report}
                                            onUpdateWorker={handleUpdateWorker}
                                            onDeleteWorker={handleDeleteWorker}
                                            onUpdateReport={handleUpdateReport}
                                        />
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar {
                    width: 6px;
                }
                .custom-scrollbar::-webkit-scrollbar-track {
                    background: transparent; 
                }
                .custom-scrollbar::-webkit-scrollbar-thumb {
                    background: #cbd5e1; 
                    border-radius: 3px;
                }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover {
                    background: #94a3b8; 
                }
            `}</style>
        </div>
    );
};

export default DailyReportList;

import React, { useEffect, useMemo, useState, useCallback } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import Swal from 'sweetalert2';
import {
    faCalendarAlt,
    faSearch,
    faSortAmountDown,
    faSortAmountUp,
    faPenToSquare,
    faTrash,
    faSave,
    faFilter,
    faDownload,
    faSpinner,
    faTrashCan,
} from '@fortawesome/free-solid-svg-icons';
import { dailyReportService, DailyReportWorker, DailyReportWorkerRow } from '../../services/dailyReportService';
import { dailyReportTransferService } from '../../services/dailyReportTransferService';
import { teamService, Team } from '../../services/teamService';
import { manpowerService, Worker } from '../../services/manpowerService';
import { siteService, Site } from '../../services/siteService';
import { confirm, toast } from '../../utils/swal';
import { normalizeTypedDateInput, sanitizeTypedDateInput } from '../../utils/typedDateInput';
import { loadSessionState, saveSessionState } from '../../utils/sessionStorage';
import { resolveReportPayType, resolveWorkerPayType } from '../../utils/payType';
import SingleSelectPopover, { InputPopover } from '../../components/common/SingleSelectPopover';
import '../taxinvoice/WorkbookLedgerPage.css';
import './DailyReportListV2.css';

interface DailyReportListV2Props {
    initialDate?: string;
}

const formatYmd = (d: Date): string => {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
};

const formatNumber = (value: number): string => {
    return new Intl.NumberFormat('ko-KR').format(value);
};

const compareKo = (a: string, b: string): number => {
    return a.localeCompare(b, 'ko');
};

const normalizeTeamNameKey = (value?: string | null): string => {
    return String(value ?? '').trim().replace(/\s+/g, '').toLowerCase();
};

const compareTeamsWithPriority = (a: string, b: string): number => {
    const isAPriority = a.includes('청연');
    const isBPriority = b.includes('청연');

    if (isAPriority && !isBPriority) return -1;
    if (!isAPriority && isBPriority) return 1;

    return a.localeCompare(b, 'ko');
};

const SALARY_MODEL_OPTIONS = ['일급제', '일급', '월급제', '월급', '지원팀', '용역팀', '도급', '팀기성'];

type RowDraft = {
    siteId: string;
    teamId: string;
    responsibleTeamId: string;
    responsibleTeamName: string;
    workerId?: string; // New Worker ID if changed
    workerName?: string;
    workerTeamName?: string;
    workerTeamId?: string; // 소속팀 ID 추가
    salaryModel: string;
    manDay: string;
    unitPrice: string;
    workContent: string;
    siteType: string;
    paymentType: string;
};

type ColumnFilterKey =
    | 'date'
    | 'siteName'
    | 'siteType'
    | 'paymentType'
    | 'teamName'
    | 'workerName'
    | 'workerTeamName'
    | 'salaryModel'
    | 'manDay'
    | 'unitPrice'
    | 'amount';

type ColumnFilterState = Partial<Record<ColumnFilterKey, string[]>>;

const EMPTY_COLUMN_FILTER_VALUE = '__EMPTY__';

type DailyReportListViewState = {
    startDate: string;
    endDate: string;
    startDateInput: string;
    endDateInput: string;
    selectedTeamId: string;
    selectedWorkerTeamId: string;
    selectedSiteId: string;
    workerSearch: string;
    dateSortOrder: 'asc' | 'desc';
    sortMode: 'date' | 'name' | 'site';
    nameSortOrder: 'asc' | 'desc';
    siteSortOrder: 'asc' | 'desc';
    columnFilters: ColumnFilterState;
};

const DAILY_REPORT_LIST_VIEW_KEY = 'output-management:daily-report-list-v2:v1';

const formatManDay = (value: number): string => {
    return (Number.isFinite(value) ? value : 0).toFixed(1);
};

const toColumnFilterValue = (value: string): string => {
    return value === '' ? EMPTY_COLUMN_FILTER_VALUE : value;
};

const fromColumnFilterValue = (value: string): string => {
    return value === EMPTY_COLUMN_FILTER_VALUE ? '(빈값)' : value;
};

const DailyReportListV2: React.FC<DailyReportListV2Props> = ({ initialDate }) => {
    const todayStr = formatYmd(new Date());
    const defaultDate = initialDate || todayStr;
    const persistedViewState = useMemo(() => {
        const fallback: DailyReportListViewState = {
            startDate: defaultDate,
            endDate: defaultDate,
            startDateInput: defaultDate,
            endDateInput: defaultDate,
            selectedTeamId: '',
            selectedWorkerTeamId: '',
            selectedSiteId: '',
            workerSearch: '',
            dateSortOrder: 'desc',
            sortMode: 'date',
            nameSortOrder: 'asc',
            siteSortOrder: 'asc',
            columnFilters: {}
        };
        const persisted = loadSessionState<DailyReportListViewState>(DAILY_REPORT_LIST_VIEW_KEY, fallback);

        if (!initialDate) {
            return persisted;
        }

        return {
            ...persisted,
            startDate: initialDate,
            endDate: initialDate,
            startDateInput: initialDate,
            endDateInput: initialDate
        };
    }, [defaultDate, initialDate]);

    const [rows, setRows] = useState<DailyReportWorkerRow[]>([]);
    const [teams, setTeams] = useState<Team[]>([]);
    const [sites, setSites] = useState<Site[]>([]);
    const [allWorkers, setAllWorkers] = useState<Worker[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    const [startDate, setStartDate] = useState(persistedViewState.startDate);
    const [endDate, setEndDate] = useState(persistedViewState.endDate);
    const [startDateInput, setStartDateInput] = useState(persistedViewState.startDateInput);
    const [endDateInput, setEndDateInput] = useState(persistedViewState.endDateInput);
    const [selectedTeamId, setSelectedTeamId] = useState(persistedViewState.selectedTeamId); // 해당팀 (Report Team)
    const [selectedWorkerTeamId, setSelectedWorkerTeamId] = useState(persistedViewState.selectedWorkerTeamId); // 소속팀 (Worker Team)
    const [selectedSiteId, setSelectedSiteId] = useState(persistedViewState.selectedSiteId);
    const [workerSearch, setWorkerSearch] = useState(persistedViewState.workerSearch);
    const [dateSortOrder, setDateSortOrder] = useState<'asc' | 'desc'>(persistedViewState.dateSortOrder === 'asc' ? 'asc' : 'desc');

    const [sortMode, setSortMode] = useState<'date' | 'name' | 'site'>(persistedViewState.sortMode);
    const [nameSortOrder, setNameSortOrder] = useState<'asc' | 'desc'>(persistedViewState.nameSortOrder === 'desc' ? 'desc' : 'asc');
    const [siteSortOrder, setSiteSortOrder] = useState<'asc' | 'desc'>(persistedViewState.siteSortOrder === 'desc' ? 'desc' : 'asc');

    const [isEditMode, setIsEditMode] = useState(false);
    const isFixed = true;

    const [selectedRowKeys, setSelectedRowKeys] = useState<Set<string>>(new Set());
    const [isBulkEditOpen, setIsBulkEditOpen] = useState(false);

    const [rowDrafts, setRowDrafts] = useState<Record<string, RowDraft>>({});
    const [rowSavingKeys, setRowSavingKeys] = useState<Set<string>>(new Set());

    const [bulkManDay, setBulkManDay] = useState('');
    const [bulkUnitPrice, setBulkUnitPrice] = useState('');
    const [bulkSalaryModel, setBulkSalaryModel] = useState('');
    const [bulkWorkContent, setBulkWorkContent] = useState('');
    const [bulkSiteType, setBulkSiteType] = useState('');
    const [bulkPaymentType, setBulkPaymentType] = useState('');
    const [bulkWorkerTeamName, setBulkWorkerTeamName] = useState('');
    const [columnFilters, setColumnFilters] = useState<ColumnFilterState>(persistedViewState.columnFilters);
    const [openColumnFilter, setOpenColumnFilter] = useState<ColumnFilterKey | null>(null);
    const [columnFilterSearch, setColumnFilterSearch] = useState('');
    const [pendingColumnFilterValues, setPendingColumnFilterValues] = useState<string[] | null>(null);
    const filterMenuRef = React.useRef<HTMLDivElement | null>(null);
    const [isResettingDb, setIsResettingDb] = useState(false);
    const [isDownloadingExcel, setIsDownloadingExcel] = useState(false);

    useEffect(() => {
        (async () => {
            try {
                const [teamsData, sitesData, workersData] = await Promise.all([
                    teamService.getTeams(),
                    siteService.getSites(),
                    manpowerService.getWorkers()
                ]);
                setTeams(teamsData);
                setSites(sitesData);
                setAllWorkers(workersData);
            } catch (error) {
                console.error('[DailyReportListV2] Failed to fetch initial data', error);
            }
        })();
    }, []);

    useEffect(() => {
        setStartDateInput(startDate);
    }, [startDate]);

    useEffect(() => {
        setEndDateInput(endDate);
    }, [endDate]);

    useEffect(() => {
        saveSessionState(DAILY_REPORT_LIST_VIEW_KEY, {
            startDate,
            endDate,
            startDateInput,
            endDateInput,
            selectedTeamId,
            selectedWorkerTeamId,
            selectedSiteId,
            workerSearch,
            dateSortOrder,
            sortMode,
            nameSortOrder,
            siteSortOrder,
            columnFilters
        } satisfies DailyReportListViewState);
    }, [
        columnFilters,
        dateSortOrder,
        endDate,
        endDateInput,
        nameSortOrder,
        selectedSiteId,
        selectedTeamId,
        selectedWorkerTeamId,
        siteSortOrder,
        sortMode,
        startDate,
        startDateInput,
        workerSearch
    ]);

    // 10자리(YYYY-MM-DD)가 완성되어도 자동으로 조회를 트리거하지 않도록 변경
    // 사용자가 '조회' 버튼을 누를 때만 startDate/endDate가 업데이트 되도록 관리합니다.


    const fetchRows = useCallback(async (): Promise<void> => {
        setIsLoading(true);
        try {
            const data = await dailyReportService.getReportWorkerRowsByRange({
                startDate,
                endDate
            });
            setRows(data);
        } catch (error) {
            console.error('[DailyReportListV2] Failed to fetch rows', error);
        } finally {
            setIsLoading(false);
        }
    }, [startDate, endDate]);

    // 초기 로딩 시에만 1회 호출
    useEffect(() => {
        fetchRows();
    }, []);


    useEffect(() => {
        if (!openColumnFilter) return;

        const handlePointerDown = (event: MouseEvent) => {
            if (!filterMenuRef.current?.contains(event.target as Node)) {
                setOpenColumnFilter(null);
            }
        };

        const handleEscape = (event: KeyboardEvent) => {
            if (event.key === 'Escape') {
                setOpenColumnFilter(null);
            }
        };

        document.addEventListener('mousedown', handlePointerDown);
        document.addEventListener('keydown', handleEscape);

        return () => {
            document.removeEventListener('mousedown', handlePointerDown);
            document.removeEventListener('keydown', handleEscape);
        };
    }, [openColumnFilter]);

    const commitDateInput = useCallback((field: 'start' | 'end') => {
        const currentValue = field === 'start' ? startDate : endDate;
        const draftValue = field === 'start' ? startDateInput : endDateInput;
        const normalizedValue = normalizeTypedDateInput(draftValue) ?? currentValue;

        if (field === 'start') {
            setStartDateInput(normalizedValue);
            if (normalizedValue !== startDate) {
                setStartDate(normalizedValue);
                return true;
            }
            return false;
        }

        setEndDateInput(normalizedValue);
        if (normalizedValue !== endDate) {
            setEndDate(normalizedValue);
            return true;
        }
        return false;
    }, [endDate, endDateInput, startDate, startDateInput]);

    const applyDateRange = useCallback((nextStartDate: string, nextEndDate: string) => {
        setStartDateInput(nextStartDate);
        setEndDateInput(nextEndDate);
        setStartDate(nextStartDate);
        setEndDate(nextEndDate);
    }, []);

    const handleSearch = useCallback(() => {
        const normalizedStart = normalizeTypedDateInput(startDateInput) ?? startDate;
        const normalizedEnd = normalizeTypedDateInput(endDateInput) ?? endDate;

        setStartDate(normalizedStart);
        setEndDate(normalizedEnd);
        setStartDateInput(normalizedStart);
        setEndDateInput(normalizedEnd);

        // 상태 반영을 위해 fetchData를 직접 호출하거나 의존성을 startDate/endDate로 넘겨야 하지만
        // 여기서는 안전하게 normalized 값으로 직접 호출할 수 있도록 fetchRows를 수정하거나
        // 또는 set이 비동기이므로 fetchRows 내부에서 최신 상태를 쓰게 합니다.
        // 현재 fetchRows는 startDate, endDate에 의존하므로, 이 함수가 다음 렌더링에 호출되게 하지 않고
        // 즉시 fetch를 할 수 있도록 인자를 받는 버전으로 고려합니다.
        
        setIsLoading(true);
        dailyReportService.getReportWorkerRowsByRange({
            startDate: normalizedStart,
            endDate: normalizedEnd
        }).then(data => {
            setRows(data);
        }).catch(error => {
            console.error('[DailyReportListV2] Search fetch failed', error);
        }).finally(() => {
            setIsLoading(false);
        });
    }, [startDateInput, endDateInput, startDate, endDate]);


    const getRowKey = useCallback((r: DailyReportWorkerRow) => {
        return `${String(r.reportId)}::${String(r.workerId)}`;
    }, []);

    const rowByKey = useMemo(() => {
        const map = new Map<string, DailyReportWorkerRow>();
        for (const r of rows) {
            map.set(getRowKey(r), r);
        }
        return map;
    }, [rows, getRowKey]);

    const teamCanonicalIdMap = useMemo(() => {
        const map = new Map<string, string>();
        for (const t of teams) {
            const id = t.id ? String(t.id) : '';
            const legacyId = t.legacyId ? String(t.legacyId) : '';
            if (id) map.set(id, id);
            if (legacyId && id) map.set(legacyId, id);
            if (legacyId && !map.has(legacyId)) map.set(legacyId, legacyId);
        }
        return map;
    }, [teams]);

    const siteCanonicalIdMap = useMemo(() => {
        const map = new Map<string, string>();
        for (const s of sites) {
            const id = s.id ? String(s.id) : '';
            const legacyId = s.legacyId ? String(s.legacyId) : '';
            if (id) map.set(id, id);
            if (legacyId && id) map.set(legacyId, id);
            if (legacyId && !map.has(legacyId)) map.set(legacyId, legacyId);
        }
        return map;
    }, [sites]);

    const normalizeTeamId = useCallback((id?: string | null) => {
        const raw = id ? String(id) : '';
        if (!raw) return '';
        return teamCanonicalIdMap.get(raw) ?? raw;
    }, [teamCanonicalIdMap]);

    const teamNameCanonicalIdMap = useMemo(() => {
        const map = new Map<string, string>();
        for (const team of teams) {
            const canonicalId = normalizeTeamId(team.id ? String(team.id) : (team.legacyId ? String(team.legacyId) : ''));
            const nameKey = normalizeTeamNameKey(team.name);
            if (canonicalId && nameKey && !map.has(nameKey)) {
                map.set(nameKey, canonicalId);
            }
        }
        return map;
    }, [teams, normalizeTeamId]);

    const resolveWorkerTeamCanonicalId = useCallback((params: { workerTeamId?: string | null; workerTeamName?: string | null }) => {
        // 소속팀명과 소속팀ID가 충돌하는 레거시 데이터가 있어, 이름 매핑을 우선 사용합니다.
        const nameKey = normalizeTeamNameKey(params.workerTeamName);
        if (nameKey) {
            const byName = teamNameCanonicalIdMap.get(nameKey);
            if (byName) return byName;
        }

        const byId = normalizeTeamId(params.workerTeamId);
        if (byId) return byId;
        return '';
    }, [normalizeTeamId, teamNameCanonicalIdMap]);

    const resolveWorkerTeamDisplayName = useCallback((params: { workerTeamId?: string | null; workerTeamName?: string | null }) => {
        const rawName = String(params.workerTeamName ?? '').trim();
        if (rawName) return rawName;

        const canonicalId = resolveWorkerTeamCanonicalId(params);
        if (!canonicalId) return '';

        return teams.find((team) => normalizeTeamId(team.id ?? team.legacyId ?? '') === canonicalId)?.name ?? '';
    }, [normalizeTeamId, resolveWorkerTeamCanonicalId, teams]);

    const resolveResponsibleTeamCanonicalId = useCallback((params: { responsibleTeamId?: string | null; responsibleTeamName?: string | null }) => {
        const nameKey = normalizeTeamNameKey(params.responsibleTeamName);
        if (nameKey) {
            const byName = teamNameCanonicalIdMap.get(nameKey);
            if (byName) return byName;
        }

        const byId = normalizeTeamId(params.responsibleTeamId);
        if (byId) return byId;

        const rawName = String(params.responsibleTeamName ?? '').trim();
        if (rawName) return rawName;

        return '';
    }, [normalizeTeamId, teamNameCanonicalIdMap]);

    const resolveResponsibleTeamOptionId = useCallback((params: { responsibleTeamId?: string | null; responsibleTeamName?: string | null }) => {
        return resolveResponsibleTeamCanonicalId(params) || String(params.responsibleTeamName ?? '').trim();
    }, [resolveResponsibleTeamCanonicalId]);

    const resolveResponsibleTeamDisplayName = useCallback((params: { responsibleTeamId?: string | null; responsibleTeamName?: string | null }) => {
        const rawName = String(params.responsibleTeamName ?? '').trim();
        if (rawName) return rawName;

        const canonicalId = resolveResponsibleTeamCanonicalId(params);
        if (!canonicalId) return '';

        return teams.find((team) => normalizeTeamId(team.id ?? team.legacyId ?? '') === canonicalId)?.name ?? '';
    }, [normalizeTeamId, resolveResponsibleTeamCanonicalId, teams]);

    const normalizeSiteId = useCallback((id?: string | null) => {
        const raw = id ? String(id) : '';
        if (!raw) return '';
        return siteCanonicalIdMap.get(raw) ?? raw;
    }, [siteCanonicalIdMap]);

    const getColumnFilterValue = useCallback((row: DailyReportWorkerRow, key: ColumnFilterKey): string => {
        switch (key) {
            case 'date':
                return row.date ?? '';
            case 'siteName':
                return row.siteName ?? '';
            case 'siteType':
                return row.siteType ?? '';
            case 'paymentType':
                return row.paymentType ?? '';
            case 'teamName':
                return resolveResponsibleTeamDisplayName({
                    responsibleTeamId: row.responsibleTeamId ?? row.teamId,
                    responsibleTeamName: row.responsibleTeamName ?? row.teamName
                });
            case 'workerName':
                return row.workerName ?? '';
            case 'workerTeamName':
                return resolveWorkerTeamDisplayName({
                    workerTeamId: row.workerTeamId,
                    workerTeamName: row.workerTeamName
                });
            case 'salaryModel':
                return resolveReportPayType(row);
            case 'manDay':
                return formatManDay(row.manDay);
            case 'unitPrice':
                return formatNumber(Math.round(Number.isFinite(row.unitPrice) ? row.unitPrice : 0));
            case 'amount':
                return formatNumber(Math.round(Number.isFinite(row.amount) ? row.amount : 0));
            default:
                return '';
        }
    }, [resolveWorkerTeamDisplayName, resolveResponsibleTeamDisplayName]);

    const getFiltered = useCallback((criteria: { teamId?: string; siteId?: string; workerTeamId?: string }) => {
        const wantTeam = criteria.teamId ? normalizeTeamId(criteria.teamId) : '';
        const wantTeamNameKey = criteria.teamId
            ? normalizeTeamNameKey(
                teams.find((team) => normalizeTeamId(team.id ?? team.legacyId ?? '') === wantTeam)?.name
                ?? criteria.teamId
            )
            : '';
        const wantSite = criteria.siteId ? normalizeSiteId(criteria.siteId) : '';
        const wantWorkerTeam = criteria.workerTeamId ? normalizeTeamId(criteria.workerTeamId) : '';

        return rows.filter(r => {
            if (wantTeam) {
                const rowResponsibleTeamId = resolveResponsibleTeamCanonicalId({
                    responsibleTeamId: r.responsibleTeamId ?? r.teamId,
                    responsibleTeamName: r.responsibleTeamName ?? r.teamName
                });
                const rowResponsibleTeamNameKey = normalizeTeamNameKey(resolveResponsibleTeamDisplayName({
                    responsibleTeamId: r.responsibleTeamId ?? r.teamId,
                    responsibleTeamName: r.responsibleTeamName ?? r.teamName
                }));

                if (rowResponsibleTeamId !== wantTeam && (!wantTeamNameKey || rowResponsibleTeamNameKey !== wantTeamNameKey)) {
                    return false;
                }
            }
            if (wantSite && normalizeSiteId(r.siteId) !== wantSite) return false;
            
            // 소속팀 필터: workerTeamId 우선, 없으면 workerTeamName으로 팀 ID 매핑
            if (wantWorkerTeam) {
                const rowWorkerTeamId = resolveWorkerTeamCanonicalId({
                    workerTeamId: r.workerTeamId,
                    workerTeamName: r.workerTeamName
                });
                if (!rowWorkerTeamId || rowWorkerTeamId !== wantWorkerTeam) return false;
            }
            return true;
        });
    }, [rows, normalizeTeamId, normalizeSiteId, resolveResponsibleTeamCanonicalId, resolveResponsibleTeamDisplayName, resolveWorkerTeamCanonicalId, teams]);

    // 1. Available Sites (Filtered by Report Team ONLY) - Worker Team selection does NOT constrain sites
    const availableSites = useMemo(() => {
        if (rows.length === 0) {
            return sites
                .slice()
                .sort((a, b) => compareKo(a.name ?? '', b.name ?? ''));
        }

        const filtered = getFiltered({ teamId: selectedTeamId });
        const siteIds = new Set(filtered.map(r => r.siteId ? String(r.siteId) : null).filter((id): id is string => !!id));
        return sites
            .filter(s => siteIds.has(String(s.id)) || (s.legacyId ? siteIds.has(String(s.legacyId)) : false))
            .slice()
            .sort((a, b) => compareKo(a.name ?? '', b.name ?? ''));
    }, [getFiltered, sites, selectedTeamId, rows.length]);

    // 2. Available Responsible Teams (Filtered by Site ONLY)
    const availableReportTeams = useMemo(() => {
        if (rows.length === 0) {
            return teams
                .slice()
                .sort((a, b) => compareTeamsWithPriority(a.name ?? '', b.name ?? ''));
        }

        const filtered = getFiltered({ siteId: selectedSiteId });
        const foundTeamIds = new Set<string>();
        const foundTeamNames = new Set<string>();

        filtered.forEach((row) => {
            const responsibleTeamId = resolveResponsibleTeamCanonicalId({
                responsibleTeamId: row.responsibleTeamId ?? row.teamId,
                responsibleTeamName: row.responsibleTeamName ?? row.teamName
            });
            const responsibleTeamName = resolveResponsibleTeamDisplayName({
                responsibleTeamId: row.responsibleTeamId ?? row.teamId,
                responsibleTeamName: row.responsibleTeamName ?? row.teamName
            });

            if (responsibleTeamId) foundTeamIds.add(responsibleTeamId);
            if (responsibleTeamName) foundTeamNames.add(responsibleTeamName);
        });

        const matchedTeams = teams.filter((team) => {
            const canonicalId = normalizeTeamId(team.id ?? team.legacyId ?? '');
            return (canonicalId && foundTeamIds.has(canonicalId)) || foundTeamNames.has(team.name ?? '');
        });

        const matchedTeamNames = new Set(matchedTeams.map((team) => team.name ?? ''));
        const virtualTeams: Team[] = [];

        foundTeamNames.forEach((name) => {
            if (!matchedTeamNames.has(name)) {
                virtualTeams.push({
                    id: name,
                    name,
                    active: true,
                } as any);
            }
        });

        return [...matchedTeams, ...virtualTeams]
            .sort((a, b) => compareTeamsWithPriority(a.name ?? '', b.name ?? ''));
    }, [getFiltered, normalizeTeamId, resolveResponsibleTeamCanonicalId, resolveResponsibleTeamDisplayName, teams, selectedSiteId, rows.length]);

    // 3. Available Worker Teams (Filtered by Site & Report Team)
    const availableWorkerTeams = useMemo(() => {
        // 소속팀 옵션은 현재 선택된 현장/현장담당팀 범위 내 데이터에서만 계산
        const scopedRows = getFiltered({ siteId: selectedSiteId, teamId: selectedTeamId });

        // 1단계: 현재 범위 내 행에서 소속팀 정보(ID 및 이름) 추출
        const foundTeamIds = new Set<string>();
        const foundTeamNames = new Set<string>();
        
        scopedRows.forEach(r => {
            if (r.workerTeamId) foundTeamIds.add(normalizeTeamId(r.workerTeamId));
            const displayName = resolveWorkerTeamDisplayName({
                workerTeamId: r.workerTeamId,
                workerTeamName: r.workerTeamName
            });
            if (displayName) foundTeamNames.add(displayName);
        });

        // 2단계: 만약 범위 내 데이터가 없다면 전체 팀 목록을 반환
        if (scopedRows.length === 0) {
            return teams
                .slice()
                .sort((a, b) => compareTeamsWithPriority(a.name ?? '', b.name ?? ''));
        }

        // 3단계: 기존 팀 목록에서 매칭되는 항목 추출
        const matchedTeams = teams.filter(t => 
            foundTeamIds.has(String(t.id)) || 
            (t.legacyId ? foundTeamIds.has(String(t.legacyId)) : false) || 
            foundTeamNames.has(t.name ?? '')
        );

        // 4단계: 팀 목록에 없지만 데이터(workerTeamName)에는 존재하는 "직접 입력" 팀들 추가 (예: 지원팀, 용역팀 등)
        const matchedTeamNamesSet = new Set(matchedTeams.map(t => t.name));
        const virtualTeams: Team[] = [];
        
        foundTeamNames.forEach(name => {
            if (!matchedTeamNamesSet.has(name)) {
                virtualTeams.push({
                    id: name, // 이름을 ID로 사용
                    name: name,
                    active: true,
                } as any);
            }
        });

        // 5단계: 합치고 정렬 (청연 우선)
        return [...matchedTeams, ...virtualTeams]
            .sort((a, b) => compareTeamsWithPriority(a.name ?? '', b.name ?? ''));
    }, [getFiltered, selectedSiteId, selectedTeamId, teams, normalizeTeamId, resolveWorkerTeamDisplayName]);


    // 4. Base Display Rows (Filtered by ALL selection + Search)
    const baseFilteredRows = useMemo(() => {
        let result = getFiltered({
            siteId: selectedSiteId,
            teamId: selectedTeamId,
            workerTeamId: selectedWorkerTeamId
        });

        // Text Search (Worker Name Only)
        const q = workerSearch.trim().toLowerCase();
        if (q) {
            result = result.filter((r) => {
                const name = (r.workerName ?? '').toLowerCase();
                return name.includes(q);
            });
        }

        return result;
    }, [getFiltered, selectedSiteId, selectedTeamId, selectedWorkerTeamId, workerSearch]);

    const filteredRows = useMemo(() => {
        const activeKeys = Object.keys(columnFilters) as ColumnFilterKey[];
        if (activeKeys.length === 0) {
            return baseFilteredRows;
        }

        return baseFilteredRows.filter((row) => {
            return activeKeys.every((key) => {
                const selectedValues = columnFilters[key] ?? [];
                return selectedValues.includes(toColumnFilterValue(getColumnFilterValue(row, key)));
            });
        });
    }, [baseFilteredRows, columnFilters, getColumnFilterValue]);

    const activeColumnFilterCount = useMemo(() => {
        return Object.keys(columnFilters).length;
    }, [columnFilters]);

    const sortedRows = useMemo(() => {
        const copied = [...filteredRows];
        copied.sort((a, b) => {
            if (sortMode === 'name') {
                const nameDiff = nameSortOrder === 'asc'
                    ? compareKo(a.workerName ?? '', b.workerName ?? '')
                    : compareKo(b.workerName ?? '', a.workerName ?? '');
                if (nameDiff !== 0) return nameDiff;

                const dateDiff = (b.date ?? '').localeCompare(a.date ?? '', 'en');
                if (dateDiff !== 0) return dateDiff;

                const teamDiff = compareKo(a.teamName ?? '', b.teamName ?? '');
                if (teamDiff !== 0) return teamDiff;

                return compareKo(a.siteName ?? '', b.siteName ?? '');
            }

            if (sortMode === 'site') {
                const siteDiff = siteSortOrder === 'asc'
                    ? compareKo(a.siteName ?? '', b.siteName ?? '')
                    : compareKo(b.siteName ?? '', a.siteName ?? '');
                if (siteDiff !== 0) return siteDiff;

                const dateDiff = (b.date ?? '').localeCompare(a.date ?? '', 'en');
                if (dateDiff !== 0) return dateDiff;

                const teamDiff = compareKo(a.teamName ?? '', b.teamName ?? '');
                if (teamDiff !== 0) return teamDiff;

                return compareKo(a.workerName ?? '', b.workerName ?? '');
            }

            const diff = dateSortOrder === 'asc'
                ? (a.date ?? '').localeCompare(b.date ?? '', 'en')
                : (b.date ?? '').localeCompare(a.date ?? '', 'en');
            if (diff !== 0) return diff;
            const team = compareKo(a.teamName ?? '', b.teamName ?? '');
            if (team !== 0) return team;
            return compareKo(a.workerName ?? '', b.workerName ?? '');
        });
        return copied;
    }, [filteredRows, dateSortOrder, sortMode, nameSortOrder, siteSortOrder]);

    const workerNameOptions = useMemo(() => {
        return allWorkers.map((worker, index) => ({
            id: String(worker.id ?? worker.legacyId ?? `${worker.name ?? 'worker'}-${index}`),
            name: worker.name ?? '',
            teamName: worker.teamName ?? '',
        }));
    }, [allWorkers]);

    const siteOptions = useMemo(() => {
        return sites
            .filter((site) => Boolean(site.id))
            .slice()
            .sort((a, b) => compareKo(a.name ?? '', b.name ?? ''));
    }, [sites]);

    const openColumnFilterOptions = useMemo(() => {
        if (!openColumnFilter) return [];

        const candidateRows = baseFilteredRows.filter((row) => {
            return (Object.keys(columnFilters) as ColumnFilterKey[]).every((key) => {
                if (key === openColumnFilter) return true;
                const selectedValues = columnFilters[key] ?? [];
                return selectedValues.includes(toColumnFilterValue(getColumnFilterValue(row, key)));
            });
        });

        const values = Array.from(new Set(
            candidateRows.map((row) => toColumnFilterValue(getColumnFilterValue(row, openColumnFilter)))
        ));

        values.sort((a, b) => compareKo(fromColumnFilterValue(a), fromColumnFilterValue(b)));
        return values;
    }, [baseFilteredRows, columnFilters, getColumnFilterValue, openColumnFilter]);

    const visibleOpenColumnFilterOptions = useMemo(() => {
        const keyword = columnFilterSearch.trim().toLowerCase();
        if (!keyword) return openColumnFilterOptions;

        return openColumnFilterOptions.filter((value) => {
            return fromColumnFilterValue(value).toLowerCase().includes(keyword);
        });
    }, [columnFilterSearch, openColumnFilterOptions]);

    useEffect(() => {
        if (!openColumnFilter) {
            setPendingColumnFilterValues(null);
            return;
        }

        const appliedValues = Object.prototype.hasOwnProperty.call(columnFilters, openColumnFilter)
            ? (columnFilters[openColumnFilter] ?? [])
            : openColumnFilterOptions;

        setPendingColumnFilterValues(appliedValues);
    }, [columnFilters, openColumnFilter, openColumnFilterOptions]);

    const hasColumnFilter = useCallback((key: ColumnFilterKey) => {
        return Object.prototype.hasOwnProperty.call(columnFilters, key);
    }, [columnFilters]);

    const handleToggleColumnFilterMenu = useCallback((key: ColumnFilterKey) => {
        setColumnFilterSearch('');
        setOpenColumnFilter((prev) => prev === key ? null : key);
    }, []);

    const handleResetColumnFilter = useCallback((key: ColumnFilterKey) => {
        if (openColumnFilter === key) {
            setPendingColumnFilterValues(openColumnFilterOptions);
            return;
        }

        setColumnFilters((prev) => {
            if (!Object.prototype.hasOwnProperty.call(prev, key)) return prev;
            const { [key]: _, ...rest } = prev;
            return rest;
        });
    }, [openColumnFilter, openColumnFilterOptions]);

    const handleResetAllColumnFilters = useCallback(() => {
        setColumnFilters({});
        setOpenColumnFilter(null);
        setColumnFilterSearch('');
    }, []);

    const isColumnFilterValueChecked = useCallback((_key: ColumnFilterKey, value: string, options: string[]) => {
        const values = pendingColumnFilterValues ?? options;
        return values.includes(value);
    }, [pendingColumnFilterValues]);

    const handleToggleColumnFilterValue = useCallback((_key: ColumnFilterKey, value: string, options: string[]) => {
        setPendingColumnFilterValues((prev) => {
            const baseValues = prev ?? options;
            const hasValue = baseValues.includes(value);
            const nextValues = hasValue
                ? baseValues.filter((item) => item !== value)
                : [...baseValues, value];
            return options.filter((item) => nextValues.includes(item));
        });
    }, []);

    const handleSelectAllColumnFilterValues = useCallback((_key: ColumnFilterKey) => {
        setPendingColumnFilterValues(openColumnFilterOptions);
    }, [openColumnFilterOptions]);

    const handleApplyColumnFilter = useCallback((key: ColumnFilterKey, options: string[]) => {
        const sourceValues = pendingColumnFilterValues ?? options;
        const orderedValues = options.filter((item) => sourceValues.includes(item));

        setColumnFilters((prev) => {
            if (orderedValues.length === options.length) {
                const { [key]: _, ...rest } = prev;
                return rest;
            }

            return {
                ...prev,
                [key]: orderedValues
            };
        });

        setOpenColumnFilter(null);
        setColumnFilterSearch('');
    }, [pendingColumnFilterValues]);

    const handleCloseColumnFilterMenu = useCallback(() => {
        setOpenColumnFilter(null);
        setColumnFilterSearch('');
    }, []);

    const handleClearColumnFilterValues = useCallback((key: ColumnFilterKey) => {
        if (openColumnFilter === key) {
            setPendingColumnFilterValues([]);
            return;
        }

        setColumnFilters((prev) => ({
            ...prev,
            [key]: []
        }));
    }, [openColumnFilter]);

    const renderFilterHeader = useCallback((
        key: ColumnFilterKey,
        label: string,
        className: string,
        menuAlign: 'left' | 'right' = 'left'
    ) => {
        const isOpen = openColumnFilter === key;
        const isActive = hasColumnFilter(key);
        const stagedValues = isOpen
            ? (pendingColumnFilterValues ?? openColumnFilterOptions)
            : (isActive ? (columnFilters[key] ?? []) : openColumnFilterOptions);
        const checkedCount = isOpen
            ? stagedValues.length
            : (isActive ? (columnFilters[key] ?? []).length : openColumnFilterOptions.length);
        const allCount = openColumnFilter === key ? openColumnFilterOptions.length : undefined;
        const previewValues = stagedValues.slice(0, 4);
        const isAllSelected = typeof allCount === 'number' && checkedCount === allCount;
        const isSelectionEmpty = checkedCount === 0;

        return (
            <th className={`${className} relative`}>
                <div className={`flex items-center gap-1 ${menuAlign === 'right' ? 'justify-end' : 'justify-between'}`}>
                    <span>{label}</span>
                    <button
                        type="button"
                        onClick={(event) => {
                            event.stopPropagation();
                            handleToggleColumnFilterMenu(key);
                        }}
                        className={`inline-flex h-6 w-6 items-center justify-center rounded border transition-colors ${
                            isActive || isOpen
                                ? 'border-white/50 bg-white/15 text-white'
                                : 'border-transparent text-white/80 hover:border-white/35 hover:bg-white/10 hover:text-white'
                        }`}
                        title={`${label} 필터`}
                    >
                        <FontAwesomeIcon icon={faFilter} className="text-[11px]" />
                    </button>
                </div>
                {isOpen && (
                    <div
                        ref={filterMenuRef}
                        onClick={(event) => event.stopPropagation()}
                        className={`absolute top-full mt-2 w-[240px] rounded-xl border border-slate-200 bg-white p-3 shadow-xl ${
                            menuAlign === 'right' ? 'right-0' : 'left-0'
                        } z-50`}
                    >
                        <div className="mb-2 flex items-center justify-between gap-2">
                            <div className="text-xs font-semibold text-slate-700">{label} 필터</div>
                            <button
                                type="button"
                                onClick={() => handleResetColumnFilter(key)}
                                className="text-[11px] text-slate-500 hover:text-slate-700"
                            >
                                초기화
                            </button>
                        </div>
                        <input
                            type="text"
                            value={columnFilterSearch}
                            onChange={(event) => setColumnFilterSearch(event.target.value)}
                            placeholder="값 검색"
                            className="mb-2 w-full rounded-lg border border-slate-300 px-3 py-2 text-xs"
                        />
                        <div className="mb-2 flex items-center justify-between text-[11px] text-slate-500">
                            <span>
                                {isAllSelected
                                    ? '전체 선택 상태'
                                    : (isSelectionEmpty ? '선택 없음' : `${checkedCount}개 선택`)}
                            </span>
                            {typeof allCount === 'number' && (
                                <span>전체 {allCount}개</span>
                            )}
                        </div>
                        <div className="mb-2 rounded-lg border border-slate-200 bg-slate-50 px-2.5 py-2">
                            <div className="mb-1 text-[11px] font-medium text-slate-500">현재 선택</div>
                            {isAllSelected ? (
                                <div className="text-xs font-semibold text-sky-700">전체 선택</div>
                            ) : (isSelectionEmpty ? (
                                <div className="text-xs font-semibold text-rose-600">선택된 값이 없습니다.</div>
                            ) : (
                                <div className="flex flex-wrap gap-1">
                                    {previewValues.map((value) => (
                                        <span
                                            key={`${key}-preview-${value}`}
                                            className="inline-flex max-w-full items-center rounded-full bg-sky-100 px-2 py-0.5 text-[11px] font-semibold text-sky-700"
                                        >
                                            <span className="truncate">{fromColumnFilterValue(value)}</span>
                                        </span>
                                    ))}
                                    {checkedCount > previewValues.length && (
                                        <span className="inline-flex items-center rounded-full bg-slate-200 px-2 py-0.5 text-[11px] font-semibold text-slate-600">
                                            +{checkedCount - previewValues.length}
                                        </span>
                                    )}
                                </div>
                            ))}
                        </div>
                        <div className="mb-2 flex gap-2">
                            <button
                                type="button"
                                onClick={() => handleSelectAllColumnFilterValues(key)}
                                className="rounded border border-slate-200 px-2 py-1 text-[11px] text-slate-600 hover:bg-slate-50"
                            >
                                전체선택
                            </button>
                            <button
                                type="button"
                                onClick={() => handleClearColumnFilterValues(key)}
                                className="rounded border border-slate-200 px-2 py-1 text-[11px] text-slate-600 hover:bg-slate-50"
                            >
                                전체해제
                            </button>
                        </div>
                        <div className="max-h-64 overflow-y-auto rounded-lg border border-slate-100">
                            {visibleOpenColumnFilterOptions.length === 0 ? (
                                <div className="px-3 py-6 text-center text-xs text-slate-400">선택 가능한 값이 없습니다.</div>
                            ) : (
                                visibleOpenColumnFilterOptions.map((value) => {
                                    const isChecked = isColumnFilterValueChecked(key, value, openColumnFilterOptions);

                                    return (
                                        <label
                                            key={`${key}-${value}`}
                                            className={`flex cursor-pointer items-center gap-2 border-b border-slate-100 px-3 py-2 text-xs last:border-b-0 ${
                                                isChecked
                                                    ? 'bg-sky-50 text-slate-900'
                                                    : 'text-slate-600 hover:bg-slate-50'
                                            }`}
                                        >
                                            <input
                                                type="checkbox"
                                                checked={isChecked}
                                                onChange={() => handleToggleColumnFilterValue(key, value, openColumnFilterOptions)}
                                                className="h-4 w-4 cursor-pointer rounded border-slate-300 accent-sky-600 focus:ring-2 focus:ring-sky-500"
                                                style={{ accentColor: '#0284c7' }}
                                            />
                                            <div className="flex min-w-0 flex-1 items-center justify-between gap-2">
                                                <span className={`truncate ${isChecked ? 'font-semibold text-slate-900' : ''}`}>
                                                    {fromColumnFilterValue(value)}
                                                </span>
                                                {isChecked && (
                                                    <span className="shrink-0 rounded-full bg-sky-100 px-1.5 py-0.5 text-[10px] font-semibold text-sky-700">
                                                        선택
                                                    </span>
                                                )}
                                            </div>
                                        </label>
                                    );
                                })
                            )}
                        </div>
                        <div className="mt-3 flex justify-end gap-2">
                            <button
                                type="button"
                                onClick={handleCloseColumnFilterMenu}
                                className="rounded border border-slate-200 px-3 py-1.5 text-[11px] text-slate-600 hover:bg-slate-50"
                            >
                                닫기
                            </button>
                            <button
                                type="button"
                                onClick={() => handleApplyColumnFilter(key, openColumnFilterOptions)}
                                className="rounded border border-indigo-600 bg-indigo-600 px-3 py-1.5 text-[11px] font-semibold text-white hover:bg-indigo-700"
                            >
                                적용
                            </button>
                        </div>
                    </div>
                )}
            </th>
        );
    }, [
        columnFilters,
        columnFilterSearch,
        handleApplyColumnFilter,
        handleClearColumnFilterValues,
        handleCloseColumnFilterMenu,
        handleResetColumnFilter,
        handleSelectAllColumnFilterValues,
        handleToggleColumnFilterMenu,
        handleToggleColumnFilterValue,
        hasColumnFilter,
        isColumnFilterValueChecked,
        openColumnFilter,
        openColumnFilterOptions,
        pendingColumnFilterValues,
        visibleOpenColumnFilterOptions
    ]);

    const visibleRowKeys = useMemo(() => {
        return sortedRows.map(getRowKey);
    }, [sortedRows, getRowKey]);

    useEffect(() => {
        setSelectedRowKeys((prev) => {
            if (prev.size === 0) return prev;
            const visibleSet = new Set(visibleRowKeys);
            const nextKeys = Array.from(prev).filter((k) => visibleSet.has(k));
            if (nextKeys.length === prev.size) return prev;
            return new Set(nextKeys);
        });
    }, [visibleRowKeys]);

    const isAllSelected = useMemo(() => {
        return visibleRowKeys.length > 0 && visibleRowKeys.every(k => selectedRowKeys.has(k));
    }, [visibleRowKeys, selectedRowKeys]);

    const toggleSelectAll = useCallback(() => {
        setSelectedRowKeys((prev) => {
            const next = new Set(prev);
            const allSelected = visibleRowKeys.length > 0 && visibleRowKeys.every(k => next.has(k));
            if (allSelected) {
                visibleRowKeys.forEach(k => next.delete(k));
                return next;
            }

            visibleRowKeys.forEach(k => next.add(k));
            return next;
        });
    }, [visibleRowKeys]);

    const toggleSelectRow = useCallback((rowKey: string) => {
        setSelectedRowKeys((prev) => {
            const next = new Set(prev);
            if (next.has(rowKey)) next.delete(rowKey);
            else next.add(rowKey);
            return next;
        });
    }, []);

    const handleToggleEditMode = () => {
        setIsEditMode((prev) => {
            const next = !prev;
            if (!next) {
                setSelectedRowKeys(new Set());
                setIsBulkEditOpen(false);
                setRowDrafts({});
                setRowSavingKeys(new Set());
            }
            return next;
        });
    };

    const getRowInitialDraft = useCallback((r: DailyReportWorkerRow): RowDraft => {
        const baseManDay = Number.isFinite(r.manDay) ? String(r.manDay) : '0';
        const baseUnitPrice = Number.isFinite(r.unitPrice) ? String(r.unitPrice) : '0';
        const canonicalWorkerTeamId = resolveWorkerTeamCanonicalId({
            workerTeamId: r.workerTeamId,
            workerTeamName: r.workerTeamName
        });
        const fallbackWorkerTeamName = r.workerTeamName
            ?? teams.find((team) => normalizeTeamId(team.id ?? team.legacyId ?? '') === canonicalWorkerTeamId)?.name
            ?? '';
        return {
            siteId: normalizeSiteId(r.siteId),
            teamId: normalizeTeamId(r.teamId),
            responsibleTeamId: resolveResponsibleTeamOptionId({
                responsibleTeamId: r.responsibleTeamId,
                responsibleTeamName: r.responsibleTeamName
            }),
            responsibleTeamName: resolveResponsibleTeamDisplayName({
                responsibleTeamId: r.responsibleTeamId,
                responsibleTeamName: r.responsibleTeamName
            }),
            workerName: r.workerName ?? '',
            workerTeamName: fallbackWorkerTeamName,
            workerTeamId: canonicalWorkerTeamId || undefined,
            salaryModel: resolveReportPayType(r),
            manDay: baseManDay,
            unitPrice: baseUnitPrice,
            workContent: String(r.workContent ?? ''),
            siteType: String(r.siteType ?? ''),
            paymentType: String(r.paymentType ?? '')
        };
    }, [normalizeSiteId, normalizeTeamId, resolveWorkerTeamCanonicalId, teams]);

    const isRowDirty = useCallback((original: DailyReportWorkerRow, draft?: RowDraft) => {
        if (!draft) return false;

        // 1. Check Worker Change
        if (draft.workerId && String(draft.workerId) !== String(original.workerId)) return true;

        // 2. Check Name Change (Typo fix)
        if (draft.workerName !== undefined && draft.workerName !== original.workerName) return true;

        if (draft.siteId !== normalizeSiteId(original.siteId)) return true;
        if (draft.teamId !== normalizeTeamId(original.teamId)) return true;
        if (draft.responsibleTeamId !== resolveResponsibleTeamOptionId({
            responsibleTeamId: original.responsibleTeamId,
            responsibleTeamName: original.responsibleTeamName
        })) return true;
        if (draft.responsibleTeamName !== resolveResponsibleTeamDisplayName({
            responsibleTeamId: original.responsibleTeamId,
            responsibleTeamName: original.responsibleTeamName
        })) return true;
        if (draft.salaryModel !== resolveReportPayType(original)) return true;
        if (Number(draft.manDay) !== (Number.isFinite(original.manDay) ? original.manDay : 0)) return true;
        if (Number(draft.unitPrice) !== (Number.isFinite(original.unitPrice) ? original.unitPrice : 0)) return true;
        if (draft.workContent !== (original.workContent ?? '')) return true;
        if (draft.siteType !== (original.siteType ?? '')) return true;
        if (draft.paymentType !== (original.paymentType ?? '')) return true;

        // Check workerTeamName change
        if (draft.workerTeamName !== undefined && draft.workerTeamName !== (original.workerTeamName ?? '')) return true;

        return false;
    }, [normalizeSiteId, normalizeTeamId, resolveResponsibleTeamDisplayName, resolveResponsibleTeamOptionId]);

    const setRowDraft = useCallback((r: DailyReportWorkerRow, changes: Partial<RowDraft>) => {
        const key = getRowKey(r);
        setRowDrafts(prev => {
            const current = prev[key] || {
                siteId: normalizeSiteId(r.siteId),
                teamId: normalizeTeamId(r.teamId),
                responsibleTeamId: resolveResponsibleTeamOptionId({
                    responsibleTeamId: r.responsibleTeamId,
                    responsibleTeamName: r.responsibleTeamName
                }),
                responsibleTeamName: resolveResponsibleTeamDisplayName({
                    responsibleTeamId: r.responsibleTeamId,
                    responsibleTeamName: r.responsibleTeamName
                }),
                workerName: r.workerName ?? '',
                workerTeamName: r.workerTeamName ?? '',
                workerTeamId: resolveWorkerTeamCanonicalId({
                    workerTeamId: r.workerTeamId,
                    workerTeamName: r.workerTeamName
                }) || undefined,
                salaryModel: resolveReportPayType(r),
                manDay: String(Number.isFinite(r.manDay) ? r.manDay : 0),
                unitPrice: String(Number.isFinite(r.unitPrice) ? r.unitPrice : 0),
                workContent: r.workContent ?? '',
                siteType: r.siteType ?? '',
                paymentType: r.paymentType ?? ''
            };
            return {
                ...prev,
                [key]: { ...current, ...changes }
            };
        });
    }, [getRowKey, normalizeSiteId, resolveResponsibleTeamDisplayName, resolveResponsibleTeamOptionId, resolveWorkerTeamCanonicalId]);

    const mergeRowDraft = useCallback((r: DailyReportWorkerRow, changes: Partial<RowDraft>): RowDraft => {
        const key = getRowKey(r);
        return {
            ...getRowInitialDraft(r),
            ...(rowDrafts[key] ?? {}),
            ...changes
        };
    }, [getRowInitialDraft, getRowKey, rowDrafts]);

    const clearRowDraft = useCallback((rowKey: string) => {
        setRowDrafts((prev) => {
            if (!prev[rowKey]) return prev;
            const { [rowKey]: _, ...rest } = prev;
            return rest;
        });
    }, []);

    const buildReportLevelUpdates = useCallback((original: DailyReportWorkerRow, draft: RowDraft) => {
        const reportLevelUpdates: Partial<DailyReportWorkerRow> & { siteId?: string; siteName?: string } = {};

        if (
            draft.responsibleTeamId !== resolveResponsibleTeamOptionId({
                responsibleTeamId: original.responsibleTeamId,
                responsibleTeamName: original.responsibleTeamName
            }) ||
            draft.responsibleTeamName !== resolveResponsibleTeamDisplayName({
                responsibleTeamId: original.responsibleTeamId,
                responsibleTeamName: original.responsibleTeamName
            })
        ) {
            const matchedTeam = teams.find((team) => {
                const canonicalId = normalizeTeamId(team.id ?? team.legacyId ?? '');
                const nameKey = normalizeTeamNameKey(team.name);
                return canonicalId === draft.responsibleTeamId || nameKey === normalizeTeamNameKey(draft.responsibleTeamName);
            });

            reportLevelUpdates.responsibleTeamId = matchedTeam?.id ? String(matchedTeam.id) : '';
            reportLevelUpdates.responsibleTeamName = matchedTeam?.name ?? draft.responsibleTeamName ?? '';
        }

        if (draft.siteId !== normalizeSiteId(original.siteId)) {
            const matchedSite = siteOptions.find((site) => String(site.id ?? '') === draft.siteId)
                ?? siteOptions.find((site) => String(site.legacyId ?? '') === draft.siteId);

            if (matchedSite?.id) {
                reportLevelUpdates.siteId = String(matchedSite.id);
                reportLevelUpdates.siteName = matchedSite.name ?? '';
            }
        }

        if (draft.siteType !== (original.siteType ?? '')) {
            reportLevelUpdates.siteType = draft.siteType;
        }

        if (draft.paymentType !== (original.paymentType ?? '')) {
            reportLevelUpdates.paymentType = draft.paymentType;
        }

        return reportLevelUpdates;
    }, [normalizeSiteId, normalizeTeamId, resolveResponsibleTeamDisplayName, resolveResponsibleTeamOptionId, siteOptions, teams]);

    // Worker Change Logic
    // Worker Change Logic
    const handleWorkerNameChange = useCallback((r: DailyReportWorkerRow, newName: string) => {
        // 1. Try to find match in allWorkers (exact first, then normalized without spaces - same as input tab)
        const trimmedName = newName.trim();
        const normalizedName = trimmedName.replace(/\s+/g, '');
        const matched = allWorkers.find(w => w.name === trimmedName)
            || (normalizedName ? allWorkers.find(w => w.name.replace(/\s+/g, '') === normalizedName) : undefined);

        if (matched) {
            // Check for duplicates ONLY within the same report (same reportId)
            // 같은 일보(reportId) 내에서만 중복 체크 (다른 날짜/현장에 같은 작업자가 있는 것은 정상)
            const isDuplicate = rows.some(existingRow => {
                // 같은 리포트 내에서만 체크
                if (existingRow.reportId !== r.reportId) return false;
                // 자신이 아닌 행 중에서
                if (getRowKey(existingRow) === getRowKey(r)) return false;
                // workerId가 같은 행이 있는지 확인 (draft가 있으면 draft 우선)
                const existingKey = getRowKey(existingRow);
                const existingDraft = rowDrafts[existingKey];
                const currentId = existingDraft?.workerId ?? existingRow.workerId;
                return String(currentId) === String(matched.id);
            });

            if (isDuplicate) {
                toast.warning(`'${newName}' 작업자는 같은 일보에 이미 포함되어 있습니다. (이름만 변경됨)`);
                setRowDraft(r, {
                    workerName: newName,
                    workerId: undefined, // 중복 방지를 위해 ID 매칭 해제
                    workerTeamName: '',
                    unitPrice: '0',
                    salaryModel: ''
                });
                return;
            }

            // 2. Lookup team from teams array
            // Try by teamId (checking both UUID and legacyId), then fallback to teamName
            let team = matched.teamId
                ? teams.find(t => t.id === matched.teamId || t.legacyId === matched.teamId)
                : undefined;

            // Fallback: if no team found by ID, try finding by name (try exact, then relaxed)
            if (!team && matched.teamName) {
                team = teams.find(t => t.name === matched.teamName);
                if (!team) {
                    const searchName = matched.teamName.replace(/\s+/g, '');
                    team = teams.find(t => t.name.replace(/\s+/g, '') === searchName);
                }
            }

            const resolvedTeamName = team?.name ?? matched.teamName ?? '';

            // Worker Found -> Auto-fill (단가, 급여방식, 작업팀 모두 채움)
            const draftUpdate = {
                workerName: newName,
                workerId: matched.id ? String(matched.id) : undefined,
                // 우선순위: 1. 팀 매칭 결과(resolvedTeamName) 2. 작업자 정보의 팀명(matched.teamName) 3. 작업자 정보의 팀유형(matched.teamType - 지원팀 등)
                workerTeamName: resolvedTeamName || matched.teamName || (matched.teamType === '지원팀' ? '지원팀' : ''),
                workerTeamId: normalizeTeamId(team?.id ? String(team.id) : (matched.teamId ? String(matched.teamId) : '')) || undefined,
                unitPrice: String(matched.unitPrice ?? 0),
                salaryModel: resolveWorkerPayType(matched) || '일급제'
            };
            setRowDraft(r, draftUpdate);
        } else {
            // Worker Not Found -> Just update name only (타이핑 중에는 다른 필드 초기화하지 않음)
            setRowDraft(r, {
                workerName: newName
            });
        }
    }, [allWorkers, teams, setRowDraft, rows, rowDrafts, getRowKey, normalizeTeamId]);

    const saveRowDraft = useCallback(async (
        r: DailyReportWorkerRow,
        draft: RowDraft,
        options?: { confirmSave?: boolean; successMessage?: string }
    ) => {
        const key = getRowKey(r);
        const { confirmSave = true, successMessage = '저장되었습니다.' } = options ?? {};

        if (confirmSave) {
            const result = await confirm.save('저장하시겠습니까?');
            if (!result.isConfirmed) return false;
        }

        setRowSavingKeys(prev => {
            const next = new Set(prev);
            next.add(key);
            return next;
        });

        try {
            // Prepare updates
            const updates: any = {};

            if (draft.workerId && String(draft.workerId) !== String(r.workerId)) {
                updates.workerId = draft.workerId;
            }
            if (draft.workerName !== undefined && draft.workerName !== r.workerName) {
                updates.name = draft.workerName;
            }

            const resolvedWorkerTeamId = draft.workerTeamId
                ? normalizeTeamId(draft.workerTeamId)
                : resolveWorkerTeamCanonicalId({ workerTeamName: draft.workerTeamName });

            // Resolve teamId from worker master when worker is changed
            if (draft.workerId) {
                const matchedWorker = allWorkers.find(w => String(w.id) === String(draft.workerId));
                if (matchedWorker?.teamId) {
                    updates.teamId = matchedWorker.teamId;
                }
            }
            if (!updates.teamId && resolvedWorkerTeamId) {
                updates.teamId = resolvedWorkerTeamId;
            }

            updates.salaryModel = draft.salaryModel;
            updates.payType = draft.salaryModel; // sync
            updates.manDay = Number(draft.manDay);
            updates.unitPrice = Number(draft.unitPrice);
            updates.workContent = draft.workContent;
            updates.workerTeamName = draft.workerTeamName ?? '';
            updates.siteType = draft.siteType;
            updates.paymentType = draft.paymentType;
            updates.amount = updates.manDay * updates.unitPrice;
            const reportLevelUpdates = buildReportLevelUpdates(r, draft);

            await dailyReportService.updateWorkerInReport(r.reportId, r.workerId, updates);
            if (Object.keys(reportLevelUpdates).length > 0) {
                await dailyReportService.updateReport(r.reportId, reportLevelUpdates as any);
            }
            if (successMessage) {
                toast.success(successMessage);
            }
            clearRowDraft(key);

            // Optimistic Update
            setRows(prev => prev.map(row => {
                const isSameReport = row.reportId === r.reportId;
                const isSameWorker = row.workerId === r.workerId;

                if (isSameWorker) {
                    return { ...row, ...updates, ...reportLevelUpdates };
                }

                if (isSameReport) {
                    if (Object.keys(reportLevelUpdates).length > 0) {
                        return { ...row, ...reportLevelUpdates };
                    }
                }

                return row;
            }));
            return true;
        } catch (error) {
            console.error(error);
            toast.error('저장 실패');
            return false;
        } finally {
            setRowSavingKeys(prev => {
                const next = new Set(prev);
                next.delete(key);
                return next;
            });
        }
    }, [allWorkers, buildReportLevelUpdates, clearRowDraft, confirm, getRowKey, normalizeTeamId, resolveWorkerTeamCanonicalId, toast]);

    const handleSaveRow = useCallback(async (r: DailyReportWorkerRow) => {
        const key = getRowKey(r);
        const draft = rowDrafts[key];
        if (!draft) return;
        await saveRowDraft(r, draft, { confirmSave: true, successMessage: '저장되었습니다.' });
    }, [getRowKey, rowDrafts, saveRowDraft]);

    const handleQuickRowUpdate = useCallback(async (r: DailyReportWorkerRow, changes: Partial<RowDraft>) => {
        const key = getRowKey(r);
        const nextDraft = mergeRowDraft(r, changes);

        setRowDrafts((prev) => ({
            ...prev,
            [key]: nextDraft
        }));

        if (!isRowDirty(r, nextDraft)) {
            clearRowDraft(key);
            return;
        }

        await saveRowDraft(r, nextDraft, { confirmSave: false, successMessage: '수정되었습니다.' });
    }, [clearRowDraft, getRowKey, isRowDirty, mergeRowDraft, saveRowDraft]);

    const handleQuickWorkerNameUpdate = useCallback(async (r: DailyReportWorkerRow, workerName: string) => {
        const trimmedName = workerName.trim();
        const normalizedName = trimmedName.replace(/\s+/g, '');
        const matched = allWorkers.find(w => w.name === trimmedName)
            || (normalizedName ? allWorkers.find(w => w.name.replace(/\s+/g, '') === normalizedName) : undefined);

        let nextChanges: Partial<RowDraft> = {
            workerName
        };

        if (matched) {
            const isDuplicate = rows.some(existingRow => {
                if (existingRow.reportId !== r.reportId) return false;
                if (getRowKey(existingRow) === getRowKey(r)) return false;
                const existingKey = getRowKey(existingRow);
                const existingDraft = rowDrafts[existingKey];
                const currentId = existingDraft?.workerId ?? existingRow.workerId;
                return String(currentId) === String(matched.id);
            });

            if (isDuplicate) {
                toast.warning(`'${workerName}' 작업자는 같은 일보에 이미 포함되어 있습니다. (이름만 변경됨)`);
                nextChanges = {
                    workerName,
                    workerId: undefined,
                    workerTeamName: '',
                    unitPrice: '0',
                    salaryModel: ''
                };
            } else {
                let team = matched.teamId
                    ? teams.find(t => t.id === matched.teamId || t.legacyId === matched.teamId)
                    : undefined;

                if (!team && matched.teamName) {
                    team = teams.find(t => t.name === matched.teamName);
                    if (!team) {
                        const searchName = matched.teamName.replace(/\s+/g, '');
                        team = teams.find(t => t.name.replace(/\s+/g, '') === searchName);
                    }
                }

                const resolvedTeamName = team?.name ?? matched.teamName ?? '';
                nextChanges = {
                    workerName,
                    workerId: matched.id ? String(matched.id) : undefined,
                    workerTeamName: resolvedTeamName || matched.teamName || (matched.teamType === '지원팀' ? '지원팀' : ''),
                    workerTeamId: normalizeTeamId(team?.id ? String(team.id) : (matched.teamId ? String(matched.teamId) : '')) || undefined,
                    unitPrice: String(matched.unitPrice ?? 0),
                    salaryModel: resolveWorkerPayType(matched) || '일급제'
                };
            }
        }

        await handleQuickRowUpdate(r, nextChanges);
    }, [allWorkers, getRowKey, handleQuickRowUpdate, normalizeTeamId, rowDrafts, rows, teams, toast]);

    const handleBulkApply = async () => {
        const selected = Array.from(selectedRowKeys)
            .map((k) => rowByKey.get(k))
            .filter((r): r is DailyReportWorkerRow => !!r);

        if (selected.length === 0) return;

        const parsedManDay = bulkManDay.trim() === '' ? null : Number(bulkManDay);
        const parsedUnitPrice = bulkUnitPrice.trim() === '' ? null : Number(bulkUnitPrice);
        const nextSalaryModel = bulkSalaryModel.trim() === '' ? null : bulkSalaryModel.trim();
        const nextWorkContent = bulkWorkContent.trim() === '' ? null : bulkWorkContent.trim();

        if (parsedManDay != null && (!Number.isFinite(parsedManDay) || parsedManDay < 0)) {
            alert('공수 값이 올바르지 않습니다.');
            return;
        }
        if (parsedUnitPrice != null && (!Number.isFinite(parsedUnitPrice) || parsedUnitPrice < 0)) {
            alert('단가 값이 올바르지 않습니다.');
            return;
        }

        if (parsedManDay == null && parsedUnitPrice == null && nextSalaryModel == null && nextWorkContent == null) {
            alert('변경할 값이 없습니다.');
            return;
        }

        const ok = await confirm.batch('일보', selected.length);
        if (!ok.isConfirmed) return;

        setIsLoading(true);
        try {
            const tasks = selected.map((r) => {
                const updates: Partial<DailyReportWorker> = {};
                if (parsedManDay != null) updates.manDay = parsedManDay;
                if (parsedUnitPrice != null) updates.unitPrice = parsedUnitPrice;
                if (nextSalaryModel != null) updates.salaryModel = nextSalaryModel;
                if (nextWorkContent != null) updates.workContent = nextWorkContent;
                if (bulkSiteType) updates.siteType = bulkSiteType;
                if (bulkPaymentType) updates.paymentType = bulkPaymentType;
                if (bulkWorkerTeamName.trim()) updates.workerTeamName = bulkWorkerTeamName.trim();
                return dailyReportService.updateWorkerInReport(r.reportId, r.workerId, updates);
            });

            const batchSize = 10;
            for (let i = 0; i < tasks.length; i += batchSize) {
                await Promise.all(tasks.slice(i, i + batchSize));
            }

            toast.updated('일보');
            setSelectedRowKeys(new Set());
            setIsBulkEditOpen(false);
            setBulkManDay('');
            setBulkUnitPrice('');
            setBulkSalaryModel('');
            setBulkWorkContent('');
            setBulkSiteType('');
            setBulkPaymentType('');
            setBulkWorkerTeamName('');
            await fetchRows();
        } catch (error) {
            console.error('[DailyReportListV2] bulk update failed', error);
            toast.error('일괄 수정에 실패했습니다.');
        } finally {
            setIsLoading(false);
        }
    };

    const handleBulkDelete = async () => {
        const selected = Array.from(selectedRowKeys)
            .map((k) => rowByKey.get(k))
            .filter((r): r is DailyReportWorkerRow => !!r);

        if (selected.length === 0) return;

        const ok = await confirm.delete(`선택한 ${selected.length}건 삭제`);
        if (!ok.isConfirmed) return;

        setIsLoading(true);
        try {
            // Execute sequentially to prevent race conditions on Report Header Stats (Total ManDay updates)
            // Parallel execution causes multiple requests to read the same initial Total and overwrite each other's decrements.
            let successCount = 0;
            for (const r of selected) {
                try {
                    await dailyReportService.removeWorkerFromReport(r.reportId, r.workerId);
                    successCount++;
                } catch (e) {
                    console.error(`Failed to delete worker ${r.workerName} `, e);
                }
            }

            if (successCount === selected.length) {
                toast.deleted('일보', successCount);
            } else {
                toast.updated(`일보 ${successCount}건 삭제 완료(실패 ${selected.length - successCount}건)`);
            }

            setSelectedRowKeys(new Set());
            setIsBulkEditOpen(false);
            await fetchRows();
        } catch (error) {
            console.error('[DailyReportListV2] bulk delete failed', error);
            toast.error('삭제 중 오류가 발생했습니다.');
        } finally {
            setIsLoading(false);
        }
    };

    const totals = useMemo(() => {
        const totalManDay = sortedRows.reduce((sum, r) => sum + (Number.isFinite(r.manDay) ? r.manDay : 0), 0);
        const totalAmount = sortedRows.reduce((sum, r) => sum + (Number.isFinite(r.amount) ? r.amount : 0), 0);
        return { totalManDay, totalAmount };
    }, [sortedRows]);

    const dirtyRowCount = useMemo(() => {
        let count = 0;
        const keys = Object.keys(rowDrafts);
        for (const key of keys) {
            const draft = rowDrafts[key];
            const original = rowByKey.get(key);
            if (original && isRowDirty(original, draft)) {
                count++;
            }
        }
        return count;
    }, [rowDrafts, rowByKey, isRowDirty]);

    const handleSaveAllDirtyRows = async () => {
        if (dirtyRowCount === 0) return;

        const result = await confirm.save(`변경된 ${dirtyRowCount}건의 항목을 일괄 저장하시겠습니까?`);
        if (!result.isConfirmed) return;

        setIsLoading(true);
        try {
            const dirtyKeys = Object.keys(rowDrafts).filter(key => {
                const original = rowByKey.get(key);
                return original && isRowDirty(original, rowDrafts[key]);
            });

            let successCount = 0;
            let failCount = 0;

            for (const key of dirtyKeys) {
                const r = rowByKey.get(key)!;
                const draft = rowDrafts[key];

                try {
                    const updates: any = {};
                    if (draft.workerId && String(draft.workerId) !== String(r.workerId)) updates.workerId = draft.workerId;
                    if (draft.workerName !== undefined && draft.workerName !== r.workerName) updates.name = draft.workerName;
                    
                    // 소속팀 ID 및 이름 업데이트
                    if (draft.workerTeamId !== undefined) {
                        updates.teamId = normalizeTeamId(draft.workerTeamId);
                    } else {
                        const resolvedWorkerTeamId = resolveWorkerTeamCanonicalId({ workerTeamName: draft.workerTeamName });
                        if (resolvedWorkerTeamId) updates.teamId = resolvedWorkerTeamId;
                    }

                    if (!updates.teamId && draft.workerId) {
                        const matchedWorker = allWorkers.find(w => String(w.id) === String(draft.workerId));
                        if (matchedWorker?.teamId) {
                            updates.teamId = matchedWorker.teamId;
                        }
                    }

                    updates.salaryModel = draft.salaryModel;
                    updates.payType = draft.salaryModel;
                    updates.manDay = Number(draft.manDay);
                    updates.unitPrice = Number(draft.unitPrice);
                    updates.workContent = draft.workContent;
                    updates.workerTeamName = draft.workerTeamName ?? '';
                    updates.siteType = draft.siteType;
                    updates.paymentType = draft.paymentType;
                    updates.amount = updates.manDay * updates.unitPrice;

                    const reportLevelUpdates = buildReportLevelUpdates(r, draft);

                    await dailyReportService.updateWorkerInReport(r.reportId, r.workerId, updates);
                    if (Object.keys(reportLevelUpdates).length > 0) {
                        await dailyReportService.updateReport(r.reportId, reportLevelUpdates as any);
                    }

                    successCount++;
                } catch (error) {
                    failCount++;
                    console.error('[SaveAll] Row save failed:', error);
                }
            }

            if (failCount === 0) {
                toast.success(`${successCount}건 저장 완료`);
            } else {
                toast.warning(`${successCount}건 저장, ${failCount}건 실패 (중복 등 확인 필요)`);
            }

            setRowDrafts({}); // Clear all drafts (Successful ones are updated via fetchRows, failed ones lost but safer than inconsistent state)
            await fetchRows();
        } catch (error) {
            console.error('[DailyReportListV2] Save All Failed (Critical)', error);
            toast.error('일괄 저장 중 시스템 오류가 발생했습니다.');
        } finally {
            setIsLoading(false);
        }
    };

    const isTransferBusy = isLoading || isResettingDb || isDownloadingExcel;

    const handleResetDb = useCallback(async () => {
        const confirmed = await Swal.fire({
            icon: 'warning',
            title: '일보 DB 초기화',
            html: '<div class="text-sm text-slate-600">`daily_reports`와 `daily_report_workers`를 모두 비웁니다.<br />계속하려면 <strong>일보DB초기화</strong>를 입력하세요.</div>',
            input: 'text',
            inputPlaceholder: '일보DB초기화',
            showCancelButton: true,
            confirmButtonText: '초기화',
            cancelButtonText: '취소',
            confirmButtonColor: '#dc2626',
            preConfirm: (value) => {
                if (String(value ?? '').trim() !== '일보DB초기화') {
                    Swal.showValidationMessage('확인 문구가 일치하지 않습니다.');
                }
                return value;
            },
        });
        if (!confirmed.isConfirmed) return;

        setIsResettingDb(true);
        try {
            const result = await dailyReportTransferService.resetDb();
            setSelectedRowKeys(new Set());
            setRowDrafts({});
            await fetchRows();
            toast.success(`DB 초기화 완료 (일보 ${result.reports} / 상세 ${result.legacyRows})`);
        } catch (error) {
            console.error('[DailyReportListV2] DB reset failed', error);
            toast.error('일보 DB 초기화에 실패했습니다.');
        } finally {
            setIsResettingDb(false);
        }
    }, [fetchRows]);

    const handleDownloadExcel = useCallback(async () => {
        if (sortedRows.length === 0) {
            toast.info('다운로드할 행이 없습니다.');
            return;
        }

        setIsDownloadingExcel(true);
        try {
            const exportRows = sortedRows.map((row) => ({
                ...row,
                workerTeamName: resolveWorkerTeamDisplayName({
                    workerTeamId: row.workerTeamId,
                    workerTeamName: row.workerTeamName
                })
            }));

            await dailyReportTransferService.exportRowsToExcel(exportRows, `조회일보목록_${startDate}_${endDate}`);
            toast.success('조회 목록 엑셀 다운로드 완료');
        } catch (error) {
            console.error('[DailyReportListV2] Excel download failed', error);
            toast.error('조회 목록 엑셀 다운로드에 실패했습니다.');
        } finally {
            setIsDownloadingExcel(false);
        }
    }, [endDate, resolveWorkerTeamDisplayName, sortedRows, startDate]);

    return (
        <div className="daily-report-v2-page flex flex-col flex-1 min-h-0 gap-3 p-0 pb-1">
            <div className="flex-shrink-0 bg-white px-3 py-2.5 rounded-xl shadow-sm border border-slate-200 flex flex-wrap gap-2 items-end">
                <div className="flex items-center gap-2 flex-wrap w-full">
                    <div className="flex items-center gap-2">
                        <div className="relative">
                            <FontAwesomeIcon icon={faCalendarAlt} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                            <input
                                type="text"
                                inputMode="numeric"
                                value={startDateInput}
                                onChange={(e) => setStartDateInput(sanitizeTypedDateInput(e.target.value))}
                                onBlur={() => { commitDateInput('start'); }}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        commitDateInput('start');
                                    }
                                }}
                                placeholder="YYYY-MM-DD"
                                className="pl-10 pr-3 py-2 border-slate-300 rounded-lg text-sm w-[130px]"
                            />
                        </div>
                        <span className="text-slate-400">~</span>
                        <input
                            type="text"
                            inputMode="numeric"
                            value={endDateInput}
                            onChange={(e) => setEndDateInput(sanitizeTypedDateInput(e.target.value))}
                            onBlur={() => { commitDateInput('end'); }}
                            onKeyDown={(e) => {
                                if (e.key === 'Enter') {
                                    commitDateInput('end');
                                }
                            }}
                            placeholder="YYYY-MM-DD"
                            className="px-3 py-2 border-slate-300 rounded-lg text-sm w-[130px]"
                            />

                        <div className="flex gap-1">
                            <button
                                onClick={() => {
                                    const d = new Date();
                                    d.setMonth(d.getMonth() - 1);
                                    d.setDate(1);
                                    const start = formatYmd(d);

                                    const endD = new Date(d.getFullYear(), d.getMonth() + 1, 0);
                                    const end = formatYmd(endD);
                                    applyDateRange(start, end);
                                }}
                                className="px-2 py-1.5 text-xs bg-slate-50 text-slate-600 rounded-lg font-medium hover:bg-slate-100 transition-colors border border-slate-200"
                            >
                                전달
                            </button>
                            <button
                                onClick={() => {
                                    const d = new Date();
                                    d.setDate(1);
                                    const start = formatYmd(d);

                                    const endD = new Date(d.getFullYear(), d.getMonth() + 1, 0);
                                    const end = formatYmd(endD);
                                    applyDateRange(start, end);
                                }}
                                className="px-2 py-1.5 text-xs bg-blue-50 text-blue-600 rounded-lg font-medium hover:bg-blue-100 transition-colors border border-blue-100"
                            >
                                이달
                            </button>
                            <button
                                onClick={() => {
                                    const y = new Date();
                                    y.setDate(y.getDate() - 1);
                                    const yStr = formatYmd(y);
                                    applyDateRange(yStr, yStr);
                                }}
                                className="px-2 py-1.5 text-xs bg-slate-50 text-slate-600 rounded-lg font-medium hover:bg-slate-100 transition-colors border border-slate-200"
                            >
                                어제
                            </button>
                            <button
                                onClick={() => {
                                    applyDateRange(todayStr, todayStr);
                                }}
                                className="px-2 py-1.5 text-xs bg-slate-50 text-slate-600 rounded-lg font-medium hover:bg-slate-100 transition-colors border border-slate-200"
                            >
                                오늘
                            </button>
                        </div>

                        <button
                            onClick={() => {
                                setSortMode('date');
                                setDateSortOrder((prev) => (prev === 'desc' ? 'asc' : 'desc'));
                            }}
                            className={`px-3 py-2 text-sm rounded-lg font-medium flex items-center gap-2 transition-colors border ${dateSortOrder === 'desc'
                                ? 'bg-indigo-50 text-indigo-600 border-indigo-100'
                                : 'bg-amber-50 text-amber-600 border-amber-100'
                                }`}
                            title="날짜 정렬"
                        >
                            <FontAwesomeIcon icon={dateSortOrder === 'desc' ? faSortAmountDown : faSortAmountUp} />
                        </button>

                        <button
                            onClick={() => {
                                setSortMode('name');
                                setNameSortOrder((prev) => (prev === 'asc' ? 'desc' : 'asc'));
                            }}
                            className={`px-3 py-2 text-sm rounded-lg font-medium flex items-center gap-2 transition-colors border ${sortMode === 'name'
                                ? 'bg-emerald-50 text-emerald-700 border-emerald-100'
