                )}
                <div className="flex flex-wrap gap-6 items-start content-start">
                    {tables.map((table, tableIndex) => (
                        <TypingTable
                            key={table.id}
                            table={table}
                            index={tableIndex}
                            sites={sites}
                            onSiteChange={handleTableSiteChange}
                            onNameChange={handleNameChange}
                            onRowChange={handleRowChange}
                            onAddRows={addRowsToTable}
                        />
                    ))}
                </div>
            </div>
        </div>
    );
};

export default DailyReportTyping;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { HotTable } from '@handsontable/react';
import { registerAllModules } from 'handsontable/registry';
import 'handsontable/dist/handsontable.full.min.css';
import { dailyReportService, DailyReport } from '../../services/dailyReportService';
import { teamService, Team } from '../../services/teamService';
import { siteService, Site } from '../../services/siteService';
import { manpowerService, Worker } from '../../services/manpowerService';
import { geminiService } from '../../services/geminiService';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faSave, faCalendarAlt, faSpinner, faPlus, faComment, faCloudUploadAlt } from '@fortawesome/free-solid-svg-icons';
import Swal from 'sweetalert2';

// Register Handsontable modules
registerAllModules();

const DailyReportV2Page: React.FC = () => {
    const hotRef = useRef<any>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [loading, setLoading] = useState(false);
    const [teams, setTeams] = useState<Team[]>([]);
    const [sites, setSites] = useState<Site[]>([]);
    const [workers, setWorkers] = useState<Worker[]>([]);
    const [data, setData] = useState<any[]>([]);
    const [isDragging, setIsDragging] = useState(false);

    // Dropdown Sources
    const [teamNames, setTeamNames] = useState<string[]>([]);
    const [siteNames, setSiteNames] = useState<string[]>([]);
    const [workerNames, setWorkerNames] = useState<string[]>([]);

    useEffect(() => {
        fetchInitialData();
    }, []);

    useEffect(() => {
        fetchReports();
    }, [date]);

    const fetchInitialData = async () => {
        try {
            const [fetchedTeams, fetchedSites, fetchedWorkers] = await Promise.all([
                teamService.getTeams(),
                siteService.getSites(),
                manpowerService.getWorkers()
            ]);

            setTeams(fetchedTeams);
            setSites(fetchedSites);
            setWorkers(fetchedWorkers);

            setTeamNames(fetchedTeams.map(t => t.name));
            setSiteNames(fetchedSites.map(s => s.name));
            setWorkerNames(fetchedWorkers.map(w => w.name));

        } catch (error) {
            console.error("Error fetching initial data:", error);
            Swal.fire('Error', '기초 데이터를 불러오는데 실패했습니다.', 'error');
        }
    };

    const fetchReports = async () => {
        setLoading(true);
        try {
            const reports = await dailyReportService.getReports({ startDate: date, endDate: date });
            const gridData: any[] = [];

            reports.forEach(report => {
                report.workers.forEach(worker => {
                    gridData.push({
                        id: report.id,
                        workerId: worker.workerId,
                        team: report.teamName,
                        site: report.siteName,
                        name: worker.name,
                        role: worker.role,
                        manDay: worker.manDay,
                        unitPrice: worker.unitPrice || 0,
                        amount: (worker.manDay || 0) * (worker.unitPrice || 0),
                        note: worker.workContent || ''
                    });
                });
            });

            // Fill with empty rows if few
            while (gridData.length < 20) {
                gridData.push({});
            }

            setData(gridData);

        } catch (error) {
            console.error("Error fetching reports:", error);
            Swal.fire('Error', '일보 데이터를 불러오는데 실패했습니다.', 'error');
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        setLoading(true);
        try {
            const hot = hotRef.current?.hotInstance;
            const sourceData = hot?.getSourceData();

            if (!sourceData) return;

            // Group by Team and Site to create/update reports
            const reportsToSave = new Map<string, any>();

            for (const row of sourceData) {
                if (!row.team || !row.site || !row.name) continue;

                const team = teams.find(t => t.name === row.team);
                const site = sites.find(s => s.name === row.site);

                // Try to find worker by name
                let worker = workers.find(w => w.name === row.name);

                if (!team || !site) continue;

                const key = `${team.id}_${site.id}`;

                if (!reportsToSave.has(key)) {
                    reportsToSave.set(key, {
                        date: date,
                        teamId: team.id,
                        teamName: team.name,
                        siteId: site.id,
                        siteName: site.name,
                        workers: [],
                        totalManDay: 0,
                        writerId: 'system'
                    });
                }

                const report = reportsToSave.get(key);

                report.workers.push({
                    workerId: worker ? worker.id : 'unknown_' + Date.now(),
                    name: row.name,
                    role: row.role || (worker ? worker.role : '조공'),
                    status: 'attendance',
                    manDay: parseFloat(row.manDay) || 0,
                    unitPrice: parseInt(row.unitPrice) || 0,
                    workContent: row.note || '',
                    teamId: worker ? worker.teamId : undefined,
                    salaryModel: worker?.teamType === '지원팀' ? '지원팀' : worker?.teamType === '용역팀' ? '용역팀' : (worker?.salaryModel || '일급제')
                });

                report.totalManDay += parseFloat(row.manDay) || 0;
            }

            // Optimized Batch Save
            for (const report of Array.from(reportsToSave.values())) {
                await dailyReportService.addWorkersToReportBatch({
                    date: report.date,
                    teamId: report.teamId,
                    teamName: report.teamName,
                    siteId: report.siteId,
                    siteName: report.siteName,
                    workers: report.workers
                });
            }

            Swal.fire('Success', '일보가 저장되었습니다.', 'success');
            fetchReports();

        } catch (error) {
            console.error("Error saving reports:", error);
            Swal.fire('Error', '저장 중 오류가 발생했습니다.', 'error');
        } finally {
            setLoading(false);
        }
    };

    // AI & Drag Drop Logic
    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        if (!e.currentTarget.contains(e.relatedTarget as Node)) {
            setIsDragging(false);
        }
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);

        const file = e.dataTransfer.files?.[0];
        if (file) {
            processKakaoImage(file);
        }
    };

    const handleKakaoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            processKakaoImage(file);
        }
        e.target.value = ''; // Reset
    };

    const processKakaoImage = async (file: File) => {
        if (!file.type.startsWith('image/')) {
            Swal.fire('Error', '이미지 파일만 가능합니다.', 'error');
            return;
        }

        const apiKey = geminiService.getKey();
        if (!apiKey) {
            Swal.fire('Info', 'API 키 설정이 필요합니다. (/settings/ai)', 'info');
            return;
        }

        setLoading(true);
        try {
            const analyzedReports = await geminiService.analyzeKakaoImage(file);

            // Convert analyzed data to grid rows
            const newRows: any[] = [];

            for (const report of analyzedReports) {
                // Find matching Site
                // Priority: Exact > Contains
                const site = sites.find(s => s.name === report.siteName) ||
                    sites.find(s => s.name.includes(report.siteName || '') || (report.siteName || '').includes(s.name));
                const siteName = site?.name || report.siteName || ''; // Use matched or raw
                const siteResponsibleTeam = site?.responsibleTeamName || '';

                for (const w of report.workers) {
                    const worker = workers.find(wk => wk.name === w.name);

                    let teamName = siteResponsibleTeam || '미지정';
                    if (worker?.teamType === '지원팀') teamName = '지원';
                    // If worker has a specific team and it's not support, use that? 
                    // Usually Report is mostly about Site's team, but if worker is borrowed...
                    // Let's stick to site's team or simple logic for now.

                    newRows.push({
                        team: teamName,
                        site: siteName,
                        name: w.name,
                        role: w.role || worker?.role || '작업자',
                        manDay: w.manDay,
                        unitPrice: worker?.unitPrice || 0,
                        amount: (typeof w.manDay === 'number' ? w.manDay : 1) * (worker?.unitPrice || 0),
                        note: ''
                    });
                }
            }

            if (newRows.length === 0) {
                Swal.fire('Info', '인식된 데이터가 없습니다.', 'info');
                return;
            }

            // Append to existing data
            setData(prev => {
                // Filter out trailing empty rows from prev to make space
                const nonEmpty = prev.filter(r => r.name || r.site || r.team);
                const combined = [...nonEmpty, ...newRows];
                // Pad to at least 20
                while (combined.length < 20) combined.push({});
                return combined;
            });

            Swal.fire('Success', `${newRows.length}명의 데이터가 추가되었습니다.`, 'success');

        } catch (error) {
            console.error("AI Analysis Failed", error);
            Swal.fire('Error', '이미지 분석에 실패했습니다.', 'error');
        } finally {
            setLoading(false);
        }
    };

    // Handsontable Settings
    const hotSettings = {
        data: data,
        colHeaders: ['팀', '현장', '성명', '공종', '공수', '단가', '금액', '비고'],
        columns: [
            { data: 'team', type: 'dropdown', source: teamNames },
            { data: 'site', type: 'dropdown', source: siteNames },
            { data: 'name', type: 'autocomplete', source: workerNames, strict: false },
            { data: 'role', type: 'text' },
            { data: 'manDay', type: 'numeric', numericFormat: { pattern: '0.0' } },
            { data: 'unitPrice', type: 'numeric', numericFormat: { pattern: '0,0' } },
            { data: 'amount', type: 'numeric', numericFormat: { pattern: '0,0' }, readOnly: true },
            { data: 'note', type: 'text' }
        ],
        rowHeaders: true,
        width: '100%',
        height: 'auto',
        licenseKey: 'non-commercial-and-evaluation',
        contextMenu: true,
        minSpareRows: 5,
        afterChange: (changes: any, source: any) => {
            if (source === 'loadData') return;
            if (!changes) return;

            const hot = hotRef.current?.hotInstance;
            if (!hot) return;

            changes.forEach(([row, prop, oldValue, newValue]: any) => {
                // Auto-calculate Amount
                if (prop === 'manDay' || prop === 'unitPrice') {
                    const manDay = hot.getDataAtRowProp(row, 'manDay');
                    const unitPrice = hot.getDataAtRowProp(row, 'unitPrice');
                    const amount = (parseFloat(manDay) || 0) * (parseInt(unitPrice) || 0);
                    hot.setDataAtRowProp(row, 'amount', amount);
                }

                // Auto-fill Role/UnitPrice if Name changes
                if (prop === 'name' && newValue) {
                    const worker = workers.find(w => w.name === newValue);
                    if (worker) {
                        if (!hot.getDataAtRowProp(row, 'role')) hot.setDataAtRowProp(row, 'role', worker.role);
                        if (!hot.getDataAtRowProp(row, 'unitPrice')) hot.setDataAtRowProp(row, 'unitPrice', worker.unitPrice);
                    }
                }
            });
        }
    };

    return (
        <div
            className="flex flex-col h-full bg-slate-50 relative"
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
        >
            {/* Overlay */}
            {isDragging && (
                <div className="absolute inset-0 bg-yellow-400/80 z-50 flex items-center justify-center backdrop-blur-sm pointer-events-none">
                    <div className="text-center bg-white p-8 rounded-2xl shadow-2xl">
                        <FontAwesomeIcon icon={faComment} className="text-6xl text-yellow-500 mb-4" />
                        <h2 className="text-3xl font-bold text-slate-800">카톡 이미지 떨어뜨리기</h2>
                        <p className="text-xl text-slate-500 mt-2">AI가 자동으로 일보를 작성합니다!</p>
                    </div>
                </div>
            )}

            {/* Header Toolbar */}
            <div className="bg-white px-6 py-4 border-b border-slate-200 flex items-center justify-between shadow-sm">
                <div className="flex items-center gap-4">
                    <h1 className="text-lg font-bold text-slate-800">일보 등록 (Spreadsheet)</h1>
                    <div className="flex items-center gap-2 bg-slate-100 rounded-lg px-3 py-2">
                        <FontAwesomeIcon icon={faCalendarAlt} className="text-slate-500" />
                        <input
                            type="date"
                            value={date}
                            onChange={(e) => setDate(e.target.value)}
                            className="bg-transparent border-none text-sm font-bold text-slate-700 focus:ring-0 p-0"
                        />
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    <button
                        onClick={() => fileInputRef.current?.click()}
                        className="px-4 py-2 bg-yellow-400 text-slate-900 rounded-lg font-bold hover:bg-yellow-500 transition-colors flex items-center gap-2 shadow-sm"
                    >
                        <FontAwesomeIcon icon={faComment} />
                        카톡 분석 (AI)
                    </button>
                    <input
                        type="file"
                        ref={fileInputRef}
                        onChange={handleKakaoUpload}
                        className="hidden"
                        accept="image/*"
                    />

                    <button
                        onClick={handleSave}
                        disabled={loading}
                        className="px-4 py-2 bg-indigo-600 text-white rounded-lg font-bold hover:bg-indigo-700 transition-colors flex items-center gap-2 shadow-sm disabled:opacity-50"
                    >
                        {loading ? <FontAwesomeIcon icon={faSpinner} spin /> : <FontAwesomeIcon icon={faSave} />}
                        저장하기
                    </button>
                </div>
            </div>

            {/* Content */}
            <div className="flex-1 p-4 overflow-hidden flex flex-col">
                <div className="flex-1 bg-white rounded-xl shadow-sm overflow-hidden p-4">
                    <HotTable
                        ref={hotRef}
                        settings={hotSettings}
                    />
                </div>

                {loading && (
                    <div className="absolute inset-0 bg-black/20 flex items-center justify-center z-40 backdrop-blur-[1px]">
                        <div className="bg-white p-6 rounded-xl shadow-2xl flex flex-col items-center">
                            <div className="animate-spin text-indigo-600 mb-3">
                                <FontAwesomeIcon icon={faSpinner} size="2x" />
                            </div>
                            <span className="font-bold text-slate-700">처리 중입니다...</span>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default DailyReportV2Page;

import React, { useState, useCallback, useRef } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import * as XLSX from 'xlsx';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faCloudUploadAlt, faArrowRight, faCheckCircle, faSpinner,
    faExclamationTriangle, faFileExcel, faLink, faDatabase,
    faBuilding, faUser, faTable
} from '@fortawesome/free-solid-svg-icons';
import Swal from 'sweetalert2';
import { dailyReportService } from '../../services/dailyReportService';
import { siteService } from '../../services/siteService';
import { teamService } from '../../services/teamService';
import { manpowerService } from '../../services/manpowerService';

// --- Types ---
type UploadStep = 'upload' | 'mapping' | 'preview' | 'uploading' | 'complete';

interface SystemField {
    key: string;
    label: string;
    required: boolean;
    description: string;
    aliases: string[]; // For auto-mapping
}

const SYSTEM_FIELDS: SystemField[] = [
    { key: 'date', label: '날짜', required: true, description: 'YYYY-MM-DD 형식', aliases: ['날짜', '작업일', '일자', 'Date'] },
    { key: 'siteName', label: '현장명', required: true, description: '현장이 없으면 자동 생성됨', aliases: ['현장', '현장명', 'Site'] },
    { key: 'teamName', label: '팀명', required: true, description: '팀이 없으면 자동 생성됨', aliases: ['팀', '팀명', '업체', 'Team'] },
    { key: 'workerName', label: '작업자명', required: true, description: '작업자 이름', aliases: ['이름', '작업자', '성명', 'Name'] },
    { key: 'manDay', label: '공수', required: true, description: '기본 1.0', aliases: ['공수', '품', 'ManDay'] },
    { key: 'role', label: '직종/역할', required: false, description: '예: 기공, 조공', aliases: ['직종', '역할', 'Role'] },
    { key: 'workContent', label: '작업내용', required: false, description: '상세 작업 내용', aliases: ['작업내용', '내용', 'Content'] },
    { key: 'payType', label: '지급구분', required: false, description: '월급제 / 일급제 / 팀기성', aliases: ['지급구분', '구분', 'PayType'] },
    { key: 'note', label: '비고', required: false, description: '기타 메모', aliases: ['비고', 'Note'] },
];

const MassDailyReportUploader: React.FC = () => {
    const { currentUser } = useAuth();
    const [step, setStep] = useState<UploadStep>('upload');

    // Data State
    const [excelHeaders, setExcelHeaders] = useState<string[]>([]);
    const [rawExcelData, setRawExcelData] = useState<any[]>([]); // 10k rows potentially
    const [columnMapping, setColumnMapping] = useState<{ [key: string]: string }>({}); // SystemKey -> ExcelHeader
    const [previewData, setPreviewData] = useState<any[]>([]);

    // Upload State
    const [progress, setProgress] = useState(0);
    const [log, setLog] = useState<string[]>([]);
    const [uploadStats, setUploadStats] = useState({ success: 0, fail: 0, total: 0 });

    // --- Step 1: File Upload ---
    const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (evt) => {
            const bstr = evt.target?.result;
            const wb = XLSX.read(bstr, { type: 'binary' });
            const wsname = wb.SheetNames[0];
            const ws = wb.Sheets[wsname];

            // Read headers first
            const data: any[] = XLSX.utils.sheet_to_json(ws, { header: 1 });
            if (data.length === 0) return;

            const headers = data[0] as string[];
            setExcelHeaders(headers);

            // Read full data as objects
            const jsonData = XLSX.utils.sheet_to_json(ws);
            setRawExcelData(jsonData);

            // Auto-Map Logic
            const initialMapping: { [key: string]: string } = {};
            SYSTEM_FIELDS.forEach(field => {
                const match = headers.find(h => field.aliases.includes(h) || h.includes(field.label));
                if (match) initialMapping[field.key] = match;
            });
            setColumnMapping(initialMapping);

            setStep('mapping');
        };
        reader.readAsBinaryString(file);
    };

    // --- Step 2: Mapping Logic ---
    const handleMappingChange = (systemKey: string, excelHeader: string) => {
        setColumnMapping(prev => ({ ...prev, [systemKey]: excelHeader }));
    };

    const proceedToPreview = () => {
        // Validate required fields
        const missingRequired = SYSTEM_FIELDS.filter(f => f.required && !columnMapping[f.key]);
        if (missingRequired.length > 0) {
            Swal.fire('매핑 확인 필요', `필수 항목이 연결되지 않았습니다: ${missingRequired.map(f => f.label).join(', ')}`, 'warning');
            return;
        }

        // Generate Preview (First 5 Rows)
        const sample = rawExcelData.slice(0, 5).map(row => {
            const mappedRow: any = {};
            SYSTEM_FIELDS.forEach(field => {
                const excelKey = columnMapping[field.key];
                mappedRow[field.key] = excelKey ? row[excelKey] : '';
            });
            return mappedRow;
        });

        setPreviewData(sample);
        setStep('preview');
    };

    // --- Step 3: Execution ---
    const startUpload = async () => {
        setStep('uploading');
        setLog([]);
        setUploadStats({ success: 0, fail: 0, total: rawExcelData.length });

        // --- PRE-FETCH CACHE ---
        setLog(prev => [...prev, "시스템 데이터(현장, 팀) 로딩 중..."]);
        const [existingSites, existingTeams, existingWorkers] = await Promise.all([
            siteService.getSites(),
            teamService.getTeams(),
            manpowerService.getWorkers()
        ]);

        const siteMap = new Map(existingSites.map(s => [s.name, s]));
        const teamMap = new Map(existingTeams.map(t => [t.name, t]));
        const workerMap = new Map(existingWorkers.map(w => [w.name, w]));

        const BATCH_SIZE = 50; // Firestore limit 500 writes, safe size 50 docs (writes can assume multiple ops per doc)
        const totalRows = rawExcelData.length;
        let successCount = 0;
        let failCount = 0;

        // Process in Chunks
        for (let i = 0; i < totalRows; i += BATCH_SIZE) {
            const chunk = rawExcelData.slice(i, i + BATCH_SIZE);
            const batchReports: any[] = [];

            // Process Chunk
            for (const row of chunk) {
                try {
                    // Extract Mapped Data
                    const mapped: any = {};
                    SYSTEM_FIELDS.forEach(field => {
                        const excelKey = columnMapping[field.key] || '';
                        mapped[field.key] = excelKey ? row[excelKey] : undefined;
                    });

                    // Skip empty rows
                    if (!mapped.workerName) continue;

                    // 1. Resolve Site (Find or Create)
                    let siteName = (mapped.siteName || '미지정현장').toString().trim();
                    let siteId = '';

                    if (siteMap.has(siteName)) {
                        siteId = siteMap.get(siteName)!.id!;
                    } else {
                        // Create New Site on Fly (Wait for creation to ensure ID exists?)
                        // Ideally we should batch create sites, but for simplicity we create one by one or assume creation in service.
                        // To avoid awaits in loop, we optimistically create? No, needs ID.
                        // We must await creation if it's new.
                        const newId = await siteService.addSite({
                            name: siteName,
                            code: 'AUTO',
                            address: '',
                            status: 'active'
                        });
                        const newSite: any = { id: newId, name: siteName };
                        siteMap.set(siteName, newSite);
                        siteId = newId;
                        setLog(prev => [...prev, `[신규생성] 현장: ${siteName}`]);
                    }

                    // 2. Resolve Team (Find or Create)
                    let teamName = (mapped.teamName || '미지정팀').toString().trim();
                    let teamId = '';

                    if (teamMap.has(teamName)) {
                        teamId = teamMap.get(teamName)!.id!;
                    } else {
                        const newId = await teamService.addTeam({
                            name: teamName,
                            type: 'partner',
                            leaderId: 'unknown',
                            leaderName: '미지정'
                        });
                        const newTeam: any = { id: newId, name: teamName };
                        teamMap.set(teamName, newTeam);
                        teamId = newId;
                        setLog(prev => [...prev, `[신규생성] 팀: ${teamName}`]);
                    }

                    // 3. Prepare Report Object
                    const existingWorker = workerMap.get(mapped.workerName);

                    batchReports.push({
                        date: mapped.date || new Date().toISOString().split('T')[0], // Need cleaner Logic
                        siteId,
                        siteName,
                        teamId,
                        teamName,
                        totalManDay: parseFloat(mapped.manDay || '1'),
                        writerId: currentUser?.uid || 'system',
                        workers: [{
                            workerId: existingWorker ? existingWorker.id : `batch_${Date.now()}_${Math.random()}`,
                            name: mapped.workerName,
                            role: mapped.role || (existingWorker ? existingWorker.role : '조공'),
                            manDay: parseFloat(mapped.manDay || '1'),
                            workContent: mapped.workContent || '',
                            status: 'attendance',
                            teamId: existingWorker ? existingWorker.teamId : undefined,
                            payType: mapped.payType || '',
                            salaryModel: (mapped.payType || '일급제').toString().trim() || '일급제'
                        }]
                    });

                } catch (err) {
                    failCount++;
                }
            }

            // Save Batch
            if (batchReports.length > 0) {
                try {
                    // Use dailyReportService.addReportsBatch (Optimized)
                    // Note: addReportsBatch expects arrays of reports.
                    // If multiple workers are in same day/team/site, we should ideally merge them?
                    // For now, let's just save individual reports (legacy support).
                    // Or better, we just loop addWorkerToReport? No, that's too many reads.
                    // Let's use addReportsBatch (it creates separate docs).
                    await dailyReportService.addReportsBatch(batchReports);
                    successCount += batchReports.length;
                } catch (e) {
                    console.error('Batch Save Failed', e);
                    failCount += batchReports.length;
                    setLog(prev => [...prev, `[에러] 배치 저장 실패: ${i}~${i + BATCH_SIZE}`]);
                }
            }

            // Update Progress
            const currentProgress = Math.min(100, Math.round(((i + BATCH_SIZE) / totalRows) * 100));
            setProgress(currentProgress);
            setUploadStats({ success: successCount, fail: failCount, total: totalRows });

            // Artificial delay to prevent UI freeze and rate limits
            await new Promise(r => setTimeout(r, 50));
        }

        setStep('complete');
    };

    // --- UI Components ---
    return (
        <div className="max-w-6xl mx-auto p-8 h-full flex flex-col">
            {/* Header */}
            <div className="mb-8">
                <h1 className="text-3xl font-bold text-slate-800">대용량 엑셀 업로드 마법사</h1>
                <p className="text-slate-500 mt-2">10,000건 이상의 데이터도 안전하게 나누어 전송합니다.</p>
            </div>

            {/* Stepper */}
            <div className="flex items-center mb-8 bg-white p-4 rounded-xl shadow-sm border border-slate-100">
                {[
                    { id: 'upload', label: '1. 파일 선택', icon: faFileExcel },
                    { id: 'mapping', label: '2. 항목 연결', icon: faLink },
                    { id: 'preview', label: '3. 데이터 검사', icon: faTable },
                    { id: 'uploading', label: '4. 저장 실행', icon: faDatabase },
                ].map((s, idx) => (
                    <div key={s.id} className={`flex items-center ${step === s.id ? 'text-blue-600 font-bold' : 'text-slate-400'}`}>
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center mr-2 border ${step === s.id ? 'bg-blue-100 border-blue-500' : 'bg-slate-50 border-slate-200'}`}>
                            <FontAwesomeIcon icon={s.icon} />
                        </div>
                        <span className="mr-8">{s.label}</span>
                        {idx < 3 && <FontAwesomeIcon icon={faArrowRight} className="mr-8 text-slate-300" />}
                    </div>
                ))}
            </div>

            {/* Content Area */}
            <div className="flex-1 bg-white rounded-2xl shadow-lg border border-slate-200 overflow-hidden flex flex-col p-8">

                {/* Step 1: Upload */}
                {step === 'upload' && (
                    <div className="flex flex-col items-center justify-center h-full border-4 border-dashed border-slate-200 rounded-xl hover:bg-slate-50 transition-colors p-20 cursor-pointer relative">
                        <input type="file" onChange={handleFileUpload} accept=".xlsx, .xls" className="absolute inset-0 opacity-0 cursor-pointer" />
                        <FontAwesomeIcon icon={faCloudUploadAlt} className="text-6xl text-blue-400 mb-6" />
                        <h2 className="text-2xl font-bold text-slate-700 mb-2">엑셀 파일을 여기에 끌어다 놓으세요</h2>
                        <p className="text-slate-500">또는 클릭하셔서 파일을 선택하세요 (최대 50MB)</p>
                        <div className="mt-8 bg-blue-50 text-blue-700 px-4 py-2 rounded text-sm">
                            💡 Tip: 첫 번째 줄에 '날짜', '현장명', '팀명', '이름'이 있으면 자동 인식됩니다.
                        </div>
                    </div>
                )}

                {/* Step 2: Mapping */}
                {step === 'mapping' && (
                    <div className="h-full flex flex-col">
                        <h3 className="text-xl font-bold text-slate-800 mb-4 border-l-4 border-blue-500 pl-3">엑셀 항목과 시스템 항목을 연결합니다</h3>
                        <div className="flex-1 overflow-auto">
                            <table className="w-full text-left border-collapse">
                                <thead className="bg-slate-100 text-slate-600">
                                    <tr>
                                        <th className="p-4 border-b">시스템 항목 (저장될 곳)</th>
                                        <th className="p-4 border-b text-center"><FontAwesomeIcon icon={faArrowRight} /></th>
                                        <th className="p-4 border-b">내 엑셀 파일 항목</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {SYSTEM_FIELDS.map(field => (
                                        <tr key={field.key} className="border-b hover:bg-slate-50">
                                            <td className="p-4">
                                                <div className="font-bold text-slate-700">{field.label} {field.required && <span className="text-red-500">*</span>}</div>
                                                <div className="text-xs text-slate-400">{field.description}</div>
                                            </td>
                                            <td className="p-4 text-center text-slate-300">
                                                <FontAwesomeIcon icon={faLink} />
                                            </td>
                                            <td className="p-4">
                                                <select
                                                    className={`w-full p-2 border rounded-lg ${columnMapping[field.key] ? 'border-green-300 bg-green-50 text-green-700 font-bold' : 'border-slate-200 text-slate-400'}`}
                                                    value={columnMapping[field.key] || ''}
                                                    onChange={(e) => handleMappingChange(field.key, e.target.value)}
                                                >
                                                    <option value="">(선택 안함)</option>
                                                    {excelHeaders.map(h => (
                                                        <option key={h} value={h}>{h}</option>
                                                    ))}
                                                </select>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <div className="mt-6 flex justify-end">
                            <button onClick={proceedToPreview} className="px-8 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold shadow-lg transition transform hover:scale-105">
                                데이터 검사하기 <FontAwesomeIcon icon={faArrowRight} />
                            </button>
                        </div>
                    </div>
                )}

                {/* Step 3: Preview */}
                {step === 'preview' && (
                    <div className="h-full flex flex-col">
                        <div className="mb-6 bg-yellow-50 p-4 rounded-xl border border-yellow-200 flex items-start gap-4">
                            <FontAwesomeIcon icon={faExclamationTriangle} className="text-yellow-500 text-xl mt-1" />
                            <div>
                                <h3 className="font-bold text-yellow-800">최종 확인 (총 {rawExcelData.length.toLocaleString()}건)</h3>
                                <p className="text-sm text-yellow-700 mt-1">
                                    아래는 처음 5건의 데이터 미리보기입니다.<br />
                                    <strong>주의:</strong> '현장명'과 '팀명'이 시스템에 없는 경우, <strong>자동으로 신규 생성</strong>됩니다.
                                </p>
                            </div>
                        </div>

                        <div className="overflow-x-auto border rounded-xl shadow-sm">
                            <table className="w-full text-sm text-left">
                                <thead className="bg-slate-100 text-slate-700 font-bold">
                                    <tr>
                                        {SYSTEM_FIELDS.map(f => (
                                            <th key={f.key} className="p-3 border-b whitespace-nowrap">{f.label}</th>
                                        ))}
                                    </tr>
                                </thead>
                                <tbody>
                                    {previewData.map((row, idx) => (
                                        <tr key={idx} className="border-b hover:bg-slate-50">
                                            {SYSTEM_FIELDS.map(f => (
                                                <td key={f.key} className="p-3 border-r last:border-r-0 max-w-[200px] truncate">
                                                    {row[f.key] || <span className="text-slate-300 italic">(비어있음)</span>}
                                                </td>
                                            ))}
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>

                        <div className="mt-8 flex justify-between items-center">
                            <button onClick={() => setStep('mapping')} className="text-slate-500 hover:text-slate-800 font-medium">
                                ← 항목 연결 다시하기
                            </button>
                            <button onClick={startUpload} className="px-8 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold shadow-lg transition transform hover:scale-105 flex items-center gap-2">
                                <FontAwesomeIcon icon={faCloudUploadAlt} />
                                {rawExcelData.length.toLocaleString()}건 저장 시작
                            </button>
                        </div>
                    </div>
                )}

                {/* Step 4: Uploading */}
                {(step === 'uploading' || step === 'complete') && (
                    <div className="h-full flex flex-col items-center justify-center max-w-2xl mx-auto w-full">

                        {step === 'uploading' ? (
                            <div className="text-center mb-10">
                                <FontAwesomeIcon icon={faSpinner} spin className="text-6xl text-blue-500 mb-6" />
                                <h2 className="text-3xl font-bold text-slate-800 mb-2">데이터 저장 중...</h2>
                                <p className="text-slate-500">창을 닫지 마세요. 100건씩 나누어 안전하게 저장하고 있습니다.</p>
                            </div>
                        ) : (
                            <div className="text-center mb-10">
                                <FontAwesomeIcon icon={faCheckCircle} className="text-6xl text-green-500 mb-6" />
                                <h2 className="text-3xl font-bold text-slate-800 mb-2">저장 완료!</h2>
                                <p className="text-slate-500">모든 데이터 처리가 끝났습니다.</p>
                            </div>
                        )}

                        {/* Progress Bar */}
                        <div className="w-full bg-slate-200 rounded-full h-6 mb-4 overflow-hidden shadow-inner">
                            <div
                                className="bg-gradient-to-r from-blue-500 to-indigo-500 h-6 rounded-full transition-all duration-300 relative flex items-center justify-center text-xs text-white font-bold"
                                style={{ width: `${progress}%` }}
                            >
                                {progress}%
                            </div>
                        </div>

                        {/* Stats */}
                        <div className="grid grid-cols-3 gap-6 w-full mb-8">
                            <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm text-center">
                                <div className="text-slate-500 text-sm mb-1">총 데이터</div>
                                <div className="text-2xl font-bold text-slate-800">{uploadStats.total.toLocaleString()}</div>
                            </div>
                            <div className="bg-green-50 p-4 rounded-xl border border-green-200 shadow-sm text-center">
                                <div className="text-green-600 text-sm mb-1">성공</div>
                                <div className="text-2xl font-bold text-green-700">{uploadStats.success.toLocaleString()}</div>
                            </div>
                            <div className="bg-red-50 p-4 rounded-xl border border-red-200 shadow-sm text-center">
                                <div className="text-red-600 text-sm mb-1">실패</div>
                                <div className="text-2xl font-bold text-red-700">{uploadStats.fail.toLocaleString()}</div>
                            </div>
                        </div>

                        {/* Live Logs */}
                        <div className="w-full bg-slate-900 rounded-xl p-4 h-48 overflow-y-auto font-mono text-sm text-green-400 shadow-inner">
                            {log.map((line, idx) => (
                                <div key={idx} className="mb-1 opacity-80">{'>'} {line}</div>
                            ))}
                            {step === 'uploading' && <div className="animate-pulse">{'>'} Processing...</div>}
                        </div>

                        {step === 'complete' && (
                            <button onClick={() => window.location.reload()} className="mt-8 px-6 py-2 bg-slate-200 hover:bg-slate-300 text-slate-700 rounded-lg font-bold">
                                추가 업로드 하기
                            </button>
                        )}
                    </div>
                )}

            </div>
        </div>
    );
};

export default MassDailyReportUploader;

import SmartExcelGrid from './SmartExcelGrid';

import React, { useState, useEffect } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faPaste, faSave, faCheckCircle, faExclamationTriangle, faSpinner, faArrowRight } from '@fortawesome/free-solid-svg-icons';
import { dailyReportService } from '../../services/dailyReportService';
import { teamService, Team } from '../../services/teamService';
import { siteService, Site } from '../../services/siteService';
import { manpowerService, Worker } from '../../services/manpowerService';
import Swal from 'sweetalert2';

const FIELD_LABELS: { [key: string]: string } = {
    date: '날짜',
    siteName: '현장명',
    teamName: '팀명',
    workerName: '성명',
    manDay: '공수',
    unitPrice: '단가',
    workContent: '작업내용',
    payType: '구분'
};

const SmartDailyReportRegistrationPage: React.FC = () => {
    // Data States
    const [parsedData, setParsedData] = useState<any[]>([]);
    const [headers, setHeaders] = useState<string[]>([]);
    const [mappedFields, setMappedFields] = useState<{ [index: number]: string }>({});
    const [loading, setLoading] = useState(false);

    // Lookups
    const [teams, setTeams] = useState<Team[]>([]);
    const [sites, setSites] = useState<Site[]>([]);
    const [workers, setWorkers] = useState<Worker[]>([]);

    useEffect(() => {
        const fetchLookups = async () => {
            try {
                const [teamsData, sitesData, workersData] = await Promise.all([
                    teamService.getTeams(),
                    siteService.getSites(),
                    manpowerService.getWorkers()
                ]);
                setTeams(teamsData);
                setSites(sitesData);
                setWorkers(workersData);
            } catch (error) {
                console.error("Error fetching lookups:", error);
            }
        };
        fetchLookups();
    }, []);

    const handleSave = async () => {
        const validRows = parsedData.filter(r => r._valid);
        if (validRows.length === 0) {
            Swal.fire('Error', '저장할 유효한 데이터가 없습니다.', 'error');
            return;
        }

        setLoading(true);
        let successCount = 0;
        let failCount = 0;

        try {
            for (const row of validRows) {
                try {
                    // Find Site ID and Team ID
                    const site = sites.find(s => s.name === row.siteName);
                    const team = teams.find(t => t.name === row.teamName);

                    if (!site) throw new Error(`현장을 찾을 수 없음: ${row.siteName}`);
                    if (!team) throw new Error(`팀을 찾을 수 없음: ${row.teamName}`);

                    const existingWorker = workers.find(w => w.name === row.workerName);

                    await dailyReportService.addWorkerToReport(
                        row.date,
                        team.id!,
                        team.name,
                        site.id!,
                        site.name,
                        {
                            workerId: existingWorker ? existingWorker.id! : `temp_${Date.now()}_${Math.random()}`,
                            name: row.workerName,
                            role: existingWorker?.role || '일용직',
                            status: 'attendance',
                            manDay: parseFloat(row.manDay),
                            unitPrice: row.unitPrice ? parseFloat(row.unitPrice) : (existingWorker ? (existingWorker as any).unitPrice || 0 : 0),
                            payType: row.payType || (existingWorker ? (existingWorker as any).payType : ''),
                            workContent: row.workContent || '',
                            teamId: existingWorker ? existingWorker.teamId : team.id
                        },
                        {
                            companyId: site.companyId,
                            companyName: site.companyName,
                            constructorCompanyId: site.constructorCompanyId,
                            constructorCompanyName: site.constructorCompanyName,
                            partnerId: site.partnerId,
                            partnerName: site.partnerName != null ? String(site.partnerName) : undefined
                        }
                    );
                    successCount++;
                } catch (error) {
                    console.error("Failed to add report entry:", row, error);
                    failCount++;
                }
            }

            Swal.fire({
                title: '완료',
                text: `성공: ${successCount}건, 실패: ${failCount}건`,
                icon: failCount > 0 ? 'warning' : 'success'
            });

            if (successCount > 0) {
                setParsedData([]);
                setHeaders([]);
            }

        } catch (error) {
            console.error("Batch save error:", error);
            Swal.fire('Error', '저장 중 오류가 발생했습니다.', 'error');
        } finally {
            setLoading(false);
        }
    };

    // ... (keep useEffect)

    const handleGridChange = (data: any[]) => {
        // Map grid data to component state
        const mapped = data.map((row, idx) => {
            const { date, siteName, responsibleTeamName, name, teamName, manDay, workContent, payType, unitPrice } = row;

            const matchedWorker = workers.find(w => w.name === name);
            const matchedSite = sites.find(s => s.name === siteName);

            const rowData: any = {
                _valid: true,
                _errors: [],
                date: date || new Date().toISOString().split('T')[0],
                siteName: siteName,
                // New Fields for Display
                clientName: matchedSite?.companyName || '',
                partnerName: matchedSite?.partnerName || '',
                constructorName: matchedSite?.constructorCompanyName || '',
                teamName: teamName,  // Worker's Team
                workerName: name,
                manDay: typeof manDay === 'number' ? manDay.toFixed(1) : (manDay || '1.0'),
                unitPrice: unitPrice || (matchedWorker ? matchedWorker.unitPrice : '0'),
                workContent: workContent || '',
                payType: payType || (matchedWorker ? matchedWorker.payType : '')
            };

            // Validation
            if (!rowData.siteName) { rowData._valid = false; rowData._errors.push('현장명 누락'); }
            if (!rowData.teamName) { rowData._valid = false; rowData._errors.push('팀명 누락'); }
            if (!rowData.workerName) { rowData._valid = false; rowData._errors.push('이름 누락'); }

            return rowData;
        });

        // Set Headers purely for display (fixed structure now)
        setHeaders(['날짜', '현장명', '담당팀', '이름', '팀명', '공수', '단가', '구분', '작업내용']);
        // Mock mapped fields for preview table compatibility
        setMappedFields({ 0: 'date', 1: 'siteName', 2: 'teamName', 3: 'workerName', 4: 'teamName', 5: 'manDay', 6: 'unitPrice', 7: 'payType', 8: 'workContent' });

        setParsedData(mapped);
    };

    // ... (keep handleSave)

    return (
        <div className="p-6 max-w-7xl mx-auto">
            {/* ... Header ... */}
            <div className="flex flex-col gap-6">
                {/* ... Title ... */}
                <div className="flex justify-between items-end">
                    <div>
                        <h1 className="text-2xl font-bold text-slate-800 tracking-tight">일보 대량 등록 (엑셀 그리드)</h1>
                        <p className="text-slate-500 mt-1 text-sm">엑셀 데이터를 아래 표에 붙여넣으세요 (Ctrl+V).</p>
                    </div>
                    {/* ... Button ... */}
                    <div className="flex gap-2">
                        <button
                            onClick={handleSave}
                            disabled={loading || parsedData.length === 0}
                            className="bg-black hover:bg-slate-800 text-white px-5 py-2.5 rounded-lg font-medium text-sm shadow-sm flex items-center gap-2 transition-all disabled:opacity-30 disabled:cursor-not-allowed"
                        >
                            {loading ? <FontAwesomeIcon icon={faSpinner} spin /> : <FontAwesomeIcon icon={faSave} />}
                            일괄 등록
                        </button>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-1 gap-6 h-[800px]">
                    {/* Full Width Grid Input */}
                    <div className="flex flex-col h-1/2">
                        <SmartExcelGrid onChange={handleGridChange} />
                    </div>

                    {/* Preview Area */}
                    <div className="flex flex-col h-1/2 bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-white">
                            <h3 className="font-bold text-slate-700 flex items-center gap-2">
                                <span className="w-2 h-2 rounded-full bg-green-500"></span>
                                데이터 미리보기
                                <span className="text-slate-400 font-normal text-sm ml-1">({parsedData.length}건)</span>
                            </h3>
                        </div>
                        {/* ... Table (keep existing table logic) ... */}
                        <div className="flex-1 overflow-auto bg-slate-50/50 relative">
                            {parsedData.length > 0 ? (
                                <table className="w-full text-sm text-left border-collapse">
                                    {/* ... Use existing table structure ... */}
                                    <thead className="text-xs text-slate-500 font-medium bg-white sticky top-0 shadow-sm z-10">
                                        <tr>
                                            <th className="px-4 py-3 border-b border-slate-100 w-12 text-center">상태</th>
                                            <th className="px-4 py-3 border-b border-slate-100">날짜</th>
                                            <th className="px-4 py-3 border-b border-slate-100">현장명</th>
                                            <th className="px-4 py-3 border-b border-slate-100">발주사</th>
                                            <th className="px-4 py-3 border-b border-slate-100">협력사</th>
                                            <th className="px-4 py-3 border-b border-slate-100">시공사</th>
                                            <th className="px-4 py-3 border-b border-slate-100">팀명</th>
                                            <th className="px-4 py-3 border-b border-slate-100">이름</th>
                                            <th className="px-4 py-3 border-b border-slate-100">공수</th>
                                            <th className="px-4 py-3 border-b border-slate-100">단가</th>
                                            <th className="px-4 py-3 border-b border-slate-100">구분</th>
                                            <th className="px-4 py-3 border-b border-slate-100">작업내용</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100 bg-white">
                                        {parsedData.map((row, rowIdx) => (
                                            <tr key={rowIdx} className={`group transition-colors ${row._valid ? 'hover:bg-slate-50' : 'bg-red-50/50 hover:bg-red-50'}`}>
                                                <td className="px-4 py-2.5 text-center">
                                                    {row._valid ? (
                                                        <div className="w-1.5 h-1.5 rounded-full bg-green-400 mx-auto"></div>
                                                    ) : (
                                                        <FontAwesomeIcon icon={faExclamationTriangle} className="text-red-400 text-xs" title={row._errors.join(', ')} />
                                                    )}
                                                </td>
                                                <td className="px-4 py-2.5">{row.date}</td>
                                                <td className="px-4 py-2.5">{row.siteName}</td>
                                                <td className="px-4 py-2.5 text-slate-500 text-xs">{row.clientName || '-'}</td>
                                                <td className="px-4 py-2.5 text-slate-500 text-xs">{row.partnerName || '-'}</td>
                                                <td className="px-4 py-2.5 text-slate-500 text-xs">{row.constructorName || '-'}</td>
                                                <td className="px-4 py-2.5">{row.teamName}</td>
                                                <td className="px-4 py-2.5">{row.workerName}</td>
                                                <td className="px-4 py-2.5">{row.manDay}</td>
                                                <td className="px-4 py-2.5">{row.unitPrice ? parseInt(row.unitPrice).toLocaleString() : '0'}</td>
                                                <td className="px-4 py-2.5">
                                                    <span className={`px-2 py-0.5 rounded text-xs ${row.payType === '일급' ? 'bg-blue-50 text-blue-600' : 'bg-slate-100 text-slate-500'}`}>
                                                        {row.payType || '-'}
                                                    </span>
                                                </td>
                                                <td className="px-4 py-2.5">{row.workContent}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            ) : (
                                <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-300">
                                    <FontAwesomeIcon icon={faPaste} className="text-4xl mb-3 opacity-20" />
                                    <p className="text-sm">위 그리드에 데이터를 붙여넣으면 미리보기가 표시됩니다.</p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default SmartDailyReportRegistrationPage;

import React, { useRef, useEffect, useState } from 'react';
import { HotTable } from '@handsontable/react';
import { registerAllModules } from 'handsontable/registry';
import 'handsontable/dist/handsontable.full.min.css';
import Handsontable from 'handsontable';

registerAllModules();

interface SmartExcelGridProps {
    onChange: (data: any[]) => void;
}

const SmartExcelGrid: React.FC<SmartExcelGridProps> = ({ onChange }) => {
    const hotRef = useRef<any>(null);

    // Initial Data: 20 empty rows for easy pasting
    const [hotData, setHotData] = useState<any[]>(
        Array.from({ length: 50 }, () => ['', '', '', '', '', '', '', ''])
    );

    const columns = [
        { title: '날짜 (YYYY-MM-DD)', type: 'date', dateFormat: 'YYYY-MM-DD', width: 100 },
        { title: '현장명', type: 'text', width: 120 },
        { title: '담당팀', type: 'text', width: 100 },
        { title: '이름', type: 'text', width: 80 },
        { title: '팀명 (소속)', type: 'text', width: 100 },
        { title: '공수', type: 'numeric', numericFormat: { pattern: '0.0' }, width: 60 },
        { title: '작업내용', type: 'text', width: 200 },
        { title: '구분 (월급제/일급제)', type: 'text', width: 100 },
    ];

    const handleChange = (changes: any, source: string) => {
        if (!hotRef.current) return;

        // Timeout to ensure data is updated
        setTimeout(() => {
            const instance = hotRef.current?.hotInstance;
            if (instance) {
                const rawData = instance.getData();

                // Transform to Object Array for parent parsing
                const structuredData = rawData.map((row: any[]) => {
                    // Skip completely empty rows
                    if (row.every(cell => !cell)) return null;

                    return {
                        date: row[0],
                        siteName: row[1],
                        responsibleTeamName: row[2],
                        name: row[3],
                        teamName: row[4],
                        manDay: row[5],
                        workContent: row[6],
                        payType: row[7]
                    };
                }).filter(Boolean); // Remove nulls

                onChange(structuredData);
            }
        }, 100);
    };

    // Force render on mount to fix layout issues in Flex/Grid
    useEffect(() => {
        const timer = setTimeout(() => {
            if (hotRef.current?.hotInstance) {
                hotRef.current.hotInstance.render();
            }
        }, 100);
        return () => clearTimeout(timer);
    }, []);

    return (
        <div className="w-full h-full flex flex-col relative z-0">
            <div className="mb-2 p-2 bg-indigo-50 border border-indigo-100 rounded text-xs text-indigo-700 font-bold whitespace-nowrap overflow-x-auto shrink-0">
                <span className="mr-2">📝 입력 순서:</span>
                날짜 ➔ 현장명 ➔ 담당팀 ➔ 이름 ➔ 팀명 ➔ 공수 ➔ 작업내용 ➔ 구분
            </div>
            {/* Wrapper with relative positioning and z-index to ensure clickability */}
            <div className="flex-1 overflow-hidden border border-gray-300 rounded-lg relative z-10 bg-white">
                <HotTable
                    ref={hotRef}
                    data={hotData}
                    colHeaders={columns.map(c => c.title)}
                    columns={columns}
                    rowHeaders={true}
                    width="100%"
                    height="100%" // Fill container
                    licenseKey="non-commercial-and-evaluation"
                    afterChange={handleChange}
                    contextMenu={true}
                    minSpareRows={5}
                    manualColumnResize={true}
                    enterMoves={{ row: 1, col: 0 }} // Enter moves down
                    tabMoves={{ row: 0, col: 1 }}   // Tab moves right
                    // Ensure events are captured
                    outsideClickDeselects={false}
                />

                {/* Force Styles for Handsontable */}
                <style>{`
                    .handsontable .wtHolder {
                        height: 100% !important;
                        pointer-events: auto !important;
                    }
                    .handsontable td {
                        cursor: text;
                    }
                    /* Ensure headers are visible */
                    .handsontable th {
                        z-index: 10;
                    }
                `}</style>
            </div>
        </div>
    );
};

export default SmartExcelGrid;

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { dailyReportService } from '../../services/dailyReportService';
import type { DailyReport, DailyReportWorker } from '../../services/dailyReportService';
import { manpowerService } from '../../services/manpowerService';
import type { Worker } from '../../services/manpowerService';
import { siteService } from '../../services/siteService';
import type { Site } from '../../services/siteService';
import { teamService } from '../../services/teamService';
import type { Team } from '../../services/teamService';
import { normalizeTypedDateInput, sanitizeTypedDateInput } from '../../utils/typedDateInput';

interface Filters {
    startDate: string;
    endDate: string;
    teamName: string;
    workerName: string;
    siteName: string;
    type: string;
    category: string;
    includeSupportNote: boolean;
}

interface ReportRow {
    date: string;
    siteId: string;
    siteName: string;
    siteCode: string;
    workerId: string;
    workerName: string;
    manDay: number;
    teamId: string;
    workTeamName: string;
    teamCategory: string;
    responsibleTeamName: string;
    salaryModel: string;
    type: string;
    note: string;
}

const normalizeText = (value: string): string => value.replace(/\s+/g, '').trim();

const isSupportNote = (note: string): boolean => normalizeText(note).includes('지원');

const toYyyyMmDd = (date: Date): string => {
    const yyyy = date.getFullYear();
    const mm = String(date.getMonth() + 1).padStart(2, '0');
    const dd = String(date.getDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
};

const TeamPersonnelStatusReportPage: React.FC = () => {
    const today = useMemo(() => toYyyyMmDd(new Date()), []);

    const initialFilters = useMemo<Filters>(() => ({
        startDate: today,
        endDate: today,
        teamName: '',
        workerName: '',
        siteName: '',
        type: '',
        category: '',
        includeSupportNote: true
    }), [today]);

    const [filters, setFilters] = useState<Filters>(initialFilters);

    const [rows, setRows] = useState<ReportRow[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [errorMessage, setErrorMessage] = useState<string>('');

    const [masterData, setMasterData] = useState<{ teams: Team[]; sites: Site[]; workers: Worker[] }>({
        teams: [],
        sites: [],
        workers: []
    });

    const masterDataRef = useRef<{ teams: Team[]; sites: Site[]; workers: Worker[] } | null>(null);

    const deriveSalaryModel = useCallback((reportWorker: DailyReportWorker, workerInfo: Worker | undefined): string => {
        if (typeof reportWorker.salaryModel === 'string' && reportWorker.salaryModel.trim().length > 0) return reportWorker.salaryModel;
        if (typeof reportWorker.payType === 'string' && reportWorker.payType.trim().length > 0) return reportWorker.payType;

        if (workerInfo) {
            if (workerInfo.teamType === '지원팀') return '지원팀';
            if (workerInfo.teamType === '용역팀') return '용역팀';
            if (typeof workerInfo.salaryModel === 'string' && workerInfo.salaryModel.trim().length > 0) return workerInfo.salaryModel;
            if (typeof workerInfo.payType === 'string' && workerInfo.payType.trim().length > 0) return workerInfo.payType;
        }

        return '일급제';
    }, []);

    const ensureMasterData = useCallback(async () => {
        if (masterDataRef.current) return masterDataRef.current;

        const [teams, sites, workers] = await Promise.all([
            teamService.getTeams(),
            siteService.getSites(),
            manpowerService.getWorkers()
        ]);

        const next = { teams, sites, workers };
        masterDataRef.current = next;
        setMasterData(next);
        return next;
    }, []);

    const fetchRows = useCallback(async (nextFilters: Filters) => {
        const start = nextFilters.startDate;
        const end = nextFilters.endDate;
        if (start.trim().length === 0 || end.trim().length === 0) {
            setErrorMessage('기간(시작/종료)을 입력해주세요.');
            setRows([]);
            return;
        }
        if (start > end) {
            setErrorMessage('검색시작일이 검색종료일보다 클 수 없습니다.');
            setRows([]);
            return;
        }

        setIsLoading(true);
        setErrorMessage('');

        try {
            const [reports, { teams, sites, workers }] = await Promise.all([
                dailyReportService.getReportsByRange(start, end),
                ensureMasterData()
            ]);

            const teamById = new Map<string, Team>();
            teams.forEach(team => {
                if (team.id) teamById.set(team.id, team);
            });

            const siteById = new Map<string, Site>();
            sites.forEach(site => {
                if (site.id) siteById.set(site.id, site);
            });

            const workerById = new Map<string, Worker>();
            workers.forEach(worker => {
                if (worker.id) workerById.set(worker.id, worker);
            });

            const baseRows: ReportRow[] = reports.flatMap((report: DailyReport) => {
                const site = siteById.get(report.siteId);
                const team = teamById.get(report.teamId);

                const teamCategory = typeof team?.type === 'string' ? team.type : '';
                const derivedType = typeof team?.role === 'string' && team.role.trim().length > 0
                    ? team.role
                    : typeof team?.type === 'string'
                        ? team.type
                        : '';

                return report.workers.map((reportWorker: DailyReportWorker) => {
                    const workerInfo = workerById.get(reportWorker.workerId);
                    const salaryModel = deriveSalaryModel(reportWorker, workerInfo);
                    const note = reportWorker.workContent || '';

                    return {
                        date: report.date,
                        siteId: report.siteId,
                        siteName: report.siteName || site?.name || '',
                        siteCode: site?.code || '',
                        workerId: reportWorker.workerId,
                        workerName: reportWorker.name,
                        manDay: reportWorker.manDay,
                        teamId: report.teamId,
                        workTeamName: report.teamName || team?.name || '',
                        teamCategory,
                        responsibleTeamName: report.responsibleTeamName || site?.responsibleTeamName || '',
                        salaryModel,
                        type: reportWorker.role || derivedType,
                        note
                    };
                });
            });

            const teamNameFilter = normalizeText(nextFilters.teamName);
            const workerNameFilter = normalizeText(nextFilters.workerName);
            const siteNameFilter = normalizeText(nextFilters.siteName);
            const typeFilter = normalizeText(nextFilters.type);

            const filtered = baseRows
                .filter(row => {
                    if (teamNameFilter.length > 0) {
                        const a = normalizeText(row.workTeamName);
                        const b = normalizeText(row.teamCategory);
                        if (!a.includes(teamNameFilter) && !b.includes(teamNameFilter)) return false;
                    }

                    if (workerNameFilter.length > 0) {
                        if (!normalizeText(row.workerName).includes(workerNameFilter)) return false;
                    }

                    if (siteNameFilter.length > 0) {
                        const a = normalizeText(row.siteName);
                        if (!a.includes(siteNameFilter)) return false;
                    }

                    if (nextFilters.category.trim().length > 0) {
                        if (row.salaryModel !== nextFilters.category) return false;
                    }

                    if (typeFilter.length > 0) {
                        const a = normalizeText(row.type);
                        if (!a.includes(typeFilter)) return false;
                    }

                    if (!nextFilters.includeSupportNote) {
                        if (isSupportNote(row.note)) return false;
                    }

                    return true;
                })
                .sort((a, b) => {
                    const dateCompare = a.date.localeCompare(b.date);
                    if (dateCompare !== 0) return dateCompare;

                    const siteCompare = a.siteName.localeCompare(b.siteName, 'ko');
                    if (siteCompare !== 0) return siteCompare;

                    const teamCompare = a.workTeamName.localeCompare(b.workTeamName, 'ko');
                    if (teamCompare !== 0) return teamCompare;

                    return a.workerName.localeCompare(b.workerName, 'ko');
                });

            setRows(filtered);
        } catch (error) {
            console.error(error);
            setErrorMessage('데이터 조회 중 오류가 발생했습니다.');
            setRows([]);
        } finally {
            setIsLoading(false);
        }
    }, [deriveSalaryModel, ensureMasterData]);

    const totalManDay = useMemo(() => rows.reduce((sum, row) => sum + row.manDay, 0), [rows]);

    useEffect(() => {
        fetchRows(initialFilters).catch(e => console.error(e));
    }, [fetchRows, initialFilters]);

    return (
        <div className="p-6 md:p-8 max-w-[1800px] mx-auto">
            <div className="flex flex-col gap-2 md:flex-row md:items-end md:justify-between">
                <div>
                    <h1 className="text-2xl md:text-3xl font-black text-slate-800">팀별/인원별 현황 조회</h1>
                    <div className="mt-2 text-sm text-slate-500">
                        구글시트 리포트(원장 기반) 기능을 웹으로 이식하는 개발중 페이지입니다.
                    </div>
                </div>
                <div className="text-xs text-slate-500">
                    Route: <span className="font-mono">/reports/team-personnel-status</span>
                </div>
            </div>

            <div className="mt-6 bg-white border border-slate-200 rounded-2xl shadow-sm p-4">
                <div className="grid grid-cols-1 md:grid-cols-6 gap-3">
                    <label className="flex flex-col gap-1">
                        <span className="text-xs font-bold text-slate-600">검색시작일</span>
                        <input
                            type="text"
                            inputMode="numeric"
                            value={filters.startDate}
                            onChange={(e) => setFilters(prev => ({ ...prev, startDate: sanitizeTypedDateInput(e.target.value) }))}
                            onBlur={() => setFilters(prev => ({
                                ...prev,
                                startDate: normalizeTypedDateInput(prev.startDate) ?? prev.startDate,
                            }))}
                            onKeyDown={(e) => {
                                if (e.key === 'Enter') {
                                    e.currentTarget.blur();
                                }
                            }}
                            placeholder="YYYY-MM-DD"
                            className="border border-slate-200 rounded px-3 py-2 text-sm"
                        />
                    </label>

                    <label className="flex flex-col gap-1">
                        <span className="text-xs font-bold text-slate-600">검색종료일</span>
                        <input
                            type="text"
                            inputMode="numeric"
                            value={filters.endDate}
                            onChange={(e) => setFilters(prev => ({ ...prev, endDate: sanitizeTypedDateInput(e.target.value) }))}
                            onBlur={() => setFilters(prev => ({
                                ...prev,
                                endDate: normalizeTypedDateInput(prev.endDate) ?? prev.endDate,
                            }))}
                            onKeyDown={(e) => {
                                if (e.key === 'Enter') {
                                    e.currentTarget.blur();
                                }
                            }}
                            placeholder="YYYY-MM-DD"
                            className="border border-slate-200 rounded px-3 py-2 text-sm"
                        />
                    </label>

                    <label className="flex flex-col gap-1">
                        <span className="text-xs font-bold text-slate-600">팀명(팀구분)</span>
                        <input
                            value={filters.teamName}
                            onChange={(e) => setFilters(prev => ({ ...prev, teamName: e.target.value }))}
                            placeholder="예: 이재욱팀"
                            className="border border-slate-200 rounded px-3 py-2 text-sm"
                        />
                    </label>

                    <label className="flex flex-col gap-1">
                        <span className="text-xs font-bold text-slate-600">이름</span>
                        <input
                            value={filters.workerName}
                            onChange={(e) => setFilters(prev => ({ ...prev, workerName: e.target.value }))}
                            placeholder="예: 김해용"
                            className="border border-slate-200 rounded px-3 py-2 text-sm"
                        />
                    </label>

                    <label className="flex flex-col gap-1">
                        <span className="text-xs font-bold text-slate-600">현장명</span>
                        <input
                            value={filters.siteName}
                            onChange={(e) => setFilters(prev => ({ ...prev, siteName: e.target.value }))}
                            placeholder="예: 여의도"
                            className="border border-slate-200 rounded px-3 py-2 text-sm"
                        />
                    </label>

                    <label className="flex flex-col gap-1">
                        <span className="text-xs font-bold text-slate-600">구분</span>
                        <select
                            value={filters.category}
                            onChange={(e) => setFilters(prev => ({ ...prev, category: e.target.value }))}
                            className="border border-slate-200 rounded px-3 py-2 text-sm bg-white"
                        >
                            <option value="">전체</option>
                            <option value="월급제">월급제</option>
                            <option value="일급제">일급제</option>
                            <option value="지원팀">지원팀</option>
                        </select>
                    </label>

                    <label className="flex flex-col gap-1">
                        <span className="text-xs font-bold text-slate-600">TYPE</span>
                        <input
                            value={filters.type}
                            onChange={(e) => setFilters(prev => ({ ...prev, type: e.target.value }))}
                            placeholder="예: A"
                            className="border border-slate-200 rounded px-3 py-2 text-sm"
                        />
                    </label>

                    <label className="flex items-center gap-2 mt-6">
                        <input
                            type="checkbox"
                            checked={filters.includeSupportNote}
                            onChange={(e) => setFilters(prev => ({ ...prev, includeSupportNote: e.target.checked }))}
                            className="w-4 h-4"
                        />
                        <span className="text-sm text-slate-700">비고=지원 포함</span>
                    </label>

                    <div className="md:col-span-4 flex items-center justify-end gap-2 mt-4 md:mt-6">
                        <button
                            type="button"
                            onClick={() => {
                                setFilters(prev => ({
                                    ...prev,
                                    ...initialFilters
                                }));
                                setRows([]);
                                setErrorMessage('');
                            }}
                            className="px-4 py-2 rounded-lg border border-slate-200 text-slate-700 bg-white hover:bg-slate-50 text-sm font-bold"
                        >
                            초기화
                        </button>
                        <button
                            type="button"
                            onClick={() => {
                                const nextFilters = {
                                    ...filters,
                                    startDate: normalizeTypedDateInput(filters.startDate) ?? filters.startDate,
                                    endDate: normalizeTypedDateInput(filters.endDate) ?? filters.endDate,
                                };
                                setFilters(nextFilters);
                                fetchRows(nextFilters).catch(e => console.error(e));
                            }}
                            className="px-4 py-2 rounded-lg bg-indigo-600 text-white hover:bg-indigo-700 text-sm font-bold"
                        >
                            조회
                        </button>
                    </div>
                </div>
            </div>

            <div className="mt-6 bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
                <div className="p-4 border-b border-slate-200 flex items-center justify-between">
                    <div className="font-bold text-slate-700">결과</div>
                    <div className="text-sm text-slate-500">
                        총공수: <span className="font-bold">{totalManDay.toFixed(1)}</span>
                    </div>
                </div>

                <div className="overflow-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="text-xs text-slate-500 uppercase bg-slate-50 sticky top-0 z-10">
                            <tr>
                                <th className="px-4 py-3 font-bold text-slate-600">날짜</th>
                                <th className="px-4 py-3 font-bold text-slate-600">현장명</th>
                                <th className="px-4 py-3 font-bold text-slate-600">이름</th>
                                <th className="px-4 py-3 font-bold text-slate-600 text-right">공수</th>
                                <th className="px-4 py-3 font-bold text-slate-600">팀구분</th>
                                <th className="px-4 py-3 font-bold text-slate-600">현장소속팀</th>
                                <th className="px-4 py-3 font-bold text-slate-600">현장번호</th>
                                <th className="px-4 py-3 font-bold text-slate-600">구분</th>
                                <th className="px-4 py-3 font-bold text-slate-600">TYPE</th>
                                <th className="px-4 py-3 font-bold text-slate-600">비고</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-200">
                            {errorMessage.trim().length > 0 ? (
                                <tr>
                                    <td colSpan={10} className="px-4 py-6 text-center text-rose-600">
                                        {errorMessage}
                                    </td>
                                </tr>
                            ) : isLoading ? (
                                <tr>
                                    <td colSpan={10} className="px-4 py-6 text-center text-slate-500">
                                        로딩 중...
                                    </td>
                                </tr>
                            ) : rows.length === 0 ? (
                                <tr>
                                    <td colSpan={10} className="px-4 py-6 text-center text-slate-500">
                                        조회된 데이터가 없습니다.
                                    </td>
                                </tr>
                            ) : (
                                rows.map(row => (
                                    <tr key={`${row.date}-${row.siteId}-${row.teamId}-${row.workerId}`} className="hover:bg-slate-50">
                                        <td className="px-4 py-3 font-mono text-xs text-slate-600">{row.date}</td>
                                        <td className="px-4 py-3 text-slate-800">{row.siteName}</td>
                                        <td className="px-4 py-3 text-slate-800 font-bold">{row.workerName}</td>
                                        <td className="px-4 py-3 text-right font-mono text-slate-800">{row.manDay.toFixed(1)}</td>
                                        <td className="px-4 py-3 text-slate-700">{row.teamCategory || '-'}</td>
                                        <td className="px-4 py-3 text-slate-700">{row.responsibleTeamName || '-'}</td>
                                        <td className="px-4 py-3 font-mono text-xs text-slate-600">{row.siteCode || '-'}</td>
                                        <td className="px-4 py-3 text-slate-700">{row.salaryModel || '-'}</td>
                                        <td className="px-4 py-3 text-slate-700">{row.type || '-'}</td>
                                        <td className="px-4 py-3 text-slate-600">{row.note || '-'}</td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default TeamPersonnelStatusReportPage;

import React, { useMemo } from 'react';
import { AnalyticsResult } from '../../../services/geminiAnalyticsService';
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
    LineChart, Line, PieChart, Pie, Cell, AreaChart, Area
} from 'recharts';

interface AiResultChartsProps {
    result: AnalyticsResult | null;
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

export const AiResultCharts: React.FC<AiResultChartsProps> = ({ result }) => {
    const analysisType = result?.query?.analysisType;

    // 1. 일별 추이 (Line Chart)
    const dailyChart = useMemo(() => {
        if (!result || !result.success) return null;
        if (analysisType !== 'daily_summary' && analysisType !== 'comparison') return null;
        if (!result.dailyAgg || result.dailyAgg.length === 0) return null;

        const data = result.dailyAgg.map(day => ({
            date: day.date.substring(5), // MD only
            totalManDay: day.totalManDay,
            totalCost: day.totalAmount / 10000, // 만원 단위
        }));

        return (
            <div className="h-64 w-full bg-slate-900/30 rounded-lg p-4 mb-4 border border-slate-700/30">
                <h4 className="text-sm font-semibold text-slate-300 mb-2">일별 공수 추이</h4>
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={data}>
                        <defs>
                            <linearGradient id="colorManDay" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.8} />
                                <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                        <XAxis dataKey="date" stroke="#94a3b8" fontSize={12} />
                        <YAxis stroke="#94a3b8" fontSize={12} />
                        <Tooltip
                            contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155' }}
                            itemStyle={{ color: '#e2e8f0' }}
                            formatter={(val: number | string | undefined) => [typeof val === 'number' ? val.toFixed(1) : (val ?? ''), '공수']}
                        />
                        <Area type="monotone" dataKey="totalManDay" stroke="#3b82f6" fillOpacity={1} fill="url(#colorManDay)" />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        );
    }, [result, analysisType]);

    // 2. 팀별/현장별 비교 (Bar Chart)
    const categoryChart = useMemo(() => {
        if (!result || !result.success) return null;
        // team_summary, site_summary, general 모두 팀 차트 우선
        if (['team_summary', 'site_summary', 'general'].includes(analysisType as string) || !analysisType) {
            let data: any[] = [];
            let key = '';
            let label = '';

            if (result.teamAgg && result.teamAgg.length > 0) {
                // 상위 10개만
                data = result.teamAgg.slice(0, 10).map(t => ({
                    name: t.teamName,
                    value: t.totalManDay
                }));
                key = 'team';
                label = '팀별 공수 Top 10';
            } else if (result.siteAgg && result.siteAgg.length > 0) {
                data = result.siteAgg.slice(0, 10).map(s => ({
                    name: s.siteName,
                    value: s.totalManDay
                }));
                key = 'site';
                label = '현장별 공수 Top 10';
            }

            if (data.length === 0) return null;

            return (
                <div className="h-64 w-full bg-slate-900/30 rounded-lg p-4 mb-4 border border-slate-700/30">
                    <h4 className="text-sm font-semibold text-slate-300 mb-2">{label}</h4>
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={data} layout="vertical" margin={{ left: 40 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke="#334155" horizontal={false} />
                            <XAxis type="number" stroke="#94a3b8" fontSize={12} />
                            <YAxis dataKey="name" type="category" stroke="#94a3b8" fontSize={12} width={80} />
                            <Tooltip
                                cursor={{ fill: '#334155', opacity: 0.2 }}
                                contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155' }}
                                itemStyle={{ color: '#e2e8f0' }}
                            />
                            <Bar dataKey="value" fill="#10b981" radius={[0, 4, 4, 0]} barSize={20} />
                        </BarChart>
                    </ResponsiveContainer>
                </div>
            );
        }
        return null;
    }, [result, analysisType]);

    // 3. 임금 모델 비율 (Pie Chart) -- salary_model or general
    const pieChart = useMemo(() => {
        if (!result || !result.success) return null;
        if (!result.salaryModelAgg || result.salaryModelAgg.length === 0) return null;

        const data = result.salaryModelAgg.map(m => ({
            name: m.salaryModel,
            value: m.totalManDay
        }));

        return (
            <div className="h-64 w-full bg-slate-900/30 rounded-lg p-4 mb-4 border border-slate-700/30">
                <h4 className="text-sm font-semibold text-slate-300 mb-2">고용 형태 비율</h4>
                <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Pie
                            data={data}
                            cx="50%"
                            cy="50%"
                            innerRadius={60}
                            outerRadius={80}
                            paddingAngle={5}
                            dataKey="value"
                        >
                            {data.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                            ))}
                        </Pie>
                        <Tooltip
                            contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155' }}
                            itemStyle={{ color: '#e2e8f0' }}
                        />
                        <Legend />
                    </PieChart>
                </ResponsiveContainer>
            </div>
        );
    }, [result]);

    if (!result || !result.success) return null;

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {dailyChart}
            {categoryChart}
            {pieChart}
        </div>
    );
};

import React, { useState } from 'react';
import { DailyReport, DailyReportWorker } from '../../../services/dailyReportService';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faBuilding, faUsers, faUser, faTrash, faComment, faUserShield, faUserGear, faCoins, faClock
} from '@fortawesome/free-solid-svg-icons';
import Swal from 'sweetalert2';

interface DailyReportCardProps {
    report: DailyReport;
    onUpdateWorker: (reportId: string, workerId: string, field: keyof DailyReportWorker, value: any) => Promise<void>;
    onDeleteWorker: (reportId: string, workerId: string, workerName: string) => Promise<void>;
    onUpdateReport?: (reportId: string, field: keyof DailyReport, value: any) => Promise<void>; // Optional for now
}

const DailyReportCard: React.FC<DailyReportCardProps> = ({
    report,
    onUpdateWorker,
    onDeleteWorker,
    onUpdateReport
}) => {
    const [editingCell, setEditingCell] = useState<string | null>(null);

    const getRoleIcon = (role?: string) => {
        if (!role) return faUser;
        if (role.includes('사장') || role.includes('대표')) return faUserShield;
        if (role.includes('팀장') || role.includes('반장')) return faUserGear;
        return faUser;
    };

    const handleInlineSave = async (workerId: string, field: keyof DailyReportWorker, value: any) => {
        if (!report.id) return;
        try {
            await onUpdateWorker(report.id, workerId, field, value);
            setEditingCell(null);
        } catch (error) {
            console.error("Failed to update worker", error);
            Swal.fire('Error', '수정 중 오류가 발생했습니다.', 'error');
        }
    };

    return (
        <div className="bg-white border border-slate-300 rounded-lg overflow-hidden shadow-sm flex flex-col w-full hover:shadow-md transition-shadow">
            {/* Header */}
            <div className="bg-[#4A192C] text-white px-3 py-2 flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <div className="flex items-center gap-2" title="현장">
                        <FontAwesomeIcon icon={faBuilding} className="text-white/70 text-xs" />
                        <span className="font-bold text-sm tracking-tight">{report.siteName}</span>
                    </div>
                    <div className="w-px h-3 bg-white/30"></div>
                    <div className="flex items-center gap-2" title="작업팀">
                        <FontAwesomeIcon icon={faUsers} className="text-white/70 text-xs" />
                        <span className="font-bold text-sm tracking-tight">{report.teamName}</span>
                    </div>
                </div>
                <div className="flex items-center gap-3">
                    <span className="bg-white/20 px-2 py-0.5 rounded text-xs font-bold" title="총 공수">
                        {report.totalManDay.toFixed(1)}공수
                    </span>
                </div>
            </div>

            {/* Site Metadata / Partners */}
            {(report.companyName || report.constructorCompanyName || report.partnerName) && (
                <div className="bg-[#5d253b] px-3 py-1.5 flex flex-wrap gap-x-4 gap-y-1 text-[11px] text-white/90 border-t border-white/10">
                    {report.companyName && (
                        <div className="flex items-center gap-1.5 opacity-80">
                            <span className="font-light">발주:</span>
                            <span className="font-medium">{report.companyName}</span>
                        </div>
                    )}
                    {report.constructorCompanyName && (
                        <div className="flex items-center gap-1.5 opacity-80">
                            <span className="font-light">시공:</span>
                            <span className="font-medium">{report.constructorCompanyName}</span>
                        </div>
                    )}
                    {report.partnerName && (
                        <div className="flex items-center gap-1.5 opacity-80">
                            <span className="font-light">협력:</span>
                            <span className="font-medium">{report.partnerName}</span>
                        </div>
                    )}
                </div>
            )}

            {/* Workers Table */}
            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse text-sm">
                    <thead className="bg-slate-50 text-xs text-slate-500 font-bold uppercase">
                        <tr>
                            <th className="px-3 py-2 border-b w-24">이름</th>
                            <th className="px-3 py-2 border-b w-20 text-center">공수</th>
                            <th className="px-3 py-2 border-b w-24 text-right">단가</th>
                            <th className="px-3 py-2 border-b w-24">급여구분</th>
                            <th className="px-3 py-2 border-b">작업내용</th>
                            <th className="px-3 py-2 border-b w-8"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {report.workers.map((worker) => (
                            <tr key={worker.workerId} className="group hover:bg-slate-50 transition-colors">
                                {/* Name */}
                                <td className="px-3 py-2">
                                    <div className="flex items-center gap-2">
                                        <div className="w-6 h-6 rounded-full bg-slate-100 flex items-center justify-center shrink-0">
                                            <FontAwesomeIcon icon={getRoleIcon(worker.role)} className="text-slate-400 text-xs" />
                                        </div>
                                        <div>
                                            <div className="font-bold text-slate-700 leading-tight">{worker.name}</div>
                                            <div className="text-[10px] text-slate-400">{worker.role || '작업자'}</div>
                                        </div>
                                    </div>
                                </td>

                                {/* ManDay */}
                                <td className="px-3 py-2 text-center">
                                    {editingCell === `${worker.workerId}-manDay` ? (
                                        <input
                                            type="number"
                                            step="0.1"
                                            autoFocus
                                            defaultValue={worker.manDay}
                                            onBlur={(e) => handleInlineSave(worker.workerId, 'manDay', parseFloat(e.target.value) || 0)}
                                            onKeyDown={(e) => e.key === 'Enter' && e.currentTarget.blur()}
                                            className="w-16 px-1 py-1 text-center border-2 border-brand-500 rounded font-bold text-brand-600 outline-none bg-white"
                                        />
                                    ) : (
                                        <button
                                            onClick={() => setEditingCell(`${worker.workerId}-manDay`)}
                                            className="px-2 py-1 rounded hover:bg-white hover:shadow-sm hover:ring-1 hover:ring-slate-200 transition-all font-bold text-slate-600"
                                        >
                                            {worker.manDay.toFixed(1)}
                                        </button>
                                    )}
                                </td>

                                {/* Unit Price */}
                                <td className="px-3 py-2 text-right">
                                    {editingCell === `${worker.workerId}-unitPrice` ? (
                                        <input
                                            type="number"
                                            autoFocus
                                            defaultValue={worker.unitPrice || 0}
                                            onBlur={(e) => handleInlineSave(worker.workerId, 'unitPrice', parseInt(e.target.value) || 0)}
                                            onKeyDown={(e) => e.key === 'Enter' && e.currentTarget.blur()}
                                            className="w-20 px-1 py-1 text-right border-2 border-brand-500 rounded font-medium outline-none bg-white"
                                        />
                                    ) : (
                                        <button
                                            onClick={() => setEditingCell(`${worker.workerId}-unitPrice`)}
                                            className="px-2 py-1 rounded hover:bg-white hover:shadow-sm hover:ring-1 hover:ring-slate-200 transition-all font-mono text-slate-500"
                                        >
                                            {(worker.unitPrice || 0).toLocaleString()}
                                        </button>
                                    )}
                                </td>

                                {/* Salary Model */}
                                <td className="px-3 py-2">
                                    <select
                                        value={worker.salaryModel || '일급제'}
                                        onChange={(e) => handleInlineSave(worker.workerId, 'salaryModel', e.target.value)}
                                        className={`w-full px-2 py-1 text-xs border rounded cursor-pointer outline-none appearance-none font-medium text-center
                                            ${worker.salaryModel === '일급제' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                                                worker.salaryModel === '월급제' ? 'bg-purple-50 text-purple-700 border-purple-200' :
                                                    worker.salaryModel === '지원팀' ? 'bg-green-50 text-green-700 border-green-200' :
                                                        worker.salaryModel === '용역팀' ? 'bg-orange-50 text-orange-700 border-orange-200' :
                                                            'bg-slate-50 text-slate-700 border-slate-200'}`}
                                    >
                                        <option value="일급제">일급제</option>
                                        <option value="월급제">월급제</option>
                                        <option value="지원팀">지원팀</option>
                                        <option value="용역팀">용역팀</option>
                                    </select>
                                </td>

                                {/* Work Content */}
                                <td className="px-3 py-2">
                                    <input
                                        type="text"
                                        defaultValue={worker.workContent || ''}
                                        placeholder="작업 내용"
                                        onBlur={(e) => handleInlineSave(worker.workerId, 'workContent', e.target.value)}
                                        className="w-full px-2 py-1 text-xs bg-transparent border border-transparent rounded hover:bg-white hover:border-slate-200 focus:bg-white focus:border-brand-500 outline-none transition-all placeholder-slate-300"
                                    />
                                </td>

                                {/* Actions */}
                                <td className="px-3 py-2 text-right">
                                    <button
                                        onClick={() => report.id && onDeleteWorker(report.id, worker.workerId, worker.name)}
                                        className="text-red-400 hover:text-red-600 transition-colors p-1.5 opacity-80 hover:opacity-100"
                                        title="삭제"
                                    >
                                        <FontAwesomeIcon icon={faTrash} className="text-sm" />
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Footer / Report Level Info */}
            <div className="bg-slate-50 border-t border-slate-200 px-3 py-2 flex items-center justify-between">
                <div className="flex items-center gap-2 flex-1">
                    <FontAwesomeIcon icon={faComment} className="text-slate-400 text-xs" />
                    <input
                        type="text"
                        defaultValue={report.workContent || ''}
                        placeholder="이 장부의 전체 작업 내용 (선택사항)"
                        onBlur={(e) => report.id && onUpdateReport && onUpdateReport(report.id, 'workContent', e.target.value)}
                        className="flex-1 bg-transparent text-xs font-medium text-slate-700 placeholder-slate-400 outline-none border-b border-transparent focus:border-brand-500 transition-colors py-0.5"
                    />
                </div>
            </div>
        </div>
    );
};

export default DailyReportCard;

import React, { useState, useEffect, useRef } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCog, faUpload, faSpinner, faCheck, faImage, faFilm } from '@fortawesome/free-solid-svg-icons';
import { storage } from '../../config/firebase';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import Swal from 'sweetalert2';

const SystemConfigurationSection: React.FC = () => {
    const [loading, setLoading] = useState(false);
    const [logoUrl, setLogoUrl] = useState<string | null>(null);
    const [logoType, setLogoType] = useState<'image' | 'video' | null>(null);
    const [faviconUrl, setFaviconUrl] = useState<string | null>(null);

    const logoInputRef = useRef<HTMLInputElement>(null);
    const faviconInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        fetchCurrentSettings();
    }, []);

    const fetchCurrentSettings = async () => {
        try {
            // Fetch Logo
            try {
                // Try fetching as company_logo (no extension check, just get URL)
                // Note: Firebase Storage doesn't strictly enforce extensions for getDownloadURL if the path is generic, 
                // but usually we need to know the exact path. 
                // We'll try common paths or we'll list items (if we had list permission). 
                // For simplicity, we'll try to fetch 'settings/company_logo' directly. 
                // If the user uploads with metadata, we can determine type.
                const logoRef = ref(storage, 'settings/company_logo');
                const url = await getDownloadURL(logoRef);
                setLogoUrl(url);

                // Determine type roughly by extension or assume based on previous upload behavior?
                // Ideally we should store metadata. For now, we'll fetch metadata or just check if it plays as video.
                // Let's assume content-type verification happens on upload or via metadata fetch.
                // For UI, we'll default to Image unless we know better.
                // However, fetching metadata requires another call. 
                // Let's try to infer from the URL if possible, or just default to image validation.
                // Actually, let's try to see if it works as img or video on the UI side.
            } catch (e) {
                // Fallback to default or empty
                console.log("No custom logo found.");
            }

            // Fetch Favicon
            try {
                const faviconRef = ref(storage, 'settings/favicon');
                const url = await getDownloadURL(faviconRef);
                setFaviconUrl(url);
            } catch (e) {
                console.log("No custom favicon found.");
            }
        } catch (error) {
            console.error("Error fetching system settings:", error);
        }
    };

    const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        // Validate type
        if (!file.type.startsWith('image/') && !file.type.startsWith('video/')) {
            Swal.fire('Error', '이미지 또는 동영상 파일만 업로드 가능합니다.', 'error');
            return;
        }

        setLoading(true);
        try {
            const storageRef = ref(storage, 'settings/company_logo');

            // Upload with metadata so we know the content type later!
            const metadata = { contentType: file.type };
            await uploadBytes(storageRef, file, metadata);

            const url = await getDownloadURL(storageRef);
            setLogoUrl(url);
            setLogoType(file.type.startsWith('video/') ? 'video' : 'image');

            Swal.fire({
                icon: 'success',
                title: '로고 업데이트 완료',
                text: '새로운 로고가 적용되었습니다. (새로고침 후 확인)',
                timer: 1500
            });
        } catch (error) {
            console.error("Logo upload failed:", error);
            Swal.fire('Error', '로고 업로드 중 오류가 발생했습니다.', 'error');
        } finally {
            setLoading(false);
        }
    };

    const handleFaviconUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        // Validate type (ICO, PNG, SVG)
        const validTypes = ['image/x-icon', 'image/png', 'image/svg+xml'];
        if (!validTypes.includes(file.type)) {
            Swal.fire('Error', '파비콘은 .ico, .png, .svg 파일만 가능합니다.', 'error');
            return;
        }

        setLoading(true);
        try {
            const storageRef = ref(storage, 'settings/favicon');

            // Upload with metadata
            const metadata = { contentType: file.type };
            await uploadBytes(storageRef, file, metadata);

            const url = await getDownloadURL(storageRef);
            setFaviconUrl(url);

            // Dynamically update favicon
            const link = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
            if (link) {
                link.href = url;
            } else {
                const newLink = document.createElement('link');
                newLink.rel = 'icon';
                newLink.href = url;
                document.head.appendChild(newLink);
            }

            Swal.fire({
                icon: 'success',
                title: '파비콘 업데이트 완료',
                text: '브라우저 탭 아이콘이 변경되었습니다.',
                timer: 1500
            });
        } catch (error) {
            console.error("Favicon upload failed:", error);
            Swal.fire('Error', '파비콘 업로드 중 오류가 발생했습니다.', 'error');
        } finally {
            setLoading(false);
        }
    };

    return (
        <section className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="p-6 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
                <div>
                    <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                        <FontAwesomeIcon icon={faCog} className="text-slate-500" />
                        시스템 브랜딩 설정
                    </h3>
                    <p className="text-sm text-slate-500 mt-1">회사 로고와 브라우저 아이콘(Favicon)을 설정합니다.</p>
                </div>
            </div>

            <div className="p-6 space-y-8">
                {/* Logo Section */}
                <div className="flex flex-col md:flex-row gap-6 items-start">
                    <div className="w-full md:w-1/3">
                        <label className="block text-sm font-bold text-slate-700 mb-2">
                            회사 로고 (대시보드 메인)
                        </label>
                        <p className="text-xs text-slate-500 mb-4">
                            대시보드 상단에 표시될 로고입니다.<br />
                            동영상(MP4) 또는 이미지(PNG, JPG)를 지원합니다.
                        </p>
                        <div className="flex gap-2">
                            <button
                                onClick={() => logoInputRef.current?.click()}
                                disabled={loading}
                                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm font-medium transition-colors flex items-center gap-2"
                            >
                                <FontAwesomeIcon icon={loading ? faSpinner : faUpload} spin={loading} />
                                {loading ? '업로드 중...' : '로고 업로드'}
                            </button>
                            <input
                                type="file"
                                ref={logoInputRef}
                                onChange={handleLogoUpload}
                                className="hidden"
                                accept="image/*,video/mp4"
                            />
                        </div>
                    </div>

                    <div className="w-full md:w-2/3 bg-slate-100 rounded-lg p-6 flex flex-col items-center justify-center min-h-[200px] border-2 border-dashed border-slate-300">
                        {logoUrl ? (
                            <div className="relative group">
                                {logoType === 'video' || (logoUrl && logoUrl.includes('.mp4')) ? (
                                    <video src={logoUrl} autoPlay loop muted className="max-h-48 rounded-lg shadow-md" />
                                ) : (
                                    <img src={logoUrl} alt="Company Logo" className="max-h-48 rounded-lg shadow-md object-contain" />
                                )}
                                <div className="absolute top-2 right-2 bg-black/50 text-white text-xs px-2 py-1 rounded">
                                    현재 적용 중
                                </div>
                            </div>
                        ) : (
                            <div className="text-center text-slate-400">
                                <FontAwesomeIcon icon={faImage} className="text-4xl mb-2" />
                                <p>등록된 로고가 없습니다.</p>
                            </div>
                        )}
                    </div>
                </div>

                <div className="w-full h-px bg-slate-100 my-6"></div>

                {/* Favicon Section */}
                <div className="flex flex-col md:flex-row gap-6 items-start">
                    <div className="w-full md:w-1/3">
                        <label className="block text-sm font-bold text-slate-700 mb-2">
                            파비콘 (브라우저 탭 아이콘)
                        </label>
                        <p className="text-xs text-slate-500 mb-4">
                            브라우저 탭에 표시되는 작은 아이콘입니다.<br />
                            SVG(권장), PNG, ICO 형식을 지원합니다.
                        </p>
                        <button
                            onClick={() => faviconInputRef.current?.click()}
                            disabled={loading}
                            className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium transition-colors flex items-center gap-2"
                        >
                            <FontAwesomeIcon icon={loading ? faSpinner : faUpload} spin={loading} />
                            {loading ? '업로드 중...' : '파비콘 업로드'}
                        </button>
                        <input
                            type="file"
                            ref={faviconInputRef}
                            onChange={handleFaviconUpload}
                            className="hidden"
                            accept=".ico,.png,.svg"
                        />
                    </div>

                    <div className="w-full md:w-2/3 bg-slate-100 rounded-lg p-6 flex flex-col items-center justify-center min-h-[120px] border-2 border-dashed border-slate-300">
                        {faviconUrl ? (
                            <div className="flex items-center gap-4">
                                <div className="bg-white p-4 rounded-full shadow-sm">
                                    <img src={faviconUrl} alt="Favicon" className="w-8 h-8 object-contain" />
                                </div>
                                <span className="text-sm text-slate-600 font-medium">현재 적용된 파비콘</span>
                            </div>
                        ) : (
                            <div className="text-center text-slate-400">
                                <FontAwesomeIcon icon={faCog} className="text-3xl mb-2" />
                                <p>등록된 파비콘이 없습니다.</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </section>
    );
};

export default SystemConfigurationSection;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faRobot, faUsers, faBuilding, faUserGroup, faArrowLeft, faTrash, faCheckCircle, faExclamationCircle } from '@fortawesome/free-solid-svg-icons';
import { manpowerService, Worker } from '../../services/manpowerService';
import { siteService, Site } from '../../services/siteService';
import { teamService, Team } from '../../services/teamService';
import { companyService, Company } from '../../services/companyService';
import { dailyReportService, DailyReport, DailyReportWorker } from '../../services/dailyReportService';

// --- Interfaces ---
interface TestCompanyData {
    name: string;
    code: string;
    ceoName: string;
    businessNumber: string;
    type: '건설사' | '협력사';
}

interface TestWorkerData {
    name: string;
    idNumber: string;
    contact: string;
    bankName: string;
    accountNumber: string;
    accountHolder: string;
    address: string;
    role: string;
    unitPrice: number;
}

interface TestTeamData {
    name: string;
    leaderName: string;
    leaderId: string;
    companyId: string;
    companyName: string;
}

interface TestSiteData {
    name: string;
    responsibleTeamId: string;
    responsibleTeamName: string;
}

const TestSettingsPage: React.FC = () => {
    const navigate = useNavigate();

    // --- State ---
    const [companies, setCompanies] = useState<Company[]>([]);
    const [workers, setWorkers] = useState<Worker[]>([]);
    const [teams, setTeams] = useState<Team[]>([]);
    const [sites, setSites] = useState<Site[]>([]);

    const [testCompanies, setTestCompanies] = useState<TestCompanyData[]>([]);
    const [testWorkers, setTestWorkers] = useState<TestWorkerData[]>([]);
    const [testTeams, setTestTeams] = useState<TestTeamData[]>([]);
    const [testSites, setTestSites] = useState<TestSiteData[]>([]);
    const [testReports, setTestReports] = useState<DailyReport[]>([]);

    const [loading, setLoading] = useState(false);

    // Generation Counts
    const [counts, setCounts] = useState({
        company: 3,
        worker: 10,
        team: 3,
        site: 3,
        report: 30
    });

    // --- Fetch Data ---
    const fetchData = async () => {
        try {
            const [c, w, t, s] = await Promise.all([
                companyService.getCompanies(),
                manpowerService.getWorkers(),
                teamService.getTeams(),
                siteService.getSites()
            ]);
            setCompanies(c);
            setWorkers(w);
            setTeams(t);
            setSites(s);
        } catch (error) {
            console.error("Failed to fetch data:", error);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    // --- Generators ---

    // 1. Company Generator
    const generateTestCompanies = () => {
        setLoading(true);
        const newCompanies: TestCompanyData[] = [];
        const types: ('건설사' | '협력사')[] = ['건설사', '협력사'];

        for (let i = 0; i < counts.company; i++) {
            const type = types[Math.floor(Math.random() * types.length)];
            const name = type === '건설사'
                ? `(주)${['태양', '대한', '한국', '미래', '청연'][Math.floor(Math.random() * 5)]}건설`
                : `${['김', '이', '박', '최'][Math.floor(Math.random() * 4)]}반장 협력사`;

            newCompanies.push({
                name: `${name}_${Math.floor(Math.random() * 1000)}`,
                code: Math.random().toString(36).substr(2, 6).toUpperCase(),
                ceoName: `대표${i}`,
                businessNumber: `${Math.floor(Math.random() * 999)}-${Math.floor(Math.random() * 99)}-${Math.floor(Math.random() * 99999)}`,
                type
            });
        }
        setTestCompanies(newCompanies);
        setLoading(false);
    };

    const registerCompanies = async () => {
        if (testCompanies.length === 0) return;
        setLoading(true);
        try {
            for (const c of testCompanies) {
                await companyService.addCompany({
                    ...c,
                    address: '서울시 강남구',
                    phone: '02-1234-5678',
                    email: 'test@example.com'
                });
            }
            alert(`${testCompanies.length}개 회사 등록 완료`);
            setTestCompanies([]);
            fetchData();
        } catch (e) {
            console.error(e);
            alert('회사 등록 실패');
        } finally {
            setLoading(false);
        }
    };

    // 2. Worker Generator
    const generateTestWorkers = () => {
        setLoading(true);
        const newWorkers: TestWorkerData[] = [];
        const surnames = ['김', '이', '박', '최', '정'];
        const names = ['민수', '철수', '영희', '지훈', '서준'];

        for (let i = 0; i < counts.worker; i++) {
            newWorkers.push({
                name: `${surnames[Math.floor(Math.random() * surnames.length)]}${names[Math.floor(Math.random() * names.length)]}`,
                idNumber: '900101-1234567',
                contact: `010-${Math.floor(Math.random() * 9000) + 1000}-${Math.floor(Math.random() * 9000) + 1000}`,
                bankName: '국민은행',
                accountNumber: '123-456-789012',
                accountHolder: '예금주',
                address: '서울시',
                role: '조공',
                unitPrice: 150000
            });
        }
        setTestWorkers(newWorkers);
        setLoading(false);
    };

    const registerWorkers = async () => {
        if (testWorkers.length === 0) return;
        setLoading(true);
        try {
            for (const w of testWorkers) {
                await manpowerService.addWorker({
                    ...w,
                    email: '',
                    teamType: '',
                    teamName: '',
                    status: 'active',
                    salaryModel: '일급'
                });
            }
            alert(`${testWorkers.length}명 작업자 등록 완료`);
            setTestWorkers([]);
            fetchData();
        } catch (e) {
            console.error(e);
            alert('작업자 등록 실패');
        } finally {
            setLoading(false);
        }
    };

    // 3. Team Generator (Links to Company & Worker)
    const generateTestTeams = () => {
        if (companies.length === 0 || workers.length === 0) {
            alert('회사와 작업자 데이터가 먼저 필요합니다.');
            return;
        }
        setLoading(true);
        const newTeams: TestTeamData[] = [];

        for (let i = 0; i < counts.team; i++) {
            const company = companies[Math.floor(Math.random() * companies.length)];
            const leader = workers[Math.floor(Math.random() * workers.length)];

            newTeams.push({
                name: `${leader.name}팀_${Math.floor(Math.random() * 100)}`,
                leaderName: leader.name,
                leaderId: leader.id!,
                companyId: company.id!,
                companyName: company.name
            });
        }
        setTestTeams(newTeams);
        setLoading(false);
    };

    const registerTeams = async () => {
        if (testTeams.length === 0) return;
        setLoading(true);
        try {
            for (const t of testTeams) {
                await teamService.addTeam({
                    ...t,
                    type: '협력사', // Using '협력사' as team type for consistency, though Team type is string
                    memberCount: 1
                });
            }
            alert(`${testTeams.length}개 팀 등록 완료`);
            setTestTeams([]);
            fetchData();
        } catch (e) {
            console.error(e);
            alert('팀 등록 실패');
        } finally {
            setLoading(false);
        }
    };

    // 4. Site Generator (Links to Team)
    const generateTestSites = () => {
        if (teams.length === 0) {
            alert('팀 데이터가 먼저 필요합니다.');
            return;
        }
        setLoading(true);
        const newSites: TestSiteData[] = [];
        const locations = ['서울', '경기', '인천', '부산'];

        for (let i = 0; i < counts.site; i++) {
            const team = teams[Math.floor(Math.random() * teams.length)];
            const loc = locations[Math.floor(Math.random() * locations.length)];

            newSites.push({
                name: `${loc} 현장_${Math.floor(Math.random() * 100)}`,
                responsibleTeamId: team.id!,
                responsibleTeamName: team.name
            });
        }
        setTestSites(newSites);
        setLoading(false);
    };

    const registerSites = async () => {
        if (testSites.length === 0) return;
        setLoading(true);
        try {
            for (const s of testSites) {
                await siteService.addSite({
                    ...s,
                    code: Math.random().toString(36).substr(2, 5).toUpperCase(),
                    address: '주소 미정',
                    status: 'active',
                    responsibleTeamId: s.responsibleTeamId,
                    responsibleTeamName: s.responsibleTeamName
                });
            }
            alert(`${testSites.length}개 현장 등록 완료`);
            setTestSites([]);
            fetchData();
        } catch (e) {
            console.error(e);
            alert('현장 등록 실패');
        } finally {
            setLoading(false);
        }
    };

    // 5. Daily Report Generator
    const generateTestReports = () => {
        if (sites.length === 0 || teams.length === 0 || workers.length === 0) {
            alert('현장, 팀, 작업자 데이터가 모두 필요합니다.');
            return;
        }
        setLoading(true);
        const newReports: DailyReport[] = [];

        const startDate = new Date('2025-09-01').getTime();
        const endDate = new Date().getTime();

        for (let i = 0; i < counts.report; i++) {
            const site = sites[Math.floor(Math.random() * sites.length)];
            // Find team assigned to this site or random
            const team = teams.find(t => t.id === site.responsibleTeamId) || teams[0];

            // Random Date between 2025-09-01 and Today
            const randomDate = new Date(startDate + Math.random() * (endDate - startDate));
            const dateStr = randomDate.toISOString().split('T')[0];

            // Random workers
            const reportWorkers: DailyReportWorker[] = [];
            const workerCount = Math.floor(Math.random() * 5) + 1;

            for (let j = 0; j < workerCount; j++) {
                const w = workers[Math.floor(Math.random() * workers.length)];
                reportWorkers.push({
                    workerId: w.id!,
                    name: w.name,
                    role: w.role || '작업자',
                    status: 'attendance',
                    manDay: 1,
                    workContent: '작업내용',
                    teamId: team.id!,
                    unitPrice: w.unitPrice || 150000,
                    salaryModel: w.teamType === '지원팀' ? '지원팀'
                        : w.teamType === '용역팀' ? '용역팀'
                            : w.salaryModel || '일급제'
                });
            }

            newReports.push({
                date: dateStr,
                siteId: site.id!,
                siteName: site.name,
                teamId: team.id!,
                teamName: team.name,
                responsibleTeamId: site.responsibleTeamId || '',
                responsibleTeamName: site.responsibleTeamName || '',
                writerId: 'test',
                workers: reportWorkers,
                totalManDay: workerCount
            });
        }
        setTestReports(newReports);
        setLoading(false);
    };

    const registerReports = async () => {
        if (testReports.length === 0) return;
        setLoading(true);
        try {
            await dailyReportService.addReportsBatch(testReports);
            alert(`${testReports.length}개 일보 등록 완료`);
            setTestReports([]);
        } catch (e) {
            console.error(e);
            alert('일보 등록 실패');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="p-8 max-w-6xl mx-auto bg-slate-50 min-h-screen font-['Pretendard']">
            <div className="flex items-center gap-4 mb-8">
                <button onClick={() => navigate(-1)} className="text-slate-500 hover:text-slate-800">
                    <FontAwesomeIcon icon={faArrowLeft} size="lg" />
                </button>
                <h1 className="text-2xl font-bold text-slate-800">테스트 데이터 생성기</h1>
            </div>

            <div className="bg-blue-50 border border-blue-200 rounded-lg p-6 mb-8 shadow-sm">
                <h3 className="text-blue-800 font-bold mb-3 flex items-center gap-2 text-lg">
                    <FontAwesomeIcon icon={faExclamationCircle} />
                    사용 가이드 (필독)
                </h3>
                <p className="text-blue-700 mb-4">
                    데이터 간의 연결 관계를 위해 반드시 <strong>아래 순서대로</strong> 진행해주세요.
                </p>
                <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
                    {[
                        { step: 1, title: '회사 데이터', desc: '시공팀/건설사 생성' },
                        { step: 2, title: '작업자 데이터', desc: '팀장 후보 생성' },
                        { step: 3, title: '팀 데이터', desc: '회사-팀장 연결' },
                        { step: 4, title: '현장 데이터', desc: '담당팀 연결' },
                        { step: 5, title: '일보 데이터', desc: '최종 테스트 데이터' },
                    ].map((item, idx) => (
                        <div key={idx} className="bg-white p-3 rounded border border-blue-100 flex flex-col items-center text-center">
                            <div className="w-6 h-6 rounded-full bg-blue-600 text-white flex items-center justify-center text-xs font-bold mb-2">
                                {item.step}
                            </div>
                            <div className="font-bold text-blue-900 text-sm">{item.title}</div>
                            <div className="text-xs text-blue-600 mt-1">{item.desc}</div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* 1. Company */}
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="text-lg font-bold flex items-center gap-2">
                            <span className="w-6 h-6 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center text-xs">1</span>
                            회사 데이터
                        </h2>
                        <span className="text-sm text-slate-500">현재: {companies.length}개</span>
                    </div>
                    <div className="flex gap-2 mb-4">
                        <input
                            type="number"
                            value={counts.company}
                            onChange={e => setCounts({ ...counts, company: +e.target.value })}
                            className="w-20 border rounded px-2"
                        />
                        <button onClick={generateTestCompanies} className="bg-slate-100 px-3 py-1 rounded hover:bg-slate-200">생성</button>
                        <button onClick={registerCompanies} disabled={testCompanies.length === 0} className="bg-blue-600 text-white px-3 py-1 rounded hover:bg-blue-700 disabled:opacity-50">등록</button>
                    </div>
                    {testCompanies.length > 0 && (
                        <div className="bg-slate-50 p-2 rounded text-xs max-h-32 overflow-y-auto">
                            {testCompanies.map((c, i) => <div key={i}>{c.name} ({c.type})</div>)}
                        </div>
                    )}
                </div>

                {/* 2. Worker */}
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="text-lg font-bold flex items-center gap-2">
                            <span className="w-6 h-6 rounded-full bg-green-100 text-green-600 flex items-center justify-center text-xs">2</span>
                            작업자 데이터
                        </h2>
                        <span className="text-sm text-slate-500">현재: {workers.length}명</span>
                    </div>
                    <div className="flex gap-2 mb-4">
                        <input
                            type="number"
                            value={counts.worker}
                            onChange={e => setCounts({ ...counts, worker: +e.target.value })}
                            className="w-20 border rounded px-2"
                        />
                        <button onClick={generateTestWorkers} className="bg-slate-100 px-3 py-1 rounded hover:bg-slate-200">생성</button>
                        <button onClick={registerWorkers} disabled={testWorkers.length === 0} className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700 disabled:opacity-50">등록</button>
                    </div>
                    {testWorkers.length > 0 && (
                        <div className="bg-slate-50 p-2 rounded text-xs max-h-32 overflow-y-auto">
                            {testWorkers.map((w, i) => <div key={i}>{w.name}</div>)}
                        </div>
                    )}
                </div>

                {/* 3. Team */}
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="text-lg font-bold flex items-center gap-2">
                            <span className="w-6 h-6 rounded-full bg-purple-100 text-purple-600 flex items-center justify-center text-xs">3</span>
                            팀 데이터
                        </h2>
                        <span className="text-sm text-slate-500">현재: {teams.length}개</span>
                    </div>
                    <p className="text-xs text-slate-400 mb-2">* 회사와 작업자(팀장)가 연결됩니다.</p>
                    <div className="flex gap-2 mb-4">
                        <input
                            type="number"
                            value={counts.team}
                            onChange={e => setCounts({ ...counts, team: +e.target.value })}
                            className="w-20 border rounded px-2"
                        />
                        <button onClick={generateTestTeams} className="bg-slate-100 px-3 py-1 rounded hover:bg-slate-200">생성</button>
                        <button onClick={registerTeams} disabled={testTeams.length === 0} className="bg-purple-600 text-white px-3 py-1 rounded hover:bg-purple-700 disabled:opacity-50">등록</button>
                    </div>
                    {testTeams.length > 0 && (
                        <div className="bg-slate-50 p-2 rounded text-xs max-h-32 overflow-y-auto">
                            {testTeams.map((t, i) => <div key={i}>{t.name} (팀장: {t.leaderName}, 회사: {t.companyName})</div>)}
                        </div>
                    )}
                </div>

                {/* 4. Site */}
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="text-lg font-bold flex items-center gap-2">
                            <span className="w-6 h-6 rounded-full bg-orange-100 text-orange-600 flex items-center justify-center text-xs">4</span>
                            현장 데이터
                        </h2>
                        <span className="text-sm text-slate-500">현재: {sites.length}개</span>
                    </div>
                    <p className="text-xs text-slate-400 mb-2">* 담당 팀이 연결됩니다.</p>
                    <div className="flex gap-2 mb-4">
                        <input
                            type="number"
                            value={counts.site}
                            onChange={e => setCounts({ ...counts, site: +e.target.value })}
                            className="w-20 border rounded px-2"
                        />
                        <button onClick={generateTestSites} className="bg-slate-100 px-3 py-1 rounded hover:bg-slate-200">생성</button>
                        <button onClick={registerSites} disabled={testSites.length === 0} className="bg-orange-600 text-white px-3 py-1 rounded hover:bg-orange-700 disabled:opacity-50">등록</button>
                    </div>
                    {testSites.length > 0 && (
                        <div className="bg-slate-50 p-2 rounded text-xs max-h-32 overflow-y-auto">
                            {testSites.map((s, i) => <div key={i}>{s.name} (담당: {s.responsibleTeamName})</div>)}
                        </div>
                    )}
                </div>

                {/* 5. Daily Report */}
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 md:col-span-2">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="text-lg font-bold flex items-center gap-2">
                            <span className="w-6 h-6 rounded-full bg-red-100 text-red-600 flex items-center justify-center text-xs">5</span>
                            일보 데이터 (테스트용)
                        </h2>
                        <span className="text-sm text-slate-500">생성 대기: {testReports.length}건</span>
                    </div>
                    <div className="flex gap-2 mb-4">
                        <input
                            type="number"
                            value={counts.report}
                            onChange={e => setCounts({ ...counts, report: +e.target.value })}
                            className="w-20 border rounded px-2"
                        />
                        <button onClick={generateTestReports} className="bg-slate-100 px-3 py-1 rounded hover:bg-slate-200">생성</button>
                        <button onClick={registerReports} disabled={testReports.length === 0} className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700 disabled:opacity-50">등록</button>
                    </div>
                    {testReports.length > 0 && (
                        <div className="bg-slate-50 p-2 rounded text-xs max-h-32 overflow-y-auto">
                            {testReports.map((r, i) => <div key={i}>{r.date} / {r.siteName} / {r.teamName} / {r.workers.length}명</div>)}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

