                        className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                        title="Refresh"
                    >
                        <FontAwesomeIcon icon={faSync} spin={isLoading} />
                    </button>
                    <div className="h-6 w-px bg-slate-200 mx-2"></div>
                    <input
                        type="file"
