                return false;
            }).sort((a: Team, b: Team) => (a.name || '').localeCompare(b.name || ''));

            setAccommodations(accommodationList);
            setAssignments(assignmentList);
            setBillingTargets(billingTargetList);
            setCurrentMonthLedgerRecords(ledgerList);
