            console.error("Failed to load accommodations", error);
        } finally {
            setLoading(false);
        }
    };

    // Build team info maps (color + icon)
    const teamInfoByIdMap = useMemo(() => {
        const map = new Map<string, { color: string; icon?: string; name: string }>();
        teams.forEach(t => {
