                                                                        const atc = assignTeamInfo?.color;

                                                                        return (
                                                                            <span key={assign.id}
                                                                                className="text-xs px-2 py-1 rounded-lg font-bold border flex items-center gap-1.5"
                                                                                style={atc ? {
