                <button onClick={loadData} className="px-4 py-2 bg-white border border-slate-300 rounded-lg text-slate-600 hover:bg-slate-50 transition-colors flex items-center gap-2">
                    <FontAwesomeIcon icon={faSync} /> 새로고침
