export default DataSyncStatusPage;

import React, { useEffect, useMemo, useState } from 'react';
import styled from 'styled-components';
import { format, startOfMonth } from 'date-fns';
import { fetchNtsTaxInvoicesRange } from '../../services/barobillService';
import { TransactionFilterBar } from './components/TransactionFilterBar';
import { TransactionSummaryCards } from './components/TransactionSummaryCards';
import { TransactionTable, TaxAffairsRecord } from './components/TransactionTable';
import Swal from 'sweetalert2';
import { useNavigate } from 'react-router-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faBook, faSave } from '@fortawesome/free-solid-svg-icons';
import { taxLedgerService } from '../../services/taxLedgerService';

// Styled Components
const PageContainer = styled.div`
    padding: 24px;
    height: 100%;
    display: flex;
    flex-direction: column;
    background-color: #f8f9fa;
    max-width: 1600px;
    margin: 0 auto;
    width: 100%;
`;

const PageHeader = styled.div`
    margin-bottom: 24px;
`;

const Title = styled.h1`
    font-size: 28px;
    font-weight: 800;
    color: #1e293b;
    margin-bottom: 8px;
    letter-spacing: -0.5px;
`;

const Subtitle = styled.p`
    font-size: 14px;
    color: #64748b;
    font-weight: 500;
`;

// Helpers
const asString = (v: unknown): string => (typeof v === 'string' ? v : v == null ? '' : String(v));
const asNumber = (v: unknown): number => {
    if (typeof v === 'number' && Number.isFinite(v)) return v;
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
};
const toIsoDate = (yyyymmdd: string): string => {
    const digits = yyyymmdd.replace(/\D/g, '');
    if (!/^\d{8}$/.test(digits)) return '';
    return `${digits.slice(0, 4)}-${digits.slice(4, 6)}-${digits.slice(6, 8)}`;
};
const toYyyyMmDdDigits = (value: string): string => value.replace(/\D/g, '').slice(0, 8);

const TaxAffairsPage: React.FC = () => {
    const navigate = useNavigate();
    // State
    // Default: This Month (1st to Today)
    const [startDate, setStartDate] = useState<string>(format(startOfMonth(new Date()), 'yyyy-MM-dd'));
    const [endDate, setEndDate] = useState<string>(format(new Date(), 'yyyy-MM-dd'));

    const [transactionType, setTransactionType] = useState<'전체' | '매출' | '매입'>('전체');
    const [searchQuery, setSearchQuery] = useState<string>('');
    const [records, setRecords] = useState<TaxAffairsRecord[]>([]);
    const [loading, setLoading] = useState<boolean>(false);
    const [selectedIds, setSelectedIds] = useState<string[]>([]);

    // Filter Logic
    const filteredRecords = useMemo(() => {
        const query = searchQuery.trim().toLowerCase();
        return records.filter(r => {
            if (transactionType !== '전체' && r.type !== transactionType) return false;

            if (query) {
                return (
                    r.partnerName.toLowerCase().includes(query) ||
                    r.description.toLowerCase().includes(query) ||
                    (r.invoiceNum && r.invoiceNum.toLowerCase().includes(query))
                );
            }
            return true;
        });
    }, [records, transactionType, searchQuery]);

    // Calculate Summary Split by Type
    const summary = useMemo(() => {
        const initial = {
            sales: { supply: 0, tax: 0, total: 0 },
            purchase: { supply: 0, tax: 0, total: 0 }
        };

        return filteredRecords.reduce((acc, curr) => {
            if (curr.type === '매출') {
                acc.sales.supply += curr.supplyAmount;
                acc.sales.tax += curr.taxAmount;
                acc.sales.total += curr.totalAmount;
            } else if (curr.type === '매입') {
                acc.purchase.supply += curr.supplyAmount;
                // Purchase amounts are stored negative in current logic? 
                // Let's check `mapToRecords`. 
                // Currently `mapToRecords` applies `sign`. 
                // If we want to display positive numbers in summary cards for "amount spent", we might want absolute values, 
                // BUT usually in accounting summary:
                // Sales = Positive, Purchase = Negative (or Positive Cost).
                // Let's look at `TransactionSummaryCards` labels: "총 매입가액". 
                // Usually users want to see "How much I bought" as a positive number.
                // However, `mapToRecords` makes them negative.
                // Let's accumulate RAW values (absolute) for the cards if they are negative.
                // Actually, let's keep the sign logic consistent with the grid.
                // If the grid shows negative for purchase, summary showing negative is mathematically correct, but visually awkward for "Total Purchase Amount".
                // I will use `Math.abs` for the purchase summary to display "Magnitude" of purchase.
                acc.purchase.supply += Math.abs(curr.supplyAmount);
                acc.purchase.tax += Math.abs(curr.taxAmount);
                acc.purchase.total += Math.abs(curr.totalAmount);
            }
            return acc;
        }, initial);
    }, [filteredRecords]);

    // Data Fetching
    const fetchData = async () => {
        const startDigits = toYyyyMmDdDigits(startDate);
        const endDigits = toYyyyMmDdDigits(endDate);

        if (startDigits.length !== 8 || endDigits.length !== 8) {
            Swal.fire('오류', '날짜 형식이 올바르지 않습니다.', 'error');
            return;
        }

        setLoading(true);
        setRecords([]);

        const typesToFetch: ('매출' | '매입')[] = transactionType === '전체' ? ['매출', '매입'] : [transactionType];

        try {
            const promises = typesToFetch.map(async (type) => {
                const res = await fetchNtsTaxInvoicesRange(startDigits, endDigits, type);
                return mapToRecords(res.data, type);
            });

            const results = await Promise.all(promises);
            const combined = results.flat().sort((a, b) => {
                // Sort by Date DESC, then ID
                return b.date.localeCompare(a.date) || b.id.localeCompare(a.id);
            });

            setRecords(combined);

            // Optional: Toast for success
            const count = combined.length;
            if (count > 0) {
                const Toast = Swal.mixin({
                    toast: true,
                    position: 'top-end',
                    showConfirmButton: false,
                    timer: 2000,
                    timerProgressBar: true,
                    didOpen: (toast) => {
                        toast.addEventListener('mouseenter', Swal.stopTimer)
                        toast.addEventListener('mouseleave', Swal.resumeTimer)
                    }
                });
                Toast.fire({
                    icon: 'success',
                    title: `총 ${count}건의 내역을 조회했습니다.`
                });
            } else {
                const Toast = Swal.mixin({
                    toast: true,
                    position: 'top-end',
                    showConfirmButton: false,
                    timer: 2000,
                    timerProgressBar: true,
                });
                Toast.fire({
                    icon: 'info',
                    title: `조회된 내역이 없습니다.`
                });
            }

        } catch (error: any) {
            console.error(error);
            Swal.fire('조회 실패', error.message || '데이터를 불러오는 중 오류가 발생했습니다.', 'error');
        } finally {
            setLoading(false);
        }
    };

    // Helper: Map API response to Frontend model
    const mapToRecords = (rows: Array<Record<string, unknown>>, type: '매출' | '매입'): TaxAffairsRecord[] => {
        const sign = type === '매입' ? -1 : 1;

        return rows.map((row) => {
            const baseDate =
                asString(row.__baseDate) ||
                asString(row.WriteDate) ||
                asString(row.IssueDT) ||
                asString(row.NTSSendDT);

            const taxInvoiceKey = asString(row.TaxInvoiceKey);
            const invoicerCorpName = asString(row.InvoicerCorpName);
            const invoiceeCorpName = asString(row.InvoiceeCorpName);

            // Note: NTS API field names usually PascalCase
            const supplyAmount = asNumber(row.AmountTotal) || asNumber(row.SupplyCostTotal);
            const taxAmount = asNumber(row.TaxTotal);
            let totalAmount = asNumber(row.TotalAmount);
            if (!totalAmount) totalAmount = supplyAmount + taxAmount;

            return {
                id: `nts-${taxInvoiceKey || Math.random().toString(36).slice(2)}`,
                date: toIsoDate(baseDate),
                type,
                partnerName: type === '매입' ? invoicerCorpName : invoiceeCorpName,
                description: asString(row.ItemName) || asString(row.Remark1) || '품목내용 없음',

                // Keep sign for table display logic (Red for negative/purchase)
                supplyAmount: sign * supplyAmount,
                taxAmount: sign * taxAmount,
                totalAmount: sign * totalAmount,

                invoiceNum: asString(row.InvoiceNum) || undefined,

                // Initialize new fields with smart mapping
                // Remark1 -> Site Name (Common usage)
                // Remark2 -> Team Name
                // Remark3 -> Memo
                siteName: asString(row.Remark1) || '',
                teamName: asString(row.Remark2) || '',
                memo: asString(row.Remark3) || ''
            };
        });
    };

    useEffect(() => {
        // Auto-fetch on mount for better UX
        fetchData();
    }, []);

    const handleViewLedger = () => {
        navigate('/payroll/taxinvoice/ledger');
    };

    const handleSaveToLedger = async () => {
        if (selectedIds.length === 0) {
            Swal.fire('알림', '저장할 내역을 선택해주세요.', 'warning');
            return;
        }

        const selectedRecords = records.filter(r => selectedIds.includes(r.id));

        try {
            setLoading(true);
            await taxLedgerService.saveRecords(selectedRecords);
            setLoading(false);

            const result = await Swal.fire({
                title: '저장 완료',
                text: `${selectedRecords.length}건의 내역을 장부에 저장했습니다. 장부로 이동하시겠습니까?`,
                icon: 'success',
                showCancelButton: true,
                confirmButtonText: '장부로 이동',
                cancelButtonText: '계속 조회'
            });

            if (result.isConfirmed) {
                navigate('/payroll/taxinvoice/ledger');
            }
            // Clear selection after save? Maybe keep it for reference.
            setSelectedIds([]);
        } catch (error) {
            console.error(error);
            setLoading(false);
            Swal.fire('저장 실패', '장부 저장 중 오류가 발생했습니다.', 'error');
        }
    };

    return (
        <PageContainer>
            <PageHeader>
                <div className="flex justify-between items-end">
                    <div>
                        <Title>전자세금계산서 조회</Title>
                        <Subtitle>국세청(홈택스)에 신고된 매입/매출 세금계산서 내역을 조회합니다.</Subtitle>
                    </div>
                    <div className="flex gap-2">
                        <button
                            onClick={handleSaveToLedger}
                            className="bg-emerald-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-emerald-700 transition shadow-sm flex items-center gap-2"
                        >
                            <FontAwesomeIcon icon={faSave} />
                            장부로 저장 ({selectedIds.length})
                        </button>
                        <button
                            onClick={handleViewLedger}
                            className="bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-lg text-sm font-bold hover:bg-slate-50 transition shadow-sm flex items-center gap-2"
                        >
                            <FontAwesomeIcon icon={faBook} className="text-slate-500" />
                            장부 보기
                        </button>
                    </div>
                </div>
            </PageHeader>

            {/* Expanded Summary: Sales vs Purchase */}
            <TransactionSummaryCards
                sales={summary.sales}
                purchase={summary.purchase}
            />

            <TransactionFilterBar
                startDate={startDate}
                endDate={endDate}
                onDateChange={(s, e) => { setStartDate(s); setEndDate(e); }}
                type={transactionType}
                onTypeChange={setTransactionType}
                search={searchQuery}
                onSearchChange={setSearchQuery}
                onRefresh={fetchData}
                loading={loading}
            />

            {/* Replaced Grid with Standard Table */}
            <TransactionTable
                records={filteredRecords}
                loading={loading}
                selectable={true}
                selectedIds={selectedIds}
                onSelectionChange={setSelectedIds}
            />
        </PageContainer>
    );
};

export default TaxAffairsPage;

import React from 'react';
import { ReceivableLedger } from '../../../services/receivableService';
import { format } from 'date-fns';

type TableProps = {
    records: ReceivableLedger[];
    loading: boolean;
    onRowClick?: (record: ReceivableLedger) => void;
    selectedId?: string | null;
    isFixed?: boolean;
};

export const ReceivableTable: React.FC<TableProps> = ({
    records,
    loading,
    onRowClick,
    selectedId,
    isFixed
}) => {
    // Calculate totals for footer
    const totals = records.reduce((acc, r) => ({
        total: acc.total + r.invoiceData.totalAmount,
        paid: acc.paid + r.totalPaidAmount,
        outstanding: acc.outstanding + r.outstandingAmount
    }), { total: 0, paid: 0, outstanding: 0 });

    if (loading) {
        return (
            <div className="w-full h-64 flex items-center justify-center bg-white rounded-xl border border-slate-200">
                <span className="text-slate-500">데이터를 불러오는 중입니다...</span>
            </div>
        );
    }

    if (records.length === 0) {
        return (
            <div className="w-full h-64 flex items-center justify-center bg-white rounded-xl border border-slate-200">
                <span className="text-slate-400">데이터가 없습니다.</span>
            </div>
        );
    }

    return (
        <div className="w-full bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col h-full">
            <div className="overflow-auto flex-1">
                <table className="w-full text-sm text-center text-slate-600">
                    <thead className="text-xs text-slate-700 uppercase bg-slate-50 sticky top-0 z-10 shadow-sm">
                        <tr>
                            <th className={`px-3 py-3 font-bold border-b border-slate-200 whitespace-nowrap transition-all ${isFixed ? 'sticky left-0 z-20 bg-slate-50' : ''}`}>작성일자</th>
                            <th className={`px-3 py-3 font-bold border-b border-slate-200 whitespace-nowrap transition-all ${isFixed ? 'sticky left-[100px] z-20 bg-slate-50 border-r border-slate-200' : ''}`}>거래처명</th>
                            <th className="px-3 py-3 font-bold border-b border-slate-200 whitespace-nowrap text-left">품목</th>
                            <th className="px-3 py-3 font-bold border-b border-slate-200 whitespace-nowrap text-right">청구금액</th>
                            <th className="px-3 py-3 font-bold border-b border-slate-200 whitespace-nowrap text-right">수금액</th>
                            <th className="px-3 py-3 font-bold border-b border-slate-200 whitespace-nowrap text-right">미수잔액</th>
                            <th className="px-3 py-3 font-bold border-b border-slate-200 whitespace-nowrap">상태</th>
                            <th className="px-3 py-3 font-bold border-b border-slate-200 whitespace-nowrap">최근수금일</th>
                        </tr>
                    </thead>
                    <tbody>
                        {records.map((record) => (
                            <tr
                                key={record.id}
                                className={`border-b hover:bg-slate-50 transition-colors cursor-pointer ${selectedId === record.id ? 'bg-blue-50 hover:bg-blue-100' : ''}`}
                                onClick={() => onRowClick && onRowClick(record)}
                            >
                                <td className={`px-3 py-2 whitespace-nowrap text-slate-500 transition-all ${isFixed ? 'sticky left-0 z-10 bg-inherit shadow-[1px_0_0_0_rgba(226,232,240,1)]' : ''}`}>
                                    {record.invoiceData.date}
                                </td>
                                <td className={`px-3 py-2 whitespace-nowrap font-medium text-slate-800 transition-all ${isFixed ? 'sticky left-[100px] z-10 bg-inherit border-r border-slate-200 shadow-[1px_0_0_0_rgba(226,232,240,1)]' : ''}`}>
                                    {record.invoiceData.partnerName}
                                </td>
                                <td className="px-3 py-2 text-left max-w-[200px] truncate text-slate-600" title={record.invoiceData.itemName}>
                                    {record.invoiceData.itemName}
                                </td>
                                <td className="px-3 py-2 text-right font-medium text-slate-700">
                                    {record.invoiceData.totalAmount.toLocaleString()}
                                </td>
                                <td className="px-3 py-2 text-right font-medium text-emerald-600">
                                    {record.totalPaidAmount > 0 ? record.totalPaidAmount.toLocaleString() : '-'}
                                </td>
                                <td className="px-3 py-2 text-right font-bold text-red-600">
                                    {record.outstandingAmount !== 0 ? record.outstandingAmount.toLocaleString() : '-'}
                                </td>
                                <td className="px-3 py-2 whitespace-nowrap">
                                    <StatusBadge status={record.status} />
                                </td>
                                <td className="px-3 py-2 whitespace-nowrap text-slate-400 text-xs">
                                    {record.lastPaymentDate || '-'}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                    <tfoot className="bg-slate-100 font-bold text-slate-800 border-t-2 border-slate-200 sticky bottom-0 z-10">
                        <tr>
                            <td colSpan={3} className="px-3 py-3 text-center">합계</td>
                            <td className="px-3 py-3 text-right text-blue-700">{totals.total.toLocaleString()}</td>
                            <td className="px-3 py-3 text-right text-emerald-700">{totals.paid.toLocaleString()}</td>
                            <td className="px-3 py-3 text-right text-red-700">{totals.outstanding.toLocaleString()}</td>
                            <td colSpan={2}></td>
                        </tr>
                    </tfoot>
                </table>
            </div>
        </div>
    );
};

const StatusBadge = ({ status }: { status: string }) => {
    let colorClass = 'bg-slate-100 text-slate-600';
    if (status === '완납') colorClass = 'bg-emerald-100 text-emerald-700';
    if (status === '미수') colorClass = 'bg-red-100 text-red-700';
    if (status === '부분수납') colorClass = 'bg-orange-100 text-orange-700';
    if (status === '과입금') colorClass = 'bg-blue-100 text-blue-700';

    return (
        <span className={`px-2 py-1 rounded-full text-xs font-semibold ${colorClass}`}>
            {status}
        </span>
    );
};

import React, { useEffect, useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCalendarAlt, faSearch, faUndo } from '@fortawesome/free-solid-svg-icons';
import { format, startOfMonth, endOfMonth, subMonths, startOfQuarter, subQuarters, addDays } from 'date-fns';

type FilterProps = {
    startDate: string;
    endDate: string;
    onDateChange: (start: string, end: string) => void;

    type: '전체' | '매출' | '매입';
    onTypeChange: (type: '전체' | '매출' | '매입') => void;

    search: string;
    onSearchChange: (value: string) => void;

    onRefresh: () => void;
    loading: boolean;
};

export const TransactionFilterBar: React.FC<FilterProps> = ({
    startDate,
    endDate,
    onDateChange,
    type,
    onTypeChange,
    search,
    onSearchChange,
    onRefresh,
    loading
}) => {
    // Quick Presets
    const setPreset = (preset: 'today' | 'yesterday' | 'thisMonth' | 'lastMonth' | 'lastQuarter') => {
        const today = new Date();
        let start = new Date();
        let end = new Date();

        switch (preset) {
            case 'today':
                // default
                break;
            case 'yesterday':
                start = addDays(today, -1);
                end = addDays(today, -1);
                break;
            case 'thisMonth':
                start = startOfMonth(today);
                end = today;
                break;
            case 'lastMonth':
                const lastM = subMonths(today, 1);
                start = startOfMonth(lastM);
                end = endOfMonth(lastM);
                break;
            case 'lastQuarter':
                const lastQ = subQuarters(today, 1);
                start = startOfQuarter(lastQ);
                end = endOfMonth(addDays(startOfQuarter(today), -1)); // End of last quarter
                // Simplified: just last 3 months approximation for accounting convenience often suffices, but let's be precise if possible or stick to "Last 3 Months"
                // Let's use "Last 3 Months" logic for simplicity in accounting context usually means "Recent trend"
                start = subMonths(today, 3);
                break;
        }

        onDateChange(format(start, 'yyyy-MM-dd'), format(end, 'yyyy-MM-dd'));
    };

    return (
        <div className="bg-white rounded-2xl border border-slate-200 p-4 mb-6 shadow-sm">
            <div className="flex flex-col lg:flex-row gap-4 items-center justify-between">

                {/* Left: Date Range & Presets */}
                <div className="flex flex-col sm:flex-row gap-3 items-center w-full lg:w-auto">
                    <div className="flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-lg p-1">
                        <input
                            type="date"
                            className="bg-transparent border-none text-sm font-medium text-slate-700 outline-none px-2"
                            value={startDate}
                            onChange={(e) => onDateChange(e.target.value, endDate)}
                        />
                        <span className="text-slate-400">~</span>
                        <input
                            type="date"
                            className="bg-transparent border-none text-sm font-medium text-slate-700 outline-none px-2"
                            value={endDate}
                            onChange={(e) => onDateChange(startDate, e.target.value)}
                        />
                    </div>

                    <div className="flex gap-1 overflow-x-auto max-w-full pb-1 sm:pb-0 scrollbar-hide">
                        {[
                            { label: '오늘', value: 'today' },
                            { label: '어제', value: 'yesterday' },
                            { label: '이번달', value: 'thisMonth' },
                            { label: '지난달', value: 'lastMonth' },
                        ].map((p) => (
                            <button
                                key={p.value}
                                onClick={() => setPreset(p.value as any)}
                                className="px-3 py-1.5 rounded-lg text-xs font-semibold bg-white border border-slate-200 text-slate-600 hover:bg-slate-50 hover:text-slate-900 transition whitespace-nowrap"
                            >
                                {p.label}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Right: Type, Search, Action */}
                <div className="flex flex-col sm:flex-row gap-3 items-center w-full lg:w-auto">
                    {/* Type Filter */}
                    <div className="flex bg-slate-100 p-1 rounded-lg">
                        {(['전체', '매출', '매입'] as const).map((t) => (
                            <button
                                key={t}
                                onClick={() => onTypeChange(t)}
                                className={`px-4 py-1.5 rounded-md text-sm font-bold transition ${type === t
                                    ? t === '매출' ? 'bg-blue-600 text-white shadow-sm'
                                        : t === '매입' ? 'bg-red-500 text-white shadow-sm'
                                            : 'bg-white text-slate-800 shadow-sm'
                                    : 'text-slate-500 hover:text-slate-700'
                                    }`}
                            >
                                {t}
                            </button>
                        ))}
                    </div>

                    {/* Search */}
                    <div className="relative w-full sm:w-64">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                            <FontAwesomeIcon icon={faSearch} className="text-slate-400" />
                        </div>
                        <input
                            type="text"
                            value={search}
                            onChange={(e) => onSearchChange(e.target.value)}
                            className="pl-10 pr-4 py-2 w-full border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-slate-500 focus:border-transparent outline-none transition"
                            placeholder="거래처, 품목 검색..."
                        />
                    </div>

                    {/* Refresh Button */}
                    <button
                        onClick={onRefresh}
                        disabled={loading}
                        className="w-full sm:w-auto bg-slate-800 text-white px-5 py-2 rounded-lg text-sm font-bold hover:bg-slate-700 transition disabled:opacity-50 flex items-center justify-center gap-2"
                    >
                        {loading ? (
                            <>
                                <FontAwesomeIcon icon={faUndo} className="animate-spin" />
                                <span>조회중</span>
                            </>
                        ) : (
                            <>
                                <FontAwesomeIcon icon={faUndo} />
                                <span>조회</span>
                            </>
                        )}
                    </button>
                </div>
            </div>
        </div>
    );
};

