    font-weight: 500;
    color: #64748b;
`;

const AccountInquiryPage: React.FC = () => {
    const navigate = useNavigate();

    // State
    const [accountNum, setAccountNum] = useState('');
    const [startDate, setStartDate] = useState(format(startOfMonth(new Date()), 'yyyy-MM-dd'));
    const [endDate, setEndDate] = useState(format(new Date(), 'yyyy-MM-dd'));

    // Data State
    const [transactions, setTransactions] = useState<BankAccountLog[]>([]);
    const [registeredAccounts, setRegisteredAccounts] = useState<BankAccount[]>([]);
    const [loading, setLoading] = useState(false);

    // Pagination State
    const [currentPage, setCurrentPage] = useState(1);
    const [totalPages, setTotalPages] = useState(1);
    const [totalCount, setTotalCount] = useState(0);

    // Initial Load
    useEffect(() => {
        const loadAccounts = async () => {
            try {
                const accounts = await barobillAccountService.getBankAccountList();
                setRegisteredAccounts(accounts || []);
                if (accounts && accounts.length > 0) {
                    const defaultAcc = '66620101767628'; // Legacy default
                    const found = accounts.find(a => a.accountNum === defaultAcc);
                    if (found) {
                        setAccountNum(found.accountNum);
                    } else {
                        setAccountNum(accounts[0].accountNum);
                    }
                }
            } catch (e) {
                console.error("Failed to load accounts", e);
            }
        };
        loadAccounts();
    }, []);

    // Summary Calculation (for the current page view - API limitation unless we fetch all to sum)
    // Actually Barobill might not give total stats for period. We summarize what we see.
    // Or we use the Balance from the latest record.
    const summary = useMemo(() => {
        const deposit = transactions.reduce((acc, curr) => acc + (Number(curr.Deposit) || 0), 0);
        const withdraw = transactions.reduce((acc, curr) => acc + (Number(curr.Withdraw) || 0), 0);
        // Latest balance: The first record if sorted desc by date? Barobill returns usually desc.
        // Let's assume index 0 is latest.
        const latestBalance = transactions.length > 0 ? Number(transactions[0].Balance) || 0 : 0;

        return { totalDeposit: deposit, totalWithdraw: withdraw, latestBalance };
    }, [transactions]);


    const fetchHistory = async (page: number) => {
        if (!accountNum) {
            Swal.fire('알림', '계좌를 선택해주세요.', 'warning');
            return;
        }

        setLoading(true);
        try {
            // Remove dashes from date if needed, but service expects generic string potentially.
            // Looking at previous code: formatDateForApi remove dashes.
            const startStr = startDate.replace(/-/g, '');
            const endStr = endDate.replace(/-/g, '');

            console.log(`[AccountInquiry] Fetching page ${page} for ${accountNum}, ${startStr}~${endStr}`);

            const result = await barobillAccountService.getBankAccountHistory(
                accountNum,
                startStr,
                endStr,
                page
            );

            setTransactions(result.logs || []);
            setTotalPages(result.maxPageNum || 1);
            setTotalCount(result.totalCount || 0);
            setCurrentPage(page);

        } catch (error: any) {
            console.error(error);
            Swal.fire('조회 실패', error.message || '내역을 불러오지 못했습니다.', 'error');
        } finally {
            setLoading(false);
        }
    };

    const handleSearch = () => {
        fetchHistory(1);
    };

    const handleRegister = async () => {
        const { value: formValues } = await Swal.fire({
            title: '계좌 등록 (바로빌)',
            html: `
                <div style="text-align: left; font-size: 14px; display: flex; flex-direction: column; gap: 12px;">
                    <div>
                        <label style="display:block; margin-bottom:5px; font-weight:bold; color: #374151;">은행</label>
                        <select id="swal-bank" class="swal2-input" style="margin:0; width:100%;">
                            <option value="">은행 선택</option>
                            <option value="004">국민은행</option>
                            <option value="088">신한은행</option>
                            <option value="020">우리은행</option>
                            <option value="081">하나은행</option>
                            <option value="011">농협</option>
                            <option value="003">기업은행</option>
                            <option value="023">SC제일은행</option>
                            <option value="002">산업은행</option>
                        </select>
                    </div>
                    <div>
                        <label style="display:block; margin-bottom:5px; font-weight:bold; color: #374151;">계좌번호 ('-' 없이)</label>
                        <input id="swal-account" class="swal2-input" placeholder="1234567890" style="margin:0; width:100%;">
                    </div>
                    <div>
                        <label style="display:block; margin-bottom:5px; font-weight:bold; color: #374151;">계좌 비밀번호</label>
                        <input id="swal-pwd" type="password" class="swal2-input" placeholder="비밀번호" style="margin:0; width:100%;">
                    </div>
                    <div>
                        <label style="display:block; margin-bottom:5px; font-weight:bold; color: #374151;">예금주 식별번호 (사업자/주민번호)</label>
                        <input id="swal-identity" class="swal2-input" placeholder="사업자번호 또는 주민번호" style="margin:0; width:100%;">
                    </div>
                    <div>
                        <label style="display:block; margin-bottom:5px; font-weight:bold; color: #374151;">별칭 (선택)</label>
                        <input id="swal-alias" class="swal2-input" placeholder="예: 법인 주거래" style="margin:0; width:100%;">
                    </div>
                </div>
            `,
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: '등록',
            cancelButtonText: '취소',
            confirmButtonColor: '#059669',
            preConfirm: () => {
                const bank = (document.getElementById('swal-bank') as HTMLSelectElement).value;
                const account = (document.getElementById('swal-account') as HTMLInputElement).value;
                const pwd = (document.getElementById('swal-pwd') as HTMLInputElement).value;
                const identity = (document.getElementById('swal-identity') as HTMLInputElement).value;
                const alias = (document.getElementById('swal-alias') as HTMLInputElement).value;

                if (!bank || !account || !pwd || !identity) {
                    Swal.showValidationMessage('모든 필수 정보를 입력해주세요.');
                    return false;
                }
                return { bank, account, pwd, identity, alias };
            }
        });

        if (formValues) {
            try {
                // Loading
                Swal.fire({
                    title: '등록 중...',
                    text: '바로빌에 계좌를 등록하고 있습니다.',
                    allowOutsideClick: false,
                    didOpen: () => {
                        Swal.showLoading();
                    }
                });

                const result = await barobillAccountService.registBankAccount(
                    formValues.bank,
                    formValues.account,
                    formValues.pwd,
                    formValues.identity,
                    formValues.alias
                );

                if (result.success) {
                    Swal.fire({
                        icon: 'success',
                        title: '등록 성공',
                        text: '계좌가 성공적으로 등록되었습니다.',
                        confirmButtonText: '확인',
                        confirmButtonColor: '#059669'
                    });
                    // Refresh account list
                    const accounts = await barobillAccountService.getBankAccountList();
                    setRegisteredAccounts(accounts || []);
                    if (accounts && accounts.length > 0 && !accountNum) {
                        setAccountNum(accounts[0].accountNum);
                    }
                }
            } catch (error: any) {
                Swal.fire({
                    icon: 'error',
                    title: '등록 실패',
                    text: error.message,
                    confirmButtonColor: '#d33'
                });
            }
        }
    };

    const handleBack = () => {
        navigate(-1);
    };

    return (
        <PageContainer>
            <BackButton onClick={handleBack}>
                <FontAwesomeIcon icon={faArrowLeft} />
                이전으로
            </BackButton>

            <PageHeader>
                <HeaderContent>
                    <div>
                        <Title>
                            <FontAwesomeIcon icon={faUniversity} className="text-emerald-600" />
                            계좌 입출금 내역 조회
                        </Title>
                        <Subtitle>
                            바로빌 서비스에 등록된 계좌의 입출금 내역을 조회합니다.
                        </Subtitle>
                    </div>
                </HeaderContent>
            </PageHeader>

            <AccountSummaryCards
                totalDeposit={summary.totalDeposit}
                totalWithdraw={summary.totalWithdraw}
                latestBalance={summary.latestBalance}
            />

            <AccountInquiryFilterBar
                accountNum={accountNum}
                onAccountChange={setAccountNum}
                accounts={registeredAccounts}
                startDate={startDate}
                endDate={endDate}
                onDateChange={(s, e) => { setStartDate(s); setEndDate(e); }}
                onRefresh={handleSearch}
                onRegister={handleRegister}
                loading={loading}
            />

            <AccountTransactionTable
                records={transactions}
                loading={loading}
            />

            {/* Pagination */}
            {totalCount > 0 && (
                <PaginationBar>
                    <PageButton
                        onClick={() => fetchHistory(currentPage - 1)}
                        disabled={currentPage === 1 || loading}
                    >
                        이전
                    </PageButton>
                    <PageInfo>
                        페이지 {currentPage} / {totalPages} (총 {totalCount.toLocaleString()}건)
                    </PageInfo>
                    <PageButton
                        onClick={() => fetchHistory(currentPage + 1)}
                        disabled={currentPage === totalPages || loading}
                    >
                        다음
                    </PageButton>
                </PaginationBar>
            )}
        </PageContainer>
    );
};

export default AccountInquiryPage;

import React, { useState, useEffect } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faDashboard,
    faMoneyBillTrendUp,
    faMoneyBillWave,
    faExclamationTriangle,
    faCheckCircle,
    faArrowUp,
    faArrowDown,
    faClock,
    faBuilding,
    faUniversity,
    faThumbtack
} from '@fortawesome/free-solid-svg-icons';
import { useNavigate } from 'react-router-dom';
import { receivableService } from '../../services/receivableService';
import {
    Receivable,
    ReceivableStatistics,
    ReceivableStatus
} from '../../types/receivable';

const ReceivablesDashboardPage: React.FC = () => {
    const navigate = useNavigate();

    // State
    const [statistics, setStatistics] = useState<ReceivableStatistics>({
        totalIssued: 0,
        totalPaid: 0,
        totalBalance: 0,
        overdueCount: 0,
        overdueAmount: 0
    });
    const [recentReceivables, setRecentReceivables] = useState<Receivable[]>([]);
    const [loading, setLoading] = useState(true);
    const [isFixed, setIsFixed] = useState(true);

    // Lock parent scroll for internal scrolling
    useEffect(() => {
        const mainContent = document.getElementById('main-content');
        if (mainContent) {
            const originalOverflow = mainContent.style.overflow;
            mainContent.style.overflow = 'hidden';
            return () => {
                mainContent.style.overflow = originalOverflow;
            };
        }
    }, []);

    // Load data
    useEffect(() => {
        loadDashboardData();
    }, []);

    const loadDashboardData = async () => {
        setLoading(true);
        try {
            // Load all active receivables
            const all = await receivableService.getReceivables();

            // Calculate statistics locally
            const stats: ReceivableStatistics = all.reduce((acc, curr) => {
                acc.totalIssued += curr.outstandingAmount + curr.totalPaidAmount; // Approximate total issued
                acc.totalPaid += curr.totalPaidAmount;
                acc.totalBalance += curr.outstandingAmount;

                // Overdue logic (simple check: if unpaid and older than 30 days)
                const issueDate = new Date(curr.invoiceData.date);
                const diffTime = Math.abs(new Date().getTime() - issueDate.getTime());
                const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

                if (curr.status !== '완납' && curr.status !== '과입금' && diffDays > 30) {
                    acc.overdueCount += 1;
                    acc.overdueAmount += curr.outstandingAmount;
                }

                return acc;
            }, {
                totalIssued: 0,
                totalPaid: 0,
                totalBalance: 0,
                overdueCount: 0,
                overdueAmount: 0
            });

            setStatistics(stats);

            // Recent unpaid
            const unpaid = all
                .filter(r => r.status !== '완납' && r.status !== '과입금')
                .sort((a, b) => new Date(b.invoiceData.date).getTime() - new Date(a.invoiceData.date).getTime())
                .slice(0, 10);

            // Map to compatible format if needed by component
            const mapStatus = (s: string, date: string): ReceivableStatus => {
                const issueDate = new Date(date);
                const diffTime = Math.abs(new Date().getTime() - issueDate.getTime());
                const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

                if (diffDays > 30 && s !== '완납' && s !== '과입금') return ReceivableStatus.OVERDUE;
                if (s === '완납' || s === '과입금') return ReceivableStatus.PAID;
                if (s === '부분수납') return ReceivableStatus.PARTIAL;
                return ReceivableStatus.UNPAID;
            };

            const mappedUnpaid = unpaid.map(r => ({
                id: r.id,
                customerName: r.invoiceData.partnerName,
                issueDate: r.invoiceData.date,
                totalAmount: r.outstandingAmount + r.totalPaidAmount,
                totalPaid: r.totalPaidAmount,
                balance: r.outstandingAmount,
                status: mapStatus(r.status, r.invoiceData.date),
                note: r.invoiceData.itemName
            }));

            setRecentReceivables(mappedUnpaid as any); // Cast to any or fix type in state
        } catch (error) {
            console.error('Error loading dashboard data:', error);
        } finally {
            setLoading(false);
        }
    };

    // Calculate collection rate
    const collectionRate = statistics.totalIssued > 0
        ? ((statistics.totalPaid / statistics.totalIssued) * 100).toFixed(1)
        : '0';

    // Status badge
    const getStatusBadge = (status: ReceivableStatus) => {
        const badges = {
            [ReceivableStatus.PAID]: { bg: 'bg-green-100', text: 'text-green-800', label: '완납' },
            [ReceivableStatus.PARTIAL]: { bg: 'bg-yellow-100', text: 'text-yellow-800', label: '부분납부' },
            [ReceivableStatus.UNPAID]: { bg: 'bg-red-100', text: 'text-red-800', label: '미납' },
            [ReceivableStatus.OVERDUE]: { bg: 'bg-gray-800', text: 'text-white', label: '연체' }
        };
        const badge = badges[status];
        return (
            <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${badge.bg} ${badge.text}`}>
                {badge.label}
            </span>
        );
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-screen">
                <div className="text-lg text-gray-500">데이터 로딩 중...</div>
            </div>
        );
    }

    return (
        <div className="flex-1 min-h-0 flex flex-col bg-gradient-to-br from-slate-50 to-slate-100 p-6 overflow-hidden">
            <div className="max-w-7xl mx-auto w-full flex-1 min-h-0 flex flex-col overflow-hidden">
                {/* Header */}
                <div className="flex-shrink-0 mb-6">
                    <h1 className="text-3xl font-bold text-gray-800 flex items-center gap-3">
                        <FontAwesomeIcon icon={faDashboard} className="text-blue-600" />
                        미수금 대시보드
                    </h1>
                    <p className="text-sm text-gray-500 mt-1">미수금 현황을 한눈에 확인하세요</p>
                </div>

                {/* Stats Cards */}
                <div className="flex-shrink-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                    {/* Total Issued */}
                    <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 hover:shadow-md transition-shadow">
                        <div className="flex items-center justify-between mb-4">
                            <div className="p-3 bg-blue-100 rounded-lg">
                                <FontAwesomeIcon icon={faMoneyBillTrendUp} className="text-2xl text-blue-600" />
                            </div>
                        </div>
                        <div className="text-sm text-gray-600 mb-1">총 발행액</div>
                        <div className="text-3xl font-bold text-gray-800 mb-2">
                            {(statistics.totalIssued / 10000).toFixed(0)}
                            <span className="text-lg text-gray-500 ml-1">만원</span>
                        </div>
                        <div className="text-xs text-gray-500">
                            {statistics.totalIssued.toLocaleString()}원
                        </div>
                    </div>

                    {/* Total Paid */}
                    <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 hover:shadow-md transition-shadow">
                        <div className="flex items-center justify-between mb-4">
                            <div className="p-3 bg-green-100 rounded-lg">
                                <FontAwesomeIcon icon={faCheckCircle} className="text-2xl text-green-600" />
                            </div>
                        </div>
                        <div className="text-sm text-gray-600 mb-1">총 입금액</div>
                        <div className="text-3xl font-bold text-green-600 mb-2">
                            {(statistics.totalPaid / 10000).toFixed(0)}
                            <span className="text-lg text-green-500 ml-1">만원</span>
                        </div>
                        <div className="text-xs text-gray-500">
                            수금률: {collectionRate}%
                        </div>
                    </div>

                    {/* Total Balance */}
                    <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 hover:shadow-md transition-shadow">
                        <div className="flex items-center justify-between mb-4">
                            <div className="p-3 bg-red-100 rounded-lg">
                                <FontAwesomeIcon icon={faMoneyBillWave} className="text-2xl text-red-600" />
                            </div>
                        </div>
                        <div className="text-sm text-gray-600 mb-1">총 미수금</div>
                        <div className="text-3xl font-bold text-red-600 mb-2">
                            {(statistics.totalBalance / 10000).toFixed(0)}
                            <span className="text-lg text-red-500 ml-1">만원</span>
                        </div>
                        <div className="text-xs text-gray-500">
                            {statistics.totalBalance.toLocaleString()}원
                        </div>
                    </div>

                    {/* Overdue */}
                    <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 hover:shadow-md transition-shadow">
                        <div className="flex items-center justify-between mb-4">
                            <div className="p-3 bg-yellow-100 rounded-lg">
                                <FontAwesomeIcon icon={faExclamationTriangle} className="text-2xl text-yellow-600" />
                            </div>
                        </div>
                        <div className="text-sm text-gray-600 mb-1">연체 (30일 초과)</div>
                        <div className="text-3xl font-bold text-yellow-600 mb-2">
                            {statistics.overdueCount}
                            <span className="text-lg text-yellow-500 ml-1">건</span>
                        </div>
                        <div className="text-xs text-gray-500">
                            {(statistics.overdueAmount / 10000).toFixed(0)}만원
                        </div>
                    </div>
                </div>

                {/* Quick Actions */}
                <div className="flex-shrink-0 grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
                    <button
                        onClick={() => navigate('/payroll/taxinvoice/receivables')}
                        className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 hover:shadow-md transition-all hover:border-blue-300"
                    >
                        <div className="flex items-center gap-4">
                            <div className="p-3 bg-blue-50 rounded-lg">
                                <FontAwesomeIcon icon={faMoneyBillWave} className="text-xl text-blue-600" />
                            </div>
                            <div className="text-left">
                                <div className="font-bold text-gray-800">미수금 관리</div>
                                <div className="text-xs text-gray-500">입금 등록 및 관리</div>
                            </div>
                        </div>
                    </button>

                    <button
                        onClick={() => navigate('/payroll/taxinvoice/bank-inquiry')}
                        className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 hover:shadow-md transition-all hover:border-green-300"
                    >
                        <div className="flex items-center gap-4">
                            <div className="p-3 bg-green-50 rounded-lg">
                                <FontAwesomeIcon icon={faUniversity} className="text-xl text-green-600" />
                            </div>
                            <div className="text-left">
                                <div className="font-bold text-gray-800">입금내역 계좌조회</div>
                                <div className="text-xs text-gray-500">바로빌 계좌조회</div>
                            </div>
                        </div>
                    </button>

                    <button
                        onClick={() => navigate('/payroll/taxinvoice/ledger')}
                        className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 hover:shadow-md transition-all hover:border-purple-300"
                    >
                        <div className="flex items-center gap-4">
                            <div className="p-3 bg-purple-50 rounded-lg">
                                <FontAwesomeIcon icon={faClock} className="text-xl text-purple-600" />
                            </div>
                            <div className="text-left">
                                <div className="font-bold text-gray-800">거래장 조회</div>
                                <div className="text-xs text-gray-500">전체 내역 확인</div>
                            </div>
                        </div>
                    </button>
                </div>

                {/* Recent Unpaid Receivables */}
                <div className="flex-1 min-h-0 bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden flex flex-col">
                    <div className="p-6 border-b border-gray-200 bg-gradient-to-r from-gray-50 to-white flex justify-between items-center">
                        <div>
                            <h2 className="text-xl font-bold text-gray-800">미수금 현황</h2>
                            <p className="text-sm text-gray-500 mt-1">미납 및 부분 납부 내역</p>
                        </div>
                        <button
                            onClick={() => setIsFixed(!isFixed)}
                            className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all border ${isFixed
                                ? 'bg-amber-500 text-white border-amber-500 shadow-sm'
                                : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
                                }`}
                        >
                            <FontAwesomeIcon icon={faThumbtack} className={isFixed ? 'rotate-45' : ''} />
                            {isFixed ? '틀고정 해제' : '틀고정 활성'}
                        </button>
                    </div>

                    <div className="flex-1 min-h-0 overflow-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-gray-50 border-b border-gray-200 sticky top-0 z-30">
                                <tr>
                                    <th className={`px-6 py-4 text-xs font-medium text-gray-500 uppercase tracking-wider ${isFixed ? 'sticky left-0 z-40 bg-gray-50 border-r border-gray-200' : ''}`}>
                                        거래처
                                    </th>
                                    <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        발행일
                                    </th>
                                    <th className="px-6 py-4 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        발행액
                                    </th>
                                    <th className="px-6 py-4 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        입금액
                                    </th>
                                    <th className="px-6 py-4 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        미수금
                                    </th>
                                    <th className="px-6 py-4 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        상태
                                    </th>
                                </tr>
                            </thead>
                            <tbody className="bg-white divide-y divide-gray-200">
                                {recentReceivables.length === 0 ? (
                                    <tr>
                                        <td colSpan={6} className="px-6 py-12 text-center text-gray-500">
                                            미납 내역이 없습니다! 🎉
                                        </td>
                                    </tr>
                                ) : (
                                    recentReceivables.map((receivable) => (
                                        <tr
                                            key={receivable.id}
                                            className="hover:bg-blue-50 transition-colors cursor-pointer group"
                                            onClick={() => navigate('/payroll/taxinvoice/receivables')}
                                        >
                                            <td className={`px-6 py-4 whitespace-nowrap ${isFixed ? 'sticky left-0 z-20 bg-white group-hover:bg-blue-50 border-r border-gray-100' : ''}`}>
                                                <div className="font-medium text-gray-900">{receivable.customerName}</div>
                                                <div className="text-xs text-gray-500">{receivable.note}</div>
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                                                {receivable.issueDate}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-right font-mono text-gray-900">
                                                {receivable.totalAmount.toLocaleString()}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-right font-mono text-green-600">
                                                {receivable.totalPaid.toLocaleString()}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-right font-mono font-bold text-red-600">
                                                {receivable.balance.toLocaleString()}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-center">
                                                {getStatusBadge(receivable.status)}
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>

                    {recentReceivables.length > 0 && (
                        <div className="p-4 bg-gray-50 border-t border-gray-200 text-center">
                            <button
                                onClick={() => navigate('/payroll/taxinvoice/receivables')}
                                className="text-blue-600 hover:text-blue-800 text-sm font-medium"
                            >
                                전체 미수금 보기 →
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default ReceivablesDashboardPage;

// @ts-nocheck
import React, { useState, useEffect } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
    faFileInvoiceDollar,
    faSearch,
    faFilter,
    faPlus,
    faDownload,
    faMoneyBillWave,
    faCheckCircle,
    faExclamationTriangle,
    faTimesCircle,
    faEdit
} from '@fortawesome/free-solid-svg-icons';
import { Timestamp } from 'firebase/firestore';
import { receivableService } from '../../services/receivableService';
import {
    Receivable,
    ReceivableFilters,
    ReceivableStatus
} from '../../types/receivable';
import * as XLSX from 'xlsx';

const ReceivablesManagementPage: React.FC = () => {
    // State
    const [receivables, setReceivables] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');

    // Filters
    const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
    const [selectedMonth, setSelectedMonth] = useState<number | ''>('');
    const [selectedStatus, setSelectedStatus] = useState<ReceivableStatus | ''>('');

    // Modal
    const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
    const [selectedReceivable, setSelectedReceivable] = useState<any | null>(null);

    // Payment Form
    const [paymentDate, setPaymentDate] = useState(new Date().toISOString().split('T')[0]);
    const [paymentAmount, setPaymentAmount] = useState('');
    const [paymentMethod, setPaymentMethod] = useState('이체');
    const [paymentNote, setPaymentNote] = useState('');

    // Load data
    useEffect(() => {
        loadReceivables();
    }, [selectedYear, selectedMonth, selectedStatus]);

    const loadReceivables = async () => {
        setLoading(true);
        try {
            const filters: ReceivableFilters = {
                year: selectedYear
            };
            if (selectedMonth) filters.month = selectedMonth as number;
            if (selectedStatus) filters.status = selectedStatus as ReceivableStatus;

            const data = await receivableService.getReceivables();
            setReceivables(data);
        } catch (error) {
            console.error('Error loading receivables:', error);
        } finally {
            setLoading(false);
        }
    };

    // Filtered receivables
    const filteredReceivables = receivables.filter(r =>
        r.customerName.toLowerCase().includes(searchTerm.toLowerCase()) ||
        r.note?.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Status badge
    const getStatusBadge = (status: ReceivableStatus) => {
        const badges = {
            [ReceivableStatus.PAID]: { bg: 'bg-green-100', text: 'text-green-800', icon: faCheckCircle, label: '완납' },
            [ReceivableStatus.PARTIAL]: { bg: 'bg-yellow-100', text: 'text-yellow-800', icon: faExclamationTriangle, label: '부분납부' },
            [ReceivableStatus.UNPAID]: { bg: 'bg-red-100', text: 'text-red-800', icon: faTimesCircle, label: '미납' },
            [ReceivableStatus.OVERDUE]: { bg: 'bg-gray-800', text: 'text-white', icon: faExclamationTriangle, label: '연체' }
        };
        const badge = badges[status];
        return (
            <span className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-medium ${badge.bg} ${badge.text}`}>
                <FontAwesomeIcon icon={badge.icon} className="text-xs" />
                {badge.label}
            </span>
        );
    };

    // Open payment modal
    const openPaymentModal = (receivable: Receivable) => {
        setSelectedReceivable(receivable);
        setPaymentAmount(receivable.balance.toString());
        setPaymentDate(new Date().toISOString().split('T')[0]);
        setPaymentMethod('BankMatch');
        setPaymentNote('');
        setIsPaymentModalOpen(true);
    };

    // Submit payment
    const handleSubmitPayment = async () => {
        if (!selectedReceivable || !paymentAmount) return;

        try {
            await receivableService.addPayment(selectedReceivable.id!, {
                paymentDate,
                amount: parseFloat(paymentAmount),
                method: paymentMethod as any,
                // note: paymentNote,
                // createdBy: 'current-user', // TODO: 실제 사용자 정보
                // createdAt: Timestamp.now()
            });

            alert('입금이 등록되었습니다.');
            setIsPaymentModalOpen(false);
            loadReceivables();
        } catch (error) {
            console.error('Error adding payment:', error);
            alert('입금 등록 중 오류가 발생했습니다.');
        }
    };

    // Excel download
    const downloadExcel = () => {
        const data = filteredReceivables.map(r => ({
            '년도': r.issueYear,
            '거래처명': r.customerName,
            '발행일': r.issueDate,
            '발행액': r.totalAmount,
            '세액': r.taxAmount,
            '공급가액': r.supplyAmount,
            '총 입금액': r.totalPaid,
            '미수금': r.balance,
            '상태': r.status === ReceivableStatus.PAID ? '완납' :
                r.status === ReceivableStatus.PARTIAL ? '부분납부' :
                    r.status === ReceivableStatus.UNPAID ? '미납' : '연체',
            '담당자': r.manager || '',
            '비고': r.note || ''
        }));

        const ws = XLSX.utils.json_to_sheet(data);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, '미수금');
        XLSX.writeFile(wb, `미수금_${selectedYear}년${selectedMonth ? `_${selectedMonth}월` : ''}.xlsx`);
    };

    // Years for filter
    const years = Array.from({ length: 5 }, (_, i) => new Date().getFullYear() - i);
    const months = Array.from({ length: 12 }, (_, i) => i + 1);

    if (loading && receivables.length === 0) {
        return (
            <div className="flex items-center justify-center h-screen">
                <div className="text-lg text-gray-500">데이터 로딩 중...</div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 p-6">
            <div className="max-w-7xl mx-auto">
                {/* Header */}
                <div className="mb-6">
                    <h1 className="text-3xl font-bold text-gray-800 flex items-center gap-3">
                        <FontAwesomeIcon icon={faFileInvoiceDollar} className="text-blue-600" />
                        미수금 관리
                    </h1>
                    <p className="text-sm text-gray-500 mt-1">세금계산서 발행에 대한 입금 및 미수금을 관리합니다</p>
                </div>

                {/* Filters */}
                <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-4 mb-6">
                    <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
                        {/* Year */}
                        <div>
                            <label className="block text-xs font-medium text-gray-700 mb-1">년도</label>
                            <select
                                value={selectedYear}
                                onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                            >
                                {years.map(year => (
                                    <option key={year} value={year}>{year}년</option>
                                ))}
                            </select>
                        </div>

                        {/* Month */}
                        <div>
                            <label className="block text-xs font-medium text-gray-700 mb-1">월</label>
                            <select
                                value={selectedMonth}
                                onChange={(e) => setSelectedMonth(e.target.value ? parseInt(e.target.value) : '')}
                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                            >
                                <option value="">전체</option>
                                {months.map(month => (
                                    <option key={month} value={month}>{month}월</option>
                                ))}
                            </select>
                        </div>

                        {/* Status */}
                        <div>
                            <label className="block text-xs font-medium text-gray-700 mb-1">상태</label>
                            <select
                                value={selectedStatus}
                                onChange={(e) => setSelectedStatus(e.target.value as ReceivableStatus | '')}
                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                            >
                                <option value="">전체</option>
                                <option value={ReceivableStatus.UNPAID}>미납</option>
                                <option value={ReceivableStatus.PARTIAL}>부분납부</option>
                                <option value={ReceivableStatus.PAID}>완납</option>
                                <option value={ReceivableStatus.OVERDUE}>연체</option>
                            </select>
                        </div>

                        {/* Search */}
                        <div className="md:col-span-2">
                            <label className="block text-xs font-medium text-gray-700 mb-1">검색</label>
                            <div className="relative">
                                <FontAwesomeIcon icon={faSearch} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                                <input
                                    type="text"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    placeholder="거래처명, 비고 검색..."
                                    className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                />
                            </div>
                        </div>
                    </div>

                    {/* Actions */}
                    <div className="mt-4 flex gap-2">
                        <button
                            onClick={downloadExcel}
                            className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors flex items-center gap-2"
                        >
                            <FontAwesomeIcon icon={faDownload} />
                            Excel 다운로드
                        </button>
                    </div>
                </div>

                {/* Summary Cards */}
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
                    <div className="bg-white rounded-lg shadow-sm p-4 border-l-4 border-blue-500">
                        <div className="text-sm text-gray-600">총 발행액</div>
                        <div className="text-2xl font-bold text-gray-800 mt-1">
                            {filteredReceivables.reduce((sum, r) => sum + r.totalAmount, 0).toLocaleString()}원
                        </div>
                    </div>
                    <div className="bg-white rounded-lg shadow-sm p-4 border-l-4 border-green-500">
                        <div className="text-sm text-gray-600">총 입금액</div>
                        <div className="text-2xl font-bold text-green-600 mt-1">
                            {filteredReceivables.reduce((sum, r) => sum + r.totalPaid, 0).toLocaleString()}원
                        </div>
                    </div>
                    <div className="bg-white rounded-lg shadow-sm p-4 border-l-4 border-red-500">
                        <div className="text-sm text-gray-600">총 미수금</div>
                        <div className="text-2xl font-bold text-red-600 mt-1">
                            {filteredReceivables.reduce((sum, r) => sum + r.balance, 0).toLocaleString()}원
                        </div>
                    </div>
                    <div className="bg-white rounded-lg shadow-sm p-4 border-l-4 border-yellow-500">
                        <div className="text-sm text-gray-600">미납 건수</div>
                        <div className="text-2xl font-bold text-yellow-600 mt-1">
                            {filteredReceivables.filter(r => r.status !== ReceivableStatus.PAID).length}건
                        </div>
                    </div>
                </div>

                {/* Table */}
                <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-gray-50 border-b border-gray-200">
                                <tr>
                                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">년도</th>
                                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">거래처명</th>
                                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">발행일</th>
                                    <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">발행액</th>
                                    <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">입금액</th>
                                    <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">미수금</th>
                                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase">상태</th>
                                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">비고</th>
                                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase">액션</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-200">
                                {filteredReceivables.length === 0 ? (
                                    <tr>
                                        <td colSpan={9} className="px-4 py-8 text-center text-gray-500">
                                            조회된 미수금 내역이 없습니다.
                                        </td>
                                    </tr>
                                ) : (
                                    filteredReceivables.map((receivable) => (
                                        <tr key={receivable.id} className="hover:bg-gray-50 transition-colors">
                                            <td className="px-4 py-3 text-sm text-gray-900">{receivable.issueYear}</td>
                                            <td className="px-4 py-3 text-sm font-medium text-gray-900">{receivable.customerName}</td>
                                            <td className="px-4 py-3 text-sm text-gray-600">{receivable.issueDate}</td>
                                            <td className="px-4 py-3 text-sm text-right text-gray-900 font-mono">
                                                {receivable.totalAmount.toLocaleString()}
                                            </td>
                                            <td className="px-4 py-3 text-sm text-right text-green-600 font-mono">
                                                {receivable.totalPaid.toLocaleString()}
                                            </td>
                                            <td className="px-4 py-3 text-sm text-right text-red-600 font-mono font-bold">
                                                {receivable.balance.toLocaleString()}
                                            </td>
                                            <td className="px-4 py-3 text-center">
                                                {getStatusBadge(receivable.status)}
                                            </td>
                                            <td className="px-4 py-3 text-sm text-gray-600 max-w-xs truncate">
                                                {receivable.note || '-'}
                                            </td>
                                            <td className="px-4 py-3 text-center">
                                                {receivable.status !== ReceivableStatus.PAID && (
                                                    <button
                                                        onClick={() => openPaymentModal(receivable)}
                                                        className="px-3 py-1 bg-blue-600 text-white text-xs rounded-lg hover:bg-blue-700 transition-colors"
                                                    >
                                                        <FontAwesomeIcon icon={faMoneyBillWave} className="mr-1" />
                                                        입금등록
                                                    </button>
                                                )}
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Payment Modal */}
                {isPaymentModalOpen && selectedReceivable && (
                    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                        <div className="bg-white rounded-xl shadow-xl max-w-md w-full mx-4">
                            <div className="p-6">
                                <h3 className="text-xl font-bold text-gray-800 mb-4">입금 등록</h3>

                                <div className="mb-4 p-3 bg-blue-50 rounded-lg">
                                    <div className="text-sm text-gray-600">거래처</div>
                                    <div className="font-bold text-gray-800">{selectedReceivable.customerName}</div>
                                    <div className="text-xs text-gray-500 mt-1">발행일: {selectedReceivable.issueDate}</div>
                                    <div className="text-sm text-red-600 font-bold mt-2">
                                        미수금: {selectedReceivable.balance.toLocaleString()}원
                                    </div>
                                </div>

                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">입금일</label>
                                        <input
                                            type="date"
                                            value={paymentDate}
                                            onChange={(e) => setPaymentDate(e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                        />
                                    </div>

                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">입금액</label>
                                        <input
                                            type="number"
                                            value={paymentAmount}
                                            onChange={(e) => setPaymentAmount(e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                            placeholder="입금액 입력"
                                        />
                                    </div>

                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">입금 방법</label>
                                        <select
                                            value={paymentMethod}
                                            onChange={(e) => setPaymentMethod(e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                        >
                                            <option value="이체">이체</option>
                                            <option value="현금">현금</option>
                                            <option value="수표">수표</option>
                                            <option value="기타">기타</option>
                                        </select>
                                    </div>

                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">비고</label>
                                        <textarea
                                            value={paymentNote}
                                            onChange={(e) => setPaymentNote(e.target.value)}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                            rows={3}
                                            placeholder="비고 입력 (선택)"
                                        />
                                    </div>
                                </div>

                                <div className="flex gap-2 mt-6">
                                    <button
                                        onClick={handleSubmitPayment}
                                        className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium"
                                    >
                                        등록
                                    </button>
                                    <button
                                        onClick={() => setIsPaymentModalOpen(false)}
                                        className="flex-1 px-4 py-2 bg-gray-300 text-gray-700 rounded-lg hover:bg-gray-400 transition-colors font-medium"
                                    >
                                        취소
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default ReceivablesManagementPage;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import styled from 'styled-components';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faFileInvoiceDollar, faTimes, faHistory, faPencilAlt, faSyncAlt, faEdit, faTrash } from '@fortawesome/free-solid-svg-icons';
import Swal from 'sweetalert2';
import { format, startOfMonth } from 'date-fns';

import { receivableService, ReceivableLedger, ReceivablePayment } from '../../services/receivableService';
import { ReceivableSummaryCards } from '../tax/components/ReceivableSummaryCards';
import { ReceivableFilterBar } from '../tax/components/ReceivableFilterBar';
import { ReceivableTable } from '../tax/components/ReceivableTable';
import { BankMatchModal } from './modals/BankMatchModal';
import { ManualPaymentModal } from './modals/ManualPaymentModal';
import { ReceivableEditModal } from './modals/ReceivableEditModal';

// --- Styled Components (Matching TaxInvoiceLedgerPage) ---
const PageContainer = styled.div`
    padding: 0; /* DashboardLayout already has padding */
    height: 100%;
    display: flex;
    flex-direction: column;
    background-color: #f8f9fa;
`;

const PageHeader = styled.div`
    margin-bottom: 24px;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
`;

const Title = styled.h1`
    font-size: 28px;
    font-weight: 800;
    color: #1e293b;
    margin-bottom: 8px;
    letter-spacing: -0.5px;
    display: flex;
    align-items: center;
    gap: 12px;
`;

const Subtitle = styled.p`
    font-size: 14px;
    color: #64748b;
    font-weight: 500;
`;

const ContentArea = styled.div`
    flex: 1;
    display: flex;
    gap: 24px;
    overflow: hidden;
`;

const TableSection = styled.div`
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
`;

// Integrated Detail Panel
const DetailPanel = styled.div<{ $isOpen: boolean }>`
    width: ${props => props.$isOpen ? '380px' : '0px'};
    background: white;
    border-radius: 16px;
    border: ${props => props.$isOpen ? '1px solid #e2e8f0' : 'none'};
    box-shadow: -4px 0 20px rgba(0,0,0,0.05);
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    opacity: ${props => props.$isOpen ? 1 : 0};
    margin-left: 0;
`;

// --- Main Component ---
const ReceivablesManagerPage: React.FC = () => {
    // State
    const [receivables, setReceivables] = useState<ReceivableLedger[]>([]);
    const [loading, setLoading] = useState(false);

    // Filters
    const [startDate, setStartDate] = useState(format(startOfMonth(new Date()), 'yyyy-MM-dd'));
    const [endDate, setEndDate] = useState(format(new Date(), 'yyyy-MM-dd'));
    const [statusFilter, setStatusFilter] = useState<'전체' | '미수' | '완납'>('전체');
    const [searchQuery, setSearchQuery] = useState('');
    const [isFixed, setIsFixed] = useState(false);

    // Selection & Modals
    const [selectedId, setSelectedId] = useState<string | null>(null);
    const [isBankMatchModalOpen, setIsBankMatchModalOpen] = useState(false);
    const [isManualModalOpen, setIsManualModalOpen] = useState(false);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);

    // Fetch Data
    const fetchReceivables = useCallback(async () => {
        setLoading(true);
        try {
            const data = await receivableService.getReceivables();
            setReceivables(data);
        } catch (error) {
            console.error(error);
            Swal.fire('오류', '미수금 데이터를 불러오지 못했습니다.', 'error');
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchReceivables();
    }, []);

    // Derived State
    const filteredReceivables = useMemo(() => {
        return receivables.filter(r => {
            // Date Filter (Using Invoice Date)
            if (r.invoiceData.date < startDate || r.invoiceData.date > endDate) return false;

            // Status Filter
            if (statusFilter !== '전체') {
                if (statusFilter === '미수' && (r.status === '완납' || r.status === '과입금')) return false;
                if (statusFilter === '완납' && r.status !== '완납') return false;
            }

            // Search Query
            if (searchQuery) {
                const q = searchQuery.toLowerCase();
                return (
                    r.invoiceData.partnerName.toLowerCase().includes(q) ||
                    r.invoiceData.itemName.toLowerCase().includes(q)
                );
            }

            return true;
        });
    }, [receivables, startDate, endDate, statusFilter, searchQuery]);

    const summary = useMemo(() => {
        return filteredReceivables.reduce((acc, r) => ({
            totalReceivables: acc.totalReceivables + r.invoiceData.totalAmount,
            totalCollected: acc.totalCollected + r.totalPaidAmount,
            outstandingAmount: acc.outstandingAmount + r.outstandingAmount
        }), { totalReceivables: 0, totalCollected: 0, outstandingAmount: 0 });
    }, [filteredReceivables]);

    const selectedReceivable = useMemo(() =>
        receivables.find(r => r.id === selectedId),
        [receivables, selectedId]);

    // Handlers
    const handleRowClick = (record: ReceivableLedger) => {
        setSelectedId(prev => prev === record.id ? null : record.id);
    };

    const handleDeleteReceivable = async () => {
        if (!selectedReceivable) return;

        const confirm = await Swal.fire({
            title: '미수금 삭제',
            text: '정말 삭제하시겠습니까? 관련 입금 내역은 유지되거나 별도 정리가 필요할 수 있습니다.',
            icon: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#ef4444',
            confirmButtonText: '삭제'
        });

        if (confirm.isConfirmed) {
            try {
                await receivableService.deleteReceivable(selectedReceivable.id);
                Swal.fire('삭제됨', '삭제되었습니다.', 'success');
                setSelectedId(null);
                fetchReceivables();
            } catch (e) {
                console.error(e);
                Swal.fire('오류', '삭제 실패', 'error');
            }
        }
    };

    return (
        <PageContainer>
            <PageHeader>
                <div>
                    <Title>
                        <FontAwesomeIcon icon={faFileInvoiceDollar} className="text-emerald-600" />
                        미수금 관리
                    </Title>
                    <Subtitle>세금계산서 기반 미수 채권 관리 및 입금 매칭</Subtitle>
                </div>
            </PageHeader>

            {/* Summary Cards */}
            <ReceivableSummaryCards summary={summary} />

            {/* Filter Bar */}
            <ReceivableFilterBar
                startDate={startDate}
                endDate={endDate}
                onDateChange={(s, e) => { setStartDate(s); setEndDate(e); }}
                status={statusFilter}
                onStatusChange={setStatusFilter}
                search={searchQuery}
                onSearchChange={setSearchQuery}
                onRefresh={fetchReceivables}
                loading={loading}
                isFixed={isFixed}
                onFixedChange={setIsFixed}
            />

            <ContentArea>
                <TableSection>
                    <ReceivableTable
                        records={filteredReceivables}
                        loading={loading}
                        onRowClick={handleRowClick}
                        selectedId={selectedId}
                        isFixed={isFixed}
                    />
                </TableSection>

                {/* Detail Panel */}
                <DetailPanel $isOpen={!!selectedId}>
                    {selectedReceivable && (
                        <div className="flex flex-col h-full bg-white">
                            {/* Panel Header */}
                            <div className="p-5 border-b border-gray-100 bg-slate-50">
                                <div className="flex justify-between items-start mb-2">
                                    <h3 className="font-bold text-lg text-slate-800">{selectedReceivable.invoiceData.partnerName}</h3>
                                    <div className="flex gap-2">
                                        <button
                                            onClick={() => setIsEditModalOpen(true)}
                                            className="text-slate-400 hover:text-blue-600 transition p-1"
                                            title="수정"
                                        >
                                            <FontAwesomeIcon icon={faEdit} />
                                        </button>
                                        <button
                                            onClick={handleDeleteReceivable}
                                            className="text-slate-400 hover:text-red-600 transition p-1"
                                            title="삭제"
                                        >
                                            <FontAwesomeIcon icon={faTrash} />
                                        </button>
                                        <button
                                            onClick={() => setSelectedId(null)}
                                            className="text-slate-400 hover:text-slate-600 transition p-1 ml-2"
                                            title="닫기"
                                        >
                                            <FontAwesomeIcon icon={faTimes} />
                                        </button>
                                    </div>
                                </div>
                                <p className="text-slate-500 text-sm mb-4 truncate">{selectedReceivable.invoiceData.itemName}</p>

                                <div className="bg-white rounded-lg border border-gray-200 p-3 shadow-sm">
                                    <div className="flex justify-between text-sm mb-1">
                                        <span className="text-slate-500">청구금액</span>
                                        <span className="font-medium text-slate-800">{selectedReceivable.invoiceData.totalAmount.toLocaleString()}원</span>
                                    </div>
                                    <div className="flex justify-between text-base font-bold text-red-600">
                                        <span>미수잔액</span>
                                        <span>{selectedReceivable.outstandingAmount.toLocaleString()}원</span>
                                    </div>
                                </div>
                            </div>

                            {/* Actions */}
                            <div className="p-4 grid grid-cols-2 gap-3 border-b border-gray-100">
                                <button
                                    onClick={() => setIsBankMatchModalOpen(true)}
                                    className="p-3 bg-indigo-50 text-indigo-700 rounded-xl hover:bg-indigo-100 font-bold text-sm transition flex flex-col items-center gap-2 group"
                                >
                                    <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center group-hover:bg-white transition">
                                        <FontAwesomeIcon icon={faHistory} />
                                    </div>
                                    계좌조회 매칭
                                </button>
                                <button
                                    onClick={() => setIsManualModalOpen(true)}
                                    className="p-3 bg-orange-50 text-orange-700 rounded-xl hover:bg-orange-100 font-bold text-sm transition flex flex-col items-center gap-2 group"
                                >
                                    <div className="w-8 h-8 rounded-full bg-orange-100 flex items-center justify-center group-hover:bg-white transition">
                                        <FontAwesomeIcon icon={faPencilAlt} />
                                    </div>
                                    직접 입력
                                </button>
                            </div>

                            {/* History List */}
                            <div className="flex-1 overflow-auto bg-white">
                                <PaymentHistoryList
                                    key={selectedReceivable?.id}
                                    receivableId={selectedReceivable.id}
                                />
                            </div>
                        </div>
                    )}
                </DetailPanel>
            </ContentArea>

            {/* MODALS */}
            {selectedReceivable && isBankMatchModalOpen && (
                <BankMatchModal
                    isOpen={isBankMatchModalOpen}
                    onClose={() => setIsBankMatchModalOpen(false)}
                    receivable={selectedReceivable}
                    onSuccess={() => {
                        setIsBankMatchModalOpen(false);
                        fetchReceivables();
                    }}
                />
            )}

            {selectedReceivable && isManualModalOpen && (
                <ManualPaymentModal
                    isOpen={isManualModalOpen}
                    onClose={() => setIsManualModalOpen(false)}
                    receivable={selectedReceivable}
                    onSuccess={() => {
                        setIsManualModalOpen(false);
                        fetchReceivables();
                    }}
                />
            )}

            {selectedReceivable && isEditModalOpen && (
                <ReceivableEditModal
                    isOpen={isEditModalOpen}
                    onClose={() => setIsEditModalOpen(false)}
                    receivable={selectedReceivable}
                    onSuccess={() => {
                        setIsEditModalOpen(false);
                        fetchReceivables();
                    }}
                />
            )}
        </PageContainer>
    );
};

// Internal Sub-component for Payment History
const PaymentHistoryList: React.FC<{ receivableId: string }> = ({ receivableId }) => {
    const [payments, setPayments] = useState<ReceivablePayment[]>([]);
    const [refreshTick, setRefreshTick] = useState<number>(0);

    const loadPayments = async () => {
        try {
            const data = await receivableService.getPayments(receivableId);
            setPayments(data);
        } catch (error: any) {
            if (error.code === 'failed-precondition' && error.message.includes('index')) {
                console.warn('Index building for payments');
            } else {
                console.error('Failed to load payments:', error);
            }
            setPayments([]);
        }
    };

    useEffect(() => {
        loadPayments();
    }, [receivableId, refreshTick]); // re-load when ID changes or refreshTick changes

    const handleDelete = async (payment: ReceivablePayment) => {
        const confirm = await Swal.fire({
            title: '입금 취소',
            text: '이 입금 내역을 삭제하고 미수금액을 복구하시겠습니까?',
            icon: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#ef4444',
            confirmButtonText: '삭제'
        });

        if (confirm.isConfirmed) {
            try {
                await receivableService.deletePayment(payment.id, payment.receivableId, payment.amount);
                Swal.fire({
                    title: '삭제됨',
                    text: '입금 내역이 취소되었습니다.',
                    icon: 'success',
                    timer: 1000,
                    showConfirmButton: false
                });
                // Force update to reload payments
                setRefreshTick(prev => prev + 1);
            } catch (e) {
                Swal.fire('오류', '삭제 실패', 'error');
            }
        }
    };

    return (
        <div className="flex flex-col h-full">
            <div className="flex justify-between items-center mb-3 px-4 pt-4">
                <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">입금 처리 내역</h4>
                <button
                    onClick={() => setRefreshTick(prev => prev + 1)}
                    className="text-xs text-slate-400 hover:text-emerald-600"
                    title="새로고침"
                >
                    <FontAwesomeIcon icon={faSyncAlt} />
                </button>
            </div>
            <div className="flex-1 overflow-auto px-4 pb-4">
                {payments.length === 0 ? (
                    <div className="text-center text-sm text-gray-400 py-4">
                        <div className="italic">입금 내역이 없습니다.</div>
                    </div>
                ) : (
                    <div className="space-y-3">
                        {payments.map(p => (
                            <div key={p.id} className="border border-gray-100 rounded-lg p-3 shadow-sm bg-white hover:border-emerald-200 transition">
                                <div className="flex justify-between items-start mb-2">
                                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${p.type === 'BANK_MATCH' ? 'bg-indigo-100 text-indigo-700' : 'bg-orange-100 text-orange-700'}`}>
                                        {p.method === 'BankMatch' ? '계좌조회' :
                                            p.method === 'Cash' ? '현금' :
