};
const normalizePartnerMatchKey = (value: unknown) => normalizeText(value)
    .toLowerCase()
    .replace(/\(주\)|㈜|주식회사/g, '')
    .replace(/\s+/g, '')
    .replace(/[^0-9a-z가-힣]/g, '');
const escapeHtml = (value: string) => value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
