            isInvoiceEntry(entry) &&
            entries.some((item) => (
                Boolean(item.id) &&
                isPaymentEntry(item) &&
                item.matchedEntryId === entry.id &&
                !selectedIdSet.has(item.id!)
            ))
        ));

        const blockedInvoiceIdSet = new Set(
