interface BankMatchModalProps {
    isOpen: boolean;
    onClose: () => void;
    receivable: ReceivableLedger;
    onSuccess: () => void;
}

export const BankMatchModal: React.FC<BankMatchModalProps> = ({ isOpen, onClose, receivable, onSuccess }) => {
    const [accounts, setAccounts] = useState<BankAccount[]>([]);
    const [selectedAccount, setSelectedAccount] = useState<string>('');
    const [searchMonth, setSearchMonth] = useState(format(new Date(), 'yyyy-MM'));
    const [deposits, setDeposits] = useState<BankAccountLog[]>([]);
    const [selectedDeposit, setSelectedDeposit] = useState<BankAccountLog | null>(null);
    const [matchAmount, setMatchAmount] = useState<number>(0);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (isOpen) {
            barobillAccountService.getBankAccountList().then(list => {
                setAccounts(list);
                if (list.length > 0 && !selectedAccount) setSelectedAccount(list[0].accountNum);
            });
        }
    }, [isOpen]);

    const fetchHistory = async () => {
        if (!selectedAccount) return;
        setLoading(true);
        // Clear previous selection reset
        setSelectedDeposit(null);

        try {
            const start = `${searchMonth}-01`.replace(/-/g, '');
            const [y, m] = searchMonth.split('-').map(Number);
            const lastDay = new Date(y, m, 0).getDate();
            const end = `${searchMonth}-${lastDay}`.replace(/-/g, '');

            // Fetch all pages logic
            let allLogs: BankAccountLog[] = [];
            let page = 1;
            let maxPage = 1;

            do {
                const res = await barobillAccountService.getBankAccountHistory(selectedAccount, start, end, page);
                allLogs = [...allLogs, ...res.logs];
                maxPage = res?.maxPageNum || page; // Safety check
                page++;
            } while (page <= maxPage && page <= 50); // Safety limit 50 pages

            // Filter only deposits (Deposit > 0)
            const dep = allLogs.filter(l => Number(l.Deposit) > 0);
            setDeposits(dep);
        } catch (e) {
            console.error(e);
            Swal.fire('오류', '계좌 내역 조회 실패', 'error');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (selectedAccount && isOpen) fetchHistory();
    }, [selectedAccount, searchMonth, isOpen]);

    useEffect(() => {
        if (selectedDeposit) {
            const depositAmt = Number(selectedDeposit.Deposit);
            // Default match amount is MIN(Deposit, Outstanding)
            setMatchAmount(Math.min(depositAmt, receivable.outstandingAmount));
        } else {
            setMatchAmount(0);
        }
    }, [selectedDeposit, receivable]);

    const handleConfirm = async () => {
        if (!selectedDeposit) return;
        try {
            await receivableService.addPayment(receivable.id, {
                receivableId: receivable.id,
                type: 'BANK_MATCH',
                amount: matchAmount,
                paymentDate: selectedDeposit.TransDT.substring(0, 8).replace(/(\d{4})(\d{2})(\d{2})/, '$1-$2-$3'),
                bankTxId: `${selectedDeposit.TransDT}-${selectedDeposit.Balance}-${selectedDeposit.Identity}`, // More unique ID
                bankSender: selectedDeposit.TransRemark1 || selectedDeposit.TransRemark2,
                method: 'BankMatch',
            });
            Swal.fire({
                title: '매칭 완료',
                text: '성공적으로 매칭되었습니다.',
                icon: 'success',
                timer: 1500,
                showConfirmButton: false
            });
            onSuccess();
        } catch (e) {
            console.error(e);
            Swal.fire('오류', '매칭 실패', 'error');
        }
    };

    if (!isOpen) return null;

    return (
        <ModalOverlay onClick={onClose}>
            <ModalContent onClick={e => e.stopPropagation()}>
                <ModalHeader>
                    <HeaderTitle>
                        <FontAwesomeIcon icon={faBuildingColumns} className="text-blue-600" />
                        입금 내역 매칭
                    </HeaderTitle>
                    <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition">
                        <FontAwesomeIcon icon={faTimes} size="lg" />
                    </button>
                </ModalHeader>

                <ModalBody>
                    {/* Filters */}
                    <FilterSection>
                        <StyledSelect
                            value={selectedAccount}
                            onChange={e => setSelectedAccount(e.target.value)}
                        >
                            {accounts.map(acc => (
                                <option key={acc.accountNum} value={acc.accountNum}>
                                    {acc.bank} {acc.accountNum} ({acc.alias || '별칭없음'})
                                </option>
                            ))}
                        </StyledSelect>
                        <StyledInput
                            type="month"
                            value={searchMonth}
                            onChange={e => setSearchMonth(e.target.value)}
                        />
                        <button
                            onClick={fetchHistory}
                            className="bg-slate-800 text-white px-4 py-2 rounded-lg font-medium hover:bg-slate-700 transition flex items-center gap-2"
                        >
                            <FontAwesomeIcon icon={faSearch} />
                            조회
                        </button>
                    </FilterSection>

                    {/* Table */}
                    <TableContainer>
                        <Table>
                            <thead>
                                <tr>
                                    <Th>거래일시</Th>
                                    <Th>적요 (보낸분)</Th>
                                    <Th style={{ textAlign: 'right' }}>입금액</Th>
                                    <Th style={{ textAlign: 'center', width: '60px' }}>선택</Th>
                                </tr>
                            </thead>
                            <tbody>
                                {loading ? (
                                    <tr>
                                        <Td colSpan={4} style={{ textAlign: 'center', padding: '40px', color: '#94a3b8' }}>
                                            데이터를 불러오는 중입니다...
                                        </Td>
                                    </tr>
                                ) : deposits.length === 0 ? (
                                    <tr>
                                        <Td colSpan={4} style={{ textAlign: 'center', padding: '40px', color: '#94a3b8' }}>
                                            조회된 입금 내역이 없습니다.
                                        </Td>
                                    </tr>
                                ) : (
                                    deposits.map((log, idx) => (
                                        <Tr
                                            key={idx}
                                            $selected={selectedDeposit === log}
                                            onClick={() => setSelectedDeposit(log)}
                                        >
                                            <Td>{log.TransDT.substring(0, 10)} <span className="text-xs text-slate-400">{log.TransDT.substring(11, 19)}</span></Td>
                                            <Td>
                                                <div className="font-medium text-slate-700">{log.TransRemark1}</div>
                                                {log.TransRemark2 && <div className="text-xs text-slate-500">{log.TransRemark2}</div>}
                                            </Td>
                                            <Td style={{ textAlign: 'right' }}>
                                                <Amount>{Number(log.Deposit).toLocaleString()}</Amount>
                                            </Td>
                                            <Td style={{ textAlign: 'center' }}>
                                                {selectedDeposit === log && (
                                                    <FontAwesomeIcon icon={faCheckCircle} className="text-blue-600 text-lg" />
                                                )}
                                            </Td>
                                        </Tr>
                                    ))
                                )}
                            </tbody>
                        </Table>
                    </TableContainer>
                </ModalBody>

                <ModalFooter>
                    <div className="flex flex-col">
                        <span className="text-xs text-slate-500 font-medium">매칭 대상: {receivable.invoiceData.partnerName}</span>
                        <div className="text-sm font-bold text-slate-700">
                            미수잔액: <span className="text-red-500">{receivable.outstandingAmount.toLocaleString()}원</span>
                        </div>
                    </div>

                    <div className="flex items-center gap-4">
                        {selectedDeposit && (
                            <div className="text-right mr-4 animate-in slide-in-from-right-4 fade-in">
                                <span className="text-xs text-slate-500 block">설정할 입금액</span>
                                <input
                                    type="number"
                                    className="font-bold text-blue-600 border-b border-blue-200 focus:border-blue-500 outline-none w-32 text-right bg-transparent"
                                    value={matchAmount}
                                    onChange={e => setMatchAmount(Number(e.target.value))}
                                />
                                <span className="text-sm font-bold text-blue-600 ml-1">원</span>
                            </div>
                        )}
                        <div className="flex gap-2">
                            <button
                                onClick={onClose}
                                className="px-5 py-2.5 rounded-lg border border-slate-300 text-slate-600 font-medium hover:bg-slate-50 transition"
                            >
                                취소
                            </button>
                            <MatchButton
                                onClick={handleConfirm}
                                disabled={!selectedDeposit || matchAmount <= 0}
                            >
                                <FontAwesomeIcon icon={faCheckCircle} className="mr-2" />
                                매칭 확정
                            </MatchButton>
                        </div>
                    </div>
                </ModalFooter>
            </ModalContent>
        </ModalOverlay>
    );
};

import { toast } from '../utils/swal';
import {
    listAllAccommodationAssignments,
    createAccommodationAssignment,
    updateAccommodationAssignment,
    deleteAccommodationAssignment,
    listAllWorkers,
    listAllTeams,
    listAllAccommodations,
} from './firestoreCrudCompat';
import { Timestamp } from '../types/timestamp';
import { z } from 'zod';
import { format, parseISO, subDays } from 'date-fns';
import {
    AccommodationAssignment,
    AccommodationAssignmentSource,
    AccommodationAssignmentStatus
} from '../types/accommodationAssignment';

const isUuidString = (value: string) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);

const toFirestoreTimestamp = (value?: unknown): Timestamp | undefined => {
    if (!value) return undefined;
    if (value instanceof Timestamp) return value;
    if (typeof (value as any)?.toDate === 'function') {
        try {
            return Timestamp.fromDate((value as any).toDate());
        } catch {
            // ignore
        }
    }
    if (typeof value === 'object') {
        const obj = value as any;
        const seconds = obj?._seconds ?? obj?.seconds;
        const nanos = obj?._nanoseconds ?? obj?.nanoseconds ?? 0;
        if (typeof seconds === 'number' && Number.isFinite(seconds)) {
            return Timestamp.fromMillis(seconds * 1000 + Math.floor((typeof nanos === 'number' ? nanos : 0) / 1_000_000));
        }
    }
    try {
        return Timestamp.fromDate(new Date(String(value)));
    } catch {
        return undefined;
    }
};

let dcWorkersLoaded = false;
let dcTeamsLoaded = false;
let dcAccommodationsLoaded = false;
let dcAssignmentsLoaded = false;

const dcWorkerLegacyIdToUuid = new Map<string, string>();
const dcTeamLegacyIdToUuid = new Map<string, string>();
const dcAccommodationLegacyIdToUuid = new Map<string, string>();
const dcAssignmentLegacyIdToUuid = new Map<string, string>();

let dcAssignmentsCache: any[] = [];

const loadDcWorkers = async (): Promise<void> => {
    if (dcWorkersLoaded) return;
    const res = await listAllWorkers();
    const rows = (res as any)?.data?.workers ?? [];
    dcWorkerLegacyIdToUuid.clear();
    rows.forEach((w: any) => {
        const id = w?.id ? String(w.id) : '';
        const legacyId = w?.legacyId ? String(w.legacyId) : '';
        if (id) dcWorkerLegacyIdToUuid.set(id, id);
        if (legacyId) dcWorkerLegacyIdToUuid.set(legacyId, id);
    });
    dcWorkersLoaded = true;
};

const loadDcTeams = async (): Promise<void> => {
    if (dcTeamsLoaded) return;
    const res = await listAllTeams();
    const rows = (res as any)?.data?.teams ?? [];
    dcTeamLegacyIdToUuid.clear();
    rows.forEach((t: any) => {
        const id = t?.id ? String(t.id) : '';
        const legacyId = t?.legacyId ? String(t.legacyId) : '';
        if (id) dcTeamLegacyIdToUuid.set(id, id);
        if (legacyId) dcTeamLegacyIdToUuid.set(legacyId, id);
    });
    dcTeamsLoaded = true;
};

const loadDcAccommodations = async (): Promise<void> => {
    if (dcAccommodationsLoaded) return;
    const res = await listAllAccommodations();
    const rows = (res as any)?.data?.accommodations ?? [];
    dcAccommodationLegacyIdToUuid.clear();
    rows.forEach((a: any) => {
        const id = a?.id ? String(a.id) : '';
        const legacyId = a?.legacyId ? String(a.legacyId) : '';
        if (id) dcAccommodationLegacyIdToUuid.set(id, id);
        if (legacyId) dcAccommodationLegacyIdToUuid.set(legacyId, id);
    });
    dcAccommodationsLoaded = true;
};

const loadDcAssignments = async (): Promise<void> => {
    if (dcAssignmentsLoaded) return;
    const res = await listAllAccommodationAssignments();
    const rows = (res as any)?.data?.accommodationAssignments ?? [];

    dcAssignmentsCache = rows;
    dcAssignmentLegacyIdToUuid.clear();
    rows.forEach((a: any) => {
        const id = a?.id ? String(a.id) : '';
        const legacyId = a?.legacyId ? String(a.legacyId) : '';
        if (id) dcAssignmentLegacyIdToUuid.set(id, id);
        if (legacyId) dcAssignmentLegacyIdToUuid.set(legacyId, id);
    });
    dcAssignmentsLoaded = true;
};

const resolveWorkerUuid = async (id: string): Promise<string | null> => {
    const raw = id ? String(id) : '';
    if (!raw) return null;
    if (isUuidString(raw)) return raw;
    await loadDcWorkers();
    return dcWorkerLegacyIdToUuid.get(raw) ?? null;
};

const resolveTeamUuid = async (id: string | undefined): Promise<string | null> => {
    const raw = id ? String(id) : '';
    if (!raw) return null;
    if (isUuidString(raw)) return raw;
    await loadDcTeams();
    return dcTeamLegacyIdToUuid.get(raw) ?? null;
};

const resolveAccommodationUuid = async (id: string): Promise<string | null> => {
    const raw = id ? String(id) : '';
    if (!raw) return null;
    if (isUuidString(raw)) return raw;
    await loadDcAccommodations();
    return dcAccommodationLegacyIdToUuid.get(raw) ?? null;
};

const resolveAssignmentUuid = async (id: string): Promise<string | null> => {
    const raw = id ? String(id) : '';
    if (!raw) return null;
    if (isUuidString(raw)) return raw;
    await loadDcAssignments();
    const found = dcAssignmentLegacyIdToUuid.get(raw);
    if (found) return found;

    dcAssignmentsLoaded = false;
    await loadDcAssignments();
    return dcAssignmentLegacyIdToUuid.get(raw) ?? null;
};

const normalizeStatus = (value?: string | null): AccommodationAssignmentStatus => {
    return value === 'ended' ? 'ended' : 'active';
};

const normalizeSource = (value?: string | null): AccommodationAssignmentSource | undefined => {
    if (value === 'team' || value === 'worker') return value;
    return undefined;
};

const mapAssignmentRow = (row: any): AccommodationAssignment => {
    const id = row?.legacyId ? String(row.legacyId) : String(row?.id ?? '');
    const workerId = row?.worker?.legacyId
        ? String(row.worker.legacyId)
        : (row?.worker?.id ? String(row.worker.id) : (row?.workerId ? String(row.workerId) : ''));
    const teamId = row?.team?.legacyId
        ? String(row.team.legacyId)
        : (row?.team?.id ? String(row.team.id) : (row?.teamId ? String(row.teamId) : undefined));
    const accommodationId = row?.accommodation?.id
        ? String(row.accommodation.id)
        : (row?.accommodation?.legacyId ? String(row.accommodation.legacyId) : (row?.accommodationId ? String(row.accommodationId) : ''));

    return {
        id,
        workerId,
        workerName: row?.workerName ? String(row.workerName) : (row?.worker?.name ? String(row.worker.name) : undefined),
        teamId,
        teamName: row?.teamName ? String(row.teamName) : (row?.team?.name ? String(row.team.name) : undefined),
        accommodationId,
        accommodationName: row?.accommodationName ? String(row.accommodationName) : (row?.accommodation?.name ? String(row.accommodation.name) : undefined),
        status: normalizeStatus(row?.status ?? null),
        startDate: String(row?.startDate ?? ''),
        endDate: row?.endDate ? String(row.endDate) : undefined,
        source: normalizeSource(row?.source ?? null),
        memo: row?.memo ? String(row.memo) : undefined,
        createdAt: toFirestoreTimestamp(row?.createdAt),
        updatedAt: toFirestoreTimestamp(row?.updatedAt)
    };
};

const omitUndefined = (value: Record<string, unknown>): Record<string, unknown> => {
    const entries = Object.entries(value).filter(([, v]) => v !== undefined);
    return Object.fromEntries(entries);
};

const DateStringSchema = z.string().regex(/^\d{4}-\d{2}-\d{2}$/, '?좎쭨 ?뺤떇? YYYY-MM-DD ?댁뼱???⑸땲??');

// Status and Source are validated as strings, type narrowing happens at runtime
const StatusSchema = z.string().refine(
    (val): val is AccommodationAssignmentStatus => val === 'active' || val === 'ended',
    { message: 'status??active ?먮뒗 ended?댁뼱???⑸땲??' }
);

const SourceSchema = z.string().refine(
    (val): val is AccommodationAssignmentSource => val === 'team' || val === 'worker',
    { message: 'source??team ?먮뒗 worker?댁뼱???⑸땲??' }
);

const AssignmentSchema = z.object({
    workerId: z.string().min(1),
    workerName: z.string().optional(),

    teamId: z.string().optional(),
    teamName: z.string().optional(),

    accommodationId: z.string().min(1),
    accommodationName: z.string().optional(),

    status: StatusSchema.default('active'),

    startDate: DateStringSchema,
    endDate: DateStringSchema.optional(),

    source: SourceSchema.optional(),
    memo: z.string().optional()
});

type AssignmentInput = z.infer<typeof AssignmentSchema>;

type AssignmentUpdate = Partial<AssignmentInput>;

const toMillis = (ts?: Timestamp): number => (ts ? ts.toMillis() : 0);

const isActive = (item: AccommodationAssignment): boolean => {
    return (item.status || 'active') === 'active' && !item.endDate;
};

const buildEndDateAsDayBefore = (startDate: string): string => {
    const dayBefore = subDays(parseISO(startDate), 1);
    return format(dayBefore, 'yyyy-MM-dd');
};

export const accommodationAssignmentService = {
    buildEndDateAsDayBefore,

    addAssignment: async (
        assignment: Omit<AccommodationAssignment, 'id' | 'createdAt' | 'updatedAt'>
    ): Promise<string> => {
        const parsed = AssignmentSchema.parse({
            ...assignment,
            status: assignment.status ?? 'active'
        });

        const workerUuid = await resolveWorkerUuid(String(parsed.workerId));
        if (!workerUuid) throw new Error('?묒뾽?먮? 李얠쓣 ???놁뒿?덈떎.');
        const teamUuid = parsed.teamId ? await resolveTeamUuid(String(parsed.teamId)) : null;
        const accommodationUuid = await resolveAccommodationUuid(String(parsed.accommodationId));
        if (!accommodationUuid) throw new Error('?숈냼瑜?李얠쓣 ???놁뒿?덈떎.');

        const legacyId = (assignment as any)?.legacyId;
        const res = await createAccommodationAssignment({
            legacyId: legacyId ? String(legacyId) : null,
            workerId: workerUuid,
            teamId: teamUuid ?? null,
            accommodationId: accommodationUuid,
            workerName: parsed.workerName ?? null,
            teamName: parsed.teamName ?? null,
            accommodationName: parsed.accommodationName ?? null,
            status: parsed.status ?? 'active',
            startDate: parsed.startDate,
            endDate: parsed.endDate ?? null,
            source: parsed.source ?? null,
            memo: parsed.memo ?? null
        } as any);

        const id = (res as any)?.data?.accommodationAssignment_insert?.id ? String((res as any).data.accommodationAssignment_insert.id) : '';
        if (!id) throw new Error('Failed to create accommodation assignment');

        dcAssignmentsLoaded = false;
        toast.saved('?숈냼 諛곗젙', 1);
        return id;
    },

    addAssignmentsBatch: async (
        assignments: Array<Omit<AccommodationAssignment, 'id' | 'createdAt' | 'updatedAt'>>
    ): Promise<string[]> => {
        if (assignments.length === 0) return [];

        const parsed = assignments
            .map((a) =>
                AssignmentSchema.parse({
                    ...a,
                    status: a.status ?? 'active'
                })
            )
            .map((item) => omitUndefined(item as unknown as Record<string, unknown>));

        const ids: string[] = [];

        // Preload FK maps once
        const responses = await Promise.all([
            listAllWorkers(),
            listAllTeams(),
            listAllAccommodations()
        ]);

        const chunkSize = 50;
        for (let i = 0; i < parsed.length; i += chunkSize) {
            const chunk = parsed.slice(i, i + chunkSize);
            const results = await Promise.all(chunk.map(async (item) => {
                const workerUuid = await resolveWorkerUuid(String(item.workerId));
                if (!workerUuid) return null;
                const teamUuid = item.teamId ? await resolveTeamUuid(String(item.teamId)) : null;
                const accommodationUuid = await resolveAccommodationUuid(String(item.accommodationId));
                if (!accommodationUuid) return null;

                const res = await createAccommodationAssignment({
                    legacyId: null,
                    workerId: workerUuid,
                    teamId: teamUuid ?? null,
                    accommodationId: accommodationUuid,
                    workerName: item.workerName ?? null,
                    teamName: item.teamName ?? null,
                    accommodationName: item.accommodationName ?? null,
                    status: item.status ?? 'active',
                    startDate: item.startDate,
                    endDate: item.endDate ?? null,
                    source: item.source ?? null,
                    memo: item.memo ?? null
                } as any);

                const id = (res as any)?.data?.accommodationAssignment_insert?.id ? String((res as any).data.accommodationAssignment_insert.id) : '';
                return id || null;
            }));

            results.forEach((id) => {
                if (id) ids.push(id);
            });
        }

        dcAssignmentsLoaded = false;
        toast.saved('?숈냼 諛곗젙', assignments.length);
        return ids;
    },

    updateAssignment: async (id: string, updates: AssignmentUpdate): Promise<void> => {
        if (!id) throw new Error('諛곗젙 ID媛 ?꾩슂?⑸땲??');

        const parsedUpdates = AssignmentSchema.partial().parse(updates);

        const uuid = await resolveAssignmentUuid(id);
        if (!uuid) throw new Error('諛곗젙??李얠쓣 ???놁뒿?덈떎.');

        const data = omitUndefined(parsedUpdates as unknown as Record<string, unknown>);
        if (Object.keys(data).length === 0) return;

        const vars: any = { id: uuid };
        if (data.workerId !== undefined) vars.workerId = data.workerId ? (await resolveWorkerUuid(String(data.workerId))) : null;
        if (data.workerName !== undefined) vars.workerName = data.workerName ?? null;
        if (data.teamId !== undefined) vars.teamId = data.teamId ? (await resolveTeamUuid(String(data.teamId))) : null;
        if (data.teamName !== undefined) vars.teamName = data.teamName ?? null;
        if (data.accommodationId !== undefined) vars.accommodationId = data.accommodationId ? (await resolveAccommodationUuid(String(data.accommodationId))) : null;
        if (data.accommodationName !== undefined) vars.accommodationName = data.accommodationName ?? null;
        if (data.status !== undefined) vars.status = data.status ?? null;
        if (data.startDate !== undefined) vars.startDate = data.startDate ?? null;
        if (data.endDate !== undefined) vars.endDate = data.endDate ?? null;
        if (data.source !== undefined) vars.source = data.source ?? null;
        if (data.memo !== undefined) vars.memo = data.memo ?? null;

        await updateAccommodationAssignment(vars as any);

        dcAssignmentsLoaded = false;
        toast.updated('?숈냼 諛곗젙');
    },

    endAssignment: async (id: string, endDate: string): Promise<void> => {
        if (!id) throw new Error('諛곗젙 ID媛 ?꾩슂?⑸땲??');
        const parsedEndDate = DateStringSchema.parse(endDate);

        const uuid = await resolveAssignmentUuid(id);
        if (!uuid) throw new Error('諛곗젙??李얠쓣 ???놁뒿?덈떎.');
        await updateAccommodationAssignment({ id: uuid, status: 'ended', endDate: parsedEndDate } as any);
        dcAssignmentsLoaded = false;
        toast.updated('?숈냼 諛곗젙');
    },

    endAssignmentsBatch: async (ids: string[], endDate: string): Promise<void> => {
        if (ids.length === 0) return;
        const parsedEndDate = DateStringSchema.parse(endDate);

        const chunkSize = 50;
        for (let i = 0; i < ids.length; i += chunkSize) {
            const chunk = ids.slice(i, i + chunkSize);
            await Promise.all(chunk.map(async (id) => {
                const uuid = await resolveAssignmentUuid(id);
                if (!uuid) return;
                await updateAccommodationAssignment({ id: uuid, status: 'ended', endDate: parsedEndDate } as any);
            }));
        }

        dcAssignmentsLoaded = false;
        toast.updated('?숈냼 諛곗젙');
    },

    deleteAssignment: async (id: string): Promise<void> => {
        if (!id) throw new Error('諛곗젙 ID媛 ?꾩슂?⑸땲??');
        const uuid = await resolveAssignmentUuid(id);
        if (!uuid) return;
        await deleteAccommodationAssignment({ id: uuid } as any);
        dcAssignmentsLoaded = false;
        toast.deleted('?숈냼 諛곗젙', 1);
    },

    getAssignment: async (id: string): Promise<AccommodationAssignment | null> => {
        if (!id) return null;
        await loadDcAssignments();
        const raw = String(id);
        const row = dcAssignmentsCache.find((a: any) => String(a?.id ?? '') === raw || (a?.legacyId && String(a.legacyId) === raw));
        if (!row) return null;
        return mapAssignmentRow(row);
    },

    getAssignmentsByWorker: async (workerId: string): Promise<AccommodationAssignment[]> => {
        await loadDcAssignments();
        const raw = workerId ? String(workerId) : '';
        const uuid = await resolveWorkerUuid(raw);

        return dcAssignmentsCache
            .filter((row: any) => {
                const rowWorkerId = row?.worker?.id ? String(row.worker.id) : '';
                const rowWorkerLegacyId = row?.worker?.legacyId ? String(row.worker.legacyId) : '';
                if (raw && (rowWorkerLegacyId === raw || rowWorkerId === raw)) return true;
                return uuid ? rowWorkerId === uuid : false;
            })
            .map(mapAssignmentRow)
            .sort((a, b) => toMillis(b.createdAt as Timestamp | undefined) - toMillis(a.createdAt as Timestamp | undefined));
    },

    getActiveAssignmentsByWorker: async (workerId: string): Promise<AccommodationAssignment[]> => {
        const items = await accommodationAssignmentService.getAssignmentsByWorker(workerId);
        return items.filter(isActive);
    },

    getAssignmentsByAccommodation: async (accommodationId: string): Promise<AccommodationAssignment[]> => {
        await loadDcAssignments();
        const raw = accommodationId ? String(accommodationId) : '';
        const uuid = await resolveAccommodationUuid(raw);

        return dcAssignmentsCache
            .filter((row: any) => {
                const rowId = row?.accommodation?.id
                    ? String(row.accommodation.id)
                    : (row?.accommodationId ? String(row.accommodationId) : '');
                const rowLegacyId = row?.accommodation?.legacyId ? String(row.accommodation.legacyId) : '';
                const rowName = row?.accommodationName
                    ? String(row.accommodationName)
                    : (row?.accommodation?.name ? String(row.accommodation.name) : '');
                if (raw && (rowLegacyId === raw || rowId === raw || rowName === raw)) return true;
                return uuid ? rowId === uuid : false;
            })
            .map(mapAssignmentRow)
            .sort((a, b) => toMillis(b.createdAt as Timestamp | undefined) - toMillis(a.createdAt as Timestamp | undefined));
    },

    getActiveAssignmentsByAccommodation: async (accommodationId: string): Promise<AccommodationAssignment[]> => {
        const items = await accommodationAssignmentService.getAssignmentsByAccommodation(accommodationId);
        return items.filter(isActive);
    },

    getAssignmentsByTeam: async (teamId: string): Promise<AccommodationAssignment[]> => {
        await loadDcAssignments();
        const raw = teamId ? String(teamId) : '';
        const uuid = await resolveTeamUuid(raw);

        return dcAssignmentsCache
            .filter((row: any) => {
                const rowTeamId = row?.team?.id
                    ? String(row.team.id)
                    : (row?.teamId ? String(row.teamId) : '');
                const rowTeamLegacyId = row?.team?.legacyId ? String(row.team.legacyId) : '';
                const rowTeamName = row?.teamName ? String(row.teamName) : (row?.team?.name ? String(row.team.name) : '');
                if (raw && (rowTeamLegacyId === raw || rowTeamId === raw || rowTeamName === raw)) return true;
                return uuid ? rowTeamId === uuid : false;
            })
            .map(mapAssignmentRow)
            .sort((a, b) => toMillis(b.createdAt as Timestamp | undefined) - toMillis(a.createdAt as Timestamp | undefined));
    },

    getActiveAssignmentsByTeam: async (teamId: string): Promise<AccommodationAssignment[]> => {
        const items = await accommodationAssignmentService.getAssignmentsByTeam(teamId);
        return items.filter(isActive);
    },

    getAllAssignments: async (): Promise<AccommodationAssignment[]> => {
        await loadDcAssignments();
        return dcAssignmentsCache
            .map(mapAssignmentRow)
            .sort((a, b) => toMillis(b.createdAt as Timestamp | undefined) - toMillis(a.createdAt as Timestamp | undefined));
    }
};

import { db } from '../config/firebase';
import {
    collection,
    doc,
    getDoc,
    getDocs,
    setDoc,
    deleteDoc,
    query,
    where,
    orderBy,
    Timestamp,
    limit as firestoreLimit
} from 'firebase/firestore';
import { createConverter } from '../utils/firestoreConverter';
import { accommodationSchema, utilityRecordSchema } from '../types/zod/accommodationSchema';
import { Accommodation, UtilityRecord } from '../types/accommodation';

const ACCOMMODATION_COLLECTION = 'accommodations';
const UTILITY_RECORD_COLLECTION = 'accommodationUtilityRecords';
const ASSIGNMENT_COLLECTION = 'accommodationAssignments';

export const accommodationFirestoreService = {
    /**
     * 숙소 목록 조회
     */
    listAccommodations: async (status?: 'active' | 'inactive') => {
        let q = query(collection(db, ACCOMMODATION_COLLECTION).withConverter(createConverter(accommodationSchema)));
        if (status) {
            q = query(q, where('status', '==', status));
        }
        q = query(q, orderBy('name', 'asc'));
        const snapshot = await getDocs(q);
        return snapshot.docs.map(doc => doc.data() as Accommodation);
    },

    /**
     * 단일 숙소 상세 조회
     */
    getAccommodation: async (id: string) => {
        const ref = doc(db, ACCOMMODATION_COLLECTION, id).withConverter(createConverter(accommodationSchema));
        const snapshot = await getDoc(ref);
        return snapshot.exists() ? (snapshot.data() as Accommodation) : null;
    },

    /**
     * 숙소 저장 (생성/수정)
     */
    saveAccommodation: async (data: Partial<Accommodation> & { id: string }) => {
        const ref = doc(db, ACCOMMODATION_COLLECTION, data.id).withConverter(createConverter(accommodationSchema));
        await setDoc(ref, {
            ...data,
            updatedAt: Timestamp.now()
        }, { merge: true });
    },

    /**
     * 숙소 삭제
     */
    deleteAccommodation: async (id: string) => {
        const ref = doc(db, ACCOMMODATION_COLLECTION, id);
        await deleteDoc(ref);
    },

    /**
     * 공과금 기록 목록 조회 (연월 기준)
     */
    listUtilityRecords: async (yearMonth?: string) => {
        let q = query(collection(db, UTILITY_RECORD_COLLECTION).withConverter(createConverter(utilityRecordSchema)));
        if (yearMonth) {
            q = query(q, where('yearMonth', '==', yearMonth));
        }
        q = query(q, orderBy('yearMonth', 'desc'));
        const snapshot = await getDocs(q);
        return snapshot.docs.map(doc => doc.data() as UtilityRecord);
    },

    /**
     * 공과금 기록 저장
     */
    saveUtilityRecord: async (data: Partial<UtilityRecord> & { id: string }) => {
        const ref = doc(db, UTILITY_RECORD_COLLECTION, data.id).withConverter(createConverter(utilityRecordSchema));
        await setDoc(ref, {
            ...data,
            updatedAt: Timestamp.now()
        }, { merge: true });
    },

    /**
     * 특정 숙소의 최근 공과금 기록 조회
     */
    getLatestUtilityRecord: async (accommodationId: string) => {
        const q = query(
            collection(db, UTILITY_RECORD_COLLECTION).withConverter(createConverter(utilityRecordSchema)),
            where('accommodationId', '==', accommodationId),
            orderBy('yearMonth', 'desc'),
            firestoreLimit(1)
        );
        const snapshot = await getDocs(q);
        return snapshot.empty ? null : (snapshot.docs[0].data() as UtilityRecord);
    }
};

import {
    listAllAdvancePayments,
    createAdvancePayment,
    updateAdvancePayment,
    deleteAdvancePayment,
    listAllWorkers,
    listAllTeams
} from '../services/firestoreCrudCompat';

export interface AdvancePayment {
    id?: string;
    workerId: string;
    workerName: string;
    teamId: string;
    teamName: string;
    yearMonth: string; // "YYYY-MM"

    // Dynamic deduction items (custom fields)
    items?: Record<string, number>;
    
    // Per-item assignment types: item key -> 'corporate' | 'labor'
    itemAssignments?: Record<string, 'corporate' | 'labor'>;

    // Explicit Columns
    prevMonthCarryover: number; // 전월이월
    accommodation: number;      // 숙소비
    privateRoom: number;        // 개인방
    gloves: number;            // 장갑
    deposit: number;           // 보증금
    fines: number;             // 과태료
    electricity: number;       // 전기료
    gas: number;               // 도시가스
    internet: number;          // 인터넷
    water: number;             // 수도료

    totalDeduction: number;    // 공제 합계 (Calculated)
    assignmentType?: 'corporate' | 'labor'; // 분류: 법인(corporate) / 노무(labor) - Legacy row-level field
    memo?: string;
    updatedAt?: Date;
}

const isUuidString = (value: string) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);

let dcWorkersLoaded = false;
let dcTeamsLoaded = false;

const dcWorkerLegacyIdToUuid = new Map<string, string>();
const dcTeamLegacyIdToUuid = new Map<string, string>();

const loadDcWorkers = async (): Promise<void> => {
    if (dcWorkersLoaded) return;

    const limit = 500;
    let offset = 0;
    const rows: any[] = [];

    while (true) {
        const res = await listAllWorkers({ limit, offset } as any);
        const pageRows = (res as any)?.data?.workers ?? [];
        if (Array.isArray(pageRows)) rows.push(...pageRows);
        if (!Array.isArray(pageRows) || pageRows.length < limit) break;
        offset += limit;
    }

    if (rows.length === 0) {
        const fallbackRes = await listAllWorkers();
        const fallbackRows = (fallbackRes as any)?.data?.workers ?? [];
        if (Array.isArray(fallbackRows)) rows.push(...fallbackRows);
    }

    dcWorkerLegacyIdToUuid.clear();
    rows.forEach((w: any) => {
        const id = w?.id ? String(w.id) : '';
        const legacyId = w?.legacyId ? String(w.legacyId) : '';
        if (id) dcWorkerLegacyIdToUuid.set(id, id);
        if (legacyId) dcWorkerLegacyIdToUuid.set(legacyId, id);
    });
    dcWorkersLoaded = true;
};

const loadDcTeams = async (): Promise<void> => {
    if (dcTeamsLoaded) return;

    const limit = 500;
    let offset = 0;
    const rows: any[] = [];

    while (true) {
        const res = await listAllTeams({ limit, offset } as any);
        const pageRows = (res as any)?.data?.teams ?? [];
        if (Array.isArray(pageRows)) rows.push(...pageRows);
        if (!Array.isArray(pageRows) || pageRows.length < limit) break;
        offset += limit;
    }

    if (rows.length === 0) {
        const fallbackRes = await listAllTeams();
        const fallbackRows = (fallbackRes as any)?.data?.teams ?? [];
        if (Array.isArray(fallbackRows)) rows.push(...fallbackRows);
    }

    dcTeamLegacyIdToUuid.clear();
    rows.forEach((t: any) => {
        const id = t?.id ? String(t.id) : '';
        const legacyId = t?.legacyId ? String(t.legacyId) : '';
        if (id) dcTeamLegacyIdToUuid.set(id, id);
        if (legacyId) dcTeamLegacyIdToUuid.set(legacyId, id);
    });
    dcTeamsLoaded = true;
};

const resolveWorkerUuid = async (id: string): Promise<string | null> => {
    const raw = id ? String(id) : '';
    if (!raw) return null;
    if (isUuidString(raw)) return raw;
    await loadDcWorkers();
    const found = dcWorkerLegacyIdToUuid.get(raw);
    if (found) return found;
    dcWorkersLoaded = false;
    await loadDcWorkers();
    return dcWorkerLegacyIdToUuid.get(raw) ?? null;
};

const resolveTeamUuid = async (id: string): Promise<string | null> => {
    const raw = id ? String(id) : '';
    if (!raw) return null;
    if (isUuidString(raw)) return raw;
    await loadDcTeams();
    const found = dcTeamLegacyIdToUuid.get(raw);
    if (found) return found;
    dcTeamsLoaded = false;
    await loadDcTeams();
    return dcTeamLegacyIdToUuid.get(raw) ?? null;
};

const normalizeAssignmentRecord = (value: unknown): Record<string, 'corporate' | 'labor'> => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
    return Object.fromEntries(
        Object.entries(value as Record<string, unknown>)
            .filter(([k, v]) => typeof k === 'string' && k.trim().length > 0 && (v === 'corporate' || v === 'labor'))
            .map(([k, v]) => [k, v as 'corporate' | 'labor'] as const)
    );
};

const safeJsonParseAssignmentRecord = (value: unknown): Record<string, 'corporate' | 'labor'> => {
    if (!value) return {};
    if (typeof value === 'object') return normalizeAssignmentRecord(value);
    if (typeof value !== 'string') return {};
    const raw = value.trim();
    if (!raw) return {};
    try {
        return normalizeAssignmentRecord(JSON.parse(raw));
    } catch {
        return {};
    }
};

const asFiniteNumber = (value: unknown): number => {
    if (typeof value === 'number' && Number.isFinite(value)) return value;
    if (typeof value === 'string') {
        const normalized = value.replace(/,/g, '').trim();
        if (!normalized) return 0;
        const parsed = Number(normalized);
        return Number.isFinite(parsed) ? parsed : 0;
    }
    return 0;
};

const normalizeNumberRecord = (value: unknown): Record<string, number> => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
    return Object.fromEntries(
        Object.entries(value as Record<string, unknown>)
            .filter(([k]) => typeof k === 'string' && k.trim().length > 0)
            .map(([k, v]) => [k, asFiniteNumber(v)] as const)
    );
};

const safeJsonParseRecord = (value: unknown): Record<string, number> => {
    if (!value) return {};
    if (typeof value === 'object') return normalizeNumberRecord(value);
    if (typeof value !== 'string') return {};
    const raw = value.trim();
    if (!raw) return {};
    try {
        return normalizeNumberRecord(JSON.parse(raw));
    } catch {
        return {};
    }
};

const normalizeItems = (items?: Record<string, number>): Record<string, number> => {
    if (!items) return {};
    return Object.fromEntries(
        Object.entries(items)
            .filter(([k]) => typeof k === 'string' && k.trim().length > 0)
            .map(([k, v]) => [k, asFiniteNumber(v)] as const)
    );
};

const parseAdvancePaymentCompositeId = (
    rawId: string
): { teamId: string; workerId: string; yearMonth: string } | null => {
    const id = String(rawId ?? '').trim();
    if (!id) return null;

    const parts = id.split('_');
    if (parts.length < 3) return null;

    const yearMonth = parts[parts.length - 1];
    const workerId = parts[parts.length - 2];
    const teamId = parts.slice(0, parts.length - 2).join('_');

    if (!yearMonth || !workerId || !teamId) return null;
    if (!/^\d{4}-\d{2}$/.test(yearMonth)) return null;

    return { teamId, workerId, yearMonth };
};

const listEveryAdvancePaymentRow = async (): Promise<any[]> => {
    const limit = 1000;
    let offset = 0;
    const rows: any[] = [];

    while (true) {
        const res = await listAllAdvancePayments({ limit, offset } as any);
        const pageRows = (res as any)?.data?.advancePayments ?? [];
        if (Array.isArray(pageRows)) rows.push(...pageRows);
        if (!Array.isArray(pageRows) || pageRows.length < limit) break;
        offset += limit;
    }

    if (rows.length === 0) {
        const fallbackRes = await listAllAdvancePayments();
        const fallbackRows = (fallbackRes as any)?.data?.advancePayments ?? [];
        if (Array.isArray(fallbackRows)) rows.push(...fallbackRows);
    }

    return rows;
};

const toDate = (value?: string | null): Date | undefined => {
    const raw = value ? String(value) : '';
    if (!raw) return undefined;
    const d = new Date(raw);
    if (Number.isNaN(d.getTime())) return undefined;
    return d;
};

const isAlreadyExistsError = (error: unknown): boolean => {
    if (!error) return false;
    const asAny = error as any;
    const messageFromError = error instanceof Error ? error.message : '';
    const messageFromField = typeof asAny?.message === 'string' ? asAny.message : '';
    const normalized = `${messageFromError} | ${messageFromField}`.toLowerCase();
    return normalized.includes('already') && normalized.includes('exists') || normalized.includes('duplicate');
};

const isOpaqueSqlFailureOnAdvancePaymentInsert = (error: unknown): boolean => {
    const message = error instanceof Error ? error.message : '';
    const normalized = String(message).toLowerCase();
    return (normalized.includes('partial-error') || normalized.includes('sql execution failed'))
        && (normalized.includes('advancepayment') || normalized.includes('insert'));
};

const mapAdvancePaymentRow = (row: any): AdvancePayment => {
    const parsed = parseAdvancePaymentCompositeId(String(row?.id ?? ''));
    const rawItems = safeJsonParseRecord(row?.items);
    return {
        id: String(row?.id ?? ''),
        workerId:
            row?.worker?.legacyId
                ? String(row.worker.legacyId)
                : String(row?.worker?.id ?? row?.workerId ?? (parsed?.workerId ?? '')),
        workerName: row?.workerName ? String(row.workerName) : (row?.worker?.name ? String(row.worker.name) : ''),
        teamId:
            row?.team?.legacyId
                ? String(row.team.legacyId)
                : String(row?.team?.id ?? row?.teamId ?? (parsed?.teamId ?? '')),
        teamName: row?.teamName ? String(row.teamName) : (row?.team?.name ? String(row.team.name) : ''),
        yearMonth: String(row?.yearMonth ?? (parsed?.yearMonth ?? '')),
        items: rawItems,
        prevMonthCarryover: asFiniteNumber(row?.prevMonthCarryover),
        accommodation: asFiniteNumber(row?.accommodation),
        privateRoom: asFiniteNumber(row?.privateRoom),
        gloves: asFiniteNumber(row?.gloves),
        deposit: asFiniteNumber(row?.deposit),
        fines: asFiniteNumber(row?.fines),
        electricity: asFiniteNumber(row?.electricity),
        gas: asFiniteNumber(row?.gas),
        internet: asFiniteNumber(row?.internet),
        water: asFiniteNumber(row?.water),
        totalDeduction: asFiniteNumber(row?.totalDeduction),
        itemAssignments: safeJsonParseAssignmentRecord(row?.itemAssignments),
        assignmentType: row?.assignmentType ? (String(row.assignmentType) as 'corporate' | 'labor') : 'labor',
        memo: row?.memo ? String(row.memo) : '',
        updatedAt: toDate(row?.updatedAt)
    } as AdvancePayment;
};

export const advancePaymentService = {
    getAdvancePayments: async (year: number, month: number, teamId: string): Promise<AdvancePayment[]> => {
        try {
            const yearMonth = `${year}-${String(month).padStart(2, '0')}`;
            const safeTeamId = String(teamId ?? '').trim();
            const teamUuid = await resolveTeamUuid(safeTeamId);
            const rows = await listEveryAdvancePaymentRow();

            return rows
                .filter((row: any) => {
                    const parsed = parseAdvancePaymentCompositeId(String(row?.id ?? ''));
                    const rowYearMonth = String(row?.yearMonth ?? (parsed?.yearMonth ?? ''));
                    if (rowYearMonth !== String(yearMonth)) return false;

                    const dcTeamId = row?.team?.id ? String(row.team.id).trim() : '';
                    const dcTeamLegacyId = row?.team?.legacyId ? String(row.team.legacyId).trim() : '';
                    const flatTeamId = row?.teamId ? String(row.teamId).trim() : '';
                    const parsedTeamId = parsed?.teamId ? String(parsed.teamId).trim() : '';

                    const candidateTeamIds = new Set<string>(
                        [dcTeamId, dcTeamLegacyId, flatTeamId, parsedTeamId].filter((v) => Boolean(v))
                    );

                    if (!safeTeamId && !teamUuid) return true;
                    if (safeTeamId && candidateTeamIds.has(safeTeamId)) return true;
                    if (teamUuid && candidateTeamIds.has(teamUuid)) return true;
                    return false;
                })
                .map(mapAdvancePaymentRow);
        } catch (error) {
            console.error("Error fetching advance payments:", error);
            throw error;
        }
    },

    getAdvancePaymentsByYearMonth: async (year: number, month: number): Promise<AdvancePayment[]> => {
        try {
            const yearMonth = `${year}-${String(month).padStart(2, '0')}`;
            const rows = await listEveryAdvancePaymentRow();

            return rows
                .filter((row: any) => {
                    const parsed = parseAdvancePaymentCompositeId(String(row?.id ?? ''));
                    return String(row?.yearMonth ?? (parsed?.yearMonth ?? '')) === String(yearMonth);
                })
                .map(mapAdvancePaymentRow);
        } catch (error) {
            console.error("Error fetching advance payments by yearMonth:", error);
            throw error;
        }
    },

    saveAdvancePayment: async (data: AdvancePayment) => {
        try {
            const safeTeamId = String(data.teamId ?? '').trim();
            const safeWorkerId = String(data.workerId ?? '').trim();
            const safeYearMonth = String(data.yearMonth ?? '').trim();
            const docId = `${safeTeamId}_${safeWorkerId}_${safeYearMonth}`;
            const [teamUuid, workerUuid] = await Promise.all([
                resolveTeamUuid(safeTeamId),
                resolveWorkerUuid(safeWorkerId)
            ]);

            const resolvedTeamId = teamUuid ?? safeTeamId;
            const resolvedWorkerId = workerUuid ?? safeWorkerId;

            if (!resolvedTeamId) {
                throw new Error('팀 ID가 비어 있어 저장할 수 없습니다.');
            }

            if (!teamUuid) {
                console.warn('[advancePaymentService.saveAdvancePayment] Team UUID resolve failed. Fallback to raw teamId.', {
                    teamId: safeTeamId,
                    yearMonth: safeYearMonth,
                });
            }

            if (!workerUuid) {
                console.warn('[advancePaymentService.saveAdvancePayment] Worker UUID resolve failed. Fallback to raw workerId.', {
                    workerId: safeWorkerId,
                    yearMonth: safeYearMonth,
                });
            }
            
            const normalizedItems = normalizeItems(data.items);

            const payload: any = {
                id: docId,
                yearMonth: safeYearMonth,
                workerId: resolvedWorkerId || null,
                workerName: data.workerName ?? null,
                teamId: resolvedTeamId,
                teamName: data.teamName ?? null,
                items: JSON.stringify(normalizedItems),
                prevMonthCarryover: data.prevMonthCarryover ?? 0,
                accommodation: data.accommodation ?? 0,
                privateRoom: data.privateRoom ?? 0,
                gloves: data.gloves ?? 0,
                deposit: data.deposit ?? 0,
                fines: data.fines ?? 0,
                electricity: data.electricity ?? 0,
                gas: data.gas ?? 0,
                internet: data.internet ?? 0,
                water: data.water ?? 0,
                totalDeduction: data.totalDeduction ?? 0,
                itemAssignments: JSON.stringify(data.itemAssignments ?? {}),
                assignmentType: data.assignmentType ?? 'labor',
                memo: data.memo ?? null,
                updatedAt: new Date().toISOString()
            };

            try {
                await createAdvancePayment(payload);
            } catch (error) {
                if (isAlreadyExistsError(error) || isOpaqueSqlFailureOnAdvancePaymentInsert(error)) {
                    await updateAdvancePayment(payload);
                } else {
                    throw error;
                }
            }
            return docId;
        } catch (error) {
            console.error("Error saving advance payment:", error);
            throw error;
        }
    },

    deleteAdvancePayment: async (id: string) => {
        try {
            if (!id) return;
            await deleteAdvancePayment({ id } as any);
        } catch (error) {
            console.error("Error deleting advance payment:", error);
            throw error;
        }
    }
};

/**
 * AI 분석 에이전트
 * 
 * Gemini AI를 사용하여 사용자 질의를 분석하고
 * 공수 데이터를 조회하여 Markdown 표 형식으로 응답 생성
 */

import { manpowerAnalyticsService } from './manpowerAnalyticsService';
import { aiSettingsService } from './aiSettingsService';

// ===========================
// Types
// ===========================

interface AnalysisRequest {
    userQuery: string;
    userId?: string;
}

interface AnalysisResponse {
    markdown: string;
    rawData?: any;
    insights?: string[];
}

// ===========================
// Helper Functions
// ===========================

/**
 * 현재 날짜 기준으로 기간 계산
 */
function calculatePeriod(periodType: string): { startDate: string; endDate: string } {
    const today = new Date();
    const year = today.getFullYear();
    const month = today.getMonth();
    const day = today.getDate();

    switch (periodType) {
        case 'today':
            const todayStr = today.toISOString().split('T')[0];
            return { startDate: todayStr, endDate: todayStr };

        case 'yesterday':
            const yesterday = new Date(today);
            yesterday.setDate(yesterday.getDate() - 1);
            const yesterdayStr = yesterday.toISOString().split('T')[0];
            return { startDate: yesterdayStr, endDate: yesterdayStr };

        case 'this_week':
            const thisWeekStart = new Date(today);
            thisWeekStart.setDate(today.getDate() - today.getDay());
            return {
                startDate: thisWeekStart.toISOString().split('T')[0],
                endDate: today.toISOString().split('T')[0]
            };

        case 'last_week':
            const lastWeekEnd = new Date(today);
            lastWeekEnd.setDate(today.getDate() - today.getDay() - 1);
            const lastWeekStart = new Date(lastWeekEnd);
            lastWeekStart.setDate(lastWeekEnd.getDate() - 6);
            return {
                startDate: lastWeekStart.toISOString().split('T')[0],
                endDate: lastWeekEnd.toISOString().split('T')[0]
            };

        case 'this_month':
            const thisMonthStart = new Date(year, month, 1);
            return {
                startDate: thisMonthStart.toISOString().split('T')[0],
                endDate: today.toISOString().split('T')[0]
            };

        case 'last_month':
            const lastMonthStart = new Date(year, month - 1, 1);
            const lastMonthEnd = new Date(year, month, 0);
            return {
                startDate: lastMonthStart.toISOString().split('T')[0],
                endDate: lastMonthEnd.toISOString().split('T')[0]
            };

        case 'this_year':
            const thisYearStart = new Date(year, 0, 1);
            return {
                startDate: thisYearStart.toISOString().split('T')[0],
                endDate: today.toISOString().split('T')[0]
            };

        default:
            // 최근 7일
            const defaultStart = new Date(today);
            defaultStart.setDate(today.getDate() - 7);
            return {
                startDate: defaultStart.toISOString().split('T')[0],
                endDate: today.toISOString().split('T')[0]
            };
    }
}

/**
 * 숫자를 한국 통화 형식으로 포맷
 */
function formatCurrency(amount: number): string {
    return `₩${amount.toLocaleString('ko-KR')}`;
}

/**
 * Gemini AI 호출
 */
async function callGemini(prompt: string): Promise<string> {
    aiSettingsService.assertCurrentPageEnabled('AI 에이전트 분석');
    const apiKey = aiSettingsService.getApiKey();
    if (!apiKey) {
        throw new Error('Gemini API Key가 설정되지 않았습니다');
    }

    const model = aiSettingsService.getModels().textModel || 'gemini-2.0-flash';
    const endpoint = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;

    const response = await fetch(
        endpoint,
        {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                contents: [{
                    role: "user",
                    parts: [{ text: prompt }]
                }]
            })
        }
    );

    const data = await response.json();
    if (data.error) throw new Error(data.error.message);

    return data.candidates[0].content.parts[0].text;
}

// ===========================
// Main Analytics Agent
// ===========================

export class AnalyticsAgent {
    /**
     * 사용자 질의 분석 및 처리
     */
    async analyze(request: AnalysisRequest): Promise<AnalysisResponse> {
        const { userQuery } = request;

        // 1. AI로 질의 의도 파악
        const intent = await this.parseIntent(userQuery);

        // 2. 데이터 조회
        let data: any;
        let markdown = '';

        try {
            switch (intent.type) {
                case 'team_manpower':
                    data = await manpowerAnalyticsService.getTeamManpower(
                        intent.startDate!,
                        intent.endDate!
                    );
                    markdown = this.formatTeamManpowerTable(data, intent);
                    break;

                case 'worker_manpower':
                    data = await manpowerAnalyticsService.getWorkerManpower(
                        intent.startDate!,
                        intent.endDate!,
                        intent.workerName
                    );
                    markdown = this.formatWorkerManpowerTable(data, intent);
                    break;

                case 'site_manpower':
                    data = await manpowerAnalyticsService.getSiteManpower(
                        intent.startDate!,
                        intent.endDate!
                    );
                    markdown = this.formatSiteManpowerTable(data, intent);
                    break;

                case 'statistics':
                    data = await manpowerAnalyticsService.getManpowerStatistics(
                        intent.startDate!,
                        intent.endDate!
                    );
                    markdown = this.formatStatisticsTable(data, intent);
                    break;

                default:
                    markdown = '죄송합니다. 해당 질문을 이해하지 못했습니다.';
            }

            // 3. AI 인사이트 생성
            const insights = await this.generateInsights(userQuery, data);

            return {
                markdown: markdown + '\n\n' + insights,
                rawData: data
            };

        } catch (error: any) {
            return {
                markdown: `⚠️ **오류 발생**\n\n${error.message}`
            };
        }
    }

    /**
     * 사용자 질의 의도 파악
     */
    private async parseIntent(userQuery: string): Promise<{
        type: 'team_manpower' | 'worker_manpower' | 'site_manpower' | 'statistics';
        startDate?: string;
        endDate?: string;
        workerName?: string;
        siteName?: string;
        periodType?: string;
    }> {
        const query = userQuery.toLowerCase();

        // 기간 파악
        let periodType = 'this_month';
        if (query.includes('오늘') || query.includes('today')) {
            periodType = 'today';
        } else if (query.includes('어제') || query.includes('yesterday')) {
            periodType = 'yesterday';
        } else if (query.includes('이번 주') || query.includes('this week')) {
            periodType = 'this_week';
        } else if (query.includes('지난 주') || query.includes('last week')) {
            periodType = 'last_week';
        } else if (query.includes('이번 달') || query.includes('this month')) {
            periodType = 'this_month';
        } else if (query.includes('지난 달') || query.includes('last month')) {
            periodType = 'last_month';
        } else if (query.includes('올해') || query.includes('this year')) {
            periodType = 'this_year';
        }

        const { startDate, endDate } = calculatePeriod(periodType);

        // 질의 타입 파악
        if (query.includes('팀별') || (query.includes('팀') && query.includes('공수'))) {
            return { type: 'team_manpower', startDate, endDate, periodType };
        }

        if (query.includes('작업자') || query.includes('근로자') || query.includes('이름')) {
            // 작업자 이름 추출 시도
            const nameMatch = userQuery.match(/([가-힣]{2,4})\s*(작업자|님|씨)?/);
            const workerName = nameMatch ? nameMatch[1] : undefined;
            return { type: 'worker_manpower', startDate, endDate, workerName, periodType };
        }

        if (query.includes('현장별') || (query.includes('현장') && query.includes('공수'))) {
            return { type: 'site_manpower', startDate, endDate, periodType };
        }

        if (query.includes('통계') || query.includes('전체') || query.includes('요약')) {
            return { type: 'statistics', startDate, endDate, periodType };
        }

        // 기본값: 전체 통계
        return { type: 'statistics', startDate, endDate, periodType };
    }

    /**
     * 팀별 공수 표 포맷
     */
    private formatTeamManpowerTable(data: any[], intent: any): string {
        const periodText = this.getPeriodText(intent.periodType, intent.startDate, intent.endDate);

        let markdown = `## 📊 팀별 공수 현황\n\n**${periodText}**\n\n`;

        if (data.length === 0) {
            return markdown + '*데이터가 없습니다.*';
        }

        markdown += '| 순위 | 팀명 | 총 공수 | 투입 인원 | 작업일 | 평균 일일 공수 | 총 금액 |\n';
        markdown += '|------|------|---------|-----------|--------|----------------|----------|\n';

        data.forEach((team, idx) => {
            markdown += `| ${idx + 1} | ${team.teamName} | ${team.totalManDay.toFixed(1)} | ${team.workerCount}명 | ${team.days}일 | ${team.avgDailyManDay.toFixed(1)} | ${formatCurrency(team.totalAmount)} |\n`;
        });

        return markdown;
    }

    /**
     * 작업자별 공수 표 포맷
     */
    private formatWorkerManpowerTable(data: any[], intent: any): string {
        const periodText = this.getPeriodText(intent.periodType, intent.startDate, intent.endDate);
        const titleSuffix = intent.workerName ? ` - ${intent.workerName}` : '';

        let markdown = `## 👤 작업자별 공수 현황${titleSuffix}\n\n**${periodText}**\n\n`;

        if (data.length === 0) {
            return markdown + '*데이터가 없습니다.*';
        }

        markdown += '| 순위 | 이름 | 총 공수 | 출근일 | 평균 공수 | 투입 현장 | 총 금액 |\n';
        markdown += '|------|------|---------|--------|-----------|-----------|----------|\n';

        data.slice(0, 50).forEach((worker, idx) => {
            markdown += `| ${idx + 1} | ${worker.workerName} | ${worker.totalManDay.toFixed(1)} | ${worker.workDays}일 | ${worker.avgManDay.toFixed(2)} | ${worker.sites.join(', ')} | ${formatCurrency(worker.totalAmount)} |\n`;
        });

        if (data.length > 50) {
            markdown += `\n*상위 50명만 표시 (전체 ${data.length}명)*\n`;
        }

        return markdown;
    }

    /**
     * 현장별 공수 표 포맷
     */
    private formatSiteManpowerTable(data: any[], intent: any): string {
        const periodText = this.getPeriodText(intent.periodType, intent.startDate, intent.endDate);

        let markdown = `## 🏗️ 현장별 공수 현황\n\n**${periodText}**\n\n`;

        if (data.length === 0) {
            return markdown + '*데이터가 없습니다.*';
        }

        markdown += '| 순위 | 현장명 | 총 공수 | 투입 인원 | 투입 팀 | 작업일 | 총 금액 |\n';
        markdown += '|------|--------|---------|-----------|---------|--------|----------|\n';

        data.forEach((site, idx) => {
            markdown += `| ${idx + 1} | ${site.siteName} | ${site.totalManDay.toFixed(1)} | ${site.workerCount}명 | ${site.teamCount}개 | ${site.days}일 | ${formatCurrency(site.totalAmount)} |\n`;
        });

        return markdown;
    }

    /**
     * 전체 통계 표 포맷
     */
    private formatStatisticsTable(data: any, intent: any): string {
        const periodText = this.getPeriodText(intent.periodType, intent.startDate, intent.endDate);

        let markdown = `## 📈 전체 공수 통계\n\n**${periodText}**\n\n`;

        markdown += '| 항목 | 값 |\n';
        markdown += '|------|----|\ n';
        markdown += `| 총 공수 | ${data.totalManDay.toFixed(1)} |\n`;
        markdown += `| 투입 인원 | ${data.totalWorkers}명 |\n`;
        markdown += `| 평균 일일 공수 | ${data.avgManDay.toFixed(1)} |\n`;
        markdown += `| 최대 일일 공수 | ${data.maxManDay.toFixed(1)} |\n`;
        markdown += `| 최소 일일 공수 | ${data.minManDay.toFixed(1)} |\n`;
        markdown += `| 총 금액 | ${formatCurrency(data.totalAmount)} |\n`;

        return markdown;
    }

    /**
     * 기간 텍스트 생성
     */
    private getPeriodText(periodType: string, startDate: string, endDate: string): string {
        const periodNames: Record<string, string> = {
            'today': '오늘',
            'yesterday': '어제',
            'this_week': '이번 주',
            'last_week': '지난 주',
            'this_month': '이번 달',
            'last_month': '지난 달',
            'this_year': '올해'
        };

        const periodName = periodNames[periodType] || '';
        return `${periodName} (${startDate} ~ ${endDate})`;
    }

    /**
     * AI 인사이트 생성
     */
    private async generateInsights(userQuery: string, data: any): Promise<string> {
        if (!data || (Array.isArray(data) && data.length === 0)) {
            return '';
        }

        try {
            const prompt = `다음은 공수 데이터 분석 결과입니다:

사용자 질문: ${userQuery}

데이터:
${JSON.stringify(data, null, 2)}

위 데이터를 바탕으로 3가지 핵심 인사이트를 제공해주세요:
1. 가장 주목할 만한 통계
2. 트렌드나 패턴
3. 실행 가능한 제안

응답 형식:
💡 **인사이트:**
- [인사이트 1]
