// Singleton instance
export const analyticsAgent = new AnalyticsAgent();

import {
    collection,
    doc,
    getDoc,
    getDocs,
    setDoc,
    updateDoc,
    deleteDoc,
    query,
    where,
    orderBy,
    writeBatch,
    serverTimestamp,
    runTransaction,
    Timestamp as FirestoreTimestamp
} from 'firebase/firestore';
import { db } from '../config/firebase';
import {
    Card,
    CardAssignmentRecord,
    CardTransaction,
    CardAssigneeType
} from '../types/card';
import { CardBillingDocument } from '../types/cardBilling';
import {
    CardSchema,
    CardAssignmentRecordSchema,
    CardTransactionSchema,
    CardBillingDocumentSchema
} from '../types/zod/cardSchema';
import {
    listCards,
    listCardAssignments,
    listCardTransactions,
    listCardBillingDocuments
} from './firestoreCrudCompat';

const CARDS_COLLECTION = 'cards';
const ASSIGNMENTS_COLLECTION = 'cardAssignments';
const TRANSACTIONS_COLLECTION = 'cardTransactions';
const BILLINGS_COLLECTION = 'cardBillings';

export const cardFirestoreService = {
    // --- Cards ---
    async getCards(): Promise<Card[]> {
        const q = query(collection(db, CARDS_COLLECTION), orderBy('name', 'asc'));
        const snapshot = await getDocs(q);
        return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Card));
    },

    async getCard(id: string): Promise<Card | null> {
        const docRef = doc(db, CARDS_COLLECTION, id);
        const docSnap = await getDoc(docRef);
        return docSnap.exists() ? ({ id: docSnap.id, ...docSnap.data() } as Card) : null;
    },

    async createCard(data: Omit<Card, 'id' | 'createdAt' | 'updatedAt'>): Promise<string> {
        const validated = CardSchema.parse(data);
        const docRef = doc(collection(db, CARDS_COLLECTION));
        await setDoc(docRef, {
            ...validated,
            createdAt: serverTimestamp(),
            updatedAt: serverTimestamp(),
        });
        return docRef.id;
    },

    async updateCard(id: string, data: Partial<Card>): Promise<void> {
        const docRef = doc(db, CARDS_COLLECTION, id);
        await updateDoc(docRef, {
            ...data,
            updatedAt: serverTimestamp(),
        });
    },

    // --- Card Assignments ---
    async getAssignmentHistory(cardId: string): Promise<CardAssignmentRecord[]> {
        const q = query(
            collection(db, ASSIGNMENTS_COLLECTION),
            where('cardId', '==', cardId),
            orderBy('startDate', 'desc')
        );
        const snapshot = await getDocs(q);
        return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as CardAssignmentRecord));
    },

    async assignCard(params: {
        cardId: string;
        assigneeId: string;
        assigneeType: CardAssigneeType;
        assigneeName: string;
        startDate: string;
        cardLabel: string;
    }): Promise<void> {
        await runTransaction(db, async (transaction) => {
            const cardRef = doc(db, CARDS_COLLECTION, params.cardId);
            const assignmentRef = doc(collection(db, ASSIGNMENTS_COLLECTION));

            transaction.update(cardRef, {
                status: 'ASSIGNED',
                currentAssigneeId: params.assigneeId,
                currentAssigneeType: params.assigneeType,
                currentAssigneeName: params.assigneeName,
                updatedAt: serverTimestamp(),
            });

            transaction.set(assignmentRef, {
                cardId: params.cardId,
                cardLabel: params.cardLabel,
                assigneeId: params.assigneeId,
                assigneeType: params.assigneeType,
                assigneeName: params.assigneeName,
                startDate: params.startDate,
                createdAt: serverTimestamp(),
                updatedAt: serverTimestamp(),
            });
        });
    },

    async unassignCard(cardId: string, endDate: string): Promise<void> {
        await runTransaction(db, async (transaction) => {
            const cardRef = doc(db, CARDS_COLLECTION, cardId);

            // 1. ?꾩옱 吏꾪뻾 以묒씤 諛곗젙 ?덉퐫??李얘린
            const q = query(
                collection(db, ASSIGNMENTS_COLLECTION),
                where('cardId', '==', cardId)
            );
            const snapshot = await getDocs(q);
            const activeAssignment = snapshot.docs.find(d => !d.data().endDate);

            if (activeAssignment) {
                transaction.update(activeAssignment.ref, {
                    endDate,
                    updatedAt: serverTimestamp(),
                });
            }

            // 2. 移대뱶 ?곹깭 ?낅뜲?댄듃
            transaction.update(cardRef, {
                status: 'AVAILABLE',
                currentAssigneeId: null,
                currentAssigneeType: null,
                currentAssigneeName: null,
                updatedAt: serverTimestamp(),
            });
        });
    },

    // --- Transactions ---
    async getTransactionsByMonth(yearMonth: string): Promise<CardTransaction[]> {
        const q = query(
            collection(db, TRANSACTIONS_COLLECTION),
            where('yearMonth', '==', yearMonth),
            orderBy('date', 'desc')
        );
        const snapshot = await getDocs(q);
        return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as CardTransaction));
    },

    async addTransaction(data: Omit<CardTransaction, 'id' | 'createdAt'>): Promise<string> {
        const validated = CardTransactionSchema.parse(data);
        const docRef = doc(collection(db, TRANSACTIONS_COLLECTION));
        await setDoc(docRef, {
            ...validated,
            createdAt: serverTimestamp(),
        });
        return docRef.id;
    },

    async deleteTransaction(id: string): Promise<void> {
        await deleteDoc(doc(db, TRANSACTIONS_COLLECTION, id));
    },

    // --- Billings ---
    async getBillingsByMonth(yearMonth: string): Promise<CardBillingDocument[]> {
        const q = query(
            collection(db, BILLINGS_COLLECTION),
            where('yearMonth', '==', yearMonth)
        );
        const snapshot = await getDocs(q);
        return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as CardBillingDocument));
    },

    async saveBilling(billing: CardBillingDocument): Promise<void> {
        const docRef = doc(db, BILLINGS_COLLECTION, billing.id);
        const { id, ...data } = billing;
        await setDoc(docRef, {
            ...data,
            updatedAt: serverTimestamp(),
        }, { merge: true });
    },

    async deleteBilling(id: string): Promise<void> {
        await deleteDoc(doc(db, BILLINGS_COLLECTION, id));
    },

    // --- Migration ---
    async migrateLegacyData() {
        console.log('Starting Card & Transaction migration...');

        // 1. Fetch all from DC
        const [cardsRes, assignmentsRes, transactionsRes, billingsRes] = await Promise.all([
            listCards(),
            listCardAssignments(),
            listCardTransactions(),
            listCardBillingDocuments()
        ]);

        const dcCards = (cardsRes as any).data?.cards ?? [];
        const dcAssignments = (assignmentsRes as any).data?.cardAssignments ?? [];
        const dcTransactions = (transactionsRes as any).data?.cardTransactions ?? [];
        const dcBillings = (billingsRes as any).data?.cardBillingDocuments ?? [];

        const batch = writeBatch(db);
        const cardIdMap = new Map<string, string>(); // UUID -> Firestore ID

        // 2. Migrate Cards
        for (const dcCard of dcCards) {
            const ref = doc(collection(db, CARDS_COLLECTION));
            batch.set(ref, {
                name: dcCard.name,
                issuer: dcCard.issuer,
                cardType: dcCard.cardType,
                last4: dcCard.last4,
                maskedNumber: dcCard.maskedNumber,
                expiry: dcCard.expiry,
                status: dcCard.status,
                currentAssigneeId: dcCard.currentAssigneeId,
                currentAssigneeType: dcCard.currentAssigneeType,
                currentAssigneeName: dcCard.currentAssigneeName,
                memo: dcCard.memo,
                legacyId: dcCard.id,
                createdAt: serverTimestamp(),
                updatedAt: serverTimestamp()
            });
            cardIdMap.set(dcCard.id, ref.id);
        }

        // 3. Migrate Assignments
        for (const dcAs of dcAssignments) {
            const fsCardId = cardIdMap.get(dcAs.card?.id);
            if (!fsCardId) continue;

            const ref = doc(collection(db, ASSIGNMENTS_COLLECTION));
            batch.set(ref, {
                cardId: fsCardId,
                cardLabel: dcAs.cardLabel,
                assigneeId: dcAs.assigneeId,
                assigneeType: dcAs.assigneeType,
                assigneeName: dcAs.assigneeName,
                startDate: dcAs.startDate,
                endDate: dcAs.endDate,
                note: dcAs.note,
                legacyId: dcAs.id,
                createdAt: serverTimestamp(),
                updatedAt: serverTimestamp()
            });
        }

        // 4. Migrate Transactions
        for (const dcTx of dcTransactions) {
            const fsCardId = cardIdMap.get(dcTx.card?.id);
            if (!fsCardId) continue;

            const ref = doc(collection(db, TRANSACTIONS_COLLECTION));
            batch.set(ref, {
                cardId: fsCardId,
                cardLabel: dcTx.cardLabel,
                date: dcTx.date,
                yearMonth: dcTx.yearMonth,
                merchant: dcTx.merchant,
                category: dcTx.category,
                amount: dcTx.amount,
                memo: dcTx.memo,
                evidenceUrl: dcTx.evidenceUrl,
                legacyId: dcTx.id,
                createdAt: serverTimestamp()
            });
        }

        // 5. Migrate Billings
        for (const dcBi of dcBillings) {
            const fsCardId = cardIdMap.get(dcBi.card?.id);
            if (!fsCardId) continue;

            const ref = doc(db, BILLINGS_COLLECTION, dcBi.id); // 泥?뎄?쒕뒗 ID ?좎??섍굅???덈줈 ?앹꽦
            batch.set(ref, {
                yearMonth: dcBi.yearMonth,
                cardId: fsCardId,
                cardLabel: dcBi.cardLabel,
                assignedTeamId: dcBi.assignedTeamId,
                assignedTeamName: dcBi.assignedTeamName,
                teamId: dcBi.team?.id || dcBi.teamId,
                teamName: dcBi.teamName,
                issuedToType: dcBi.issuedToType,
                issuedToWorkerId: dcBi.issuedToWorkerId,
                issuedToWorkerName: dcBi.issuedToWorkerName,
                variableCost: dcBi.variableCost,
                totalAmount: dcBi.totalAmount,
                status: dcBi.status,
                lineItems: typeof dcBi.lineItems === 'string' ? JSON.parse(dcBi.lineItems) : dcBi.lineItems,
                statementAttachmentPaths: typeof dcBi.statementAttachmentPaths === 'string' ? JSON.parse(dcBi.statementAttachmentPaths) : dcBi.statementAttachmentPaths,
                memo: dcBi.memo,
                legacyId: dcBi.id,
                createdAt: serverTimestamp(),
                updatedAt: serverTimestamp()
            });
        }

        await batch.commit();
        return {
            cards: dcCards.length,
            assignments: dcAssignments.length,
            transactions: dcTransactions.length,
            billings: dcBillings.length
        };
    }
};

import { dailyReportFirestoreService } from './dailyReportFirestoreService';
import {
    DailyReportZod as DailyReport,
    DailyReportInputZod as DailyReportInput,
    DailyReportWorkerZod as DailyReportWorker,
    DailyReportWorkerInputZod as DailyReportWorkerInput,
} from '../types/zod/dailyReportSchema';
import { db } from '../config/firebase';
import {
    collection,
    getDocs,
    query,
    where,
    writeBatch,
    doc,
    getDoc,
} from 'firebase/firestore';
import { normalizeLooseDateString, normalizeLooseDateText } from '../utils/dateNormalization';
import { resolveReportPayType, resolveWorkerPayType, syncPayTypeFields } from '../utils/payType';

export type { DailyReport, DailyReportWorker };

export interface DailyReportWorkerRow {
    reportId: string;
    date: string;
    teamId: string;
    teamName: string | undefined;
    siteId: string;
    siteName: string | undefined;
    responsibleTeamId?: string | undefined;
    responsibleTeamName?: string | undefined;
    workerId: string;
    name?: string;
    workerName: string;
    role: string | undefined;
    status: 'attendance' | 'absent' | 'half';
    manDay: number;
    unitPrice: number;
    amount: number;
    payType: string | undefined;
    salaryModel: string | undefined;
    workContent: string | undefined;
    siteType: string;
    paymentType: string;
    createdAt: any;
    workerTeamName?: string | undefined;
    workerTeamId?: string | undefined;
}

const normalizeReport = (report: Partial<DailyReport> & { date: string; teamId: string; siteId: string }): DailyReport => ({
    ...report,
    date: normalizeLooseDateText(report.date),
    workers: Array.isArray(report.workers)
        ? report.workers.map((worker) => syncPayTypeFields(worker, { returnUndefinedOnEmpty: true, priority: 'salaryModel' }))
        : [],
    totalManDay: report.totalManDay ?? 0,
    totalAmount: report.totalAmount ?? 0,
}) as DailyReport;

const filterReportsByParams = (reports: DailyReport[], params: {
    startDate?: string;
    endDate?: string;
    teamId?: string;
    siteId?: string;
}): DailyReport[] => {
    const normalizedStartDate = normalizeLooseDateString(params.startDate);
    const normalizedEndDate = normalizeLooseDateString(params.endDate);

    return reports.filter((report) => {
        const normalizedReportDate = normalizeLooseDateString(report.date);
        if (!normalizedReportDate) return false;
        if (normalizedStartDate && normalizedReportDate < normalizedStartDate) return false;
        if (normalizedEndDate && normalizedReportDate > normalizedEndDate) return false;
        if (params.teamId && report.teamId !== params.teamId) return false;
        if (params.siteId && report.siteId !== params.siteId) return false;
        return true;
    }).sort((a, b) => {
        const dateCompare = String(b.date ?? '').localeCompare(String(a.date ?? ''));
        if (dateCompare !== 0) return dateCompare;
        return String(b.createdAt ?? '').localeCompare(String(a.createdAt ?? ''));
    });
};

// undefined를 null로 치환 (타입 보존)
const cleanWorker = (worker: any): DailyReportWorker => {
    const cleaned: any = { ...worker };
    Object.keys(cleaned).forEach((k) => {
        if (cleaned[k] === undefined) cleaned[k] = null;
    });
    return cleaned as DailyReportWorker;
};

export const dailyReportService = {
    addReport: async (report: DailyReportInput): Promise<string> => {
        const normalized = normalizeReport(report as any);
        const docId = await dailyReportFirestoreService.addReport(normalized as any);
        await dailyReportService._updateStats(normalized, 1);
        return docId;
    },

    updateReport: async (id: string, updates: Partial<DailyReport>): Promise<void> => {
        const oldSnap = await getDoc(doc(db, 'daily_reports', id));
        if (!oldSnap.exists()) throw new Error('Report not found');
        const oldData = normalizeReport(oldSnap.data() as any);
        let normalizedUpdates = {
            ...updates,
            ...(updates.date !== undefined ? { date: normalizeLooseDateText(updates.date) } : {})
        };
        // workers 필드가 있으면 undefined -> null 치환
        if (Array.isArray(normalizedUpdates.workers)) {
          normalizedUpdates = {
            ...normalizedUpdates,
            workers: normalizedUpdates.workers.map(cleanWorker)
          };
        }

        await dailyReportService._updateStats(oldData, -1);
        await dailyReportFirestoreService.updateReport(id, normalizedUpdates);

        const newData = normalizeReport({ ...oldData, ...normalizedUpdates } as any);
        await dailyReportService._updateStats(newData, 1);
    },

    addReportsBatch: async (reports: DailyReportInput[]): Promise<void> => {
        const normalized = reports.map(report => normalizeReport(report as any));
        await dailyReportFirestoreService.saveReportsBatch(normalized as any[]);
        for (const report of normalized) {
            await dailyReportService._updateStats(report, 1);
        }
    },

    overwriteReports: async (date: string, reports: DailyReportInput[], teamIdsToCheck: string[]): Promise<void> => {
        const teamIdSet = new Set(teamIdsToCheck);
        const existingSnap = await getDocs(query(
            collection(db, 'daily_reports'),
            where('date', '==', date)
        ));

        const toDelete = existingSnap.docs.filter(snapshot => teamIdSet.has(String(snapshot.data().teamId ?? '')));
        for (const snapshot of toDelete) {
            await dailyReportService._updateStats(normalizeReport(snapshot.data() as any), -1);
            await dailyReportFirestoreService.deleteReport(snapshot.id);
        }

        await dailyReportService.addReportsBatch(reports);
    },

    deleteReport: async (id: string): Promise<void> => {
        const snap = await getDoc(doc(db, 'daily_reports', id));
        if (snap.exists()) {
            await dailyReportService._updateStats(normalizeReport(snap.data() as any), -1);
        }
        await dailyReportFirestoreService.deleteReport(id);
    },

    deleteReports: async (ids: string[]): Promise<void> => {
        const batch = writeBatch(db);
        for (const id of ids) {
            const snap = await getDoc(doc(db, 'daily_reports', id));
            if (snap.exists()) {
                await dailyReportService._updateStats(normalizeReport(snap.data() as any), -1);
            }
            batch.delete(doc(db, 'daily_reports', id));
        }
        await batch.commit();
    },

    getReport: async (id: string): Promise<DailyReport | null> => {
        const report = await dailyReportFirestoreService.getReport(id);
        return report ? normalizeReport(report as any) : null;
    },

    getReports: async (
        paramsOrDate: {
            startDate?: string;
            endDate?: string;
            teamId?: string;
            siteId?: string;
        } | string = {},
        legacyTeamId?: string,
        legacySiteId?: string
    ): Promise<DailyReport[]> => {
        const params = typeof paramsOrDate === 'string'
            ? { startDate: paramsOrDate, endDate: paramsOrDate, teamId: legacyTeamId, siteId: legacySiteId }
            : paramsOrDate;

        const normalized = {
            startDate: normalizeLooseDateText(params.startDate ?? params.endDate ?? ''),
            endDate: normalizeLooseDateText(params.endDate ?? params.startDate ?? ''),
            teamId: params.teamId,
            siteId: params.siteId,
        };

        const all = await dailyReportService.getAllReports();
        return filterReportsByParams(all, normalized);
    },

    getReportsList: async (): Promise<DailyReport[]> => {
        return dailyReportService.getReports();
    },

    getAllReports: async (): Promise<DailyReport[]> => {
        const snapshots = await getDocs(collection(db, 'daily_reports'));
        return snapshots.docs.map(snapshot => normalizeReport({ id: snapshot.id, ...(snapshot.data() as any) }));
    },

    _updateStats: async (report: DailyReport, multiplier: number) => {
        try {
            const { manpowerService } = await import('./manpowerService');
            const { teamService } = await import('./teamService');
            const { siteService } = await import('./siteService');
            const { companyService } = await import('./companyService');

            const promises: Promise<any>[] = [];
            const totalManDay = report.totalManDay || 0;

            report.workers.forEach(worker => {
                if (worker.workerId && !worker.workerId.startsWith('unknown') && worker.manDay > 0) {
                    promises.push(manpowerService.incrementManDay(worker.workerId, worker.manDay * multiplier));
                }
            });

            if (totalManDay > 0 && report.teamId) {
                promises.push(teamService.incrementManDay(report.teamId, totalManDay * multiplier));
                try {
                    promises.push(companyService.incrementManDayByTeam(report.teamId, totalManDay * multiplier));
                } catch {
                }
            }

            if (totalManDay > 0 && report.siteId) {
                promises.push(siteService.incrementManDay(report.siteId, totalManDay * multiplier));
            }

            await Promise.all(promises);
        } catch (error) {
            console.warn('[dailyReportService] _updateStats failed (ignored):', error);
        }
    },

    getWorkerRows: async (params: {
        startDate?: string;
        endDate?: string;
        teamId?: string;
        siteId?: string;
    } = {}): Promise<DailyReportWorkerRow[]> => {
        const reports = await dailyReportService.getReports(params);
        const { siteService } = await import('./siteService');
        const sites = await siteService.getSites();
        const siteMap = new Map<string, (typeof sites)[number]>();
        const siteNameMap = new Map<string, (typeof sites)[number]>();

        sites.forEach((site) => {
            const id = String(site.id ?? '').trim();
            const legacyId = String(site.legacyId ?? '').trim();
            const name = String(site.name ?? '').trim();

            if (id) siteMap.set(id, site);
            if (legacyId) siteMap.set(legacyId, site);
            if (name && !siteNameMap.has(name)) siteNameMap.set(name, site);
        });

        const rows: DailyReportWorkerRow[] = [];
        reports.forEach(report => {
            const site = report.siteId
                ? siteMap.get(String(report.siteId).trim())
                : undefined;
            const resolvedSite = site ?? siteNameMap.get(String(report.siteName ?? '').trim());
            const fallbackSiteType = resolvedSite?.siteType || '';
            const fallbackPaymentType = resolvedSite?.paymentMethod || '';

            report.workers.forEach(worker => {
                const unitPrice = worker.unitPrice || 0;
                const resolvedPayType = resolveReportPayType(worker) || undefined;
                rows.push({
                    reportId: report.id || '',
                    date: report.date,
                    teamId: report.teamId,
                    teamName: report.teamName,
                    siteId: report.siteId,
                    siteName: report.siteName,
                    responsibleTeamId: report.responsibleTeamId ?? resolvedSite?.responsibleTeamId,
                    responsibleTeamName: report.responsibleTeamName ?? resolvedSite?.responsibleTeamName,
                    workerId: worker.workerId,
                    workerName: worker.name,
                    role: worker.role,
                    status: worker.status,
                    manDay: worker.manDay,
                    unitPrice,
                    amount: worker.manDay * unitPrice,
                    payType: resolvedPayType,
                    salaryModel: resolvedPayType,
                    workContent: worker.workContent,
                    siteType: worker.siteType || report.siteType || fallbackSiteType || '',
                    paymentType: worker.paymentType || report.paymentType || fallbackPaymentType || '',
                    createdAt: report.createdAt,
                    workerTeamName: worker.workerTeamName,
                    workerTeamId: worker.teamId,
                });
            });
        });

        return rows;
    },

    getReportWorkerRowsByRange: async (params: { startDate: string; endDate: string; teamId?: string; siteId?: string }) => {
        return dailyReportService.getWorkerRows(params);
    },

    getReportsByRange: async (startDate: string, endDate: string, teamId?: string, siteId?: string): Promise<DailyReport[]> => {
        return dailyReportService.getReports({ startDate, endDate, teamId, siteId });
    },

    checkReportExists: async (date: string, teamId: string, siteId: string): Promise<boolean> => {
        const reports = await dailyReportService.getReports(date, teamId, siteId);
        return reports.length > 0;
    },

    getReportsBySite: async (siteId: string): Promise<DailyReport[]> => {
        const normalizedTargetSiteId = String(siteId ?? '').trim();
        if (!normalizedTargetSiteId) return [];

        const reports = await dailyReportService.getAllReports();

        // 현장 ID 체계가 바뀐 경우(legacyId <-> id)에도 과거 일보를 함께 조회한다.
        const { siteService } = await import('./siteService');
        const allSites = await siteService.getSites();

        const candidateSiteIds = new Set<string>();
        const candidateSiteNames = new Set<string>();
        candidateSiteIds.add(normalizedTargetSiteId);

        let expanded = true;
        while (expanded) {
            expanded = false;
            allSites.forEach((site) => {
                const id = String(site.id ?? '').trim();
                const legacyId = String(site.legacyId ?? '').trim();
                if (!id && !legacyId) return;

                const isLinked = (id && candidateSiteIds.has(id)) || (legacyId && candidateSiteIds.has(legacyId));
                if (!isLinked) return;

                if (id && !candidateSiteIds.has(id)) {
                    candidateSiteIds.add(id);
                    expanded = true;
                }
                if (legacyId && !candidateSiteIds.has(legacyId)) {
                    candidateSiteIds.add(legacyId);
                    expanded = true;
                }

                const name = String(site.name ?? '').trim();
                if (name) candidateSiteNames.add(name);
            });
        }

        return reports.filter((report) => {
            const reportSiteId = String(report.siteId ?? '').trim();
            if (reportSiteId && candidateSiteIds.has(reportSiteId)) return true;

            // 일부 구 데이터가 siteId가 비정상인 경우를 대비해 siteName도 보조 매칭한다.
            const reportSiteName = String(report.siteName ?? '').trim();
            return !!reportSiteName && candidateSiteNames.has(reportSiteName);
        });
    },

    syncReportsSalaryModel: async (): Promise<{ updated: number; errors: string[] }> => {
        const errors: string[] = [];
        let updated = 0;

        try {
            const { manpowerService } = await import('./manpowerService');
            const workers = await manpowerService.getWorkers(true);
            const workerMap = new Map(
                workers
                    .filter(worker => worker.id)
                    .map(worker => [
                        String(worker.id),
                        {
                            payType: resolveWorkerPayType(worker) || undefined,
                            salaryModel: resolveWorkerPayType(worker) || undefined,
                        },
                    ])
            );

            const reports = await dailyReportService.getAllReports();
            for (const report of reports) {
                if (!report.id) continue;

                let changed = false;
                const nextWorkers = report.workers.map(worker => {
                    const current = workerMap.get(String(worker.workerId));
                    if (!current) return worker;

                    const nextPayType = resolveReportPayType(worker, current) || undefined;
                    const nextSalaryModel = nextPayType;
                    if (nextPayType !== worker.payType || nextSalaryModel !== worker.salaryModel) {
                        changed = true;
                    }

                    return {
                        ...worker,
                        payType: nextPayType,
                        salaryModel: nextSalaryModel,
                    };
                });

                if (!changed) continue;

                const totalManDay = nextWorkers.reduce((sum, worker) => sum + (worker.manDay || 0), 0);
                const totalAmount = nextWorkers.reduce((sum, worker) => sum + ((worker.manDay || 0) * (worker.unitPrice || 0)), 0);
                await dailyReportFirestoreService.updateReport(report.id, {
                    workers: nextWorkers,
                    totalManDay,
                    totalAmount,
                } as any);
                updated += 1;
            }
        } catch (error) {
            console.error('Error syncing daily report salary models:', error);
            errors.push(String(error));
        }

        return { updated, errors };
    },

    getLastReportDate: async (teamId: string): Promise<string | null> => {
        const reports = await dailyReportFirestoreService.getReportsByTeam(teamId, 1);
        return reports.length > 0 ? reports[0].date : null;
    },

    addWorkerToReport: async (
        date: string,
        teamId: string,
        teamName: string,
        siteId: string,
        siteName: string,
        worker: DailyReportWorkerInput,
        extraFields: Partial<DailyReport> = {}
    ): Promise<void> => {
        const reports = await dailyReportService.getReports({ startDate: date, endDate: date, teamId, siteId });
        const report = reports[0];

        if (!report) {
            await dailyReportService.addReport({
                ...extraFields,
                date,
                teamId,
                teamName,
                siteId,
                siteName,
                workers: [worker],
                totalManDay: worker.manDay || 0,
                totalAmount: (worker.manDay || 0) * (worker.unitPrice || 0),
            });
            return;
        }

        const updatedWorkers = [...report.workers];
        const existingIndex = updatedWorkers.findIndex(existingWorker => existingWorker.workerId === worker.workerId);
        if (existingIndex >= 0) {
            updatedWorkers[existingIndex] = syncPayTypeFields({ ...updatedWorkers[existingIndex], ...worker } as DailyReportWorker, { returnUndefinedOnEmpty: true, priority: 'salaryModel' });
        } else {
            updatedWorkers.push(syncPayTypeFields(worker as DailyReportWorker, { returnUndefinedOnEmpty: true, priority: 'salaryModel' }));
        }

        const totalManDay = updatedWorkers.reduce((sum, currentWorker) => sum + (currentWorker.manDay || 0), 0);
        const totalAmount = updatedWorkers.reduce((sum, currentWorker) => sum + ((currentWorker.manDay || 0) * (currentWorker.unitPrice || 0)), 0);
        await dailyReportService.updateReport(report.id as string, {
            ...extraFields,
            workers: updatedWorkers,
            totalManDay,
            totalAmount,
        });
    },

    updateWorkerInReport: async (reportId: string, workerId: string, updates: Partial<DailyReportWorker>): Promise<void> => {
        const report = await dailyReportService.getReport(reportId);
        if (!report) throw new Error('Report not found');

        const updatedWorkers = [...report.workers];
        const index = updatedWorkers.findIndex(worker => worker.workerId === workerId);
        if (index === -1) throw new Error('Worker not found in report');

        updatedWorkers[index] = syncPayTypeFields({ ...updatedWorkers[index], ...updates } as DailyReportWorker, { returnUndefinedOnEmpty: true, priority: 'salaryModel' });
        const totalManDay = updatedWorkers.reduce((sum, worker) => sum + (worker.manDay || 0), 0);
        const totalAmount = updatedWorkers.reduce((sum, worker) => sum + ((worker.manDay || 0) * (worker.unitPrice || 0)), 0);

        await dailyReportService.updateReport(reportId, {
            workers: updatedWorkers,
            totalManDay,
            totalAmount,
        });
    },

    removeWorkerFromReport: async (reportId: string, workerId: string): Promise<void> => {
        const report = await dailyReportService.getReport(reportId);
        if (!report) throw new Error('Report not found');

                // undefined 필드를 null로 치환하되 타입 보존
                const cleanWorker = (worker: any): DailyReportWorker => {
                    const cleaned: any = { ...worker };
                    Object.keys(cleaned).forEach((k) => {
                        if (cleaned[k] === undefined) cleaned[k] = null;
                    });
                    return cleaned as DailyReportWorker;
                };

                const updatedWorkers = report.workers
                    .filter(worker => worker.workerId !== workerId)
                    .map(cleanWorker);
                const totalManDay = updatedWorkers.reduce((sum, worker) => sum + ((worker.manDay || 0) as number), 0);
                const totalAmount = updatedWorkers.reduce((sum, worker) => sum + (((worker.manDay || 0) as number) * ((worker.unitPrice || 0) as number)), 0);

                await dailyReportService.updateReport(reportId, {
                        workers: updatedWorkers,
                        totalManDay,
                        totalAmount,
                });
    },

    getDBStats: async () => {
        return dailyReportFirestoreService.getDBStats();
    },

    addWorkersToReportBatch: async (params: {
        date: string;
        teamId: string;
        teamName: string;
        siteId: string;
        siteName: string;
        workers: DailyReportWorker[];
    }) => {
        await dailyReportFirestoreService.upsertReportWorkersBatch(params);

        const tempReport: DailyReport = normalizeReport({
            date: params.date,
            teamId: params.teamId,
            teamName: params.teamName,
            siteId: params.siteId,
            siteName: params.siteName,
            workers: params.workers,
            totalManDay: params.workers.reduce((sum, worker) => sum + (worker.manDay || 0), 0),
            totalAmount: params.workers.reduce((sum, worker) => sum + ((worker.manDay || 0) * (worker.unitPrice || 0)), 0),
        });

        await dailyReportService._updateStats(tempReport, 1);
    },
};

/**
