            const manDay = data.manDay || 0;

            if (workerId) {
                const stats = workerStats.get(workerId) || { workDays: 0, totalManDay: 0, workerId };
                stats.workDays++;
                stats.totalManDay += manDay;
                workerStats.set(workerId, stats);
            }
        });

        // 정렬
